'use client'

import { useState } from 'react'
import Link from 'next/link'
import { Metadata } from 'next'
import { Loader2, Mail, ArrowLeft, CheckCircle2 } from 'lucide-react'

// Metadata exported via layout — client components cannot export metadata directly

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState('')
  const [loading, setLoading] = useState(false)
  const [sent, setSent] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      const res = await fetch('/api/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.trim().toLowerCase() }),
      })

      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.message || 'Failed to send reset email')
      }

      setSent(true)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  if (sent) {
    return (
      <div className="text-center">
        <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-green-50">
          <CheckCircle2 className="h-8 w-8 text-green-500" />
        </div>
        <h2 className="text-aerojet-blue mb-3 text-2xl font-black tracking-tight uppercase">
          Check Your Email
        </h2>
        <p className="mb-8 text-sm text-slate-500 dark:text-slate-400">
          If an account exists for <strong className="text-slate-700">{email}</strong>, we've sent a
          password reset link. Please check your spam/junk folder if you don't see it in your inbox.
        </p>
        <Link
          href="/login"
          className="text-aerojet-sky inline-flex items-center gap-2 text-sm font-bold hover:underline"
        >
          <ArrowLeft className="h-4 w-4" /> Back to Login
        </Link>
      </div>
    )
  }

  return (
    <div>
      <div className="mb-8">
        <h2 className="text-aerojet-blue text-2xl font-black tracking-tight uppercase sm:text-3xl">
          Reset Password
        </h2>
        <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">
          Enter the email associated with your account.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-5">
        {error && (
          <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            {error}
          </div>
        )}

        <div>
          <label className="mb-2 block text-xs font-bold tracking-widest text-slate-500 uppercase dark:text-slate-400">
            Email Address
          </label>
          <div className="relative">
            <Mail className="absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              required
              autoComplete="email"
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck="false"
              className="focus:ring-aerojet-sky w-full rounded-xl border border-slate-200 bg-white py-3.5 pr-4 pl-11 text-sm text-slate-900 transition-all placeholder:text-slate-300 focus:border-transparent focus:ring-2 focus:outline-none dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
            />
          </div>
        </div>

        <button
          type="submit"
          disabled={loading || !email}
          className="bg-aerojet-blue hover:bg-aerojet-sky flex w-full items-center justify-center gap-2 rounded-xl py-4 text-xs font-black tracking-widest text-white uppercase shadow-lg transition-all disabled:cursor-not-allowed disabled:opacity-50"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" /> Sending...
            </>
          ) : (
            'Send Reset Link'
          )}
        </button>
      </form>

      <div className="mt-8 text-center">
        <Link
          href="/login"
          className="hover:text-aerojet-sky inline-flex items-center gap-2 text-sm font-medium text-slate-500 transition-colors dark:text-slate-400"
        >
          <ArrowLeft className="h-4 w-4" /> Back to Login
        </Link>
      </div>
    </div>
  )
}

'use client'

import { useState, useTransition, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { signIn, getSession } from 'next-auth/react'
import Link from 'next/link'
import { startAuthentication } from '@simplewebauthn/browser'
import { Eye, EyeOff, Loader2, Mail, Lock, ShieldCheck, Fingerprint } from 'lucide-react'
import { useFormErrorAnnouncer } from '@/hooks/useFormErrorAnnouncer'

export default function LoginForm() {
  const router = useRouter()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState('')
  const [needs2FA, setNeeds2FA] = useState(false)
  const [totpCode, setTotpCode] = useState('')
  const [isPasskeyLoading, setIsPasskeyLoading] = useState(false)
  const [supportsConditionalUI, setSupportsConditionalUI] = useState(false)
  const { announcerRef, getFieldErrorProps, ErrorMessage } = useFormErrorAnnouncer({
    errors: error ? { _global: error } : {},
    touched: error ? { _global: true } : {},
  })

  // Complete passkey login after browser returns a credential (shared by button + conditional UI)
  const completePasskeyLogin = useCallback(async (credential: any) => {
    const verifyRes = await fetch('/api/auth/passkey/login-verify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ credential }),
    })

    if (!verifyRes.ok) {
      throw new Error(await verifyRes.text() || 'Passkey verification failed')
    }

    const { token } = await verifyRes.json()

    startTransition(async () => {
      const result = await signIn('credentials', { redirect: false, token })
      if (result?.error) {
        setError(result.error)
        return
      }
      const session = await getSession()
      const userRole = session?.user?.role
      if (userRole === 'STUDENT' || userRole === 'APPLICANT') {
        router.push('/student')
      } else {
        router.push('/staff')
      }
      router.refresh()
    })
  }, [router])

  // Conditional UI: automatically prompt passkey when email field is focused (if browser supports it)
  useEffect(() => {
    let aborted = false

    async function initConditionalUI() {
      if (
        typeof window === 'undefined' ||
        !window.PublicKeyCredential ||
        !PublicKeyCredential.isConditionalMediationAvailable
      ) {
        return
      }

      const available = await PublicKeyCredential.isConditionalMediationAvailable()
      if (!available || aborted) return

      setSupportsConditionalUI(true)

      try {
        // Get authentication options (discoverable credential flow)
        const optionsRes = await fetch('/api/auth/passkey/login-options', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({}),
        })
        if (!optionsRes.ok || aborted) return
        const { options } = await optionsRes.json()

        // Start conditional mediation — browser shows passkey in autofill dropdown
        const credential = await startAuthentication({ optionsJSON: options, useBrowserAutofill: true })
        if (aborted) return

        await completePasskeyLogin(credential)
      } catch (err: any) {
        // AbortError is normal when user navigates away or uses password instead
        if (err.name !== 'AbortError' && !aborted) {
          console.debug('[ConditionalUI]', err.message)
        }
      }
    }

    initConditionalUI()
    return () => { aborted = true }
  }, [completePasskeyLogin])

  const handlePasskeyLogin = async () => {
    try {
      setIsPasskeyLoading(true)
      setError('')

      // 1. Get options from server
      const optionsRes = await fetch('/api/auth/passkey/login-options', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.trim() || undefined }),
      })

      if (!optionsRes.ok) {
        throw new Error('Failed to initiate passkey login')
      }
      const { options } = await optionsRes.json()

      // 2. Browser authentication
      let credential
      try {
        credential = await startAuthentication({ optionsJSON: options })
      } catch (err: any) {
        if (err.name === 'NotAllowedError') {
          return // User cancelled
        }
        throw err
      }

      // 3. Verify and complete login
      await completePasskeyLogin(credential)
    } catch (err: any) {
      console.error(err)
      setError(err.message || 'An error occurred during passkey login')
    } finally {
      setIsPasskeyLoading(false)
    }
  }

  // Extracted so we can trigger it from both the explicit submit and the
  // auto-submit-on-6-digits path. The optional `codeOverride` bypasses React's
  // state-lag: when the user types the 6th digit, the onChange-derived value
  // is passed directly instead of waiting for the next render.
  const performLogin = useCallback(
    (codeOverride?: string) => {
      startTransition(async () => {
        setError('')
        try {
          const result = await signIn('credentials', {
            redirect: false,
            email: email.trim().toLowerCase(),
            password,
            totpCode: needs2FA ? (codeOverride ?? totpCode) : undefined,
          })

          if (!result) {
            throw new Error('Something went wrong. Please try again.')
          }

          if (result.error) {
            // Check if the error indicates 2FA is required
            if (result.error.includes('2FA_REQUIRED')) {
              setNeeds2FA(true)
              setTotpCode('')
              return
            }
            if (needs2FA && result.error.includes('Invalid 2FA code')) {
              // Wipe the code on invalid attempt so the user can retype
              // (and the autosubmit fires again on the 6th digit).
              setTotpCode('')
              throw new Error('Invalid verification code. Please try again.')
            }
            throw new Error('Invalid email or password.')
          }

          // Get session to read role and redirect accordingly
          const session = await getSession()
          const role = session?.user?.role

          const redirectMap: Record<string, string> = {
            SUPER_ADMIN: '/staff',
            ADMIN: '/staff',
            STAFF: '/staff',
            INSTRUCTOR: '/instructor',
            STUDENT: '/student',
            APPLICANT: '/applicant',
          }

          // Use window.location for full page navigation after auth
          window.location.href = redirectMap[role || ''] ?? '/login'
        } catch (err: any) {
          setError(err.message || 'Something went wrong. Please try again.')
        }
      })
    },
    [email, password, needs2FA, totpCode]
  )

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    performLogin()
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div ref={announcerRef} aria-live="polite" aria-atomic="true" className="sr-only" />
      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700" role="alert">
          {error}
        </div>
      )}

      {/* Email */}
      <div>
        <label
          htmlFor="email"
          className="mb-2 block text-xs font-bold tracking-widest text-slate-500 uppercase dark:text-slate-400"
        >
          Email Address
        </label>
        <div className="relative">
          <Mail className="absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="you@example.com"
            required
            autoComplete={supportsConditionalUI ? 'username webauthn' : 'email'}
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck="false"
            className="w-full rounded-xl border border-slate-200 bg-white py-3.5 pr-4 pl-11 text-sm text-slate-900 transition-all placeholder:text-slate-300 focus:border-transparent focus:ring-2 focus:ring-aerojet-sky focus:outline-none dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
          />
        </div>
      </div>

      {/* Password */}
      <div>
        <div className="mb-2 flex items-center justify-between">
          <label
            htmlFor="password"
            className="text-xs font-bold tracking-widest text-slate-500 uppercase dark:text-slate-400"
          >
            Password
          </label>
          <Link
            href="/forgot-password"
            className="text-xs font-bold text-aerojet-sky hover:underline"
          >
            Forgot?
          </Link>
        </div>
        <div className="relative">
          <Lock className="absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            id="password"
            type={showPassword ? 'text' : 'password'}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="••••••••"
            required
            autoComplete="current-password"
            className="w-full rounded-xl border border-slate-200 bg-white py-3.5 pr-12 pl-11 text-sm text-slate-900 transition-all placeholder:text-slate-300 focus:border-transparent focus:ring-2 focus:ring-aerojet-sky focus:outline-none dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
          />
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute top-1/2 right-4 -translate-y-1/2 text-slate-400 transition-colors hover:text-slate-600 dark:text-slate-400"
          >
            {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
          </button>
        </div>
      </div>

      {/* 2FA Code */}
      {needs2FA && (
        <div>
          <label
            htmlFor="totpCode"
            className="mb-2 block text-xs font-bold tracking-widest text-slate-500 uppercase dark:text-slate-400"
          >
            Verification Code
          </label>
          <p className="mb-3 text-xs text-slate-400 dark:text-slate-500">
            Enter the 6-digit code from your authenticator app. It will submit automatically.
          </p>
          <div className="relative">
            <ShieldCheck className="absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              id="totpCode"
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              maxLength={6}
              value={totpCode}
              onChange={(e) => {
                const next = e.target.value.replace(/\D/g, '').slice(0, 6)
                setTotpCode(next)
                // Auto-submit the moment the 6th digit lands. We pass the
                // value directly (instead of relying on state) because
                // setState hasn't flushed yet. Guard on !isPending so we
                // don't double-fire if the user pastes a code while a
                // submit is already in flight.
                if (next.length === 6 && !isPending) {
                  performLogin(next)
                }
              }}
              placeholder="000000"
              required
              autoFocus
              autoComplete="one-time-code"
              className="w-full rounded-xl border border-slate-200 bg-white py-3.5 pr-4 pl-11 text-center text-lg font-mono tracking-[0.3em] text-slate-900 transition-all placeholder:text-slate-300 focus:border-transparent focus:ring-2 focus:ring-aerojet-sky focus:outline-none dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
            />
          </div>
        </div>
      )}

      {/* Submit */}
      <button
        type="submit"
        disabled={isPending}
        className="flex w-full items-center justify-center gap-2 rounded-xl bg-aerojet-blue py-4 text-xs font-black tracking-widest text-white uppercase shadow-lg transition-all hover:bg-aerojet-sky disabled:cursor-not-allowed disabled:opacity-50"
      >
        {isPending ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" /> Signing In...
          </>
        ) : (
          'Sign In'
        )}
      </button>

      <div className="relative py-4">
        <div className="absolute inset-0 flex items-center">
          <span className="w-full border-t border-slate-200 dark:border-slate-700" />
        </div>
        <div className="relative flex justify-center text-xs uppercase">
          <span className="bg-white px-2 text-slate-400 dark:bg-slate-950">Or continue with</span>
        </div>
      </div>

      <button
        type="button"
        onClick={handlePasskeyLogin}
        disabled={isPending || isPasskeyLoading}
        className="flex w-full items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white py-4 text-xs font-bold tracking-widest text-slate-700 uppercase shadow-sm transition-all hover:bg-slate-50 focus:ring-2 focus:ring-slate-200 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300 dark:hover:bg-slate-800"
      >
        {isPasskeyLoading ? (
          <Loader2 className="h-4 w-4 animate-spin text-slate-500" />
        ) : (
          <Fingerprint className="h-4 w-4 text-slate-500" />
        )}
        Sign in with Passkey
      </button>
    </form>
  )
}

"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Loader2, Eye, EyeOff, Lock, CheckCircle2 } from "lucide-react";

export default function ResetPasswordPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token");

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState("");

  if (!token) {
    return (
      <div className="text-center">
        <h2 className="text-2xl font-black text-aerojet-blue uppercase tracking-tight mb-3">Invalid Link</h2>
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">This password reset link is invalid or has expired.</p>
        <Link href="/forgot-password" className="text-aerojet-sky font-bold text-sm hover:underline">Request a new link</Link>
      </div>
    );
  }

  if (success) {
    return (
      <div className="text-center">
        <div className="w-16 h-16 bg-green-50 rounded-full flex items-center justify-center mx-auto mb-6">
          <CheckCircle2 className="w-8 h-8 text-green-500" />
        </div>
        <h2 className="text-2xl font-black text-aerojet-blue uppercase tracking-tight mb-3">Password Updated</h2>
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">You can now sign in with your new password.</p>
        <Link href="/login" className="inline-block bg-aerojet-blue text-white px-8 py-3 rounded-xl font-black uppercase text-xs tracking-widest hover:bg-aerojet-sky transition-all">
          Sign In
        </Link>
      </div>
    );
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password !== confirmPassword) { setError("Passwords do not match"); return; }
    setError("");
    setLoading(true);

    try {
      const res = await fetch("/api/auth/reset-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, password }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.message || "Failed to reset password");
      }

      setSuccess(true);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="mb-8">
        <h2 className="text-2xl font-black text-aerojet-blue uppercase tracking-tight">New Password</h2>
        <p className="text-sm text-slate-500 dark:text-slate-400 mt-2">Choose a strong password for your account.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-5">
        {error && <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl text-sm font-medium">{error}</div>}

        <div>
          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-2">New Password</label>
          <div className="relative">
            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input type={showPassword ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Min. 8 characters" required minLength={8} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl pl-11 pr-12 py-3.5 text-sm text-slate-900 dark:text-slate-100 placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-aerojet-sky focus:border-transparent transition-all" />
            <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 dark:text-slate-400">
              {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </button>
          </div>
        </div>

        <div>
          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-2">Confirm Password</label>
          <input type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Re-enter password" required className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3.5 text-sm text-slate-900 dark:text-slate-100 placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-aerojet-sky focus:border-transparent transition-all" />
        </div>

        <button type="submit" disabled={loading || password.length < 8} className="w-full bg-aerojet-blue text-white py-4 rounded-xl font-black uppercase tracking-widest text-xs hover:bg-aerojet-sky transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-lg">
          {loading ? <><Loader2 className="w-4 h-4 animate-spin" /> Updating...</> : "Update Password"}
        </button>
      </form>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { toast } from 'sonner'
import { CheckCircle2, RefreshCw } from 'lucide-react'
import { UploadDropzone } from '@/lib/uploads/uploadthing'

export default function UploadProofForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [registrationCode, setRegistrationCode] = useState('')
  const [uploading, setUploading] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const [receiptUrl, setReceiptUrl] = useState('')

  useEffect(() => {
    const code = searchParams.get('code')
    if (code) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setRegistrationCode(code)
    }
  }, [searchParams])

  if (submitted) {
    return (
      <div className="space-y-3 rounded-2xl border border-green-200 bg-green-50 p-6 text-center">
        <CheckCircle2 className="mx-auto h-10 w-10 text-green-500" />
        <p className="font-bold text-green-800">Proof Submitted Successfully!</p>
        <p className="text-sm text-green-600">
          Our admissions team will review your payment as soon as possible. Once verified, you will
          receive your portal login credentials via email.
        </p>
        <button
          onClick={() => router.push('/')}
          className="mt-4 w-full rounded-xl bg-green-600 px-4 py-3 text-sm font-bold text-white transition hover:bg-green-700"
        >
          Go to Home Page
        </button>
        <div className="mt-4 text-center">
          <p className="text-sm text-green-600">
            Already verified?{' '}
            <button
              onClick={() => router.push('/login')}
              className="font-bold text-green-700 hover:underline"
            >
              Login here
            </button>
          </p>
        </div>
      </div>
    )
  }

  const handleManualRegistrationCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setRegistrationCode(e.target.value.toUpperCase().replace(/\s/g, ''))
  }

  return (
    <div className="space-y-6">
      <div>
        <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
          Registration Code
        </label>
        <input
          type="text"
          value={registrationCode}
          onChange={handleManualRegistrationCodeChange}
          placeholder="e.g. AERO-2026-123456"
          className="w-full rounded-lg border border-slate-300 bg-white px-4 py-3 font-mono text-slate-900 transition-all outline-none focus:border-aerojet-sky focus:ring-2 focus:ring-blue-100 dark:border-slate-700 dark:bg-slate-900 dark:text-white"
          required
        />
        <p className="mt-1 text-xs text-slate-500">
          Enter the code from your registration confirmation email.
        </p>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-800 dark:bg-slate-900/50">
        <p className="mb-3 text-sm font-medium text-slate-700 dark:text-slate-300">
          Upload Payment Receipt
        </p>
        {!registrationCode ? (
          <div className="text-center text-sm text-amber-600">
            Please enter your registration code above first.
          </div>
        ) : (
          <UploadDropzone
            endpoint="paymentProof"
            onUploadBegin={() => setUploading(true)}
            onClientUploadComplete={async (res) => {
              setUploading(false)
              if (!res?.[0]?.url) {
                toast.error('Upload failed â€” no file URL returned.')
                return
              }

              try {
                const proofUrl = res[0].url
                setReceiptUrl(proofUrl)

                // Save the URL to the user's record using the public API
                const response = await fetch('/api/public/submit-payment-proof', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ registrationCode, proofUrl }),
                })

                const data = await response.json()

                if (!response.ok) {
                  toast.error(data.error || 'Failed to submit payment proof.')
                  return
                }

                toast.success('Payment proof submitted successfully!')
                setSubmitted(true)
              } catch {
                toast.error('Network error while saving payment proof.')
              }
            }}
            onUploadError={(error) => {
              setUploading(false)
              toast.error(`Upload error: ${error.message}`)
            }}
            appearance={{
              container:
                'border-2 border-dashed border-slate-300 bg-white dark:bg-slate-900 rounded-xl p-8 cursor-pointer hover:border-aerojet-sky transition-colors',
              label: 'text-slate-700 dark:text-slate-300 font-semibold',
              allowedContent: 'text-slate-400 text-xs',
              button:
                'bg-aerojet-blue text-white font-bold px-6 py-2.5 rounded-xl hover:bg-[#003875] transition-colors disabled:opacity-50 disabled:cursor-not-allowed',
            }}
          />
        )}
        {uploading && (
          <p className="mt-3 animate-pulse text-center text-sm text-slate-500">
            Uploading your receipt...
          </p>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState, useRef } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { signIn } from 'next-auth/react'
import { CheckCircle2, XCircle, Loader2, Mail } from 'lucide-react'

export default function VerifyEmailPage() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const token = searchParams.get('token')
  const type = searchParams.get('type') // 'registration' or null (activation)
  const [status, setStatus] = useState<'loading' | 'verified' | 'success' | 'error'>('loading')
  const [message, setMessage] = useState('')
  const hasAttempted = useRef(false)

  useEffect(() => {
    if (!token) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setStatus('error')
      setMessage('Invalid verification link.')
      return
    }

    if (hasAttempted.current) return
    hasAttempted.current = true

    const verify = async () => {
      try {
        if (type === 'registration') {
          // Pre-approval: Just verify email, don't try to login (no password yet)
          const res = await fetch(`/api/auth/verify-email?token=${token}`)
          const data = await res.json()

          if (!res.ok) {
            throw new Error(data.error || 'Verification failed')
          }

          setStatus('verified')

          if (data.registrationCode) {
            // setTimeout(() => {
            //   router.push(`/register?success=true&code=${data.registrationCode}`)
            // }, 2000)
          }

          setMessage(
            'Your email has been verified successfully! Please check your inbox for payment instructions to complete your registration.'
          )
        } else {
          // Post-approval: Verify and auto-login with credentials
          const result = await signIn('credentials', {
            token,
            redirect: false,
          })

          if (result?.error) {
            throw new Error(result.error)
          }

          setStatus('success')
          setMessage('Login successful! Redirecting to your portal...')

          setTimeout(() => {
            router.push('/student')
          }, 1500)
        }
      } catch (err: any) {
        setStatus('error')
        setMessage(err.message || 'Verification failed. The link may have expired.')
      }
    }

    verify()
  }, [token, type, router])

  return (
    <div className="mx-auto max-w-md overflow-hidden rounded-3xl bg-white p-8 shadow-2xl dark:bg-white">
      <div className="text-center">
        {status === 'loading' && (
          <>
            <Loader2 className="mx-auto mb-6 h-12 w-12 animate-spin text-aerojet-sky" />
            <h2 className="mb-3 text-2xl font-black tracking-tight text-slate-800 uppercase">
              {type === 'registration' ? 'Verifying Email' : 'Logging You In'}
            </h2>
            <p className="text-sm text-slate-500">Please wait...</p>
          </>
        )}

        {/* Registration verification â€” no auto-login */}
        {status === 'verified' && (
          <>
            <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-green-50">
              <CheckCircle2 className="h-8 w-8 text-green-500" />
            </div>
            <h2 className="mb-3 text-2xl font-black tracking-tight text-slate-800 uppercase">
              Email Verified
            </h2>
            <p className="mb-6 text-sm text-slate-500">{message}</p>

            <div className="rounded-xl border border-blue-100 bg-blue-50 p-4 text-left">
              <div className="mb-2 flex items-center gap-2">
                <Mail className="h-4 w-4 text-blue-600" />
                <span className="text-xs font-bold text-blue-700 uppercase">Next Steps</span>
              </div>
              <ol className="ml-5 list-decimal space-y-1 text-sm text-blue-800">
                <li>Check your email for the "Registration Received" message</li>
                <li>Follow the payment instructions and copy your reference code</li>
                <li>Log in to your portal and upload your payment proof</li>
              </ol>
            </div>

            <div className="mt-6 flex flex-col items-center gap-4">
              <button
                onClick={() => {
                  window.close()
                  // Fallback: If window.close() is blocked, redirect after a short delay
                  setTimeout(() => {
                    window.location.href = '/'
                  }, 1000)
                }}
                className="inline-flex items-center gap-2 rounded-xl bg-aerojet-blue px-6 py-3 text-xs font-bold tracking-widest text-white uppercase transition-all hover:bg-aerojet-sky"
              >
                Close Page
              </button>
              <Link
                href="/"
                className="text-xs font-bold text-slate-400 hover:text-aerojet-sky hover:underline"
              >
                Return to Homepage
              </Link>
            </div>
          </>
        )}

        {/* Activation verification â€” auto-login */}
        {status === 'success' && (
          <>
            <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-green-50">
              <CheckCircle2 className="h-8 w-8 text-green-500" />
            </div>
            <h2 className="mb-3 text-2xl font-black tracking-tight text-slate-800 uppercase">
              Success
            </h2>
            <p className="mb-8 text-sm text-slate-500">{message}</p>
            <Loader2 className="mx-auto h-6 w-6 animate-spin text-slate-400" />
          </>
        )}

        {status === 'error' && (
          <>
            <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-red-50">
              <XCircle className="h-8 w-8 text-red-500" />
            </div>
            <h2 className="mb-3 text-2xl font-black tracking-tight text-slate-800 uppercase">
              Verification Failed
            </h2>
            <p className="mb-8 text-sm text-slate-500">{message}</p>

            <div className="mx-auto max-w-sm space-y-4">
              <p className="mb-4 text-xs text-slate-400 italic">
                If your link expired or didn&apos;t work, enter your email below to receive a new
                one.
              </p>
              <form
                className="flex flex-col gap-3"
                onSubmit={async (e) => {
                  e.preventDefault()
                  const email = (e.currentTarget.elements.namedItem('email') as HTMLInputElement)
                    .value
                  if (!email) return

                  try {
                    const btn = e.currentTarget.querySelector('button')
                    if (btn) btn.disabled = true

                    const res = await fetch('/api/auth/resend-verification', {
                      method: 'POST',
                      body: JSON.stringify({ email }),
                      headers: { 'Content-Type': 'application/json' },
                    })

                    if (res.ok) {
                      const data = await res.json()
                      setMessage(
                        data.message ||
                          'A new verification link has been sent to your email. (Please check your spam/junk folder)'
                      )
                      alert(
                        data.message ||
                          'A new verification link has been sent to your email. (Please check your spam/junk folder)'
                      )
                    } else {
                      const data = await res.json()
                      alert(data.error || 'Failed to resend link')
                    }
                  } catch {
                    alert('An error occurred. Please try again.')
                  } finally {
                    const btn = e.currentTarget.querySelector('button')
                    if (btn) btn.disabled = false
                  }
                }}
              >
                <input
                  name="email"
                  type="email"
                  placeholder="Enter your email address"
                  required
                  className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-aerojet-sky focus:outline-none"
                />
                <button
                  type="submit"
                  className="w-full rounded-xl bg-aerojet-blue px-6 py-3 text-xs font-bold tracking-widest text-white uppercase transition-all hover:bg-aerojet-sky disabled:opacity-50"
                >
                  Resend Verification Link
                </button>
              </form>

              <div className="pt-4">
                <Link href="/login" className="text-sm font-bold text-aerojet-sky hover:underline">
                  Return to Login
                </Link>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { AlertCircle, X } from 'lucide-react'

/**
 * Sets a CSS custom property --advisory-banner-height on <html> so the
 * fixed navbar (z-50) can offset itself downward when the banner is visible.
 * The banner itself is fixed at top-0 with z-[60] (above the navbar).
 */
export default function AdvisoryBanner({ message }: { message: string }) {
  const [isVisible, setIsVisible] = useState(false)
  const bannerRef = useRef<HTMLDivElement>(null)
  const storageKey = 'aerojet-advisory-closed'

  // Sync the CSS variable with the banner's rendered height
  const syncHeight = () => {
    if (bannerRef.current && isVisible) {
      const h = bannerRef.current.offsetHeight
      document.documentElement.style.setProperty('--advisory-banner-height', `${h}px`)
    } else {
      document.documentElement.style.setProperty('--advisory-banner-height', '0px')
    }
  }

  useEffect(() => {
    if (!message) return
    const closedMessage = sessionStorage.getItem(storageKey)
    if (closedMessage !== message) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsVisible(true)
    }
  }, [message])

  // Update CSS variable whenever visibility or message changes
  useEffect(() => {
    syncHeight()
    // Re-measure on resize (banner text may wrap differently)
    window.addEventListener('resize', syncHeight)
    return () => {
      window.removeEventListener('resize', syncHeight)
      document.documentElement.style.setProperty('--advisory-banner-height', '0px')
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isVisible])

  if (!isVisible || !message) return null

  const handleClose = () => {
    sessionStorage.setItem(storageKey, message)
    setIsVisible(false)
    document.documentElement.style.setProperty('--advisory-banner-height', '0px')
  }

  return (
    <div
      ref={bannerRef}
      className="fixed top-0 right-0 left-0 z-[60] border-b border-amber-300 bg-amber-50 px-4 py-3 shadow-sm sm:px-6 lg:px-8"
    >
      <div className="mx-auto flex max-w-7xl items-center justify-center gap-3">
        <AlertCircle className="h-5 w-5 shrink-0 text-amber-600" />
        <p className="text-center text-sm leading-snug font-semibold text-amber-900">{message}</p>
      </div>
      <button
        onClick={handleClose}
        type="button"
        className="absolute right-4 top-1/2 -translate-y-1/2 shrink-0 rounded-md p-1.5 text-amber-600 transition-colors hover:bg-amber-200/50 hover:text-amber-800 focus:ring-2 focus:ring-amber-500 focus:outline-none sm:right-6 lg:right-8"
        aria-label="Dismiss advisory"
      >
        <X className="h-5 w-5" aria-hidden="true" />
      </button>
    </div>
  )
}

