import { NextRequest, NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/auth/helpers'
import { apiError, withErrorHandler } from '@/lib/api/response'
import { createAuditLog } from '@/lib/audit/logger'
import {
  BACKUP_MODELS,
  exportAllTables,
  generateJsonBackup,
  generateReadableReport,
  sendBackupEmail,
} from '@/lib/backup'

// GET: Download backup file
// ?format=json (default) | html
export const GET = withErrorHandler(async (req: NextRequest) => {
  const admin = await requireAdmin()
  const format = req.nextUrl.searchParams.get('format') || 'json'

  const backup = await exportAllTables()
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-')

  await createAuditLog({
    action: 'EXPORT',
    entity: 'System',
    entityId: 'database-backup',
    userId: admin.id,
    description: `Database backup downloaded as ${format.toUpperCase()} (${BACKUP_MODELS.length} tables)`,
  })

  if (format === 'html') {
    const html = generateReadableReport(backup)
    return new NextResponse(html, {
      status: 200,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Content-Disposition': `attachment; filename="aerojet-backup-${timestamp}.html"`,
      },
    })
  }

  // Default: JSON
  const payload = generateJsonBackup(backup)
  const json = JSON.stringify(payload, null, 2)

  return new NextResponse(json, {
    status: 200,
    headers: {
      'Content-Type': 'application/json',
      'Content-Disposition': `attachment; filename="aerojet-backup-${timestamp}.json"`,
    },
  })
})

// POST: Export and send backup via email (both formats attached)
export const POST = withErrorHandler(async (req: NextRequest) => {
  const admin = await requireAdmin()
  const { email } = await req.json()

  if (!email || typeof email !== 'string') {
    return apiError('Email address is required', 400)
  }

  const backup = await exportAllTables()

  try {
    await sendBackupEmail(email, backup)
  } catch (err: any) {
    console.error('[Backup Email] Failed:', err.message)
    return apiError(err.message, 500)
  }

  await createAuditLog({
    action: 'EXPORT',
    entity: 'System',
    entityId: 'database-backup',
    userId: admin.id,
    description: `Database backup emailed to ${email} (${BACKUP_MODELS.length} tables, JSON + HTML)`,
  })

  return NextResponse.json({ success: true, message: `Backup sent to ${email}` })
})

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireAdmin, hashPassword } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { createAuditLog } from '@/lib/audit/logger'
import { wrapEmail, sendEmail } from '@/lib/email/service'
import crypto from 'crypto'

function generateSecurePassword(): string {
  const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ'
  const lower = 'abcdefghjkmnpqrstuvwxyz'
  const digits = '23456789'
  const special = '!@#$%&*'
  const all = upper + lower + digits + special
  const pick = (chars: string) => chars[crypto.randomInt(chars.length)]
  const parts = [pick(upper), pick(lower), pick(digits), pick(special)]
  for (let i = 4; i < 12; i++) parts.push(pick(all))
  for (let i = parts.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1)
    ;[parts[i], parts[j]] = [parts[j], parts[i]]
  }
  return parts.join('')
}

/**
 * POST /api/admin/bulk-send-credentials
 *
 * Generates new temporary passwords and emails credentials to selected users.
 * Supports custom email overrides per user.
 *
 * Body:
 * {
 *   users: [
 *     { userId: "...", customEmail?: "optional@override.com" },
 *     ...
 *   ]
 * }
 */
export const POST = withErrorHandler(async (req: NextRequest) => {
  const admin = await requireAdmin()

  const body = await req.json()
  const { users } = body as {
    users: { userId: string; customEmail?: string }[]
  }

  if (!users || !Array.isArray(users) || users.length === 0) {
    return apiError('users array is required')
  }

  const results: {
    sent: { userId: string; email: string; name: string }[]
    failed: { userId: string; error: string }[]
  } = { sent: [], failed: [] }

  // Batch-fetch all users upfront instead of N+1 queries in the loop
  const allUsers = await prismaUnfiltered.user.findMany({
    where: { id: { in: users.map(u => u.userId) } },
    include: { profile: true, wallet: true, studentProfile: true },
  })
  const userMap = new Map(allUsers.map(u => [u.id, u]))

  for (const entry of users) {
    try {
      const user = userMap.get(entry.userId)

      if (!user) {
        results.failed.push({ userId: entry.userId, error: 'User not found' })
        continue
      }

      // Generate new temp password
      const tempPassword = generateSecurePassword()
      const hashedPw = await hashPassword(tempPassword)

      // Update password and set mustChangePassword
      await prismaUnfiltered.user.update({
        where: { id: user.id },
        data: {
          password: hashedPw,
          mustChangePassword: true,
          passwordChanged: false,
        },
      })

      const firstName = user.profile?.firstName || 'Student'
      const lastName = user.profile?.lastName || ''
      const loginEmail = user.academyEmail || user.email
      const sendToEmail = entry.customEmail || user.personalEmail || user.email
      const walletBalance = user.wallet
        ? `${user.wallet.currency} ${Number(user.wallet.availableBalance).toFixed(2)}`
        : 'No wallet'
      const studentId = user.studentProfile?.studentId || 'N/A'

      // Build and send email
      const emailBody = await wrapEmail(
        'Your Aerojet Academy Login Credentials',
        `
        <div class="h1">Welcome to Aerojet Academy</div>
        <div class="text">
          Hello ${firstName},<br/><br/>
          Your student portal account has been created. Please use the credentials below to log in.
          <strong>You will be required to change your password on first login.</strong>
        </div>
        <div class="info-box">
          <div class="info-row"><strong>Login Email:</strong> ${loginEmail}</div>
          <div class="info-row"><strong>Temporary Password:</strong> <code style="background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-weight: bold; color: #002a5c;">${tempPassword}</code></div>
          <div class="info-row"><strong>Student ID:</strong> ${studentId}</div>
          <div class="info-row"><strong>Wallet Balance:</strong> ${walletBalance}</div>
        </div>
        <div class="btn-container">
          <a href="${process.env.NEXTAUTH_URL}/login" class="btn">Log In Now</a>
        </div>
        <div class="text" style="font-size: 12px; color: #64748b; margin-top: 16px;">
          If you did not expect this email, please contact the Aerojet Academy administration.
        </div>
        `,
        sendToEmail
      )

      await sendEmail({
        to: sendToEmail,
        subject: 'Your Aerojet Academy Login Credentials',
        html: emailBody,
      })

      results.sent.push({
        userId: user.id,
        email: sendToEmail,
        name: `${firstName} ${lastName}`.trim(),
      })

      await createAuditLog({
        action: 'SYSTEM_UPDATE',
        entity: 'User',
        entityId: user.id,
        userId: admin.id,
        description: `Bulk sent credentials to ${sendToEmail} for ${firstName} ${lastName}`,
      })
    } catch (error: any) {
      results.failed.push({ userId: entry.userId, error: error.message })
    }
  }

  return apiSuccess({
    summary: {
      total: users.length,
      sent: results.sent.length,
      failed: results.failed.length,
    },
    sent: results.sent,
    failed: results.failed,
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { createAuditLog } from '@/lib/audit/logger'
import { revalidatePath } from 'next/cache'
import { ExamAttendanceStatus } from '@prisma/client'
import { markExamAttendance } from '@/lib/exams/attendance'

export async function POST(req: NextRequest) {
  try {
    const staff = await requireStaff()

    const { membershipId, bookingId, sittingId } = await req.json()

    if (!membershipId && !bookingId && !sittingId) {
      return NextResponse.json(
        { error: 'Must provide either membershipId, bookingId, or sittingId' },
        { status: 400 }
      )
    }

    const result = await markExamAttendance({
      membershipId,
      bookingId,
      sittingId,
      status: ExamAttendanceStatus.ABSENT,
      notes: 'Marked as no-show by staff',
      recordedBy: staff.id,
    })

    await createAuditLog({
      action: 'UPDATE',
      entity: 'ExamAttendance',
      entityId: result.attendance.id,
      userId: staff.id,
      details: {
        bookingId: result.bookingId,
        membershipId: result.membershipId,
        sittingId: result.sittingId,
        status: 'ABSENT',
        reason: 'Staff marked as NO-SHOW',
      },
    })

    revalidatePath('/staff/exams')
    revalidatePath('/student/exams')
    if (result.poolId) revalidatePath(`/staff/exams/pools/${result.poolId}`)
    if (result.eventId) revalidatePath(`/staff/exams/events/${result.eventId}`)
    if (result.userId) revalidatePath(`/staff/students/${result.userId}`)

    return NextResponse.json({ success: true, message: 'Successfully marked as NO_SHOW' })
  } catch (error: any) {
    console.error('Mark NO-SHOW error:', error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireAuth } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { z } from 'zod'

const answerSchema = z.object({
  sessionId: z.string().cuid(),
  questionId: z.string().cuid(),
  answer: z.string(),
})

// POST /api/applicant/aptitude/answer
export const POST = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  const body = await req.json()
  const parsed = answerSchema.safeParse(body)
  if (!parsed.success) return apiError(parsed.error.issues[0].message)

  const { sessionId, questionId, answer } = parsed.data

  // Validate session belongs to user and is active
  const session = await prismaUnfiltered.aptitudeTestSession.findUnique({
    where: { id: sessionId },
  })

  if (!session) return apiError('Session not found', 404)
  if (session.userId !== user.id) return apiError('Unauthorized', 403)
  if (session.status !== 'IN_PROGRESS') return apiError(`Session is ${session.status}`, 403)
  
  if (session.expiresAt && new Date() > session.expiresAt) {
    await prismaUnfiltered.aptitudeTestSession.update({
      where: { id: sessionId },
      data: { status: 'TIMED_OUT' }
    })
    return apiError('Time expired', 403)
  }

  // Update answer
  const updatedAnswer = await prismaUnfiltered.aptitudeAnswer.update({
    where: { sessionId_questionId: { sessionId, questionId } },
    data: { 
      selectedAnswer: answer,
      answeredAt: new Date(),
    }
  })

  return apiSuccess({ saved: true })
})

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getAptitudeConfig } from '@/lib/settings'
import { requireAuth } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { z } from 'zod'

const eventSchema = z.object({
  sessionId: z.string().cuid(),
  eventType: z.enum(['TAB_SWITCH', 'FULLSCREEN_EXIT']),
})

// POST /api/applicant/aptitude/anti-cheat
export const POST = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  const body = await req.json()
  const parsed = eventSchema.safeParse(body)
  if (!parsed.success) return apiError(parsed.error.issues[0].message)

  const { sessionId, eventType } = parsed.data

  const session = await prismaUnfiltered.aptitudeTestSession.findUnique({
    where: { id: sessionId },
  })

  if (!session) return apiError('Session not found', 404)
  if (session.userId !== user.id) return apiError('Unauthorized', 403)
  if (session.status !== 'IN_PROGRESS') return apiSuccess({ ignored: true })

  // Get limits
  const config = await getAptitudeConfig()
  const maxViolations = config.aptitude_max_tab_switches

  let tabSwitchCount = session.tabSwitchCount
  let fullscreenExits = session.fullscreenExits

  if (eventType === 'TAB_SWITCH') tabSwitchCount++
  if (eventType === 'FULLSCREEN_EXIT') fullscreenExits++

  let status: any = session.status

  if (tabSwitchCount + fullscreenExits > maxViolations) {
    status = 'FLAGGED'
  }

  await prismaUnfiltered.aptitudeTestSession.update({
    where: { id: sessionId },
    data: {
      tabSwitchCount,
      fullscreenExits,
      status,
    }
  })

  return apiSuccess({ status })
})

