import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { sendPasswordResetEmail } from '@/lib/email/service'
import { generateToken } from '@/lib/auth/helpers'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'

export const POST = withErrorHandler(async (req: NextRequest) => {
  let body: any
  try {
    body = await req.json()
  } catch (e) {
    return apiError('Invalid request body', 400)
  }

  const { email } = body
  if (!email) {
    return apiError('Email is required', 400)
  }

  // Find user by either personal email or academy email
  const user = await prisma.user.findFirst({
    where: {
      OR: [
        { email: { equals: email, mode: 'insensitive' } },
        { academyEmail: { equals: email, mode: 'insensitive' } },
      ],
    },
    include: {
      profile: true,
    },
  })

  // Silently return success to prevent email enumeration
  if (!user) {
    return apiSuccess({ message: 'If an account exists, a reset link has been sent' })
  }

  // Generate a reset token valid for 1 hour
  const token = generateToken()
  const tokenExpires = new Date(Date.now() + 60 * 60 * 1000)

  await prisma.user.update({
    where: { id: user.id },
    data: {
      passwordResetToken: token,
      passwordResetExpires: tokenExpires,
    },
  })

  // Send the email to personal email (primary)
  const targetEmail = user.personalEmail || user.email
  await sendPasswordResetEmail(targetEmail, user.profile?.firstName || 'User', token).catch(
    console.error
  )

  await createAuditLog({
    action: AuditAction.UPDATE,
    entity: 'User',
    entityId: user.id,
    userId: user.id,
    description: 'Password reset link requested',
  })

  return apiSuccess({ message: 'If an account exists, a reset link has been sent' })
})

import { NextResponse } from 'next/server'
import { generateRegistrationOptions } from '@simplewebauthn/server'
import { getAuthSession } from '@/lib/auth/auth-options'
import { prismaBase as prisma } from '@/lib/prisma/db-base'
import { rpConfig } from '@/lib/auth/passkey-config'

type AuthenticatorTransport = 'ble' | 'cable' | 'hybrid' | 'internal' | 'nfc' | 'smart-card' | 'usb'

const VALID_TRANSPORTS = new Set<string>(['ble', 'cable', 'hybrid', 'internal', 'nfc', 'smart-card', 'usb'])

export async function POST() {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return new NextResponse('Unauthorized', { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      include: {
        profile: { select: { firstName: true, lastName: true } },
        passkeys: { select: { credentialId: true, transports: true } },
      },
    })

    if (!user) {
      return new NextResponse('User not found', { status: 404 })
    }

    // Cleanup expired challenges
    await prisma.passkeyChallenge.deleteMany({
      where: { expiresAt: { lt: new Date() } },
    })

    const displayName = user.profile
      ? `${user.profile.firstName} ${user.profile.lastName}`
      : user.email

    // Build excludeCredentials defensively — filter invalid transports
    const excludeCredentials = user.passkeys
      .filter((pk) => pk.credentialId)
      .map((pk) => ({
        id: pk.credentialId,
        transports: (pk.transports || []).filter(
          (t) => VALID_TRANSPORTS.has(t)
        ) as AuthenticatorTransport[],
      }))

    const options = await generateRegistrationOptions({
      rpName: rpConfig.rpName,
      rpID: rpConfig.rpID,
      userName: user.academyEmail || user.email,
      userDisplayName: displayName,
      excludeCredentials,
      authenticatorSelection: {
        residentKey: 'preferred',
        userVerification: 'preferred',
      },
      attestationType: 'none',
    })

    // Store challenge for verification
    await prisma.passkeyChallenge.create({
      data: {
        userId: session.user.id,
        challenge: options.challenge,
        type: 'registration',
        expiresAt: new Date(Date.now() + 10 * 60 * 1000), // 10 minutes
      },
    })

    return NextResponse.json({ options })
  } catch (error: any) {
    console.error('[PASSKEY_REGISTER_OPTIONS]', error?.message || error)
    return NextResponse.json(
      { error: 'Failed to generate registration options', detail: error?.message },
      { status: 500 }
    )
  }
}

import { NextResponse } from 'next/server'
import { verifyRegistrationResponse } from '@simplewebauthn/server'
import { getAuthSession } from '@/lib/auth/auth-options'
import { prismaBase as prisma } from '@/lib/prisma/db-base'
import { rpConfig } from '@/lib/auth/passkey-config'
import { createAuditLog } from '@/lib/audit/logger'

export async function POST(req: Request) {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return new NextResponse('Unauthorized', { status: 401 })
    }

    const body = await req.json()
    const { credential, name } = body

    if (!credential) {
      return new NextResponse('Missing credential', { status: 400 })
    }

    // Atomically consume the challenge to prevent replay race conditions
    const storedChallenge = await prisma.$transaction(async (tx) => {
      const challenge = await tx.passkeyChallenge.findFirst({
        where: {
          userId: session.user.id,
          type: 'registration',
          expiresAt: { gt: new Date() },
        },
        orderBy: { createdAt: 'desc' },
      })
      if (!challenge) return null
      await tx.passkeyChallenge.delete({ where: { id: challenge.id } })
      return challenge
    })

    if (!storedChallenge) {
      return new NextResponse('Challenge expired or not found. Please try again.', { status: 400 })
    }

    const verification = await verifyRegistrationResponse({
      response: credential,
      expectedChallenge: storedChallenge.challenge,
      expectedOrigin: rpConfig.origin as string[],
      expectedRPID: rpConfig.rpID,
      requireUserVerification: true,
    })

    if (!verification.verified || !verification.registrationInfo) {
      return NextResponse.json(
        { error: 'Verification failed. Ensure you are on the correct domain.' },
        { status: 400 }
      )
    }

    const {
      credential: cred,
      credentialDeviceType,
      credentialBackedUp,
    } = verification.registrationInfo

    // Count existing passkeys for auto-naming
    const existingCount = await prisma.passkey.count({
      where: { userId: session.user.id },
    })

    const passkeyName = name || `Passkey ${existingCount + 1}`

    // Store the credential — handle potential type edge cases
    const publicKeyBytes =
      cred.publicKey instanceof Uint8Array
        ? Buffer.from(cred.publicKey)
        : Buffer.from(cred.publicKey as unknown as ArrayBuffer)

    const passkey = await prisma.passkey.create({
      data: {
        userId: session.user.id,
        credentialId: cred.id,
        publicKey: publicKeyBytes,
        counter: BigInt(cred.counter ?? 0),
        deviceType: credentialDeviceType || 'singleDevice',
        backedUp: credentialBackedUp ?? false,
        transports: Array.isArray(credential.response?.transports)
          ? credential.response.transports
          : [],
        name: passkeyName,
      },
    })

    await createAuditLog({
      action: 'PASSKEY_REGISTERED',
      entity: 'users',
      entityId: session.user.id,
      userId: session.user.id,
      description: `Registered passkey: ${passkeyName}`,
    })

    return NextResponse.json({
      success: true,
      passkeyId: passkey.id,
      name: passkeyName,
    })
  } catch (error: any) {
    console.error('[PASSKEY_REGISTER_VERIFY]', error?.message || error)
    return NextResponse.json(
      { error: 'Registration verification failed', detail: error?.message },
      { status: 500 }
    )
  }
}

import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { hashPassword } from '@/lib/auth/helpers'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'

export const POST = withErrorHandler(async (req: NextRequest) => {
  let body: any
  try {
    body = await req.json()
  } catch (e) {
    return apiError('Invalid request body', 400)
  }

  const { token, password } = body

  if (!token || !password) {
    return apiError('Token and password are required', 400)
  }

  if (password.length < 8) {
    return apiError('Password must be at least 8 characters long', 400)
  }

  const user = await prisma.user.findFirst({
    where: {
      passwordResetToken: token,
      passwordResetExpires: {
        gt: new Date(),
      },
    },
  })

  if (!user) {
    return apiError('Invalid or expired reset token', 400)
  }

  const hashedPassword = await hashPassword(password)

  await prisma.user.update({
    where: { id: user.id },
    data: {
      password: hashedPassword,
      passwordResetToken: null,
      passwordResetExpires: null,
      loginAttempts: 0,
      lockedUntil: null,
    },
  })

  await createAuditLog({
    action: AuditAction.UPDATE,
    entity: 'User',
    entityId: user.id,
    userId: user.id,
    description: 'Password successfully reset',
  })

  return apiSuccess({ message: 'Password reset successful' })
})

interface CacheEntry<T> {
  data: T
  timestamp: Date
}

export class BadgeCountsCache {
  private static instance: BadgeCountsCache
  private globalCache: Map<string, CacheEntry<any>> = new Map()
  private userCache: Map<string, CacheEntry<any>> = new Map()
  private readonly GLOBAL_TTL = 60 * 1000 // 60 seconds
  private readonly USER_TTL = 45 * 1000 // 45 seconds

  private constructor() {}

  public static getInstance(): BadgeCountsCache {
    if (!BadgeCountsCache.instance) {
      BadgeCountsCache.instance = new BadgeCountsCache()
    }
    return BadgeCountsCache.instance
  }

  getGlobal(key: string) {
    const entry = this.globalCache.get(key)
    if (!entry) return null
    if (Date.now() - entry.timestamp.getTime() > this.GLOBAL_TTL) {
      this.globalCache.delete(key)
      return null
    }
    return entry.data
  }

  setGlobal(key: string, data: any) {
    this.globalCache.set(key, { data, timestamp: new Date() })
  }

  getUser(userId: string, key: string) {
    const compositeKey = `${userId}:${key}`
    const entry = this.userCache.get(compositeKey)
    if (!entry) return null
    if (Date.now() - entry.timestamp.getTime() > this.USER_TTL) {
      this.userCache.delete(compositeKey)
      return null
    }
    return entry.data
  }

  setUser(userId: string, key: string, data: any) {
    const compositeKey = `${userId}:${key}`
    this.userCache.set(compositeKey, { data, timestamp: new Date() })
  }

  invalidateUser(userId: string) {
    // Clear all keys starting with userId:
    for (const key of this.userCache.keys()) {
      if (key.startsWith(`${userId}:`)) {
        this.userCache.delete(key)
      }
    }
  }

  invalidateGlobal() {
    this.globalCache.clear()
  }
}

export const badgeCountsCache = BadgeCountsCache.getInstance()

import { NextRequest, NextResponse } from 'next/server'
import prisma, { prismaUnfiltered } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { badgeCountsCache } from './cache'

export async function GET(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = session.user.id
    const role = session.user.role

    // Try user cache first
    const cachedUser = badgeCountsCache.getUser(userId, 'badges')
    if (cachedUser) return NextResponse.json(cachedUser)

    const counts: any = {
      pendingApplicants: 0,
      pendingEnrollments: 0,
      pendingPayments: 0,
      unreadMessages: 0,
      unreadNotifications: 0,
    }

    // Role-based counts
    if (['SUPER_ADMIN', 'ADMIN', 'STAFF'].includes(role)) {
      const globalCache = badgeCountsCache.getGlobal('staff_badges')
      if (globalCache) {
        Object.assign(counts, globalCache)
      } else {
        const [applicants, enrollments, payments] = await Promise.allSettled([
          prismaUnfiltered.user.count({ where: { role: 'APPLICANT', status: 'PENDING' } }),
          prismaUnfiltered.enrollment.count({ where: { status: 'PENDING' } }),
          prismaUnfiltered.payment.count({ where: { status: 'PENDING' } }),
        ])

        counts.pendingApplicants = applicants.status === 'fulfilled' ? applicants.value : 0
        counts.pendingEnrollments = enrollments.status === 'fulfilled' ? enrollments.value : 0
        counts.pendingPayments = payments.status === 'fulfilled' ? payments.value : 0

        badgeCountsCache.setGlobal('staff_badges', {
          pendingApplicants: counts.pendingApplicants,
          pendingEnrollments: counts.pendingEnrollments,
          pendingPayments: counts.pendingPayments,
        })
      }
    }

    // User-specific counts
    const [messages, notifications] = await Promise.allSettled([
      prismaUnfiltered.message.count({ where: { recipientId: userId, isRead: false } }),
      prismaUnfiltered.notification.count({ where: { userId, isRead: false } }),
    ])

    counts.unreadMessages = messages.status === 'fulfilled' ? messages.value : 0
    counts.unreadNotifications = notifications.status === 'fulfilled' ? notifications.value : 0

    // Save to user cache
    badgeCountsCache.setUser(userId, 'badges', counts)

    return NextResponse.json(counts)
  } catch (error) {
    console.error('Error fetching staff badge counts:', error)
    return NextResponse.json({
      pendingApplicants: 0,
      pendingEnrollments: 0,
      pendingPayments: 0,
      unreadMessages: 0,
      unreadNotifications: 0,
      error: 'Partial failure fetching counts',
    })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getStudentStatus } from '@/lib/access-control'
import { getAuthSession } from '@/lib/auth/helpers'
import { addHours } from 'date-fns'

function escapeString(str: string | null | undefined) {
  if (!str) return ''
  return str.replace(/[\\;,]/g, (match) => `\\${match}`).replace(/\n/g, '\\n')
}

function formatDateToiCal(date: Date) {
  return date.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z'
}

export async function GET(req: NextRequest, { params }: { params: Promise<{ userId: string }> }) {
  const { userId } = await params

  if (!userId) {
    return new NextResponse('User ID required', { status: 400 })
  }

  // Auth check: only the user themselves or staff can access this calendar
  const session = await getAuthSession()
  if (!session) {
    return new NextResponse('Unauthorized', { status: 401 })
  }
  const staffRoles = ['ADMIN', 'SUPER_ADMIN', 'STAFF']
  if (session.user.id !== userId && !staffRoles.includes(session.user.role)) {
    return new NextResponse('Forbidden', { status: 403 })
  }

  try {
    const { enrollmentType: resolvedEnrollmentType } = await getStudentStatus(userId)

    const [
      personalEvents,
      examBookings,
      semesters,
      enrollments,
      adminEvents,
      sittingAssignments,
      tuitionRuns,
      examEvents,
      examPools,
    ] = await Promise.all([
      prismaUnfiltered.studentCalendarEvent.findMany({
        where: { userId },
        orderBy: { startDate: 'asc' },
      }),
      prismaUnfiltered.examBooking.findMany({
        where: { userId, deletedAt: null },
        select: {
          id: true,
          moduleCode: true,
          examDate: true,
          examCategory: true,
          status: true,
        },
      }),
      prismaUnfiltered.semester.findMany({
        where: { isActive: true },
        orderBy: { startDate: 'asc' },
        select: { id: true, name: true, startDate: true, endDate: true },
      }),
      prismaUnfiltered.enrollment.findMany({
        where: { userId, status: { in: ['ACTIVE', 'APPROVED', 'ENROLLED'] } },
        include: {
          course: {
            include: {
              classes: {
                select: {
                  id: true,
                  name: true,
                  startDate: true,
                  endDate: true,
                  schedule: true,
                  recurrenceType: true,
                  recurrenceDays: true,
                  recurrenceUntil: true,
                },
              },
            },
          },
        },
      }),
      prismaUnfiltered.adminCalendarEvent.findMany({
        where: {
          deletedAt: null,
          OR: [
            { visibleTo: { in: ['ALL', 'STUDENTS', 'EXAM_ONLY', 'MODULAR', 'FULL_TIME'] } },
            { visibleTo: 'SPECIFIC_USER', targetUserId: userId },
          ],
        },
        orderBy: { startDate: 'asc' },
      }),
      prismaUnfiltered.examSittingAssignment.findMany({
        where: { userId, status: { not: 'CANCELLED' } },
        include: {
          sitting: {
            include: {
              event: { select: { name: true } },
              examComponent: { select: { code: true, name: true } },
            },
          },
        },
      }),
      prismaUnfiltered.tuitionRun.findMany({
        where: { status: { in: ['OPEN', 'SCHEDULED'] } },
      }),
      prismaUnfiltered.examEvent.findMany({
        where: { deletedAt: null, endDate: { gte: new Date() } },
        select: { id: true, name: true, joinDeadline: true, paymentDeadline: true },
      }),
      prismaUnfiltered.examPool.findMany({
        where: {
          memberships: { some: { userId } },
        },
        select: { id: true, name: true, examStartTime: true, examEndTime: true },
      }),
    ])

    const enrollmentType = resolvedEnrollmentType || 'UNKNOWN'
    const icsEvents: string[] = []

    // 1. Personal events
    personalEvents.forEach((evt) => {
      const start = evt.startDate
      const end = evt.endDate || addHours(start, 1)
      icsEvents.push(`BEGIN:VEVENT
UID:personal-${evt.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:${escapeString(evt.title)}
DESCRIPTION:${escapeString(evt.description || 'Personal event')}
END:VEVENT`)
    })

    // 2. Exam bookings
    examBookings.forEach((exam) => {
      if (exam.examDate) {
        const start = exam.examDate
        const end = addHours(start, 2)
        icsEvents.push(`BEGIN:VEVENT
UID:exam-${exam.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:Exam: ${escapeString(exam.moduleCode || 'Module')} (${exam.examCategory === 'OFFICIAL_EASA' ? 'EASA' : 'Internal'})
DESCRIPTION:Status: ${escapeString(exam.status)}
END:VEVENT`)
      }
    })

    // 3. Semesters
    semesters.forEach((sem) => {
      if (sem.startDate) {
        icsEvents.push(`BEGIN:VEVENT
UID:sem-start-${sem.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(sem.startDate)}
DTEND:${formatDateToiCal(addHours(sem.startDate, 1))}
SUMMARY:${escapeString(sem.name)} — Starts
DESCRIPTION:Academic semester begins
END:VEVENT`)
      }
      if (sem.endDate) {
        icsEvents.push(`BEGIN:VEVENT
UID:sem-end-${sem.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(sem.endDate)}
DTEND:${formatDateToiCal(addHours(sem.endDate, 1))}
SUMMARY:${escapeString(sem.name)} — Ends
DESCRIPTION:Academic semester concludes
END:VEVENT`)
      }
    })

    // 4. Class schedules via enrollments
    enrollments.forEach((enrollment: any) => {
      enrollment.course?.classes?.forEach((cls: any) => {
        if (cls.startDate) {
          const start = new Date(cls.startDate)
          const end = cls.endDate ? new Date(cls.endDate) : addHours(start, 2)
          icsEvents.push(`BEGIN:VEVENT
UID:class-${cls.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:${escapeString(cls.name || `Class: ${enrollment.course.code}`)}
DESCRIPTION:Course Class Schedule
END:VEVENT`)
        }
      })
    })

    // 5. Admin events
    adminEvents.forEach((evt: any) => {
      if (evt.visibleTo === 'EXAM_ONLY' && enrollmentType !== 'EXAM_ONLY') return
      if (evt.visibleTo === 'MODULAR' && enrollmentType !== 'MODULAR') return
      if (evt.visibleTo === 'FULL_TIME' && enrollmentType !== 'FULL_TIME') return
      if (evt.visibleTo === 'SPECIFIC_USER' && evt.targetUserId !== userId) return

      const start = evt.startDate
      const end = evt.endDate || addHours(start, 1)
      icsEvents.push(`BEGIN:VEVENT
UID:admin-${evt.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:${escapeString(evt.title)}
DESCRIPTION:${escapeString(evt.description || 'Academy Event')}
END:VEVENT`)
    })

    // 6. Exam sitting assignments
    sittingAssignments.forEach((assignment: any) => {
      const sitting = assignment.sitting
      if (sitting?.startTime) {
        const start = sitting.startTime
        const end = sitting.endTime || addHours(start, 2)
        icsEvents.push(`BEGIN:VEVENT
UID:sitting-${assignment.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:Exam Sitting: ${escapeString(sitting.examComponent?.code || 'Module')}
DESCRIPTION:${escapeString(sitting.event?.name || '')} — ${escapeString(sitting.sessionType || '')} session
END:VEVENT`)
      }
    })

    // 7. Tuition runs
    tuitionRuns.forEach((run: any) => {
      if (run.startDatetime) {
        const start = run.startDatetime
        const end = run.endDatetime || addHours(start, 2)
        icsEvents.push(`BEGIN:VEVENT
UID:revision-${run.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:Revision: ${escapeString(run.title)}
DESCRIPTION:${escapeString(run.description || 'Module revision and study support session.')}
END:VEVENT`)
      }
    })

    // 8. Exam Event deadlines
    examEvents.forEach((evt: any) => {
      if (evt.joinDeadline) {
        const start = evt.joinDeadline
        icsEvents.push(`BEGIN:VEVENT
UID:event-join-${evt.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(addHours(start, 1))}
SUMMARY:Exam Pool Deadline: ${escapeString(evt.name)}
DESCRIPTION:Join or apply deadline for this exam event
END:VEVENT`)
      }

      if (evt.paymentDeadline) {
        const start = evt.paymentDeadline
        icsEvents.push(`BEGIN:VEVENT
UID:event-pay-${evt.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(addHours(start, 1))}
SUMMARY:Exam Payment Deadline: ${escapeString(evt.name)}
DESCRIPTION:Final day to clear payment for bookings
END:VEVENT`)
      }
    })

    // 9. Exam pools
    examPools.forEach((pool: any) => {
      if (pool.examStartTime) {
        const start = pool.examStartTime
        const end = pool.examEndTime || addHours(start, 2)
        icsEvents.push(`BEGIN:VEVENT
UID:pool-${pool.id}@aerojet-academy.com
DTSTAMP:${formatDateToiCal(new Date())}
DTSTART:${formatDateToiCal(start)}
DTEND:${formatDateToiCal(end)}
SUMMARY:Pool Exam Day: ${escapeString(pool.name)}
DESCRIPTION:Scheduled exam date for this pool
END:VEVENT`)
      }
    })

    const iCalContent = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//Aerojet Academy//Academic Calendar//EN',
      'CALSCALE:GREGORIAN',
      ...icsEvents,
      'END:VCALENDAR',
    ].join('\r\n')

    return new NextResponse(iCalContent, {
      headers: {
        'Content-Type': 'text/calendar; charset=utf-8',
        'Content-Disposition': 'attachment; filename="aerojet-calendar.ics"',
      },
    })
  } catch (error) {
    console.error('Failed to generate iCal feed:', error)
    return new NextResponse('Internal server error', { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getSignedUrl } from '@/lib/storage/supabase-storage'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { getRequestContext } from '@/lib/server/request-context'

export const GET = withErrorHandler(async (
  req: NextRequest,
  ctx: { params: Promise<{ id: string }> }
) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)

  const { id } = await ctx.params

  const certificate = await prismaUnfiltered.certificate.findUnique({
    where: { id },
    select: {
      id: true,
      certificateId: true,
      sessionId: true,
      studentId: true,
      pdfUrl: true,
      issuedAt: true,
      moduleCode: true,
      score: true,
      percentage: true,
      verified: true,
    },
  })

  if (!certificate) return apiNotFound('Certificate not found')

  const isStudent = session.user.role === 'STUDENT'
  const isStaff = ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER'].includes(session.user.role)

  if (isStudent && certificate.studentId !== session.user.id) {
    return apiError('You do not have access to this certificate', 403)
  }

  if (!isStudent && !isStaff) {
    return apiError('Unauthorized', 401)
  }

  if (!certificate.pdfUrl) {
    return apiError('Certificate PDF has not been generated yet', 404)
  }

  const ctx2 = await getRequestContext().catch(() => ({ ipAddress: undefined, userAgent: undefined }))
  await createAuditLog({
    userId: session.user.id,
    action: AuditAction.SYSTEM_UPDATE,
    entity: 'Certificate',
    entityId: certificate.id,
    description: `Certificate PDF downloaded: ${certificate.certificateId}`,
    ipAddress: ctx2.ipAddress ?? undefined,
    userAgent: ctx2.userAgent ?? undefined,
  })

  // Return JSON with signed download URL for the client to fetch/stream
  const signedUrl = await getSignedUrl(certificate.pdfUrl, 60 * 60 * 24)
  if (!signedUrl) {
    return apiError('Unable to generate download URL', 500)
  }

  const filename = `Certificate_${certificate.certificateId}.pdf`

  return apiSuccess({
    certificateId: certificate.certificateId,
    issuedAt: certificate.issuedAt.toISOString(),
    moduleCode: certificate.moduleCode,
    score: certificate.score,
    percentage: certificate.percentage,
    verified: certificate.verified,
    downloadUrl: signedUrl,
    filename,
  })
})

export const DELETE = withErrorHandler(async (
  _req: NextRequest,
  ctx: { params: Promise<{ id: string }> }
) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)

