})

import { NextRequest } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import {
  createCertificate,
  getCertificatesEnabled,
  getCertificateDownloadUrl,
} from '@/lib/certificates/generator'

export const POST = withErrorHandler(async (req: NextRequest) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)

  const certificatesEnabled = await getCertificatesEnabled()
  if (!certificatesEnabled) {
    return apiError('Certificate generation is disabled', 403)
  }

  const STAFF_ROLES = ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER']
  const isAuthorized = STAFF_ROLES.includes(session.user.role)
  if (!isAuthorized) {
    return apiError('Only staff can generate certificates', 403)
  }

  const body = await req.json().catch(() => ({}))
  const { sessionId } = body

  if (!sessionId) return apiError('sessionId is required', 400)

  const examSession = await prismaUnfiltered.internalExamSession.findUnique({
    where: { id: sessionId },
    select: {
      id: true,
      studentId: true,
      bankId: true,
      score: true,
      percentage: true,
      passed: true,
      isPublished: true,
      status: true,
      bank: {
        select: {
          name: true,
          moduleCode: true,
          courseId: true,
          certificateEnabled: true,
          course: { select: { code: true, name: true } },
          ruleSet: true,
        },
      },
    },
  })

  if (!examSession) return apiError('Exam session not found', 404)
  if (!examSession.bank.certificateEnabled) {
    return apiError('Certificate generation is disabled for this exam bank', 403)
  }
  if (!examSession.isPublished) return apiError('Results must be published before generating a certificate', 409)
  if (examSession.status !== 'COMPLETED' && examSession.status !== 'TIMED_OUT') {
    return apiError('Exam session must be completed to generate a certificate', 409)
  }

  const result = await createCertificate({
    sessionId: examSession.id,
    studentId: examSession.studentId,
    courseId: examSession.bank.courseId,
    moduleCode: examSession.bank.moduleCode,
    score: examSession.score ?? 0,
    percentage: examSession.percentage ?? 0,
    passMarkPct: undefined,
    issuedBy: session.user.id,
  })

  return apiSuccess(result)
})

export const GET = withErrorHandler(async (req: NextRequest) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)

  const STUDENT_ROLES = ['STUDENT']
  const isStudent = STUDENT_ROLES.includes(session.user.role)
  const isStaff = ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER'].includes(session.user.role)

  if (!isStudent && !isStaff) {
    return apiError('Unauthorized', 401)
  }

  const url = new URL(req.url)
  const sessionIdFilter = url.searchParams.get('sessionId')

  const where: any = {}
  if (isStudent) {
    where.studentId = session.user.id
  }
  if (sessionIdFilter) {
    where.sessionId = sessionIdFilter
  }

  const certificates = await prismaUnfiltered.certificate.findMany({
    where,
    include: {
      student: {
        select: {
          id: true,
          email: true,
          profile: { select: { firstName: true, lastName: true } },
          studentProfile: { select: { studentId: true } },
        },
      },
    },
    orderBy: { issuedAt: 'desc' },
  })

  const result = await Promise.all(
    certificates.map(async (cert) => {
      const downloadUrl = cert.pdfUrl
        ? await getCertificateDownloadUrl(cert.pdfUrl)
        : null
      return {
        id: cert.id,
        certificateId: cert.certificateId,
        sessionId: cert.sessionId,
        studentId: cert.studentId,
        studentName: cert.student?.profile
          ? `${cert.student.profile.firstName} ${cert.student.profile.lastName}`
          : cert.student?.email || '',
        moduleCode: cert.moduleCode,
        score: cert.score,
        percentage: cert.percentage,
        issuedAt: cert.issuedAt.toISOString(),
        issuedBy: cert.issuedBy,
        verified: cert.verified,
        downloadUrl,
      }
    })
  )

  return apiSuccess(result)
})

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { sendAptitudeTestReminderEmail } from '@/lib/email/admissions'

/**
 * CRON: Aptitude Test Reminders
 * Runs daily — nudges applicants who have been in APTITUDE_PENDING for >3 days
 * without completing their test.
 */
export async function GET(req: NextRequest) {
  const secret = req.headers.get('authorization')
  if (secret !== `Bearer ${process.env.CRON_SECRET}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()
    const threeDaysAgo = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000)

    // Find applications stuck in APTITUDE_PENDING for over 3 days
    const pending = await prismaUnfiltered.application.findMany({
      where: {
        stage: 'APTITUDE_PENDING',
        updatedAt: { lte: threeDaysAgo },
      },
      include: {
        user: {
          select: {
            email: true,
            profile: { select: { firstName: true } },
          },
        },
      },
    })

    let sent = 0
    for (const app of pending) {
      if (!app.user) continue
      const firstName = app.user.profile?.firstName || 'Applicant'
      const deadline = app.completionDeadline
        ? app.completionDeadline.toLocaleDateString('en-GB', { year: 'numeric', month: 'long', day: 'numeric' })
        : 'as soon as possible'

      await sendAptitudeTestReminderEmail(app.user.email, firstName, deadline)
      sent++
    }

    return NextResponse.json({
      success: true,
      message: `Sent ${sent} aptitude test reminders`,
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('[Cron] Aptitude test reminders failed:', error)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { env } from '@/lib/env'
import { createAuditLog } from '@/lib/audit/logger'
import {
  BACKUP_MODELS,
  exportAllTables,
  sendBackupEmail,
  isBackupDue,
  type BackupSchedule,
} from '@/lib/backup'

// Cron job: Automated database backup
// Runs daily at 4:00 AM — checks schedule settings and sends backup if due
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    // Read schedule settings
    const settings = await prisma.systemSetting.findMany({
      where: {
        key: { in: ['backup_schedule', 'backup_email', 'backup_custom_days', 'backup_last_run'] },
      },
    })

    const vals: Record<string, string> = {}
    for (const s of settings) vals[s.key] = s.value

    const schedule = (vals.backup_schedule || 'off') as BackupSchedule
    const email = vals.backup_email || ''
    const customDays = parseInt(vals.backup_custom_days || '7', 10)
    const lastRun = vals.backup_last_run || null

    // Check if backup is due
    if (!isBackupDue(schedule, lastRun, customDays)) {
      return NextResponse.json({
        success: true,
        message: 'Backup not due yet',
        schedule,
        lastRun,
      })
    }

    if (!email) {
      return NextResponse.json({
        success: false,
        message: 'Backup is due but no email address configured',
      })
    }

    // Run the backup
    const backup = await exportAllTables()
    const { jsonFilename, htmlFilename } = await sendBackupEmail(email, backup)

    // Update last run timestamp
    await prisma.systemSetting.upsert({
      where: { key: 'backup_last_run' },
      update: { value: new Date().toISOString() },
      create: { key: 'backup_last_run', value: new Date().toISOString(), type: 'STRING' },
    })

    await createAuditLog({
      action: 'EXPORT',
      entity: 'System',
      entityId: 'database-backup',
      description: `Scheduled ${schedule} backup sent to ${email} (${BACKUP_MODELS.length} tables)`,
    })

    return NextResponse.json({
      success: true,
      message: `Backup sent to ${email}`,
      schedule,
      files: [jsonFilename, htmlFilename],
    })
  } catch (err: any) {
    console.error('[Cron Backup] Error:', err.message)
    return NextResponse.json({ success: false, error: err.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { env } from '@/lib/env'

// Cron job: Expire Browser Exam Keys (BEKs) past their rotation window.
// Sessions with bekExpiresAt < now have their BEK cleared so the key cannot
// be reused after expiry. Runs daily.
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()

    const expired = await prismaUnfiltered.internalExamSession.findMany({
      where: {
        bekExpiresAt: { lt: now },
        status: 'IN_PROGRESS',
      },
      select: { id: true, bankId: true, studentId: true },
    })

    if (expired.length === 0) {
      return NextResponse.json({ success: true, expired: 0 })
    }

    await prismaUnfiltered.internalExamSession.updateMany({
      where: { id: { in: expired.map((s) => s.id) } },
      data: { bekExpiresAt: null },
    })

    await createAuditLog({
      action: 'SYSTEM_UPDATE',
      entity: 'InternalExamSession',
      entityId: 'cron',
      description: `BEK rotation expired ${expired.length} session key(s)`,
    })

    return NextResponse.json({ success: true, expired: expired.length })
  } catch (error: any) {
    console.error('[CRON] bek-rotation error:', error)
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { env } from '@/lib/env'

// Cron job: Check exam events for automatic status transitions
// - OPEN events past end date → mark COMPLETED
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()
    const results = { completed: 0, errors: [] as string[] }

    // Mark past events as COMPLETED (valid statuses: OPEN, CONFIRMED, POSTPONED)
    const pastEvents = await prisma.examEvent.findMany({
      where: {
        status: { in: ['OPEN', 'CONFIRMED', 'POSTPONED'] },
        endDate: { lt: now },
      },
    })

    for (const event of pastEvents) {
      try {
        await prisma.examEvent.update({
          where: { id: event.id },
          data: { status: 'COMPLETED' },
        })
        results.completed++

        await createAuditLog({
          action: 'UPDATE',
          entity: 'ExamEvent',
          entityId: event.id,
          userId: undefined,
          details: { transition: 'auto-completed', previousStatus: event.status },
        })
      } catch (err: any) {
        results.errors.push(`Event ${event.id}: ${err.message}`)
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Event check completed',
      results,
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('Cron check-events error:', error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { evaluateGoNoGo, executeGo, executeNoGo } from '@/lib/events/go-no-go'
import { env } from '@/lib/env'

// Cron job: Check pools that should be auto-confirmed or failed
// Runs daily — pools that haven't reached 25 members by T-21 days before exam are failed
export async function GET(req: NextRequest) {
  // Verify cron secret strictly
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET

  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()

    // Evaluate events at or past the payment deadline using the new event-level viability rules.
    const eventsToEvaluate = await prisma.examEvent.findMany({
      where: {
        paymentDeadline: { lte: now },
        status: { in: ['OPEN', 'CONFIRMED'] },
      },
      select: { id: true, name: true, status: true },
    })

    const results = {
      checked: eventsToEvaluate.length,
      confirmedEvents: 0,
      cancelledEvents: 0,
      reviewEvents: 0,
      confirmedPools: 0,
      errors: [] as string[],
    }

    for (const event of eventsToEvaluate) {
      try {
        const evaluation = await evaluateGoNoGo(event.id, { unfiltered: true })

        if (evaluation.decision === 'GO' || evaluation.decision === 'GO_WITH_UNDERFILLED_SITTINGS') {
          if (event.status !== 'CONFIRMED') {
            await executeGo(event.id, 'SYSTEM')
            results.confirmedEvents++
            // Count pools now LOCKED as a result of this executeGo call
            const lockedCount = await prisma.examPool.count({
              where: { eventId: event.id, status: 'LOCKED' },
            })
            results.confirmedPools += lockedCount
          }
        } else if (evaluation.decision === 'NO_GO') {
          await executeNoGo(event.id, 'SYSTEM')
          results.cancelledEvents++
        } else {
          results.reviewEvents++
        }

        await createAuditLog({
          action: 'UPDATE',
          entity: 'ExamEvent',
          entityId: event.id,
          details: {
            source: 'check-pools-cron',
            decision: evaluation.decision,
            reasons: evaluation.reasons,
          },
        })
      } catch (err: any) {
        results.errors.push(`Event ${event.id}: ${err.message}`)
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Pool check completed',
      results: { ...results },
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('Cron check-pools error:', error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered as prisma } from '@/lib/prisma/client'
import { env } from '@/lib/env'
import { getSystemSetting } from '@/lib/settings'

const DEFAULT_RETENTION_DAYS = 365
const ARCHIVE_BATCH_SIZE = 1000

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret) {
    return NextResponse.json({ error: 'CRON_SECRET is not configured' }, { status: 503 })
  }
  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    // Read configurable retention period from system settings
    const retentionSetting = await getSystemSetting('audit_log_retention_days', String(DEFAULT_RETENTION_DAYS))
    const retentionDays = Math.max(30, parseInt(retentionSetting, 10) || DEFAULT_RETENTION_DAYS)
    const cutoff = new Date(Date.now() - retentionDays * 24 * 60 * 60 * 1000)

    // Count logs to be archived
    const expiredCount = await prisma.auditLog.count({
      where: { createdAt: { lt: cutoff } },
    })

    if (expiredCount === 0) {
      return NextResponse.json({
        success: true,
        message: `No audit logs older than ${retentionDays} days`,
        archivedCount: 0,
        deletedCount: 0,
      })
    }

    // Archive expired logs to the audit_log_archive table in batches
    let archivedCount = 0
    let cursor: string | undefined

    while (archivedCount < expiredCount) {
      const batch = await prisma.auditLog.findMany({
        where: { createdAt: { lt: cutoff } },
        take: ARCHIVE_BATCH_SIZE,
        ...(cursor ? { cursor: { id: cursor }, skip: 1 } : {}),
        orderBy: { createdAt: 'asc' },
      })

      if (batch.length === 0) break

      // Insert into archive table
      await prisma.auditLogArchive.createMany({
        data: batch.map(log => ({
          originalId: log.id,
          userId: log.userId,
          action: log.action,
          entity: log.entity,
          entityId: log.entityId,
          description: log.description,
          changes: log.changes ?? undefined,
          ipAddress: log.ipAddress,
          userAgent: log.userAgent,
          originalCreatedAt: log.createdAt,
        })),
        skipDuplicates: true,
      })

      archivedCount += batch.length
      cursor = batch[batch.length - 1].id
    }

    // Delete the archived logs
    const { count: deletedCount } = await prisma.auditLog.deleteMany({
      where: { createdAt: { lt: cutoff } },
    })

    // Record the last cleanup timestamp
    await prisma.systemSetting.upsert({
      where: { key: 'audit_log_last_cleanup' },
      update: { value: new Date().toISOString() },
      create: { key: 'audit_log_last_cleanup', value: new Date().toISOString(), type: 'STRING' },
    })

    return NextResponse.json({
      success: true,
      message: `Archived and deleted ${deletedCount} audit logs older than ${retentionDays} days`,
      cutoffDate: cutoff.toISOString(),
      archivedCount,
      deletedCount,
      retentionDays,
    })
  } catch (error: any) {
    console.error('Cron cleanup-audit-logs error:', error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { env } from '@/lib/env'

// Cron job: Expire bundles past their validity date
// ACTIVE bundles with validUntil < now → mark EXPIRED
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    // Find bundles about to expire so we can notify their owners
    const expiredBundles = await prisma.examBundle.findMany({
      where: {
        status: 'ACTIVE',
        validUntil: { lt: new Date() },
      },
      select: { id: true, userId: true, bundleType: true },
    })

    const result = await prisma.examBundle.updateMany({
      where: {
        id: { in: expiredBundles.map((b) => b.id) },
      },
      data: { status: 'EXPIRED' },
    })

    if (result.count > 0) {
      // Notify each user whose bundle expired
      for (const bundle of expiredBundles) {
        await prisma.notification.create({
          data: {
            userId: bundle.userId,
            title: 'Exam Bundle Expired',
            message: `Your ${bundle.bundleType} exam bundle has expired. Contact admin for renewal options.`,
            type: 'WARNING',
          },
        }).catch(() => {}) // Don't fail the cron if notification fails
      }

      await createAuditLog({
        action: 'SYSTEM_UPDATE',
        entity: 'ExamBundle',
        entityId: 'cron',
        description: `Expired ${result.count} bundle(s) past validity date`,
      })
    }

    return NextResponse.json({
      success: true,
      expired: result.count,
    })
  } catch (error: any) {
    console.error('[CRON] expire-bundles error:', error)
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { env } from '@/lib/env'
import { runRetentionSweep, seedDefaultRetentionPolicies } from '@/lib/gdpr/retention'
import { createAuditLog } from '@/lib/audit/logger'

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    await seedDefaultRetentionPolicies()
    const results = await runRetentionSweep()
    const totalAffected = results.reduce((s, r) => s + r.affected, 0)
    const errors = results.filter((r) => r.error).length

    await createAuditLog({
      action: 'SYSTEM',
      entity: 'GdprRetention',
      entityId: 'weekly',
      description: `Retention sweep — ${totalAffected} rows affected across ${results.length} policies (${errors} errors)`,
      changes: { results },
    })

    return NextResponse.json({ ok: true, totalAffected, results })
  } catch (err: any) {
    console.error('[Cron gdpr-retention] Error:', err.message)
    return NextResponse.json({ ok: false, error: err.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { sendInterviewReminderEmail } from '@/lib/email/admissions'

/**
 * CRON: Interview Reminders
 * Runs daily — sends reminders 24h before scheduled interviews.
 * Secured by CRON_SECRET header.
 */
export async function GET(req: NextRequest) {
  const secret = req.headers.get('authorization')
  if (secret !== `Bearer ${process.env.CRON_SECRET}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()
    const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000)

    // Find interview slots happening in the next 24 hours
    const upcomingSlots = await prismaUnfiltered.interviewSlot.findMany({
      where: {
        date: {
          gte: now,
          lte: tomorrow,
        },
      },
      include: {
        applications: {
          where: { stage: 'INTERVIEW_SCHEDULED' },
          include: {
            user: {
              select: {
                email: true,
                profile: { select: { firstName: true } },
              },
            },
          },
        },
      },
    })

    let sent = 0
    for (const slot of upcomingSlots) {
      for (const app of slot.applications) {
        if (!app.user) continue
        const firstName = app.user.profile?.firstName || 'Applicant'
        const date = slot.date.toLocaleDateString('en-GB', {
          weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
        })
        const time = slot.startTime.toLocaleTimeString('en-GB', {
          hour: '2-digit', minute: '2-digit',
        })
        const location = slot.location || 'Aerojet Academy Campus'

        await sendInterviewReminderEmail(app.user.email, firstName, date, time, location)
        sent++
      }
    }

    return NextResponse.json({
      success: true,
      message: `Sent ${sent} interview reminders`,
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('[Cron] Interview reminders failed:', error)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { env } from '@/lib/env'
import prisma from '@/lib/prisma/client'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { sendMilestoneReminderEmail } from '@/lib/email/service'
import { createNotification } from '@/lib/email/service'

const REMINDER_DAYS = [14, 7, 1]

function getReminderType(daysUntil: number): string | null {
  if (daysUntil === 14) return '14_DAY'
  if (daysUntil === 7) return '7_DAY'
  if (daysUntil === 1) return '1_DAY'
  return null
}

function getDaysUntilDue(dueDate: Date): number {
  const now = new Date()
  now.setHours(0, 0, 0, 0)
  const due = new Date(dueDate)
  due.setHours(0, 0, 0, 0)
  const diffTime = due.getTime() - now.getTime()
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24))
  return diffDays
}

async function checkAndSendReminders() {
  const results = {
    sent: 0,
    skipped: 0,
    errors: [] as string[],
  }

  const allMilestones = await prisma.paymentMilestone.findMany({
    where: {
      status: { in: ['DUE', 'OVERDUE'] },
    },
    take: 500, // Prevent unbounded fetch
    include: {
      enrollment: {
        include: {
          student: {
            include: { profile: true },
          },
          programme: true,
        },
      },
    },
  })

  // Filter to only milestones that match our reminder days
  const actionableMilestones = allMilestones.filter((m) => {
    const daysUntil = getDaysUntilDue(m.dueDate)
    return daysUntil >= 0 && getReminderType(daysUntil) !== null
  })

  if (actionableMilestones.length === 0) {
    return results
  }

  // Batch idempotency check: find all existing reminders in the last 7 days for these students
  const studentIds = [...new Set(actionableMilestones.map((m) => m.enrollment.studentId))]
  const existingReminders = await prisma.notification.findMany({
    where: {
      userId: { in: studentIds },
      title: { startsWith: 'Payment Reminder - ' },
      createdAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },
    },
    select: { userId: true, title: true, message: true },
  })

  // Build lookup: "userId:reminderType:milestoneType"
  const reminderSet = new Set(
    existingReminders.map((r) => {
      const type = r.title.replace('Payment Reminder - ', '')
      return `${r.userId}:${type}`
    })
  )

  for (const milestone of actionableMilestones) {
    try {
      const daysUntil = getDaysUntilDue(milestone.dueDate)
      const reminderType = getReminderType(daysUntil)!

      const key = `${milestone.enrollment.studentId}:${reminderType}`
      if (reminderSet.has(key)) {
        results.skipped++
        continue
      }

      const student = milestone.enrollment.student
      const profile = student.profile

      if (!profile) {
        results.errors.push(`No profile for student ${student.id}`)
        continue
      }

      await sendMilReminderEmail(
        student.email,
        profile.firstName,
        milestone.milestoneType,
        Number(milestone.amountDue),
        daysUntil,
        milestone.enrollment.programme.name
      )

      await prisma.notification.create({
        data: {
          userId: student.id,
          type: 'PAYMENT_UPDATE',
          title: `Payment Reminder - ${reminderType}`,
          message: `Your ${milestone.milestoneType} payment of €${milestone.amountDue} is due in ${daysUntil} days.`,
          linkUrl: '/student/wallet?tab=payments',
        },
      })

      reminderSet.add(key) // Prevent duplicates within same run
      results.sent++
    } catch (err) {
      const error = err as Error
      results.errors.push(`Error processing milestone ${milestone.id}: ${error.message}`)
    }
  }

  return results
}

async function sendMilReminderEmail(
  email: string,
  firstName: string,
  milestoneType: string,
  amount: number,
  daysUntil: number,
  programmeName: string
) {
  const { renderMilestoneReminderEmail, sendEmail } = await import('@/lib/email/service')

  const milestoneLabel =
    {
      SEAT_CONFIRMATION: 'Seat Confirmation',
      SEM1_DUE: 'Semester 1 Payment',
      SEM2_DUE: 'Semester 2 Payment',
    }[milestoneType] || milestoneType

  const html = await renderMilestoneReminderEmail(
    firstName,
    milestoneLabel,
    amount,
    daysUntil,
    programmeName
  )

  return sendEmail({
    to: email,
    subject: `Payment Reminder: ${milestoneLabel} due in ${daysUntil} days`,
    html,
  })
}

export const GET = withErrorHandler(async (req: NextRequest) => {
  const cronSecret = env.CRON_SECRET
  const authHeader = req.headers.get('authorization')

  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
    return apiError('Unauthorized', 401)
  }

  const results = await checkAndSendReminders()

  return apiSuccess({
    message: `Milestone reminder check complete`,
    ...results,
  })
})

export const POST = withErrorHandler(async (req: NextRequest) => {
  const cronSecret = env.CRON_SECRET
  const authHeader = req.headers.get('authorization')

  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
    return apiError('Unauthorized', 401)
  }

  const results = await checkAndSendReminders()
  return apiSuccess({
    message: `Milestone reminder check complete`,
    ...results,
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { sendModularDeadlineWarningEmail } from '@/lib/email/admissions'

/**
 * CRON: Modular Deadline Warnings
 * Runs daily — checks MODULAR students approaching their completion deadline.
 * Sends warnings at 75% and 90% elapsed thresholds.
 */
export async function GET(req: NextRequest) {
  const secret = req.headers.get('authorization')
  if (secret !== `Bearer ${process.env.CRON_SECRET}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()

    // Find all active modular applications with a completion deadline
    const modularApps = await prismaUnfiltered.application.findMany({
      where: {
        programmeChoice: 'MODULAR',
        stage: 'ENROLLED',
        completionDeadline: { not: null },
      },
      include: {
        user: {
          select: {
            id: true,
            email: true,
            profile: { select: { firstName: true } },
          },
        },
      },
    })

    let sent = 0
    for (const app of modularApps) {
      if (!app.user || !app.completionDeadline || !app.createdAt) continue

      const totalDuration = app.completionDeadline.getTime() - app.createdAt.getTime()
      const elapsed = now.getTime() - app.createdAt.getTime()
      const percentElapsed = Math.round((elapsed / totalDuration) * 100)

      // Only warn at 75% and 90% thresholds
      if (percentElapsed < 75) continue
      const threshold = percentElapsed >= 90 ? 90 : 75

      // Check if we already sent a warning for this threshold (within last 7 days)
      const alreadySent = await prismaUnfiltered.auditLog.findFirst({
        where: {
          action: `MODULAR_DEADLINE_WARNING_${threshold}`,
          targetId: app.id,
          createdAt: { gte: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000) },
        },
      })
      if (alreadySent) continue

      const firstName = app.user.profile?.firstName || 'Student'
      const deadline = app.completionDeadline.toLocaleDateString('en-GB', {
        year: 'numeric', month: 'long', day: 'numeric',
      })

      // Count remaining modular enrollments
      const totalModules = await prismaUnfiltered.modularEnrollment.count({
        where: { studentId: app.user.id },
      })
      const graduatedModules = await prismaUnfiltered.modularEnrollment.count({
        where: { studentId: app.user.id, status: 'GRADUATED' },
      })
      const remaining = Math.max(0, totalModules - graduatedModules)

      await sendModularDeadlineWarningEmail(app.user.email, firstName, threshold, deadline, remaining)

      // Log that we sent this warning to avoid re-sending
      await prismaUnfiltered.auditLog.create({
        data: {
          userId: app.user.id,
          action: `MODULAR_DEADLINE_WARNING_${threshold}`,
          targetType: 'APPLICATION',
          targetId: app.id,
          metadata: { percentElapsed: threshold, deadline },
        },
      })

      sent++
    }

    return NextResponse.json({
      success: true,
      message: `Sent ${sent} modular deadline warnings`,
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('[Cron] Modular deadline warnings failed:', error)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { sendPaymentDeadlineEmail } from '@/lib/email/service'
import { createAuditLog } from '@/lib/audit/logger'
import { env } from '@/lib/env'

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()
    const results = { remindersSent: 0, forfeited: 0, errors: [] as string[] }

    // Deadlines to check: T-28, T-24, T-22
    const targetDays = [28, 24, 22]
    const todayStart = new Date(now)
    todayStart.setHours(0, 0, 0, 0)

    // Fetch pricing config once
    const { getExamPricingConfig } = await import('@/lib/pools/pricing-config')
    const pricingConfig = await getExamPricingConfig()

    // Build date ranges for all target days at once
    const dateRanges = targetDays.map((days) => {
      const targetDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000)
      const start = new Date(targetDate)
      start.setHours(0, 0, 0, 0)
      const end = new Date(targetDate)
      end.setHours(23, 59, 59, 999)
      return { days, start, end }
    })

    // Fetch all relevant events across all target date ranges in one query
    const allEvents = await prisma.examEvent.findMany({
      where: {
        OR: dateRanges.map(({ start, end }) => ({
          startDate: { gte: start, lte: end },
        })),
        status: { in: ['OPEN', 'CONFIRMED'] },
      },
      select: { id: true, name: true, startDate: true },
    })

    if (allEvents.length > 0) {
      // Fetch all pending individual bookings for these events in one query
      const pendingBookings = await prisma.examBooking.findMany({
        where: {
          eventId: { in: allEvents.map((e) => e.id) },
          bookingType: 'INDIVIDUAL',
          status: 'PENDING',
        },
        include: {
          user: { include: { profile: true } },
          examComponent: { include: { course: { select: { code: true } } } },
        },
      })

      // Batch idempotency check: find all existing reminders sent today
      const bookingUserIds = [...new Set(pendingBookings.map((b) => b.userId))]
      const existingReminders = await prisma.notification.findMany({
        where: {
          userId: { in: bookingUserIds },
          type: 'WARNING',
          title: { startsWith: 'Payment Reminder T-' },
          createdAt: { gte: todayStart },
        },
        select: { userId: true, title: true },
      })

      // Create a Set for fast lookup: "userId:T-28"
      const reminderSet = new Set(existingReminders.map((r) => `${r.userId}:${r.title}`))

      // Map event IDs to their target day
      const eventToDays = new Map<string, number>()
      for (const event of allEvents) {
        for (const { days, start, end } of dateRanges) {
          if (event.startDate >= start && event.startDate <= end) {
            eventToDays.set(event.id, days)
          }
        }
      }

      const eventMap = new Map(allEvents.map((e) => [e.id, e]))

      for (const booking of pendingBookings) {
        if (!booking.eventId) continue
        const days = eventToDays.get(booking.eventId)
        if (!days) continue
        const event = eventMap.get(booking.eventId)!

        const reminderKey = `${booking.userId}:Payment Reminder T-${days}`
        if (reminderSet.has(reminderKey)) continue // Already reminded today

        try {
          const email = booking.user.personalEmail || booking.user.email
          const name = booking.user.profile?.firstName || 'Student'
          const moduleLabel = booking.examComponent?.course?.code ?? 'Module'
          const balance = pricingConfig.individualExamFee - Number(booking.amountPaid)

          await sendPaymentDeadlineEmail(email, name, moduleLabel, event.name, days, balance)

          await prisma.notification.create({
            data: {
              userId: booking.userId,
              title: `Payment Reminder T-${days}`,
              message: `Balance of €${balance} due for ${moduleLabel} exam`,
              type: 'WARNING',
            },
          })

          results.remindersSent++
        } catch (err: any) {
          results.errors.push(`Reminder for booking ${booking.id}: ${err.message}`)
        }
      }
    }

    // Now handle T-21 Forfeitures
    const t21Date = new Date(now.getTime() + 21 * 24 * 60 * 60 * 1000)
    const t21Start = new Date(t21Date)
    t21Start.setHours(0, 0, 0, 0)
    const t21End = new Date(t21Date)
    t21End.setHours(23, 59, 59, 999)

    const t21Events = await prisma.examEvent.findMany({
      where: {
        startDate: { gte: t21Start, lte: t21End },
        status: { in: ['OPEN', 'CONFIRMED'] },
      },
      select: { id: true },
    })

    if (t21Events.length > 0) {
      // Fetch all pending bookings for T-21 events in one query
      const expiredBookings = await prisma.examBooking.findMany({
        where: {
          eventId: { in: t21Events.map((e) => e.id) },
          bookingType: 'INDIVIDUAL',
          status: 'PENDING',
        },
      })

      // Batch: find all linked pending/approved payments for these bookings
      const bookingIds = expiredBookings.map((b) => b.id)
      const linkedPayments = await prisma.payment.findMany({
        where: {
          referenceId: { in: bookingIds },
          status: { in: ['PENDING', 'APPROVED'] },
        },
        select: { id: true, referenceId: true, status: true },
      })
      const paymentByBooking = new Map(linkedPayments.map((p) => [p.referenceId, p]))

      for (const booking of expiredBookings) {
        try {
          const linkedPayment = paymentByBooking.get(booking.id)
          if (linkedPayment) {
            results.errors.push(
              `Booking ${booking.id}: skipped forfeit — payment ${linkedPayment.id} (${linkedPayment.status}) exists`
            )
            continue
          }

          await prisma.examBooking.update({
            where: { id: booking.id, status: 'PENDING' }, // optimistic concurrency
            data: { status: 'FAILED' },
          })

          await createAuditLog({
            action: 'UPDATE',
            entity: 'ExamBooking',
            entityId: booking.id,
            userId: booking.userId,
            details: { reason: 'Failed to pay individual booking balance by T-21 deadline' },
          })

          results.forfeited++
        } catch (err: any) {
          results.errors.push(`Forfeiting booking ${booking.id}: ${err.message}`)
        }
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Payment deadlines processed',
      results,
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('Cron payment-deadlines error:', error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { sendEmail } from '@/lib/email/sender'
import { createAuditLog } from '@/lib/audit/logger'
import { env } from '@/lib/env'

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const now = new Date()
    const results = { remindersSent: 0, errors: [] as string[] }

    // Check 30, 14, and 7 days ahead
    const windows = [30, 14, 7]
    const windowMap = new Map<number, Date>()

    for (const days of windows) {
      const d = new Date(now.getTime() + days * 24 * 60 * 60 * 1000)
      windowMap.set(days, d)
    }

    // Documents expiring within 30 days
    const docs30 = windowMap.get(30)!
    const expiringDocs = await prisma.studentDocument.findMany({
      where: {
        expiresAt: { not: null, lte: docs30, gte: now },
        status: { not: 'ARCHIVED' },
      },
      select: {
        id: true,
        userId: true,
        type: true,
        title: true,
        expiresAt: true,
        user: {
          select: {
            email: true,
            personalEmail: true,
            profile: { select: { firstName: true } },
          },
        },
      },
      take: 200,
    })

    // Licenses expiring within 30 days
    const expiringLicenses = await prisma.studentLicenseTarget.findMany({
      where: {
        expiresAt: { not: null, lte: docs30, gte: now },
      },
      select: {
        id: true,
        expiresAt: true,
        validFrom: true,
        ratingClass: true,
        validityPeriodMonths: true,
        studentProfileId: true,
        licenseCategory: { select: { name: true } },
        studentProfile: {
          select: {
            userId: true,
            studentId: true,
            user: {
              select: {
                email: true,
                personalEmail: true,
                profile: { select: { firstName: true } },
              },
            },
          },
        },
      },
      take: 200,
    })

    // Batch idempotency: avoid duplicate reminders within 24h
    const todayStart = new Date(now)
    todayStart.setHours(0, 0, 0, 0)

    const allUserIds = [
      ...new Set([
        ...expiringDocs.map((d) => d.userId),
        ...expiringLicenses.map((l) => l.studentProfile.userId),
      ]),
    ]

    const existingReminders = await prisma.notification.findMany({
      where: {
        userId: { in: allUserIds },
        type: 'WARNING',
        title: { startsWith: 'Renewal Reminder: ' },
        createdAt: { gte: todayStart },
      },
      select: { userId: true, title: true },
    })

    const reminderSet = new Set(existingReminders.map((r) => `${r.userId}:${r.title}`))

    const fromEmail = process.env.FROM_EMAIL || 'Aerojet Academy <admissions@mail.aerojet-academy.com>'

    // Send document reminders
    for (const doc of expiringDocs) {
      const days = Math.ceil((new Date(doc.expiresAt!).getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
      const reminderKey = `${doc.userId}:Renewal Reminder: ${doc.title}`
      if (reminderSet.has(reminderKey)) continue

      try {
        const email = doc.user.personalEmail || doc.user.email
        const name = doc.user.profile?.firstName || 'Student'

        await sendEmail({
          to: email,
          subject: `Renewal Reminder: ${doc.title} expires in ${days} days`,
          html: `
            <p>Dear ${name},</p>
            <p>Your document <strong>${doc.title}</strong> (${doc.type}) is set to expire on <strong>${new Date(doc.expiresAt!).toLocaleDateString()}</strong> (in ${days} days).</p>
            <p>Please upload a renewed copy to the student portal to avoid any disruption to your studies.</p>
            <p>Best regards,<br/>Aerojet Academy</p>
          `,
          template: 'renewal-reminder',
          userId: doc.userId,
        })

        await prisma.notification.create({
          data: {
            userId: doc.userId,
            title: `Renewal Reminder: ${doc.title}`,
            message: `${doc.title} expires in ${days} days`,
            type: 'WARNING',
          },
        })

        results.remindersSent++
      } catch (err: any) {
        results.errors.push(`Document ${doc.id}: ${err.message}`)
      }
    }

    // Send license reminders
    for (const lic of expiringLicenses) {
      const days = Math.ceil((new Date(lic.expiresAt!).getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
      const reminderKey = `${lic.studentProfile.userId}:Renewal Reminder: ${lic.licenseCategory.name}`
      if (reminderSet.has(reminderKey)) continue

      try {
        const email = lic.studentProfile.user.personalEmail || lic.studentProfile.user.email
        const name = lic.studentProfile.user.profile?.firstName || 'Student'

        await sendEmail({
          to: email,
          subject: `Renewal Reminder: ${lic.licenseCategory.name} expires in ${days} days`,
          html: `
            <p>Dear ${name},</p>
            <p>Your license <strong>${lic.licenseCategory.name}</strong> is set to expire on <strong>${new Date(lic.expiresAt!).toLocaleDateString()}</strong> (in ${days} days).</p>
            <p>Please ensure your license documentation is renewed before the expiry date to maintain your enrollment status.</p>
            <p>Best regards,<br/>Aerojet Academy</p>
          `,
          template: 'renewal-reminder',
          userId: lic.studentProfile.userId,
        })

        await prisma.notification.create({
          data: {
            userId: lic.studentProfile.userId,
            title: `Renewal Reminder: ${lic.licenseCategory.name}`,
            message: `${lic.licenseCategory.name} expires in ${days} days`,
            type: 'WARNING',
          },
        })

        results.remindersSent++
      } catch (err: any) {
        results.errors.push(`License ${lic.id}: ${err.message}`)
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Renewal reminders processed',
      results,
      timestamp: now.toISOString(),
    })
  } catch (error: any) {
    console.error('Cron renewal-reminders error:', error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered as prisma } from '@/lib/prisma/client'
import { env } from '@/lib/env'
import { getFinanceReportSummary, getYoYComparison } from '@/lib/analytics/reports'
import { sendEmail } from '@/lib/email/sender'
import { format } from 'date-fns'

/**
 * Cron job to send scheduled financial reports to board/admin
 * Frequency: Weekly (Mondays at 8 AM)
 */
export async function GET(req: NextRequest) {
  // Feature hidden for now as per Tier 4 request
  return NextResponse.json({ success: true, message: 'Feature disabled' })

  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET

  // Authorization check
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    // 1. Check if reporting is enabled
    const settings = await prisma.systemSetting.findMany({
      where: {
        key: { in: ['report_schedule', 'report_email', 'report_last_sent'] },
      },
    })

    const vals: Record<string, string> = {}
    for (const s of settings) vals[s.key] = s.value

    const schedule = vals.report_schedule || 'off'
    const email = vals.report_email || ''
    const lastSent = vals.report_last_sent ? new Date(vals.report_last_sent) : null

    // Respect the "Cancel" / "Off" request
    if (schedule === 'off') {
      return NextResponse.json({
        success: true,
        message: 'Reporting is disabled (off)',
      })
    }

    // 2. Check if it's time to send (simple day-of-week check for weekly)
    const now = new Date()
    const isMonday = now.getDay() === 1
    
    // For manual testing or if it's actually Monday
    if (!isMonday && req.nextUrl.searchParams.get('force') !== 'true') {
      return NextResponse.json({
        success: true,
        message: 'Not a reporting day (Scheduled for Mondays)',
      })
    }

    // Prevent double sending on the same day
    if (lastSent && format(lastSent as Date, 'yyyy-MM-dd') === format(now, 'yyyy-MM-dd')) {
       return NextResponse.json({
        success: true,
        message: 'Report already sent today',
      })
    }

    if (!email) {
      return NextResponse.json({
        success: false,
        message: 'No recipient email configured for reports',
      })
    }

    // 3. Gather Data
    const [financeSummary, yoyData] = await Promise.all([
      getFinanceReportSummary({ year: now.getFullYear(), month: now.getMonth() + 1 }),
      getYoYComparison(now.getFullYear()),
