// Weekly Neon ↔ Supabase replication drift sanity check.
// Scheduled in vercel.json. See docs/guides/neon-supabase-logical-replication.md.
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const cronSecret = env.CRON_SECRET
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const result = await runSyncCheck()

    if (!result.ran) {
      return NextResponse.json({ ok: true, skipped: true, reason: result.reason })
    }

    if (result.anyAlarmed) {
      await createAuditLog({
        action: AuditAction.SYSTEM,
        entity: 'SyncCheck',
        entityId: 'neon-supabase',
        description: `Neon↔Supabase drift detected — worst ${(result.worstDriftPct * 100).toFixed(2)}%`,
        changes: {
          rows: JSON.parse(JSON.stringify(result.rows.filter((r) => r.alarmed))),
        },
      })
      await notifyStaff(
        'Data Sync Drift Detected',
        `Neon ↔ Supabase replication drift detected (worst ${(result.worstDriftPct * 100).toFixed(2)}%).`
      )
    }

    return NextResponse.json({ ok: true, ...result })
  } catch (err: any) {
    console.error('[Cron sync-check] Error:', err.message)
    await notifyStaff('Sync Check Failed', `Neon ↔ Supabase sync check failed: ${err.message}`)
    await createAuditLog({
      action: AuditAction.SYSTEM,
      entity: 'SyncCheck',
      entityId: 'neon-supabase',
      description: `Sync check failed: ${err.message}`,
    })
    return NextResponse.json({ ok: false, error: err.message }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { requireExaminer } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { apiSuccess, apiError, apiCreated, withErrorHandler } from '@/lib/api/response'

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireExaminer()
  const slots = await prismaUnfiltered.staffAvailability.findMany({
    where: { userId: user.id },
    orderBy: [{ kind: 'asc' }, { dayOfWeek: 'asc' }, { date: 'asc' }],
  })
  return apiSuccess(slots)
})

export const POST = withErrorHandler(async (req: NextRequest) => {
  const user = await requireExaminer()
  const body = await req.json()
  const { kind, dayOfWeek, date, startTime, endTime, available, notes } = body as Record<string, unknown>

  if (!startTime || !endTime) return apiError('Start and end time are required')
  if (kind === 'RECURRING_WEEKLY' && (dayOfWeek == null || (dayOfWeek as number) < 0)) {
    return apiError('Select a day of week')
  }
  if (kind === 'SPECIFIC_DATE' && !date) return apiError('Select a date')

  const slot = await prismaUnfiltered.staffAvailability.create({
    data: {
      userId: user.id,
      kind: kind as 'RECURRING_WEEKLY' | 'SPECIFIC_DATE',
      dayOfWeek: kind === 'RECURRING_WEEKLY' ? (dayOfWeek as number) : null,
      date: kind === 'SPECIFIC_DATE' ? new Date(date as string) : null,
      startTime: startTime as string,
      endTime: endTime as string,
      available: (available as boolean | undefined) ?? true,
      notes: (notes as string | undefined)?.trim() || null,
    },
  })

  return apiCreated(slot)
})

import { NextRequest } from 'next/server'
import { requireExaminer } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireExaminer()
  const examiner = await prismaUnfiltered.examiner.findUnique({
    where: { userId: user.id },
    include: {
      user: {
        include: {
          profile: { select: { firstName: true, lastName: true } },
        },
      },
    },
  })

  if (!examiner) return apiError('Examiner profile not found', 404)

  const [completedSittings, upcomingSittings] = await Promise.all([
    prismaUnfiltered.examSitting.count({
      where: { examinerId: examiner.id, status: 'COMPLETED' },
    }),
    prismaUnfiltered.examSitting.count({
      where: {
        examinerId: examiner.id,
        status: { in: ['DRAFT', 'OPEN', 'SCHEDULED', 'CONFIRMED'] },
        startTime: { gte: new Date() },
      },
    }),
  ])

  const fullName = examiner.user.profile
    ? `${examiner.user.profile.firstName} ${examiner.user.profile.lastName}`
    : examiner.user.email

  return apiSuccess({
    id: examiner.id,
    fullName,
    isActive: examiner.isActive,
    maxParallelSittings: examiner.maxParallelSittings,
    createdAt: examiner.createdAt,
    notes: examiner.notes,
    completedSittings,
    upcomingSittings,
  })
})

