import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth/auth-options'
import { getStorageAdapter } from '@/lib/storage/proxy'

/**
 * Auth-gated image proxy.
 *
 * Fetches images from UploadThing (or any HTTP-accessible storage) through
 * an authenticated API route. Validates the user's session and optionally
 * checks role-based permissions before returning the image.
 *
 * Query params:
 *   - url:   The UploadThing / remote image URL to proxy (required)
 *   - scope: Optional scope to validate access (e.g. "students", "resources")
 *   - w:     Optional width for resizing (e.g. 400)
 *   - q:     Optional quality 1-100 (default 85)
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const imageUrl = searchParams.get('url')
  const scope = searchParams.get('scope')
  const width = searchParams.get('w')
  const quality = Math.min(100, Math.max(1, parseInt(searchParams.get('q') || '85', 10)))

  if (!imageUrl) {
    return new NextResponse(JSON.stringify({ error: 'Missing url parameter' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 1. Authenticate ──
  const session = await getServerSession(authOptions)
  if (!session?.user) {
    return new NextResponse(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 2. Scope-based access control ──
  if (scope) {
    const role = session.user.role as string
    const userId = session.user.id

    switch (scope) {
      case 'students':
        if (!['SUPER_ADMIN', 'ADMIN', 'STAFF', 'INSTRUCTOR', 'EXAMINER'].includes(role)) {
          if (!imageUrl.includes(`/students/${userId}/`)) {
            return new NextResponse(JSON.stringify({ error: 'Forbidden' }), {
              status: 403,
              headers: { 'Content-Type': 'application/json' },
            })
          }
        }
        break

      case 'resources':
        if (!['SUPER_ADMIN', 'ADMIN', 'STAFF', 'INSTRUCTOR', 'EXAMINER'].includes(role)) {
          return new NextResponse(JSON.stringify({ error: 'Forbidden' }), {
            status: 403,
            headers: { 'Content-Type': 'application/json' },
          })
        }
        break

      case 'staff':
        if (!['SUPER_ADMIN', 'ADMIN', 'STAFF', 'EXAMINER'].includes(role)) {
          return new NextResponse(JSON.stringify({ error: 'Forbidden' }), {
            status: 403,
            headers: { 'Content-Type': 'application/json' },
          })
        }
        break

      case 'profile-photos':
        // Anyone authenticated can view profile photos
        break

      default:
        return new NextResponse(JSON.stringify({ error: 'Invalid scope' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        })
    }
  }

  // ── 3. Validate URL against allowed domains before fetching ──
  const allowedHosts = [
    'utfs.io',
    'www.utfs.io',
    'ufs.sh',
    'uploadthing.com',
  ]

  let parsedUrl: URL
  try {
    parsedUrl = new URL(imageUrl)
  } catch {
    return new NextResponse(JSON.stringify({ error: 'Invalid image URL' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  if (!allowedHosts.includes(parsedUrl.hostname)) {
    return new NextResponse(JSON.stringify({ error: 'Image source not allowed' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 4. Fetch the image via the active storage adapter ──
  const adapter = getStorageAdapter()
  let data: ArrayBuffer
  let contentType: string

  try {
    const result = await adapter.fetch(imageUrl)
    data = result.data
    contentType = result.contentType
  } catch (err: any) {
    console.error('[image-proxy] fetch error:', err.message)
    return new NextResponse(JSON.stringify({ error: 'Image not found' }), {
      status: 404,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 5. Optionally resize using sharp (if width param provided) ──
  if (width) {
    try {
      const sharp = (await import('sharp')).default
      const buffer = Buffer.from(data)
      const resized = await sharp(buffer)
        .resize({ width: parseInt(width, 10), withoutEnlargement: true })
        .webp({ quality })
        .toBuffer()

      return new NextResponse(new Uint8Array(resized), {
        headers: {
          'Content-Type': 'image/webp',
          'Cache-Control': 'private, max-age=3600',
          'X-Content-Type-Options': 'nosniff',
        },
      })
    } catch {
      // Fall through to return original if sharp fails
    }
  }

  // ── 6. Return the original image ──
  return new NextResponse(data, {
    headers: {
      'Content-Type': contentType,
      'Cache-Control': 'private, max-age=3600',
      'X-Content-Type-Options': 'nosniff',
    },
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth/auth-options'
import { getStorageAdapter } from '@/lib/storage/proxy'
import sharp from 'sharp'

/**
 * Image transformation API route.
 *
 * Fetches an image from UploadThing (or any HTTP-accessible storage) via the
 * active storage adapter, applies transformations (watermark, resize, EXIF
 * stripping), and returns the processed image.
 *
 * Query params:
 *   - url:      The UploadThing / remote image URL (required)
 *   - w:        Optional max width (e.g. 800)
 *   - watermark: Set to "true" to overlay an "© Aerojet Academy" mark
 *   - strip:    Set to "true" to strip EXIF/metadata (default: true)
 *   - q:        Quality 1-100 (default: 85)
 *   - format:   Output format: webp, jpeg, png, avif (default: webp)
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const imageUrl = searchParams.get('url')
  const width = searchParams.get('w')
  const addWatermark = searchParams.get('watermark') === 'true'
  const stripMetadata = searchParams.get('strip') !== 'false'
  const quality = Math.min(100, Math.max(1, parseInt(searchParams.get('q') || '85', 10)))
  const format = (searchParams.get('format') || 'webp') as 'webp' | 'jpeg' | 'png' | 'avif'

  if (!imageUrl) {
    return new NextResponse(JSON.stringify({ error: 'Missing url parameter' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 1. Authenticate (staff only) ──
  const session = await getServerSession(authOptions)
  if (!session?.user) {
    return new NextResponse(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const role = session.user.role as string
  const isStaff = ['SUPER_ADMIN', 'ADMIN', 'STAFF', 'INSTRUCTOR', 'EXAMINER'].includes(role)
  if (!isStaff) {
    return new NextResponse(JSON.stringify({ error: 'Forbidden' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 2. Fetch the image via the active storage adapter ──
  const adapter = getStorageAdapter()
  let data: ArrayBuffer

  try {
    const result = await adapter.fetch(imageUrl)
    data = result.data
  } catch (err: any) {
    console.error('[image-transform] fetch error:', err.message)
    return new NextResponse(JSON.stringify({ error: 'Image not found' }), {
      status: 404,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // ── 3. Transform with sharp ──
  try {
    const buffer = Buffer.from(data)
    let pipeline = sharp(buffer)

    // Strip EXIF metadata
    if (stripMetadata) {
      pipeline = pipeline.withMetadata({ exif: {} })
    }

    // Resize if width specified (maintain aspect ratio, no upscaling)
    if (width) {
      pipeline = pipeline.resize({
        width: parseInt(width, 10),
        withoutEnlargement: true,
        fit: 'inside',
      })
    }

    // Add watermark SVG overlay
    if (addWatermark) {
      const watermarkSvg = Buffer.from(`
        <svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
          <style>
            .watermark { font-family: Arial, sans-serif; font-size: 16px; fill: rgba(255,255,255,0.4); }
          </style>
          <text x="10" y="30" class="watermark">© Aerojet Academy</text>
          <text x="10" y="50" class="watermark" font-size="12">${new Date().toISOString().split('T')[0]}</text>
        </svg>
      `)
      pipeline = pipeline.composite([{ input: watermarkSvg, top: 0, left: 0 }])
    }

    // Convert to requested format
    const formatOptions: Record<string, { quality: number }> = {
      webp: { quality },
      jpeg: { quality },
      png: { quality },
      avif: { quality },
    }

    const output = await (pipeline as any)[format](formatOptions[format]).toBuffer()

    const mimeTypes: Record<string, string> = {
      webp: 'image/webp',
      jpeg: 'image/jpeg',
      png: 'image/png',
      avif: 'image/avif',
    }

    return new NextResponse(new Uint8Array(output), {
      headers: {
        'Content-Type': mimeTypes[format] || 'image/webp',
        'Cache-Control': 'private, max-age=3600',
        'X-Content-Type-Options': 'nosniff',
        'X-Image-Transformed': 'true',
      },
    })
  } catch (err: any) {
    console.error('[image-transform] sharp processing error:', err.message)
    return new NextResponse(JSON.stringify({ error: 'Image processing failed' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    })
  }
}

import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { requireAuth } from '@/lib/auth/helpers'
import { apiSuccess, apiForbidden, apiPaginated, withErrorHandler } from '@/lib/api/response'
import { parsePagination } from '@/lib/api/response'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'
import { UserRole } from '@prisma/client'

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  if (user.role !== UserRole.INSTRUCTOR) return apiForbidden('Instructor access required')

  const instructorProfile = await getInstructorProfileByUserId(user.id)
  if (!instructorProfile) return apiForbidden('Instructor profile not found')

  const { searchParams } = new URL(req.url)
  const { page, limit, skip } = parsePagination(searchParams)
  const upcoming = searchParams.get('upcoming') === 'true'

  const where: any = { instructorId: instructorProfile.id }
  if (upcoming) where.startDate = { gte: new Date() }

  const [classes, total] = await Promise.all([
    prisma.class.findMany({
      where,
      include: {
        course: { select: { code: true, name: true } },
        _count: { select: { attendanceRecords: true } },
      },
      orderBy: { startDate: upcoming ? 'asc' : 'desc' },
      take: limit,
      skip,
    }),
    prisma.class.count({ where }),
  ])

  return apiPaginated(classes, total, page, limit)
})

import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { requireAuth } from '@/lib/auth/helpers'
import { apiSuccess, apiForbidden, withErrorHandler } from '@/lib/api/response'
import { UserRole } from '@prisma/client'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  if (user.role !== UserRole.INSTRUCTOR) return apiForbidden('Instructor access required')

  const instructorProfile = await getInstructorProfileByUserId(user.id)
  if (!instructorProfile) return apiForbidden('Instructor profile not found')
  const instructorId = instructorProfile.id

  const [classes, upcomingClasses, totalStudents, recentAttendance] = await Promise.all([
    prisma.class.findMany({
      where: { instructorId },
      include: {
        course: { select: { code: true, name: true } },
        _count: { select: { attendanceRecords: true } },
      },
      orderBy: { startDate: 'desc' },
    }),
    prisma.class.findMany({
      where: { instructorId, startDate: { gte: new Date() } },
      include: { course: { select: { code: true, name: true } } },
      orderBy: { startDate: 'asc' },
      take: 10,
    }),
    prisma.attendanceRecord.findMany({
      where: { class: { instructorId } },
      select: { userId: true },
      distinct: ['userId'],
    }),
    prisma.attendanceRecord.findMany({
      where: { class: { instructorId } },
      orderBy: { date: 'desc' },
      take: 100,
    }),
  ])

  const attendanceRate =
    recentAttendance.length > 0
      ? Math.round(
          (recentAttendance.filter((r) => r.status === 'PRESENT').length /
            recentAttendance.length) *
            100
        )
      : 0

  return apiSuccess({
    instructorProfile,
    stats: {
      totalClasses: classes.length,
      upcomingClasses: upcomingClasses.length,
      totalStudents: totalStudents.length,
      attendanceRate,
    },
    upcomingClasses,
    recentClasses: classes.slice(0, 10),
  })
})

import { NextRequest } from 'next/server'
import { requireInstructor } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiForbidden, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { isInternalExamSystemEnabled, getBankRules } from '@/lib/internal-exam/engine'
import { AuditAction, createAuditLog } from '@/lib/audit/logger'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'
import { z } from 'zod'

const overrideSchema = z.object({
  passMarkPct: z.number().min(0).max(100).optional(),
  timePerQuestionSecs: z.number().min(10).max(600).optional(),
  retakeWaitDays: z.number().min(0).max(365).optional(),
  maxRetakes: z.number().min(0).max(10).optional(),
  completionWindowYears: z.number().min(1).max(20).optional(),
  allowKeyboardAutoSubmit: z.boolean().optional(),
  customInstructions: z.string().max(2000).optional(),
  mcqCount: z.number().min(5).max(200).optional(),
})

/**
 * GET /api/instructor/exams/banks/[bankId]/rule-override
 * Returns the current rule override for the bank (instructor must have canEdit).
 */
export const GET = withErrorHandler(
  async (req: NextRequest, ctx: { params: Promise<{ bankId: string }> }) => {
    const user = await requireInstructor()
    const instructorProfile = await getInstructorProfileByUserId(user.id)
    if (!instructorProfile) return apiForbidden('Instructor profile not found')

    if (!(await isInternalExamSystemEnabled())) {
      return apiError('Internal exams are not currently available', 403)
    }

    const { bankId } = await ctx.params

    const grant = await prismaUnfiltered.internalExamBankInstructor.findFirst({
      where: { bankId, instructorId: instructorProfile.id },
      select: { canEdit: true },
    })
    if (!grant) return apiForbidden('You do not have access to this bank')

    const override = await prismaUnfiltered.internalExamRuleOverride.findUnique({
      where: { bankId },
    })
    const bank = await prismaUnfiltered.internalExamBank.findUnique({
      where: { id: bankId },
      select: { mcqCount: true },
    })

    return apiSuccess({
      ...override,
      mcqCount: bank?.mcqCount ?? 40,
    })
  }
)

/**
 * PUT /api/instructor/exams/banks/[bankId]/rule-override
 * Updates the rule override for the bank (instructor must have canEdit).
 */
export const PUT = withErrorHandler(
  async (req: NextRequest, ctx: { params: Promise<{ bankId: string }> }) => {
    const user = await requireInstructor()
    const instructorProfile = await getInstructorProfileByUserId(user.id)
    if (!instructorProfile) return apiForbidden('Instructor profile not found')

    if (!(await isInternalExamSystemEnabled())) {
      return apiError('Internal exams are not currently available', 403)
    }

    const { bankId } = await ctx.params

    const grant = await prismaUnfiltered.internalExamBankInstructor.findFirst({
      where: { bankId, instructorId: instructorProfile.id },
      select: { canEdit: true },
    })
    if (!grant?.canEdit) return apiForbidden('You do not have permission to edit this bank')

    const body = await req.json()
    const parsed = overrideSchema.safeParse(body)
    if (!parsed.success) {
      return apiError(`Invalid request: ${parsed.error.message}`, 400)
    }

    const { mcqCount, ...ruleData } = parsed.data

    // Update rule override
    const override = await prismaUnfiltered.internalExamRuleOverride.upsert({
      where: { bankId },
      update: ruleData,
      create: { bankId, ...ruleData },
    })

    // Update bank mcqCount if provided
    if (mcqCount) {
      await prismaUnfiltered.internalExamBank.update({
        where: { id: bankId },
        data: { mcqCount },
      })
    }

    await createAuditLog({
      userId: user.id,
      action: AuditAction.UPDATE,
      entity: 'InternalExamRuleOverride',
      entityId: bankId,
      description: `Updated exam rules for bank ${bankId}`,
      changes: { ...ruleData, ...(mcqCount ? { mcqCount } : {}) },
    })

    return apiSuccess(override)
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireInstructor } from '@/lib/auth/helpers'
import { apiPaginated, apiError, apiForbidden, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { parsePagination } from '@/lib/api/response'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'
import { isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'

export const GET = withErrorHandler(async (req: NextRequest, ctx: { params: Promise<{ classId: string }> }) => {
  const user = await requireInstructor()
  const instructorProfile = await getInstructorProfileByUserId(user.id)
  if (!instructorProfile) return apiForbidden('Instructor profile not found')

  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }
  const { classId } = await ctx.params

  const classItem = await prismaUnfiltered.class.findUnique({
    where: { id: classId },
    select: { id: true, instructorId: true },
  })
  if (!classItem) return apiNotFound('Class not found')
  if (classItem.instructorId !== instructorProfile.id) {
    return apiForbidden('Not assigned to this class')
  }

  const { searchParams } = new URL(req.url)
  const format = searchParams.get('format')
  const { page, limit, skip } = parsePagination(searchParams)

  const from = searchParams.get('from')
  const to = searchParams.get('to')
  const dateFilter: Record<string, Date> = {}
  if (from) dateFilter.gte = new Date(from)
  if (to) dateFilter.lte = new Date(to)
  const hasDateFilter = Object.keys(dateFilter).length > 0

  const sessionsWhere: any = { classId, status: { in: ['COMPLETED', 'TIMED_OUT'] } }
  if (hasDateFilter) sessionsWhere.submittedAt = dateFilter

  const [
    totalAttempts,
    completedSessions,
    passedSessions,
    avgScoreResult,
    questionStatsRaw,
    correctStatsRaw,
    students,
    studentTotal,
  ] = await Promise.all([
    prismaUnfiltered.internalExamSession.count({
      where: hasDateFilter ? { classId, submittedAt: dateFilter } : { classId },
    }),
    prismaUnfiltered.internalExamSession.count({ where: sessionsWhere }),
    prismaUnfiltered.internalExamSession.count({ where: { ...sessionsWhere, passed: true } }),
    prismaUnfiltered.internalExamSession.aggregate({
      where: { ...sessionsWhere, percentage: { not: null } },
      _avg: { percentage: true },
    }),
    prismaUnfiltered.internalExamAnswer.groupBy({
      by: ['questionId'],
      where: { session: { classId, status: { in: ['COMPLETED', 'TIMED_OUT'] }, ...(hasDateFilter ? { submittedAt: dateFilter } : {}) } },
      _count: { id: true },
    }),
    prismaUnfiltered.internalExamAnswer.groupBy({
      by: ['questionId'],
      where: { session: { classId, status: { in: ['COMPLETED', 'TIMED_OUT'] }, isCorrect: true, ...(hasDateFilter ? { submittedAt: dateFilter } : {}) } },
      _count: { id: true },
    }),
    prismaUnfiltered.internalExamSession.findMany({
      where: hasDateFilter ? { classId, submittedAt: dateFilter } : { classId },
      include: {
        student: {
          select: { id: true, email: true, profile: { select: { firstName: true, lastName: true } } },
        },
        bank: { select: { id: true, name: true } },
      },
      orderBy: { submittedAt: 'desc' },
      take: limit,
      skip,
    }),
    prismaUnfiltered.internalExamSession.count({
      where: hasDateFilter ? { classId, submittedAt: dateFilter } : { classId },
    }),
  ])

  const correctMap = new Map(correctStatsRaw.map((c) => [c.questionId, c._count.id]))
  const questionIds = questionStatsRaw.map((q) => q.questionId)
  const questionDetails =
    questionIds.length > 0
      ? await prismaUnfiltered.internalExamQuestion.findMany({
          where: { id: { in: questionIds } },
          select: { id: true, text: true, difficulty: true },
        })
      : []
  const questionDetailMap = new Map(questionDetails.map((qd) => [qd.id, qd]))

  const questionStats = questionStatsRaw.map((q) => {
    const total = q._count.id
    const correct = correctMap.get(q.questionId) || 0
    const detail = questionDetailMap.get(q.questionId)
    return {
      questionId: q.questionId,
      text: detail?.text || 'Unknown question',
      difficulty: detail?.difficulty || 'MEDIUM',
      totalAnswers: total,
      correctAnswers: correct,
      correctPct: total > 0 ? Math.round((correct / total) * 100) : 0,
    }
  })

  const passRate = completedSessions > 0 ? Math.round((passedSessions / completedSessions) * 100) : 0
  const completionRate = totalAttempts > 0 ? Math.round((completedSessions / totalAttempts) * 100) : 0
  const averageScore = avgScoreResult._avg.percentage ? Math.round(avgScoreResult._avg.percentage) : null

  const studentDrilldown = students.map((s) => ({
    id: s.id,
    student: {
      id: s.student.id,
      name: `${s.student.profile?.firstName || ''} ${s.student.profile?.lastName || ''}`.trim() || s.student.email,
      email: s.student.email,
    },
    bank: s.bank,
    status: s.status,
    score: s.score,
    totalPoints: s.totalPoints,
    percentage: s.percentage,
    passed: s.passed,
    startedAt: s.startedAt?.toISOString() || null,
    submittedAt: s.submittedAt?.toISOString() || null,
  }))

  const payload = {
    summary: {
      totalAttempts,
      completedSessions,
      passRate,
      averageScore,
      completionRate,
    },
    questionStats,
    students: studentDrilldown,
  }

  if (format === 'csv') {
    const headers = ['Student ID', 'Name', 'Email', 'Bank', 'Status', 'Score', 'Total Points', 'Percentage', 'Passed', 'Started At', 'Submitted At']
    const rows = studentDrilldown.map((s) => [
      s.student.id,
      s.student.name,
      s.student.email,
      s.bank.name,
      s.status,
      s.score ?? '',
      s.totalPoints ?? '',
      s.percentage ?? '',
      s.passed ?? '',
      s.startedAt ?? '',
      s.submittedAt ?? '',
    ])

    const csvContent = [
      headers.join(','),
      ...rows.map((row) =>
        row
          .map((val) => {
            if (val === null || val === undefined) val = ''
            val = String(val).replace(/"/g, '""')
            if (val.includes(',') || val.includes('"') || val.includes('\n')) {
              return `"${val}"`
            }
            return val
          })
          .join(',')
      ),
    ].join('\n')

    return new NextResponse(csvContent, {
      headers: {
        'Content-Type': 'text/csv',
        'Content-Disposition': `attachment; filename="class-${classId}-analytics.csv"`,
      },
    })
  }

  return apiPaginated(studentDrilldown, studentTotal, page, limit, {
    summary: {
      totalAttempts,
      completedSessions,
      passRate,
      averageScore,
      completionRate,
    },
    questionStats,
  })
})

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireInstructor } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiForbidden, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'
import { isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'

export const GET = withErrorHandler(async (req: NextRequest, ctx: { params: Promise<{ classId: string }> }) => {
  const user = await requireInstructor()
  const instructorProfile = await getInstructorProfileByUserId(user.id)
  if (!instructorProfile) return apiForbidden('Instructor profile not found')

  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }
  const { classId } = await ctx.params

  const classItem = await prismaUnfiltered.class.findUnique({
    where: { id: classId },
    select: { id: true, instructorId: true },
  })
  if (!classItem) return apiNotFound('Class not found')
  if (classItem.instructorId !== instructorProfile.id) {
    return apiForbidden('Not assigned to this class')
  }

  const sessions = await prismaUnfiltered.internalExamSession.findMany({
    where: { classId },
    include: {
      student: {
        select: { id: true, email: true, profile: { select: { firstName: true, lastName: true } } },
      },
      bank: { select: { id: true, name: true } },
      answers: {
        include: {
          question: { select: { id: true, correctAnswer: true, points: true, text: true } },
        },
      },
    },
    orderBy: { createdAt: 'desc' },
  })

  const now = new Date()

  const result = sessions.map((s) => {
    let correctCount = 0
    let totalPoints = 0
    let earnedPoints = 0

    for (const answer of s.answers) {
      if (answer.question) {
        totalPoints += answer.question.points
        if (answer.selectedAnswer !== null && answer.selectedAnswer === answer.question.correctAnswer) {
          correctCount++
          earnedPoints += answer.question.points
        }
      }
    }

    const timeRemaining =
      s.status === 'IN_PROGRESS' && s.expiresAt
        ? Math.max(0, Math.floor((s.expiresAt.getTime() - now.getTime()) / 1000))
        : null

    return {
      id: s.id,
      status: s.status,
      student: {
        id: s.student.id,
        name: `${s.student.profile?.firstName || ''} ${s.student.profile?.lastName || ''}`.trim() || s.student.email,
        email: s.student.email,
      },
      bank: s.bank,
      startedAt: s.startedAt?.toISOString() || null,
      expiresAt: s.expiresAt?.toISOString() || null,
      submittedAt: s.submittedAt?.toISOString() || null,
      score: s.score,
      totalPoints: s.totalPoints ?? totalPoints,
      percentage: s.percentage,
      passed: s.passed,
      correctCount,
      timeRemaining,
      answerCount: s.answers.length,
    }
  })

  return apiSuccess(result)
})

