import { apiPaginated, apiError, apiForbidden, withErrorHandler } from '@/lib/api/response'
import { parsePagination } from '@/lib/api/response'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'
import { isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'
import { z } from 'zod'

const QUESTION_STATUS_VALUES = ['DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED'] as const

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireInstructor()
  const instructorProfile = await getInstructorProfileByUserId(user.id)
  if (!instructorProfile) return apiForbidden('Instructor profile not found')

  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }

  const { searchParams } = new URL(req.url)
  const { page, limit, skip } = parsePagination(searchParams)
  const view = searchParams.get('view') || 'mine'
  const bankId = searchParams.get('bankId')
  const status = searchParams.get('status')
  const submittedById = searchParams.get('submittedById')

  let bankIds: string[] = []

  if (view === 'mine') {
    const assignments = await prismaUnfiltered.internalExamBankInstructor.findMany({
      where: { instructorId: instructorProfile.id },
      select: { bankId: true },
    })
    bankIds = assignments.map((a) => a.bankId)
  } else if (view === 'module') {
    const classes = await prismaUnfiltered.class.findMany({
      where: { instructorId: instructorProfile.id },
      select: { courseId: true },
    })
    const courseIds = [...new Set(classes.map((c) => c.courseId))]
    if (courseIds.length > 0) {
      const banks = await prismaUnfiltered.internalExamBank.findMany({
        where: { courseId: { in: courseIds } },
        select: { id: true },
      })
      bankIds = banks.map((b) => b.id)
    }
  }

  if (bankIds.length === 0) {
    return apiPaginated([], 0, page, limit)
  }

  const where: any = { bankId: { in: bankIds } }
  if (bankId) where.bankId = bankId
  if (status) {
    const parsed = z.enum(QUESTION_STATUS_VALUES).safeParse(status)
    if (!parsed.success) {
      return apiError(`Invalid status; must be one of ${QUESTION_STATUS_VALUES.join(' | ')}`, 400)
    }
    where.status = parsed.data
  }
  if (submittedById) where.submittedById = submittedById
  if (view === 'mine') where.submittedById = user.id

  const [rawQuestions, total] = await Promise.all([
    prismaUnfiltered.internalExamQuestion.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      skip,
      include: {
        bank: { select: { id: true, name: true } },
      },
    }),
    prismaUnfiltered.internalExamQuestion.count({ where }),
  ])

  const authorIds = Array.from(
    new Set(rawQuestions.map((q) => q.submittedById).filter((id): id is string => Boolean(id)))
  )
  const authors = authorIds.length
    ? await prismaUnfiltered.user.findMany({
        where: { id: { in: authorIds } },
        select: { id: true, name: true, profile: { select: { firstName: true, lastName: true } } },
      })
    : []
  const authorMap = new Map(authors.map((a) => [a.id, a]))

  const questions = rawQuestions.map((q) => ({
    ...q,
    submittedBy: q.submittedById ? authorMap.get(q.submittedById) ?? null : null,
  }))

  return apiPaginated(questions, total, page, limit)
})

import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { requireAuth, verifyPassword, hashPassword } from '@/lib/auth/helpers'
import { apiSuccess, apiForbidden, apiError, withErrorHandler } from '@/lib/api/response'
import { changePasswordSchema, validateBody } from '@/lib/validation/schemas'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { UserRole } from '@prisma/client'

export const POST = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  if (user.role !== UserRole.INSTRUCTOR) return apiForbidden('Instructor access required')

  const body = await req.json()
  const validation = validateBody(changePasswordSchema, body)
  if (!validation.success) return apiError(validation.error)

  const { currentPassword, newPassword } = validation.data

  const dbUser = await prisma.user.findUnique({ where: { id: user.id } })
  if (!dbUser?.password) return apiError('No password set')

  const isValid = await verifyPassword(currentPassword, dbUser.password)
  if (!isValid) return apiError('Current password is incorrect')

  const hashedPassword = await hashPassword(newPassword)
  await prisma.user.update({
    where: { id: user.id },
    data: { password: hashedPassword, mustChangePassword: false, passwordChanged: true, passwordChangedAt: new Date() },
  })

  await createAuditLog({
    action: 'PASSWORD_CHANGE',
    entity: 'User',
    entityId: user.id,
    userId: user.id,
  })

  return apiSuccess({ message: 'Password changed successfully' })
})

import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { requireAuth, verifyPassword, hashPassword } from '@/lib/auth/helpers'
import { apiSuccess, apiForbidden, apiError, withErrorHandler } from '@/lib/api/response'
import { updateProfileSchema, changePasswordSchema, validateBody } from '@/lib/validation/schemas'
import { createAuditLog } from '@/lib/audit/logger'
import { UserRole } from '@prisma/client'

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  if (user.role !== UserRole.INSTRUCTOR) return apiForbidden('Instructor access required')

  const [profile, instructorProfile] = await Promise.all([
    prisma.profile.findUnique({ where: { userId: user.id } }),
    prisma.instructorProfile.findUnique({ where: { userId: user.id } }),
  ])
  return apiSuccess({ profile, instructorProfile })
})

export const PATCH = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  if (user.role !== UserRole.INSTRUCTOR) return apiForbidden('Instructor access required')

  const body = await req.json()
  const validation = validateBody(updateProfileSchema, body)
  if (!validation.success) return apiError(validation.error)

  const profile = await prisma.profile.update({
    where: { userId: user.id },
    data: validation.data,
  })
  return apiSuccess(profile)
})

import { NextRequest } from 'next/server'
import prisma from '@/lib/prisma/client'
import { requireAuth } from '@/lib/auth/helpers'
import { apiSuccess, apiForbidden, withErrorHandler } from '@/lib/api/response'
import { UserRole } from '@prisma/client'
import { getInstructorProfileByUserId } from '@/lib/instructor/profile'

export const GET = withErrorHandler(async (req: NextRequest) => {
  const user = await requireAuth()
  if (user.role !== UserRole.INSTRUCTOR) return apiForbidden('Instructor access required')
  const instructorProfile = await getInstructorProfileByUserId(user.id)
  if (!instructorProfile) return apiForbidden('Instructor profile not found')

  const { searchParams } = new URL(req.url)
  const startDate = searchParams.get('start')
  const endDate = searchParams.get('end')

  const where: any = { instructorId: instructorProfile.id }
  if (startDate || endDate) {
    where.startDate = {}
    if (startDate) where.startDate.gte = new Date(startDate)
    if (endDate) where.startDate.lte = new Date(endDate)
  }

  const classes = await prisma.class.findMany({
    where,
    include: {
      course: { select: { code: true, name: true, category: true } },
    },
    orderBy: { startDate: 'asc' },
  })

  return apiSuccess(classes)
})

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import prisma from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { triggerAutoEnrollmentIfRequired } from '@/lib/enrollment/engine'
import { generateStudentId } from '@/lib/auth/helpers'

export async function POST(req: NextRequest) {
  const session = await getAuthSession()
  if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['APPLICANT', 'STUDENT'].includes(session.user.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const userId = session.user.id

  try {
    const { studyPathway, licenseCodes } = await req.json()

    // Validate using relational pathway codes
    const pathway = await prisma.studyPathwayModel.findUnique({
      where: { code: studyPathway },
    })

    if (!pathway) {
      return NextResponse.json({ error: 'Invalid study pathway selected' }, { status: 400 })
    }

    // Check if a pathway is already locked
    const existingProfile = await prisma.studentProfile.findUnique({
      where: { userId },
      select: { id: true, pathwayId: true },
    })

    if (existingProfile?.pathwayId) {
      return NextResponse.json(
        { error: 'Study pathway is already locked and cannot be changed' },
        { status: 400 }
      )
    }

    let profileId = ''

    await prisma.$transaction(async (tx) => {
      // 1. Create or update StudentProfile
      if (existingProfile) {
        await tx.studentProfile.update({
          where: { userId },
          data: {
            pathwayId: pathway.id,
            studyPathwayLockedAt: new Date(),
            studyPathwayLocked: true,
          },
        })
        profileId = existingProfile.id
      } else {
        const created = await tx.studentProfile.create({
          data: {
            userId,
            studentId: await generateStudentId(),
            pathwayId: pathway.id,
            studyPathwayLockedAt: new Date(),
            studyPathwayLocked: true,
          },
        })
        profileId = created.id
      }

      // 2. Link License Targets
      if (licenseCodes && Array.isArray(licenseCodes)) {
        const licenseCats = await tx.licenseCategory.findMany({
          where: { code: { in: licenseCodes } },
        })

        for (const lc of licenseCats) {
          await tx.studentLicenseTarget.upsert({
            where: {
              studentProfileId_licenseCategoryId: {
                studentProfileId: profileId,
                licenseCategoryId: lc.id,
              },
            },
            update: {},
            create: {
              studentProfileId: profileId,
              licenseCategoryId: lc.id,
            },
          })
        }
      }

      // 3. Ensure they have a Wallet
      const existingWallet = await tx.wallet.findUnique({ where: { userId } })
      if (!existingWallet) {
        await tx.wallet.create({
          data: {
            userId,
            balance: 0,
            reservedBalance: 0,
            availableBalance: 0,
            currency: 'EUR',
          },
        })
      }
    })

    // 4. Trigger Auto-Enrollment (after transaction)
    await triggerAutoEnrollmentIfRequired(profileId)

    await createAuditLog({
      action: 'PATHWAY_SETUP',
      entity: 'student_profiles',
      entityId: userId,
      userId,
      description: `Student chose ${studyPathway} pathway and licenses: ${licenseCodes?.join(', ') || 'none'}. Locked.`,
    })

    return NextResponse.json({
      success: true,
      studyPathway,
      message: 'Pathway locked and auto-enrollment triggered.',
    })
  } catch (error: any) {
    console.error('Pathway selection error:', error)
    return NextResponse.json({ error: 'Failed to process pathway selection' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { withErrorHandler, apiSuccess } from '@/lib/api/response'
import { requireAuth } from '@/lib/auth/helpers'
import { resolvePresenceForViewer } from '@/lib/presence'

/**
 * Returns presence info for a list of peer user-ids, scoped to what the
 * current viewer is allowed to see. Pass peer ids via repeated `id=` query
 * params: `/api/messages/presence?id=u1&id=u2&id=u3`.
 */
export const GET = withErrorHandler(async (req: NextRequest) => {
  const viewer = await requireAuth()
  const url = new URL(req.url)
  const ids = url.searchParams.getAll('id').filter(Boolean).slice(0, 100)
  if (ids.length === 0) return apiSuccess([])

  const role = (viewer as any).role ?? 'STUDENT'
  const entries = await resolvePresenceForViewer({
    viewerId: viewer.id,
    viewerRole: role,
    peerIds: ids,
  })
  return apiSuccess(entries)
})

import { NextRequest, NextResponse } from 'next/server'
import { renderToStream } from '@react-pdf/renderer'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getPDFSettings } from '@/lib/pdf-settings'
import { TranscriptTemplate, TranscriptRecord } from '@/components/pdf/templates/TranscriptTemplate'
import React from 'react'

const STAFF_ROLES = ['ADMIN', 'SUPER_ADMIN', 'STAFF']

export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await getAuthSession()
    if (!session || !STAFF_ROLES.includes(session.user.role)) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { id: studentUserId } = await params

    // Fetch student data in parallel
    const [profile, examResults, pdfSettings] = await Promise.all([
      prismaUnfiltered.studentProfile.findUnique({
        where: { userId: studentUserId },
        select: {
          studentId: true,
          enrollmentType: true,
          enrollmentDate: true,
          user: {
            select: {
              profile: { select: { firstName: true, lastName: true } },
              email: true,
            },
          },
          pathwayRel: { select: { name: true } },
        },
      }),
      prismaUnfiltered.examResult.findMany({
        where: { userId: studentUserId },
        select: {
          moduleCode: true,
          percentage: true,
          passed: true,
          examCategory: true,
          attemptType: true,
          createdAt: true,
          exam: {
            select: {
              examDate: true,
              examComponent: {
                select: {
                  course: { select: { code: true, name: true, credits: true } },
                },
              },
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      }),
      getPDFSettings(req.nextUrl.origin),
    ])

    if (!profile) {
      return NextResponse.json({ error: 'Student profile not found' }, { status: 404 })
    }

    const fullName = profile.user.profile
      ? `${profile.user.profile.firstName} ${profile.user.profile.lastName}`
      : (profile.user.email ?? 'Student')

    const programName = profile.pathwayRel?.name ?? profile.enrollmentType ?? 'EASA Programme'

    // Deduplicate by module code — keep the best (passed) result per module
    const moduleMap = new Map<string, TranscriptRecord>()
    for (const r of examResults) {
      const code = r.exam?.examComponent?.course?.code ?? r.moduleCode ?? '—'
      const courseName = r.exam?.examComponent?.course?.name ?? r.moduleCode ?? '—'
      const credits = r.exam?.examComponent?.course?.credits ?? 0

      const existing = moduleMap.get(code)
      if (!existing || (r.passed && !existing.status.includes('Pass'))) {
        moduleMap.set(code, {
          code,
          courseName,
          credits,
          grade: r.passed ? 'Pass' : 'Fail',
          status: r.passed ? 'Pass' : 'Fail',
        })
      }
    }

    const records: TranscriptRecord[] = Array.from(moduleMap.values()).sort((a, b) =>
      a.code.localeCompare(b.code, undefined, { numeric: true })
    )

    const now = new Date()

    const stream = await renderToStream(
      <TranscriptTemplate
        logoUrl={pdfSettings.logoUrl}
        watermarkUrl={pdfSettings.watermarkUrl}
        footerText={pdfSettings.footerText}
        watermarkOpacity={pdfSettings.watermarkOpacity}
        studentName={fullName}
        studentId={profile.studentId ?? '—'}
        programName={programName}
        enrollmentDate={
          profile.enrollmentDate?.toLocaleDateString('en-GB', {
            day: '2-digit',
            month: 'short',
            year: 'numeric',
          }) ?? '—'
        }
        generatedDate={now.toLocaleDateString('en-GB', {
          day: '2-digit',
          month: 'short',
          year: 'numeric',
        })}
        records={records}
      />
    )

    const safeId = (profile.studentId ?? 'student').replace(/[^a-zA-Z0-9-]/g, '_')

    return new NextResponse(stream as any, {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `inline; filename="Transcript_${safeId}.pdf"`,
      },
    })
  } catch (error: any) {
    console.error('[pdf/staff/student-transcript] Error:', error)
    return NextResponse.json(
      { error: 'Failed to generate transcript', details: error.message },
      { status: 500 }
    )
  }
}

