import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { BondingStatus } from '@prisma/client'
import { z } from 'zod'

const VALID_TRANSITIONS: Record<BondingStatus, BondingStatus[]> = {
  ISSUED: [BondingStatus.SIGNED],
  SIGNED: [BondingStatus.IN_PROGRESS],
  IN_PROGRESS: [BondingStatus.FULFILLED, BondingStatus.BREACHED],
  FULFILLED: [],
  BREACHED: [],
}

const updateSchema = z.object({
  status: z.nativeEnum(BondingStatus).optional(),
  facilityName: z.string().optional(),
  notes: z.string().optional(),
  signedAt: z.string().datetime().optional().nullable(),
  startDate: z.string().datetime().optional().nullable(),
  endDate: z.string().datetime().optional().nullable(),
})

export const GET = withErrorHandler(async (_req: NextRequest, ctx: any) => {
  await requireStaff()
  const { id } = ctx.params

  const contract = await prismaUnfiltered.bondingContract.findUnique({
    where: { id },
    include: {
      application: {
        select: {
          programmeChoice: true,
          fundingType: true,
          stage: true,
          user: {
            select: {
              id: true,
              email: true,
              profile: { select: { firstName: true, lastName: true, phone: true } },
            },
          },
        },
      },
      studentProfile: {
        select: { studentId: true, enrollmentStatus: true, enrollmentDate: true },
      },
    },
  })

  if (!contract) return apiError('Bonding contract not found', 404)
  return apiSuccess(contract)
})

export const PUT = withErrorHandler(async (req: NextRequest, ctx: any) => {
  const staff = await requireStaff()
  const { id } = ctx.params

  const body = await req.json()
  const parsed = updateSchema.safeParse(body)
  if (!parsed.success) return apiError(parsed.error.issues[0].message)

  const contract = await prismaUnfiltered.bondingContract.findUnique({ where: { id } })
  if (!contract) return apiError('Bonding contract not found', 404)

  const { status, facilityName, notes, signedAt, startDate, endDate } = parsed.data

  // Validate status transition
  if (status && status !== contract.status) {
    const allowed = VALID_TRANSITIONS[contract.status]
    if (!allowed.includes(status)) {
      return apiError(
        `Cannot transition from ${contract.status} to ${status}. Allowed: ${allowed.join(', ') || 'none (terminal state)'}`
      )
    }
  }

  const updated = await prismaUnfiltered.bondingContract.update({
    where: { id },
    data: {
      ...(status ? { status } : {}),
      ...(facilityName !== undefined ? { facilityName } : {}),
      ...(notes !== undefined ? { notes } : {}),
      ...(signedAt !== undefined ? { signedAt: signedAt ? new Date(signedAt) : null } : {}),
      ...(startDate !== undefined ? { startDate: startDate ? new Date(startDate) : null } : {}),
      ...(endDate !== undefined ? { endDate: endDate ? new Date(endDate) : null } : {}),
      updatedBy: staff.id,
    },
    include: {
      application: {
        select: {
          programmeChoice: true,
          fundingType: true,
          user: {
            select: {
              id: true,
              email: true,
              profile: { select: { firstName: true, lastName: true } },
            },
          },
        },
      },
      studentProfile: { select: { studentId: true } },
    },
  })

  if (status && status !== contract.status) {
    await createAuditLog({
      userId: staff.id,
      action: 'UPDATE',
      entity: 'BondingContract',
      entityId: id,
      description: `Bonding contract status changed from ${contract.status} to ${status}`,
      changes: { from: contract.status, to: status, notes },
    })
  }

  return apiSuccess(updated)
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiPaginated, apiError, withErrorHandler, parsePagination } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { BondingStatus, Prisma } from '@prisma/client'

export const GET = withErrorHandler(async (req: NextRequest) => {
  await requireStaff()

  const url = new URL(req.url)
  const { page, limit, skip } = parsePagination(url.searchParams)
  const status = url.searchParams.get('status') as BondingStatus | null
  const search = url.searchParams.get('search')?.trim()

  const where: Prisma.BondingContractWhereInput = {}

  if (status && Object.values(BondingStatus).includes(status)) {
    where.status = status
  }

  if (search) {
    where.OR = [
      { application: { user: { email: { contains: search, mode: 'insensitive' } } } },
      { application: { user: { profile: { firstName: { contains: search, mode: 'insensitive' } } } } },
      { application: { user: { profile: { lastName: { contains: search, mode: 'insensitive' } } } } },
      { studentProfile: { studentId: { contains: search, mode: 'insensitive' } } },
      { facilityName: { contains: search, mode: 'insensitive' } },
    ]
  }

  const [contracts, total, statusCounts] = await Promise.all([
    prismaUnfiltered.bondingContract.findMany({
      where,
      include: {
        application: {
          select: {
            programmeChoice: true,
            fundingType: true,
            user: {
              select: {
                id: true,
                email: true,
                profile: { select: { firstName: true, lastName: true } },
              },
            },
          },
        },
        studentProfile: {
          select: { studentId: true },
        },
      },
      orderBy: { createdAt: 'desc' },
      skip,
      take: limit,
    }),
    prismaUnfiltered.bondingContract.count({ where }),
    prismaUnfiltered.bondingContract.groupBy({
      by: ['status'],
      _count: { status: true },
    }),
  ])

  const counts: Record<string, number> = {}
  for (const s of statusCounts) {
    counts[s.status] = s._count.status
  }

  return apiPaginated(contracts, total, page, limit, { statusCounts: counts })
})

