import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiCreated, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { z } from 'zod'

const evaluationSchema = z.object({
  communicationScore: z.number().int().min(1).max(10),
  technicalScore: z.number().int().min(1).max(10),
  motivationScore: z.number().int().min(1).max(10),
  problemSolvingScore: z.number().int().min(1).max(10),
  teamworkScore: z.number().int().min(1).max(10),
  professionalismScore: z.number().int().min(1).max(10),
  overallImpression: z.number().int().min(1).max(10),
  personalScore: z.number().int().min(0).max(100),
  recommendation: z.enum(['STRONG_YES', 'YES', 'MAYBE', 'NO', 'STRONG_NO']),
  communicationNotes: z.string().optional(),
  technicalNotes: z.string().optional(),
  motivationNotes: z.string().optional(),
  problemSolvingNotes: z.string().optional(),
  teamworkNotes: z.string().optional(),
  professionalismNotes: z.string().optional(),
  generalRemarks: z.string().optional(),
})

// GET — list all evaluations for an application
export const GET = withErrorHandler(async (_req: NextRequest, ctx: any) => {
  await requireStaff()
  const { applicationId } = ctx.params

  const evaluations = await prismaUnfiltered.interviewEvaluation.findMany({
    where: { applicationId },
    include: {
      evaluator: {
        select: {
          id: true,
          email: true,
          profile: { select: { firstName: true, lastName: true } },
        },
      },
    },
    orderBy: { createdAt: 'desc' },
  })

  // Calculate averaged scores across all evaluators
  let averages = null
  if (evaluations.length > 0) {
    const sum = (key: keyof typeof evaluations[0]) =>
      evaluations.reduce((acc, e) => acc + (e[key] as number), 0)

    const count = evaluations.length
    averages = {
      communicationScore: Math.round((sum('communicationScore') / count) * 10) / 10,
      technicalScore: Math.round((sum('technicalScore') / count) * 10) / 10,
      motivationScore: Math.round((sum('motivationScore') / count) * 10) / 10,
      problemSolvingScore: Math.round((sum('problemSolvingScore') / count) * 10) / 10,
      teamworkScore: Math.round((sum('teamworkScore') / count) * 10) / 10,
      professionalismScore: Math.round((sum('professionalismScore') / count) * 10) / 10,
      overallImpression: Math.round((sum('overallImpression') / count) * 10) / 10,
      personalScore: Math.round((sum('personalScore') / count) * 10) / 10,
      evaluatorCount: count,
      // Composite interview score: average of all dimension scores (scaled to 0-100)
      compositeScore: Math.round(
        (((sum('communicationScore') +
          sum('technicalScore') +
          sum('motivationScore') +
          sum('problemSolvingScore') +
          sum('teamworkScore') +
          sum('professionalismScore') +
          sum('overallImpression')) /
          (count * 7)) *
          10) *
          10
      ) / 10,
    }
  }

  return apiSuccess({ evaluations, averages })
})

// POST — create or update evaluation (one per evaluator per application)
export const POST = withErrorHandler(async (req: NextRequest, ctx: any) => {
  const staff = await requireStaff()
  const { applicationId } = ctx.params

  const body = await req.json()
  const parsed = evaluationSchema.safeParse(body)
  if (!parsed.success) return apiError(parsed.error.issues[0].message)

  // Verify application exists and is at interview stage
  const application = await prismaUnfiltered.application.findUnique({
    where: { id: applicationId },
    select: { id: true, stage: true },
  })
  if (!application) return apiError('Application not found', 404)

  const validStages = [
    'INTERVIEW_SCHEDULED',
    'INTERVIEW_COMPLETED',
    'SELECTED',
    'SHORTLISTED',
    'MEDICAL_PENDING',
    'MEDICAL_SUBMITTED',
    'MEDICAL_CLEARED',
    'ENROLLED',
  ]
  if (!validStages.includes(application.stage)) {
    return apiError('Application is not at a stage where interview evaluations can be submitted')
  }

  // Upsert: one evaluation per evaluator per application
  const evaluation = await prismaUnfiltered.interviewEvaluation.upsert({
    where: {
      applicationId_evaluatorId: {
        applicationId,
        evaluatorId: staff.id,
      },
    },
    create: {
      applicationId,
      evaluatorId: staff.id,
      ...parsed.data,
    },
    update: parsed.data,
    include: {
      evaluator: {
        select: {
          id: true,
          email: true,
          profile: { select: { firstName: true, lastName: true } },
        },
      },
    },
  })

  await createAuditLog({
    userId: staff.id,
    action: 'CREATE',
    entity: 'InterviewEvaluation',
    entityId: evaluation.id,
    description: `Interview evaluation submitted for application ${applicationId}`,
    changes: {
      personalScore: parsed.data.personalScore,
      recommendation: parsed.data.recommendation,
    },
  })

  return apiCreated(evaluation)
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { transitionApplication } from '@/lib/admissions/state-machine'
import { z } from 'zod'

const schema = z.object({
  applicationId: z.string(),
  outcome: z.enum(['PASS', 'FAIL', 'CONDITIONAL', 'NO_SHOW']),
  score: z.number().min(0).max(100).optional(),
  notes: z.string().optional(),
})

export const POST = withErrorHandler(async (req: NextRequest) => {
  const staff = await requireStaff()
  const staffId = staff.id

  const body = await req.json()
  const result = schema.safeParse(body)
  if (!result.success) return apiError('Invalid input')

  const { applicationId, outcome, score, notes } = result.data

  const app = await prismaUnfiltered.application.findUnique({
    where: { id: applicationId },
  })

  if (!app) return apiError('Application not found', 404)

  if (outcome === 'NO_SHOW') {
    // Return to pending and clear slot
    await prismaUnfiltered.application.update({
      where: { id: applicationId },
      data: { interviewSlotId: null }
    })
    
    // Decrease booked count on the slot
    if (app.interviewSlotId) {
      await prismaUnfiltered.interviewSlot.update({
        where: { id: app.interviewSlotId },
        data: { bookedCount: { decrement: 1 } }
      })
    }

    await transitionApplication(applicationId, 'INTERVIEW_PENDING', staffId, {
      metadata: { notes, noShow: true }
    })
  } else {
    // First mark as completed if it's currently scheduled
    if (app.stage === 'INTERVIEW_SCHEDULED') {
      await transitionApplication(applicationId, 'INTERVIEW_COMPLETED', staffId, {
        metadata: { notes }
      })
    }

    // Then move to final outcome
    if (outcome === 'PASS' || outcome === 'CONDITIONAL') {
      await transitionApplication(applicationId, 'SELECTED', staffId, {
        metadata: { notes, score, isConditional: outcome === 'CONDITIONAL' }
      })
    } else {
      await transitionApplication(applicationId, 'REJECTED', staffId, {
        rejectionReason: notes || 'Interview failed'
      })
    }
    
    // Save notes and score to metadata
    const existingMeta = (app.metadata as any) || {}
    await prismaUnfiltered.application.update({
      where: { id: applicationId },
      data: {
        metadata: { 
          ...existingMeta, 
          interviewNotes: notes,
          interviewScore: score,
          interviewConditional: outcome === 'CONDITIONAL'
        }
      }
    })
  }

  return apiSuccess({ success: true })
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getInterviewConfig } from '@/lib/settings'
import { z } from 'zod'

const schema = z.object({
  dateStart: z.string().datetime(),
  dateEnd: z.string().datetime(),
  daysOfWeek: z.array(z.number().min(0).max(6)), // 0 = Sunday, 6 = Saturday
  timeBlocks: z.array(z.object({
    start: z.string(), // "09:00"
    end: z.string(), // "10:00"
    capacity: z.number().min(1),
    location: z.string().optional()
  })).min(1),
})

export const POST = withErrorHandler(async (req: NextRequest, { params }: { params: Promise<{ id: string }> }) => {
  await requireStaff()
  const { id } = await params
  
  const body = await req.json()
  const result = schema.safeParse(body)
  if (!result.success) return apiError('Invalid input')

  const { dateStart, dateEnd, daysOfWeek, timeBlocks } = result.data

  const schedule = await prismaUnfiltered.interviewSchedule.findUnique({ where: { id } })
  if (!schedule) return apiError('Schedule not found', 404)

  const config = await getInterviewConfig()

  const start = new Date(dateStart)
  const end = new Date(dateEnd)
  
  if (start > end) return apiError('Start date must be before end date', 400)

  const slotsToCreate = []

  const currentDate = new Date(start)
  while (currentDate <= end) {
    if (daysOfWeek.includes(currentDate.getDay())) {
      for (const block of timeBlocks) {
        const [startHours, startMinutes] = block.start.split(':').map(Number)
        const [endHours, endMinutes] = block.end.split(':').map(Number)
        
        const slotStartTime = new Date(currentDate)
        slotStartTime.setHours(startHours, startMinutes, 0, 0)
        
        const slotEndTime = new Date(currentDate)
        slotEndTime.setHours(endHours, endMinutes, 0, 0)

        // Verify it doesn't exceed daily capacity if we want to enforce it (optional, 
        // plan says "daily capacity limit", but here we just create slots per timeBlocks)
        
        slotsToCreate.push({
          scheduleId: id,
          date: new Date(currentDate), // Strip time for date field
          startTime: slotStartTime,
          endTime: slotEndTime,
          capacity: block.capacity,
          location: block.location,
        })
      }
    }
    currentDate.setDate(currentDate.getDate() + 1)
  }

  const created = await prismaUnfiltered.interviewSlot.createMany({
    data: slotsToCreate
  })

  return apiSuccess({ count: created.count })
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { transitionApplication } from '@/lib/admissions/state-machine'
import { ApplicationStage, MedicalStatus } from '@prisma/client'
import { z } from 'zod'

const MEDICAL_STATUSES = ['CLEARED', 'FAILED', 'EXEMPTED'] as const
const reviewSchema = z.object({
  applicationId: z.string(),
  decision: z.enum(MEDICAL_STATUSES),
  notes: z.string().optional(),
  facility: z.string().optional(),
})

export const POST = withErrorHandler(async (req: NextRequest, _ctx: any) => {
  const staff = await requireStaff()

  const body = await req.json()
  const parsed = reviewSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input')

  const { applicationId, decision, notes, facility } = parsed.data

  // Load current application
  const app = await prismaUnfiltered.application.findUnique({
    where: { id: applicationId },
    include: { user: { select: { id: true, email: true } } },
    // fundingType is a scalar field on Application, included by default
  })
  if (!app) return apiError('Application not found', 404)
  if (app.stage !== 'MEDICAL_SUBMITTED' && app.stage !== 'MEDICAL_PENDING') {
    return apiError(`Application is in stage ${app.stage}, cannot review medical`)
  }

  // Update medical fields
  await prismaUnfiltered.application.update({
    where: { id: applicationId },
    data: {
      medicalStatus: decision as MedicalStatus,
      medicalNotes: notes || null,
      medicalFacility: facility || null,
      ...(decision === 'CLEARED' || decision === 'EXEMPTED'
        ? { medicalClearedAt: new Date(), medicalClearedBy: staff.id }
        : {}),
    },
  })

  // Transition based on decision
  if (decision === 'CLEARED' || decision === 'EXEMPTED') {
    const result = await transitionApplication(
      applicationId,
      ApplicationStage.MEDICAL_CLEARED,
      staff.id,
      { metadata: { medicalDecision: decision, reviewedBy: staff.id } }
    )
    if (!result.success) return apiError(result.error || 'Transition failed')

    // Auto-enroll if MEDICAL_CLEARED is the last pre-enrollment stage
    const enrollResult = await transitionApplication(
      applicationId,
      ApplicationStage.ENROLLED,
      staff.id,
      { metadata: { autoEnrolled: true, trigger: 'medical_cleared' } }
    )

    if (enrollResult.success) {
      // Create StudentProfile on enrollment
      const existing = await prismaUnfiltered.studentProfile.findUnique({
        where: { userId: app.userId },
      })
      if (!existing) {
        // Generate unique student ID
        let studentId = ''
        let unique = false
        while (!unique) {
          const rand = Math.floor(1000 + Math.random() * 9000).toString()
          studentId = `AATA-${rand}`
          const check = await prismaUnfiltered.studentProfile.findUnique({ where: { studentId } })
          if (!check) unique = true
        }

        await prismaUnfiltered.studentProfile.create({
          data: {
            userId: app.userId,
            studentId,
            enrollmentStatus: 'ENROLLED',
            enrollmentDate: new Date(),
            programmeChoice: app.programmeChoice,
          },
        })
      }

      // Auto-create BondingContract for SCHOLARSHIP students
      if (app.fundingType === 'SCHOLARSHIP') {
        const existingContract = await prismaUnfiltered.bondingContract.findUnique({
          where: { applicationId: app.id },
        })
        if (!existingContract) {
          const sp = await prismaUnfiltered.studentProfile.findUnique({
            where: { userId: app.userId },
          })
          await prismaUnfiltered.bondingContract.create({
            data: {
              applicationId: app.id,
              studentProfileId: sp?.id || null,
              status: 'ISSUED',
            },
          })
        }
      }

      // Update user role to STUDENT
      await prismaUnfiltered.user.update({
        where: { id: app.userId },
        data: { role: 'STUDENT' },
      })
    }

    return apiSuccess({ decision, enrolled: enrollResult.success })
  } else {
    // FAILED — reject the application
    const result = await transitionApplication(
      applicationId,
      ApplicationStage.REJECTED,
      staff.id,
      { rejectionReason: `Medical examination failed: ${notes || 'No details provided'}` }
    )
    return apiSuccess({ decision, rejected: result.success })
  }
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { STAGE_ORDER, STAGE_INFO } from '@/lib/admissions/constants'

/**
 * GET /api/staff/admissions/pipeline
 * Returns real-time pipeline analytics: stage distribution, conversion rates,
 * and time-in-stage averages for the admissions funnel.
 */
export const GET = withErrorHandler(async (req: NextRequest, _ctx: any) => {
  await requireStaff()
  const url = new URL(req.url)
  const intakeCycleId = url.searchParams.get('intakeCycleId')

  const where: any = {}
  if (intakeCycleId) where.intakeCycleId = intakeCycleId

  // Stage distribution
  const stageCounts = await prismaUnfiltered.application.groupBy({
    by: ['stage'],
    where,
    _count: { _all: true },
  })

  const stageMap: Record<string, number> = {}
  let totalApps = 0
  for (const sc of stageCounts) {
    stageMap[sc.stage] = sc._count._all
    totalApps += sc._count._all
  }

  // Build funnel from defined stages
  const funnel = STAGE_ORDER.map((stage) => ({
    stage,
    label: STAGE_INFO[stage]?.label || stage,
    count: stageMap[stage] || 0,
    percent: totalApps > 0 ? Math.round(((stageMap[stage] || 0) / totalApps) * 100) : 0,
  }))

  // Programme breakdown
  const programmeBreakdown = await prismaUnfiltered.application.groupBy({
    by: ['programmeChoice'],
    where,
    _count: { _all: true },
  })

  // Outcome stats
  const enrolled = stageMap['ENROLLED'] || 0
  const rejected = stageMap['REJECTED'] || 0
  const withdrawn = stageMap['WITHDRAWN'] || 0
  const conversionRate = totalApps > 0 ? Math.round((enrolled / totalApps) * 100) : 0

  // Recent activity (last 7 days)
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
  const recentApps = await prismaUnfiltered.application.count({
    where: { ...where, createdAt: { gte: sevenDaysAgo } },
  })
  const recentEnrolled = await prismaUnfiltered.application.count({
    where: { ...where, stage: 'ENROLLED', updatedAt: { gte: sevenDaysAgo } },
  })

  // Active intake cycles
  const cycles = await prismaUnfiltered.intakeCycle.findMany({
    where: { isActive: true },
    select: { id: true, name: true, startDate: true, endDate: true },
    orderBy: { startDate: 'desc' },
  })

  return apiSuccess({
    total: totalApps,
    funnel,
    programmeBreakdown: programmeBreakdown.map(p => ({
      programme: p.programmeChoice,
      count: p._count._all,
    })),
    outcomes: {
      enrolled,
      rejected,
      withdrawn,
      conversionRate,
    },
    recentActivity: {
      newApplications: recentApps,
      newEnrollments: recentEnrolled,
    },
    cycles,
  })
})

