import { NextRequest, NextResponse } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getAttendanceThreshold } from '@/lib/attendance'

interface EnrollmentWithCourse {
  user: {
    id: string
    email: string
    profile: { firstName: string; lastName: string } | null
    studentProfile: { studentId: string } | null
  }
  course: { code: string; name: string }
  courseId: string
}

interface AttendanceWithClass {
  userId: string
  status: string
  class: { courseId: string }
}

export const GET = withErrorHandler(async (req: NextRequest) => {
  await requireStaff()
  const url = new URL(req.url)
  const courseId = url.searchParams.get('courseId')
  const moduleCode = url.searchParams.get('moduleCode')
  const format = url.searchParams.get('format') // 'json' or 'csv'

  const { effective: threshold } = await getAttendanceThreshold()

  // Get all active students with their enrollments
  const enrollments = await prismaUnfiltered.enrollment.findMany({
    where: {
      status: { in: ['ENROLLED', 'ACTIVE', 'APPROVED'] },
      ...(courseId ? { courseId } : {}),
      ...(moduleCode ? { course: { code: moduleCode } } : {}),
    },
    include: {
      user: {
        select: {
          id: true,
          email: true,
          profile: { select: { firstName: true, lastName: true } },
          studentProfile: { select: { studentId: true } },
        },
      },
      course: { select: { code: true, name: true } },
    },
  })

  const studentIds = enrollments.map((e: EnrollmentWithCourse) => e.user.id)

  const records = await prismaUnfiltered.attendanceRecord.findMany({
    where: { userId: { in: studentIds } },
    include: {
      class: { select: { id: true, name: true, courseId: true } },
    },
  })

  const recordsByUser = new Map<string, AttendanceWithClass[]>()
  for (const r of records) {
    const list = recordsByUser.get(r.userId) || []
    list.push(r as AttendanceWithClass)
    recordsByUser.set(r.userId, list)
  }

  const report = enrollments.map((e: EnrollmentWithCourse) => {
    const userRecords = recordsByUser.get(e.user.id) || []
    const courseRecords = userRecords.filter((r: AttendanceWithClass) => r.class.courseId === e.courseId)
    const total = courseRecords.length
    const present = courseRecords.filter((r: AttendanceWithClass) => r.status === 'PRESENT' || r.status === 'LATE').length
    const rate = total > 0 ? Math.round((present / total) * 100) : 0
    const absent = courseRecords.filter((r: AttendanceWithClass) => r.status === 'ABSENT').length
    const excused = courseRecords.filter((r: AttendanceWithClass) => r.status === 'EXCUSED').length
    const complianceStatus = rate >= threshold ? 'COMPLIANT' : rate >= threshold - 5 ? 'AT_RISK' : 'NON_COMPLIANT'

    return {
      userId: e.user.id,
      studentId: e.user.studentProfile?.studentId,
      name: `${e.user.profile?.firstName || ''} ${e.user.profile?.lastName || ''}`.trim() || e.user.email,
      email: e.user.email,
      courseId: e.courseId,
      moduleCode: e.course.code,
      moduleName: e.course.name,
      total,
      present,
      absent,
      excused,
      rate,
      complianceStatus,
      threshold,
    }
  })

  if (format === 'csv') {
    const headers = [
      'Student ID',
      'Name',
      'Email',
      'Module Code',
      'Module Name',
      'Total Sessions',
      'Present',
      'Absent',
      'Excused',
      'Rate %',
      'Threshold %',
      'Compliance Status',
    ]
    const rows = [headers.join(',')]
    for (const r of report) {
      rows.push(
        [
          r.studentId || '',
          `"${r.name.replace(/"/g, '""')}"`,
          r.email,
          r.moduleCode,
          `"${r.moduleName.replace(/"/g, '""')}"`,
          r.total,
          r.present,
          r.absent,
          r.excused,
          r.rate,
          r.threshold,
          r.complianceStatus,
        ].join(',')
      )
    }
    const csv = rows.join('\n')
    return new NextResponse(csv, {
      headers: {
        'Content-Type': 'text/csv',
        'Content-Disposition': 'attachment; filename="attendance_compliance_report.csv"',
      },
    })
  }

  return apiSuccess({ report, threshold })
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { AttendanceStatus } from '@prisma/client'
import { z } from 'zod'

const STATUSES = Object.values(AttendanceStatus) as [AttendanceStatus, ...AttendanceStatus[]]

const batchSchema = z.object({
  classId: z.string(),
  date: z.string(),
  records: z.array(
    z.object({
      userId: z.string(),
      status: z.enum(STATUSES),
      minutesLate: z.number().optional(),
      notes: z.string().optional(),
    })
  ),
})

// GET — fetch attendance for a class + date, and the class roster (from course enrollments)
export const GET = withErrorHandler(async (req: NextRequest, _ctx: any) => {
  await requireStaff()
  const url = new URL(req.url)
  const classId = url.searchParams.get('classId')
  const date = url.searchParams.get('date')

  if (!classId) return apiError('classId is required')

  const where: any = { classId }
  if (date) {
    const d = new Date(date)
    const next = new Date(d.getTime() + 24 * 60 * 60 * 1000)
    where.date = { gte: d, lt: next }
  }

  const records = await prismaUnfiltered.attendanceRecord.findMany({
    where,
    include: {
      user: {
        select: {
          id: true,
          email: true,
          profile: { select: { firstName: true, lastName: true } },
          studentProfile: { select: { studentId: true } },
        },
      },
    },
    orderBy: { user: { profile: { firstName: 'asc' } } },
  })

  // Get the class with its courseId to pull enrolled students
  const classData = await prismaUnfiltered.class.findUnique({
    where: { id: classId },
    select: { id: true, name: true, courseId: true },
  })

  // Get course enrollments as class roster
  const enrollments = classData
    ? await prismaUnfiltered.enrollment.findMany({
        where: { courseId: classData.courseId, status: { in: ['ENROLLED', 'ACTIVE', 'APPROVED'] } },
        select: {
          user: {
            select: {
              id: true,
              email: true,
              profile: { select: { firstName: true, lastName: true } },
              studentProfile: { select: { studentId: true } },
            },
          },
        },
      })
    : []

  // Attendance stats
  const totalRecords = records.length
  const present = records.filter((r) => r.status === 'PRESENT' || r.status === 'LATE').length
  const rate = totalRecords > 0 ? Math.round((present / totalRecords) * 100) : 0

  return apiSuccess({
    records,
    roster: enrollments.map((e: any) => e.user),
    className: classData?.name,
    stats: { total: totalRecords, present, rate },
  })
})

// POST — batch submit attendance
export const POST = withErrorHandler(async (req: NextRequest, _ctx: any) => {
  const staff = await requireStaff()
  const body = await req.json()
  const parsed = batchSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input')

  const { classId, date, records } = parsed.data
  const dateObj = new Date(date)

  // Validate: check total instructional hours for the day (6h max)
  const sessionsToday = await prismaUnfiltered.classSession.findMany({
    where: {
      classId,
      date: {
        gte: new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate()),
        lt: new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate() + 1),
      },
    },
  })

  const totalHoursToday = sessionsToday.reduce((s, sess) => s + sess.instructionalHours, 0)
  if (totalHoursToday > 6) {
    console.warn(
      `[Attendance] Day total ${totalHoursToday}h exceeds 6h limit for class ${classId} on ${date}`
    )
  }

  // Upsert attendance records
  const results = await prismaUnfiltered.$transaction(
    records.map((r) =>
      prismaUnfiltered.attendanceRecord.upsert({
        where: {
          classId_userId_date: {
            classId,
            userId: r.userId,
            date: dateObj,
          },
        },
        update: {
          status: r.status,
          minutesLate: r.minutesLate || null,
          notes: r.notes || null,
          recordedBy: staff.id,
        },
        create: {
          classId,
          userId: r.userId,
          date: dateObj,
          status: r.status,
          minutesLate: r.minutesLate || null,
          notes: r.notes || null,
          recordedBy: staff.id,
        },
      })
    )
  )

  return apiSuccess({ saved: results.length })
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'

/**
 * GET /api/staff/attendance/summary?userId=xxx
 * Returns per-module and overall attendance % for a student.
 * Also returns cumulative training hours toward 2,400h target.
 */
export const GET = withErrorHandler(async (req: NextRequest, _ctx: any) => {
  await requireStaff()
  const url = new URL(req.url)
  const userId = url.searchParams.get('userId')
  if (!userId) return apiError('userId is required')

  // All attendance records for this user
  const records = await prismaUnfiltered.attendanceRecord.findMany({
    where: { userId },
    include: {
      class: { select: { id: true, name: true, courseId: true } },
    },
  })

  // Group by class
  const byClass: Record<string, { className: string; total: number; present: number; courseId: string }> = {}
  for (const r of records) {
    if (!byClass[r.classId]) {
      byClass[r.classId] = { className: r.class.name, total: 0, present: 0, courseId: r.class.courseId }
    }
    byClass[r.classId].total++
    if (r.status === 'PRESENT' || r.status === 'LATE') {
      byClass[r.classId].present++
    }
  }

  const classSummaries = Object.entries(byClass).map(([classId, data]) => ({
    classId,
    className: data.className,
    courseId: data.courseId,
    total: data.total,
    present: data.present,
    rate: data.total > 0 ? Math.round((data.present / data.total) * 100) : 0,
    belowThreshold: data.total > 0 ? (data.present / data.total) * 100 < 90 : false,
  }))

  // Overall
  const totalRecords = records.length
  const totalPresent = records.filter(r => r.status === 'PRESENT' || r.status === 'LATE').length
  const overallRate = totalRecords > 0 ? Math.round((totalPresent / totalRecords) * 100) : 0

  // Cumulative training hours (from ClassSessions the student has attended)
  const attendedClassIds = [...new Set(records.filter(r => r.status === 'PRESENT' || r.status === 'LATE').map(r => r.classId))]
  const sessions = attendedClassIds.length > 0
    ? await prismaUnfiltered.classSession.findMany({
        where: { classId: { in: attendedClassIds } },
        select: { instructionalHours: true },
      })
    : []

  const totalTrainingHours = Math.round(sessions.reduce((s, sess) => s + sess.instructionalHours, 0) * 10) / 10
  const TARGET_HOURS = 2400

  return apiSuccess({
    classSummaries,
    overall: { total: totalRecords, present: totalPresent, rate: overallRate },
    trainingHours: { completed: totalTrainingHours, target: TARGET_HOURS, percent: Math.round((totalTrainingHours / TARGET_HOURS) * 100) },
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered as prisma } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { z } from 'zod'

const batchSchema = z.object({
  cohortId: z.string().cuid(),
})

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const { id } = await params
    const json = await req.json()
    const result = batchSchema.safeParse(json)

    if (!result.success) {
      return NextResponse.json({ error: 'Invalid cohort selected' }, { status: 400 })
    }

    // Get class details
    const cls = await prisma.class.findUnique({
      where: { id },
    })

    if (!cls) {
      return NextResponse.json({ error: 'Class not found' }, { status: 404 })
    }

    // Get students in the cohort who are ACTIVE
    const students = await prisma.studentProfile.findMany({
      where: {
        academicYearId: result.data.cohortId,
        user: { status: 'ACTIVE' },
      },
      select: { userId: true },
    })

    if (students.length === 0) {
      return NextResponse.json(
        { error: 'No active students found in this cohort' },
        { status: 400 }
      )
    }

    // Get currently enrolled students
    const existingRecords = await prisma.attendanceRecord.findMany({
      where: { classId: id },
      distinct: ['userId'],
      select: { userId: true },
    })

    const existingIds = new Set(existingRecords.map((r) => r.userId))

    // Filter to only new students
    const newStudents = students.filter((s) => !existingIds.has(s.userId))

    if (newStudents.length === 0) {
      return NextResponse.json(
        { error: 'All students in this cohort are already enrolled' },
        { status: 400 }
      )
    }

    // Capacity check
    const currentOccupancy = existingIds.size
    const projectedOccupancy = currentOccupancy + newStudents.length

    if (projectedOccupancy > cls.maxStudents) {
      return NextResponse.json(
        {
          error: `Cannot enroll cohort. Adding ${newStudents.length} students would exceed class capacity of ${cls.maxStudents} (currently at ${currentOccupancy}).`,
        },
        { status: 400 }
      )
    }

    // Enroll students (create an initial attendance record or enrollment mapping)
    // Here we use attendance records as a proxy for roster membership
    // as per existing schema structure for classes.
    const recordsToCreate = newStudents.map((student) => ({
      classId: id,
      userId: student.userId,
      date: new Date(),
      status: 'RECORDED' as const,
      notes: 'Batch Enrolled',
    }))

    await prisma.attendanceRecord.createMany({
      data: recordsToCreate,
      skipDuplicates: true,
    })

    // Update currentStudents count
    await prisma.class.update({
      where: { id },
      data: { currentStudents: projectedOccupancy },
    })

    return NextResponse.json({ success: true, addedCount: newStudents.length })
  } catch (error: any) {
    console.error('[BATCH_ENROLL]', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
