import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiPaginated, withErrorHandler, parsePagination, parseSearch } from '@/lib/api/response'
import { buildOrderBy } from '@/lib/utils/build-order-by'

const ALLOWED_SORT_KEYS = {
  student: 'user.profile.lastName',
  course: 'course.name',
  status: 'status',
  enrolledAt: 'enrolledAt',
  amount: 'amountPaid',
} as const
type SortKey = keyof typeof ALLOWED_SORT_KEYS

// GET /api/staff/enrollments
export const GET = withErrorHandler(async (req: NextRequest) => {
  await requireStaff()
  const { searchParams } = new URL(req.url)
  const { page, limit, skip } = parsePagination(searchParams)
  const search = parseSearch(searchParams)
  const statusFilter = searchParams.get('status')
  const orderBy = buildOrderBy<SortKey>(
    { sort: searchParams.get('sort'), order: searchParams.get('order') },
    ALLOWED_SORT_KEYS,
    { createdAt: 'desc' }
  )

  const where: any = {}
  if (statusFilter) where.status = statusFilter
  if (search) {
    where.OR = [
      { user: { profile: { firstName: { contains: search, mode: 'insensitive' } } } },
      { user: { profile: { lastName: { contains: search, mode: 'insensitive' } } } },
      { course: { code: { contains: search, mode: 'insensitive' } } },
      { course: { name: { contains: search, mode: 'insensitive' } } },
    ]
  }

  const [enrollments, total] = await Promise.all([
    prismaUnfiltered.enrollment.findMany({
      where,
      include: {
        user: { include: { profile: { select: { firstName: true, lastName: true } }, studentProfile: { select: { studentId: true } } } },
        course: { select: { code: true, name: true, price: true } },
      },
      orderBy,
      skip,
      take: limit,
    }),
    prismaUnfiltered.enrollment.count({ where }),
  ])

  return apiPaginated(enrollments, total, page, limit)
})

import { NextRequest, NextResponse } from 'next/server'
import { ExamAttendanceStatus } from '@prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { revalidatePath } from 'next/cache'
import { createAuditLog } from '@/lib/audit/logger'
import { markExamAttendance } from '@/lib/exams/attendance'

export async function POST(req: NextRequest) {
  try {
    const staff = await requireStaff()
    const body = await req.json()
    const membershipId = typeof body.membershipId === 'string' ? body.membershipId : undefined
    const bookingId = typeof body.bookingId === 'string' ? body.bookingId : undefined
    const sittingId = typeof body.sittingId === 'string' ? body.sittingId : undefined
    const notes = typeof body.notes === 'string' ? body.notes : undefined
    const status = body.status as ExamAttendanceStatus

    if (!Object.values(ExamAttendanceStatus).includes(status)) {
      return NextResponse.json({ error: 'Invalid attendance status' }, { status: 400 })
    }

    const result = await markExamAttendance({
      membershipId,
      bookingId,
      sittingId,
      status,
      notes,
      recordedBy: staff.id,
    })

    await createAuditLog({
      action: 'UPDATE',
      entity: 'ExamAttendance',
      entityId: result.attendance.id,
      userId: staff.id,
      details: {
        bookingId: result.bookingId,
        membershipId: result.membershipId,
        sittingId: result.sittingId,
        status,
      },
    })

    revalidatePath('/staff/exams')
    revalidatePath('/student/exams')
    if (result.poolId) revalidatePath(`/staff/exams/pools/${result.poolId}`)
    if (result.eventId) revalidatePath(`/staff/exams/events/${result.eventId}`)
    if (result.userId) {
      revalidatePath(`/staff/students/${result.userId}`)
      revalidatePath(`/staff/users/${result.userId}`)
    }

    return NextResponse.json({ success: true, attendance: result.attendance })
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error?.message || 'Failed to mark exam attendance' },
      { status: 500 }
    )
  }
}

