import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { decrementPoolMemberCount } from '@/lib/pools/operations'
import { releaseFunds, creditToWallet } from '@/lib/wallet/operations'

// DELETE /api/staff/exam-pools/[id]/members/[memberId] — Remove a member from a pool
export const DELETE = withErrorHandler(
  async (req: NextRequest, ctx?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const poolId = ctx?.params?.id
    const memberId = ctx?.params?.memberId

    const { reason } = await req.json()
    if (!reason || reason.trim().length < 5) {
      return apiError('A valid withdrawal reason (at least 5 characters) is required.')
    }

    const result = await prismaUnfiltered.$transaction(
      async (tx) => {
        const membership = await tx.poolMembership.findUnique({
          where: { id: memberId },
          include: {
            user: { select: { id: true, email: true, profile: { select: { firstName: true } } } },
            pool: { select: { name: true } },
          },
        })

        if (!membership) throw new Error('NOT_FOUND')
        if (membership.poolId !== poolId) throw new Error('NOT_FOUND')

        if (!['RESERVED', 'CONFIRMED'].includes(membership.status)) {
          throw new Error(`Cannot remove member with status ${membership.status}`)
        }

        let refundAmount = 0
        let refundType: 'RELEASE' | 'CREDIT' = 'RELEASE'

        if (membership.status === 'RESERVED') {
          refundAmount = Number(membership.amountReserved) || 0
          if (refundAmount > 0) {
            await releaseFunds(
              tx,
              membership.userId,
              refundAmount,
              `Removed from pool by staff: ${membership.pool.name}. Reason: ${reason}`,
              poolId,
              'STAFF_REMOVAL'
            )
          }
        } else if (membership.status === 'CONFIRMED') {
          // Wallet credit for confirmed members (no bank refund)
          refundAmount = Number(membership.amountPaid) || Number(membership.amountReserved) || 0
          refundType = 'CREDIT'
          if (refundAmount > 0) {
            await creditToWallet(
              tx,
              membership.userId,
              refundAmount,
              `Removed from pool by staff: ${membership.pool.name}. Reason: ${reason}`,
              poolId,
              'STAFF_REMOVAL'
            )
          }
        }

        // Cancel membership
        await tx.poolMembership.update({
          where: { id: memberId },
          data: { status: 'CANCELLED' },
        })

        // Lock pool row and decrement count
        await tx.$executeRawUnsafe(`SELECT id FROM exam_pools WHERE id = $1 FOR UPDATE`, poolId)
        await decrementPoolMemberCount(poolId, tx)

        // Notify the student
        await tx.notification.create({
          data: {
            userId: membership.userId,
            title: 'Removed from Exam Pool',
            message:
              refundAmount > 0
                ? `You have been removed from "${membership.pool.name}". €${refundAmount.toFixed(2)} has been ${refundType === 'CREDIT' ? 'credited to' : 'released to'} your wallet. Reason: ${reason}`
                : `You have been removed from "${membership.pool.name}". Reason: ${reason}`,
            type: 'POOL_UPDATE',
            linkUrl: '/student/exam-bookings',
            linkText: 'View Bookings',
          },
        })

        return {
          userId: membership.userId,
          refundAmount,
          refundType,
          poolName: membership.pool.name,
        }
      },
      { isolationLevel: Prisma.TransactionIsolationLevel.Serializable }
    )

    await createAuditLog({
      action: AuditAction.DELETE,
      entity: 'PoolMembership',
      entityId: memberId,
      userId: staff.id,
      description: `Removed member from pool "${result.poolName}" - Refund: €${result.refundAmount.toFixed(2)} (${result.refundType}). Reason: ${reason}`,
      details: {
        poolId,
        removedUserId: result.userId,
        amountRefunded: result.refundAmount,
        refundType: result.refundType,
        reason,
      },
    })

    return apiSuccess({
      message: 'Member removed',
      amountRefunded: result.refundAmount,
      refundType: result.refundType,
    })
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { SessionType, SittingStatus, Prisma } from '@prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { revalidatePath } from 'next/cache'

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(_req: NextRequest, { params }: RouteContext) {
  try {
    await requireStaff()
    const { id } = await params

    const sitting = await prismaUnfiltered.examSitting.findUnique({
      where: { id },
      include: {
        examComponent: { include: { course: true } },
        examiner: { include: { user: { select: { name: true, email: true } } } },
        assignments: {
          where: { status: { notIn: ['CANCELLED'] } },
          include: {
            user: { select: { id: true, name: true, email: true } },
            booking: {
              select: {
                id: true,
                moduleCode: true,
                bookingType: true,
                guaranteedSeat: true,
                demandStatus: true,
              },
            },
          },
          orderBy: { assignedAt: 'asc' },
        },
      },
    })

    if (!sitting) {
      return NextResponse.json({ error: 'Sitting not found' }, { status: 404 })
    }

    return NextResponse.json({ sitting })
  } catch (error: any) {
    return NextResponse.json(
      { error: error?.message || 'Failed to fetch sitting' },
      { status: 500 }
    )
  }
}

export async function PATCH(req: NextRequest, { params }: RouteContext) {
  try {
    const staff = await requireStaff()
    const { id } = await params
    const body = await req.json()

    const sitting = await prismaUnfiltered.examSitting.findUnique({
      where: { id },
      select: { id: true, eventId: true, dayNumber: true, sessionType: true, status: true },
    })

    if (!sitting) {
      return NextResponse.json({ error: 'Sitting not found' }, { status: 404 })
    }

    // Build update payload from whitelisted fields only
    const data: Record<string, unknown> = {}

    if (typeof body.dayNumber === 'number' && body.dayNumber >= 1) {
      data.dayNumber = body.dayNumber
    }
    if (
      typeof body.sessionType === 'string' &&
      Object.values(SessionType).includes(body.sessionType as SessionType)
    ) {
      data.sessionType = body.sessionType as SessionType
    }
    if (typeof body.capacity === 'number' && body.capacity >= 1) {
      data.capacity = body.capacity
    }
    if (typeof body.venue === 'string') {
      data.venue = body.venue.trim() || null
    }
    if (typeof body.notes === 'string') {
      data.notes = body.notes.trim() || null
    }
    if (
      typeof body.status === 'string' &&
      Object.values(SittingStatus).includes(body.status as SittingStatus)
    ) {
      data.status = body.status as SittingStatus
    }
    if (body.startTime) {
      const parsed = new Date(body.startTime)
      if (!isNaN(parsed.getTime())) data.startTime = parsed
    }
    if (body.endTime) {
      const parsed = new Date(body.endTime)
      if (!isNaN(parsed.getTime())) data.endTime = parsed
    }
    if (typeof body.examinerId === 'string') {
      data.examinerId = body.examinerId || null
    }

    if (Object.keys(data).length === 0) {
      return NextResponse.json({ error: 'No valid fields to update' }, { status: 400 })
    }

    const updated = await prismaUnfiltered.examSitting.update({
      where: { id },
      data,
    })

    await createAuditLog({
      action: 'UPDATE',
      entity: 'ExamSitting',
      entityId: id,
      userId: staff.id,
      details: { changes: data as Prisma.InputJsonValue, eventId: sitting.eventId },
    })

    revalidatePath(`/staff/exams/events/${sitting.eventId}`)
    revalidatePath('/staff/exams')

    return NextResponse.json({ success: true, sitting: updated })
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error?.message || 'Failed to update sitting' },
      { status: 500 }
    )
  }
}

