import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiCreated, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'
import { getInternalBankCategoryCode, normalizeCategoryCode } from '@/lib/easa/category-selection'
import { z } from 'zod'

// GET — list all exam banks with pool health
export const GET = withErrorHandler(async (req: NextRequest) => {
  await requireStaff()
  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }
  const url = new URL(req.url)
  const courseId = url.searchParams.get('courseId')

  const where: any = {}
  if (courseId) where.courseId = courseId

  const banks = await prismaUnfiltered.internalExamBank.findMany({
    where,
    include: {
      course: { select: { id: true, name: true, code: true } },
      ruleOverride: true,
      _count: { 
        select: { 
          questions: { where: { status: 'APPROVED', isActive: true } }, 
          sessions: true 
        } 
      },
    },
    orderBy: { name: 'asc' },
  })

  const pendingCounts = await prismaUnfiltered.internalExamQuestion.groupBy({
    by: ['bankId'],
    where: { 
      bankId: { in: banks.map(b => b.id) }, 
      status: 'PENDING_APPROVAL', 
      isActive: true 
    },
    _count: true
  })
  const pendingMap = Object.fromEntries(pendingCounts.map(pc => [pc.bankId, pc._count]))

  // Compute pool health inline from _count to avoid N+1 queries
  const enriched = banks.map((bank) => {
    const questionCount = bank._count.questions
    const requiredMinimum = bank.minimumPoolSize ?? bank.mcqCount * 5
    const ratio = requiredMinimum > 0 ? questionCount / requiredMinimum : 0
    const health = ratio >= 1.0 ? 'GREEN' : ratio >= 0.6 ? 'AMBER' : 'RED'
    return {
      ...bank,
      categoryCode: getInternalBankCategoryCode(bank),
      poolHealth: { health, questionCount, requiredMinimum },
      pendingCount: pendingMap[bank.id] || 0,
    }
  })

  return apiSuccess(enriched)
})

// POST — create new exam bank
const createSchema = z.object({
  courseId: z.string(),
  name: z.string().min(1),
  description: z.string().optional(),
  moduleCode: z.string().optional(),
  categoryCode: z.string().optional(),
  mcqCount: z.number().min(5).default(40),
  ruleSet: z.enum(['EASA', 'CUSTOM']).default('EASA'),
})

export const POST = withErrorHandler(async (req: NextRequest) => {
  await requireStaff()
  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }
  const body = await req.json()
  const parsed = createSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input')

  const bank = await prismaUnfiltered.internalExamBank.create({
    data: {
      courseId: parsed.data.courseId,
      name: parsed.data.name,
      description: parsed.data.description || null,
      moduleCode: parsed.data.moduleCode || null,
      categoryCode: normalizeCategoryCode(parsed.data.categoryCode),
      mcqCount: parsed.data.mcqCount,
      ruleSet: parsed.data.ruleSet,
      minimumPoolSize: parsed.data.mcqCount * 5,
    },
  })

  return apiCreated(bank)
})

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { getCertificatesEnabled, createCertificate } from '@/lib/certificates/generator'
import { getBankRules } from '@/lib/internal-exam/engine'

const publishSchema = z.object({
  sessionIds: z.array(z.string()).min(1).max(500),
})

/**
 * POST /api/staff/exams/internal/operations/publish
 * Publishes results for one or more completed exam sessions. Once
 * published, students can see their scores in their exam records.
 * Idempotent — sessions already published are skipped silently.
 */
export const POST = withErrorHandler(async (req: NextRequest) => {
  const staff = await requireStaff()

  const body = await req.json()
  const parsed = publishSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input — provide an array of session IDs')

  const { sessionIds } = parsed.data

  // Only publish sessions that are COMPLETED or TIMED_OUT and not already
  // published. Snapshot the ids that will flip so we can audit-log them.
  const candidates = await prismaUnfiltered.internalExamSession.findMany({
    where: {
      id: { in: sessionIds },
      status: { in: ['COMPLETED', 'TIMED_OUT'] },
      isPublished: false,
    },
    select: {
      id: true,
      studentId: true,
      bankId: true,
      percentage: true,
      passed: true,
      bank: { select: { certificateEnabled: true } },
    },
  })

  if (candidates.length === 0) {
    return apiSuccess({ published: 0 })
  }

  const result = await prismaUnfiltered.internalExamSession.updateMany({
    where: { id: { in: candidates.map((c) => c.id) } },
    data: { isPublished: true },
  })

  await createAuditLog({
    userId: staff.id,
    action: 'UPDATE',
    entity: 'InternalExamSession',
    entityId: candidates.length === 1 ? candidates[0].id : `batch:${result.count}`,
    description: `Published ${result.count} internal exam result${result.count === 1 ? '' : 's'}`,
    changes: {
      sessionIds: candidates.map((c) => c.id),
      before: { isPublished: false },
      after: { isPublished: true },
    },
  })

  // Auto-generate certificates for students who passed (feature-gated).
  // Requires both the global toggle AND the per-bank certificateEnabled flag.
  const certificatesEnabled = await getCertificatesEnabled()
  let certificatesGenerated = 0
  if (certificatesEnabled) {
    const passingSessions = candidates.filter((c) => c.passed && c.bank.certificateEnabled)
    const certPromises: Promise<any>[] = []

    for (const c of passingSessions) {
      const rules = await getBankRules(c.bankId)
      const certPromise = createCertificate({
        sessionId: c.id,
        studentId: c.studentId,
        score: 0,
        percentage: c.percentage ?? 0,
        passMarkPct: rules.passMarkPct,
        issuedBy: staff.id,
      }).catch((err) => {
        console.error(`[certificates] Failed to generate certificate for session ${c.id}:`, err)
        return null
      })
      certPromises.push(certPromise)
    }

    const certResults = await Promise.allSettled(certPromises)
    certificatesGenerated = certResults.filter(
      (r) => r.status === 'fulfilled' && r.value != null
    ).length
  }

  return apiSuccess({ published: result.count, certificatesGenerated })
})

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { withErrorHandler, apiSuccess, apiError } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import {
  generateBekPair,
  buildSebConfig,
  generateSebConfig,
  BekPair,
  BankSebConfig,
} from '@/lib/internal-exam/seb-config'

// GET /api/staff/exams/internal/sessions/[id]/seb-config — return .seb config
export const GET = withErrorHandler(async (req: NextRequest) => {
  const { searchParams } = new URL(req.url)
  const sessionId = searchParams.get('sessionId')

  if (!sessionId) {
    return apiError('sessionId is required', 400)
  }

  const session = await prismaUnfiltered.internalExamSession.findUnique({
    where: { id: sessionId },
    include: {
      bank: { select: { id: true, name: true, sebConfig: true } },
      class: { select: { id: true, name: true } },
    },
  })

  if (!session) {
    return apiError('Session not found', 404)
  }

  if (!session.classId || !session.class) {
    return apiError('This session is not tied to a class schedule', 400)
  }

  const schedule = await prismaUnfiltered.internalExamClassSchedule.findFirst({
    where: { bankId: session.bankId, classId: session.classId },
  })

  if (!schedule || !schedule.sebRequired) {
    return apiError('SEB is not required for this exam schedule', 403)
  }

  const bekPair = generateBekPair()

  await prismaUnfiltered.internalExamSession.update({
    where: { id: sessionId },
    data: {
      sebKeys: bekPair as unknown as any,
    },
  })

  const examDurationSecs = session.expiresAt
    ? Math.max(0, Math.floor((session.expiresAt.getTime() - Date.now()) / 1000))
    : 0

  const bankConfig = (session.bank?.sebConfig as BankSebConfig | null) ?? null
  const startUrl = `${process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000'}/student/exams/internal/${sessionId}`

  const sebConfig = buildSebConfig({
    bekPair,
    startUrl,
    examDurationSecs,
    bankConfig,
  })

  const sebZip = generateSebConfig(sebConfig)

  const headers = new Headers()
  headers.set('Content-Type', 'application/octet-stream')
  headers.set('Content-Disposition', `attachment; filename="exam-${sessionId}.seb"`)

  await createAuditLog({
    action: AuditAction.EXAM_SESSION_STARTED,
    userId: session.studentId,
    entity: 'InternalExamSession',
    entityId: sessionId,
    description: `SEB config generated for session ${sessionId}`,
    details: {
      bankId: session.bankId,
      classId: session.classId,
      lockdownLevel: bankConfig?.lockdownLevel || 'strict',
    },
  })

  return new NextResponse(Buffer.from(sebZip), { headers, status: 200 })
})

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered as prisma } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { z } from 'zod'

const seatAssignmentSchema = z.object({
  assignments: z.array(
    z.object({
      assignmentId: z.string(),
      seatId: z.string().nullable(),
    })
  ),
})

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { id: sittingId } = await params

  try {
    const json = await req.json()
    const result = seatAssignmentSchema.safeParse(json)

    if (!result.success) {
      return NextResponse.json(
        { error: 'Invalid data', details: result.error.flatten() },
        { status: 400 }
      )
    }

    // Verify sitting exists
    const sitting = await prisma.examSitting.findUnique({
      where: { id: sittingId },
    })
    if (!sitting) {
      return NextResponse.json({ error: 'Sitting not found' }, { status: 404 })
    }

    const { assignments } = result.data

    // Batch update seat assignments
    await prisma.$transaction(
      assignments.map((a) =>
        prisma.examSittingAssignment.update({
          where: { id: a.assignmentId },
          data: { seatId: a.seatId },
        })
      )
    )

    // Return updated assignments
    const updated = await prisma.examSittingAssignment.findMany({
      where: { sittingId },
      include: {
        user: {
          include: {
            profile: { select: { firstName: true, lastName: true } },
          },
        },
        seat: true,
      },
      orderBy: { assignedAt: 'asc' },
    })

    return NextResponse.json(updated)
  } catch (error: any) {
    console.error('[SITTING_SEATS_UPDATE]', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { id: sittingId } = await params

  const sitting = await prisma.examSitting.findUnique({
    where: { id: sittingId },
    include: {
      event: { select: { id: true, name: true } },
      examComponent: { select: { id: true, code: true, name: true } },
      assignments: {
        include: {
          user: {
            include: {
              profile: { select: { firstName: true, lastName: true } },
            },
          },
          seat: true,
        },
        orderBy: { assignedAt: 'asc' },
      },
    },
  })

  if (!sitting) {
    return NextResponse.json({ error: 'Sitting not found' }, { status: 404 })
  }

  return NextResponse.json(sitting)
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth/auth-options'
import { prismaUnfiltered } from '@/lib/prisma/client'

export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
      return new NextResponse('Unauthorized', { status: 403 })
    }

    const { searchParams } = new URL(request.url)
    const type = searchParams.get('type')
    // Optional date-range filter (SEC-23). Bounded export prevents accidental
    // multi-million row dumps + matches the financial reporting period the
    // staff member is actually looking at.
    const fromParam = searchParams.get('from')
    const toParam = searchParams.get('to')
    const limitParam = searchParams.get('limit')
    const dateFilter: { gte?: Date; lte?: Date } = {}
    if (fromParam) {
      const d = new Date(fromParam)
      if (!Number.isNaN(d.getTime())) dateFilter.gte = d
    }
    if (toParam) {
      const d = new Date(toParam)
      if (!Number.isNaN(d.getTime())) dateFilter.lte = d
    }
    const takeCap = Math.min(
      Math.max(parseInt(limitParam || '10000', 10) || 10000, 1),
      50_000
    )

    let data: any[] = []
    let filename = 'export.csv'

    if (type === 'students') {
      const users = await prismaUnfiltered.user.findMany({
        where: { role: 'STUDENT' },
        include: { profile: true, studentProfile: true },
      })

      data = users.map((u) => ({
        ID: u.id,
        Name: `${u.profile?.firstName || ''} ${u.profile?.lastName || ''}`.trim(),
        Email: u.email,
        AcademyEmail: u.academyEmail || '',
        StudentId: u.studentProfile?.studentId || '',
        EnrollmentType: u.studentProfile?.enrollmentType || '',
        Pathway: u.programmeChoice || '',
        JoinedAt: u.createdAt.toISOString(),
      }))
      filename = 'students_export.csv'
    } else if (type === 'pools') {
      const pools = await prismaUnfiltered.examPool.findMany({
        include: { event: true },
      })

      data = pools.map((p) => ({
        ID: p.id,
        Name: p.name,
        Event: p.event?.name || '',
        Date: p.examDate ? p.examDate.toISOString().split('T')[0] : '',
        Status: p.status,
        CurrentCandidates: p.currentMemberCount,
        MaxCandidates: p.maxCandidates,
        Modules: p.allowedModules.join(', '),
      }))
      filename = 'exam_pools_export.csv'
    } else if (type === 'finances') {
      const txs = await prismaUnfiltered.walletTransaction.findMany({
        where: Object.keys(dateFilter).length > 0 ? { createdAt: dateFilter } : undefined,
        include: { wallet: { include: { user: { include: { profile: true } } } } },
        orderBy: { createdAt: 'desc' },
        take: takeCap,
      })

      data = txs.map((t) => ({
        ID: t.id,
        Date: t.createdAt.toISOString(),
        Student:
          `${t.wallet.user.profile?.firstName || ''} ${t.wallet.user.profile?.lastName || ''}`.trim(),
        Type: t.type,
        Reference: t.referenceType,
        Amount: t.amount,
        Description: t.description,
      }))
      filename = 'financial_transactions.csv'
    } else if (type === 'audit-logs') {
      const logs = await prismaUnfiltered.auditLog.findMany({
        where: Object.keys(dateFilter).length > 0 ? { createdAt: dateFilter } : undefined,
        include: { user: { include: { profile: true } } },
        orderBy: { createdAt: 'desc' },
        take: Math.min(takeCap, 5000),
      })

      data = logs.map((l) => ({
        Date: l.createdAt.toISOString(),
        Action: l.action,
        Entity: l.entity || '',
        EntityId: l.entityId || '',
        User: l.user?.profile
          ? `${l.user.profile.firstName || ''} ${l.user.profile.lastName || ''}`.trim()
          : l.user?.email || 'System',
        Description: l.description || '',
        IP: l.ipAddress || '',
      }))
      filename = 'audit_logs_export.csv'
    } else {
      return NextResponse.json({ error: 'Invalid export type' }, { status: 400 })
    }

    if (data.length === 0) {
      return NextResponse.json({ error: 'No data to export' }, { status: 404 })
    }

    // Convert to CSV
    const headers = Object.keys(data[0])
    const csvContent = [
      headers.join(','),
      ...data.map((row) =>
        headers
          .map((header) => {
            let val = row[header]
            if (val === null || val === undefined) val = ''
            // Escape quotes and wrap in quotes if contains comma
            val = String(val).replace(/"/g, '""')
            if (val.includes(',') || val.includes('"') || val.includes('\n')) {
              val = `"${val}"`
            }
            return val
          })
          .join(',')
      ),
    ].join('\n')

    return new NextResponse(csvContent, {
      headers: {
        'Content-Type': 'text/csv',
        'Content-Disposition': `attachment; filename="${filename}"`,
      },
    })
  } catch (error: any) {
    console.error('[CSV_EXPORT]', error)
    return NextResponse.json({ error: error.message || 'Failed to export data' }, { status: 500 })
  }
}

