import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'

export const POST = withErrorHandler(async (req: NextRequest) => {
  const staff = await requireStaff()

  let body: any
  try {
    body = await req.json()
  } catch (e) {
    return apiError('Invalid request body', 400)
  }

  const { paymentIds, notes } = body
  if (!paymentIds || !Array.isArray(paymentIds)) {
    return apiError('paymentIds array is required')
  }

  const result = await prismaUnfiltered.$transaction(async (tx) => {
    const updated = await tx.payment.updateMany({
      where: {
        id: { in: paymentIds },
        status: 'APPROVED',
        reconciled: false,
      },
      data: {
        reconciled: true,
        reconciledAt: new Date(),
        reconciledBy: staff.id,
        reconciliationNotes: notes || 'Hand-matched reconciliation',
      },
    })

    // Add audit logs for each payment? Might be excessive for bulk.
    // We'll log the bulk action.
    await createAuditLog({
      action: AuditAction.PAYMENT_RECONCILE_BULK,
      entity: 'Payment',
      userId: staff.id,
      details: {
        count: updated.count,
        paymentIds,
        notes,
      },
    })

    return updated
  })

  return apiSuccess({ message: `Reconciled ${result.count} payments`, count: result.count })
})

import { NextRequest, NextResponse } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import {
  getFinanceReportSummary,
  getRevenueByProgrammeType,
  getMonthlyRevenueData,
  getPaymentStatusBreakdown,
} from '@/lib/analytics/reports'
import { renderToStream } from '@react-pdf/renderer'
import { FinancialReportTemplate } from '@/components/pdf/templates/FinancialReportTemplate'
import { getPDFSettings } from '@/lib/pdf-settings'
import React from 'react'

function FinancialReportElement(props: any) {
  return <FinancialReportTemplate {...props} />
}

/**
 * GET /api/staff/finance/reports/export
 *
 * Generates a PDF financial report.
 * Query params: ?year=2024&month=6
 */
export async function GET(req: NextRequest) {
  try {
    await requireStaff()

    const { searchParams } = new URL(req.url)
    const yearParam = searchParams.get('year')
    const monthParam = searchParams.get('month')

    const year = yearParam ? parseInt(yearParam) : new Date().getFullYear()
    // Default to 1 (January) if no month is provided and we need a month for the template.
    // In a real app, you might adjust the template to handle yearly reports without a specific month.
    const month = monthParam ? parseInt(monthParam) : new Date().getMonth() + 1

    const [summary, revenueByType, monthlyData, paymentStatus] = await Promise.all([
      getFinanceReportSummary({ year, month }),
      getRevenueByProgrammeType({ year, month }),
      getMonthlyRevenueData({ year }),
      getPaymentStatusBreakdown({ year, month }),
    ])

    // Get PDF branding settings
    const pdfSettings = await getPDFSettings(req.nextUrl.origin)

    const stream = await renderToStream(
      FinancialReportElement({
        year,
        month,
        summary: {
          totalRevenue: summary.totalRevenue,
          revenueThisMonth: summary.revenueThisMonth,
          pendingAmount: summary.pendingAmount,
          avgTransactionValue: summary.avgTransactionValue,
        },
        monthlyData: monthlyData,
        revenueByType: revenueByType,
        paymentStatus: paymentStatus,
        logoUrl: pdfSettings.logoUrl,
        watermarkUrl: pdfSettings.watermarkUrl,
        watermarkOpacity: pdfSettings.watermarkOpacity,
      })
    )

    return new NextResponse(stream as any, {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `inline; filename="financial-report-${year}-${month}.pdf"`,
      },
    })
  } catch (error) {
    console.error('[FINANCE_REPORT_EXPORT]', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { serializePrisma } from '@/lib/utils/serialization'

/**
 * GET /api/staff/finance/transactions
 *
 * Paginated wallet transactions endpoint for the finance transactions tab.
 */
export async function GET(req: NextRequest) {
  try {
    await requireStaff()

    const { searchParams } = new URL(req.url)
    const page = parseInt(searchParams.get('page') || '1')
    const limit = parseInt(searchParams.get('limit') || '25')
    const query = searchParams.get('query') || ''
    const sortBy = searchParams.get('sortBy') || 'createdAt'
    const sortDir = (searchParams.get('sortDir') || 'desc') as 'asc' | 'desc'

    const skip = (page - 1) * limit

    // Build where filter
    const where = query
      ? {
          OR: [
            {
              wallet: {
                user: {
                  OR: [
                    { email: { contains: query, mode: 'insensitive' as const } },
                    { profile: { firstName: { contains: query, mode: 'insensitive' as const } } },
                    { profile: { lastName: { contains: query, mode: 'insensitive' as const } } },
                  ],
                },
              },
            },
            { referenceId: { contains: query, mode: 'insensitive' as const } },
            { referenceType: { contains: query, mode: 'insensitive' as const } },
          ],
        }
      : undefined

    // Build orderBy
    const orderBy: any = {}
    if (['createdAt', 'amount', 'type'].includes(sortBy)) {
      orderBy[sortBy] = sortDir
    } else {
      orderBy.createdAt = 'desc'
    }

    const [transactions, total] = await Promise.all([
      prismaUnfiltered.walletTransaction.findMany({
        where,
        orderBy,
        include: { wallet: { include: { user: { include: { profile: true } } } } },
        skip,
        take: limit,
      }),
      prismaUnfiltered.walletTransaction.count({ where }),
    ])

    const serialized = serializePrisma(transactions)
    const transactionIds = serialized.map((tx: any) => tx.id)

    const paymentIds = serialized
      .filter((tx: any) => tx.referenceType === 'PAYMENT_ID' && tx.referenceId)
      .map((tx: any) => tx.referenceId!)
    const examBookingReferenceIds = serialized
      .filter((tx: any) => tx.referenceType === 'EXAM_BOOKING' && tx.referenceId)
      .map((tx: any) => tx.referenceId!)
    const fullTimeEnrollmentIds = serialized
      .filter((tx: any) => tx.referenceType === 'FULL_TIME_ENROLLMENT' && tx.referenceId)
      .map((tx: any) => tx.referenceId!)

    // Fetch related data in parallel
    const [relatedPayments, relatedExamBookings, relatedFullTimeEnrollments, relatedModularEnrollments, relatedMilestones] =
      await Promise.all([
        paymentIds.length > 0
          ? prismaUnfiltered.payment.findMany({
              where: { id: { in: paymentIds } },
              select: { id: true, reconciled: true, paymentCurrency: true, originalAmount: true, status: true },
            })
          : Promise.resolve([]),
        transactionIds.length > 0 || examBookingReferenceIds.length > 0
          ? prismaUnfiltered.examBooking.findMany({
              where: {
                OR: [
                  { id: { in: examBookingReferenceIds } },
                  { walletTxnId: { in: transactionIds } },
                ],
              },
              select: { id: true, walletTxnId: true, status: true, demandStatus: true, result: true, moduleCode: true },
            })
          : Promise.resolve([]),
        fullTimeEnrollmentIds.length > 0
          ? prismaUnfiltered.fullTimeEnrollment.findMany({
              where: { id: { in: fullTimeEnrollmentIds } },
              select: { id: true, status: true },
            })
          : Promise.resolve([]),
        transactionIds.length > 0
          ? prismaUnfiltered.modularEnrollment.findMany({
              where: { walletTxnId: { in: transactionIds } },
              select: { id: true, walletTxnId: true, status: true },
            })
          : Promise.resolve([]),
        transactionIds.length > 0
          ? prismaUnfiltered.paymentMilestone.findMany({
              where: { walletTxnId: { in: transactionIds } },
              select: { id: true, walletTxnId: true, milestoneType: true, status: true },
            })
          : Promise.resolve([]),
      ])

    return NextResponse.json({
      data: serialized,
      meta: { total, page, limit },
      related: {
        payments: serializePrisma(relatedPayments),
        examBookings: serializePrisma(relatedExamBookings),
        fullTimeEnrollments: serializePrisma(relatedFullTimeEnrollments),
        modularEnrollments: serializePrisma(relatedModularEnrollments),
        milestones: serializePrisma(relatedMilestones),
      },
    })
  } catch (error) {
    console.error('[FINANCE_TRANSACTIONS_API]', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requirePermission, PERMISSIONS } from '@/lib/auth/permissions'
import { createAuditLog } from '@/lib/audit/logger'
import { getOrCreateWallet, topUpWallet } from '@/lib/wallet/operations'
import { convertCurrency } from '@/lib/currency-api'

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const staff = await requirePermission(PERMISSIONS.APPROVE_PAYMENTS)
    const { id } = await params

    const payment = await prismaUnfiltered.payment.findUnique({
      where: { id },
    })

    if (!payment) {
      return NextResponse.json({ error: 'Payment record not found' }, { status: 404 })
    }

    if (payment.status !== 'PENDING') {
      return NextResponse.json({ error: 'Top-up request is not pending' }, { status: 400 })
    }

    if (payment.referenceType !== 'WALLET_TOPUP') {
      return NextResponse.json({ error: 'Payment is not a wallet top-up request' }, { status: 400 })
    }

    // Ensure wallet exists before tx
    await getOrCreateWallet(payment.userId)

    // Use paymentCurrency and originalAmount if available (standardized fields)
    const paymentCurrency = payment.paymentCurrency || (payment.currency !== 'EUR' ? payment.currency : 'EUR')
    const originalAmount = payment.originalAmount ? Number(payment.originalAmount) : Number(payment.amount)
    
    let eurAmount = Number(payment.amount) // Default to stored indicative amount
    let conversionNote = ''

    if (paymentCurrency !== 'EUR') {
      try {
        const { convertedAmount, rate } = await convertCurrency(
          originalAmount,
          paymentCurrency,
          'EUR'
        )
        eurAmount = convertedAmount
        conversionNote = ` (converted from ${paymentCurrency} ${originalAmount} at rate ${rate.toFixed(4)})`
      } catch (err) {
        console.error('Conversion failed during approval:', err)
        // Fallback to indicative amount if live conversion fails
        conversionNote = ` (using indicative amount; live conversion failed)`
      }
    }

    // Process atomically
    await prismaUnfiltered.$transaction(async (tx) => {
      // Update payment status
      await tx.payment.update({
        where: { id },
        data: {
          status: 'APPROVED',
          approvedAt: new Date(),
          approvedBy: staff.id,
        },
      })

      // Top up wallet in EUR
      await topUpWallet(
        tx,
        payment.userId,
        eurAmount,
        `Wallet top-up approved by admin${conversionNote}`,
        payment.id,
        'PAYMENT_ID'
      )

      await tx.notification.create({
        data: {
          userId: payment.userId,
          title: 'Wallet Top-Up Approved',
          message: paymentCurrency !== 'EUR'
            ? `Your ${paymentCurrency} ${payment.amount} top-up has been approved and credited as EUR ${eurAmount.toFixed(2)}.`
            : `Your wallet top-up of EUR ${payment.amount} has been approved.`,
          type: 'SUCCESS',
          linkUrl: '/student/wallet',
          linkText: 'View Wallet',
        },
      })
    })

    // Qualify any pending referral for this user (non-blocking)
    import('@/lib/referral/operations')
      .then(({ qualifyReferral }) => qualifyReferral(payment.userId))
      .catch(console.error)

    await createAuditLog({
      action: 'SYSTEM_UPDATE',
      entity: 'payments',
      entityId: id,
      userId: staff.id,
      description: `Approved wallet top-up of ${payment.amount} for user ID ${payment.userId}`,
    })

    return NextResponse.json({ success: true })
  } catch (error: any) {
    console.error('Approve top-up err:', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requirePermission, PERMISSIONS } from '@/lib/auth/permissions'
import { createAuditLog } from '@/lib/audit/logger'

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const staff = await requirePermission(PERMISSIONS.APPROVE_PAYMENTS)
    const { id } = await params
    const { reason } = await req.json()

    if (!reason) {
      return NextResponse.json({ error: 'Rejection reason is required' }, { status: 400 })
    }

    const payment = await prismaUnfiltered.payment.findUnique({
      where: { id },
    })

    if (!payment || payment.status !== 'PENDING' || payment.referenceType !== 'WALLET_TOPUP') {
      return NextResponse.json(
        { error: 'Invalid or already processed top-up request' },
        { status: 400 }
      )
    }

    await prismaUnfiltered.payment.update({
      where: { id },
      data: {
        status: 'REJECTED',
        rejectedAt: new Date(),
        rejectedBy: staff.id,
        rejectionReason: reason,
      },
    })

    await createAuditLog({
      action: 'SYSTEM_UPDATE',
      entity: 'payments',
      entityId: id,
      userId: staff.id,
      description: `Rejected wallet top-up of ${payment.amount} for user ID ${payment.userId}. Reason: ${reason}`,
    })

    return NextResponse.json({ success: true })
  } catch (error: any) {
    console.error('Reject top-up err:', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { withErrorHandler, apiCreated, apiPaginated } from '@/lib/api/response'
import { requirePermission } from '@/lib/auth/permissions'
import { ADDITIONAL_PERMISSION_KEYS } from '@/lib/auth/permission-registry'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'

const createSchema = z.object({
  userId: z.string(),
  requestType: z.enum(['ACCESS', 'ERASURE', 'RECTIFICATION', 'RESTRICTION', 'PORTABILITY', 'OBJECTION']),
  notes: z.string().max(500).optional(),
})

export const GET = withErrorHandler(async (req: NextRequest) => {
  await requirePermission(ADDITIONAL_PERMISSION_KEYS.MANAGE_GDPR)
  const url = new URL(req.url)
  const limit = Math.min(parseInt(url.searchParams.get('limit') || '50', 10), 200)
  const page = Math.max(1, parseInt(url.searchParams.get('page') || '1', 10))
  const skip = (page - 1) * limit
  const status = url.searchParams.get('status') || undefined

  const where = status ? { status: status as any } : {}
  const [rows, total] = await Promise.all([
    prismaUnfiltered.dataSubjectRequest.findMany({
      where,
      orderBy: [{ status: 'asc' }, { dueBy: 'asc' }],
      take: limit,
      skip,
      include: {
        user: { select: { id: true, email: true, profile: { select: { firstName: true, lastName: true } } } },
        assignedTo: { select: { id: true, email: true } },
      },
    }),
    prismaUnfiltered.dataSubjectRequest.count({ where }),
  ])
  return apiPaginated(rows, total, page, limit)
})

export const POST = withErrorHandler(async (req: NextRequest) => {
  const actor = await requirePermission(ADDITIONAL_PERMISSION_KEYS.MANAGE_GDPR)
  const body = createSchema.parse(await req.json())
  const dueBy = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // 30 days per GDPR Art. 12(3)

  const created = await prismaUnfiltered.dataSubjectRequest.create({
    data: { ...body, dueBy },
  })
  await createAuditLog({
    userId: actor.id,
    action: 'CREATE',
    entity: 'DataSubjectRequest',
    entityId: created.id,
    description: `${body.requestType} request opened for user ${body.userId}`,
    changes: { after: created },
  })
  return apiCreated(created)
})

