// POST — create an OJT logbook for a student
const createSchema = z.object({
  studentProfileId: z.string(),
  licenceCategory: z.string(),
  facilityName: z.string(),
  facilityApprovalNo: z.string().optional(),
  startDate: z.string(),
  targetEndDate: z.string().optional(),
  mentorId: z.string().optional(),
})

export const POST = withErrorHandler(async (req: NextRequest, _ctx?: RouteContext) => {
  await requireStaff()
  const body = await req.json()
  const parsed = createSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input')

  // Ensure student doesn't already have a logbook
  const existing = await prismaUnfiltered.oJTLogbook.findUnique({
    where: { studentProfileId: parsed.data.studentProfileId },
  })
  if (existing) return apiError('Student already has an OJT logbook', 409)

  const logbook = await prismaUnfiltered.$transaction(async (tx) => {
    const lb = await tx.oJTLogbook.create({
      data: {
        studentProfileId: parsed.data.studentProfileId,
        licenceCategory: parsed.data.licenceCategory,
        facilityName: parsed.data.facilityName,
        facilityApprovalNo: parsed.data.facilityApprovalNo || null,
        startDate: new Date(parsed.data.startDate),
        targetEndDate: parsed.data.targetEndDate ? new Date(parsed.data.targetEndDate) : null,
      },
    })

    // Assign primary mentor if provided
    if (parsed.data.mentorId) {
      await tx.oJTMentorAssignment.create({
        data: {
          logbookId: lb.id,
          mentorId: parsed.data.mentorId,
          assignedDate: new Date(),
          isPrimary: true,
        },
      })
    }

    return lb
  })

  return apiCreated(logbook)
})

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { requirePermission, PERMISSIONS } from '@/lib/auth/permissions'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import {
  sendPaymentApprovedEmail,
  sendPaymentRejectedEmail,
  sendSeatReservationConfirmedEmail,
  sendActivationEmail,
} from '@/lib/email/service'
import { trackPayment } from '@/lib/analytics/events'
import {
  hashPassword,
  generateToken,
  generateTempPassword,
  generateAcademyEmail,
} from '@/lib/auth/helpers'
import { PaymentStatus, ProgrammeChoice } from '@prisma/client'
import { topUpWallet } from '@/lib/wallet/operations'
import { shouldPromoteOnPayment, promoteApplicantToStudent } from '@/lib/enrollment/pathway'
import { generateMilestonesForYear } from '@/lib/enrollment/full-time'
import { formatPaymentType } from '@/lib/utils/string'

/** Maps ProgrammeChoice enum to FullTimeProgramme.code */
const PROGRAMME_CODE_MAP: Record<string, string> = {
  FULL_TIME_4YEAR: 'FT_4Y_B1B2',
  FULL_TIME_2YEAR: 'FT_2Y_B1',
  MILITARY_1YEAR: 'MIL_1Y_B1',
}

// POST /api/staff/payments/[id]/approve — Approve or reject a payment
export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requirePermission(PERMISSIONS.APPROVE_PAYMENTS)
    const id = context?.params?.id

    if (!id) return apiError('Payment ID required')

    let body: any
    try {
      body = await req.json()
    } catch (e) {
      return apiError('Invalid request body', 400)
    }

    const { action, notes, reason } = body
    if (!['approve', 'reject'].includes(action)) {
      return apiError('Action must be "approve" or "reject"')
    }

    const payment = await prismaUnfiltered.payment.findUnique({
      where: { id },
      include: { user: { include: { profile: true } } },
    })

    if (!payment) return apiNotFound('Payment not found')
    if (payment.status !== 'PENDING') return apiError(`Payment is already ${payment.status}`)

    if (action === 'approve') {
      await prismaUnfiltered.payment.update({
        where: { id },
        data: {
          status: PaymentStatus.APPROVED,
          approvedBy: staff.id,
          approvedAt: new Date(),
          notes,
        },
      })

      // Handle Wallet Top-up
      if (payment.referenceType === 'WALLET_TOPUP') {
        const topUpReference = payment.referenceCode || `PAY-${payment.id.slice(-6)}`
        await prismaUnfiltered.$transaction(async (tx) => {
          // If Wallet doesn't exist yet (APPLICANT topping up for the first time), create it
          let wallet = await tx.wallet.findUnique({ where: { userId: payment.userId } })
          if (!wallet) {
            wallet = await tx.wallet.create({
              data: {
                userId: payment.userId,
                balance: 0,
                reservedBalance: 0,
                availableBalance: 0,
              },
            })
          }

          await topUpWallet(
            tx,
            payment.userId,
            Number(payment.amount),
            `Wallet top-up approved (Ref: ${topUpReference})`,
            payment.id,
            'PAYMENT_ID'
          )
        })
      }

      // Handle Course Enrollment (Modular)
      if (payment.referenceType === 'COURSE' && payment.referenceId) {
        const courseEnrollment = await prismaUnfiltered.enrollment.findFirst({
          where: { userId: payment.userId, courseId: payment.referenceId },
        })
        if (courseEnrollment) {
          await prismaUnfiltered.enrollment.update({
            where: { id: courseEnrollment.id },
            data: {
              status: 'ENROLLED',
              approvedAt: new Date(),
              amountPaid: payment.amount,
            },
          })
        }
      }

      // Handle Full-Time enrollment creation + milestone tracking on seat-related payments
      const isFTPayment = [
        'SEAT_CONFIRMATION',
        'CUSTOM_PART_PAYMENT',
        'YEAR_1_FULL',
        'FULL_PROGRAMME',
      ].includes(payment.referenceType || '')
      const isFTApplicant =
        payment.user.role === 'APPLICANT' &&
        payment.user.status === 'ACTIVE' &&
        payment.user.programmeChoice &&
        PROGRAMME_CODE_MAP[payment.user.programmeChoice]

      if (isFTPayment && isFTApplicant) {
        const programmeCode = PROGRAMME_CODE_MAP[payment.user.programmeChoice!]
        const programme = await prismaUnfiltered.fullTimeProgramme.findUnique({
          where: { code: programmeCode },
          include: { programmeYears: { where: { yearNumber: 1 } } },
        })

        if (programme && programme.programmeYears.length > 0) {
          const programmeCode = programme.code

          // Validate pathway restriction
          const { allowed, error, severity } = await import('@/lib/enrollment/validation').then(
            (v) => v.validateFullTimeProgrammeEnrollment(payment.userId, programmeCode)
          )

          const force = body.ignorePathwayRestrictions === true

          if (!allowed && !force) {
            console.error(`Enrollment blocked: ${error}`)
            return apiError(error || 'Student is not eligible for this programme.', 400, {
              needsOverride: severity === 'WARNING',
              warning: error,
            })
          }

          const year1 = programme.programmeYears[0]

          // Create FullTimeEnrollment if it doesn't exist yet
          let enrollment = await prismaUnfiltered.fullTimeEnrollment.findFirst({
            where: { studentId: payment.userId, programmeId: programme.id },
          })

          if (!enrollment) {
            enrollment = await prismaUnfiltered.fullTimeEnrollment.create({
              data: {
                studentId: payment.userId,
                programmeId: programme.id,
                programmeYearId: year1.id,
                status: 'PENDING_CONFIRMATION',
                currentYearNumber: 1,
                academicYear: '2026/2027',
              },
            })

            // Generate Year 1 milestones (40/30/30)
            await generateMilestonesForYear(enrollment.id, year1.id)
          }

          // Mark milestones based on payment type
          const milestones = await prismaUnfiltered.paymentMilestone.findMany({
            where: { enrollmentId: enrollment.id, yearNumber: 1 },
            orderBy: { createdAt: 'asc' },
          })

          if (
            payment.referenceType === 'SEAT_CONFIRMATION' ||
            payment.referenceType === 'CUSTOM_PART_PAYMENT'
          ) {
            // Mark SEAT_CONFIRMATION milestone as PAID
            const seatMs = milestones.find((m) => m.milestoneType === 'SEAT_CONFIRMATION')
            if (seatMs && seatMs.status !== 'PAID') {
              await prismaUnfiltered.paymentMilestone.update({
                where: { id: seatMs.id },
                data: { status: 'PAID', paidAt: new Date() },
              })
            }

            // For CUSTOM_PART_PAYMENT: if amount > seat fee, apply excess to SEM1_DUE via wallet
            if (payment.referenceType === 'CUSTOM_PART_PAYMENT' && seatMs) {
              const seatAmount = Number(seatMs.amountDue)
              const paidAmount = Number(payment.amount)
              const excess = paidAmount - seatAmount

              if (excess > 0) {
                // Credit excess to wallet for future milestone payments
                await prismaUnfiltered.$transaction(async (tx) => {
                  let wallet = await tx.wallet.findUnique({ where: { userId: payment.userId } })
                  if (!wallet) {
                    wallet = await tx.wallet.create({
                      data: {
                        userId: payment.userId,
                        balance: 0,
                        reservedBalance: 0,
                        availableBalance: 0,
                      },
                    })
                  }
                  await topUpWallet(
                    tx,
                    payment.userId,
                    excess,
                    `Excess from custom part payment credited to wallet`,
                    payment.id,
                    'PAYMENT_ID'
                  )
                })
              }
            }

            // Update enrollment status
            await prismaUnfiltered.fullTimeEnrollment.update({
              where: { id: enrollment.id },
              data: { status: 'ACTIVE' },
            })

            // Send seat reservation confirmation email
            if (payment.user.profile) {
              const programmeName =
                programme?.name || payment.user.programmeChoice || 'Your Programme'

              const targetEmail = payment.user.personalEmail || payment.user.email

              await sendSeatReservationConfirmedEmail(
                targetEmail,
                payment.user.profile.firstName,
                programmeName,
                Number(payment.amount),
                payment.currency || 'EUR'
              ).catch(console.error)

              // Also send to academy email if different
              if (payment.user.academyEmail && payment.user.academyEmail !== targetEmail) {
                await sendSeatReservationConfirmedEmail(
                  payment.user.academyEmail,
                  payment.user.profile.firstName,
                  programmeName,
                  Number(payment.amount),
                  payment.currency || 'EUR'
                ).catch(console.error)
              }
            }
          }
        }
      }

      // Promote APPLICANT → STUDENT if payment type satisfies pathway conditions
      // (YEAR_1_FULL and FULL_PROGRAMME promote immediately; SEAT_CONFIRMATION does NOT)
      if (
        payment.user.role === 'APPLICANT' &&
        payment.user.status === 'ACTIVE' &&
        payment.referenceType &&
        shouldPromoteOnPayment(payment.user.programmeChoice, payment.referenceType)
      ) {
        await promoteApplicantToStudent(payment.userId, staff.id)
      }

      // Qualify any pending referral for this user (non-blocking)
      import('@/lib/referral/operations')
        .then(({ qualifyReferral }) => qualifyReferral(payment.userId))
        .catch(console.error)

      // Handle REGISTRATION payment - send activation email with credentials
      if (payment.referenceType === 'REGISTRATION' && payment.user.profile) {
        const profile = payment.user.profile

        // Only generate credentials if user is still PENDING (not yet activated)
        if (payment.user.status === 'PENDING') {
          const tempPassword = generateTempPassword()
          const hashedTempPassword = await hashPassword(tempPassword)
          const verifyToken = generateToken()
          const verifyTokenExpires = new Date(Date.now() + 24 * 60 * 60 * 1000)
          const academyEmail = await generateAcademyEmail(
            profile.firstName,
            profile.middleName || undefined,
            profile.lastName
          )

          // Update user with credentials and activate
          await prismaUnfiltered.user.update({
            where: { id: payment.userId },
            data: {
              status: 'ACTIVE',
              email: academyEmail,
              academyEmail,
              password: hashedTempPassword,
              verifyToken,
              verifyTokenExpires,
              mustChangePassword: true,
              paymentApprovedAt: new Date(),
              paymentApprovedBy: staff.id,
              registrationPaid: true,
            },
          })

          // Send activation email
          await sendActivationEmail(
            payment.user.personalEmail || payment.user.email,
            profile.firstName,
            academyEmail,
            tempPassword,
            verifyToken
          )
        }
      } else if (payment.user.profile) {
        const targetEmail = payment.user.personalEmail || payment.user.email
        // Send payment approved email
        await sendPaymentApprovedEmail(
          targetEmail,
          payment.user.profile.firstName,
          payment.referenceType || 'Payment',
          Number(payment.amount)
        ).catch(console.error)

        // Academy email domain not active — skip sending there
      }

      await createAuditLog({
        action: AuditAction.PAYMENT_APPROVE,
        entity: 'Payment',
        entityId: id,
        userId: staff.id,
        description: `Approved payment of ${payment.currency || 'EUR'} ${payment.amount} for ${payment.user.profile ? `${payment.user.profile.firstName} (${payment.user.email})` : payment.userId} - ${payment.referenceType || 'Payment'}`,
        details: {
          targetUserId: payment.userId,
          amount: payment.amount,
          type: payment.referenceType,
        },
      })

      // Send in-app notification
      await prismaUnfiltered.notification.create({
        data: {
          userId: payment.userId,
          title: 'Payment Approved',
          message: `Your payment of ${payment.currency || 'EUR'} ${payment.amount} for ${formatPaymentType(payment.referenceType || 'services')} has been approved.`,
          type: 'SUCCESS',
          linkUrl: '/student/wallet?tab=payments',
          linkText: 'View Payments',
        },
      })

      // Analytics tracking (non-blocking)
      trackPayment(
        Number(payment.amount),
        payment.currency || 'EUR',
        payment.id,
        payment.userId
      ).catch(console.error)

      return apiSuccess({ message: 'Payment approved' })
    } else {
      if (!reason) return apiError('Rejection reason is required')

      await prismaUnfiltered.payment.update({
        where: { id },
        data: {
          status: PaymentStatus.REJECTED,
          rejectedBy: staff.id,
          rejectedAt: new Date(),
          rejectionReason: reason,
        },
      })

      if (payment.user.profile) {
        // Send payment rejected email to personal email
        const rejectEmail = payment.user.personalEmail || payment.user.email
        await sendPaymentRejectedEmail(
          rejectEmail,
          payment.user.profile.firstName,
          payment.referenceType || 'Payment',
          reason
        ).catch(console.error)
      }

      await createAuditLog({
        action: AuditAction.PAYMENT_REJECT,
        entity: 'Payment',
        entityId: id,
        userId: staff.id,
        description: `Rejected payment of ${payment.currency || 'EUR'} ${payment.amount} for ${payment.user.profile ? `${payment.user.profile.firstName} (${payment.user.email})` : payment.userId} - Reason: ${reason}`,
        details: { targetUserId: payment.userId, reason },
      })

      // Send in-app notification
      await prismaUnfiltered.notification.create({
        data: {
          userId: payment.userId,
          title: 'Payment Rejected',
          message: `Your payment of ${payment.currency || 'EUR'} ${payment.amount} for ${formatPaymentType(payment.referenceType || 'services')} has been rejected. Reason: ${reason}.`,
          type: 'ERROR',
          linkUrl: '/student/wallet?tab=payments',
          linkText: 'View Payments',
        },
      })

      return apiSuccess({ message: 'Payment rejected' })
    }
  }
)

import { NextRequest, NextResponse } from 'next/server'
import prisma, { prismaUnfiltered } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { serializePrisma } from '@/lib/utils/serialization'

export async function GET(req: NextRequest) {
  const session = await getAuthSession()
  if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { searchParams } = new URL(req.url)
  const status = searchParams.get('status')
  const search = searchParams.get('search')
  const page = parseInt(searchParams.get('page') || '1')
  const limit = Math.min(parseInt(searchParams.get('limit') || '50'), 100)

  const where: any = {}

  if (status && status !== 'ALL') {
    where.status = status
  }

  if (search) {
    where.OR = [
      { user: { email: { contains: search, mode: 'insensitive' } } },
      { user: { profile: { firstName: { contains: search, mode: 'insensitive' } } } },
      { user: { profile: { lastName: { contains: search, mode: 'insensitive' } } } },
      { referenceCode: { contains: search, mode: 'insensitive' } },
    ]
  }

  const [count, payments] = await Promise.all([
    prismaUnfiltered.payment.count({ where }),
    prismaUnfiltered.payment.findMany({
      where,
      include: {
        user: {
          select: {
            id: true,
            email: true,
            academyEmail: true,
            role: true,
            profile: { select: { firstName: true, lastName: true } },
          },
        },
      },
      orderBy: { createdAt: 'desc' },
      skip: (page - 1) * limit,
      take: limit,
    }),
  ])

  return NextResponse.json({
    total: count,
    page,
    limit,
    payments: serializePrisma(payments),
  })
}

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'

// PUT — sign/update a practical training record (dual signature or full admin edit)
export const PUT = withErrorHandler(async (req: NextRequest, ctx: any) => {
  await requireStaff()
  const { id } = ctx.params
  const body = await req.json()

  const record = await prismaUnfiltered.practicalTrainingRecord.findUnique({ where: { id } })
  if (!record) return apiError('Record not found', 404)

  // Handle full admin edit payload if provided
  if (body.isFullEdit) {
    const updated = await prismaUnfiltered.practicalTrainingRecord.update({
      where: { id },
      data: {
        studentProfileId: body.studentProfileId,
        courseId: body.courseId,
        classId: body.classId || null,
        taskCategory: body.taskCategory,
        taskReference: body.taskReference || null,
        ataChapterId: body.ataChapterId || null,
        description: body.description,
        deliveryMethod: body.deliveryMethod,
        date: new Date(body.date),
        durationMinutes: Number(body.durationMinutes),
        instructorId: body.instructorId,
        result: body.result || null,
        assessorNotes: body.assessorNotes || null,
      },
    })
    return apiSuccess(updated)
  }

  // Otherwise fallback to the signature/quick-result update path
  const data: any = {}

  // Instructor signature
  if (body.signedByInstructor !== undefined) {
    data.signedByInstructor = body.signedByInstructor
  }

  // Assessment result
  if (body.result) {
    data.result = body.result
    data.assessorNotes = body.assessorNotes || null
    data.assessorId = body.assessorId || null
  }

  // Track signature timestamp
  if (body.signedByInstructor || body.signedByStudent) {
    data.signedAt = new Date()
  }

  // Student signature (can come from student portal too)
  if (body.signedByStudent !== undefined) {
    data.signedByStudent = body.signedByStudent
  }

  const updated = await prismaUnfiltered.practicalTrainingRecord.update({
    where: { id },
    data,
  })

  return apiSuccess(updated)
})

// DELETE — delete practical training record
export const DELETE = withErrorHandler(async (req: NextRequest, ctx: any) => {
  await requireStaff()
  const { id } = ctx.params

  const record = await prismaUnfiltered.practicalTrainingRecord.findUnique({ where: { id } })
  if (!record) return apiError('Record not found', 404)

  await prismaUnfiltered.practicalTrainingRecord.delete({
    where: { id },
  })

  return apiSuccess({ message: 'Practical training record deleted successfully' })
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiCreated, withErrorHandler, RouteContext } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { z } from 'zod'

const MAX_STUDENTS_PER_SESSION = 15

const recordSchema = z.object({
  studentProfileId: z.string(),
  courseId: z.string(),
  classId: z.string().optional(),
  taskCategory: z.enum(['P1', 'P2']),
  taskReference: z.string().optional(),
  ataChapterId: z.string().optional(),
  description: z.string().min(1),
  deliveryMethod: z.enum(['TASK_PERFORMANCE', 'DEMONSTRATION', 'TECHNICAL_DISCUSSION', 'SIMULATION']),
  date: z.string(),
  durationMinutes: z.number().min(15),
  instructorId: z.string(),
  assessorId: z.string().optional(),
  result: z.enum(['SATISFACTORY', 'UNSATISFACTORY', 'NEEDS_REVIEW']).optional(),
  assessorNotes: z.string().optional(),
})

// GET — list practical training records
export const GET = withErrorHandler(async (req: NextRequest, _ctx?: RouteContext) => {
  await requireStaff()
  const url = new URL(req.url)
  let studentProfileId = url.searchParams.get('studentProfileId')
  const userId = url.searchParams.get('userId')
  if (!studentProfileId && userId) {
    const sp = await prismaUnfiltered.studentProfile.findUnique({
      where: { userId },
      select: { id: true },
    })
    if (sp) studentProfileId = sp.id
  }
  const courseId = url.searchParams.get('courseId')
  const page = parseInt(url.searchParams.get('page') || '1')
  const limit = parseInt(url.searchParams.get('limit') || '50')

  const where: any = {}
  if (studentProfileId) where.studentProfileId = studentProfileId
  if (courseId) where.courseId = courseId

  const [records, total] = await Promise.all([
    prismaUnfiltered.practicalTrainingRecord.findMany({
      where,
      include: {
        ataChapter: { select: { code: true, title: true } },
        course: { select: { name: true, code: true } },
        instructor: { select: { profile: { select: { firstName: true, lastName: true } } } },
        studentProfile: {
          select: {
            studentId: true,
            user: { select: { profile: { select: { firstName: true, lastName: true } } } },
          },
        },
      },
      orderBy: { date: 'desc' },
      skip: (page - 1) * limit,
      take: limit,
    }),
    prismaUnfiltered.practicalTrainingRecord.count({ where }),
  ])

  // ATA coverage analysis
  let ataCoverage = null
  if (studentProfileId) {
    const allChapters = await prismaUnfiltered.aTAChapter.findMany({
      where: { isActive: true },
      select: { id: true, code: true, title: true, category: true },
      orderBy: { sortOrder: 'asc' },
    })

    const completedChapterIds = new Set(
      records.filter(r => r.ataChapterId && r.result === 'SATISFACTORY').map(r => r.ataChapterId!)
    )

    ataCoverage = {
      total: allChapters.length,
      completed: completedChapterIds.size,
      percent: allChapters.length > 0 ? Math.round((completedChapterIds.size / allChapters.length) * 100) : 0,
      chapters: allChapters.map(ch => ({
        ...ch,
        completed: completedChapterIds.has(ch.id),
      })),
    }
  }

  return apiSuccess({ records, total, page, limit, ataCoverage })
})

// POST — create practical training record
export const POST = withErrorHandler(async (req: NextRequest, _ctx?: RouteContext) => {
  await requireStaff()
  const body = await req.json()
  const parsed = recordSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input')

  // Enforce 15-student max per instructor per session
  const sessionDate = new Date(parsed.data.date)
  const dayStart = new Date(sessionDate.getFullYear(), sessionDate.getMonth(), sessionDate.getDate())
  const dayEnd = new Date(dayStart.getTime() + 24 * 60 * 60 * 1000)

  const studentsToday = await prismaUnfiltered.practicalTrainingRecord.findMany({
    where: {
      instructorId: parsed.data.instructorId,
      date: { gte: dayStart, lt: dayEnd },
    },
    select: { studentProfileId: true },
    distinct: ['studentProfileId'],
  })

  if (studentsToday.length >= MAX_STUDENTS_PER_SESSION &&
      !studentsToday.some(s => s.studentProfileId === parsed.data.studentProfileId)) {
    return apiError(`Maximum ${MAX_STUDENTS_PER_SESSION} students per instructor per day`, 400)
  }

  const record = await prismaUnfiltered.practicalTrainingRecord.create({
    data: {
      studentProfileId: parsed.data.studentProfileId,
      courseId: parsed.data.courseId,
      classId: parsed.data.classId || null,
      taskCategory: parsed.data.taskCategory as any,
      taskReference: parsed.data.taskReference || null,
      ataChapterId: parsed.data.ataChapterId || null,
      description: parsed.data.description,
      deliveryMethod: parsed.data.deliveryMethod as any,
      date: sessionDate,
      durationMinutes: parsed.data.durationMinutes,
      instructorId: parsed.data.instructorId,
      assessorId: parsed.data.assessorId || null,
      result: (parsed.data.result as any) || null,
      assessorNotes: parsed.data.assessorNotes || null,
    },
  })

  return apiCreated(record)
})

import { NextRequest } from 'next/server'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'

// PUT — approve/reject upgrade request
export const PUT = withErrorHandler(async (req: NextRequest, ctx: any) => {
  const staff = await requireStaff()
  const { id } = await ctx.params
  const { action, notes, newDeadline } = await req.json()

  const request = await prismaUnfiltered.programmeUpgradeRequest.findUnique({
    where: { id },
    include: { application: true },
  })
  if (!request) return apiError('Upgrade request not found', 404)
  if (request.status !== 'PENDING') return apiError('Request is not pending')

  if (action === 'APPROVE') {
    await prismaUnfiltered.$transaction(async (tx) => {
      // Update the upgrade request
      await tx.programmeUpgradeRequest.update({
        where: { id },
        data: {
          status: 'APPROVED',
          approvedBy: staff.id,
          approvedAt: new Date(),
          notes: notes || null,
        },
      })

      // Update the application programme choice and deadline
      await tx.application.update({
        where: { id: request.applicationId },
        data: {
          programmeChoice: request.toProgramme,
          completionDeadline: newDeadline ? new Date(newDeadline) : undefined,
        },
      })

      // Update student profile programme
      await tx.studentProfile.update({
        where: { id: request.studentProfileId },
        data: {
          programmeChoice: request.toProgramme,
        },
      })

      // Audit log
      await tx.auditLog.create({
        data: {
          userId: staff.id,
          action: 'PROGRAMME_UPGRADE_APPROVED',
          targetType: 'PROGRAMME_UPGRADE',
          targetId: id,
          metadata: {
            from: request.fromProgramme,
            to: request.toProgramme,
            studentProfileId: request.studentProfileId,
          },
        },
      })
    })

    return apiSuccess({ status: 'APPROVED' })
  } else if (action === 'REJECT') {
    await prismaUnfiltered.programmeUpgradeRequest.update({
      where: { id },
      data: {
        status: 'REJECTED',
        approvedBy: staff.id,
        approvedAt: new Date(),
        notes: notes || null,
      },
    })

    return apiSuccess({ status: 'REJECTED' })
  }

  return apiError('Invalid action')
})

