import { NextRequest } from 'next/server'
import { withErrorHandler, apiPaginated, parsePagination } from '@/lib/api/response'
import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'

export const GET = withErrorHandler(async (req: NextRequest) => {
  await requireStaff()
  const url = new URL(req.url)
  const { page, limit, skip } = parsePagination(url.searchParams)

  const statusParam = url.searchParams.get('status') ?? 'all'
  const search = url.searchParams.get('search')?.trim().toLowerCase() ?? ''

  const where: any = {}
  if (statusParam !== 'all') {
    where.status = statusParam as 'SUCCESS' | 'FAILED' | 'RETRYING'
  }
  if (search) {
    where.OR = [
      { recipient: { contains: search, mode: 'insensitive' } },
      { subject: { contains: search, mode: 'insensitive' } },
      { error: { contains: search, mode: 'insensitive' } },
    ]
  }

  const [rows, total] = await Promise.all([
    prismaUnfiltered.emailDelivery.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      skip,
      take: limit,
    }),
    prismaUnfiltered.emailDelivery.count({ where }),
  ])

  return apiPaginated(rows, total, page, limit)
})

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireAdmin, getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, withErrorHandler, apiError } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { revalidateTag } from 'next/cache'

export const GET = withErrorHandler(async (req: NextRequest) => {
  await requireAdmin()
  const { searchParams } = new URL(req.url)
  const group = searchParams.get('group')

  const where: any = {}
  if (group) where.group = group

  const settings = await prismaUnfiltered.systemSetting.findMany({ where, orderBy: { key: 'asc' } })
  return apiSuccess(settings)
})

export async function POST(req: NextRequest) {
  const session = await getAuthSession()
  if (!session) return apiError('Unauthorized', 401)
  const staff = session.user

  try {
    const formData = await req.formData()
    const updates: { key: string; value: string; type: string }[] = []

    const fieldNames = new Set<string>()
    for (const [key] of formData.entries()) {
      if (key.endsWith('__type')) {
        fieldNames.add(key.replace('__type', ''))
      } else {
        fieldNames.add(key)
      }
    }

    for (const fieldName of fieldNames) {
      const type = (formData.get(`${fieldName}__type`) as string) ?? 'STRING'

      let value: string
      if (type === 'BOOLEAN') {
        const val = formData.get(fieldName)
        value = (val === 'on' || val === 'true') ? 'true' : 'false'
      } else {
        const val = formData.get(fieldName)
        if (val === null) continue
        value = (val as string).trim()
      }

      updates.push({ key: fieldName, value, type })
    }

    await Promise.all(
      updates.map(({ key, value, type }) =>
        prismaUnfiltered.systemSetting.upsert({
          where: { key },
          update: { value, updatedBy: session.user.id },
          create: { key, value, type },
        })
      )
    )

    await createAuditLog({
      action: AuditAction.SYSTEM_UPDATE,
      entity: 'SystemSetting',
      userId: staff.id,
      details: { updates },
    })

    revalidateTag('settings', 'max')

    // Return JSON when requested (client-side form submissions)
    const accept = req.headers.get('accept') || ''
    if (accept.includes('application/json')) {
      return apiSuccess({ saved: true, count: updates.length })
    }

    // Redirect back for native form submissions
    return new Response(null, {
      status: 303,
      headers: { Location: '/staff/settings?saved=1' },
    })
  } catch (error: any) {
    return apiError(error.message || 'Failed to save settings', 500)
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { createAuditLog } from '@/lib/audit/logger'

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await getAuthSession()
  if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const staff = session.user as any
  if (!['STAFF', 'ADMIN'].includes(staff.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { id } = await params

  try {
    const { academicYearId, semesterId } = await req.json()

    // Validate: can't have semester without academic year
    if (semesterId && !academicYearId) {
      return NextResponse.json(
        { error: 'Cannot assign a semester without an academic year' },
        { status: 400 }
      )
    }

    // Validate semester belongs to the chosen academic year
    if (semesterId && academicYearId) {
      const semester = await prismaUnfiltered.semester.findUnique({
        where: { id: semesterId },
        select: { academicYearId: true },
      })
      if (!semester || semester.academicYearId !== academicYearId) {
        return NextResponse.json(
          { error: 'Selected semester does not belong to the chosen academic year' },
          { status: 400 }
        )
      }
    }

    const targetUser = await prismaUnfiltered.user.findUnique({
      where: { id },
      include: { studentProfile: { select: { id: true, academicYearId: true, semesterId: true } } },
    })

    if (!targetUser) return NextResponse.json({ error: 'User not found' }, { status: 404 })
    if (!targetUser.studentProfile) {
      return NextResponse.json({ error: 'Student profile not found' }, { status: 404 })
    }

    await prismaUnfiltered.studentProfile.update({
      where: { userId: id },
      data: {
        academicYearId: academicYearId || null,
        semesterId: semesterId || null,
      },
    })

    await createAuditLog({
      action: 'USER_UPDATE',
      entity: 'student_profiles',
      entityId: id,
      userId: staff.id,
      details: {
        oldAcademicYearId: targetUser.studentProfile.academicYearId,
        oldSemesterId: targetUser.studentProfile.semesterId,
        newAcademicYearId: academicYearId,
        newSemesterId: semesterId,
      },
      description: `Admin updated student academic period`,
    })

    return NextResponse.json({ success: true, message: 'Academic period updated' })
  } catch (error: any) {
    console.error('Academic period update error:', error)
    return NextResponse.json({ error: 'Failed to update academic period' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { getExamPricingConfig } from '@/lib/pools/pricing-config'
import { logAuditEvent } from '@/lib/audit/logger'
import { revalidatePath } from 'next/cache'

/**
 * POST /api/staff/students/[id]/book-exam
 *
 * Admin books exam(s) on behalf of a student.
 * Supports: INDIVIDUAL, TWIN_PACK, FOUR_PACK, RESIT booking types.
 * Payment: AUTO_DEBIT (wallet debit now) or MANUAL_LATER (create pending booking).
 */
export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const studentId = context?.params?.id
    if (!studentId) return apiError('Student ID required')

    const body = await req.json()
    const { staffBookExamSchema, validateBody } = await import('@/lib/validation/schemas')
    const validation = validateBody(staffBookExamSchema, body)
    if (!validation.success) return apiError(validation.error)
    const { bookingType, moduleIds, eventId, examDate, paymentMethod, notes, attemptType } = validation.data

    // Validate module count per booking type
    const expectedModules: Record<string, number> = {
      INDIVIDUAL: 1,
      TWIN_PACK: 2,
      FOUR_PACK: 4,
      RESIT: 1,
    }
    if (moduleIds.length !== expectedModules[bookingType]) {
      return apiError(
        `${bookingType} requires exactly ${expectedModules[bookingType]} module(s). Got ${moduleIds.length}.`
      )
    }

    // Verify student exists
    const student = await prismaUnfiltered.user.findUnique({
      where: { id: studentId, role: 'STUDENT' },
      include: { profile: true },
    })
    if (!student) return apiError('Student not found')

    // Fetch pricing
    const pricing = await getExamPricingConfig()
    const priceMap: Record<string, number> = {
      INDIVIDUAL: pricing.individualExamFee,
      TWIN_PACK: pricing.twoSeatBundle,
      FOUR_PACK: pricing.fourSeatBundle,
      RESIT: pricing.resitExamFee,
    }
    const totalPrice = priceMap[bookingType]

    // Resolve exam components from IDs (moduleIds are ExamComponent IDs)
    const components = await prismaUnfiltered.examComponent.findMany({
      where: { id: { in: moduleIds } },
      include: { course: true },
    })
    if (components.length !== moduleIds.length) {
      return apiError('One or more invalid module IDs')
    }

    // Resolve exam date
    let resolvedExamDate: Date | null = examDate ? new Date(examDate) : null

    // If event specified, try to use event start date
    if (eventId && !resolvedExamDate) {
      const event = await prismaUnfiltered.examEvent.findUnique({ where: { id: eventId } })
      if (event) resolvedExamDate = event.startDate
    }

    if (!resolvedExamDate) {
      return apiError('Exam date is required (either directly or via an exam event)')
    }

    // Perform the booking in a transaction
    const result = await prismaUnfiltered.$transaction(async (tx) => {
      let walletTxnId: string | null = null

      // Handle wallet debit if AUTO_DEBIT
      if (paymentMethod === 'AUTO_DEBIT') {
        const wallet = await tx.wallet.findUnique({ where: { userId: studentId } })
        if (!wallet) {
          throw new Error(
            'Student wallet not found. Please ensure the student has a wallet before booking. You may need to credit their wallet first via the Wallet tab.'
          )
        }

        const available = Number(wallet.availableBalance)
        if (available < totalPrice) {
          throw new Error(
            `Insufficient wallet balance. Need €${totalPrice.toFixed(2)}, available €${available.toFixed(2)}. ` +
            `Please adjust the student's wallet balance first (Student Profile → Wallet tab → Manual Adjustment), then try booking again.`
          )
        }

        // Use standard chargeWallet() for proper audit trail
        const { chargeWallet } = await import('@/lib/wallet/operations')
        await chargeWallet(
          tx,
          studentId,
          totalPrice,
          `Admin booked ${bookingType.replace(/_/g, ' ')} exam(s): ${components.map((c) => c.code).join(', ')}`,
          `ADMIN_BOOKING_${Date.now()}`,
          'EXAM_BOOKING'
        )

        // Retrieve the wallet transaction ID for linking to bookings
        const latestTxn = await tx.walletTransaction.findFirst({
          where: { wallet: { userId: studentId }, referenceType: 'EXAM_BOOKING' },
          orderBy: { createdAt: 'desc' },
          select: { id: true },
        })
        walletTxnId = latestTxn?.id ?? null
      }

      // Create exam bookings
      const bookingGroupRef = moduleIds.length > 1 ? `ADMIN_BUNDLE_${Date.now()}` : undefined

      const createdBookings = []
      for (let i = 0; i < components.length; i++) {
        const comp = components[i]
        const isFirst = i === 0

        const booking = await tx.examBooking.create({
          data: {
            userId: studentId,
            examComponentId: comp.id,
            courseId: comp.courseId,
            moduleCode: comp.course?.code?.toUpperCase() || comp.code,
            examDate: resolvedExamDate!,
            eventId: eventId || undefined,
            amountPaid: isFirst ? totalPrice : 0,
            status: paymentMethod === 'AUTO_DEBIT' ? ('COMPLETED') : ('PENDING'),
            bookingType: bookingType,
            attemptType: attemptType || (bookingType === 'RESIT' ? 'RESIT_1' : 'FIRST'),
            isResit: bookingType === 'RESIT',

            bookingGroupRef,
            walletTxnId: isFirst ? walletTxnId : undefined,
          },
        })
        createdBookings.push(booking)
      }

      // Create notification for student
      await tx.notification.create({
        data: {
          userId: studentId,
          title: 'Exam Booking Created',
          message: `An admin has booked ${components.map((c) => c.code).join(', ')} exam(s) for you${resolvedExamDate ? ` on ${resolvedExamDate.toLocaleDateString('en-GB')}` : ''}. ${paymentMethod === 'AUTO_DEBIT' ? `€${totalPrice} has been debited from your wallet.` : 'Payment is pending.'}`,
          type: 'EXAM_REMINDER',
          sentBy: staff.id,
          linkUrl: '/student/exams',
          linkText: 'View Exams',
        },
      })

      return {
        bookingIds: createdBookings.map((b) => b.id),
        walletTxnId,
        totalPrice,
      }
    })

    const studentName = student.profile ? `${student.profile.firstName} ${student.profile.lastName}` : student.email

    // Audit log
    await logAuditEvent({
      userId: staff.id,
      action: 'EXAM_BOOKING_CREATED',
      entity: 'ExamBooking',
      entityId: result.bookingIds[0],
      description: `Admin booked ${bookingType} exam(s) for student ${studentName}: ${components.map((c) => c.code).join(', ')}. Payment: ${paymentMethod}`,
    })

    // Revalidate paths
    revalidatePath('/student')
    revalidatePath('/student/exams')
    revalidatePath('/student/wallet')
    revalidatePath('/student/notifications')
    revalidatePath('/staff/exams')
    revalidatePath(`/staff/students/${studentId}`)

    return apiSuccess({
      success: true,
      bookingIds: result.bookingIds,
      walletTransaction: result.walletTxnId
        ? { id: result.walletTxnId, amount: result.totalPrice }
        : null,
    })
  }
)

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiCreated, withErrorHandler, RouteContext } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { serializePrisma } from '@/lib/utils/serialization'

// GET /api/staff/students/[id]/ojt — List OJT periods for a student
export const GET = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    await requireStaff()
    const userId = context?.params?.id
    if (!userId) return apiError('Student user ID required')

    const enrollments = await prismaUnfiltered.fullTimeEnrollment.findMany({
      where: { studentId: userId },
      include: {
        ojtPeriods: { orderBy: { startDate: 'desc' } },
        programme: { select: { code: true, name: true } },
      },
    })

    return apiSuccess(serializePrisma(enrollments))
  }
)

// POST /api/staff/students/[id]/ojt — Create an OJT period
export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const userId = context?.params?.id
    if (!userId) return apiError('Student user ID required')

    const body = await req.json()
    const { enrollmentId, companyName, companyAddress, supervisorName, supervisorEmail, startDate, hoursRequired } = body

    if (!enrollmentId || !companyName || !startDate) {
      return apiError('Enrollment ID, company name, and start date are required')
    }

    // Validate OJT access for the student
    const { allowed, error: validationError, severity } = await import('@/lib/enrollment/validation').then(v => 
      v.validateOjtAccess(userId)
    )

    const force = body.ignorePathwayRestrictions === true

    if (!allowed && !force) {
      return apiError(validationError || 'Student is not eligible for OJT.', 400, {
        needsOverride: severity === 'WARNING',
        warning: validationError
      })
    }

    const enrollment = await prismaUnfiltered.fullTimeEnrollment.findUnique({
      where: { id: enrollmentId, studentId: userId },
    })
    if (!enrollment) return apiError('Enrollment not found for this student', 404)

    const ojt = await prismaUnfiltered.ojtPeriod.create({
      data: {
        enrollmentId,
        companyName,
        companyAddress: companyAddress || null,
        supervisorName: supervisorName || null,
        supervisorEmail: supervisorEmail || null,
        startDate: new Date(startDate),
        hoursRequired: hoursRequired ? parseInt(hoursRequired) : 2000,
        status: 'PENDING',
      },
    })

    await createAuditLog({
      action: AuditAction.CREATE,
      entity: 'OjtPeriod',
      entityId: ojt.id,
      userId: staff.id,
      details: { studentUserId: userId, companyName },
    })

    return apiCreated(serializePrisma(ojt))
  }
)

// PATCH /api/staff/students/[id]/ojt — Update an OJT period
export const PATCH = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const body = await req.json()
    const { ojtId, status, hoursCompleted, endDate, notes } = body

    if (!ojtId) return apiError('OJT period ID required')

    const ojt = await prismaUnfiltered.ojtPeriod.findUnique({ where: { id: ojtId } })
    if (!ojt) return apiError('OJT period not found', 404)

    const updated = await prismaUnfiltered.ojtPeriod.update({
      where: { id: ojtId },
      data: {
        ...(status !== undefined && { status }),
        ...(hoursCompleted !== undefined && { hoursCompleted: parseInt(hoursCompleted) }),
        ...(endDate !== undefined && { endDate: endDate ? new Date(endDate) : null }),
        ...(notes !== undefined && { notes }),
      },
    })

    await createAuditLog({
      action: AuditAction.UPDATE,
      entity: 'OjtPeriod',
      entityId: ojtId,
      userId: staff.id,
      details: body,
    })

    return apiSuccess(serializePrisma(updated))
  }
)

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiNotFound, apiError, withErrorHandler } from '@/lib/api/response'
import { serializePrisma } from '@/lib/utils/serialization'

// GET /api/staff/students/[id]
// Comprehensive student detail — used by StudentDetailPanel (quick preview)
// and the full student management page at /staff/students/[id]
export const GET = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    await requireStaff()
    const id = context?.params?.id
    if (!id) return apiError('Student ID required')

    const { searchParams } = new URL(req.url)
    const full = searchParams.get('full') === '1'

    const [student, ftEnrollmentsRaw] = await Promise.all([
      prismaUnfiltered.user.findUnique({
      where: { id, role: 'STUDENT' },
      include: {
        profile: true,
        studentProfile: {
          include: {
            academicYear: { select: { id: true, name: true } },
            semester: { select: { id: true, name: true } },
            pathwayRel: { select: { id: true, code: true, name: true } },
            licenseTargets: {
              include: { licenseCategory: { select: { id: true, code: true, name: true } } },
            },
          },
        },
        wallet: {
          include: {
            transactions: {
              orderBy: { createdAt: 'desc' },
              take: full ? 100 : 20,
            },
          },
        },
        enrollments: {
          include: {
            course: true,
            grades: { orderBy: { assessmentDate: 'desc' } },
          },
        },
        poolMemberships: {
          include: {
            pool: { include: { event: true } },
            examComponent: { include: { course: { select: { name: true, code: true } } } },
          },
        },
        attendanceRecords: {
          orderBy: { date: 'desc' },
          take: full ? 100 : 30,
          include: {
            class: { select: { name: true, course: { select: { name: true, code: true } } } },
          },
        },
        examResults: {
          include: {
            exam: {
              include: {
                examComponent: { include: { course: { select: { name: true, code: true } } } },
              },
            },
          },
          orderBy: { createdAt: 'desc' },
        },
        // Fetch ALL exam bookings, not just COMPLETED
        examBookings: {
          include: {
            exam: {
              include: {
                examComponent: { include: { course: { select: { name: true, code: true } } } },
              },
            },
            event: { select: { id: true, name: true, startDate: true, endDate: true } },
            course: { select: { id: true, name: true, code: true } },
          },
          orderBy: { examDate: 'desc' },
        },
        examBundles: {
          orderBy: { createdAt: 'desc' },
        },
        bookingEntitlements: {
          orderBy: { createdAt: 'desc' },
        },
      },
      }),
      full
        ? prismaUnfiltered.fullTimeEnrollment.findMany({
            where: { studentId: id },
            include: {
              programme: { select: { code: true, name: true } },
              ojtPeriods: { orderBy: { startDate: 'desc' } },
              milestones: { orderBy: [{ yearNumber: 'asc' }, { createdAt: 'asc' }] },
            },
          })
        : Promise.resolve([]),
    ])

    if (!student) return apiNotFound('Student not found')

    // If full mode, format full-time enrollment / OJT data
    let fullTimeData = null
    if (full && ftEnrollmentsRaw.length > 0) {
      fullTimeData = ftEnrollmentsRaw.map((e) => {
        const { programme, ojtPeriods, milestones, ...rest } = e
        return {
          ...rest,
          programme,
          ojtPeriods: ojtPeriods.map((o) => ({
            ...o,
            startDate: o.startDate.toISOString(),
            endDate: o.endDate?.toISOString() ?? null,
            createdAt: o.createdAt.toISOString(),
            updatedAt: o.updatedAt.toISOString(),
          })),
          milestones,
        }
      })
    }

    const { password, ...safe } = student

    return apiSuccess(serializePrisma({
      ...safe,
      fullTimeEnrollments: fullTimeData,
    }))
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { createAuditLog } from '@/lib/audit/logger'
import { triggerAutoEnrollmentIfRequired } from '@/lib/enrollment/engine'

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const staff = await requireStaff()
  const { id } = await params

  try {
    const { pathwayCode, reason } = await req.json()

    if (!pathwayCode || typeof pathwayCode !== 'string') {
      return NextResponse.json({ error: 'Pathway code is required' }, { status: 400 })
    }

    if (!reason || reason.length < 5) {
      return NextResponse.json(
        { error: 'A valid reason is required for administrative override' },
        { status: 400 }
      )
    }

    // Validate the pathway exists
    const pathway = await prismaUnfiltered.studyPathwayModel.findUnique({ where: { code: pathwayCode } })
    if (!pathway) {
      return NextResponse.json({ error: 'Invalid pathway code' }, { status: 400 })
    }

    const targetUser = await prismaUnfiltered.user.findUnique({
      where: { id },
      include: { studentProfile: { select: { id: true, pathwayId: true } } },
    })

    if (!targetUser) return NextResponse.json({ error: 'User not found' }, { status: 404 })

    let studentProfileId: string

    await prismaUnfiltered.$transaction(async (tx) => {
      const profileData = {
        pathwayId: pathway.id,
        studyPathwayLockedAt: new Date(),
        studyPathwayLocked: true,
        studyPathwayLastChangedBy: staff.id,
        studyPathwayChangeReason: reason,
      }

      if (targetUser.studentProfile) {
        studentProfileId = targetUser.studentProfile.id
        await tx.studentProfile.update({
          where: { userId: id },
          data: profileData,
        })
      } else {
        const { generateStudentId } = await import('@/lib/auth/helpers')
        const created = await tx.studentProfile.create({
          data: {
            userId: id,
            studentId: await generateStudentId(),
            ...profileData,
          },
        })
        studentProfileId = created.id
      }
    })

    // Trigger auto-enrollment if the new pathway requires it
    await triggerAutoEnrollmentIfRequired(studentProfileId!)

    await createAuditLog({
      action: 'USER_UPDATE',
      entity: 'student_profiles',
      entityId: id,
      userId: staff.id,
      details: {
        oldPathwayId: targetUser.studentProfile?.pathwayId,
        newPathwayId: pathway.id,
        newPathwayCode: pathwayCode,
      },
      description: `Admin updated study pathway to ${pathwayCode}. Reason: ${reason}`,
    })

    return NextResponse.json({
      success: true,
      pathwayCode,
      message: 'Pathway updated',
    })
  } catch (error: any) {
    console.error('Pathway override error:', error)
    return NextResponse.json({ error: 'Failed to update pathway' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { topUpWallet, adjustWallet, setWalletBalance, getOrCreateWallet } from '@/lib/wallet/operations'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { TransactionType } from '@prisma/client'
import { serializePrisma } from '@/lib/utils/serialization'

// GET /api/staff/students/[id]/wallet — View student wallet with full history
export const GET = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    await requireStaff()
    const id = context?.params?.id
    if (!id) return apiError('Student ID required')

    const { searchParams } = new URL(req.url)
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') || '50')))
    const offset = Math.max(0, parseInt(searchParams.get('offset') || '0'))
    const typeFilter = searchParams.get('type') as TransactionType | null

    const wallet = await prismaUnfiltered.wallet.findUnique({
      where: { userId: id },
    })

    if (!wallet) return apiNotFound('Wallet not found')

    const where: any = { walletId: wallet.id }
    if (typeFilter) where.type = typeFilter

    const [transactions, total] = await Promise.all([
      prismaUnfiltered.walletTransaction.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset,
      }),
      prismaUnfiltered.walletTransaction.count({ where }),
    ])

    // Get user info for context
    const user = await prismaUnfiltered.user.findUnique({
      where: { id },
      select: {
        email: true,
        personalEmail: true,
        academyEmail: true,
        profile: { select: { firstName: true, middleName: true, lastName: true } },
      },
    })

    // Resolve staff names for transactions with createdBy
    const staffIds = [...new Set(transactions.filter((t) => t.createdBy).map((t) => t.createdBy!))]
    const staffUsers =
      staffIds.length > 0
        ? await prismaUnfiltered.user.findMany({
            where: { id: { in: staffIds } },
            select: { id: true, profile: { select: { firstName: true, lastName: true } } },
          })
        : []
    const staffMap = Object.fromEntries(
      staffUsers.map((u) => [
        u.id,
        u.profile ? `${u.profile.firstName} ${u.profile.lastName}` : 'Staff',
      ])
    )

    // Check for linked payment proofs on staff transactions
    const txnIds = transactions.map((t) => t.id)
    const linkedPayments =
      txnIds.length > 0
        ? await prismaUnfiltered.payment.findMany({
            where: {
              OR: [
                { referenceId: { in: txnIds } },
                { referenceType: 'wallet_transaction_proof', referenceId: { in: txnIds } },
              ],
            },
            select: { referenceId: true, proofUrl: true },
          })
        : []
    const proofMap = Object.fromEntries(
      linkedPayments.filter((p) => p.proofUrl && p.referenceId).map((p) => [p.referenceId!, p.proofUrl!])
    )

    // Enrich transactions with staff names and proof URLs
    const enrichedTransactions = transactions.map((t) => ({
      ...t,
      staffName: t.createdBy ? staffMap[t.createdBy] || null : null,
      proofUrl: proofMap[t.id] || null,
    }))

    return apiSuccess(serializePrisma({
      wallet: {
        id: wallet.id,
        userId: wallet.userId,
        balance: wallet.balance,
        reservedBalance: wallet.reservedBalance,
        availableBalance: wallet.availableBalance,
        currency: wallet.currency,
        updatedAt: wallet.updatedAt,
      },
      user: user ? {
        email: user.academyEmail || user.email,
        personalEmail: user.personalEmail,
        name: user.profile
          ? `${user.profile.firstName} ${user.profile.middleName || ''} ${user.profile.lastName}`.replace(/\s+/g, ' ').trim()
          : user.email,
      } : null,
      transactions: enrichedTransactions,
      meta: { total, limit, offset },
    }))
  }
)

// POST /api/staff/students/[id]/wallet — Wallet operations
// Supports: top_up, credit, debit, adjustment, set_balance
export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const id = context?.params?.id
    if (!id) return apiError('Student ID required')

    const body = await req.json()
    const {
      action = 'top_up',
      amount,
      description,
      reference,
      referenceType,
      proofUrl,
      notes,
      targetBalance,
    } = body as {
      action?: 'top_up' | 'credit' | 'debit' | 'adjustment' | 'set_balance'
      amount?: number
      description?: string
      reference?: string
      referenceType?: string
      proofUrl?: string
      notes?: string
      targetBalance?: number
    }

    // Ensure wallet exists
    await getOrCreateWallet(id)

    let wallet
    let operationDescription: string

    switch (action) {
      case 'top_up': {
        if (!amount || amount <= 0) return apiError('Valid positive amount required for top-up')
        operationDescription = description || `Staff top-up: €${amount}`
        if (notes) operationDescription += ` — ${notes}`

        wallet = await prismaUnfiltered.$transaction(async (tx) => {
          return topUpWallet(tx, id, amount, operationDescription, reference, referenceType || 'staff_topup')
        })
        break
      }

      case 'credit': {
        if (!amount || amount <= 0) return apiError('Valid positive amount required for credit')
        operationDescription = description || `Staff credit: €${amount}`
        if (notes) operationDescription += ` — ${notes}`

        wallet = await prismaUnfiltered.$transaction(async (tx) => {
          return adjustWallet(tx, id, amount, operationDescription, reference, referenceType || 'staff_credit', staff.id)
        })
        break
      }

      case 'debit': {
        if (!amount || amount <= 0) return apiError('Valid positive amount required for debit')
        if (!description && !notes) return apiError('Description or notes required for debit operations')
        operationDescription = description || `Staff debit: €${amount}`
        if (notes) operationDescription += ` — ${notes}`

        wallet = await prismaUnfiltered.$transaction(async (tx) => {
          return adjustWallet(tx, id, -amount, operationDescription, reference, referenceType || 'staff_debit', staff.id)
        })
        break
      }

      case 'adjustment': {
        if (amount === undefined || amount === null) return apiError('Amount required for adjustment (positive=credit, negative=debit)')
        if (!description && !notes) return apiError('Description or notes required for adjustments')
        operationDescription = description || `Staff adjustment: €${amount}`
        if (notes) operationDescription += ` — ${notes}`

        wallet = await prismaUnfiltered.$transaction(async (tx) => {
          return adjustWallet(tx, id, amount, operationDescription, reference, referenceType || 'staff_adjustment', staff.id)
        })
        break
      }

      case 'set_balance': {
        if (targetBalance === undefined || targetBalance === null || targetBalance < 0) {
          return apiError('Valid non-negative targetBalance required')
        }
        if (!description && !notes) return apiError('Description or notes required for balance override')
        operationDescription = description || `Staff set balance to €${targetBalance}`
        if (notes) operationDescription += ` — ${notes}`

        wallet = await prismaUnfiltered.$transaction(async (tx) => {
          return setWalletBalance(tx, id, targetBalance, operationDescription, reference, referenceType || 'staff_set_balance', staff.id)
        })
        break
      }

      default:
        return apiError(`Unknown action: ${action}. Use top_up, credit, debit, adjustment, or set_balance.`)
    }

    // If proof of payment URL was provided, create a payment record
    if (proofUrl) {
      await prismaUnfiltered.payment.create({
        data: {
          userId: id,
          amount: Math.abs(amount || targetBalance || 0),
          currency: 'EUR',
          paymentMethod: 'STAFF_IMPORT',
          status: 'COMPLETED',
          proofUrl,
          proofUploadedAt: new Date(),
          referenceType: referenceType || `staff_wallet_${action}`,
          referenceId: reference,
          approvedAt: new Date(),
          approvedBy: staff.id,
          notes: operationDescription,
        },
      })
    }

    await createAuditLog({
      action: AuditAction.WALLET_TOP_UP,
      entity: 'Wallet',
      entityId: wallet.id,
      userId: staff.id,
      description: operationDescription,
      changes: {
        targetUserId: id,
        action,
        amount: amount || targetBalance,
        reference,
        proofUrl: proofUrl || null,
        notes,
      },
    })

    // Notify the student about the wallet adjustment
    const actionLabels: Record<string, string> = {
      top_up: 'Top-Up',
      credit: 'Credit',
      debit: 'Debit',
      adjustment: 'Adjustment',
      set_balance: 'Balance Update',
    }
    const actionLabel = actionLabels[action] || 'Update'
    const adjustmentAmount = amount || targetBalance || 0

    await prismaUnfiltered.notification.create({
      data: {
        userId: id,
        title: `Wallet ${actionLabel}`,
        message: operationDescription,
        type: 'WALLET_ADJUSTMENT',
        linkUrl: '/student/wallet',
        linkText: 'View Wallet',
      },
    })

    return apiSuccess(serializePrisma({
      message: operationDescription,
      wallet: {
        id: wallet.id,
        balance: wallet.balance,
        reservedBalance: wallet.reservedBalance,
        availableBalance: wallet.availableBalance,
        currency: wallet.currency,
      },
    }))
  }
)

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import {
  requireStaff,
  hashPassword,
  generateAcademyEmail,
  generateStudentId,
} from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { topUpWallet } from '@/lib/wallet/operations'
import {
  EnrollmentType,
  EnrollmentStatus,
  ProgrammeChoice,
  UserRole,
  UserStatus,
  TransactionType,
  BookingType,
  PaymentStatus,
  FundingSource,
} from '@prisma/client'
import crypto from 'crypto'

// ---------------------------------------------------------------------------
// TYPES
// ---------------------------------------------------------------------------

interface ImportStudent {
  // Core fields
  email: string
  firstName: string
  lastName: string
  middleName?: string
  phone?: string

  // Pathway & programme
  enrollmentType?: string // FULL_TIME, MODULAR, EXAM_ONLY, SHORT_COURSE
  programmeChoice?: string // FULL_TIME_4YEAR, FULL_TIME_2YEAR, MILITARY_1YEAR, MODULAR, EXAM_ONLY
  selectedLicenseCategories?: string[] // e.g. ['B1.1', 'B2']

  // Academy email override (if admin wants a specific one)
  academyEmail?: string

  // Wallet
  walletCreditEur?: number
  walletNotes?: string

  // Completed modules from elsewhere (module codes like M1, M2, etc.)
  completedModules?: CompletedModuleEntry[]

  // Exam history (for candidates with prior exam sittings)
  examHistory?: ExamHistoryEntry[]

  // Free resit entitlements
  entitlements?: EntitlementEntry[]

  // Planned upcoming bookings
  plannedBookings?: PlannedBookingEntry[]

  // Admin notes
  notes?: string

  // Scholarship / status
  fundingSource?: 'SELF_FUNDED' | 'SCHOLARSHIP' | 'SPONSORED'
  enrollmentStatus?: string // ACTIVE, DEFERRED, WITHDRAWN, SUSPENDED, ENROLLED
  currentYearNumber?: number
  currentSemesterNumber?: number

  // Semester-by-semester course enrollments
  semesterEnrollments?: SemesterEnrollmentEntry[]
}

interface CompletedModuleEntry {
  moduleCode: string
  result: 'pass' | 'fail'
  completedAt?: string // ISO date string
  institution?: string // where they completed it
  sourceNotes?: string
}

interface ExamHistoryEntry {
  sittingLabel: string
  moduleCode: string
  bookingGroupRef: string
  bookingType: string // twin, single, quad, etc.
  attemptType: 'first_attempt' | 'resit'
  result: 'pass' | 'fail'
  score?: number
  percentage?: number
  examDate?: string // ISO date string
  academicYearName?: string // e.g. "2024/2025" — links exam to semester
  semesterName?: string // e.g. "Semester 1"
  sourceNotes?: string
}

interface SemesterEnrollmentEntry {
  academicYearName: string // e.g. "2024/2025"
  semesterName: string // e.g. "Semester 1"
  yearNumber: number // 1, 2, 3, 4
  semesterNumber: number // 1 or 2
  courseCodes: string[] // e.g. ["M1", "M2", "M3"]
  status?: string // "COMPLETED" | "ACTIVE" | "FAILED"
}

interface EntitlementEntry {
  bookingGroupRef: string
  bookingType: string
  includedFreeResits: number
  usedFreeResits: number
  transferable: boolean
  notes?: string
}

interface PlannedBookingEntry {
  moduleCode: string
  bookingGroupRef: string
  bookingType: string
  paymentStatus: 'paid' | 'unpaid'
  sourceNotes?: string
}

// ---------------------------------------------------------------------------
// HELPERS
// ---------------------------------------------------------------------------

function generateSecurePassword(): string {
  const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ'
  const lower = 'abcdefghjkmnpqrstuvwxyz'
  const digits = '23456789'
  const special = '!@#$%&*'
  const all = upper + lower + digits + special
  const pick = (chars: string) => chars[crypto.randomInt(chars.length)]
  const parts = [pick(upper), pick(lower), pick(digits), pick(special)]
  for (let i = 4; i < 12; i++) parts.push(pick(all))
  for (let i = parts.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1)
    ;[parts[i], parts[j]] = [parts[j], parts[i]]
  }
  return parts.join('')
}

function resolveEnrollmentType(programme: string | undefined): EnrollmentType {
  switch (programme) {
    case 'FULL_TIME_4YEAR':
    case 'FULL_TIME_2YEAR':
    case 'MILITARY_1YEAR':
      return EnrollmentType.FULL_TIME
    case 'MODULAR':
      return EnrollmentType.MODULAR
    case 'EXAM_ONLY':
      return EnrollmentType.EXAM_ONLY
    case 'SHORT_COURSE':
      return EnrollmentType.SHORT_COURSE
    default:
      return EnrollmentType.MODULAR
  }
}

function mapEnrollmentStatusToUserStatus(enrollmentStatus: string | undefined): UserStatus {
  switch (enrollmentStatus) {
    case 'SUSPENDED':
      return UserStatus.SUSPENDED
    case 'WITHDRAWN':
    case 'EXPELLED':
      return UserStatus.ARCHIVED
    default:
      return UserStatus.ACTIVE // ACTIVE, DEFERRED, ENROLLED, APPROVED, GRADUATED
  }
}

function mapProgrammeToPathwayCode(choice: string | undefined): string {
  const map: Record<string, string> = {
    FULL_TIME_4YEAR: 'FULL_TIME_4Y',
    FULL_TIME_2YEAR: 'FULL_TIME_2Y',
    MILITARY_1YEAR: 'MILITARY_1Y',
    MODULAR: 'MODULAR',
    EXAM_ONLY: 'EXAM_ONLY',
  }
  return map[choice || ''] || 'MODULAR'
}

// ---------------------------------------------------------------------------
// POST /api/staff/students/import — Enhanced bulk import
// ---------------------------------------------------------------------------

export const POST = withErrorHandler(async (req: NextRequest) => {
  const staff = await requireStaff()
  const body = await req.json()
  const { students, migrationRef: customRef } = body as {
    students: ImportStudent[]
    migrationRef?: string
  }

  if (!Array.isArray(students) || students.length === 0) {
    return apiError('Students array is required')
  }

  const migrationRef = customRef || `STAFF_IMPORT_${Date.now()}`

  const results = {
    created: 0,
    updated: 0,
    skipped: 0,
    errors: [] as string[],
    credentials: [] as {
      firstName: string
      lastName: string
      personalEmail: string
      academyEmail: string
      temporaryPassword: string
      walletBalanceEur: number
      studentId: string
      enrollmentType: string
      fundingSource: string
      enrollmentStatus: string
      notes: string
    }[],
  }

  for (const s of students) {
    try {
      // --- Validation ---
      if (!s.email || !s.firstName || !s.lastName) {
        results.errors.push(`Missing required fields for ${s.email || 'unknown'}`)
        results.skipped++
        continue
      }

      // --- Dedupe check: look up by personal email, academy email, or main email ---
      const existingUser = await prismaUnfiltered.user.findFirst({
        where: {
          OR: [
            { email: s.email },
            { personalEmail: s.email },
            ...(s.academyEmail ? [{ academyEmail: s.academyEmail }] : []),
          ],
        },
        include: { profile: true, wallet: true, studentProfile: true },
      })

      const tempPassword = generateSecurePassword()
      const hashedPassword = await hashPassword(tempPassword)

      // Resolve pathway
      const programmeChoice = (s.programmeChoice || s.enrollmentType || 'EXAM_ONLY') as string
      const enrollmentType = s.enrollmentType
        ? (s.enrollmentType as EnrollmentType)
        : resolveEnrollmentType(programmeChoice)
      const pathwayCode = mapProgrammeToPathwayCode(programmeChoice)

      let userId: string
      let finalAcademyEmail: string
      let finalStudentId: string

      if (!existingUser) {
        // ===================== CREATE NEW USER =====================
        const academyEmail =
          s.academyEmail || (await generateAcademyEmail(s.firstName, s.middleName, s.lastName))
        const studentId = await generateStudentId()

        // Look up pathway for linking
        const pathway = await prismaUnfiltered.studyPathwayModel.findUnique({
          where: { code: pathwayCode },
        })

        const user = await prismaUnfiltered.$transaction(async (tx) => {
          const newUser = await tx.user.create({
            data: {
              email: academyEmail,
              personalEmail: s.email,
              academyEmail,
              password: hashedPassword,
              role: UserRole.STUDENT,
              status: mapEnrollmentStatusToUserStatus(s.enrollmentStatus),
              programmeChoice: Object.values(ProgrammeChoice).includes(
                programmeChoice as ProgrammeChoice
              )
                ? (programmeChoice as ProgrammeChoice)
                : ProgrammeChoice.EXAM_ONLY,
              selectedLicenseCategories: s.selectedLicenseCategories || [],
              mustChangePassword: true,
              passwordChanged: false,
              emailVerified: new Date(),
              registrationPaid: true,
              registrationFee: 0,
            },
          })

          await tx.profile.create({
            data: {
              userId: newUser.id,
              firstName: s.firstName,
              lastName: s.lastName,
              middleName: s.middleName,
              phone: s.phone,
            },
          })

          const resolvedEnrollmentStatus = Object.values(EnrollmentStatus).includes(
            s.enrollmentStatus as EnrollmentStatus
          )
            ? (s.enrollmentStatus as EnrollmentStatus)
            : EnrollmentStatus.ENROLLED
          const resolvedFundingSource = Object.values(FundingSource).includes(
            s.fundingSource as unknown as FundingSource
          )
            ? (s.fundingSource as unknown as FundingSource)
            : FundingSource.SELF_FUNDED

          await tx.studentProfile.create({
            data: {
              userId: newUser.id,
              studentId,
              enrollmentType,
              programmeChoice: Object.values(ProgrammeChoice).includes(
                programmeChoice as ProgrammeChoice
              )
                ? (programmeChoice as ProgrammeChoice)
                : ProgrammeChoice.EXAM_ONLY,
              enrollmentStatus: resolvedEnrollmentStatus,
              fundingSource: resolvedFundingSource,
              pathwayId: pathway?.id ?? null,
              currentYearNumber: s.currentYearNumber || 1,
              currentSemesterNumber: s.currentSemesterNumber || 1,
            },
          })

          await tx.wallet.create({
            data: {
              userId: newUser.id,
              balance: 0,
              reservedBalance: 0,
              availableBalance: 0,
              currency: 'EUR',
            },
          })

          // Link license targets if provided
          if (s.selectedLicenseCategories && s.selectedLicenseCategories.length > 0) {
            const sp = await tx.studentProfile.findUnique({ where: { userId: newUser.id } })
            if (sp) {
              const licenseCats = await tx.licenseCategory.findMany({
                where: { code: { in: s.selectedLicenseCategories } },
              })
              if (licenseCats.length > 0) {
                await tx.studentLicenseTarget.createMany({
                  data: licenseCats.map((lc) => ({
                    studentProfileId: sp.id,
                    licenseCategoryId: lc.id,
                  })),
                  skipDuplicates: true,
                })
              }
            }
          }

          return newUser
        })

        userId = user.id
        finalAcademyEmail = academyEmail
        finalStudentId = studentId
        results.created++
      } else {
        // ===================== UPDATE EXISTING USER =====================
        const academyEmail =
          s.academyEmail ||
          existingUser.academyEmail ||
          (await generateAcademyEmail(s.firstName, s.middleName, s.lastName))
        const pathway = await prismaUnfiltered.studyPathwayModel.findUnique({
          where: { code: pathwayCode },
        })

        await prismaUnfiltered.user.update({
          where: { id: existingUser.id },
          data: {
            email: academyEmail,
            personalEmail: s.email,
            academyEmail,
            password: hashedPassword,
            role: UserRole.STUDENT,
            status: mapEnrollmentStatusToUserStatus(s.enrollmentStatus),
            programmeChoice: Object.values(ProgrammeChoice).includes(
              programmeChoice as ProgrammeChoice
            )
              ? (programmeChoice as ProgrammeChoice)
              : existingUser.programmeChoice,
            selectedLicenseCategories:
              s.selectedLicenseCategories || existingUser.selectedLicenseCategories,
            mustChangePassword: true,
            passwordChanged: false,
            emailVerified: existingUser.emailVerified || new Date(),
            registrationPaid: true,
          },
        })

        // Ensure profile
        if (existingUser.profile) {
          await prismaUnfiltered.profile.update({
            where: { userId: existingUser.id },
            data: {
              firstName: s.firstName,
              lastName: s.lastName,
              middleName: s.middleName,
              ...(s.phone && { phone: s.phone }),
            },
          })
        } else {
          await prismaUnfiltered.profile.create({
            data: {
              userId: existingUser.id,
              firstName: s.firstName,
              lastName: s.lastName,
              middleName: s.middleName,
              phone: s.phone,
            },
          })
        }

        // Ensure student profile
        const resolvedEnrollmentStatus = Object.values(EnrollmentStatus).includes(
          s.enrollmentStatus as EnrollmentStatus
        )
          ? (s.enrollmentStatus as EnrollmentStatus)
          : undefined
        const resolvedFundingSource = Object.values(FundingSource).includes(
          s.fundingSource as unknown as FundingSource
        )
          ? (s.fundingSource as unknown as FundingSource)
          : undefined

        if (!existingUser.studentProfile) {
          const studentId = await generateStudentId()
          await prismaUnfiltered.studentProfile.create({
            data: {
              userId: existingUser.id,
              studentId,
              enrollmentType,
              programmeChoice: Object.values(ProgrammeChoice).includes(
                programmeChoice as ProgrammeChoice
              )
                ? (programmeChoice as ProgrammeChoice)
                : ProgrammeChoice.EXAM_ONLY,
              enrollmentStatus: resolvedEnrollmentStatus || EnrollmentStatus.ENROLLED,
              fundingSource: resolvedFundingSource || FundingSource.SELF_FUNDED,
              pathwayId: pathway?.id ?? null,
              currentYearNumber: s.currentYearNumber || 1,
              currentSemesterNumber: s.currentSemesterNumber || 1,
            },
          })
          finalStudentId = studentId
        } else {
          // Update existing student profile
          await prismaUnfiltered.studentProfile.update({
            where: { userId: existingUser.id },
            data: {
              enrollmentType,
              ...(pathway && { pathwayId: pathway.id }),
              ...(Object.values(ProgrammeChoice).includes(programmeChoice as ProgrammeChoice) && {
                programmeChoice: programmeChoice as ProgrammeChoice,
              }),
              ...(resolvedEnrollmentStatus && { enrollmentStatus: resolvedEnrollmentStatus }),
              ...(resolvedFundingSource && { fundingSource: resolvedFundingSource }),
              ...(s.currentYearNumber && { currentYearNumber: s.currentYearNumber }),
              ...(s.currentSemesterNumber && { currentSemesterNumber: s.currentSemesterNumber }),
            },
          })
          finalStudentId = existingUser.studentProfile.studentId
        }

        // Ensure wallet
        if (!existingUser.wallet) {
          await prismaUnfiltered.wallet.create({
            data: {
              userId: existingUser.id,
              balance: 0,
              reservedBalance: 0,
              availableBalance: 0,
              currency: 'EUR',
            },
          })
        }

        userId = existingUser.id
        finalAcademyEmail = academyEmail
        results.updated++
      }

      // ===================== WALLET CREDIT =====================
      if (s.walletCreditEur && s.walletCreditEur > 0) {
        await prismaUnfiltered.$transaction(async (tx) => {
          // Idempotent: check if this migration credit was already applied
          const wallet = await tx.wallet.findUnique({ where: { userId } })
          if (!wallet) return

          const alreadyApplied = await tx.walletTransaction.findFirst({
            where: {
              walletId: wallet.id,
              referenceType: 'staff_import',
              referenceId: migrationRef,
            },
          })

          if (!alreadyApplied) {
            await topUpWallet(
              tx,
              userId,
              s.walletCreditEur!,
              `Staff import: wallet credit €${s.walletCreditEur}. ${s.walletNotes || ''}`.trim(),
              migrationRef,
              'staff_import'
            )
          }
        })
      }

      // ===================== COMPLETED MODULES =====================
      if (s.completedModules && s.completedModules.length > 0) {
        for (const mod of s.completedModules) {
          const migRef = `${migrationRef}:COMPLETED:${mod.moduleCode}`

          const existing = await prismaUnfiltered.examBooking.findFirst({
            where: { userId, migrationRef: migRef },
          })

          if (!existing) {
            await prismaUnfiltered.examBooking.create({
              data: {
                userId,
                bookingType: BookingType.INDIVIDUAL,
                moduleCode: mod.moduleCode,
                amountPaid: 0,
                status: PaymentStatus.COMPLETED,
                attemptType: 'first_attempt',
                result: mod.result,
                sourceNotes:
                  `[Import] Completed elsewhere${mod.institution ? ` at ${mod.institution}` : ''}. ${mod.sourceNotes || ''}`.trim(),
                migrationRef: migRef,
                ...(mod.completedAt && { bookedAt: new Date(mod.completedAt) }),
              },
            })
          }
        }
      }

      // ===================== EXAM HISTORY =====================
      if (s.examHistory && s.examHistory.length > 0) {
        for (const entry of s.examHistory) {
          const migRef = `${migrationRef}:${entry.bookingGroupRef}:${entry.moduleCode}:${entry.attemptType}`

          const existing = await prismaUnfiltered.examBooking.findFirst({
            where: { userId, migrationRef: migRef },
          })

          if (!existing) {
            await prismaUnfiltered.examBooking.create({
              data: {
                userId,
                bookingType: BookingType.BUNDLE,
                moduleCode: entry.moduleCode,
                amountPaid: 0,
                status: PaymentStatus.COMPLETED,
                bookingGroupRef: entry.bookingGroupRef,
                attemptType: entry.attemptType,
                result: entry.result,
                ...(entry.score != null && { score: entry.score }),
                ...(entry.percentage != null && { percentage: entry.percentage }),
                ...(entry.examDate && { examDate: new Date(entry.examDate) }),
                sourceNotes: `[Import] ${entry.sittingLabel}. ${entry.sourceNotes || ''}`.trim(),
                migrationRef: migRef,
              },
            })
          }
        }
      }

      // ===================== ENTITLEMENTS =====================
      if (s.entitlements && s.entitlements.length > 0) {
        for (const ent of s.entitlements) {
          await prismaUnfiltered.bookingEntitlement.upsert({
            where: {
              userId_bookingGroupRef: {
                userId,
                bookingGroupRef: ent.bookingGroupRef,
              },
            },
            update: {
              includedFreeResits: ent.includedFreeResits,
              usedFreeResits: ent.usedFreeResits,
              transferable: ent.transferable,
              notes: ent.notes ? `[Import] ${ent.notes}` : undefined,
            },
            create: {
              userId,
              bookingGroupRef: ent.bookingGroupRef,
              bookingType: ent.bookingType,
              includedFreeResits: ent.includedFreeResits,
              usedFreeResits: ent.usedFreeResits,
              transferable: ent.transferable,
              notes: ent.notes ? `[Import] ${ent.notes}` : undefined,
            },
          })
        }
      }

      // ===================== PLANNED BOOKINGS =====================
      if (s.plannedBookings && s.plannedBookings.length > 0) {
        for (const planned of s.plannedBookings) {
          const migRef = `${migrationRef}:PLANNED:${planned.bookingGroupRef}:${planned.moduleCode}`

          const existing = await prismaUnfiltered.examBooking.findFirst({
            where: { userId, migrationRef: migRef },
          })

          if (!existing) {
            await prismaUnfiltered.examBooking.create({
              data: {
                userId,
                bookingType: BookingType.BUNDLE,
                moduleCode: planned.moduleCode,
                amountPaid: 0,
                status:
                  planned.paymentStatus === 'paid'
                    ? PaymentStatus.COMPLETED
                    : PaymentStatus.PENDING,
                bookingGroupRef: planned.bookingGroupRef,
                attemptType: 'first_attempt',
                result: 'pending',
                sourceNotes: `[Import] Planned. ${planned.sourceNotes || ''}`.trim(),
                migrationRef: migRef,
              },
            })
          }
        }
      }

      // ===================== FULL-TIME ENROLLMENT =====================
      if (
        programmeChoice === 'FULL_TIME_4YEAR' ||
        programmeChoice === 'FULL_TIME_2YEAR' ||
        programmeChoice === 'MILITARY_1YEAR'
      ) {
        const ftCodeMap: Record<string, string> = {
          FULL_TIME_4YEAR: 'FT4Y',
          FULL_TIME_2YEAR: 'FT2Y',
          MILITARY_1YEAR: 'MIL1Y',
        }
        const ftProgramme = await prismaUnfiltered.fullTimeProgramme.findFirst({
          where: { code: ftCodeMap[programmeChoice] },
          include: { programmeYears: { orderBy: { yearNumber: 'asc' } } },
        })

        if (ftProgramme) {
          const currentYear = s.currentYearNumber || 1
          const targetProgrammeYear =
            ftProgramme.programmeYears.find((py) => py.yearNumber === currentYear) ||
            ftProgramme.programmeYears[0]

          if (targetProgrammeYear) {
            await prismaUnfiltered.fullTimeEnrollment.upsert({
              where: {
                studentId_programmeId: {
                  studentId: userId,
                  programmeId: ftProgramme.id,
                },
              },
              update: {
                currentYearNumber: currentYear,
                programmeYearId: targetProgrammeYear.id,
              },
              create: {
                studentId: userId,
                programmeId: ftProgramme.id,
                programmeYearId: targetProgrammeYear.id,
                currentYearNumber: currentYear,
                status: 'ACTIVE',
                startDate: new Date(),
              },
            })
          }
        }
      }

      // ===================== SEMESTER ENROLLMENTS =====================
      if (s.semesterEnrollments && s.semesterEnrollments.length > 0) {
        for (const sem of s.semesterEnrollments) {
          // Look up academic year
          const academicYear = await prismaUnfiltered.academicYear.findFirst({
            where: { name: sem.academicYearName },
          })
          if (!academicYear) continue // Skip if academic year not configured

          // Look up semester
          const semester = await prismaUnfiltered.semester.findFirst({
            where: {
              name: sem.semesterName,
              academicYearId: academicYear.id,
            },
          })
          if (!semester) continue // Skip if semester not configured

          // Create enrollment for each course
          for (const courseCode of sem.courseCodes) {
            const course = await prismaUnfiltered.course.findFirst({
              where: { code: courseCode },
            })
            if (!course) continue

            const isCompleted = sem.status === 'COMPLETED'
            const enrollmentStatus: EnrollmentStatus = isCompleted
              ? EnrollmentStatus.ENROLLED
              : (sem.status as EnrollmentStatus) || EnrollmentStatus.ACTIVE

            // Use createMany-style idempotency: check first
            const existingEnrollment = await prismaUnfiltered.enrollment.findFirst({
              where: {
                userId,
                courseId: course.id,
                semesterId: semester.id,
              },
            })

            if (!existingEnrollment) {
              await prismaUnfiltered.enrollment.create({
                data: {
                  userId,
                  courseId: course.id,
                  academicYearId: academicYear.id,
                  semesterId: semester.id,
                  status: enrollmentStatus,
                  amountPaid: course.price,
                  enrolledAt: academicYear.startDate,
                  completedAt: isCompleted ? semester.endDate : null,
                },
              })
            }
          }
        }
      }

      // ===================== AUDIT =====================
      await createAuditLog({
        action: AuditAction.IMPORT,
        entity: 'users',
        entityId: userId,
        userId: staff.id,
        description: `Staff imported student: ${s.firstName} ${s.lastName} (${s.email})`,
        changes: {
          migrationRef,
          isNew: !existingUser,
          enrollmentType: enrollmentType,
          programmeChoice,
          walletCreditEur: s.walletCreditEur || 0,
          completedModulesCount: s.completedModules?.length || 0,
          examHistoryCount: s.examHistory?.length || 0,
          plannedBookingsCount: s.plannedBookings?.length || 0,
        },
      })

      // Fetch final wallet balance
      const finalWallet = await prismaUnfiltered.wallet.findUnique({ where: { userId } })

      results.credentials.push({
        firstName: s.firstName,
        lastName: s.lastName,
        personalEmail: s.email,
        academyEmail: finalAcademyEmail,
        temporaryPassword: tempPassword,
        walletBalanceEur: finalWallet?.balance.toNumber() || 0,
        studentId: finalStudentId,
        enrollmentType: enrollmentType,
        fundingSource: s.fundingSource || 'SELF_FUNDED',
        enrollmentStatus: s.enrollmentStatus || 'ENROLLED',
        notes: s.notes || '',
      })
    } catch (error: any) {
      results.errors.push(`${s.email}: ${error.message}`)
      results.skipped++
    }
  }

  await createAuditLog({
    action: AuditAction.IMPORT,
    entity: 'StudentBulkImport',
    userId: staff.id,
    description: `Bulk student import: ${results.created} created, ${results.updated} updated, ${results.skipped} skipped`,
    changes: {
      migrationRef,
      total: students.length,
      created: results.created,
      updated: results.updated,
      skipped: results.skipped,
      errorCount: results.errors.length,
    },
  })

  return apiSuccess({
    migrationRef,
    summary: {
      total: students.length,
      created: results.created,
      updated: results.updated,
      skipped: results.skipped,
      errors: results.errors.length,
    },
    credentials: results.credentials.map(({ temporaryPassword, ...rest }) => rest),
    errors: results.errors,
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { apiPaginated } from '@/lib/api/response'

export async function GET(req: NextRequest) {
  const session = await getAuthSession()
  if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { searchParams } = new URL(req.url)
  const status = searchParams.get('status') || 'all'
  const search = searchParams.get('search') || ''
  const page = parseInt(searchParams.get('page') || '1')
  const limit = parseInt(searchParams.get('limit') || '20')

  const where: any = { role: 'STUDENT' }

  if (status === 'all') {
    where.status = { notIn: ['ARCHIVED', 'DELETED'] }
  } else if (status === 'active') where.status = 'ACTIVE'
  else if (status === 'suspended') where.status = 'SUSPENDED'
  else if (status === 'archived') where.status = 'ARCHIVED'

  if (search) {
    where.OR = [
      { email: { contains: search, mode: 'insensitive' } },
      { profile: { firstName: { contains: search, mode: 'insensitive' } } },
      { profile: { lastName: { contains: search, mode: 'insensitive' } } },
      { studentProfile: { studentId: { contains: search, mode: 'insensitive' } } },
    ]
  }

  const [students, total] = await Promise.all([
    prismaUnfiltered.user.findMany({
      where,
      include: {
        profile: true,
        studentProfile: true,
        wallet: { select: { availableBalance: true, balance: true, currency: true } },
        enrollments: {
          include: { course: { select: { code: true, name: true } } },
          take: 3,
        },
      },
      orderBy: { createdAt: 'desc' },
      skip: (page - 1) * limit,
      take: limit,
    }),
    prismaUnfiltered.user.count({ where }),
  ])

  return apiPaginated(students, total, page, limit)
}

import { NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import prisma, { prismaUnfiltered } from '@/lib/prisma/client'

const STAFF_ROLES = ['SUPER_ADMIN', 'ADMIN', 'STAFF']

export async function GET() {
  try {
    const session = await getAuthSession()
    if (!session || !STAFF_ROLES.includes(session.user.role)) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = session.user.id

    const [notifications, messages, recentApplicants, recentPayments, recentEnrollments] =
      await Promise.all([
        prismaUnfiltered.notification.findMany({
          where: { userId },
          orderBy: { createdAt: 'desc' },
          take: 5,
          select: {
            id: true,
            title: true,
            message: true,
            type: true,
            isRead: true,
            createdAt: true,
            linkUrl: true,
          },
        }),
        prismaUnfiltered.message.findMany({
          where: { recipientId: userId },
          orderBy: { createdAt: 'desc' },
          take: 5,
          select: {
            id: true,
            subject: true,
            body: true,
            isRead: true,
            createdAt: true,
            sender: {
              select: {
                email: true,
                profile: { select: { firstName: true, lastName: true } },
              },
            },
          },
        }),
        prismaUnfiltered.user.findMany({
          where: { role: 'APPLICANT', status: 'PENDING' },
          orderBy: { createdAt: 'desc' },
          take: 3,
          select: {
            id: true,
            email: true,
            createdAt: true,
            profile: { select: { firstName: true, lastName: true } },
          },
        }),
        prismaUnfiltered.payment.findMany({
          where: { status: 'PENDING' },
          orderBy: { createdAt: 'desc' },
          take: 3,
          select: {
            id: true,
            amount: true,
            currency: true,
            createdAt: true,
            user: {
              select: {
                email: true,
                profile: { select: { firstName: true, lastName: true } },
              },
            },
          },
        }),
        prismaUnfiltered.enrollment.findMany({
          where: { status: 'PENDING' },
          orderBy: { createdAt: 'desc' },
          take: 3,
          select: {
            id: true,
            createdAt: true,
            user: {
              select: {
                email: true,
                profile: { select: { firstName: true, lastName: true } },
              },
            },
            course: { select: { name: true, code: true } },
          },
        }),
      ])

    const transformedMessages = messages.map((msg) => ({
      ...msg,
      sender: {
        name: msg.sender.profile
          ? `${msg.sender.profile.firstName} ${msg.sender.profile.lastName}`
          : null,
        email: msg.sender.email,
      },
    }))

    const pendingItems = {
      applicants: recentApplicants.map((a) => ({
        id: a.id,
        name: a.profile ? `${a.profile.firstName} ${a.profile.lastName}` : null,
        email: a.email,
        createdAt: a.createdAt,
      })),
      payments: recentPayments.map((p) => ({
        id: p.id,
        userName: p.user.profile
          ? `${p.user.profile.firstName} ${p.user.profile.lastName}`
          : p.user.email,
        amount: Number(p.amount),
        currency: p.currency,
        createdAt: p.createdAt,
      })),
      enrollments: recentEnrollments.map((e) => ({
        id: e.id,
        userName: e.user.profile
          ? `${e.user.profile.firstName} ${e.user.profile.lastName}`
          : e.user.email,
        courseName: e.course.name,
        createdAt: e.createdAt,
      })),
    }

    return NextResponse.json({
      notifications,
      messages: transformedMessages,
      pendingItems,
    })
  } catch (error) {
    console.error('Staff topbar items error:', error)
    return NextResponse.json({
      notifications: [],
      messages: [],
      pendingItems: { applicants: [], payments: [], enrollments: [] },
    })
  }
}

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'
import { createAuditLog } from '@/lib/audit/logger'
import { UserRole } from '@prisma/client'

export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const session = await getAuthSession()
    if (!session || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
      return apiError('Unauthorized', 401)
    }
    const staff = session.user
    const id = context?.params?.id
    if (!id) return apiError('User ID required')

    const user = await prismaUnfiltered.user.findUnique({ where: { id } })
    if (!user) return apiNotFound('User not found')

    const updated = await prismaUnfiltered.user.update({
      where: { id },
      data: { status: 'ACTIVE' },
    })

    await createAuditLog({
      action: 'ACTIVATE_USER',
      entity: 'User',
      entityId: id,
      userId: staff.id,
      description: `User ${user.email} activated by staff`,
      changes: { status: 'ACTIVE', previousStatus: user.status },
    })

    return apiSuccess(updated)
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { requirePermission } from '@/lib/auth/permissions'
import { ADDITIONAL_PERMISSION_KEYS } from '@/lib/auth/permission-registry'
import { buildUserDataExport } from '@/lib/gdpr/export'
import { createAuditLog } from '@/lib/audit/logger'

export async function GET(
  _req: NextRequest,
  ctx: { params: Promise<{ id: string }> }
) {
  let actor
  try {
    actor = await requirePermission(ADDITIONAL_PERMISSION_KEYS.MANAGE_GDPR)
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: err.message === 'Unauthorized' ? 401 : 403 })
  }
  const { id } = await ctx.params

  try {
    const data = await buildUserDataExport(id)
    await createAuditLog({
      userId: actor.id,
      action: 'EXPORT',
      entity: 'User',
      entityId: id,
      description: 'GDPR Article 15 export',
    })
    return new NextResponse(JSON.stringify(data, null, 2), {
      headers: {
        'Content-Type': 'application/json; charset=utf-8',
        'Content-Disposition': `attachment; filename="gdpr-export-${id}.json"`,
      },
    })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff, hashPassword, generateToken, generateTempPassword } from '@/lib/auth/helpers'
import { sendActivationEmail, sendStudentPromotionEmail } from '@/lib/email/service'
import { createAuditLog } from '@/lib/audit/logger'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'

/**
 * POST /api/staff/users/[id]/resend-credentials
 *
 * Resets and resends login credentials to a user.
 */
export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const id = context?.params?.id
    if (!id) return apiError('User ID required')

    const user = await prismaUnfiltered.user.findUnique({
      where: { id },
      include: { profile: true, studentProfile: true },
    })

    if (!user) return apiNotFound('User not found')
    if (!user.profile) return apiError('User profile not found')

    // 1. Generate new temporary credentials
    const tempPassword = generateTempPassword()
    const hashedPassword = await hashPassword(tempPassword)
    const verifyToken = generateToken()
    const verifyTokenExpires = new Date(Date.now() + 24 * 60 * 60 * 1000)

    // 2. Update user in database
    await prismaUnfiltered.user.update({
      where: { id },
      data: {
        password: hashedPassword,
        verifyToken,
        verifyTokenExpires,
        mustChangePassword: true,
      },
    })

    // 3. Determine target emails
    const personalEmail = user.personalEmail || user.email
    const academyEmail = user.academyEmail
    const firstName = user.profile.firstName

    // 4. Send Activation Emails (credentials)
    const sendPromises = []

    // Always send to the main contact email (usually personal)
    sendPromises.push(
      sendActivationEmail(
        personalEmail,
        firstName,
        academyEmail || personalEmail,
        tempPassword,
        verifyToken
      ).catch((err) => console.error(`Failed to send activation to ${personalEmail}:`, err))
    )

    // 5. If User is a STUDENT, also resend their Student ID (Promotion Email)
    if (user.role === 'STUDENT' && user.studentProfile?.studentId) {
      const studentId = user.studentProfile.studentId

      sendPromises.push(
        sendStudentPromotionEmail(personalEmail, firstName, studentId).catch((err) =>
          console.error(`Failed to send promotion to ${personalEmail}:`, err)
        )
      )
    }

    await Promise.all(sendPromises)

    // 6. Log the action
    await createAuditLog({
      action: 'SYSTEM_UPDATE',
      entity: 'User',
      entityId: id,
      userId: staff.id,
      description: `Resent login credentials to ${personalEmail}${academyEmail ? ` and ${academyEmail}` : ''}. Password reset and token generated.`,
    })

    return apiSuccess({ message: 'Credentials resent successfully' })
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff, generateToken } from '@/lib/auth/helpers'
import { sendEmailVerificationEmail, sendActivationEmail } from '@/lib/email/service'
import { createAuditLog } from '@/lib/audit/logger'
import { apiSuccess, apiError, apiNotFound, withErrorHandler } from '@/lib/api/response'

/**
 * POST /api/staff/users/[id]/resend-verification
 *
 * Resends the verification or activation email to a user.
 */
export const POST = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const staff = await requireStaff()
    const id = context?.params?.id
    if (!id) return apiError('User ID required')

    const user = await prismaUnfiltered.user.findUnique({
      where: { id },
      include: { profile: true },
    })

    if (!user) return apiNotFound('User not found')
    if (!user.profile) return apiError('User profile not found')

    if (user.emailVerified) {
      return apiError('Email is already verified')
    }

    // 1. Generate new verification token
    const verifyToken = generateToken()
    const verifyTokenExpires = new Date(Date.now() + 24 * 60 * 60 * 1000) // 24 hours

    // 2. Update user in database
    await prismaUnfiltered.user.update({
      where: { id },
      data: {
        verifyToken,
        verifyTokenExpires,
      },
    })

    const firstName = user.profile.firstName
    const personalEmail = user.personalEmail || user.email

    // 3. Send appropriate email
    if (user.password) {
      // Post-approval user: has credentials, send activation email
      await sendActivationEmail(
        personalEmail,
        firstName,
        user.academyEmail || personalEmail,
        '(use your existing password)',
        verifyToken
      )
    } else {
      // Pre-approval user: no credentials yet, send simple verification email
      await sendEmailVerificationEmail(personalEmail, firstName, verifyToken)
    }

    // 4. Log the action
    await createAuditLog({
      action: 'SYSTEM_UPDATE',
      entity: 'User',
      entityId: id,
      userId: staff.id,
      description: `Resent verification email to ${personalEmail}.`,
    })

    return apiSuccess({ message: 'Verification email resent successfully' })
  }
)

