// PATCH /api/staff/users/[id]
export const PATCH = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const session = await getAuthSession()
    if (!session || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
      return apiError('Unauthorized', 401)
    }
    const staff = session.user
    const { id } = context!.params
    if (!id) return apiError('User ID required')

    const body = await req.json()
    const validation = updateUserSchema.safeParse(body)
    if (!validation.success) {
      const error = validation.error.issues
        .map((e) => `${e.path.join('.')}: ${e.message}`)
        .join(', ')
      return apiError(error)
    }

    const {
      firstName,
      middleName,
      lastName,
      phone,
      studentId,
      employeeId,
      nationality,
      dateOfBirth,
      gender,
      alternatePhone,
      postalCode,
      profilePhotoUrl,
      specialization,
      qualifications,
      department,
      position,
      ...userData
    } = validation.data

    const user = await prismaUnfiltered.user.findUnique({ where: { id } })
    if (!user) return apiNotFound('User not found')

    // Update user fields
    const updated = await prismaUnfiltered.user.update({
      where: { id },
      data: userData,
    })

    // Evict if status changed to inactive
    if (userData.status && userData.status !== 'ACTIVE' && user.status === 'ACTIVE') {
      await evictInactiveUserFromExams(id, staff.id, `Account status changed to ${userData.status}`)
    }

    // Update profile fields if provided
    if (
      firstName ||
      middleName !== undefined ||
      lastName ||
      phone ||
      nationality ||
      dateOfBirth ||
      gender ||
      alternatePhone ||
      postalCode ||
      profilePhotoUrl !== undefined
    ) {
      await prismaUnfiltered.profile.upsert({
        where: { userId: id },
        update: {
          ...(firstName && { firstName }),
          ...(middleName !== undefined && { middleName }),
          ...(lastName && { lastName }),
          ...(phone && { phone }),
          ...(nationality && { nationality }),
          ...(dateOfBirth && { dateOfBirth: new Date(dateOfBirth) }),
          ...(gender && { gender }),
          ...(alternatePhone && { alternatePhone }),
          ...(postalCode && { postalCode }),
          ...(profilePhotoUrl !== undefined && { profilePhotoUrl }),
        },
        create: {
          userId: id,
          firstName: firstName || 'Unknown',
          middleName,
          lastName: lastName || 'Unknown',
          phone,
          nationality,
          dateOfBirth: dateOfBirth ? new Date(dateOfBirth) : undefined,
          gender,
          alternatePhone,
          postalCode,
          profilePhotoUrl,
        },
      })
    }

    // Handle Custom ID Updates

    if (studentId && user.role === 'STUDENT') {
      const existing = await prismaUnfiltered.studentProfile.findUnique({ where: { studentId } })
      if (existing && existing.userId !== id) {
        return apiError('Student ID already in use', 409)
      }
      await prismaUnfiltered.studentProfile.update({
        where: { userId: id },
        data: { studentId },
      })
    }

    if (employeeId || specialization !== undefined || qualifications !== undefined) {
      if (user.role === 'INSTRUCTOR') {
        const existing = employeeId
          ? await prismaUnfiltered.instructorProfile.findUnique({ where: { employeeId } })
          : null
        if (existing && existing.userId !== id) {
          return apiError('Employee ID already in use', 409)
        }
        await prismaUnfiltered.instructorProfile.upsert({
          where: { userId: id },
          update: {
            ...(employeeId && { employeeId }),
            ...(specialization !== undefined && { specialization }),
            ...(qualifications !== undefined && { qualifications }),
            ...(department !== undefined && { department }),
          },
          create: {
            userId: id,
            employeeId: employeeId || `INST-${id.slice(0, 8)}`,
            specialization: specialization || '',
            qualifications: qualifications || '',
            department: department || '',
          },
        })
      } else if (['ADMIN', 'STAFF', 'SUPER_ADMIN'].includes(user.role)) {
        const staffData: any = {}
        if (employeeId) staffData.employeeId = employeeId
        if (department !== undefined) staffData.department = department
        if (position !== undefined) staffData.position = position

        if (Object.keys(staffData).length > 0) {
          const existing = employeeId
            ? await prismaUnfiltered.staffProfile.findUnique({ where: { employeeId } })
            : null
          if (existing && existing.userId !== id) {
            return apiError('Employee ID already in use', 409)
          }

          await prismaUnfiltered.staffProfile.upsert({
            where: { userId: id },
            update: staffData,
            create: {
              userId: id,
              employeeId: employeeId || `STAFF-${id.slice(0, 8)}`,
              ...staffData,
            },
          })
        }
      }
    }

    await createAuditLog({
      action: 'UPDATE',
      entity: 'User',
      entityId: id,
      userId: staff.id,
      description: `User ${user.email} updated by staff`,
      changes: validation.data,
    })

    return apiSuccess({ message: 'User updated', id: updated.id })
  }
)

// DELETE /api/staff/users/[id]
export const DELETE = withErrorHandler(
  async (req: NextRequest, context?: { params: Record<string, string> }) => {
    const session = await getAuthSession()
    if (!session || !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)) {
      return apiError('Unauthorized', 401)
    }
    const staff = session.user
    const { id } = context!.params
    if (!id) return apiError('User ID required')

    const user = await prismaUnfiltered.user.findUnique({ where: { id } })
    if (!user) return apiNotFound('User not found')

    const { searchParams } = new URL(req.url)
    const isHardDelete = searchParams.get('hard') === 'true'

    if (isHardDelete) {
      // Only ADMIN/SUPER_ADMIN can permanently delete users
      if (!['ADMIN', 'SUPER_ADMIN'].includes(staff.role)) {
        return apiError('Only administrators can permanently delete users', 403)
      }
      // Permanent hard delete
      await prismaUnfiltered.user.delete({ where: { id } })

      await createAuditLog({
        action: 'DELETE',
        entity: 'User',
        entityId: id,
        userId: staff.id,
        description: `User ${user.email} permanently deleted by staff`,
        changes: { email: user.email, hardDelete: true },
      })

      await evictInactiveUserFromExams(id, staff.id, 'Account permanently deleted')

      return apiSuccess({ message: 'User permanently deleted' })
    } else {
      // Soft delete — archive
      await prismaUnfiltered.user.update({
        where: { id },
        data: { status: UserStatus.ARCHIVED },
      })

      await createAuditLog({
        action: 'DELETE',
        entity: 'User',
        entityId: id,
        userId: staff.id,
        description: `User ${user.email} archived by staff`,
        changes: { email: user.email, softDelete: true },
      })

      await evictInactiveUserFromExams(id, staff.id, 'Account archived')

      return apiSuccess({ message: 'User deactivated' })
    }
  }
)

