import { NextRequest } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { apiSuccess, apiUnauthorized, apiForbidden } from '@/lib/api/response'
import { unstable_cache } from 'next/cache'

const getCachedCounts = unstable_cache(
  async () => {
    const queryResult: any[] = await prismaUnfiltered.$queryRaw`
      SELECT
        COUNT(*)::int as "total",
        COUNT(*) FILTER (WHERE "role"::text = 'APPLICANT' AND "status"::text = 'PENDING')::int as "applicantAll",
        COUNT(*) FILTER (WHERE "role"::text = 'APPLICANT' AND "status"::text = 'PENDING' AND "registrationPaid" = false)::int as "applicantPendingPayment",
        COUNT(*) FILTER (WHERE "role"::text = 'APPLICANT' AND "status"::text = 'PENDING' AND "registrationPaid" = true)::int as "applicantPendingApproval",
        COUNT(*) FILTER (WHERE "role"::text = 'STUDENT')::int as "studentAll",
        COUNT(*) FILTER (WHERE "role"::text = 'STUDENT' AND "status"::text = 'ACTIVE')::int as "studentActive",
        COUNT(*) FILTER (WHERE "role"::text = 'STUDENT' AND "status"::text = 'SUSPENDED')::int as "studentSuspended",
        COUNT(*) FILTER (WHERE "role"::text = 'STUDENT' AND "status"::text = 'ARCHIVED')::int as "studentArchived",
        COUNT(*) FILTER (WHERE "role"::text = 'EXAMINER')::int as "examinerAll"
      FROM "users"
      WHERE "deletedAt" IS NULL
    `
    return queryResult[0] || {
      total: 0,
      applicantAll: 0,
      applicantPendingPayment: 0,
      applicantPendingApproval: 0,
      studentAll: 0,
      studentActive: 0,
      studentSuspended: 0,
      studentArchived: 0,
      examinerAll: 0,
    }
  },
  ['staff-users-counts'],
  { revalidate: 60 }
)

export async function GET(req: NextRequest) {
  const session = await getAuthSession()
  if (!session) return apiUnauthorized()

  const counts = await getCachedCounts()
  return apiSuccess(counts)
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthSession, hashPassword } from '@/lib/auth/helpers'
import { requirePermission, PERMISSIONS } from '@/lib/auth/permissions'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { serializePrisma } from '@/lib/utils/serialization'
import { UserRole, EnrollmentType } from '@prisma/client'

// Schema for user creation
const createUserSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  role: z.enum(['APPLICANT', 'STUDENT', 'INSTRUCTOR', 'STAFF', 'ADMIN']),
  firstName: z.string().min(2, 'First name is required'),
  lastName: z.string().min(2, 'Last name is required'),
  phone: z.string().optional(),
})

export async function POST(req: NextRequest) {
  try {
    await requirePermission(PERMISSIONS.MANAGE_USERS)
    const session = await getAuthSession()

    const body = await req.json()
    const validation = createUserSchema.safeParse(body)

    if (!validation.success) {
      return NextResponse.json(
        { error: 'Invalid input', details: validation.error.format() },
        { status: 400 }
      )
    }

    const { email, password, role, firstName, lastName, phone } = validation.data

    // Check if user already exists
    const existingUser = await prismaUnfiltered.user.findUnique({
      where: { email },
    })

    if (existingUser) {
      return NextResponse.json({ error: 'User with this email already exists' }, { status: 409 })
    }

    const hashedPassword = await hashPassword(password)

    // Create user and related profiles in a transaction
    const newUser = await prismaUnfiltered.$transaction(async (tx) => {
      // Generate random 4-digit number with collision retry
      const generateUniqueId = async (prefix: string, type: 'STUDENT' | 'INSTRUCTOR' | 'STAFF') => {
        let isUnique = false
        let newId = ''
        while (!isUnique) {
          const random = Math.floor(1000 + Math.random() * 9000).toString()
          newId = `${prefix}-${random}`

          if (type === 'STUDENT') {
            const existing = await tx.studentProfile.findUnique({ where: { studentId: newId } })
            if (!existing) isUnique = true
          } else if (type === 'INSTRUCTOR') {
            const existing = await tx.instructorProfile.findUnique({ where: { employeeId: newId } })
            if (!existing) isUnique = true
          } else {
            const existing = await tx.staffProfile.findUnique({ where: { employeeId: newId } })
            if (!existing) isUnique = true
          }
        }
        return newId
      }

      // 1. Create base user
      const user = await tx.user.create({
        data: {
          email,
          password: hashedPassword,
          role,
          status: 'ACTIVE', // Active by default when created by staff
          emailVerified: new Date(), // Automatically verify email for staff-created users
          mustChangePassword: true, // Require password change for temporary passwords
          profile: {
            create: {
              firstName,
              lastName,
              phone,
            },
          },
        },
        include: {
          profile: true,
        },
      })

      // 2. Create role-specific profiles
      if (role === 'INSTRUCTOR') {
        const empId = await generateUniqueId('IN', 'INSTRUCTOR')
        await tx.instructorProfile.create({
          data: {
            userId: user.id,
            employeeId: empId,
          },
        })
      } else if (role === 'STAFF') {
        const empId = await generateUniqueId('ST', 'STAFF')
        await tx.staffProfile.create({
          data: {
            userId: user.id,
            employeeId: empId,
          },
        })
      } else if (role === 'ADMIN') {
        // Admins share StaffProfile but get AD- prefix
        const empId = await generateUniqueId('AD', 'STAFF')
        await tx.staffProfile.create({
          data: {
            userId: user.id,
            employeeId: empId,
          },
        })
      } else if (role === 'STUDENT') {
        const studentId = await generateUniqueId('AATA', 'STUDENT')
        await tx.studentProfile.create({
          data: {
            userId: user.id,
            studentId,
            enrollmentType: EnrollmentType.FULL_TIME, // Default, can be updated later
          },
        })
      }

      return user
    })

    // Return user without password
    const { password: _, ...userWithoutPassword } = newUser

    return NextResponse.json(serializePrisma(userWithoutPassword), { status: 201 })
  } catch (error) {
    console.error('Error creating user:', error)
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { apiPaginated, apiUnauthorized, parsePagination } from '@/lib/api/response'
import { buildOrderBy } from '@/lib/utils/build-order-by'

const ALLOWED_SORT_KEYS = {
  name: 'profile.lastName',
  role: 'role',
  status: 'status',
  joined: 'createdAt',
} as const
type SortKey = keyof typeof ALLOWED_SORT_KEYS

export async function GET(req: NextRequest) {
  const session = await getAuthSession()
  if (!session) return apiUnauthorized()

  const staffRoles = ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER']
  if (!staffRoles.includes(session.user.role)) return apiUnauthorized()

  const { searchParams } = new URL(req.url)
  const role = searchParams.get('role') || 'all'
  const status = searchParams.get('status') || 'all'
  const search = searchParams.get('search') || ''
  const page = parseInt(searchParams.get('page') || '1')
  const limit = parseInt(searchParams.get('limit') || '25')
  const orderBy = buildOrderBy<SortKey>(
    { sort: searchParams.get('sort'), order: searchParams.get('order') },
    ALLOWED_SORT_KEYS,
    { createdAt: 'desc' }
  )

  const where: any = {}
  if (role !== 'all') where.role = role

  if (status === 'all') {
    where.status = { notIn: ['ARCHIVED', 'DELETED'] }
  } else {
    where.status = status
  }
  if (search) {
    where.OR = [
      { email: { contains: search, mode: 'insensitive' } },
      { profile: { firstName: { contains: search, mode: 'insensitive' } } },
      { profile: { lastName: { contains: search, mode: 'insensitive' } } },
    ]
  }

  const [users, total] = await Promise.all([
    prismaUnfiltered.user.findMany({
      where,
      select: {
        id: true,
        email: true,
        personalEmail: true,
        academyEmail: true,
        role: true,
        status: true,
        emailVerified: true,
        mustChangePassword: true,
        createdAt: true,
        profile: {
          select: { firstName: true, lastName: true, phone: true, profilePhotoUrl: true },
        },
        ...(role === 'INSTRUCTOR'
          ? {
              instructorProfile: { select: { employeeId: true, specialization: true } },
            }
          : role === 'EXAMINER'
            ? {
                examinerProfile: {
                  select: { id: true, isActive: true, maxParallelSittings: true, notes: true },
                },
              }
            : {}),
      },
      orderBy,
      skip: (page - 1) * limit,
      take: limit,
    }),
    prismaUnfiltered.user.count({ where }),
  ])

  return apiPaginated(users, total, page, limit)
}

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'

export async function POST(req: NextRequest) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'STAFF'].includes(session.user.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const body = await req.json()
  const messages = body.messages // This can be an object: { STUDENT: [], STAFF: [] ... }

  if (!messages || typeof messages !== 'object') {
    return NextResponse.json({ error: 'Invalid payload' }, { status: 400 })
  }

  // Sanitise each role's messages
  const cleanMessages: Record<string, string[]> = {}

  for (const [role, roleMsgs] of Object.entries(messages)) {
    if (Array.isArray(roleMsgs)) {
      cleanMessages[role] = [...new Set(roleMsgs.map((m: any) => String(m).trim()).filter(Boolean))]
    }
  }

  if (Object.keys(cleanMessages).length === 0) {
    return NextResponse.json({ error: 'At least one message is required' }, { status: 400 })
  }

  await prismaUnfiltered.systemSetting.upsert({
    where: { key: 'welcome_messages' },
    update: { value: JSON.stringify(cleanMessages), updatedBy: session.user.id },
    create: {
      key: 'welcome_messages',
      value: JSON.stringify(cleanMessages),
      type: 'JSON',
      description: 'Rotating welcome messages shown on portal dashboards (categorised by role)',
      updatedBy: session.user.id,
    },
  })

  return NextResponse.json({ success: true, count: Object.values(cleanMessages).flat().length })
}

