import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { withErrorHandler, apiError, apiSuccess } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { buildSebConfig, generateSebConfig, BankSebConfig } from '@/lib/internal-exam/seb-config'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'

// GET /api/student/exams/internal/banks/[bankId]/seb-config — return .seb config for a bank
export const GET = withErrorHandler(async (req: NextRequest, ctx: { params: Promise<{ bankId: string }> }) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)

  const { bankId } = await ctx.params

  const bank = await prismaUnfiltered.internalExamBank.findUnique({
    where: { id: bankId },
    select: { id: true, name: true, sebConfig: true, courseId: true },
  })

  if (!bank) {
    return apiError('Exam bank not found', 404)
  }

  const enrollment = await prismaUnfiltered.enrollment.findFirst({
    where: {
      userId: session.user.id,
      courseId: bank.courseId,
      status: { in: ['ENROLLED', 'ACTIVE', 'APPROVED'] },
    },
  })

  if (!enrollment) {
    return apiError('You must be enrolled in the course to download this config', 403)
  }

  const schedule = await prismaUnfiltered.internalExamClassSchedule.findFirst({
    where: { bankId, sebRequired: true },
    select: { sebRequired: true },
  })

  if (!schedule) {
    return apiError('SEB is not required for this exam bank', 403)
  }

  const bankConfig = (bank.sebConfig as BankSebConfig | null) ?? null
  const startUrl = `${process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000'}/student/exams/internal/take/${bankId}`

  const sebConfig = buildSebConfig({
    bekPair: { publicKey: '', privateKey: '', configKey: '' },
    startUrl,
    examDurationSecs: 0,
    bankConfig,
  })

  sebConfig.browserExamKey = ''
  sebConfig.config_key = ''

  const sebZip = generateSebConfig(sebConfig)

  await createAuditLog({
    action: AuditAction.EXAM_SESSION_STARTED,
    userId: session.user.id,
    entity: 'InternalExamBank',
    entityId: bankId,
    description: `SEB config downloaded for bank ${bankId}`,
    details: { bankId, bankName: bank.name },
  })

  const headers = new Headers()
  headers.set('Content-Type', 'application/octet-stream')
  headers.set('Content-Disposition', `attachment; filename="exam-${bankId}.seb"`)

  return new NextResponse(Buffer.from(sebZip), { headers, status: 200 })
})

import { NextRequest } from 'next/server'
import { Prisma } from '@prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { EASA_DEFAULTS, isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'
import {
  categoryMatchesTarget,
  getInternalBankCategoryCode,
  getStudentTargetCategoryCodes,
} from '@/lib/easa/category-selection'

/**
 * GET /api/student/exams/internal/progress
 * Returns the student's internal exam progress, including:
 * - Per-bank attempt history and pass/fail status
 * - 10-year completion window tracking
 * - Overall module progress
 */
export const GET = withErrorHandler(async () => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)
  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }

  const studentId = session.user.id

  const user = await prismaUnfiltered.user.findUnique({
    where: { id: studentId },
    select: {
      role: true,
      email: true,
      profile: {
        select: {
          firstName: true,
          lastName: true,
          dateOfBirth: true,
          phone: true,
          nationality: true,
        },
      },
      studentProfile: {
        select: {
          studentId: true,
          enrollmentType: true,
          programmeChoice: true,
        },
      },
    },
  })
  if (!user || user.role !== 'STUDENT') {
    return apiError('Only enrolled students may view internal exam progress', 403)
  }

  // Get all exam banks the student has attempted
  const sessions = await prismaUnfiltered.internalExamSession.findMany({
    where: { studentId, status: { not: 'VOIDED' } },
    include: {
      bank: {
        select: {
          id: true,
          name: true,
          moduleCode: true,
          categoryCode: true,
          categoryConfig: true,
          course: { select: { name: true, code: true } },
        },
      },
    },
    orderBy: { createdAt: 'desc' },
  })

  // Group by bank
  interface BankSummary {
    id: string
    name: string
    moduleCode: string | null
    categoryCode: string | null
    categoryConfig: Prisma.JsonValue | null
    course: { name: string; code: string }
  }

  interface SessionAttempt {
    id: string
    attemptNumber: number
    status: string
    score: number | null
    totalPoints: number | null
    percentage: number | null
    passed: boolean | null
    submittedAt: Date | null
  }

  const byBank: Record<string, {
    bank: BankSummary
    attempts: SessionAttempt[]
    passed: boolean
    bestScore: number
    latestAttempt: Date | null
    retakeEligibleAt: Date | null
    banned: boolean
    banLiftDate: Date | null
    isPublished: boolean
    status: string
  }> = {}

  // Sessions come back ordered `createdAt` DESC — newest first. We only
  // set `status` on the FIRST insertion per bank so it reflects the
  // newest attempt; iterating after that would overwrite it with the
  // older session's status (the pre-fix bug).
  for (const s of sessions) {
    if (!byBank[s.bankId]) {
      byBank[s.bankId] = {
        bank: s.bank,
        attempts: [],
        passed: false,
        bestScore: 0,
        latestAttempt: null,
        retakeEligibleAt: null,
        banned: false,
        banLiftDate: null,
        isPublished: false,
        // Set once at creation = newest attempt's status (sessions are DESC)
        status: s.status,
      }
    }
    const entry = byBank[s.bankId]
    entry.attempts.push({
      id: s.id,
      attemptNumber: s.attemptNumber,
      status: s.status,
      score: s.score,
      totalPoints: s.totalPoints,
      percentage: s.percentage,
      passed: s.passed,
      submittedAt: s.submittedAt,
    })
    if (s.passed) entry.passed = true
    if (s.percentage && s.percentage > entry.bestScore) entry.bestScore = s.percentage
    if (!entry.latestAttempt || (s.submittedAt && s.submittedAt > entry.latestAttempt)) {
      entry.latestAttempt = s.submittedAt
    }
    if (s.retakeEligibleAt) entry.retakeEligibleAt = s.retakeEligibleAt
    if (s.banLiftDate && s.banLiftDate > new Date()) {
      entry.banned = true
      entry.banLiftDate = s.banLiftDate
    }
    if (s.isPublished) entry.isPublished = true
    // Intentionally do NOT overwrite entry.status here — see comment above.
  }

  // 10-year completion window
  const firstAttempt = sessions.length > 0
    ? sessions.reduce((earliest, s) => {
        const t = s.createdAt
        return !earliest || t < earliest ? t : earliest
      }, null as Date | null)
    : null

  let completionWindow = null
  if (firstAttempt) {
    const deadline = new Date(firstAttempt)
    deadline.setFullYear(deadline.getFullYear() + EASA_DEFAULTS.completionWindowYears)
    const now = new Date()
    const totalMs = deadline.getTime() - firstAttempt.getTime()
    const elapsedMs = now.getTime() - firstAttempt.getTime()
    const percentElapsed = Math.round((elapsedMs / totalMs) * 100)

    completionWindow = {
      startDate: firstAttempt.toISOString(),
      deadline: deadline.toISOString(),
      yearsTotal: EASA_DEFAULTS.completionWindowYears,
      percentElapsed: Math.min(100, percentElapsed),
      remainingDays: Math.max(0, Math.ceil((deadline.getTime() - now.getTime()) / (24 * 60 * 60 * 1000))),
    }
  }

  const enrollments = await prismaUnfiltered.enrollment.findMany({
    where: {
      userId: studentId,
      status: { in: ['ENROLLED', 'ACTIVE', 'APPROVED'] },
    },
    select: { courseId: true },
  })
  const enrolledCourseIds = [...new Set(enrollments.map((enrollment) => enrollment.courseId))]
  const targetCategories = await getStudentTargetCategoryCodes(prismaUnfiltered, studentId)

  // Only show banks tied to courses the student can actually access.
  const allBanks = await prismaUnfiltered.internalExamBank.findMany({
    where: {
      isActive: true,
      courseId: { in: enrolledCourseIds },
    },
    select: {
      id: true,
      name: true,
      moduleCode: true,
      categoryCode: true,
      categoryConfig: true,
      course: { select: { name: true, code: true } },
    },
  })

  const eligibleBanks = allBanks.filter((bank) =>
    categoryMatchesTarget(getInternalBankCategoryCode(bank), targetCategories)
  )

  const bankProgress = eligibleBanks.map(bank => {
    const progress = byBank[bank.id]
    const categoryCode = getInternalBankCategoryCode(bank)
    // Only show scores if admin has published the results
    const isPublished = progress?.isPublished || false
    return {
      bankId: bank.id,
      bankName: bank.name,
      moduleCode: bank.moduleCode,
      categoryCode,
      courseName: bank.course.name,
      courseCode: bank.course.code,
      attempted: !!progress,
      passed: isPublished ? (progress?.passed || false) : false,
      bestScore: isPublished ? (progress?.bestScore || 0) : 0,
      totalAttempts: progress?.attempts.length || 0,
      banned: progress?.banned || false,
      banLiftDate: progress?.banLiftDate?.toISOString() || null,
      retakeEligibleAt: progress?.retakeEligibleAt?.toISOString() || null,
      isPublished,
      pendingReview: !!progress && !isPublished && (progress.status === 'COMPLETED' || progress.status === 'TIMED_OUT'),
    }
  })

  const totalBanks = eligibleBanks.length
  const passedBanks = bankProgress.filter(b => b.passed).length

  return apiSuccess({
    studentDetails: {
      name: user.profile ? `${user.profile.firstName} ${user.profile.lastName}` : session.user.email,
      email: user.email,
      studentId: user.studentProfile?.studentId || null,
      dateOfBirth: user.profile?.dateOfBirth?.toISOString() || null,
      phone: user.profile?.phone || null,
      nationality: user.profile?.nationality || null,
      enrollmentType: user.studentProfile?.enrollmentType || null,
      programmeChoice: user.studentProfile?.programmeChoice || null,
      targetCategories,
    },
    bankProgress,
    completionWindow,
    summary: {
      totalModules: totalBanks,
      passedModules: passedBanks,
      progressPercent: totalBanks > 0 ? Math.round((passedBanks / totalBanks) * 100) : 0,
    },
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiError, withErrorHandler, RouteContext } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getBankRules, isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'

export const runtime = 'nodejs'

export const GET = withErrorHandler(async (req: NextRequest, _ctx: RouteContext) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)
  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }

  const user = await prismaUnfiltered.user.findUnique({
    where: { id: session.user.id },
    select: { role: true },
  })
  if (!user || user.role !== 'STUDENT') {
    return apiError('Only enrolled students may view internal exam sessions', 403)
  }

  const url = new URL(req.url)
  const sessionId = url.pathname.split('/').filter(Boolean).at(-2)
  if (!sessionId) return apiError('sessionId is required', 400)

  const examSession = await prismaUnfiltered.internalExamSession.findUnique({
    where: { id: sessionId },
    select: {
      id: true,
      studentId: true,
      status: true,
      expiresAt: true,
      timeExtensionSec: true,
      bankId: true,
    },
  })

  if (!examSession) return apiError('Session not found', 404)
  if (examSession.studentId !== session.user.id) return apiError('Unauthorized', 403)

  const rules = await getBankRules(examSession.bankId)

  const encoder = new TextEncoder()
  const stream = new ReadableStream({
    async start(controller) {
      const send = (data: string) => {
        controller.enqueue(encoder.encode(data))
      }

      const heartbeatInterval = setInterval(() => {
        send(': heartbeat\n\n')
      }, 15_000)

      const timerInterval = setInterval(async () => {
        const current = await prismaUnfiltered.internalExamSession.findUnique({
          where: { id: sessionId },
          select: { status: true, expiresAt: true, timeExtensionSec: true },
        })

        if (!current || current.status !== 'IN_PROGRESS') {
          clearInterval(timerInterval)
          clearInterval(heartbeatInterval)
          send('event: close\ndata: {}\n\n')
          controller.close()
          return
        }

        const effectiveExpiresAt = current.expiresAt
          ? new Date(current.expiresAt.getTime() + (current.timeExtensionSec || 0) * 1000)
          : null
        const totalTimeSecs = effectiveExpiresAt
          ? Math.max(0, Math.floor((effectiveExpiresAt.getTime() - Date.now()) / 1000))
          : 0

        send(
          `event: tick\ndata: ${JSON.stringify({ timeRemaining: totalTimeSecs, expiresAt: effectiveExpiresAt?.toISOString() ?? null })}\n\n`
        )

        if (totalTimeSecs <= 0) {
          clearInterval(timerInterval)
          clearInterval(heartbeatInterval)
          send('event: close\ndata: {}\n\n')
          controller.close()
        }
      }, 1000)

      req.signal.addEventListener('abort', () => {
        clearInterval(timerInterval)
        clearInterval(heartbeatInterval)
      })
    },
  })

  return new NextResponse(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  })
})

import { NextRequest } from 'next/server'
import { Prisma } from '@prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import {
  buildRandomizedPaper,
  checkEligibility,
  getBankRules,
  isInternalExamSystemEnabled,
  selectInternalExamQuestions,
} from '@/lib/internal-exam/engine'
import {
  categoryMatchesTarget,
  getInternalBankCategoryCode,
  getStudentTargetCategoryCodes,
  normalizeCategoryCode,
} from '@/lib/easa/category-selection'
import { isSEBRequest } from '@/lib/middleware/seb-detection'
import { SebValidationError, validateSebRequest } from '@/lib/middleware/seb-validation'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { rateLimitByUser } from '@/lib/security/rate-limit'
import { z } from 'zod'

interface QuestionOrderEntry {
  id: string
  [key: string]: unknown
}

const startSchema = z.object({
  bankId: z.string().min(1),
  categoryCode: z.string().optional(),
  classId: z.string().optional(),
})

// POST /api/student/exams/internal/start — start a new exam session
export const POST = withErrorHandler(async (req: NextRequest) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)
  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }

  const user = await prismaUnfiltered.user.findUnique({
    where: { id: session.user.id },
    select: { role: true },
  })
  if (!user || user.role !== 'STUDENT') {
    return apiError('Only enrolled students may take internal exams', 403)
  }

  // Rate limit: 5 exam starts per minute per user
  const rateLimitResult = rateLimitByUser(session.user.id, 5, 60000)
  if (!rateLimitResult.allowed) {
    return apiError('Too many exam start requests. Please wait a moment and try again.', 429)
  }

  const body = await req.json()
  const parsed = startSchema.safeParse(body)
  if (!parsed.success) {
    return apiError('Invalid request body', 400)
  }
  const { bankId, categoryCode: requestedCategoryCode, classId } = parsed.data

  // Verify the bank exists and get the course it belongs to
  const bank = await prismaUnfiltered.internalExamBank.findUnique({
    where: { id: bankId },
    select: {
      id: true,
      mcqCount: true,
      ruleSet: true,
      courseId: true,
      isActive: true,
      categoryCode: true,
      categoryConfig: true,
      reviewState: true,
    },
  })
  if (!bank) return apiError('Exam bank not found', 404)
  if (!bank.isActive) return apiError('This exam bank is not currently active', 403)
  if (bank.reviewState !== 'APPROVED') {
    return apiError('This exam bank has not been approved for student use', 403)
  }

  // Verify student is enrolled in the course this bank belongs to
  const enrollment = await prismaUnfiltered.enrollment.findFirst({
    where: {
      userId: session.user.id,
      courseId: bank.courseId,
      status: { in: ['ENROLLED', 'ACTIVE', 'APPROVED'] },
    },
  })
  if (!enrollment) {
    return apiError('You must be enrolled in the course to take this exam', 403)
  }

  const targetCategories = await getStudentTargetCategoryCodes(prismaUnfiltered, session.user.id)
  const bankCategoryCode = getInternalBankCategoryCode(bank)
  const selectedCategoryCode = normalizeCategoryCode(requestedCategoryCode) || bankCategoryCode

  if (bankCategoryCode && selectedCategoryCode !== bankCategoryCode) {
    return apiError(`This exam bank is configured for category ${bankCategoryCode}.`, 400)
  }
  if (selectedCategoryCode && !categoryMatchesTarget(selectedCategoryCode, targetCategories)) {
    return apiError(
      `Category ${selectedCategoryCode} is not part of your selected licence pathway.`,
      403
    )
  }

  // Class-schedule validation if classId is provided
  let schedule = null
  if (classId) {
    const cls = await prismaUnfiltered.class.findUnique({
      where: { id: classId },
      select: { id: true },
    })
    if (!cls) return apiError('Class not found', 404)

    schedule = await prismaUnfiltered.internalExamClassSchedule.findFirst({
      where: { bankId, classId },
    })
    if (!schedule) return apiError('No exam schedule found for this class', 403)

    if (!schedule.isActive) {
      return apiError('This exam schedule is not active', 403)
    }

    const now = new Date()
    if (schedule.scheduledStart && now < schedule.scheduledStart) {
      return apiError('Exam has not started yet', 403)
    }

    const effectiveEnd =
      schedule.allowLateStart && schedule.scheduledEnd
        ? new Date(schedule.scheduledEnd.getTime() + 15 * 60 * 1000)
        : schedule.scheduledEnd

    if (effectiveEnd && now > effectiveEnd) {
      return apiError('Exam not available outside scheduled window', 403)
    }

    if (schedule.sebRequired && !isSEBRequest(req)) {
      return apiError('This exam requires Safe Exam Browser', 403)
    }
  }

  const userRecord = await prismaUnfiltered.user.findUnique({
    where: { id: session.user.id },
    select: { requiresAlternativeProctoring: true, email: true },
  })

  if (userRecord?.requiresAlternativeProctoring) {
    if (classId) {
      const eligibility = await checkEligibility(session.user.id, bankId)
      if (!eligibility.eligible) {
        return apiError(eligibility.reason || 'Not eligible', 403)
      }

      const rules = await getBankRules(bankId)
      const questionIds = await selectInternalExamQuestions(bankId, bank.mcqCount)
      if (questionIds.length === 0) {
        return apiError('No questions available in this exam bank')
      }

      const totalTimeSecs = questionIds.length * rules.timePerQuestionSecs
      const expiresAt = new Date(Date.now() + totalTimeSecs * 1000)

      const supervisedSession = await prismaUnfiltered.internalExamSession.create({
        data: {
          studentId: session.user.id,
          bankId,
          classId,
          ruleSet: bank.ruleSet,
          status: 'NOT_STARTED',
          supervised: true,
          expiresAt,
          attemptNumber: 'attemptNumber' in eligibility ? eligibility.attemptNumber : 1,
          categoryCode: selectedCategoryCode,
        },
      })

      if (schedule?.sebRequired) {
        try {
          await validateSebRequest(supervisedSession.id, req)
        } catch (err) {
          if (err instanceof SebValidationError) {
            return apiError(err.message, err.statusCode)
          }
          throw err
        }
      }

      await prismaUnfiltered.internalExamAnswer.createMany({
        data: questionIds.map((qId) => ({
          sessionId: supervisedSession.id,
          questionId: qId,
        })),
      })

      await createAuditLog({
        action: AuditAction.EXAM_SESSION_STARTED,
        userId: session.user.id,
        entity: 'InternalExamSession',
        entityId: supervisedSession.id,
        description: `Supervised exam session prepared for candidate requiring alternative proctoring`,
        details: {
          bankId,
          classId,
          studentEmail: userRecord.email,
          questionCount: questionIds.length,
        },
      })

      return apiSuccess({
        supervised: true,
        sessionId: supervisedSession.id,
        message: 'Your invigilator will start this exam for you. Please wait.',
      })
    }

    return apiError('Supervised exams require a scheduled class', 400)
  }

  // Check for an existing NOT_STARTED placeholder session first (reuse it)
  if (classId) {
    const placeholderSession = await prismaUnfiltered.internalExamSession.findFirst({
      where: {
        studentId: session.user.id,
        bankId,
        classId,
        status: 'NOT_STARTED',
      },
    })
    if (placeholderSession) {
      const allQuestions = await prismaUnfiltered.internalExamQuestion.findMany({
        where: {
          answers: { some: { sessionId: placeholderSession.id } },
        },
        select: { id: true, text: true, options: true, points: true, subTopic: true },
      })
      const savedAnswers = await prismaUnfiltered.internalExamAnswer.findMany({
        where: { sessionId: placeholderSession.id },
        select: { id: true, selectedAnswer: true, flaggedForReview: true },
      })
      const rules = await getBankRules(bankId)

      // Apply stored question order if present
      let questions = allQuestions
      if (placeholderSession.questionOrder && Array.isArray(placeholderSession.questionOrder)) {
        const order = placeholderSession.questionOrder as QuestionOrderEntry[]
        const orderMap = new Map(order.map((q) => [q.id, q]))
        questions = order
          .map((q) => allQuestions.find((aq) => aq.id === q.id))
          .filter((q): q is NonNullable<(typeof allQuestions)[number]> => q != null)
      }

      return apiSuccess({
        sessionId: placeholderSession.id,
        questions,
        savedAnswers,
        resumed: true,
        totalTimeSecs: placeholderSession.expiresAt
          ? Math.max(0, Math.floor((placeholderSession.expiresAt.getTime() - Date.now()) / 1000))
          : 0,
        expiresAt: placeholderSession.expiresAt?.toISOString(),
        rules: {
          timePerQuestionSecs: rules.timePerQuestionSecs,
          passMarkPct: rules.passMarkPct,
          allowKeyboardAutoSubmit: rules.allowKeyboardAutoSubmit,
        },
      })
    }
  }

  // Check for an existing in-progress session (allow resume)
  const existingSessionWhere: Prisma.InternalExamSessionWhereInput = {
    studentId: session.user.id,
    bankId,
    status: 'IN_PROGRESS',
  }
  if (classId) {
    existingSessionWhere.classId = classId
  }

  const existingSession = await prismaUnfiltered.internalExamSession.findFirst({
    where: existingSessionWhere,
  })
  if (existingSession) {
    const allQuestions = await prismaUnfiltered.internalExamQuestion.findMany({
      where: {
        answers: { some: { sessionId: existingSession.id } },
      },
      select: { id: true, text: true, options: true, points: true, subTopic: true },
    })
    const savedAnswers = await prismaUnfiltered.internalExamAnswer.findMany({
      where: { sessionId: existingSession.id },
      select: { questionId: true, selectedAnswer: true },
    })
    const rules = await getBankRules(bankId)

    // Apply stored question order if present
    let questions = allQuestions
    if (existingSession.questionOrder && Array.isArray(existingSession.questionOrder)) {
      const order = existingSession.questionOrder as QuestionOrderEntry[]
      const orderMap = new Map(order.map((q) => [q.id, q]))
      questions = order
        .map((q) => allQuestions.find((aq) => aq.id === q.id))
        .filter((q): q is NonNullable<(typeof allQuestions)[number]> => q != null)
    }

    return apiSuccess({
      sessionId: existingSession.id,
      questions,
      savedAnswers,
      resumed: true,
      totalTimeSecs: existingSession.expiresAt
        ? Math.max(0, Math.floor((existingSession.expiresAt.getTime() - Date.now()) / 1000))
        : 0,
      expiresAt: existingSession.expiresAt?.toISOString(),
      rules: {
        timePerQuestionSecs: rules.timePerQuestionSecs,
        passMarkPct: rules.passMarkPct,
        allowKeyboardAutoSubmit: rules.allowKeyboardAutoSubmit,
      },
    })
  }

  // Check retake eligibility
  const eligibility = await checkEligibility(session.user.id, bankId)
  if (!eligibility.eligible) {
    return apiError(eligibility.reason || 'Not eligible', 403)
  }

  const rules = await getBankRules(bankId)

  // Select questions
  const questionIds = await selectInternalExamQuestions(bankId, bank.mcqCount)
  if (questionIds.length === 0) {
    return apiError('No questions available in this exam bank')
  }

  // Fetch full question data for randomised paper assembly
  const rawQuestions = await prismaUnfiltered.internalExamQuestion.findMany({
    where: { id: { in: questionIds } },
    select: {
      id: true,
      text: true,
      options: true,
      points: true,
      subTopic: true,
      syllabusRef: true,
    },
  })

  // Build randomised paper (shuffled question order + shuffled options)
  const { paper: randomisedQuestions, questionOrder } = await buildRandomizedPaper(
    rawQuestions.map((q) => ({
      ...q,
      options: Array.isArray(q.options)
        ? q.options.filter((o): o is string => typeof o === 'string')
        : [],
    }))
  )

  // Calculate expiry time
  const totalTimeSecs = questionIds.length * rules.timePerQuestionSecs
  const expiresAt = new Date(Date.now() + totalTimeSecs * 1000)

  // Create session with randomised question order
  const examSession = await prismaUnfiltered.internalExamSession.create({
    data: {
      studentId: session.user.id,
      bankId,
      classId: classId || null,
      ruleSet: bank.ruleSet,
      status: 'IN_PROGRESS',
      startedAt: new Date(),
      expiresAt,
      questionOrder,
      attemptNumber: 'attemptNumber' in eligibility ? eligibility.attemptNumber : 1,
      categoryCode: selectedCategoryCode,
      ipAddress: req.headers.get('x-forwarded-for') || req.headers.get('x-real-ip') || null,
      userAgent: req.headers.get('user-agent') || null,
    },
  })

  if (schedule?.sebRequired) {
    try {
      await validateSebRequest(examSession.id, req)
    } catch (err) {
      if (err instanceof SebValidationError) {
        return apiError(err.message, err.statusCode)
      }
      throw err
    }
  }

  // Create blank answer records in randomised order
  await prismaUnfiltered.internalExamAnswer.createMany({
    data: questionOrder.map((qId: string) => ({
      sessionId: examSession.id,
      questionId: qId,
    })),
  })

  return apiSuccess({
    sessionId: examSession.id,
    questions: randomisedQuestions,
    savedAnswers: [],
    resumed: false,
    totalTimeSecs,
    expiresAt: expiresAt.toISOString(),
    rules: {
      timePerQuestionSecs: rules.timePerQuestionSecs,
      passMarkPct: rules.passMarkPct,
      allowKeyboardAutoSubmit: rules.allowKeyboardAutoSubmit,
    },
  })
})

import { NextRequest } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getBankRules, isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'
import { calculateScore } from '@/lib/internal-exam/grading'
import { z } from 'zod'

const submitSchema = z.object({
  sessionId: z.string(),
  answers: z.array(z.object({
    questionId: z.string(),
    selectedAnswer: z.string(),
  })),
  autoSubmitted: z.boolean().optional(),
})

// POST /api/student/exams/internal/submit — submit exam answers
export const POST = withErrorHandler(async (req: NextRequest) => {
  const session = await getAuthSession()
  if (!session?.user?.id) return apiError('Unauthorized', 401)
  if (!(await isInternalExamSystemEnabled())) {
    return apiError('Internal exams are not currently available', 403)
  }

  const user = await prismaUnfiltered.user.findUnique({
    where: { id: session.user.id },
    select: { role: true },
  })
  if (!user || user.role !== 'STUDENT') {
    return apiError('Only enrolled students may submit internal exams', 403)
  }

  const body = await req.json()
  const parsed = submitSchema.safeParse(body)
  if (!parsed.success) return apiError('Invalid input')

  const { sessionId, answers, autoSubmitted } = parsed.data

  // Load session with answers
  const examSession = await prismaUnfiltered.internalExamSession.findUnique({
    where: { id: sessionId },
    include: {
      answers: { include: { question: { select: { correctAnswer: true, points: true } } } },
      bank: { select: { id: true } },
    },
  })

  if (!examSession) return apiError('Session not found', 404)
  if (examSession.studentId !== session.user.id) return apiError('Unauthorized', 403)
  if (examSession.status !== 'IN_PROGRESS') return apiError('Session already submitted')

  // Check expiry — if expired, force auto-submit with TIMED_OUT status
  const now = new Date()
  const isExpired = examSession.expiresAt && now > examSession.expiresAt
  const finalStatus = isExpired ? 'TIMED_OUT' : 'COMPLETED'

  // Grade answers and update everything in a single transaction
  const result = await prismaUnfiltered.$transaction(async (tx) => {
    const responses = answers.map(a => ({ questionId: a.questionId, selectedAnswer: a.selectedAnswer }))
    const gradableAnswers = examSession.answers.map(a => ({
      questionId: a.questionId,
      correctAnswer: a.question.correctAnswer,
      points: a.question.points,
    }))

    const rules = await getBankRules(examSession.bankId)
    const { score, totalPoints, percentage, passed } = calculateScore(responses, gradableAnswers, rules.passMarkPct)

    for (const ans of examSession.answers) {
      const studentAnswer = answers.find(a => a.questionId === ans.questionId)
      const isCorrect = studentAnswer?.selectedAnswer === ans.question.correctAnswer
      const pointsAwarded = isCorrect ? ans.question.points : 0

      await tx.internalExamAnswer.update({
        where: { id: ans.id },
        data: {
          selectedAnswer: studentAnswer?.selectedAnswer || null,
          isCorrect,
          pointsAwarded,
          answeredAt: now,
        },
      })
    }
    // Single-attempt policy: `checkEligibility` blocks any retake of a
    // non-VOIDED COMPLETED/TIMED_OUT session, and only an admin void
    // clears the block. We deliberately do NOT compute retakeEligibleAt
    // or banLiftDate here — those vestigial columns from the prior
    // multi-attempt model are left as `null` so reports surface the
    // current policy honestly.
    await tx.internalExamSession.update({
      where: { id: sessionId },
      data: {
        status: finalStatus,
        submittedAt: now,
        autoSubmitted: autoSubmitted || isExpired || false,
        ...(autoSubmitted && !isExpired ? { keyboardEvents: { increment: 1 } } : {}),
        score,
        totalPoints,
        percentage,
        passed,
      },
    })

    return { score, totalPoints, percentage, passed, rules }
  })

  // Do NOT return scores to students — results are pending admin review
  return apiSuccess({
    submitted: true,
    pendingReview: true,
    timedOut: isExpired,
  })
})

