import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered as prisma } from '@/lib/prisma/client'
import { renderToStream } from '@react-pdf/renderer'
import { InvoiceTemplate, InvoiceItem } from '@/components/pdf/templates/InvoiceTemplate'
import { getPDFSettings } from '@/lib/pdf-settings'
import React from 'react'

export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await getAuthSession()
  if (!session) return new NextResponse('Unauthorized', { status: 401 })

  const { id } = await params

  const invoice = await prisma.invoice.findUnique({
    where: { id },
    include: {
      user: {
        include: {
          profile: true,
          studentProfile: true,
        },
      },
    },
  })

  if (!invoice) return new NextResponse('Not Found', { status: 404 })

  if (
    invoice.userId !== session.user.id &&
    !['ADMIN', 'SUPER_ADMIN', 'STAFF'].includes(session.user.role)
  ) {
    return new NextResponse('Forbidden', { status: 403 })
  }

  try {
    const pdfSettings = await getPDFSettings(req.nextUrl.origin)
    const studentName =
      [invoice.user.profile?.firstName, invoice.user.profile?.lastName].filter(Boolean).join(' ') ||
      'Student'

    // Ensure items are properly shaped
    let items = invoice.items as any as InvoiceItem[]
    if (!items || !Array.isArray(items) || items.length === 0) {
      items = [
        {
          description: 'Academy Fees',
          quantity: 1,
          unitPrice: Number(invoice.amount),
          total: Number(invoice.amount),
        },
      ]
    }

    const stream = await renderToStream(
      <InvoiceTemplate
        logoUrl={pdfSettings.logoUrl}
        watermarkUrl={pdfSettings.watermarkUrl}
        watermarkOpacity={pdfSettings.watermarkOpacity}
        invoiceNumber={invoice.invoiceNumber || 'N/A'}
        date={invoice.createdAt}
        dueDate={new Date(invoice.createdAt.getTime() + 7 * 24 * 60 * 60 * 1000)}
        studentName={studentName}
        studentEmail={invoice.user.email}
        studentId={invoice.user.studentProfile?.studentId || undefined}
        items={items}
        subtotal={Number(invoice.amount)}
        total={Number(invoice.amount)}
        currency={invoice.currency || 'EUR'}
      />
    )

    const filename = `Invoice_${invoice.invoiceNumber || id}.pdf`

    return new NextResponse(stream as any, {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="${filename}"`,
      },
    })
  } catch (error: any) {
    console.error('[Invoice Download Error]', error)
    return new NextResponse('Internal Server Error', { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { apiSuccess, apiError, withErrorHandler } from '@/lib/api/response'
import { chargeWallet } from '@/lib/wallet/operations'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'

// POST /api/student/milestones/pay — Pay a DUE milestone from wallet (for students)
export const POST = withErrorHandler(async (req: NextRequest) => {
  const session = await getAuthSession()
  if (!session) return apiError('Unauthorized', 401)

  const userId = session.user.id

  // Verify user is a student
  const user = await prismaUnfiltered.user.findUnique({ where: { id: userId } })
  if (!user || user.role !== 'STUDENT') return apiError('Only students can use this endpoint', 403)

  let body: any
  try {
    body = await req.json()
  } catch {
    return apiError('Invalid request body', 400)
  }

  const { milestoneId } = body
  if (!milestoneId) return apiError('milestoneId is required')

  const milestone = await prismaUnfiltered.paymentMilestone.findUnique({
    where: { id: milestoneId },
    include: { enrollment: true },
  })

  if (!milestone) return apiError('Milestone not found', 404)
  if (milestone.enrollment.studentId !== userId) return apiError('Unauthorized', 403)
  if (milestone.status === 'PAID') return apiError('Milestone is already paid')
  if (milestone.status !== 'DUE' && milestone.status !== 'OVERDUE') {
    return apiError(`Cannot pay milestone with status: ${milestone.status}`)
  }

  const amountToCharge = Number(milestone.amountDue)

  const wallet = await prismaUnfiltered.wallet.findUnique({ where: { userId } })
  if (!wallet || Number(wallet.availableBalance) < amountToCharge) {
    return apiError(
      `Insufficient wallet balance. Need ${amountToCharge.toLocaleString()}, available: ${Number(wallet?.availableBalance ?? 0).toLocaleString()}`
    )
  }

  await prismaUnfiltered.$transaction(async (tx) => {
    await chargeWallet(
      tx,
      userId,
      amountToCharge,
      `Paid milestone: ${milestone.milestoneType} (Year ${milestone.yearNumber})`,
      milestone.id,
      'MILESTONE_ID'
    )

    await tx.paymentMilestone.update({
      where: { id: milestone.id },
      data: { status: 'PAID', paidAt: new Date() },
    })

    if (milestone.milestoneType === 'SEAT_CONFIRMATION') {
      await tx.fullTimeEnrollment.update({
        where: { id: milestone.enrollmentId },
        data: { status: 'ACTIVE' },
      })
    }

    await tx.notification.create({
      data: {
        userId,
        title: 'Milestone Paid Successfully',
        message: `You have successfully paid your milestone: ${milestone.milestoneType} (Year ${milestone.yearNumber}) for €${amountToCharge.toLocaleString()}.`,
        type: 'SUCCESS',
        linkUrl: '/student/wallet?tab=payments',
        linkText: 'View Payments',
      },
    })
  })

  await createAuditLog({
    action: AuditAction.PAYMENT_APPROVE,
    entity: 'PaymentMilestone',
    entityId: milestoneId,
    userId,
    details: {
      milestoneType: milestone.milestoneType,
      yearNumber: milestone.yearNumber,
      amount: amountToCharge,
    },
  })

  return apiSuccess({ message: 'Milestone paid successfully' })
})

