import { NextRequest, NextResponse } from 'next/server'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { createAuditLog } from '@/lib/audit/logger'

export async function POST(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = session.user.id
    const { amount, currency: paymentCurrency, eurEquivalent, studentId, proofUrl, filename, fileType, fileSize } = await req.json()
    const submittedCurrency = paymentCurrency || 'GHS'

    if (!amount || !proofUrl) {
      return NextResponse.json({ error: 'Amount and payment proof are required.' }, { status: 400 })
    }

    const parsedAmount = parseFloat(amount)
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      return NextResponse.json({ error: 'Invalid amount provided.' }, { status: 400 })
    }

    // Generate a unique reference code
    const referenceCode = `W-TOPUP-${Date.now()}-${Math.floor(Math.random() * 1000)}`

    const eurAmt = eurEquivalent ? parseFloat(eurEquivalent) : parsedAmount
    const rate = eurEquivalent ? (parsedAmount / parseFloat(eurEquivalent)) : 1

    const payment = await prismaUnfiltered.payment.create({
      data: {
        userId,
        amount: eurAmt,
        currency: 'EUR',
        paymentCurrency: submittedCurrency,
        originalAmount: parsedAmount,
        exchangeRate: rate,
        paymentMethod: 'BANK_TRANSFER',
        status: 'PENDING',
        proofUrl,
        proofUploadedAt: new Date(),
        referenceCode,
        referenceType: 'WALLET_TOPUP',
        referenceId: studentId,
        notes: `Student uploaded proof for Wallet Top-up. Original: ${submittedCurrency} ${parsedAmount}. File: ${filename || 'Unknown'}`,
      },
    })

    // Optionally record FileUpload if needed for the system
    if (filename && proofUrl) {
      await prismaUnfiltered.fileUpload.create({
        data: {
          userId,
          url: proofUrl,
          filename: filename || 'unknown',
          originalName: filename || 'unknown',
          size: fileSize ? parseInt(fileSize) : 0,
          mimeType: fileType || 'application/octet-stream',
          fileType: 'PAYMENT_PROOF',
        },
      })
    }

    await createAuditLog({
      action: 'SYSTEM_UPDATE',
      entity: 'payments',
      entityId: payment.id,
      userId,
      description: `Student submitted a wallet top-up request for ${submittedCurrency} ${parsedAmount}`,
    })

    return NextResponse.json({ success: true, paymentId: payment.id }, { status: 201 })
  } catch (error: any) {
    console.error('Wallet proof upload error:', error)
    return NextResponse.json({ error: 'Failed to submit payment proof.' }, { status: 500 })
  }
}

import { createUploadthing, type FileRouter } from 'uploadthing/next'
import { getAuthSession } from '@/lib/auth/helpers'
import { UploadThingError } from 'uploadthing/server'
import { recordFileUpload } from '@/lib/storage/file-upload-record'
import { trackDocumentUpload } from '@/lib/analytics/events'

const f = createUploadthing()

/**
 * Capture every UploadThing upload into the `FileUpload` table so the nightly
 * `/api/cron/supabase-mirror` job can mirror bytes to the Supabase bucket.
 * Best-effort — failures here are logged, not thrown, so the user's upload
 * never breaks because of a record-write hiccup.
 */
async function captureUpload(args: {
  metadata: { userId: string }
  route: string
  file: { name: string; size: number; type: string; ufsUrl: string; key: string }
  referenceType?: string
  referenceId?: string
}) {
  // Anonymous applicant uploads (paymentProof pre-registration) — skip the
  // FileUpload row entirely; we'll backfill once they create an account.
  if (!args.metadata.userId || args.metadata.userId === 'anonymous_applicant') return
  await recordFileUpload({
    userId: args.metadata.userId,
    route: args.route,
    filename: args.file.key,
    originalName: args.file.name,
    mimeType: args.file.type,
    size: args.file.size,
    uploadthingUrl: args.file.ufsUrl,
    uploadthingKey: args.file.key,
    referenceType: args.referenceType,
    referenceId: args.referenceId,
  })
}

