import { NextResponse } from 'next/server'
import { Webhook } from 'svix'
import prisma from '@/lib/prisma/client'

/**
 * Resend Webhook Handler
 *
 * Receives events from Resend (sent, delivered, bounced, etc.)
 * and logs them to the AuditLog for tracking.
 * Verifies webhook signatures using Svix when RESEND_WEBHOOK_SECRET is configured.
 */
export async function POST(req: Request) {
  try {
    const body = await req.text()
    const webhookSecret = process.env.RESEND_WEBHOOK_SECRET

    let payload: any

    if (webhookSecret) {
      const svixId = req.headers.get('svix-id')
      const svixTimestamp = req.headers.get('svix-timestamp')
      const svixSignature = req.headers.get('svix-signature')

      if (!svixId || !svixTimestamp || !svixSignature) {
        return NextResponse.json({ error: 'Missing webhook signature headers' }, { status: 401 })
      }

      const wh = new Webhook(webhookSecret)
      try {
        payload = wh.verify(body, {
          'svix-id': svixId,
          'svix-timestamp': svixTimestamp,
          'svix-signature': svixSignature,
        })
      } catch {
        console.error('[Webhooks] Resend signature verification failed')
        return NextResponse.json({ error: 'Invalid signature' }, { status: 401 })
      }
    } else {
      console.error(
        '[Webhooks] RESEND_WEBHOOK_SECRET not configured — rejecting unverified webhook'
      )
      return NextResponse.json({ error: 'Webhook verification not configured' }, { status: 503 })
    }

    const { type, data, created_at } = payload

    if (!type || !data) {
      return NextResponse.json({ error: 'Invalid payload' }, { status: 400 })
    }

    await prisma.auditLog.create({
      data: {
        action: `EMAIL_${type.replace('.', '_').toUpperCase()}`,
        entity: 'email',
        entityId: data.email_id || data.id || 'unknown',
        description: `Email event ${type} received from Resend at ${created_at}`,
        changes: {
          payload: payload,
          to: data.to,
          subject: data.subject,
        },
      },
    })

    return NextResponse.json({ received: true })
  } catch (error) {
    console.error('[Webhooks] Resend handler error:', error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'
import { topUpWallet } from '@/lib/wallet/operations'
import { createAuditLog } from '@/lib/audit/logger'
import Stripe from 'stripe'

/**
 * Stripe webhook handler.
 * Requires STRIPE_SECRET_KEY and STRIPE_WEBHOOK_SECRET to be set.
 * All events are verified via signature before processing.
 */
export async function POST(req: NextRequest) {
  const stripeSecretKey = process.env.STRIPE_SECRET_KEY
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET

  if (!stripeSecretKey || !webhookSecret) {
    return NextResponse.json(
      { error: 'Stripe integration not configured' },
      { status: 503 }
    )
  }

  const stripe = new Stripe(stripeSecretKey)

  const body = await req.text()
  const sig = req.headers.get('stripe-signature')

  if (!sig) {
    return NextResponse.json({ error: 'Missing stripe-signature header' }, { status: 400 })
  }

  // Verify webhook signature — rejects tampered/forged payloads
  let event: Stripe.Event
  try {
    event = stripe.webhooks.constructEvent(body, sig, webhookSecret)
  } catch (err: any) {
    console.error('Stripe webhook signature verification failed:', err.message)
    return NextResponse.json({ error: 'Invalid signature' }, { status: 401 })
  }

  try {
    switch (event.type) {
      case 'payment_intent.succeeded': {
        const paymentIntent = event.data.object as Stripe.PaymentIntent
        const { userId, paymentType, paymentId } = paymentIntent.metadata || {}

        if (!userId || !paymentId) {
          console.warn('Stripe webhook: missing metadata', paymentIntent.id)
          break
        }

        // Idempotency: skip if payment already approved
        const existing = await prisma.payment.findUnique({ where: { id: paymentId } })
        if (!existing || existing.status === 'APPROVED') {
          console.log(`Stripe webhook: payment ${paymentId} already processed or not found`)
          break
        }

        await prisma.payment.update({
          where: { id: paymentId },
          data: {
            status: 'APPROVED',
            referenceCode: paymentIntent.id,
            approvedAt: new Date(),
            approvedBy: 'STRIPE',
          },
        })

        if (paymentType === 'WALLET_TOP_UP') {
          await prisma.$transaction(async (tx) => {
            await topUpWallet(
              tx,
              userId,
              paymentIntent.amount / 100,
              `Stripe payment ${paymentIntent.id}`,
              paymentId,
              'PAYMENT_ID'
            )
          })
        }

        await createAuditLog({
          action: 'PAYMENT_APPROVE',
          entity: 'Payment',
          entityId: paymentId,
          userId: userId,
          details: { stripePaymentIntentId: paymentIntent.id, amount: paymentIntent.amount / 100 },
        })
        break
      }

      case 'payment_intent.payment_failed': {
        const paymentIntent = event.data.object as Stripe.PaymentIntent
        const { paymentId } = paymentIntent.metadata || {}

        if (paymentId) {
          // Idempotency: skip if already rejected
          const existing = await prisma.payment.findUnique({ where: { id: paymentId } })
          if (existing && existing.status === 'PENDING') {
            await prisma.payment.update({
              where: { id: paymentId },
              data: {
                status: 'REJECTED',
                rejectionReason: `Stripe payment failed: ${paymentIntent.last_payment_error?.message || 'Unknown error'}`,
                rejectedAt: new Date(),
                rejectedBy: 'STRIPE',
              },
            })
          }
        }
        break
      }

      case 'checkout.session.completed': {
        const session = event.data.object as Stripe.Checkout.Session
        console.log('Checkout session completed:', session.id)
        break
      }

      default:
        console.log(`Unhandled Stripe event type: ${event.type}`)
    }

    return NextResponse.json({ received: true })
  } catch (error: any) {
    console.error('Stripe webhook processing error:', error)
    return NextResponse.json({ error: 'Webhook processing failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import prisma from '@/lib/prisma/client'

/**
 * UploadThing Webhook Handler
 *
 * Handles file upload completion callbacks.
 * Verifies requests using UPLOADTHING_SECRET as a bearer token.
 */
export async function POST(req: NextRequest) {
  try {
    // Verify the webhook comes from UploadThing using the shared secret
    const uploadthingSecret = process.env.UPLOADTHING_SECRET
    if (uploadthingSecret) {
      const authHeader = req.headers.get('authorization')
      const uploadthingHeader = req.headers.get('uploadthing-hook')

      // UploadThing sends a custom header; also accept bearer token for flexibility
      if (!uploadthingHeader && authHeader !== `Bearer ${uploadthingSecret}`) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
      }
    }

    const body = await req.json()
    const { file, metadata } = body

    if (!file || !file.url) {
      return NextResponse.json({ error: 'Invalid payload' }, { status: 400 })
    }

    const fileUpload = await prisma.fileUpload.create({
      data: {
        filename: file.name || 'unknown',
        originalName: file.name || 'unknown',
        url: file.url,
        mimeType: file.type || 'application/octet-stream',
        size: file.size || 0,
        userId: metadata?.userId,
        fileType: metadata?.entityType || 'GENERAL',
        referenceType: metadata?.entityType,
        referenceId: metadata?.entityId,
      },
    })

    if (metadata?.entityType === 'PaymentProof' && metadata?.userId) {
      await prisma.payment.update({
        where: { id: metadata.entityId },
        data: { proofUrl: file.url },
      })
    }

    return NextResponse.json({ success: true, fileId: fileUpload.id })
  } catch (error: any) {
    console.error('UploadThing webhook error:', error)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
}

'use server'

import { revalidatePath } from 'next/cache'
import { getAuthSession, requireApplicant } from '@/lib/auth/helpers'
import prisma from '@/lib/prisma/client'

export async function updateApplicantProfile(formData: FormData) {
  const user = await requireApplicant()
  const userId = user.id

  const data = {
    firstName: formData.get('firstName') as string,
    lastName: formData.get('lastName') as string,
    phone: (formData.get('phone') as string) || null,
    alternatePhone: (formData.get('alternatePhone') as string) || null,
    gender: (formData.get('gender') as string) || null,
    nationality: (formData.get('nationality') as string) || null,
    dateOfBirth: formData.get('dateOfBirth')
      ? new Date(formData.get('dateOfBirth') as string)
      : null,
    address: (formData.get('address') as string) || null,
    city: (formData.get('city') as string) || null,
    state: (formData.get('state') as string) || null,
    country: (formData.get('country') as string) || null,
    postalCode: (formData.get('postalCode') as string) || null,
    emergencyContactName: (formData.get('emergencyContactName') as string) || null,
    emergencyContactPhone: (formData.get('emergencyContactPhone') as string) || null,
    emergencyContactRelation: (formData.get('emergencyContactRelation') as string) || null,
  }

  if (!data.firstName || !data.lastName) {
    return { error: 'First name and last name are required.' }
  }

  try {
    await prisma.profile.upsert({
      where: { userId },
      update: data,
      create: { userId, ...data },
    })

    revalidatePath('/applicant')
    revalidatePath('/applicant/profile')
    revalidatePath('/applicant/application/status')

    return { success: true }
  } catch (err) {
    console.error('updateApplicantProfile error:', err)
    return { error: 'Failed to save profile. Please try again.' }
  }
}

'use client'

import { useState, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { ChevronLeft, ChevronRight, Check, Loader2 } from 'lucide-react'
import TestTimer from './TestTimer'
import QuestionCard from './QuestionCard'

interface TestInterfaceProps {
  session: {
    id: string
    expiresAt: string
    questions: any[]
  }
}

export interface TestQuestion {
  questionId: string
  text: string
  options: string[]
  selectedAnswer: string | null
}

export default function TestInterface({ session }: TestInterfaceProps) {
  const router = useRouter()
  const [questions, setQuestions] = useState(session.questions)
  const [currentIndex, setCurrentIndex] = useState(0)
  const [submitting, setSubmitting] = useState(false)

  const handleAnswer = async (questionId: string, answer: string) => {
    // Optimistic update
    setQuestions((prev) =>
      prev.map((q) => (q.questionId === questionId ? { ...q, selectedAnswer: answer } : q))
    )

    // Background sync
    try {
      await fetch('/api/applicant/aptitude/answer', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: session.id, questionId, answer }),
      })
    } catch (e) {
      console.error('Failed to sync answer')
    }
  }

  const handleSubmit = useCallback(async () => {
    if (submitting) return
    setSubmitting(true)
    try {
      await fetch('/api/applicant/aptitude/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: session.id }),
      })
      router.push('/applicant/application/aptitude-test')
    } catch (e) {
      console.error(e)
      setSubmitting(false)
    }
  }, [session.id, submitting, router])

  const handleTimeExpire = useCallback(() => {
    handleSubmit()
  }, [handleSubmit])

  const answeredCount = questions.filter(
    (q) => q.selectedAnswer !== null && q.selectedAnswer !== ''
  ).length
  const allAnswered = answeredCount === questions.length

  const currentQ = questions[currentIndex]

  return (
    <div className="flex h-screen flex-col bg-slate-50 dark:bg-black">
      {/* Header */}
      <header className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-200 bg-white px-6 py-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-4">
          <div className="h-2 w-24 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
            <div
              className="bg-aerojet-blue h-full transition-all"
              style={{ width: `${(answeredCount / questions.length) * 100}%` }}
            />
          </div>
          <span className="text-xs font-bold text-slate-500">
            {answeredCount} of {questions.length} answered
          </span>
        </div>

        <div className="flex items-center gap-4">
          <TestTimer expiresAt={session.expiresAt} onExpire={handleTimeExpire} />
          <button
            onClick={() => {
              if (
                !allAnswered &&
                !confirm('You have unanswered questions. Are you sure you want to submit?')
              )
                return
              handleSubmit()
            }}
            disabled={submitting}
            className={`flex items-center gap-2 rounded-xl px-5 py-2 font-bold transition-all ${
              allAnswered
                ? 'bg-emerald-500 text-white shadow-md hover:bg-emerald-600'
                : 'bg-slate-200 text-slate-600 hover:bg-slate-300 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700'
            }`}
          >
            {submitting ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Check className="h-4 w-4" />
            )}
            Submit
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto px-4 py-12">
        <QuestionCard
          question={currentQ}
          index={currentIndex}
          total={questions.length}
          onAnswer={handleAnswer}
        />
      </main>

      {/* Footer Navigation */}
      <footer className="border-t border-slate-200 bg-white px-6 py-4 dark:border-slate-800 dark:bg-slate-900">
        <div className="mx-auto flex max-w-3xl items-center justify-between">
          <button
            onClick={() => setCurrentIndex((prev) => Math.max(0, prev - 1))}
            disabled={currentIndex === 0}
            className="flex items-center gap-2 rounded-xl border border-slate-200 px-5 py-2.5 font-bold text-slate-600 transition-colors hover:bg-slate-50 disabled:opacity-30 dark:border-slate-700 dark:text-slate-300 dark:hover:bg-slate-800"
          >
            <ChevronLeft className="h-5 w-5" /> Previous
          </button>

          <div className="hidden gap-1 md:flex">
            {questions.map((q, i) => (
              <button
                key={i}
                onClick={() => setCurrentIndex(i)}
                className={`h-2.5 w-2.5 rounded-full transition-all ${
                  currentIndex === i
                    ? 'bg-aerojet-blue scale-125'
                    : q.selectedAnswer
                      ? 'bg-slate-400'
                      : 'bg-slate-200 dark:bg-slate-700'
                }`}
                title={`Question ${i + 1}`}
              />
            ))}
          </div>

          <button
            onClick={() => setCurrentIndex((prev) => Math.min(questions.length - 1, prev + 1))}
            disabled={currentIndex === questions.length - 1}
            className="bg-aerojet-blue flex items-center gap-2 rounded-xl px-5 py-2.5 font-bold text-white shadow-md transition-all hover:bg-blue-700 disabled:opacity-30"
          >
            Next <ChevronRight className="h-5 w-5" />
          </button>
        </div>
      </footer>
    </div>
  )
}

