    } catch (e) {
      toast.error('An error occurred')
      setStarting(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="text-aerojet-blue h-8 w-8 animate-spin" />
      </div>
    )
  }

  if (sessionInfo?.status === 'IN_PROGRESS') {
    // Return the active test interface directly (or redirect)
    // We'll redirect to the actual test page if we had one, but we can also just render it.
    // For simplicity, let's redirect to the test running page.
    router.push('/applicant/application/aptitude-test/take')
    return null
  }

  if (sessionInfo && sessionInfo.status !== 'IN_PROGRESS') {
    return (
      <div className="mx-auto max-w-2xl space-y-6 text-center">
        <div className="rounded-2xl border border-slate-200 bg-white p-12 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <CheckCircle2 className="mx-auto mb-4 h-16 w-16 text-emerald-500" />
          <h2 className="text-2xl font-black tracking-tight text-slate-800 sm:text-3xl dark:text-white">
            Aptitude Test Completed
          </h2>
          <p className="mt-2 text-slate-500 dark:text-slate-400">
            You have successfully completed the aptitude test. You will be notified of the next
            steps via email and your dashboard.
          </p>
          <button
            onClick={() => router.push('/applicant/application/status')}
            className="mt-8 rounded-xl bg-slate-100 px-6 py-3 font-bold text-slate-600 transition-colors hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700"
          >
            Return to Dashboard
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="rounded-2xl border border-slate-200 bg-white p-8 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-4 border-b border-slate-100 pb-6 dark:border-slate-800">
          <div className="text-aerojet-blue flex h-12 w-12 items-center justify-center rounded-xl bg-blue-50 dark:bg-blue-900/30 dark:text-blue-400">
            <BrainCircuit className="h-6 w-6" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-slate-800 dark:text-white">Aptitude Test</h1>
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
              Engineering & Logic Evaluation
            </p>
          </div>
        </div>

        <div className="prose prose-slate dark:prose-invert max-w-none py-6 text-sm">
          <p>
            The Aerojet Aviation Training Academy aptitude test evaluates your foundational
            knowledge in Mathematics, English, Engineering principles, and Logical Reasoning. This
            is a mandatory step in the admission pipeline.
          </p>
          <ul className="space-y-2 font-medium">
            <li className="flex items-start gap-2">
              <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-500" />
              <span>
                <strong>Time Limit:</strong> You will have 60 minutes to complete the test. The
                timer cannot be paused once started.
              </span>
            </li>
            <li className="flex items-start gap-2">
              <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-500" />
              <span>
                <strong>Anti-Cheat Active:</strong> This test requires full screen. Navigating away
                or switching tabs will flag your session and may result in an automatic failure.
              </span>
            </li>
            <li className="flex items-start gap-2">
              <FileCheck className="text-aerojet-blue mt-0.5 h-4 w-4 shrink-0" />
              <span>
                <strong>Preparation:</strong> Ensure you have a stable internet connection and a
                quiet environment before starting.
              </span>
            </li>
          </ul>
        </div>

        <div className="border-t border-slate-100 pt-6 text-center dark:border-slate-800">
          <button
            onClick={() => setShowModal(true)}
            className="bg-aerojet-blue shadow-aerojet-blue/20 hover:shadow-aerojet-blue/30 inline-flex items-center gap-2 rounded-xl px-8 py-4 font-black text-white shadow-lg transition-all hover:-translate-y-0.5 hover:shadow-xl"
          >
            <Play className="h-5 w-5 fill-current" />
            Begin Assessment
          </button>
        </div>
      </div>

      {showModal && (
        <TestWarningModal
          onCancel={() => setShowModal(false)}
          onConfirm={handleStart}
          starting={starting}
        />
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { Loader2 } from 'lucide-react'
import TestInterface, { type TestQuestion } from '../_components/TestInterface'
import AntiCheatProvider from '../_components/AntiCheatProvider'

export default function TakeTestPage() {
  const router = useRouter()
  const [session, setSession] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  const fetchSession = useCallback(async () => {
    try {
      const res = await fetch('/api/applicant/aptitude/session')
      const json = await res.json()
      if (json.data && json.data.status === 'IN_PROGRESS') {
        setSession(json.data)
      } else {
        router.push('/applicant/application/aptitude-test')
      }
    } finally {
      setLoading(false)
    }
  }, [router])

  useEffect(() => {
    fetchSession()
  }, [fetchSession])

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  if (!session) {
    return (
      <div className="flex h-screen flex-col items-center justify-center gap-4">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
        <p className="text-sm font-bold uppercase tracking-widest text-slate-400">Redirecting…</p>
      </div>
    )
  }

  return (
    <AntiCheatProvider sessionId={session.id}>
      <TestInterface session={session} />
    </AntiCheatProvider>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { UploadButton } from '@/lib/uploads/uploadthing'
import {
  CheckCircle2,
  XCircle,
  Clock,
  FileText,
  AlertTriangle,
  RefreshCw,
} from 'lucide-react'

interface DocumentType {
  id: string
  name: string
  slug: string
  description: string | null
  fileTypes: string
  maxSizeMB: number
  isRequired: boolean
}

interface UploadedDocument {
  id: string
  documentTypeId: string
  status: 'PENDING' | 'APPROVED' | 'REJECTED'
  rejectionReason: string | null
  documentType: { id: string; name: string; slug: string }
  fileUpload: { id: string; url: string; filename: string }
}

interface DocumentUploadFormProps {
  documentTypes: DocumentType[]
  uploadedDocuments: UploadedDocument[]
  applicationId: string
  onRefresh: () => void
}

const STATUS_CONFIG = {
  PENDING: {
    icon: Clock,
    label: 'Under Review',
    bg: 'bg-amber-50 dark:bg-amber-900/20',
    text: 'text-amber-700 dark:text-amber-400',
    border: 'border-amber-200 dark:border-amber-800',
  },
  APPROVED: {
    icon: CheckCircle2,
    label: 'Approved',
    bg: 'bg-emerald-50 dark:bg-emerald-900/20',
    text: 'text-emerald-700 dark:text-emerald-400',
    border: 'border-emerald-200 dark:border-emerald-800',
  },
  REJECTED: {
    icon: XCircle,
    label: 'Rejected',
    bg: 'bg-red-50 dark:bg-red-900/20',
    text: 'text-red-700 dark:text-red-400',
    border: 'border-red-200 dark:border-red-800',
  },
}

export default function DocumentUploadForm({
  documentTypes,
  uploadedDocuments,
  applicationId,
  onRefresh,
}: DocumentUploadFormProps) {
  const [uploading, setUploading] = useState<string | null>(null)

  const getUploadedDoc = (typeId: string) =>
    uploadedDocuments.find(d => d.documentTypeId === typeId)

  const requiredTypes = documentTypes.filter(dt => dt.isRequired)
  const optionalTypes = documentTypes.filter(dt => !dt.isRequired)
  const allRequired = requiredTypes.every(dt => {
    const doc = getUploadedDoc(dt.id)
    return doc && doc.status !== 'REJECTED'
  })

  async function linkUploadedFile(typeId: string, fileUrl: string, fileName: string, fileSize: number, fileType: string) {
    setUploading(typeId)
    try {
      const res = await fetch('/api/applicant/documents', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          documentTypeId: typeId,
          fileUrl,
          fileName,
          fileSize,
          fileType,
        }),
      })

      if (res.ok) {
        toast.success('Document uploaded successfully')
        onRefresh()
      } else {
        const data = await res.json()
        toast.error(data.error || 'Failed to save document')
      }
    } catch {
      toast.error('Upload failed. Please try again.')
    } finally {
      setUploading(null)
    }
  }

  return (
    <div className="space-y-8">
      {/* Progress Summary */}
      <div className="rounded-2xl border border-slate-200 bg-linear-to-br from-white to-slate-50 p-6 shadow-sm dark:border-slate-700 dark:from-slate-900 dark:to-slate-800">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-black text-aerojet-blue dark:text-white">
              Document Upload Progress
            </h2>
            <p className="mt-1 text-xs text-slate-500 dark:text-slate-400">
              {uploadedDocuments.length} of {documentTypes.length} documents uploaded
              {requiredTypes.length > 0 && ` · ${requiredTypes.length} required`}
            </p>
          </div>
          {allRequired && requiredTypes.length > 0 && (
            <div className="flex items-center gap-2 rounded-xl bg-emerald-50 px-4 py-2 dark:bg-emerald-900/30">
              <CheckCircle2 className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
              <span className="text-sm font-black text-emerald-700 dark:text-emerald-400">
                All Required Complete
              </span>
            </div>
          )}
        </div>

        {/* Progress bar */}
        <div className="mt-4 h-2 w-full overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
          <div
            className="h-full rounded-full bg-linear-to-r from-aerojet-blue to-aerojet-sky transition-all duration-700"
            style={{
              width: `${documentTypes.length > 0 ? (uploadedDocuments.filter(d => d.status !== 'REJECTED').length / documentTypes.length) * 100 : 0}%`,
            }}
          />
        </div>
      </div>

      {/* Required Documents */}
      {requiredTypes.length > 0 && (
        <div>
          <h3 className="mb-4 flex items-center gap-2 text-sm font-black uppercase tracking-widest text-red-600">
            <AlertTriangle className="h-4 w-4" />
            Required Documents
          </h3>
          <div className="grid gap-4 sm:grid-cols-2">
            {requiredTypes.map(dt => (
              <DocumentCard
                key={dt.id}
                docType={dt}
                uploaded={getUploadedDoc(dt.id)}
                uploading={uploading === dt.id}
                onUploaded={(url, name, size, type) => linkUploadedFile(dt.id, url, name, size, type)}
              />
            ))}
          </div>
        </div>
      )}

      {/* Optional Documents */}
      {optionalTypes.length > 0 && (
        <div>
          <h3 className="mb-4 text-sm font-black uppercase tracking-widest text-slate-400">
            Optional Documents
          </h3>
          <div className="grid gap-4 sm:grid-cols-2">
            {optionalTypes.map(dt => (
              <DocumentCard
                key={dt.id}
                docType={dt}
                uploaded={getUploadedDoc(dt.id)}
                uploading={uploading === dt.id}
                onUploaded={(url, name, size, type) => linkUploadedFile(dt.id, url, name, size, type)}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

function DocumentCard({
  docType,
  uploaded,
  uploading,
  onUploaded,
}: {
  docType: DocumentType
  uploaded?: UploadedDocument
  uploading: boolean
  onUploaded: (url: string, name: string, size: number, type: string) => void
}) {
  const status = uploaded ? STATUS_CONFIG[uploaded.status] : null
  const StatusIcon = status?.icon
  const showUploader = !uploaded || uploaded.status === 'REJECTED'

  return (
    <div
      className={`relative overflow-hidden rounded-2xl border p-5 transition-all ${
        uploaded
          ? `${status?.bg} ${status?.border}`
          : 'border-dashed border-slate-300 bg-white hover:border-aerojet-blue/40 hover:bg-blue-50/30 dark:border-slate-600 dark:bg-slate-900 dark:hover:border-aerojet-sky/40'
      }`}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1">
          <h4 className="font-black text-slate-800 dark:text-white">{docType.name}</h4>
          {docType.description && (
            <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">{docType.description}</p>
          )}
          <p className="mt-1 text-[10px] font-bold text-slate-400">
            Max {docType.maxSizeMB} MB · {docType.fileTypes.split(',').map(t => t.split('/')[1]).join(', ')}
          </p>
        </div>

        {status && StatusIcon && (
          <div className={`flex items-center gap-1.5 rounded-lg px-2.5 py-1 ${status.bg} ${status.text}`}>
            <StatusIcon className="h-3.5 w-3.5" />
            <span className="text-[10px] font-black">{status.label}</span>
          </div>
        )}
      </div>

      {/* Uploaded file info */}
      {uploaded && (
        <div className="mt-3 flex items-center gap-2 rounded-lg bg-white/60 px-3 py-2 dark:bg-black/20">
          <FileText className="h-4 w-4 text-slate-400" />
          <span className="flex-1 truncate text-xs font-bold text-slate-600 dark:text-slate-300">
            {uploaded.fileUpload.filename}
          </span>
          <a
            href={uploaded.fileUpload.url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-[10px] font-bold text-aerojet-blue hover:underline"
          >
            View
          </a>
        </div>
      )}

      {/* Rejection reason */}
      {uploaded?.status === 'REJECTED' && uploaded.rejectionReason && (
        <div className="mt-2 rounded-lg bg-red-100 px-3 py-2 dark:bg-red-900/30">
          <p className="text-xs font-bold text-red-700 dark:text-red-400">
            Reason: {uploaded.rejectionReason}
          </p>
        </div>
      )}

      {/* Upload button via UploadThing */}
      {showUploader && (
        <div className="mt-4">
          {uploaded?.status === 'REJECTED' && (
            <p className="mb-2 flex items-center gap-1 text-xs font-bold text-slate-500">
              <RefreshCw className="h-3 w-3" /> Re-upload to replace rejected document
            </p>
          )}
          <UploadButton
            endpoint="applicantDocument"
            onUploadBegin={() => {/* uploading state handled by parent */}}
            onClientUploadComplete={(res) => {
              if (res?.[0]) {
                const file = res[0]
                onUploaded(
                  file.ufsUrl ?? file.url,
                  file.name,
                  file.size,
                  file.type ?? 'application/pdf'
                )
              }
            }}
            onUploadError={(error) => {
              toast.error(error.message || 'Upload failed')
            }}
            appearance={{
              button: 'bg-aerojet-blue hover:bg-aerojet-blue/90 text-white text-xs font-bold px-4 py-2 rounded-xl ut-uploading:bg-slate-400',
              allowedContent: 'text-[10px] text-slate-400',
            }}
          />
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Loader2, FileText } from 'lucide-react'
import DocumentUploadForm from './_components/DocumentUploadForm'

export default function DocumentsPage() {
  const [data, setData] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchDocuments = useCallback(async () => {
    try {
      const res = await fetch('/api/applicant/documents')
      const json = await res.json()
      if (json.data) {
        setData(json.data)
      } else {
        setError(json.error || 'Failed to load documents')
      }
    } catch {
      setError('Failed to load documents')
    } finally {
      setLoading(false)
    }
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchDocuments() }, [fetchDocuments])

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className="mx-auto max-w-2xl rounded-2xl border border-slate-200 bg-white px-6 py-16 text-center shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <FileText className="mx-auto mb-4 h-12 w-12 text-slate-300" />
        <h2 className="text-lg font-black text-slate-600 dark:text-slate-300">
          {error === 'No application found'
            ? 'No Application Found'
            : 'Unable to Load Documents'}
        </h2>
        <p className="mt-2 text-sm text-slate-400">
          {error === 'No application found'
            ? 'Your admissions application has not been created yet. Please complete registration first.'
            : 'Something went wrong. Please try refreshing the page.'}
        </p>
      </div>
    )
  }

  return (
    <div className="max-w-4xl space-y-6">
      <div>
        <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white sm:text-3xl">
          Upload Documents
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Submit your application documents for review. Required documents must be uploaded before your application can proceed.
        </p>
      </div>

      <DocumentUploadForm
        documentTypes={data.documentTypes}
        uploadedDocuments={data.uploadedDocuments}
        applicationId={data.applicationId}
        onRefresh={fetchDocuments}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Calendar, Clock, MapPin, CheckCircle2, AlertCircle } from 'lucide-react'
import { format } from 'date-fns'

interface Slot {
  id: string
  date: string
  startTime: string
  endTime: string
  location: string | null
}

export default function SlotBooking({ currentSlot }: { currentSlot: Slot | null }) {
  const router = useRouter()
  const [slots, setSlots] = useState<Slot[]>([])
  const [loading, setLoading] = useState(true)
  const [booking, setBooking] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    fetch('/api/applicant/interview/slots')
      .then(res => res.json())
      .then(data => {
        if (data.data) {
          setSlots(data.data.availableSlots)
        }
      })
      .finally(() => setLoading(false))
  }, [])

  const handleBook = async (slotId: string) => {
    if (!confirm('Are you sure you want to book this slot?')) return

    setBooking(slotId)
    setError(null)
    
    try {
      const res = await fetch('/api/applicant/interview/book', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ slotId })
      })

      if (res.ok) {
        router.push('/applicant/application/status')
        router.refresh()
      } else {
        const err = await res.json()
        setError(err.error || 'Failed to book slot')
      }
    } catch (e) {
      setError('An unexpected error occurred')
    } finally {
      setBooking(null)
    }
  }

  if (loading) {
    return <div className="animate-pulse rounded-2xl bg-slate-100 dark:bg-slate-800 h-64 w-full" />
  }

  return (
    <div className="space-y-6">
      {currentSlot && (
        <div className="rounded-2xl border border-green-200 bg-green-50 p-6 dark:border-green-900/50 dark:bg-green-900/20">
          <div className="flex items-start gap-4">
            <CheckCircle2 className="mt-1 h-6 w-6 text-green-600 dark:text-green-400" />
            <div>
              <h2 className="text-lg font-bold text-green-900 dark:text-green-300">Your Interview is Confirmed</h2>
              <p className="mt-1 text-sm text-green-700 dark:text-green-400">
                You are currently scheduled for the following time slot. If you need to reschedule, please select a new slot below. Note that frequent rescheduling may negatively impact your application.
              </p>
              
              <div className="mt-4 flex flex-wrap gap-6 rounded-xl bg-white/60 p-4 dark:bg-slate-900/40">
                <div className="flex items-center gap-2 text-sm font-medium text-slate-800 dark:text-slate-200">
                  <Calendar className="h-5 w-5 text-aerojet-blue" />
                  {format(new Date(currentSlot.date), 'EEEE, MMMM d, yyyy')}
                </div>
                <div className="flex items-center gap-2 text-sm font-medium text-slate-800 dark:text-slate-200">
                  <Clock className="h-5 w-5 text-aerojet-blue" />
                  {format(new Date(currentSlot.startTime), 'h:mm a')} - {format(new Date(currentSlot.endTime), 'h:mm a')}
                </div>
                {currentSlot.location && (
                  <div className="flex items-center gap-2 text-sm font-medium text-slate-800 dark:text-slate-200">
                    <MapPin className="h-5 w-5 text-aerojet-blue" />
                    {currentSlot.location}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {error && (
        <div className="flex items-center gap-2 rounded-lg bg-red-50 p-4 text-sm font-medium text-red-600 dark:bg-red-900/20 dark:text-red-400">
          <AlertCircle className="h-5 w-5" />
          {error}
        </div>
      )}

      <div>
        <h2 className="text-lg font-bold text-slate-900 dark:text-white mb-4">
          {currentSlot ? 'Available Alternative Slots' : 'Available Slots'}
        </h2>
        
        {slots.length === 0 ? (
          <div className="rounded-2xl border border-slate-200 bg-white p-8 text-center dark:border-slate-800 dark:bg-slate-900">
            <p className="text-slate-500">No interview slots are currently available. Please check back later or contact admissions.</p>
          </div>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2">
            {slots.map((slot) => {
              const isCurrent = currentSlot?.id === slot.id
              return (
                <div 
                  key={slot.id} 
                  className={`flex flex-col justify-between rounded-xl border p-5 shadow-xs transition-shadow hover:shadow-md ${
                    isCurrent 
                      ? 'border-green-500 bg-green-50/50 dark:border-green-500/50 dark:bg-green-900/10' 
                      : 'border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900'
                  }`}
                >
                  <div>
                    <div className="flex items-center gap-2 font-bold text-slate-900 dark:text-white">
                      <Calendar className="h-4 w-4 text-aerojet-blue" />
                      {format(new Date(slot.date), 'MMM d, yyyy')}
                    </div>
                    <div className="mt-2 flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
                      <Clock className="h-4 w-4" />
                      {format(new Date(slot.startTime), 'h:mm a')} - {format(new Date(slot.endTime), 'h:mm a')}
                    </div>
                    {slot.location && (
                      <div className="mt-2 flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
                        <MapPin className="h-4 w-4" />
                        <span className="truncate">{slot.location}</span>
                      </div>
                    )}
                  </div>
                  
                  <div className="mt-6">
                    {isCurrent ? (
                      <button disabled className="w-full rounded-lg bg-green-100 py-2.5 text-sm font-bold text-green-700 dark:bg-green-900/30 dark:text-green-400">
                        Current Booking
                      </button>
                    ) : (
                      <button
                        onClick={() => handleBook(slot.id)}
                        disabled={!!booking}
                        className="w-full rounded-lg bg-aerojet-blue py-2.5 text-sm font-bold text-white transition-colors hover:bg-aerojet-blue/90 disabled:opacity-50"
                      >
                        {booking === slot.id ? 'Booking...' : currentSlot ? 'Reschedule to this Slot' : 'Book this Slot'}
                      </button>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { toast } from 'sonner'
import {
  Stethoscope,
  Upload,
  CheckCircle2,
  Clock,
  FileText,
  AlertTriangle,
  Loader2,
  ExternalLink,
} from 'lucide-react'

interface MedicalDoc {
  id: string
  status: string
  documentType: { name: string }
  fileUpload: { url: string; filename: string }
}

interface MedicalData {
  stage: string
  medicalStatus: string | null
  medicalClearedAt: string | null
  medicalFacility: string | null
  medicalNotes: string | null
  documents: MedicalDoc[]
  medicalDocTypes: { id: string; name: string; slug: string }[]
  applicationId: string
}

export default function MedicalPage() {
  const [data, setData] = useState<MedicalData | null>(null)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)

  const fetchData = useCallback(async () => {
    try {
      const res = await fetch('/api/applicant/medical')
      const json = await res.json()
      if (json.data) setData(json.data)
    } catch {
      // silent
    } finally {
      setLoading(false)
    }
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchData() }, [fetchData])

  const handleSubmit = async () => {
    setSubmitting(true)
    try {
      const res = await fetch('/api/applicant/medical/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })
      const json = await res.json()
      if (json.success) {
        toast.success('Medical documents submitted for review')
        fetchData()
      } else {
        toast.error(json.error || 'Failed to submit')
      }
    } catch {
      toast.error('An error occurred')
    } finally {
      setSubmitting(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  if (!data) {
    return (
      <div className="mx-auto max-w-2xl rounded-2xl border border-slate-200 bg-white px-6 py-16 text-center shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <Stethoscope className="mx-auto mb-4 h-12 w-12 text-slate-300" />
        <h2 className="text-lg font-black text-slate-600 dark:text-slate-300">
          Medical Stage Not Active
        </h2>
        <p className="mt-2 text-sm text-slate-400">
          You haven&apos;t reached the medical examination stage yet.
        </p>
      </div>
    )
  }

  const isCleared = data.stage === 'MEDICAL_CLEARED' || data.medicalStatus === 'CLEARED'
  const isSubmitted = data.stage === 'MEDICAL_SUBMITTED'
  const isPending = data.stage === 'MEDICAL_PENDING'

  return (
    <div className="mx-auto max-w-3xl space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div>
        <h1 className="text-3xl font-black tracking-tight text-aerojet-blue dark:text-white">
          Medical Examination
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Complete your medical examination at an approved facility and upload your documents.
        </p>
      </div>

      {/* Status Card */}
      <div className={`rounded-2xl border p-6 ${
        isCleared
          ? 'border-green-200 bg-green-50 dark:border-green-800/50 dark:bg-green-900/10'
          : isSubmitted
            ? 'border-blue-200 bg-blue-50 dark:border-blue-800/50 dark:bg-blue-900/10'
            : 'border-amber-200 bg-amber-50 dark:border-amber-800/50 dark:bg-amber-900/10'
      }`}>
        <div className="flex items-start gap-4">
          <div className={`rounded-xl p-3 ${
            isCleared ? 'bg-green-200 dark:bg-green-800/40' :
            isSubmitted ? 'bg-blue-200 dark:bg-blue-800/40' :
            'bg-amber-200 dark:bg-amber-800/40'
          }`}>
            {isCleared ? (
              <CheckCircle2 className="h-6 w-6 text-green-700 dark:text-green-300" />
            ) : isSubmitted ? (
              <Clock className="h-6 w-6 text-blue-700 dark:text-blue-300" />
            ) : (
              <Stethoscope className="h-6 w-6 text-amber-700 dark:text-amber-300" />
            )}
          </div>
          <div>
            <h2 className={`text-lg font-bold ${
              isCleared ? 'text-green-800 dark:text-green-200' :
              isSubmitted ? 'text-blue-800 dark:text-blue-200' :
              'text-amber-800 dark:text-amber-200'
            }`}>
              {isCleared
                ? 'Medical Examination Cleared'
                : isSubmitted
                  ? 'Documents Under Review'
                  : 'Medical Documents Required'}
            </h2>
            <p className={`mt-1 text-sm ${
              isCleared ? 'text-green-600 dark:text-green-400' :
              isSubmitted ? 'text-blue-600 dark:text-blue-400' :
              'text-amber-600 dark:text-amber-400'
            }`}>
              {isCleared
                ? `You have been cleared for enrollment${data.medicalFacility ? ` by ${data.medicalFacility}` : ''}.`
                : isSubmitted
                  ? 'Your medical documents are being reviewed by the admissions team.'
                  : 'Please visit an approved medical facility and upload the required documents below.'}
            </p>
          </div>
        </div>
      </div>

      {/* Instructions */}
      {isPending && (
        <div className="rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
          <h3 className="mb-4 flex items-center gap-2 font-bold text-slate-900 dark:text-white">
            <AlertTriangle className="h-5 w-5 text-amber-500" />
            Required Steps
          </h3>
          <ol className="space-y-3 text-sm text-slate-600 dark:text-slate-400">
            <li className="flex gap-3">
              <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-aerojet-blue text-xs font-bold text-white">1</span>
              <span>Visit an approved medical facility for a complete aviation medical examination (Class 1 or Class 2 as applicable).</span>
            </li>
            <li className="flex gap-3">
              <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-aerojet-blue text-xs font-bold text-white">2</span>
              <span>Obtain your signed medical certificate and any supporting lab reports.</span>
            </li>
            <li className="flex gap-3">
              <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-aerojet-blue text-xs font-bold text-white">3</span>
              <span>Upload the documents using the &quot;Documents&quot; page in the sidebar â€” select the medical document type.</span>
            </li>
            <li className="flex gap-3">
              <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-aerojet-blue text-xs font-bold text-white">4</span>
              <span>Click the <strong>&quot;Submit for Review&quot;</strong> button below once all documents are uploaded.</span>
            </li>
          </ol>
        </div>
      )}

      {/* Uploaded Documents */}
      {data.documents.length > 0 && (
        <div className="rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
          <h3 className="mb-4 font-bold text-slate-900 dark:text-white">Uploaded Medical Documents</h3>
          <div className="space-y-2">
            {data.documents.map(doc => (
              <div
                key={doc.id}
                className="flex items-center justify-between rounded-lg border border-slate-100 bg-slate-50 px-4 py-3 dark:border-slate-700 dark:bg-slate-800"
              >
                <div className="flex items-center gap-3">
                  <FileText className="h-5 w-5 text-aerojet-blue dark:text-aerojet-sky" />
                  <div>
                    <p className="text-sm font-medium text-slate-900 dark:text-white">{doc.documentType.name}</p>
                    <p className="text-xs text-slate-500">{doc.fileUpload.filename}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className={`rounded-full px-2.5 py-0.5 text-xs font-bold ${
                    doc.status === 'APPROVED'
                      ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300'
                      : doc.status === 'REJECTED'
                        ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300'
                        : 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300'
                  }`}>{doc.status}</span>
                  <a
                    href={doc.fileUpload.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="rounded p-1 text-slate-400 hover:text-aerojet-blue"
                  >
                    <ExternalLink className="h-4 w-4" />
                  </a>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Submit Button */}
      {isPending && (
        <div className="flex justify-end">
          <button
            onClick={handleSubmit}
            disabled={submitting || data.documents.length === 0}
            className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-8 py-3 font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50 dark:bg-aerojet-sky"
          >
            {submitting ? (
              <Loader2 className="h-5 w-5 animate-spin" />
            ) : (
              <Upload className="h-5 w-5" />
            )}
            Submit for Review
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useMemo } from 'react'
import Link from 'next/link'
import {
  CheckCircle2,
  Circle,
  Clock,
  XCircle,
  LogOut,
  CreditCard,
  ArrowRight,
  BrainCircuit,
  ListChecks,
  CalendarDays,
  type LucideIcon,
} from 'lucide-react'
import { format } from 'date-fns'

// ---------------------------------------------------------------------------
// Types (serialized versions — dates are ISO strings)
// ---------------------------------------------------------------------------

interface StageLogEntry {
  id: string
  fromStage: string
  toStage: string
  actorId: string
  metadata: unknown
  createdAt: string
}

interface Milestone {
  stage: string
  label: string
}

interface StageInfoMap {
  [stage: string]: {
    label: string
    shortLabel: string
    description: string
    color: string
    textColor: string
    applicantInstruction: string
    group: string
  }
}

export interface PipelineTrackerProps {
  currentStage: string
  previousStage: string | null
  programmeLabel: string
  registrationCode: string | null
  rejectionReason: string | null
  progress: number
  milestones: Milestone[]
  activeStages: string[]
  stageLogs: StageLogEntry[]
  stageInfo: StageInfoMap
  paymentProofUrl: string | null
  createdAt: string
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getStageStatus(
  milestoneStage: string,
  currentStage: string,
  activeStages: string[],
  isTerminal: boolean
): 'completed' | 'current' | 'upcoming' {
  if (isTerminal) return 'upcoming'

  const currentIdx = activeStages.indexOf(currentStage)
  const milestoneIdx = activeStages.indexOf(milestoneStage)

  if (milestoneIdx === -1 || currentIdx === -1) return 'upcoming'
  if (milestoneIdx < currentIdx) return 'completed'
  if (milestoneIdx === currentIdx) return 'current'

  // For milestones that represent the "end" of a group, check if current stage
  // is past the milestone's position
  return 'upcoming'
}

function isMilestoneCompleted(
  milestoneStage: string,
  currentStage: string,
  activeStages: string[]
): boolean {
  const currentIdx = activeStages.indexOf(currentStage)
  const milestoneIdx = activeStages.indexOf(milestoneStage)
  if (milestoneIdx === -1 || currentIdx === -1) return false
  return currentIdx > milestoneIdx
}

function isMilestoneCurrent(
  milestoneStage: string,
  currentStage: string,
  activeStages: string[]
): boolean {
  const currentIdx = activeStages.indexOf(currentStage)
  const milestoneIdx = activeStages.indexOf(milestoneStage)
  if (milestoneIdx === -1 || currentIdx === -1) return false
  return currentIdx === milestoneIdx
}

const TERMINAL_STAGES = ['REJECTED', 'WITHDRAWN']

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function PipelineTracker({
  currentStage,
  previousStage,
  programmeLabel,
  registrationCode,
  rejectionReason,
  progress,
  milestones,
  activeStages,
  stageLogs,
  stageInfo,
  paymentProofUrl,
  createdAt,
}: PipelineTrackerProps) {
  const isTerminal = TERMINAL_STAGES.includes(currentStage)
  const isEnrolled = currentStage === 'ENROLLED'
  const currentInfo = stageInfo[currentStage]

  // Determine which milestone is "closest" to the current stage
  // This handles sub-stages (e.g., PAYMENT_SUBMITTED maps to PAYMENT_VERIFIED milestone)
  const currentMilestoneIndex = useMemo(() => {
    if (isTerminal) return -1
    if (isEnrolled) return milestones.length - 1

    const currentActiveIdx = activeStages.indexOf(currentStage)
    if (currentActiveIdx === -1) return 0

    // Find the milestone whose stage index is >= current stage index
    for (let i = milestones.length - 1; i >= 0; i--) {
      const milestoneActiveIdx = activeStages.indexOf(milestones[i].stage)
      if (milestoneActiveIdx !== -1 && currentActiveIdx >= milestoneActiveIdx) {
        return i
      }
    }
    // Current stage is before the first milestone's stage (it's a sub-stage in group)
    // Find the first milestone whose group stage is AFTER the current stage
    for (let i = 0; i < milestones.length; i++) {
      const milestoneActiveIdx = activeStages.indexOf(milestones[i].stage)
      if (milestoneActiveIdx !== -1 && milestoneActiveIdx >= currentActiveIdx) {
        return i
      }
    }
    return 0
  }, [currentStage, milestones, activeStages, isTerminal, isEnrolled])

  const needsPayment =
    (currentStage === 'REGISTERED' || currentStage === 'PAYMENT_PENDING') && !paymentProofUrl

  return (
    <div className="max-w-7xl space-y-8">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white sm:text-3xl">
          Application Status
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Track your progress through the {programmeLabel} admissions pipeline.
        </p>
      </div>

      {/* Registration Code Banner */}
      {registrationCode && (
        <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl bg-aerojet-blue p-6 text-white">
          <div>
            <p className="mb-1 text-xs font-semibold uppercase tracking-widest text-white/60">
              Registration Code
            </p>
            <p className="font-mono text-2xl font-black tracking-widest">
              {registrationCode}
            </p>
          </div>
          <div className="text-right">
            <p className="mb-1 text-xs font-semibold uppercase tracking-widest text-white/60">
              Status
            </p>
            <span
              className={`rounded-full px-3 py-1.5 text-sm font-black uppercase ${
                isEnrolled
                  ? 'bg-green-500'
                  : isTerminal
                    ? currentStage === 'REJECTED'
                      ? 'bg-red-500'
                      : 'bg-gray-500'
                    : 'bg-white/20'
              }`}
            >
              {currentInfo?.shortLabel ?? currentStage}
            </span>
          </div>
        </div>
      )}

      {/* Terminal State Banner */}
      {isTerminal && (
        <div
          className={`rounded-2xl border p-6 ${
            currentStage === 'REJECTED'
              ? 'border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-950/30'
              : 'border-gray-200 bg-gray-50 dark:border-gray-700 dark:bg-gray-900'
          }`}
        >
          <div className="flex items-start gap-3">
            {currentStage === 'REJECTED' ? (
              <XCircle className="mt-0.5 h-6 w-6 shrink-0 text-red-500" />
            ) : (
              <LogOut className="mt-0.5 h-6 w-6 shrink-0 text-gray-500" />
            )}
            <div>
              <h3
                className={`text-lg font-bold ${
                  currentStage === 'REJECTED'
                    ? 'text-red-700 dark:text-red-400'
                    : 'text-gray-700 dark:text-gray-300'
                }`}
              >
                {currentInfo?.label}
              </h3>
              <p className="mt-1 text-sm text-slate-600 dark:text-slate-400">
                {currentInfo?.applicantInstruction}
              </p>
              {rejectionReason && (
                <p className="mt-3 rounded-lg bg-white/60 dark:bg-slate-800/60 px-4 py-3 text-sm text-slate-700 dark:text-slate-300">
                  <span className="font-semibold">Reason: </span>
                  {rejectionReason}
                </p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Progress Bar */}
      {!isTerminal && (
        <div className="rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-2 flex items-center justify-between text-sm">
            <span className="font-semibold text-slate-700 dark:text-slate-300">
              Pipeline Progress
            </span>
            <span className="font-bold text-aerojet-blue dark:text-aerojet-sky">
              {progress}%
            </span>
          </div>
          <div className="h-3 w-full overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
            <div
              className="h-full rounded-full bg-linear-to-r from-aerojet-blue to-aerojet-sky transition-all duration-700 ease-out"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      )}

      {/* Milestone Tracker */}
      {!isTerminal && (
        <div className="rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900 sm:p-8">
          <h2 className="mb-6 font-bold text-slate-900 dark:text-slate-100">
            Admissions Pipeline
          </h2>

          {/* Horizontal milestones — desktop */}
          <div className="hidden md:block">
            <div className="relative flex items-start justify-between">
              {milestones.map((milestone, i) => {
                const isCompleted = i < currentMilestoneIndex || isEnrolled
                const isCurrent = i === currentMilestoneIndex && !isEnrolled
                const isLast = i === milestones.length - 1

                return (
                  <div key={milestone.stage} className="relative flex flex-1 flex-col items-center">
                    {/* Connector line */}
                    {i < milestones.length - 1 && (
                      <div className="absolute left-1/2 top-4 h-0.5 w-full">
                        <div
                          className={`h-full ${
                            isCompleted
                              ? 'bg-green-500'
                              : 'bg-slate-200 dark:bg-slate-700'
                          }`}
                        />
                      </div>
                    )}
                    {/* Circle */}
                    <div
                      className={`relative z-10 flex h-8 w-8 items-center justify-center rounded-full border-2 transition-all ${
                        isCompleted
                          ? 'border-green-500 bg-green-500 text-white'
                          : isCurrent
                            ? 'border-aerojet-blue bg-aerojet-blue text-white ring-4 ring-aerojet-blue/20'
                            : 'border-slate-300 bg-white text-slate-400 dark:border-slate-600 dark:bg-slate-800'
                      }`}
                    >
                      {isCompleted ? (
                        <CheckCircle2 className="h-4 w-4" />
                      ) : isCurrent ? (
                        <Clock className="h-4 w-4" />
                      ) : (
                        <Circle className="h-3 w-3" />
                      )}
                    </div>
                    {/* Label */}
                    <span
                      className={`mt-2 text-center text-xs font-semibold ${
                        isCompleted
                          ? 'text-green-700 dark:text-green-400'
                          : isCurrent
                            ? 'text-aerojet-blue dark:text-aerojet-sky'
                            : 'text-slate-400 dark:text-slate-500'
                      }`}
                    >
                      {milestone.label}
                    </span>
                  </div>
                )
              })}
            </div>
          </div>

          {/* Vertical milestones — mobile */}
          <ol className="relative ml-3 space-y-6 border-l border-slate-200 dark:border-slate-700 md:hidden">
            {milestones.map((milestone, i) => {
              const isCompleted = i < currentMilestoneIndex || isEnrolled
              const isCurrent = i === currentMilestoneIndex && !isEnrolled

              return (
                <li key={milestone.stage} className="ml-6">
                  <span
                    className={`absolute -left-3 flex h-6 w-6 items-center justify-center rounded-full ring-4 ring-white dark:ring-slate-900 ${
                      isCompleted
                        ? 'bg-green-500 text-white'
                        : isCurrent
                          ? 'bg-aerojet-blue text-white'
                          : 'bg-slate-200 dark:bg-slate-700'
                    }`}
                  >
                    {isCompleted ? (
                      <CheckCircle2 className="h-3 w-3" />
                    ) : isCurrent ? (
                      <Clock className="h-3 w-3" />
                    ) : (
                      <Circle className="h-2.5 w-2.5 text-slate-400" />
                    )}
                  </span>
                  <span
                    className={`text-sm font-semibold ${
                      isCompleted
                        ? 'text-green-700 dark:text-green-400'
                        : isCurrent
                          ? 'text-aerojet-blue dark:text-aerojet-sky'
                          : 'text-slate-400 dark:text-slate-500'
                    }`}
                  >
                    {milestone.label}
                  </span>
                </li>
              )
            })}
          </ol>
        </div>
      )}

      {/* Current Stage Card */}
      {!isTerminal && currentInfo && (
        <div className="rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900 sm:p-8">
          <div className="flex items-center gap-3">
            <div
              className={`flex h-10 w-10 items-center justify-center rounded-xl ${currentInfo.color}`}
            >
              <Clock className={`h-5 w-5 ${currentInfo.textColor}`} />
            </div>
            <div>
              <h2 className="font-bold text-slate-900 dark:text-slate-100">
                {currentInfo.label}
              </h2>
              <p className="text-xs text-slate-500 dark:text-slate-400">
                {currentInfo.description}
              </p>
            </div>
          </div>

          <div className="mt-4 rounded-xl bg-slate-50 dark:bg-slate-800/50 p-4">
            <h3 className="mb-1 text-xs font-semibold uppercase tracking-wider text-slate-400">
              What to do next
            </h3>
            <p className="text-sm text-slate-700 dark:text-slate-300">
              {currentInfo.applicantInstruction}
            </p>
          </div>

          {needsPayment && (
            <Link
              href="/applicant/application/payment"
              className="mt-4 inline-flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white transition-colors hover:bg-aerojet-blue/90"
            >
              <CreditCard className="h-4 w-4" />
              Upload Payment Proof
              <ArrowRight className="h-4 w-4" />
            </Link>
          )}

          {currentStage === 'APTITUDE_PENDING' && (
            <Link
              href="/applicant/application/aptitude-test"
              className="mt-4 inline-flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-aerojet-blue/20 transition-all hover:-translate-y-0.5 hover:shadow-xl hover:shadow-aerojet-blue/30"
            >
              <BrainCircuit className="h-4 w-4" />
              Take Aptitude Test
              <ArrowRight className="h-4 w-4" />
            </Link>
          )}

          {currentStage === 'SHORTLISTED' && (
            <div className="mt-4 rounded-xl border border-indigo-200 bg-indigo-50 p-4 dark:border-indigo-800 dark:bg-indigo-900/20">
              <div className="flex items-center gap-2 text-indigo-700 dark:text-indigo-400">
                <ListChecks className="h-5 w-5" />
                <span className="font-bold">You've been shortlisted!</span>
              </div>
              <p className="mt-1 text-sm text-indigo-600 dark:text-indigo-300">
                Our admissions team will contact you shortly to schedule your interview.
              </p>
            </div>
          )}

          {currentStage === 'INTERVIEW_PENDING' && (
            <Link
              href="/applicant/application/interview"
              className="mt-4 inline-flex items-center gap-2 rounded-xl bg-cyan-600 px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-cyan-600/20 transition-all hover:-translate-y-0.5 hover:shadow-xl hover:shadow-cyan-600/30"
            >
              <CalendarDays className="h-4 w-4" />
              Book Interview Slot
              <ArrowRight className="h-4 w-4" />
            </Link>
          )}
        </div>
      )}

      {/* Stage History Timeline */}
      {stageLogs.length > 0 && (
        <div className="rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900 sm:p-8">
          <h2 className="mb-6 font-bold text-slate-900 dark:text-slate-100">
            Application Timeline
          </h2>
          <ol className="relative ml-3 space-y-6 border-l border-slate-200 dark:border-slate-700">
            {stageLogs.map((log) => {
              const toInfo = stageInfo[log.toStage]
              const fromInfo = stageInfo[log.fromStage]
              const isAutoSkipped = !!(log.metadata && (log.metadata as Record<string, unknown>).autoSkipped)

              return (
                <li key={log.id} className="ml-6">
                  <span
                    className={`absolute -left-3 flex h-6 w-6 items-center justify-center rounded-full ring-4 ring-white dark:ring-slate-900 ${
                      toInfo?.color ?? 'bg-slate-200'
                    }`}
                  >
                    <ArrowRight
                      className={`h-3 w-3 ${toInfo?.textColor ?? 'text-slate-400'}`}
                    />
                  </span>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="text-sm font-bold text-slate-700 dark:text-slate-200">
                        {toInfo?.label ?? log.toStage}
                      </h3>
                      {isAutoSkipped && (
                        <span className="rounded bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 text-[10px] font-semibold uppercase text-slate-500 dark:text-slate-400">
                          Auto-skipped
                        </span>
                      )}
                    </div>
                    <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">
                      From {fromInfo?.label ?? log.fromStage}
                    </p>
                    <p className="mt-0.5 text-xs text-slate-400 dark:text-slate-500">
                      {format(new Date(log.createdAt), 'd MMMM yyyy, h:mm a')}
                    </p>
                  </div>
                </li>
              )
            })}

            {/* Application Created entry */}
            <li className="ml-6">
              <span className="absolute -left-3 flex h-6 w-6 items-center justify-center rounded-full bg-slate-100 ring-4 ring-white dark:bg-slate-700 dark:ring-slate-900">
                <Circle className="h-3 w-3 text-slate-400" />
              </span>
              <div>
                <h3 className="text-sm font-bold text-slate-700 dark:text-slate-200">
                  Application Created
                </h3>
                <p className="mt-0.5 text-xs text-slate-400 dark:text-slate-500">
                  {format(new Date(createdAt), 'd MMMM yyyy, h:mm a')}
                </p>
              </div>
            </li>
          </ol>
        </div>
      )}
    </div>
  )
}

import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import { CheckCircle2, Clock, User, CreditCard, ShieldCheck } from 'lucide-react'

import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { serializePrisma } from '@/lib/utils/serialization'
import { formatDateLong } from '@/lib/utils/date'
import {
  isPipelineEnabled,
  getPipelineStageConfig,
  calculateProgress,
} from '@/lib/admissions/state-machine'
import {
  STAGE_INFO,
  getMilestoneStages,
  getActiveStagesForConfig,
} from '@/lib/admissions/constants'
import type { ApplicationStage } from '@prisma/client'
import PipelineTracker from './_components/PipelineTracker'
import { PageTransition } from '@/components/shared/PageTransition'

export const metadata: Metadata = { title: 'Application Status | Applicant Portal' }
export const dynamic = 'force-dynamic'

// ---------------------------------------------------------------------------
// Programme labels
// ---------------------------------------------------------------------------

const PROGRAMME_LABELS: Record<string, string> = {
  FULL_TIME_4YEAR: 'Full-Time 4-Year',
  FULL_TIME_2YEAR: 'Full-Time 2-Year',
  MILITARY_1YEAR: 'Military 1-Year',
  MODULAR: 'Modular',
  EXAM_ONLY: 'Exam Only',
}

// ---------------------------------------------------------------------------
// Page
// ---------------------------------------------------------------------------

export default async function ApplicationStatusPage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const userId = session.user.id

  // Fetch user + application data in parallel with the pipeline feature flag
  const [applicant, pipelineEnabled] = await Promise.all([
    prismaUnfiltered.user.findUnique({
      where: { id: userId },
      select: {
        registrationPaid: true,
        paymentProofUrl: true,
        paymentApprovedAt: true,
        status: true,
        role: true,
        registrationCode: true,
        registrationFee: true,
        registrationCurrency: true,
        createdAt: true,
        email: true,
        profile: {
          select: {
            firstName: true,
            lastName: true,
            phone: true,
            nationality: true,
            country: true,
            city: true,
            dateOfBirth: true,
          },
        },
        application: {
          select: {
            id: true,
            stage: true,
            previousStage: true,
            programmeChoice: true,
            rejectionReason: true,
            createdAt: true,
            stageLogs: {
              orderBy: { createdAt: 'desc' },
              take: 50,
              select: {
                id: true,
                fromStage: true,
                toStage: true,
                actorId: true,
                metadata: true,
                createdAt: true,
              },
            },
          },
        },
      },
    }),
    isPipelineEnabled(),
  ])

  if (!applicant) redirect('/login')

  const application = applicant.application

  // ---------------------------------------------------------------------------
  // Pipeline enabled + application exists => dynamic tracker
  // ---------------------------------------------------------------------------
  if (pipelineEnabled && application) {
    const config = await getPipelineStageConfig(application.programmeChoice)
    const activeStages = getActiveStagesForConfig(config)
    const milestones = getMilestoneStages(config)
    const progress = calculateProgress(application.stage, activeStages)

    // Build a serializable stage info map for the client component
    const stageInfoMap: Record<
      string,
      {
        label: string
        shortLabel: string
        description: string
        color: string
        textColor: string
        applicantInstruction: string
        group: string
      }
    > = {}

    for (const [stage, info] of Object.entries(STAGE_INFO)) {
      stageInfoMap[stage] = {
        label: info.label,
        shortLabel: info.shortLabel,
        description: info.description,
        color: info.color,
        textColor: info.textColor,
        applicantInstruction: info.applicantInstruction,
        group: info.group,
      }
    }

    return (
      <PipelineTracker
        currentStage={application.stage}
        previousStage={application.previousStage}
        programmeLabel={
          PROGRAMME_LABELS[application.programmeChoice] ?? application.programmeChoice
        }
        registrationCode={applicant.registrationCode}
        rejectionReason={application.rejectionReason}
        progress={progress}
        milestones={milestones}
        activeStages={activeStages}
        stageLogs={serializePrisma(application.stageLogs)}
        stageInfo={stageInfoMap}
        paymentProofUrl={applicant.paymentProofUrl}
        createdAt={serializePrisma(application.createdAt)}
      />
    )
  }

  // ---------------------------------------------------------------------------
  // Fallback: pipeline NOT enabled — original 4-step tracker
  // ---------------------------------------------------------------------------

  const isApproved = applicant.status === 'ACTIVE'
  const isRejected = applicant.status === 'SUSPENDED'
  const paymentSubmitted = !!applicant.paymentProofUrl
  const paymentVerified = applicant.registrationPaid

  const steps = [
    {
      label: 'Account Created',
      description: `Registered on ${formatDateLong(applicant.createdAt)}`,
      done: true,
      icon: User,
    },
    {
      label: 'Registration Payment Uploaded',
      description: paymentSubmitted
        ? 'Payment proof has been submitted for review.'
        : `Upload proof of payment for ${applicant.registrationFee} ${applicant.registrationCurrency}.`,
      done: paymentSubmitted,
      icon: CreditCard,
      action: !paymentSubmitted
        ? { label: 'Upload Now', href: '/applicant/application/payment' }
        : undefined,
    },
    {
      label: 'Payment Verified',
      description: paymentVerified
        ? `Verified on ${formatDateLong(applicant.paymentApprovedAt) ?? 'N/A'}`
        : 'Pending admissions review.',
      done: paymentVerified,
      icon: CheckCircle2,
    },
    {
      label: 'Application Approved',
      description: isApproved
        ? 'Your application has been approved! You can now enroll in a course.'
        : isRejected
          ? 'Your application was not accepted. Contact admissions.'
          : 'Pending final admissions decision.',
      done: isApproved,
      icon: ShieldCheck,
    },
  ]

  return (
    <PageTransition className="max-w-7xl space-y-8">
      <div>
        <h1 className="text-aerojet-blue text-3xl font-black tracking-tight dark:text-white">
          Application Status
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Track every step of your registration journey.
        </p>
      </div>

      {/* Application Reference */}
      {applicant.registrationCode && (
        <div className="bg-aerojet-blue flex flex-wrap items-center justify-between gap-4 rounded-2xl p-6 text-white">
          <div>
            <p className="mb-1 text-xs font-semibold tracking-widest text-white/60 uppercase">
              Registration Code
            </p>
            <p className="font-mono text-2xl font-black tracking-widest">
              {applicant.registrationCode}
            </p>
          </div>
          <div className="text-right">
            <p className="mb-1 text-xs font-semibold tracking-widest text-white/60 uppercase">
              Status
            </p>
            <span
              className={`rounded-full px-3 py-1.5 text-sm font-black uppercase ${
                isApproved
                  ? 'bg-green-500'
                  : isRejected
                    ? 'bg-red-500'
                    : paymentVerified
                      ? 'bg-purple-500'
                      : paymentSubmitted
                        ? 'bg-orange-500'
                        : 'bg-slate-500'
              }`}
            >
              {isApproved
                ? 'Approved'
                : isRejected
                  ? 'Rejected'
                  : paymentVerified
                    ? 'Under Review'
                    : paymentSubmitted
                      ? 'Payment Submitted'
                      : 'Payment Pending'}
            </span>
          </div>
        </div>
      )}

      {/* Timeline */}
      <div className="rounded-2xl border border-slate-100 bg-white p-6 sm:p-8 dark:border-slate-800 dark:bg-slate-900">
        <h2 className="mb-6 font-bold text-slate-900 dark:text-slate-100">Application Progress</h2>
        <ol className="relative ml-3 space-y-8 border-l border-slate-200 dark:border-slate-700">
          {steps.map((step, i) => {
            const StepIcon = step.icon
            return (
              <li key={i} className="ml-6">
                <span
                  className={`absolute -left-3 flex h-6 w-6 items-center justify-center rounded-full ring-4 ring-white ${
                    step.done ? 'bg-green-500' : 'bg-slate-200'
                  }`}
                >
                  <StepIcon className={`h-3 w-3 ${step.done ? 'text-white' : 'text-slate-400'}`} />
                </span>
                <div>
                  <h3
                    className={`text-sm font-bold ${step.done ? 'text-green-700' : 'text-slate-700'}`}
                  >
                    {step.label}
                  </h3>
                  <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">
                    {step.description}
                  </p>
                  {step.action && (
                    <Link
                      href={step.action.href}
                      className="text-aerojet-blue hover:text-aerojet-sky mt-2 inline-flex items-center gap-1.5 text-xs font-bold underline underline-offset-2"
                    >
                      <CreditCard className="h-3.5 w-3.5" />
                      {step.action.label}
                    </Link>
                  )}
                </div>
              </li>
            )
          })}
        </ol>
      </div>

      {/* Personal Details Summary */}
      <div className="rounded-2xl border border-slate-100 bg-white p-6 sm:p-8 dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-5 flex items-center justify-between">
          <h2 className="font-bold text-slate-900 dark:text-slate-100">Personal Details</h2>
          <Link
            href="/applicant/profile"
            className="text-aerojet-blue text-xs font-bold hover:underline"
          >
            Edit Profile
          </Link>
        </div>
        <dl className="grid gap-4 text-sm sm:grid-cols-2">
          {[
            {
              label: 'Full Name',
              value: applicant.profile
                ? `${applicant.profile.firstName} ${applicant.profile.lastName}`
                : '\u2014',
            },
            { label: 'Email', value: applicant.email },
            { label: 'Phone', value: applicant.profile?.phone ?? '\u2014' },
            { label: 'Nationality', value: applicant.profile?.nationality ?? '\u2014' },
            { label: 'Country', value: applicant.profile?.country ?? '\u2014' },
            { label: 'City', value: applicant.profile?.city ?? '\u2014' },
          ].map(({ label, value }) => (
            <div key={label} className="flex items-start gap-3">
              <div>
                <dt className="text-xs font-semibold tracking-wide text-slate-400 uppercase">
                  {label}
                </dt>
                <dd className="mt-0.5 font-medium text-slate-700 dark:text-slate-300">{value}</dd>
              </div>
            </div>
          ))}
        </dl>
      </div>
    </PageTransition>
  )
}

import { Metadata } from 'next'
import Link from 'next/link'
import { redirect, notFound } from 'next/navigation'
import { ArrowLeft, Info } from 'lucide-react'

import { getAuthSession } from '@/lib/auth/helpers'
import PaymentMethodsDisplay from '@/components/shared/PaymentMethodsDisplay'
import CoursePaymentUploadForm from '../../_components/CoursePaymentUploadForm'
import { getActivePaymentMethods } from '@/lib/payment-methods'
import { resolveEffectiveEnrollmentType } from '@/lib/enrollment/pathway'
import { prismaUnfiltered, prisma } from '@/lib/prisma/client'
import type { ExamComponent } from '@prisma/client'

export const metadata: Metadata = { title: 'Purchase Course | Applicant Portal' }

interface Props {
  params: Promise<{ id: string }>
}

export default async function PurchasePage({ params }: Props) {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const { id } = await params
  const userId = session.user.id

  const [course, enrollment, paymentMethods] = await Promise.all([
    prismaUnfiltered.course.findUnique({
      where: { id },
      include: { category: true },
    }),
    prismaUnfiltered.enrollment.findFirst({
      where: { userId, courseId: id },
    }),
    getActivePaymentMethods(),
  ])

  if (!course) notFound()

  const applicantState = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      programmeChoice: true,
      studentProfile: {
        select: {
          enrollmentType: true,
          pathwayRel: { select: { code: true } },
          licenseTargets: {
            include: { licenseCategory: true },
          },
        },
      },
    },
  })

  const studentProfile = applicantState?.studentProfile
  const targetLicenseCodes = studentProfile?.licenseTargets
    .map((lt) => lt.licenseCategory.code)
    .join(', ')

  const isRequiredForTarget = await prisma.licenseModuleRequirement.findFirst({
    where: {
      courseId: id,
      licenseCategory: {
        code: { in: studentProfile?.licenseTargets.map((lt) => lt.licenseCategory.code) || [] },
      },
    },
  })

  const effectiveEnrollmentType = resolveEffectiveEnrollmentType({
    pathwayCode: studentProfile?.pathwayRel?.code,
    enrollmentType: studentProfile?.enrollmentType,
    programmeChoice: applicantState?.programmeChoice,
  })
  const isExamOnly = effectiveEnrollmentType === 'EXAM_ONLY'

  const examComponents = isExamOnly
    ? await prisma.examComponent.findMany({
        where: { courseId: id },
        select: { poolPrice: true },
      })
    : []
  const examPrice =
    examComponents.length > 0
      ? Math.min(...examComponents.map((component) => Number(component.poolPrice || 300)))
      : 300

  if (isExamOnly) {
    const wallet = await prisma.wallet.findUnique({
      where: { userId },
      select: { availableBalance: true },
    })

    if (Number(wallet?.availableBalance || 0) < examPrice) {
      redirect('/applicant/wallet-top-up')
    }
  }

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 mx-auto max-w-2xl space-y-8 duration-700">
      <div>
        <Link
          href={`/applicant/courses/${id}`}
          className="inline-flex items-center gap-2 text-sm font-bold text-slate-500 transition-colors hover:text-slate-900 dark:text-slate-100"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Course Details
        </Link>
        <h1 className="text-aerojet-blue mt-4 text-2xl font-black tracking-tight sm:text-3xl dark:text-white">
          {isExamOnly ? 'Book Exam' : 'Purchase Course'}
        </h1>
        <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1">
          <p className="text-sm text-slate-500 dark:text-slate-400">
            {isExamOnly ? 'Complete exam booking for' : 'Complete enrollment for'}{' '}
            <span className="font-bold text-slate-700 dark:text-slate-200">{course.name}</span>
          </p>
          <div className="flex gap-2">
            <span className="inline-flex items-center rounded-full bg-slate-100 px-2.5 py-0.5 text-[10px] font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-400">
              {course.category?.name || course.categoryId || 'CORE'}
            </span>
            {isRequiredForTarget && (
              <span className="inline-flex items-center rounded-full bg-blue-50 px-2.5 py-0.5 text-[10px] font-bold text-blue-600 dark:bg-blue-900/30 dark:text-blue-400">
                Target: {targetLicenseCodes}
              </span>
            )}
          </div>
        </div>
      </div>

      {enrollment?.status === 'ENROLLED' || enrollment?.status === 'APPROVED' ? (
        <div className="rounded-2xl border border-green-200 bg-green-50 p-6 text-center">
          <p className="font-bold text-green-700">You are already enrolled in this course.</p>
          <Link
            href="/student"
            className="mt-4 inline-block text-sm font-bold text-green-800 underline"
          >
            Go to Student Portal
          </Link>
        </div>
      ) : (
        <div className="grid gap-6">
          <div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
            <div className="mb-4 flex items-center justify-between">
              <span className="text-[10px] font-black tracking-widest text-slate-400 uppercase">
                {isExamOnly ? 'Pool seat from' : 'Total Amount'}
              </span>
              <span className="text-aerojet-blue font-mono text-lg font-black dark:text-blue-400">
                {course.currency}{' '}
                {isExamOnly ? examPrice.toLocaleString() : Number(course.price).toLocaleString()}
              </span>
            </div>

            <PaymentMethodsDisplay methods={paymentMethods} />

            <div className="mt-4 flex items-start gap-3 rounded-xl bg-slate-50 p-4 text-xs text-slate-500">
              <Info className="mt-0.5 h-4 w-4 shrink-0 text-slate-400" />
              <p>
                Please use your <strong>Applicant ID</strong> or <strong>Name</strong> as the
                transfer reference to speed up verification.
              </p>
            </div>
          </div>

          <CoursePaymentUploadForm courseId={id} courseName={course.name} />
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { UploadDropzone } from '@/lib/uploads/uploadthing'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { CheckCircle2, FileImage, RefreshCw } from 'lucide-react'

interface Props {
  courseId: string
  courseName: string
}

export default function CoursePaymentUploadForm({ courseId, courseName }: Props) {
  const [uploading, setUploading] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const router = useRouter()

  if (submitted) {
    return (
      <div className="space-y-3 rounded-2xl border border-green-200 bg-green-50 p-6 text-center">
        <CheckCircle2 className="mx-auto h-10 w-10 text-green-500" />
        <p className="font-bold text-green-800">Enrollment Proof Submitted</p>
        <p className="text-sm text-green-600">
          Your payment proof for <strong>{courseName}</strong> has been received. Our team will
          verify it and once approved, you will be onboarded to the student portal.
        </p>
        <button
          onClick={() => setSubmitted(false)}
          className="mx-auto mt-2 block text-xs text-slate-400 underline hover:text-slate-600 dark:text-slate-400"
        >
          <RefreshCw className="mr-1 inline h-3 w-3" />
          Upload a different file
        </button>
      </div>
    )
  }

  return (
    <div className="space-y-4 rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
      <h2 className="font-bold text-slate-900 dark:text-slate-100">Upload Enrollment Proof</h2>
      <p className="text-sm text-slate-500 dark:text-slate-400">
        Upload a screenshot or PDF of your bank transfer receipt for this course.
      </p>

      <UploadDropzone
        endpoint="paymentProof"
        onUploadBegin={() => setUploading(true)}
        onClientUploadComplete={async (res) => {
          setUploading(false)
          if (!res?.[0]?.url) {
            toast.error('Upload failed — no file URL returned.')
            return
          }

          try {
            const response = await fetch(`/api/applicant/courses/${courseId}/enroll`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ proofUrl: res[0].url }),
            })
            const data = await response.json()
            if (!response.ok) {
              toast.error(data.error || 'Failed to submit enrollment request.')
              return
            }
            toast.success('Enrollment submitted for review!')
            setSubmitted(true)
            router.refresh()
          } catch {
            toast.error('Network error while saving enrollment proof.')
          }
        }}
        onUploadError={(error) => {
          setUploading(false)
          toast.error(`Upload error: ${error.message}`)
        }}
        appearance={{
          container:
            'border-2 border-dashed border-slate-200 rounded-xl p-8 cursor-pointer hover:border-aerojet-sky transition-colors',
          label: 'text-slate-700 font-semibold',
          allowedContent: 'text-slate-400 text-xs',
          button:
            'bg-aerojet-blue text-white font-bold px-6 py-2.5 rounded-xl hover:bg-[#003875] transition-colors',
        }}
      />

      {uploading && (
        <p className="animate-pulse text-center text-sm text-slate-500 dark:text-slate-400">
          Uploading…
        </p>
      )}
    </div>
  )
}

