async function CourseList({
  category,
  canEnroll,
  enrollmentType,
  visibility,
}: {
  category?: string
  canEnroll: boolean
  enrollmentType: string | null
  visibility: ReturnType<typeof getCatalogVisibility>
}) {
  const coursesRaw = await prisma.course.findMany({
    where: {
      isActive: true,
      ...(category ? { category: { name: category } } : {}),
    },
    include: {
      category: true,
      examComponents: {
        select: { poolPrice: true },
      },
    },
    orderBy: [{ category: { name: 'asc' } }, { code: 'asc' }],
  })

  const courses = coursesRaw.sort((a: { code: string }, b: { code: string }) =>
    a.code.localeCompare(b.code, undefined, { numeric: true, sensitivity: 'base' })
  )

  if (courses.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center rounded-3xl border border-dashed border-slate-200 bg-slate-50/50 py-20 text-center dark:border-slate-800 dark:bg-slate-900/50">
        <div className="mb-4 flex h-20 w-20 items-center justify-center rounded-2xl bg-white shadow-sm dark:bg-slate-900">
          <BookOpen className="h-10 w-10 text-slate-300 dark:text-slate-700" />
        </div>
        <h3 className="text-xl font-black text-slate-900 dark:text-slate-100">No Modules Found</h3>
        <p className="mt-2 text-sm font-medium text-slate-500 dark:text-slate-400">
          Try adjusting your category filter or check back later for new additions.
        </p>
      </div>
    )
  }

  const grouped = courses.reduce(
    (acc, course) => {
      const cat = course.category?.name || 'GENERAL'
      if (!acc[cat]) acc[cat] = []
      acc[cat].push(course)
      return acc
    },
    {} as Record<string, typeof courses>
  )

  const isExamOnly = enrollmentType === 'EXAM_ONLY'
  const isDirectPurchasePath = visibility.canPurchaseEasaModules || isExamOnly

  return (
    <div className="space-y-16">
      {Object.entries(grouped).map(([cat, items]) => (
        <div key={cat} className="space-y-8">
          <div className="flex items-center gap-4">
            <h2 className="dark:text-aerojet-sky text-[10px] font-black tracking-[0.3em] text-blue-500 uppercase">
              {cat.replace(/_/g, ' ')}
            </h2>
            <div className="h-px flex-1 bg-slate-100 dark:bg-slate-800/50" />
          </div>

          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {items.map((course) => {
              const poolPrices = course.examComponents
                .map((component) => Number(component.poolPrice || 0))
                .filter((price) => price > 0)
              const displayPrice = isExamOnly
                ? poolPrices.length > 0
                  ? Math.min(...poolPrices)
                  : null
                : Number(course.price)
              const ctaHref = isDirectPurchasePath
                ? `/applicant/courses/${course.id}`
                : '/applicant/pathway'
              const ctaLabel = isExamOnly
                ? displayPrice
                  ? 'Book Exam'
                  : 'View Module'
                : isDirectPurchasePath
                  ? 'Enroll'
                  : 'Programme Route'

              return (
                <div
                  key={course.id}
                  className="group hover:border-aerojet-sky/30 hover:shadow-aerojet-blue/5 relative flex flex-col overflow-hidden rounded-3xl border border-slate-100 bg-white shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-xl dark:border-slate-800 dark:bg-slate-900"
                >
                  <TrackedImpression courseId={course.id} />
                  <div
                    className={`absolute top-0 left-0 h-1 w-full transition-all group-hover:h-1.5 ${
                      categoryColor[cat]?.split(' ')[2]?.replace('border-', 'bg-') || 'bg-slate-200'
                    }`}
                  />

                  <div className="flex flex-1 flex-col p-7">
                    <div className="mb-4 flex items-start justify-between gap-3">
                      <span className="text-aerojet-sky group-hover:bg-aerojet-sky/10 rounded-lg bg-slate-50 px-2.5 py-1 font-mono text-[10px] font-black tracking-widest uppercase transition-colors dark:bg-slate-800">
                        {course.code}
                      </span>
                      <span
                        className={`rounded-full border px-2.5 py-1 text-[10px] font-black tracking-wide uppercase ${
                          categoryColor[cat] || 'border-slate-200 bg-slate-50 text-slate-700'
                        }`}
                      >
                        {cat.replace(/_/g, ' ')}
                      </span>
                    </div>

                    <h3 className="text-aerojet-blue group-hover:text-aerojet-sky text-xl leading-tight font-black transition-colors dark:text-white dark:group-hover:text-blue-400">
                      {course.name}
                    </h3>

                    {course.description && (
                      <p className="mt-4 line-clamp-3 text-sm leading-relaxed text-slate-500 dark:text-slate-400">
                        {course.description}
                      </p>
                    )}

                    <div className="mt-6 flex flex-wrap gap-4 text-[11px] font-bold text-slate-400">
                      {course.duration && (
                        <div className="flex items-center gap-1.5 rounded-lg border border-slate-50 bg-slate-50/50 px-2 py-1 dark:border-slate-800 dark:bg-slate-800/30">
                          <Clock className="text-aerojet-sky h-3.5 w-3.5" />
                          <span className="text-slate-600 dark:text-slate-300">
                            {course.duration.toLocaleString()} Hours
                          </span>
                        </div>
                      )}
                      <div className="flex items-center gap-1.5 rounded-lg border border-slate-50 bg-slate-50/50 px-2 py-1 dark:border-slate-800 dark:bg-slate-800/30">
                        <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" />
                        <span className="text-slate-600 dark:text-slate-300">Certified</span>
                      </div>
                    </div>

                    <div className="mt-8 flex items-center justify-between gap-4 border-t border-slate-50 pt-6 dark:border-slate-800/50">
                      <div className="min-w-0">
                        <p className="text-[10px] font-black tracking-widest text-slate-400 uppercase">
                          {isExamOnly
                            ? 'Pool seat from'
                            : isDirectPurchasePath
                              ? 'Tuition'
                              : 'Programme access'}
                        </p>
                        <p className="text-aerojet-blue truncate text-2xl font-black dark:text-white">
                          {displayPrice !== null
                            ? `${course.currency} ${displayPrice.toLocaleString()}`
                            : 'By module'}
                        </p>
                      </div>
                      {canEnroll ? (
                        <TrackedCourseLink
                          courseId={course.id}
                          href={ctaHref}
                          className="bg-aerojet-blue inline-flex h-11 items-center justify-center rounded-xl px-6 text-xs font-black tracking-widest text-white uppercase ring-offset-white transition-all hover:bg-[#003875] hover:shadow-lg active:scale-95 sm:px-8 dark:bg-blue-600 dark:hover:bg-blue-500"
                        >
                          {ctaLabel}
                        </TrackedCourseLink>
                      ) : (
                        <span className="inline-flex h-11 cursor-not-allowed items-center justify-center rounded-xl bg-slate-50 px-6 text-xs font-black tracking-widest text-slate-400 uppercase dark:bg-slate-800/50">
                          Locked
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      ))}
    </div>
  )
}

