async function PoolList() {
  // Get open/upcoming exam pools
  const currency = await getSystemSetting('course_currency', 'EUR')

  const { getCurrencySymbol } = await import('@/lib/currency')
  const symbol = getCurrencySymbol(currency)

  const pools = await prismaUnfiltered.examPool.findMany({
    where: {
      status: { in: ['OPEN', 'NEAR_FULL', 'CONFIRMED', 'DRAFT'] },
    },
    include: {
      event: {
        select: {
          name: true,
          startDate: true,
          endDate: true,
          location: true,
        },
      },
      _count: { select: { memberships: { where: { status: { in: ACTIVE_MEMBERSHIP_STATUSES } } } } },
    },
    orderBy: { createdAt: 'desc' },
    take: 30,
  })

  if (pools.length === 0) {
    return (
      <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-12 text-center dark:border-slate-700 dark:bg-slate-800/50">
        <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-white text-slate-300 shadow-sm dark:bg-slate-900">
          <BookOpen className="h-8 w-8" />
        </div>
        <h3 className="text-lg font-bold text-slate-900 dark:text-slate-100">No open exam bookings</h3>
        <p className="mx-auto mt-2 max-w-sm text-sm text-slate-500 dark:text-slate-400">
          There are currently no active exam bookings open for registration. Exam bookings will be listed
          here when they become available.
        </p>
      </div>
    )
  }

  return (
    <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
      {pools.map((pool) => {
        const currentCount = pool._count.memberships
        const maxCandidates = pool.maxCandidates
        const fillPct = maxCandidates > 0 ? Math.round((currentCount / maxCandidates) * 100) : 0

        return (
          <div
            key={pool.id}
            className="flex flex-col gap-4 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"
          >
            {/* Header */}
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="mb-1 font-mono text-xs font-bold text-slate-400">Exam Booking</p>
                <h2 className="text-base leading-snug font-bold text-slate-900 dark:text-slate-100">
                  {pool.event?.name ?? pool.name ?? 'Exam Booking'}
                </h2>
              </div>
              <span
                className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-bold tracking-widest uppercase ${poolStatusColor[pool.status] ?? 'bg-slate-100 text-slate-500'}`}
              >
                {poolStatusLabel[pool.status] ?? pool.status}
              </span>
            </div>

            {/* Details */}
            <div className="space-y-2 text-xs text-slate-500 dark:text-slate-400">
              {pool.event?.startDate && (
                <div className="flex items-center gap-2">
                  <CalendarDays className="h-3.5 w-3.5 shrink-0 text-slate-400" />
                  {pool.event.startDate.toLocaleDateString('en-GB', {
                    weekday: 'short',
                    day: 'numeric',
                    month: 'short',
                    year: 'numeric',
                  })}
                </div>
              )}
              {pool.event?.location && (
                <div className="flex items-center gap-2">
                  <MapPin className="h-3.5 w-3.5 shrink-0 text-slate-400" />
                  {pool.event.location}
                </div>
              )}

              <div className="flex items-center gap-2">
                <Users className="h-3.5 w-3.5 shrink-0 text-slate-400" />
                {currentCount} / {maxCandidates} registered
              </div>
            </div>

            {/* Fill bar */}
            <div>
              <div className="mb-1 flex justify-between text-[10px] text-slate-400">
                <span>Capacity</span>
                <span>{fillPct}%</span>
              </div>
              <div className="h-1.5 overflow-hidden rounded-full bg-slate-100">
                <div
                  className={`h-full rounded-full transition-all ${fillPct >= 90 ? 'bg-red-400' : fillPct >= 70 ? 'bg-orange-400' : 'bg-green-400'}`}
                  style={{ width: `${fillPct}%` }}
                />
              </div>
            </div>

            {/* Fee */}
            <div className="mt-auto flex items-center justify-between border-t border-slate-50 pt-3">
              <div>
                <p className="text-[10px] text-slate-400">Exam Fee</p>
                <p className="text-base font-black text-aerojet-blue dark:text-blue-400">
                  {currency} {Number(pool.seatPrice).toLocaleString()}
                </p>
              </div>
              <Link
                href={`/applicant/exam-bookings/${pool.id}`}
                className="text-xs font-bold text-aerojet-blue hover:underline"
              >
                View Details
              </Link>
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { ChevronUp, ChevronDown, Loader2 } from 'lucide-react'
import { GroupedCourse } from './examOnlyTypes'

interface BundleSelectionModalProps {
  bundleType: 'TWO_SEAT' | 'FOUR_SEAT' | null
  onCancel: () => void
  selectedModules: string[]
  setSelectedModules: (next: string[]) => void
  expandedCourse: string | null
  setExpandedCourse: (value: string | null) => void
  groupedComponents: Record<string, GroupedCourse>
  onConfirm: (bundleType: 'TWO_SEAT' | 'FOUR_SEAT', componentIds: string[]) => void
  fmt: (amount: number) => string
  twoSeatPrice: number
  fourSeatPrice: number
  purchasingBundle: string | null
}

export default function BundleSelectionModal({
  bundleType,
  onCancel,
  selectedModules,
  setSelectedModules,
  expandedCourse,
  setExpandedCourse,
  groupedComponents,
  onConfirm,
  fmt,
  twoSeatPrice,
  fourSeatPrice,
  purchasingBundle,
}: BundleSelectionModalProps) {
  if (!bundleType) return null

  const requiredSeats = bundleType === 'TWO_SEAT' ? 2 : 4

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4 backdrop-blur-sm">
      <div className="w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-xl dark:bg-slate-900">
        <div className="border-b border-slate-100 p-6 dark:border-slate-800">
          <h3 className="text-xl font-bold text-slate-900 dark:text-slate-100">
            Select {bundleType === 'TWO_SEAT' ? '2' : '4'} Modules
          </h3>
          <p className="mt-1 text-sm text-slate-500">
            Choose the modules for your {bundleType === 'TWO_SEAT' ? 'Twin Pack' : '4-Pack'}.
            <span className="ml-1 font-semibold text-indigo-600">
              {selectedModules.length}/{requiredSeats} selected
            </span>
          </p>
        </div>

        <div className="max-h-[50vh] overflow-y-auto p-6">
          <div className="space-y-2">
            {Object.values(groupedComponents)
              .sort((a, b) => a.code.localeCompare(b.code, undefined, { numeric: true }))
              .map((course) => {
                const isExpanded = expandedCourse === `bun_${course.code}`
                const selectedInCourse = course.components.filter((c) =>
                  selectedModules.includes(c.id)
                ).length
                const isMaxSelected = selectedModules.length >= requiredSeats

                return (
                  <div
                    key={course.code}
                    className="rounded-xl border border-slate-200 dark:border-slate-700"
                  >
                    <button
                      onClick={() =>
                        setExpandedCourse(isExpanded ? null : `bun_${course.code}`)
                      }
                      className="flex w-full items-center justify-between p-4 text-left"
                    >
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-slate-900 dark:text-slate-100">
                          {course.code}: {course.name}
                        </span>
                        {selectedInCourse > 0 && (
                          <span className="rounded-full bg-indigo-100 px-2 py-0.5 text-xs font-bold text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300">
                            {selectedInCourse} selected
                          </span>
                        )}
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-slate-400">{course.components.length}</span>
                        {isExpanded ? (
                          <ChevronUp className="h-4 w-4 text-slate-400" />
                        ) : (
                          <ChevronDown className="h-4 w-4 text-slate-400" />
                        )}
                      </div>
                    </button>
                    {isExpanded && (
                      <div className="border-t border-slate-100 px-4 pb-4 dark:border-slate-800">
                        <div className="mt-3 space-y-2">
                          {course.components
                            .sort((a, b) => a.code.localeCompare(b.code, undefined, { numeric: true }))
                            .map((component) => {
                              const isSelected = selectedModules.includes(component.id)
                              return (
                                <label
                                  key={component.id}
                                  className={`flex cursor-pointer items-center gap-3 rounded-lg border p-3 transition-colors ${
                                    isSelected
                                      ? 'border-indigo-500 bg-indigo-50/50 dark:border-indigo-400 dark:bg-indigo-900/20'
                                      : 'border-slate-100 hover:border-slate-300 dark:border-slate-800 dark:hover:border-slate-600'
                                  } ${isMaxSelected && !isSelected ? 'cursor-not-allowed opacity-50' : ''}`}
                                >
                                  <input
                                    type="checkbox"
                                    className="h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                                    checked={isSelected}
                                    disabled={isMaxSelected && !isSelected}
                                    onChange={(e) => {
                                      if (e.target.checked && !isMaxSelected) {
                                        setSelectedModules([...selectedModules, component.id])
                                      } else if (!e.target.checked) {
                                        setSelectedModules(
                                          selectedModules.filter((id) => id !== component.id)
                                        )
                                      }
                                    }}
                                  />
                                  <div className="flex-1">
                                    <p className="text-sm font-semibold text-slate-900 dark:text-slate-100">
                                      {component.code} - {component.name}
                                    </p>
                                    <p className="text-xs text-slate-500">
                                      {component.type} &bull; {component.duration}m
                                    </p>
                                  </div>
                                </label>
                              )
                            })}
                        </div>
                      </div>
                    )}
                  </div>
                )
              })}
          </div>
        </div>

        <div className="flex gap-3 border-t border-slate-100 bg-slate-50 p-6 dark:border-slate-800 dark:bg-slate-900">
          <button
            onClick={onCancel}
            className="flex-1 rounded-xl border border-slate-200 bg-white py-3 text-center text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
          >
            Cancel
          </button>
          <button
            onClick={() => onConfirm(bundleType, selectedModules)}
            disabled={selectedModules.length !== requiredSeats}
            className="flex-1 rounded-xl bg-indigo-600 py-3 text-center text-sm font-bold text-white hover:bg-indigo-700 disabled:opacity-50"
          >
            Confirm & Purchase ({fmt(bundleType === 'TWO_SEAT' ? twoSeatPrice : fourSeatPrice)})
          </button>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  History,
  X,
  AlertCircle,
  CheckCircle2,
  Clock,
  XCircle,
  Loader2,
  ArrowUpRight,
  ArrowDownRight,
  Wallet,
} from 'lucide-react'

interface Transaction {
  id: string
  amount: number
  type: string
  status: string
  createdAt: string
  referenceType?: string
  referenceId?: string
  description?: string
}

interface Payment {
  id: string
  amount: number
  status: string
  paymentMethod?: string
  createdAt: string
  rejectionReason?: string
}

interface TransactionHistoryProps {
  transactions: Transaction[]
  payments: Payment[]
}

interface StatusConfig {
  APPROVED: {
    color: 'text-green-600'
    bg: 'bg-green-50'
    icon: typeof CheckCircle2
    label: 'Approved'
  }
  PENDING: { color: 'text-orange-600'; bg: 'bg-orange-50'; icon: typeof Clock; label: 'Pending' }
  REJECTED: { color: 'text-red-600'; bg: 'bg-red-50'; icon: typeof XCircle; label: 'Rejected' }
  COMPLETED: {
    color: 'text-green-600'
    bg: 'bg-green-50'
    icon: typeof CheckCircle2
    label: 'Completed'
  }
  FAILED: { color: 'text-red-600'; bg: 'bg-red-50'; icon: typeof XCircle; label: 'Failed' }
  TOP_UP: { color: 'text-green-600'; bg: 'bg-green-50'; icon: typeof ArrowUpRight; label: 'Credit' }
  DEBIT: { color: 'text-red-600'; bg: 'bg-red-50'; icon: typeof ArrowDownRight; label: 'Debit' }
  RESERVE: { color: 'text-orange-600'; bg: 'bg-orange-50'; icon: typeof Clock; label: 'Reserved' }
}

export default function TransactionHistory({ transactions, payments }: TransactionHistoryProps) {
  const router = useRouter()
  const [showCancelModal, setShowCancelModal] = useState<string | null>(null)
  const [cancelReason, setCancelReason] = useState('')
  const [cancelling, setCancelling] = useState(false)

  const statusConfig: StatusConfig = {
    APPROVED: { color: 'text-green-600', bg: 'bg-green-50', icon: CheckCircle2, label: 'Approved' },
    PENDING: { color: 'text-orange-600', bg: 'bg-orange-50', icon: Clock, label: 'Pending' },
    REJECTED: { color: 'text-red-600', bg: 'bg-red-50', icon: XCircle, label: 'Rejected' },
    COMPLETED: {
      color: 'text-green-600',
      bg: 'bg-green-50',
      icon: CheckCircle2,
      label: 'Completed',
    },
    FAILED: { color: 'text-red-600', bg: 'bg-red-50', icon: XCircle, label: 'Failed' },
    TOP_UP: { color: 'text-green-600', bg: 'bg-green-50', icon: ArrowUpRight, label: 'Credit' },
    DEBIT: { color: 'text-red-600', bg: 'bg-red-50', icon: ArrowDownRight, label: 'Debit' },
    RESERVE: { color: 'text-orange-600', bg: 'bg-orange-50', icon: Clock, label: 'Reserved' },
  }

  const handleCancelPayment = async (paymentId: string) => {
    if (!cancelReason || cancelReason.trim().length < 10) {
      toast.error('Please provide a reason (min 10 characters)')
      return
    }

    setCancelling(true)
    try {
      const res = await fetch(`/api/applicant/exam-only/payments/${paymentId}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: cancelReason }),
      })

      const data = await res.json()

      if (!res.ok) {
        toast.error(data.error || 'Failed to cancel payment')
        return
      }

      toast.success('Payment cancelled successfully')
      setShowCancelModal(null)
      setCancelReason('')
      router.refresh()
    } catch (error) {
      toast.error('Network error. Please try again.')
    } finally {
      setCancelling(false)
    }
  }

  const allItems = [
    ...transactions.map((t) => ({ ...t, itemType: 'transaction' as const })),
    ...payments.map((p) => ({ ...p, itemType: 'payment' as const })),
  ].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())

  if (allItems.length === 0) {
    return (
      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
        <div className="border-b border-slate-100 bg-slate-50 px-6 py-4 dark:border-slate-700 dark:bg-slate-800/50">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-200 dark:bg-slate-700">
              <History className="h-5 w-5 text-slate-500" />
            </div>
            <div>
              <h3 className="font-bold text-slate-900 dark:text-slate-100">Transaction History</h3>
              <p className="text-xs text-slate-500">Your wallet activity</p>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-center justify-center py-12">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-slate-100 dark:bg-slate-800">
            <Wallet className="h-8 w-8 text-slate-300" />
          </div>
          <p className="font-medium text-slate-500">No transactions yet</p>
          <p className="text-sm text-slate-400">Your wallet transactions will appear here</p>
        </div>
      </div>
    )
  }

  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">
        <div className="border-b border-slate-100 bg-slate-50 px-6 py-4 dark:border-slate-700 dark:bg-slate-800/50">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-200 dark:bg-slate-700">
                <History className="h-5 w-5 text-slate-500" />
              </div>
              <div>
                <h3 className="font-bold text-slate-900 dark:text-slate-100">
                  Transaction History
                </h3>
                <p className="text-xs text-slate-500">{allItems.length} transactions</p>
              </div>
            </div>
          </div>
        </div>

        <div className="divide-y divide-slate-100 dark:divide-slate-800">
          {allItems.map((item) => {
            const isPayment = item.itemType === 'payment'
            const transactionType = isPayment ? '' : (item as Transaction).type
            const status = isPayment ? item.status : transactionType
            const config =
              (status in statusConfig
                ? statusConfig[status as keyof typeof statusConfig]
                : statusConfig.PENDING) || statusConfig.PENDING
            const StatusIcon = config.icon
            const isCredit =
              isPayment || transactionType === 'TOP_UP' || transactionType === 'REFUND'
            const isDebit = transactionType === 'DEBIT' || transactionType === 'RESERVE'

            return (
              <div
                key={item.id}
                className="group px-6 py-4 transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50"
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-4">
                    <div
                      className={`mt-0.5 flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${config.bg} dark:bg-slate-800`}
                    >
                      <StatusIcon className={`h-5 w-5 ${config.color}`} />
                    </div>
                    <div>
                      <p className="font-semibold text-slate-900 dark:text-slate-100">
                        {isPayment ? 'Wallet Top-Up' : item.description || item.type}
                      </p>
                      <div className="mt-1 flex items-center gap-2 text-xs text-slate-500">
                        <span>{new Date(item.createdAt).toLocaleDateString()}</span>
                        <span>•</span>
                        <span>{new Date(item.createdAt).toLocaleTimeString()}</span>
                        {isPayment && item.paymentMethod && (
                          <>
                            <span>•</span>
                            <span className="capitalize">{item.paymentMethod}</span>
                          </>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div
                      className={`flex items-center gap-1 font-bold ${
                        isCredit
                          ? 'text-green-600'
                          : isDebit
                            ? 'text-orange-600'
                            : 'text-slate-900 dark:text-slate-100'
                      }`}
                    >
                      {isCredit && <ArrowUpRight className="h-4 w-4" />}
                      {isDebit && <ArrowDownRight className="h-4 w-4" />}
                      <span>€{Number(item.amount).toFixed(2)}</span>
                    </div>
                    <span
                      className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${config.bg} ${config.color}`}
                    >
                      <StatusIcon className="h-3 w-3" />
                      {config.label}
                    </span>
                  </div>
                </div>

                {/* Actions for pending payments */}
                {isPayment && item.status === 'PENDING' && (
                  <div className="mt-3 flex justify-end">
                    <button
                      onClick={() => setShowCancelModal(item.id)}
                      className="flex items-center gap-1.5 rounded-lg border border-red-200 bg-red-50 px-3 py-1.5 text-xs font-medium text-red-600 transition-colors hover:bg-red-100 dark:border-red-900/30 dark:bg-red-900/20 dark:text-red-400"
                    >
                      <X className="h-3 w-3" />
                      Cancel
                    </button>
                  </div>
                )}

                {/* Rejection reason */}
                {isPayment && item.status === 'REJECTED' && item.rejectionReason && (
                  <div className="mt-3 rounded-lg border border-red-100 bg-red-50/50 p-3 dark:border-red-900/20 dark:bg-red-900/10">
                    <p className="text-xs font-medium text-red-600 dark:text-red-400">
                      <AlertCircle className="mr-1 inline h-3 w-3" />
                      Reason: {item.rejectionReason}
                    </p>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      </div>

      {/* Cancel Modal */}
      {showCancelModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
          <div className="w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl dark:bg-slate-900">
            <div className="border-b border-slate-100 bg-red-50 px-6 py-4 dark:border-slate-800 dark:bg-red-900/20">
              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-red-100 dark:bg-red-900/30">
                  <AlertCircle className="h-5 w-5 text-red-600 dark:text-red-400" />
                </div>
                <div>
                  <h3 className="font-bold text-red-900 dark:text-red-300">Cancel Payment</h3>
                  <p className="text-xs text-red-600 dark:text-red-400">
                    This action cannot be undone
                  </p>
                </div>
              </div>
            </div>

            <div className="p-6">
              <div className="mb-4">
                <label className="mb-2 block text-sm font-medium text-slate-700 dark:text-slate-300">
                  Reason for cancellation
                </label>
                <textarea
                  value={cancelReason}
                  onChange={(e) => setCancelReason(e.target.value)}
                  placeholder="Please provide a reason (min 10 characters)..."
                  className="w-full rounded-xl border-2 border-slate-200 p-3 text-sm transition-colors focus:border-red-400 focus:outline-none dark:border-slate-700 dark:bg-slate-800"
                  rows={3}
                />
                <p className="mt-1 text-xs text-slate-400">
                  {cancelReason.length}/10 characters minimum
                </p>
              </div>

              <div className="flex gap-3">
                <button
                  onClick={() => {
                    setShowCancelModal(null)
                    setCancelReason('')
                  }}
                  className="flex-1 rounded-xl border-2 border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-600 transition-colors hover:bg-slate-50 dark:border-slate-700 dark:text-slate-400 dark:hover:bg-slate-800"
                >
                  Keep Payment
                </button>
                <button
                  onClick={() => handleCancelPayment(showCancelModal)}
                  disabled={cancelling || cancelReason.length < 10}
                  className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-red-600 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {cancelling ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <>
                      <X className="h-4 w-4" />
                      Cancel Payment
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  Wallet,
  CircleDot,
  Circle,
  AlertCircle,
  Loader2,
  CheckCircle2,
  Building,
  Smartphone,
  CreditCard,
  Upload,
  ArrowRight,
  PiggyBank,
} from 'lucide-react'
import { UploadDropzone } from '@/lib/uploads/uploadthing'

interface PaymentMethod {
  id: string
  name: string
  type: string
  instructions?: string
  details?: Record<string, string>
}

interface WalletTopUpFormProps {
  minAmount: number
  currency?: string
  paymentMethods: PaymentMethod[]
}

const FIXED_AMOUNTS = [300, 500, 1000, 2000]

export default function WalletTopUpForm({
  minAmount,
  currency = 'EUR',
  paymentMethods = [],
}: WalletTopUpFormProps) {
  const router = useRouter()
  const [step, setStep] = useState<'amount' | 'payment' | 'success'>('amount')
  const [selectedAmount, setSelectedAmount] = useState<number | null>(null)
  const [customAmount, setCustomAmount] = useState('')
  const [selectedMethodId, setSelectedMethodId] = useState<string>('')
  const [uploading, setUploading] = useState(false)
  const [proofUrl, setProofUrl] = useState<string>('')

  const getAmount = (): number => {
    if (selectedAmount !== null) return selectedAmount
    const val = parseFloat(customAmount)
    return isNaN(val) ? 0 : val
  }

  const isCustomValid = (): boolean => {
    const val = parseFloat(customAmount)
    return !isNaN(val) && val >= minAmount
  }

  const isAmountSelected = (): boolean => {
    if (selectedAmount !== null) return true
    return !!customAmount && isCustomValid()
  }

  const selectedMethod = paymentMethods.find((m) => m.id === selectedMethodId)

  const handleAmountContinue = () => {
    if (!isAmountSelected()) {
      toast.error('Please select or enter an amount')
      return
    }
    if (!selectedMethodId && paymentMethods.length > 0) {
      setSelectedMethodId(paymentMethods[0].id)
    }
    setStep('payment')
  }

  const handleUploadComplete = async (res: { url: string }[]) => {
    if (res && res[0]?.url) {
      setProofUrl(res[0].url)
      setUploading(true)

      try {
        const apiRes = await fetch('/api/applicant/exam-only/top-up', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            amount: getAmount(),
            paymentMethodId: selectedMethodId,
            proofUrl: res[0].url,
          }),
        })

        const data = await apiRes.json()

        if (!apiRes.ok) {
          if (data.error && data.error.includes('pending')) {
            toast.error('You already have a pending top-up. Please wait for it to be processed.')
          } else {
            toast.error(data.error || 'Failed to submit payment')
          }
          setProofUrl('')
          return
        }

        toast.success('Payment submitted successfully!')
        setStep('success')
      } catch (error) {
        console.error('Payment error:', error)
        toast.error('Network error. Please try again.')
      } finally {
        setUploading(false)
      }
    }
  }

  const handleBack = () => {
    if (step === 'payment') {
      setStep('amount')
    }
  }

  const getMethodIcon = (type: string) => {
    switch (type) {
      case 'BANK_TRANSFER':
        return <Building className="h-6 w-6" />
      case 'MOBILE_MONEY':
        return <Smartphone className="h-6 w-6" />
      case 'CARD_STRIPE':
        return <CreditCard className="h-6 w-6" />
      default:
        return <Wallet className="h-6 w-6" />
    }
  }

  // Step 1: Amount Selection
  if (step === 'amount') {
    return (
      <div className="space-y-6">
        {/* Amount Selection Card */}
        <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">
          <div className="bg-linear-to-r from-aerojet-blue to-aerojet-sky px-6 py-4">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/20 backdrop-blur">
                <PiggyBank className="h-5 w-5 text-white" />
              </div>
              <div>
                <h3 className="font-bold text-white">Top Up Your Wallet</h3>
                <p className="text-xs text-white/80">Minimum: €{minAmount}</p>
              </div>
            </div>
          </div>

          <div className="p-6">
            <p className="mb-5 text-sm text-slate-600 dark:text-slate-400">
              Choose an amount to add to your wallet for exam bookings.
            </p>

            {/* Fixed Amount Options */}
            <div className="mb-5 grid grid-cols-2 gap-3">
              {FIXED_AMOUNTS.map((amount) => (
                <button
                  key={amount}
                  type="button"
                  onClick={() => {
                    setSelectedAmount(amount)
                    setCustomAmount('')
                  }}
                  className={`group relative overflow-hidden rounded-xl border-2 p-4 text-center transition-all hover:shadow-md ${
                    selectedAmount === amount
                      ? 'border-aerojet-blue bg-aerojet-blue/5 dark:border-blue-500 dark:bg-blue-500/10'
                      : 'border-slate-200 hover:border-slate-300 dark:border-slate-700'
                  }`}
                >
                  {selectedAmount === amount && (
                    <div className="absolute top-0 right-0">
                      <div className="h-0 w-0 border-b-20 border-l-20 border-b-transparent border-l-aerojet-blue" />
                    </div>
                  )}
                  <span
                    className={`text-xl font-black ${
                      selectedAmount === amount
                        ? 'text-aerojet-blue dark:text-blue-400'
                        : 'text-slate-900 dark:text-slate-100'
                    }`}
                  >
                    €{amount}
                  </span>
                  {amount === 500 && (
                    <span className="absolute -top-1 -right-1 rounded-full bg-amber-100 px-2 py-0.5 text-[10px] font-bold text-amber-700">
                      Popular
                    </span>
                  )}
                </button>
              ))}
            </div>

            {/* Custom Amount */}
            <div className="space-y-2">
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300">
                <button
                  type="button"
                  onClick={() => setSelectedAmount(null)}
                  className="flex items-center"
                >
                  {selectedAmount === null && !customAmount ? (
                    <CircleDot className="mr-2 h-5 w-5 text-aerojet-blue dark:text-blue-400" />
                  ) : (
                    <Circle className="mr-2 h-5 w-5 text-slate-300" />
                  )}
                  Custom Amount
                </button>
              </label>
              {selectedAmount === null && (
                <div className="relative">
                  <span className="absolute top-1/2 left-4 -translate-y-1/2 text-lg font-bold text-slate-400">
                    €
                  </span>
                  <input
                    type="number"
                    value={customAmount}
                    onChange={(e) => setCustomAmount(e.target.value)}
                    min={minAmount}
                    step="0.01"
                    placeholder={`Min. ${minAmount}`}
                    className="w-full rounded-xl border-2 border-slate-200 bg-slate-50 py-3 pr-4 pl-10 text-lg font-bold transition-all outline-none focus:border-aerojet-blue focus:bg-white dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
              )}
              {customAmount && !isCustomValid() && (
                <p className="flex items-center gap-1 text-sm text-red-500">
                  <AlertCircle className="h-4 w-4" />
                  Minimum amount is €{minAmount}
                </p>
              )}
            </div>
          </div>

          {/* Continue Button */}
          {isAmountSelected() && (
            <div className="border-t border-slate-100 bg-slate-50 px-6 py-4 dark:border-slate-800 dark:bg-slate-800/50">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-slate-500 dark:text-slate-400">Amount to pay</p>
                  <p className="text-2xl font-black text-aerojet-blue dark:text-blue-400">
                    €{getAmount().toLocaleString()}
                  </p>
                </div>
                <button
                  onClick={handleAmountContinue}
                  className="flex items-center gap-2 rounded-xl bg-linear-to-r from-aerojet-blue to-aerojet-sky px-6 py-3 font-bold text-white shadow-lg shadow-blue-500/25 transition-all hover:shadow-xl hover:shadow-blue-500/30"
                >
                  Continue
                  <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    )
  }

  // Step 2: Payment Details + Upload Proof
  if (step === 'payment') {
    return (
      <div className="space-y-5">
        {/* Payment Method Card */}
        <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-100 px-6 py-4 dark:border-slate-800">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 dark:bg-blue-900/30">
                {selectedMethod && getMethodIcon(selectedMethod.type)}
              </div>
              <div>
                <h3 className="font-bold text-slate-900 dark:text-slate-100">
                  {selectedMethod?.name || 'Payment Method'}
                </h3>
                <p className="text-sm text-slate-500">
                  Amount:{' '}
                  <span className="font-bold text-aerojet-blue">€{getAmount().toLocaleString()}</span>
                </p>
              </div>
            </div>
            <button
              onClick={handleBack}
              className="text-sm font-medium text-slate-500 hover:text-aerojet-blue"
            >
              Change
            </button>
          </div>

          {/* Bank Details */}
          {selectedMethod?.type === 'BANK_TRANSFER' && selectedMethod.details && (
            <div className="bg-slate-50 px-6 py-4 dark:bg-slate-800/50">
              <h4 className="mb-3 flex items-center gap-2 font-bold text-slate-900 dark:text-slate-100">
                <Building className="h-4 w-4" />
                Bank Account Details
              </h4>
              <div className="grid grid-cols-2 gap-3 rounded-xl bg-white p-4 dark:bg-slate-900">
                {Object.entries(selectedMethod.details).map(([key, value]) => (
                  <div
                    key={key}
                    className="col-span-2 flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 dark:bg-slate-800"
                  >
                    <span className="text-xs font-medium text-slate-500 uppercase">
                      {key.replace(/_/g, ' ')}
                    </span>
                    <span className="font-mono font-bold text-slate-900 dark:text-slate-100">
                      {value}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Instructions */}
          {selectedMethod?.instructions && (
            <div className="px-6 pb-4">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                {selectedMethod.instructions}
              </p>
            </div>
          )}
        </div>

        {/* Upload Proof Card */}
        <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">
          <div className="border-b border-slate-100 bg-linear-to-r from-green-50 to-emerald-50 px-6 py-4 dark:border-slate-800 dark:from-green-900/20 dark:to-emerald-900/20">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-green-100 dark:bg-green-900/30">
                <Upload className="h-5 w-5 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <h3 className="font-bold text-slate-900 dark:text-slate-100">
                  Upload Payment Proof
                </h3>
                <p className="text-xs text-slate-500">Required for verification</p>
              </div>
            </div>
          </div>

          <div className="p-6">
            {!proofUrl ? (
              <UploadDropzone
                endpoint="paymentProof"
                onUploadBegin={() => setUploading(true)}
                onClientUploadComplete={handleUploadComplete}
                onUploadError={(error) => {
                  setUploading(false)
                  toast.error(`Upload error: ${error.message}`)
                }}
                appearance={{
                  container:
                    'border-2 border-dashed border-slate-300 rounded-xl p-8 cursor-pointer hover:border-aerojet-sky hover:bg-blue-50/50 transition-all dark:border-slate-600 dark:hover:border-blue-400',
                  label: 'text-slate-700 dark:text-slate-300 font-semibold text-base',
                  allowedContent: 'text-slate-400 text-sm mt-2',
                  button:
                    'bg-aerojet-blue text-white font-bold px-6 py-3 rounded-xl hover:bg-[#003875] transition-all shadow-lg shadow-blue-500/20',
                }}
              />
            ) : uploading ? (
              <div className="flex items-center justify-center gap-4 rounded-xl border-2 border-blue-200 bg-blue-50 p-8 dark:border-blue-900/30 dark:bg-blue-900/20">
                <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
                <div className="text-center">
                  <p className="font-bold text-blue-900 dark:text-blue-300">
                    Processing Payment...
                  </p>
                  <p className="text-sm text-blue-700 dark:text-blue-400">
                    Please wait while we submit your payment
                  </p>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-4 rounded-xl border-2 border-green-200 bg-green-50 p-6 dark:border-green-900/30 dark:bg-green-900/20">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-green-100 dark:bg-green-900/30">
                  <CheckCircle2 className="h-6 w-6 text-green-600 dark:text-green-400" />
                </div>
                <div>
                  <p className="font-bold text-green-900 dark:text-green-300">
                    Payment Submitted Successfully!
                  </p>
                  <p className="text-sm text-green-700 dark:text-green-400">
                    Your payment is being verified by our team.
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Back Button */}
          {!uploading && !proofUrl && (
            <div className="border-t border-slate-100 bg-slate-50 px-6 py-4 dark:border-slate-800 dark:bg-slate-800/50">
              <button
                onClick={handleBack}
                className="flex w-full items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 font-medium text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-400"
              >
                <ArrowRight className="h-4 w-4 rotate-180" />
                Back to Amount
              </button>
            </div>
          )}
        </div>
      </div>
    )
  }

  // Success State
  if (step === 'success') {
    return (
      <div className="space-y-6">
        <div className="overflow-hidden rounded-2xl border-2 border-green-200 bg-linear-to-br from-green-50 to-emerald-50 shadow-lg shadow-green-500/10 dark:border-green-900/30 dark:from-green-900/20 dark:to-emerald-900/20">
          <div className="flex flex-col items-center justify-center p-10 text-center">
            <div className="mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-green-100 shadow-lg dark:bg-green-900/30">
              <CheckCircle2 className="h-10 w-10 text-green-600 dark:text-green-400" />
            </div>
            <h3 className="mb-2 text-2xl font-black text-green-900 dark:text-green-300">
              Payment Submitted!
            </h3>
            <p className="mb-6 max-w-sm text-green-800 dark:text-green-400">
              Your payment of{' '}
              <strong className="text-green-900 dark:text-green-300">
                €{getAmount().toLocaleString()}
              </strong>{' '}
              has been submitted successfully. Our team will verify it and credit your wallet.
            </p>
            <button
              onClick={() => router.push('/applicant/exam-only')}
              className="flex items-center gap-2 rounded-xl bg-green-600 px-8 py-3 font-bold text-white shadow-lg shadow-green-500/25 transition-all hover:bg-green-700 hover:shadow-xl"
            >
              Return to Dashboard
              <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>
    )
  }

  return null
}

import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import {
  Wallet,
  ClipboardList,
  BookOpen,
  CreditCard,
  ArrowRight,
  Clock,
  CheckCircle2,
  AlertCircle,
  Package,
} from 'lucide-react'

import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered, prisma } from '@/lib/prisma/client'

export const metadata: Metadata = { title: 'Dashboard | Exam-Only Portal' }
export const dynamic = 'force-dynamic'

export default async function ExamOnlyDashboardPage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const userId = session.user.id

  const user = await prismaUnfiltered.user.findUnique({
    where: { id: userId },
    select: {
      role: true,
      programmeChoice: true,
      status: true,
      profile: { select: { firstName: true, lastName: true } },
    },
  })

  if (!user) redirect('/login')

  if (user.role === 'STUDENT') {
    redirect('/student')
  }

  const firstName = user.profile?.firstName ?? 'Applicant'

  // Fetch wallet
  const wallet = await prismaUnfiltered.wallet.findUnique({
    where: { userId },
    select: {
      balance: true,
      reservedBalance: true,
      availableBalance: true,
      currency: true,
    },
  })

  const balance = wallet ? Number(wallet.balance) : 0
  const reserved = wallet ? Number(wallet.reservedBalance) : 0
  const available = wallet ? Number(wallet.availableBalance) : 0
  const currency = wallet?.currency ?? 'EUR'

  // Fetch recent exam bookings
  const recentBookings = await prisma.examBooking.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    take: 5,
    include: {
      examComponent: {
        select: { code: true, name: true },
      },
    },
  })

  // Fetch active exam bundles (confirmed bookings with future exam dates)
  const activeBundles = await prisma.examBooking.findMany({
    where: {
      userId,
      status: 'APPROVED',
      examDate: { gte: new Date() },
    },
    orderBy: { examDate: 'asc' },
    include: {
      examComponent: {
        select: { code: true, name: true },
      },
    },
  })

  const formatCurrency = (amount: number) =>
    `${currency} ${amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`

  const statusColors: Record<string, { bg: string; text: string }> = {
