                    <p className="text-sm font-bold text-slate-700 dark:text-slate-200">
                      {booking.examComponent?.code ?? booking.moduleCode ?? 'Exam'}{' '}
                      {booking.examComponent?.name && (
                        <span className="font-normal text-slate-400">
                          — {booking.examComponent.name}
