'use client'

export const metadata = { title: 'Exam Only Pathway | Applicant Portal' }

import dynamic from 'next/dynamic'
import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { Loader2, Package, Users } from 'lucide-react'
import { toast } from 'sonner'
import { useSession } from 'next-auth/react'
import { CurrencyToggle, useCurrencyRates } from '@/components/shared/CurrencyDisplay'
const PackagesTab = dynamic(() => import('./_components/PackagesTab'), {
  ssr: false,
  loading: () => (
    <div className="flex min-h-[200px] items-center justify-center">
      <Loader2 className="h-6 w-6 animate-spin text-slate-400" />
    </div>
  ),
})
const PoolsTab = dynamic(() => import('./_components/PoolsTab'), {
  ssr: false,
  loading: () => (
    <div className="flex min-h-[200px] items-center justify-center">
      <Loader2 className="h-6 w-6 animate-spin text-slate-400" />
    </div>
  ),
})
import {
  ExamComponent,
  ExamPool,
  WalletInfo,
  PoolMembership,
  ExamBooking,
  WalletTransaction,
  WalletPayment,
  ExamBundle,
  TabType,
  ExamOnlyPrices,
  GroupedCourse,
} from './_components/examOnlyTypes'

const IndividualBookingModal = dynamic(
  () => import('./_components/IndividualBookingModal'),
  { ssr: false }
)
const BundleSelectionModal = dynamic(
  () => import('./_components/BundleSelectionModal'),
  { ssr: false }
)
import type { ConfirmationBooking } from './_components/ConfirmationModal'

const ConfirmationModal = dynamic(
  () => import('./_components/ConfirmationModal').then(m => ({ default: m.default })),
  { ssr: false }
)

type TabTypeAlias = TabType

const DEFAULT_PRICES: ExamOnlyPrices = {
  pool: 300,
  individual: 520,
  twoSeat: 980,
  fourSeat: 1900,
}

export default function ExamOnlyPathwayPage() {
  const { update } = useSession()
  const router = useRouter()
  const [activeTab, setActiveTab] = useState<TabTypeAlias>('packages')
  const [showIndividualModal, setShowIndividualModal] = useState(false)
  const [loading, setLoading] = useState(true)
  const [wallet, setWallet] = useState<WalletInfo | null>(null)
  const [examComponents, setExamComponents] = useState<ExamComponent[]>([])
  const [pools, setPools] = useState<ExamPool[]>([])
  const [memberships, setMemberships] = useState<PoolMembership[]>([])
  const [bookings, setBookings] = useState<ExamBooking[]>([])
  const [topUpAmount, setTopUpAmount] = useState<number>(DEFAULT_PRICES.pool)
  const [processingPayment, setProcessingPayment] = useState(false)
  const [joiningPool, setJoiningPool] = useState<string | null>(null)
  const [joiningWaitlist, setJoiningWaitlist] = useState<string | null>(null)
  const [bookingExam, setBookingExam] = useState<string | null>(null)
  const [expandedCourse, setExpandedCourse] = useState<string | null>(null)
  const [selectedModules, setSelectedModules] = useState<Record<string, string>>({})
  const [walletTransactions, setWalletTransactions] = useState<WalletTransaction[]>([])
  const [walletPayments, setWalletPayments] = useState<WalletPayment[]>([])
  const [bundles, setBundles] = useState<ExamBundle[]>([])
  const [purchasingBundle, setPurchasingBundle] = useState<string | null>(null)
  const [selectedBundleType, setSelectedBundleType] = useState<'TWO_SEAT' | 'FOUR_SEAT' | null>(
    null
  )
  const [bundleSelectedModules, setBundleSelectedModules] = useState<string[]>([])
  const [confirmingBooking, setConfirmingBooking] = useState<ConfirmationBooking | null>(null)
  const [prices, setPrices] = useState<ExamOnlyPrices>(DEFAULT_PRICES)
  const [displayCurrency, setDisplayCurrency] = useState('EUR')
  const { convert, loading: ratesLoading } = useCurrencyRates()

  const fmt = (eurAmount: number) => {
    if (displayCurrency === 'EUR') return `â‚¬${eurAmount.toFixed(2)}`
    const converted = convert(eurAmount, 'EUR', displayCurrency)
    const sym = displayCurrency === 'GHS' ? 'GHâ‚µ' : '$'
    return `${sym}${converted.toFixed(2)}`
  }

  const fetchData = useCallback(async () => {
    try {
      const [walletRes, componentsRes, poolsRes, membershipsRes, bookingsRes, txRes, bundlesRes, pricingRes] =
        await Promise.all([
          fetch('/api/applicant/exam-only/wallet')
            .then((r) => r.json())
            .catch(() => null),
          fetch('/api/applicant/exam-only/exam-components')
            .then((r) => r.json())
            .catch(() => []),
          fetch('/api/applicant/exam-only/pools')
            .then((r) => r.json())
            .catch(() => []),
          fetch('/api/applicant/exam-only/memberships')
            .then((r) => r.json())
            .catch(() => []),
          fetch('/api/applicant/exam-only/bookings')
            .then((r) => r.json())
            .catch(() => []),
          fetch('/api/applicant/exam-only/wallet/transactions')
            .then((r) => r.json())
            .catch(() => ({ transactions: [], payments: [] })),
          fetch('/api/applicant/exam-only/bundles')
            .then((r) => r.json())
            .then((res) => res?.bundles || [])
            .catch(() => []),
          fetch('/api/applicant/exam-only/pricing')
            .then((r) => r.json())
            .catch(() => null),
        ])

      setWallet(walletRes)
      setExamComponents(componentsRes)
      setPools(poolsRes)
      setMemberships(membershipsRes)
      setBookings(bookingsRes)
      setWalletTransactions(txRes.transactions || [])
      setWalletPayments(txRes.payments || [])
      setBundles(bundlesRes)

      if (pricingRes) {
        setPrices({
          pool: pricingRes?.pool?.standardPrice ?? DEFAULT_PRICES.pool,
          individual: pricingRes?.individual?.price ?? DEFAULT_PRICES.individual,
          twoSeat: pricingRes?.bundles?.twoSeat?.price ?? DEFAULT_PRICES.twoSeat,
          fourSeat: pricingRes?.bundles?.fourSeat?.price ?? DEFAULT_PRICES.fourSeat,
        })
      }
    } catch (error) {
      toast.error('Failed to load exam data. Please refresh the page.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchData()
  }, [fetchData])

  const handleTopUp = async () => {
    if (!wallet || wallet.availableBalance === 0) {
      const lowestPrice = getLowestExamPrice()
      if (topUpAmount < lowestPrice) {
        toast.error(`Minimum top-up must be at least â‚¬${lowestPrice} (lowest exam fee)`)
        return
      }
    }

    setProcessingPayment(true)
    try {
      const res = await fetch('/api/applicant/exam-only/top-up', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ amount: topUpAmount }),
      })

      const data = await res.json()

      if (!res.ok) {
        toast.error(data.error || 'Failed to process top-up')
        return
      }

      toast.success('Wallet top-up initiated. Upload your payment proof to complete.')
      router.push('/applicant/upload-proof?code=' + data.registrationCode)
    } catch (error) {
      toast.error('Network error during top-up')
    } finally {
      setProcessingPayment(false)
    }
  }

  const handleJoinPool = async (poolId: string, moduleCode: string) => {
    if (!wallet) return

    const pool = pools.find((p) => p.id === poolId)
    if (!pool) return

    const requiredAmount = Number(pool.seatPrice)
    if (wallet.availableBalance < requiredAmount) {
      toast.error(
        `Insufficient funds. You need â‚¬${requiredAmount} but have â‚¬${wallet.availableBalance.toFixed(2)} available.`,
        {
          action: {
            label: 'Top Up',
            onClick: () => router.push(`/applicant/exam-only/top-up?required=${requiredAmount}`),
          },
        }
      )
      return
    }

    setJoiningPool(poolId)
    try {
      const res = await fetch('/api/applicant/exam-only/join-pool', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poolId, moduleCode }),
      })

      const data = await res.json()

      if (!res.ok) {
        if (data.error === 'INSUFFICIENT_BALANCE') {
          toast.error(
            `Insufficient funds. You need â‚¬${requiredAmount} but have â‚¬${wallet.availableBalance.toFixed(2)} available.`,
            {
              action: {
                label: 'Top Up',
                onClick: () =>
                  router.push(`/applicant/exam-only/top-up?required=${requiredAmount}`),
              },
            }
          )
          return
        }
        toast.error(data.error || 'Failed to join booking')
        return
      }

      if (data.promotedToStudent) {
        toast.success('Enrolled successfully! Updating your account...')
        await update() // Refresh NextAuth session

        setTimeout(() => {
          toast.success('Redirecting to Student Portal...')
          window.location.href = '/student'
        }, 1500)
        return
      }

      toast.success('Successfully joined booking! Funds have been reserved.')
      fetchData()
    } catch (error) {
      toast.error('Network error while joining booking')
    } finally {
      setJoiningPool(null)
    }
  }

  const handleJoinWaitlist = async (poolId: string, moduleCode: string) => {
    setJoiningWaitlist(poolId)
    try {
      const res = await fetch('/api/applicant/exam-only/join-waitlist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poolId, moduleCode }),
      })

      const data = await res.json()

      if (!res.ok) {
        toast.error(data.error || 'Failed to join waitlist')
        return
      }

      toast.success('Added to waitlist! You will be auto-promoted if a seat opens.')
      fetchData()
    } catch (error) {
      toast.error('Network error while joining waitlist')
    } finally {
      setJoiningWaitlist(null)
    }
  }

  const handleBookExamClick = (componentId: string, bookingType: 'POOL' | 'INDIVIDUAL') => {
    const component = examComponents.find((c) => c.id === componentId)
    if (!component) return

    const requiredAmount = bookingType === 'POOL' ? prices.pool : prices.individual

    if (!wallet || Number(wallet.availableBalance) < requiredAmount) {
      toast.error(
        `Insufficient funds. You need â‚¬${requiredAmount} but have â‚¬${Number(wallet?.availableBalance || 0).toFixed(2)} available.`,
        {
          action: {
            label: 'Top Up',
            onClick: () => router.push(`/applicant/exam-only/top-up?required=${requiredAmount}`),
          },
        }
      )
      return
    }

    setConfirmingBooking({
      componentId,
      type: bookingType,
      price: requiredAmount,
      moduleName: `${component.course.code} - ${component.name}`,
    })
  }

  const submitBooking = async () => {
    if (!confirmingBooking || !wallet) return
    const { componentId, type, price } = confirmingBooking

    setBookingExam(componentId)
    setConfirmingBooking(null)
    try {
      const res = await fetch('/api/applicant/exam-only/book-exam', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ examComponentId: componentId, bookingType: type }),
      })

      const data = await res.json()

      if (!res.ok) {
        if (data.error === 'INSUFFICIENT_BALANCE') {
          toast.error(
            `Insufficient funds. You need â‚¬${data.required || price} but have â‚¬${Number(data.available || 0).toFixed(2)} available.`,
            {
              action: {
                label: 'Top Up',
                onClick: () =>
                  router.push(`/applicant/exam-only/top-up?required=${data.required || price}`),
              },
            }
          )
          return
        }
        toast.error(data.error || 'Failed to book exam')
        return
      }

      if (data.promotedToStudent) {
        toast.success('Enrolled successfully! Updating your account...')
        await update() // Refresh NextAuth session

        setTimeout(() => {
          toast.success('Redirecting to Student Portal...')
          window.location.href = '/student'
        }, 1500)
        return
      }

      if (type === 'POOL' && data.pool) {
        toast.success(`Joined ${data.pool.name}! (â‚¬${prices.pool}) - ${data.pool.memberCount}/${data.pool.maxCandidates || 28} candidates`)
      } else {
        toast.success(`Individual exam booked successfully! (â‚¬${prices.individual})`)
      }
      fetchData()
    } catch (error) {
      toast.error('Network error while booking exam')
    } finally {
      setBookingExam(null)
    }
  }

  const handleBuyBundle = async (bundleType: 'TWO_SEAT' | 'FOUR_SEAT', componentIds: string[]) => {
    if (!wallet) return

    const requiredAmount = bundleType === 'TWO_SEAT' ? prices.twoSeat : prices.fourSeat
    const requiredSeats = bundleType === 'TWO_SEAT' ? 2 : 4

    if (componentIds.length !== requiredSeats) {
      toast.error(`Please select exactly ${requiredSeats} modules for this package.`)
      return
    }

    if (wallet.availableBalance < requiredAmount) {
      toast.error(
        `Insufficient funds. You need â‚¬${requiredAmount} but have â‚¬${wallet.availableBalance.toFixed(2)} available.`,
        {
          action: {
            label: 'Top Up',
            onClick: () => router.push(`/applicant/exam-only/top-up?required=${requiredAmount}`),
          },
        }
      )
      return
    }

    setPurchasingBundle(bundleType)
    setSelectedBundleType(null)
    setBundleSelectedModules([])

    try {
      const res = await fetch('/api/applicant/exam-only/bundles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ bundleType, examComponentIds: componentIds }),
      })

      const data = await res.json()

      if (!res.ok) {
        toast.error(data.error || 'Failed to purchase Exam Package')
        return
      }

      if (data.promotedToStudent) {
        toast.success(`Exam Package purchased successfully! Updating your account...`)
        await update() // Refresh NextAuth session

        setTimeout(() => {
          toast.success('Redirecting to Student Portal...')
          window.location.href = '/student'
        }, 1500)
        return
      }

      toast.success(`${bundleType === 'TWO_SEAT' ? 'Twin Pack' : '4-Pack'} purchased successfully!`)
      fetchData()
    } catch (error) {
      toast.error('Network error while purchasing package')
    } finally {
      setPurchasingBundle(null)
    }
  }

  const getLowestExamPrice = (): number => {
    return Math.min(prices.pool, prices.individual)
  }

  const groupedComponents = examComponents.reduce(
    (acc, component) => {
      const courseCode = component.course.code
      if (!acc[courseCode]) {
        acc[courseCode] = {
          code: courseCode,
          name: component.course.name,
          components: [],
        }
      }
      acc[courseCode].components.push(component)
      return acc
    },
    {} as Record<string, GroupedCourse>
  )

  if (loading) {
    return (
      <div className="flex min-h-[400px] items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
      </div>
    )
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-black tracking-tight text-aerojet-blue dark:text-white">
          Exam Only Pathway
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Book individual exams or join exam bookings using your wallet
        </p>
      </div>

      {/* Tab Navigation */}
      <div className="flex gap-2 border-b border-slate-200 dark:border-slate-700">
        {[
          { id: 'packages', label: 'Exam Packages', icon: Package },
          { id: 'pools', label: 'Exam Bookings', icon: Users },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as TabTypeAlias)}
            className={`flex items-center gap-2 border-b-2 px-4 py-3 text-sm font-medium transition-colors ${
              activeTab === tab.id
                ? 'border-aerojet-sky text-aerojet-sky'
                : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-300'
            }`}
          >
            <tab.icon className="h-4 w-4" />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Packages Tab */}
      {activeTab === 'packages' && (
        <PackagesTab
          bundles={bundles}
          purchasingBundle={purchasingBundle}
          onSelectIndividual={() => setShowIndividualModal(true)}
          onSelectPool={() => setActiveTab('pools')}
          onSelectBundle={(type) => setSelectedBundleType(type)}
          fmt={fmt}
          prices={prices}
        />
      )}

      {/* Pools Tab */}
      {activeTab === 'pools' && (
        <PoolsTab
          pools={pools}
          selectedModules={selectedModules}
          onSelectedModulesChange={setSelectedModules}
          wallet={wallet}
          joiningPool={joiningPool}
          joiningWaitlist={joiningWaitlist}
          onJoinPool={handleJoinPool}
          onJoinWaitlist={handleJoinWaitlist}
          fmt={fmt}
          poolPrice={prices.pool}
        />
      )}

      {/* Individual Module Selection Modal */}
      <IndividualBookingModal
        open={showIndividualModal}
        onClose={() => setShowIndividualModal(false)}
        groupedComponents={groupedComponents}
        expandedCourse={expandedCourse}
        setExpandedCourse={setExpandedCourse}
        wallet={wallet}
        bookingExam={bookingExam}
        onBook={(id) => handleBookExamClick(id, 'INDIVIDUAL')}
        fmt={fmt}
        individualPrice={prices.individual}
      />

      {/* Module Selection Modal for Bundles (grouped by course) */}
      <BundleSelectionModal
        bundleType={selectedBundleType}
        onCancel={() => {
          setSelectedBundleType(null)
          setBundleSelectedModules([])
          setExpandedCourse(null)
        }}
        selectedModules={bundleSelectedModules}
        setSelectedModules={setBundleSelectedModules}
        expandedCourse={expandedCourse}
        setExpandedCourse={setExpandedCourse}
        groupedComponents={groupedComponents}
        onConfirm={handleBuyBundle}
        fmt={fmt}
        twoSeatPrice={prices.twoSeat}
        fourSeatPrice={prices.fourSeat}
        purchasingBundle={purchasingBundle}
      />

      {/* Confirmation Modal for Individual / Pool Bookings */}
      <ConfirmationModal
        booking={confirmingBooking}
        onCancel={() => setConfirmingBooking(null)}
        onConfirm={submitBooking}
      />
    </div>
  )
}

import { getAuthSession } from '@/lib/auth/helpers'
import { redirect } from 'next/navigation'
import ApplicantSidebar from './_components/ApplicantSidebar'
import BreadcrumbNav from '@/components/layouts/BreadcrumbNav'
import PortalHeader from '@/components/layouts/PortalHeader'
import TourTrigger from '@/components/Tour/TourTrigger'
import AppTour from '@/components/Tour/AppTour'
import { prismaUnfiltered } from '@/lib/prisma/client'
import type { User } from '@prisma/client'
import ForcePasswordChange from './_components/ForcePasswordChange'
import {
  resolveEffectiveEnrollmentType,
  resolveEffectivePathwayCode,
} from '@/lib/enrollment/pathway'
import { getPipelineStageConfig, isPipelineEnabled } from '@/lib/admissions/state-machine'

export const dynamic = 'force-dynamic'

export default async function ApplicantLayout({ children }: { children: React.ReactNode }) {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const user = session.user
  if (!['APPLICANT'].includes(user.role)) redirect('/login')

  // Single consolidated query instead of 4 sequential queries
  const dbUser = await prismaUnfiltered.user.findUnique({
    where: { id: user.id },
    select: {
      status: true,
      role: true,
      mustChangePassword: true,
      hasCompletedTour: true,
      programmeChoice: true,
      profile: { select: { firstName: true, lastName: true } },
      studentProfile: {
        select: { pathwayId: true, enrollmentType: true, pathwayRel: { select: { code: true } } },
      },
      fullTimeEnrollments: { take: 1, select: { id: true } },
      application: { select: { stage: true, programmeChoice: true } },
    },
  })

  if (
    !dbUser ||
    ['SUSPENDED', 'DELETED', 'ARCHIVED'].includes(dbUser.status) ||
    dbUser.role !== 'APPLICANT'
  ) {
    redirect('/login')
  }

  // Force password change if required
  if (dbUser.mustChangePassword) {
    return <ForcePasswordChange />
  }

  const profile = dbUser.profile
  const studentProfile = dbUser.studentProfile
  const hasFullTimeEnrollment =
    (dbUser.fullTimeEnrollments?.length ?? 0) > 0 ? { id: dbUser.fullTimeEnrollments[0].id } : null

  const effectivePathwayCode = resolveEffectivePathwayCode({
    pathwayCode: studentProfile?.pathwayRel?.code,
    enrollmentType: studentProfile?.enrollmentType,
    programmeChoice: dbUser.programmeChoice,
  })
  const effectiveEnrollmentType = resolveEffectiveEnrollmentType({
    pathwayCode: studentProfile?.pathwayRel?.code,
    enrollmentType: studentProfile?.enrollmentType,
    programmeChoice: dbUser.programmeChoice,
  })

  const hasPathway =
    !!effectivePathwayCode || !!studentProfile?.pathwayId || !!hasFullTimeEnrollment
  const isExamOnly = effectiveEnrollmentType === 'EXAM_ONLY'
  const pipelineEnabled = await isPipelineEnabled()
  const applicationStage = dbUser.application?.stage ?? null
  const enabledStageGroups = dbUser.application
    ? await getPipelineStageConfig(dbUser.application.programmeChoice)
    : undefined

  const userName = profile ? `${profile.firstName} ${profile.lastName}` : (user.email ?? '')
  const userRole = 'Applicant'

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900">
      <a
        href="#main-content"
        className="sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 focus:z-50 focus:rounded-lg focus:bg-white focus:px-4 focus:py-2 focus:text-sm focus:font-bold focus:text-slate-900 focus:shadow-lg dark:focus:bg-slate-800 dark:focus:text-white"
      >
        Skip to main content
      </a>
      <ApplicantSidebar
        userName={userName}
        userRole={userRole}
        userImage={user.image ?? undefined}
        hasPathway={hasPathway}
        isExamOnly={isExamOnly}
        pipelineEnabled={pipelineEnabled}
        applicationStage={applicationStage}
        enabledStageGroups={enabledStageGroups}
      />
      <AppTour hasCompletedTour={dbUser.hasCompletedTour} userRole={userRole} />
      <main
        id="main-content"
        className="relative min-h-screen min-w-0 flex-1 overflow-x-hidden pt-16 lg:pt-0"
      >
        <div className="mx-auto max-w-[1920px] p-4 pt-16 sm:p-8 lg:px-8 lg:py-6 lg:pt-10">
          <PortalHeader
            actions={
              <TourTrigger aria-label="Take a guided tour" title="Take a tour of this portal" />
            }
          >
            <BreadcrumbNav />
          </PortalHeader>
          {children}
        </div>
      </main>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  CheckCircle2,
  Circle,
  Clock,
  AlertTriangle,
  Loader2,
  Wallet,
} from 'lucide-react'

interface Milestone {
  id: string
  milestoneType: string
  yearNumber: number
  percentOfYearFee: number
  amountDue: number
  status: string
  dueDate: string
  paidAt: string | null
}

interface Props {
  milestones: Milestone[]
  walletBalance: number
  currency: string
}

const MILESTONE_LABELS: Record<string, string> = {
  SEAT_CONFIRMATION: 'Seat Confirmation',
  SEM1_DUE: 'Before Semester 1',
  SEM2_DUE: 'Before Semester 2',
  FULL_YEAR: 'Full Year',
  FULL_COURSE: 'Full Programme',
}

function statusIcon(status: string) {
  switch (status) {
    case 'PAID':
      return <CheckCircle2 className="h-5 w-5 text-emerald-500" />
    case 'OVERDUE':
      return <AlertTriangle className="h-5 w-5 text-red-500" />
    case 'DUE':
      return <Clock className="h-5 w-5 text-amber-500" />
    default:
      return <Circle className="h-5 w-5 text-slate-300" />
  }
}

function statusBadge(status: string) {
  const styles: Record<string, string> = {
    PAID: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400',
    DUE: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400',
    OVERDUE: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
    WAIVED: 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400',
  }
  return (
    <span
      className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${styles[status] ?? styles.DUE}`}
    >
      {status}
    </span>
  )
}

export default function MilestoneTracker({ milestones, walletBalance, currency }: Props) {
  const [paying, setPaying] = useState<string | null>(null)
  const router = useRouter()

  const totalDue = milestones.reduce((acc, m) => acc + m.amountDue, 0)
  const totalPaid = milestones
    .filter((m) => m.status === 'PAID')
    .reduce((acc, m) => acc + m.amountDue, 0)
  const progressPercent = totalDue > 0 ? Math.round((totalPaid / totalDue) * 100) : 0

  const handlePayFromWallet = async (milestoneId: string) => {
    setPaying(milestoneId)
    try {
      const res = await fetch('/api/applicant/pay-milestone', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ milestoneId }),
      })
      const data = await res.json()
      if (!res.ok) {
        toast.error(data.error || 'Failed to pay milestone')
        return
      }
      toast.success('Milestone paid successfully!')
      router.refresh()
    } catch {
      toast.error('Network error while paying milestone')
    } finally {
      setPaying(null)
    }
  }

  return (
    <div className="space-y-4 rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
      <div className="flex items-center justify-between">
        <h2 className="font-bold text-slate-900 dark:text-slate-100">Payment Milestones</h2>
        {statusBadge(`${progressPercent}% Complete`)}
      </div>

      {/* Progress Bar */}
      <div className="space-y-1">
        <div className="h-2.5 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
          <div
            className="h-full rounded-full bg-emerald-500 transition-all duration-500"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
        <div className="flex justify-between text-xs text-slate-400">
          <span>
            {currency} {totalPaid.toLocaleString()} paid
          </span>
          <span>
            {currency} {totalDue.toLocaleString()} total
          </span>
        </div>
      </div>

      {/* Milestone List */}
      <div className="space-y-3">
        {milestones.map((m, idx) => {
          const canPay = m.status === 'DUE' || m.status === 'OVERDUE'
          const hasEnoughBalance = walletBalance >= m.amountDue
          const isPaying = paying === m.id

          return (
            <div
              key={m.id}
              className={`rounded-xl border p-4 transition-colors ${
                m.status === 'PAID'
                  ? 'border-emerald-100 bg-emerald-50/50 dark:border-emerald-900/20 dark:bg-emerald-900/5'
                  : m.status === 'OVERDUE'
                    ? 'border-red-100 bg-red-50/50 dark:border-red-900/20 dark:bg-red-900/5'
                    : 'border-slate-100 bg-white dark:border-slate-800 dark:bg-slate-900'
              }`}
            >
              <div className="flex items-start gap-3">
                <div className="mt-0.5 shrink-0">{statusIcon(m.status)}</div>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-slate-900 dark:text-slate-100">
                      {MILESTONE_LABELS[m.milestoneType] || m.milestoneType}
                    </span>
                    {statusBadge(m.status)}
                    <span className="text-xs text-slate-400">
                      Year {m.yearNumber} — {m.percentOfYearFee}%
                    </span>
                  </div>

                  <div className="mt-1 flex items-center justify-between">
                    <div className="text-sm text-slate-500 dark:text-slate-400">
                      {m.status === 'PAID' && m.paidAt ? (
                        <span>
                          Paid on{' '}
                          {new Date(m.paidAt).toLocaleDateString('en-GB', {
                            day: 'numeric',
                            month: 'short',
                            year: 'numeric',
                          })}
                        </span>
                      ) : (
                        <span>
                          Due:{' '}
                          {new Date(m.dueDate).toLocaleDateString('en-GB', {
                            day: 'numeric',
                            month: 'short',
                            year: 'numeric',
                          })}
                        </span>
                      )}
                    </div>
                    <span className="text-lg font-black text-slate-900 dark:text-slate-100">
                      {currency} {m.amountDue.toLocaleString()}
                    </span>
                  </div>

                  {/* Pay from Wallet button */}
                  {canPay && (
                    <div className="mt-3 border-t border-slate-100 pt-3 dark:border-slate-800">
                      {hasEnoughBalance ? (
                        <button
                          onClick={() => handlePayFromWallet(m.id)}
                          disabled={isPaying}
                          className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2 text-xs font-bold text-white transition-colors hover:bg-[#003875] disabled:opacity-50"
                        >
                          {isPaying ? (
                            <>
                              <Loader2 className="h-3.5 w-3.5 animate-spin" />
                              Processing...
                            </>
                          ) : (
                            <>
                              <Wallet className="h-3.5 w-3.5" />
                              Pay from Wallet
                            </>
                          )}
                        </button>
                      ) : (
                        <p className="text-xs text-slate-400">
                          Insufficient wallet balance ({currency}{' '}
                          {walletBalance.toLocaleString()} available). Top up your wallet first.
                        </p>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { GraduationCap, FileSignature, Layers, AlertCircle, ArrowRight, X } from 'lucide-react'
import { getCurrencySymbol } from '@/lib/currency'

type PathwayType = 'FULL_TIME' | 'EXAM_ONLY' | 'MODULAR'

export default function PathwaySelector({ currency = 'EUR' }: { currency?: string }) {
  const router = useRouter()
  const [selected, setSelected] = useState<PathwayType | null>(null)
  const [isConfirming, setIsConfirming] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const symbol = getCurrencySymbol(currency)

  const pathways = [
    {
      id: 'FULL_TIME' as PathwayType,
      title: 'Full-Time Programme',
      icon: GraduationCap,
      description: 'Structured 1 to 4-year programmes with milestones.',
      features: [
        'Organized chronological curriculum',
        'Milestone-based payment schedules (Y1: 40/30/30)',
        'Classroom attendance tracking',
      ],
      color:
        'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/10 dark:text-blue-400 dark:border-blue-800',
      activeColor: 'border-blue-600 ring-2 ring-blue-600 dark:border-blue-500',
    },
    {
      id: 'EXAM_ONLY' as PathwayType,
      title: 'Exam-Only',
      icon: FileSignature,
      description: 'Book individual EASA module exams with 100% upfront payment.',
      features: [
        'Flexible schedule',
        `Group Pooling discounts (${symbol}300 per seat)`,
        `Individual bookings (${symbol}520 per seat)`,
      ],
      color:
        'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/10 dark:text-purple-400 dark:border-purple-800',
      activeColor: 'border-purple-600 ring-2 ring-purple-600 dark:border-purple-500',
    },
    {
      id: 'MODULAR' as PathwayType,
      title: 'Modular Packages',
      icon: Layers,
      description: 'Purchase bundles of modules for self-paced learning.',
      features: [
        '100% upfront package payment',
        'Learn exactly what you need',
        'Optional tuition sessions',
      ],
      color:
        'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/10 dark:text-orange-400 dark:border-orange-800',
      activeColor: 'border-orange-600 ring-2 ring-orange-600 dark:border-orange-600',
    },
  ]

  const handleSelect = (id: PathwayType) => {
    setSelected(id)
  }

  const handleConfirm = async () => {
    if (!selected) return
    setIsSubmitting(true)
    setError(null)
    try {
      const res = await fetch('/api/me/study-pathway', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ studyPathway: selected }),
      })
      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to lock pathway')
      }
      router.refresh()
      router.push('/applicant/dashboard')
    } catch (err: any) {
      setError(err.message)
      setIsSubmitting(false)
      setIsConfirming(false)
    }
  }

  return (
    <div className="mx-auto max-w-5xl space-y-8">
      <div className="text-center">
        <h1 className="text-3xl font-black tracking-tight text-slate-900 sm:text-4xl dark:text-slate-100">
          Choose Your Study Pathway
        </h1>
        <p className="mt-4 text-base text-slate-500 dark:text-slate-400">
          This is a permanent selection that shapes your entire journey at Aerojet Academy.
          <br /> Select the pathway that aligns with your educational goals.
        </p>
      </div>

      <div className="grid gap-6 md:grid-cols-3">
        {pathways.map((path) => {
          const Icon = path.icon
          const isSelected = selected === path.id
          return (
            <div
              key={path.id}
              onClick={() => handleSelect(path.id)}
              className={`relative cursor-pointer rounded-2xl border bg-white p-6 shadow-sm transition-all hover:shadow-md dark:bg-slate-900 ${
                isSelected ? path.activeColor : 'border-slate-200 dark:border-slate-800'
              }`}
            >
              <div
                className={`flex h-12 w-12 items-center justify-center rounded-xl border ${path.color} mb-4`}
              >
                <Icon className="h-6 w-6" />
              </div>
              <h3 className="text-lg font-bold text-slate-900 dark:text-slate-100">{path.title}</h3>
              <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">{path.description}</p>
              <ul className="mt-4 space-y-2">
                {path.features.map((feature, idx) => (
                  <li key={idx} className="flex text-xs text-slate-600 dark:text-slate-300">
                    <span className="mr-2 text-aerojet-sky">•</span>
                    {feature}
                  </li>
                ))}
              </ul>
              {isSelected && (
