function formatTime(iso: string) {
  const d = new Date(iso)
  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

interface MonitorAnswer {
  question: { id: string; text: string; correctAnswer: string; points: number }
