                    onSort={requestSort}
                    className="py-2 pr-4"
                  />
                  <SortHeader
                    label="Status"
                    sortKey="status"
                    currentSort={sortConfig}
                    onSort={requestSort}
                    align="center"
                    className="py-2 pr-4"
                  />
                  <SortHeader
                    label="Progress"
                    sortKey="percentage"
                    currentSort={sortConfig}
                    onSort={requestSort}
                    align="right"
                    className="py-2 pr-4"
                  />
                  <SortHeader
                    label="Time Left"
                    sortKey="timeRemaining"
                    currentSort={sortConfig}
                    onSort={requestSort}
                    align="right"
                    className="py-2 pr-4"
                  />
                  <SortHeader
                    label="Score"
                    sortKey="score"
                    currentSort={sortConfig}
