'use client'

import { useState, useCallback, useEffect } from 'react'
import {
  Play,
  XCircle,
  Clock,
  CheckCircle2,
  AlertCircle,
  Users,
  RefreshCw,
  ChevronDown,
  ChevronUp,
  ShieldAlert,
  Send,
  Hourglass,
  Award,
} from 'lucide-react'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'
import { TableSkeleton } from '@/components/shared/DashboardSkeleton'
import { useExamMonitor } from '@/hooks/useExamMonitor'
import { cn, formatDateTime } from '@/lib/utils'
import { ACADEMIC_RULES } from '@/lib/constants/business-rules'
import { toast } from 'sonner'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

interface MonitorClassInfo {
  id: string
  name: string
  courseName: string
  courseCode: string
  enrolledCount: number
  startDate: string
  endDate: string
}

interface MonitorSession {
  id: string
  status: string
  student: { id: string; name: string; email: string }
  bank: { id: string; name: string }
  startedAt: string | null
  expiresAt: string | null
  submittedAt: string | null
  score: number | null
  totalPoints: number | null
  percentage: number | null
  passed: boolean | null
  correctCount: number
  timeRemaining: number | null
  answerCount: number
  answers?: { question: { id: string; text: string; correctAnswer: string; points: number }; selectedAnswer: string | null }[]
}

type StatusFilter = 'all' | 'IN_PROGRESS' | 'COMPLETED' | 'TIMED_OUT' | 'VOIDED' | 'NOT_STARTED'

function formatDuration(seconds: number) {
  const m = Math.floor(seconds / 60)
  const s = seconds % 60
  return `${m}:${s.toString().padStart(2, '0')}`
}

function SessionStatusBadge({ status }: { status: string }) {
  const map: Record<string, { label: string; cls: string; icon: React.ReactNode }> = {
    IN_PROGRESS: { label: 'Active', cls: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300', icon: <Clock className="h-3 w-3" /> },
    COMPLETED: { label: 'Finished', cls: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300', icon: <CheckCircle2 className="h-3 w-3" /> },
    TIMED_OUT: { label: 'Timeout', cls: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300', icon: <XCircle className="h-3 w-3" /> },
    VOIDED: { label: 'Voided', cls: 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-300', icon: <AlertCircle className="h-3 w-3" /> },
    NOT_STARTED: { label: 'Not started', cls: 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300', icon: <Clock className="h-3 w-3" /> },
  }
  const s = map[status] || map.NOT_STARTED
  return (
    <span className={cn('inline-flex items-center gap-1 rounded-full border-transparent px-2.5 py-0.5 text-xs font-bold', s.cls)}>
      {s.icon}
      {s.label}
    </span>
  )
}

function ScoreBar({ value }: { value: number | null }) {
  const pct = value ?? 0
  const color =
    pct >= ACADEMIC_RULES.GRADE_THRESHOLD_PASS
      ? 'bg-emerald-500'
      : pct >= ACADEMIC_RULES.GRADE_THRESHOLD_WARNING
        ? 'bg-amber-500'
        : 'bg-red-500'
  return (
    <div className="h-2 w-full overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
      <div className={cn('h-full rounded-full transition-all', color)} style={{ width: `${Math.min(100, Math.max(0, pct))}%` }} />
    </div>
  )
}

export default function ClassMonitorPage({
  classId,
  initialClass,
  initialSessions,
}: {
  classId: string
  initialClass: MonitorClassInfo | null
  initialSessions: MonitorSession[]
}) {
  const [sessions, setSessions] = useState<MonitorSession[]>(initialSessions)
  const [loading, setLoading] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all')
  const [expandedSession, setExpandedSession] = useState<string | null>(null)
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const [startConfirmOpen, setStartConfirmOpen] = useState(false)
  const [extendModalOpen, setExtendModalOpen] = useState<string | null>(null)
  const [extendMinutes, setExtendMinutes] = useState(5)

  const filteredSessions = statusFilter === 'all'
    ? sessions
    : sessions.filter((s) => s.status === statusFilter)
  const { items, requestSort, sortConfig } = useSort(filteredSessions, { key: 'student.name', order: 'asc' })

  const refresh = useCallback(async () => {
    setRefreshing(true)
    try {
      const res = await fetch(`/api/instructor/exams/classes/${classId}/monitor`)
      const json = await res.json()
      if (json.success) setSessions(json.data)
    } catch {
      toast.error('Failed to refresh monitor')
    } finally {
      setRefreshing(false)
    }
  }, [classId])

  useExamMonitor(classId, refresh)

  const activeCount = sessions.filter((s) => s.status === 'IN_PROGRESS').length
  const completedCount = sessions.filter((s) => s.status === 'COMPLETED').length
  const timeoutCount = sessions.filter((s) => s.status === 'TIMED_OUT').length
  const avgScore = sessions.length > 0
    ? Math.round(sessions.reduce((sum, s) => sum + (s.percentage ?? 0), 0) / sessions.length)
    : 0

  const handleStartExam = async () => {
    setStartConfirmOpen(false)
    setActionLoading('start')
    try {
      const res = await fetch(`/api/instructor/exams/classes/${classId}/start`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })
      const json = await res.json()
      if (json.success) {
        toast.success(`Exam started: ${json.data.started} students, ${json.data.skipped} skipped`)
        refresh()
      } else {
        toast.error(json.error || 'Failed to start exam')
      }
    } catch {
      toast.error('Failed to start exam')
    } finally {
      setActionLoading(null)
    }
  }

  const handleVoid = async (sessionId: string) => {
    setActionLoading(`void-${sessionId}`)
    try {
      const res = await fetch(`/api/instructor/exams/classes/${classId}/void`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId }),
      })
      const json = await res.json()
      if (json.success) {
        toast.success('Session voided')
        refresh()
      } else {
        toast.error(json.error || 'Failed to void session')
      }
    } catch {
      toast.error('Failed to void session')
    } finally {
      setActionLoading(null)
    }
  }

  const handleExtend = async (sessionId: string) => {
    setActionLoading(`extend-${sessionId}`)
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/extend`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ minutes: extendMinutes }),
      })
      const json = await res.json()
      if (json.success) {
        toast.success(`Extended by ${extendMinutes} minutes`)
        setExtendModalOpen(null)
        refresh()
      } else {
        toast.error(json.error || 'Failed to extend time')
      }
    } catch {
      toast.error('Failed to extend time')
    } finally {
      setActionLoading(null)
    }
  }

  const handleForceSubmit = async (sessionId: string) => {
    setActionLoading(`force-${sessionId}`)
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/force-submit`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })
      const json = await res.json()
      if (json.success) {
        toast.success('Session force-submitted')
        refresh()
      } else {
        toast.error(json.error || 'Failed to force submit')
      }
    } catch {
      toast.error('Failed to force submit')
    } finally {
      setActionLoading(null)
    }
  }

  const handleRemind = async (sessionId: string) => {
    setActionLoading(`remind-${sessionId}`)
    try {
      const res = await fetch(`/api/instructor/exams/classes/${classId}/remind`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId }),
      })
      const json = await res.json()
      if (json.success) {
        toast.success('Reminder sent')
      } else {
        toast.error(json.error || 'Failed to send reminder')
      }
    } catch {
      toast.error('Failed to send reminder')
    } finally {
      setActionLoading(null)
    }
  }

  if (!initialClass) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
        <AlertCircle className="h-10 w-10 text-amber-500" />
        <h2 className="text-lg font-bold text-slate-800 dark:text-slate-100">Internal Exams Disabled</h2>
        <p className="max-w-md text-sm text-slate-500">
          The internal exam system is not currently enabled. Contact an administrator.
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h1 className="text-2xl font-black text-slate-900 dark:text-white">Live Monitor</h1>
          <p className="mt-1 text-sm text-slate-500">
            {initialClass.name} — {initialClass.courseCode} · {initialClass.enrolledCount} enrolled
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={refresh}
            disabled={refreshing}
            className="flex items-center gap-2 rounded-xl border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300 disabled:opacity-50"
          >
            <RefreshCw className={cn('h-4 w-4', refreshing && 'animate-spin')} />
            Refresh
          </button>
          <button
            onClick={() => setStartConfirmOpen(true)}
            disabled={actionLoading === 'start'}
            className="flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-2 text-sm font-bold text-white hover:bg-emerald-700 disabled:opacity-50"
          >
            <Play className="h-4 w-4" />
            {actionLoading === 'start' ? 'Starting...' : 'Start Exam for Class'}
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <div className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-50 dark:bg-blue-900/20">
              <Users className="h-4 w-4 text-blue-600" />
            </div>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Active</p>
              <p className="text-2xl font-black text-slate-900 dark:text-white">{activeCount}</p>
            </div>
          </div>
        </div>
        <div className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-50 dark:bg-emerald-900/20">
              <CheckCircle2 className="h-4 w-4 text-emerald-600" />
            </div>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Finished</p>
              <p className="text-2xl font-black text-slate-900 dark:text-white">{completedCount}</p>
            </div>
          </div>
        </div>
        <div className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-red-50 dark:bg-red-900/20">
              <Hourglass className="h-4 w-4 text-red-600" />
            </div>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Timed Out</p>
              <p className="text-2xl font-black text-slate-900 dark:text-white">{timeoutCount}</p>
            </div>
          </div>
        </div>
        <div className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-50 dark:bg-amber-900/20">
              <Award className="h-4 w-4 text-amber-600" />
            </div>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Avg Score</p>
              <p className="text-2xl font-black text-slate-900 dark:text-white">{avgScore}%</p>
            </div>
          </div>
        </div>
      </div>

      {/* Status Filter */}
      <div className="flex flex-wrap gap-2">
        {([
          ['all', 'All'],
          ['IN_PROGRESS', 'Active'],
          ['COMPLETED', 'Finished'],
          ['TIMED_OUT', 'Timed Out'],
          ['VOIDED', 'Voided'],
          ['NOT_STARTED', 'Not Started'],
        ] as const).map(([key, label]) => (
          <button
            key={key}
            onClick={() => setStatusFilter(key as StatusFilter)}
            className={cn(
              'rounded-full px-3 py-1.5 text-xs font-bold transition-colors',
              statusFilter === key
                ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900'
                : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300'
            )}
          >
            {label}
          </button>
        ))}
      </div>

      {/* Session Table */}
      {loading ? (
        <TableSkeleton rows={8} />
      ) : filteredSessions.length === 0 ? (
        <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-slate-200 py-16 dark:border-slate-800">
          <CheckCircle2 className="mb-3 h-10 w-10 text-slate-200 dark:text-slate-700" />
          <p className="text-sm font-medium text-slate-400">No sessions match the current filter.</p>
        </div>
      ) : (
        <div className="overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-700">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 dark:bg-slate-800">
              <tr>
                <SortHeader label="Student" sortKey="student.name" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300" />
                <SortHeader label="Status" sortKey="status" currentSort={sortConfig} onSort={requestSort} align="center" className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300" />
                <SortHeader label="Progress" sortKey="percentage" currentSort={sortConfig} onSort={requestSort} align="right" className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300" />
                <SortHeader label="Time Left" sortKey="timeRemaining" currentSort={sortConfig} onSort={requestSort} align="right" className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300" />
                <SortHeader label="Score" sortKey="score" currentSort={sortConfig} onSort={requestSort} align="right" className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300" />
                <th className="px-4 py-3 font-semibold text-right text-slate-600 dark:text-slate-300">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
              {items.map((s) => (
                <SessionRow
                  key={s.id}
                  session={s}
                  expanded={expandedSession === s.id}
                  onToggle={() => setExpandedSession(expandedSession === s.id ? null : s.id)}
                  onVoid={handleVoid}
                  onExtend={(id) => { setExtendModalOpen(id); setExtendMinutes(5) }}
                  onForceSubmit={handleForceSubmit}
                  onRemind={handleRemind}
                  actionLoading={actionLoading}
                  extendModalOpen={extendModalOpen === s.id}
                  extendMinutes={extendMinutes}
                  onExtendMinutesChange={setExtendMinutes}
                  onExtendConfirm={() => handleExtend(s.id)}
                  onExtendCancel={() => setExtendModalOpen(null)}
                />
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Start Exam Confirmation */}
      <ConfirmDialog
        open={startConfirmOpen}
        onOpenChange={setStartConfirmOpen}
        title="Start Exam for Class"
        description={`This will start the exam for all ${initialClass.enrolledCount} enrolled students in ${initialClass.name}. Each student will receive the full exam duration from when they begin.`}
        confirmLabel="Start Exam"
        variant="default"
        onConfirm={handleStartExam}
      />
    </div>
  )
}

function SessionRow({
  session,
  expanded,
  onToggle,
  onVoid,
  onExtend,
  onForceSubmit,
  onRemind,
  actionLoading,
  extendModalOpen,
  extendMinutes,
  onExtendMinutesChange,
  onExtendConfirm,
  onExtendCancel,
}: {
  session: MonitorSession
  expanded: boolean
  onToggle: () => void
  onVoid: (id: string) => void
  onExtend: (id: string) => void
  onForceSubmit: (id: string) => void
  onRemind: (id: string) => void
  actionLoading: string | null
  extendModalOpen: boolean
  extendMinutes: number
  onExtendMinutesChange: (m: number) => void
  onExtendConfirm: () => void
  onExtendCancel: () => void
}) {
  const isLoading = (action: string) => actionLoading === `${action}-${session.id}`

  return (
    <>
      <tr className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
        <td className="px-4 py-3">
          <p className="truncate font-medium text-slate-900 dark:text-white">{session.student.name}</p>
          <p className="truncate text-xs text-slate-500">{session.bank.name}</p>
        </td>
        <td className="px-4 py-3 text-center"><SessionStatusBadge status={session.status} /></td>
        <td className="px-4 py-3 w-40 tabular-nums">
          <ScoreBar value={session.percentage} />
          <span className="mt-1 block text-xs text-slate-400">
            {session.percentage != null ? `${session.percentage}%` : `${session.answerCount} answered`}
          </span>
        </td>
        <td className="px-4 py-3 text-right tabular-nums text-slate-500">
          {session.timeRemaining != null ? formatDuration(session.timeRemaining) : '—'}
        </td>
        <td className="px-4 py-3 text-right tabular-nums font-semibold text-slate-700 dark:text-slate-200">
          {session.score != null ? `${session.score}/${session.totalPoints ?? '?'}` : '—'}
        </td>
        <td className="px-4 py-3 text-right">
          <div className="flex items-center gap-1">
            <button
              onClick={onToggle}
              className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-medium text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-800"
            >
              {expanded ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
              {expanded ? 'Less' : 'More'}
            </button>
            {session.status === 'IN_PROGRESS' && (
              <>
                <button
                  onClick={() => onExtend(session.id)}
                  disabled={isLoading('extend')}
                  className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-medium text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                >
                  <Clock className="h-3 w-3" />
                  Extend
                </button>
                <button
                  onClick={() => onForceSubmit(session.id)}
                  disabled={isLoading('force')}
                  className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-medium text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/20"
                >
                  <Send className="h-3 w-3" />
                  Submit
                </button>
              </>
            )}
            {session.status !== 'VOIDED' && session.status !== 'COMPLETED' && (
              <button
                onClick={() => onVoid(session.id)}
                disabled={isLoading('void')}
                className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-medium text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
              >
                <XCircle className="h-3 w-3" />
                Void
              </button>
            )}
            {session.status === 'NOT_STARTED' && (
              <button
                onClick={() => onRemind(session.id)}
                disabled={isLoading('remind')}
                className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-medium text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-800"
              >
                <Send className="h-3 w-3" />
                Remind
              </button>
            )}
          </div>
        </td>
      </tr>
      {expanded && (
        <tr>
          <td colSpan={6} className="bg-slate-50 px-4 py-4 dark:bg-slate-800/30">
            <div className="space-y-2">
              <p className="text-xs font-bold text-slate-500">Session Detail</p>
              <div className="grid gap-2 text-xs text-slate-600 dark:text-slate-400 sm:grid-cols-3">
                <span>Started: {session.startedAt ? formatDateTime(session.startedAt) : '—'}</span>
                <span>Expires: {session.expiresAt ? formatDateTime(session.expiresAt) : '—'}</span>
                <span>Submitted: {session.submittedAt ? formatDateTime(session.submittedAt) : '—'}</span>
                <span>Correct: {session.correctCount}</span>
                <span>Answers: {session.answerCount}</span>
                <span>Passed: {session.passed == null ? '—' : session.passed ? 'Yes' : 'No'}</span>
              </div>
            </div>
          </td>
        </tr>
      )}
      {extendModalOpen && (
        <tr>
          <td colSpan={6} className="bg-blue-50 px-4 py-4 dark:bg-blue-900/10">
            <div className="flex flex-wrap items-center gap-3">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300">Extend time by:</span>
              {[5, 10, 15, 20, 30].map((m) => (
                <button
                  key={m}
                  onClick={() => onExtendMinutesChange(m)}
                  className={cn(
                    'rounded-lg px-3 py-1 text-xs font-bold',
                    extendMinutes === m
                      ? 'bg-blue-600 text-white'
                      : 'bg-white text-slate-600 border border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                  )}
                >
                  {m} min
                </button>
              ))}
              <button
                onClick={onExtendConfirm}
                className="rounded-lg bg-blue-600 px-4 py-1.5 text-xs font-bold text-white hover:bg-blue-700"
              >
                Confirm
              </button>
              <button
                onClick={onExtendCancel}
                className="rounded-lg border border-slate-200 px-4 py-1.5 text-xs font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300"
              >
                Cancel
              </button>
            </div>
          </td>
        </tr>
      )}
    </>
  )
}

'use client'

import React, { useMemo, useState } from 'react'
import {
  Search,
  History,
  User as UserIcon,
  BookOpen,
  Calendar,
  ChevronRight,
  Edit2,
  CheckCircle2,
  Clock,
} from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'

const MotionDiv = motion.div
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { format } from 'date-fns'
import { submitGrade } from '@/lib/actions/instructor'
import { toast } from 'sonner'
import TablePagination from '@/components/shared/TablePagination'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Label } from '@/components/ui/label'

interface GradedItem {
  id: string
  assessmentName: string
  assessmentType: string
  score: number
  comments?: string | null
  updatedAt: string
  user: {
    profile: {
      firstName: string
      lastName: string
    } | null
  }
  enrollment: {
    course: {
      code: string
      name: string
    }
  }
}

interface GradingHistoryViewProps {
  initialHistory: GradedItem[]
}

export default function GradingHistoryView({ initialHistory }: GradingHistoryViewProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedGrade, setSelectedGrade] = useState<GradedItem | null>(null)
  const [score, setScore] = useState<string>('')
  const [comments, setComments] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)

  const filteredHistory = useMemo(() => {
    return initialHistory.filter((item) => {
      const lowerQuery = searchQuery.toLowerCase()
      const studentName =
        `${item.user.profile?.firstName} ${item.user.profile?.lastName}`.toLowerCase()
      return (
        studentName.includes(lowerQuery) ||
        item.assessmentName.toLowerCase().includes(lowerQuery) ||
        item.enrollment.course.code.toLowerCase().includes(lowerQuery) ||
        item.enrollment.course.name.toLowerCase().includes(lowerQuery)
      )
    })
  }, [initialHistory, searchQuery])

  const total = filteredHistory.length
  const paged = filteredHistory.slice((page - 1) * perPage, page * perPage)

  const handleEditSubmit = async () => {
    if (!selectedGrade || !score) return

    const scoreNum = parseFloat(score)
    if (isNaN(scoreNum) || scoreNum < 0 || scoreNum > 100) {
      toast.error('Please enter a valid score between 0 and 100')
      return
    }

    setIsSubmitting(true)
    try {
      await submitGrade({
        gradeId: selectedGrade.id,
        score: scoreNum,
        comments,
      })
      toast.success(`Grade updated for ${selectedGrade.user.profile?.firstName || 'Student'}`)
      setSelectedGrade(null)
    } catch (error) {
      toast.error('Failed to update grade. Please try again.')
    } finally {
      setIsSubmitting(false)
    }
  }

  const openEditModal = (item: GradedItem) => {
    setSelectedGrade(item)
    setScore(item.score.toString())
    setComments(item.comments || '')
  }

  return (
    <div className="flex flex-col space-y-8">
      {/* Search Header */}
      <div className="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
        <div className="relative max-w-xl flex-1">
          <Search className="absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400 dark:text-slate-300" />
          <Input
            placeholder="Search history by student, assessment, or module..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="focus:border-aerojet-sky h-14 rounded-2xl border-slate-100 bg-white pl-11 text-sm font-medium shadow-sm transition-all focus:ring-4 focus:ring-blue-50/50 dark:border-slate-800 dark:bg-slate-900"
          />
        </div>

        <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-slate-500 uppercase">
          <History className="text-aerojet-sky h-4 w-4" />
          <span>{total} Graded Assessments</span>
        </div>
      </div>

      {/* History List */}
      <div className="grid gap-4">
        <AnimatePresence mode="popLayout">
          {initialHistory.length > 0 ? (
            initialHistory.map((item) => (
              <MotionDiv
                key={item.id}
                layout
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.98 }}
                transition={{ duration: 0.2 }}
              >
                <Card className="group hover:border-aerojet-sky/30 overflow-hidden rounded-3xl border-slate-100 bg-white transition-all hover:shadow-xl hover:shadow-blue-500/5 dark:border-slate-800 dark:bg-slate-900">
                  <CardContent className="p-0">
                    <div className="flex flex-col md:flex-row md:items-center">
                      {/* Left: Score Badge */}
                      <div className="flex flex-col items-center justify-center gap-1 border-b border-slate-50 p-6 md:w-32 md:border-r md:border-b-0 dark:border-slate-800/50">
                        <span className="text-aerojet-sky text-2xl font-black">{item.score}%</span>
                        <span className="text-[10px] font-black text-slate-400 uppercase">
                          Score
                        </span>
                      </div>

                      {/* Middle: Content */}
                      <div className="flex-1 space-y-2 p-6">
                        <div className="flex flex-wrap items-center gap-2">
                          <p className="text-aerojet-sky text-[10px] font-black tracking-widest uppercase">
                            {item.enrollment.course.code}
                          </p>
                          <span className="text-slate-200">|</span>
                          <span className="text-xs font-bold text-slate-900 dark:text-white">
                            {item.assessmentName}
                          </span>
                        </div>

                        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                          <div className="space-y-1">
                            <h3 className="line-clamp-1 text-lg font-black text-slate-900 dark:text-white">
                              {item.user.profile?.firstName} {item.user.profile?.lastName}
                            </h3>
                            <div className="flex items-center gap-4 text-xs font-bold text-slate-400">
                              <div className="flex items-center gap-1.5">
                                <Clock className="h-3.5 w-3.5" />
                                <span>
                                  Graded on {format(new Date(item.updatedAt), 'MMM d, yyyy')}
                                </span>
                              </div>
                            </div>
                          </div>

                          <Button
                            variant="outline"
                            onClick={() => openEditModal(item)}
                            className="hover:border-aerojet-sky hover:text-aerojet-sky rounded-xl border-slate-100 font-bold transition-all hover:bg-blue-50 dark:border-slate-800 dark:hover:bg-blue-900/20"
                          >
                            <Edit2 className="mr-2 h-4 w-4" />
                            Edit Grade
                          </Button>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </MotionDiv>
            ))
          ) : (
            <div className="flex flex-col items-center justify-center rounded-4xl border border-dashed border-slate-200 py-32 dark:border-slate-800">
              <div className="mb-4 flex h-20 w-20 items-center justify-center rounded-3xl bg-slate-50 dark:bg-slate-800/50">
                <History className="h-10 w-10 text-slate-200 dark:text-slate-700" />
              </div>
              <h3 className="text-xl font-black text-slate-900 dark:text-white">No history yet</h3>
              <p className="mt-2 text-sm font-medium text-slate-400">
                Assessments you grade will appear here.
              </p>
            </div>
          )}
        </AnimatePresence>
      </div>

      {total > 0 && (
        <TablePagination
          page={page}
          perPage={perPage}
          total={total}
          onPageChange={setPage}
          onPerPageChange={setPerPage}
        />
      )}

      {/* Edit Grading Dialog */}
      <Dialog open={!!selectedGrade} onOpenChange={(open) => !open && setSelectedGrade(null)}>
        <DialogContent className="max-w-lg overflow-hidden rounded-4xl border-none p-0">
          <div className="bg-slate-900 p-8 text-white">
            <DialogHeader className="space-y-1">
              <div className="flex items-center gap-2 text-[10px] font-black tracking-[0.2em] text-blue-300 uppercase">
                <Edit2 className="h-4 w-4" />
                Edit Grade Entry
              </div>
              <DialogTitle className="text-3xl font-black">Update Score</DialogTitle>
              <DialogDescription className="text-slate-400">
                Adjusting results for{' '}
                <span className="font-bold text-white">
                  {selectedGrade?.user.profile?.firstName} {selectedGrade?.user.profile?.lastName}
                </span>
              </DialogDescription>
            </DialogHeader>
          </div>

          <div className="space-y-8 p-8">
            <div className="grid gap-6">
              <div className="space-y-3">
                <Label
                  htmlFor="score"
                  className="text-xs font-black tracking-widest text-slate-400 uppercase"
                >
                  New Score (%)
                </Label>
                <div className="relative">
                  <Input
                    id="score"
                    type="number"
                    placeholder="0-100"
                    value={score}
                    onChange={(e) => setScore(e.target.value)}
                    className="h-16 rounded-2xl border-slate-100 bg-slate-50 text-2xl font-black placeholder:text-slate-200 dark:border-slate-800 dark:bg-slate-900"
                    min="0"
                    max="100"
                  />
                  <div className="absolute top-1/2 right-6 -translate-y-1/2 text-xl font-black text-slate-300">
                    %
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <Label
                  htmlFor="comments"
                  className="text-xs font-black tracking-widest text-slate-400 uppercase"
                >
                  Updated Feedback
                </Label>
                <textarea
                  id="comments"
                  rows={4}
                  value={comments}
                  onChange={(e) => setComments(e.target.value)}
                  placeholder="Update your feedback for the student..."
                  className="focus:border-aerojet-sky w-full rounded-2xl border border-slate-100 bg-slate-50 p-4 text-sm font-medium focus:ring-4 focus:ring-blue-50/50 focus:outline-none dark:border-slate-800 dark:bg-slate-900"
                />
              </div>
            </div>

            <DialogFooter className="flex-col gap-3 sm:flex-col">
              <Button
                onClick={handleEditSubmit}
                disabled={isSubmitting || !score}
                className="bg-aerojet-blue h-14 w-full rounded-2xl text-base font-black text-white hover:bg-[#003a7c] disabled:opacity-50 dark:bg-blue-600 dark:hover:bg-blue-700"
              >
                {isSubmitting ? (
                  <span className="flex items-center gap-2">
                    <div className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                    Updating...
                  </span>
                ) : (
                  'Save Changes'
                )}
              </Button>
              <Button
                variant="ghost"
                onClick={() => setSelectedGrade(null)}
                className="h-12 w-full rounded-2xl font-bold text-slate-400 hover:text-slate-900 dark:hover:text-white"
              >
                Go Back
              </Button>
            </DialogFooter>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

