'use client'

import { useState, useMemo } from 'react'
import {
  TrendingUp,
  Clock,
  CheckCircle2,
  XCircle,
  RefreshCw,
  Wallet,
} from 'lucide-react'
import dynamic from 'next/dynamic'
import type { FinanceOverviewData } from '@/lib/finance/overview'
import { useSort, SortHeader } from '@/lib/hooks/useSort'
const RevenueChart = dynamic(() => import('./RevenueChart'), { ssr: false })

const STATUS_CONFIG: Record<string, { label: string; icon: any; style: string }> = {
  APPROVED: { label: 'Approved', icon: CheckCircle2, style: 'text-emerald-600 bg-emerald-50' },
  PENDING: { label: 'Pending', icon: Clock, style: 'text-amber-600 bg-amber-50' },
  REJECTED: { label: 'Rejected', icon: XCircle, style: 'text-red-600 bg-red-50' },
}

export default function FinanceOverview({
  chartData,
  initialData,
}: {
  chartData: { month: string; revenue: number }[]
  initialData: FinanceOverviewData
}) {
  const [data, setData] = useState<FinanceOverviewData | null>(initialData)
  const [loading, setLoading] = useState(false)

  const sortableTransactions = useMemo(
    () =>
      (data?.recentTransactions ?? []).map((tx) => ({
        ...tx,
        _userSort: tx.user.profile
          ? `${tx.user.profile.firstName} ${tx.user.profile.lastName}`.toLowerCase()
          : tx.user.email.toLowerCase(),
      })),
    [data]
  )
  const { items: sortedTransactions, requestSort, sortConfig } = useSort(sortableTransactions)

  const fetchData = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/staff/finance/overview')
      if (!res.ok) return
      setData(await res.json())
    } finally {
      setLoading(false)
    }
  }

  const regGrowth = data
    ? data.lastMonthRegistration > 0
      ? ((data.monthRegistration - data.lastMonthRegistration) / data.lastMonthRegistration) * 100
      : 0
    : 0

  const courseGrowth = data
    ? data.lastMonthCourse > 0
      ? ((data.monthCourse - data.lastMonthCourse) / data.lastMonthCourse) * 100
      : 0
    : 0

  const statCards = [
    {
      label: 'Total Revenue',
      value: `EUR ${Number(data?.totalRevenue ?? 0).toLocaleString('en-GB', { minimumFractionDigits: 0 })}`,
      icon: TrendingUp,
      bg: 'bg-emerald-50',
      color: 'text-emerald-600',
      sub: data ? `${data.totalRevenueCount} approved payments` : undefined,
    },
    {
      label: 'Registration Revenue',
      value: `GHS ${Number(data?.totalRegistration ?? 0).toLocaleString('en-GH', { minimumFractionDigits: 0 })}`,
      icon: Wallet,
      bg: 'bg-blue-50',
      color: 'text-aerojet-sky',
      sub: data ? `${regGrowth >= 0 ? '+' : ''}${regGrowth.toFixed(1)}% vs last month` : undefined,
      growthPositive: regGrowth >= 0,
    },
    {
      label: 'Course Revenue',
      value: `EUR ${Number(data?.totalCourse ?? 0).toLocaleString('en-GB', { minimumFractionDigits: 0 })}`,
      icon: Wallet,
      bg: 'bg-emerald-50',
      color: 'text-emerald-600',
      sub: data
        ? `${courseGrowth >= 0 ? '+' : ''}${courseGrowth.toFixed(1)}% vs last month`
        : undefined,
      growthPositive: courseGrowth >= 0,
    },
    {
      label: 'Pending Verification',
      value: String(data?.pendingCount ?? 0),
      icon: Clock,
      bg: 'bg-amber-50',
      color: 'text-amber-600',
      sub: data ? `Pending total: EUR ${Number(data.pendingTotal ?? 0).toLocaleString('en-GB', { minimumFractionDigits: 0 })}` : undefined,
      href: '/staff/payments?tab=PENDING',
    },
  ]

  return (
    <div className="space-y-6">
      {/* Refresh */}
      <div className="flex justify-end">
        <button
          onClick={fetchData}
          className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 dark:hover:border-slate-600"
        >
          <RefreshCw className="h-3.5 w-3.5" /> Refresh
        </button>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {statCards.map((s) => {
          const Icon = s.icon
          const card = (
            <div
              className={`flex items-start gap-4 rounded-2xl border border-slate-100 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900 ${s.href ? 'cursor-pointer transition-shadow hover:shadow-md' : ''}`}
            >
              <div
                className={`h-11 w-11 rounded-xl ${s.bg} flex shrink-0 items-center justify-center`}
              >
                <Icon className={`h-5 w-5 ${s.color}`} />
              </div>
              <div className="min-w-0">
                <p className="truncate text-xl font-black text-slate-800 dark:text-slate-200">
                  {loading ? '—' : s.value}
                </p>
                <p className="truncate text-[11px] font-bold tracking-wider text-slate-400 uppercase">
                  {s.label}
                </p>
                {s.sub && (
                  <p
                    className={`mt-0.5 text-[11px] font-bold ${
                      'growthPositive' in s
                        ? s.growthPositive
                          ? 'text-emerald-600'
                          : 'text-red-500'
                        : 'text-slate-400'
                    }`}
                  >
                    {s.sub}
                  </p>
                )}
              </div>
            </div>
          )
          return s.href ? (
            <a key={s.label} href={s.href}>
              {card}
            </a>
          ) : (
            <div key={s.label}>{card}</div>
          )
        })}
      </div>

      {/* Revenue Chart */}
      <div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h2 className="text-sm font-black tracking-tight text-slate-800 uppercase dark:text-slate-200">
              Revenue - Last 6 Months
            </h2>
            <p className="mt-0.5 text-xs text-slate-400">Approved payments in EUR</p>
          </div>
          <TrendingUp className="text-aerojet-sky h-5 w-5" />
        </div>
        {chartData.some((d) => d.revenue > 0) ? (
          <RevenueChart data={chartData} currency="EUR " />
        ) : (
          <div className="flex h-48 items-center justify-center">
            <p className="text-sm font-bold text-slate-300">No revenue data yet</p>
          </div>
        )}
      </div>

      {/* Transactions Table */}
      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="border-b border-slate-100 px-6 py-4 dark:border-slate-800">
          <h2 className="text-sm font-black tracking-tight text-slate-800 uppercase dark:text-slate-200">
            Recent Transactions
          </h2>
        </div>
        <div className="hidden overflow-x-auto md:block">
          <table className="w-full text-left">
            <thead>
              <tr className="border-b border-slate-100 bg-slate-50 dark:border-slate-800 dark:bg-slate-800/50">
                <SortHeader label="User" sortKey="_userSort" currentSort={sortConfig} onSort={requestSort} className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-400 uppercase" />
                <SortHeader label="Type" sortKey="referenceType" currentSort={sortConfig} onSort={requestSort} className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-400 uppercase" />
                <SortHeader label="Amount" sortKey="amount" currentSort={sortConfig} onSort={requestSort} align="right" className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-400 uppercase" />
                <SortHeader label="Method" sortKey="paymentMethod" currentSort={sortConfig} onSort={requestSort} className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-400 uppercase" />
                <SortHeader label="Status" sortKey="status" currentSort={sortConfig} onSort={requestSort} align="center" className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-400 uppercase" />
                <SortHeader label="Date" sortKey="createdAt" currentSort={sortConfig} onSort={requestSort} align="right" className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-400 uppercase" />
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                Array.from({ length: 8 }).map((_, i) => (
                  <tr key={i}>
                    {Array.from({ length: 6 }).map((_, j) => (
                      <td key={j} className="px-5 py-3.5">
                        <div className="h-4 w-3/4 animate-pulse rounded bg-slate-100" />
                      </td>
                    ))}
                  </tr>
                ))
              ) : !sortedTransactions.length ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center">
                    <p className="text-sm font-bold text-slate-400">No transactions yet</p>
                  </td>
                </tr>
              ) : (
                sortedTransactions.map((tx) => {
                  const fullName = tx.user.profile
                    ? [
                        tx.user.profile.firstName,
                        tx.user.profile.middleName,
                        tx.user.profile.lastName,
                      ]
                        .filter(Boolean)
                        .join(' ')
                    : tx.user.email
                  const cfg = STATUS_CONFIG[tx.status] ?? {
                    label: tx.status,
                    icon: Clock,
                    style: 'text-slate-500 bg-slate-50',
                  }
                  const StatusIcon = cfg.icon
                  return (
                    <tr
                      key={tx.id}
                      className="transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/60"
                    >
                      <td className="px-5 py-3.5">
                        <p className="text-sm font-bold text-slate-700">{fullName}</p>
                        <p className="text-xs text-slate-400">{tx.user.email}</p>
                      </td>
                      <td className="px-5 py-3.5 text-xs font-bold text-slate-600 dark:text-slate-400">
                        {tx.referenceType?.replace(/_/g, ' ') ?? '-'}
                      </td>
                      <td className="text-aerojet-blue dark:text-aerojet-sky px-5 py-3.5 text-sm font-black">
                        {tx.currency}{' '}
                        {Number(tx.amount).toLocaleString('en-GH', { minimumFractionDigits: 2 })}
                      </td>
                      <td className="px-5 py-3.5 text-xs text-slate-500 dark:text-slate-400">
                        {tx.paymentMethod.replace(/_/g, ' ')}
                      </td>
                      <td className="px-5 py-3.5">
                        <span
                          className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-black uppercase ${cfg.style}`}
                        >
                          <StatusIcon className="h-3 w-3" /> {cfg.label}
                        </span>
                      </td>
                      <td className="px-5 py-3.5 text-xs text-slate-500 dark:text-slate-400">
                        {new Date(tx.createdAt).toLocaleDateString('en-GB', {
                          day: 'numeric',
                          month: 'short',
                          year: 'numeric',
                        })}
                      </td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>

        {/* Mobile Card View */}
        <div className="block divide-y divide-slate-100 md:hidden dark:divide-slate-800">
          {loading ? (
            Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="space-y-3 p-4">
                <div className="h-4 w-3/4 animate-pulse rounded bg-slate-100" />
                <div className="h-4 w-1/2 animate-pulse rounded bg-slate-100" />
              </div>
            ))
          ) : !data?.recentTransactions?.length ? (
            <div className="py-12 text-center">
              <p className="text-sm font-bold text-slate-400">No transactions yet</p>
            </div>
          ) : (
            data.recentTransactions.map((tx) => {
              const fullName = tx.user.profile
                ? [tx.user.profile.firstName, tx.user.profile.middleName, tx.user.profile.lastName]
                    .filter(Boolean)
                    .join(' ')
                : tx.user.email
              const cfg = STATUS_CONFIG[tx.status] ?? {
                label: tx.status,
                icon: Clock,
                style: 'text-slate-500 bg-slate-50',
              }
              const StatusIcon = cfg.icon
              return (
                <div key={tx.id} className="space-y-2 p-4">
                  <div className="flex items-start justify-between">
                    <div>
                      <p className="text-sm font-bold text-slate-700 dark:text-slate-200">
                        {fullName}
                      </p>
                      <p className="text-xs text-slate-400">{tx.user.email}</p>
                    </div>
                    <span
                      className={`inline-flex shrink-0 items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-black uppercase ${cfg.style}`}
                    >
                      <StatusIcon className="h-3 w-3" /> {cfg.label}
                    </span>
                  </div>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div>
                      <p className="font-bold tracking-wider text-slate-400 uppercase">Amount</p>
                      <p className="text-aerojet-blue font-black dark:text-blue-400">
                        {tx.currency}{' '}
                        {Number(tx.amount).toLocaleString('en-GH', { minimumFractionDigits: 2 })}
                      </p>
                    </div>
                    <div>
                      <p className="font-bold tracking-wider text-slate-400 uppercase">Method</p>
                      <p className="font-bold text-slate-600 dark:text-slate-400">
                        {tx.paymentMethod.replace(/_/g, ' ')}
                      </p>
                    </div>
                    <div>
                      <p className="font-bold tracking-wider text-slate-400 uppercase">Type</p>
                      <p className="font-bold text-slate-600 dark:text-slate-400">
                        {tx.referenceType?.replace(/_/g, ' ') ?? '-'}
                      </p>
                    </div>
                    <div>
                      <p className="font-bold tracking-wider text-slate-400 uppercase">Date</p>
                      <p className="font-bold text-slate-600 dark:text-slate-400">
                        {new Date(tx.createdAt).toLocaleDateString('en-GB', {
                          day: 'numeric',
                          month: 'short',
                          year: 'numeric',
                        })}
                      </p>
                    </div>
                  </div>
                </div>
              )
            })
          )}
        </div>
        <div className="border-t border-slate-100 px-6 py-3 dark:border-slate-800">
          <a
            href="/staff/finance?tab=transactions"
            className="text-aerojet-sky text-xs font-bold hover:underline"
          >
            View all transactions →
          </a>
        </div>
      </div>
    </div>
  )
}

'use client'

import { TrendingUp, TrendingDown, AlertTriangle, CheckCircle2 } from 'lucide-react'

interface GoNoGoMeterProps {
  currentRevenue: number
  targetRevenue: number
  confirmedSeats: number
  totalSeats: number
  paymentDeadline: string
  poolName?: string
}

export default function GoNoGoMeter({
  currentRevenue,
  targetRevenue,
  confirmedSeats,
  totalSeats,
  paymentDeadline,
  poolName,
}: GoNoGoMeterProps) {
  const progress = Math.min((currentRevenue / targetRevenue) * 100, 100)
  const isGo = currentRevenue >= targetRevenue
  // eslint-disable-next-line react-hooks/purity
  const isNearDeadline = new Date(paymentDeadline).getTime() - Date.now() < 7 * 24 * 60 * 60 * 1000

  const deadlineStr = new Date(paymentDeadline).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  })

  const progressColor = isGo ? 'bg-emerald-500' : progress >= 75 ? 'bg-amber-500' : 'bg-red-500'

  const statusBg = isGo
    ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-200 dark:border-emerald-800/50'
    : isNearDeadline
      ? 'bg-red-50 dark:bg-red-900/10 border-red-200 dark:border-red-800/50'
      : 'bg-amber-50 dark:bg-amber-900/10 border-amber-200 dark:border-amber-800/50'

  return (
    <div className={`rounded-2xl border p-5 ${statusBg}`}>
      {/* Header */}
      <div className="mb-4 grid grid-cols-[1fr_auto] items-start gap-4">
        <div>
          <p className="text-[10px] font-black tracking-widest text-slate-500 uppercase dark:text-slate-400">
            Go / No-Go Meter
          </p>
          {poolName && (
            <h3 className="mt-0.5 text-sm font-black leading-tight text-slate-800 dark:text-white">
              {poolName}
            </h3>
          )}
        </div>
        <div
          className={`flex shrink-0 items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-black ${
            isGo ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'
          }`}
        >
          {isGo ? (
            <CheckCircle2 className="h-3.5 w-3.5" />
          ) : (
            <AlertTriangle className="h-3.5 w-3.5" />
          )}
          {isGo ? 'GO' : 'NO-GO'}
        </div>
      </div>

      {/* Revenue Progress */}
      <div className="mb-4">
        <div className="mb-1.5 flex items-baseline justify-between">
          <span className="text-xs font-bold text-slate-600 dark:text-slate-300">
            Revenue Progress
          </span>
          <span className="text-xs font-black text-slate-800 dark:text-white">
            €{currentRevenue.toLocaleString()} / €{targetRevenue.toLocaleString()}
          </span>
        </div>
        <div className="h-3 overflow-hidden rounded-full border border-slate-200 bg-white/70 dark:border-slate-700 dark:bg-slate-900/50">
          <div
            className={`h-full rounded-full transition-all duration-700 ${progressColor}`}
            style={{ width: `${progress}%` }}
          />
        </div>
        <div className="mt-1 flex justify-between">
          <span className="text-[10px] text-slate-400 dark:text-slate-500">
            {progress.toFixed(0)}% of target
          </span>
          <span className="text-[10px] text-slate-400 dark:text-slate-500">
            {isGo
              ? `+€${(currentRevenue - targetRevenue).toLocaleString()} over target`
              : `€${(targetRevenue - currentRevenue).toLocaleString()} remaining`}
          </span>
        </div>
      </div>

      {/* Stats Row */}
      <div className="grid grid-cols-2 gap-3">
        <div className="rounded-xl bg-white/60 px-3 py-2.5 dark:bg-black/20">
          <p className="text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
            Seats Filled
          </p>
          <p className="text-lg font-black text-slate-800 dark:text-white">
            {confirmedSeats}
            <span className="text-sm font-bold text-slate-400 dark:text-slate-500">
              /{totalSeats}
            </span>
          </p>
        </div>
        <div
          className={`rounded-xl px-3 py-2.5 ${isNearDeadline ? 'bg-red-100 dark:bg-red-900/30' : 'bg-white/60 dark:bg-black/20'}`}
        >
          <p className="text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
            Deadline
          </p>
          <p
            className={`text-sm font-black ${isNearDeadline ? 'text-red-600 dark:text-red-400' : 'text-slate-800 dark:text-white'}`}
          >
            {deadlineStr}
          </p>
          {isNearDeadline && (
            <p className="text-[10px] font-bold text-red-500 dark:text-red-400">⚠ Closing soon</p>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import {
  GraduationCap,
  RefreshCw,
  Search,
  CheckSquare,
  Square,
  CheckCircle2,
  AlertTriangle,
  Trash2,
  Mail,
  LockOpen,
  Archive,
} from 'lucide-react'

import TablePagination from './TablePagination'
import BulkActionsDropdown from './BulkActionsDropdown'
import { SortableTh } from '@/components/ui/sortable-th'
import { useSearchParams } from 'next/navigation'
import {
  bulkUpdateUserStatus,
  bulkDeleteUsers,
  bulkArchiveUsers,
  bulkBypassPasswordChange,
} from '../actions'
import { toast } from 'sonner'

interface Instructor {
  id: string
  email: string
  academyEmail: string | null
  status: string
  profile: { firstName: string; middleName?: string | null; lastName: string } | null
  instructorProfile: { employeeId: string | null; specialization: string | null } | null
}


function slugify(text: string) {
  return text?.toString().toLowerCase().trim().replace(/\s+/g, '-').replace(/[^\w\-]+/g, '').replace(/\-\-+/g, '-') || '';
}

export default function InstructorsTable() {
  const searchParams = useSearchParams()
  const [instructors, setInstructors] = useState<Instructor[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)
  const router = useRouter()

  const fetchInstructors = useCallback(async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        role: 'INSTRUCTOR',
        search,
        page: page.toString(),
        limit: perPage.toString(),
      })
      const sort = searchParams.get('sort')
      const order = searchParams.get('order')
      if (sort) params.set('sort', sort)
      if (order) params.set('order', order)
      const res = await fetch(`/api/staff/users?${params}`)
      const data = await res.json()

      if (data.success) {
        setInstructors(data.data ?? [])
        setTotal(data.meta?.total ?? 0)
      } else {
        setInstructors([])
        setTotal(0)
      }
    } finally {
      setLoading(false)
    }
  }, [search, page, perPage, searchParams])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setPage(1)
  }, [search])

  useEffect(() => {
    const t = setTimeout(fetchInstructors, search ? 350 : 0)
    return () => clearTimeout(t)
  }, [fetchInstructors, search])

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <p className="text-sm text-slate-500 dark:text-slate-400">
          Manage teaching staff and their assignments
        </p>
        <div className="flex items-center gap-2">
          <div className="relative w-full sm:w-60">
            <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              id="instructors-search"
              name="instructors-search"
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search instructors..."
              autoComplete="off"
              className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pr-4 pl-9 text-xs outline-none focus:ring-2 focus:ring-aerojet-sky dark:border-slate-700 dark:bg-slate-800/50"
            />
          </div>
          <button
            onClick={fetchInstructors}
            className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 dark:hover:border-slate-600"
          >
            <RefreshCw className="h-3.5 w-3.5" />
          </button>
          <BulkActionsDropdown
            selectedIds={selectedIds}
            onClear={() => setSelectedIds([])}
            actions={[
              {
                label: 'Activate',
                icon: CheckCircle2,
                variant: 'success',
                confirmTitle: 'Activate Instructors',
                confirmMessage: `Are you sure you want to activate ${selectedIds.length} selected instructors?`,
                onClick: async (ids) => {
                  const res = await bulkUpdateUserStatus(ids, 'ACTIVE')
                  if (res.success) {
                    toast.success(`Activated ${ids.length} instructors`)
                    fetchInstructors()
                  } else toast.error(res.error)
                },
              },
              {
                label: 'Suspend',
                icon: AlertTriangle,
                variant: 'warning',
                confirmTitle: 'Suspend Instructors',
                confirmMessage: `Are you sure you want to suspend ${selectedIds.length} selected instructors?`,
                onClick: async (ids) => {
                  const res = await bulkUpdateUserStatus(ids, 'SUSPENDED')
                  if (res.success) {
                    toast.success(`Suspended ${ids.length} instructors`)
                    fetchInstructors()
                  } else toast.error(res.error)
                },
              },
              instructors.filter((i) => selectedIds.includes(i.id)).length > 0 &&
              instructors
                .filter((i) => selectedIds.includes(i.id))
                .every((i) => i.status === 'ARCHIVED')
                ? {
                    label: 'Permanently Delete',
                    icon: Trash2,
                    variant: 'danger',
                    confirmTitle: 'Permanently Delete Instructors',
                    confirmMessage: `Are you sure you want to permanently delete ${selectedIds.length} instructors? This cannot be undone.`,
                    onClick: async (ids) => {
                      const res = await bulkDeleteUsers(ids)
                      if (res.success) {
                        toast.success(`Permanently deleted ${ids.length} instructors`)
                        fetchInstructors()
                      } else toast.error(res.error)
                    },
                  }
                : {
                    label: 'Archive',
                    icon: Archive,
                    variant: 'warning',
                    confirmTitle: 'Archive Instructors',
                    confirmMessage: `Are you sure you want to archive ${selectedIds.length} instructors?`,
                    onClick: async (ids) => {
                      const res = await bulkArchiveUsers(ids)
                      if (res.success) {
                        toast.success(`Archived ${ids.length} instructors`)
                        fetchInstructors()
                      } else toast.error(res.error)
                    },
                  },
              {
                label: 'Bypass PW Change',
                icon: LockOpen,
                variant: 'primary',
                confirmTitle: 'Bypass Password Change',
                confirmMessage: `Are you sure you want to bypass the required password change for ${selectedIds.length} selected instructors?`,
                onClick: async (ids) => {
                  const res = await bulkBypassPasswordChange(ids)
                  if (res.success) {
                    toast.success(`Bypassed password change for ${ids.length} instructors`)
                    fetchInstructors()
                  } else toast.error(res.error)
                },
              },
              {
                label: 'Send Email',
                icon: Mail,
                variant: 'default',
                onClick: async (ids) => {
                  const selectedEmails = instructors
                    .filter((i) => ids.includes(i.id))
                    .map((i) => i.email)
                    .filter(Boolean)
                  if (selectedEmails.length > 0) {
                    window.location.href = `mailto:${selectedEmails.join(',')}`
                  }
                },
              },
            ]}
          />
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase dark:bg-slate-800/50 dark:text-slate-400">
              <tr>
                <th className="w-12 px-6 py-4">
                  <button
                    onClick={() => {
                      if (selectedIds.length === instructors.length && instructors.length > 0) {
                        setSelectedIds([])
                      } else {
                        setSelectedIds(instructors.map((i) => i.id))
                      }
                    }}
                    className="hover:text-aerojet-blue text-slate-400 transition-colors"
                    aria-label="Select all instructors"
                  >
                    {selectedIds.length === instructors.length && instructors.length > 0 ? (
                      <CheckSquare className="text-aerojet-blue h-4 w-4" />
                    ) : (
                      <Square className="h-4 w-4" />
                    )}
                  </button>
                </th>
                <SortableTh sortKey="name" label="Instructor" />
                <th className="px-6 py-4">Employee ID</th>
                <th className="px-6 py-4">Specialization</th>
                <SortableTh sortKey="name" label="Email" />
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {loading ? (
                Array.from({ length: 4 }).map((_, i) => (
                  <tr key={i}>
                    <td className="px-6 py-4">
                      <div className="h-4 w-4 animate-pulse rounded bg-slate-100 dark:bg-slate-800" />
                    </td>
                    {Array.from({ length: 5 }).map((_, j) => (
                      <td key={j} className="px-6 py-4">
                        <div className="h-4 w-3/4 animate-pulse rounded bg-slate-100 dark:bg-slate-800" />
                      </td>
                    ))}
                  </tr>
                ))
              ) : instructors.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center">
                    <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-slate-50 dark:bg-slate-800/50">
                      <GraduationCap className="h-6 w-6 text-slate-300" />
                    </div>
                    <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100">
                      No instructors found
                    </h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400">
                      Instructors will appear here once added to the system.
                    </p>
                  </td>
                </tr>
              ) : (
                instructors.map((instructor) => (
                  <tr
                    key={instructor.id}
                    onClick={() => router.push(`/staff/users/${instructor.id}`)}
                    className={`group cursor-pointer transition-all duration-150 ease-out hover:bg-accent hover:shadow-[0_1px_4px_rgba(0,0,0,0.06)] dark:hover:bg-accent ${selectedIds.includes(instructor.id) ? 'bg-aerojet-blue/5' : ''}`}
                  >
                    <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                      <button
                        onClick={() => {
                          setSelectedIds((prev) =>
                            prev.includes(instructor.id)
                              ? prev.filter((id) => id !== instructor.id)
                              : [...prev, instructor.id]
                          )
                        }}
                        className="hover:text-aerojet-blue text-slate-300 transition-colors"
                        aria-label={`Select ${instructor.profile ? `${instructor.profile.firstName} ${instructor.profile.lastName}` : instructor.email}`}
                      >
                        {selectedIds.includes(instructor.id) ? (
                          <CheckSquare className="text-aerojet-blue h-4 w-4" />
                        ) : (
                          <Square className="h-4 w-4" />
                        )}
                      </button>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-100 font-bold text-aerojet-blue dark:bg-slate-800">
                          {instructor.profile?.firstName?.charAt(0)}
                          {instructor.profile?.lastName?.charAt(0)}
                        </div>
                        <div>
                          <div className="font-bold text-slate-900 dark:text-slate-100">
                            {(() => {
                              const fullName = instructor.profile
                                ? [
                                    instructor.profile.firstName,
                                    instructor.profile.middleName,
                                    instructor.profile.lastName,
                                  ]
                                    .filter(Boolean)
                                    .join(' ')
                                : instructor.email
                              return fullName
                            })()}
                          </div>
                          <div className="text-xs text-slate-500 dark:text-slate-400">
                            {instructor.email}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-400">
                      {instructor.instructorProfile?.employeeId ?? 'â€”'}
                    </td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-400">
                      {instructor.instructorProfile?.specialization ?? 'â€”'}
                    </td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-400">
                      {instructor.academyEmail ?? instructor.email}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <Link
                        href={`/staff/users/${slugify(instructor.profile ? `${instructor.profile.firstName} ${instructor.profile.lastName}` : instructor.email.split('@')[0])}`}
                        className="inline-flex items-center rounded-md px-1.5 py-0.5 text-xs font-bold text-aerojet-blue transition-all duration-150 ease-out hover:bg-aerojet-blue/8 hover:shadow-sm dark:text-aerojet-sky"
                      >
                        View
                      </Link>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
        <TablePagination
          page={page}
          perPage={perPage}
          total={total}
          onPageChange={setPage}
          onPerPageChange={setPerPage}
        />
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  CheckCircle2,
  XCircle,
  ExternalLink,
  Loader2,
  User,
  Calendar,
  DollarSign,
} from 'lucide-react'

interface PaymentApprovalCardProps {
  payment: {
    id: string
    amount: number
    currency?: string
    paymentMethod: string
    referenceCode?: string | null
    referenceType?: string | null
    proofUrl?: string | null
    createdAt: string
    user: {
      id: string
      email: string
      profile?: { firstName: string; lastName: string } | null
    }
  }
  onApproved?: (id: string) => void
  onRejected?: (id: string) => void
}

export default function PaymentApprovalCard({
  payment,
  onApproved,
  onRejected,
}: PaymentApprovalCardProps) {
  const [loading, setLoading] = useState<'approve' | 'reject' | null>(null)
  const [rejectionReason, setRejectionReason] = useState('')
  const [showRejectForm, setShowRejectForm] = useState(false)

  const fullName = payment.user.profile
    ? `${payment.user.profile.firstName} ${payment.user.profile.lastName}`
    : payment.user.email

  const dateStr = new Date(payment.createdAt).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  })

  const router = useRouter()

  const handleApprove = async () => {
    setLoading('approve')
    try {
      const res = await fetch(`/api/staff/payments/${payment.id}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'approve' }),
      })
      if (!res.ok) throw new Error('Failed to approve')
      toast.success('Payment approved')
      onApproved?.(payment.id)
      router.refresh()
    } catch {
      toast.error('Failed to approve payment')
    } finally {
      setLoading(null)
    }
  }

  const handleReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Please provide a rejection reason')
      return
    }
    setLoading('reject')
    try {
      const res = await fetch(`/api/staff/payments/${payment.id}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'reject', reason: rejectionReason }),
      })
      if (!res.ok) throw new Error('Failed to reject')
      toast.success('Payment rejected')
      onRejected?.(payment.id)
      router.refresh()
    } catch {
      toast.error('Failed to reject payment')
    } finally {
      setLoading(null)
      setShowRejectForm(false)
    }
  }

  return (
    <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm transition-shadow hover:shadow-md dark:border-slate-800 dark:bg-slate-900/50">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-slate-100 px-5 py-4 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-full bg-aerojet-blue/10 dark:bg-blue-500/10">
            <User className="h-4 w-4 text-aerojet-blue dark:text-blue-400" />
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800 dark:text-white">{fullName}</p>
            <p className="text-xs text-slate-400 dark:text-slate-500">{payment.user.email}</p>
          </div>
        </div>
        <span className="rounded-full bg-amber-100 px-2.5 py-1 text-xs font-bold text-amber-700 dark:bg-amber-900/30 dark:text-amber-500">
          Pending
        </span>
      </div>

      {/* Details */}
      <div className="grid grid-cols-2 gap-3 px-5 py-4">
        <div>
          <p className="mb-0.5 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
            Amount
          </p>
          <p className="text-base font-black text-aerojet-blue dark:text-blue-400">
            {payment.currency ?? 'GHS'} {payment.amount.toFixed(2)}
          </p>
        </div>
        <div>
          <p className="mb-0.5 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
            Method
          </p>
          <p className="text-sm font-bold text-slate-700 dark:text-slate-300">
            {payment.paymentMethod.replace(/_/g, ' ')}
          </p>
        </div>
        <div>
          <p className="mb-0.5 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
            Type
          </p>
          <p className="text-sm font-bold text-slate-700 dark:text-slate-300">
            {payment.referenceType?.replace(/_/g, ' ') ?? '—'}
          </p>
        </div>
        <div>
          <p className="mb-0.5 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
            Submitted
          </p>
          <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{dateStr}</p>
        </div>
      </div>

      {/* Proof Link */}
      {payment.proofUrl && (
        <div className="px-5 pb-4">
          <a
            href={payment.proofUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-1.5 rounded-md px-1.5 py-0.5 text-xs font-bold text-aerojet-sky transition-all duration-150 ease-out hover:bg-aerojet-sky/10 hover:shadow-sm"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            View Payment Proof
          </a>
        </div>
      )}

      {/* Rejection Form */}
      {showRejectForm && (
        <div className="px-5 pb-4">
          <textarea
            value={rejectionReason}
            onChange={(e) => setRejectionReason(e.target.value)}
            placeholder="Reason for rejection..."
            rows={2}
            className="w-full resize-none rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm text-slate-900 outline-none focus:ring-2 focus:ring-red-300 dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:focus:ring-red-900/50"
          />
        </div>
      )}

      {/* Actions */}
      <div className="flex gap-2 px-5 pb-5">
        {showRejectForm ? (
          <>
            <button
              onClick={handleReject}
              disabled={loading === 'reject'}
              className="flex flex-1 items-center justify-center gap-1.5 rounded-xl bg-red-500 py-2.5 text-xs font-black text-white transition-all hover:bg-red-600 disabled:opacity-50"
            >
              {loading === 'reject' ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <XCircle className="h-3.5 w-3.5" />
              )}
              Confirm Reject
            </button>
            <button
              onClick={() => setShowRejectForm(false)}
              className="px-4 text-xs font-bold text-slate-500 dark:text-slate-400 hover:text-slate-700"
            >
              Cancel
            </button>
          </>
        ) : (
          <>
            <button
              onClick={handleApprove}
              disabled={!!loading}
              className="flex flex-1 items-center justify-center gap-1.5 rounded-xl bg-emerald-500 py-2.5 text-xs font-black text-white transition-all hover:bg-emerald-600 disabled:opacity-50"
            >
              {loading === 'approve' ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <CheckCircle2 className="h-3.5 w-3.5" />
              )}
              Approve
            </button>
            <button
              onClick={() => setShowRejectForm(true)}
              disabled={!!loading}
              className="flex flex-1 items-center justify-center gap-1.5 rounded-xl bg-red-50 py-2.5 text-xs font-black text-red-600 transition-all hover:bg-red-100 disabled:opacity-50"
            >
              <XCircle className="h-3.5 w-3.5" />
              Reject
            </button>
          </>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { format } from 'date-fns'
import { CheckSquare, Square, CheckCircle2, XCircle, ExternalLink } from 'lucide-react'
import { bulkUpdatePaymentStatus } from '../actions'
import { toast } from 'sonner'
import Link from 'next/link'
import { PaymentStatus } from '@/types/enums'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import TablePagination from './TablePagination'
import BulkActionsDropdown from './BulkActionsDropdown'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

interface PendingTopup {
  id: string
  amount: any
  currency: string
  paymentCurrency: string | null
  originalAmount: any | null
  createdAt: string | Date
  proofUrl: string | null
  user: {
    email: string
    profile: { firstName: string; lastName: string } | null
  }
}

interface PendingTopupsTableProps {
  requests: PendingTopup[]
}

export default function PendingTopupsTable({ requests }: PendingTopupsTableProps) {
  const router = useRouter()
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)

  const sortableRequests = useMemo(
    () =>
      requests.map((r) => ({
        ...r,
        _studentSort:
          r.user.profile
            ? `${r.user.profile.lastName ?? ''} ${r.user.profile.firstName ?? ''}`.toLowerCase()
            : r.user.email.toLowerCase(),
      })),
    [requests]
  )
  const { items: sortedRequests, requestSort, sortConfig } = useSort(sortableRequests)

  const total = sortedRequests.length
  const paged = sortedRequests.slice((page - 1) * perPage, page * perPage)

  const toggleAll = () => {
    if (selectedIds.length === paged.length && paged.length > 0) {
      setSelectedIds([])
    } else {
      setSelectedIds(paged.map((r) => r.id))
    }
  }

  const toggleOne = (id: string) => {
    setSelectedIds((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]))
  }

  return (
    <div className="relative">
      <div className="mb-3 flex items-center justify-end">
        <BulkActionsDropdown
          selectedIds={selectedIds}
          onClear={() => setSelectedIds([])}
          actions={[
            {
              label: 'Approve',
              icon: CheckCircle2,
              variant: 'success',
              confirmTitle: 'Approve Top-ups',
              confirmMessage: `Are you sure you want to approve ${selectedIds.length} selected top-up requests?`,
              onClick: async (ids) => {
                const res = await bulkUpdatePaymentStatus(ids, PaymentStatus.APPROVED)
                if (res.success) {
                  toast.success(`Approved ${ids.length} top-ups`)
                  router.refresh()
                } else toast.error(res.error)
              },
            },
            {
              label: 'Reject',
              icon: XCircle,
              variant: 'danger',
              confirmTitle: 'Reject Top-ups',
              confirmMessage: `Are you sure you want to reject ${selectedIds.length} selected top-up requests?`,
              onClick: async (ids) => {
                const res = await bulkUpdatePaymentStatus(ids, PaymentStatus.REJECTED)
                if (res.success) {
                  toast.success(`Rejected ${ids.length} top-ups`)
                  router.refresh()
                } else toast.error(res.error)
              },
            },
          ]}
        />
      </div>
      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <Table>
          <TableHeader className="bg-slate-50 dark:bg-slate-800/50">
            <TableRow>
              <TableHead className="w-12 px-6">
                <button
                  onClick={toggleAll}
                  className="hover:text-aerojet-blue text-slate-400 transition-colors"
                >
                  {selectedIds.length === paged.length && paged.length > 0 ? (
                    <CheckSquare className="text-aerojet-blue h-4 w-4" />
                  ) : (
                    <Square className="h-4 w-4" />
                  )}
                </button>
              </TableHead>
              <TableHead>Select</TableHead>
              <SortHeader
                label="Student"
                sortKey="_studentSort"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6"
              />
              <SortHeader
                label="Amount"
                sortKey="amount"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6"
              />
              <TableHead>Proof</TableHead>
              <SortHeader
                label="Requested"
                sortKey="createdAt"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6"
              />
            </TableRow>
          </TableHeader>
          <TableBody>
            {paged.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="h-32 text-center text-slate-500">
                  No pending top-up requests.
                </TableCell>
              </TableRow>
            ) : (
              paged.map((req) => {
                const userName = req.user.profile
                  ? `${req.user.profile.firstName} ${req.user.profile.lastName}`
                  : req.user.email

                return (
                  <TableRow
                    key={req.id}
                    className={selectedIds.includes(req.id) ? 'bg-aerojet-blue/5' : ''}
                  >
                    <TableCell className="px-6">
                      <button
                        onClick={() => toggleOne(req.id)}
                        className="hover:text-aerojet-blue text-slate-300 transition-colors"
                      >
                        {selectedIds.includes(req.id) ? (
                          <CheckSquare className="text-aerojet-blue h-4 w-4" />
                        ) : (
                          <Square className="h-4 w-4" />
                        )}
                      </button>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-900 dark:text-slate-100">
                          {userName}
                        </span>
                        <span className="text-xs text-slate-500">{req.user.email}</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-900 dark:text-slate-100">
                          {req.currency} {Number(req.amount).toFixed(2)}
                        </span>
                        {req.paymentCurrency && req.paymentCurrency !== req.currency && (
                          <span className="text-[10px] font-medium text-slate-400">
                            (Original: {req.paymentCurrency}{' '}
                            {Number(req.originalAmount || 0).toFixed(2)})
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {req.proofUrl ? (
                        <Link
                          href={req.proofUrl}
                          target="_blank"
                          className="flex items-center gap-1 text-xs font-bold text-blue-600 hover:text-blue-800 dark:text-blue-400"
                        >
                          View Receipt <ExternalLink className="h-3 w-3" />
                        </Link>
                      ) : (
                        <span className="text-xs text-slate-400">No proof</span>
                      )}
                    </TableCell>
                    <TableCell className="text-xs text-slate-500">
                      {format(new Date(req.createdAt), 'MMM d, yyyy HH:mm')}
                    </TableCell>
                  </TableRow>
                )
              })
            )}
          </TableBody>
        </Table>
        <TablePagination
          page={page}
          perPage={perPage}
          total={total}
          onPageChange={setPage}
          onPerPageChange={setPerPage}
        />
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { Users, UserCheck, GraduationCap, UserCog, ShieldCheck } from 'lucide-react'
import MotionTabs from '@/components/ui/MotionTabs'
import UsersTable from './UsersTable'
import ApplicantsQueue from './ApplicantsQueue'
import StudentsTable from './StudentsTable'
import InstructorsTable from './InstructorsTable'
import ExaminersTable from './ExaminersTable'
import type { ApplicantSummary, ApplicantCounts } from '@/lib/types/staff'

const TAB_DEFS = [
  { key: 'all', label: 'All Users', icon: Users },
  { key: 'applicants', label: 'Applicants', icon: UserCheck },
  { key: 'students', label: 'Students', icon: GraduationCap },
  { key: 'instructors', label: 'Instructors', icon: UserCog },
  { key: 'examiners', label: 'Examiners', icon: ShieldCheck },
] as const

type TabKey = (typeof TAB_DEFS)[number]['key']

interface Counts {
  total: number
  applicantAll: number
  applicantPendingPayment: number
  applicantPendingApproval: number
  studentAll: number
  studentActive: number
  studentSuspended: number
  studentArchived: number
  examinerAll: number
}

const DEFAULT_COUNTS: Counts = {
  total: 0,
  applicantAll: 0,
  applicantPendingPayment: 0,
  applicantPendingApproval: 0,
  studentAll: 0,
  studentActive: 0,
  studentSuspended: 0,
  studentArchived: 0,
  examinerAll: 0,
}

interface PeopleTabsProps {
  initialTab?: string
}

export default function PeopleTabs({
  initialTab,
  initialApplicants,
  initialTotal,
  initialApplicantCounts,
}: {
  initialTab?: string
  initialApplicants?: ApplicantSummary[]
  initialTotal?: number
  initialApplicantCounts?: ApplicantCounts
}) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const currentTab = (searchParams.get('tab') as TabKey) || initialTab || 'all'
  const [counts, setCounts] = useState<Counts>(DEFAULT_COUNTS)

  useEffect(() => {
    fetch('/api/staff/users/counts')
      .then((res) => res.json())
      .then((data) => {
        if (data.success && data.data) setCounts(data.data)
      })
      .catch(() => {})
  }, [])

  const tabs = TAB_DEFS.map((t) => ({
    ...t,
    badge:
      t.key === 'applicants'
        ? counts.applicantAll
        : t.key === 'examiners'
          ? counts.examinerAll
          : undefined,
  }))

  const applicantCounts = {
    all: counts.applicantAll,
    pending_payment: counts.applicantPendingPayment,
    pending_approval: counts.applicantPendingApproval,
  }

  const studentCounts = {
    all: counts.studentAll,
    active: counts.studentActive,
    suspended: counts.studentSuspended,
    archived: counts.studentArchived,
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-aerojet-blue text-2xl font-black tracking-tight uppercase dark:text-white">
          People
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Manage all users, applicants, students, and instructors
        </p>
      </div>

      <MotionTabs
        tabs={tabs}
        activeTab={currentTab}
        onChange={(tab) => router.push(`/staff/users?tab=${tab}`, { scroll: false })}
        layoutId="people-tab"
        ariaLabel="People management"
      />

      <div>
        {currentTab === 'all' && <UsersTable initialTotal={counts.total} />}
        {currentTab === 'applicants' && (
          <ApplicantsQueue
            initialCounts={
              initialApplicantCounts ?? { all: 0, pending_payment: 0, pending_approval: 0 }
            }
          />
        )}
        {currentTab === 'students' && <StudentsTable initialCounts={studentCounts} />}
        {currentTab === 'instructors' && <InstructorsTable />}
        {currentTab === 'examiners' && <ExaminersTable />}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import {
  BarChart3,
  TrendingUp,
  Users,
  CheckCircle2,
  XCircle,
  ArrowRight,
  Loader2,
} from 'lucide-react'

interface FunnelStage {
  stage: string
  label: string
  count: number
  percent: number
}

interface PipelineData {
  total: number
  funnel: FunnelStage[]
  programmeBreakdown: { programme: string; count: number }[]
  outcomes: { enrolled: number; rejected: number; withdrawn: number; conversionRate: number }
  recentActivity: { newApplications: number; newEnrollments: number }
  cycles: { id: string; name: string }[]
}

const STAGE_COLORS: Record<string, string> = {
  REGISTERED: 'bg-slate-400',
  PAYMENT_PENDING: 'bg-amber-400',
  PAYMENT_VERIFIED: 'bg-blue-400',
  APTITUDE_PENDING: 'bg-purple-400',
  APTITUDE_COMPLETED: 'bg-purple-500',
  SHORTLISTED: 'bg-indigo-500',
  INTERVIEW_SCHEDULED: 'bg-cyan-500',
  INTERVIEW_COMPLETED: 'bg-cyan-600',
  SELECTED: 'bg-emerald-400',
  MEDICAL_PENDING: 'bg-rose-400',
  MEDICAL_SUBMITTED: 'bg-rose-500',
  MEDICAL_CLEARED: 'bg-green-500',
  ENROLLED: 'bg-green-600',
  REJECTED: 'bg-red-500',
  WITHDRAWN: 'bg-slate-500',
}

export default function PipelineAnalytics() {
  const [data, setData] = useState<PipelineData | null>(null)
  const [loading, setLoading] = useState(true)
  const [cycleId, setCycleId] = useState('')

  const fetch_ = useCallback(async () => {
    setLoading(true)
    try {
      const params = cycleId ? `?intakeCycleId=${cycleId}` : ''
      const res = await fetch(`/api/staff/admissions/pipeline${params}`)
      const json = await res.json()
      if (json.data) setData(json.data)
    } catch { /* silent */ } finally { setLoading(false) }
  }, [cycleId])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetch_() }, [fetch_])

  if (loading || !data) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  const maxCount = Math.max(1, ...data.funnel.map(s => s.count))

  return (
    <div className="space-y-6">
      {/* Header + Cycle Filter */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-indigo-100 dark:bg-indigo-900/30">
            <BarChart3 className="h-5 w-5 text-indigo-600 dark:text-indigo-400" />
          </div>
          <div>
            <h3 className="text-sm font-black uppercase tracking-wider text-slate-800 dark:text-white">Admissions Pipeline</h3>
            <p className="text-[11px] text-slate-400">{data.total} total applications</p>
          </div>
        </div>
        {data.cycles.length > 0 && (
          <select
            value={cycleId}
            onChange={e => setCycleId(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium dark:border-slate-700 dark:bg-slate-800"
          >
            <option value="">All Intakes</option>
            {data.cycles.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        )}
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <div className="rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-800 dark:bg-slate-900">
          <p className="text-xs font-bold text-slate-400">Total</p>
          <p className="text-xl font-black text-slate-900 dark:text-white">{data.total}</p>
        </div>
        <div className="rounded-xl border border-green-200 bg-green-50 p-3 dark:border-green-800/50 dark:bg-green-900/10">
          <p className="text-xs font-bold text-green-600">Enrolled</p>
          <p className="text-xl font-black text-green-800 dark:text-green-200">{data.outcomes.enrolled}</p>
        </div>
        <div className="rounded-xl border border-red-200 bg-red-50 p-3 dark:border-red-800/50 dark:bg-red-900/10">
          <p className="text-xs font-bold text-red-600">Rejected</p>
          <p className="text-xl font-black text-red-800 dark:text-red-200">{data.outcomes.rejected}</p>
        </div>
        <div className="rounded-xl border border-indigo-200 bg-indigo-50 p-3 dark:border-indigo-800/50 dark:bg-indigo-900/10">
          <p className="text-xs font-bold text-indigo-600">Conversion</p>
          <p className="text-xl font-black text-indigo-800 dark:text-indigo-200">{data.outcomes.conversionRate}%</p>
        </div>
      </div>

      {/* Funnel Bars */}
      <div className="rounded-xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900">
        <h4 className="mb-4 text-xs font-bold uppercase tracking-widest text-slate-400">Stage Distribution</h4>
        <div className="space-y-2">
          {data.funnel.filter(s => s.count > 0).map(stage => (
            <div key={stage.stage} className="flex items-center gap-3">
              <span className="w-36 truncate text-xs font-medium text-slate-600 dark:text-slate-400">{stage.label}</span>
              <div className="relative h-6 flex-1 rounded-full bg-slate-100 dark:bg-slate-800">
                <div
                  className={`h-full rounded-full transition-all ${STAGE_COLORS[stage.stage] || 'bg-slate-400'}`}
                  style={{ width: `${Math.max(2, (stage.count / maxCount) * 100)}%` }}
                />
                <span className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-bold text-slate-600 dark:text-slate-300">
                  {stage.count}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Programme Breakdown */}
      {data.programmeBreakdown.length > 0 && (
        <div className="rounded-xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900">
          <h4 className="mb-3 text-xs font-bold uppercase tracking-widest text-slate-400">By Programme</h4>
          <div className="flex flex-wrap gap-3">
            {data.programmeBreakdown.map(p => (
              <div key={p.programme} className="rounded-lg bg-slate-50 px-4 py-2 dark:bg-slate-800">
                <p className="text-sm font-bold text-slate-900 dark:text-white">{p.count}</p>
                <p className="text-[10px] font-medium text-slate-500">{p.programme || 'Unset'}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Recent Activity */}
      <div className="flex gap-3">
        <div className="flex-1 rounded-xl border border-blue-200 bg-blue-50 p-3 dark:border-blue-800/50 dark:bg-blue-900/10">
          <p className="text-xs font-bold text-blue-600">New Apps (7d)</p>
          <p className="text-lg font-black text-blue-800 dark:text-blue-200">{data.recentActivity.newApplications}</p>
        </div>
        <div className="flex-1 rounded-xl border border-green-200 bg-green-50 p-3 dark:border-green-800/50 dark:bg-green-900/10">
          <p className="text-xs font-bold text-green-600">Enrolled (7d)</p>
          <p className="text-lg font-black text-green-800 dark:text-green-200">{data.recentActivity.newEnrollments}</p>
        </div>
      </div>
    </div>
  )
}

'use client'

import { Users, Calendar, ArrowRight } from 'lucide-react'
import Link from 'next/link'
import { format } from 'date-fns'

interface PoolSummary {
