'use client'

import { useState, useEffect, useCallback, useMemo } from 'react'
import {
  CheckCircle2,
  RefreshCw,
  Search,
  FileCheck,
  Calendar,
  User,
  ExternalLink,
  ChevronDown,
  Loader2,
  AlertCircle,
} from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { toast } from 'sonner'
import { format } from 'date-fns'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

interface Payment {
  id: string
  amount: number
  currency: string
  paymentCurrency?: string | null
  originalAmount?: number | null
  paymentMethod: string
  referenceType: string
  referenceCode: string | null
  proofUrl: string | null
  createdAt: string
  approvedAt: string | null
  user: {
    email: string
    profile?: { firstName: string; lastName: string } | null
  }
}

export default function ReconciliationQueue() {
  const [payments, setPayments] = useState<Payment[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [isProcessing, setIsProcessing] = useState(false)

  const fetchPayments = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/staff/finance/reconcile/pending')
      if (!res.ok) throw new Error()
      const data = await res.json()
      // Fix: access data.data.payments because of apiSuccess envelope
      setPayments(data.data?.payments || [])
    } catch {
      toast.error('Failed to load pending payments')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchPayments()
  }, [fetchPayments])

  const handleReconcile = async () => {
    if (selectedIds.length === 0) return

    setIsProcessing(true)
    try {
      const res = await fetch('/api/staff/finance/reconcile', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ paymentIds: selectedIds }),
      })

      if (!res.ok) throw new Error()

      const data = await res.json()
      // Fix: access data.data.message
      toast.success(data.data?.message || 'Reconciled successfully')
      setPayments((prev) => prev.filter((p) => !selectedIds.includes(p.id)))
      setSelectedIds([])
    } catch {
      toast.error('Reconciliation failed')
    } finally {
      setIsProcessing(false)
    }
  }

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]))
  }

  const toggleAll = () => {
    setSelectedIds((prev) =>
      prev.length === sortedPayments.length ? [] : sortedPayments.map((p) => p.id)
    )
  }

  const filteredPayments = useMemo(() => {
    return payments
      .map((p) => ({
        ...p,
        _studentSort: p.user.profile
          ? `${p.user.profile.firstName} ${p.user.profile.lastName}`.toLowerCase()
          : '',
        _amount: Number(p.originalAmount ?? p.amount),
        _approvalDate: p.approvedAt ? new Date(p.approvedAt).getTime() : 0,
      }))
      .filter((p) => {
        const searchLow = search.toLowerCase()
        const name = p.user.profile ? `${p.user.profile.firstName} ${p.user.profile.lastName}` : ''
        return (
          p.user.email.toLowerCase().includes(searchLow) ||
          name.toLowerCase().includes(searchLow) ||
          p.referenceCode?.toLowerCase().includes(searchLow)
        )
      })
  }, [payments, search])

  const { items: sortedPayments, requestSort, sortConfig } = useSort(filteredPayments)

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-aerojet-blue text-2xl font-black tracking-tight uppercase dark:text-white">
            Finance Reconciliation
          </h1>
          <p className="mt-1 text-sm text-slate-500">
            Verify approved payments against bank statements.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={fetchPayments}
            className="flex h-10 w-10 items-center justify-center rounded-xl border border-slate-200 bg-white text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-800 dark:bg-slate-900 dark:hover:border-slate-600"
          >
            <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
          </button>

          <button
            onClick={handleReconcile}
            disabled={selectedIds.length === 0 || isProcessing}
            className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-2.5 text-xs font-black tracking-widest text-white uppercase transition-all hover:bg-blue-700 disabled:opacity-50"
          >
            {isProcessing ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <FileCheck className="h-4 w-4" />
            )}
            Reconcile {selectedIds.length > 0 && `(${selectedIds.length})`}
          </button>
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex border-b border-slate-100 p-4 dark:border-slate-800">
          <div className="relative flex-1">
            <label htmlFor="reconcile-search" className="sr-only">
              Search by user, email, or reference
            </label>
            <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              id="reconcile-search"
              name="reconcile-search"
              type="text"
              placeholder="Search user, email or reference..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              autoComplete="off"
              className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pr-4 pl-10 text-xs outline-none focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-800/50">
                <th className="w-12 px-6 py-4">
                  <label htmlFor="select-all-reconcile" className="sr-only">
                    Select all for reconciliation
                  </label>
                  <input
                    id="select-all-reconcile"
                    name="select-all-reconcile"
                    type="checkbox"
                    checked={
                      selectedIds.length === sortedPayments.length && sortedPayments.length > 0
                    }
                    onChange={toggleAll}
                    className="h-4 w-4 rounded border-slate-300 transition-all checked:bg-blue-600"
                  />
                </th>
                <SortHeader label="Student" sortKey="_studentSort" currentSort={sortConfig} onSort={requestSort} className="px-6 py-4 text-[10px] font-black tracking-widest text-slate-400 uppercase" />
                <SortHeader label="Payment Details" sortKey="_amount" currentSort={sortConfig} onSort={requestSort} align="right" className="px-6 py-4 text-[10px] font-black tracking-widest text-slate-400 uppercase" />
                <SortHeader label="Approval" sortKey="_approvalDate" currentSort={sortConfig} onSort={requestSort} className="px-6 py-4 text-[10px] font-black tracking-widest text-slate-400 uppercase" />
                <th className="px-6 py-4 text-right text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Action
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td colSpan={5} className="px-6 py-8">
                      <div className="h-4 w-full rounded bg-slate-100 dark:bg-slate-800" />
                    </td>
                  </tr>
                ))
              ) : sortedPayments.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-20 text-center">
                    <AlertCircle className="mx-auto mb-4 h-12 w-12 text-slate-200" />
                    <p className="text-sm font-bold text-slate-400">
                      No payments awaiting reconciliation
                    </p>
                  </td>
                </tr>
              ) : (
                sortedPayments.map((p) => (
                  <tr
                    key={p.id}
                    className="group transition-all duration-150 ease-out hover:bg-white/80 hover:shadow-[0_1px_4px_rgba(0,0,0,0.06)] dark:hover:bg-slate-800/40"
                  >
                    <td className="px-6 py-5">
                      <label htmlFor={`select-payment-${p.id}`} className="sr-only">
                        Select payment for reconciliation
                      </label>
                      <input
                        id={`select-payment-${p.id}`}
                        name={`select-payment-${p.id}`}
                        type="checkbox"
                        checked={selectedIds.includes(p.id)}
                        onChange={() => toggleSelect(p.id)}
                        className="h-4 w-4 rounded border-slate-300 transition-all checked:bg-blue-600"
                      />
                    </td>
                    <td className="px-6 py-5 text-sm">
                      <div className="font-bold text-slate-900 dark:text-slate-100">
                        {p.user.profile
                          ? `${p.user.profile.firstName} ${p.user.profile.lastName}`
                          : 'System User'}
                      </div>
                      <div className="text-xs text-slate-500">{p.user.email}</div>
                    </td>
                    <td className="px-6 py-5">
                      <div className="text-aerojet-blue text-sm font-black dark:text-blue-400">
                        {p.paymentCurrency || p.currency} {Number(p.originalAmount ?? p.amount).toFixed(2)}
                      </div>
                      {(p.paymentCurrency || p.currency) !== 'EUR' && (
                        <div className="text-[10px] font-medium text-slate-400">
                          (Converted: EUR {Number(p.amount).toFixed(2)})
                        </div>
                      )}
                      <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase">
                        <span>{p.paymentMethod.replace(/_/g, ' ')}</span>
                        <span className="h-1 w-1 rounded-full bg-slate-200" />
                        <span className="font-mono">{p.referenceCode || 'No Ref'}</span>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-2 text-xs font-bold text-slate-600 dark:text-slate-400">
                        <Calendar className="h-3 w-3" />
                        {p.approvedAt ? format(new Date(p.approvedAt), 'MMM d, yyyy') : 'â€”'}
                      </div>
                      {p.proofUrl && (
                        <a
                          href={p.proofUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="mt-1 flex items-center gap-1 text-[10px] font-black tracking-widest text-aerojet-sky uppercase hover:underline dark:text-blue-400"
                        >
                          <ExternalLink className="h-3 w-3" /> View Proof
                        </a>
                      )}
                    </td>
                    <td className="px-6 py-5 text-right">
                      <button
                        onClick={() => toggleSelect(p.id)}
                        className={`rounded-xl px-4 py-2 text-[10px] font-black tracking-widest uppercase transition-all ${
                          selectedIds.includes(p.id)
                            ? 'bg-blue-600 text-white'
                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-400'
                        }`}
                      >
                        {selectedIds.includes(p.id) ? 'Selected' : 'Reconcile'}
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  DollarSign,
  TrendingUp,
  Calendar,
  Clock,
  CheckCircle,
  XCircle,
  AlertCircle,
  Loader2,
  Download,
  FileText,
  ChevronLeft,
  ChevronRight,
  BarChart3,
  PieChart,
  CreditCard,
  Target,
  ShieldAlert,
  Percent,
} from 'lucide-react'
import { formatCurrency } from '@/lib/currency'
import { generateFinancialPDF } from '@/lib/analytics/pdf-export'
import type {
  MonthlyRevenueItem,
  RevenueByProgrammeItem,
  PaymentStatusBreakdownItem,
  PaymentMethodBreakdownItem,
} from '@/lib/types/staff'

interface ReportsPanelProps {
  initialData: {
    summary: any
    revenueByType: any[]
    paymentMethods: any[]
    monthlyData: any[]
    paymentStatus: any[]
  }
}

const MONTH_NAMES = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
]

const STATUS_ICON: Record<
  string,
  { icon: typeof CheckCircle; color: string; bg: string; bar: string }
> = {
  APPROVED: {
    icon: CheckCircle,
    color: 'text-emerald-600',
    bg: 'bg-emerald-50 dark:bg-emerald-900/20',
    bar: 'bg-emerald-500',
  },
  COMPLETED: {
    icon: CheckCircle,
    color: 'text-emerald-600',
    bg: 'bg-emerald-50 dark:bg-emerald-900/20',
    bar: 'bg-emerald-500',
  },
  PENDING: {
    icon: Clock,
    color: 'text-amber-600',
    bg: 'bg-amber-50 dark:bg-amber-900/20',
    bar: 'bg-amber-500',
  },
  REJECTED: {
    icon: XCircle,
    color: 'text-red-600',
    bg: 'bg-red-50 dark:bg-red-900/20',
    bar: 'bg-red-500',
  },
  FAILED: {
    icon: XCircle,
    color: 'text-red-600',
    bg: 'bg-red-50 dark:bg-red-900/20',
    bar: 'bg-red-500',
  },
  PROCESSING: {
    icon: AlertCircle,
    color: 'text-blue-600',
    bg: 'bg-blue-50 dark:bg-blue-900/20',
    bar: 'bg-blue-500',
  },
}

export default function ReportsPanel({ initialData }: ReportsPanelProps) {
  const now = new Date()
  const [year, setYear] = useState(now.getFullYear())
  const [month, setMonth] = useState(now.getMonth() + 1)
  const [data, setData] = useState(initialData)
  const [loading, setLoading] = useState(false)

  const fetchData = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/finance/reports?year=${year}&month=${month}`)
      const json = await res.json()
      setData(json)
    } finally {
      setLoading(false)
    }
  }, [year, month])

  const isInitialYear = year === now.getFullYear()
  const isInitialMonth = month === now.getMonth() + 1
  useEffect(() => {
    if (!isInitialYear || !isInitialMonth) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchData()
    }
  }, [year, month, fetchData, isInitialYear, isInitialMonth])

  const { summary, revenueByType, paymentMethods, monthlyData, paymentStatus } = data
  const maxMonthlyRevenue = Math.max(...monthlyData.map((m: MonthlyRevenueItem) => m.revenue), 1)
  const successRate =
    summary.totalCount + summary.rejectedCount > 0
      ? Math.round((summary.totalCount / (summary.totalCount + summary.rejectedCount)) * 100)
      : 0

  const handleExportCSV = () => {
    window.open(`/api/staff/export?type=finances`, '_blank')
  }

  return (
    <div className="space-y-6">
      {/* â”€â”€ Period Selector & Actions â”€â”€ */}
      <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-100 bg-white px-6 py-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-3">
          <div className="bg-aerojet-blue/10 dark:bg-aerojet-sky/10 flex h-9 w-9 items-center justify-center rounded-xl">
            <Calendar className="text-aerojet-blue dark:text-aerojet-sky h-4 w-4" />
          </div>
          <div>
            <p className="text-xs font-bold tracking-wider text-slate-400 uppercase">
              Reporting Period
            </p>
            <p className="text-sm font-black text-slate-800 dark:text-slate-200">
              {MONTH_NAMES[month - 1]} {year}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 rounded-xl border border-slate-200 bg-slate-50 px-1 py-1 dark:border-slate-700 dark:bg-slate-800">
            <button
              onClick={() => setYear((y) => y - 1)}
              className="rounded-lg p-1.5 text-slate-500 transition-colors hover:bg-white hover:text-slate-900 dark:hover:bg-slate-700 dark:hover:text-slate-100"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <span className="min-w-[56px] px-2 text-center text-sm font-black text-slate-900 dark:text-slate-100">
              {year}
            </span>
            <button
              onClick={() => setYear((y) => y + 1)}
              disabled={year >= now.getFullYear()}
              className="rounded-lg p-1.5 text-slate-500 transition-colors hover:bg-white hover:text-slate-900 disabled:cursor-not-allowed disabled:opacity-30 dark:hover:bg-slate-700 dark:hover:text-slate-100"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>

          <select
            value={month}
            onChange={(e) => setMonth(parseInt(e.target.value))}
            className="focus:border-aerojet-blue rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm font-semibold text-slate-900 transition-colors outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
          >
            {MONTH_NAMES.map((name, i) => (
              <option key={i + 1} value={i + 1}>
                {name}
              </option>
            ))}
          </select>

          <button
            onClick={() => {
              setYear(now.getFullYear())
