const STATUS_FILTERS = [
  { key: 'all', label: 'All Students' },
  { key: 'active', label: 'Active' },
  { key: 'suspended', label: 'Suspended' },
  { key: 'archived', label: 'Archived' },
]

const STATUS_STYLE: Record<string, string> = {
  ACTIVE: 'bg-emerald-100 text-emerald-700',
  SUSPENDED: 'bg-amber-100 text-amber-700',
  ARCHIVED: 'bg-slate-100 text-slate-500',
  PENDING: 'bg-blue-100 text-blue-700',
}

export default function StudentsTable({
  initialCounts,
}: {
  initialCounts: Record<string, number>
}) {
  const [students, setStudents] = useState<Student[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState('all')
  const [search, setSearch] = useState('')
  const [selected, setSelected] = useState<Student | null>(null)
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)
  const [viewCurrency, setViewCurrency] = useState('EUR')

  // paged is now the raw students array since the server handles slicing
  const paged = students

  const fetchStudents = useCallback(async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        status: filter,
        search,
        page: page.toString(),
        limit: perPage.toString(),
      })
      const res = await fetch(`/api/staff/students?${params}`)
      const data = await res.json()
      
      if (data.success) {
        setStudents(data.data ?? [])
        setTotal(data.meta?.total ?? 0)
      } else {
        setStudents([])
        setTotal(0)
      }
    } finally {
      setLoading(false)
    }
  }, [filter, search, page, perPage])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setPage(1)
  }, [filter, search])

  useEffect(() => {
    const t = setTimeout(fetchStudents, search ? 350 : 0)
    return () => clearTimeout(t)
  }, [fetchStudents, search])

  // Keep selected in sync after refresh
  const handleActionComplete = () => {
    fetchStudents()
    setSelected(null)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-slate-400">
            {initialCounts.all ?? total} registered students
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={fetchStudents}
            className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 dark:hover:border-slate-600"
          >
            <RefreshCw className="h-3.5 w-3.5" />
          </button>

          <Link
            href="/staff/students/import"
            className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 dark:hover:border-slate-600"
          >
            <Users className="h-3.5 w-3.5 text-blue-600" />
            Import Students
          </Link>

          <CurrencyToggle value={viewCurrency} onChange={setViewCurrency} size="sm" />

          <BulkActionsDropdown
            selectedIds={selectedIds}
            onClear={() => setSelectedIds([])}
            actions={[
              {
                label: 'Activate',
                icon: CheckCircle2,
                variant: 'success',
                confirmTitle: 'Activate Students',
                confirmMessage: `Are you sure you want to activate ${selectedIds.length} selected students?`,
                onClick: async (ids) => {
                  const res = await bulkUpdateUserStatus(ids, 'ACTIVE')
                  if (res.success) {
                    toast.success(`Activated ${ids.length} students`)
                    fetchStudents()
                  } else toast.error(res.error)
                },
              },
              {
                label: 'Suspend',
                icon: AlertTriangle,
                variant: 'warning',
                confirmTitle: 'Suspend Students',
                confirmMessage: `Are you sure you want to suspend ${selectedIds.length} selected students?`,
                onClick: async (ids) => {
                  const res = await bulkUpdateUserStatus(ids, 'SUSPENDED')
                  if (res.success) {
                    toast.success(`Suspended ${ids.length} students`)
                    fetchStudents()
                  } else toast.error(res.error)
                },
              },
              {
                label: 'Send Credentials',
                icon: Mail,
                variant: 'primary',
                confirmTitle: 'Send Login Credentials',
                confirmMessage: `This will generate new temporary passwords and email login credentials to ${selectedIds.length} selected students.`,
                onClick: async (ids) => {
                  try {
                    const res = await fetch('/api/admin/bulk-send-credentials', {
                      method: 'POST',
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify({ users: ids.map((id) => ({ userId: id })) }),
                    })
                    const data = await res.json()
                    if (!res.ok) throw new Error(data.error || 'Failed')
                    toast.success(`Credentials sent to ${data.data.summary.sent} students`)
                    fetchStudents()
                  } catch (err: any) {
                    toast.error(err.message || 'Failed')
                  }
                },
              },
              students.filter((s) => selectedIds.includes(s.id)).length > 0 &&
              students
                .filter((s) => selectedIds.includes(s.id))
                .every((s) => s.status === 'ARCHIVED')
                ? {
                    label: 'Permanently Delete',
                    icon: Trash2,
                    variant: 'danger',
                    confirmTitle: 'Permanently Delete Students',
                    confirmMessage: `Are you sure you want to permanently delete ${selectedIds.length} students? This cannot be undone.`,
                    onClick: async (ids) => {
                      const res = await bulkDeleteUsers(ids)
                      if (res.success) {
                        toast.success(`Permanently deleted ${ids.length} students`)
                        fetchStudents()
                      } else toast.error(res.error)
                    },
                  }
                : {
                    label: 'Archive',
                    icon: Archive,
                    variant: 'warning',
                    confirmTitle: 'Archive Students',
                    confirmMessage: `Are you sure you want to archive ${selectedIds.length} students?`,
                    onClick: async (ids) => {
                      const res = await bulkArchiveUsers(ids)
                      if (res.success) {
                        toast.success(`Archived ${ids.length} students`)
                        fetchStudents()
                      } else toast.error(res.error)
                    },
                  },
              {
                label: 'Bypass PW Change',
                icon: LockOpen,
                variant: 'primary',
                confirmTitle: 'Bypass Password Change',
                confirmMessage: `Are you sure you want to bypass the required password change for ${selectedIds.length} selected students?`,
                onClick: async (ids) => {
                  const res = await bulkBypassPasswordChange(ids)
                  if (res.success) {
                    toast.success(`Bypassed password change for ${ids.length} students`)
                    fetchStudents()
                  } else toast.error(res.error)
                },
              },
              {
                label: 'Send Email',
                icon: Mail,
                variant: 'default',
                onClick: async (ids) => {
                  const selectedEmails = students
                    .filter((s) => ids.includes(s.id))
                    .map((s) => s.email)
                    .filter(Boolean)
                  if (selectedEmails.length > 0) {
                    window.location.href = `mailto:${selectedEmails.join(',')}`
                  }
                },
              },
            ]}
          />
        </div>
      </div>

      {/* Split Panel */}
      <div
        className="flex h-[calc(100vh-300px)] min-h-[500px] overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900"
      >
        {/* Left: List */}
        <div className="flex w-full shrink-0 flex-col border-r border-slate-100 lg:w-[380px] xl:w-[420px] dark:border-slate-800">
          {/* Search + Filters */}
          <div className="space-y-3 border-b border-slate-100 p-4 dark:border-slate-800">
            <div className="relative">
              <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <input
                id="students-search"
                name="students-search"
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search name, ID, email..."
                className="focus:ring-aerojet-sky w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pr-4 pl-9 text-sm outline-none focus:ring-2 dark:border-slate-700 dark:bg-slate-800/50"
                autoComplete="off"
              />
            </div>
            <div
              className="flex items-center gap-1.5 overflow-x-auto pb-0.5"
              style={{ scrollbarWidth: 'none' }}
            >
              <button
                onClick={() => {
                  if (selectedIds.length === paged.length && paged.length > 0) {
                    setSelectedIds([])
                  } else {
                    setSelectedIds(paged.map((s) => s.id))
                  }
                }}
                className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full border transition-all ${
                  selectedIds.length === paged.length && paged.length > 0
                    ? 'border-aerojet-blue bg-aerojet-blue text-white'
                    : 'border-slate-200 bg-white text-slate-400 hover:border-slate-300'
                }`}
                title="Select All"
                aria-label="Select all students"
              >
                <CheckSquare className="h-3.5 w-3.5" />
              </button>
              {STATUS_FILTERS.map((f) => {
                const count =
                  f.key === 'all'
                    ? initialCounts.all
                    : initialCounts[f.key]
                return (
                  <button
                    key={f.key}
                    onClick={() => setFilter(f.key)}
                    className={`rounded-full border px-3 py-1 text-xs font-bold whitespace-nowrap transition-all ${
                      filter === f.key
                        ? 'border-aerojet-blue bg-aerojet-blue text-white'
                        : 'border-slate-200 bg-white text-slate-500 hover:border-slate-300'
                    }`}
                  >
                    {f.label}
                    {count !== undefined && (
                      <span className="ml-1 opacity-70">({count})</span>
                    )}
                  </button>
                )
              })}
            </div>
          </div>

          {/* Student Cards */}
          <div
            className="flex-1 overflow-y-auto py-2"
            style={{ scrollbarWidth: 'thin', scrollbarColor: 'rgba(0,0,0,0.06) transparent' }}
          >
            {loading ? (
              Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="animate-pulse p-4">
                  <div className="flex items-center gap-3">
                    <div className="h-4 w-4 rounded bg-slate-100" />
                    <div className="h-10 w-10 rounded-full bg-slate-100" />
                    <div className="flex-1 space-y-2">
                      <div className="h-3 w-2/3 rounded bg-slate-100" />
                      <div className="h-2.5 w-1/2 rounded bg-slate-100" />
                    </div>
                  </div>
                </div>
              ))
            ) : students.length === 0 ? (
              <div className="flex flex-col items-center justify-center px-4 py-16 text-center">
                <GraduationCap className="mb-2 h-10 w-10 text-slate-200" />
                <p className="text-sm font-bold text-slate-400">No students found</p>
              </div>
            ) : (
              paged.map((student) => {
                const fullName = student.profile
                  ? [
                      student.profile.firstName,
                      student.profile.middleName,
                      student.profile.lastName,
                    ]
                      .filter(Boolean)
                      .join(' ')
                  : student.email
                const initials = student.profile
                  ? `${student.profile.firstName[0]}${student.profile.lastName[0]}`
                  : student.email[0].toUpperCase()
                const isSelected = selected?.id === student.id
                const walletBal = Number(student.wallet?.availableBalance ?? 0)
                const statusStyle = STATUS_STYLE[student.status] ?? 'bg-slate-100 text-slate-500'

                return (
                  <div
                    key={student.id}
                    onClick={() => setSelected(student)}
                    className={`group relative mx-2 my-1 cursor-pointer rounded-xl border p-4 transition-all duration-150 ease-out ${
                      isSelected
                        ? 'border-aerojet-blue/30 bg-aerojet-blue/5 shadow-sm ring-1 ring-aerojet-blue/20'
                        : selectedIds.includes(student.id)
                          ? 'border-aerojet-blue/20 bg-aerojet-blue/5'
                          : 'border-slate-100 bg-white hover:border-slate-200 hover:bg-accent hover:shadow-sm dark:border-slate-800 dark:bg-slate-900 dark:hover:border-slate-700 dark:hover:bg-accent'
                    }`}
                  >
                    <div className="mb-2 flex items-start justify-between">
                      <div className="flex items-center gap-3">
                        <button
                          onClick={(e) => {
                            e.stopPropagation()
                            setSelectedIds((prev) =>
                              prev.includes(student.id)
                                ? prev.filter((id) => id !== student.id)
                                : [...prev, student.id]
                            )
                          }}
                          className={`flex h-5 w-5 shrink-0 items-center justify-center rounded transition-all ${
                            selectedIds.includes(student.id)
                              ? 'text-aerojet-blue'
                              : 'hover:text-aerojet-blue text-slate-300 opacity-0 group-hover:opacity-100'
                          }`}
                          aria-label={`Select ${fullName}`}
                        >
                          {selectedIds.includes(student.id) ? (
                            <CheckSquare className="h-4 w-4" />
                          ) : (
                            <Square className="h-4 w-4" />
                          )}
                        </button>

                        <div className="bg-aerojet-blue/10 text-aerojet-blue relative flex h-10 w-10 shrink-0 items-center justify-center overflow-hidden rounded-full text-xs font-black">
                          {student.profile?.profilePhotoUrl ? (
                            <img
                              src={student.profile.profilePhotoUrl}
                              alt={fullName}
                              className="h-full w-full object-cover"
                            />
                          ) : (
                            initials
                          )}
                        </div>
                        <div className="flex-1">
                          <p className="text-sm font-bold text-slate-800 group-hover:text-aerojet-blue dark:text-slate-200 transition-colors duration-150">
                            {fullName}
                          </p>
                          <p className="font-mono text-xs text-slate-400">
                            {student.studentProfile?.studentId ?? 'â€”'}
                          </p>
                        </div>
                      </div>
                      <span className={`rounded-full px-2 py-0.5 text-[10px] font-black uppercase ${statusStyle}`}>
                        {student.status}
                      </span>
                    </div>
                    <div
                      className="mt-1 flex items-center justify-between text-xs"
                      style={{ marginLeft: '52px' }}
                    >
                      <span className="text-slate-400">
                        {student.studentProfile?.cohort ?? 'No cohort'}
                      </span>
                      <CurrencyDisplay
                        amount={walletBal}
                        baseCurrency={student.wallet?.currency || 'EUR'}
                        currency={viewCurrency}
                        showToggle={false}
                        clickToToggle={true}
                        onCurrencyChange={setViewCurrency}
                        size="sm"
                        amountClassName={`${walletBal >= 0 ? 'text-emerald-600!' : 'text-red-500!'}`}
                      />
                    </div>
                  </div>
                )
              })
            )}
          </div>

          {/* Footer */}
          {total > 0 && (
            <TablePagination
              page={page}
              perPage={perPage}
              total={total}
              onPageChange={setPage}
              onPerPageChange={setPerPage}
            />
          )}
        </div>

        {/* Right: Detail Panel */}
        <StudentDetailPanel
          student={selected}
          viewCurrency={viewCurrency}
          onCurrencyChange={setViewCurrency}
          onClose={() => setSelected(null)}
          onActionComplete={handleActionComplete}
        />
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { format } from 'date-fns'
import { Loader2 } from 'lucide-react'
import TablePagination from './TablePagination'
import { Badge } from '@/components/ui/badge'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { SortableTh } from '@/components/ui/sortable-th'
import SearchInput from '@/components/SearchInput'
import { SerializedTransactionRow, SerializedTransactionRelated } from '@/lib/types/staff'

interface TransactionsTableProps {
  currencySymbol: string
  initialData: any[]
  initialTotal: number
  initialRelated: any
  query?: string
}

export default function TransactionsTable({
  currencySymbol,
  initialData,
  initialTotal,
  initialRelated,
  query: initialQuery,
}: TransactionsTableProps) {
  const [data, setData] = useState<any[]>(initialData)
  const [total, setTotal] = useState(initialTotal)
  const [related, setRelated] = useState(initialRelated)
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)
  const [loading, setLoading] = useState(false)
  const searchParams = useSearchParams()
  const sortBy = searchParams.get('sort') ?? 'createdAt'
  const sortDir = (searchParams.get('order') ?? 'desc') as 'asc' | 'desc'

  const symbol = currencySymbol

  const fetchData = useCallback(async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: perPage.toString(),
        sortBy,
        sortDir,
        ...(initialQuery ? { query: initialQuery } : {}),
      })
      const res = await fetch(`/api/staff/finance/transactions?${params}`)
      const json = await res.json()
      setData(json.data ?? [])
      setTotal(json.meta?.total ?? 0)
      setRelated(json.related ?? {})
    } finally {
      setLoading(false)
    }
  }, [page, perPage, sortBy, sortDir, initialQuery])

  useEffect(() => {
    const isInitial = page === 1 && perPage === 25 && sortBy === 'createdAt' && sortDir === 'desc'
    if (!isInitial) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchData()
    }
  }, [page, perPage, sortBy, sortDir, fetchData])

  // Build lookup maps from related data
  const paymentDataMap = new Map<string, any>(
    (related?.payments || []).map((p: any) => [
      p.id,
      {
        reconciled: p.reconciled,
        originalCurrency: p.paymentCurrency,
        originalAmount: p.originalAmount,
        status: p.status,
      },
    ])
  )
  const examBookingStatusByReference = new Map<string, any>(
    (related?.examBookings || []).flatMap((b: any) => {
      const entries: [string, any][] = [[b.id, b]]
      if (b.walletTxnId) entries.push([b.walletTxnId, b])
      return entries
    })
  )
  const enrollmentStatusMap = new Map(
    (related?.fullTimeEnrollments || []).map((e: any) => [e.id, e.status])
  )
  const modularStatusByTxn = new Map(
    (related?.modularEnrollments || [])
      .filter((e: any) => e.walletTxnId)
      .map((e: any) => [e.walletTxnId!, e.status])
  )
  const milestoneStatusByTxn = new Map(
    (related?.milestones || [])
      .filter((m: any) => m.walletTxnId)
      .map((m: any) => [m.walletTxnId!, `${m.milestoneType.replace(/_/g, ' ')} ${m.status}`])
  )

  const CREDIT_TYPES = ['TOP_UP', 'REFUND', 'RELEASE', 'CREDIT']
  const DEBIT_TYPES = ['CAPTURE', 'PAYMENT', 'RESERVE', 'DEBIT']

  const getTypeColor = (type: string) => {
    if (CREDIT_TYPES.includes(type))
      return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-400'
    if (['CAPTURE', 'PAYMENT'].includes(type))
      return 'bg-blue-100 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400'
    if (type === 'RESERVE')
      return 'bg-amber-100 text-amber-700 dark:bg-amber-500/10 dark:text-amber-400'
    return 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-400'
  }

  const getReferenceDisplay = (tx: SerializedTransactionRow) => {
    const typeLabel = tx.referenceType
      ? tx.referenceType.replace(/_/g, ' ')
      : `${tx.type.replace(/_/g, ' ')} Transaction`
    let refId: string
    if (tx.referenceType === 'FULL_TIME_ENROLLMENT' && tx.referenceId) {
      refId = `ENR-${tx.referenceId.slice(-6).toUpperCase()}`
    } else if (tx.referenceType === 'EXAM_BOOKING' && tx.referenceId) {
      const booking =
        examBookingStatusByReference.get(tx.referenceId) || examBookingStatusByReference.get(tx.id)
      refId = booking?.moduleCode
        ? `${booking.moduleCode}`
        : `EXM-${(tx.referenceId || tx.id).slice(-6).toUpperCase()}`
    } else if (tx.referenceType === 'PAYMENT_ID' && tx.referenceId) {
      refId = `PAY-${tx.referenceId.slice(-6).toUpperCase()}`
    } else if (tx.referenceId) {
      refId = `REF-${tx.referenceId.slice(-6).toUpperCase()}`
    } else {
      refId = `TX-${tx.id.slice(-8).toUpperCase()}`
    }
    return { type: typeLabel, id: refId }
  }

  const getStatusStyle = (status: string) => {
    const n = status.toUpperCase()
    if (
      ['PAID', 'APPROVED', 'COMPLETED', 'CONFIRMED', 'RECONCILED', 'POSTED'].some((s) =>
        n.includes(s)
      )
    )
      return 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20 dark:text-emerald-400'
    if (['PENDING', 'RESERVED', 'DUE', 'POOLED', 'SCHEDULED'].some((s) => n.includes(s)))
      return 'bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400'
    if (['FAILED', 'REJECTED', 'CANCELLED', 'EXPIRED'].some((s) => n.includes(s)))
      return 'bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400'
    return 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400'
  }

  const getTransactionStatus = (
    tx: SerializedTransactionRow,
    paymentData: SerializedTransactionRelated['payments'][0] | null | undefined
  ) => {
    if (tx.referenceType === 'PAYMENT_ID')
      return paymentData?.reconciled ? 'Reconciled' : paymentData?.status || 'Pending Settlement'
    if (tx.referenceType === 'EXAM_BOOKING') {
      const booking = tx.referenceId
        ? examBookingStatusByReference.get(tx.referenceId) ||
          examBookingStatusByReference.get(tx.id)
        : examBookingStatusByReference.get(tx.id)
      if (booking?.result) return booking.result
      if (booking?.demandStatus && booking.demandStatus !== 'DEMAND_CAPTURED')
        return booking.demandStatus.replace(/_/g, ' ')
      if (booking?.status) return booking.status
    }
    if (tx.referenceType === 'FULL_TIME_ENROLLMENT' && tx.referenceId)
      return enrollmentStatusMap.get(tx.referenceId) || 'Enrollment Posted'
    const ms = modularStatusByTxn.get(tx.id)
    if (ms) return ms
    const mls = milestoneStatusByTxn.get(tx.id)
    if (mls) return mls
    if (tx.referenceType?.includes('WALLET_TOP'))
      return tx.type === 'TOP_UP' ? 'Completed' : 'Pending'
    if (tx.type === 'RESERVE') return 'Reserved'
    if (CREDIT_TYPES.includes(tx.type) || ['CAPTURE', 'PAYMENT'].includes(tx.type))
      return 'Completed'
    if (tx.type === 'ADJUSTMENT') return 'Posted'
    return tx.type.replace(/_/g, ' ')
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-end">
        <div className="w-72">
          <SearchInput id="finance-transactions-search" placeholder="Search user or reference..." />
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-900">
        <Table>
          <TableHeader className="bg-slate-50 dark:bg-slate-800/50">
            <TableRow>
              <TableHead className="px-6 py-4 text-[10px] font-black tracking-widest text-slate-400 uppercase">
                User
              </TableHead>
              <SortableTh sortKey="type" label="Type" />
              <SortableTh sortKey="amount" label="Amount" align="right" />
              <TableHead className="px-6 py-4 text-[10px] font-black tracking-widest text-slate-400 uppercase">
                Reference &amp; Status
              </TableHead>
              <SortableTh sortKey="createdAt" label="Date" align="right" />
            </TableRow>
          </TableHeader>
          <TableBody className="divide-y divide-slate-100 dark:divide-slate-800">
            {loading ? (
              <TableRow>
                <TableCell colSpan={5} className="h-32 text-center">
                  <Loader2 className="text-aerojet-blue mx-auto h-6 w-6 animate-spin" />
                </TableCell>
              </TableRow>
            ) : data.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={5}
                  className="h-24 text-center font-bold text-slate-500 dark:text-slate-400"
                >
                  No transactions found.
                </TableCell>
              </TableRow>
            ) : (
              data.map((tx) => {
                const user = tx.wallet.user
                const userName = user.profile
                  ? `${user.profile.firstName} ${user.profile.lastName}`
                  : user.email
                const paymentData =
                  tx.referenceType === 'PAYMENT_ID'
                    ? (paymentDataMap.get(tx.referenceId!) ?? null)
                    : null
                const reference = getReferenceDisplay(tx)
                const statusLabel = getTransactionStatus(tx, paymentData)
                const isCredit = CREDIT_TYPES.includes(tx.type)

                return (
                  <TableRow
                    key={tx.id}
                    className="group transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/40"
                  >
                    <TableCell className="px-6 py-5">
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-900 dark:text-slate-100">
                          {userName}
                        </span>
                        <span className="text-xs text-slate-500 dark:text-slate-400">
                          {user.email}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="px-6 py-5">
                      <Badge
                        className={`${getTypeColor(tx.type)} rounded-lg border-none px-2 py-0.5 text-[10px] font-black tracking-widest uppercase transition-all`}
                        variant="secondary"
                      >
                        {tx.type.replace('_', ' ')}
                      </Badge>
                    </TableCell>
                    <TableCell className="px-6 py-5">
                      <div className="flex flex-col">
                        <span
                          className={`text-sm font-black ${
                            isCredit
                              ? 'text-emerald-600 dark:text-emerald-400'
                              : 'text-slate-900 dark:text-slate-100'
                          }`}
                        >
                          {isCredit ? '+' : '-'}
                          {symbol}
                          {Number(tx.amount).toFixed(2)}
                        </span>
                        {paymentData?.originalCurrency &&
                          paymentData.originalCurrency !== symbol && (
                            <span className="text-[10px] font-medium text-slate-400">
                              ({paymentData.originalCurrency}{' '}
                              {paymentData.originalAmount?.toFixed(2)})
                            </span>
                          )}
                      </div>
                    </TableCell>
                    <TableCell className="px-6 py-5">
                      <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-bold text-slate-700 dark:text-slate-300">
                            {reference.type}
                          </span>
                          <span
                            className={`flex items-center gap-0.5 rounded-full px-2 py-0.5 text-[9px] font-bold ${getStatusStyle(statusLabel)}`}
                          >
                            {statusLabel}
                          </span>
                        </div>
                        <span className="text-[10px] font-medium text-slate-400">
                          {reference.id}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="px-6 py-5 text-xs text-slate-500">
                      {format(new Date(tx.createdAt), 'MMM d, yyyy HH:mm')}
                    </TableCell>
                  </TableRow>
                )
              })
            )}
          </TableBody>
        </Table>
      </div>
      <TablePagination
        page={page}
        perPage={perPage}
        total={total}
        onPageChange={setPage}
        onPerPageChange={setPerPage}
      />
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import Link from 'next/link'
import {
  MoreHorizontal,
  Eye,
  UserCheck,
  UserX,
  KeyRound,
  Trash2,
  Mail,
  Loader2,
  ShieldCheck,
  LockOpen,
  Lock,
} from 'lucide-react'
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from '@/components/ui/dropdown-menu'
import ChangeRoleDialog from '../users/[id]/_components/ChangeRoleDialog'

interface UserActionsMenuProps {
  userId: string
  userStatus: string
  userEmail: string
  userRole?: string
  userName?: string
  isEmailVerified?: boolean
  mustChangePassword?: boolean
  onActionComplete?: () => void
}


function slugify(text: string) {
  return text?.toString().toLowerCase().trim().replace(/\s+/g, '-').replace(/[^\w\-]+/g, '').replace(/\-\-+/g, '-') || '';
}

export default function UserActionsMenu({
  userId,
  userStatus,
  userEmail,
  userRole,
  userName = 'this user',
  isEmailVerified = true,
  mustChangePassword,
  onActionComplete,
}: UserActionsMenuProps) {
  const [loading, setLoading] = useState<string | null>(null)
  const [roleDialogOpen, setRoleDialogOpen] = useState(false)

  const handleAction = async (action: string, label: string) => {
    setLoading(action)
    try {
      const url =
        action === 'delete'
          ? `/api/staff/users/${userId}`
          : action === 'hard-delete'
            ? `/api/staff/users/${userId}?hard=true`
            : `/api/staff/users/${userId}/${action}`

      const res = await fetch(url, {
        method: action === 'delete' || action === 'hard-delete' ? 'DELETE' : 'POST',
      })
      if (!res.ok) throw new Error()
      toast.success(`${label} successful`)
      onActionComplete?.()
    } catch {
      toast.error(`Failed to ${label.toLowerCase()}`)
    } finally {
      setLoading(null)
    }
  }

  const isSuspended = userStatus === 'SUSPENDED'
  const isArchived = userStatus === 'ARCHIVED'

  const actions = isArchived
    ? [
        {
          label: 'View Profile',
          icon: Eye,
          href: `/staff/users/${slugify(userName) || userId}`,
          variant: 'default',
        },
        {
          label: 'Restore User',
          icon: UserCheck,
          action: 'restore',
          variant: 'success',
        },
        {
          label: 'Permanently Delete',
          icon: Trash2,
          action: 'hard-delete',
          variant: 'danger',
        },
      ]
    : [
        {
          label: 'View Profile',
          icon: Eye,
          href: `/staff/users/${slugify(userName) || userId}`,
          variant: 'default',
        },
        {
          label: 'Change Role',
          icon: ShieldCheck,
          onClick: () => setRoleDialogOpen(true),
          variant: 'default',
        },
        {
          label: 'Reset Password',
          icon: KeyRound,
          action: 'reset-password',
          variant: 'default',
        },
        !isEmailVerified && {
          label: 'Resend Verification Email',
          icon: ShieldCheck,
          action: 'resend-verification',
          variant: 'default',
        },
        {
          label: 'Send Email',
          icon: Mail,
          href: `mailto:${userEmail}`,
          variant: 'default',
        },
        {
          label: 'Resend Login Credentials',
          icon: ShieldCheck,
          action: 'resend-credentials',
          variant: 'default',
        },
        mustChangePassword !== undefined && {
          label: mustChangePassword ? 'Bypass Password Change' : 'Require Password Change',
          icon: mustChangePassword ? LockOpen : Lock,
          action: 'toggle-password-change',
          variant: 'default',
        },
        isSuspended
          ? { label: 'Activate Account', icon: UserCheck, action: 'activate', variant: 'success' }
          : { label: 'Suspend Account', icon: UserX, action: 'suspend', variant: 'warning' },
        {
          label: 'Archive User',
          icon: Trash2,
          action: 'delete',
          variant: 'danger',
        },
      ]

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            disabled={!!loading}
            onClick={(e) => e.stopPropagation()}
            aria-label={`Actions for ${userName}`}
            className="flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 transition-all outline-none hover:bg-slate-100 hover:text-slate-700 focus:ring-2 focus:ring-aerojet-blue focus:ring-offset-2 disabled:opacity-50"
          >
            {loading ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <MoreHorizontal className="h-4 w-4" />
            )}
          </button>
        </DropdownMenuTrigger>

        <DropdownMenuContent align="end" side="bottom" collisionPadding={10} className="w-48 p-1">
          {actions.filter(Boolean).map((item: any) => {
            const Icon = item.icon
            const colorClass =
              item.variant === 'danger'
                ? 'text-red-600 focus:text-red-600 focus:bg-red-50'
                : item.variant === 'warning'
                  ? 'text-amber-600 focus:text-amber-600 focus:bg-amber-50'
                  : item.variant === 'success'
                    ? 'text-emerald-600 focus:text-emerald-600 focus:bg-emerald-50'
                    : 'text-slate-700 focus:text-slate-900 focus:bg-slate-50'

            if ('href' in item) {
              return (
                <DropdownMenuItem key={item.label} asChild className={colorClass}>
                  <Link
                    href={item.href}
                    onClick={(e) => e.stopPropagation()}
                    className="flex w-full cursor-pointer items-center gap-2.5 px-2 py-2"
                  >
                    <Icon className="h-3.5 w-3.5" />
                    {item.label}
                  </Link>
                </DropdownMenuItem>
              )
            }

            if ('onClick' in item) {
              return (
                <DropdownMenuItem
                  key={item.label}
                  onClick={(e) => {
                    e.stopPropagation()
                    item.onClick()
                  }}
                  className={`${colorClass} flex w-full cursor-pointer items-center gap-2.5 px-2 py-2`}
                >
                  <Icon className="h-3.5 w-3.5" />
                  {item.label}
                </DropdownMenuItem>
              )
            }

            return (
              <DropdownMenuItem
                key={item.label}
                onClick={(e) => {
                  e.stopPropagation()
                  handleAction(item.action!, item.label)
                }}
                className={`${colorClass} flex w-full cursor-pointer items-center gap-2.5 px-2 py-2`}
              >
                <Icon className="h-3.5 w-3.5" />
                {item.label}
              </DropdownMenuItem>
            )
          })}
        </DropdownMenuContent>
      </DropdownMenu>

      <ChangeRoleDialog
        userId={userId}
        currentRole={userRole || ''}
        userName={userName}
        open={roleDialogOpen}
        onOpenChange={setRoleDialogOpen}
      />
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import Link from 'next/link'
import { useSearchParams } from 'next/navigation'
import {
  Users,
  RefreshCw,
  CheckSquare,
  Square,
  CheckCircle2,
  AlertTriangle,
  Trash2,
  Mail,
  LockOpen,
  Archive,
} from 'lucide-react'
import CreateUserDialog from './CreateUserDialog'
import TablePagination from './TablePagination'
import BulkActionsDropdown from './BulkActionsDropdown'
import UsersTableFilters from './users-table/UsersTableFilters'
import UsersTableRow from './users-table/UsersTableRow'
import type { User } from './users-table/types'
import { SortableTh } from '@/components/ui/sortable-th'

import {
  bulkUpdateUserStatus,
  bulkDeleteUsers,
  bulkArchiveUsers,
  bulkBypassPasswordChange,
} from '../actions'
import { toast } from 'sonner'

export default function UsersTable({ initialTotal }: { initialTotal: number }) {
  const searchParams = useSearchParams()
  const [users, setUsers] = useState<User[]>([])
  const [total, setTotal] = useState(initialTotal)
  const [loading, setLoading] = useState(true)
  const [role, setRole] = useState('all')
  const [status, setStatus] = useState('all')
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)
  const [selectedIds, setSelectedIds] = useState<string[]>([])

  const fetchUsers = useCallback(async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        role,
        status,
        page: String(page),
        limit: String(perPage),
        ...(search && { search }),
      })
      const sort = searchParams.get('sort')
      const order = searchParams.get('order')
      if (sort) params.set('sort', sort)
      if (order) params.set('order', order)
      const res = await fetch(`/api/staff/users?${params}`)
      const data = await res.json()

      if (data.success) {
        setUsers(data.data ?? [])
        setTotal(data.meta?.total ?? 0)
      } else {
        setUsers([])
        setTotal(0)
      }
    } finally {
      setLoading(false)
    }
  }, [role, status, search, page, perPage, searchParams])

  useEffect(() => {
    const t = setTimeout(fetchUsers, search ? 350 : 0)
    return () => clearTimeout(t)
  }, [fetchUsers, search])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setPage(1)
  }, [role, status, search])

  const bulkActions = [
    {
      label: 'Activate',
      icon: CheckCircle2,
      variant: 'success' as const,
      confirmTitle: 'Activate Users',
      confirmMessage: `Are you sure you want to activate ${selectedIds.length} selected users?`,
      onClick: async (ids: string[]) => {
        const res = await bulkUpdateUserStatus(ids, 'ACTIVE')
        if (res.success) { toast.success(`Activated ${ids.length} users`); fetchUsers() }
        else toast.error(res.error)
      },
    },
    {
      label: 'Suspend',
      icon: AlertTriangle,
      variant: 'warning' as const,
      confirmTitle: 'Suspend Users',
      confirmMessage: `Are you sure you want to suspend ${selectedIds.length} selected users?`,
      onClick: async (ids: string[]) => {
        const res = await bulkUpdateUserStatus(ids, 'SUSPENDED')
        if (res.success) { toast.success(`Suspended ${ids.length} users`); fetchUsers() }
        else toast.error(res.error)
      },
    },
    {
      label: 'Send Credentials',
      icon: Mail,
      variant: 'primary' as const,
      confirmTitle: 'Send Login Credentials',
      confirmMessage: `This will generate new temporary passwords and email login credentials to ${selectedIds.length} selected users.`,
      onClick: async (ids: string[]) => {
        try {
          const res = await fetch('/api/admin/bulk-send-credentials', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ users: ids.map((id) => ({ userId: id })) }),
          })
          const data = await res.json()
          if (!res.ok) throw new Error(data.error || 'Failed')
          toast.success(`Credentials sent to ${data.data.summary.sent} users`)
          fetchUsers()
        } catch (err: any) {
          toast.error(err.message || 'Failed')
        }
      },
    },
    users.filter((u) => selectedIds.includes(u.id)).every((u) => u.status === 'ARCHIVED') &&
    users.filter((u) => selectedIds.includes(u.id)).length > 0
      ? {
          label: 'Permanently Delete',
          icon: Trash2,
          variant: 'danger' as const,
          confirmTitle: 'Permanently Delete Users',
          confirmMessage: `Are you sure you want to permanently delete ${selectedIds.length} users? This cannot be undone.`,
          onClick: async (ids: string[]) => {
            const res = await bulkDeleteUsers(ids)
            if (res.success) { toast.success(`Permanently deleted ${ids.length} users`); fetchUsers() }
            else toast.error(res.error)
          },
        }
      : {
          label: 'Archive',
          icon: Archive,
          variant: 'warning' as const,
          confirmTitle: 'Archive Users',
          confirmMessage: `Are you sure you want to archive ${selectedIds.length} users?`,
          onClick: async (ids: string[]) => {
            const res = await bulkArchiveUsers(ids)
            if (res.success) { toast.success(`Archived ${ids.length} users`); fetchUsers() }
            else toast.error(res.error)
          },
        },
    {
      label: 'Bypass PW Change',
      icon: LockOpen,
      variant: 'primary' as const,
      confirmTitle: 'Bypass Password Change',
      confirmMessage: `Are you sure you want to bypass the required password change for ${selectedIds.length} selected users?`,
      onClick: async (ids: string[]) => {
        const res = await bulkBypassPasswordChange(ids)
        if (res.success) { toast.success(`Bypassed password change for ${ids.length} users`); fetchUsers() }
        else toast.error(res.error)
      },
    },
    {
      label: 'Send Email',
      icon: Mail,
      variant: 'default' as const,
      onClick: async (ids: string[]) => {
        const selectedEmails = users
          .filter((u) => ids.includes(u.id))
          .map((u) => u.email)
          .filter(Boolean)
        if (selectedEmails.length > 0) {
          window.location.href = `mailto:${selectedEmails.join(',')}`
        }
      },
    },
  ]

  const allSelected = selectedIds.length === users.length && users.length > 0

  return (
    <div className="space-y-6">
      {/* Actions Bar */}
      <div className="flex items-center justify-between">
        <p className="text-sm text-slate-400">{total.toLocaleString()} total users</p>
        <div className="flex gap-2">
          <CreateUserDialog />
          <Link
            href="/staff/students/import"
            className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 dark:hover:border-slate-600"
          >
            <Users className="h-3.5 w-3.5 text-blue-600" />
            Import Students
          </Link>
          <button
            onClick={fetchUsers}
            className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 dark:hover:border-slate-600"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Refresh
          </button>
          <BulkActionsDropdown
            selectedIds={selectedIds}
            onClear={() => setSelectedIds([])}
            actions={bulkActions}
          />
        </div>
      </div>

      {/* Filters */}
      <UsersTableFilters
        role={role}
        status={status}
        search={search}
        onRoleChange={setRole}
        onStatusChange={setStatus}
        onSearchChange={setSearch}
      />

      {/* Table */}
      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="hidden overflow-x-auto md:block">
          <table className="w-full text-left">
            <thead>
              <tr className="border-b border-slate-100 bg-slate-50 dark:border-slate-800 dark:bg-slate-800/50">
                <th className="w-12 px-5 py-3">
                  <button
                    onClick={() => setSelectedIds(allSelected ? [] : users.map((u) => u.id))}
                    className="hover:text-aerojet-blue text-slate-400 transition-colors"
                    aria-label="Select all users"
                  >
                    {allSelected ? (
                      <CheckSquare className="text-aerojet-blue h-4 w-4" />
                    ) : (
                      <Square className="h-4 w-4" />
                    )}
                  </button>
                </th>
                <SortableTh sortKey="name" label="User" />
                <SortableTh sortKey="role" label="Role" />
                <SortableTh sortKey="status" label="Status" />
                <SortableTh sortKey="joined" label="Joined" />
                <th
                  key="actions"
                  className="px-5 py-3 text-[10px] font-black tracking-wider text-slate-500 uppercase"
                >
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                Array.from({ length: 8 }).map((_, i) => (
                  <tr key={i}>
                    <td className="px-5 py-3.5">
                      <div className="h-4 w-4 animate-pulse rounded bg-slate-100" />
                    </td>
                    {Array.from({ length: 5 }).map((_, j) => (
                      <td key={j} className="px-5 py-3.5">
                        <div className="h-4 w-3/4 animate-pulse rounded bg-slate-100" />
                      </td>
                    ))}
                  </tr>
                ))
              ) : users.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-16 text-center">
                    <Users className="mx-auto mb-2 h-10 w-10 text-slate-200" />
                    <p className="text-sm font-bold text-slate-400">No users found</p>
                  </td>
                </tr>
              ) : (
                users.map((user) => (
                  <UsersTableRow
                    key={user.id}
                    user={user}
                    isSelected={selectedIds.includes(user.id)}
                    onToggleSelect={() =>
                      setSelectedIds((prev) =>
                        prev.includes(user.id)
                          ? prev.filter((id) => id !== user.id)
                          : [...prev, user.id]
                      )
                    }
                    onActionComplete={fetchUsers}
                  />
                ))
              )}
            </tbody>
          </table>
        </div>

        <TablePagination
          page={page}
          perPage={perPage}
          total={total}
          onPageChange={setPage}
          onPerPageChange={setPerPage}
        />
      </div>
    </div>
  )
}

'use client'

import { useRouter } from 'next/navigation'
import { CheckSquare, Square } from 'lucide-react'
import UserActionsMenu from '../UserActionsMenu'
import type { User } from './types'
import { ROLE_STYLE, STATUS_STYLE } from './types'

export default function UsersTableRow({
  user,
  isSelected,
  onToggleSelect,
  onActionComplete,
}: {
  user: User
  isSelected: boolean
  onToggleSelect: () => void
  onActionComplete: () => void
}) {
  const router = useRouter()

  const fullName = user.profile
    ? [user.profile.firstName, user.profile.middleName, user.profile.lastName]
        .filter(Boolean)
        .join(' ')
    : user.email
  const initials = user.profile
    ? `${user.profile.firstName[0]}${user.profile.lastName[0]}`
    : user.email[0].toUpperCase()

  return (
    <tr
      onClick={() =>
        router.push(
          user.role === 'STUDENT' || user.role === 'APPLICANT'
            ? `/staff/students/${user.id}`
            : `/staff/users/${user.id}`
        )
      }
      className={`cursor-pointer transition-all duration-150 ease-out hover:bg-accent hover:shadow-[0_1px_4px_rgba(0,0,0,0.06)] dark:hover:bg-accent ${isSelected ? 'bg-aerojet-blue/5' : ''}`}
    >
      <td className="px-5 py-3.5" onClick={(e) => e.stopPropagation()}>
        <button
          onClick={onToggleSelect}
          className="hover:text-aerojet-blue text-slate-300 transition-colors"
          aria-label={`Select ${fullName}`}
        >
          {isSelected ? (
            <CheckSquare className="text-aerojet-blue h-4 w-4" />
          ) : (
            <Square className="h-4 w-4" />
          )}
        </button>
      </td>
      <td className="px-5 py-3.5">
        <div className="flex items-center gap-3">
          <div className="bg-aerojet-blue/10 text-aerojet-blue relative flex h-8 w-8 shrink-0 items-center justify-center overflow-hidden rounded-full text-xs font-black">
            {user.profile?.profilePhotoUrl ? (
              <img
                src={user.profile.profilePhotoUrl}
                alt={fullName}
                className="h-full w-full object-cover"
              />
            ) : (
              initials
            )}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800 dark:text-slate-200">{fullName}</p>
            <p className="text-xs text-slate-500 dark:text-slate-400">{user.email}</p>
          </div>
        </div>
      </td>
      <td className="px-5 py-3.5">
        <span
          className={`rounded-full px-2 py-0.5 text-xs font-black uppercase ${ROLE_STYLE[user.role] ?? 'bg-slate-100 text-slate-500'}`}
        >
          {user.role}
        </span>
      </td>
      <td className="px-5 py-3.5">
        <span
          className={`rounded-full px-2 py-0.5 text-xs font-black uppercase ${STATUS_STYLE[user.status] ?? 'bg-slate-100 text-slate-500'}`}
        >
          {user.status}
        </span>
      </td>
      <td className="px-5 py-3.5 text-xs text-slate-500 dark:text-slate-400">
        {new Date(user.createdAt).toLocaleDateString('en-GB', {
          day: 'numeric',
          month: 'short',
          year: 'numeric',
        })}
      </td>
      <td className="px-5 py-3.5" onClick={(e) => e.stopPropagation()}>
        <UserActionsMenu
          userId={user.id}
          userStatus={user.status}
          userEmail={user.email}
          userRole={user.role}
          userName={fullName}
          isEmailVerified={!!user.emailVerified}
          mustChangePassword={user.mustChangePassword}
          onActionComplete={onActionComplete}
        />
      </td>
    </tr>
  )
}

'use client'

import { useState, useMemo, useCallback } from 'react'
import { toast } from 'sonner'
import { CalendarDays, BookOpen, Plus, X, Check, Loader2, Search } from 'lucide-react'
import { compareNatural } from '@/lib/utils/natural-sort'
import { Button } from '@/components/ui/button'

// ─── Types ────────────────────────────────────────────────────────────────────

interface CourseRef {
  id: string
  code: string
  name: string
}

interface TermCourseAssignment {
  id: string
  termId: string
  courseId: string
  course: CourseRef
}

interface AcademicTerm {
  id: string
  pathwayId: string
  yearNumber: number
  semesterNumber: number
  courseAssignments: TermCourseAssignment[]
}

interface Pathway {
  id: string
  code: string
  name: string
  academicTerms: AcademicTerm[]
}

interface Course {
  id: string
  code: string
  name: string
  isActive: boolean
  duration: number | null
}

interface SchedulingMatrixProps {
  initialPathways: Pathway[]
  initialCourses: Course[]
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function SchedulingMatrix({
  initialPathways,
  initialCourses,
}: SchedulingMatrixProps) {
  const [pathways, setPathways] = useState<Pathway[]>(initialPathways)
  const [courses] = useState<Course[]>(initialCourses)
  const [selectedPathwayId, setSelectedPathwayId] = useState<string>(initialPathways[0]?.id ?? '')
  const [actionLoading, setActionLoading] = useState<string | null>(null)

  // Mobile specific state
  const [isMobileSidebarExpanded, setIsMobileSidebarExpanded] = useState(false)

  // ─── Refetch after mutations ──────────────────────────────────────────────

  const refetchPathways = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/academic/scheduling')
      if (!res.ok) throw new Error('Failed to refresh')
      const data = await res.json()
      setPathways(data.data?.pathways ?? data.pathways ?? [])
    } catch {
      // Silent — data will be stale but user already saw the toast
    }
  }, [])

  // ─── Derived state ────────────────────────────────────────────────────────

  const selectedPathway = useMemo(
    () => pathways.find((p) => p.id === selectedPathwayId) ?? null,
    [pathways, selectedPathwayId]
  )

  const termColumns = useMemo(() => {
    if (!selectedPathway) return []
    return [...selectedPathway.academicTerms].sort((a, b) =>
      a.yearNumber !== b.yearNumber
        ? a.yearNumber - b.yearNumber
        : a.semesterNumber - b.semesterNumber
    )
  }, [selectedPathway])

  const assignmentMap = useMemo(() => {
    const map = new Map<string, string>()
    if (!selectedPathway) return map
    for (const term of selectedPathway.academicTerms) {
      for (const a of term.courseAssignments) {
        map.set(`${term.id}-${a.courseId}`, a.id)
      }
    }
    return map
  }, [selectedPathway])

  const sortedCourses = useMemo(() => {
    return [...courses].sort((a, b) => compareNatural(a.code, b.code))
  }, [courses])

  const termCounts = useMemo(() => {
    const counts: Record<string, number> = {}
    for (const term of termColumns) {
      counts[term.id] = term.courseAssignments.length
    }
    return counts
  }, [termColumns])

  // ─── Actions ──────────────────────────────────────────────────────────────

  const handleAssign = async (termId: string, courseId: string) => {
    const key = `${termId}-${courseId}`
    setActionLoading(key)
    try {
      const res = await fetch('/api/staff/academic/scheduling', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ termId, courseId }),
      })
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}))
        throw new Error(errData.error ?? 'Failed to assign course')
      }
      toast.success('Course assigned to term')
      await refetchPathways()
    } catch (err: any) {
      toast.error(err.message ?? 'Failed to assign course')
    } finally {
      setActionLoading(null)
    }
  }

  const handleRemove = async (termId: string, courseId: string) => {
    const confirmed = window.confirm('Remove this course from the term? This cannot be undone.')
    if (!confirmed) return

    const key = `${termId}-${courseId}`
    setActionLoading(key)
    try {
      const res = await fetch(
        `/api/staff/academic/scheduling?termId=${termId}&courseId=${courseId}`,
        { method: 'DELETE' }
      )
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}))
        throw new Error(errData.error ?? 'Failed to remove assignment')
      }
      toast.success('Course removed from term')
      await refetchPathways()
    } catch (err: any) {
      toast.error(err.message ?? 'Failed to remove assignment')
    } finally {
      setActionLoading(null)
    }
  }

  const handleCellClick = (termId: string, courseId: string) => {
    const key = `${termId}-${courseId}`
    if (actionLoading) return
    if (assignmentMap.has(key)) {
      handleRemove(termId, courseId)
    } else {
      handleAssign(termId, courseId)
    }
  }

  return (
    <div className="mx-auto max-w-[1800px] space-y-6 px-4 py-8 md:space-y-8 md:px-8">
      {/* Header */}
      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-3">
          <CalendarDays className="text-aerojet-sky h-7 w-7 md:h-8 md:w-8" />
          <h1 className="text-aerojet-blue text-2xl font-black tracking-tight md:text-3xl dark:text-white">
            Academic Scheduling
          </h1>
        </div>
        <p className="text-xs font-medium text-slate-500 md:text-sm dark:text-slate-400">
