import { AuditAction, createAuditLog } from '@/lib/audit/logger'
import { handleActionError } from '@/lib/staff/errors'
import { getRequestContext } from '@/lib/server/request-context'

export async function bulkUpdateExamBookingStatus(bookingIds: string[], status: PaymentStatus) {
  try {
    await requireStaff()
    if (!bookingIds.length || !status) return { error: 'Invalid parameters.' }

    await prismaUnfiltered.examBooking.updateMany({
      where: { id: { in: bookingIds } },
      data: { status },
    })

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/student/exams', 'page')
    revalidatePath('/staff/reports', 'page')
    return { success: true }
  } catch (error) {
    return {
      error: handleActionError('bulkUpdateExamBookingStatus', error, 'Failed to update bookings.'),
    }
  }
}

export interface ExamRecordUpdateData {
  courseId?: string
  bookingType?: string
  moduleCode?: string
  examDate?: Date
  score?: number
  result?: string
  status?: PaymentStatus
  attemptType?: string
  isResit?: boolean
  isMigrated?: boolean
  migrationRef?: string
  resultIdToSync?: string
  examCategory?: 'INTERNAL' | 'OFFICIAL_EASA'
  certificateUrl?: string | null
  certificateIssued?: Date | null
  supervisorOverrideJustification?: string
}

async function resolveTargetStudent(
  prisma: typeof prismaUnfiltered,
  actualId: string,
  isResultId: boolean
): Promise<{ userId: string; name: string }> {
  let targetUserId = ''
  if (isResultId) {
    const res = await prisma.examResult.findUnique({
      where: { id: actualId },
      select: { userId: true },
    })
    targetUserId = res?.userId || ''
  } else {
    const b = await prisma.examBooking.findUnique({
      where: { id: actualId },
      select: { userId: true },
    })
    targetUserId = b?.userId || ''
  }
  let targetStudentName = 'unknown'
  if (targetUserId) {
    const profile = await prisma.profile.findUnique({
      where: { userId: targetUserId },
      select: { firstName: true, lastName: true },
    })
    if (profile) targetStudentName = `${profile.firstName} ${profile.lastName}`
  }
  return { userId: targetUserId, name: targetStudentName }
}

async function finalizeExamUpdate(
  staff: { id: string; role: string },
  actualId: string,
  isResultId: boolean,
  targetUserId: string,
  targetStudentName: string,
  data: ExamRecordUpdateData,
  moduleCode: string | undefined,
  score: number | undefined,
  overrides?: { resultLocked?: boolean; supervisorOverride?: string }
) {
  revalidatePath('/staff/exams')
  revalidatePath('/student/exams')
  if (targetUserId) {
    revalidatePath(`/staff/students/${targetUserId}`)
  }

  const ctx = await getRequestContext()
  await createAuditLog({
    userId: staff.id,
    action: AuditAction.UPDATE,
    entity: isResultId ? 'ExamResult' : 'ExamBooking',
    entityId: actualId,
    description: `Updated ${isResultId ? 'exam result' : 'exam booking'} record for student ${targetStudentName}.${isResultId && data.supervisorOverrideJustification ? ` Supervisor override: ${data.supervisorOverrideJustification}` : ''}`,
    changes: {
      recordId: actualId,
      targetUserId,
      fields: Object.keys(data),
      moduleCode,
      score,
      result: data.result,
      status: data.status,
      attemptType: data.attemptType,
      examCategory: data.examCategory,
      resultLocked:
        overrides?.resultLocked ??
        (isResultId ? (data.supervisorOverrideJustification ? false : undefined) : undefined),
      supervisorOverride:
        overrides?.supervisorOverride ?? (data.supervisorOverrideJustification || undefined),
      certificateUrl: data.certificateUrl,
      certificateIssued: data.certificateIssued?.toISOString?.() || data.certificateIssued,
    },
    ipAddress: ctx.ipAddress ?? undefined,
    userAgent: ctx.userAgent ?? undefined,
  })
  return { success: true }
}

interface BookingResultSyncData {
  bookingId: string
  userId: string
  moduleCode: string
  score: number | undefined
  percentage: number | undefined
  passed: boolean | undefined
  grade: string | undefined
  attemptType?: string
  examCategory?: string
  isMigrated?: boolean
  migrationRef?: string
  resultIdToSync?: string
}

/**
 * Syncs booking-level score/attempt data to the exam_results table.
 * Separated from updateExamBooking to maintain booking/result domain boundaries.
 */
async function syncExamResultFromBooking(
  tx: any,
  booking: { userId: string; moduleCode?: string | null },
  sync: BookingResultSyncData
) {
  if (sync.score === undefined && !sync.attemptType && !sync.examCategory) return

  const {
    userId,
    moduleCode: finalModule,
    score,
    percentage,
    passed,
    grade,
    attemptType,
    examCategory,
    isMigrated,
    migrationRef,
    resultIdToSync,
  } = sync

  if (resultIdToSync) {
    await tx.examResult.update({
      where: { id: resultIdToSync },
      data: {
        ...(score !== undefined ? { score, maxScore: 100, percentage, passed, grade } : {}),
        ...(attemptType !== undefined ? { attemptType } : {}),
        ...(examCategory !== undefined ? { examCategory: examCategory as ExamCategory } : {}),
        moduleCode: finalModule,
        migrationRef:
          isMigrated !== undefined
            ? isMigrated
              ? migrationRef || 'MANUAL_CORRECTION'
              : null
            : undefined,
      },
    })
  } else {
    const existingResult = await tx.examResult.findFirst({
      where: { userId, moduleCode: finalModule },
      orderBy: { createdAt: 'desc' },
    })

    if (existingResult) {
      await tx.examResult.update({
        where: { id: existingResult.id },
        data: {
          ...(score !== undefined ? { score, maxScore: 100, percentage, passed, grade } : {}),
          ...(attemptType !== undefined ? { attemptType } : {}),
          ...(examCategory !== undefined ? { examCategory: examCategory as ExamCategory } : {}),
          migrationRef:
            isMigrated !== undefined
              ? isMigrated
                ? migrationRef || 'MANUAL_CORRECTION'
                : null
              : undefined,
        },
      })
    } else {
      await tx.examResult.create({
        data: {
          userId,
          moduleCode: finalModule,
          score: score ?? 0,
          maxScore: 100,
          percentage: score ?? 0,
          passed: (score ?? 0) >= 75,
          grade: grade || 'F',
          ...(attemptType !== undefined ? { attemptType } : {}),
          ...(examCategory !== undefined ? { examCategory: examCategory as ExamCategory } : {}),
          migrationRef: isMigrated ? migrationRef || 'MANUAL_CORRECTION' : undefined,
          sourceNotes: 'Auto-created from booking update',
        },
      })
    }
  }
}

export async function updateExamBooking(bookingId: string, data: ExamRecordUpdateData) {
  try {
    const staff = await requireStaff()
    const moduleCode = data.moduleCode?.toUpperCase()
    const score = data.score !== undefined && data.score !== null ? data.score : undefined
    const percentage = score !== undefined ? score : undefined
    const passed = score !== undefined ? score >= 75 : undefined
    const grade =
      score !== undefined
        ? score >= 90
          ? 'A'
          : score >= 80
            ? 'B'
            : score >= 75
              ? 'C'
              : 'F'
        : undefined

    const isResit =
      data.isResit !== undefined
        ? data.isResit
        : data.attemptType
          ? data.attemptType.startsWith('RESIT')
          : undefined

    await prismaUnfiltered.$transaction(
      async (tx) => {
        const booking = await tx.examBooking.findUnique({ where: { id: bookingId } })
        if (!booking) throw new Error('Booking not found')

        const finalModule = moduleCode || booking.moduleCode || ''

        await tx.examBooking.update({
          where: { id: bookingId },
          data: {
            ...(moduleCode ? { moduleCode } : {}),
            ...(data.examDate ? { examDate: data.examDate } : {}),
            ...(data.attemptType ? { attemptType: data.attemptType } : {}),
            ...(data.examCategory ? { examCategory: data.examCategory as ExamCategory } : {}),
            ...(isResit !== undefined ? { isResit } : {}),
            ...(data.bookingType ? { bookingType: data.bookingType as BookingType } : {}),
            ...(!data.isMigrated &&
            (score !== undefined ||
              data.attemptType ||
              data.examCategory ||
              (booking.result?.toUpperCase().includes('MIGRATE') && booking.score != null))
              ? {
                  score: score ?? (booking.score != null ? Number(booking.score) : undefined),
                  percentage: score ?? (booking.score != null ? Number(booking.score) : undefined),
                  result:
                    (score ?? (booking.score != null ? Number(booking.score) : 0)) >= 75
                      ? 'pass'
                      : 'fail',
                  status: PaymentStatus.APPROVED,
                }
              : {}),
            ...(data.isMigrated !== undefined
              ? {
                  result: data.isMigrated
                    ? 'MIGRATED'
                    : booking.result === 'MIGRATED'
                      ? 'pass'
                      : booking.result,
                }
              : {}),
          },
        })

        await syncExamResultFromBooking(tx, booking, {
          bookingId,
          userId: booking.userId,
          moduleCode: finalModule,
          score,
          percentage,
          passed,
          grade,
          attemptType: data.attemptType,
          examCategory: data.examCategory as ExamCategory | undefined,
          isMigrated: data.isMigrated,
          migrationRef: data.migrationRef,
          resultIdToSync: data.resultIdToSync,
        })

        if (score !== undefined) {
          await tx.examAttendance.upsert({
            where: { bookingId },
            update: { status: 'PRESENT' },
            create: {
              userId: booking.userId,
              bookingId,
              status: 'PRESENT',
              attendanceDate: booking.examDate || new Date(),
              recordedBy: 'system',
              eventId: booking.eventId,
              examId: booking.examId,
              examComponentId: booking.examComponentId,
              classId: booking.courseId ? undefined : undefined,
            },
          })
        }
      },
      {
        timeout: 30000,
      }
    )

    const { userId, name: targetStudentName } = await resolveTargetStudent(
      prismaUnfiltered,
      bookingId,
      false
    )

    return finalizeExamUpdate(
      staff,
      bookingId,
      false,
      userId,
      targetStudentName,
      data,
      moduleCode,
      score
    )
  } catch (error) {
    return { error: handleActionError('updateExamBooking', error, 'Failed to update booking.') }
  }
}

export async function updateExamResult(resultId: string, data: ExamRecordUpdateData) {
  try {
    const staff = await requireStaff()
    const isSupervisor = ['ADMIN', 'SUPER_ADMIN'].includes(staff.role)

    const existingResult = await prismaUnfiltered.examResult.findUnique({
      where: { id: resultId },
      select: { resultLocked: true, lockedBy: true, certificateUrl: true, certificateIssued: true },
    })

    if (existingResult?.resultLocked && !isSupervisor) {
      return {
        error: 'Result is locked and cannot be modified. Contact a supervisor for an override.',
      }
    }

    if (
      existingResult?.resultLocked &&
      isSupervisor &&
      !data.supervisorOverrideJustification?.trim()
    ) {
      return { error: 'Supervisor override justification is required to modify a locked result.' }
    }

    const moduleCode = data.moduleCode?.toUpperCase()
    const score = data.score !== undefined && data.score !== null ? data.score : undefined
    const percentage = score !== undefined ? score : undefined
    const passed = score !== undefined ? score >= 75 : undefined
    const grade =
      score !== undefined
        ? score >= 90
          ? 'A'
          : score >= 80
            ? 'B'
            : score >= 75
              ? 'C'
              : 'F'
        : undefined

    const updateData: Record<string, unknown> = {
      ...(moduleCode ? { moduleCode } : {}),
      ...(score !== undefined ? { score, maxScore: 100, percentage, passed, grade } : {}),
      ...(data.attemptType ? { attemptType: data.attemptType } : {}),
      ...(data.examCategory ? { examCategory: data.examCategory } : {}),
      ...(data.isMigrated !== undefined
        ? {
            migrationRef: data.isMigrated ? data.migrationRef || 'MANUAL_CORRECTION' : null,
          }
        : {}),
    }

    if (data.certificateUrl !== undefined || data.certificateIssued !== undefined) {
      updateData.certificateUrl = data.certificateUrl ?? undefined
      updateData.certificateIssued = data.certificateIssued ?? undefined
      if (data.certificateUrl || data.certificateIssued) {
        updateData.resultLocked = true
        updateData.lockedBy = staff.id
        updateData.lockedAt = new Date()
      }
    }

    if (isSupervisor && data.supervisorOverrideJustification) {
      updateData.resultLocked = false
      updateData.lockedBy = null
      updateData.lockedAt = null
    }

    await prismaUnfiltered.examResult.update({
      where: { id: resultId },
      data: updateData,
    })

    const res = await prismaUnfiltered.examResult.findUnique({
      where: { id: resultId },
      select: { userId: true, moduleCode: true },
    })
    if (res && res.moduleCode) {
      const normModule = res.moduleCode.trim()
      await prismaUnfiltered.examBooking.updateMany({
        where: {
          userId: res.userId,
          OR: [
            { moduleCode: { equals: normModule, mode: 'insensitive' } },
            { moduleCode: { contains: normModule, mode: 'insensitive' } },
          ],
        },
        data: {
          ...(data.attemptType ? { attemptType: data.attemptType } : {}),
          ...(data.examCategory ? { examCategory: data.examCategory } : {}),
          ...(data.bookingType ? { bookingType: data.bookingType as BookingType } : {}),
        },
      })
    }

    const { userId, name: targetStudentName } = await resolveTargetStudent(
      prismaUnfiltered,
      resultId,
      true
    )

    return finalizeExamUpdate(
      staff,
      resultId,
      true,
      userId,
      targetStudentName,
      data,
      moduleCode,
      score,
      {
        resultLocked: data.supervisorOverrideJustification ? false : undefined,
        supervisorOverride: data.supervisorOverrideJustification,
      }
    )
  } catch (error) {
    return { error: handleActionError('updateExamResult', error, 'Failed to update result.') }
  }
}

export async function bulkUpdateExamCategory(
  ids: string[],
  category: 'INTERNAL' | 'OFFICIAL_EASA'
) {
  try {
    await requireStaff()

    if (!ids || ids.length === 0) {
      return { error: 'No records selected' }
    }

    const cleanIds = ids.map((id) => id.replace('result_', ''))

    const affectedBookings = await prismaUnfiltered.examBooking.findMany({
      where: { id: { in: cleanIds } },
      select: { id: true, userId: true, moduleCode: true },
    })

    const affectedResults = await prismaUnfiltered.examResult.findMany({
      where: { id: { in: cleanIds } },
      select: { id: true, userId: true, moduleCode: true },
    })

    const bookingIds = new Set(affectedBookings.map((b) => b.id))
    const resultIds = new Set(affectedResults.map((r) => r.id))

    const pairs = new Set<string>()
    affectedBookings.forEach((b) => {
      if (b.userId && b.moduleCode) pairs.add(`${b.userId}:${b.moduleCode.toUpperCase()}`)
    })
    affectedResults.forEach((r) => {
      if (r.userId && r.moduleCode) pairs.add(`${r.userId}:${r.moduleCode.toUpperCase()}`)
    })

    for (const pair of Array.from(pairs)) {
      const [uId, mCode] = pair.split(':')

      const relatedBookings = await prismaUnfiltered.examBooking.findMany({
        where: {
          userId: uId,
          moduleCode: { equals: mCode, mode: 'insensitive' },
        },
        select: { id: true },
      })
      relatedBookings.forEach((b) => bookingIds.add(b.id))

      const relatedResults = await prismaUnfiltered.examResult.findMany({
        where: {
          userId: uId,
          moduleCode: { equals: mCode, mode: 'insensitive' },
        },
        select: { id: true },
      })
      relatedResults.forEach((r) => resultIds.add(r.id))
    }

    const [bookingCount, resultCount] = await prismaUnfiltered.$transaction([
      prismaUnfiltered.examBooking.updateMany({
        where: { id: { in: Array.from(bookingIds) } },
        data: { examCategory: category },
      }),
      prismaUnfiltered.examResult.updateMany({
        where: { id: { in: Array.from(resultIds) } },
        data: { examCategory: category },
      }),
    ])

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/staff/reports', 'page')
    return { success: true }
  } catch (error) {
    return {
      error: handleActionError('bulkUpdateExamCategory', error, 'Failed to update records.'),
    }
  }
}

'use server'

import { requireStaff, requireAdmin } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { revalidatePath } from 'next/cache'
import { headers } from 'next/headers'
import { BookingType, EnrollmentStatus, ExamCategory, PaymentStatus, UserStatus, UserRole } from '@prisma/client'
import { AuditAction, createAuditLog } from '@/lib/audit/logger'
import { handleActionError } from '@/lib/staff/errors'
import { getRequestContext } from '@/lib/server/request-context'

export async function bulkUpdateExamBookingStatus(bookingIds: string[], status: PaymentStatus) {
  try {
    await requireStaff()
    if (!bookingIds.length || !status) return { error: 'Invalid parameters.' }

    await prismaUnfiltered.examBooking.updateMany({
      where: { id: { in: bookingIds } },
      data: { status },
    })

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/student/exams', 'page')
    revalidatePath('/staff/reports', 'page')
    return { success: true }
  } catch (error) {
    return { error: handleActionError('bulkUpdateExamBookingStatus', error, 'Failed to update bookings.') }
  }
}

export async function updateExamBooking(
  recordId: string,
  data: {
    courseId?: string
    bookingType?: string
    moduleCode?: string
    examDate?: Date
    score?: number
    result?: string
    status?: PaymentStatus
    attemptType?: string
    isResit?: boolean
    isMigrated?: boolean
    migrationRef?: string
    resultIdToSync?: string
    examCategory?: 'INTERNAL' | 'OFFICIAL_EASA'
    certificateUrl?: string | null
    certificateIssued?: Date | null
    supervisorOverrideJustification?: string
  }
) {
  try {
    const staff = await requireStaff()
    const actualId = recordId.replace('result_', '')
    const isResultId = recordId.startsWith('result_')
    const isSupervisor = ['ADMIN', 'SUPER_ADMIN'].includes(staff.role)

    if (isResultId) {
      const existingResult = await prismaUnfiltered.examResult.findUnique({
        where: { id: actualId },
        select: { resultLocked: true, lockedBy: true, certificateUrl: true, certificateIssued: true },
      })

      if (existingResult?.resultLocked && !isSupervisor) {
        return { error: 'Result is locked and cannot be modified. Contact a supervisor for an override.' }
      }

      if (existingResult?.resultLocked && isSupervisor && !data.supervisorOverrideJustification?.trim()) {
        return { error: 'Supervisor override justification is required to modify a locked result.' }
      }
    }

    const moduleCode = data.moduleCode?.toUpperCase()
    const score = data.score !== undefined && data.score !== null ? data.score : undefined
    const percentage = score !== undefined ? score : undefined
    const passed = score !== undefined ? score >= 75 : undefined
    const grade = score !== undefined
      ? score >= 90 ? 'A' : score >= 80 ? 'B' : score >= 75 ? 'C' : 'F'
      : undefined

    if (isResultId) {
      const updateData: Record<string, unknown> = {
        ...(moduleCode ? { moduleCode } : {}),
        ...(score !== undefined ? { score, maxScore: 100, percentage, passed, grade } : {}),
        ...(data.attemptType ? { attemptType: data.attemptType } : {}),
        ...(data.examCategory ? { examCategory: data.examCategory } : {}),
        ...(data.isMigrated !== undefined ? { 
          migrationRef: data.isMigrated ? (data.migrationRef || 'MANUAL_CORRECTION') : null 
        } : {}),
      }

      if (data.certificateUrl !== undefined || data.certificateIssued !== undefined) {
        updateData.certificateUrl = data.certificateUrl ?? undefined
        updateData.certificateIssued = data.certificateIssued ?? undefined
        if (data.certificateUrl || data.certificateIssued) {
          updateData.resultLocked = true
          updateData.lockedBy = staff.id
          updateData.lockedAt = new Date()
        }
      }

      if (isSupervisor && data.supervisorOverrideJustification) {
        updateData.resultLocked = false
        updateData.lockedBy = null
        updateData.lockedAt = null
      }

      await prismaUnfiltered.examResult.update({
        where: { id: actualId },
        data: updateData,
      })

      const res = await prismaUnfiltered.examResult.findUnique({
        where: { id: actualId },
        select: { userId: true, moduleCode: true }
      })
      if (res && res.moduleCode) {
        const normModule = res.moduleCode.trim()
        const updateRes = await prismaUnfiltered.examBooking.updateMany({
          where: { 
            userId: res.userId, 
            OR: [
              { moduleCode: { equals: normModule, mode: 'insensitive' } },
              { moduleCode: { contains: normModule, mode: 'insensitive' } }
            ]
          },
          data: { 
            ...(data.attemptType ? { attemptType: data.attemptType } : {}),
            ...(data.examCategory ? { examCategory: data.examCategory } : {}),
            ...(data.bookingType ? { bookingType: data.bookingType as BookingType } : {}),
          },
        })
      }
    } else {
      const isResit = data.isResit !== undefined 
        ? data.isResit 
        : (data.attemptType ? data.attemptType.startsWith('RESIT') : undefined)

      await prismaUnfiltered.$transaction(async (tx) => {
        const booking = await tx.examBooking.findUnique({ where: { id: actualId } })
        if (!booking) throw new Error('Booking not found')

        const finalModule = moduleCode || booking.moduleCode || ''

        await tx.examBooking.update({
          where: { id: actualId },
          data: {
            ...(moduleCode ? { moduleCode } : {}),
            ...(data.examDate ? { examDate: data.examDate } : {}),
            ...(data.attemptType ? { attemptType: data.attemptType } : {}),
            ...(data.examCategory ? { examCategory: data.examCategory as ExamCategory } : {}),
            ...(isResit !== undefined ? { isResit } : {}),
            ...(data.bookingType ? { bookingType: data.bookingType as BookingType } : {}),
            ...(!data.isMigrated && (score !== undefined || data.attemptType || data.examCategory || (booking.result?.toUpperCase().includes('MIGRATE') && booking.score != null)) ? { 
              score: score ?? (booking.score != null ? Number(booking.score) : undefined),
              percentage: score ?? (booking.score != null ? Number(booking.score) : undefined),
              result: (score ?? (booking.score != null ? Number(booking.score) : 0)) >= 75 ? 'pass' : 'fail',
              status: PaymentStatus.APPROVED
            } : {}),
            ...(data.isMigrated !== undefined ? { 
              result: data.isMigrated ? 'MIGRATED' : (booking.result === 'MIGRATED' ? 'pass' : booking.result)
            } : {}),
          },
        })

        if (score !== undefined || data.attemptType !== undefined || data.examCategory !== undefined) {
          if (data.resultIdToSync) {
            await tx.examResult.update({
              where: { id: data.resultIdToSync },
              data: { 
                ...(score !== undefined ? { score, maxScore: 100, percentage, passed, grade } : {}),
                attemptType: data.attemptType || booking.attemptType,
                examCategory: (data.examCategory as ExamCategory) || booking.examCategory,
                moduleCode: finalModule,
                migrationRef: data.isMigrated !== undefined 
                  ? (data.isMigrated ? (data.migrationRef || 'MANUAL_CORRECTION') : null)
                  : undefined
              },
            })
          } else {
            const existingResult = await tx.examResult.findFirst({
              where: {
                userId: booking.userId,
                moduleCode: finalModule,
              },
              orderBy: { createdAt: 'desc' }
            })

            if (existingResult) {
              await tx.examResult.update({
                where: { id: existingResult.id },
                data: { 
                  ...(score !== undefined ? { score, maxScore: 100, percentage, passed, grade } : {}),
                  attemptType: data.attemptType || booking.attemptType,
                  examCategory: (data.examCategory as ExamCategory) || booking.examCategory,
                  migrationRef: data.isMigrated !== undefined 
                    ? (data.isMigrated ? (data.migrationRef || 'MANUAL_CORRECTION') : null)
                    : undefined
                },
              })
            } else {
              await tx.examResult.create({
                data: {
                  userId: booking.userId,
                  moduleCode: finalModule,
                  score: score ?? 0,
                  maxScore: 100,
                  percentage: score ?? 0,
                  passed: (score ?? 0) >= 75,
                  grade: grade || 'F',
                  attemptType: data.attemptType || booking.attemptType,
                  examCategory: data.examCategory as ExamCategory || booking.examCategory,
                  migrationRef: data.isMigrated ? (data.migrationRef || 'MANUAL_CORRECTION') : undefined,
                  sourceNotes: 'Auto-created from booking update',
                },
              })
            }
          }

          if (score !== undefined) {
            await tx.examAttendance.upsert({
              where: { bookingId: actualId },
              update: { status: 'PRESENT' },
              create: {
                userId: booking.userId,
                bookingId: actualId,
                status: 'PRESENT',
                attendanceDate: booking.examDate || new Date(),
                recordedBy: 'system',
                eventId: booking.eventId,
                examId: booking.examId,
                examComponentId: booking.examComponentId,
                classId: booking.courseId ? undefined : undefined,
              }
            })
          }
        }
      }, {
        timeout: 30000
      })
    }

    let targetUserId = ''
    let targetStudentName = 'unknown'
    if (isResultId) {
      const res = await prismaUnfiltered.examResult.findUnique({ where: { id: actualId }, select: { userId: true } })
      targetUserId = res?.userId || ''
    } else {
      const b = await prismaUnfiltered.examBooking.findUnique({ where: { id: actualId }, select: { userId: true } })
      targetUserId = b?.userId || ''
    }
    if (targetUserId) {
      const profile = await prismaUnfiltered.profile.findUnique({ where: { userId: targetUserId }, select: { firstName: true, lastName: true } })
      if (profile) targetStudentName = `${profile.firstName} ${profile.lastName}`
    }

    revalidatePath('/staff/exams')
    revalidatePath('/student/exams')
    if (targetUserId) {
      revalidatePath(`/staff/students/${targetUserId}`)
    }

    const ctx = await getRequestContext()
    await createAuditLog({
      userId: staff.id,
      action: AuditAction.UPDATE,
      entity: isResultId ? 'ExamResult' : 'ExamBooking',
      entityId: actualId,
      description: `Updated ${isResultId ? 'exam result' : 'exam booking'} record for student ${targetStudentName}.${isResultId && data.supervisorOverrideJustification ? ` Supervisor override: ${data.supervisorOverrideJustification}` : ''}`,
      changes: {
        recordId,
        targetUserId,
        fields: Object.keys(data),
        moduleCode,
        score,
        result: data.result,
        status: data.status,
        attemptType: data.attemptType,
        examCategory: data.examCategory,
        resultLocked: isResultId ? (data.supervisorOverrideJustification ? false : undefined) : undefined,
        supervisorOverride: data.supervisorOverrideJustification || undefined,
        certificateUrl: data.certificateUrl,
        certificateIssued: data.certificateIssued?.toISOString?.() || data.certificateIssued,
      },
      ipAddress: ctx.ipAddress ?? undefined,
      userAgent: ctx.userAgent ?? undefined,
    })
    return { success: true }
  } catch (error) {
    return { error: handleActionError('updateExamResult', error, 'Failed to update record.') }
  }
}

export async function createExamRecord(data: {
  userId: string
  bookingType: 'INDIVIDUAL' | 'TWIN_PACK' | 'FOUR_PACK'
  examDate: string
  attemptType?: string
  examCategory?: 'INTERNAL' | 'OFFICIAL_EASA'
  notes?: string
  isPending?: boolean
  entries: { 
    courseId?: string; 
    examComponentId?: string; 
    moduleCode: string; 
    score?: number;
    resultOverride?: string;
  }[]
}) {
  try {
    const staff = await requireStaff()
    const { userId, bookingType, examDate, attemptType, examCategory, notes, entries, isPending } = data

    const user = await prismaUnfiltered.user.findUnique({ where: { id: userId } })
    if (!user) return { error: 'Student not found.' }

    const bookingGroupRef = entries.length > 1 ? `STAFF_MANUAL_${Date.now()}` : undefined
    const affectedBookingIds: string[] = []

    await prismaUnfiltered.$transaction(async (tx) => {
      for (const entry of entries) {
        let finalModuleCode = entry.moduleCode.toUpperCase().trim()
        if (entry.courseId && !entry.moduleCode) {
          const course = await tx.course.findUnique({ where: { id: entry.courseId } })
          if (course) finalModuleCode = course.code.toUpperCase().trim()
        }

        const targetAttemptType = attemptType || 'FIRST'

        let result: string | undefined
        let percentage: number | undefined

        if (isPending) {
          result = undefined
          percentage = undefined
        } else if (entry.resultOverride && entry.resultOverride !== 'auto') {
          result = entry.resultOverride
          if (entry.score !== undefined) percentage = entry.score
        } else if (entry.score !== undefined) {
          percentage = entry.score
          result = entry.score >= 75 ? 'pass' : 'fail'
        }

        const bookingStatus = isPending ? PaymentStatus.PENDING : PaymentStatus.APPROVED

        const existingBooking = await tx.examBooking.findFirst({
          where: {
            userId,
            moduleCode: finalModuleCode,
            attemptType: targetAttemptType,
            deletedAt: null,
          }
        })

        let finalBookingId = existingBooking?.id

        if (existingBooking) {
          await tx.examBooking.update({
            where: { id: existingBooking.id },
            data: {
              courseId: entry.courseId || existingBooking.courseId,
              examComponentId: entry.examComponentId || existingBooking.examComponentId,
              examDate: new Date(examDate),
              status: bookingStatus,
              result,
              score: entry.score ?? existingBooking.score,
              percentage: percentage ?? existingBooking.percentage,
              examCategory: examCategory || existingBooking.examCategory,
              bookingGroupRef: bookingGroupRef || existingBooking.bookingGroupRef,
            }
          })
          affectedBookingIds.push(existingBooking.id)
        } else {
          const newBooking = await tx.examBooking.create({
            data: {
              userId,
              courseId: entry.courseId,
              examComponentId: entry.examComponentId,
              moduleCode: finalModuleCode,
              examDate: new Date(examDate),
              amountPaid: 0,
              status: bookingStatus,
              bookingType,
              attemptType: targetAttemptType,
              result,
              score: entry.score,
              percentage,
              examCategory: examCategory || 'OFFICIAL_EASA',
              bookingGroupRef,
            }
          })
          finalBookingId = newBooking.id
          affectedBookingIds.push(newBooking.id)
        }

        if (entry.score !== undefined && finalBookingId) {
          await tx.examAttendance.upsert({
            where: { bookingId: finalBookingId },
            update: { status: 'PRESENT' },
            create: {
              userId,
              bookingId: finalBookingId,
              status: 'PRESENT',
              attendanceDate: new Date(examDate),
              recordedBy: staff.id,
            }
          })
        }

        if (result && ['pass', 'fail'].includes(result)) {
          const scoreVal = entry.score ?? (result === 'pass' ? 75 : 0)
          const grade = (percentage ?? 0) >= 90 ? 'A' : (percentage ?? 0) >= 80 ? 'B' : (percentage ?? 0) >= 75 ? 'C' : 'F'

          const existingResult = await tx.examResult.findFirst({
            where: { userId, moduleCode: finalModuleCode, attemptType: targetAttemptType }
          })

          if (existingResult) {
            await tx.examResult.update({
              where: { id: existingResult.id },
              data: {
                score: scoreVal,
                percentage,
                passed: result === 'pass',
                grade,
                examCategory: examCategory || 'OFFICIAL_EASA',
                sourceNotes: notes || 'Manually updated by staff',
              }
            })
          } else {
            await tx.examResult.create({
              data: {
                userId,
                moduleCode: finalModuleCode,
                score: scoreVal,
                maxScore: 100,
                percentage,
                passed: result === 'pass',
                grade,
                attemptType: targetAttemptType,
                examCategory: examCategory || 'OFFICIAL_EASA',
                sourceNotes: notes || 'Manually added by staff',
              }
            })
          }
        }
      }
    })

    revalidatePath('/staff/exams')
    revalidatePath('/student/exams')
    revalidatePath(`/staff/students/${userId}`)
    revalidatePath(`/staff/users/${userId}`)
    revalidatePath('/staff/reports')

    const studentProfile = await prismaUnfiltered.profile.findUnique({ where: { userId }, select: { firstName: true, lastName: true } })
    const studentName = studentProfile ? `${studentProfile.firstName} ${studentProfile.lastName}` : user.email

    const ctx = await getRequestContext()
    await createAuditLog({
      userId: staff.id,
      action: AuditAction.CREATE,
      entity: 'ExamBooking',
      entityId: affectedBookingIds[0],
      description: `Created or updated ${affectedBookingIds.length} manual exam record(s) for student ${studentName}.`,
      changes: {
        studentId: userId,
        bookingIds: affectedBookingIds,
        bookingType,
        attemptType: attemptType || 'FIRST',
        examCategory: examCategory || 'OFFICIAL_EASA',
        isPending: Boolean(isPending),
        moduleCodes: entries.map((entry) => entry.moduleCode?.toUpperCase().trim()).filter(Boolean),
      },
      ipAddress: ctx.ipAddress ?? undefined,
      userAgent: ctx.userAgent ?? undefined,
    })

    return { success: true }
  } catch (error) {
    return { error: handleActionError('createExamRecord', error, 'Failed to create record.') }
  }
}

export async function deleteExamRecord(id: string) {
  try {
    const admin = await requireAdmin()

    const actualId = id.replace('result_', '')
    const isResultId = id.startsWith('result_')
    let existing:
      | { id: string; certificateUrl: string | null; deletedAt: Date | null }
      | { id: string; deletedAt: Date | null }
      | null = null

    if (isResultId) {
      existing = await prismaUnfiltered.examResult.findUnique({ where: { id: actualId } })
    } else {
      existing = await prismaUnfiltered.examBooking.findUnique({ where: { id: actualId } })
    }

    if (!existing) return { error: 'Record not found.' }
    if (existing.deletedAt) return { error: 'Record already deleted.' }

    if (isResultId && 'certificateUrl' in existing && existing.certificateUrl) {
      return { error: 'Cannot delete an issued exam result. Contact a SUPER_ADMIN if correction is required.' }
    }

    if (isResultId) {
      await prismaUnfiltered.examResult.update({
        where: { id: actualId },
        data: { deletedAt: new Date() },
      })
    } else {
      await prismaUnfiltered.examBooking.update({
        where: { id: actualId },
        data: { deletedAt: new Date() },
      })
    }

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/staff/reports', 'page')
    const ctx = await getRequestContext()
    await createAuditLog({
      userId: admin.id,
      action: AuditAction.DELETE,
      entity: isResultId ? 'ExamResult' : 'ExamBooking',
      entityId: actualId,
      description: `Soft-deleted ${isResultId ? 'exam result' : 'exam booking'} record ${actualId}.`,
      changes: { ...existing, deletedAt: new Date().toISOString() },
      ipAddress: ctx.ipAddress ?? undefined,
      userAgent: ctx.userAgent ?? undefined,
    })
    return { success: true }
  } catch (error) {
    return { error: handleActionError('deleteExamRecord', error, 'Failed to delete record.') }
  }
}

export async function searchStudents(query: string) {
  try {
    await requireStaff()

    if (!query || query.length < 2) return { students: [] }

    const users = await prismaUnfiltered.user.findMany({
      where: {
        role: { in: [UserRole.STUDENT, UserRole.APPLICANT] },
        OR: [
          { email: { contains: query, mode: 'insensitive' } },
          { profile: { firstName: { contains: query, mode: 'insensitive' } } },
          { profile: { lastName: { contains: query, mode: 'insensitive' } } },
          { studentProfile: { studentId: { contains: query, mode: 'insensitive' } } },
        ],
      },
      include: {
        profile: { select: { firstName: true, lastName: true } },
        studentProfile: { select: { studentId: true } },
      },
      take: 10,
    })

    return {
      students: users.map((u) => ({
        id: u.id,
        email: u.email,
        firstName: u.profile?.firstName || '',
        lastName: u.profile?.lastName || '',
        studentId: u.studentProfile?.studentId || '',
      })),
    }
  } catch (error) {
    handleActionError('searchStudents', error, 'Failed to search students.')
    return { students: [] }
  }
}

export async function getAvailableModules() {
  try {
    await requireStaff()
    const courses = await prismaUnfiltered.course.findMany({
      select: { id: true, code: true, name: true },
      orderBy: { code: 'asc' },
    })
    const components = await prismaUnfiltered.examComponent.findMany({
      select: { 
        id: true, 
        code: true, 
        name: true, 
        type: true,
        courseId: true,
        course: { select: { code: true, name: true } }
      },
      orderBy: { code: 'asc' },
    })

    const courseOptions = courses.map(c => ({
      id: c.id,
      courseId: c.id,
      code: c.code,
      name: `${c.code}: ${c.name} (General)`,
      moduleCode: c.code,
      isComponent: false
    }))

    const componentOptions = components.map(c => ({
      id: c.id,
      courseId: c.courseId,
      code: c.code,
      name: `${c.course.code}: ${c.name} (${c.type})`,
      moduleCode: c.course.code,
      isComponent: true
    }))

    return [...courseOptions, ...componentOptions].sort((a, b) => a.code.localeCompare(b.code))
  } catch (error) {
    handleActionError('getAvailableModules', error, 'Failed to load modules.')
    return []
  }
}

export async function bulkUpdateExamCategory(ids: string[], category: 'INTERNAL' | 'OFFICIAL_EASA') {
  try {
    await requireStaff()

    if (!ids || ids.length === 0) {
      return { error: 'No records selected' }
    }

    const cleanIds = ids.map(id => id.replace('result_', ''))

    const affectedBookings = await prismaUnfiltered.examBooking.findMany({
      where: { id: { in: cleanIds } },
      select: { id: true, userId: true, moduleCode: true }
    })

    const affectedResults = await prismaUnfiltered.examResult.findMany({
      where: { id: { in: cleanIds } },
      select: { id: true, userId: true, moduleCode: true }
    })

    const bookingIds = new Set(affectedBookings.map(b => b.id))
    const resultIds = new Set(affectedResults.map(r => r.id))

    const pairs = new Set<string>()
    affectedBookings.forEach(b => {
      if (b.userId && b.moduleCode) pairs.add(`${b.userId}:${b.moduleCode.toUpperCase()}`)
    })
    affectedResults.forEach(r => {
      if (r.userId && r.moduleCode) pairs.add(`${r.userId}:${r.moduleCode.toUpperCase()}`)
    })

    for (const pair of Array.from(pairs)) {
      const [uId, mCode] = pair.split(':')

      const relatedBookings = await prismaUnfiltered.examBooking.findMany({
        where: { 
          userId: uId, 
          moduleCode: { equals: mCode, mode: 'insensitive' } 
        },
        select: { id: true }
      })
      relatedBookings.forEach(b => bookingIds.add(b.id))

      const relatedResults = await prismaUnfiltered.examResult.findMany({
        where: { 
          userId: uId, 
          moduleCode: { equals: mCode, mode: 'insensitive' } 
        },
        select: { id: true }
      })
      relatedResults.forEach(r => resultIds.add(r.id))
    }

    const [bookingCount, resultCount] = await prismaUnfiltered.$transaction([
      prismaUnfiltered.examBooking.updateMany({
        where: { id: { in: Array.from(bookingIds) } },
        data: { examCategory: category },
      }),
      prismaUnfiltered.examResult.updateMany({
        where: { id: { in: Array.from(resultIds) } },
        data: { examCategory: category },
      }),
    ])

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/staff/reports', 'page')
    return { success: true }
  } catch (error) {
    return { error: handleActionError('bulkUpdateExamCategory', error, 'Failed to update records.') }
  }
}

'use server'

import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { revalidatePath } from 'next/cache'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { getRequestContext } from '@/lib/server/request-context'
import { getRegistrationConfig, getExamsConfig } from '@/lib/settings'

const DISMISSABLE_TITLES = new Set([
  'Pending Payments >7 Days',
  'Fraud Referrals Pending Review',
  'Expiring Exam Bundles',
  'Supabase Mirror Backlog',
  'Email Delivery Failures',
  'Internal Exam Reports Pending',
])

async function createIfMissing(userId: string, data: {
  type: 'CRITICAL' | 'WARNING' | 'ERROR' | 'INFO'
  title: string
  message: string
  linkUrl?: string
  linkText?: string
}) {
  const existing = await prismaUnfiltered.notification.findFirst({
    where: {
      userId,
      title: data.title,
      isRead: false,
    },
  })

  if (existing) {
    // Update message/link if the condition still applies but notification exists
    await prismaUnfiltered.notification.update({
      where: { id: existing.id },
      data: {
        message: data.message,
        linkUrl: data.linkUrl || existing.linkUrl,
        linkText: data.linkText || existing.linkText,
      },
    })
    return
  }

  await prismaUnfiltered.notification.create({
    data: {
      userId,
      type: data.type,
      title: data.title,
      message: data.message,
      linkUrl: data.linkUrl,
      linkText: data.linkText,
    },
  })
}

async function dismissIfExists(userId: string, title: string) {
  const existing = await prismaUnfiltered.notification.findFirst({
    where: { userId, title, isRead: false },
  })

  if (existing) {
    await prismaUnfiltered.notification.update({
      where: { id: existing.id },
      data: { isRead: true, readAt: new Date() },
    })
  }
}

export async function dismissStaffNotification(notificationId: string) {
  try {
    await prismaUnfiltered.notification.update({
      where: { id: notificationId },
      data: { isRead: true, readAt: new Date() },
    })
    return { success: true }
  } catch {
    return { error: 'Failed to dismiss notification' }
  }
}

export async function ensureSystemNotifications() {
  try {
    const user = await requireStaff()
    const [registrationConfig, examsConfig] = await Promise.all([
      getRegistrationConfig(),
      getExamsConfig(),
    ])

    const now = new Date()
    const todayMinus7 = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
    const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000)
    const sevenDaysOut = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000)

    const [
      pendingPayments,
      overdueDsr,
      failingFraud,
      expiringBundles,
      mirrorBacklog,
      emailFailures24h,
      pendingExamReports,
    ] = await Promise.all([
      prismaUnfiltered.payment.count({
        where: { status: 'PENDING', createdAt: { lt: todayMinus7 } },
      }).catch(() => 0),

      prismaUnfiltered.dataSubjectRequest.count({
        where: {
          dueBy: { lt: now },
          status: { in: ['RECEIVED', 'IN_PROGRESS', 'AWAITING_USER'] },
        },
      }).catch(() => 0),

      prismaUnfiltered.referral.count({
        where: { fraudScore: { gte: 50 }, reviewedAt: null },
      }).catch(() => 0),

      prismaUnfiltered.examBundle.count({
        where: {
          validUntil: { gte: tomorrow, lte: sevenDaysOut },
          status: 'ACTIVE',
        },
      }).catch(() => 0),

      prismaUnfiltered.fileUpload.count({
        where: {
          mirroredAt: null,
          supabasePath: { not: null },
          createdAt: { lt: new Date(now.getTime() - 24 * 60 * 60 * 1000) },
        },
      }).catch(() => 0),

      prismaUnfiltered.emailDelivery.count({
        where: {
          status: 'FAILED',
          createdAt: { gte: new Date(now.getTime() - 24 * 60 * 60 * 1000) },
        },
      }).catch(() => 0),

      prismaUnfiltered.internalExamReport.count({
        where: { status: 'PENDING' },
      }).catch(() => 0),
    ])

    // ── CRITICAL (non-dismissable) ──────────────────────────────────────

    // 1. Registration closed
    if (!registrationConfig.isOpen) {
      await createIfMissing(user.id, {
        type: 'CRITICAL',
        title: 'Registration Closed',
        message:
          'Training programs and new registrations are currently paused on the public site.',
        linkUrl: '/staff/settings?tab=general',
        linkText: 'Manage Settings',
      })
    } else {
      await dismissIfExists(user.id, 'Registration Closed')
    }

    // 2. Exam bookings closed
    if (!examsConfig.isOpen) {
      await createIfMissing(user.id, {
        type: 'CRITICAL',
        title: 'Exam Bookings Closed',
        message:
          'Public exam booking and enrollment are currently disabled.',
        linkUrl: '/staff/settings?tab=general',
        linkText: 'Manage Settings',
      })
    } else {
      await dismissIfExists(user.id, 'Exam Bookings Closed')
    }

    // 3. Overdue GDPR DSRs (legal deadline)
    if (overdueDsr > 0) {
      await createIfMissing(user.id, {
        type: 'CRITICAL',
        title: 'GDPR Requests Overdue',
        message: `${overdueDsr} data subject request${overdueDsr === 1 ? '' : 's'} past the 30-day SLA.`,
        linkUrl: '/staff/gdpr',
        linkText: 'View DSR Queue',
      })
    } else {
      await dismissIfExists(user.id, 'GDPR Requests Overdue')
    }

    // 4. Email delivery failures >= 10 in 24h
    if (emailFailures24h >= 10) {
      await createIfMissing(user.id, {
        type: 'CRITICAL',
        title: 'Email Delivery Failures',
        message: `${emailFailures24h} emails failed to deliver in the last 24 hours.`,
        linkUrl: '/staff/settings?tab=email-delivery',
        linkText: 'View Email Log',
      })
    } else if (emailFailures24h > 0 && emailFailures24h < 10) {
      await dismissIfExists(user.id, 'Email Delivery Failures')
    }

    // ── DISMISSABLE ─────────────────────────────────────────────────────

    // 5. Pending payments >7 days
    if (pendingPayments > 0) {
      await createIfMissing(user.id, {
        type: pendingPayments > 10 ? 'WARNING' : 'INFO',
        title: 'Pending Payments >7 Days',
        message: `${pendingPayments} payment${pendingPayments === 1 ? '' : 's'} awaiting reconciliation for over 7 days.`,
        linkUrl: '/staff/payments?status=PENDING',
        linkText: 'Review Payments',
      })
    } else {
      await dismissIfExists(user.id, 'Pending Payments >7 Days')
    }

    // 6. Fraud-flagged referrals
    if (failingFraud > 0) {
      await createIfMissing(user.id, {
        type: 'WARNING',
        title: 'Fraud Referrals Pending Review',
        message: `${failingFraud} referral${failingFraud === 1 ? '' : 's'} flagged for fraud (score ≥ 50).`,
        linkUrl: '/staff/referrals?minFraud=50',
        linkText: 'Review Referrals',
      })
    } else {
      await dismissIfExists(user.id, 'Fraud Referrals Pending Review')
    }

    // 7. Expiring bundles
    if (expiringBundles > 0) {
      await createIfMissing(user.id, {
        type: 'INFO',
        title: 'Expiring Exam Bundles',
        message: `${expiringBundles} exam bundle${expiringBundles === 1 ? '' : 's'} expiring this week.`,
        linkUrl: '/staff/exams?filter=expiring',
        linkText: 'View Bundles',
      })
    } else {
      await dismissIfExists(user.id, 'Expiring Exam Bundles')
    }

    // 8. Mirror backlog
    if (mirrorBacklog > 0) {
      await createIfMissing(user.id, {
        type: mirrorBacklog > 100 ? 'WARNING' : 'INFO',
        title: 'Supabase Mirror Backlog',
        message: `${mirrorBacklog} file${mirrorBacklog === 1 ? '' : 's'} not yet mirrored to Supabase.`,
        linkUrl: '/staff/admin/permissions',
        linkText: 'View Details',
      })
    } else {
      await dismissIfExists(user.id, 'Supabase Mirror Backlog')
    }

    // 9. Internal exam reports pending
    if (pendingExamReports > 0) {
      await createIfMissing(user.id, {
        type: pendingExamReports >= 5 ? 'WARNING' : 'INFO',
        title: 'Internal Exam Reports Pending',
        message: `${pendingExamReports} internal exam report${pendingExamReports === 1 ? '' : 's'} awaiting review.`,
        linkUrl: '/staff/exams/internal?view=operations',
        linkText: 'Review Reports',
      })
    } else {
      await dismissIfExists(user.id, 'Internal Exam Reports Pending')
    }

    return { success: true }
  } catch (error) {
    return { error: 'Failed to ensure system notifications' }
  }
}

'use server'

import { requireStaff, requireAdmin } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { revalidatePath } from 'next/cache'
import { Prisma } from '@prisma/client'
import { PaymentStatus } from '@prisma/client'
import { AuditAction, createAuditLog } from '@/lib/audit/logger'
import { handleActionError } from '@/lib/staff/errors'
import { getRequestContext } from '@/lib/server/request-context'

type AttemptType = 'FIRST' | 'RESIT_1'

type ResultOverride =
  | { kind: 'auto' }
  | { kind: 'explicit'; value: string }

type ExamEntry = {
  courseId?: string
  examComponentId?: string
  moduleCode: string
  score?: number
  resultOverride?: ResultOverride
}

type BookingInput = {
  userId: string
  courseId?: string
  examComponentId?: string
  moduleCode: string
  examDate: Date
  bookingType: 'INDIVIDUAL' | 'TWIN_PACK' | 'FOUR_PACK'
  attemptType: AttemptType
  bookingStatus: typeof PaymentStatus.PENDING | typeof PaymentStatus.APPROVED
  result?: 'pass' | 'fail'
  score?: number
  percentage?: number | undefined
  examCategory?: 'INTERNAL' | 'OFFICIAL_EASA'
  bookingGroupRef?: string
  staffId: string
}

type ResultInput = {
  userId: string
  moduleCode: string
  attemptType: AttemptType
  scoreVal: number
  percentage: number | undefined
  passed: boolean
  grade: string
  examCategory?: 'INTERNAL' | 'OFFICIAL_EASA'
  notes?: string
  existingNotes?: string
  override: boolean
}

function normalizeResultOverride(override?: ResultOverride): ResultOverride {
  if (!override || override.kind === 'auto') return { kind: 'auto' }
  return { kind: 'explicit', value: override.value }
}

function resolveAttemptType(raw?: string): AttemptType {
  const normalized = (raw || 'FIRST').toUpperCase().trim()
  if (normalized === 'RESIT_1') return 'RESIT_1'
  return 'FIRST'
}

function validateExamDate(raw: string): Date {
  const parsed = new Date(raw)
  if (Number.isNaN(parsed.getTime())) {
    throw new Error('Invalid exam date format. Use a valid ISO date string.')
  }
  return parsed
}

function validateScore(score?: number): void {
  if (score !== undefined && (score < 0 || score > 100)) {
    throw new Error('Score must be between 0 and 100.')
  }
}

async function resolveModuleCode(tx: Prisma.TransactionClient, entry: ExamEntry): Promise<string> {
  let finalModuleCode = entry.moduleCode.toUpperCase().trim()
  if (entry.courseId && !entry.moduleCode) {
    const course = await tx.course.findUnique({ where: { id: entry.courseId } })
    if (course) finalModuleCode = course.code.toUpperCase().trim()
  }
  return finalModuleCode
}

function computeResult(entry: ExamEntry, isPending: boolean | undefined): { result?: 'pass' | 'fail'; percentage?: number; override: boolean } {
  if (isPending) return { override: false }
  const override = normalizeResultOverride(entry.resultOverride)
  if (override.kind === 'explicit') {
    return { result: override.value as 'pass' | 'fail', percentage: entry.score, override: true }
  }
  if (entry.score !== undefined) {
    const percentage = entry.score
    const result = entry.score >= 75 ? 'pass' : 'fail'
    return { result, percentage, override: false }
  }
  return { override: false }
}

async function upsertExamBooking(tx: Prisma.TransactionClient, input: BookingInput): Promise<string> {
  const {
    userId, courseId, examComponentId, moduleCode, examDate, bookingType,
    attemptType, bookingStatus, result, score, percentage, examCategory,
    bookingGroupRef, staffId
  } = input

  const existing = await tx.examBooking.findFirst({
    where: { userId, moduleCode, attemptType, deletedAt: null },
  })

  if (existing) {
    await tx.examBooking.update({
      where: { id: existing.id },
      data: {
        courseId: courseId || existing.courseId,
        examComponentId: examComponentId || existing.examComponentId,
        examDate,
        status: bookingStatus,
        result,
        score: score ?? existing.score,
        percentage: percentage ?? existing.percentage,
        examCategory: examCategory || existing.examCategory,
        bookingGroupRef: bookingGroupRef || existing.bookingGroupRef,
      },
    })
    return existing.id
  }

  const created = await tx.examBooking.create({
    data: {
      userId,
      courseId,
      examComponentId,
      moduleCode,
      examDate,
      amountPaid: 0,
      status: bookingStatus,
      bookingType,
      attemptType,
      result,
      score,
      percentage,
      examCategory: examCategory || 'OFFICIAL_EASA',
      bookingGroupRef,
    },
  })
  return created.id
}

async function upsertExamAttendance(tx: Prisma.TransactionClient, bookingId: string, userId: string, examDate: Date, staffId: string): Promise<void> {
  await tx.examAttendance.upsert({
    where: { bookingId },
    update: { status: 'PRESENT' },
    create: {
      userId,
      bookingId,
      status: 'PRESENT',
      attendanceDate: examDate,
      recordedBy: staffId,
    },
  })
}

function computeGrade(percentage: number | undefined): string {
  const p = percentage ?? 0
  if (p >= 90) return 'A'
  if (p >= 80) return 'B'
  if (p >= 75) return 'C'
  return 'F'
}

async function upsertExamResult(tx: Prisma.TransactionClient, input: ResultInput): Promise<void> {
  const { userId, moduleCode, attemptType, scoreVal, percentage, passed, grade, examCategory, notes, existingNotes, override } = input

  const existing = await tx.examResult.findFirst({
    where: { userId, moduleCode, attemptType },
  })

  if (existing) {
    await tx.examResult.update({
      where: { id: existing.id },
      data: {
        score: scoreVal,
        percentage,
        passed,
        grade,
        examCategory: examCategory || 'OFFICIAL_EASA',
        sourceNotes: notes || existingNotes || 'Manually updated by staff',
      },
    })
  } else {
    await tx.examResult.create({
      data: {
        userId,
        moduleCode,
        score: scoreVal,
        maxScore: 100,
        percentage,
        passed,
        grade,
        attemptType,
        examCategory: examCategory || 'OFFICIAL_EASA',
        sourceNotes: notes || 'Manually added by staff',
      },
    })
  }
}

export async function createExamRecord(data: {
  userId: string
  bookingType: 'INDIVIDUAL' | 'TWIN_PACK' | 'FOUR_PACK'
  examDate: string
  attemptType?: string
  examCategory?: 'INTERNAL' | 'OFFICIAL_EASA'
  notes?: string
  isPending?: boolean
  entries: ExamEntry[]
}) {
  try {
    const staff = await requireStaff()
    const { userId, bookingType, examDate, attemptType, examCategory, notes, entries, isPending } = data

    const user = await prismaUnfiltered.user.findUnique({ where: { id: userId } })
    if (!user) return { error: 'Student not found.' }

    const parsedExamDate = validateExamDate(examDate)
    const targetAttemptType = resolveAttemptType(attemptType)

    for (const entry of entries) {
      validateScore(entry.score)
    }

    const bookingGroupRef = entries.length > 1 ? `STAFF_MANUAL_${Date.now()}` : undefined
    const affectedBookingIds: string[] = []
    const overrideCount = { value: 0 }

    await prismaUnfiltered.$transaction(async (tx) => {
      for (const entry of entries) {
        const finalModuleCode = await resolveModuleCode(tx, entry)
        const { result, percentage, override } = computeResult(entry, isPending)
        const bookingStatus = isPending ? PaymentStatus.PENDING : PaymentStatus.APPROVED

        if (override) overrideCount.value++

        const bookingId = await upsertExamBooking(tx, {
          userId,
          courseId: entry.courseId,
          examComponentId: entry.examComponentId,
          moduleCode: finalModuleCode,
          examDate: parsedExamDate,
          bookingType,
          attemptType: targetAttemptType,
          bookingStatus,
          result,
          score: entry.score,
          percentage,
          examCategory: examCategory || 'OFFICIAL_EASA',
          bookingGroupRef,
          staffId: staff.id,
        })
        affectedBookingIds.push(bookingId)

        if (entry.score !== undefined && bookingId) {
          await upsertExamAttendance(tx, bookingId, userId, parsedExamDate, staff.id)
        }

        if (result && ['pass', 'fail'].includes(result)) {
          const scoreVal = entry.score ?? (result === 'pass' ? 75 : 0)
          const grade = computeGrade(percentage)
          await upsertExamResult(tx, {
            userId,
            moduleCode: finalModuleCode,
            attemptType: targetAttemptType,
            scoreVal,
            percentage,
            passed: result === 'pass',
            grade,
            examCategory: examCategory || 'OFFICIAL_EASA',
            notes,
            override,
          })
        }
      }
    })

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/student/exams', 'page')
    revalidatePath(`/staff/students/${userId}`, 'page')
    revalidatePath(`/staff/users/${userId}`, 'page')
    revalidatePath('/staff/reports', 'page')

    const studentProfile = await prismaUnfiltered.profile.findUnique({ where: { userId }, select: { firstName: true, lastName: true } })
    const studentName = studentProfile ? `${studentProfile.firstName} ${studentProfile.lastName}` : user.email

    const ctx = await getRequestContext()
    await createAuditLog({
      userId: staff.id,
      action: AuditAction.CREATE,
      entity: 'ExamBooking',
      entityId: affectedBookingIds[0],
      description: `Created or updated ${affectedBookingIds.length} manual exam record(s) for student ${studentName}.${overrideCount.value > 0 ? ` ${overrideCount.value} record(s) used manual result override.` : ''}`,
      changes: {
        studentId: userId,
        bookingIds: affectedBookingIds,
        bookingType,
        attemptType: targetAttemptType,
        examCategory: examCategory || 'OFFICIAL_EASA',
        isPending: Boolean(isPending),
        moduleCodes: entries.map((entry) => entry.moduleCode?.toUpperCase().trim()).filter(Boolean),
        overridesApplied: overrideCount.value,
      },
      ipAddress: ctx.ipAddress ?? undefined,
      userAgent: ctx.userAgent ?? undefined,
    })

    return { success: true }
  } catch (error) {
    return { error: handleActionError('createExamRecord', error, 'Failed to create record.') }
  }
}

export async function deleteExamRecord(id: string) {
  try {
    const admin = await requireAdmin()

    const actualId = id.replace('result_', '')
    const isResultId = id.startsWith('result_')
    let existing:
      | { id: string; certificateUrl: string | null; deletedAt: Date | null }
      | { id: string; deletedAt: Date | null }
      | null = null

    if (isResultId) {
      existing = await prismaUnfiltered.examResult.findUnique({ where: { id: actualId } })
    } else {
      existing = await prismaUnfiltered.examBooking.findUnique({ where: { id: actualId } })
    }

    if (!existing) return { error: 'Record not found.' }
    if (existing.deletedAt) return { error: 'Record already deleted.' }

    if (isResultId && 'certificateUrl' in existing && existing.certificateUrl) {
      return { error: 'Cannot delete an issued exam result. Contact a SUPER_ADMIN if correction is required.' }
    }

    if (isResultId) {
      await prismaUnfiltered.examResult.update({
        where: { id: actualId },
        data: { deletedAt: new Date() },
      })
    } else {
      await prismaUnfiltered.examBooking.update({
        where: { id: actualId },
        data: { deletedAt: new Date() },
      })
    }

    revalidatePath('/staff/exams', 'page')
    revalidatePath('/staff/reports', 'page')
    const ctx = await getRequestContext()
    await createAuditLog({
      userId: admin.id,
      action: AuditAction.DELETE,
      entity: isResultId ? 'ExamResult' : 'ExamBooking',
      entityId: actualId,
      description: `Soft-deleted ${isResultId ? 'exam result' : 'exam booking'} record ${actualId}.`,
      changes: { ...existing, deletedAt: new Date().toISOString() },
      ipAddress: ctx.ipAddress ?? undefined,
      userAgent: ctx.userAgent ?? undefined,
    })
    return { success: true }
  } catch (error) {
    return { error: handleActionError('deleteExamRecord', error, 'Failed to delete record.') }
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Plus, Pencil, Trash2, Database, Loader2, ArrowRight } from 'lucide-react'
import Link from 'next/link'

interface Bank {
  id: string
  name: string
  description: string | null
  applicableProgrammes: string[]
  isActive: boolean
  _count: { questions: number; sessions: number }
  createdAt: string
}

export default function BankList() {
  const [banks, setBanks] = useState<Bank[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [form, setForm] = useState({ name: '', description: '', isActive: true })
  const [saving, setSaving] = useState(false)

  const fetchBanks = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/admissions/aptitude/banks')
      const json = await res.json()
      if (json.data) setBanks(json.data)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchBanks()
  }, [fetchBanks])

  const handleCreate = async () => {
    if (!form.name) return
    setSaving(true)
    try {
      const res = await fetch('/api/staff/admissions/aptitude/banks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      })
      if (res.ok) {
        setForm({ name: '', description: '', isActive: true })
        setShowForm(false)
        fetchBanks()
      }
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this test bank?')) return
    await fetch(`/api/staff/admissions/aptitude/banks/${id}`, { method: 'DELETE' })
    fetchBanks()
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-black text-slate-800 dark:text-white">Question Banks</h2>
        <button
          onClick={() => setShowForm(true)}
          className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2 text-sm font-bold text-white transition-all hover:bg-blue-700"
        >
          <Plus className="h-4 w-4" /> New Bank
        </button>
      </div>

      {showForm && (
        <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <h3 className="mb-4 font-bold text-slate-800 dark:text-white">Create Test Bank</h3>
          <div className="space-y-4">
            <div>
              <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Name *</label>
              <input
                value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                placeholder="e.g. 2026 General Aptitude"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Description</label>
              <input
                value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>
            <div className="flex gap-3">
              <button
                onClick={handleCreate}
                disabled={saving || !form.name}
                className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2 text-sm font-bold text-white transition-all hover:bg-blue-700 disabled:opacity-50"
              >
                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Create'}
              </button>
              <button
                onClick={() => setShowForm(false)}
                className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-400 dark:hover:bg-slate-800"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {banks.length === 0 ? (
        <div className="rounded-2xl border border-slate-200 bg-white p-12 text-center shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <Database className="mx-auto mb-3 h-12 w-12 text-slate-300 dark:text-slate-600" />
          <p className="font-bold text-slate-500 dark:text-slate-400">No test banks found.</p>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {banks.map(bank => (
            <div key={bank.id} className="group relative flex flex-col justify-between overflow-hidden rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition-all hover:border-aerojet-blue/50 hover:shadow-md dark:border-slate-800 dark:bg-slate-900">
              <div>
                <div className="flex items-center justify-between">
                  <div className={`h-2.5 w-2.5 rounded-full ${bank.isActive ? 'bg-emerald-500' : 'bg-slate-300'}`} />
                  {bank._count.sessions === 0 && (
                    <button onClick={() => handleDelete(bank.id)} className="text-slate-400 hover:text-red-500">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}
                </div>
                <h3 className="mt-3 text-lg font-black text-slate-800 dark:text-white">{bank.name}</h3>
                {bank.description && (
                  <p className="mt-1 line-clamp-2 text-xs text-slate-500 dark:text-slate-400">{bank.description}</p>
                )}
                <div className="mt-4 flex items-center gap-4 text-xs font-bold text-slate-500 dark:text-slate-400">
                  <span className="flex items-center gap-1 rounded-md bg-slate-100 px-2 py-1 dark:bg-slate-800">
                    <Database className="h-3.5 w-3.5 text-aerojet-blue" />
                    {bank._count.questions} Questions
                  </span>
                </div>
              </div>
              <Link
                href={`/staff/admissions/aptitude/banks/${bank.id}`}
                className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-slate-50 py-2.5 text-sm font-bold text-aerojet-blue transition-colors hover:bg-blue-50 dark:bg-slate-800 dark:text-blue-400 dark:hover:bg-slate-700"
              >
                Manage Questions <ArrowRight className="h-4 w-4" />
              </Link>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Pencil, Trash2, Check, X, Loader2, AlertCircle } from 'lucide-react'

interface Question {
  id: string
  category: string
  questionType: string
  difficulty: string
  text: string
  options: any
  correctAnswer: string
  points: number
  explanation: string | null
  isActive: boolean
}

interface QuestionEditorProps {
  bankId: string
  isCreating: boolean
  onCancelCreate: () => void
}

const CATEGORIES = ['MATH', 'ENGLISH', 'ENGINEERING', 'LOGICAL_REASONING', 'PHYSICS']
const TYPES = ['MCQ', 'NUMERIC_INPUT', 'TRUE_FALSE']
const DIFFICULTIES = ['EASY', 'MEDIUM', 'HARD']

export default function QuestionEditor({ bankId, isCreating, onCancelCreate }: QuestionEditorProps) {
  const [questions, setQuestions] = useState<Question[]>([])
  const [loading, setLoading] = useState(true)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)

  const [form, setForm] = useState({
    category: 'MATH',
    questionType: 'MCQ',
    difficulty: 'MEDIUM',
    text: '',
    options: ['Option 1', 'Option 2', 'Option 3', 'Option 4'],
    correctAnswer: 'Option 1',
    points: 1,
    explanation: '',
    isActive: true,
  })

  const fetchQuestions = useCallback(async () => {
    try {
      const res = await fetch(`/api/staff/admissions/aptitude/banks/${bankId}/questions`)
      const json = await res.json()
      if (json.data) setQuestions(json.data)
    } finally {
      setLoading(false)
    }
  }, [bankId])

  useEffect(() => {
    fetchQuestions()
  }, [fetchQuestions])

  useEffect(() => {
    if (isCreating && !editingId) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setEditingId('NEW')
      setForm({
        category: 'MATH',
        questionType: 'MCQ',
        difficulty: 'MEDIUM',
        text: '',
        options: ['Option 1', 'Option 2', 'Option 3', 'Option 4'],
        correctAnswer: 'Option 1',
        points: 1,
        explanation: '',
        isActive: true,
      })
    }
  }, [isCreating, editingId])

  const handleSave = async () => {
    if (!form.text || !form.correctAnswer) return
    setSaving(true)
    try {
      const isNew = editingId === 'NEW'
      const url = isNew 
        ? `/api/staff/admissions/aptitude/banks/${bankId}/questions`
        : `/api/staff/admissions/aptitude/banks/${bankId}/questions/${editingId}`
      
      const payload = {
        ...form,
        options: form.questionType === 'MCQ' ? form.options : null
      }

      const res = await fetch(url, {
        method: isNew ? 'POST' : 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (res.ok) {
        setEditingId(null)
        if (isNew) onCancelCreate()
        fetchQuestions()
      }
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this question?')) return
    await fetch(`/api/staff/admissions/aptitude/banks/${bankId}/questions/${id}`, { method: 'DELETE' })
    fetchQuestions()
  }

  const handleEdit = (q: Question) => {
    setForm({
      category: q.category,
      questionType: q.questionType,
      difficulty: q.difficulty,
      text: q.text,
      options: Array.isArray(q.options) ? q.options : ['Option 1', 'Option 2', 'Option 3', 'Option 4'],
      correctAnswer: q.correctAnswer,
      points: q.points,
      explanation: q.explanation || '',
      isActive: q.isActive,
    })
    setEditingId(q.id)
  }

  const handleOptionChange = (index: number, val: string) => {
    const newOpts = [...form.options]
    newOpts[index] = val
    setForm({ ...form, options: newOpts })
  }

  const cancelEdit = () => {
    setEditingId(null)
    if (editingId === 'NEW') onCancelCreate()
  }

  if (loading) {
    return <div className="flex py-12 justify-center"><Loader2 className="h-6 w-6 animate-spin text-slate-400" /></div>
  }

  return (
    <div className="space-y-6">
      {editingId && (
        <div className="rounded-2xl border border-blue-200 bg-blue-50/30 p-5 dark:border-blue-900/30 dark:bg-blue-900/10">
          <div className="mb-4 grid gap-4 sm:grid-cols-3">
            <div>
              <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Category</label>
              <select value={form.category} onChange={e => setForm({...form, category: e.target.value})} className="w-full rounded-lg border border-slate-200 p-2 text-sm">
                {CATEGORIES.map(c => <option key={c} value={c}>{c.replace('_', ' ')}</option>)}
              </select>
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Type</label>
              <select value={form.questionType} onChange={e => setForm({...form, questionType: e.target.value})} className="w-full rounded-lg border border-slate-200 p-2 text-sm">
                {TYPES.map(t => <option key={t} value={t}>{t.replace('_', ' ')}</option>)}
              </select>
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Difficulty</label>
              <select value={form.difficulty} onChange={e => setForm({...form, difficulty: e.target.value})} className="w-full rounded-lg border border-slate-200 p-2 text-sm">
                {DIFFICULTIES.map(d => <option key={d} value={d}>{d}</option>)}
              </select>
            </div>
          </div>

          <div className="mb-4">
            <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Question Text *</label>
            <textarea
              value={form.text}
              onChange={e => setForm({...form, text: e.target.value})}
              rows={3}
              className="w-full rounded-lg border border-slate-200 p-3 text-sm focus:border-aerojet-blue focus:ring-2 focus:ring-aerojet-blue/20"
              placeholder="Enter question text..."
            />
          </div>

          {form.questionType === 'MCQ' && (
            <div className="mb-4 space-y-2">
              <label className="block text-xs font-bold uppercase text-slate-500">Options & Correct Answer</label>
              {form.options.map((opt: string, i: number) => (
                <div key={i} className="flex items-center gap-3">
                  <input
                    type="radio"
                    name="correct"
                    checked={form.correctAnswer === opt && opt !== ''}
                    onChange={() => setForm({...form, correctAnswer: opt})}
                    className="h-4 w-4 text-aerojet-blue"
                  />
                  <input
                    value={opt}
                    onChange={e => handleOptionChange(i, e.target.value)}
                    className="flex-1 rounded-lg border border-slate-200 p-2 text-sm"
                    placeholder={`Option ${i+1}`}
                  />
                </div>
              ))}
            </div>
          )}

          {form.questionType === 'TRUE_FALSE' && (
            <div className="mb-4 space-y-2">
              <label className="block text-xs font-bold uppercase text-slate-500">Correct Answer</label>
              <div className="flex gap-4">
                <label className="flex items-center gap-2"><input type="radio" checked={form.correctAnswer === 'True'} onChange={() => setForm({...form, correctAnswer: 'True'})} /> True</label>
                <label className="flex items-center gap-2"><input type="radio" checked={form.correctAnswer === 'False'} onChange={() => setForm({...form, correctAnswer: 'False'})} /> False</label>
              </div>
            </div>
          )}

          {form.questionType === 'NUMERIC_INPUT' && (
            <div className="mb-4">
              <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Exact Answer (Number)</label>
              <input type="text" value={form.correctAnswer} onChange={e => setForm({...form, correctAnswer: e.target.value})} className="w-full rounded-lg border border-slate-200 p-2 text-sm" />
            </div>
          )}

          <div className="mt-6 flex items-center justify-between">
            <label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={form.isActive} onChange={e => setForm({...form, isActive: e.target.checked})} /> Active</label>
            <div className="flex gap-3">
              <button onClick={handleSave} disabled={saving || !form.text || !form.correctAnswer} className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-5 py-2 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-50">
                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Save Question'}
              </button>
              <button onClick={cancelEdit} className="rounded-xl border border-slate-200 px-5 py-2 text-sm font-bold hover:bg-slate-50">Cancel</button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-3">
        {questions.length === 0 && !editingId && (
          <div className="py-8 text-center text-sm font-bold text-slate-400">No questions in this bank yet.</div>
        )}
        {questions.map((q, i) => (
          <div key={q.id} className="flex items-start justify-between rounded-xl border border-slate-100 bg-slate-50/50 p-4 transition-colors hover:bg-slate-50 dark:border-slate-800 dark:bg-slate-900/50">
            <div className="flex-1">
              <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-slate-400">
                <span className="rounded bg-slate-200 px-1.5 py-0.5 text-slate-600 dark:bg-slate-800 dark:text-slate-300">Q{questions.length - i}</span>
                <span className="text-aerojet-blue">{q.category.replace('_', ' ')}</span>
                <span>â€¢</span>
                <span>{q.questionType.replace('_', ' ')}</span>
                <span>â€¢</span>
                <span className={q.difficulty === 'EASY' ? 'text-green-500' : q.difficulty === 'HARD' ? 'text-red-500' : 'text-amber-500'}>{q.difficulty}</span>
              </div>
              <p className="mt-2 text-sm font-medium text-slate-800 dark:text-slate-200">{q.text}</p>
              <div className="mt-2 text-xs font-bold text-emerald-600">Ans: {q.correctAnswer}</div>
            </div>
            <div className="flex items-center gap-2 opacity-0 transition-opacity group-hover:opacity-100 md:opacity-100">
              <button onClick={() => handleEdit(q)} className="rounded-lg p-2 text-slate-400 hover:bg-blue-50 hover:text-blue-600"><Pencil className="h-4 w-4" /></button>
              <button onClick={() => handleDelete(q.id)} className="rounded-lg p-2 text-slate-400 hover:bg-red-50 hover:text-red-600"><Trash2 className="h-4 w-4" /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, use } from 'react'
import { ArrowLeft, Plus, Loader2 } from 'lucide-react'
import Link from 'next/link'
import QuestionEditor from './_components/QuestionEditor'

interface Bank {
  id: string
  name: string
  description: string | null
  isActive: boolean
}

export default function BankDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params)
  const [bank, setBank] = useState<Bank | null>(null)
  const [loading, setLoading] = useState(true)
  const [showEditor, setShowEditor] = useState(false)
  const [refreshKey, setRefreshKey] = useState(0)

  const fetchBank = useCallback(async () => {
    try {
      const res = await fetch(`/api/staff/admissions/aptitude/banks/${id}`)
      const json = await res.json()
      if (json.data) setBank(json.data)
    } finally {
      setLoading(false)
    }
  }, [id])

  useEffect(() => {
    fetchBank()
  }, [fetchBank])

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
