          <ArrowLeft className="h-5 w-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white sm:text-3xl">
            {bank.name}
          </h1>
          {bank.description && (
            <p className="mt-1 text-sm font-medium text-slate-500 dark:text-slate-400">
              {bank.description}
            </p>
          )}
        </div>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-6 flex items-center justify-between">
          <h2 className="text-lg font-black text-slate-800 dark:text-white">Questions</h2>
          <button
            onClick={() => setShowEditor(true)}
            className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-aerojet-blue/20 transition-all hover:shadow-xl hover:shadow-aerojet-blue/30"
          >
            <Plus className="h-4 w-4" /> Add Question
          </button>
        </div>

        <QuestionEditor 
          bankId={id} 
          isCreating={showEditor} 
          onCancelCreate={() => setShowEditor(false)} 
          key={refreshKey}
        />
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Check, Loader2, Save } from 'lucide-react'

interface SystemSettings {
  [key: string]: any
}

export default function AptitudeConfigPage() {
  const [settings, setSettings] = useState<SystemSettings>({})
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [success, setSuccess] = useState(false)

  const fetchSettings = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/admissions/aptitude/config')
      const json = await res.json()
      if (json.data) {
        setSettings(json.data)
      }
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchSettings()
  }, [fetchSettings])

  const handleSave = async () => {
    setSaving(true)
    setSuccess(false)
    try {
      const res = await fetch('/api/staff/admissions/aptitude/config', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings),
      })
      if (res.ok) {
        setSuccess(true)
        setTimeout(() => setSuccess(false), 3000)
      }
    } finally {
      setSaving(false)
    }
  }

  const handleChange = (key: string, value: any) => {
    setSettings(prev => ({ ...prev, [key]: value }))
  }

  if (loading) {
    return <div className="flex py-24 justify-center"><Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" /></div>
  }

  return (
    <div className="space-y-6 max-w-4xl">
      <div>
        <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white sm:text-3xl">
          Test Configuration
        </h1>
        <p className="mt-1 text-sm font-medium text-slate-500 dark:text-slate-400">
          Global rules and composition settings for the admissions aptitude test.
        </p>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <h3 className="mb-4 text-lg font-black text-slate-800 dark:text-white">Test Limits</h3>
        <div className="grid gap-6 sm:grid-cols-2">
          <div>
            <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Time Limit (Minutes)</label>
            <input
              type="number"
              value={settings.aptitude_time_limit_minutes}
              onChange={e => handleChange('aptitude_time_limit_minutes', parseInt(e.target.value) || 0)}
              className="w-full rounded-lg border border-slate-200 p-2 text-sm"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Pass Threshold (%)</label>
            <input
              type="number"
              min={1} max={100}
              value={settings.aptitude_pass_threshold_pct}
              onChange={e => handleChange('aptitude_pass_threshold_pct', parseInt(e.target.value) || 0)}
              className="w-full rounded-lg border border-slate-200 p-2 text-sm"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold uppercase text-slate-500">Anti-Cheat: Max Tab Switches</label>
            <input
              type="number"
              value={settings.aptitude_max_tab_switches}
              onChange={e => handleChange('aptitude_max_tab_switches', parseInt(e.target.value) || 0)}
              className="w-full rounded-lg border border-slate-200 p-2 text-sm"
            />
            <p className="mt-1 text-[10px] text-slate-400">Test is flagged if applicant switches tabs more than this.</p>
          </div>
        </div>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <h3 className="mb-4 text-lg font-black text-slate-800 dark:text-white">Question Composition (per session)</h3>
        <p className="mb-4 text-xs text-slate-500">How many questions to pull randomly from each category for a single test attempt.</p>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-500">Math</label>
            <input type="number" value={settings.aptitude_math_count} onChange={e => handleChange('aptitude_math_count', parseInt(e.target.value) || 0)} className="w-full rounded-lg border border-slate-200 p-2 text-sm" />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-500">English</label>
            <input type="number" value={settings.aptitude_english_count} onChange={e => handleChange('aptitude_english_count', parseInt(e.target.value) || 0)} className="w-full rounded-lg border border-slate-200 p-2 text-sm" />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-500">Engineering</label>
            <input type="number" value={settings.aptitude_engineering_count} onChange={e => handleChange('aptitude_engineering_count', parseInt(e.target.value) || 0)} className="w-full rounded-lg border border-slate-200 p-2 text-sm" />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-500">Logical Reasoning</label>
            <input type="number" value={settings.aptitude_reasoning_count} onChange={e => handleChange('aptitude_reasoning_count', parseInt(e.target.value) || 0)} className="w-full rounded-lg border border-slate-200 p-2 text-sm" />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-500">Physics</label>
            <input type="number" value={settings.aptitude_physics_count} onChange={e => handleChange('aptitude_physics_count', parseInt(e.target.value) || 0)} className="w-full rounded-lg border border-slate-200 p-2 text-sm" />
          </div>
        </div>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <h3 className="mb-4 text-lg font-black text-slate-800 dark:text-white">Behaviors</h3>
        <div className="space-y-3">
          <label className="flex items-center gap-3">
            <input type="checkbox" checked={settings.aptitude_require_for_modular} onChange={e => handleChange('aptitude_require_for_modular', e.target.checked)} className="h-4 w-4" />
            <span className="text-sm font-bold text-slate-700 dark:text-slate-300">Require test for Modular applicants</span>
          </label>
          <label className="flex items-center gap-3">
            <input type="checkbox" checked={settings.aptitude_shuffle_questions} onChange={e => handleChange('aptitude_shuffle_questions', e.target.checked)} className="h-4 w-4" />
            <span className="text-sm font-bold text-slate-700 dark:text-slate-300">Shuffle questions order for each applicant</span>
          </label>
          <label className="flex items-center gap-3">
            <input type="checkbox" checked={settings.aptitude_shuffle_options} onChange={e => handleChange('aptitude_shuffle_options', e.target.checked)} className="h-4 w-4" />
            <span className="text-sm font-bold text-slate-700 dark:text-slate-300">Shuffle MCQ options for each applicant</span>
          </label>
        </div>
      </div>

      <div className="flex items-center gap-4 pt-4">
        <button
          onClick={handleSave}
          disabled={saving}
          className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-6 py-2.5 text-sm font-bold text-white transition-all hover:bg-blue-700 hover:shadow-lg disabled:opacity-50"
        >
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save Configuration
        </button>
        {success && <span className="flex items-center gap-1 text-sm font-bold text-emerald-500"><Check className="h-4 w-4" /> Saved!</span>}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { format } from 'date-fns'
import { CheckCircle2, XCircle, AlertTriangle, Clock, Ban, Loader2, RefreshCw } from 'lucide-react'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

interface Session {
  id: string
  status: string
  startedAt: string | null
  submittedAt: string | null
  score: number | null
  totalPoints: number | null
  percentage: number | null
  passed: boolean | null
  tabSwitchCount: number
  fullscreenExits: number
  user: { firstName: string; lastName: string; email: string }
  bank: { name: string }
}

export default function SessionResultsPage() {
  const [sessions, setSessions] = useState<Session[]>([])
  const [loading, setLoading] = useState(true)

  const fetchSessions = useCallback(async () => {
    try {
      setLoading(true)
      const res = await fetch('/api/staff/admissions/aptitude/sessions')
      const json = await res.json()
      if (json.data) setSessions(json.data)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchSessions()
  }, [fetchSessions])

  const { items: sortedSessions, requestSort, sortConfig } = useSort<Session>(sessions, {
    key: 'submittedAt',
    order: 'desc',
  })

  const handleVoid = async (id: string) => {
    if (!confirm('Are you sure you want to void this session? It will be marked as failed.')) return
    const res = await fetch(`/api/staff/admissions/aptitude/sessions/${id}/void`, { method: 'POST' })
    if (res.ok) fetchSessions()
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white sm:text-3xl">
            Test Session Results
          </h1>
          <p className="mt-1 text-sm font-medium text-slate-500 dark:text-slate-400">
            View aptitude test results, scores, and anti-cheat violations.
          </p>
        </div>
        <button onClick={fetchSessions} className="flex items-center gap-2 rounded-xl border border-slate-200 px-4 py-2 text-sm font-bold text-slate-600 transition-colors hover:bg-slate-50 dark:border-slate-800 dark:text-slate-400 dark:hover:bg-slate-900">
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} /> Refresh
        </button>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:bg-slate-800/50">
              <tr>
                <SortHeader label="Applicant" sortKey="user.lastName" currentSort={sortConfig} onSort={requestSort} />
                <SortHeader label="Test Bank" sortKey="bank.name" currentSort={sortConfig} onSort={requestSort} />
                <SortHeader label="Score" sortKey="percentage" currentSort={sortConfig} onSort={requestSort} align="center" />
                <SortHeader label="Status" sortKey="status" currentSort={sortConfig} onSort={requestSort} align="center" />
                <SortHeader label="Anti-Cheat" sortKey="tabSwitchCount" currentSort={sortConfig} onSort={requestSort} align="center" />
                <SortHeader label="Submitted" sortKey="submittedAt" currentSort={sortConfig} onSort={requestSort} align="center" />
                <th className="px-4 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {sessions.length === 0 ? (
                <tr><td colSpan={7} className="px-6 py-12 text-center text-slate-500">No sessions found.</td></tr>
              ) : sortedSessions.map(session => (
                <tr key={session.id} className="transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800 dark:text-white">{session.user.firstName} {session.user.lastName}</div>
                    <div className="text-xs text-slate-500">{session.user.email}</div>
                  </td>
                  <td className="px-4 py-4 font-medium text-slate-600 dark:text-slate-400">{session.bank.name}</td>
                  <td className="px-4 py-4 text-center">
                    {session.score !== null ? (
                      <div className="font-black">
                        <span className="text-aerojet-blue">{session.score}</span>
                        <span className="text-slate-400">/{session.totalPoints}</span>
                        <div className="text-[10px] text-slate-500">{session.percentage?.toFixed(1)}%</div>
                      </div>
                    ) : (
                      <span className="text-slate-400">-</span>
                    )}
                  </td>
                  <td className="px-4 py-4 text-center">
                    {session.status === 'COMPLETED' ? (
                      <div className="flex justify-center">
                        {session.passed ? (
                          <div className="flex items-center gap-1 rounded-lg bg-emerald-50 px-2 py-1 text-[10px] font-black text-emerald-600 dark:bg-emerald-900/30">
                            <CheckCircle2 className="h-3 w-3" /> PASSED
                          </div>
                        ) : (
                          <div className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] font-black text-red-600 dark:bg-red-900/30">
                            <XCircle className="h-3 w-3" /> FAILED
                          </div>
                        )}
                      </div>
                    ) : session.status === 'IN_PROGRESS' ? (
                      <div className="flex justify-center">
                        <div className="flex items-center gap-1 rounded-lg bg-blue-50 px-2 py-1 text-[10px] font-black text-blue-600 dark:bg-blue-900/30">
                          <Clock className="h-3 w-3" /> IN PROGRESS
                        </div>
                      </div>
                    ) : session.status === 'VOIDED' ? (
                      <div className="flex justify-center">
                        <div className="flex items-center gap-1 rounded-lg bg-slate-100 px-2 py-1 text-[10px] font-black text-slate-600 dark:bg-slate-800">
                          <Ban className="h-3 w-3" /> VOIDED
                        </div>
                      </div>
                    ) : (
                      <div className="flex justify-center">
                        <div className="flex items-center gap-1 rounded-lg bg-amber-50 px-2 py-1 text-[10px] font-black text-amber-600 dark:bg-amber-900/30">
                          <AlertTriangle className="h-3 w-3" /> {session.status}
                        </div>
                      </div>
                    )}
                  </td>
                  <td className="px-4 py-4 text-center">
                    {(session.tabSwitchCount > 0 || session.fullscreenExits > 0) ? (
                      <div className="flex flex-col items-center gap-1 text-[10px] font-bold">
                        {session.tabSwitchCount > 0 && <span className="text-amber-500">{session.tabSwitchCount} tab switches</span>}
                        {session.fullscreenExits > 0 && <span className="text-amber-500">{session.fullscreenExits} fs exits</span>}
                      </div>
                    ) : (
                      <span className="text-[10px] font-bold text-slate-400">Clean</span>
                    )}
                  </td>
                  <td className="px-4 py-4 text-center text-xs text-slate-500">
                    {session.submittedAt ? format(new Date(session.submittedAt), 'MMM d, HH:mm') : '-'}
                  </td>
                  <td className="px-4 py-4 text-right">
                    {(session.status === 'COMPLETED' || session.status === 'FLAGGED') && (
                      <button onClick={() => handleVoid(session.id)} className="rounded-lg p-2 text-slate-400 transition-colors hover:bg-red-50 hover:text-red-600" title="Void Session">
                        <Ban className="h-4 w-4" />
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { toast } from 'sonner'
import {
  FileSignature,
  CheckCircle2,
  XOctagon,
  Clock,
  PenLine,
  Briefcase,
  ChevronLeft,
  ChevronRight,
  Search,
  Shield,
} from 'lucide-react'

type BondingStatus = 'ISSUED' | 'SIGNED' | 'IN_PROGRESS' | 'FULFILLED' | 'BREACHED'

interface Contract {
  id: string
  status: BondingStatus
  issuedAt: string
  signedAt: string | null
  startDate: string | null
  endDate: string | null
  facilityName: string | null
  notes: string | null
  application: {
    programmeChoice: string
    fundingType: string
    user: {
      id: string
      email: string
      profile: { firstName: string; lastName: string } | null
    }
  }
  studentProfile: { studentId: string } | null
}

const STATUS_CONFIG: Record<BondingStatus, { label: string; color: string; icon: any }> = {
  ISSUED: { label: 'Issued', color: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300', icon: Clock },
  SIGNED: { label: 'Signed', color: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300', icon: PenLine },
  IN_PROGRESS: { label: 'In Progress', color: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300', icon: Briefcase },
  FULFILLED: { label: 'Fulfilled', color: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300', icon: CheckCircle2 },
  BREACHED: { label: 'Breached', color: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300', icon: XOctagon },
}

const VALID_TRANSITIONS: Record<BondingStatus, BondingStatus[]> = {
  ISSUED: ['SIGNED'],
  SIGNED: ['IN_PROGRESS'],
  IN_PROGRESS: ['FULFILLED', 'BREACHED'],
  FULFILLED: [],
  BREACHED: [],
}

const STAT_CARDS: { key: BondingStatus; label: string; borderColor: string; bgColor: string; iconBg: string; iconColor: string; textColor: string; subColor: string }[] = [
  { key: 'ISSUED', label: 'Issued', borderColor: 'border-amber-200 dark:border-amber-800/50', bgColor: 'bg-amber-50 dark:bg-amber-900/10', iconBg: 'bg-amber-200 dark:bg-amber-800/50', iconColor: 'text-amber-700 dark:text-amber-300', textColor: 'text-amber-800 dark:text-amber-200', subColor: 'text-amber-600 dark:text-amber-400' },
  { key: 'SIGNED', label: 'Signed', borderColor: 'border-blue-200 dark:border-blue-800/50', bgColor: 'bg-blue-50 dark:bg-blue-900/10', iconBg: 'bg-blue-200 dark:bg-blue-800/50', iconColor: 'text-blue-700 dark:text-blue-300', textColor: 'text-blue-800 dark:text-blue-200', subColor: 'text-blue-600 dark:text-blue-400' },
  { key: 'IN_PROGRESS', label: 'In Progress', borderColor: 'border-purple-200 dark:border-purple-800/50', bgColor: 'bg-purple-50 dark:bg-purple-900/10', iconBg: 'bg-purple-200 dark:bg-purple-800/50', iconColor: 'text-purple-700 dark:text-purple-300', textColor: 'text-purple-800 dark:text-purple-200', subColor: 'text-purple-600 dark:text-purple-400' },
  { key: 'FULFILLED', label: 'Fulfilled', borderColor: 'border-green-200 dark:border-green-800/50', bgColor: 'bg-green-50 dark:bg-green-900/10', iconBg: 'bg-green-200 dark:bg-green-800/50', iconColor: 'text-green-700 dark:text-green-300', textColor: 'text-green-800 dark:text-green-200', subColor: 'text-green-600 dark:text-green-400' },
  { key: 'BREACHED', label: 'Breached', borderColor: 'border-red-200 dark:border-red-800/50', bgColor: 'bg-red-50 dark:bg-red-900/10', iconBg: 'bg-red-200 dark:bg-red-800/50', iconColor: 'text-red-700 dark:text-red-300', textColor: 'text-red-800 dark:text-red-200', subColor: 'text-red-600 dark:text-red-400' },
]

const STAT_ICONS: Record<BondingStatus, any> = {
  ISSUED: Clock,
  SIGNED: PenLine,
  IN_PROGRESS: Briefcase,
  FULFILLED: CheckCircle2,
  BREACHED: XOctagon,
}

export default function BondingContractsTable({
  initialContracts,
  initialTotal,
  statusCounts,
}: {
  initialContracts: Contract[]
  initialTotal: number
  statusCounts: Record<string, number>
}) {
  const router = useRouter()
  const searchParams = useSearchParams()

  const [contracts, setContracts] = useState(initialContracts)
  const [total, setTotal] = useState(initialTotal)
  const [filter, setFilter] = useState<string>(searchParams.get('status') || 'ALL')
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(false)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [editForm, setEditForm] = useState<{
    facilityName: string
    notes: string
    signedAt: string
    startDate: string
    endDate: string
  }>({ facilityName: '', notes: '', signedAt: '', startDate: '', endDate: '' })
  const [saving, setSaving] = useState(false)

  const limit = 20
  const totalPages = Math.ceil(total / limit)

  const fetchContracts = useCallback(async (f: string, s: string, p: number) => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      params.set('page', String(p))
      params.set('limit', String(limit))
      if (f !== 'ALL') params.set('status', f)
      if (s.trim()) params.set('search', s.trim())

      const res = await fetch(`/api/staff/admissions/bonding?${params}`)
      const data = await res.json()
      if (data.success) {
        setContracts(data.data)
        setTotal(data.meta.total)
      }
    } catch {
      toast.error('Failed to load contracts')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    const timeout = setTimeout(() => {
      fetchContracts(filter, search, page)
    }, search ? 300 : 0)
    return () => clearTimeout(timeout)
  }, [filter, search, page, fetchContracts])

  const handleExpand = (contract: Contract) => {
    if (expandedId === contract.id) {
      setExpandedId(null)
      return
    }
    setExpandedId(contract.id)
    setEditForm({
      facilityName: contract.facilityName || '',
      notes: contract.notes || '',
      signedAt: contract.signedAt ? contract.signedAt.slice(0, 10) : '',
      startDate: contract.startDate ? contract.startDate.slice(0, 10) : '',
      endDate: contract.endDate ? contract.endDate.slice(0, 10) : '',
    })
  }

  const handleStatusChange = async (contractId: string, newStatus: BondingStatus) => {
    setSaving(true)
    try {
      const payload: Record<string, any> = {
        status: newStatus,
        facilityName: editForm.facilityName || null,
        notes: editForm.notes || null,
      }
      if (editForm.signedAt) payload.signedAt = new Date(editForm.signedAt).toISOString()
      if (editForm.startDate) payload.startDate = new Date(editForm.startDate).toISOString()
      if (editForm.endDate) payload.endDate = new Date(editForm.endDate).toISOString()

      const res = await fetch(`/api/staff/admissions/bonding/${contractId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      const data = await res.json()
      if (data.success) {
        toast.success(`Contract updated to ${STATUS_CONFIG[newStatus].label}`)
        setExpandedId(null)
        fetchContracts(filter, search, page)
        router.refresh()
      } else {
        toast.error(data.error || 'Failed to update contract')
      }
    } catch {
      toast.error('An error occurred')
    } finally {
      setSaving(false)
    }
  }

  const handleSaveFields = async (contractId: string) => {
    setSaving(true)
    try {
      const payload: Record<string, any> = {
        facilityName: editForm.facilityName || null,
        notes: editForm.notes || null,
      }
      if (editForm.signedAt) payload.signedAt = new Date(editForm.signedAt).toISOString()
      if (editForm.startDate) payload.startDate = new Date(editForm.startDate).toISOString()
      if (editForm.endDate) payload.endDate = new Date(editForm.endDate).toISOString()

      const res = await fetch(`/api/staff/admissions/bonding/${contractId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      const data = await res.json()
      if (data.success) {
        toast.success('Contract details saved')
        fetchContracts(filter, search, page)
      } else {
        toast.error(data.error || 'Failed to save')
      }
    } catch {
      toast.error('An error occurred')
    } finally {
      setSaving(false)
    }
  }

  const getName = (c: Contract) => {
    const p = c.application.user.profile
    return p ? `${p.firstName} ${p.lastName}`.trim() || c.application.user.email : c.application.user.email
  }

  const totalAll = Object.values(statusCounts).reduce((a, b) => a + b, 0)

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-5">
        {STAT_CARDS.map(card => {
          const Icon = STAT_ICONS[card.key]
          return (
            <div key={card.key} className={`rounded-xl border ${card.borderColor} ${card.bgColor} p-4`}>
              <div className="flex items-center gap-3">
                <div className={`rounded-lg ${card.iconBg} p-2`}>
                  <Icon className={`h-5 w-5 ${card.iconColor}`} />
                </div>
                <div>
                  <p className={`text-2xl font-bold ${card.textColor}`}>{statusCounts[card.key] || 0}</p>
                  <p className={`text-xs font-medium ${card.subColor}`}>{card.label}</p>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {/* Filter Tabs + Search */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-wrap gap-2">
          {[
            { key: 'ALL', label: `All (${totalAll})` },
            ...STAT_CARDS.map(c => ({ key: c.key, label: `${c.label} (${statusCounts[c.key] || 0})` })),
          ].map(tab => (
            <button
              key={tab.key}
              onClick={() => { setFilter(tab.key); setPage(1) }}
              className={`rounded-lg px-3 py-1.5 text-sm font-bold transition-colors ${
                filter === tab.key
                  ? 'bg-aerojet-blue text-white dark:bg-aerojet-sky'
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search name, email, ID..."
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(1) }}
            className="w-full rounded-lg border border-slate-200 py-2 pl-9 pr-3 text-sm dark:border-slate-700 dark:bg-slate-900 sm:w-64"
          />
        </div>
      </div>

      {/* Table */}
      <div className="overflow-hidden rounded-xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-aerojet-blue border-t-transparent" />
          </div>
        ) : contracts.length === 0 ? (
          <div className="py-16 text-center">
            <Shield className="mx-auto mb-4 h-12 w-12 text-slate-300 dark:text-slate-600" />
            <p className="text-slate-500">No bonding contracts found.</p>
          </div>
        ) : (
          <>
            {/* Header */}
            <div className="hidden border-b border-slate-100 bg-slate-50 px-5 py-3 dark:border-slate-800 dark:bg-slate-800/50 md:grid md:grid-cols-7 md:gap-4">
              <span className="col-span-2 text-xs font-bold uppercase text-slate-500">Student</span>
              <span className="text-xs font-bold uppercase text-slate-500">Student ID</span>
              <span className="text-xs font-bold uppercase text-slate-500">Programme</span>
              <span className="text-xs font-bold uppercase text-slate-500">Status</span>
              <span className="text-xs font-bold uppercase text-slate-500">Issued</span>
              <span className="text-xs font-bold uppercase text-slate-500">Actions</span>
            </div>

            {contracts.map(contract => {
              const cfg = STATUS_CONFIG[contract.status]
              const BadgeIcon = cfg.icon
              const isExpanded = expandedId === contract.id
              const nextStatuses = VALID_TRANSITIONS[contract.status]

              return (
                <div key={contract.id} className="border-b border-slate-100 last:border-0 dark:border-slate-800">
                  {/* Row */}
                  <div className="grid grid-cols-1 gap-2 px-5 py-4 md:grid-cols-7 md:items-center md:gap-4">
                    <div className="col-span-2 flex items-center gap-3">
                      <div className="flex h-9 w-9 items-center justify-center rounded-full bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400">
                        <FileSignature className="h-4 w-4" />
                      </div>
                      <div>
                        <p className="font-bold text-slate-900 dark:text-white">{getName(contract)}</p>
                        <p className="text-xs text-slate-500">{contract.application.user.email}</p>
                      </div>
                    </div>
                    <div>
                      <span className="text-sm text-slate-700 dark:text-slate-300">
                        {contract.studentProfile?.studentId || '---'}
                      </span>
                    </div>
                    <div>
                      <span className="text-sm text-slate-700 dark:text-slate-300">
                        {contract.application.programmeChoice.replace(/_/g, ' ')}
                      </span>
                    </div>
                    <div>
                      <span className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold ${cfg.color}`}>
                        <BadgeIcon className="h-3.5 w-3.5" />
                        {cfg.label}
                      </span>
                    </div>
                    <div>
                      <span className="text-sm text-slate-600 dark:text-slate-400">
                        {new Date(contract.issuedAt).toLocaleDateString()}
                      </span>
                    </div>
                    <div>
                      {nextStatuses.length > 0 ? (
                        <button
                          onClick={() => handleExpand(contract)}
                          className="rounded-lg bg-aerojet-blue px-3 py-1.5 text-xs font-bold text-white hover:bg-aerojet-blue/90"
                        >
                          {isExpanded ? 'Close' : 'Manage'}
                        </button>
                      ) : (
                        <button
                          onClick={() => handleExpand(contract)}
                          className="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300"
                        >
                          {isExpanded ? 'Close' : 'View'}
                        </button>
                      )}
                    </div>
                  </div>

                  {/* Expanded Form */}
                  {isExpanded && (
                    <div className="border-t border-aerojet-blue/20 bg-aerojet-blue/5 px-5 py-5 dark:border-aerojet-sky/20 dark:bg-aerojet-sky/5">
                      <h4 className="mb-4 font-bold text-aerojet-blue dark:text-aerojet-sky">
                        Contract Details
                      </h4>
                      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                        <div>
                          <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Facility Name</label>
                          <input
                            type="text"
                            className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                            value={editForm.facilityName}
                            onChange={e => setEditForm(prev => ({ ...prev, facilityName: e.target.value }))}
                            placeholder="e.g. Aerojet Engineering Ltd"
                          />
                        </div>
                        <div>
                          <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Date Signed</label>
                          <input
                            type="date"
                            className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                            value={editForm.signedAt}
                            onChange={e => setEditForm(prev => ({ ...prev, signedAt: e.target.value }))}
                          />
                        </div>
                        <div>
                          <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Start Date</label>
                          <input
                            type="date"
                            className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                            value={editForm.startDate}
                            onChange={e => setEditForm(prev => ({ ...prev, startDate: e.target.value }))}
                          />
                        </div>
                        <div>
                          <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">End Date</label>
                          <input
                            type="date"
                            className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                            value={editForm.endDate}
                            onChange={e => setEditForm(prev => ({ ...prev, endDate: e.target.value }))}
                          />
                        </div>
                        <div className="sm:col-span-2">
                          <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Notes</label>
                          <textarea
                            className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                            rows={2}
                            value={editForm.notes}
                            onChange={e => setEditForm(prev => ({ ...prev, notes: e.target.value }))}
                            placeholder="Any additional notes..."
                          />
                        </div>
                      </div>

                      <div className="mt-4 flex flex-wrap gap-3">
                        {nextStatuses.map(ns => {
                          const nsCfg = STATUS_CONFIG[ns]
                          const NsIcon = nsCfg.icon
                          const isDestructive = ns === 'BREACHED'
                          return (
                            <button
                              key={ns}
                              onClick={() => handleStatusChange(contract.id, ns)}
                              disabled={saving}
                              className={`flex items-center gap-2 rounded-lg px-5 py-2 text-sm font-bold text-white disabled:opacity-50 ${
                                isDestructive
                                  ? 'bg-red-600 hover:bg-red-700'
                                  : ns === 'FULFILLED'
                                    ? 'bg-green-600 hover:bg-green-700'
                                    : 'bg-aerojet-blue hover:bg-aerojet-blue/90'
                              }`}
                            >
                              <NsIcon className="h-4 w-4" />
                              Mark as {nsCfg.label}
                            </button>
                          )
                        })}
                        {nextStatuses.length === 0 && (
                          <button
                            onClick={() => handleSaveFields(contract.id)}
                            disabled={saving}
                            className="flex items-center gap-2 rounded-lg bg-aerojet-blue px-5 py-2 text-sm font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50"
                          >
                            Save Notes
                          </button>
                        )}
                        {nextStatuses.length > 0 && (
                          <button
                            onClick={() => handleSaveFields(contract.id)}
                            disabled={saving}
                            className="rounded-lg border border-slate-300 px-5 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300"
                          >
                            Save Without Status Change
                          </button>
                        )}
                        <button
                          onClick={() => setExpandedId(null)}
                          className="rounded-lg border border-slate-300 px-5 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300"
                        >
                          Cancel
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-slate-500">
            Showing {(page - 1) * limit + 1}–{Math.min(page * limit, total)} of {total}
          </p>
          <div className="flex gap-2">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page <= 1}
              className="rounded-lg border border-slate-200 p-2 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page >= totalPages}
              className="rounded-lg border border-slate-200 p-2 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useRef } from 'react'
import Papa from 'papaparse'
import { CustomFieldDefinition, ProgrammeChoice, ApplicationStage } from '@prisma/client'
import { Upload, ArrowRight, CheckCircle2, AlertTriangle, FileSpreadsheet } from 'lucide-react'

type Step = 'UPLOAD' | 'MAP' | 'VALIDATE' | 'IMPORT'

const STANDARD_FIELDS = [
  { key: 'firstName', label: 'First Name', required: true },
  { key: 'lastName', label: 'Last Name', required: true },
  { key: 'email', label: 'Email', required: true },
  { key: 'phone', label: 'Phone', required: false },
  { key: 'programmeChoice', label: 'Programme Choice', required: true },
  { key: 'stage', label: 'Application Stage', required: false },
]

export default function ImportWizard({ customFields }: { customFields: CustomFieldDefinition[] }) {
  const [step, setStep] = useState<Step>('UPLOAD')
  const [csvData, setCsvData] = useState<any[]>([])
  const [csvHeaders, setCsvHeaders] = useState<string[]>([])
  const [mapping, setMapping] = useState<Record<string, string>>({}) // targetField -> csvHeader
  
  const [validationResults, setValidationResults] = useState<any[]>([])
  const [isImporting, setIsImporting] = useState(false)
  const [importStats, setImportStats] = useState<{ imported: number, errors: string[] } | null>(null)

  const fileInputRef = useRef<HTMLInputElement>(null)

  const allTargetFields = [
    ...STANDARD_FIELDS,
    ...customFields.map(cf => ({ key: `custom_${cf.slug}`, label: `Custom: ${cf.name}`, required: cf.isRequired }))
  ]

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        setCsvHeaders(results.meta.fields || [])
        setCsvData(results.data)
        
        // Auto-map where possible
        const initialMapping: Record<string, string> = {}
        const lowerHeaders = (results.meta.fields || []).map(h => ({ original: h, lower: h.toLowerCase() }))
        
        allTargetFields.forEach(tf => {
          const match = lowerHeaders.find(h => 
            h.lower === tf.key.toLowerCase() || 
            h.lower === tf.label.toLowerCase() ||
            h.lower === tf.key.replace('custom_', '').toLowerCase()
          )
          if (match) initialMapping[tf.key] = match.original
        })
        
        setMapping(initialMapping)
        setStep('MAP')
      }
    })
  }

  const handleValidate = async () => {
    setIsImporting(true)

    // Build rows according to mapping
    const rowsToValidate = csvData.map(row => {
      const parsed: any = { customFields: {} }
      
      allTargetFields.forEach(tf => {
        const csvCol = mapping[tf.key]
        if (!csvCol) return
        
        const val = row[csvCol]
        if (tf.key.startsWith('custom_')) {
          const slug = tf.key.replace('custom_', '')
          parsed.customFields[slug] = val
        } else {
          parsed[tf.key] = val
        }
      })
      
      // Defaults if missing mapping
      if (!parsed.stage) parsed.stage = 'REGISTERED'
      
      return parsed
    })

    try {
      const res = await fetch('/api/staff/admissions/import/validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows: rowsToValidate })
      })
      const data = await res.json()
      if (data.results) {
        setValidationResults(data.results)
        setStep('VALIDATE')
      } else {
        alert(data.error || 'Validation failed')
      }
    } catch (e) {
      alert('Error validating data')
    } finally {
      setIsImporting(false)
    }
  }

  const handleImport = async () => {
    setIsImporting(true)
    const validRows = validationResults.filter(r => r.valid).map(r => r.data)

    try {
      const res = await fetch('/api/staff/admissions/import/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ validRows })
      })
      const data = await res.json()
      if (data.importedCount !== undefined) {
        setImportStats({ imported: data.importedCount, errors: data.errors || [] })
        setStep('IMPORT')
      } else {
        alert(data.error || 'Import failed')
      }
    } catch (e) {
      alert('Error executing import')
    } finally {
      setIsImporting(false)
    }
  }

  return (
    <div className="rounded-xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
      <div className="border-b border-slate-100 p-4 dark:border-slate-800">
        <div className="flex items-center justify-between text-sm font-medium text-slate-500">
          <span className={step === 'UPLOAD' ? 'text-aerojet-blue font-bold dark:text-aerojet-sky' : ''}>1. Upload</span>
          <ArrowRight className="h-4 w-4" />
          <span className={step === 'MAP' ? 'text-aerojet-blue font-bold dark:text-aerojet-sky' : ''}>2. Map Columns</span>
          <ArrowRight className="h-4 w-4" />
          <span className={step === 'VALIDATE' ? 'text-aerojet-blue font-bold dark:text-aerojet-sky' : ''}>3. Validate</span>
          <ArrowRight className="h-4 w-4" />
          <span className={step === 'IMPORT' ? 'text-aerojet-blue font-bold dark:text-aerojet-sky' : ''}>4. Result</span>
        </div>
      </div>

      <div className="p-6">
        {step === 'UPLOAD' && (
          <div className="flex flex-col items-center justify-center rounded-xl border-2 border-dashed border-slate-300 bg-slate-50 py-16 text-center dark:border-slate-700 dark:bg-slate-800/50">
            <FileSpreadsheet className="mb-4 h-12 w-12 text-slate-400" />
            <h3 className="mb-2 text-lg font-bold text-slate-900 dark:text-white">Upload CSV File</h3>
            <p className="mb-6 max-w-sm text-sm text-slate-500">
              Ensure your file has a header row. Legacy data will automatically create applications and user profiles.
            </p>
            <input 
              type="file" 
              accept=".csv" 
              className="hidden" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="rounded-lg bg-aerojet-blue px-6 py-2.5 text-sm font-bold text-white hover:bg-aerojet-blue/90"
            >
              Select CSV File
            </button>
          </div>
        )}

        {step === 'MAP' && (
          <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Map Columns</h3>
            <p className="text-sm text-slate-500">Match the fields in your CSV to the system properties.</p>
            
            <div className="grid gap-4 sm:grid-cols-2">
              {allTargetFields.map(tf => (
                <div key={tf.key} className="flex items-center justify-between rounded-lg border border-slate-200 p-3 dark:border-slate-700">
                  <div>
                    <div className="text-sm font-bold text-slate-800 dark:text-slate-200">
                      {tf.label}
                      {tf.required && <span className="ml-1 text-red-500">*</span>}
                    </div>
                  </div>
                  <select
                    className="w-1/2 rounded-md border border-slate-300 bg-white px-2 py-1.5 text-sm dark:border-slate-600 dark:bg-slate-800"
                    value={mapping[tf.key] || ''}
                    onChange={e => setMapping({ ...mapping, [tf.key]: e.target.value })}
                  >
                    <option value="">-- Ignore --</option>
                    {csvHeaders.map(h => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>

            <div className="flex justify-end pt-4 border-t border-slate-100 dark:border-slate-800">
              <button
                onClick={handleValidate}
                disabled={isImporting}
                className="rounded-lg bg-aerojet-blue px-6 py-2 font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50"
              >
                {isImporting ? 'Validating...' : 'Validate Data'}
              </button>
            </div>
          </div>
        )}

        {step === 'VALIDATE' && (
          <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Validation Results</h3>
            
            <div className="flex gap-4">
              <div className="rounded-lg bg-green-50 p-4 text-green-800 dark:bg-green-900/20 dark:text-green-300 flex-1 border border-green-200 dark:border-green-800/50">
                <div className="font-bold text-xl">{validationResults.filter(r => r.valid).length}</div>
                <div className="text-sm">Ready to Import</div>
              </div>
              <div className="rounded-lg bg-red-50 p-4 text-red-800 dark:bg-red-900/20 dark:text-red-300 flex-1 border border-red-200 dark:border-red-800/50">
                <div className="font-bold text-xl">{validationResults.filter(r => !r.valid).length}</div>
                <div className="text-sm">Rows with Errors</div>
              </div>
            </div>

            {validationResults.filter(r => !r.valid).length > 0 && (
              <div className="max-h-64 overflow-y-auto rounded-lg border border-red-200 bg-red-50/50 p-4 text-sm dark:border-red-900/50 dark:bg-red-900/10">
                <h4 className="mb-2 font-bold text-red-800 dark:text-red-400">Errors found:</h4>
                <ul className="list-disc pl-5 space-y-1 text-red-700 dark:text-red-300">
                  {validationResults.filter(r => !r.valid).slice(0, 50).map((r, i) => (
                    <li key={i}>Row {r.row + 1}: {r.errors?.join(', ')}</li>
                  ))}
                  {validationResults.filter(r => !r.valid).length > 50 && (
                    <li className="font-medium text-red-800">+ {validationResults.filter(r => !r.valid).length - 50} more errors</li>
                  )}
                </ul>
              </div>
            )}

            <div className="flex justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
              <button
                onClick={() => setStep('MAP')}
                disabled={isImporting}
                className="rounded-lg border border-slate-300 px-6 py-2 font-bold text-slate-700 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-600 dark:text-slate-300 dark:hover:bg-slate-800"
              >
                Back to Mapping
              </button>
              <button
                onClick={handleImport}
                disabled={isImporting || validationResults.filter(r => r.valid).length === 0}
                className="rounded-lg bg-green-600 px-6 py-2 font-bold text-white hover:bg-green-700 disabled:opacity-50"
              >
                {isImporting ? 'Importing...' : `Import ${validationResults.filter(r => r.valid).length} Valid Rows`}
              </button>
            </div>
          </div>
        )}

        {step === 'IMPORT' && importStats && (
          <div className="flex flex-col items-center justify-center py-8 text-center space-y-4">
            <div className="rounded-full bg-green-100 p-3 text-green-600 dark:bg-green-900/30 dark:text-green-400">
              <CheckCircle2 className="h-10 w-10" />
            </div>
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white">Import Complete!</h3>
            <p className="text-slate-500">Successfully imported {importStats.imported} records.</p>

            {importStats.errors.length > 0 && (
              <div className="mt-4 w-full max-w-lg rounded-lg border border-amber-200 bg-amber-50 p-4 text-left text-sm text-amber-800 dark:border-amber-900/50 dark:bg-amber-900/20 dark:text-amber-300">
                <div className="mb-2 flex items-center gap-2 font-bold">
                  <AlertTriangle className="h-4 w-4" />
                  {importStats.errors.length} Execution Errors:
                </div>
                <ul className="list-disc pl-5 space-y-1">
                  {importStats.errors.slice(0, 10).map((err, i) => (
                    <li key={i}>{err}</li>
                  ))}
                  {importStats.errors.length > 10 && (
                    <li>...and {importStats.errors.length - 10} more.</li>
                  )}
                </ul>
              </div>
            )}

            <button
              onClick={() => {
                setStep('UPLOAD')
                setCsvData([])
                setCsvHeaders([])
                setMapping({})
                setValidationResults([])
                setImportStats(null)
              }}
              className="mt-6 rounded-lg bg-slate-900 px-6 py-2.5 font-bold text-white hover:bg-slate-800 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
            >
              Start New Import
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Plus, Pencil, Trash2, Check, X, Calendar, Users, Loader2 } from 'lucide-react'
import { format } from 'date-fns'

interface IntakeCycle {
  id: string
  name: string
  description: string | null
  startDate: string
  endDate: string
  isActive: boolean
  academicYear: { id: string; name: string } | null
  _count: { applications: number }
}

interface AcademicYear {
  id: string
  name: string
}

export default function IntakeCycleManager() {
  const [cycles, setCycles] = useState<IntakeCycle[]>([])
  const [academicYears, setAcademicYears] = useState<AcademicYear[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({
    name: '',
    description: '',
    academicYearId: '' as string | null,
    startDate: '',
    endDate: '',
    isActive: true,
  })

  const fetchCycles = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/admissions/intake-cycles?limit=50')
      const json = await res.json()
      if (json.data) setCycles(json.data)
    } finally {
      setLoading(false)
    }
  }, [])

  const fetchAcademicYears = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/academic-years')
      const json = await res.json()
      if (json.data) setAcademicYears(json.data)
    } catch {
      // Non-critical
    }
  }, [])

  useEffect(() => {
    fetchCycles()
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchAcademicYears()
  }, [fetchCycles, fetchAcademicYears])

  const resetForm = () => {
    setForm({ name: '', description: '', academicYearId: null, startDate: '', endDate: '', isActive: true })
    setEditingId(null)
    setShowForm(false)
  }

  const handleSave = async () => {
    if (!form.name || !form.startDate || !form.endDate) return
    setSaving(true)
    try {
      const url = editingId
        ? `/api/staff/admissions/intake-cycles/${editingId}`
        : '/api/staff/admissions/intake-cycles'
      const method = editingId ? 'PUT' : 'POST'
      const payload = {
        ...form,
        academicYearId: form.academicYearId || null,
      }
      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (res.ok) {
        resetForm()
        fetchCycles()
      }
    } finally {
      setSaving(false)
    }
  }

  const handleEdit = (cycle: IntakeCycle) => {
    setForm({
      name: cycle.name,
      description: cycle.description ?? '',
      academicYearId: cycle.academicYear?.id ?? null,
      startDate: cycle.startDate.split('T')[0],
      endDate: cycle.endDate.split('T')[0],
      isActive: cycle.isActive,
    })
    setEditingId(cycle.id)
    setShowForm(true)
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this intake cycle?')) return
    await fetch(`/api/staff/admissions/intake-cycles/${id}`, { method: 'DELETE' })
    fetchCycles()
  }

  const toggleActive = async (cycle: IntakeCycle) => {
    await fetch(`/api/staff/admissions/intake-cycles/${cycle.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ isActive: !cycle.isActive }),
    })
    fetchCycles()
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white sm:text-3xl">
            Intake Cycles
          </h1>
          <p className="mt-1 text-sm font-medium text-slate-500 dark:text-slate-400">
            Manage admissions intake periods and link them to academic years.
          </p>
        </div>
        <button
          onClick={() => { resetForm(); setShowForm(true) }}
          className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-aerojet-blue/20 transition-all hover:shadow-xl hover:shadow-aerojet-blue/30"
        >
          <Plus className="h-4 w-4" /> New Cycle
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-lg dark:border-slate-700 dark:bg-slate-900">
          <h3 className="mb-4 text-lg font-black text-aerojet-blue dark:text-white">
            {editingId ? 'Edit Intake Cycle' : 'New Intake Cycle'}
          </h3>
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="sm:col-span-2">
              <label className="mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500">Name *</label>
              <input
                value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                placeholder="e.g. September 2026 Intake"
              />
            </div>
            <div className="sm:col-span-2">
              <label className="mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500">Description</label>
              <input
                value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                placeholder="Optional description"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500">Start Date *</label>
              <input
                type="date"
                value={form.startDate}
                onChange={e => setForm(f => ({ ...f, startDate: e.target.value }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500">End Date *</label>
              <input
                type="date"
                value={form.endDate}
                onChange={e => setForm(f => ({ ...f, endDate: e.target.value }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500">Academic Year</label>
              <select
                value={form.academicYearId ?? ''}
                onChange={e => setForm(f => ({ ...f, academicYearId: e.target.value || null }))}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              >
                <option value="">None</option>
                {academicYears.map(ay => (
                  <option key={ay.id} value={ay.id}>{ay.name}</option>
                ))}
              </select>
            </div>
            <div className="flex items-end">
              <label className="flex items-center gap-2 text-sm font-bold text-slate-600 dark:text-slate-300">
                <input
                  type="checkbox"
                  checked={form.isActive}
                  onChange={e => setForm(f => ({ ...f, isActive: e.target.checked }))}
                  className="h-4 w-4 rounded border-slate-300 text-aerojet-blue"
                />
                Active
              </label>
            </div>
          </div>
          <div className="mt-6 flex gap-3">
            <button
              onClick={handleSave}
              disabled={saving || !form.name || !form.startDate || !form.endDate}
              className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-5 py-2.5 text-sm font-bold text-white transition-all hover:shadow-lg disabled:opacity-50"
            >
              {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
              {editingId ? 'Update' : 'Create'}
            </button>
            <button
              onClick={resetForm}
              className="flex items-center gap-2 rounded-xl border border-slate-200 px-5 py-2.5 text-sm font-bold text-slate-600 transition-all hover:bg-slate-50 dark:border-slate-700 dark:text-slate-400"
            >
              <X className="h-4 w-4" /> Cancel
            </button>
          </div>
        </div>
      )}

      {/* List */}
      {cycles.length === 0 ? (
        <div className="rounded-2xl border border-slate-100 bg-white px-6 py-16 text-center shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <Calendar className="mx-auto mb-3 h-12 w-12 text-slate-300" />
          <p className="text-sm font-bold text-slate-400">No intake cycles yet.</p>
          <p className="mt-1 text-xs text-slate-400">Create your first intake cycle to start grouping applicants.</p>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {cycles.map(cycle => (
            <div
              key={cycle.id}
              className={`group relative overflow-hidden rounded-2xl border bg-white p-6 shadow-sm transition-all hover:shadow-xl dark:bg-slate-900 ${
                cycle.isActive
                  ? 'border-emerald-200 dark:border-emerald-800'
                  : 'border-slate-100 opacity-60 dark:border-slate-800'
              }`}
            >
              {/* Status dot */}
              <div className={`absolute right-4 top-4 h-2.5 w-2.5 rounded-full ${cycle.isActive ? 'bg-emerald-500' : 'bg-slate-300'}`} />

              <h3 className="pr-8 text-base font-black text-aerojet-blue dark:text-white">{cycle.name}</h3>
              {cycle.description && (
                <p className="mt-1 text-xs text-slate-400">{cycle.description}</p>
              )}

              <div className="mt-4 space-y-2">
                <div className="flex items-center gap-2 text-xs text-slate-500">
                  <Calendar className="h-3.5 w-3.5" />
                  {format(new Date(cycle.startDate), 'MMM d, yyyy')} â€” {format(new Date(cycle.endDate), 'MMM d, yyyy')}
                </div>
                <div className="flex items-center gap-2 text-xs text-slate-500">
                  <Users className="h-3.5 w-3.5" />
                  {cycle._count.applications} application{cycle._count.applications !== 1 ? 's' : ''}
                </div>
                {cycle.academicYear && (
                  <div className="mt-1">
                    <span className="rounded-lg bg-indigo-50 px-2 py-1 text-[10px] font-black text-indigo-600">
                      {cycle.academicYear.name}
                    </span>
                  </div>
                )}
              </div>

              {/* Actions */}
              <div className="mt-4 flex gap-2 border-t border-slate-100 pt-3 dark:border-slate-800">
                <button
                  onClick={() => handleEdit(cycle)}
                  className="flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-[11px] font-bold text-slate-500 transition-colors hover:bg-blue-50 hover:text-blue-600"
                >
                  <Pencil className="h-3 w-3" /> Edit
                </button>
                <button
                  onClick={() => toggleActive(cycle)}
                  className="flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-[11px] font-bold text-slate-500 transition-colors hover:bg-amber-50 hover:text-amber-600"
                >
                  {cycle.isActive ? 'Deactivate' : 'Activate'}
                </button>
                {cycle._count.applications === 0 && (
                  <button
                    onClick={() => handleDelete(cycle.id)}
                    className="flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-[11px] font-bold text-slate-500 transition-colors hover:bg-red-50 hover:text-red-600"
                  >
                    <Trash2 className="h-3 w-3" /> Delete
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  CheckCircle2,
  XCircle,
  AlertCircle,
  Clock,
  Calendar,
  HelpCircle,
  ClipboardList,
} from 'lucide-react'
import { format } from 'date-fns'
import InterviewEvaluationForm from './InterviewEvaluationForm'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

export default function InterviewOutcomesTable({ data }: { data: any[] }) {
  const router = useRouter()
  const [processing, setProcessing] = useState<string | null>(null)
  const [evaluatingApp, setEvaluatingApp] = useState<{ id: string; name: string } | null>(null)

  const sortableData = useMemo(
    () =>
      data.map((row) => ({
        ...row,
        _slotDate: row.slot?.date ? new Date(row.slot.date).getTime() : 0,
      })),
    [data]
  )
  const { items: sortedData, requestSort, sortConfig } = useSort(sortableData)

  const handleOutcome = async (
    applicationId: string,
    outcome: 'PASS' | 'FAIL' | 'CONDITIONAL' | 'NO_SHOW'
  ) => {
    let notes = ''
    let score: number | undefined

    if (outcome !== 'NO_SHOW') {
      const scoreInput = prompt(`Enter numeric score (0-100) for ${outcome}:`)
      if (scoreInput !== null && !isNaN(parseInt(scoreInput, 10))) {
        score = parseInt(scoreInput, 10)
      }
    }

    if (outcome === 'FAIL' || outcome === 'NO_SHOW' || outcome === 'CONDITIONAL') {
      const input = prompt(`Enter notes/conditions for ${outcome.replace('_', ' ')}:`)
      if (input === null && outcome !== 'CONDITIONAL') return
      notes = input || ''
    } else {
      const input = prompt('Enter positive remarks (optional):')
      if (input !== null) notes = input
    }

    setProcessing(applicationId)
    try {
      const res = await fetch('/api/staff/admissions/interviews/outcome', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ applicationId, outcome, score, notes }),
      })

      if (res.ok) {
        router.refresh()
      } else {
        toast.error('Failed to update outcome')
      }
    } finally {
      setProcessing(null)
    }
  }

  return (
    <>
      <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-xs dark:border-slate-800 dark:bg-slate-900">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-slate-500 dark:bg-slate-800/50 dark:text-slate-400">
            <tr>
              <SortHeader label="Candidate" sortKey="applicantName" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" />
              <SortHeader label="Programme" sortKey="programmeChoice" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" />
              <SortHeader label="Slot & Time" sortKey="_slotDate" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" />
              <SortHeader label="Status" sortKey="stage" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" align="center" />
              <th className="px-4 py-3 font-medium">Evaluate</th>
              <th className="px-4 py-3 font-medium text-right">Record Outcome</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
            {sortedData.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-8 text-center text-slate-500">
                  No candidates pending interviews right now.
                </td>
              </tr>
            ) : (
              sortedData.map((row) => (
                <tr
                  key={row.id}
                  className="transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50"
                >
                  <td className="px-4 py-4">
                    <div className="font-bold text-slate-900 dark:text-white">
                      {row.applicantName}
                    </div>
                    <div className="text-xs text-slate-500">{row.email}</div>
                  </td>
                  <td className="px-4 py-4 text-slate-600 dark:text-slate-300">
                    {row.programmeChoice}
                    <div className="text-xs text-slate-500">{row.intakeCycle}</div>
                  </td>
                  <td className="px-4 py-4">
                    {row.slot ? (
                      <div>
                        <div className="flex items-center gap-1.5 font-medium text-slate-700 dark:text-slate-300">
                          <Calendar className="h-3.5 w-3.5 text-aerojet-blue" />
                          {format(new Date(row.slot.date), 'MMM d, yyyy')}
                        </div>
                        <div className="mt-0.5 flex items-center gap-1.5 text-xs text-slate-500">
                          <Clock className="h-3.5 w-3.5" />
                          {format(new Date(row.slot.startTime), 'h:mm a')}
                        </div>
                      </div>
                    ) : (
                      <span className="text-xs font-semibold text-amber-600 dark:text-amber-400">
                        Not Booked Yet
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-4">
                    <span
                      className={`inline-flex items-center gap-1 rounded-full px-2 py-1 text-xs font-semibold ${
                        row.stage === 'INTERVIEW_COMPLETED'
                          ? 'bg-teal-50 text-teal-700 dark:bg-teal-900/30 dark:text-teal-400'
                          : row.stage === 'INTERVIEW_SCHEDULED'
                            ? 'bg-cyan-50 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-400'
                            : 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300'
                      }`}
                    >
                      {row.stage.replace('INTERVIEW_', '')}
                    </span>
                  </td>
                  <td className="px-4 py-4">
                    <button
                      onClick={() =>
                        setEvaluatingApp({ id: row.id, name: row.applicantName })
                      }
                      className="flex items-center gap-1.5 rounded-lg border border-indigo-200 bg-indigo-50 px-3 py-1.5 text-xs font-semibold text-indigo-700 hover:bg-indigo-100 dark:border-indigo-900/50 dark:bg-indigo-900/20 dark:text-indigo-400"
                    >
                      <ClipboardList className="h-3.5 w-3.5" />
                      Evaluate
                    </button>
                  </td>
                  <td className="px-4 py-4 text-right">
                    {row.slot && row.stage !== 'INTERVIEW_COMPLETED' ? (
                      <div className="flex items-center justify-end gap-2">
                        <button
                          onClick={() => handleOutcome(row.id, 'PASS')}
                          disabled={processing === row.id}
                          className="rounded-lg border border-green-200 bg-green-50 px-3 py-1.5 text-xs font-semibold text-green-700 hover:bg-green-100 disabled:opacity-50 dark:border-green-900/50 dark:bg-green-900/20 dark:text-green-400"
                        >
                          <CheckCircle2 className="mr-1 inline-block h-3.5 w-3.5" />
                          Pass
                        </button>
                        <button
                          onClick={() => handleOutcome(row.id, 'CONDITIONAL')}
                          disabled={processing === row.id}
                          className="rounded-lg border border-blue-200 bg-blue-50 px-3 py-1.5 text-xs font-semibold text-blue-700 hover:bg-blue-100 disabled:opacity-50 dark:border-blue-900/50 dark:bg-blue-900/20 dark:text-blue-400"
                        >
                          <HelpCircle className="mr-1 inline-block h-3.5 w-3.5" />
                          Conditional
                        </button>
                        <button
                          onClick={() => handleOutcome(row.id, 'FAIL')}
                          disabled={processing === row.id}
                          className="rounded-lg border border-red-200 bg-red-50 px-3 py-1.5 text-xs font-semibold text-red-700 hover:bg-red-100 disabled:opacity-50 dark:border-red-900/50 dark:bg-red-900/20 dark:text-red-400"
                        >
                          <XCircle className="mr-1 inline-block h-3.5 w-3.5" />
                          Fail
                        </button>
                        <button
                          onClick={() => handleOutcome(row.id, 'NO_SHOW')}
                          disabled={processing === row.id}
                          className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-1.5 text-xs font-semibold text-amber-700 hover:bg-amber-100 disabled:opacity-50 dark:border-amber-900/50 dark:bg-amber-900/20 dark:text-amber-400"
                        >
                          <AlertCircle className="mr-1 inline-block h-3.5 w-3.5" />
                          No-Show
                        </button>
                      </div>
                    ) : (
                      <span className="text-xs text-slate-400">
                        {row.stage === 'INTERVIEW_COMPLETED'
                          ? 'Outcome Pending'
                          : 'Waiting for Booking'}
                      </span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Evaluation Form Modal */}
      {evaluatingApp && (
        <InterviewEvaluationForm
          applicationId={evaluatingApp.id}
          candidateName={evaluatingApp.name}
          onClose={() => setEvaluatingApp(null)}
        />
      )}
    </>
  )
}

import { Metadata } from 'next'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { requireStaff } from '@/lib/auth/helpers'
import InterviewSchedulesManager from './_components/InterviewSchedulesManager'
import InterviewOutcomesTable from './_components/InterviewOutcomesTable'

export const metadata: Metadata = { title: 'Interview Management' }
export const dynamic = 'force-dynamic'

export default async function InterviewsPage() {
  await requireStaff()

  const [applications, schedules] = await Promise.all([
    prismaUnfiltered.application.findMany({
      where: {
        stage: {
          in: ['INTERVIEW_PENDING', 'INTERVIEW_SCHEDULED', 'INTERVIEW_COMPLETED']
        }
      },
      include: {
        user: { include: { profile: true } },
        intakeCycle: true,
        interviewSlot: { include: { schedule: true } }
      },
      orderBy: { updatedAt: 'desc' }
    }),
    prismaUnfiltered.interviewSchedule.findMany({
      include: {
        slots: {
          include: {
            _count: { select: { applications: true } }
          },
          orderBy: { date: 'asc' }
        },
        intakeCycle: true,
      },
      orderBy: { createdAt: 'desc' }
    }),
  ])

  // Format data for the table
  const tableData = applications.map((app) => ({
    id: app.id,
    applicantName: `${app.user.profile?.firstName} ${app.user.profile?.lastName}`,
    email: app.user.email,
    programmeChoice: app.programmeChoice,
    intakeCycle: app.intakeCycle?.name || 'Unknown Cycle',
    stage: app.stage,
    slot: app.interviewSlot ? {
      date: app.interviewSlot.date.toISOString(),
      startTime: app.interviewSlot.startTime.toISOString(),
      endTime: app.interviewSlot.endTime.toISOString(),
      location: app.interviewSlot.location,
    } : null,
    metadata: app.metadata,
  }))

  const scheduleData = schedules.map(s => ({
    ...s,
    startDate: s.startDate.toISOString(),
    endDate: s.endDate.toISOString(),
    createdAt: s.createdAt.toISOString(),
    updatedAt: s.updatedAt.toISOString(),
    slots: s.slots.map(sl => ({
      ...sl,
      date: sl.date.toISOString(),
      startTime: sl.startTime.toISOString(),
      endTime: sl.endTime.toISOString(),
      createdAt: sl.createdAt.toISOString(),
      updatedAt: sl.updatedAt.toISOString(),
    }))
  }))

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div>
        <h1 className="text-3xl font-black tracking-tight text-aerojet-blue dark:text-white">Interview Management</h1>
        <p className="mt-1 text-sm font-medium text-slate-500 dark:text-slate-400">
          Manage interview schedules, slots, and record outcomes for shortlisted candidates.
        </p>
      </div>

      <InterviewSchedulesManager initialSchedules={scheduleData as any} />

      <div>
        <h2 className="text-xl font-black tracking-tight text-slate-900 dark:text-white mb-4">Candidate Interviews</h2>
        <InterviewOutcomesTable data={tableData} />
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import {
  Stethoscope,
  CheckCircle2,
  XCircle,
  ShieldCheck,
  FileText,
  ExternalLink,
  Clock,
  AlertTriangle,
} from 'lucide-react'

interface MedicalApp {
  id: string
  stage: string
  medicalStatus: string | null
  medicalNotes: string | null
  medicalFacility: string | null
  medicalClearedAt: string | null
  user: {
    id: string
    email: string
    name: string | null
    profile: { firstName: string; lastName: string; phone: string | null } | null
  }
  documents: {
    id: string
    status: string
    documentType: { name: string }
    fileUpload: { url: string; filename: string }
  }[]
}

const STAGE_BADGES: Record<string, { label: string; color: string; icon: any }> = {
  MEDICAL_PENDING: { label: 'Awaiting Docs', color: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300', icon: Clock },
  MEDICAL_SUBMITTED: { label: 'Ready for Review', color: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300', icon: FileText },
  MEDICAL_CLEARED: { label: 'Cleared', color: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300', icon: CheckCircle2 },
}

export default function MedicalReviewDashboard({ applications }: { applications: MedicalApp[] }) {
  const router = useRouter()
  const [filter, setFilter] = useState<string>('ALL')
  const [reviewingId, setReviewingId] = useState<string | null>(null)
  const [notes, setNotes] = useState('')
  const [facility, setFacility] = useState('')
  const [loading, setLoading] = useState(false)

  const filtered = filter === 'ALL' ? applications : applications.filter(a => a.stage === filter)

  const handleDecision = async (appId: string, decision: 'CLEARED' | 'FAILED' | 'EXEMPTED') => {
    if (decision === 'FAILED' && !notes.trim()) {
      alert('Please provide notes explaining why the medical review failed')
      return
    }

    setLoading(true)
    try {
      const res = await fetch('/api/staff/admissions/medical/review', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ applicationId: appId, decision, notes, facility }),
      })
      const data = await res.json()
      if (data.success) {
        setReviewingId(null)
        setNotes('')
        setFacility('')
        router.refresh()
      } else {
        alert(data.error || 'Failed to process medical review')
      }
    } catch {
      alert('An error occurred')
    } finally {
      setLoading(false)
    }
  }

  const pendingCount = applications.filter(a => a.stage === 'MEDICAL_PENDING').length
  const submittedCount = applications.filter(a => a.stage === 'MEDICAL_SUBMITTED').length
  const clearedCount = applications.filter(a => a.stage === 'MEDICAL_CLEARED').length

  return (
    <div className="space-y-6">
      {/* Stats Row */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 dark:border-amber-800/50 dark:bg-amber-900/10">
          <div className="flex items-center gap-3">
            <div className="rounded-lg bg-amber-200 p-2 dark:bg-amber-800/50">
              <Clock className="h-5 w-5 text-amber-700 dark:text-amber-300" />
            </div>
            <div>
              <p className="text-2xl font-bold text-amber-800 dark:text-amber-200">{pendingCount}</p>
              <p className="text-xs font-medium text-amber-600 dark:text-amber-400">Awaiting Documents</p>
            </div>
          </div>
        </div>
        <div className="rounded-xl border border-blue-200 bg-blue-50 p-4 dark:border-blue-800/50 dark:bg-blue-900/10">
          <div className="flex items-center gap-3">
            <div className="rounded-lg bg-blue-200 p-2 dark:bg-blue-800/50">
              <FileText className="h-5 w-5 text-blue-700 dark:text-blue-300" />
            </div>
            <div>
              <p className="text-2xl font-bold text-blue-800 dark:text-blue-200">{submittedCount}</p>
              <p className="text-xs font-medium text-blue-600 dark:text-blue-400">Ready for Review</p>
            </div>
          </div>
        </div>
        <div className="rounded-xl border border-green-200 bg-green-50 p-4 dark:border-green-800/50 dark:bg-green-900/10">
          <div className="flex items-center gap-3">
            <div className="rounded-lg bg-green-200 p-2 dark:bg-green-800/50">
              <CheckCircle2 className="h-5 w-5 text-green-700 dark:text-green-300" />
            </div>
            <div>
              <p className="text-2xl font-bold text-green-800 dark:text-green-200">{clearedCount}</p>
              <p className="text-xs font-medium text-green-600 dark:text-green-400">Cleared</p>
            </div>
          </div>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="flex gap-2">
        {[
          { key: 'ALL', label: `All (${applications.length})` },
          { key: 'MEDICAL_SUBMITTED', label: `To Review (${submittedCount})` },
          { key: 'MEDICAL_PENDING', label: `Pending (${pendingCount})` },
          { key: 'MEDICAL_CLEARED', label: `Cleared (${clearedCount})` },
        ].map(tab => (
          <button
            key={tab.key}
            onClick={() => setFilter(tab.key)}
            className={`rounded-lg px-4 py-2 text-sm font-bold transition-colors ${
              filter === tab.key
                ? 'bg-aerojet-blue text-white dark:bg-aerojet-sky'
                : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Applications List */}
      <div className="space-y-4">
        {filtered.length === 0 ? (
          <div className="rounded-xl border border-slate-200 bg-white p-12 text-center dark:border-slate-800 dark:bg-slate-900">
            <Stethoscope className="mx-auto mb-4 h-12 w-12 text-slate-300 dark:text-slate-600" />
            <p className="text-slate-500">No applications in this category.</p>
          </div>
        ) : (
          filtered.map(app => {
            const badge = STAGE_BADGES[app.stage] || STAGE_BADGES.MEDICAL_PENDING
            const BadgeIcon = badge.icon
            const isReviewing = reviewingId === app.id
            const fullName = app.user.profile
              ? `${app.user.profile.firstName} ${app.user.profile.lastName}`
              : app.user.email

            return (
              <div
                key={app.id}
                className="rounded-xl border border-slate-200 bg-white transition-shadow hover:shadow-md dark:border-slate-800 dark:bg-slate-900"
              >
                <div className="flex items-center justify-between p-5">
                  <div className="flex items-center gap-4">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400">
                      <Stethoscope className="h-5 w-5" />
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-900 dark:text-white">{fullName}</h3>
                      <p className="text-sm text-slate-500">{app.user.email}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold ${badge.color}`}>
                      <BadgeIcon className="h-3.5 w-3.5" />
                      {badge.label}
                    </span>
                    {app.stage === 'MEDICAL_SUBMITTED' && !isReviewing && (
                      <button
                        onClick={() => setReviewingId(app.id)}
                        className="rounded-lg bg-aerojet-blue px-4 py-2 text-sm font-bold text-white hover:bg-aerojet-blue/90"
                      >
                        Review
                      </button>
                    )}
                  </div>
                </div>

                {/* Documents */}
                {app.documents.length > 0 && (
                  <div className="border-t border-slate-100 px-5 py-3 dark:border-slate-800">
                    <p className="mb-2 text-xs font-bold text-slate-500">Uploaded Documents</p>
                    <div className="flex flex-wrap gap-2">
                      {app.documents.map(doc => (
                        <a
                          key={doc.id}
                          href={doc.fileUpload.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-slate-50 px-3 py-1.5 text-xs font-medium text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
                        >
                          <FileText className="h-3.5 w-3.5" />
                          {doc.documentType.name}
                          <ExternalLink className="h-3 w-3 text-slate-400" />
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                {/* Review Form */}
                {isReviewing && (
                  <div className="border-t border-aerojet-blue/20 bg-aerojet-blue/5 p-5 dark:border-aerojet-sky/20 dark:bg-aerojet-sky/5">
                    <h4 className="mb-4 font-bold text-aerojet-blue dark:text-aerojet-sky">Medical Review Decision</h4>
                    <div className="grid gap-4 sm:grid-cols-2">
                      <div>
                        <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Facility Name</label>
                        <input
                          type="text"
                          className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                          value={facility}
                          onChange={e => setFacility(e.target.value)}
                          placeholder="e.g. Korle-Bu Teaching Hospital"
                        />
                      </div>
                      <div>
                        <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Notes</label>
                        <input
                          type="text"
                          className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                          value={notes}
                          onChange={e => setNotes(e.target.value)}
                          placeholder="Any additional notes..."
                        />
                      </div>
                    </div>
                    <div className="mt-4 flex gap-3">
                      <button
                        onClick={() => handleDecision(app.id, 'CLEARED')}
                        disabled={loading}
                        className="flex items-center gap-2 rounded-lg bg-green-600 px-5 py-2 text-sm font-bold text-white hover:bg-green-700 disabled:opacity-50"
                      >
                        <CheckCircle2 className="h-4 w-4" /> Clear
                      </button>
                      <button
                        onClick={() => handleDecision(app.id, 'EXEMPTED')}
                        disabled={loading}
                        className="flex items-center gap-2 rounded-lg bg-blue-600 px-5 py-2 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-50"
                      >
                        <ShieldCheck className="h-4 w-4" /> Exempt
                      </button>
                      <button
                        onClick={() => handleDecision(app.id, 'FAILED')}
                        disabled={loading}
                        className="flex items-center gap-2 rounded-lg bg-red-600 px-5 py-2 text-sm font-bold text-white hover:bg-red-700 disabled:opacity-50"
                      >
                        <XCircle className="h-4 w-4" /> Fail
                      </button>
                      <button
                        onClick={() => { setReviewingId(null); setNotes(''); setFacility(''); }}
                        className="rounded-lg border border-slate-300 px-5 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300"
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                )}

                {/* Existing clearance info */}
                {app.medicalClearedAt && (
                  <div className="border-t border-green-200 bg-green-50/50 px-5 py-3 text-sm text-green-800 dark:border-green-800/50 dark:bg-green-900/10 dark:text-green-300">
                    Cleared on {new Date(app.medicalClearedAt).toLocaleDateString()}
                    {app.medicalFacility && ` — ${app.medicalFacility}`}
                  </div>
                )}
              </div>
            )
          })
        )}
      </div>
    </div>
  )
}

import { Metadata } from 'next'
import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import MedicalReviewDashboard from './_components/MedicalReviewDashboard'

export const metadata: Metadata = { title: 'Medical Review | Admissions' }
export const dynamic = 'force-dynamic'

export default async function MedicalPage() {
  await requireStaff()

  const applications = await prismaUnfiltered.application.findMany({
    where: {
      stage: { in: ['MEDICAL_PENDING', 'MEDICAL_SUBMITTED', 'MEDICAL_CLEARED'] },
    },
    include: {
      user: {
        select: {
          id: true,
          email: true,
          profile: { select: { firstName: true, lastName: true, phone: true } },
        },
      },
      documents: {
        where: {
          documentType: { slug: { contains: 'medical' } },
        },
        include: {
          documentType: { select: { name: true } },
          fileUpload: { select: { url: true, filename: true } },
        },
      },
    },
    orderBy: { updatedAt: 'desc' },
  })

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-black text-aerojet-blue uppercase dark:text-white sm:text-3xl">
          Medical Review
        </h1>
        <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
          Review medical examination documents and clear applicants for enrollment.
        </p>
      </div>

      <MedicalReviewDashboard applications={applications as any} />
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  CheckCircle2,
  XCircle,
  FileText,
  Search,
  Filter,
  CheckSquare,
  Square,
  AlertCircle,
  Edit2,
  ChevronDown,
  BarChart3,
  Users,
  ClipboardList,
} from 'lucide-react'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

interface ScoreData {
  compositeScore: number
  aptitudeScore: number
  aptitudePercentile: number | null
  profileScore: number
  referralScore: number
  experienceScore: number
  interviewScore: number | null
  interviewEvaluatorCount: number
  isAutoShortlist: boolean
  isAutoReject: boolean
  mathRawScore: number | null
  mathPercentile: number | null
  verbalRawScore: number | null
  verbalPercentile: number | null
  engineeringRawScore: number | null
  engineeringPercentile: number | null
  reasoningRawScore: number | null
  reasoningPercentile: number | null
}

interface ApplicationRow {
  id: string
  applicantName: string
  email: string
  programmeChoice: string
  intakeCycle: string
  cvUrl: string | null
  scores: ScoreData
  metadata: any
}

function PercentileBar({ label, percentile, raw }: { label: string; percentile: number | null; raw?: string }) {
  if (percentile == null) return null
  const color =
    percentile >= 75 ? 'bg-green-500' : percentile >= 50 ? 'bg-blue-500' : percentile >= 25 ? 'bg-amber-500' : 'bg-red-500'
  const textColor =
    percentile >= 75
      ? 'text-green-700 dark:text-green-400'
      : percentile >= 50
        ? 'text-blue-700 dark:text-blue-400'
        : percentile >= 25
          ? 'text-amber-700 dark:text-amber-400'
          : 'text-red-700 dark:text-red-400'

  return (
    <div className="flex items-center gap-2">
      <span className="w-20 text-xs text-slate-500">{label}</span>
      <div className="relative h-2 flex-1 rounded-full bg-slate-200 dark:bg-slate-700">
        <div className={`absolute left-0 top-0 h-2 rounded-full ${color}`} style={{ width: `${Math.min(percentile, 100)}%` }} />
      </div>
      <span className={`w-10 text-right text-xs font-bold ${textColor}`}>P{Math.round(percentile)}</span>
      {raw && <span className="w-8 text-right text-xs text-slate-400">{raw}</span>}
    </div>
  )
}

function PercentileBadge({ value }: { value: number | null }) {
  if (value == null) return <span className="text-xs text-slate-400">--</span>
  const color =
    value >= 75
      ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
      : value >= 50
        ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
        : value >= 25
          ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'
          : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
  return (
    <span className={`rounded-full px-2 py-0.5 text-xs font-bold ${color}`}>P{Math.round(value)}</span>
  )
}

export default function ShortlistingTable({ data }: { data: ApplicationRow[] }) {
  const router = useRouter()
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
  const [search, setSearch] = useState('')
  const [processing, setProcessing] = useState(false)
  const [editingScoreId, setEditingScoreId] = useState<string | null>(null)
  const [tempScore, setTempScore] = useState<string>('')
  const [expandedId, setExpandedId] = useState<string | null>(null)

  const filteredData = data.filter(
    (row) =>
      row.applicantName.toLowerCase().includes(search.toLowerCase()) ||
      row.email.toLowerCase().includes(search.toLowerCase()) ||
      row.programmeChoice.toLowerCase().includes(search.toLowerCase())
  )

  const { items: sortedData, requestSort, sortConfig } = useSort(filteredData)
  const displayData = sortedData

  const toggleSelectAll = () => {
    if (selectedIds.size === displayData.length && displayData.length > 0) {
      setSelectedIds(new Set())
    } else {
      setSelectedIds(new Set(displayData.map((d) => d.id)))
    }
  }

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds)
    if (next.has(id)) next.delete(id)
    else next.add(id)
    setSelectedIds(next)
  }

  const handleAction = async (action: 'SHORTLIST' | 'REJECT', ids: string[]) => {
    if (ids.length === 0) return
    let reason = ''
    if (action === 'REJECT') {
      const input = prompt('Enter rejection reason (optional):')
      if (input === null) return
      reason = input
    }

    if (!confirm(`Are you sure you want to ${action.toLowerCase()} ${ids.length} candidate(s)?`)) return

    setProcessing(true)
    try {
      const res = await fetch('/api/staff/admissions/shortlist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ applicationIds: ids, action, reason }),
      })

      if (res.ok) {
        setSelectedIds(new Set())
        router.refresh()
      } else {
        const err = await res.json()
        toast.error(err.error || 'Failed to process applications')
      }
    } finally {
      setProcessing(false)
    }
  }

  const handleSaveScore = async (id: string) => {
    const score = parseInt(tempScore)
    if (isNaN(score) || score < 0 || score > 100) {
      toast.error('Score must be between 0 and 100')
      return
    }

    try {
      const res = await fetch(`/api/staff/admissions/shortlist/${id}/score`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ experienceScore: score }),
      })
      if (res.ok) {
        setEditingScoreId(null)
        router.refresh()
      }
    } catch (e) {
      toast.error('Failed to load shortlist')
    }
  }

  return (
    <div className="rounded-2xl border border-slate-200 bg-white shadow-xs dark:border-slate-800 dark:bg-slate-900">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-200 p-4 dark:border-slate-800">
        <div className="flex items-center gap-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Search applicants..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-64 rounded-lg border border-slate-200 py-2 pl-9 pr-4 text-sm dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
          <button className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300 dark:hover:bg-slate-800">
            <Filter className="h-4 w-4" />
            Filter
          </button>
        </div>

        {selectedIds.size > 0 && (
          <div className="flex items-center gap-2 animate-in fade-in slide-in-from-bottom-2">
            <span className="mr-2 text-sm font-medium text-slate-600 dark:text-slate-300">
              {selectedIds.size} selected
            </span>
            <button
              onClick={() => handleAction('REJECT', Array.from(selectedIds))}
              disabled={processing}
              className="flex items-center gap-1.5 rounded-lg border border-red-200 bg-red-50 px-3 py-1.5 text-sm font-medium text-red-600 hover:bg-red-100 disabled:opacity-50 dark:border-red-900/50 dark:bg-red-900/20 dark:text-red-400"
            >
              <XCircle className="h-4 w-4" />
              Reject Selected
            </button>
            <button
              onClick={() => handleAction('SHORTLIST', Array.from(selectedIds))}
              disabled={processing}
              className="flex items-center gap-1.5 rounded-lg bg-green-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-green-700 disabled:opacity-50"
            >
              <CheckCircle2 className="h-4 w-4" />
              Shortlist Selected
            </button>
          </div>
        )}
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-slate-500 dark:bg-slate-800/50 dark:text-slate-400">
            <tr>
              <th className="px-4 py-3 font-medium">
                <button onClick={toggleSelectAll} className="text-slate-400 hover:text-slate-600">
                  {selectedIds.size === displayData.length && displayData.length > 0 ? (
                    <CheckSquare className="h-5 w-5 text-aerojet-blue" />
                  ) : (
                    <Square className="h-5 w-5" />
                  )}
                </button>
              </th>
              <SortHeader label="Candidate" sortKey="applicantName" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" />
              <SortHeader label="Programme" sortKey="programmeChoice" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" />
              <SortHeader label="Aptitude" sortKey="scores.aptitudeScore" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" align="right" />
              <SortHeader label="Percentile" sortKey="scores.aptitudePercentile" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" align="right" />
              <SortHeader label="Interview" sortKey="scores.interviewScore" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" align="right" />
              <SortHeader label="Exp." sortKey="scores.experienceScore" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" align="right" />
              <SortHeader label="Composite" sortKey="scores.compositeScore" currentSort={sortConfig} onSort={requestSort} className="px-4 py-3 font-medium" align="right" />
              <th className="px-4 py-3 font-medium">Status</th>
              <th className="px-4 py-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
            {displayData.length === 0 ? (
              <tr>
                <td colSpan={10} className="py-8 text-center text-slate-500">
                  No applicants pending shortlisting.
                </td>
              </tr>
            ) : (
              displayData.map((row) => {
                const isExpanded = expandedId === row.id
                return (
                  <tr key={row.id} className="group">
                    <td className="px-4 py-4 align-top">
                      <button onClick={() => toggleSelect(row.id)} className="text-slate-400">
                        {selectedIds.has(row.id) ? (
                          <CheckSquare className="h-5 w-5 text-aerojet-blue" />
                        ) : (
                          <Square className="h-5 w-5" />
                        )}
                      </button>
                    </td>
                    <td className="px-4 py-4 align-top">
                      <div className="font-medium text-slate-900 dark:text-white">{row.applicantName}</div>
                      <div className="text-xs text-slate-500">{row.email}</div>
                      <div className="mt-1 flex gap-2">
                        {row.cvUrl && (
                          <a
                            href={row.cvUrl}
                            target="_blank"
                            rel="noreferrer"
                            className="flex items-center gap-1 text-xs font-medium text-aerojet-blue hover:underline"
                          >
                            <FileText className="h-3 w-3" /> CV
                          </a>
                        )}
                        <button
                          onClick={() => setExpandedId(isExpanded ? null : row.id)}
                          className="flex items-center gap-1 text-xs font-medium text-indigo-600 hover:underline dark:text-indigo-400"
                        >
                          <BarChart3 className="h-3 w-3" />
                          {isExpanded ? 'Hide' : 'Detail'}
                          <ChevronDown className={`h-3 w-3 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                        </button>
                      </div>

                      {/* Expanded sub-score breakdown */}
                      {isExpanded && (
                        <div className="mt-3 w-72 space-y-1.5 rounded-lg border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-800/50">
                          <p className="mb-2 text-xs font-bold text-slate-600 dark:text-slate-300">
                            Aptitude Sub-Scores (Criteria-Style)
                          </p>
                          <PercentileBar
                            label="Math"
                            percentile={row.scores.mathPercentile}
                            raw={row.scores.mathRawScore != null ? String(row.scores.mathRawScore) : undefined}
                          />
                          <PercentileBar
                            label="Verbal"
                            percentile={row.scores.verbalPercentile}
                            raw={row.scores.verbalRawScore != null ? String(row.scores.verbalRawScore) : undefined}
                          />
                          <PercentileBar
                            label="Engineering"
                            percentile={row.scores.engineeringPercentile}
                            raw={row.scores.engineeringRawScore != null ? String(row.scores.engineeringRawScore) : undefined}
                          />
                          <PercentileBar
                            label="Reasoning"
                            percentile={row.scores.reasoningPercentile}
                            raw={row.scores.reasoningRawScore != null ? String(row.scores.reasoningRawScore) : undefined}
                          />
                          {row.scores.interviewScore != null && (
                            <div className="mt-2 border-t border-slate-200 pt-2 dark:border-slate-700">
                              <div className="flex items-center gap-2 text-xs">
                                <Users className="h-3 w-3 text-purple-500" />
                                <span className="text-slate-500">Interview Avg:</span>
                                <span className="font-bold text-purple-700 dark:text-purple-400">
                                  {row.scores.interviewScore}/100
                                </span>
                                <span className="text-slate-400">
                                  ({row.scores.interviewEvaluatorCount} evaluator{row.scores.interviewEvaluatorCount !== 1 ? 's' : ''})
                                </span>
                              </div>
                            </div>
                          )}
                        </div>
                      )}
                    </td>
                    <td className="px-4 py-4 align-top">
                      <div className="text-slate-600 dark:text-slate-300">{row.programmeChoice}</div>
                      <div className="text-xs text-slate-500">{row.intakeCycle}</div>
                    </td>
                    <td className="px-4 py-4 align-top">
                      <div className="inline-flex items-center gap-1.5 rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-700 dark:bg-slate-800 dark:text-slate-300">
                        {row.scores.aptitudeScore}%
                      </div>
                    </td>
                    <td className="px-4 py-4 align-top">
                      <PercentileBadge value={row.scores.aptitudePercentile} />
                    </td>
                    <td className="px-4 py-4 align-top">
                      {row.scores.interviewScore != null ? (
                        <div className="flex items-center gap-1">
                          <span className="text-sm font-bold text-purple-700 dark:text-purple-400">
                            {row.scores.interviewScore}
                          </span>
                          <span className="text-xs text-slate-400">
                            /{row.scores.interviewEvaluatorCount}
                          </span>
                        </div>
                      ) : (
                        <span className="text-xs text-slate-400">--</span>
                      )}
                    </td>
                    <td className="px-4 py-4 align-top">
                      {editingScoreId === row.id ? (
                        <div className="flex items-center gap-2">
                          <input
                            type="number"
