'use client'

import { useState, useEffect } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { UserCheck, X, Mail, Calendar, Clock } from 'lucide-react'
import { toast } from 'sonner'
import UserJourneyTimeline from './UserJourneyTimeline'
import UserSearchInput from './UserSearchInput'

interface UserProfile {
  id: string
  email: string
  role: string
  createdAt: string
  lastSeenAt: string | null
  firstName: string | null
  lastName: string | null
  avatarUrl: string | null
  studentId: string | null
}

interface JourneyData {
  user: UserProfile
  events: Array<{
    event: string
    entity: string
    timestamp: string
    payload: Record<string, any>
  }>
}

export default function UserJourney() {
  const [userId, setUserId] = useState('')
  const [data, setData] = useState<JourneyData | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const loadJourney = async (id: string) => {
    if (!id.trim()) return
    setLoading(true)
    setError(null)
    try {
      const res = await fetch(`/api/staff/analytics/journey/${encodeURIComponent(id)}`)
      const json = await res.json()
      if (json.success) {
        setData(json.data)
      } else if (res.status === 404) {
        setError('User not found. Please check the user ID.')
        setData(null)
      } else {
        setError(json.error || 'Failed to load journey')
        setData(null)
      }
    } catch (err) {
      toast.error('Failed to load user journey')
      setError('Network error. Please try again.')
      setData(null)
    } finally {
      setLoading(false)
    }
  }

  const handleSelect = (id: string) => {
    setUserId(id)
    setError(null)
    setData(null)
    loadJourney(id)
  }

  const handleClear = () => {
    setUserId('')
    setData(null)
    setError(null)
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <UserCheck className="h-5 w-5 text-aerojet-sky" />
            User Journey
          </CardTitle>
          <p className="text-xs text-slate-500 dark:text-slate-400">
            Track a specific user&apos;s event timeline across the platform
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex gap-4">
            <UserSearchInput
              onSelect={handleSelect}
              onTrack={() => loadJourney(userId)}
              loading={loading}
              disabled={!userId.trim()}
            />
            {userId && (
              <Button
                onClick={handleClear}
                variant="outline"
                size="icon"
                className="rounded-xl border-slate-200 dark:border-slate-700"
                title="Clear selection"
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>
          {error && (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700 dark:border-red-900 dark:bg-red-900/10 dark:text-red-400">
              {error}
            </div>
          )}
        </CardContent>
      </Card>

      {data && (
        <div className="space-y-4">
          <UserProfileCard user={data.user} />
          <UserJourneyTimeline events={data.events} />
        </div>
      )}
    </div>
  )
}

function UserProfileCard({ user }: { user: UserProfile }) {
  const fullName = [user.firstName, user.lastName].filter(Boolean).join(' ') || 'Unknown User'
  const initials = fullName
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)

  return (
    <Card className="overflow-hidden">
      <CardContent className="p-0">
        <div className="flex flex-col sm:flex-row">
          <div className="flex h-24 w-full items-center justify-center bg-gradient-to-br from-aerojet-blue/10 to-aerojet-sky/10 sm:h-auto sm:w-24 dark:from-aerojet-blue/20 dark:to-aerojet-sky/20">
            {user.avatarUrl ? (
              <img
                src={user.avatarUrl}
                alt={fullName}
                className="h-20 w-20 rounded-full object-cover ring-4 ring-white dark:ring-slate-900"
              />
            ) : (
              <div className="flex h-20 w-20 items-center justify-center rounded-full bg-aerojet-blue text-2xl font-black text-white ring-4 ring-white dark:ring-slate-900">
                {initials}
              </div>
            )}
          </div>
          <div className="flex-1 p-4 sm:p-6">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
              <div>
                <h3 className="text-lg font-black text-slate-900 dark:text-white">{fullName}</h3>
                <div className="mt-1 flex flex-wrap items-center gap-3 text-xs text-slate-500 dark:text-slate-400">
                  <span className="flex items-center gap-1">
                    <Mail className="h-3.5 w-3.5" />
                    {user.email}
                  </span>
                  {user.studentId && (
                    <span className="flex items-center gap-1 rounded-full bg-slate-100 px-2 py-0.5 font-mono dark:bg-slate-800">
                      ID: {user.studentId}
                    </span>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-2">
                <span className="rounded-full bg-aerojet-blue/10 px-3 py-1 text-[10px] font-black uppercase tracking-widest text-aerojet-blue dark:bg-aerojet-blue/20">
                  {user.role}
                </span>
              </div>
            </div>
            <div className="mt-4 flex flex-wrap gap-4 border-t border-slate-100 pt-3 dark:border-slate-800">
              <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                <Calendar className="h-3.5 w-3.5" />
                <span>Joined {new Date(user.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
              </div>
              {user.lastSeenAt && (
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                  <Clock className="h-3.5 w-3.5" />
                  <span>Active {new Date(user.lastSeenAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Search, Loader2 } from 'lucide-react'
import { toast } from 'sonner'

interface Student {
  id: string
  email: string
  profile: {
    firstName: string | null
    lastName: string | null
  } | null
  studentProfile: {
    studentId: string | null
  } | null
}

interface UserSearchInputProps {
  onSelect: (userId: string) => void
  onTrack: () => void
  loading: boolean
  disabled: boolean
}

export default function UserSearchInput({ onSelect, onTrack, loading, disabled }: UserSearchInputProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [students, setStudents] = useState<Student[]>([])
  const [searching, setSearching] = useState(false)
  const [selectedId, setSelectedId] = useState('')
  const wrapperRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined)

  const fetchStudents = useCallback(async (searchQuery: string) => {
    setSearching(true)
    try {
      const res = await fetch(`/api/staff/users/search?q=${encodeURIComponent(searchQuery)}`)
      const json = await res.json()
      if (json.success) {
        setStudents(json.data)
      }
    } catch (err) {
      toast.error('Search failed')
    } finally {
      setSearching(false)
    }
  }, [])

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      fetchStudents(query)
    }, 200)
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [query, fetchStudents])

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleFocus = () => {
    setIsOpen(true)
    if (students.length === 0 && !query) {
      fetchStudents('')
    }
  }

  const handleSelect = (student: Student) => {
    setSelectedId(student.id)
    onSelect(student.id)
    setIsOpen(false)
    setQuery('')
  }

  const displayName = (student: Student) => {
    const name = [student.profile?.firstName, student.profile?.lastName].filter(Boolean).join(' ')
    return name || 'Unknown'
  }

  return (
    <div ref={wrapperRef} className="relative flex-1">
      <div className="relative">
        <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
        <Input
          ref={inputRef}
          value={isOpen ? query : (selectedId ? '' : query)}
          onChange={(e) => {
            setQuery(e.target.value)
            if (!isOpen) setIsOpen(true)
            if (selectedId) setSelectedId('')
          }}
          onFocus={handleFocus}
          placeholder="Search students by name, email, or ID..."
          className="rounded-xl border-slate-200 bg-white pl-9 pr-10 font-bold dark:border-slate-700 dark:bg-slate-900"
          onKeyDown={(e) => e.key === 'Enter' && !isOpen && onTrack()}
        />
        {searching && (
          <Loader2 className="absolute right-3 top-2.5 h-4 w-4 animate-spin text-slate-400" />
        )}
      </div>

      {isOpen && (
        <div className="absolute z-50 mt-1 max-h-64 w-full overflow-auto rounded-xl border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-slate-900">
          {students.length === 0 && !searching && (
            <div className="px-3 py-4 text-center text-xs text-slate-500">
              {query.length < 2 ? 'Type at least 2 characters to search...' : 'No students found'}
            </div>
          )}
          {students.map((student) => (
            <button
              key={student.id}
              type="button"
              onClick={() => handleSelect(student)}
              className="flex w-full flex-col gap-0.5 px-3 py-2.5 text-left hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
            >
              <span className="text-sm font-bold text-slate-900 dark:text-slate-100">
                {displayName(student)}
              </span>
              <span className="text-xs text-slate-500 dark:text-slate-400">
                {student.email} {student.studentProfile?.studentId ? `• ${student.studentProfile.studentId}` : ''}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useTransition, useMemo } from 'react'
import { Plus, Edit2, Shield, Loader2, ArrowUp, ArrowDown, ArrowUpDown, ChevronDown } from 'lucide-react'
import { upsertATAChapter, toggleATAChapterStatus } from '../actions'

interface ATAChapter {
  id: string
  code: string
  title: string
  description: string | null
  category: string
  sortOrder: number
  isActive: boolean
}

type SortField = 'code' | 'title' | 'sortOrder' | 'isActive'

export default function ATAChaptersClient({
  initialChapters,
}: {
  initialChapters: ATAChapter[]
}) {
  const [chapters, setChapters] = useState(initialChapters)
  const [isPending, startTransition] = useTransition()
  const [editingChapter, setEditingChapter] = useState<ATAChapter | null>(null)
  const [isModalOpen, setIsModalOpen] = useState(false)

  // Sorting and Grouping State
  const [sortField, setSortField] = useState<SortField>('sortOrder')
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc')
  const [openCategories, setOpenCategories] = useState<Record<string, boolean>>({
    GENERAL: true,
    AIRFRAME: true,
    AVIONICS: true,
    POWERPLANT: true,
  })

  // Form state
  const [code, setCode] = useState('')
  const [title, setTitle] = useState('')
  const [description, setDescription] = useState('')
  const [category, setCategory] = useState<'AIRFRAME' | 'POWERPLANT' | 'AVIONICS' | 'GENERAL'>('GENERAL')
  const [sortOrder, setSortOrder] = useState<number>(0)
  const [isActive, setIsActive] = useState(true)

  const openModal = (chapter?: ATAChapter) => {
    if (chapter) {
      setEditingChapter(chapter)
      setCode(chapter.code)
      setTitle(chapter.title)
      setDescription(chapter.description || '')
      setCategory(chapter.category as 'AIRFRAME' | 'POWERPLANT' | 'AVIONICS' | 'GENERAL')
      setSortOrder(chapter.sortOrder)
      setIsActive(chapter.isActive)
    } else {
      setEditingChapter(null)
      setCode('')
      setTitle('')
      setDescription('')
      setCategory('GENERAL')
      setSortOrder(chapters.length > 0 ? Math.max(...chapters.map((c) => c.sortOrder)) + 10 : 10)
      setIsActive(true)
    }
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
    setEditingChapter(null)
  }

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault()
    startTransition(async () => {
      const res = await upsertATAChapter({
        id: editingChapter?.id,
        code,
        title,
        description,
        category,
        sortOrder,
        isActive,
      })

      if (!res.success) {
        alert(res.error || 'Failed to save chapter')
      } else {
        closeModal()
        window.location.reload()
      }
    })
  }

  const handleToggleStatus = async (id: string, currentStatus: boolean) => {
    startTransition(async () => {
      const res = await toggleATAChapterStatus(id, !currentStatus)
      if (!res.success) {
        alert(res.error || 'Failed to toggle status')
      } else {
        window.location.reload()
      }
    })
  }

  const toggleCategory = (cat: string) => {
    setOpenCategories((prev) => ({ ...prev, [cat]: !prev[cat] }))
  }

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'))
    } else {
      setSortField(field)
      setSortDirection('asc')
    }
  }

  const sortedChapters = useMemo(() => {
    return [...chapters].sort((a, b) => {
      let comparison = 0
      if (sortField === 'code') comparison = a.code.localeCompare(b.code)
      if (sortField === 'title') comparison = a.title.localeCompare(b.title)
      if (sortField === 'sortOrder') comparison = a.sortOrder - b.sortOrder
      if (sortField === 'isActive') {
        comparison = a.isActive === b.isActive ? 0 : a.isActive ? -1 : 1
      }
      return sortDirection === 'asc' ? comparison : -comparison
    })
  }, [chapters, sortField, sortDirection])

  const CATEGORIES = ['GENERAL', 'AIRFRAME', 'AVIONICS', 'POWERPLANT']

  const SortIndicator = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <ArrowUpDown className="ml-1 mb-0.5 inline-block h-3 w-3 opacity-30" />
    return sortDirection === 'asc' ? (
      <ArrowUp className="ml-1 mb-0.5 inline-block h-3 w-3 text-blue-600 dark:text-blue-400" />
    ) : (
      <ArrowDown className="ml-1 mb-0.5 inline-block h-3 w-3 text-blue-600 dark:text-blue-400" />
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold tracking-tight text-slate-800 dark:text-white">
          Chapter Directory
        </h2>
        <button
          onClick={() => openModal()}
          className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-blue-700"
        >
          <Plus className="h-4 w-4" />
          Add Chapter
        </button>
      </div>

      <div className="space-y-4">
        {CATEGORIES.map((categoryName) => {
          const items = sortedChapters.filter((c) => c.category === categoryName)
          if (items.length === 0) return null

          const isOpen = openCategories[categoryName]

          return (
            <div
              key={categoryName}
              className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900"
            >
              <button
                onClick={() => toggleCategory(categoryName)}
                className="flex w-full items-center justify-between bg-slate-50 px-4 py-3 text-left transition-colors hover:bg-slate-100 dark:bg-slate-800 dark:hover:bg-slate-700/80"
              >
                <div className="flex items-center gap-3">
                  <ChevronDown
                    className={`h-5 w-5 text-slate-400 transition-transform ${
                      isOpen ? '' : '-rotate-90'
                    }`}
                  />
                  <h3 className="font-bold text-slate-800 dark:text-white">
                    {categoryName} CHAPTERS
                  </h3>
                  <span className="rounded-full bg-slate-200 px-2 py-0.5 text-xs font-semibold text-slate-600 dark:bg-slate-700 dark:text-slate-300">
                    {items.length}
                  </span>
                </div>
              </button>

              {isOpen && (
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-y border-slate-200/60 bg-white dark:border-slate-700/60 dark:bg-slate-900">
                      <th
                        className="cursor-pointer select-none px-4 py-3 text-left font-semibold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                        onClick={() => handleSort('code')}
                      >
                        ATA Code <SortIndicator field="code" />
                      </th>
                      <th
                        className="cursor-pointer select-none px-4 py-3 text-left font-semibold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                        onClick={() => handleSort('title')}
                      >
                        Title <SortIndicator field="title" />
                      </th>
                      <th
                        className="cursor-pointer select-none px-4 py-3 text-center font-semibold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                        onClick={() => handleSort('sortOrder')}
                      >
                        Order <SortIndicator field="sortOrder" />
                      </th>
                      <th
                        className="cursor-pointer select-none px-4 py-3 text-center font-semibold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                        onClick={() => handleSort('isActive')}
                      >
                        Status <SortIndicator field="isActive" />
                      </th>
                      <th className="px-4 py-3 text-right font-semibold text-slate-500 dark:text-slate-400">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200/60 dark:divide-slate-700/60">
                    {items.map((chapter) => (
                      <tr
                        key={chapter.id}
                        className="transition-colors hover:bg-slate-50/50 dark:hover:bg-slate-800/50"
                      >
                        <td className="w-32 px-4 py-3 font-mono font-medium text-slate-900 dark:text-white">
                          {chapter.code}
                        </td>
                        <td className="px-4 py-3 text-slate-700 dark:text-slate-300">
                          <div className="font-semibold">{chapter.title}</div>
                          {chapter.description && (
                            <div className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">
                              {chapter.description}
                            </div>
                          )}
                        </td>
                        <td className="w-24 px-4 py-3 text-center font-mono text-slate-500">
                          {chapter.sortOrder}
                        </td>
                        <td className="w-28 px-4 py-3 text-center">
                          <button
                            onClick={() => handleToggleStatus(chapter.id, chapter.isActive)}
                            disabled={isPending}
                            className={`inline-flex rounded-full px-2.5 py-0.5 text-xs font-semibold ${
                              chapter.isActive
                                ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:hover:bg-emerald-500/20'
                                : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:hover:bg-slate-700'
                            }`}
                          >
                            {chapter.isActive ? 'Active' : 'Inactive'}
                          </button>
                        </td>
                        <td className="w-20 px-4 py-3 text-right">
                          <button
                            onClick={() => openModal(chapter)}
                            className="inline-flex items-center rounded-md p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-700 dark:hover:bg-slate-800 dark:hover:text-slate-300"
                          >
                            <Edit2 className="h-4 w-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          )
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
          <div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl dark:bg-slate-900">
            <h3 className="mb-4 text-lg font-bold text-slate-900 dark:text-white">
              {editingChapter ? 'Edit ATA Chapter' : 'Add ATA Chapter'}
            </h3>
            <form onSubmit={handleSave} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                    ATA Code (e.g. 21)
                  </label>
                  <input
                    type="text"
                    required
                    value={code}
                    onChange={(e) => setCode(e.target.value)}
                    className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:focus:border-blue-500"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                    Category
                  </label>
                  <select
                    value={category}
                    onChange={(e) => setCategory(e.target.value as 'AIRFRAME' | 'POWERPLANT' | 'AVIONICS' | 'GENERAL')}
                    className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:focus:border-blue-500"
                  >
                    <option value="GENERAL">General</option>
                    <option value="AIRFRAME">Airframe</option>
                    <option value="POWERPLANT">Powerplant</option>
                    <option value="AVIONICS">Avionics</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                  Title
                </label>
                <input
                  type="text"
                  required
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:focus:border-blue-500"
                />
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                  Description (Optional)
                </label>
                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="h-20 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:focus:border-blue-500"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                    Sort Order
                  </label>
                  <input
                    type="number"
                    required
                    value={sortOrder}
                    onChange={(e) => setSortOrder(parseInt(e.target.value) || 0)}
                    className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:focus:border-blue-500"
                  />
                </div>
                <div className="flex items-center pt-6">
                  <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300">
                    <input
                      type="checkbox"
                      checked={isActive}
                      onChange={(e) => setIsActive(e.target.checked)}
                      className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 dark:border-slate-600 dark:bg-slate-700 dark:checked:bg-blue-500"
                    />
                    Active Status
                  </label>
                </div>
              </div>

              <div className="mt-6 flex justify-end gap-3">
                <button
                  type="button"
                  onClick={closeModal}
                  className="rounded-lg px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isPending}
                  className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
                >
                  {isPending && <Loader2 className="h-4 w-4 animate-spin" />}
                  Save Chapter
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use server'

import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { revalidatePath } from 'next/cache'

export async function upsertATAChapter(data: {
  id?: string
  code: string
  title: string
  description?: string
  category: 'AIRFRAME' | 'POWERPLANT' | 'AVIONICS' | 'GENERAL'
  sortOrder: number
  isActive: boolean
}) {
  const staff = await requireStaff()

  try {
    if (data.id) {
      await prismaUnfiltered.aTAChapter.update({
        where: { id: data.id },
        data: {
          code: data.code,
          title: data.title,
          description: data.description,
          category: data.category,
          sortOrder: data.sortOrder,
          isActive: data.isActive,
        },
      })
    } else {
      await prismaUnfiltered.aTAChapter.create({
        data: {
          code: data.code,
          title: data.title,
          description: data.description,
          category: data.category,
          sortOrder: data.sortOrder,
          isActive: data.isActive,
        },
      })
    }

    revalidatePath('/staff/ata-chapters')
    return { success: true }
  } catch (error: any) {
    return { success: false, error: error.message }
  }
}

export async function toggleATAChapterStatus(id: string, isActive: boolean) {
  const staff = await requireStaff()

  try {
    await prismaUnfiltered.aTAChapter.update({
      where: { id },
      data: { isActive },
    })

    revalidatePath('/staff/ata-chapters')
    return { success: true }
  } catch (error: any) {
    return { success: false, error: error.message }
  }
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import {
  CheckCircle2,
  XCircle,
  Clock,
  ShieldCheck,
  Loader2,
  Users,
  Calendar,
  Save,
  AlertTriangle,
} from 'lucide-react'

const STATUSES = ['PRESENT', 'ABSENT', 'LATE', 'EXCUSED'] as const
type Status = typeof STATUSES[number]

const STATUS_CONFIG: Record<Status, { label: string; color: string; icon: any }> = {
  PRESENT: { label: 'Present', color: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300', icon: CheckCircle2 },
  ABSENT: { label: 'Absent', color: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300', icon: XCircle },
  LATE: { label: 'Late', color: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300', icon: Clock },
  EXCUSED: { label: 'Excused', color: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300', icon: ShieldCheck },
}

interface StudentRecord {
  userId: string
  status: Status
  minutesLate?: number
  notes?: string
  profile?: { firstName: string; lastName: string }
  studentId?: string
  email?: string
}

interface ClassOption {
  id: string
  name: string
  courseId: string
}

export default function AttendanceManager({ classes }: { classes: ClassOption[] }) {
  const [classId, setClassId] = useState(classes[0]?.id || '')
  const [date, setDate] = useState(new Date().toISOString().split('T')[0])
  const [students, setStudents] = useState<StudentRecord[]>([])
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [stats, setStats] = useState<{ total: number; present: number; rate: number } | null>(null)

  const fetchRoster = useCallback(async () => {
    if (!classId) return
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/attendance?classId=${classId}&date=${date}`)
      const json = await res.json()
      if (json.data) {
        const { records, roster, stats } = json.data

        // Build student list from roster, merging existing records
        const existingMap = new Map<string, any>(records.map((r: any) => [r.userId, r]))
        const merged: StudentRecord[] = roster.map((u: any) => {
          const existing = existingMap.get(u.id) as StudentRecord | undefined
          return {
            userId: u.id,
            status: existing?.status || 'PRESENT',
            minutesLate: existing?.minutesLate || undefined,
            notes: existing?.notes || '',
            profile: u.profile,
            studentId: u.studentProfile?.studentId,
            email: u.email,
          }
        })
        setStudents(merged)
        setStats(stats)
      }
    } catch {
      // silent
    } finally {
      setLoading(false)
    }
  }, [classId, date])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchRoster() }, [fetchRoster])

  const setStatus = (userId: string, status: Status) => {
    setStudents(prev => prev.map(s =>
      s.userId === userId ? { ...s, status, minutesLate: status === 'LATE' ? s.minutesLate || 5 : undefined } : s
    ))
  }

  const markAll = (status: Status) => {
    setStudents(prev => prev.map(s => ({ ...s, status })))
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      const res = await fetch('/api/staff/attendance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          classId,
          date,
          records: students.map(s => ({
            userId: s.userId,
            status: s.status,
            minutesLate: s.minutesLate,
            notes: s.notes,
          })),
        }),
      })
      const json = await res.json()
      if (json.success) {
        fetchRoster() // refresh stats
      } else {
        alert(json.error || 'Failed to save')
      }
    } catch {
      alert('An error occurred')
    } finally {
      setSaving(false)
    }
  }

  const presentCount = students.filter(s => s.status === 'PRESENT' || s.status === 'LATE').length
  const rate = students.length > 0 ? Math.round((presentCount / students.length) * 100) : 0

  return (
    <div className="space-y-6">
      {/* Controls */}
      <div className="flex flex-wrap gap-4">
        <div className="min-w-[200px] flex-1">
          <label className="mb-1 block text-xs font-bold text-slate-500">Class</label>
          <select
            value={classId}
            onChange={e => setClassId(e.target.value)}
            className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium dark:border-slate-700 dark:bg-slate-900"
          >
            {classes.map(c => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
        </div>
        <div className="min-w-[160px]">
          <label className="mb-1 block text-xs font-bold text-slate-500">Date</label>
          <input
            type="date"
            value={date}
            onChange={e => setDate(e.target.value)}
            className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm dark:border-slate-700 dark:bg-slate-900"
          />
        </div>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <div className="rounded-xl border border-slate-200 bg-white p-4 text-center dark:border-slate-800 dark:bg-slate-900">
          <Users className="mx-auto h-5 w-5 text-slate-400" />
          <p className="mt-1 text-2xl font-bold text-slate-900 dark:text-white">{students.length}</p>
          <p className="text-xs text-slate-500">Enrolled</p>
        </div>
        <div className="rounded-xl border border-green-200 bg-green-50 p-4 text-center dark:border-green-800/50 dark:bg-green-900/10">
          <CheckCircle2 className="mx-auto h-5 w-5 text-green-600" />
          <p className="mt-1 text-2xl font-bold text-green-800 dark:text-green-200">{presentCount}</p>
          <p className="text-xs text-green-600">Present</p>
        </div>
        <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-center dark:border-red-800/50 dark:bg-red-900/10">
          <XCircle className="mx-auto h-5 w-5 text-red-600" />
          <p className="mt-1 text-2xl font-bold text-red-800 dark:text-red-200">{students.filter(s => s.status === 'ABSENT').length}</p>
          <p className="text-xs text-red-600">Absent</p>
        </div>
        <div className={`rounded-xl border p-4 text-center ${
          rate >= 90 ? 'border-green-200 bg-green-50 dark:border-green-800/50 dark:bg-green-900/10' : 'border-amber-200 bg-amber-50 dark:border-amber-800/50 dark:bg-amber-900/10'
        }`}>
          {rate < 90 ? <AlertTriangle className="mx-auto h-5 w-5 text-amber-600" /> : <CheckCircle2 className="mx-auto h-5 w-5 text-green-600" />}
          <p className={`mt-1 text-2xl font-bold ${rate >= 90 ? 'text-green-800 dark:text-green-200' : 'text-amber-800 dark:text-amber-200'}`}>{rate}%</p>
          <p className="text-xs text-slate-500">Rate</p>
        </div>
      </div>

      {/* Bulk Actions */}
      <div className="flex gap-2">
        <button onClick={() => markAll('PRESENT')} className="rounded-lg bg-green-100 px-3 py-1.5 text-xs font-bold text-green-700 hover:bg-green-200 dark:bg-green-900/30 dark:text-green-300">
          All Present
        </button>
        <button onClick={() => markAll('ABSENT')} className="rounded-lg bg-red-100 px-3 py-1.5 text-xs font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-300">
          All Absent
        </button>
      </div>

      {/* Student List */}
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
        </div>
      ) : students.length === 0 ? (
        <div className="rounded-xl border border-slate-200 bg-white p-12 text-center dark:border-slate-800 dark:bg-slate-900">
          <Users className="mx-auto mb-4 h-12 w-12 text-slate-300" />
          <p className="font-bold text-slate-500">No students enrolled in this class.</p>
        </div>
      ) : (
        <div className="rounded-xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
          <div className="divide-y dark:divide-slate-800">
            {students.map((s, i) => {
              const fullName = s.profile ? `${s.profile.firstName} ${s.profile.lastName}` : s.email || s.userId
              return (
                <div key={s.userId} className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between">
                  <div className="flex items-center gap-3">
                    <span className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-100 text-xs font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-300">
                      {i + 1}
                    </span>
                    <div>
                      <p className="text-sm font-bold text-slate-900 dark:text-white">{fullName}</p>
                      <p className="text-xs text-slate-500">{s.studentId || s.email}</p>
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {STATUSES.map(status => {
                      const config = STATUS_CONFIG[status]
                      const Icon = config.icon
                      const active = s.status === status
                      return (
                        <button
                          key={status}
                          onClick={() => setStatus(s.userId, status)}
                          className={`flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-bold transition-all ${
                            active
                              ? `${config.color} ring-2 ring-offset-1 ring-current`
                              : 'bg-slate-100 text-slate-400 hover:bg-slate-200 dark:bg-slate-800'
                          }`}
                        >
                          <Icon className="h-3.5 w-3.5" />
                          {config.label}
                        </button>
                      )
                    })}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* Save Button */}
      {students.length > 0 && (
        <div className="flex justify-end">
          <button
            onClick={handleSave}
            disabled={saving}
            className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-8 py-3 font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50 dark:bg-aerojet-sky"
          >
            {saving ? <Loader2 className="h-5 w-5 animate-spin" /> : <Save className="h-5 w-5" />}
            Save Attendance
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import TablePagination from '../../_components/TablePagination'
import { format } from 'date-fns'
import {
  ScrollText,
  User as UserIcon,
  X,
  ServerCrash,
  Activity,
  ShieldAlert,
  Cpu,
  Database,
  Fingerprint,
  ExternalLink,
} from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

type AuditLog = {
  id: string
  action: string
  entity: string | null
  entityId: string | null
  description: string | null
  createdAt: string | Date
  ipAddress: string | null
  user: {
    email: string
    profile: { firstName: string; lastName: string } | null
  } | null
}

import { memo } from 'react'

const LogRow = memo(
  ({
    log,
    idx,
    entityLabels,
    onSelect,
    actionStyle,
    getEntityIcon,
    getUserName,
    getUserInitials,
  }: {
    log: AuditLog
    idx: number
    entityLabels: Record<string, string>
    onSelect: (log: AuditLog) => void
    actionStyle: (act: string) => string
    getEntityIcon: (entity: string | null) => React.ReactNode
    getUserName: (log: AuditLog) => string
    getUserInitials: (name: string) => string
  }) => {
    const userName = getUserName(log)
    const initials = getUserInitials(userName)

    return (
      <motion.tr
        initial={{ opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        // Only stagger the first 25 items to save main thread on large lists
        transition={{ delay: idx < 25 ? idx * 0.02 : 0, duration: 0.2 }}
        onClick={() => onSelect(log)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            onSelect(log)
          }
        }}
        tabIndex={0}
        role="button"
        aria-label={`View details for ${log.action} on ${log.entity || 'system'}`}
        className="group relative cursor-pointer transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/40"
      >
        {/* Timestamp */}
        <td className="px-6 py-5">
          <div className="flex flex-col items-start justify-center">
            <span className="font-mono text-[10px] font-bold tracking-tighter text-slate-500 dark:text-slate-400">
              {format(new Date(log.createdAt), 'MMM dd, yyyy').toUpperCase()}
            </span>
            <span className="font-mono text-[11px] font-medium text-slate-400 dark:text-slate-500">
              {format(new Date(log.createdAt), 'HH:mm:ss.SSS')}
            </span>
          </div>
        </td>

        {/* Action */}
        <td className="px-6 py-5">
          <span
            className={`inline-flex items-center rounded-lg border px-3 py-1.5 text-[10px] font-black tracking-widest uppercase shadow-sm ${actionStyle(log.action)}`}
          >
            {log.action}
          </span>
        </td>

        {/* Entity & Description */}
        <td className="px-6 py-5">
          <div className="flex flex-col justify-center overflow-hidden">
            <div className="mb-1 flex items-center gap-2">
              <div
                className="flex items-center text-slate-400 dark:text-slate-500"
                aria-hidden="true"
              >
                {getEntityIcon(log.entity)}
              </div>
              <span className="truncate font-mono text-xs font-bold text-slate-700 dark:text-slate-200">
                {log.entity || 'system_event'}
              </span>
              {log.entityId && (
                <>
                  <span className="text-slate-300 dark:text-white/10">/</span>
                  <span className="truncate font-mono text-[10px] text-slate-500 dark:text-slate-400">
                    {entityLabels[log.entityId] ?? log.entityId.substring(0, 8)}
                  </span>
                </>
              )}
            </div>
            <p className="truncate text-xs leading-relaxed text-slate-500 dark:text-slate-400">
              {log.description ?? 'System recorded action without explicit description.'}
            </p>
          </div>
        </td>

        {/* User */}
        <td className="px-6 py-5 min-w-[200px]">
          <div className="flex items-center gap-3 overflow-hidden">
            <div
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-white font-bold text-slate-600 shadow-sm dark:border-white/10 dark:bg-slate-800 dark:text-slate-300"
              aria-hidden="true"
            >
              <span className="text-[10px]">{initials}</span>
            </div>
            <div className="flex flex-col truncate">
              <span className="truncate text-sm font-bold text-slate-800 dark:text-slate-100">
                {userName}
              </span>
              {log.user?.email && userName !== log.user.email && (
                <span className="truncate text-[10px] font-medium tracking-tight text-slate-500 dark:text-slate-500">
                  {log.user.email}
                </span>
              )}
            </div>
          </div>
        </td>

        {/* IP Address */}
        <td className="px-6 py-5 text-right">
          <div className="flex items-center justify-end gap-3">
            <div className="rounded-lg border border-slate-100 bg-slate-50 px-2.5 py-1 font-mono text-[10px] font-bold text-slate-500 dark:border-white/5 dark:bg-white/3 dark:text-slate-400">
              {log.ipAddress ?? 'INTERNAL'}
            </div>
            <ExternalLink
              className="h-3.5 w-3.5 text-slate-300 opacity-0 transition-opacity group-hover:opacity-100 dark:text-white/20"
              aria-hidden="true"
            />
          </div>
        </td>
      </motion.tr>
    )
  }
)
LogRow.displayName = 'LogRow'

interface AuditLogTableProps {
  logs: AuditLog[]
  total: number
  entityLabels: Record<string, string>
  query?: string
}

export default function AuditLogTable({ logs: initialLogs, total: initialTotal, entityLabels, query }: AuditLogTableProps) {
  const [logs, setLogs] = useState<AuditLog[]>(initialLogs)
  const [total, setTotal] = useState(initialTotal)
  const [loading, setLoading] = useState(false)
  const [selectedLog, setSelectedLog] = useState<AuditLog | null>(null)
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)

  const sortableLogs = useMemo(
    () => logs.map((log) => ({ ...log, _userName: getUserNameValue(log) })),
    [logs]
  )
  const { items: sortedLogs, requestSort, sortConfig } = useSort(sortableLogs)
  const paged = sortedLogs

  const fetchLogs = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: perPage.toString(),
        // Add current table filters here if any
      })
      const res = await fetch(`/api/staff/audit-logs?${params}`)
      const data = await res.json()
      setLogs(data.data ?? [])
      setTotal(data.meta?.total ?? 0)
    } finally {
      setLoading(false)
    }
  }

  // Effect to handle page changes
  useEffect(() => {
    // Skip first fetch if it's the initial page and we have initial logs
    const isInitial = page === 1 && perPage === 25
    if (!isInitial) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchLogs()
    }
  }, [page, perPage])

  function actionStyle(act: string) {
    if (
      act.includes('DELETE') ||
      act.includes('REJECT') ||
      act.includes('SUSPEND') ||
      act.includes('ERROR') ||
      act.includes('FAIL')
    )
      return 'bg-red-500/10 text-red-500 border-red-500/20'
    if (
      act.includes('CREATE') ||
      act.includes('APPROVE') ||
      act.includes('ACTIVATE') ||
      act.includes('SUCCESS')
    )
      return 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'
    if (act.includes('UPDATE') || act.includes('EDIT'))
      return 'bg-blue-500/10 text-blue-500 border-blue-500/20'
    if (act.includes('LOGIN') || act.includes('LOGOUT') || act.includes('AUTH'))
      return 'bg-indigo-500/10 text-indigo-500 border-indigo-500/20'
    if (act.includes('EMAIL') || act.includes('SEND'))
      return 'bg-amber-500/10 text-amber-500 border-amber-500/20'

    return 'bg-slate-500/10 text-slate-500 border-slate-500/20'
  }

  function getEntityIcon(entity: string | null) {
    if (!entity) return <Activity className="h-4 w-4" />
    const e = entity.toLowerCase()
    if (e.includes('user') || e.includes('profile')) return <UserIcon className="h-4 w-4" />
    if (e.includes('email') || e.includes('message')) return <ScrollText className="h-4 w-4" />
    if (e.includes('auth') || e.includes('session')) return <Fingerprint className="h-4 w-4" />
    if (e.includes('system') || e.includes('setting')) return <Cpu className="h-4 w-4" />
    return <Database className="h-4 w-4" />
  }

  function getUserName(log: AuditLog) {
    return log.user?.profile
      ? `${log.user.profile.firstName} ${log.user.profile.lastName}`
      : (log.user?.email ?? 'System')
  }

  function getUserNameValue(log: AuditLog): string {
    return getUserName(log)
  }

  function getUserInitials(name: string) {
    if (name === 'System') return 'SY'
    const parts = name.split(' ')
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase()
    return name.substring(0, 2).toUpperCase()
  }

  return (
    <>
      <div className="overflow-x-auto rounded-3xl border border-slate-200/60 bg-white shadow-xl dark:border-slate-800/80 dark:bg-[#0A0F1C]">
        <table className="w-full min-w-[1240px] border-collapse">
          {/* Header Row */}
          <thead>
            <tr className="hidden border-b border-slate-100 bg-slate-50/50 text-xs font-bold tracking-wider text-slate-500 uppercase lg:table-row dark:border-slate-800/80 dark:bg-slate-900/50 dark:text-slate-400">
              <SortHeader
                label="Timestamp"
                sortKey="createdAt"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6 py-4 text-left font-bold"
              />
              <SortHeader
                label="Action"
                sortKey="action"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6 py-4 text-left font-bold"
              />
              <SortHeader
                label="Entity & Context"
                sortKey="entity"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6 py-4 text-left font-bold"
              />
              <SortHeader
                label="User"
                sortKey="_userName"
                currentSort={sortConfig}
                onSort={requestSort}
                className="px-6 py-4 text-left font-bold"
              />
              <SortHeader
                label="IP Address"
                sortKey="ipAddress"
                currentSort={sortConfig}
                onSort={requestSort}
                align="right"
                className="px-6 py-4 text-right font-bold"
              />
            </tr>
          </thead>

          {/* List Body */}
          <tbody className="divide-y divide-slate-100 dark:divide-white/5">
            {loading ? (
              Array.from({ length: 10 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="px-6 py-5" colSpan={5}>
                    <div className="h-4 w-full rounded bg-slate-100 dark:bg-slate-800" />
                  </td>
                </tr>
              ))
            ) : logs.length === 0 ? (
              <tr>
                <td colSpan={5}>
                  <div className="flex flex-col items-center justify-center p-16 text-center">
                    <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-slate-50 dark:bg-slate-800/50">
                      <ShieldAlert
                        className="h-8 w-8 text-slate-300 dark:text-slate-600"
                        aria-hidden="true"
                      />
                    </div>
                    <p className="font-bold text-slate-500 dark:text-slate-400">
                      No events recorded
                    </p>
                    {query && (
                      <p className="mt-1 text-sm text-slate-400">Try adjusting your filters</p>
                    )}
                  </div>
                </td>
              </tr>
            ) : (
              paged.map((log, idx) => (
                <LogRow
                  key={log.id}
                  log={log}
                  idx={idx}
                  entityLabels={entityLabels}
                  onSelect={setSelectedLog}
                  actionStyle={actionStyle}
                  getEntityIcon={getEntityIcon}
                  getUserName={getUserName}
                  getUserInitials={getUserInitials}
                />
              ))
            )}
          </tbody>
        </table>
      </div>
      <TablePagination page={page} perPage={perPage} total={total} onPageChange={setPage} onPerPageChange={setPerPage} />

      {/* Glassmorphic Detail Modal */}
      {selectedLog && (
        <div className="animate-in fade-in fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4 backdrop-blur-md duration-300">
          <div
            className="animate-in zoom-in-95 w-full max-w-2xl overflow-hidden rounded-3xl border border-white/20 bg-white/95 shadow-2xl backdrop-blur-xl duration-300 dark:border-slate-800/80 dark:bg-[#0A0F1C]/95"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Modal Header */}
            <div className="flex items-center justify-between border-b border-slate-200/60 bg-slate-50/50 px-8 py-6 dark:border-slate-800/80 dark:bg-slate-900/50">
              <div className="flex items-center gap-4">
                <div
                  className={`flex h-12 w-12 items-center justify-center rounded-2xl border shadow-inner ${actionStyle(selectedLog.action)}`}
                >
                  {getEntityIcon(selectedLog.entity)}
                </div>
                <div>
                  <h2 className="text-xl font-black tracking-tight text-aerojet-blue dark:text-white">
                    Event Detail
                  </h2>
                  <p className="mt-0.5 font-mono text-[10px] text-slate-500 dark:text-slate-400">
                    UUID: {selectedLog.id}
                  </p>
                </div>
              </div>
              <button
                onClick={() => setSelectedLog(null)}
                aria-label="Close details"
                className="flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-slate-500 transition-colors hover:bg-slate-200 hover:text-slate-700 dark:bg-slate-800 dark:text-slate-400 dark:hover:bg-slate-700 dark:hover:text-slate-200"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="p-8">
              {/* Context Grid */}
              <div className="mb-8 grid grid-cols-1 gap-x-8 gap-y-6 md:grid-cols-2">
                {/* Action Block */}
                <div className="col-span-1">
                  <h3 className="mb-2 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
                    Event Action
                  </h3>
                  <span
                    className={`inline-flex items-center rounded-md border px-3 py-1.5 text-xs font-black tracking-wider uppercase ${actionStyle(selectedLog.action)}`}
                  >
                    {selectedLog.action}
                  </span>
                </div>

                {/* Timestamp Block */}
                <div className="col-span-1">
                  <h3 className="mb-2 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
                    Timestamp
                  </h3>
                  <div className="font-mono text-sm font-semibold text-slate-700 dark:text-slate-300">
                    <p>{format(new Date(selectedLog.createdAt), 'yyyy-MM-dd')}</p>
                    <p className="text-slate-500">
                      {format(new Date(selectedLog.createdAt), 'HH:mm:ss.SSS')}
                    </p>
                  </div>
                </div>

                {/* Actor Block */}
                <div className="col-span-full">
                  <h3 className="mb-2 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
                    Actor
                  </h3>
                  <div className="flex items-center gap-3">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-800">
                      <span className="text-xs font-bold text-slate-600 dark:text-slate-300">
                        {getUserInitials(getUserName(selectedLog))}
                      </span>
                    </div>
                    <div>
                      <p className="text-sm font-bold text-slate-800 dark:text-slate-200">
                        {getUserName(selectedLog)}
                      </p>
                      <p className="font-mono text-[10px] text-slate-500 dark:text-slate-400">
                        {selectedLog.user?.email ?? 'System Process'}
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Entity Information */}
              <div className="mb-8 rounded-2xl border border-slate-200/60 bg-slate-50/50 p-5 dark:border-slate-800/80 dark:bg-slate-900/50">
                <h3 className="mb-3 text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
                  Target Entity
                </h3>
                <div className="flex items-center gap-4 font-mono text-sm text-slate-700 dark:text-slate-300">
                  <div className="flex items-center gap-2">
                    <Database className="h-4 w-4 text-slate-400" />
                    <span className="font-semibold">{selectedLog.entity || 'N/A'}</span>
                  </div>
                  <span className="text-slate-300 dark:text-slate-600">/</span>
                  <div className="flex items-center gap-2">
                    <Fingerprint className="h-4 w-4 text-slate-400" />
                    <span>
                      {selectedLog.entityId
                        ? (entityLabels[selectedLog.entityId] ?? selectedLog.entityId)
                        : 'N/A'}
                    </span>
                  </div>
                </div>
              </div>

              {/* Main Log Data */}
              <div>
                <div className="mb-3 flex items-center justify-between">
                  <h3 className="text-[10px] font-bold tracking-widest text-slate-400 uppercase dark:text-slate-500">
                    Event Payload / Description
                  </h3>
                  <div className="flex items-center gap-1.5 font-mono text-[10px] text-slate-400">
                    <ServerCrash className="h-3 w-3" />
                    {selectedLog.ipAddress ?? 'INTERNAL_IP'}
                  </div>
                </div>
                <div className="rounded-2xl border border-slate-200/60 bg-[#FAFAFA] p-5 font-mono text-sm leading-relaxed text-slate-700 shadow-inner dark:border-slate-800/80 dark:bg-black/40 dark:text-slate-300">
                  {selectedLog.description ?? 'No payload or description provided.'}
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="flex justify-end border-t border-slate-200/60 bg-slate-50/50 px-8 py-5 dark:border-slate-800/80 dark:bg-slate-900/50">
              <button
                onClick={() => setSelectedLog(null)}
                className="rounded-xl bg-aerojet-blue px-8 py-3 text-sm font-bold text-white shadow-md transition-all hover:-translate-y-0.5 hover:bg-[#003875] hover:shadow-lg dark:hover:bg-aerojet-sky"
              >
                Done
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState, useMemo, useTransition } from 'react'
import {
  format,
  startOfWeek,
  addDays,
  addWeeks,
  subWeeks,
  addMonths,
  subMonths,
  isSameDay,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  getHours,
  getMinutes,
  addHours,
} from 'date-fns'
import {
  ChevronLeft,
  ChevronRight,
  Plus,
  Filter,
  BookOpen,
  GraduationCap,
  CalendarDays,
  Users,
  UserCheck,
  Globe,
  Pencil,
  Trash2,
  X,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { toast } from 'sonner'
import {
  createAdminCalendarEvent,
  updateAdminCalendarEvent,
  deleteAdminCalendarEvent,
} from '../actions'

export interface StaffCalendarEvent {
  id: string
  dbId: string
  title: string
  description?: string | null
  startDate: string
  endDate?: string | null
  color: string
  source: 'class' | 'exam' | 'admin'
  editable: boolean
  visibleTo:
    | 'ALL'
    | 'STUDENTS'
    | 'INSTRUCTORS'
    | 'EXAM_ONLY'
    | 'MODULAR'
    | 'FULL_TIME'
    | 'SPECIFIC_USER'
  recurrenceType?: string | null
  recurrenceDays?: string | null
  recurrenceUntil?: string | null
  targetUserId?: string | null
}

interface Props {
  events: StaffCalendarEvent[]
  initialDate?: Date
  currentUserId: string
}

const AUDIENCE_OPTIONS = [
  { value: 'ALL', label: 'Everyone', icon: Globe },
  { value: 'STUDENTS', label: 'Students Only', icon: UserCheck },
  { value: 'INSTRUCTORS', label: 'Instructors Only', icon: Users },
  { value: 'EXAM_ONLY', label: 'Exam Only Students', icon: BookOpen },
  { value: 'MODULAR', label: 'Modular Students', icon: BookOpen },
  { value: 'FULL_TIME', label: 'Full Time Students', icon: GraduationCap },
  { value: 'SPECIFIC_USER', label: 'Specific User', icon: UserCheck },
]

const COLOR_OPTIONS = ['#4A72E8', '#FF4F33', '#10b981', '#8b5cf6', '#f59e0b', '#ec4899', '#06b6d4']

function getEventStyles(source: string, color: string) {
  if (source === 'exam') return 'bg-[#FF4F33] text-white'
  if (source === 'class') return 'bg-[#EBF1FF] text-[#4A72E8]'
  return 'text-white'
}

function AudienceBadge({ visibleTo }: { visibleTo: string }) {
  if (visibleTo === 'STUDENTS')
    return (
      <span className="ml-1 rounded-full bg-blue-100 px-1.5 py-0.5 text-xs font-bold text-blue-700">
        Students
      </span>
    )
  if (visibleTo === 'INSTRUCTORS')
    return (
      <span className="ml-1 rounded-full bg-purple-100 px-1.5 py-0.5 text-xs font-bold text-purple-700">
        Instructors
      </span>
    )
  if (visibleTo === 'EXAM_ONLY')
    return (
      <span className="ml-1 rounded-full bg-indigo-100 px-1.5 py-0.5 text-xs font-bold text-indigo-700">
        Exam Only
      </span>
    )
  if (visibleTo === 'MODULAR')
    return (
      <span className="ml-1 rounded-full bg-cyan-100 px-1.5 py-0.5 text-xs font-bold text-cyan-700">
        Modular
      </span>
    )
  if (visibleTo === 'FULL_TIME')
    return (
      <span className="ml-1 rounded-full bg-emerald-100 px-1.5 py-0.5 text-xs font-bold text-emerald-700">
        Full Time
      </span>
    )
  if (visibleTo === 'SPECIFIC_USER')
    return (
      <span className="ml-1 rounded-full bg-rose-100 px-1.5 py-0.5 text-xs font-bold text-rose-700">
        Specific User
      </span>
    )
  return (
    <span className="ml-1 rounded-full bg-slate-100 px-1.5 py-0.5 text-xs font-bold text-slate-600">
      All
    </span>
  )
}

export default function StaffCalendarGrid({ events, initialDate, currentUserId }: Props) {
  const [currentDate, setCurrentDate] = useState(initialDate || new Date())
  const [viewMode, setViewMode] = useState<'Month' | 'Week' | 'Day'>('Week')
  const [popupEvent, setPopupEvent] = useState<StaffCalendarEvent | null>(null)
  const [showModal, setShowModal] = useState(false)
  const [editingEvent, setEditingEvent] = useState<StaffCalendarEvent | null>(null)
  const [isPending, startTransition] = useTransition()

  // Form state
  const [formTitle, setFormTitle] = useState('')
  const [formDesc, setFormDesc] = useState('')
  const [formStart, setFormStart] = useState('')
  const [formEnd, setFormEnd] = useState('')
  const [formColor, setFormColor] = useState('#4A72E8')
  const [formAudience, setFormAudience] = useState<
    'ALL' | 'STUDENTS' | 'INSTRUCTORS' | 'EXAM_ONLY' | 'MODULAR' | 'FULL_TIME' | 'SPECIFIC_USER'
  >('ALL')
  const [formTargetUserId, setFormTargetUserId] = useState('')
  const [formRecurrence, setFormRecurrence] = useState('NONE')

  const today = new Date()
  const hourHeight = 80
  const timeSlots = Array.from({ length: 24 }, (_, i) => i)
  const startOfRange = startOfWeek(currentDate, { weekStartsOn: 1 })
  const weekDays = Array.from({ length: 7 }, (_, i) => addDays(startOfRange, i))

  const monthDays = useMemo(() => {
    const start = startOfMonth(currentDate)
    const end = endOfMonth(currentDate)
    const days = eachDayOfInterval({ start, end })
    const startPad = start.getDay()
    const leading = Array.from({ length: startPad }, (_, i) => addDays(start, i - startPad))
    const total = [...leading, ...days]
    const trailing = Array.from({ length: 42 - total.length }, (_, i) => addDays(end, i + 1))
    return [...leading, ...days, ...trailing]
  }, [currentDate])

  const eventsByDate = useMemo(() => {
    const map: Record<string, StaffCalendarEvent[]> = {}
    events.forEach((evt) => {
      const d = format(new Date(evt.startDate), 'yyyy-MM-dd')
      if (!map[d]) map[d] = []
      if (!map[d].some((e) => e.id === evt.id)) map[d].push(evt)
    })
    return map
  }, [events])
  const currentDayEvents = useMemo(() => {
    const dayStr = format(currentDate, 'yyyy-MM-dd')
    return [...(eventsByDate[dayStr] || [])].sort(
      (a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime()
    )
  }, [currentDate, eventsByDate])

  const getPos = (evt: StaffCalendarEvent) => {
    const start = new Date(evt.startDate)
    const end = evt.endDate ? new Date(evt.endDate) : addHours(start, 1)
    const top = (getHours(start) + getMinutes(start) / 60) * hourHeight
    const height = Math.max(((end.getTime() - start.getTime()) / 3_600_000) * hourHeight, 24)
    return { top, height }
  }

  const openAdd = () => {
    setEditingEvent(null)
    setFormTitle('')
    setFormDesc('')
    setFormStart('')
    setFormEnd('')
    setFormColor('#4A72E8')
    setFormAudience('ALL')
    setFormTargetUserId('')
    setFormRecurrence('NONE')
    setShowModal(true)
  }

  const openEdit = (evt: StaffCalendarEvent) => {
    setEditingEvent(evt)
    setFormTitle(evt.title)
    setFormDesc(evt.description || '')
    setFormStart(evt.startDate.slice(0, 16))
    setFormEnd(evt.endDate?.slice(0, 16) || '')
    setFormColor(evt.color)
    setFormAudience(evt.visibleTo as 'ALL' | 'STUDENTS' | 'INSTRUCTORS' | 'EXAM_ONLY' | 'MODULAR' | 'FULL_TIME' | 'SPECIFIC_USER')
    setFormTargetUserId(evt.targetUserId || '')
    setFormRecurrence(evt.recurrenceType || 'NONE')
    setPopupEvent(null)
    setShowModal(true)
  }

  const handleSave = () => {
    if (!formTitle.trim()) {
      toast.error('Title is required')
      return
    }
    startTransition(async () => {
      const data = {
        title: formTitle,
        description: formDesc,
        startDate: formStart,
        endDate: formEnd ? formEnd : undefined,
        color: formColor,
        visibleTo: formAudience,
        targetUserId: formAudience === 'SPECIFIC_USER' ? formTargetUserId : undefined,
        recurrenceType: formRecurrence,
      }
      const res = editingEvent
        ? await updateAdminCalendarEvent(editingEvent.dbId, data)
        : await createAdminCalendarEvent(data)
      if (res.error) {
        toast.error(res.error)
      } else {
        toast.success(editingEvent ? 'Event updated!' : 'Event created!')
        setShowModal(false)
      }
    })
  }

  const handleDelete = (evt: StaffCalendarEvent) => {
    startTransition(async () => {
      const res = await deleteAdminCalendarEvent(evt.dbId)
      if (res.error) {
        toast.error(res.error)
      } else {
        toast.success('Event deleted')
        setPopupEvent(null)
      }
    })
  }

  const handlePrev = () => {
    if (viewMode === 'Day') setCurrentDate(addDays(currentDate, -1))
    else if (viewMode === 'Week') setCurrentDate(subWeeks(currentDate, 1))
    else setCurrentDate(subMonths(currentDate, 1))
  }
  const handleNext = () => {
    if (viewMode === 'Day') setCurrentDate(addDays(currentDate, 1))
    else if (viewMode === 'Week') setCurrentDate(addWeeks(currentDate, 1))
    else setCurrentDate(addMonths(currentDate, 1))
  }
  const label =
    viewMode === 'Day'
      ? format(currentDate, 'EEEE, MMMM d, yyyy')
      : viewMode === 'Week'
        ? format(startOfRange, 'MMMM yyyy')
        : format(currentDate, 'MMMM yyyy')

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col gap-4 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm sm:flex-row sm:items-end sm:justify-between dark:border-slate-800 dark:bg-slate-900">
        <div>
          <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white">
            Calendar
          </h2>
          <p className="mt-1 text-sm text-slate-500">
            Manage and broadcast institutional events across all portals
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3 text-xs text-slate-500">
          <span className="flex items-center gap-1.5">
            <span className="h-3 w-3 rounded-full bg-[#4A72E8]" /> Class Sessions
          </span>
          <span className="flex items-center gap-1.5">
            <span className="h-3 w-3 rounded-full bg-[#FF4F33]" /> Exam Events
          </span>
          <span className="flex items-center gap-1.5">
            <span className="h-3 w-3 rounded-full bg-[#8b5cf6]" /> Admin Events
          </span>
        </div>
      </div>

      {/* Controls */}
      <div className="flex flex-col items-center justify-between gap-4 rounded-2xl border border-slate-100 bg-white p-4 shadow-sm md:flex-row dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-3">
          <button
            aria-label="Previous period"
            onClick={handlePrev}
            className="rounded-full p-2 transition-colors hover:bg-slate-100 dark:hover:bg-slate-800"
          >
            <ChevronLeft className="h-5 w-5 text-slate-500" />
          </button>
          <span className="min-w-[160px] text-center text-xl font-black text-slate-900 dark:text-white">
            {label}
          </span>
          <button
            aria-label="Next period"
            onClick={handleNext}
            className="rounded-full p-2 transition-colors hover:bg-slate-100 dark:hover:bg-slate-800"
          >
            <ChevronRight className="h-5 w-5 text-slate-500" />
          </button>
          <button
            onClick={() => setCurrentDate(new Date())}
            className="rounded-full border border-slate-200 px-3 py-1.5 text-xs font-bold text-slate-500 transition-colors hover:text-slate-900 dark:border-slate-700 dark:hover:text-white"
          >
            Today
          </button>
        </div>
        <div className="flex gap-2">
          <div className="flex items-center rounded-full border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-800">
            <button
              onClick={() => setViewMode('Month')}
              className={cn(
                'rounded-l-full px-4 py-2.5 text-sm font-bold transition-colors',
                viewMode === 'Month'
                  ? 'bg-slate-100 text-slate-900 dark:bg-slate-700 dark:text-white'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              )}
            >
              Month
            </button>
            <button
              onClick={() => setViewMode('Week')}
              className={cn(
                'border-l border-slate-200 px-4 py-2.5 text-sm font-bold transition-colors dark:border-slate-700',
                viewMode === 'Week'
                  ? 'bg-slate-100 text-slate-900 dark:bg-slate-700 dark:text-white'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              )}
            >
              Week
            </button>
            <button
              onClick={() => setViewMode('Day')}
              className={cn(
                'rounded-r-full border-l border-slate-200 px-4 py-2.5 text-sm font-bold transition-colors dark:border-slate-700',
                viewMode === 'Day'
                  ? 'bg-slate-100 text-slate-900 dark:bg-slate-700 dark:text-white'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              )}
            >
              Day
            </button>
          </div>
          <button
            onClick={openAdd}
            className="flex items-center gap-2 rounded-full bg-[#FF4F33] px-6 py-2.5 text-sm font-bold text-white shadow-md shadow-[#FF4F33]/20 transition-colors hover:bg-[#E6462D]"
          >
            New Event <Plus className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Mobile Agenda */}
      <div className="space-y-2 rounded-2xl border border-slate-100 bg-white p-4 shadow-sm md:hidden dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center justify-between">
          <span className="text-xs font-black tracking-widest text-slate-400 uppercase">
            Daily Agenda
          </span>
          <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-300">
            {currentDayEvents.length}
          </span>
        </div>
        {currentDayEvents.length === 0 ? (
          <p className="py-4 text-sm font-medium text-slate-500">
            No events scheduled for this day.
          </p>
        ) : (
          currentDayEvents.map((evt) => (
            <button
              key={evt.id}
              onClick={() => setPopupEvent(evt)}
              className="flex w-full items-start gap-3 rounded-xl border border-slate-100 p-3 text-left dark:border-slate-800"
            >
              <span className="mt-1 h-3 w-3 rounded-full" style={{ backgroundColor: evt.color }} />
              <span className="min-w-0 flex-1">
                <span className="block truncate text-sm font-bold text-slate-900 dark:text-white">
                  {evt.title}
                </span>
                <span className="block text-xs font-medium text-slate-500">
                  {format(new Date(evt.startDate), 'hh:mm a')}
                  {evt.endDate ? ` - ${format(new Date(evt.endDate), 'hh:mm a')}` : ''}
                </span>
              </span>
            </button>
          ))
        )}
      </div>

      {/* Day View */}
      {viewMode === 'Day' && (
        <div className="flex flex-col rounded-3xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="border-b border-slate-100 p-4 dark:border-slate-800">
            <p className="text-sm font-bold text-slate-500">{format(currentDate, 'EEEE')}</p>
            <h3 className="text-2xl font-black text-slate-900 dark:text-white">
              {format(currentDate, 'MMMM d')}
            </h3>
          </div>
          <div className="max-h-[760px] overflow-y-auto">
            {timeSlots.map((hour) => {
              const hourEvents = currentDayEvents.filter(
                (evt) => getHours(new Date(evt.startDate)) === hour
              )
              return (
                <div
                  key={hour}
                  className="grid min-h-[84px] grid-cols-[72px_1fr] border-b border-slate-100 dark:border-slate-800"
                >
                  <div className="border-r border-slate-100 px-3 py-4 text-right text-xs font-bold text-slate-400 dark:border-slate-800">
                    {hour === 0
                      ? '12 am'
                      : hour < 12
                        ? `${hour} am`
                        : hour === 12
                          ? '12 pm'
                          : `${hour - 12} pm`}
                  </div>
                  <div className="space-y-2 p-2">
                    {hourEvents.map((evt) => (
                      <button
                        key={evt.id}
                        onClick={() => setPopupEvent(evt)}
                        title={`${evt.title} - ${format(new Date(evt.startDate), 'hh:mm a')}`}
                        className={cn(
                          'w-full rounded-xl p-3 text-left text-sm font-bold shadow-sm',
                          getEventStyles(evt.source, evt.color)
                        )}
                        style={
                          evt.source === 'admin'
                            ? { backgroundColor: evt.color, color: '#fff' }
                            : undefined
                        }
                      >
                        <span className="block truncate">{evt.title}</span>
                        <span className="block text-xs font-medium opacity-80">
                          {format(new Date(evt.startDate), 'hh:mm a')}
                          {evt.endDate ? ` - ${format(new Date(evt.endDate), 'hh:mm a')}` : ''}
                        </span>
                      </button>
                    ))}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* Week View */}
      {viewMode === 'Week' && (
        <div className="hidden flex-col overflow-hidden rounded-3xl border border-slate-100 bg-white shadow-sm md:flex dark:border-slate-800 dark:bg-slate-900">
          <div className="grid grid-cols-[80px_1fr] border-b border-slate-100 dark:border-slate-800">
            <div className="border-r border-slate-100 p-2 dark:border-slate-800" />
            <div className="grid grid-cols-7">
              {weekDays.map((day) => {
                const isToday = isSameDay(day, today)
                return (
                  <div
                    key={day.toISOString()}
                    className={cn(
                      'relative border-r border-slate-100 p-4 text-center last:border-r-0 dark:border-slate-800',
                      isToday && 'bg-[#F8FBFF] dark:bg-blue-900/10'
                    )}
                  >
                    {isToday && <div className="absolute top-0 left-0 h-1 w-full bg-[#4A72E8]" />}
                    <span
                      className={cn(
                        'text-sm font-bold',
                        isToday ? 'text-[#4A72E8]' : 'text-slate-700 dark:text-white'
                      )}
                    >
                      {format(day, 'EEE, dd')}
                    </span>
                  </div>
                )
              })}
            </div>
          </div>
          <div className="flex h-[720px] overflow-y-auto">
            <div className="relative grid w-full grid-cols-[80px_1fr]">
              <div className="border-r border-slate-100 dark:border-slate-800">
                {timeSlots.map((h) => (
                  <div key={h} className="relative h-[80px]">
                    <span className="absolute -top-3 left-0 w-full text-center text-xs font-medium text-slate-400">
                      {h === 0 ? '12 am' : h < 12 ? `${h} am` : h === 12 ? '12 pm' : `${h - 12} pm`}
                    </span>
                  </div>
                ))}
              </div>
              <div className="relative grid grid-cols-7">
                <div className="pointer-events-none absolute inset-0 flex flex-col">
                  {timeSlots.map((h) => (
                    <div
                      key={h}
                      className="h-[80px] border-b border-slate-100 dark:border-slate-800"
                    />
                  ))}
                </div>
                {weekDays.map((day, di) => (
                  <div
                    key={di}
                    className="h-[1920px] border-r border-slate-100 last:border-r-0 dark:border-slate-800"
                  />
                ))}
                {weekDays.map((day, di) => {
                  const dayStr = format(day, 'yyyy-MM-dd')
                  return (eventsByDate[dayStr] || []).map((evt) => {
                    const { top, height } = getPos(evt)
                    return (
                      <div
                        key={evt.id}
                        onClick={() => setPopupEvent(evt)}
                        className="absolute right-1 left-1 cursor-pointer transition-transform hover:z-10 hover:scale-[1.01]"
                        title={`${evt.title} - ${format(new Date(evt.startDate), 'hh:mm a')}`}
                        style={{
                          top: `${top}px`,
                          height: `${height - 4}px`,
                          gridColumnStart: di + 1,
                          gridColumnEnd: di + 2,
                        }}
                      >
                        <div
                          className={cn(
                            'flex h-full w-full flex-col overflow-hidden rounded-xl p-2 shadow-sm',
                            getEventStyles(evt.source, evt.color)
                          )}
                          style={
                            evt.source === 'admin' ? { backgroundColor: evt.color } : undefined
                          }
                        >
                          <span className="truncate text-xs leading-tight font-bold">
                            {evt.title}
                          </span>
                          <span className="truncate text-xs opacity-80">
                            {format(new Date(evt.startDate), 'hh:mm a')}
                          </span>
                          <AudienceBadge visibleTo={evt.visibleTo} />
                        </div>
                      </div>
                    )
                  })
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Month View */}
      {viewMode === 'Month' && (
        <div className="hidden flex-col overflow-hidden rounded-3xl border border-slate-100 bg-white shadow-sm md:flex dark:border-slate-800 dark:bg-slate-900">
          <div className="grid grid-cols-7 border-b border-slate-100 bg-[#F8FBFF] dark:border-slate-800 dark:bg-blue-900/10">
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((d) => (
              <div
                key={d}
                className="border-r border-slate-100 p-4 text-center text-sm font-bold text-slate-700 last:border-r-0 dark:border-slate-800 dark:text-slate-300"
              >
                {d}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7">
            {monthDays.map((day, idx) => {
              const dayStr = format(day, 'yyyy-MM-dd')
              const dayEvts = eventsByDate[dayStr] || []
              const isToday = isSameDay(day, today)
              const isCur = day.getMonth() === currentDate.getMonth()
              return (
                <div
                  key={idx}
                  className={cn(
                    'relative min-h-[110px] border-r border-b border-slate-100 p-2 dark:border-slate-800',
                    !isCur && 'bg-slate-50/50 dark:bg-slate-900/50',
                    isToday && 'bg-[#F8FBFF] dark:bg-blue-900/10'
                  )}
                >
                  {isToday && <div className="absolute top-0 left-0 h-1 w-full bg-[#4A72E8]" />}
                  <span
                    className={cn(
                      'mb-1 inline-flex h-7 w-7 items-center justify-center rounded-full text-sm font-bold',
                      isToday
                        ? 'bg-[#4A72E8] text-white'
                        : !isCur
                          ? 'text-slate-400'
                          : 'text-slate-900 dark:text-white'
                    )}
                  >
                    {format(day, 'd')}
                  </span>
                  {dayEvts.length > 0 && (
                    <span className="absolute top-2 right-2 rounded-full bg-slate-900 px-2 py-0.5 text-[10px] font-bold text-white dark:bg-white dark:text-slate-900">
                      {dayEvts.length}
                    </span>
                  )}
                  <div className="space-y-1">
                    {dayEvts.slice(0, 3).map((evt) => (
                      <div
                        key={evt.id}
                        onClick={() => setPopupEvent(evt)}
                        className={cn(
                          'cursor-pointer truncate rounded-md px-2 py-0.5 text-xs font-bold',
                          getEventStyles(evt.source, evt.color)
                        )}
                        title={`${evt.title} - ${format(new Date(evt.startDate), 'hh:mm a')}`}
                        style={
                          evt.source === 'admin'
                            ? { backgroundColor: evt.color, color: '#fff' }
                            : undefined
                        }
                      >
                        {evt.title}
                      </div>
                    ))}
                    {dayEvts.length > 3 && (
                      <div className="pl-1 text-xs font-bold text-slate-400">
                        +{dayEvts.length - 3} more
                      </div>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* Event Detail Popup */}
      {popupEvent && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm"
          onClick={() => setPopupEvent(null)}
        >
          <div
            className="relative w-full max-w-sm rounded-[28px] bg-white p-7 shadow-2xl dark:bg-slate-900"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              aria-label="Close event details"
              onClick={() => setPopupEvent(null)}
              className="absolute top-5 right-5 rounded-full p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
            >
              <X className="h-4 w-4" />
            </button>
            {popupEvent.editable && (
              <div className="absolute top-5 right-14 flex gap-1">
                <button
                  aria-label="Edit event"
                  onClick={() => openEdit(popupEvent)}
                  className="rounded-full p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
                >
                  <Pencil className="h-4 w-4" />
                </button>
                <button
                  aria-label="Delete event"
                  onClick={() => handleDelete(popupEvent)}
                  className="rounded-full p-2 text-red-400 hover:bg-red-50"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            )}
            <div className="mb-5 flex items-center gap-3">
              <div
                className="flex h-9 w-9 items-center justify-center rounded-full text-sm font-black text-white"
                style={{ backgroundColor: popupEvent.color }}
              >
                {popupEvent.title.charAt(0).toUpperCase()}
              </div>
              <div>
                <p className="text-xs font-bold tracking-wider text-slate-500 uppercase">
                  {popupEvent.source === 'exam'
                    ? 'Exam Event'
                    : popupEvent.source === 'class'
                      ? 'Class Session'
                      : 'Admin Event'}
                </p>
                <AudienceBadge visibleTo={popupEvent.visibleTo} />
              </div>
            </div>
            <h3 className="mb-2 text-xl font-black text-slate-900 dark:text-white">
              {popupEvent.title}
            </h3>
            {popupEvent.description && (
              <p className="mb-4 text-sm text-slate-500">{popupEvent.description}</p>
            )}
            <div className="flex flex-wrap gap-2">
              <span className="flex items-center gap-2 rounded-full bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-700 dark:bg-slate-800 dark:text-slate-200">
                <CalendarDays className="h-3.5 w-3.5" />{' '}
                {format(new Date(popupEvent.startDate), 'MMM dd, hh:mm a')}
              </span>
              {popupEvent.endDate && (
                <span className="flex items-center gap-2 rounded-full bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-700 dark:bg-slate-800 dark:text-slate-200">
                  → {format(new Date(popupEvent.endDate), 'hh:mm a')}
                </span>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Create/Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="w-full max-w-md rounded-[28px] border border-slate-100 bg-white p-8 shadow-2xl dark:border-slate-800 dark:bg-slate-900">
            <div className="mb-6 flex items-center justify-between">
              <h3 className="text-xl font-black text-slate-900 dark:text-white">
                {editingEvent ? 'Edit Event' : 'New Calendar Event'}
              </h3>
              <button
                aria-label="Close modal"
                onClick={() => setShowModal(false)}
                className="rounded-full p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="mb-1.5 block text-sm font-bold text-slate-700 dark:text-slate-300">
                  Title *
                </label>
                <input
                  value={formTitle}
                  onChange={(e) => setFormTitle(e.target.value)}
                  placeholder="Event title..."
                  className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50/50 px-4 py-3 text-sm font-medium text-slate-900 transition-colors outline-none focus:border-[#FF4F33] dark:border-slate-800 dark:bg-slate-900 dark:text-white"
                />
              </div>
              <div>
                <label className="mb-1.5 block text-sm font-bold text-slate-700 dark:text-slate-300">
                  Description
                </label>
                <textarea
                  value={formDesc}
                  onChange={(e) => setFormDesc(e.target.value)}
                  rows={2}
                  className="w-full resize-none rounded-2xl border-2 border-slate-100 bg-slate-50/50 px-4 py-3 text-sm font-medium text-slate-900 transition-colors outline-none focus:border-[#FF4F33] dark:border-slate-800 dark:bg-slate-900 dark:text-white"
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="mb-1.5 block text-sm font-bold text-slate-700 dark:text-slate-300">
                    Start *
                  </label>
                  <input
                    type="datetime-local"
                    value={formStart}
                    onChange={(e) => setFormStart(e.target.value)}
                    className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50/50 px-3 py-3 text-sm font-medium text-slate-900 transition-colors outline-none focus:border-[#FF4F33] dark:border-slate-800 dark:bg-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="mb-1.5 block text-sm font-bold text-slate-700 dark:text-slate-300">
                    End
                  </label>
                  <input
                    type="datetime-local"
                    value={formEnd}
                    onChange={(e) => setFormEnd(e.target.value)}
                    className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50/50 px-3 py-3 text-sm font-medium text-slate-900 transition-colors outline-none focus:border-[#FF4F33] dark:border-slate-800 dark:bg-slate-900 dark:text-white"
                  />
                </div>
              </div>
              {/* Audience selector */}
              <div>
                <label className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-300">
                  Visible To
                </label>
                <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
                  {AUDIENCE_OPTIONS.map((opt) => (
                    <button
                      key={opt.value}
                      type="button"
                      onClick={() => setFormAudience(opt.value as 'ALL' | 'STUDENTS' | 'INSTRUCTORS' | 'EXAM_ONLY' | 'MODULAR' | 'FULL_TIME' | 'SPECIFIC_USER')}
                      className={cn(
                        'flex flex-col items-center justify-center gap-1 rounded-2xl border-2 p-2 text-center text-xs font-bold transition-all',
                        formAudience === opt.value
                          ? 'border-[#FF4F33] bg-[#FF4F33]/5 text-[#FF4F33]'
                          : 'border-slate-100 text-slate-500 hover:border-slate-300 dark:border-slate-800'
                      )}
                    >
                      <opt.icon className="mb-0.5 h-4 w-4" />
                      {opt.label}
                    </button>
                  ))}
                </div>
                {formAudience === 'SPECIFIC_USER' && (
                  <div className="mt-3">
                    <label className="mb-1.5 block text-xs font-bold text-slate-700 dark:text-slate-300">
                      User ID / Email
                    </label>
                    <input
                      value={formTargetUserId}
                      onChange={(e) => setFormTargetUserId(e.target.value)}
                      placeholder="Enter user UUID or exact email..."
                      className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50/50 px-4 py-2 text-sm font-medium text-slate-900 transition-colors outline-none focus:border-[#FF4F33] dark:border-slate-800 dark:bg-slate-900 dark:text-white"
                    />
                  </div>
                )}
              </div>
              {/* Color picker */}
              <div>
                <label className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-300">
                  Color
                </label>
                <div className="flex flex-wrap gap-2">
                  {COLOR_OPTIONS.map((c) => (
                    <button
                      key={c}
                      type="button"
                      onClick={() => setFormColor(c)}
                      className={cn(
                        'h-8 w-8 rounded-full transition-transform',
                        formColor === c
                          ? 'scale-110 ring-2 ring-slate-400 ring-offset-2'
                          : 'hover:scale-110'
                      )}
                      style={{ backgroundColor: c }}
                    />
                  ))}
                </div>
              </div>
              {/* Recurrence */}
              <div>
                <label className="mb-1.5 block text-sm font-bold text-slate-700 dark:text-slate-300">
                  Repeat
                </label>
                <select
                  value={formRecurrence}
                  onChange={(e) => setFormRecurrence(e.target.value)}
                  className="w-full rounded-2xl border-2 border-slate-100 bg-slate-50/50 px-4 py-3 text-sm font-medium text-slate-900 transition-colors outline-none focus:border-[#FF4F33] dark:border-slate-800 dark:bg-slate-900 dark:text-white"
                >
                  <option value="NONE">Does not repeat</option>
                  <option value="DAILY">Every day</option>
                  <option value="WEEKLY">Every week</option>
                  <option value="MONTHLY">Every month</option>
                </select>
              </div>
              <div className="flex gap-3 pt-2">
                <button
                  onClick={() => setShowModal(false)}
                  className="flex-1 rounded-full border-2 border-slate-100 py-3.5 text-sm font-bold text-slate-700 transition-colors hover:bg-slate-50 dark:border-slate-800 dark:text-slate-300 dark:hover:bg-slate-800"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSave}
                  disabled={isPending}
                  className="flex-1 rounded-full bg-[#FF4F33] py-3.5 text-sm font-bold text-white shadow-lg shadow-[#FF4F33]/20 transition-colors hover:bg-[#E6462D] disabled:opacity-50"
                >
                  {isPending ? 'Saving...' : editingEvent ? 'Update Event' : 'Create Event'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use server'

import { revalidatePath } from 'next/cache'
import { getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { CalendarAudience, RecurrenceType } from '@prisma/client'
import { AuditAction, logAuditEvent } from '@/lib/audit/logger'
import { handleActionError } from '@/lib/staff/errors'

export interface AdminEventInput {
  title: string
  description?: string
  startDate: string
  endDate?: string
  color?: string
  recurrenceType?: string
  recurrenceDays?: string
  recurrenceUntil?: string
  visibleTo: CalendarAudience
  classId?: string
  examEventId?: string
  targetUserId?: string
}

export async function createAdminCalendarEvent(data: AdminEventInput) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'STAFF'].includes(session.user.role)) {
    return { error: 'Unauthorized' }
  }

  try {
    let resolvedTargetId: string | null = null

    if (data.visibleTo === 'SPECIFIC_USER' && data.targetUserId) {
      const u = await prismaUnfiltered.user.findFirst({
        where: {
          OR: [
            { id: data.targetUserId },
            { email: data.targetUserId },
            { academyEmail: data.targetUserId },
          ],
        },
      })
      if (!u) return { error: 'Target user not found' }
      resolvedTargetId = u.id
    } else if (data.visibleTo === 'SPECIFIC_USER') {
      return { error: 'Target user is required for specific user visibility' }
    }

    const event = await prismaUnfiltered.adminCalendarEvent.create({
      data: {
        title: data.title.trim(),
        description: data.description?.trim() || null,
        startDate: new Date(data.startDate),
        endDate: data.endDate ? new Date(data.endDate) : null,
        color: data.color || '#3b82f6',
        recurrenceType: (data.recurrenceType as RecurrenceType) || 'NONE',
        recurrenceDays: data.recurrenceDays || null,
        recurrenceUntil: data.recurrenceUntil ? new Date(data.recurrenceUntil) : null,
        visibleTo: data.visibleTo,
        targetUserId: resolvedTargetId,
        classId: data.classId || null,
        examEventId: data.examEventId || null,
        createdBy: session.user.id,
      },
    })
    await logAuditEvent({
      userId: session.user.id,
      action: AuditAction.CREATE,
      entity: 'AdminCalendarEvent',
      entityId: event.id,
      description: `Created calendar event "${event.title}" for ${event.visibleTo}.`,
      changes: {
        title: event.title,
        startDate: event.startDate,
        endDate: event.endDate,
        visibleTo: event.visibleTo,
        targetUserId: event.targetUserId,
      },
    })
    revalidatePath('/staff/calendar')
    return { success: true, event }
  } catch (err) {
    console.error('[createAdminCalendarEvent]', err)
    return { error: 'Failed to create event' }
  }
}

export async function updateAdminCalendarEvent(id: string, data: AdminEventInput) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'STAFF'].includes(session.user.role)) {
    return { error: 'Unauthorized' }
  }

  try {
    const existing = await prismaUnfiltered.adminCalendarEvent.findUnique({ where: { id } })
    if (!existing || existing.deletedAt) return { error: 'Event not found' }

    let resolvedTargetId: string | null = existing.targetUserId

    if (data.visibleTo === 'SPECIFIC_USER' && data.targetUserId) {
      const u = await prismaUnfiltered.user.findFirst({
        where: {
          OR: [
            { id: data.targetUserId },
            { email: data.targetUserId },
            { academyEmail: data.targetUserId },
          ],
        },
      })
      if (!u) return { error: 'Target user not found' }
      resolvedTargetId = u.id
    } else if (data.visibleTo === 'SPECIFIC_USER') {
      return { error: 'Target user is required for specific user visibility' }
    } else {
      resolvedTargetId = null
    }

    const event = await prismaUnfiltered.adminCalendarEvent.update({
      where: { id },
      data: {
        title: data.title.trim(),
        description: data.description?.trim() || null,
        startDate: new Date(data.startDate),
        endDate: data.endDate ? new Date(data.endDate) : null,
        color: data.color || '#3b82f6',
        recurrenceType: (data.recurrenceType as RecurrenceType) || 'NONE',
        recurrenceDays: data.recurrenceDays || null,
        recurrenceUntil: data.recurrenceUntil ? new Date(data.recurrenceUntil) : null,
        visibleTo: data.visibleTo,
        targetUserId: resolvedTargetId,
        classId: data.classId || null,
        examEventId: data.examEventId || null,
      },
    })
    await logAuditEvent({
      userId: session.user.id,
      action: AuditAction.UPDATE,
      entity: 'AdminCalendarEvent',
      entityId: event.id,
      description: `Updated calendar event "${event.title}".`,
      changes: {
        before: {
          title: existing.title,
          startDate: existing.startDate,
          endDate: existing.endDate,
          visibleTo: existing.visibleTo,
          targetUserId: existing.targetUserId,
        },
        after: {
          title: event.title,
          startDate: event.startDate,
          endDate: event.endDate,
          visibleTo: event.visibleTo,
          targetUserId: event.targetUserId,
        },
      },
    })
    revalidatePath('/staff/calendar')
    return { success: true, event }
  } catch (err) {
    console.error('[updateAdminCalendarEvent]', err)
    return { error: 'Failed to update event' }
  }
}

export async function deleteAdminCalendarEvent(id: string) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'STAFF'].includes(session.user.role)) {
    return { error: 'Unauthorized' }
  }

  try {
    const existing = await prismaUnfiltered.adminCalendarEvent.findUnique({ where: { id } })
    if (!existing || existing.deletedAt) return { error: 'Event not found' }

    await prismaUnfiltered.adminCalendarEvent.update({
      where: { id },
      data: { deletedAt: new Date() },
    })
    await logAuditEvent({
      userId: session.user.id,
      action: AuditAction.DELETE,
      entity: 'AdminCalendarEvent',
      entityId: id,
      description: `Deleted calendar event "${existing.title}".`,
      changes: {
        title: existing.title,
        startDate: existing.startDate,
        endDate: existing.endDate,
        visibleTo: existing.visibleTo,
      },
    })
    revalidatePath('/staff/calendar')
    return { success: true }
  } catch (err) {
    console.error('[deleteAdminCalendarEvent]', err)
    return { error: 'Failed to delete event' }
  }
}

