import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import StaffCalendarGrid from './_components/StaffCalendarGrid'
import { subMonths, addMonths, startOfMonth, endOfMonth } from 'date-fns'

export const metadata: Metadata = {
  title: 'Academic Calendar | Staff Portal',
  description: 'Manage and broadcast institutional events, class schedules, and exam dates.',
}

export default async function StaffCalendarPage({
  searchParams,
}: {
  searchParams: Promise<{ month?: string }>
}) {
  const session = await getAuthSession()
  if (!session || !['ADMIN', 'STAFF'].includes(session.user.role)) {
    redirect('/login')
  }

  const { month } = await searchParams
  const currentDate = month ? new Date(month) : new Date()

  const rangeStart = subMonths(startOfMonth(currentDate), 1)
  const rangeEnd = addMonths(endOfMonth(currentDate), 1)

  // Fetch all event types in parallel (using prismaUnfiltered to bypass RLS overhead for Staff)
  const [classes, examEvents, adminEvents] = await Promise.all([
    // Class sessions
    prismaUnfiltered.class.findMany({
      where: {
        startDate: { lte: rangeEnd },
        endDate: { gte: rangeStart },
      },
      include: {
        course: { select: { id: true, code: true, name: true, category: true } },
        instructor: {
          include: {
            user: { select: { profile: { select: { firstName: true, lastName: true } } } },
          },
        },
      },
      orderBy: { startDate: 'asc' },
    }),

    // Exam events
    prismaUnfiltered.examEvent.findMany({
      where: {
        deletedAt: null,
        startDate: { lte: rangeEnd },
        endDate: { gte: rangeStart },
      },
      orderBy: { startDate: 'asc' },
    }),

    // Admin-created calendar events
    prismaUnfiltered.adminCalendarEvent.findMany({
      where: {
        deletedAt: null,
        startDate: { lte: rangeEnd },
      },
      include: {
        creator: { select: { profile: { select: { firstName: true, lastName: true } } } },
      },
      orderBy: { startDate: 'asc' },
    }),
  ])

  // Map to unified event format
  const events = [
    ...classes.map((cls: any) => ({
      id: `class-${cls.id}`,
      dbId: cls.id,
      title: `${cls.course.code} — ${cls.name}`,
      description: cls.instructor?.user?.profile
        ? `Instructor: ${cls.instructor.user.profile.firstName} ${cls.instructor.user.profile.lastName}`
        : 'No instructor assigned',
      startDate: cls.startDate.toISOString(),
      endDate: cls.endDate.toISOString(),
      color: '#4A72E8',
      source: 'class' as const,
      editable: false,
      visibleTo: 'ALL' as const,
      recurrenceType: cls.recurrenceType,
      recurrenceDays: cls.recurrenceDays,
      recurrenceUntil: cls.recurrenceUntil?.toISOString() || null,
    })),
    ...examEvents.map((evt: any) => ({
      id: `exam-${evt.id}`,
      dbId: evt.id,
      title: evt.name,
      description: `Status: ${evt.status}`,
      startDate: evt.startDate.toISOString(),
      endDate: evt.endDate.toISOString(),
      color: '#FF4F33',
      source: 'exam' as const,
      editable: false,
      visibleTo: 'ALL' as const,
      recurrenceType: 'NONE',
      recurrenceDays: null,
      recurrenceUntil: null,
    })),
    ...adminEvents.map((evt: any) => ({
      id: `admin-${evt.id}`,
      dbId: evt.id,
      title: evt.title,
      description: evt.description || null,
      startDate: evt.startDate.toISOString(),
      endDate: evt.endDate?.toISOString() || null,
      color: evt.color || '#8b5cf6',
      source: 'admin' as const,
      editable: true,
      visibleTo: evt.visibleTo as 'ALL' | 'STUDENTS' | 'INSTRUCTORS',
      recurrenceType: evt.recurrenceType,
      recurrenceDays: evt.recurrenceDays,
      recurrenceUntil: evt.recurrenceUntil?.toISOString() || null,
    })),
  ]

  return (
    <div className="mx-auto max-w-[1400px] px-4 py-6 md:px-8">
      <StaffCalendarGrid
        events={events}
        initialDate={currentDate}
        currentUserId={session.user.id}
      />
    </div>
  )
}

import { getAuthSession, requireStaff } from '@/lib/auth/helpers'
import { redirect, notFound } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import EditClassForm from './EditClassForm'
import { Metadata } from 'next'
import { serializePrisma } from '@/lib/utils/serialization'

export const metadata: Metadata = { title: 'Edit Class | Staff Portal' }

interface Props {
  params: Promise<{ id: string }>
}

export default async function EditClassPage({ params }: Props) {
  await requireStaff()
  const { id } = await params

  function slugify(text: string) {
    return text?.toString().toLowerCase().trim().replace(/\s+/g, '-').replace(/[^\w\-]+/g, '').replace(/\-\-+/g, '-') || '';
  }

  // Fallback: If id is a slug, find the class by name
  let targetId = id
  if (id.length < 20) { // CUIDs are usually 25 chars, simple heuristic
    const allBasicClasses = await prismaUnfiltered.class.findMany({ select: { id: true, name: true } })
    const matchedClass = allBasicClasses.find(c => slugify(c.name) === id)
    if (matchedClass) targetId = matchedClass.id
  }

  const [cls, courses, instructors] = await Promise.all([
    prismaUnfiltered.class.findUnique({
      where: { id: targetId },
    }),
    prismaUnfiltered.course.findMany({
      where: { isActive: true },
      orderBy: { code: 'asc' },
    }),
    prismaUnfiltered.instructorProfile.findMany({
      select: {
        id: true,
        user: {
          select: {
            id: true,
            email: true,
            profile: {
              select: {
                firstName: true,
                lastName: true,
              },
            },
          },
        },
      },
    }),
  ])

  if (!cls) notFound()

  // Serialize Prisma objects (Decimal/Date) for Client Component
  const serializedCls = serializePrisma(cls)
  const serializedCourses = serializePrisma(courses)
  const serializedInstructors = serializePrisma(instructors)

  return (
    <div className="mx-auto max-w-2xl">
      <div className="mb-8">
        <h1 className="text-3xl font-black tracking-tight text-aerojet-blue dark:text-white">Edit Class</h1>
        <p className="text-slate-500 dark:text-slate-400">Update class details and schedule</p>
      </div>

      <div className="rounded-2xl border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 p-6 shadow-sm">
        <EditClassForm
          initialData={serializedCls}
          courses={serializedCourses}
          instructors={serializedInstructors}
        />
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

interface BatchEnrollmentFormProps {
  classId: string
  cohorts: { id: string; name: string }[]
  currentOccupancy: number
  maxCapacity: number
}

export default function BatchEnrollmentForm({ classId, cohorts, currentOccupancy, maxCapacity }: BatchEnrollmentFormProps) {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [selectedCohort, setSelectedCohort] = useState<string>('')

  async function handleBatchEnroll() {
    if (!selectedCohort) {
      toast.error('Error', { description: 'Please select a cohort' })
      return
    }

    setIsLoading(true)
    try {
      const response = await fetch(`/api/staff/classes/${classId}/batch-enroll`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cohortId: selectedCohort }),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || 'Failed to enroll cohort')
      }

      const data = await response.json()
      toast.success('Batch Enrolled', { 
        description: `Successfully added ${data.addedCount} students to the class.` 
      })
      router.refresh()
    } catch (error: any) {
      toast.error('Enrollment Failed', { description: error.message })
    } finally {
      setIsLoading(false)
      setSelectedCohort('')
    }
  }

  const spacesLeft = maxCapacity - currentOccupancy

  return (
    <div className="space-y-4">
      <div>
        <label className="mb-2 block text-xs font-bold text-slate-700 dark:text-slate-300">
          Select Cohort (Academic Year)
        </label>
        <Select value={selectedCohort} onValueChange={setSelectedCohort} disabled={isLoading}>
          <SelectTrigger>
            <SelectValue placeholder="Select a cohort" />
          </SelectTrigger>
          <SelectContent>
            {cohorts.map(c => (
              <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="rounded-lg bg-blue-50 p-3 text-xs text-blue-700 dark:bg-blue-900/20 dark:text-blue-400">
        <p className="font-bold">Available Seats: {spacesLeft}</p>
        <p className="mt-1 opacity-80">Batch enrollment will fail if the cohort size exceeds available seats.</p>
      </div>

      <Button 
        onClick={handleBatchEnroll} 
        disabled={isLoading || !selectedCohort || spacesLeft <= 0}
        className="w-full bg-aerojet-blue hover:bg-aerojet-blue/90"
      >
        {isLoading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
        Enroll Entire Batch
      </Button>
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import {
  Save,
  Loader2,
  User,
  Users,
  GripVertical,
  X,
  Armchair,
  Ban,
  ChevronDown,
  ChevronUp,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

interface SeatData {
  id: string
  row: number
  col: number
  label: string | null
  isEnabled: boolean
}

interface StudentData {
  id: string
  name: string
}

interface LayoutData {
  rows: number
  cols: number
  cells: { row: number; col: number; type: string; label: string | null }[]
}

interface ClassSeatingAssignmentProps {
  classId: string
  classroomId: string
  layout: LayoutData
  seats: SeatData[]
  students: StudentData[]
}

export default function ClassSeatingAssignment({
  classId,
  classroomId,
  layout,
  seats,
  students,
}: ClassSeatingAssignmentProps) {
  // assignments: { seatId: userId }
  const [assignments, setAssignments] = useState<Record<string, string>>({})
  const [draggedStudent, setDraggedStudent] = useState<StudentData | null>(null)
  const [saving, setSaving] = useState(false)
  const [loading, setLoading] = useState(true)
  const [showUnassigned, setShowUnassigned] = useState(true)

  // Load existing assignments
  useEffect(() => {
    async function load() {
      try {
        const res = await fetch(`/api/staff/classes/${classId}/seating`)
        if (res.ok) {
          const data = await res.json()
          setAssignments(data.assignments || {})
        }
      } catch { /* ignore */ }
      setLoading(false)
    }
    load()
  }, [classId])

  const assignedStudentIds = new Set(Object.values(assignments))
  const unassignedStudents = students.filter((s) => !assignedStudentIds.has(s.id))
  const assignedCount = assignedStudentIds.size

  const getStudentOnSeat = useCallback(
    (seatId: string) => {
      const userId = assignments[seatId]
      return userId ? students.find((s) => s.id === userId) : undefined
    },
    [assignments, students]
  )

  function handleDropOnSeat(seat: SeatData) {
    if (!draggedStudent) return
    setAssignments((prev) => {
      const next = { ...prev }
      // Remove student from any previous seat
      for (const [sId, uId] of Object.entries(next)) {
        if (uId === draggedStudent.id) delete next[sId]
      }
      // Remove any existing occupant of this seat
      delete next[seat.id]
      // Assign
      next[seat.id] = draggedStudent.id
      return next
    })
    setDraggedStudent(null)
  }

  function handleRemoveFromSeat(seatId: string) {
    setAssignments((prev) => {
      const next = { ...prev }
      delete next[seatId]
      return next
    })
  }

  function handleDropOnUnassigned() {
    if (!draggedStudent) return
    setAssignments((prev) => {
      const next = { ...prev }
      for (const [sId, uId] of Object.entries(next)) {
        if (uId === draggedStudent.id) delete next[sId]
      }
      return next
    })
    setDraggedStudent(null)
  }

  async function handleSave() {
    setSaving(true)
    try {
      const res = await fetch(`/api/staff/classes/${classId}/seating`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ assignments }),
      })
      if (!res.ok) throw new Error('Failed to save')
      toast.success('Seating assignments saved', {
        description: `${assignedCount} of ${students.length} students assigned`,
      })
    } catch {
      toast.error('Failed to save seating assignments')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-slate-400" />
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Stats bar */}
      <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-6 text-sm">
          <span className="flex items-center gap-1.5 text-slate-500">
            <Users className="h-4 w-4" />
            {assignedCount}/{students.length} assigned
          </span>
          <span className="flex items-center gap-1.5 text-slate-500">
            <Armchair className="h-4 w-4" />
            {seats.length - assignedCount} seats available
          </span>
        </div>
        <div className="flex items-center gap-3">
          <div className="h-2 w-32 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
            <div
              className={cn(
                'h-full rounded-full transition-all',
                assignedCount === students.length
                  ? 'bg-emerald-500'
                  : assignedCount > 0
                    ? 'bg-aerojet-sky'
                    : 'bg-slate-300'
              )}
              style={{
                width: `${students.length > 0 ? (assignedCount / students.length) * 100 : 0}%`,
              }}
            />
          </div>
          <Button
            size="sm"
            onClick={handleSave}
            disabled={saving}
            className="bg-aerojet-blue hover:bg-aerojet-sky"
          >
            {saving ? (
              <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="mr-1.5 h-3.5 w-3.5" />
            )}
            Save
          </Button>
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-[280px_1fr]">
        {/* Unassigned students sidebar */}
        <div className="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <button
            onClick={() => setShowUnassigned(!showUnassigned)}
            className="flex w-full items-center justify-between p-4"
          >
            <h3 className="text-sm font-bold text-slate-900 dark:text-white">
              Unassigned ({unassignedStudents.length})
            </h3>
            {showUnassigned ? (
              <ChevronUp className="h-4 w-4 text-slate-400" />
            ) : (
              <ChevronDown className="h-4 w-4 text-slate-400" />
            )}
          </button>

          {showUnassigned && (
            <div
              className="max-h-[500px] space-y-1 overflow-y-auto border-t border-slate-100 p-2 dark:border-slate-800"
              onDragOver={(e) => {
                e.preventDefault()
                e.dataTransfer.dropEffect = 'move'
              }}
              onDrop={(e) => {
                e.preventDefault()
                handleDropOnUnassigned()
              }}
            >
              {unassignedStudents.length === 0 ? (
                <p className="p-3 text-center text-xs text-slate-400">
                  All students assigned!
                </p>
              ) : (
                unassignedStudents.map((student) => (
                  <div
                    key={student.id}
                    draggable
                    onDragStart={() => setDraggedStudent(student)}
                    onDragEnd={() => setDraggedStudent(null)}
                    className="flex cursor-grab items-center gap-2 rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-sm transition-all hover:border-aerojet-sky hover:bg-indigo-50 active:cursor-grabbing dark:border-slate-700 dark:bg-slate-800 dark:hover:border-indigo-600"
                  >
                    <GripVertical className="h-3.5 w-3.5 shrink-0 text-slate-300" />
                    <User className="h-3.5 w-3.5 shrink-0 text-slate-400" />
                    <span className="truncate font-medium text-slate-700 dark:text-slate-300">
                      {student.name}
                    </span>
                  </div>
                ))
              )}
            </div>
          )}
        </div>

        {/* Floor plan */}
        <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-slate-50 p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900/50">
          <div className="flex justify-center">
            <div className="space-y-2">
              <div className="mb-4 flex items-center justify-center rounded-lg border border-dashed border-slate-300 bg-white/50 px-6 py-2 dark:border-slate-700 dark:bg-slate-900/50">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                  Front of Room
                </span>
              </div>

              <div
                className="grid gap-1.5"
                style={{
                  gridTemplateColumns: `repeat(${layout.cols}, minmax(0, 1fr))`,
                }}
              >
                {Array.from({ length: layout.rows }, (_, r) =>
                  Array.from({ length: layout.cols }, (_, c) => {
                    const cell = layout.cells.find(
                      (cell) => cell.row === r && cell.col === c
                    )
                    const type = cell?.type ?? 'AISLE'

                    if (type !== 'DESK') {
                      return (
                        <div
                          key={`${r}-${c}`}
                          className={cn(
                            'flex h-14 w-14 items-center justify-center rounded-lg border sm:h-16 sm:w-16',
                            type === 'OBSTACLE'
                              ? 'border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-900/20'
                              : 'border-transparent'
                          )}
                        >
                          {type === 'OBSTACLE' && <Ban className="h-4 w-4 text-red-300" />}
                        </div>
                      )
                    }

                    const seat = seats.find((s) => s.row === r && s.col === c)
                    if (!seat) return <div key={`${r}-${c}`} className="h-14 w-14 sm:h-16 sm:w-16" />

                    const occupant = getStudentOnSeat(seat.id)
                    const isDropTarget = draggedStudent && !occupant

                    return (
                      <div
                        key={`${r}-${c}`}
                        onDragOver={(e) => {
                          if (draggedStudent) {
                            e.preventDefault()
                            e.dataTransfer.dropEffect = 'move'
                          }
                        }}
                        onDrop={(e) => {
                          e.preventDefault()
                          handleDropOnSeat(seat)
                        }}
                        className={cn(
                          'relative flex h-14 w-14 flex-col items-center justify-center rounded-lg border transition-all sm:h-16 sm:w-16',
                          occupant
                            ? 'border-indigo-300 bg-indigo-100 dark:border-indigo-700 dark:bg-indigo-900/30'
                            : isDropTarget
                              ? 'border-aerojet-sky border-dashed bg-indigo-50 ring-2 ring-aerojet-sky/30 dark:bg-indigo-900/10'
                              : 'border-slate-200 bg-white hover:border-slate-300 dark:border-slate-700 dark:bg-slate-800'
                        )}
                      >
                        <span className="text-[9px] font-bold text-slate-400">{seat.label}</span>
                        {occupant ? (
                          <>
                            <span
                              className="max-w-[48px] truncate text-[9px] font-bold text-indigo-700 dark:text-indigo-400 sm:max-w-[56px]"
                              title={occupant.name}
                            >
                              {occupant.name.split(' ')[0]}
                            </span>
                            <button
                              onClick={() => handleRemoveFromSeat(seat.id)}
                              className="absolute -right-1 -top-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-white hover:bg-red-600"
                              title="Remove from seat"
                            >
                              <X className="h-2.5 w-2.5" />
                            </button>
                          </>
                        ) : (
                          <Armchair className="h-3.5 w-3.5 text-slate-300 dark:text-slate-600" />
                        )}
                      </div>
                    )
                  })
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { zodResolver } from '@hookform/resolvers/zod'
import { useForm, type Resolver } from 'react-hook-form'
import * as z from 'zod'
import { useRouter } from 'next/navigation'
import { useState } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { createClassSchema } from '@/lib/validation/schemas'

// We need to adapt the schema for the form because datetime strings are needed for the API
// but the form might use date inputs which produce strings that need converting to ISO.
const formSchema = createClassSchema.extend({
  startDate: z.string().min(1, 'Start date is required'),
  endDate: z.string().min(1, 'End date is required'),
  recurrenceType: z.enum(['NONE', 'DAILY', 'WEEKLY', 'MONTHLY', 'CUSTOM']).default('NONE'),
  recurrenceDays: z.string().optional(),
  recurrenceUntil: z.string().optional().nullable(),
  classroomId: z.string().optional(),
  weeklySchedule: z.array(z.object({
    day: z.number(), // 0-6 (Sun-Sat)
    active: z.boolean(),
    startTime: z.string(),
    endTime: z.string(),
  })).optional(),
})

type FormValues = z.infer<typeof formSchema>

interface InstructorItem {
  id: string
  user: {
    id: string
    email: string
    profile: {
      firstName: string
      lastName: string
    } | null
  }
}

interface CreateClassFormProps {
  courses: { id: string; name: string; code: string }[]
  instructors: InstructorItem[]
  classrooms: { id: string; name: string; capacity: number; type: string | null }[]
}

const DAYS_OF_WEEK = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

export default function CreateClassForm({ courses, instructors, classrooms }: CreateClassFormProps) {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema) as unknown as Resolver<FormValues>,
    defaultValues: {
      name: '',
      courseId: '',
      instructorId: undefined,
      startDate: '',
      endDate: '',
      maxStudents: 28,
      recurrenceType: 'NONE',
      recurrenceDays: '',
      recurrenceUntil: '',
      classroomId: undefined,
      weeklySchedule: Array.from({ length: 7 }).map((_, i) => ({
        day: i,
        active: false,
        startTime: '09:00',
        endTime: '17:00',
      })),
    },
  })

  const recurrenceType = form.watch('recurrenceType')

  async function onSubmit(values: FormValues) {
    setIsLoading(true)
    try {
      // Convert dates to ISO format and handle optional instructorId
      const data = {
        ...values,
        instructorId: values.instructorId === 'none' ? undefined : values.instructorId,
        startDate: new Date(values.startDate).toISOString(),
        endDate: new Date(values.endDate).toISOString(),
        recurrenceUntil: values.recurrenceUntil ? new Date(values.recurrenceUntil).toISOString() : undefined,
        classroomId: values.classroomId === 'none' ? undefined : values.classroomId,
        schedule: values.weeklySchedule?.filter(s => s.active),
      }

      const response = await fetch('/api/staff/classes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || 'Failed to create class')
      }

      toast.success('Class scheduled successfully')
      router.push('/staff/classes')
      router.refresh()
    } catch (error: any) {
      toast.error(error.message || 'Failed to create class')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
          <FormField
            control={form.control}
            name="name"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-name">Class Name</FormLabel>
                <FormControl>
                  <Input
                    id="class-name"
                    placeholder="e.g., Evening Batch A"
                    autoComplete="off"
                    {...field}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="courseId"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-course">Course</FormLabel>
                <Select onValueChange={field.onChange} defaultValue={field.value}>
                  <FormControl>
                    <SelectTrigger id="class-course">
                      <SelectValue placeholder="Select a course" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    {courses.map((course) => (
                      <SelectItem key={course.id} value={course.id}>
                        {course.code} - {course.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="instructorId"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-instructor">Instructor (Optional)</FormLabel>
                <Select onValueChange={field.onChange} defaultValue={field.value}>
                  <FormControl>
                    <SelectTrigger id="class-instructor">
                      <SelectValue placeholder="Select an instructor" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="none">Unassigned</SelectItem>
                    {instructors.map((inst) => (
                      <SelectItem key={inst.id} value={inst.id}>
                        {inst.user.profile
                          ? `${inst.user.profile.firstName} ${inst.user.profile.lastName}`
                          : inst.user.email}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="classroomId"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-room">Classroom/Venue (Optional)</FormLabel>
                <Select 
                  onValueChange={(val) => {
                    field.onChange(val)
                    if (val !== 'none') {
                      const room = classrooms.find(r => r.id === val)
                      if (room) {
                        const currentMax = form.getValues('maxStudents')
                        if (currentMax > room.capacity) {
                          form.setValue('maxStudents', room.capacity)
                          toast.info('Capacity Adjusted', { description: `Max students lowered to match room capacity (${room.capacity})` })
                        }
                      }
                    }
                  }} 
                  defaultValue={field.value}
                >
                  <FormControl>
                    <SelectTrigger id="class-room">
                      <SelectValue placeholder="Select a room" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="none">Unassigned</SelectItem>
                    {classrooms.map((room) => (
                      <SelectItem key={room.id} value={room.id}>
                        {room.name} (Cap: {room.capacity})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="startDate"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-start">Start Date</FormLabel>
                <FormControl>
                  <Input
                    id="class-start"
                    type="date"
                    autoComplete="off"
                    {...field}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="endDate"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-end">End Date</FormLabel>
                <FormControl>
                  <Input
                    id="class-end"
                    type="date"
                    autoComplete="off"
                    {...field}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="maxStudents"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-max">Max Students</FormLabel>
                <FormControl>
                  <Input
                    id="class-max"
                    type="number"
                    autoComplete="off"
                    {...field}
                    onChange={(e) => {
                      const val = parseInt(e.target.value)
                      const roomId = form.getValues('classroomId')
                      if (roomId && roomId !== 'none') {
                        const room = classrooms.find(r => r.id === roomId)
                        if (room && val > room.capacity) {
                          toast.error('Capacity Exceeded', { description: `Room max capacity is ${room.capacity}` })
                          field.onChange(room.capacity)
                          return
                        }
                      }
                      field.onChange(val)
                    }}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="recurrenceType"
            render={({ field }) => (
              <FormItem>
                <FormLabel htmlFor="class-recurrence">Recurrence</FormLabel>
                <Select onValueChange={field.onChange} defaultValue={field.value}>
                  <FormControl>
                    <SelectTrigger id="class-recurrence">
                      <SelectValue placeholder="Select recurrence" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="NONE">Does not repeat</SelectItem>
                    <SelectItem value="WEEKLY">Weekly Schedule</SelectItem>
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />

          {recurrenceType === 'WEEKLY' && (
            <div className="col-span-full mt-4 space-y-4 rounded-xl border border-slate-200 p-6 dark:border-slate-800">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-sm font-bold text-slate-900 dark:text-white">Weekly Schedule Configuration</h4>
                  <p className="text-xs text-slate-500">Configure instruction hours for each active day.</p>
                </div>
              </div>
              <div className="space-y-3">
                {form.watch('weeklySchedule')?.map((schedule, index) => (
                  <div key={index} className={`flex items-center gap-4 rounded-lg border p-3 transition-colors ${schedule.active ? 'border-aerojet-blue/30 bg-blue-50/50 dark:border-aerojet-blue/50 dark:bg-blue-900/10' : 'border-slate-100 dark:border-slate-800'}`}>
                    <label className="flex w-24 items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={schedule.active}
                        onChange={(e) => {
                          const schedules = [...form.getValues('weeklySchedule') || []]
                          schedules[index].active = e.target.checked
                          form.setValue('weeklySchedule', schedules)
                        }}
                        className="h-4 w-4 rounded border-slate-300 text-aerojet-blue focus:ring-aerojet-blue"
                      />
                      <span className={`text-sm font-bold ${schedule.active ? 'text-slate-900 dark:text-white' : 'text-slate-400'}`}>
                        {DAYS_OF_WEEK[index]}
                      </span>
                    </label>
                    
                    <div className={`flex flex-1 items-center gap-3 ${!schedule.active && 'opacity-30 pointer-events-none'}`}>
                      <Input
                        type="time"
                        value={schedule.startTime}
                        onChange={(e) => {
                          const schedules = [...form.getValues('weeklySchedule') || []]
                          schedules[index].startTime = e.target.value
                          form.setValue('weeklySchedule', schedules)
                        }}
                        className="h-9 w-32"
                      />
                      <span className="text-slate-400">to</span>
                      <Input
                        type="time"
                        value={schedule.endTime}
                        onChange={(e) => {
                          const schedules = [...form.getValues('weeklySchedule') || []]
                          schedules[index].endTime = e.target.value
                          form.setValue('weeklySchedule', schedules)
                        }}
                        className="h-9 w-32"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {recurrenceType !== 'NONE' && (
            <FormField
              control={form.control}
              name="recurrenceUntil"
              render={({ field }) => (
                <FormItem>
                  <FormLabel htmlFor="class-recurrence-until">Repeat Until</FormLabel>
                  <FormControl>
                    <Input
                      id="class-recurrence-until"
                      type="date"
                      autoComplete="off"
                      value={field.value || ''}
                      onChange={field.onChange}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          )}
        </div>

        <div className="flex justify-end gap-4">
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
            disabled={isLoading}
          >
            Cancel
          </Button>
          <Button type="submit" className="bg-aerojet-blue hover:bg-aerojet-blue/90" disabled={isLoading}>
            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Schedule Class
          </Button>
        </div>
      </form>
    </Form>
  )
}

'use client'

import { useState, useCallback } from 'react'
import {
  Save,
  Loader2,
  RotateCcw,
  Grid3X3,
  Armchair,
  Square,
  Ban,
  Minus,
  Plus,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

type CellType = 'DESK' | 'AISLE' | 'OBSTACLE'

interface Cell {
  row: number
  col: number
  type: CellType
  label: string | null
}

interface LayoutData {
  rows: number
  cols: number
  cells: Cell[]
}

interface FloorPlanDesignerProps {
  classroomId: string
  classroomName: string
  initialLayout: LayoutData | null
}

const TOOLS: { type: CellType; label: string; icon: typeof Armchair; color: string }[] = [
  { type: 'DESK', label: 'Desk', icon: Armchair, color: 'bg-indigo-100 text-indigo-700 border-indigo-300 dark:bg-indigo-900/30 dark:text-indigo-400 dark:border-indigo-700' },
  { type: 'AISLE', label: 'Aisle', icon: Square, color: 'bg-slate-50 text-slate-400 border-slate-200 dark:bg-slate-800/50 dark:text-slate-500 dark:border-slate-700' },
  { type: 'OBSTACLE', label: 'Obstacle', icon: Ban, color: 'bg-red-50 text-red-600 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-800' },
]

function generateLabels(cells: Cell[]): Cell[] {
  const desks = cells
    .filter((c) => c.type === 'DESK')
    .sort((a, b) => a.row - b.row || a.col - b.col)

  let currentRow = -1
  let rowLetter = 64 // ASCII before 'A'
  let colNum = 0

  return cells.map((cell) => {
    if (cell.type !== 'DESK') return { ...cell, label: null }

    const deskIndex = desks.findIndex((d) => d.row === cell.row && d.col === cell.col)
    const desk = desks[deskIndex]

    if (desk.row !== currentRow) {
      currentRow = desk.row
      rowLetter++
      colNum = 0
    }
    colNum++

    return { ...cell, label: `${String.fromCharCode(rowLetter)}${colNum}` }
  })
}

function buildInitialGrid(rows: number, cols: number): Cell[] {
  const cells: Cell[] = []
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      cells.push({ row: r, col: c, type: 'AISLE', label: null })
    }
  }
  return cells
}

export default function FloorPlanDesigner({
  classroomId,
  classroomName,
  initialLayout,
}: FloorPlanDesignerProps) {
  const [rows, setRows] = useState(initialLayout?.rows ?? 6)
  const [cols, setCols] = useState(initialLayout?.cols ?? 8)
  const [cells, setCells] = useState<Cell[]>(
    initialLayout?.cells ?? buildInitialGrid(6, 8)
  )
  const [activeTool, setActiveTool] = useState<CellType>('DESK')
  const [saving, setSaving] = useState(false)
  const [isDragging, setIsDragging] = useState(false)

  const deskCount = cells.filter((c) => c.type === 'DESK').length

  const getCell = useCallback(
    (row: number, col: number) => cells.find((c) => c.row === row && c.col === col),
    [cells]
  )

  function updateCell(row: number, col: number) {
    setCells((prev) => {
      const updated = prev.map((c) =>
        c.row === row && c.col === col ? { ...c, type: activeTool, label: null } : c
      )
      return generateLabels(updated)
    })
  }

  function handleResizeGrid(newRows: number, newCols: number) {
    const clamped = {
      rows: Math.max(1, Math.min(30, newRows)),
      cols: Math.max(1, Math.min(30, newCols)),
    }
    setRows(clamped.rows)
    setCols(clamped.cols)

    setCells((prev) => {
      const newCells: Cell[] = []
      for (let r = 0; r < clamped.rows; r++) {
        for (let c = 0; c < clamped.cols; c++) {
          const existing = prev.find((p) => p.row === r && p.col === c)
          newCells.push(existing ?? { row: r, col: c, type: 'AISLE', label: null })
        }
      }
      return generateLabels(newCells)
    })
  }

  function handleReset() {
    setCells(generateLabels(buildInitialGrid(rows, cols)))
  }

  async function handleSave() {
    setSaving(true)
    try {
      const labeled = generateLabels(cells)
      const res = await fetch(`/api/staff/classrooms/${classroomId}/layout`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows, cols, cells: labeled }),
      })
      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to save layout')
      }
      toast.success('Floor plan saved', {
        description: `${deskCount} desks configured for ${classroomName}`,
      })
    } catch (err: any) {
      toast.error(err.message || 'Failed to save layout')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        {/* Tool selector */}
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
            Tool:
          </span>
          {TOOLS.map((tool) => {
            const Icon = tool.icon
            return (
              <button
                key={tool.type}
                onClick={() => setActiveTool(tool.type)}
                className={cn(
                  'flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-bold transition-all',
                  activeTool === tool.type
                    ? tool.color + ' ring-2 ring-offset-1 ring-aerojet-sky'
                    : 'border-slate-200 bg-white text-slate-500 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-400'
                )}
              >
                <Icon className="h-3.5 w-3.5" />
                {tool.label}
              </button>
            )
          })}
        </div>

        <div className="h-6 w-px bg-slate-200 dark:bg-slate-700" />

        {/* Grid size */}
        <div className="flex items-center gap-2">
          <Grid3X3 className="h-4 w-4 text-slate-400" />
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={() => handleResizeGrid(rows - 1, cols)}
            >
              <Minus className="h-3 w-3" />
            </Button>
            <Input
              type="number"
              min={1}
              max={30}
              value={rows}
              onChange={(e) => handleResizeGrid(parseInt(e.target.value) || 1, cols)}
              className="h-7 w-12 text-center text-xs"
            />
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={() => handleResizeGrid(rows + 1, cols)}
            >
              <Plus className="h-3 w-3" />
            </Button>
          </div>
          <span className="text-xs text-slate-400">x</span>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={() => handleResizeGrid(rows, cols - 1)}
            >
              <Minus className="h-3 w-3" />
            </Button>
            <Input
              type="number"
              min={1}
              max={30}
              value={cols}
              onChange={(e) => handleResizeGrid(rows, parseInt(e.target.value) || 1)}
              className="h-7 w-12 text-center text-xs"
            />
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={() => handleResizeGrid(rows, cols + 1)}
            >
              <Plus className="h-3 w-3" />
            </Button>
          </div>
        </div>

        <div className="h-6 w-px bg-slate-200 dark:bg-slate-700" />

        {/* Stats */}
        <div className="flex items-center gap-4 text-xs font-bold text-slate-500 dark:text-slate-400">
          <span>
            <Armchair className="mr-1 inline h-3.5 w-3.5 text-indigo-500" />
            {deskCount} desks
          </span>
        </div>

        <div className="ml-auto flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={handleReset}>
            <RotateCcw className="mr-1.5 h-3.5 w-3.5" />
            Reset
          </Button>
          <Button
            size="sm"
            onClick={handleSave}
            disabled={saving}
            className="bg-aerojet-blue hover:bg-aerojet-sky"
          >
            {saving ? (
              <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="mr-1.5 h-3.5 w-3.5" />
            )}
            Save Layout
          </Button>
        </div>
      </div>

      {/* Grid */}
      <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-slate-50 p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900/50">
        <div className="flex justify-center">
          {/* Instructor area label */}
          <div className="space-y-2">
            <div className="mb-4 flex items-center justify-center rounded-lg border border-dashed border-slate-300 bg-white/50 px-6 py-2 dark:border-slate-700 dark:bg-slate-900/50">
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                Front of Room
              </span>
            </div>

            <div
              className="grid gap-1.5 select-none"
              style={{
                gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
              }}
              onMouseLeave={() => setIsDragging(false)}
            >
              {Array.from({ length: rows }, (_, r) =>
                Array.from({ length: cols }, (_, c) => {
                  const cell = getCell(r, c)
                  const type = cell?.type ?? 'AISLE'
                  const label = cell?.label

                  return (
                    <button
                      key={`${r}-${c}`}
                      onMouseDown={(e) => {
                        e.preventDefault()
                        setIsDragging(true)
                        updateCell(r, c)
                      }}
                      onMouseEnter={() => {
                        if (isDragging) updateCell(r, c)
                      }}
                      onMouseUp={() => setIsDragging(false)}
                      className={cn(
                        'flex h-10 w-10 items-center justify-center rounded-lg border text-[10px] font-bold transition-all sm:h-12 sm:w-12',
                        type === 'DESK' &&
                          'border-indigo-300 bg-indigo-100 text-indigo-700 hover:bg-indigo-200 dark:border-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400',
                        type === 'AISLE' &&
                          'border-slate-200 bg-white/60 text-slate-300 hover:bg-slate-100 dark:border-slate-700 dark:bg-slate-800/30 dark:text-slate-600',
                        type === 'OBSTACLE' &&
                          'border-red-200 bg-red-50 text-red-400 hover:bg-red-100 dark:border-red-800 dark:bg-red-900/20 dark:text-red-500'
                      )}
                      title={`Row ${r + 1}, Col ${c + 1} — ${type}${label ? ` (${label})` : ''}`}
                    >
                      {type === 'DESK' && label}
                      {type === 'OBSTACLE' && <Ban className="h-3.5 w-3.5" />}
                    </button>
                  )
                })
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Legend */}
      <div className="flex items-center gap-6 text-xs text-slate-500 dark:text-slate-400">
        <span className="font-bold uppercase tracking-widest">Legend:</span>
        {TOOLS.map((tool) => {
          const Icon = tool.icon
          return (
            <span key={tool.type} className="flex items-center gap-1.5">
              <span
                className={cn(
                  'flex h-5 w-5 items-center justify-center rounded border',
                  tool.color
                )}
              >
                <Icon className="h-3 w-3" />
              </span>
              {tool.label}
            </span>
          )
        })}
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'
import {
  Save,
  Loader2,
  User,
  Users,
  GripVertical,
  X,
  Armchair,
  Ban,
  ChevronDown,
  ChevronUp,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

interface SeatData {
  id: string
  row: number
  col: number
  label: string | null
  isEnabled: boolean
}

interface StudentData {
  assignmentId: string
  userId: string
  name: string
  seatId: string | null
  seatLabel: string | null
}

interface LayoutData {
  rows: number
  cols: number
  cells: { row: number; col: number; type: string; label: string | null }[]
}

interface SeatingAssignmentProps {
  sittingId: string
  sittingLabel: string
  layout: LayoutData
  seats: SeatData[]
  students: StudentData[]
}

export default function SeatingAssignment({
  sittingId,
  sittingLabel,
  layout,
  seats,
  students: initialStudents,
}: SeatingAssignmentProps) {
  const [students, setStudents] = useState<StudentData[]>(initialStudents)
  const [draggedStudent, setDraggedStudent] = useState<StudentData | null>(null)
  const [saving, setSaving] = useState(false)
  const [showUnassigned, setShowUnassigned] = useState(true)

  const assignedCount = students.filter((s) => s.seatId).length
  const unassignedStudents = students.filter((s) => !s.seatId)
  const totalSeats = seats.length

  const getStudentOnSeat = useCallback(
    (seatId: string) => students.find((s) => s.seatId === seatId),
    [students]
  )

  function handleDragStart(student: StudentData) {
    setDraggedStudent(student)
  }

  function handleDropOnSeat(seat: SeatData) {
    if (!draggedStudent) return

    setStudents((prev) => {
      // Remove student from previous seat
      const updated = prev.map((s) => {
        if (s.assignmentId === draggedStudent.assignmentId) {
          return { ...s, seatId: seat.id, seatLabel: seat.label }
        }
        // If another student was on this seat, unseat them
        if (s.seatId === seat.id) {
          return { ...s, seatId: null, seatLabel: null }
        }
        return s
      })
      return updated
    })
    setDraggedStudent(null)
  }

  function handleRemoveFromSeat(assignmentId: string) {
    setStudents((prev) =>
      prev.map((s) =>
        s.assignmentId === assignmentId ? { ...s, seatId: null, seatLabel: null } : s
      )
    )
  }

  function handleDropOnUnassigned() {
    if (!draggedStudent) return
    handleRemoveFromSeat(draggedStudent.assignmentId)
    setDraggedStudent(null)
  }

  async function handleSave() {
    setSaving(true)
    try {
      const assignments = students.map((s) => ({
        assignmentId: s.assignmentId,
        seatId: s.seatId,
      }))

      const res = await fetch(`/api/staff/exams/sittings/${sittingId}/seats`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ assignments }),
      })

      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to save assignments')
      }

      toast.success('Seating assignments saved', {
        description: `${assignedCount} of ${students.length} students assigned`,
      })
    } catch (err: any) {
      toast.error(err.message || 'Failed to save')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="space-y-4">
      {/* Stats Bar */}
      <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-6 text-sm">
          <span className="font-bold text-slate-900 dark:text-white">{sittingLabel}</span>
          <span className="flex items-center gap-1.5 text-slate-500">
            <Users className="h-4 w-4" />
            {assignedCount}/{students.length} assigned
          </span>
          <span className="flex items-center gap-1.5 text-slate-500">
            <Armchair className="h-4 w-4" />
            {totalSeats - assignedCount} seats available
          </span>
        </div>

        {/* Occupancy bar */}
        <div className="flex items-center gap-3">
          <div className="h-2 w-32 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
            <div
              className={cn(
                'h-full rounded-full transition-all',
                assignedCount === students.length
                  ? 'bg-emerald-500'
                  : assignedCount > 0
                    ? 'bg-aerojet-sky'
                    : 'bg-slate-300'
              )}
              style={{
                width: `${students.length > 0 ? (assignedCount / students.length) * 100 : 0}%`,
              }}
            />
          </div>
          <Button
            size="sm"
            onClick={handleSave}
            disabled={saving}
            className="bg-aerojet-blue hover:bg-aerojet-sky"
          >
            {saving ? (
              <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="mr-1.5 h-3.5 w-3.5" />
            )}
            Save
          </Button>
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-[280px_1fr]">
        {/* Unassigned Students Sidebar */}
        <div className="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <button
            onClick={() => setShowUnassigned(!showUnassigned)}
            className="flex w-full items-center justify-between p-4"
          >
            <h3 className="text-sm font-bold text-slate-900 dark:text-white">
              Unassigned ({unassignedStudents.length})
            </h3>
            {showUnassigned ? (
              <ChevronUp className="h-4 w-4 text-slate-400" />
            ) : (
              <ChevronDown className="h-4 w-4 text-slate-400" />
            )}
          </button>

          {showUnassigned && (
            <div
              className="max-h-[500px] space-y-1 overflow-y-auto border-t border-slate-100 p-2 dark:border-slate-800"
              onDragOver={(e) => {
                e.preventDefault()
                e.dataTransfer.dropEffect = 'move'
              }}
              onDrop={(e) => {
                e.preventDefault()
                handleDropOnUnassigned()
              }}
            >
              {unassignedStudents.length === 0 ? (
                <p className="p-3 text-center text-xs text-slate-400">
                  All students assigned!
                </p>
              ) : (
                unassignedStudents.map((student) => (
                  <div
                    key={student.assignmentId}
                    draggable
                    onDragStart={() => handleDragStart(student)}
                    onDragEnd={() => setDraggedStudent(null)}
                    className="flex cursor-grab items-center gap-2 rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-sm transition-all hover:border-aerojet-sky hover:bg-indigo-50 active:cursor-grabbing dark:border-slate-700 dark:bg-slate-800 dark:hover:border-indigo-600 dark:hover:bg-indigo-900/20"
                  >
                    <GripVertical className="h-3.5 w-3.5 shrink-0 text-slate-300" />
                    <User className="h-3.5 w-3.5 shrink-0 text-slate-400" />
                    <span className="truncate font-medium text-slate-700 dark:text-slate-300">
                      {student.name}
                    </span>
                  </div>
                ))
              )}
            </div>
          )}
        </div>

        {/* Floor Plan View */}
        <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-slate-50 p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900/50">
          <div className="flex justify-center">
            <div className="space-y-2">
              <div className="mb-4 flex items-center justify-center rounded-lg border border-dashed border-slate-300 bg-white/50 px-6 py-2 dark:border-slate-700 dark:bg-slate-900/50">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                  Front of Room
                </span>
              </div>

              <div
                className="grid gap-1.5"
                style={{
                  gridTemplateColumns: `repeat(${layout.cols}, minmax(0, 1fr))`,
                }}
              >
                {Array.from({ length: layout.rows }, (_, r) =>
                  Array.from({ length: layout.cols }, (_, c) => {
                    const cell = layout.cells.find(
                      (cell) => cell.row === r && cell.col === c
                    )
                    const type = cell?.type ?? 'AISLE'

                    if (type !== 'DESK') {
                      return (
                        <div
                          key={`${r}-${c}`}
                          className={cn(
                            'flex h-14 w-14 items-center justify-center rounded-lg border sm:h-16 sm:w-16',
                            type === 'OBSTACLE'
                              ? 'border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-900/20'
                              : 'border-transparent'
                          )}
                        >
                          {type === 'OBSTACLE' && (
                            <Ban className="h-4 w-4 text-red-300" />
                          )}
                        </div>
                      )
                    }

                    // It's a desk - find the matching seat
                    const seat = seats.find(
                      (s) => s.row === r && s.col === c
                    )
                    if (!seat) return <div key={`${r}-${c}`} className="h-14 w-14 sm:h-16 sm:w-16" />

                    const occupant = getStudentOnSeat(seat.id)
                    const isDropTarget = draggedStudent && !occupant

                    return (
                      <div
                        key={`${r}-${c}`}
                        onDragOver={(e) => {
                          if (draggedStudent) {
                            e.preventDefault()
                            e.dataTransfer.dropEffect = 'move'
                          }
                        }}
                        onDrop={(e) => {
                          e.preventDefault()
                          handleDropOnSeat(seat)
                        }}
                        className={cn(
                          'relative flex h-14 w-14 flex-col items-center justify-center rounded-lg border transition-all sm:h-16 sm:w-16',
                          occupant
                            ? 'border-indigo-300 bg-indigo-100 dark:border-indigo-700 dark:bg-indigo-900/30'
                            : isDropTarget
                              ? 'border-aerojet-sky border-dashed bg-indigo-50 ring-2 ring-aerojet-sky/30 dark:bg-indigo-900/10'
                              : 'border-slate-200 bg-white hover:border-slate-300 dark:border-slate-700 dark:bg-slate-800'
                        )}
                      >
                        <span className="text-[9px] font-bold text-slate-400">
                          {seat.label}
                        </span>
                        {occupant ? (
                          <>
                            <span
                              className="max-w-[48px] truncate text-[9px] font-bold text-indigo-700 dark:text-indigo-400 sm:max-w-[56px]"
                              title={occupant.name}
                            >
                              {occupant.name.split(' ')[0]}
                            </span>
                            <button
                              onClick={() =>
                                handleRemoveFromSeat(occupant.assignmentId)
                              }
                              className="absolute -right-1 -top-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-white opacity-0 transition-opacity hover:bg-red-600 group-hover:opacity-100"
                              style={{ opacity: 1 }}
                              title="Remove from seat"
                            >
                              <X className="h-2.5 w-2.5" />
                            </button>
                          </>
                        ) : (
                          <Armchair className="h-3.5 w-3.5 text-slate-300 dark:text-slate-600" />
                        )}
                      </div>
                    )
                  })
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import { Metadata } from 'next'
import { getAuthSession } from '@/lib/auth/helpers'
import { redirect, notFound } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import Link from 'next/link'
import { ArrowLeft, MapPin, Users, Building } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import FloorPlanDesigner from './_components/FloorPlanDesigner'

export const metadata: Metadata = {
  title: 'Classroom Layout | Staff Portal',
  description: 'Design the floor plan and seating layout for a classroom.',
}

export default async function ClassroomDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const session = await getAuthSession()
  if (!session || !['SUPER_ADMIN', 'ADMIN'].includes(session.user.role)) redirect('/login')

  const { id } = await params

  const classroom = await prismaUnfiltered.classroom.findUnique({
    where: { id },
    include: {
      seats: { orderBy: [{ row: 'asc' }, { col: 'asc' }] },
      _count: { select: { classes: true } },
    },
  })

  if (!classroom) notFound()

  const layout = classroom.layout as { rows: number; cols: number; cells: any[] } | null

  return (
    <div className="mx-auto max-w-[1400px] space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header */}
      <div className="flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-col gap-2">
          <Link
            href="/staff/classrooms"
            className="mb-1 inline-flex w-fit items-center gap-1.5 text-xs font-bold text-slate-400 transition-colors hover:text-aerojet-sky"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
            Back to Facilities
          </Link>
          <h1 className="text-3xl font-black tracking-tight text-aerojet-blue sm:text-4xl dark:text-white">
            {classroom.name}
          </h1>
          <div className="flex items-center gap-4 text-sm font-medium text-slate-500 dark:text-slate-400">
            <span className="flex items-center gap-1.5">
              <MapPin className="h-4 w-4 text-aerojet-sky" />
              {classroom.type || 'Standard Room'}
            </span>
            <span className="flex items-center gap-1.5">
              <Users className="h-4 w-4 text-slate-400" />
              Capacity: {classroom.capacity}
            </span>
            <span className="flex items-center gap-1.5">
              <Building className="h-4 w-4 text-slate-400" />
              {classroom._count.classes} classes
            </span>
          </div>
        </div>
        <Badge variant="outline" className="h-fit text-xs font-black uppercase">
          {classroom.seats.length} seats configured
        </Badge>
      </div>

      {/* Floor Plan Designer */}
      <FloorPlanDesigner
        classroomId={classroom.id}
        classroomName={classroom.name}
        initialLayout={layout}
      />
    </div>
  )
}

'use client'

import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import * as z from 'zod'
import { useRouter } from 'next/navigation'
import { useState } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'

const formSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  capacity: z.number().int().positive('Capacity must be positive'),
  type: z.string().optional(),
})

type FormValues = z.infer<typeof formSchema>

export default function CreateClassroomForm() {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: '',
      capacity: 30,
      type: '',
    },
  })

  async function onSubmit(values: FormValues) {
    setIsLoading(true)
    try {
      const response = await fetch('/api/staff/classrooms', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(values),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || 'Failed to add room')
      }

      toast.success('Success', { description: 'Room added successfully' })
      router.push('/staff/classrooms')
      router.refresh()
    } catch (error: any) {
      toast.error('Error', { description: error.message || 'Failed to add room' })
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 max-w-xl">
        <FormField
          control={form.control}
          name="name"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Room Name/Number</FormLabel>
              <FormControl>
                <Input placeholder="e.g., Room 101, Sim Lab A" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="capacity"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Seating Capacity</FormLabel>
              <FormControl>
                <Input
                  type="number"
                  {...field}
                  onChange={(e) => field.onChange(parseInt(e.target.value))}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="type"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Type (Optional)</FormLabel>
              <FormControl>
                <Input placeholder="e.g., Lecture Hall, Laboratory" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <div className="flex justify-end gap-4">
          <Button type="button" variant="outline" onClick={() => router.back()} disabled={isLoading}>
            Cancel
          </Button>
          <Button type="submit" className="bg-aerojet-blue hover:bg-aerojet-blue/90" disabled={isLoading}>
            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Room
          </Button>
        </div>
      </form>
    </Form>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { Pencil, Loader2 } from 'lucide-react'

const LICENCE_CATEGORIES = ['A', 'B1', 'B2', 'B3'] as const

export default function CourseInfoEditDialog({
  course,
  categories,
}: {
  course: any
  categories: any[]
}) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  // Form state
  const [description, setDescription] = useState(course.description || '')
  const [subtitle, setSubtitle] = useState(course.subtitle || '')
  const [duration, setDuration] = useState(course.duration?.toString() || '')
  const [categoryId, setCategoryId] = useState(course.categoryId || '')
  const [prerequisites, setPrerequisites] = useState(course.prerequisites?.join(', ') || '')
  const [topics, setTopics] = useState(course.topics?.join(', ') || '')
  const [studyHoursMin, setStudyHoursMin] = useState(
    course.estimatedStudyHoursMin?.toString() || ''
  )
  const [studyHoursMax, setStudyHoursMax] = useState(
    course.estimatedStudyHoursMax?.toString() || ''
  )
  const [applicableCategories, setApplicableCategories] = useState<string[]>(
    course.applicableCategories || []
  )

  const toggleCategory = (cat: string) => {
    setApplicableCategories((prev) =>
      prev.includes(cat) ? prev.filter((c) => c !== cat) : [...prev, cat]
    )
  }

  const handleSave = async () => {
    setLoading(true)
    setError('')
    try {
      const res = await fetch(`/api/staff/courses/${course.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          description,
          subtitle: subtitle || undefined,
          duration: duration ? parseInt(duration) : null,
          categoryId: categoryId || null,
          prerequisites: prerequisites
            .split(',')
            .map((p: string) => p.trim())
            .filter(Boolean),
          requiresPrerequisite: prerequisites.trim().length > 0,
          topics: topics
            .split(',')
            .map((t: string) => t.trim())
            .filter(Boolean),
          estimatedStudyHoursMin: studyHoursMin ? parseInt(studyHoursMin) : null,
          estimatedStudyHoursMax: studyHoursMax ? parseInt(studyHoursMax) : null,
          applicableCategories,
        }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to update')
      setOpen(false)
      router.refresh()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="ghost" size="sm" className="h-6 gap-1 px-2 text-[10px]">
          <Pencil className="h-3 w-3" /> Edit Info
        </Button>
      </DialogTrigger>
      <DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-[560px]">
        <DialogHeader>
          <DialogTitle>Edit Course Info</DialogTitle>
        </DialogHeader>
        <div className="mt-4 space-y-4">
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-600">Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-600">Subtitle</label>
            <input
              type="text"
              value={subtitle}
              onChange={(e) => setSubtitle(e.target.value)}
              placeholder="e.g. Arithmetic · Algebra · Geometry"
              className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-600">
              Topics (comma separated)
            </label>
            <input
              type="text"
              value={topics}
              onChange={(e) => setTopics(e.target.value)}
              placeholder="e.g. Arithmetic, Algebra, Geometry"
              className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-600">
                Duration (Hours)
              </label>
              <input
                type="number"
                value={duration}
                onChange={(e) => setDuration(e.target.value)}
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-600">Category</label>
              <select
                value={categoryId}
                onChange={(e) => setCategoryId(e.target.value)}
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              >
                <option value="">None</option>
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-600">
                Study Hours (Min)
              </label>
              <input
                type="number"
                value={studyHoursMin}
                onChange={(e) => setStudyHoursMin(e.target.value)}
                placeholder="e.g. 40"
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-600">
                Study Hours (Max)
              </label>
              <input
                type="number"
                value={studyHoursMax}
                onChange={(e) => setStudyHoursMax(e.target.value)}
                placeholder="e.g. 60"
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
          </div>
          <div>
            <label className="mb-1 block text-xs font-bold text-slate-600">
              Prerequisites (comma separated codes)
            </label>
            <input
              type="text"
              value={prerequisites}
              onChange={(e) => setPrerequisites(e.target.value)}
              placeholder="e.g. M1, M2"
              className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
          <div>
            <label className="mb-2 block text-xs font-bold text-slate-600">
              Applicable Licence Categories
            </label>
            <div className="flex flex-wrap gap-2">
              {LICENCE_CATEGORIES.map((cat) => (
                <button
                  key={cat}
                  type="button"
                  onClick={() => toggleCategory(cat)}
                  className={`rounded-lg border px-3 py-1.5 text-xs font-bold transition-colors ${
                    applicableCategories.includes(cat)
                      ? 'border-aerojet-blue bg-aerojet-blue text-white'
                      : 'border-slate-200 text-slate-500 hover:border-slate-300 dark:border-slate-700 dark:text-slate-400'
                  }`}
                >
                  Cat {cat}
                </button>
              ))}
            </div>
          </div>
          {error && <p className="text-sm text-red-600">{error}</p>}
        </div>
        <div className="mt-4 flex justify-end gap-3">
          <Button variant="outline" onClick={() => setOpen(false)} disabled={loading}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={loading}>
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Save Changes'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { Plus, Loader2, Trash2, FileText, CheckSquare, Pencil, ChevronDown, ChevronRight, ClipboardList } from 'lucide-react'

interface ExamComponentData {
  id: string
  code: string
  name: string
  type: string
  duration: number
  questionCount: number | null
  categoryCode: string | null
  individualPrice: string | number | null
  poolPrice: string | number | null
  _count: { exams: number; bookings: number }
}

export default function ExamComponentsSection({
  courseId,
  currency = 'EUR',
  components,
}: {
  courseId: string
  currency?: string
  components: ExamComponentData[]
}) {
  const getSymbol = () => {
    switch (currency) {
      case 'EUR':
        return '€'
      case 'GHS':
        return 'GH₵'
      case 'USD':
        return '$'
      default:
        return '€'
    }
  }
  const symbol = getSymbol()
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [deleting, setDeleting] = useState<string | null>(null)
  const [error, setError] = useState('')
  const [editingId, setEditingId] = useState<string | null>(null)
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())

  // Form state
  const [code, setCode] = useState('')
  const [name, setName] = useState('')
  const [type, setType] = useState<'MCQ' | 'ESSAY'>('MCQ')
  const [duration, setDuration] = useState('90')
  const [individualPrice, setIndividualPrice] = useState('520')
  const [poolPrice, setPoolPrice] = useState('300')
  const [questionCount, setQuestionCount] = useState('')
  const [categoryCode, setCategoryCode] = useState('')

  const useGrouped = components.length > 8

  const grouped = useMemo(() => {
    if (!useGrouped) return null
    const groups: Record<string, ExamComponentData[]> = {}
    for (const comp of components) {
      const key = comp.categoryCode || 'Uncategorized'
      if (!groups[key]) groups[key] = []
      groups[key].push(comp)
    }
    // Sort keys: A, B1, B2, B3, then Uncategorized
    const order = ['A', 'B1', 'B2', 'B3', 'Uncategorized']
    return Object.entries(groups).sort(
      ([a], [b]) => (order.indexOf(a) === -1 ? 99 : order.indexOf(a)) - (order.indexOf(b) === -1 ? 99 : order.indexOf(b))
    )
  }, [components, useGrouped])

  const toggleGroup = (key: string) => {
    setCollapsedGroups((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }

  const resetForm = () => {
    setCode('')
    setName('')
    setType('MCQ')
    setDuration('90')
    setIndividualPrice('520')
    setPoolPrice('300')
    setQuestionCount('')
    setCategoryCode('')
    setError('')
    setEditingId(null)
  }

  const openEdit = (comp: ExamComponentData) => {
    setEditingId(comp.id)
    setCode(comp.code)
    setName(comp.name)
    setType(comp.type as 'MCQ' | 'ESSAY')
    setDuration(String(comp.duration))
    setIndividualPrice(String(comp.individualPrice))
    setPoolPrice(String(comp.poolPrice))
    setQuestionCount(comp.questionCount ? String(comp.questionCount) : '')
    setCategoryCode(comp.categoryCode || '')
    setOpen(true)
  }

  const handleSave = async () => {
    if (!code || !name) {
      setError('Code and name are required')
      return
    }
    setLoading(true)
    setError('')
    try {
      const isEditing = !!editingId
      const url = isEditing
        ? `/api/staff/courses/${courseId}/exam-components/${editingId}`
        : `/api/staff/courses/${courseId}/exam-components`
      const method = isEditing ? 'PATCH' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, name, type, duration, individualPrice, poolPrice, questionCount: questionCount || undefined, categoryCode: categoryCode || undefined }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(data.error || 'Failed to save')
      setOpen(false)
      resetForm()
      router.refresh()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (componentId: string, hasRelated = false) => {
    const comp = components.find((c) => c.id === componentId)
    const msg = hasRelated
      ? `This component has ${comp?._count.exams || 0} exam(s) and ${comp?._count.bookings || 0} booking(s). Force-deleting will remove all related records. Continue?`
      : 'Delete this exam component? This cannot be undone.'
    if (!confirm(msg)) return
    setDeleting(componentId)
    try {
      const url = hasRelated
        ? `/api/staff/courses/${courseId}/exam-components/${componentId}?force=true`
        : `/api/staff/courses/${courseId}/exam-components/${componentId}`
      const res = await fetch(url, { method: 'DELETE' })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(data.error || 'Failed to delete')
      router.refresh()
    } catch (err: any) {
      alert(err.message)
    } finally {
      setDeleting(null)
    }
  }

  const renderCard = (comp: ExamComponentData) => (
    <div
      key={comp.id}
      className="flex items-center justify-between rounded-xl border border-slate-100 bg-slate-50 p-4 dark:border-slate-800 dark:bg-slate-800/50"
    >
      <div className="flex items-center gap-3">
        {comp.type === 'MCQ' ? (
          <CheckSquare className="h-5 w-5 text-blue-500" />
        ) : (
          <FileText className="h-5 w-5 text-purple-500" />
        )}
        <div>
          <p className="font-bold text-slate-700 dark:text-slate-200">
            <span className="mr-2 font-mono text-xs text-slate-400">{comp.code}</span>
            {comp.name}
          </p>
          <p className="text-xs text-slate-500">
            {comp.type}
            {comp.questionCount ? ` · ${comp.questionCount} questions` : ''}
            {' · '}{comp.duration}min
            {comp.categoryCode ? ` · Cat ${comp.categoryCode}` : ''}
            {' · '}{comp._count.exams} exam{comp._count.exams !== 1 ? 's' : ''}
            {' · '}{comp._count.bookings} booking{comp._count.bookings !== 1 ? 's' : ''}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-2">
        <button
          onClick={() => openEdit(comp)}
          className="rounded p-1 text-slate-400 transition-colors hover:text-blue-500"
          title="Edit"
        >
          <Pencil className="h-4 w-4" />
        </button>
        <span className="text-xs text-slate-500">
          {symbol}
          {Number(comp.individualPrice || 0).toFixed(0)} / {symbol}
          {Number(comp.poolPrice || 0).toFixed(0)}
        </span>
        <button
          onClick={() => handleDelete(comp.id, comp._count.exams > 0 || comp._count.bookings > 0)}
          disabled={deleting === comp.id}
          className="rounded p-1 text-slate-400 transition-colors hover:text-red-500 disabled:cursor-not-allowed disabled:opacity-30"
          title={
            comp._count.exams > 0 || comp._count.bookings > 0
              ? 'Force-delete: has exams or bookings'
              : 'Delete'
          }
        >
          {deleting === comp.id ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Trash2 className="h-4 w-4" />
          )}
        </button>
      </div>
    </div>
  )

  return (
    <div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
      <div className="mb-4 flex items-center justify-between">
        <h2 className="text-xs font-black tracking-widest text-slate-400 uppercase">
          Exam Components
          {components.length > 0 && (
            <span className="ml-2 text-slate-300">({components.length})</span>
          )}
        </h2>
        <Dialog
          open={open}
          onOpenChange={(o) => {
            setOpen(o)
            if (!o) resetForm()
          }}
        >
          <DialogTrigger asChild>
            <Button size="sm" variant="outline" className="gap-1 text-xs">
              <Plus className="h-3 w-3" /> Add Component
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[440px]">
            <DialogHeader>
              <DialogTitle>
                {editingId ? 'Edit Exam Component' : 'Add Exam Component'}
              </DialogTitle>
            </DialogHeader>
            <div className="mt-4 space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">Code</label>
                  <input
                    value={code}
                    onChange={(e) => setCode(e.target.value)}
                    placeholder="M7_MCQ"
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">Type</label>
                  <select
                    value={type}
                    onChange={(e) => setType(e.target.value as 'MCQ' | 'ESSAY')}
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  >
                    <option value="MCQ">MCQ</option>
                    <option value="ESSAY">Essay</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="mb-1 block text-xs font-bold text-slate-600">Name</label>
                <input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Module 7 MCQ Exam"
                  className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">Questions</label>
                  <input
                    type="number"
                    value={questionCount}
                    onChange={(e) => setQuestionCount(e.target.value)}
                    placeholder="e.g. 32"
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">Category</label>
                  <select
                    value={categoryCode}
                    onChange={(e) => setCategoryCode(e.target.value)}
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  >
                    <option value="">— None —</option>
                    <option value="A">Cat A</option>
                    <option value="B1">Cat B1</option>
                    <option value="B2">Cat B2</option>
                    <option value="B3">Cat B3</option>
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">
                    Duration (min)
                  </label>
                  <input
                    type="number"
                    value={duration}
                    onChange={(e) => setDuration(e.target.value)}
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">Individual</label>
                  <input
                    type="number"
                    value={individualPrice}
                    onChange={(e) => setIndividualPrice(e.target.value)}
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-bold text-slate-600">Pool</label>
                  <input
                    type="number"
                    value={poolPrice}
                    onChange={(e) => setPoolPrice(e.target.value)}
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
              </div>
              {error && <p className="text-sm text-red-600">{error}</p>}
            </div>
            <div className="mt-4 flex justify-end gap-3">
              <Button
                variant="outline"
                onClick={() => {
                  setOpen(false)
                  resetForm()
                }}
                disabled={loading}
              >
                Cancel
              </Button>
              <Button onClick={handleSave} disabled={loading}>
                {loading ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : editingId ? (
                  'Save Changes'
                ) : (
                  'Create'
                )}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      <div className="space-y-3">
        {components.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-slate-50 dark:bg-slate-800/50">
              <ClipboardList className="h-6 w-6 text-slate-300" />
            </div>
            <p className="text-sm font-bold text-slate-500">No exam components</p>
            <p className="mt-1 text-xs text-slate-400">
              Add exam components to configure assessments for this course.
            </p>
          </div>
        ) : useGrouped && grouped ? (
          // Grouped by category
          <div className="space-y-4">
            {grouped.map(([groupKey, items]) => {
              const isCollapsed = collapsedGroups.has(groupKey)
              return (
                <div key={groupKey}>
                  <button
                    onClick={() => toggleGroup(groupKey)}
                    className="mb-2 flex w-full items-center gap-2 text-left"
                  >
                    {isCollapsed ? (
                      <ChevronRight className="h-3.5 w-3.5 text-slate-400" />
                    ) : (
                      <ChevronDown className="h-3.5 w-3.5 text-slate-400" />
                    )}
                    <span className="text-xs font-black tracking-wider text-slate-500 uppercase">
                      {groupKey === 'Uncategorized' ? 'Uncategorized' : `Cat ${groupKey}`}
                    </span>
                    <span className="text-[10px] text-slate-400">({items.length})</span>
                  </button>
                  {!isCollapsed && (
                    <div className="space-y-2 pl-5">{items.map(renderCard)}</div>
                  )}
                </div>
              )
            })}
          </div>
        ) : (
          // Flat list for small counts
          components.map(renderCard)
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import Link from 'next/link'
import {
  Plus,
  BookOpen,
  ChevronDown,
  ChevronRight,
  Pin,
  PinOff,
  Search,
  SlidersHorizontal,
  Layers,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
} from 'lucide-react'
import { DbCourse, DbCourseCategory } from '@/types/database'
import { compareNatural } from '@/lib/utils/natural-sort'
import CourseActionsMenu from '../../_components/CourseActionsMenu'

interface Props {
  categories: DbCourseCategory[]
}

// EASA category IDs/names that should be pinned on top by default.
// We detect EASA by checking if the name contains "EASA" or "MODULE".
function isEasaCategory(cat: DbCourseCategory) {
  const n = cat.name.toUpperCase()
  return n.includes('EASA') || n.includes('MODULE')
}

const STORAGE_KEY_PINNED = 'aerojet_courses_pinned'
const STORAGE_KEY_COLLAPSED = 'aerojet_courses_collapsed'

function readSet(key: string): Set<string> | null {
  if (typeof window === 'undefined') return null
  try {
    const val = sessionStorage.getItem(key)
    return val ? new Set(JSON.parse(val)) : null
  } catch { return null }
}

function writeSet(key: string, set: Set<string>) {
  if (typeof window === 'undefined') return
  sessionStorage.setItem(key, JSON.stringify([...set]))
}

export default function CoursesClient({ categories }: Props) {
  // Which category IDs are manually pinned on top
  const [pinnedIds, setPinnedIds] = useState<Set<string>>(() => {
    const stored = readSet(STORAGE_KEY_PINNED)
    if (stored && stored.size > 0) return stored
    const easaIds = categories.filter(isEasaCategory).map((c) => c.id)
    return new Set(easaIds)
  })

  // Which categories are collapsed — persisted across navigation
  const [collapsed, setCollapsed] = useState<Set<string>>(() => {
    return readSet(STORAGE_KEY_COLLAPSED) ?? new Set()
  })

  // Filters
  const [search, setSearch] = useState('')
  const [activeFilter, setActiveFilter] = useState<'all' | 'active' | 'inactive'>('all')
  const [categoryFilter, setCategoryFilter] = useState<string>('all')

  // Sorting
  const [sortKey, setSortKey] = useState<'code' | 'name' | 'price' | 'isActive'>('code')
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc')

  const toggleSort = (key: 'code' | 'name' | 'price' | 'isActive') => {
    if (sortKey === key) {
      setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'))
    } else {
      setSortKey(key)
      setSortDirection('asc')
    }
  }

  const togglePin = (id: string) => {
    setPinnedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      writeSet(STORAGE_KEY_PINNED, next)
      return next
    })
  }

  const toggleCollapse = (id: string) => {
    setCollapsed((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      writeSet(STORAGE_KEY_COLLAPSED, next)
      return next
    })
  }

  // Build the sorted category order: pinned first, then rest
  const orderedCategories = useMemo(() => {
    const pinned = categories.filter((c) => pinnedIds.has(c.id))
    const rest = categories.filter((c) => !pinnedIds.has(c.id))
    return [...pinned, ...rest]
  }, [categories, pinnedIds])

  // Filter and sort courses inside each category
  const filteredCategories = useMemo(() => {
    return orderedCategories
      .map((cat) => {
        const filtered = cat.courses.filter((course) => {
          const matchSearch =
            !search ||
            course.name.toLowerCase().includes(search.toLowerCase()) ||
            course.code.toLowerCase().includes(search.toLowerCase())
          const matchStatus =
            activeFilter === 'all' ||
            (activeFilter === 'active' && course.isActive) ||
            (activeFilter === 'inactive' && !course.isActive)
          return matchSearch && matchStatus
        })

        // Sort the filtered courses
        const sorted = [...filtered].sort((a, b) => {
          if (sortKey === 'price') {
            const valA = Number(a.price)
            const valB = Number(b.price)
            return sortDirection === 'asc' ? valA - valB : valB - valA
          }

          if (sortKey === 'isActive') {
            const valA = a.isActive ? 1 : 0
            const valB = b.isActive ? 1 : 0
            return sortDirection === 'asc' ? valA - valB : valB - valA
          }

          // Natural sort for strings (code, name)
          const valA = String(a[sortKey] || '')
          const valB = String(b[sortKey] || '')

          const result = compareNatural(valA, valB)
          return sortDirection === 'asc' ? result : -result
        })

        return { ...cat, courses: sorted }
      })
      .filter((cat) => categoryFilter === 'all' || cat.id === categoryFilter)
  }, [orderedCategories, search, activeFilter, categoryFilter, sortKey, sortDirection])

  const totalCourses = categories.reduce((s, c) => s + c._count.courses, 0)
  const pinnedCategories = categories.filter((c) => pinnedIds.has(c.id))

  return (
    <div className="mx-auto max-w-[1800px] space-y-6">
      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-3xl font-black tracking-tight text-aerojet-blue dark:text-white">
            Courses
          </h1>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            {categories.length} categories · {totalCourses} courses
          </p>
        </div>
        <div className="flex flex-wrap gap-3">
          <Link
            href="/staff/courses/categories"
            className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-bold text-aerojet-blue transition-all duration-150 ease-out hover:border-slate-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white dark:hover:border-slate-600"
          >
            <Layers className="h-4 w-4" />
            Manage Categories
          </Link>
          <Link
            href="/staff/courses/create"
            className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white transition-colors hover:bg-aerojet-blue/90"
          >
            <Plus className="h-4 w-4" />
            Create Course
          </Link>
        </div>
      </div>

      {/* ── Filter Bar ─────────────────────────────────────────────────────── */}
      <div className="flex flex-col gap-3 rounded-2xl border border-slate-100 bg-white p-4 shadow-sm sm:flex-row sm:items-center dark:border-slate-800 dark:bg-slate-900">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            id="course-search"
            name="search"
            type="text"
            placeholder="Search by code or name…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pr-4 pl-9 text-sm font-medium text-slate-700 placeholder-slate-400 outline-none focus:border-aerojet-sky focus:bg-white dark:border-slate-700 dark:bg-slate-800 dark:text-slate-200"
          />
        </div>

        {/* Category dropdown */}
        <div className="flex items-center gap-2">
          <SlidersHorizontal className="h-4 w-4 text-slate-400" />
          <select
            id="category-filter"
            name="category"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm font-medium text-slate-700 outline-none focus:border-aerojet-sky dark:border-slate-700 dark:bg-slate-800 dark:text-slate-200"
          >
            <option value="all">All Categories</option>
            {orderedCategories.map((cat) => (
              <option key={cat.id} value={cat.id}>
                {cat.name.replace(/_/g, ' ')} ({cat._count.courses})
              </option>
            ))}
          </select>
        </div>

        {/* Status filter */}
        <div className="flex items-center gap-1 rounded-xl border border-slate-100 bg-slate-50 p-1 dark:border-slate-700 dark:bg-slate-800">
          {(['all', 'active', 'inactive'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setActiveFilter(f)}
              className={`rounded-lg px-3 py-1 text-xs font-bold capitalize transition-all ${
                activeFilter === f
                  ? 'bg-aerojet-blue text-white shadow-sm'
                  : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      {/* ── Pinned chips summary ────────────────────────────────────────────── */}
      {pinnedCategories.length > 0 && (
        <div className="flex flex-wrap items-center gap-2">
          <Pin className="h-3.5 w-3.5 text-aerojet-sky" />
          <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">
            Pinned:
          </span>
          {pinnedCategories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => togglePin(cat.id)}
              className="group flex items-center gap-1.5 rounded-full bg-aerojet-blue/8 px-3 py-1 text-xs font-bold text-aerojet-blue transition-all hover:bg-red-50 hover:text-red-600 dark:bg-blue-900/20 dark:text-blue-300"
            >
              {cat.name.replace(/_/g, ' ')}
              <PinOff className="h-3 w-3 opacity-0 group-hover:opacity-100" />
            </button>
          ))}
        </div>
      )}

      {/* ── Category Accordions ─────────────────────────────────────────────── */}
      <div className="space-y-4">
        {filteredCategories.map((cat) => {
          const isPinned = pinnedIds.has(cat.id)
          const isCollapsed = collapsed.has(cat.id)
          const isEasa = isEasaCategory(cat)

          return (
            <div
              key={cat.id}
              className={`overflow-hidden rounded-2xl border shadow-sm transition-all ${
                isPinned
                  ? 'border-aerojet-sky/40 dark:border-aerojet-sky/20'
                  : 'border-slate-100 dark:border-slate-800'
              } bg-white dark:bg-slate-900`}
            >
              {/* Category header bar */}
              <div
                className={`flex items-center gap-3 px-5 py-4 ${
                  isPinned
                    ? 'bg-linear-to-r from-aerojet-blue/5 to-aerojet-sky/5 dark:from-blue-900/20 dark:to-blue-800/10'
                    : 'bg-slate-50 dark:bg-slate-800/50'
                } border-b border-slate-100 dark:border-slate-800`}
              >
                {/* Collapse toggle */}
                <button
                  onClick={() => toggleCollapse(cat.id)}
                  className="shrink-0 rounded-lg p-0.5 text-slate-400 hover:text-slate-700 dark:hover:text-white"
                  title={isCollapsed ? 'Expand' : 'Collapse'}
                >
                  {isCollapsed ? (
                    <ChevronRight className="h-4 w-4" />
                  ) : (
                    <ChevronDown className="h-4 w-4" />
                  )}
                </button>

                {/* Name + badges */}
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <button
                      onClick={() => toggleCollapse(cat.id)}
                      className="text-left text-base font-black text-aerojet-blue hover:text-aerojet-sky dark:text-white"
                    >
                      {cat.name.replace(/_/g, ' ')}
                    </button>

                    {isEasa && (
                      <span className="rounded-full bg-blue-100 px-2 py-0.5 text-[10px] font-black tracking-widest text-aerojet-blue uppercase dark:bg-blue-900/30 dark:text-blue-300">
                        EASA
                      </span>
                    )}
                    {isPinned && (
                      <span className="rounded-full bg-amber-100 px-2 py-0.5 text-[10px] font-black tracking-widest text-amber-700 uppercase dark:bg-amber-900/30 dark:text-amber-300">
                        Pinned
                      </span>
                    )}
                    <span className="text-xs text-slate-400">
                      ({cat.courses.length}
                      {cat.courses.length !== cat._count.courses
                        ? ` of ${cat._count.courses}`
                        : ''}{' '}
                      {cat._count.courses === 1 ? 'course' : 'courses'})
                    </span>
                  </div>
                  {cat.description && (
                    <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">
                      {cat.description}
                    </p>
                  )}
                </div>

                {/* Pin toggle */}
                <button
                  onClick={() => togglePin(cat.id)}
                  title={isPinned ? 'Unpin category' : 'Pin to top'}
                  className={`shrink-0 rounded-lg p-1.5 transition-colors ${
                    isPinned
                      ? 'text-aerojet-sky hover:text-slate-400'
                      : 'text-slate-300 hover:text-aerojet-sky dark:text-slate-600'
                  }`}
                >
                  {isPinned ? <PinOff className="h-4 w-4" /> : <Pin className="h-4 w-4" />}
                </button>
              </div>

              {/* Courses table — hidden when collapsed */}
              {!isCollapsed && (
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead className="bg-slate-50/50 text-[10px] font-bold text-slate-400 uppercase dark:bg-slate-800/20 dark:text-slate-500">
                      <tr>
                        <th
                          className="cursor-pointer px-6 py-3 select-none hover:text-slate-600 dark:hover:text-slate-300"
                          onClick={() => toggleSort('code')}
                        >
                          <div className="flex items-center gap-1.5">
                            Code
                            {sortKey === 'code' ? (
                              sortDirection === 'asc' ? (
                                <ArrowUp className="h-3 w-3" />
                              ) : (
                                <ArrowDown className="h-3 w-3" />
                              )
                            ) : (
                              <ArrowUpDown className="h-3 w-3 opacity-30" />
                            )}
                          </div>
                        </th>
                        <th
                          className="cursor-pointer px-6 py-3 select-none hover:text-slate-600 dark:hover:text-slate-300"
                          onClick={() => toggleSort('name')}
                        >
                          <div className="flex items-center gap-1.5">
                            Course Name
                            {sortKey === 'name' ? (
                              sortDirection === 'asc' ? (
                                <ArrowUp className="h-3 w-3" />
                              ) : (
                                <ArrowDown className="h-3 w-3" />
                              )
                            ) : (
                              <ArrowUpDown className="h-3 w-3 opacity-30" />
                            )}
                          </div>
                        </th>
                        <th className="px-6 py-3">License / Pathway</th>
                        <th
                          className="cursor-pointer px-6 py-3 select-none hover:text-slate-600 dark:hover:text-slate-300"
                          onClick={() => toggleSort('isActive')}
                        >
                          <div className="flex items-center gap-1.5">
                            Status
                            {sortKey === 'isActive' ? (
                              sortDirection === 'asc' ? (
                                <ArrowUp className="h-3 w-3" />
                              ) : (
                                <ArrowDown className="h-3 w-3" />
                              )
                            ) : (
                              <ArrowUpDown className="h-3 w-3 opacity-30" />
                            )}
                          </div>
                        </th>
                        <th
                          className="cursor-pointer px-6 py-3 text-right select-none hover:text-slate-600 dark:hover:text-slate-300"
                          onClick={() => toggleSort('price')}
                        >
                          <div className="flex items-center justify-end gap-1.5">
                            Price
                            {sortKey === 'price' ? (
                              sortDirection === 'asc' ? (
                                <ArrowUp className="h-3 w-3" />
                              ) : (
                                <ArrowDown className="h-3 w-3" />
                              )
                            ) : (
                              <ArrowUpDown className="h-3 w-3 opacity-30" />
                            )}
                          </div>
                        </th>
                        <th className="px-6 py-3 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                      {cat.courses.length === 0 ? (
                        <tr>
                          <td
                            colSpan={5}
                            className="px-6 py-8 text-center text-sm text-slate-400 italic"
                          >
                            {search || activeFilter !== 'all'
                              ? 'No courses match your filters.'
                              : 'No courses in this category.'}
                          </td>
                        </tr>
                      ) : (
                        cat.courses.map((course) => (
                          <tr
                            key={course.id}
                            className="group transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/60"
                          >
                            {/* Code */}
                            <td className="px-6 py-4 font-mono text-sm font-bold text-slate-500 dark:text-slate-400">
                              {course.code}
                            </td>

                            {/* Name */}
                            <td className="px-6 py-4">
                              <div className="flex items-center gap-3">
                                <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400">
                                  <BookOpen className="h-4 w-4" />
                                </div>
                                <div>
                                  <Link
                                    href={`/staff/courses/${course.code}`}
                                    className="font-bold text-slate-900 hover:text-aerojet-sky dark:text-slate-100"
                                  >
                                    {course.name}
                                  </Link>
                                  {course.subtitle && (
                                    <p className="text-xs text-slate-400 dark:text-slate-500">
                                      {course.subtitle}
                                    </p>
                                  )}
                                </div>
                              </div>
                            </td>

                            {/* License / Pathway */}
                            <td className="px-6 py-4">
                              <div className="flex flex-wrap gap-1.5">
                                {course.moduleType && (
                                  <span className="rounded-md bg-amber-50 px-2 py-0.5 text-xs font-bold text-amber-700 ring-1 ring-amber-600/20 ring-inset dark:bg-amber-900/20 dark:text-amber-400">
                                    {course.moduleType.replace(/_/g, ' ')}
                                  </span>
                                )}
                                {course.applicableCategories?.map((cat) => (
                                  <span
                                    key={cat}
                                    className="rounded-md bg-blue-50 px-1.5 py-0.5 text-[10px] font-bold text-blue-600 dark:bg-blue-900/20 dark:text-blue-400"
                                  >
                                    {cat}
                                  </span>
                                ))}
                              </div>
                            </td>

                            {/* Status */}
                            <td className="px-6 py-4">
                              <span
                                className={`rounded-full px-2.5 py-1 text-[10px] font-black tracking-wide uppercase ${
                                  course.isActive
                                    ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400'
                                    : 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400'
                                }`}
                              >
                                {course.isActive ? 'Active' : 'Inactive'}
                              </span>
                            </td>

                            {/* Price */}
                            <td className="px-6 py-4 text-right font-bold text-slate-700 dark:text-slate-300">
                              {course.currency} {Number(course.price).toLocaleString()}
                            </td>

                            {/* Actions */}
                            <td className="px-6 py-4 text-right">
                              <CourseActionsMenu courseId={course.id} courseCode={course.code} courseName={course.name} />
                            </td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )
        })}

        {filteredCategories.length === 0 && (
          <div className="rounded-2xl border border-dashed border-slate-200 p-12 text-center text-slate-400 dark:border-slate-800">
            No categories match the current filter.
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { Plus, Loader2, Trash2, ArrowLeft, Pencil, BookOpen, MoreHorizontal } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { toast } from '@/hooks/use-toast'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'

import { DbCourseCategory } from '@/types/database'

export default function CourseCategoriesPage() {
  const [categories, setCategories] = useState<DbCourseCategory[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Create state
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [newName, setNewName] = useState('')
  const [newDescription, setNewDescription] = useState('')

  // Edit state
  const [editTarget, setEditTarget] = useState<DbCourseCategory | null>(null)
  const [editName, setEditName] = useState('')
  const [editDescription, setEditDescription] = useState('')

  // Delete state
  const [deleteTarget, setDeleteTarget] = useState<DbCourseCategory | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const fetchCategories = async () => {
    setIsLoading(true)
    try {
      const response = await fetch('/api/staff/course-categories')
      const data = await response.json()
      if (data.success) {
        setCategories(data.data)
      }
    } catch {
      toast.error('Failed to fetch categories')
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchCategories()
  }, [])

  // â”€â”€ CREATE â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!newName) return

    setIsSubmitting(true)
    try {
      const res = await fetch('/api/staff/course-categories/create', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newName, description: newDescription }),
      })
      const data = await res.json()
      if (data.success) {
        toast.success('Category created')
        setNewName('')
        setNewDescription('')
        setIsCreateOpen(false)
        fetchCategories()
      } else {
        toast.error(data.error || 'Failed to create category')
      }
    } catch {
      toast.error('Failed to create category')
    } finally {
      setIsSubmitting(false)
    }
  }

  // â”€â”€ EDIT â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const openEdit = (cat: DbCourseCategory) => {
    setEditTarget(cat)
    setEditName(cat.name.replace(/_/g, ' '))
    setEditDescription(cat.description ?? '')
  }

  const handleEdit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!editTarget) return

    setIsSubmitting(true)
    try {
      const res = await fetch(`/api/staff/course-categories/${editTarget.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName, description: editDescription }),
      })
      const data = await res.json()
      if (data.success) {
        toast.success('Category updated')
        setEditTarget(null)
        fetchCategories()
      } else {
        toast.error(data.error || 'Failed to update category')
      }
    } catch {
      toast.error('Failed to update category')
    } finally {
      setIsSubmitting(false)
    }
  }

  // â”€â”€ DELETE â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const handleDelete = async () => {
    if (!deleteTarget) return

    setIsDeleting(true)
    try {
      const res = await fetch(`/api/staff/course-categories/${deleteTarget.id}`, {
        method: 'DELETE',
      })
      const data = await res.json()
      if (data.success) {
        toast.success('Category deleted')
        setDeleteTarget(null)
        fetchCategories()
      } else {
        toast.error(data.error || 'Failed to delete category')
      }
    } catch {
      toast.error('Failed to delete category')
    } finally {
      setIsDeleting(false)
    }
  }

  // â”€â”€ RENDER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  return (
    <div className="mx-auto max-w-[1800px]">
      {/* Header */}
      <div className="mb-8 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link
            href="/staff/courses"
            className="rounded-full p-2 hover:bg-slate-100 dark:hover:bg-slate-800"
          >
            <ArrowLeft className="h-5 w-5 text-slate-500" />
          </Link>
          <div>
            <h1 className="text-3xl font-black tracking-tight text-aerojet-blue dark:text-white">
              Course Categories
            </h1>
            <p className="text-slate-500 dark:text-slate-400">
              {categories.length} {categories.length === 1 ? 'category' : 'categories'} â€¢{' '}
              {categories.reduce((sum, c) => sum + (c._count?.courses ?? 0), 0)} courses total
            </p>
          </div>
        </div>

        {/* Create dialog trigger */}
        <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
          <DialogTrigger asChild>
            <Button className="bg-aerojet-blue hover:bg-aerojet-blue/90">
              <Plus className="mr-2 h-4 w-4" />
              Add Category
            </Button>
          </DialogTrigger>
          <DialogContent>
            <form onSubmit={handleCreate}>
              <DialogHeader>
                <DialogTitle>Create Course Category</DialogTitle>
                <DialogDescription>Define a new category for grouping courses.</DialogDescription>
              </DialogHeader>
              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium">Name</label>
                  <Input
                    placeholder="e.g. EASA MODULE"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    required
                  />
                  <p className="text-[10px] text-slate-500 italic">
                    Will be saved as UPPERCASE_WITH_UNDERSCORES
                  </p>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">Description</label>
                  <Textarea
                    placeholder="Brief description of this category..."
                    value={newDescription}
                    onChange={(e) => setNewDescription(e.target.value)}
                  />
                </div>
              </div>
              <DialogFooter>
                <Button type="button" variant="outline" onClick={() => setIsCreateOpen(false)}>
                  Cancel
                </Button>
                <Button type="submit" disabled={isSubmitting} className="bg-aerojet-blue">
                  {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Create'}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {/* Category grid */}
      <div className="grid grid-cols-1 gap-5 md:grid-cols-2 lg:grid-cols-3">
        {isLoading ? (
          <div className="col-span-full flex justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-slate-300" />
          </div>
        ) : categories.length === 0 ? (
          <div className="col-span-full rounded-2xl border border-dashed border-slate-200 p-12 text-center text-slate-500 dark:border-slate-800">
            No categories yet. Create your first one.
          </div>
        ) : (
          categories.map((cat) => (
            <div
              key={cat.id}
              className="group relative flex flex-col overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm transition-all hover:shadow-md dark:border-slate-800 dark:bg-slate-900"
            >
              {/* Accent stripe */}
              <div className="h-1 w-full bg-linear-to-r from-aerojet-blue to-aerojet-sky" />

              <div className="flex flex-1 flex-col p-6">
                {/* Top row: name + actions */}
                <div className="mb-3 flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <h3 className="truncate font-black text-aerojet-blue dark:text-white">
                      {cat.name.replace(/_/g, ' ')}
                    </h3>
                    <code className="font-mono text-[10px] text-slate-400">{cat.id}</code>
                  </div>

                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <button className="rounded-lg p-1.5 opacity-0 transition-opacity group-hover:opacity-100 hover:bg-slate-100 dark:hover:bg-slate-800">
                        <MoreHorizontal className="h-4 w-4 text-slate-500" />
                      </button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-40">
                      <DropdownMenuItem onClick={() => openEdit(cat)}>
                        <Pencil className="mr-2 h-4 w-4" />
                        Edit
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        className="text-red-600 focus:text-red-600"
                        onClick={() => setDeleteTarget(cat)}
                      >
                        <Trash2 className="mr-2 h-4 w-4" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>

                {/* Description */}
                <p className="mb-4 line-clamp-2 flex-1 text-sm text-slate-500 dark:text-slate-400">
                  {cat.description || 'No description provided.'}
                </p>

                {/* Footer: course count + link */}
                <div className="flex items-center justify-between border-t border-slate-50 pt-4 dark:border-slate-800">
                  <div className="flex items-center gap-2">
                    <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-blue-50 dark:bg-blue-900/20">
                      <BookOpen className="h-3.5 w-3.5 text-aerojet-sky" />
                    </div>
                    <span className="text-sm font-black text-slate-700 dark:text-slate-300">
                      {cat._count?.courses ?? 0}
                    </span>
                    <span className="text-xs text-slate-400">
                      {cat._count?.courses === 1 ? 'course' : 'courses'}
                    </span>
                  </div>
                  <Link
                    href={`/staff/courses?category=${cat.id}`}
                    className="inline-flex items-center rounded-md px-1.5 py-0.5 text-xs font-bold text-aerojet-sky transition-all duration-150 ease-out hover:bg-aerojet-sky/10 hover:shadow-sm"
                  >
                    View courses â†’
                  </Link>
                </div>
              </div>
            </div>
          ))
        )}
