    setSelectedStudentIds((prev) => {
      const next = new Set(prev)
      next.has(id) ? next.delete(id) : next.add(id)
      return next
    })
  }

  const toggleCourse = (id: string) => {
    setSelectedCourseIds((prev) => {
      const next = new Set(prev)
      next.has(id) ? next.delete(id) : next.add(id)
      return next
    })
  }

  const selectAllStudents = () => {
    if (selectedStudentIds.size === students.length) {
      setSelectedStudentIds(new Set())
    } else {
      setSelectedStudentIds(new Set(students.map((s) => s.id)))
    }
  }

  const selectAllEasaModules = () => {
    const easaIds = new Set(easaModules.map((c) => c.id))
    const allSelected = easaModules.every((c) => selectedCourseIds.has(c.id))
    setSelectedCourseIds((prev) => {
      const next = new Set(prev)
      if (allSelected) {
        easaIds.forEach((id) => next.delete(id))
      } else {
        easaIds.forEach((id) => next.add(id))
      }
      return next
    })
  }

  const handleSubmit = async () => {
    if (selectedStudentIds.size === 0 || selectedCourseIds.size === 0) {
      setError('Please select at least one student and one course.')
      return
    }

    setLoading(true)
    setError('')
    setResult(null)

    try {
      const res = await fetch('/api/staff/enrollments/batch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          studentIds: Array.from(selectedStudentIds),
          courseIds: Array.from(selectedCourseIds),
          academicYearId: selectedYearId || undefined,
          semesterId: selectedSemesterId || undefined,
        }),
      })

      const data = await res.json()

      if (!res.ok) {
        setError(data.error || 'Something went wrong.')
        return
      }

      setResult({ created: data.created, skipped: data.skipped })
    } catch (err) {
      setError('Network error. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Academic Period Selector */}
      <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm sm:p-6 dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-4 flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400">
            <Calendar className="h-5 w-5" />
          </div>
          <div>
            <h2 className="font-bold text-slate-900 dark:text-slate-100">Academic Period</h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">
              Optional — link enrollments to a specific semester
            </p>
          </div>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <div>
            <label
              htmlFor="batch-academic-year"
              className="mb-1 block text-xs font-bold text-slate-500 uppercase dark:text-slate-400"
            >
              Academic Year
            </label>
            <select
              id="batch-academic-year"
              name="batch-academic-year"
              value={selectedYearId}
              onChange={(e) => {
                setSelectedYearId(e.target.value)
                setSelectedSemesterId('')
              }}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium text-slate-900 transition-colors focus:border-blue-500 focus:ring-1 focus:ring-blue-500 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
              autoComplete="off"
            >
              <option value="">All / None</option>
              {academicYears.map((y) => (
                <option key={y.id} value={y.id}>
                  {y.name}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label
              htmlFor="batch-semester"
              className="mb-1 block text-xs font-bold text-slate-500 uppercase dark:text-slate-400"
            >
              Semester
            </label>
            <select
              id="batch-semester"
              name="batch-semester"
              value={selectedSemesterId}
              onChange={(e) => setSelectedSemesterId(e.target.value)}
              disabled={!selectedYearId}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium text-slate-900 transition-colors focus:border-blue-500 focus:ring-1 focus:ring-blue-500 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
              autoComplete="off"
            >
              <option value="">All / None</option>
              {semesters.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        {/* Students Selector */}
        <div className="rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="flex items-center justify-between border-b border-slate-100 p-4 sm:p-5 dark:border-slate-800">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400">
                <Users className="h-5 w-5" />
              </div>
              <div>
                <h2 className="font-bold text-slate-900 dark:text-slate-100">Full-Time Students</h2>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  {selectedStudentIds.size} of {students.length} selected
                </p>
              </div>
            </div>
            <button
              onClick={selectAllStudents}
              className="rounded-lg bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-600 transition-colors hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300"
            >
              {selectedStudentIds.size === students.length ? 'Deselect All' : 'Select All'}
            </button>
          </div>
          <div className="max-h-[400px] overflow-y-auto p-3 sm:p-4">
            {students.length === 0 ? (
              <p className="py-6 text-center text-sm text-slate-500 dark:text-slate-400">
                No full-time students found.
              </p>
            ) : (
              <div className="space-y-1.5">
                {students.map((student) => {
                  const isSelected = selectedStudentIds.has(student.id)
                  return (
                    <button
                      key={student.id}
                      id={`select-student-${student.id}`}
                      name={`select-student-${student.id}`}
                      role="checkbox"
                      aria-checked={isSelected}
                      aria-label={`Select student ${student.name}`}
                      onClick={() => toggleStudent(student.id)}
                      className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-all ${
                        isSelected
                          ? 'bg-emerald-50 ring-1 ring-emerald-200 dark:bg-emerald-900/20 dark:ring-emerald-800'
                          : 'hover:bg-white/80 dark:hover:bg-slate-800/40'
                      }`}
                    >
                      <div
                        className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition-colors ${
                          isSelected
                            ? 'bg-emerald-600 text-white'
                            : 'border border-slate-300 dark:border-slate-600'
                        }`}
                      >
                        {isSelected && <Check className="h-3 w-3" />}
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-semibold text-slate-900 dark:text-slate-100">
                          {student.name}
                        </p>
                        <p className="text-[10px] text-slate-500 dark:text-slate-400">
                          {student.studentId} • {student.email}
                        </p>
                      </div>
                    </button>
                  )
                })}
              </div>
            )}
          </div>
        </div>

        {/* Courses Selector */}
        <div className="rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="flex items-center justify-between border-b border-slate-100 p-4 sm:p-5 dark:border-slate-800">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400">
                <BookOpen className="h-5 w-5" />
              </div>
              <div>
                <h2 className="font-bold text-slate-900 dark:text-slate-100">Courses</h2>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  {selectedCourseIds.size} of {courses.length} selected
                </p>
              </div>
            </div>
            {easaModules.length > 0 && (
              <button
                onClick={selectAllEasaModules}
                className="rounded-lg bg-purple-100 px-3 py-1.5 text-xs font-bold text-purple-600 transition-colors hover:bg-purple-200 dark:bg-purple-900/30 dark:text-purple-300"
              >
                {easaModules.every((c) => selectedCourseIds.has(c.id))
                  ? 'Deselect EASA'
                  : 'Select All EASA'}
              </button>
            )}
          </div>
          <div className="max-h-[400px] overflow-y-auto p-3 sm:p-4">
            {/* EASA Modules */}
            {easaModules.length > 0 && (
              <div className="mb-4">
                <p className="mb-2 text-[10px] font-black tracking-widest text-slate-400 uppercase dark:text-slate-500">
                  EASA Part-66 Modules
                </p>
                <div className="space-y-1.5">
                  {easaModules.map((course) => {
                    const isSelected = selectedCourseIds.has(course.id)
                    return (
                      <button
                        key={course.id}
                        id={`select-course-${course.id}`}
                        name={`select-course-${course.id}`}
                        role="checkbox"
                        aria-checked={isSelected}
                        aria-label={`Select course ${course.code}`}
                        onClick={() => toggleCourse(course.id)}
                        className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-all ${
                          isSelected
                            ? 'bg-purple-50 ring-1 ring-purple-200 dark:bg-purple-900/20 dark:ring-purple-800'
                            : 'hover:bg-white/80 dark:hover:bg-slate-800/40'
                        }`}
                      >
                        <div
                          className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition-colors ${
                            isSelected
                              ? 'bg-purple-600 text-white'
                              : 'border border-slate-300 dark:border-slate-600'
                          }`}
                        >
                          {isSelected && <Check className="h-3 w-3" />}
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="truncate text-sm font-semibold text-slate-900 dark:text-slate-100">
                            {course.code}: {course.name}
                          </p>
                        </div>
                      </button>
                    )
                  })}
                </div>
              </div>
            )}

            {/* Other Courses */}
            {otherCourses.length > 0 && (
              <div>
                <p className="mb-2 text-[10px] font-black tracking-widest text-slate-400 uppercase dark:text-slate-500">
                  Other Courses
                </p>
                <div className="space-y-1.5">
                  {otherCourses.map((course) => {
                    const isSelected = selectedCourseIds.has(course.id)
                    return (
                      <button
                        key={course.id}
                        id={`select-course-${course.id}`}
                        name={`select-course-${course.id}`}
                        role="checkbox"
                        aria-checked={isSelected}
                        aria-label={`Select course ${course.code}`}
                        onClick={() => toggleCourse(course.id)}
                        className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-all ${
                          isSelected
                            ? 'bg-purple-50 ring-1 ring-purple-200 dark:bg-purple-900/20 dark:ring-purple-800'
                            : 'hover:bg-white/80 dark:hover:bg-slate-800/40'
                        }`}
                      >
                        <div
                          className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition-colors ${
                            isSelected
                              ? 'bg-purple-600 text-white'
                              : 'border border-slate-300 dark:border-slate-600'
                          }`}
                        >
                          {isSelected && <Check className="h-3 w-3" />}
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="truncate text-sm font-semibold text-slate-900 dark:text-slate-100">
                            {course.code}: {course.name}
                          </p>
                        </div>
                      </button>
                    )
                  })}
                </div>
              </div>
            )}

            {courses.length === 0 && (
              <p className="py-6 text-center text-sm text-slate-500 dark:text-slate-400">
                No active courses found.
              </p>
            )}
          </div>
        </div>
      </div>

      {/* Summary & Submit */}
      <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm sm:p-6 dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-4 flex flex-wrap items-center gap-3 text-sm">
          <span className="rounded-lg bg-emerald-50 px-3 py-1.5 font-bold text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-300">
            {selectedStudentIds.size} student{selectedStudentIds.size !== 1 ? 's' : ''}
          </span>
          <span className="text-slate-400">×</span>
          <span className="rounded-lg bg-purple-50 px-3 py-1.5 font-bold text-purple-700 dark:bg-purple-900/20 dark:text-purple-300">
            {selectedCourseIds.size} course{selectedCourseIds.size !== 1 ? 's' : ''}
          </span>
          <span className="text-slate-400">=</span>
          <span className="rounded-lg bg-blue-50 px-3 py-1.5 font-black text-blue-700 dark:bg-blue-900/20 dark:text-blue-300">
            {selectedStudentIds.size * selectedCourseIds.size} enrollment
            {selectedStudentIds.size * selectedCourseIds.size !== 1 ? 's' : ''}
          </span>
        </div>

        {error && (
          <div className="mb-4 flex items-center gap-2 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/10 dark:text-red-300">
            <AlertCircle className="h-4 w-4 shrink-0" />
            {error}
          </div>
        )}

        {result && (
          <div className="mb-4 flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700 dark:border-emerald-800 dark:bg-emerald-900/10 dark:text-emerald-300">
            <CheckCircle2 className="h-4 w-4 shrink-0" />
            <span>
              <strong>{result.created}</strong> enrollment{result.created !== 1 ? 's' : ''} created
              {result.skipped > 0 && (
                <>
                  {' '}
                  • <strong>{result.skipped}</strong> skipped (already enrolled)
                </>
              )}
            </span>
          </div>
        )}

        <button
          onClick={handleSubmit}
          disabled={loading || selectedStudentIds.size === 0 || selectedCourseIds.size === 0}
          className="flex w-full items-center justify-center gap-2 rounded-xl bg-aerojet-blue py-3 text-sm font-bold text-white transition-all hover:bg-[#003a7c] active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50 sm:w-auto sm:px-8"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Activating...
            </>
          ) : (
            <>
              <CheckCircle2 className="h-4 w-4" />
              Activate Courses
            </>
          )}
        </button>
      </div>
    </div>
  )
}

import { getAuthSession } from '@/lib/auth/helpers'
import { redirect } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { serializePrisma } from '@/lib/utils/serialization'
import EnrollmentsTable from './_components/EnrollmentsTable'
import SearchInput from '@/components/SearchInput'
import { Metadata } from 'next'
import { Prisma } from '@prisma/client'
import type { EnrollmentWithDetails } from './_components/EnrollmentsTable'
import { buildOrderBy } from '@/lib/utils/build-order-by'

export const metadata: Metadata = { title: 'Enrollments | Staff Portal' }

const ALLOWED_SORT_KEYS = {
  student: 'user.profile.lastName',
  course: 'course.name',
  status: 'status',
  enrolledAt: 'enrolledAt',
  amount: 'amountPaid',
} as const

type SortKey = keyof typeof ALLOWED_SORT_KEYS

export default async function EnrollmentsPage({
  searchParams,
}: {
  searchParams: Promise<{
    query?: string
    page?: string
    limit?: string
    sort?: string
    order?: string
  }>
}) {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const params = await searchParams
  const query = params.query?.trim() || undefined
  const page = Math.max(1, parseInt(params.page || '1', 10) || 1)
  const limit = Math.min(100, Math.max(1, parseInt(params.limit || '25', 10) || 25))
  const skip = (page - 1) * limit

  const where = query
    ? {
        OR: [
          {
            user: {
              OR: [
                { email: { contains: query, mode: 'insensitive' } },
                { profile: { firstName: { contains: query, mode: 'insensitive' } } },
                { profile: { lastName: { contains: query, mode: 'insensitive' } } },
              ],
            },
          },
          { course: { name: { contains: query, mode: 'insensitive' } } },
          { course: { code: { contains: query, mode: 'insensitive' } } },
        ],
      }
    : undefined

  const orderBy = buildOrderBy<SortKey>(params, ALLOWED_SORT_KEYS, { createdAt: 'desc' })

  const [enrollments, total] = await Promise.all([
    prismaUnfiltered.enrollment.findMany({
      where: where as unknown as Prisma.EnrollmentWhereInput,
      orderBy: orderBy as unknown as Prisma.EnrollmentOrderByWithRelationInput,
      include: {
        user: {
          include: {
            profile: true,
          },
        },
        course: true,
      },
      take: limit,
      skip,
    }),
    prismaUnfiltered.enrollment.count({ where: where as unknown as Prisma.EnrollmentWhereInput }),
  ])

  const serializedEnrollments = serializePrisma(enrollments) as unknown as EnrollmentWithDetails[]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-aerojet-blue text-3xl font-black tracking-tight dark:text-white">
            Enrollments
          </h1>
          <p className="text-slate-500 dark:text-slate-400">Manage student course enrollments</p>
        </div>
        <div className="w-72">
          <SearchInput id="enrollments-search" placeholder="Search student or course..." />
        </div>
      </div>

      <EnrollmentsTable enrollments={serializedEnrollments} />
    </div>
  )
}

"use client";
export default function StaffError({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div className="flex items-center justify-center min-h-[60vh]" role="alert">
      <div className="text-center max-w-md">
        <h2 className="text-xl font-black text-slate-900 dark:text-slate-100 mb-2">Something went wrong</h2>
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">An unexpected error occurred. Please try again or contact support if the problem persists.</p>
        <button onClick={reset} className="bg-aerojet-blue text-white px-6 py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-aerojet-sky transition-colors focus:outline-none focus:ring-2 focus:ring-aerojet-blue/50">
          Try Again
        </button>
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { Users, Loader2, CheckCircle, X, Building2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { useRouter } from 'next/navigation'

interface Event {
  id: string
  name: string
}

interface Module {
  id: string
  code: string
  name: string
}

interface GroupCharterModalProps {
  events: Event[]
  modules: Module[]
}

export function GroupCharterModal({ events, modules }: GroupCharterModalProps) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)

  const [repUserId, setRepUserId] = useState('')
  const [eventId, setEventId] = useState('')
  const [groupName, setGroupName] = useState('')
  const [memberCount, setMemberCount] = useState(1)
  const [selectedModules, setSelectedModules] = useState<string[]>([])

  const toggleModule = (id: string) => {
    setSelectedModules((prev) =>
      prev.includes(id) ? prev.filter((m) => m !== id) : [...prev, id]
    )
  }

  const handleSubmit = async () => {
    if (!repUserId || !eventId || !groupName.trim() || selectedModules.length === 0) {
      setError('All fields are required')
      return
    }

    setIsSubmitting(true)
    setError(null)

    try {
      const res = await fetch('/api/staff/exam-pools/charter', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          repUserId,
          eventId,
          groupName: groupName.trim(),
          memberCount,
          modules: selectedModules,
        }),
      })
      const data = await res.json()
      if (!res.ok) {
        setError(data.error || 'Failed to create group charter')
      } else {
        setSuccess(true)
        setTimeout(() => {
          setOpen(false)
          router.refresh()
        }, 1500)
      }
    } catch {
      setError('Network error')
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleClose = () => {
    setOpen(false)
    setRepUserId('')
    setEventId('')
    setGroupName('')
    setMemberCount(1)
    setSelectedModules([])
    setError(null)
    setSuccess(false)
  }

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) handleClose(); else setOpen(true) }}>
      <DialogTrigger asChild>
        <button className="flex items-center gap-2 rounded-xl border border-indigo-200 bg-indigo-50 px-4 py-2.5 text-sm font-bold text-indigo-700 transition-all hover:border-indigo-300 hover:bg-indigo-100 dark:border-indigo-900/30 dark:bg-indigo-900/10 dark:text-indigo-400">
          <Building2 className="h-4 w-4" />
          Group Charter
        </button>
      </DialogTrigger>

      <DialogContent className="max-w-lg rounded-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-lg font-black text-aerojet-blue">
            <Building2 className="h-5 w-5" />
            Create Group Charter Booking
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 pt-2">
          <p className="text-xs text-slate-500">
            Group charters reserve a dedicated pool (up to 28 seats) for an organisation
            or military group. The representative&apos;s wallet will be charged €7,500.
          </p>

          {/* Representative User ID */}
          <div className="space-y-1.5">
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">
              Representative User ID
            </label>
            <input
              type="text"
              value={repUserId}
              onChange={(e) => setRepUserId(e.target.value)}
              placeholder="Paste student/rep user ID"
              className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
            />
          </div>

          {/* Event */}
          <div className="space-y-1.5">
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">
              Exam Event
            </label>
            <select
              value={eventId}
              onChange={(e) => setEventId(e.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
            >
              <option value="">— Select event —</option>
              {events.map((e) => (
                <option key={e.id} value={e.id}>{e.name}</option>
              ))}
            </select>
          </div>

          {/* Group Name */}
          <div className="space-y-1.5">
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">
              Organisation / Group Name
            </label>
            <input
              type="text"
              value={groupName}
              onChange={(e) => setGroupName(e.target.value)}
              placeholder="e.g. Irish Air Corps, Ryanair"
              className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
            />
          </div>

          {/* Member Count */}
          <div className="space-y-1.5">
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">
              Expected Members (max 28)
            </label>
            <input
              type="number"
              min={1}
              max={28}
              value={memberCount}
              onChange={(e) => setMemberCount(Math.min(28, Math.max(1, parseInt(e.target.value) || 1)))}
              className="w-28 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm focus:border-aerojet-blue focus:outline-none focus:ring-2 focus:ring-aerojet-blue/20 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
            />
          </div>

          {/* Module Selection */}
          <div className="space-y-1.5">
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">
              Exam Modules
            </label>
            <div className="max-h-40 space-y-1 overflow-y-auto rounded-xl border border-slate-200 bg-slate-50 p-2 dark:border-slate-700 dark:bg-slate-800/30">
              {modules.map((m) => (
                <label
                  key={m.id}
                  className={`flex cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-sm transition-colors ${
                    selectedModules.includes(m.id)
                      ? 'bg-aerojet-blue/10 font-bold text-aerojet-blue'
                      : 'text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700/50'
                  }`}
                >
                  <input
                    type="checkbox"
                    checked={selectedModules.includes(m.id)}
                    onChange={() => toggleModule(m.id)}
                    className="rounded accent-aerojet-blue"
                  />
                  <span className="font-mono text-xs">{m.code}</span>
                  <span className="truncate">{m.name}</span>
                </label>
              ))}
            </div>
            <p className="text-xs text-slate-400">{selectedModules.length} module(s) selected</p>
          </div>

          {error && (
            <div className="flex items-center gap-2 rounded-xl border border-red-100 bg-red-50 p-3 text-sm font-medium text-red-700 dark:border-red-900/20 dark:bg-red-900/10 dark:text-red-400">
              <X className="h-4 w-4 shrink-0" />
              {error}
            </div>
          )}

          {success && (
            <div className="flex items-center gap-2 rounded-xl border border-emerald-100 bg-emerald-50 p-3 text-sm font-medium text-emerald-700">
              <CheckCircle className="h-4 w-4 shrink-0" />
              Group charter created! Refreshing...
            </div>
          )}

          <div className="flex justify-end gap-3 pt-2">
            <button
              onClick={handleClose}
              className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-400"
            >
              Cancel
            </button>
            <button
              onClick={handleSubmit}
              disabled={isSubmitting || success || !repUserId || !eventId || !groupName.trim() || selectedModules.length === 0}
              className="flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-bold text-white transition-colors hover:bg-indigo-700 disabled:opacity-50"
            >
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              <Users className="h-4 w-4" />
              Create Charter
            </button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'
/** Exam Records Dashboard with Pagination and Inline Editing */

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { format } from 'date-fns'
import {
  Search,
  Plus,
  Trash2,
  Edit,
  CheckCircle2,
  XCircle,
  Clock,
  User,
  FilePlus2,
  AlertCircle,
  Calendar,
  Award,
  BookOpen,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react'
import { toast } from 'sonner'
import {
  updateExamBooking,
  searchStudents,
  bulkUpdateExamCategory,
  createExamRecord,
  deleteExamRecord,
} from '../../actions'
import { useSort, SortHeader } from '@/lib/hooks/useSort'

interface StudentOption {
  id: string
  email: string
  firstName: string
  middleName?: string | null
  lastName: string
  studentId: string
}

interface ModuleOption {
  id: string
  courseId: string
  code: string
  name: string
  moduleCode: string
  isComponent?: boolean
}

interface ExamRecord {
  id: string
  examId?: string | null
  moduleCode: string | null
  score: any
  maxScore?: any
  percentage?: any
  passed: boolean | null
  grade?: string | null
  attemptType: string | null
  bookingType?: string | null
  source: 'booking' | 'result'
  sourceNotes?: string | null
  migrationRef?: string | null
  isMigrated?: boolean
  certificateUrl?: string | null
  examCategory?: 'INTERNAL' | 'OFFICIAL_EASA' | string
  examDate?: string | Date | null
  dateDisplay?: string | null
  dateDisplayKind?: 'DATE' | 'TBC' | 'TBD'
  sittingLabel?: string | null
  result?: string | null
  displayResult?: string | null
  displayResultKind?: string | null
  createdAt: string | Date
  updatedAt?: string | Date
  user: {
    email: string
    profile: { firstName: string; middleName?: string | null; lastName: string } | null
    studentProfile: { studentId: string } | null
  }
}

interface RecordsTabProps {
  records: ExamRecord[]
  modules: ModuleOption[]
}

const ATTEMPT_TYPES = [
  { value: 'FIRST', label: '1st Attempt' },
  { value: 'RESIT_1', label: 'Resit (2nd)' },
  { value: 'RESIT_2', label: 'Resit (3rd)' },
  { value: 'RESIT_3', label: 'Resit (4th+)' },
]

const BOOKING_TYPES = [
  { value: 'INDIVIDUAL', label: 'Individual Exam (â‚¬520)', seats: 1 },
  { value: 'TWIN_PACK', label: 'Twin Pack (â‚¬980)', seats: 2 },
  { value: 'FOUR_PACK', label: '4-Pack Bundle (â‚¬1900)', seats: 4 },
]

function statusBadgeClass(result?: string | null) {
  const normalized = result?.toUpperCase()
  if (normalized === 'PASS')
    return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400'
  if (normalized === 'FAIL') return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
  if (normalized === 'ABSENT') return 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400'
  if (normalized?.includes('PENDING'))
    return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'
  if (normalized?.includes('EXCUSED'))
    return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
  if (normalized === 'MIGRATED')
    return 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400'
  if (normalized === 'SCHEDULED')
    return 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-400'
  if (normalized === 'EXECUTED')
    return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400'
  if (normalized === 'POSTPONED')
    return 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'
  if (normalized === 'ROLLED FORWARD')
    return 'bg-violet-100 text-violet-700 dark:bg-violet-900/30 dark:text-violet-400'
  if (normalized === 'CANCELLED')
    return 'bg-slate-200 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
  return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
}

export default function RecordsTab({ records, modules }: RecordsTabProps) {
  const router = useRouter()
  const {
    items: sortedRecords,
    requestSort,
    sortConfig,
  } = useSort(records, {
    key: 'createdAt',
    order: 'desc',
  })

  // Form state
  const [studentQuery, setStudentQuery] = useState('')
  const [studentResults, setStudentResults] = useState<StudentOption[]>([])
  const [selectedStudent, setSelectedStudent] = useState<StudentOption | null>(null)
  const [examDate, setExamDate] = useState('')
  const [score, setScore] = useState('')
  const [attemptType, setAttemptType] = useState('FIRST')
  const [examCategory, setExamCategory] = useState('OFFICIAL_EASA')
  const [notes, setNotes] = useState('')
  const [resultOverride, setResultOverride] = useState('auto')
  const [isPending, setIsPending] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isSearching, setIsSearching] = useState(false)
  const [showDropdown, setShowDropdown] = useState(false)

  // Bundle state
  const [bookingType, setBookingType] = useState<'INDIVIDUAL' | 'TWIN_PACK' | 'FOUR_PACK'>(
    'INDIVIDUAL'
  )
  const [moduleSelections, setModuleSelections] = useState<
    { query: string; selected: ModuleOption | null; showDropdown: boolean }[]
  >([{ query: '', selected: null, showDropdown: false }])

  // Edit state
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editCourseId, setEditCourseId] = useState<string | null>(null)
  const [editBookingType, setEditBookingType] = useState('INDIVIDUAL')
  const [editAttemptType, setEditAttemptType] = useState('FIRST')
  const [editCategory, setEditCategory] = useState<'INTERNAL' | 'OFFICIAL_EASA'>('OFFICIAL_EASA')
  const [editModuleCode, setEditModuleCode] = useState('')
  const [editScore, setEditScore] = useState('')
  const [editDate, setEditDate] = useState('')
  const [editIsMigrated, setEditIsMigrated] = useState(false)
  const [editShowDropdown, setEditShowDropdown] = useState(false)
  const [editCourseQuery, setEditCourseQuery] = useState('')
  const [showEditCourseDropdown, setShowEditCourseDropdown] = useState(false)
  const [isUpdating, setIsUpdating] = useState(false)

  // Search filter
  const [tableFilter, setTableFilter] = useState('')
  const [categoryFilter, setCategoryFilter] = useState<'ALL' | 'OFFICIAL_EASA' | 'INTERNAL'>('ALL')
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [isBulkUpdating, setIsBulkUpdating] = useState(false)

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(50)

  // Reset pagination when filters change
  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setCurrentPage(1)
  }, [tableFilter, categoryFilter])

  // Debounced student search
  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
    if (studentQuery.length < 2) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setStudentResults([])
      setShowDropdown(false)
      return
    }

    const timeout = setTimeout(async () => {
      setIsSearching(true)
      const res = await searchStudents(studentQuery)
      setStudentResults(res.students)
      setShowDropdown(true)
      setIsSearching(false)
    }, 300)

    return () => clearTimeout(timeout)
  }, [studentQuery])

  const updateModuleSelection = (
    index: number,
    updates: Partial<{ query: string; selected: ModuleOption | null; showDropdown: boolean }>
  ) => {
    setModuleSelections((prev) => {
      const next = [...prev]
      next[index] = { ...next[index], ...updates }
      return next
    })
  }

  // Adjust module slots when booking type changes
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    const seats = BOOKING_TYPES.find((t) => t.value === bookingType)?.seats || 1
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setModuleSelections((prev) => {
      const next = [...prev]
      if (next.length < seats) {
        while (next.length < seats) {
          next.push({ query: '', selected: null, showDropdown: false })
        }
      } else if (next.length > seats) {
        return next.slice(0, seats)
      }
      return next
    })
  }, [bookingType])

  const selectStudent = (student: StudentOption) => {
    setSelectedStudent(student)
    setStudentQuery(
      [student.firstName, student.middleName, student.lastName].filter(Boolean).join(' ') +
        ` (${student.email})`
    )
    setShowDropdown(false)
  }

  const resetForm = () => {
    setStudentQuery('')
    setSelectedStudent(null)
    setBookingType('INDIVIDUAL')
    setModuleSelections([{ query: '', selected: null, showDropdown: false }])
    setExamDate('')
    setScore('')
    setAttemptType('FIRST')
    setExamCategory('OFFICIAL_EASA')
    setNotes('')
    setResultOverride('auto')
    setIsPending(false)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedStudent) {
      toast.error('Please select a student')
      return
    }

    const invalid = moduleSelections.some((m) => !m.query.trim())
    if (invalid) {
      toast.error('Please fill in all module selections')
      return
    }

    if (!examDate) {
      toast.error('Please enter an exam date')
      return
    }

    setIsSubmitting(true)
    try {
      const res = await createExamRecord({
        userId: selectedStudent.id,
        bookingType,
        examDate,
        attemptType,
        examCategory: examCategory as 'INTERNAL' | 'OFFICIAL_EASA',
        notes: notes.trim() || undefined,
        isPending,
        entries: moduleSelections.map((sel) => ({
          courseId: sel.selected?.courseId,
          examComponentId: sel.selected?.isComponent ? sel.selected?.id : undefined,
          moduleCode: sel.selected?.moduleCode || sel.query,
          score: score ? parseFloat(score) : undefined,
          resultOverride: resultOverride === 'auto' ? undefined : resultOverride,
        })),
      })

      if (res.success) {
        toast.success(
          `Added ${bookingType === 'INDIVIDUAL' ? 'exam record' : 'bundle'} successfully`
        )
        resetForm()
        router.refresh()
      } else {
        toast.error(res.error || 'Failed to add record')
      }
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this record?')) return
    const res = await deleteExamRecord(id)
    if (res.success) {
      toast.success('Record deleted')
      router.refresh()
    } else {
      toast.error(res.error || 'Failed to delete')
    }
  }

  const startEdit = (record: ExamRecord) => {
    setEditingId(record.id)
    setEditCourseId(record.examId || null)
    setEditBookingType(record.bookingType || 'INDIVIDUAL')
    setEditAttemptType(record.attemptType || 'FIRST')
    setEditCategory((record.examCategory as 'INTERNAL' | 'OFFICIAL_EASA') || 'OFFICIAL_EASA')
    setEditModuleCode(record.moduleCode || '')
    setEditScore(record.score ? Number(record.score).toString() : '')
    setEditDate(record.examDate ? format(new Date(record.examDate), 'yyyy-MM-dd') : '')
    setEditIsMigrated(!!record.isMigrated)
    const linkedCourse = modules.find((m) => m.id === record.examId)
    setEditCourseQuery(
      linkedCourse ? `${linkedCourse.code} â€” ${linkedCourse.name}` : record.moduleCode || ''
    )
    setShowEditCourseDropdown(false)
  }

  const handleUpdate = async () => {
    if (!editingId) return
    setIsUpdating(true)

    const res = await updateExamBooking(
      editingId.startsWith('result_') ? editingId.replace('result_', '') : editingId,
      {
        courseId: editCourseId || undefined,
        moduleCode: editModuleCode || undefined,
        examDate: editDate ? new Date(editDate) : undefined,
        score: editScore ? Number(editScore) : undefined,
        bookingType: editBookingType as any,
        attemptType: editAttemptType,
        examCategory: editCategory as any,
        isMigrated: editIsMigrated,
      }
    )

    setIsUpdating(false)
    if (res.success) {
      toast.success('Record updated')
      setEditingId(null)
      router.refresh()
    } else {
      toast.error(res.error || 'Failed to update')
    }
  }

  const handleBulkUpdate = async (category: 'INTERNAL' | 'OFFICIAL_EASA') => {
    if (selectedIds.length === 0) {
      toast.error('No records selected')
      return
    }
    setIsBulkUpdating(true)
    try {
      const res = await bulkUpdateExamCategory(selectedIds, category)

      if (res.success) {
        toast.success(`Successfully updated ${selectedIds.length} records`)
        setSelectedIds([])
        router.refresh()
      } else {
        toast.error(res.error || 'Failed to update records')
      }
    } catch (err) {
      console.error('Bulk update exception:', err)
      toast.error('A client-side error occurred')
    } finally {
      setIsBulkUpdating(false)
    }
  }

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredRecords.length) {
      setSelectedIds([])
    } else {
      setSelectedIds(filteredRecords.map((r) => r.id))
    }
  }

  const toggleSelectRecord = (id: string) => {
    setSelectedIds((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]))
  }

  const filteredRecords = sortedRecords.filter((r) => {
    const matchesSearch = tableFilter
      ? r.moduleCode?.toLowerCase().includes(tableFilter.toLowerCase()) ||
        r.user.email.toLowerCase().includes(tableFilter.toLowerCase()) ||
        (r.user.profile?.firstName + ' ' + r.user.profile?.lastName)
          .toLowerCase()
          .includes(tableFilter.toLowerCase())
      : true

    const matchesCategory = categoryFilter === 'ALL' || r.examCategory === categoryFilter

    return matchesSearch && matchesCategory
  })

  // Pagination logic
  const totalItems = filteredRecords.length
  const totalPages = Math.ceil(totalItems / pageSize)
  const paginatedRecords = filteredRecords.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  )

  return (
    <div className="space-y-8">
      {/* â”€â”€ Add Record Form â”€â”€ */}
      <div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-6 flex items-center gap-3">
          <div className="bg-aerojet-blue flex h-10 w-10 items-center justify-center rounded-xl text-white">
            <FilePlus2 className="h-5 w-5" />
          </div>
          <div>
            <h2 className="text-lg font-black text-slate-900 dark:text-white">Add Exam Record</h2>
            <p className="text-xs text-slate-500">
              Manually create an exam result for any student. Resit attempts are fully supported.
            </p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="relative">
            <label
              htmlFor="form-student-search"
              className="mb-1.5 block text-xs font-bold tracking-wide text-slate-500 uppercase"
            >
              Student <span className="text-red-500">*</span>
            </label>
            <div className="relative">
              <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <input
                id="form-student-search"
                type="text"
                value={studentQuery}
                onChange={(e) => {
                  setStudentQuery(e.target.value)
                  if (selectedStudent) setSelectedStudent(null)
                }}
                placeholder="Search by name, email, or student ID..."
                autoComplete="off"
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pr-4 pl-10 text-sm transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
              />
              {isSearching && (
                <div className="absolute top-1/2 right-3 -translate-y-1/2">
                  <div className="border-t-aerojet-blue h-4 w-4 animate-spin rounded-full border-2 border-slate-300" />
                </div>
              )}
            </div>

            {showDropdown && studentResults.length > 0 && (
              <div className="absolute z-20 mt-1 max-h-48 w-full overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-slate-900">
                {studentResults.map((s) => (
                  <button
                    key={s.id}
                    type="button"
                    onClick={() => selectStudent(s)}
                    className="flex w-full items-center gap-3 px-4 py-3 text-left transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/60"
                  >
                    <div className="text-aerojet-blue flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-100 text-xs font-bold">
                      {s.firstName.charAt(0)}
                      {s.lastName.charAt(0)}
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-bold text-slate-900 dark:text-white">
                        {[s.firstName, s.middleName, s.lastName].filter(Boolean).join(' ')}
                      </p>
                      <p className="truncate text-xs text-slate-500">
                        {s.email}
                        {s.studentId && (
                          <span className="ml-2 text-slate-400">ID: {s.studentId}</span>
                        )}
                      </p>
                    </div>
                  </button>
                ))}
              </div>
            )}
            {selectedStudent && (
              <div className="mt-2 flex items-center gap-2 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-medium text-emerald-700">
                <CheckCircle2 className="h-3.5 w-3.5" />
                Selected:{' '}
                {[selectedStudent.firstName, selectedStudent.middleName, selectedStudent.lastName]
                  .filter(Boolean)
                  .join(' ')}{' '}
                ({selectedStudent.email})
              </div>
            )}
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <label
                htmlFor="form-booking-type"
                className="mb-1.5 block text-[10px] font-black tracking-widest text-slate-500 uppercase"
              >
                Booking Type <span className="text-red-500">*</span>
              </label>
              <select
                id="form-booking-type"
                value={bookingType}
                onChange={(e) =>
                  setBookingType(e.target.value as 'INDIVIDUAL' | 'TWIN_PACK' | 'FOUR_PACK')
                }
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm font-bold transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
              >
                {BOOKING_TYPES.map((t) => (
                  <option key={t.value} value={t.value}>
                    {t.label}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label
                htmlFor="form-exam-date"
                className="mb-1.5 block text-[10px] font-black tracking-widest text-slate-500 uppercase"
              >
                Exam Date <span className="text-red-500">*</span>
              </label>
              <input
                id="form-exam-date"
                type="date"
                value={examDate}
                onChange={(e) => setExamDate(e.target.value)}
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm font-bold transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
                required
              />
            </div>
          </div>

          <div className={`grid gap-4 ${bookingType === 'INDIVIDUAL' ? '' : 'sm:grid-cols-2'}`}>
            {moduleSelections.map((selection, idx) => (
              <div key={idx} className="relative">
                <label
                  htmlFor={`form-module-query-${idx}`}
                  className="mb-1.5 block text-xs font-bold tracking-wide text-slate-500 uppercase"
                >
                  {bookingType === 'INDIVIDUAL' ? 'Module' : `Module ${idx + 1}`}{' '}
                  <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
                  <input
                    id={`form-module-query-${idx}`}
                    type="text"
                    value={selection.query}
                    autoComplete="off"
                    onChange={(e) => {
                      const q = e.target.value
                      updateModuleSelection(idx, {
                        query: q,
                        selected: null,
                        showDropdown: q.length > 0,
                      })
                    }}
                    onFocus={() => {
                      if (selection.query.length > 0)
                        updateModuleSelection(idx, { showDropdown: true })
                    }}
                    onBlur={() => {
                      // Small timeout to allow clicking the suggestion
                      setTimeout(() => updateModuleSelection(idx, { showDropdown: false }), 200)
                    }}
                    placeholder="Search module code..."
                    className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pr-4 pl-10 text-sm font-bold uppercase transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
                  />
                  {selection.showDropdown && (
                    <div className="absolute top-full left-0 z-50 mt-1 max-h-48 w-full overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-xl dark:border-slate-700 dark:bg-slate-900">
                      {modules
                        .filter(
                          (m) =>
                            m.code.toLowerCase().includes(selection.query.toLowerCase()) ||
                            m.name.toLowerCase().includes(selection.query.toLowerCase())
                        )
                        .map((m) => (
                          <button
                            key={m.id}
                            type="button"
                            onClick={() => {
                              updateModuleSelection(idx, {
                                query: m.moduleCode,
                                selected: m,
                                showDropdown: false,
                              })
                            }}
                            className="flex w-full items-center gap-3 px-4 py-3 text-left transition-all hover:bg-slate-50 dark:hover:bg-slate-800"
                          >
                            <div className="min-w-0 flex-1">
                              <p className="truncate text-sm font-bold text-slate-900 dark:text-white">
                                {m.name}
                              </p>
                              <p className="text-[10px] tracking-tighter text-slate-500 uppercase">
                                Code: {m.code}
                              </p>
                            </div>
                          </button>
                        ))}
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>

          <div className="grid gap-4 sm:grid-cols-4">
            <div>
              <label className="mb-1.5 block text-xs font-bold tracking-wide text-slate-500 uppercase">
                Attempt Type
              </label>
              <select
                value={attemptType}
                onChange={(e) => setAttemptType(e.target.value)}
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
              >
                {ATTEMPT_TYPES.map((t) => (
                  <option key={t.value} value={t.value}>
                    {t.label}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold tracking-wide text-slate-500 uppercase">
                Category
              </label>
              <select
                value={examCategory}
                onChange={(e) => setExamCategory(e.target.value)}
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
              >
                <option value="OFFICIAL_EASA">Official EASA</option>
                <option value="INTERNAL">Internal Academy</option>
              </select>
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold tracking-wide text-slate-500 uppercase">
                Score (%)
              </label>
              <input
                type="number"
                value={score}
                onChange={(e) => setScore(e.target.value)}
                placeholder="â€”"
                min="0"
                max="100"
                step="0.01"
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold tracking-wide text-slate-500 uppercase">
                Notes
              </label>
              <input
                type="text"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Optional notes"
                className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div className="flex items-center gap-3 rounded-xl border border-slate-100 bg-slate-50/50 p-4 dark:border-slate-800 dark:bg-slate-800/30">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400">
                <Clock className="h-5 w-5" />
              </div>
              <div className="flex-1">
                <p className="text-xs font-bold text-slate-900 dark:text-white">Pending Record</p>
                <p className="text-[10px] text-slate-500">Wait for result entry</p>
              </div>
              <button
                type="button"
                onClick={() => setIsPending(!isPending)}
                className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-hidden ${
                  isPending ? 'bg-amber-500' : 'bg-slate-200 dark:bg-slate-700'
                }`}
              >
                <span
                  className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out ${isPending ? 'translate-x-5' : 'translate-x-0'}`}
                />
              </button>
            </div>

            <div className="flex items-center gap-3 rounded-xl border border-slate-100 bg-slate-50/50 p-4 dark:border-slate-800 dark:bg-slate-800/30">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400">
                <Award className="h-5 w-5" />
              </div>
              <div className="flex-1">
                <p className="text-xs font-bold text-slate-900 dark:text-white">Result Override</p>
                <select
                  disabled={isPending}
                  value={resultOverride}
                  onChange={(e) => setResultOverride(e.target.value)}
                  className="mt-1 w-full bg-transparent text-[10px] font-bold text-slate-500 focus:outline-hidden disabled:opacity-50"
                >
                  <option value="auto">Auto (from score)</option>
                  <option value="pass">Manual Pass</option>
                  <option value="fail">Manual Fail</option>
                  <option value="deferred">Deferred</option>
                  <option value="absent">Absent</option>
                </select>
              </div>
            </div>
          </div>

          <div className="flex justify-end gap-3 border-t border-slate-100 pt-4 dark:border-slate-800">
            <button
              type="button"
              onClick={resetForm}
              className="rounded-xl px-4 py-2.5 text-sm font-bold text-slate-500 transition-colors hover:bg-slate-100"
            >
              Clear
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="bg-aerojet-blue hover:bg-aerojet-blue/90 flex items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-bold text-white transition-colors disabled:opacity-50"
            >
              <Plus className="h-4 w-4" />
              {isSubmitting ? 'Adding...' : 'Add Record'}
            </button>
          </div>
        </form>
      </div>

      {/* â”€â”€ Records Table â”€â”€ */}
      <div className="space-y-4">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-center gap-2 rounded-xl bg-slate-100 p-1 dark:bg-slate-800">
            <button
              onClick={() => setCategoryFilter('ALL')}
              className={`rounded-lg px-4 py-1.5 text-xs font-bold transition-all ${
                categoryFilter === 'ALL'
                  ? 'bg-white text-slate-900 shadow-sm dark:bg-slate-700 dark:text-white'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              }`}
            >
              All
            </button>
            <button
              onClick={() => setCategoryFilter('OFFICIAL_EASA')}
              className={`flex items-center gap-2 rounded-lg px-4 py-1.5 text-xs font-bold transition-all ${
                categoryFilter === 'OFFICIAL_EASA'
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 dark:shadow-none'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              }`}
            >
              <Award className="h-3.5 w-3.5" />
              Official EASA
            </button>
            <button
              onClick={() => setCategoryFilter('INTERNAL')}
              className={`flex items-center gap-2 rounded-lg px-4 py-1.5 text-xs font-bold transition-all ${
                categoryFilter === 'INTERNAL'
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 dark:shadow-none'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              }`}
            >
              <BookOpen className="h-3.5 w-3.5" />
              Internal Academy
            </button>
          </div>
          <div className="relative w-full max-w-xs">
            <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              value={tableFilter}
              onChange={(e) => setTableFilter(e.target.value)}
              placeholder="Filter by student or module..."
              className="focus:border-aerojet-blue w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pr-4 pl-10 text-sm transition-colors focus:bg-white focus:outline-hidden dark:border-slate-700 dark:bg-slate-800"
            />
          </div>
        </div>

        <div className="flex flex-wrap gap-3 rounded-xl border border-amber-100 bg-amber-50/50 px-4 py-3 text-xs text-amber-800 dark:border-amber-900/40 dark:bg-amber-950/20 dark:text-amber-300">
          <span>
            <strong>TBC</strong>: final sitting/date is still to be confirmed.
          </span>
          <span>
            <strong>TBD</strong>: no exam date has been set yet.
          </span>
        </div>

        <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase dark:bg-slate-800/50 dark:text-slate-400">
                <tr>
                  <th className="w-10 px-6 py-4">
                    <input
                      type="checkbox"
                      checked={
                        filteredRecords.length > 0 && selectedIds.length === filteredRecords.length
                      }
                      onChange={toggleSelectAll}
                      className="text-aerojet-blue h-4 w-4 rounded border-slate-300"
                    />
                  </th>
                  <SortHeader
                    label="Student"
                    sortKey="user.email"
                    currentSort={sortConfig}
                    onSort={requestSort}
                  />
                  <SortHeader
                    label="Module"
                    sortKey="moduleCode"
                    currentSort={sortConfig}
                    onSort={requestSort}
                  />
                  <SortHeader
                    label="Dates"
                    sortKey="examDate"
                    currentSort={sortConfig}
                    onSort={requestSort}
                  />
                  <th className="px-6 py-4">Category</th>
                  <th className="px-6 py-4">Type</th>
                  <th className="px-6 py-4">Attempt</th>
                  <th className="px-6 py-4">Migrated</th>
                  <th className="px-6 py-4">Result</th>
                  <SortHeader
                    label="Score"
                    sortKey="score"
                    currentSort={sortConfig}
                    onSort={requestSort}
                    align="right"
                  />
                  <th className="px-6 py-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                {paginatedRecords.length === 0 ? (
                  <tr>
                    <td colSpan={11} className="px-6 py-12 text-center text-slate-500 italic">
                      No records match.
                    </td>
                  </tr>
                ) : (
                  paginatedRecords.map((record) => {
                    const isEditing = editingId === record.id
                    const scoreNum = isEditing
                      ? editScore
                        ? Number(editScore)
                        : null
                      : record.score
                        ? Number(record.score)
                        : null
                    const passed = isEditing
                      ? scoreNum !== null
                        ? scoreNum >= 75
                        : record.passed
                      : record.passed
                    const displayResult =
                      record.displayResult ||
                      record.result ||
                      (passed === true ? 'PASS' : passed === false ? 'FAIL' : 'Pending')

                    return (
                      <tr
                        key={record.id}
                        className={`group border-b border-slate-50 transition-all hover:bg-slate-50/50 ${isEditing ? 'bg-aerojet-blue/5 shadow-inner' : ''}`}
                      >
                        <td className="px-6 py-4">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(record.id)}
                            onChange={() => toggleSelectRecord(record.id)}
                            className="text-aerojet-blue h-4 w-4 rounded border-slate-300"
                          />
                        </td>
                        <td className="px-6 py-4">
                          <p className="font-bold text-slate-900 dark:text-white">
                            {[record.user.profile?.firstName, record.user.profile?.lastName]
                              .filter(Boolean)
                              .join(' ')}
                          </p>
                          <p className="text-[10px] text-slate-500">{record.user.email}</p>
                        </td>
                        <td className="px-6 py-4">
                          {isEditing ? (
                            <div className="relative">
                              <input
                                type="text"
                                value={editModuleCode}
                                autoComplete="off"
                                onChange={(e) => {
                                  const q = e.target.value.toUpperCase()
                                  setEditModuleCode(q)
                                  setEditShowDropdown(q.length > 0)
                                }}
                                onFocus={() => {
                                  if (editModuleCode.length > 0) setEditShowDropdown(true)
                                }}
                                onBlur={() => setTimeout(() => setEditShowDropdown(false), 200)}
                                className="focus:border-aerojet-blue w-24 rounded-lg border border-slate-200 bg-white px-2 py-1 text-xs font-bold uppercase focus:outline-hidden"
                              />
                              {editShowDropdown && (
                                <div className="absolute top-full left-0 z-50 mt-1 max-h-48 w-64 overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-xl dark:border-slate-700 dark:bg-slate-900">
                                  {modules
                                    .filter(
                                      (m) =>
                                        m.code
                                          .toLowerCase()
                                          .includes(editModuleCode.toLowerCase()) ||
                                        m.name.toLowerCase().includes(editModuleCode.toLowerCase())
                                    )
                                    .slice(0, 10)
                                    .map((m) => (
                                      <button
                                        key={m.id}
                                        type="button"
                                        onClick={() => {
                                          setEditModuleCode(m.moduleCode)
                                          setEditShowDropdown(false)
                                        }}
                                        className="flex w-full items-center gap-3 px-3 py-2 text-left transition-all hover:bg-slate-50 dark:hover:bg-slate-800"
                                      >
                                        <div className="min-w-0 flex-1">
                                          <p className="truncate text-xs font-bold text-slate-900 dark:text-white">
                                            {m.name}
                                          </p>
                                          <p className="text-[10px] text-slate-500 uppercase">
                                            Code: {m.code}
                                          </p>
                                        </div>
                                      </button>
                                    ))}
                                </div>
                              )}
                            </div>
                          ) : (
                            <span className="font-bold text-slate-700 uppercase">
                              {record.moduleCode}
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4 text-xs font-bold text-slate-900">
                          {isEditing ? (
                            <input
                              type="date"
                              value={editDate}
                              onChange={(e) => setEditDate(e.target.value)}
                              className="focus:border-aerojet-blue rounded-lg border border-slate-200 bg-white px-2 py-1 text-[10px] focus:outline-hidden"
                            />
                          ) : (
                            <div>
                              <span
                                className={
                                  record.dateDisplayKind === 'DATE'
                                    ? ''
                                    : 'rounded-md bg-amber-100 px-2 py-0.5 text-[10px] font-black text-amber-700 uppercase dark:bg-amber-900/30 dark:text-amber-300'
                                }
                              >
                                {record.dateDisplayKind === 'DATE' && record.examDate
                                  ? format(new Date(record.examDate), 'MMM d, yyyy')
                                  : record.dateDisplay || 'TBD'}
                              </span>
                              {record.sittingLabel && (
                                <div className="mt-1 text-[10px] font-bold text-slate-400 uppercase">
                                  {record.sittingLabel}
                                </div>
                              )}
                            </div>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          {isEditing ? (
                            <select
                              value={editCategory}
                              onChange={(e) =>
                                setEditCategory(e.target.value as 'INTERNAL' | 'OFFICIAL_EASA')
                              }
                              className="focus:border-aerojet-blue rounded-lg border border-slate-200 bg-white px-2 py-1 text-[10px] focus:outline-hidden"
                            >
                              <option value="OFFICIAL_EASA">EASA</option>
                              <option value="INTERNAL">Internal</option>
                            </select>
                          ) : (
                            <div
                              className={`flex items-center gap-1.5 rounded-lg border px-2 py-1 text-[10px] font-bold uppercase transition-all ${record.examCategory === 'INTERNAL' ? 'border-indigo-100 bg-indigo-50/50 text-indigo-600' : 'border-blue-100 bg-blue-50/50 text-blue-600'}`}
                            >
                              {record.examCategory === 'INTERNAL' ? (
                                <>
                                  <BookOpen className="h-3 w-3" />
                                  <span>Internal</span>
                                </>
                              ) : (
                                <>
                                  <Award className="h-3 w-3" />
                                  <span>Official EASA</span>
                                </>
                              )}
                            </div>
                          )}
                        </td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          {isEditing ? (
                            <select
                              value={editBookingType}
                              onChange={(e) =>
                                setEditBookingType(
                                  e.target.value as 'INDIVIDUAL' | 'TWIN_PACK' | 'FOUR_PACK'
                                )
                              }
                              className="focus:border-aerojet-blue rounded-lg border border-slate-200 bg-white px-2 py-1 text-[10px] focus:outline-hidden"
                            >
                              <option value="INDIVIDUAL">IND</option>
                              <option value="TWIN_PACK">TWIN</option>
                              <option value="FOUR_PACK">4-PK</option>
                            </select>
                          ) : (
                            record.bookingType
                          )}
                        </td>
                        <td className="px-6 py-4">
                          {isEditing ? (
                            <select
                              value={editAttemptType}
                              onChange={(e) => setEditAttemptType(e.target.value)}
                              className="focus:border-aerojet-blue rounded-lg border border-slate-200 bg-white px-2 py-1 text-[10px] focus:outline-hidden"
                            >
                              {ATTEMPT_TYPES.map((t) => (
                                <option key={t.value} value={t.value}>
                                  {t.label}
                                </option>
                              ))}
                            </select>
                          ) : (
                            <span className="rounded-md bg-slate-100 px-2 py-0.5 text-[9px] font-bold uppercase">
                              {record.attemptType === 'MIGRATED' ? 'â€”' : record.attemptType || 'â€”'}
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          {isEditing ? (
                            <div className="flex items-center gap-2">
                              <input
                                type="checkbox"
                                checked={editIsMigrated}
                                onChange={(e) => setEditIsMigrated(e.target.checked)}
                                className="text-aerojet-blue h-4 w-4 rounded border-slate-300"
                              />
                              <span className="text-[10px] font-bold text-slate-500 uppercase">
                                Yes
                              </span>
                            </div>
                          ) : record.isMigrated ? (
                            <span className="rounded-full bg-amber-100 px-2 py-0.5 text-[9px] font-black text-amber-700 uppercase dark:bg-amber-900/30 dark:text-amber-400">
                              Migrated
                            </span>
                          ) : (
                            <span className="text-[10px] font-bold text-slate-300 uppercase">
                              â€”
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          <span
                            className={`inline-flex items-center rounded-full px-2 py-0.5 text-[9px] font-black uppercase ${statusBadgeClass(displayResult)}`}
                          >
                            {displayResult}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right font-bold">
                          {isEditing ? (
                            <input
                              type="number"
                              value={editScore}
                              onChange={(e) => setEditScore(e.target.value)}
                              className="focus:border-aerojet-blue w-16 rounded-lg border border-slate-200 bg-white px-2 py-1 text-right text-xs font-bold focus:outline-hidden"
                            />
                          ) : scoreNum !== null ? (
                            `${scoreNum.toFixed(0)}%`
                          ) : (
                            'â€”'
                          )}
                        </td>
                        <td className="px-6 py-4 text-right">
                          {isEditing ? (
                            <div className="flex items-center justify-end gap-2">
                              <button
                                onClick={() => setEditingId(null)}
                                className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100"
                              >
                                <XCircle className="h-4 w-4" />
                              </button>
                              <button
                                onClick={handleUpdate}
                                disabled={isUpdating}
                                className="rounded-lg bg-emerald-500 p-1.5 text-white hover:bg-emerald-600 disabled:opacity-50"
                              >
                                {isUpdating ? (
                                  <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                                ) : (
                                  <CheckCircle2 className="h-4 w-4" />
                                )}
                              </button>
                            </div>
                          ) : (
                            <div className="flex items-center justify-end gap-1">
                              <button
                                onClick={() => startEdit(record)}
                                className="hover:text-aerojet-blue p-2 text-slate-400 transition-colors"
                              >
                                <Edit className="h-4 w-4" />
                              </button>
                              <button
                                onClick={() => handleDelete(record.id)}
                                className="p-2 text-slate-400 transition-colors hover:text-red-500"
                              >
                                <Trash2 className="h-4 w-4" />
                              </button>
                            </div>
                          )}
                        </td>
                      </tr>
                    )
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* â”€â”€ Pagination Controls â”€â”€ */}
          <div className="flex flex-col items-center justify-between gap-4 border-t border-slate-100 bg-slate-50/50 px-6 py-4 sm:flex-row dark:border-slate-800 dark:bg-slate-800/20">
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-500 uppercase">Rows:</span>
                <select
                  value={pageSize}
                  onChange={(e) => {
                    setPageSize(Number(e.target.value))
                    setCurrentPage(1)
                  }}
                  className="focus:border-aerojet-blue rounded-lg border border-slate-200 bg-white px-2 py-1 text-xs font-bold focus:outline-hidden"
                >
                  {[25, 50, 100, 250, 500].map((size) => (
                    <option key={size} value={size}>
                      {size}
                    </option>
                  ))}
                </select>
              </div>
              <p className="text-xs text-slate-500">
                Showing{' '}
                <span className="font-bold text-slate-900 dark:text-white">
                  {(currentPage - 1) * pageSize + 1}
                </span>{' '}
                to{' '}
                <span className="font-bold text-slate-900 dark:text-white">
                  {Math.min(currentPage * pageSize, totalItems)}
                </span>{' '}
                of <span className="font-bold text-slate-900 dark:text-white">{totalItems}</span>
              </p>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
                disabled={currentPage === 1}
                className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-600 transition-colors hover:bg-slate-50 disabled:opacity-30 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400"
              >
                <ChevronLeft className="h-4 w-4" />
              </button>

              <div className="flex items-center gap-1">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = i + 1
                  if (totalPages > 5 && currentPage > 3) {
                    pageNum = currentPage - 3 + i + 1
                    if (pageNum > totalPages) pageNum = totalPages - (4 - i)
                  }
                  return (
                    <button
                      key={pageNum}
                      onClick={() => setCurrentPage(pageNum)}
                      className={`h-8 min-w-[32px] rounded-lg border px-2 text-xs font-bold transition-all ${
                        currentPage === pageNum
                          ? 'border-aerojet-blue bg-aerojet-blue text-white shadow-md'
                          : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400'
                      }`}
                    >
                      {pageNum}
                    </button>
                  )
                })}
              </div>

              <button
                onClick={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))}
                disabled={currentPage === totalPages || totalPages === 0}
                className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-600 transition-colors hover:bg-slate-50 disabled:opacity-30 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400"
              >
                <ChevronRight className="h-4 w-4" />
              </button>

              <div className="ml-2 flex items-center gap-2">
                <span className="text-xs text-slate-500 uppercase">Go:</span>
                <input
                  type="number"
                  min="1"
                  max={totalPages}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      const val = Number((e.target as HTMLInputElement).value)
                      if (val >= 1 && val <= totalPages) setCurrentPage(val)
                    }
                  }}
                  placeholder={`1-${totalPages}`}
                  className="focus:border-aerojet-blue w-16 rounded-lg border border-slate-200 bg-white px-2 py-1 text-center text-xs font-bold focus:outline-hidden"
                />
              </div>
            </div>
          </div>
        </div>
      </div>

      {selectedIds.length > 0 && (
        <div className="animate-in fade-in zoom-in-95 slide-in-from-bottom-8 fixed bottom-8 left-1/2 z-50 flex -translate-x-1/2 items-center gap-8 rounded-2xl border border-slate-200 bg-white p-2 shadow-2xl transition-all dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center gap-4 border-r border-slate-100 pr-6 pl-4 dark:border-slate-800">
            <div className="bg-aerojet-blue flex h-10 w-10 items-center justify-center rounded-xl font-black text-white shadow-lg">
              {selectedIds.length}
            </div>
            <div>
              <p className="text-sm leading-none font-black text-slate-900 dark:text-white">
                Records
              </p>
              <p className="text-[10px] font-bold tracking-tight text-slate-400 uppercase">
                Selected
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => handleBulkUpdate('OFFICIAL_EASA')}
              className="flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-xs font-black text-white shadow-lg transition-all hover:bg-blue-700"
            >
              <Award className="h-4 w-4" /> Link to Official EASA
            </button>
            <button
              onClick={() => handleBulkUpdate('INTERNAL')}
              className="flex items-center gap-2 rounded-xl bg-indigo-600 px-5 py-2.5 text-xs font-black text-white shadow-lg transition-all hover:bg-indigo-700"
            >
              <BookOpen className="h-4 w-4" /> Link to Internal
            </button>
          </div>

          <button
            onClick={() => setSelectedIds([])}
            className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-100 text-slate-500 hover:bg-red-50 hover:text-red-500"
          >
            <Trash2 className="h-4 w-4" />
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Plus, Calendar, Users, FileText, Settings, ChevronRight } from 'lucide-react'
import { toast } from 'sonner'

interface Exam {
  id: string
  title: string
  moduleCode: string
  licenceCategory?: string
  durationMinutes: number
  passMark: number
  status: string
  config: Record<string, any>
  createdAt: string
  _count: { questions: number; sessions: number }
}

interface Session {
  id: string
  startTime: string
  endTime: string
  location?: string
  status: string
  _count: { attempts: number; accessCodes: number }
}

export function ExamDetailClient({ examId }: { examId: string }) {
  const router = useRouter()
  const [exam, setExam] = useState<Exam | null>(null)
  const [sessions, setSessions] = useState<Session[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'overview' | 'sessions' | 'questions'>('overview')

  const fetchExam = async () => {
    setLoading(true)
    try {
      const [examRes, sessionsRes] = await Promise.all([
        fetch(`/api/exams/${examId}`),
        fetch(`/api/exams/${examId}/sessions?limit=10`),
      ])

      const examJson = await examRes.json()
      const sessionsJson = await sessionsRes.json()

      if (examJson.success) setExam(examJson.data)
      if (sessionsJson.success) setSessions(sessionsJson.data.sessions)
    } catch {
      toast.error('Failed to load exam')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchExam()
  }, [examId])

  const handleCreateSession = async () => {
    const startTime = prompt('Session start time (ISO format):', new Date().toISOString())
    if (!startTime) return

    const endTime = prompt('Session end time (ISO format):', new Date(Date.now() + 90 * 60 * 1000).toISOString())
    if (!endTime) return

    const res = await fetch(`/api/exams/${examId}/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        startTime,
        endTime,
        accessCodeCount: 20,
      }),
    })

    if (res.ok) {
      toast.success('Session created with access codes')
      fetchExam()
    } else {
      toast.error('Failed to create session')
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-aerojet-blue border-t-transparent" />
      </div>
    )
  }

  if (!exam) {
    return <div className="p-8 text-center text-red-500">Exam not found</div>
  }

  const tabs = [
    { id: 'overview', label: 'Overview', icon: Settings },
    { id: 'sessions', label: 'Sessions', icon: Calendar },
    { id: 'questions', label: 'Questions', icon: FileText },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <div className="flex items-center gap-2 text-sm text-slate-500">
            <button onClick={() => router.push('/staff/exams/anticheat')} className="hover:text-aerojet-blue">
              Exams
            </button>
            <ChevronRight className="h-4 w-4" />
            <span className="font-medium text-slate-900 dark:text-white">{exam.title}</span>
          </div>
          <h1 className="mt-2 text-3xl font-bold text-slate-900 dark:text-white">{exam.title}</h1>
          <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
            {exam.moduleCode} · {exam.durationMinutes} min · {exam.passMark}% pass mark
          </p>
        </div>
        <div className="flex items-center gap-3">
          <span className={`rounded-full px-3 py-1 text-sm font-bold ${exam.status === 'active' ? 'bg-green-100 text-green-800' : exam.status === 'draft' ? 'bg-slate-100 text-slate-800' : 'bg-red-100 text-red-800'}`}>
            {exam.status}
          </span>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-slate-200 dark:border-slate-800">
        <nav className="flex gap-6">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-2 border-b-2 px-1 py-4 text-sm font-medium transition-colors ${
                activeTab === tab.id
                  ? 'border-aerojet-blue text-aerojet-blue'
                  : 'border-transparent text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
              }`}
            >
              <tab.icon className="h-4 w-4" />
              {tab.label}
            </button>
          ))}
        </nav>
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
          <div className="rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 dark:bg-blue-900/30">
                <FileText className="h-5 w-5 text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900 dark:text-white">{exam._count.questions}</p>
                <p className="text-sm text-slate-500 dark:text-slate-400">Questions</p>
              </div>
            </div>
          </div>
          <div className="rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-green-100 dark:bg-green-900/30">
                <Calendar className="h-5 w-5 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900 dark:text-white">{exam._count.sessions}</p>
                <p className="text-sm text-slate-500 dark:text-slate-400">Sessions</p>
              </div>
            </div>
          </div>
          <div className="rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-purple-100 dark:bg-purple-900/30">
                <Users className="h-5 w-5 text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900 dark:text-white">{exam.durationMinutes}</p>
                <p className="text-sm text-slate-500 dark:text-slate-400">Minutes</p>
              </div>
            </div>
          </div>
          <div className="rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-100 dark:bg-amber-900/30">
                <Settings className="h-5 w-5 text-amber-600 dark:text-amber-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900 dark:text-white">{exam.passMark}%</p>
                <p className="text-sm text-slate-500 dark:text-slate-400">Pass Mark</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'sessions' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-bold text-slate-900 dark:text-white">Exam Sessions</h2>
            <button
              onClick={handleCreateSession}
              className="flex items-center gap-2 rounded-lg bg-aerojet-blue px-3 py-2 text-sm font-bold text-white hover:bg-blue-700"
            >
              <Plus className="h-4 w-4" />
              New Session
            </button>
          </div>

          {sessions.length === 0 ? (
            <div className="rounded-2xl border border-slate-200 bg-white p-8 text-center dark:border-slate-800 dark:bg-slate-900">
              <Calendar className="mx-auto mb-4 h-12 w-12 text-slate-300 dark:text-slate-600" />
              <p className="text-lg font-medium text-slate-600 dark:text-slate-400">No sessions yet</p>
              <p className="mt-1 text-sm text-slate-500 dark:text-slate-500">Create a session to generate access codes for candidates.</p>
            </div>
          ) : (
            <div className="overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-800">
              <table className="min-w-full divide-y divide-slate-200 bg-white dark:divide-slate-800 dark:bg-slate-900">
                <thead className="bg-slate-50 dark:bg-slate-800">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Start Time</th>
                    <th className="px-6 py-3 text-left text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">End Time</th>
                    <th className="px-6 py-3 text-left text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Location</th>
                    <th className="px-6 py-3 text-left text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Attempts</th>
                    <th className="px-6 py-3 text-left text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Access Codes</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                  {sessions.map((s) => (
                    <tr key={s.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                      <td className="whitespace-nowrap px-6 py-4 text-sm text-slate-500 dark:text-slate-400">
                        {new Date(s.startTime).toLocaleString()}
                      </td>
                      <td className="whitespace-nowrap px-6 py-4 text-sm text-slate-500 dark:text-slate-400">
                        {new Date(s.endTime).toLocaleString()}
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{s.location || '-'}</td>
                      <td className="px-6 py-4 text-sm">
                        <span className={`rounded-full px-2 py-1 text-xs font-bold ${s.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-slate-100 text-slate-800'}`}>
                          {s.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{s._count.attempts}</td>
                      <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{s._count.accessCodes}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {activeTab === 'questions' && (
        <div className="rounded-2xl border border-slate-200 bg-white p-8 text-center dark:border-slate-800 dark:bg-slate-900">
          <FileText className="mx-auto mb-4 h-12 w-12 text-slate-300 dark:text-slate-600" />
          <p className="text-lg font-medium text-slate-600 dark:text-slate-400">Question management coming soon</p>
          <p className="mt-1 text-sm text-slate-500 dark:text-slate-500">Questions will be importable via the shared question import pipeline.</p>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { CalendarDays, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { triggerSittingGeneration } from './actions'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

interface Props {
  eventId: string
}

export default function GenerateSittingsButton({ eventId }: Props) {
  const [loading, setLoading] = useState(false)
  const [open, setOpen] = useState(false)

  const handleGenerate = async () => {
    setLoading(true)
    try {
      const result = await triggerSittingGeneration(eventId)
      if (!result.success) {
        toast.error(result.error || 'Failed to generate sittings')
        return
      }
      toast.success(result.message)
      setOpen(false)
    } catch (error) {
      toast.error('An unexpected error occurred')
    } finally {
      setLoading(false)
    }
  }

  return (
    <AlertDialog open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger asChild>
          <AlertDialogTrigger asChild>
            <button
              disabled={loading}
              className="flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2.5 text-sm font-bold text-emerald-700 transition-colors hover:bg-emerald-100 dark:border-emerald-900/50 dark:bg-emerald-950/30 dark:text-emerald-400"
            >
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <CalendarDays className="h-4 w-4" />}
              Generate Sittings
            </button>
          </AlertDialogTrigger>
        </TooltipTrigger>
        <TooltipContent side="bottom" align="center" className="max-w-[300px] text-xs">
          <p>Automatically distribute pooled candidates into timed exam sessions based on examiner availability and capacity.</p>
        </TooltipContent>
      </Tooltip>

      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Generate Exam Sittings?</AlertDialogTitle>
          <AlertDialogDescription>
            This action will automatically distribute all currently pooled candidates into specific timed sessions. 
            Existing manual assignments are preserved, but new sessions will be created to accommodate pending demand.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={loading}>Cancel</AlertDialogCancel>
          <AlertDialogAction 
            onClick={(e) => {
              e.preventDefault();
              handleGenerate();
            }}
            disabled={loading}
            className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold"
          >
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Generating...
              </>
            ) : (
              "Confirm & Generate"
            )}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { 
  Users, 
  ArrowRight, 
  CheckCircle2, 
  AlertCircle, 
  Loader2,
  Sparkles,
  ChevronDown,
  ChevronUp
} from 'lucide-react'
import { toast } from 'sonner'

interface SpareCapacitySitting {
  sittingId: string
  moduleCode: string | null
  dayNumber: number
  sessionType: string
  capacity: number
  assignedCount: number
  spareSeats: number
}

interface ResitCandidate {
  bookingId: string
  userId: string
  userName: string | null
  moduleCode: string | null
}

interface ResitBackfillProposal {
  sittingId: string
  bookingId: string
  userId: string
  moduleCode: string | null
  reason: string
}

interface ResitBackfillResult {
  eventId: string
  spareCapacitySittings: SpareCapacitySitting[]
  eligibleResitCandidates: ResitCandidate[]
  proposals: ResitBackfillProposal[]
  warnings: string[]
}

export default function ResitBackfillPanel({ eventId }: { eventId: string }) {
  const [result, setResult] = useState<ResitBackfillResult | null>(null)
  const [loading, setLoading] = useState(false)
  const [executing, startTransition] = useTransition()
  const [expanded, setExpanded] = useState(false)

  const fetchProposals = async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/resit-backfill?eventId=${eventId}`)
      if (!res.ok) throw new Error('Failed to fetch proposals')
      const data = await res.json()
      setResult(data)
      setExpanded(true)
    } catch (error: any) {
      toast.error(error.message)
    } finally {
      setLoading(false)
    }
  }

  const handleExecute = async () => {
    if (!result || result.proposals.length === 0) return

    startTransition(async () => {
      try {
        const res = await fetch('/api/staff/resit-backfill', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            eventId,
            proposals: result.proposals,
          }),
        })

        const data = await res.json()
        if (!res.ok) throw new Error(data.error || 'Failed to execute backfill')

        toast.success(data.message)
        setResult(null)
        setExpanded(false)
        // Revalidate would happen via the API route's revalidatePath
        // But we might need a window reload or router refresh if the parent doesn't auto-update
        window.location.reload() 
      } catch (error: any) {
        toast.error(error.message)
      }
    })
  }

  if (!result && !loading) {
    return (
      <div className="rounded-2xl border border-blue-100 bg-blue-50/30 p-6 dark:border-blue-900/30 dark:bg-blue-900/10">
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-400">
              <Sparkles className="h-5 w-5" />
            </div>
            <div>
              <h3 className="font-bold text-blue-900 dark:text-blue-300">Resit Backfill Optimization</h3>
              <p className="text-sm text-blue-700/70 dark:text-blue-400/60">
                Identify spare capacity and automatically match resit candidates.
              </p>
            </div>
          </div>
          <button
            onClick={fetchProposals}
            disabled={loading}
            className="rounded-xl bg-blue-600 px-4 py-2 text-sm font-bold text-white transition-all hover:bg-blue-700 disabled:opacity-50"
          >
