              <p className="mt-1 text-xs text-slate-400">All resit candidates are either assigned or no compatible seats exist.</p>
            </div>
          ) : (
            <div className="space-y-3">
              <div className="grid grid-cols-12 gap-4 px-3 text-[10px] font-bold uppercase tracking-wider text-slate-400">
                <div className="col-span-5">Candidate</div>
                <div className="col-span-2">Module</div>
                <div className="col-span-5">Target Sitting</div>
              </div>
              <div className="max-h-[300px] overflow-y-auto space-y-2 pr-2">
                {result.proposals.map((proposal, i) => (
                  <div key={i} className="grid grid-cols-12 items-center gap-4 rounded-xl border border-slate-100 p-3 text-sm dark:border-slate-800">
                    <div className="col-span-5 font-medium text-slate-700 dark:text-slate-300">
                      {result.eligibleResitCandidates.find(c => c.bookingId === proposal.bookingId)?.userName || 'Unknown'}
                    </div>
                    <div className="col-span-2">
                      <span className="rounded bg-slate-100 px-1.5 py-0.5 text-[10px] font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-400">
                        {proposal.moduleCode}
                      </span>
                    </div>
                    <div className="col-span-5 flex items-center gap-2 text-xs text-slate-500">
                      <ArrowRight className="h-3 w-3 text-slate-300" />
                      <span className="truncate">{proposal.reason}</span>
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-6 flex items-center justify-between border-t border-slate-100 pt-6 dark:border-slate-800">
                <div className="text-xs text-slate-400">
                  Matches are made by same-module first, ensuring no candidate overlaps.
                </div>
                <div className="flex gap-3">
                  <button
                    onClick={() => {
                      setResult(null)
                      setExpanded(false)
                    }}
                    className="rounded-xl px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleExecute}
                    disabled={executing}
                    className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-2 text-sm font-bold text-white transition-all hover:bg-blue-700 disabled:opacity-50"
                  >
                    {executing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
                    Apply {result.proposals.length} Assignments
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useEffect, useState, useTransition } from 'react'
import { AlertTriangle, Users, UserX, Box, ShieldAlert } from 'lucide-react'

type ConflictType = 'CANDIDATE_OVERLAP' | 'EXAMINER_OVERLAP' | 'SPARE_CAPACITY' | 'UNSCHEDULED_GUARANTEED'

interface SchedulingConflict {
  type: ConflictType
  sittingId?: string
  userId?: string
  examinerId?: string
  moduleCode?: string
  description: string
}

const ICON_MAP: Record<ConflictType, typeof AlertTriangle> = {
  CANDIDATE_OVERLAP: Users,
  EXAMINER_OVERLAP: UserX,
  SPARE_CAPACITY: Box,
  UNSCHEDULED_GUARANTEED: ShieldAlert,
}

const SEVERITY_MAP: Record<ConflictType, { bg: string; text: string; border: string }> = {
  CANDIDATE_OVERLAP: { bg: 'bg-red-50 dark:bg-red-900/20', text: 'text-red-700 dark:text-red-400', border: 'border-red-200 dark:border-red-800' },
  EXAMINER_OVERLAP: { bg: 'bg-red-50 dark:bg-red-900/20', text: 'text-red-700 dark:text-red-400', border: 'border-red-200 dark:border-red-800' },
  SPARE_CAPACITY: { bg: 'bg-amber-50 dark:bg-amber-900/20', text: 'text-amber-700 dark:text-amber-400', border: 'border-amber-200 dark:border-amber-800' },
  UNSCHEDULED_GUARANTEED: { bg: 'bg-orange-50 dark:bg-orange-900/20', text: 'text-orange-700 dark:text-orange-400', border: 'border-orange-200 dark:border-orange-800' },
}

export default function SchedulingWarningsPanel({ eventId }: { eventId: string }) {
  const [conflicts, setConflicts] = useState<SchedulingConflict[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setLoading(true)
    setError(null)
    fetch(`/api/staff/exam-sittings/conflicts?eventId=${eventId}`)
      .then(async (res) => {
        if (!res.ok) throw new Error('Failed to fetch conflicts')
        const data = await res.json()
        setConflicts(data.conflicts ?? [])
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false))
  }, [eventId])

  if (loading) {
    return (
      <div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-center gap-2 text-sm text-slate-400">
          <AlertTriangle className="h-4 w-4 animate-pulse" />
          Checking scheduling conflictsâ€¦
        </div>
      </div>
    )
  }

  if (error) return null
  if (conflicts.length === 0) return null

  const critical = conflicts.filter((c) => c.type === 'CANDIDATE_OVERLAP' || c.type === 'EXAMINER_OVERLAP')
  const warnings = conflicts.filter((c) => c.type !== 'CANDIDATE_OVERLAP' && c.type !== 'EXAMINER_OVERLAP')

  return (
    <div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
      <h2 className="mb-4 flex items-center gap-2 text-lg font-bold text-slate-900 dark:text-slate-100">
        <AlertTriangle className="h-5 w-5 text-amber-500" />
        Scheduling Warnings
        <span className="ml-auto text-xs font-medium text-slate-400">
          {conflicts.length} issue{conflicts.length !== 1 ? 's' : ''}
        </span>
      </h2>

      <div className="space-y-2">
        {critical.map((conflict, i) => {
          const Icon = ICON_MAP[conflict.type]
          const style = SEVERITY_MAP[conflict.type]
          return (
            <div key={`critical-${i}`} className={`flex items-start gap-3 rounded-xl border p-3 ${style.bg} ${style.border}`}>
              <Icon className={`mt-0.5 h-4 w-4 shrink-0 ${style.text}`} />
              <span className={`text-sm font-medium ${style.text}`}>
                {conflict.description}
              </span>
            </div>
          )
        })}

        {warnings.map((conflict, i) => {
          const Icon = ICON_MAP[conflict.type]
          const style = SEVERITY_MAP[conflict.type]
          return (
            <div key={`warning-${i}`} className={`flex items-start gap-3 rounded-xl border p-3 ${style.bg} ${style.border}`}>
              <Icon className={`mt-0.5 h-4 w-4 shrink-0 ${style.text}`} />
              <span className={`text-sm ${style.text}`}>
                {conflict.description}
              </span>
            </div>
          )
        })}
      </div>
    </div>
  )
}

