  const [courses, setCourses] = useState<{ id: string; name: string; code: string }[]>([])
  const [modules, setModules] = useState<{ code: string; name: string }[]>([])
  const [retiringBankId, setRetiringBankId] = useState<string | null>(null)

  const fetchBanks = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/exams/internal/banks')
      const json = await res.json()
      if (json.data) setBanks(json.data)
    } catch {
      // silent
    } finally {
      setLoading(false)
    }
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchBanks() }, [fetchBanks])

  const copyStudentLink = async (bankId: string) => {
    const path = `/student/exams/internal?bankId=${bankId}`
    const href = typeof window !== 'undefined' ? `${window.location.origin}${path}` : path
    await navigator.clipboard.writeText(href)
    setCopiedId(bankId)
    window.setTimeout(() => setCopiedId(current => current === bankId ? null : current), 1800)
  }

  const retireBank = async (bankId: string) => {
    if (!confirm('Retire this bank? It will no longer be available for exams but existing sessions will be preserved.')) return
    try {
      await fetch(`/api/staff/exams/internal/banks/${bankId}/retire`, { method: 'POST' })
      fetchBanks()
    } finally {
      setRetiringBankId(null)
    }
  }

  const totalQuestions = banks.reduce((s, b) => s + b._count.questions, 0)
  const totalSessions = banks.reduce((s, b) => s + b._count.sessions, 0)
  const healthyCounts = { GREEN: 0, AMBER: 0, RED: 0 }
  banks.forEach(b => healthyCounts[b.poolHealth.health]++)

  useEffect(() => {
    if (showCreateModal && courses.length === 0) {
      fetch('/api/staff/courses?limit=100')
        .then((r) => r.json())
        .then((j) => {
          if (j.data) setCourses(j.data)
        })
        .catch(() => {})
    }
  }, [showCreateModal, courses.length])

  useEffect(() => {
    if (createForm.courseId) {
      fetch(`/api/staff/courses/${createForm.courseId}/exam-components`)
        .then((r) => r.json())
        .then((j) => {
          if (j.data) setModules(j.data)
        })
        .catch(() => setModules([]))
  // eslint-disable-next-line react-hooks/set-state-in-effect
    } else {
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setModules([])
    }
  }, [createForm.courseId])

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-8 w-8 animate-spin text-aerojet-blue" />
      </div>
    )
  }

  return (
    <>
    <div className="space-y-6">
      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <div className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900">
          <BookOpen className="h-5 w-5 text-aerojet-blue" />
          <p className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">{banks.length}</p>
          <p className="text-xs text-slate-500">Exam Banks</p>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900">
          <FileQuestion className="h-5 w-5 text-purple-600" />
          <p className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">{totalQuestions}</p>
          <p className="text-xs text-slate-500">Total Questions</p>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900">
          <Users className="h-5 w-5 text-cyan-600" />
          <p className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">{totalSessions}</p>
          <p className="text-xs text-slate-500">Total Sessions</p>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900">
          <BarChart3 className="h-5 w-5 text-amber-600" />
          <p className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">
            <span className="text-green-600">{healthyCounts.GREEN}</span>
            {' / '}
            <span className="text-amber-600">{healthyCounts.AMBER}</span>
            {' / '}
            <span className="text-red-600">{healthyCounts.RED}</span>
          </p>
          <p className="text-xs text-slate-500">Pool Health (G/A/R)</p>
        </div>
      </div>

      {/* Create Bank Button */}
      <button
        onClick={() => setShowCreateModal(true)}
        className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white shadow-sm transition-all hover:bg-blue-700"
      >
        <Plus className="h-4 w-4" />
        Create New Bank
      </button>

      {/* Bank List */}
      {banks.length === 0 ? (
        <div className="rounded-xl border border-slate-200 bg-white p-12 text-center dark:border-slate-800 dark:bg-slate-900">
          <BookOpen className="mx-auto mb-4 h-12 w-12 text-slate-300" />
          <p className="font-bold text-slate-500">No exam banks created yet.</p>
          <p className="mt-1 text-sm text-slate-400">Create your first question bank to get started.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {banks.map(bank => {
            const health = HEALTH_CONFIG[bank.poolHealth.health]
            const expanded = expandedId === bank.id
            const fillPct = Math.min(100, Math.round((bank.poolHealth.questionCount / bank.poolHealth.requiredMinimum) * 100))

            return (
              <div key={bank.id} className="rounded-xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
                <button
                  onClick={() => setExpandedId(expanded ? null : bank.id)}
                  className="flex w-full items-center justify-between p-5 text-left"
                >
                  <div className="flex items-center gap-4">
                    <div className={`flex h-10 w-10 items-center justify-center rounded-lg ${health.bg}`}>
                      {bank.poolHealth.health === 'GREEN' ? (
                        <CheckCircle2 className={`h-5 w-5 ${health.color}`} />
                      ) : (
                        <AlertTriangle className={`h-5 w-5 ${health.color}`} />
                      )}
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-900 dark:text-white">{bank.name}</h3>
                      <p className="text-xs text-slate-500">
                        {bank.course.code} â€¢ {bank.mcqCount} MCQs â€¢ {bank.ruleSet}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${health.bg} ${health.color}`}>
                      {health.label} ({bank.poolHealth.questionCount}/{bank.poolHealth.requiredMinimum})
                    </span>
                    {(() => {
                      const rs = REVIEW_STATE_CONFIG[bank.reviewState] || REVIEW_STATE_CONFIG.DRAFT
                      return (
                        <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${rs.bg} ${rs.color}`}>
                          {rs.label}
                        </span>
                      )
                    })()}
                    {bank.pendingCount > 0 && (
                      <span className="rounded-full bg-indigo-100 px-2.5 py-1 text-xs font-bold text-indigo-700 dark:bg-indigo-900/50 dark:text-indigo-300">
                        {bank.pendingCount} Pending
                      </span>
                    )}
                    <span className="hidden sm:inline text-xs text-slate-400">{bank._count.sessions} sessions</span>
                    <ChevronRight className={`h-4 w-4 text-slate-400 transition-transform ${expanded ? 'rotate-90' : ''}`} />
                  </div>
                </button>

                {expanded && (
                  <div className="border-t border-slate-100 p-5 dark:border-slate-800">
                    <div className="mb-4 flex flex-wrap gap-2">
                      <Link
                        href={`/staff/exams/internal/banks/${bank.id}/questions`}
                        className="inline-flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2 text-xs font-bold text-white hover:bg-blue-700"
                      >
                        <FileQuestion className="h-3 w-3" />
                        Manage Questions
                      </Link>
                      <Link
                        href={`/staff/exams/internal/banks/${bank.id}/schedule`}
                        className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200"
                      >
                        Schedule Exam
                      </Link>
                      <Link
                        href={`/staff/exams/internal/banks/${bank.id}/instructors`}
                        className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200"
                      >
                        Assign Instructors
                      </Link>
                    </div>
                    <div className="grid gap-4 sm:grid-cols-2">
                      <div>
                        <h4 className="mb-2 text-xs font-bold uppercase tracking-widest text-slate-400">Pool Health</h4>
                        <div className="rounded-lg bg-slate-50 p-3 dark:bg-slate-800">
                          <div className="mb-1 flex justify-between text-sm">
                            <span className="text-slate-600 dark:text-slate-400">Question Pool</span>
                            <span className="font-bold text-slate-900 dark:text-white">{fillPct}%</span>
                          </div>
                          <div className="h-2.5 rounded-full bg-slate-200 dark:bg-slate-700">
                            <div
                              className={`h-full rounded-full transition-all ${
                                bank.poolHealth.health === 'GREEN' ? 'bg-green-500' :
                                bank.poolHealth.health === 'AMBER' ? 'bg-amber-500' : 'bg-red-500'
                              }`}
                              style={{ width: `${fillPct}%` }}
                            />
                          </div>
                          <p className="mt-1 text-xs text-slate-500">
                            {bank.poolHealth.questionCount} questions / {bank.poolHealth.requiredMinimum} required (5Ã— exam size)
                          </p>
                        </div>
                      </div>
                      <div>
                        <div className="mb-2 flex items-center justify-between">
                          <h4 className="text-xs font-bold uppercase tracking-widest text-slate-400">Rules</h4>
                          <button
                            onClick={() => {
                              setEditingRulesBankId(bank.id)
                              setRulesForm({
                                passMarkPct: bank.ruleOverride?.passMarkPct ?? 75,
                                timePerQuestionSecs: bank.ruleOverride?.timePerQuestionSecs ?? 75,
                                retakeWaitDays: bank.ruleOverride?.retakeWaitDays ?? 90,
                                maxRetakes: bank.ruleOverride?.maxRetakes ?? 3,
                                completionWindowYears: bank.ruleOverride?.completionWindowYears ?? 10,
                                allowKeyboardAutoSubmit: bank.ruleOverride?.allowKeyboardAutoSubmit ?? true,
                                customInstructions: bank.ruleOverride?.customInstructions ?? '',
                                mcqCount: bank.mcqCount,
                              })
                            }}
                            className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-bold text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                          >
                            <Edit3 className="h-3 w-3" />
                            Edit
                          </button>
                        </div>
                        <div className="space-y-1 text-sm">
                          <div className="flex justify-between">
                            <span className="text-slate-500">Pass Mark</span>
                            <span className="font-medium">{bank.ruleOverride?.passMarkPct ?? 75}%</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-slate-500">Time/Question</span>
                            <span className="font-medium">{bank.ruleOverride?.timePerQuestionSecs ?? 75}s</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-slate-500">Retake Wait</span>
                            <span className="font-medium">{bank.ruleOverride?.retakeWaitDays ?? 90} days</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-slate-500">Max Attempts</span>
                            <span className="font-medium">{bank.ruleOverride?.maxRetakes ?? 3}</span>
                          </div>
                        </div>
                      </div>
                      <div className="sm:col-span-2">
                        <h4 className="mb-2 text-xs font-bold uppercase tracking-widest text-slate-400">Student Access</h4>
                        <div className="flex flex-col gap-3 rounded-lg border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-800 sm:flex-row sm:items-center sm:justify-between">
                          <p className="text-sm text-slate-600 dark:text-slate-300">
                            Share this link with students enrolled in {bank.course.code}. Portal role and enrollment checks still apply before a student can start.
                          </p>
                          <button
                            type="button"
                            onClick={() => copyStudentLink(bank.id)}
                            className="inline-flex shrink-0 items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800"
                          >
                            <Copy className="h-3.5 w-3.5" />
                            {copiedId === bank.id ? 'Copied' : 'Copy Link'}
                          </button>
                        </div>
                      </div>
                      
                      {bank.pendingCount > 0 && (
                        <div className="sm:col-span-2 mt-4">
                          <h4 className="mb-2 text-xs font-bold uppercase tracking-widest text-indigo-600 dark:text-indigo-400">Pending Review ({bank.pendingCount})</h4>
                          <ApprovalQueue bankId={bank.id} />
                        </div>
                      )}

                      <div className="sm:col-span-2 mt-4 flex justify-end border-t border-slate-100 pt-4 dark:border-slate-800">
                        <button
                          onClick={() => retireBank(bank.id)}
                          className="flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-bold text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                        >
                          <Archive className="h-3 w-3" />
                          Retire Bank
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>

    {/* Rules Editing Modal */}
    {editingRulesBankId && (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
        <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Edit Exam Rules</h3>
            <button
              onClick={() => setEditingRulesBankId(null)}
              className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
          <p className="mt-1 text-sm text-slate-500">
            Configure exam rules. EASA standard is 75s/question â€” reduce to sharpen students for final exams.
          </p>

          <div className="mt-6 space-y-4">
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Questions per exam
              </label>
              <input
                type="number"
                min={5}
                max={200}
                value={rulesForm.mcqCount}
                onChange={(e) => setRulesForm({ ...rulesForm, mcqCount: Number(e.target.value) })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Time per question (seconds)
              </label>
              <input
                type="number"
                min={10}
                max={300}
                value={rulesForm.timePerQuestionSecs}
                onChange={(e) => setRulesForm({ ...rulesForm, timePerQuestionSecs: Number(e.target.value) })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
              <p className="mt-1 text-xs text-slate-400">EASA standard: 75s. Lower = more challenging.</p>
            </div>

            <div className="rounded-xl bg-blue-50 p-4 dark:bg-blue-900/10">
              <div className="flex items-center gap-3">
                <Clock className="h-8 w-8 text-blue-600" />
                <div>
                  <p className="text-xs font-bold uppercase tracking-widest text-blue-600">Total Exam Duration</p>
                  <p className="text-2xl font-black text-slate-900 dark:text-white">
                    {Math.round((rulesForm.timePerQuestionSecs * rulesForm.mcqCount) / 60)} minutes
                  </p>
                  <p className="text-xs text-slate-500">
                    {rulesForm.mcqCount} questions Ã— {rulesForm.timePerQuestionSecs} seconds
                  </p>
                </div>
              </div>
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Pass mark (%)
              </label>
              <input
                type="number"
                min={0}
                max={100}
                value={rulesForm.passMarkPct}
                onChange={(e) => setRulesForm({ ...rulesForm, passMarkPct: Number(e.target.value) })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Retake wait (days)
              </label>
              <input
                type="number"
                min={0}
                max={365}
                value={rulesForm.retakeWaitDays}
                onChange={(e) => setRulesForm({ ...rulesForm, retakeWaitDays: Number(e.target.value) })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Max attempts
              </label>
              <input
                type="number"
                min={1}
                max={10}
                value={rulesForm.maxRetakes}
                onChange={(e) => setRulesForm({ ...rulesForm, maxRetakes: Number(e.target.value) })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm text-slate-700 dark:text-slate-300">
                <input
                  type="checkbox"
                  checked={rulesForm.allowKeyboardAutoSubmit}
                  onChange={(e) => setRulesForm({ ...rulesForm, allowKeyboardAutoSubmit: e.target.checked })}
                  className="h-4 w-4 rounded border-slate-300 text-blue-600"
                />
                Allow keyboard auto-submit (any key press submits exam)
              </label>
            </div>
          </div>

          <div className="mt-6 flex gap-3">
            <button
              onClick={() => setEditingRulesBankId(null)}
              className="flex-1 rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300"
            >
              Cancel
            </button>
            <button
              onClick={async () => {
                setRulesSaving(true)
                try {
                  const res = await fetch(`/api/staff/exams/internal/banks/${editingRulesBankId}/rule-override`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(rulesForm),
                  })
                  if (res.ok) {
                    setEditingRulesBankId(null)
                    fetchBanks()
                  }
                } finally {
                  setRulesSaving(false)
                }
              }}
              disabled={rulesSaving}
              className="flex-1 rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-50"
            >
              {rulesSaving ? 'Saving...' : 'Save Rules'}
            </button>
          </div>
        </div>
      </div>
    )}

    {/* Create Bank Modal */}
    {showCreateModal && (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
        <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl dark:border-slate-700 dark:bg-slate-900">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Create New Exam Bank</h3>
            <button
              onClick={() => setShowCreateModal(false)}
              className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
          <p className="mt-1 text-sm text-slate-500">
            Create a new question bank for a course module.
          </p>

          <div className="mt-6 space-y-4">
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Course <span className="text-red-500">*</span>
              </label>
              <select
                value={createForm.courseId}
                onChange={(e) => setCreateForm({ ...createForm, courseId: e.target.value, moduleCode: '' })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              >
                <option value="">Select a course...</option>
                {courses.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.code} â€” {c.name}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Bank Name <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                placeholder="e.g. Module 1 â€” Air Law"
                value={createForm.name}
                onChange={(e) => setCreateForm({ ...createForm, name: e.target.value })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Module
              </label>
              <select
                value={createForm.moduleCode}
                onChange={(e) => setCreateForm({ ...createForm, moduleCode: e.target.value })}
                disabled={!createForm.courseId}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              >
                <option value="">Select a module...</option>
                {modules.map((m) => (
                  <option key={m.code} value={m.code}>
                    {m.code} â€” {m.name}
                  </option>
                ))}
              </select>
              {!createForm.courseId && (
                <p className="mt-1 text-xs text-slate-400">Select a course first to see its modules.</p>
              )}
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Questions per exam
              </label>
              <input
                type="number"
                min={1}
                value={createForm.mcqCount}
                onChange={(e) => setCreateForm({ ...createForm, mcqCount: Number(e.target.value) })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              />
              <p className="mt-1 text-xs text-slate-400">
                Recommended minimum: {createForm.mcqCount * 5} questions in pool (5Ã— exam size for {createForm.ruleSet} standard).
              </p>
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                Rule Set
              </label>
              <select
                value={createForm.ruleSet}
                onChange={(e) => setCreateForm({ ...createForm, ruleSet: e.target.value as 'EASA' | 'CUSTOM' })}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
              >
                <option value="EASA">EASA (default)</option>
                <option value="CUSTOM">Custom</option>
              </select>
            </div>
          </div>

          <div className="mt-6 flex gap-3">
            <button
              onClick={() => setShowCreateModal(false)}
              className="flex-1 rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300"
            >
              Cancel
            </button>
            <button
              onClick={async () => {
                if (!createForm.courseId || !createForm.name) return
                setCreateSaving(true)
                try {
                  const res = await fetch('/api/staff/exams/internal/banks', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(createForm),
                  })
                  if (res.ok) {
                    setShowCreateModal(false)
                    setCreateForm({ name: '', courseId: '', moduleCode: '', mcqCount: 40, ruleSet: 'EASA' })
                    fetchBanks()
                  }
                } finally {
                  setCreateSaving(false)
                }
              }}
              disabled={createSaving || !createForm.courseId || !createForm.name}
              className="flex-1 rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-50"
            >
              {createSaving ? 'Creating...' : 'Create Bank'}
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import {
  Loader2,
  RefreshCw,
  Eye,
  XCircle,
  CheckCircle2,
  Clock,
  AlertTriangle,
  Send,
  ChevronDown,
  ChevronRight,
  Flag,
  RotateCcw,
  Megaphone,
  Users,
  Activity,
  Hourglass,
  RefreshCcw,
  ShieldAlert,
  Award,
} from 'lucide-react'
import { TableSkeleton } from '@/components/shared/DashboardSkeleton'
import ViolationReviewPanel from './ViolationReviewPanel'
import ConfirmModal from './ConfirmModal'

interface StudentAnswer {
  id: string
  questionId: string
  questionText: string
  questionRef: string | null
  options: string[]
  correctAnswer: string
  selectedAnswer: string | null
  isCorrect: boolean | null
  points: number
  pointsAwarded: number | null
  answeredAt: string | null
}

interface Report {
  id: string
  reason: string
  status: string
  questionId: string | null
  questionRef: string | null
  createdAt: string
}

interface SessionData {
  id: string
  student: { id: string; name: string; email: string; studentId: string | null }
  bank: { id: string; name: string; moduleCode: string | null; courseCode: string }
  status: string
  startedAt: string | null
  expiresAt: string | null
  submittedAt: string | null
  score: number | null
  totalPoints: number | null
  percentage: number | null
  passed: boolean | null
  isPublished: boolean
  autoSubmitted: boolean | null
  voidedAt: string | null
  voidReason: string | null
  /** Total answer rows for the session (one per question). Cheap count. */
  answerCount: number
  reports: Report[]
  /** Violation count from the list endpoint â€” used for the tab badge. */
  violationCount?: number
  /** Full per-question detail â€” only populated after the row is expanded. */
  answers?: StudentAnswer[]
}

type TabKey = 'live' | 'review' | 'published' | 'voided'

export default function ExamOperations() {
  const [sessions, setSessions] = useState<SessionData[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<TabKey>('live')
  const [expandedSession, setExpandedSession] = useState<string | null>(null)
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [successMsg, setSuccessMsg] = useState<string | null>(null)
  const [violationsMap, setViolationsMap] = useState<Record<string, any[]>>({})
  const [violationsLoadingMap, setViolationsLoadingMap] = useState<Set<string>>(new Set())

  // Confirmation modal state
  const [confirmState, setConfirmState] = useState<{
    open: boolean
    title: string
    description: string
    confirmLabel: string
    variant: 'danger' | 'warning' | 'info'
    onConfirm: () => void
  }>({
    open: false,
    title: '',
    description: '',
    confirmLabel: 'Confirm',
    variant: 'info',
    onConfirm: () => {},
  })

  const fetchSessions = useCallback(async () => {
    setError(null)
    try {
      const res = await fetch('/api/staff/exams/internal/operations/sessions')
      const json = await res.json()
      if (json.success && json.data) {
        setSessions(json.data)
      } else {
        setError(json.error || 'Failed to load sessions')
      }
    } catch {
      setError('Could not connect to server')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchSessions()
  }, [fetchSessions])

  // Auto-refresh on the Live tab. Polls every 30s while the tab is visible
  // and pauses entirely when the admin's browser tab is hidden â€” same
  // pattern as `<Heartbeat>`. The slim list endpoint makes a 30s cadence
  // cheap even with several admins on the page.
  useEffect(() => {
    if (activeTab !== 'live') return
    let interval: ReturnType<typeof setInterval> | null = null
    const start = () => {
      if (interval != null) return
      interval = setInterval(fetchSessions, 30_000)
    }
    const stop = () => {
      if (interval != null) {
        clearInterval(interval)
        interval = null
      }
    }
    const onVisibility = () => {
      if (document.visibilityState === 'visible') {
        fetchSessions() // immediate refresh on return
        start()
      } else {
        stop()
      }
    }
    if (document.visibilityState === 'visible') start()
    document.addEventListener('visibilitychange', onVisibility)
    return () => {
      stop()
      document.removeEventListener('visibilitychange', onVisibility)
    }
  }, [activeTab, fetchSessions])

  // Lazy-fetch full answer detail for one session. The list endpoint
  // returns only counts + reports to keep the page payload small; this
  // is called the first time an admin expands a row.
  const fetchSessionDetail = useCallback(async (sessionId: string) => {
    try {
      const res = await fetch(`/api/staff/exams/internal/operations/sessions/${sessionId}`)
      const json = await res.json()
      if (!json.success || !json.data) return
      const detail = json.data as SessionData
      setSessions((prev) => prev.map((row) => (row.id === sessionId ? { ...row, ...detail } : row)))
    } catch {
      // Silent â€” the row stays at "Loadingâ€¦" until the next refresh
    }
  }, [])

  const fetchViolations = useCallback(async (sessionId: string) => {
    setViolationsLoadingMap((prev) => new Set([...prev, sessionId]))
    try {
      const res = await fetch(
        `/api/staff/exams/internal/sessions/${sessionId}/violations?limit=100`
      )
      const json = await res.json()
      if (json.success && json.data) {
        setViolationsMap((prev) => ({ ...prev, [sessionId]: json.data }))
      } else {
        setViolationsMap((prev) => ({ ...prev, [sessionId]: [] }))
      }
    } catch {
      setViolationsMap((prev) => ({ ...prev, [sessionId]: [] }))
    } finally {
      setViolationsLoadingMap((prev) => {
        const next = new Set(prev)
        next.delete(sessionId)
        return next
      })
    }
  }, [])

  const handleExpand = (sessionId: string) => {
    setExpandedSession((cur) => {
      const next = cur === sessionId ? null : sessionId
      if (next) {
        const row = sessions.find((s) => s.id === next)
        if (row && !row.answers) void fetchSessionDetail(next)
        if (row && !violationsMap[next]) void fetchViolations(next)
      }
      return next
    })
  }

  const handleVoid = async (sessionId: string) => {
    setConfirmState({
      open: true,
      title: 'Void this session?',
      description: 'The student will be able to retake the exam. This action cannot be undone.',
      confirmLabel: 'Void & Allow Retake',
      variant: 'danger',
      onConfirm: async () => {
        setConfirmState((prev) => ({ ...prev, open: false }))
        setActionLoading(sessionId)
        try {
          const res = await fetch('/api/staff/exams/internal/operations/void', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ sessionId, reason: 'Admin-initiated reset' }),
          })
          const json = await res.json()
          if (json.success) {
            setSuccessMsg('Session voided. Student can now retake.')
            setTimeout(() => setSuccessMsg(null), 4000)
            fetchSessions()
          } else {
            setError(json.error || 'Failed to void session')
          }
        } catch {
          setError('Action failed')
        } finally {
          setActionLoading(null)
        }
      },
    })
  }

  const handlePublish = async (sessionIds: string[]) => {
    setActionLoading(sessionIds[0])
    try {
      const res = await fetch('/api/staff/exams/internal/operations/publish', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionIds }),
      })
      const json = await res.json()
      if (json.success) {
        setSuccessMsg(`Published ${json.data.published} result(s) to students.`)
        setTimeout(() => setSuccessMsg(null), 4000)
        fetchSessions()
      } else {
        setError(json.error || 'Failed to publish')
      }
    } catch {
      setError('Action failed')
    } finally {
      setActionLoading(null)
    }
  }

  const handlePublishAll = async () => {
    const pending = filteredSessions('review')
    if (pending.length === 0) return
    setConfirmState({
      open: true,
      title: `Publish ${pending.length} result(s)?`,
      description:
        'This will make exam results visible to all pending students. This action cannot be undone.',
      confirmLabel: 'Publish All',
      variant: 'info',
      onConfirm: async () => {
        setConfirmState((prev) => ({ ...prev, open: false }))
        handlePublish(pending.map((s) => s.id))
      },
    })
  }

  const handleRegrade = async (sessionId: string) => {
    setConfirmState({
      open: true,
      title: 'Regrade this session?',
      description: 'This will recalculate the score against the current question bank answers.',
      confirmLabel: 'Regrade',
      variant: 'warning',
      onConfirm: async () => {
        setConfirmState((prev) => ({ ...prev, open: false }))
        setActionLoading(sessionId)
        try {
          const res = await fetch('/api/staff/exams/internal/operations/regrade', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ sessionIds: [sessionId] }),
          })
          const json = await res.json()
          if (json.success) {
            const detail = json.data.details?.[0]
            if (detail?.changed) {
              setSuccessMsg(`Regraded: ${detail.oldPct}% â†’ ${detail.newPct}%`)
            } else {
              setSuccessMsg('Regraded â€” no score change.')
            }
            setTimeout(() => setSuccessMsg(null), 5000)
            fetchSessions()
          } else {
            setError(json.error || 'Failed to regrade')
          }
        } catch {
          setError('Regrade failed')
        } finally {
          setActionLoading(null)
        }
      },
    })
  }

  const handleExtend = async (sessionId: string) => {
    setConfirmState({
      open: true,
      title: 'Extend exam time?',
      description: "This will add extra time to the student's exam session.",
      confirmLabel: 'Extend',
      variant: 'info',
      onConfirm: async () => {
        setConfirmState((prev) => ({ ...prev, open: false }))
        setActionLoading(sessionId)
        try {
          const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/extend`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ minutes: 5 }),
          })
          const json = await res.json()
          if (json.success) {
            setSuccessMsg('Time extended by 5 minutes')
            setTimeout(() => setSuccessMsg(null), 4000)
            fetchSessions()
          } else {
            setError(json.error || 'Failed to extend time')
          }
        } catch {
          setError('Action failed')
        } finally {
          setActionLoading(null)
        }
      },
    })
  }

  const handleForceSubmit = async (sessionId: string) => {
    setConfirmState({
      open: true,
      title: 'Force submit this exam?',
      description:
        'This will immediately submit the exam with whatever answers the student has saved.',
      confirmLabel: 'Force Submit',
      variant: 'warning',
      onConfirm: async () => {
        setConfirmState((prev) => ({ ...prev, open: false }))
        setActionLoading(sessionId)
        try {
          const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/force-submit`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
          })
          const json = await res.json()
          if (json.success) {
            setSuccessMsg('Exam force-submitted')
            setTimeout(() => setSuccessMsg(null), 4000)
            fetchSessions()
          } else {
            setError(json.error || 'Failed to force submit')
          }
        } catch {
          setError('Action failed')
        } finally {
          setActionLoading(null)
        }
      },
    })
  }

  const handleEndSession = async (sessionId: string) => {
    setConfirmState({
      open: true,
      title: 'End this exam session?',
      description: 'This will immediately end the session and auto-submit any saved answers.',
      confirmLabel: 'End Session',
      variant: 'danger',
      onConfirm: async () => {
        setConfirmState((prev) => ({ ...prev, open: false }))
        setActionLoading(sessionId)
        try {
          const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/end`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
          })
          const json = await res.json()
          if (json.success) {
            setSuccessMsg('Session ended')
            setTimeout(() => setSuccessMsg(null), 4000)
            fetchSessions()
          } else {
            setError(json.error || 'Failed to end session')
          }
        } catch {
          setError('Action failed')
        } finally {
          setActionLoading(null)
        }
      },
    })
  }

  const filteredSessions = (tab: TabKey): SessionData[] => {
    switch (tab) {
      case 'live':
        return sessions.filter((s) => s.status === 'IN_PROGRESS')
      case 'review':
        return sessions.filter(
          (s) => (s.status === 'COMPLETED' || s.status === 'TIMED_OUT') && !s.isPublished
        )
      case 'published':
        return sessions.filter((s) => s.isPublished)
      case 'voided':
        return sessions.filter((s) => s.status === 'VOIDED')
      default:
        return sessions
    }
  }

  const tabs: { key: TabKey; label: string; icon: React.ReactNode; count: number }[] = [
    {
      key: 'live',
      label: 'Live',
      icon: <Activity className="h-4 w-4" />,
      count: filteredSessions('live').length,
    },
    {
      key: 'review',
      label: 'Pending Review',
      icon: <Hourglass className="h-4 w-4" />,
      count: filteredSessions('review').length,
    },
    {
      key: 'published',
      label: 'Published',
      icon: <CheckCircle2 className="h-4 w-4" />,
      count: filteredSessions('published').length,
    },
    {
      key: 'voided',
      label: 'Voided',
      icon: <XCircle className="h-4 w-4" />,
      count: filteredSessions('voided').length,
    },
  ]

  const currentSessions = filteredSessions(activeTab)

  const getScoreColor = (pct: number | null) => {
    if (pct === null) return 'text-slate-400'
    if (pct >= 75) return 'text-green-600 dark:text-green-400'
    if (pct >= 50) return 'text-amber-600 dark:text-amber-400'
    return 'text-red-600 dark:text-red-400'
  }

  const getScoreBg = (pct: number | null) => {
    if (pct === null) return 'bg-slate-100 dark:bg-slate-800'
    if (pct >= 75) return 'bg-green-50 border-green-200 dark:bg-green-900/20 dark:border-green-800'
    if (pct >= 50) return 'bg-amber-50 border-amber-200 dark:bg-amber-900/20 dark:border-amber-800'
    return 'bg-red-50 border-red-200 dark:bg-red-900/20 dark:border-red-800'
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="text-aerojet-blue h-8 w-8 animate-spin" />
      </div>
    )
  }

  return (
    <>
      <div className="space-y-6">
        {/* Header Row */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-xl font-black text-slate-900 dark:text-white">Exam Operations</h2>
            <p className="text-sm text-slate-500">
              Monitor live exams, review results, and manage student sessions.
            </p>
          </div>
          <div className="flex gap-2">
            <button
              onClick={fetchSessions}
              className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
            >
              <RefreshCw className="h-3.5 w-3.5" />
              Refresh
            </button>
            {activeTab === 'review' && filteredSessions('review').length > 0 && (
              <button
                onClick={handlePublishAll}
                className="flex items-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-xs font-bold text-white hover:bg-green-700"
              >
                <Megaphone className="h-3.5 w-3.5" />
                Publish All ({filteredSessions('review').length})
              </button>
            )}
          </div>
        </div>

        {/* Feedback messages */}
        {error && (
          <div className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-200">
            <div className="flex items-center gap-2">
              <XCircle className="h-4 w-4 shrink-0" />
              {error}
            </div>
          </div>
        )}
        {successMsg && (
          <div className="rounded-xl border border-green-200 bg-green-50 p-3 text-sm text-green-700 dark:border-green-900/60 dark:bg-green-950/30 dark:text-green-200">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 shrink-0" />
              {successMsg}
            </div>
          </div>
        )}

        {/* Tabs */}
        <div className="flex gap-1 rounded-xl border border-slate-200 bg-slate-100 p-1 dark:border-slate-700 dark:bg-slate-800">
          {tabs.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex items-center gap-2 rounded-lg px-4 py-2 text-xs font-bold transition-all ${
                activeTab === tab.key
                  ? 'bg-white text-slate-900 shadow-sm dark:bg-slate-900 dark:text-white'
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
              }`}
            >
              {tab.icon}
              {tab.label}
              {tab.count > 0 && (
                <span
                  className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold ${
                    activeTab === tab.key
                      ? tab.key === 'live'
                        ? 'bg-green-100 text-green-700'
                        : 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300'
                      : 'bg-slate-200 text-slate-500 dark:bg-slate-700 dark:text-slate-400'
                  }`}
                >
                  {tab.count}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Live indicator */}
        {activeTab === 'live' && (
          <div className="flex items-center gap-2 text-xs text-slate-500">
            <span className="relative flex h-2.5 w-2.5">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-green-400 opacity-75" />
              <span className="relative inline-flex h-2.5 w-2.5 rounded-full bg-green-500" />
            </span>
            Auto-refreshing every 15 seconds
          </div>
        )}

        {/* Sessions List */}
        {currentSessions.length === 0 ? (
          <div className="rounded-xl border border-slate-200 bg-white p-12 text-center dark:border-slate-800 dark:bg-slate-900">
            <Users className="mx-auto mb-3 h-10 w-10 text-slate-300 dark:text-slate-600" />
            <p className="font-bold text-slate-500">No sessions in this category</p>
          </div>
        ) : (
          <div className="space-y-3">
            {currentSessions.map((session) => {
              const isExpanded = expandedSession === session.id
              // Counts available without fetching answer detail; the detailed
              // per-question breakdown lives in `session.answers` once the row
              // has been expanded at least once.
              const answeredCount = session.answers
                ? session.answers.filter((a) => a.selectedAnswer !== null).length
                : null
              const totalQuestions = session.answerCount
              const hasReports = session.reports.length > 0
              const pendingReports = session.reports.filter((r) => r.status === 'PENDING')

              return (
                <div
                  key={session.id}
                  className="rounded-xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900"
                >
                  {/* Session Header */}
                  <button
                    onClick={() => handleExpand(session.id)}
                    className="flex w-full items-center gap-4 p-4 text-left transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50"
                  >
                    {/* Score Badge */}
                    <div
                      className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-xl border text-sm font-black ${getScoreBg(session.percentage)}`}
                    >
                      <span className={getScoreColor(session.percentage)}>
                        {session.percentage !== null ? `${session.percentage}%` : 'â€”'}
                      </span>
                    </div>

                    {/* Student Info */}
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <span className="truncate font-bold text-slate-900 dark:text-white">
                          {session.student.name}
                        </span>
                        {hasReports && (
                          <span className="rounded-full bg-red-100 px-1.5 py-0.5 text-[10px] font-bold text-red-700 dark:bg-red-900/30 dark:text-red-300">
                            <Flag className="mr-0.5 inline h-2.5 w-2.5" />
                            {pendingReports.length > 0 ? pendingReports.length : 'reported'}
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-slate-500">
                        {session.bank.courseCode} Â· {session.bank.moduleCode || session.bank.name}
                        {session.student.studentId && ` Â· ${session.student.studentId}`}
                        {session.status === 'IN_PROGRESS' &&
                          (answeredCount !== null
                            ? ` Â· ${answeredCount}/${totalQuestions} answered`
                            : ` Â· ${totalQuestions} questions`)}
                      </p>
                    </div>

                    {/* Status / Time */}
                    <div className="hidden text-right sm:block">
                      {session.status === 'IN_PROGRESS' && session.expiresAt && (
                        <div className="text-xs font-bold text-green-600">
                          <Clock className="mr-1 inline h-3 w-3" />
                          Expires {new Date(session.expiresAt).toLocaleTimeString()}
                        </div>
                      )}
                      {session.submittedAt && (
                        <div className="text-xs text-slate-400">
                          Submitted {new Date(session.submittedAt).toLocaleString()}
                        </div>
                      )}
                    </div>

                    {/* Expand chevron */}
                    {isExpanded ? (
                      <ChevronDown className="h-4 w-4 text-slate-400" />
                    ) : (
                      <ChevronRight className="h-4 w-4 text-slate-400" />
                    )}
                  </button>

                  {/* Expanded Detail */}
                  {isExpanded && (
                    <div className="border-t border-slate-100 bg-slate-50 p-4 dark:border-slate-800 dark:bg-slate-800/30">
