                        <div className="rounded-lg border border-slate-200 bg-white p-3 text-center dark:border-slate-700 dark:bg-slate-900">
                          <p className={`text-lg font-black ${getScoreColor(session.percentage)}`}>
                            {session.percentage ?? 'â€”'}%
