                              Violations
                            </h4>
                          </div>
                          {violationsLoadingMap.has(session.id) ? (
                            <TableSkeleton rows={4} />
                          ) : (
                            <ViolationReviewPanel
                              sessionId={session.id}
                              violations={violationsMap[session.id] ?? []}
                            />
                          )}
                        </div>
                      )}

                      {/* Actions */}
                      <div className="flex flex-wrap gap-2">
                        {(session.status === 'COMPLETED' ||
                          session.status === 'TIMED_OUT' ||
                          session.status === 'IN_PROGRESS') && (
                          <button
                            onClick={() => handleVoid(session.id)}
                            disabled={actionLoading === session.id}
                            className="flex items-center gap-1.5 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs font-bold text-red-700 hover:bg-red-100 disabled:opacity-50 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300"
                          >
                            {actionLoading === session.id ? (
                              <Loader2 className="h-3 w-3 animate-spin" />
                            ) : (
                              <RotateCcw className="h-3 w-3" />
                            )}
                            Void & Allow Retake
                          </button>
                        )}
                        {(session.status === 'COMPLETED' || session.status === 'TIMED_OUT') &&
                          !session.isPublished && (
                            <button
                              onClick={() => {
                                setConfirmState({
                                  open: true,
                                  title: 'Publish this result?',
                                  description:
                                    'This will make the exam result visible to the student. This action cannot be undone.',
                                  confirmLabel: 'Publish',
                                  variant: 'info',
                                  onConfirm: async () => {
                                    setConfirmState((prev) => ({ ...prev, open: false }))
                                    handlePublish([session.id])
                                  },
                                })
                              }}
                              disabled={actionLoading === session.id}
                              className="flex items-center gap-1.5 rounded-lg bg-green-600 px-3 py-2 text-xs font-bold text-white hover:bg-green-700 disabled:opacity-50"
                            >
                              {actionLoading === session.id ? (
                                <Loader2 className="h-3 w-3 animate-spin" />
                              ) : (
                                <Megaphone className="h-3 w-3" />
                              )}
                              Publish Results
                            </button>
                          )}
                        {(session.status === 'COMPLETED' || session.status === 'TIMED_OUT') &&
                          !session.isPublished && (
                            <button
                              onClick={() => handleRegrade(session.id)}
                              disabled={actionLoading === session.id}
                              className="flex items-center gap-1.5 rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 text-xs font-bold text-blue-700 hover:bg-blue-100 disabled:opacity-50 dark:border-blue-800 dark:bg-blue-900/20 dark:text-blue-300"
                            >
                              {actionLoading === session.id ? (
                                <Loader2 className="h-3 w-3 animate-spin" />
                              ) : (
                                <RefreshCcw className="h-3 w-3" />
                              )}
                              Regrade
                            </button>
                          )}
                        {session.isPublished && (
                          <span className="flex items-center gap-1.5 rounded-lg bg-green-50 px-3 py-2 text-xs font-bold text-green-700 dark:bg-green-900/20 dark:text-green-300">
                            <CheckCircle2 className="h-3 w-3" />
                            Published
                          </span>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </div>

      <ConfirmModal
        open={confirmState.open}
        title={confirmState.title}
        description={confirmState.description}
        confirmLabel={confirmState.confirmLabel}
        variant={confirmState.variant}
        loading={actionLoading !== null}
        onConfirm={confirmState.onConfirm}
        onCancel={() => setConfirmState((prev) => ({ ...prev, open: false }))}
      />
    </>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { History, User, Calendar, Tag, ArrowRight, X } from 'lucide-react'

interface Version {
  id: string
  version: number
  text: string
  options: string[]
  correctAnswer: string
  points: number
  difficulty: string
  changeType: string
  changeReason: string | null
  changedAt: string
  changer: {
    id: string
    email: string
    profile: { firstName: string | null; lastName: string | null } | null
  } | null
}

export default function QuestionVersions({ questionId }: { questionId: string }) {
  const [versions, setVersions] = useState<Version[]>([])
  const [loading, setLoading] = useState(true)
  const [expanded, setExpanded] = useState(false)

  const fetchVersions = async () => {
    try {
      const res = await fetch(`/api/staff/exams/internal/questions/${questionId}/versions`)
      const json = await res.json()
      if (json.data) setVersions(json.data)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (expanded) fetchVersions()
  }, [expanded, questionId])

  if (!expanded) {
    return (
      <button
        onClick={() => setExpanded(true)}
        className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-bold text-slate-600 hover:border-aerojet-blue hover:text-aerojet-blue dark:border-slate-700 dark:text-slate-300"
      >
        <History className="h-3.5 w-3.5" />
        View History
      </button>
    )
  }

  return (
    <div className="mt-4 rounded-xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800">
      <div className="mb-3 flex items-center justify-between">
        <h4 className="text-xs font-black uppercase tracking-widest text-slate-500">Version History</h4>
        <button
          onClick={() => setExpanded(false)}
          className="flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-slate-700"
          aria-label="Close version history"
        >
          <X className="h-4 w-4" />
        </button>
      </div>
      {loading ? (
        <div className="flex justify-center py-4">
          <History className="h-5 w-5 animate-spin text-aerojet-blue" />
        </div>
      ) : versions.length === 0 ? (
        <p className="py-4 text-center text-xs text-slate-400">No version history available.</p>
      ) : (
        <div className="space-y-3">
          {versions.map((v, i) => (
            <div
              key={v.id}
              className="rounded-lg border border-slate-100 bg-white p-3 dark:border-slate-700 dark:bg-slate-900"
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="rounded bg-aerojet-blue/10 px-2 py-0.5 text-xs font-bold text-aerojet-blue">
                    v{v.version}
                  </span>
                  <span className="rounded bg-slate-100 px-2 py-0.5 text-xs font-bold text-slate-600 dark:bg-slate-700 dark:text-slate-300">
                    {v.changeType}
                  </span>
                </div>
                <span className="flex items-center gap-1 text-xs text-slate-400">
                  <Calendar className="h-3 w-3" />
                  {new Date(v.changedAt).toLocaleString('en-GB')}
                </span>
              </div>
              {v.changeReason && (
                <p className="mt-2 text-xs text-slate-500">{v.changeReason}</p>
              )}
              <div className="mt-2 text-xs text-slate-600 dark:text-slate-400">
                <p><span className="font-bold">Text:</span> {v.text}</p>
                <p><span className="font-bold">Options:</span> {JSON.stringify(v.options)}</p>
                <p><span className="font-bold">Answer:</span> {v.correctAnswer}</p>
                <p><span className="font-bold">Points:</span> {v.points} | <span className="font-bold">Difficulty:</span> {v.difficulty}</p>
              </div>
              <div className="mt-2 flex items-center gap-1 text-xs text-slate-400">
                <User className="h-3 w-3" />
                {v.changer?.profile ? `${v.changer.profile.firstName} ${v.changer.profile.lastName}` : v.changer?.email || 'Unknown'}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import {
  ShieldAlert,
  Clock,
  CheckCircle2,
  XCircle,
  AlertCircle,
  Send,
} from 'lucide-react'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'
import { TableSkeleton } from '@/components/shared/DashboardSkeleton'

export interface Violation {
  id: string
  type: string
  severity: 'WARNING' | 'NOTICE' | 'CRITICAL'
  detail: string | null
  deviceInfo: Record<string, unknown> | null
  reviewOutcome: 'PENDING' | 'GRACIOUS' | 'STRICT' | 'DISMISSED'
  reviewNote: string | null
  reviewedAt: string | null
  reviewedBy: string | null
  createdAt: string
  student: { id: string; name: string; email: string }
}

interface ViolationReviewPanelProps {
  sessionId: string
  violations: Violation[]
}

const SEVERITY_LABELS: Record<string, { label: string; Icon: React.ComponentType<{ className?: string }> }> = {
  WARNING: { label: 'Warning', Icon: AlertCircle },
  NOTICE: { label: 'Notice', Icon: ShieldAlert },
  CRITICAL: { label: 'Critical', Icon: ShieldAlert },
}

const VIOLATION_TYPE_LABELS: Record<string, string> = {
  FULLSCREEN_EXIT: 'Fullscreen Exit',
  TAB_SWITCH: 'Tab Switch',
  KEYBOARD_SHORTCUT: 'Keyboard Shortcut',
  NETWORK_DISCONNECT: 'Network Disconnect',
  EXAM_INTERFACE_UNLOAD: 'Exam Interface Unload',
}

function SeverityBadge({ severity }: { severity: Violation['severity'] }) {
  const config: Record<Violation['severity'], string> = {
    WARNING: 'bg-amber-100 text-amber-800 border-amber-200 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-800',
    NOTICE: 'bg-orange-100 text-orange-800 border-orange-200 dark:bg-orange-900/30 dark:text-orange-300 dark:border-orange-800',
    CRITICAL: 'bg-red-100 text-red-800 border-red-200 dark:bg-red-900/30 dark:text-red-300 dark:border-red-800',
  }
  const { Icon } = SEVERITY_LABELS[severity] || { Icon: AlertCircle }
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-bold ${config[severity]}`}
    >
      <Icon className="h-3 w-3" />
      {SEVERITY_LABELS[severity]?.label ?? severity}
    </span>
  )
}

function ReviewStatusBadge({ outcome }: { outcome: Violation['reviewOutcome'] }) {
  const config: Record<Violation['reviewOutcome'], string> = {
    PENDING: 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700',
    GRACIOUS: 'bg-green-100 text-green-700 border-green-200 dark:bg-green-900/30 dark:text-green-300 dark:border-green-800',
    STRICT: 'bg-red-100 text-red-700 border-red-200 dark:bg-red-900/30 dark:text-red-300 dark:border-red-800',
    DISMISSED: 'bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800',
  }
  const label = outcome === 'PENDING' ? 'Pending Review' : outcome.charAt(0).toUpperCase() + outcome.slice(1).toLowerCase()
  return (
    <span
      className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-bold ${config[outcome]}`}
    >
      {label}
    </span>
  )
}

export default function ViolationReviewPanel({ sessionId, violations }: ViolationReviewPanelProps) {
  const [items, setItems] = useState<Violation[]>(violations)
  const [loadingIds, setLoadingIds] = useState<Set<string>>(new Set())
  const [bulkLoading, setBulkLoading] = useState(false)

  const [confirmState, setConfirmState] = useState<{
    open: boolean
    title: string
    description: string
    confirmLabel: string
    onConfirm: () => void
  }>({ open: false, title: '', description: '', confirmLabel: 'Confirm', onConfirm: () => {} })

  const pendingCount = items.filter((v) => v.reviewOutcome === 'PENDING').length
  const criticalCount = items.filter((v) => v.severity === 'CRITICAL').length

  const patchOutcome = async (ids: string[], outcome: Violation['reviewOutcome'], note?: string) => {
    if (ids.length === 0) return
    const key = ids.join(',')
    setLoadingIds((prev) => new Set([...prev, key]))
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/violations`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ violationIds: ids, outcome, reviewNote: note }),
      })
      const json = await res.json()
      if (json.success) {
        setItems((prev) =>
          prev.map((v) =>
            ids.includes(v.id) ? { ...v, reviewOutcome: outcome, reviewNote: note || v.reviewNote } : v
          )
        )
      } else {
        alert(json.error || 'Failed to update outcome')
      }
    } catch {
      alert('Failed to update outcome')
    } finally {
      setLoadingIds((prev) => {
        const next = new Set(prev)
        next.delete(key)
        return next
      })
    }
  }

  const handleOutcome = (violationId: string, outcome: Violation['reviewOutcome']) => {
    if (outcome === 'STRICT') {
      // End Exam Now — confirm destructive action
      setConfirmState({
        open: true,
        title: 'End Exam Now?',
        description: 'This will immediately terminate the student\'s exam session and auto-submit all answers. This action cannot be undone.',
        confirmLabel: 'End Exam',
        onConfirm: () => forceEndExam(),
      })
    } else {
      patchOutcome([violationId], outcome)
    }
  }

  const forceEndExam = async () => {
    setConfirmState((prev) => ({ ...prev, open: false }))
    setBulkLoading(true)
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/end`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: 'Terminated via violation review — STRICT outcome' }),
      })
      const json = await res.json()
      if (json.success) {
        // Mark all pending violations as STRICT
        const pendingIds = items.filter((v) => v.reviewOutcome === 'PENDING').map((v) => v.id)
        if (pendingIds.length > 0) {
          await patchOutcome(pendingIds, 'STRICT', 'Session force-ended by admin')
        }
        alert('Exam ended and submitted. Student notified.')
      } else {
        alert(json.error || 'Failed to end exam')
      }
    } catch {
      alert('Failed to end exam')
    } finally {
      setBulkLoading(false)
    }
  }

  const handleBulk = (outcome: Violation['reviewOutcome']) => {
    const pendingIds = items.filter((v) => v.reviewOutcome === 'PENDING').map((v) => v.id)
    if (pendingIds.length === 0) return

    if (outcome === 'STRICT') {
      setConfirmState({
        open: true,
        title: `End Exam & Mark ${pendingIds.length} violation(s) as Strict?`,
        description: 'This will immediately terminate the student\'s exam session and auto-submit all answers. This action cannot be undone.',
        confirmLabel: 'End Exam',
        onConfirm: async () => {
          setConfirmState((prev) => ({ ...prev, open: false }))
          await forceEndExam()
        },
      })
    } else if (outcome === 'DISMISSED') {
      setConfirmState({
        open: true,
        title: `Dismiss ${pendingIds.length} violation(s)?`,
        description: 'These violations will be marked as dismissed and will not affect the exam outcome.',
        confirmLabel: 'Dismiss All',
        onConfirm: async () => {
          setConfirmState((prev) => ({ ...prev, open: false }))
          await patchOutcome(pendingIds, 'DISMISSED', 'Dismissed in bulk by admin')
        },
      })
    } else {
      setConfirmState({
        open: true,
        title: `Allow Continue for ${pendingIds.length} violation(s)?`,
        description: 'These violations will be marked as GRACIOUS — the student may continue without penalty.',
        confirmLabel: 'Allow Continue',
        onConfirm: async () => {
          setConfirmState((prev) => ({ ...prev, open: false }))
          await patchOutcome(pendingIds, 'GRACIOUS', 'Allowed to continue in bulk by admin')
        },
      })
    }
  }

  const isLoading = (id: string) => loadingIds.has(id)

  if (items.length === 0) {
    return (
      <div className="text-center py-8 text-sm text-slate-500">
        <ShieldAlert className="mx-auto mb-2 h-6 w-6 opacity-50" />
        No violations recorded for this session.
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Summary + Bulk Actions */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-4 text-sm">
          <div className="flex items-center gap-1.5">
            <span className="font-bold text-slate-900 dark:text-white">{items.length}</span>
            <span className="text-slate-500">total violations</span>
          </div>
          {pendingCount > 0 && (
            <div className="flex items-center gap-1.5">
              <span className="font-bold text-amber-600">{pendingCount}</span>
              <span className="text-slate-500">pending review</span>
            </div>
          )}
          {criticalCount > 0 && (
            <div className="flex items-center gap-1.5">
              <span className="font-bold text-red-600">{criticalCount}</span>
              <span className="text-slate-500">critical</span>
            </div>
          )}
        </div>

        {pendingCount > 0 && (
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => handleBulk('DISMISSED')}
              disabled={bulkLoading}
              className="flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
            >
              <XCircle className="h-3 w-3" />
              Dismiss All
            </button>
            <button
              onClick={() => handleBulk('GRACIOUS')}
              disabled={bulkLoading}
              className="flex items-center gap-1.5 rounded-lg border border-green-200 bg-white px-3 py-2 text-xs font-bold text-green-700 hover:bg-green-50 disabled:opacity-50 dark:border-green-800 dark:bg-green-900/20"
            >
              <CheckCircle2 className="h-3 w-3" />
              Allow Continue
            </button>
            <button
              onClick={() => handleBulk('STRICT')}
              disabled={bulkLoading}
              className="flex items-center gap-1.5 rounded-lg border border-red-200 bg-white px-3 py-2 text-xs font-bold text-red-700 hover:bg-red-50 disabled:opacity-50 dark:border-red-800 dark:bg-red-900/20"
            >
              <Send className="h-3 w-3" />
              End Exam
            </button>
          </div>
        )}
      </div>

      {/* Violations Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-slate-200 dark:border-slate-700">
              <th className="px-3 py-2 text-left font-bold text-slate-400">Time</th>
              <th className="px-3 py-2 text-left font-bold text-slate-400">Type</th>
              <th className="px-3 py-2 text-left font-bold text-slate-400">Severity</th>
              <th className="px-3 py-2 text-left font-bold text-slate-400">Detail</th>
              <th className="px-3 py-2 text-left font-bold text-slate-400">Status</th>
              <th className="px-3 py-2 text-center font-bold text-slate-400">Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((v) => (
              <tr key={v.id} className="border-b border-slate-100 dark:border-slate-800">
                <td className="px-3 py-2.5 whitespace-nowrap text-slate-500">
                  <div className="flex items-center gap-1">
                    <Clock className="h-3 w-3" />
                    {new Date(v.createdAt).toLocaleTimeString()}
                  </div>
                  <div className="text-[10px] text-slate-400">
                    {new Date(v.createdAt).toLocaleDateString()}
                  </div>
                </td>
                <td className="px-3 py-2.5">
                  {v.type ? (
                    <span className="font-medium text-slate-700 dark:text-slate-300">
                      {VIOLATION_TYPE_LABELS[v.type] ?? v.type}
                    </span>
                  ) : (
                    <span className="text-slate-400">Unknown</span>
                  )}
                </td>
                <td className="px-3 py-2.5">
                  <SeverityBadge severity={v.severity} />
                </td>
                <td className="px-3 py-2.5 max-w-xs truncate text-slate-600 dark:text-slate-400">
                  {v.detail || <span className="italic">No detail captured</span>}
                </td>
                <td className="px-3 py-2.5">
                  <ReviewStatusBadge outcome={v.reviewOutcome} />
                </td>
                <td className="px-3 py-2.5">
                  {v.reviewOutcome === 'PENDING' ? (
                    <div className="flex items-center justify-center gap-1">
                      <button
                        onClick={() => handleOutcome(v.id, 'GRACIOUS')}
                        disabled={isLoading(v.id)}
                        className="rounded p-1 text-green-600 hover:bg-green-50 disabled:opacity-50 dark:hover:bg-green-900/20"
                        title="Allow Continue (GRACIOUS)"
                      >
                        <CheckCircle2 className="h-3.5 w-3.5" />
                      </button>
                      <button
                        onClick={() => handleOutcome(v.id, 'STRICT')}
                        disabled={isLoading(v.id)}
                        className="rounded p-1 text-red-600 hover:bg-red-50 disabled:opacity-50 dark:hover:bg-red-900/20"
                        title="End Exam Now (STRICT)"
                      >
                        <Send className="h-3.5 w-3.5" />
                      </button>
                      <button
                        onClick={() => handleOutcome(v.id, 'DISMISSED')}
                        disabled={isLoading(v.id)}
                        className="rounded p-1 text-blue-600 hover:bg-blue-50 disabled:opacity-50 dark:hover:bg-blue-900/20"
                        title="Dismiss (DISMISSED)"
                      >
                        <XCircle className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  ) : (
                    <span className="text-slate-400">Reviewed</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <ConfirmDialog
        open={confirmState.open}
        onOpenChange={(open) => setConfirmState((prev) => ({ ...prev, open }))}
        title={confirmState.title}
        description={confirmState.description}
        confirmLabel={confirmState.confirmLabel}
        variant={confirmState.title.includes('End') ? 'destructive' : 'default'}
        loading={bulkLoading}
        onConfirm={confirmState.onConfirm}
      />
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { Search, UserPlus, UserCheck, UserX, Shield, Users } from 'lucide-react'
import { useConfirmDialog } from '@/hooks/use-confirm-dialog'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'
import { TableSkeleton } from '@/components/shared/DashboardSkeleton'
import { toast } from 'sonner'
import { cn, formatDate } from '@/lib/utils'

interface InstructorAssignment {
  id: string
  bankId: string
  instructorId: string
  canEdit: boolean
  canReview: boolean
  canMonitor: boolean
  canPublish: boolean
  assignedAt: string
  assignedBy: string
  updatedAt: string
  user: {
    id: string
    email: string
    profile?: { firstName: string; lastName: string } | null
    instructorProfile?: { employeeId: string; department: string | null } | null
  }
}

interface InstructorOption {
  id: string
  email: string
  profile?: { firstName: string; lastName: string } | null
  instructorProfile?: { employeeId: string; department: string | null } | null
}

interface InstructorAssignmentPageProps {
  bankId: string
  bankName: string
  courseCode: string
  courseId: string
}

export default function InstructorAssignmentPage({ bankId, bankName, courseCode, courseId }: InstructorAssignmentPageProps) {
  const [assignments, setAssignments] = useState<InstructorAssignment[]>([])
  const [availableInstructors, setAvailableInstructors] = useState<InstructorOption[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [showAssignModal, setShowAssignModal] = useState(false)
  const [selectedInstructor, setSelectedInstructor] = useState<string | null>(null)
  const [permissions, setPermissions] = useState({ canEdit: false, canReview: false, canMonitor: true, canPublish: false })
  const [submitting, setSubmitting] = useState(false)
  const [auditLog, setAuditLog] = useState<{ description: string; createdAt: string }[]>([])
  const [bulkAssigning, setBulkAssigning] = useState(false)

  const confirmDialog = useConfirmDialog()

  const fetchAssignments = useCallback(async () => {
    const res = await fetch(`/api/staff/exams/internal/banks/${bankId}/instructors`)
    const json = await res.json()
    if (json.success) setAssignments(json.data || [])
  }, [bankId])

  const fetchAvailableInstructors = useCallback(async () => {
    const res = await fetch('/api/staff/users?role=INSTRUCTOR&limit=100')
    const json = await res.json()
    if (json.success) setAvailableInstructors(json.data || [])
  }, [])

  const fetchAuditLog = useCallback(async () => {
    const res = await fetch(`/api/staff/audit-logs?action=EXAM_BANK_INSTRUCTOR_ASSIGNED&limit=10`)
    const json = await res.json()
    if (json.success) {
      const logs = (json.data || []) as any[]
      const relevant = logs.filter((l) => l.description?.includes(bankId) || l.changes?.bankId === bankId)
      setAuditLog(relevant.map((l: any) => ({ description: l.description, createdAt: l.createdAt })))
    }
  }, [bankId])

  useEffect(() => {
    let cancelled = false
    async function load() {
      setLoading(true)
      await Promise.all([fetchAssignments(), fetchAvailableInstructors(), fetchAuditLog()])
      if (!cancelled) setLoading(false)
    }
    load()
    return () => { cancelled = true }
  }, [fetchAssignments, fetchAvailableInstructors, fetchAuditLog])

  const handleAssign = async () => {
    if (!selectedInstructor) return
    setSubmitting(true)
    try {
      const res = await fetch(`/api/staff/exams/internal/banks/${bankId}/instructors`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ instructorId: selectedInstructor, canEdit: permissions.canEdit, canReview: permissions.canReview, canMonitor: permissions.canMonitor }),
      })
      if (res.ok) {
        setShowAssignModal(false)
        setSelectedInstructor(null)
        setPermissions({ canEdit: false, canReview: false, canMonitor: true, canPublish: false })
        toast.success('Instructor assigned successfully')
        fetchAssignments()
        fetchAuditLog()
      } else {
        const data = await res.json()
        toast.error(data.error || 'Failed to assign instructor')
      }
    } finally {
      setSubmitting(false)
    }
  }

  const handleBulkAssign = async () => {
    setBulkAssigning(true)
    try {
      const res = await fetch(`/api/staff/exams/internal/banks/${bankId}/instructors`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ bulk: true, canEdit: false, canReview: false, canMonitor: true }),
      })
      if (res.ok) {
        toast.success('Bulk assignment completed')
        fetchAssignments()
        fetchAuditLog()
      } else {
        const data = await res.json()
        toast.error(data.error || 'Failed to bulk assign')
      }
    } finally {
      setBulkAssigning(false)
    }
  }

  const handleUpdate = async (assignmentId: string, updates: Partial<InstructorAssignment>) => {
    await fetch(`/api/staff/exams/internal/banks/${bankId}/instructors/${assignmentId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updates),
    })
    toast.success('Permissions updated')
    fetchAssignments()
    fetchAuditLog()
  }

  const handleRevoke = async (assignmentId: string) => {
    confirmDialog.confirm({
      title: 'Revoke Instructor Access',
      description: 'Are you sure you want to revoke this instructor\'s access? This action cannot be undone.',
      onConfirm: async () => {
        await fetch(`/api/staff/exams/internal/banks/${bankId}/instructors/${assignmentId}`, { method: 'DELETE' })
        toast.success('Access revoked')
        fetchAssignments()
        fetchAuditLog()
      },
    })
  }

  const filteredInstructors = availableInstructors.filter((inst) => {
    if (!searchQuery) return true
    const q = searchQuery.toLowerCase()
    const name = `${inst.profile?.firstName || ''} ${inst.profile?.lastName || ''}`.toLowerCase()
    const email = inst.email.toLowerCase()
    const empId = inst.instructorProfile?.employeeId?.toLowerCase() || ''
    return name.includes(q) || email.includes(q) || empId.includes(q)
  })

  const unassignedInstructors = filteredInstructors.filter(
    (inst) => !assignments.some((a) => a.instructorId === inst.id)
  )

  if (loading) return <TableSkeleton rows={10} />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-slate-900 dark:text-white" data-tour-id="instructor-assignment-title">
            Instructor Access
          </h2>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            {bankName} • {courseCode} • Assign instructors and manage their permissions.
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={handleBulkAssign}
            disabled={bulkAssigning}
            className={cn(
              'flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-bold text-white transition-all',
              bulkAssigning ? 'bg-slate-400' : 'bg-slate-700 hover:bg-slate-800'
            )}
          >
            {bulkAssigning ? <Users className="h-4 w-4 animate-pulse" /> : <Users className="h-4 w-4" />}
            {bulkAssigning ? 'Assigning...' : 'Assign All Course Instructors'}
          </button>
          <button
            onClick={() => setShowAssignModal(true)}
            className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2 text-sm font-bold text-white hover:bg-aerojet-blue/90"
            data-tour-id="assign-instructor-button"
          >
            <UserPlus className="h-4 w-4" />
            Assign Instructor
          </button>
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-700">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 dark:bg-slate-800">
            <tr>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Instructor</th>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Employee ID</th>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Can Edit</th>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Can Review</th>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Can Monitor</th>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Assigned</th>
              <th className="px-4 py-3 font-semibold text-slate-600 dark:text-slate-300">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
            {assignments.length === 0 ? (
              <tr>
                <td colSpan={7} className="px-4 py-8 text-center text-slate-500 dark:text-slate-400">
                  No instructors assigned yet. Click "Assign Instructor" to add one.
                </td>
              </tr>
            ) : (
              assignments.map((assignment) => (
                <tr key={assignment.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                  <td className="px-4 py-3">
                    <div className="font-medium text-slate-900 dark:text-white">
                      {assignment.user.profile
                        ? `${assignment.user.profile.firstName} ${assignment.user.profile.lastName}`
                        : assignment.user.email}
                    </div>
                    <div className="text-xs text-slate-500 dark:text-slate-400">{assignment.user.email}</div>
                  </td>
                  <td className="px-4 py-3 text-slate-600 dark:text-slate-300">
                    {assignment.user.instructorProfile?.employeeId || '—'}
                  </td>
                  <td className="px-4 py-3">
                    <PermissionToggle
                      enabled={assignment.canEdit}
                      onChange={(val) => handleUpdate(assignment.id, { canEdit: val })}
                    />
                  </td>
                  <td className="px-4 py-3">
                    <PermissionToggle
                      enabled={assignment.canReview}
                      onChange={(val) => handleUpdate(assignment.id, { canReview: val })}
                    />
                  </td>
                  <td className="px-4 py-3">
                    <PermissionToggle
                      enabled={assignment.canMonitor}
                      onChange={(val) => handleUpdate(assignment.id, { canMonitor: val })}
                    />
                  </td>
                  <td className="px-4 py-3 text-slate-600 dark:text-slate-300">
                    {formatDate(assignment.assignedAt)}
                  </td>
                  <td className="px-4 py-3">
                    <button
                      onClick={() => handleRevoke(assignment.id)}
                      className="flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-medium text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                    >
                      <UserX className="h-3 w-3" />
                      Revoke
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800/50" data-tour-id="assignment-audit-log">
        <h3 className="mb-3 flex items-center gap-2 text-sm font-bold text-slate-700 dark:text-slate-300">
          <Shield className="h-4 w-4" />
          Recent Assignment Changes
        </h3>
        <div className="space-y-2">
          {auditLog.length === 0 ? (
            <p className="text-xs text-slate-500 dark:text-slate-400">No recent changes.</p>
          ) : (
            auditLog.map((entry, i) => (
              <div key={i} className="flex items-center justify-between text-xs">
                <span className="text-slate-600 dark:text-slate-400">{entry.description}</span>
                <span className="text-slate-400 dark:text-slate-500">
                  {formatDate(entry.createdAt)}
                </span>
              </div>
            ))
          )}
        </div>
      </div>

      <ConfirmDialog
        open={confirmDialog.open}
        onOpenChange={confirmDialog.onOpenChange}
        title={confirmDialog.title}
        description={confirmDialog.description}
        confirmLabel="Revoke"
        variant="destructive"
        onConfirm={confirmDialog.onConfirm}
      />

      {showAssignModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
          <div className="w-full max-w-lg rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl dark:border-slate-700 dark:bg-slate-900">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Assign Instructor</h3>
            <div className="mt-4 space-y-4">
              <div>
                <label className="mb-1 block text-sm font-medium text-slate-700 dark:text-slate-300">
                  Search Instructors
                </label>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Name, email, or employee ID..."
                    className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pl-10 pr-4 text-sm dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  />
                </div>
              </div>

              <div className="max-h-60 overflow-y-auto rounded-xl border border-slate-200 dark:border-slate-700">
                {unassignedInstructors.length === 0 ? (
                  <p className="p-4 text-center text-sm text-slate-500 dark:text-slate-400">
                    No instructors found.
                  </p>
                ) : (
                  unassignedInstructors.map((inst) => (
                    <button
                      key={inst.id}
                      onClick={() => setSelectedInstructor(inst.id)}
                      className={cn(
                        'flex w-full items-center justify-between px-4 py-3 text-left hover:bg-slate-50 dark:hover:bg-slate-800',
                        selectedInstructor === inst.id && 'bg-blue-50 dark:bg-blue-900/20'
                      )}
                    >
                      <div>
                        <div className="text-sm font-medium text-slate-900 dark:text-white">
                          {inst.profile ? `${inst.profile.firstName} ${inst.profile.lastName}` : inst.email}
                        </div>
                        <div className="text-xs text-slate-500 dark:text-slate-400">
                          {inst.email} {inst.instructorProfile?.employeeId && `• ${inst.instructorProfile.employeeId}`}
                        </div>
                      </div>
                      {selectedInstructor === inst.id && <UserCheck className="h-4 w-4 text-blue-600" />}
                    </button>
                  ))
                )}
              </div>

              {selectedInstructor && (
                <div className="space-y-2 rounded-xl border border-slate-200 p-4 dark:border-slate-700">
                  <p className="text-sm font-medium text-slate-700 dark:text-slate-300">Permissions</p>
                  <PermissionCheckboxes permissions={permissions} onChange={setPermissions} />
                </div>
              )}

              <div className="flex gap-3">
                <button
                  onClick={() => setShowAssignModal(false)}
                  className="flex-1 rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300"
                >
                  Cancel
                </button>
                <button
                  onClick={handleAssign}
                  disabled={!selectedInstructor || submitting}
                  className="flex-1 rounded-xl bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50"
                >
                  {submitting ? 'Assigning...' : 'Assign'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

function PermissionToggle({ enabled, onChange }: { enabled: boolean; onChange: (val: boolean) => void }) {
  return (
    <button
      onClick={() => onChange(!enabled)}
      className={cn(
        'relative inline-flex h-6 w-11 items-center rounded-full transition-colors',
        enabled ? 'bg-aerojet-blue' : 'bg-slate-200 dark:bg-slate-700'
      )}
    >
      <span
        className={cn(
          'inline-block h-4 w-4 rounded-full bg-white transition-transform',
          enabled ? 'translate-x-6' : 'translate-x-1'
        )}
      />
    </button>
  )
}

function PermissionCheckboxes({
  permissions,
  onChange,
}: {
  permissions: { canEdit: boolean; canReview: boolean; canMonitor: boolean; canPublish: boolean }
  onChange: (val: { canEdit: boolean; canReview: boolean; canMonitor: boolean; canPublish: boolean }) => void
}) {
  const toggle = (key: keyof typeof permissions) => {
    onChange({ ...permissions, [key]: !permissions[key] })
  }

  return (
    <div className="space-y-2">
      {([
        ['canEdit', 'Can Edit Questions'],
        ['canReview', 'Can Review/Approve'],
        ['canMonitor', 'Can Monitor Sessions'],
      ] as const).map(([key, label]) => (
        <label key={key} className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
          <input
            type="checkbox"
            checked={permissions[key]}
            onChange={() => toggle(key)}
            className="h-4 w-4 rounded border-slate-300 text-aerojet-blue focus:ring-aerojet-blue"
          />
          {label}
        </label>
      ))}
      <label className="flex items-center gap-2 text-sm text-slate-400">
        <input
          type="checkbox"
          checked={permissions.canPublish}
          disabled
          className="h-4 w-4 rounded border-slate-300 text-aerojet-blue focus:ring-aerojet-blue disabled:opacity-50"
        />
        Can Publish Results (admin only)
        <span className="rounded bg-slate-100 px-1.5 py-0.5 text-xs text-slate-500 dark:bg-slate-700 dark:text-slate-400">
          Admin only
        </span>
      </label>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { toast } from 'sonner'
import {
  ChevronLeft,
  ChevronRight,
  Loader2,
  AlertTriangle,
  CheckCircle2,
  Send,
  XCircle,
  Menu,
  X,
  Flag,
  Hourglass,
  Maximize,
  ShieldAlert,
  Bookmark,
  Clock,
  BarChart3,
  RefreshCw,
  ArrowLeft,
  BookOpen,
  Download,
  Lock,
  Eye,
} from 'lucide-react'
import Link from 'next/link'

interface BankOption {
  id: string
  name: string
  courseCode: string
  courseName: string
  mcqCount: number
  categoryCode: string | null
  sebConfig: unknown | null
  sebRequired: boolean
}

interface PreviewQuestion {
  index: number
  questionId: string
  text: string
  options: string[]
  correctAnswer: string
  subTopic: string | null
  difficulty: string
  points: number
  syllabusRef: string | null
  knowledgeLevel: number | null
}

interface BankRules {
  timePerQuestionSecs: number
  passMarkPct: number
  allowKeyboardAutoSubmit: boolean
  customInstructions?: string | null
}

interface PreviewData {
  bank: {
    id: string
    name: string
    course: { code: string; name: string }
    mcqCount: number
    ruleSet: string
    categoryCode: string | null
    sebConfig: unknown | null
    sebRequired: boolean
    bankSebConfig: unknown | null
  }
  config: {
    timePerQuestionSecs: number
    totalTimeSecs: number
    passMarkPct: number
    totalQuestions: number
    poolSize: number
    allowKeyboardAutoSubmit: boolean
    customInstructions: string | null
  }
  subTopics: { topic: string; count: number }[]
  questions: PreviewQuestion[]
}

const DIFFICULTY_COLORS: Record<string, string> = {
  EASY: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
  MEDIUM: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
  HARD: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
}

export default function ExamPreviewClient({ banks }: { banks: BankOption[] }) {
  const [selectedBankId, setSelectedBankId] = useState(banks[0]?.id || '')
  const [data, setData] = useState<PreviewData | null>(null)
  const [loading, setLoading] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)
  const [result, setResult] = useState<{
    score: number
    correctCount: number
    total: number
  } | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [currentIndex, setCurrentIndex] = useState(0)
  const [answers, setAnswers] = useState<Record<string, string>>({})
  const [timeLeft, setTimeLeft] = useState(0)
  const [isLeftPanelOpen, setIsLeftPanelOpen] = useState(true)
  const [showReport, setShowReport] = useState(false)
  const [reportReason, setReportReason] = useState('')
  const [reportSubmitting, setReportSubmitting] = useState(false)
  const [reportSubmitted, setReportSubmitted] = useState(false)
  const [showQuestionReport, setShowQuestionReport] = useState<string | null>(null)
  const [questionReportReason, setQuestionReportReason] = useState('')
  const [questionReportSubmitting, setQuestionReportSubmitting] = useState(false)
  const [reportedQuestions, setReportedQuestions] = useState<Set<string>>(new Set())
  const [isFullscreen, setIsFullscreen] = useState(false)
  const [tabSwitchCount, setTabSwitchCount] = useState(0)
  const [showFullscreenPrompt, setShowFullscreenPrompt] = useState(false)
  const [flaggedQuestions, setFlaggedQuestions] = useState<Set<string>>(new Set())
  const [showReviewLaterFilter, setShowReviewLaterFilter] = useState(false)
  const [flagging, setFlagging] = useState<string | null>(null)
  const [downloadingSeb, setDownloadingSeb] = useState<string | null>(null)
  const [showLobby, setShowLobby] = useState(false)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const logViolation = useCallback(
    async (
      type: string,
      detail?: string,
      opts?: { severity?: 'WARNING' | 'NOTICE' | 'CRITICAL' }
    ) => {
      void fetch('/api/staff/exams/internal/preview/violations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        cache: 'no-store',
        body: JSON.stringify({
          bankId: data?.bank.id,
          type,
          detail,
          deviceInfo: {
            userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : undefined,
            platform: typeof navigator !== 'undefined' ? (navigator as any).platform : undefined,
            language: typeof navigator !== 'undefined' ? navigator.language : undefined,
          },
          ...(opts?.severity ? { severity: opts.severity } : {}),
        }),
      })
      toast.warning(`Violation logged: ${type}`, {
        duration: 4000,
        position: 'bottom-right',
        dismissible: true,
      })
    },
    [data?.bank.id]
  )

  const loadPreview = async () => {
    if (!selectedBankId) return
    setLoading(true)
    setError(null)
    try {
      const res = await fetch(`/api/staff/exams/internal/preview?bankId=${selectedBankId}`)
      const json = await res.json()
      if (json.success && json.data) {
        setData(json.data)
        setCurrentIndex(0)
        setAnswers({})
        setTimeLeft(json.data.config.totalTimeSecs)
        setFlaggedQuestions(new Set())
        setTabSwitchCount(0)
        setShowLobby(false)
        setResult(null)
      } else {
        setError(json.error || 'Failed to generate preview')
      }
    } catch {
      setError('Could not connect to exam server')
    } finally {
      setLoading(false)
    }
  }

  const handleDownloadSeb = async (bankId: string) => {
    setDownloadingSeb(bankId)
    try {
      const res = await fetch(`/api/staff/exams/internal/banks/${bankId}/seb-config/download`)
      if (!res.ok) {
        toast.error('Could not download SEB config')
        return
      }
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `exam-${bankId}.seb`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
      toast.success('SEB config downloaded')
    } catch {
      toast.error('Could not download SEB config')
    } finally {
      setDownloadingSeb(null)
    }
  }

  const enterFullscreen = useCallback(async () => {
    try {
      await document.documentElement.requestFullscreen()
      setIsFullscreen(true)
      setShowFullscreenPrompt(false)
      document.body.classList.add('exam-lockdown')
    } catch {
      document.body.classList.add('exam-lockdown')
    }
  }, [])

  const toggleFlag = useCallback(async (questionId: string, flagged: boolean) => {
    setFlagging(questionId)
    try {
      setFlaggedQuestions((prev) => {
        const next = new Set(prev)
        if (flagged) next.add(questionId)
        else next.delete(questionId)
        return next
      })
    } finally {
      setFlagging(null)
    }
  }, [])

  const selectAnswer = (questionId: string, answer: string) => {
    setAnswers((prev) => ({ ...prev, [questionId]: answer }))
  }

  const handleSubmit = async (auto = false) => {
    if (submitting) return
    setSubmitting(true)
    if (timerRef.current) clearInterval(timerRef.current)

    const answeredCount = Object.keys(answers).length
    const correctCount = data!.questions.filter(
      (q) => answers[q.questionId] === q.correctAnswer
    ).length
    const score = Math.round((correctCount / data!.questions.length) * 100)

    setResult({ score, correctCount, total: data!.questions.length })
    setShowConfirm(false)
    setSubmitting(false)
    document.body.classList.remove('exam-lockdown')
    if (document.fullscreenElement) document.exitFullscreen().catch(() => {})
  }

  // â”€â”€â”€ Fullscreen lockdown mode â”€â”€â”€
  useEffect(() => {
    if (!data || result || showConfirm) return
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setShowFullscreenPrompt(true)
  }, [data, result, showConfirm])

  useEffect(() => {
    if (!data || result || showConfirm) return
    const onFsChange = () => {
      const inFS = !!document.fullscreenElement
      setIsFullscreen(inFS)
      if (!inFS && !result) {
        setShowFullscreenPrompt(true)
        void logViolation('FULLSCREEN_EXIT', 'Staff exited fullscreen during preview')
      }
    }
    document.addEventListener('fullscreenchange', onFsChange)
    return () => document.removeEventListener('fullscreenchange', onFsChange)
  }, [data, result, logViolation, showConfirm])

  // Tab visibility
  useEffect(() => {
    if (!data || result || showConfirm) return
    let warned = false
    const onVisibility = () => {
      if (document.hidden) {
        setTabSwitchCount((p) => p + 1)
        if (!warned) {
          warned = true
          void logViolation('TAB_SWITCH', 'Tab switched during preview')
        }
      } else warned = false
    }
    document.addEventListener('visibilitychange', onVisibility)
    return () => document.removeEventListener('visibilitychange', onVisibility)
  }, [data, result, logViolation, showConfirm])

  // Clipboard blocking
  useEffect(() => {
    if (!data || result || showConfirm) return
    const onClipboard = (e: ClipboardEvent) => {
      e.preventDefault()
      void logViolation('CLIPBOARD_BLOCKED', `Clipboard event blocked: ${e.type}`)
    }
    document.addEventListener('copy', onClipboard)
    document.addEventListener('cut', onClipboard)
    document.addEventListener('paste', onClipboard)
    return () => {
      document.removeEventListener('copy', onClipboard)
      document.removeEventListener('cut', onClipboard)
      document.removeEventListener('paste', onClipboard)
    }
  }, [data, result, logViolation, showConfirm])

  // Keyboard shortcuts + strict keypress auto-submit
  useEffect(() => {
    if (!data?.config.allowKeyboardAutoSubmit || result || showConfirm) return
    const MODIFIERS = new Set(['Shift', 'Control', 'Alt', 'Meta'])
    const onKeyDown = (e: KeyboardEvent) => {
      if (MODIFIERS.has(e.key)) return
      const target = e.target as HTMLElement | null
      const tag = target?.tagName?.toLowerCase()
      const inInput = tag === 'input' || tag === 'textarea' || target?.isContentEditable
      const ctrlOrCmd = e.ctrlKey || e.metaKey
      const k = e.key.toLowerCase()
      const isCopyPaste = ctrlOrCmd && (k === 'c' || k === 'v')
      const isF12 = e.key === 'F12'
      const isDevTools = ctrlOrCmd && e.shiftKey && (k === 'i' || k === 'j' || k === 'c')
      if (!inInput && (isCopyPaste || isF12 || isDevTools)) {
        e.preventDefault()
        void logViolation('KEYBOARD_SHORTCUT', `Blocked shortcut: ${e.key}`)
        return
      }
      if (!submitting) {
        e.preventDefault()
        void logViolation('KEYBOARD_SHORTCUT', `Auto-submit triggered by key: ${e.key}`, {
          severity: 'CRITICAL',
        })
        void handleSubmit(true)
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [data?.config.allowKeyboardAutoSubmit, result, showConfirm, logViolation])

  // Network detection
  useEffect(() => {
    if (!data || result || showConfirm) return
    const onNet = () =>
      void logViolation(
        'NETWORK_DISCONNECT',
        `Network ${navigator.onLine ? 'restored' : 'lost'} during preview`
      )
    window.addEventListener('online', onNet)
    window.addEventListener('offline', onNet)
    return () => {
      window.removeEventListener('online', onNet)
      window.removeEventListener('offline', onNet)
    }
  }, [data, result, logViolation, showConfirm])

  // Page unload
  useEffect(() => {
    if (!data || result || showConfirm) return
    const onUnload = () =>
      void fetch('/api/staff/exams/internal/preview/violations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        cache: 'no-store',
        keepalive: true,
        body: JSON.stringify({
          bankId: data.bank.id,
          type: 'EXAM_INTERFACE_UNLOAD',
          detail: 'Staff navigated away or closed preview during active mode',
          deviceInfo: { userAgent: navigator.userAgent, platform: (navigator as any).platform },
        }),
      })
    document.addEventListener('beforeunload', onUnload)
    document.addEventListener('pagehide', onUnload)
    return () => {
      document.removeEventListener('beforeunload', onUnload)
      document.removeEventListener('pagehide', onUnload)
    }
  }, [data, result, showConfirm])

  // Timer countdown
  useEffect(() => {
    if (!data || result) return
    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timerRef.current!)
          handleSubmit(true)
          return 0
        }
        return prev - 1
      })
    }, 1000)
    return () => {
      if (timerRef.current) clearInterval(timerRef.current)
    }
  }, [data, result])

  // Cleanup on unmount
  useEffect(
    () => () => {
      document.body.classList.remove('exam-lockdown')
      if (document.fullscreenElement) document.exitFullscreen().catch(() => {})
    },
    []
  )

  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60),
      s = secs % 60
    return `${m}:${s.toString().padStart(2, '0')}`
  }

  const handleSubmitReport = async () => {
    if (!reportReason.trim() || reportSubmitting) return
    setReportSubmitting(true)
    try {
      await fetch('/api/staff/exams/internal/preview/violations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankId: data?.bank.id,
          type: 'DEVTOOLS_DETECTED',
          detail: reportReason.trim(),
        }),
      })
      setReportSubmitted(true)
      setReportReason('')
    } finally {
      setReportSubmitting(false)
    }
  }

  const handleSubmitQuestionReport = async () => {
    if (!questionReportReason.trim() || questionReportSubmitting || !showQuestionReport) return
    setQuestionReportSubmitting(true)
    try {
      await fetch('/api/staff/exams/internal/preview/violations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankId: data?.bank.id,
          type: 'DEVTOOLS_DETECTED',
          detail: `Question ${showQuestionReport}: ${questionReportReason.trim()}`,
        }),
      })
      setReportedQuestions((prev) => new Set([...prev, showQuestionReport]))
      setShowQuestionReport(null)
      setQuestionReportReason('')
    } finally {
      setQuestionReportSubmitting(false)
    }
  }

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Loader2 className="text-aerojet-blue h-10 w-10 animate-spin" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex min-h-[60vh] flex-col items-center justify-center text-center">
        <XCircle className="mb-4 h-12 w-12 text-red-500" />
        <p className="text-lg font-bold text-slate-900 dark:text-white">{error}</p>
      </div>
    )
  }

  if (!data) {
    return (
      <div className="space-y-4">
        <div className="flex flex-wrap items-center gap-3">
          <select
            value={selectedBankId}
            onChange={(e) => setSelectedBankId(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-900 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
          >
            {banks.map((bank) => (
              <option key={bank.id} value={bank.id}>
                {bank.name} ({bank.courseCode})
              </option>
            ))}
          </select>
          <button
            onClick={loadPreview}
            className="bg-aerojet-blue hover:bg-aerojet-blue/90 flex items-center gap-1.5 rounded-lg px-4 py-2 text-xs font-bold text-white"
          >
            <BookOpen className="h-3.5 w-3.5" />
            Load Preview
          </button>
          {selectedBankId && (
            <button
              onClick={() => handleDownloadSeb(selectedBankId)}
              disabled={downloadingSeb === selectedBankId}
              className="flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
            >
              {downloadingSeb === selectedBankId ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Download className="h-3.5 w-3.5" />
              )}
              Download SEB Config
            </button>
          )}
        </div>
        <p className="text-sm text-slate-500">Select an exam bank to preview.</p>
      </div>
    )
  }

  const questions = data.questions
  const currentQ = questions[currentIndex]
  const answeredCount = Object.keys(answers).length
  const optionLabels = ['A', 'B', 'C']

  if (result) {
    return (
      <div className="space-y-4">
        <div className="flex flex-wrap items-center gap-3">
          <select
            value={selectedBankId}
            onChange={(e) => setSelectedBankId(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-900 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
          >
            {banks.map((bank) => (
              <option key={bank.id} value={bank.id}>
                {bank.name} ({bank.courseCode})
              </option>
            ))}
          </select>
          <button
            onClick={loadPreview}
            className="bg-aerojet-blue hover:bg-aerojet-blue/90 flex items-center gap-1.5 rounded-lg px-4 py-2 text-xs font-bold text-white"
          >
            <BookOpen className="h-3.5 w-3.5" /> Reload
          </button>
        </div>
        <div className="mx-auto max-w-lg rounded-2xl border border-slate-200 bg-white p-8 text-center dark:border-slate-800 dark:bg-slate-900">
          <CheckCircle2 className="mx-auto mb-4 h-16 w-16 text-green-500" />
          <h2 className="text-2xl font-black text-slate-900 dark:text-white">Preview Complete</h2>
          <p className="mt-3 text-sm text-slate-500">
            Score: {result.correctCount}/{result.total} ({result.score}%)
          </p>
        </div>
      </div>
    )
  }

  return (
    <>
      {showFullscreenPrompt && !result && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-sm">
          <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-8 text-center shadow-2xl dark:border-slate-800 dark:bg-slate-900">
            <ShieldAlert className="mx-auto mb-4 h-16 w-16 text-amber-500" />
            <h2 className="text-xl font-black text-slate-900 dark:text-white">
              Enter Preview Mode
            </h2>
            <p className="mt-2 text-sm text-slate-500">This preview runs in lockdown mode.</p>
            <button
              onClick={enterFullscreen}
              className="bg-aerojet-blue mt-6 inline-flex items-center gap-2 rounded-xl px-8 py-3 text-sm font-bold text-white"
            >
              <Maximize className="h-4 w-4" /> Enter Fullscreen
            </button>
          </div>
        </div>
      )}

      <div className="space-y-4">
        <div className="flex flex-wrap items-center gap-3">
          <select
            value={selectedBankId}
            onChange={(e) => setSelectedBankId(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-900 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
          >
            {banks.map((bank) => (
              <option key={bank.id} value={bank.id}>
                {bank.name} ({bank.courseCode})
              </option>
            ))}
          </select>
          <button
            onClick={loadPreview}
            className="bg-aerojet-blue hover:bg-aerojet-blue/90 flex items-center gap-1.5 rounded-lg px-4 py-2 text-xs font-bold text-white"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Reload
          </button>
          {selectedBankId && (
            <button
              onClick={() => handleDownloadSeb(selectedBankId)}
              disabled={downloadingSeb === selectedBankId}
              className="flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
            >
              {downloadingSeb === selectedBankId ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Download className="h-3.5 w-3.5" />
              )}
              Download SEB Config
            </button>
          )}
          <span
            className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm font-bold ${timeLeft < 120 ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300'}`}
          >
            <Clock className="h-4 w-4" /> {formatTime(timeLeft)}
          </span>
        </div>

        <div className="rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-4 flex items-center justify-between border-b border-slate-100 pb-3 dark:border-slate-800">
            <span className="text-xs font-bold text-slate-400 uppercase">
              Question {currentIndex + 1} of {questions.length}
            </span>
            <span
              className={`rounded-lg px-2.5 py-1 text-[10px] font-bold ${DIFFICULTY_COLORS[currentQ.difficulty] || ''}`}
            >
              {currentQ.difficulty}
            </span>
          </div>
          <p className="text-base font-medium text-slate-900 dark:text-slate-100">
            {currentQ.text}
          </p>
          <div className="mt-6 space-y-2">
            {currentQ.options.map((opt, i) => {
              const selected = answers[currentQ.questionId] === opt
              return (
                <button
                  key={i}
                  onClick={() => selectAnswer(currentQ.questionId, opt)}
                  className={`flex w-full items-center gap-3 rounded-xl border-2 p-3 text-left ${selected ? 'border-aerojet-blue bg-blue-50 dark:bg-blue-900/20' : 'border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900'}`}
                >
                  <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-slate-100 text-xs font-bold text-slate-600 dark:bg-slate-800">
                    {optionLabels[i]}
                  </span>
                  <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                    {opt}
                  </span>
                </button>
              )
            })}
          </div>
          <div className="mt-6 flex items-center justify-between">
            <button
              onClick={() => setCurrentIndex(Math.max(0, currentIndex - 1))}
              disabled={currentIndex === 0}
              className="flex items-center gap-2 rounded-lg bg-white px-4 py-2 text-sm font-bold text-slate-600 disabled:opacity-40 dark:bg-slate-900 dark:text-slate-300"
            >
              <ChevronLeft className="h-4 w-4" /> Previous
            </button>
            {currentIndex < questions.length - 1 ? (
              <button
                onClick={() => setCurrentIndex(currentIndex + 1)}
                className="bg-aerojet-blue flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-bold text-white"
              >
                Next <ChevronRight className="h-4 w-4" />
              </button>
            ) : (
              <button
                onClick={() => setShowConfirm(true)}
                className="flex items-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-sm font-bold text-white"
              >
                <Send className="h-4 w-4" /> Submit
              </button>
            )}
          </div>
        </div>
      </div>

      {showConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
          <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
            <AlertTriangle className="mx-auto mb-4 h-12 w-12 text-amber-500" />
            <h3 className="text-center text-xl font-black text-slate-900 dark:text-white">
              Submit Preview?
            </h3>
            <div className="mt-4 flex gap-3">
              <button
                onClick={() => setShowConfirm(false)}
                className="flex-1 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
              >
                Cancel
              </button>
              <button
                onClick={() => handleSubmit(false)}
                className="flex-1 rounded-xl bg-green-600 px-4 py-2.5 text-sm font-bold text-white"
              >
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { cn } from '@/lib/utils'

interface SupervisedExamInterfaceProps {
  sessionId: string
  studentName: string
  studentEmail: string
  bankName: string
  className?: string
}

interface ExamQuestion {
  id: string
  text: string
  options: string[]
  points: number
  subTopic: string
}

interface ActivityLogEntry {
  timestamp: string
  type: string
  description: string
}

export default function SupervisedExamInterface({
  sessionId,
  studentName,
  studentEmail,
  bankName,
  className,
}: SupervisedExamInterfaceProps) {
  const [session, setSession] = useState<any>(null)
  const [questions, setQuestions] = useState<ExamQuestion[]>([])
  const [savedAnswers, setSavedAnswers] = useState<Record<string, string>>({})
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [timeLeft, setTimeLeft] = useState(0)
  const [isSubmitted, setIsSubmitted] = useState(false)
  const [activityLog, setActivityLog] = useState<ActivityLogEntry[]>([])
  const [showActivityLog, setShowActivityLog] = useState(false)
  const [isStarting, setIsStarting] = useState(false)
  const [isExtending, setIsExtending] = useState(false)
  const [extensionMinutes, setExtensionMinutes] = useState(15)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const logActivity = useCallback((type: string, description: string) => {
    const entry: ActivityLogEntry = {
      timestamp: new Date().toISOString(),
      type,
      description,
    }
    setActivityLog((prev) => [...prev, entry])

    createAuditLog({
      action: AuditAction.EXAM_SESSION_STARTED,
      entity: 'InternalExamSession',
      entityId: sessionId,
      description: `[Supervised] ${type}: ${description}`,
      details: { studentName, studentEmail, bankName, className, type, description },
    }).catch(() => {})
  }, [sessionId, studentName, studentEmail, bankName, className])

  const startExam = useCallback(async () => {
    setIsStarting(true)
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/supervise`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })
      const data = await res.json()
      if (!res.ok || !data.success) {
        setError(data.error || 'Failed to start exam')
        return
      }

      const sessionData = data.data
      setSession(sessionData)
      setQuestions(sessionData.questions || [])
      setSavedAnswers(Object.fromEntries((sessionData.savedAnswers || []).map((a: any) => [a.questionId, a.selectedAnswer])))
      setTimeLeft(sessionData.totalTimeSecs || 0)
      setIsSubmitted(false)
      logActivity('EXAM_STARTED', `Invigilator started supervised exam for ${studentName}`)
    } catch (err) {
      setError('Failed to start exam')
    } finally {
      setIsStarting(false)
    }
  }, [sessionId, studentName, logActivity])

  const submitExam = useCallback(async () => {
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/force-submit`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })
      const data = await res.json()
      if (!res.ok || !data.success) {
        setError(data.error || 'Failed to submit exam')
        return
      }
      setIsSubmitted(true)
      logActivity('EXAM_SUBMITTED', `Invigilator force-submitted exam for ${studentName}`)
    } catch (err) {
      setError('Failed to submit exam')
    }
  }, [sessionId, studentName, logActivity])

  const extendTime = useCallback(async () => {
    setIsExtending(true)
    try {
      const res = await fetch(`/api/staff/exams/internal/sessions/${sessionId}/extend`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ timeExtensionSec: extensionMinutes * 60 }),
      })
      const data = await res.json()
      if (!res.ok || !data.success) {
        setError(data.error || 'Failed to extend time')
        return
      }
      setTimeLeft((prev) => prev + extensionMinutes * 60)
      logActivity('TIME_EXTENDED', `Invigilator extended exam time by ${extensionMinutes} minutes for ${studentName}`)
    } catch (err) {
      setError('Failed to extend time')
    } finally {
      setIsExtending(false)
    }
  }, [sessionId, extensionMinutes, studentName, logActivity])

  const handleAnswerChange = useCallback((questionId: string, answer: string) => {
    setSavedAnswers((prev) => {
      const next = { ...prev, [questionId]: answer }
      return next
    })
    logActivity('ANSWER_CHANGED', `Answer changed for question ${questionId}`)

    fetch(`/api/staff/exams/internal/sessions/${sessionId}/supervise/answer`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ questionId, selectedAnswer: answer }),
    }).catch(() => {})
  }, [sessionId, logActivity])

  const submitExamRef = useRef(submitExam)
  useEffect(() => {
    submitExamRef.current = submitExam
  }, [submitExam])

  useEffect(() => {
    if (timeLeft <= 0 && session && !isSubmitted) {
      submitExamRef.current()
      return
    }
    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current)
          return 0
        }
        return prev - 1
      })
    }, 1000)
    return () => {
      if (timerRef.current) clearInterval(timerRef.current)
    }
  }, [timeLeft, session, isSubmitted])

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current)
    }
  }, [])

  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60)
    const s = secs % 60
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`
  }

  const answeredCount = Object.keys(savedAnswers).filter((k) => savedAnswers[k]).length
  const totalQuestions = questions.length
  const progressPct = totalQuestions > 0 ? Math.round((answeredCount / totalQuestions) * 100) : 0

  return (
    <div className="max-w-5xl mx-auto p-6">
      <div className="bg-yellow-50 border-l-4 border-yellow-500 p-4 mb-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-yellow-900">Supervised Session</h1>
            <p className="text-yellow-700 mt-1">
              Candidate: <span className="font-semibold">{studentName}</span> ({studentEmail})
            </p>
            {className && (
              <p className="text-yellow-700">Class: {className}</p>
            )}
            <p className="text-yellow-700">Bank: {bankName}</p>
          </div>
          <div className="text-right">
            <p className="text-3xl font-mono font-bold text-yellow-900">{formatTime(timeLeft)}</p>
            <p className="text-sm text-yellow-600">Time Remaining</p>
          </div>
        </div>
      </div>

      <div className="flex gap-4 mb-4">
        <div className="bg-white rounded-lg shadow p-4 flex-1">
          <p className="text-sm text-gray-500">Progress</p>
          <p className="text-2xl font-bold">{answeredCount} / {totalQuestions}</p>
          <div className="w-full bg-gray-200 rounded-full h-2 mt-2">
            <div
              className="bg-blue-600 h-2 rounded-full transition-all"
              style={{ width: `${progressPct}%` }}
            />
          </div>
        </div>
        <button
          onClick={() => setShowActivityLog((prev) => !prev)}
          className="bg-white rounded-lg shadow px-4 py-2 text-sm font-medium hover:bg-gray-50"
        >
          {showActivityLog ? 'Hide' : 'Show'} Activity Log ({activityLog.length})
        </button>
      </div>

      {!session && !isStarting && (
        <div className="bg-white rounded-lg shadow p-8 text-center">
          <p className="text-lg mb-4">Ready to begin the supervised exam for {studentName}.</p>
          <button
            onClick={startExam}
            disabled={isStarting}
            className="bg-green-600 text-white px-6 py-3 rounded-lg font-medium hover:bg-green-700 disabled:opacity-50"
          >
            {isStarting ? 'Starting...' : 'Start Exam'}
          </button>
        </div>
      )}

      {session && !isSubmitted && (
        <div className="bg-white rounded-lg shadow">
          {questions.length > 0 && currentQuestionIndex < questions.length && (
            <div>
              {(() => {
                const q = questions[currentQuestionIndex]
                const selected = savedAnswers[q.id] || ''
                return (
                  <div className="p-6">
                    <div className="flex items-center justify-between mb-4">
                      <span className="text-sm text-gray-500">
                        Question {currentQuestionIndex + 1} of {totalQuestions}
                      </span>
                      <span className="text-sm text-gray-500">{q.subTopic}</span>
                    </div>
                    <p className="text-lg font-medium mb-6">{q.text}</p>
                    <div className="space-y-3">
                      {q.options.map((opt) => (
                        <label
                          key={opt}
                          className={cn(
                            'flex items-center p-4 border-2 rounded-lg cursor-pointer transition-colors',
                            selected === opt
                              ? 'border-blue-500 bg-blue-50'
                              : 'border-gray-200 hover:border-gray-300'
                          )}
                        >
                          <input
                            type="radio"
                            name={`q-${q.id}`}
                            value={opt}
                            checked={selected === opt}
                            onChange={() => handleAnswerChange(q.id, opt)}
                            className="mr-3"
                          />
                          <span>{opt}</span>
                        </label>
                      ))}
                    </div>
                    <div className="flex justify-between mt-6">
                      <button
                        onClick={() => setCurrentQuestionIndex((prev) => Math.max(0, prev - 1))}
                        disabled={currentQuestionIndex === 0}
                        className="px-4 py-2 border rounded-lg disabled:opacity-50 hover:bg-gray-50"
                      >
                        Previous
                      </button>
                      <button
                        onClick={() => setCurrentQuestionIndex((prev) => Math.min(totalQuestions - 1, prev + 1))}
                        disabled={currentQuestionIndex === totalQuestions - 1}
                        className="px-4 py-2 border rounded-lg disabled:opacity-50 hover:bg-gray-50"
                      >
                        Next
                      </button>
                    </div>
                  </div>
                )
              })()}
            </div>
          )}

          <div className="border-t p-4 flex flex-wrap gap-2 items-center justify-between">
            <div className="flex gap-2">
              <button
                onClick={submitExam}
                disabled={isSubmitted}
                className="bg-red-600 text-white px-4 py-2 rounded-lg font-medium hover:bg-red-700 disabled:opacity-50"
              >
                Force Submit
              </button>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  value={extensionMinutes}
                  onChange={(e) => setExtensionMinutes(Math.max(1, parseInt(e.target.value) || 15))}
                  className="w-16 border rounded px-2 py-2 text-center"
                  min="1"
                />
                <span className="text-sm text-gray-500">min</span>
                <button
                  onClick={extendTime}
                  disabled={isExtending}
                  className="bg-yellow-600 text-white px-4 py-2 rounded-lg font-medium hover:bg-yellow-700 disabled:opacity-50"
                >
                  {isExtending ? 'Extending...' : 'Extend Time'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isSubmitted && (
        <div className="bg-white rounded-lg shadow p-8 text-center">
          <h2 className="text-2xl font-bold text-green-600 mb-2">Exam Submitted</h2>
          <p className="text-gray-600">The supervised exam has been submitted successfully.</p>
        </div>
      )}

      {error && (
        <div className="mt-4 bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
          {error}
          <button onClick={() => setError(null)} className="ml-4 underline text-sm">Dismiss</button>
        </div>
      )}

      {showActivityLog && (
        <div className="mt-6 bg-white rounded-lg shadow p-4">
          <h3 className="font-semibold mb-3">Activity Log</h3>
          <div className="max-h-96 overflow-y-auto space-y-1">
            {activityLog.map((entry, idx) => (
              <div key={idx} className="text-sm border-b pb-1">
                <span className="text-gray-500 font-mono">{new Date(entry.timestamp).toLocaleTimeString()}</span>
                <span className="ml-2 font-medium">{entry.type}</span>
                <span className="ml-2 text-gray-600">{entry.description}</span>
              </div>
            ))}
            {activityLog.length === 0 && (
              <p className="text-gray-400 text-sm">No activity recorded yet.</p>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

