/* ─── Records Tab (Server Component Wrapper) ─── */
const FULFILLMENT_DISPLAY_STATES = new Set([
  'PENDING_POOL_CONFIRMATION',
  'PENDING_FULFILLMENT',
  'EXCUSED_PENDING_REBOOK',
  'SCHEDULED',
  'EXECUTED',
  'ROLLED_FORWARD',
  'POSTPONED',
  'CANCELLED',
])

function formatBookingDisplayResult(value: string | null) {
  if (!value) return null
  if (FULFILLMENT_DISPLAY_STATES.has(value)) {
    return fulfillmentStateLabel(value as BookingFulfillmentState)
  }
  return value.toUpperCase()
}

async function RecordsTabServer({ query }: { query?: string }) {
  try {
    const [bookingsRaw, resultsRaw, modules] = await Promise.all([
      prismaUnfiltered.examBooking.findMany({
        where: query
          ? {
              OR: [
                userSearchFilter(query),
                { moduleCode: { contains: query, mode: 'insensitive' } },
              ],
            }
          : undefined,
        include: {
          examAttendance: {
            include: {
              sitting: true,
            },
          },
          sittingAssignments: {
            where: { status: { in: ['ASSIGNED', 'CONFIRMED', 'ATTENDED', 'ABSENT', 'EXCUSED'] } },
            include: { sitting: true },
            orderBy: { assignedAt: 'desc' },
          },
          user: {
            include: {
              profile: { select: { firstName: true, middleName: true, lastName: true } },
              studentProfile: { select: { studentId: true } },
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      }),
      prismaUnfiltered.examResult.findMany({
        where: query
          ? {
              OR: [
                userSearchFilter(query),
                { moduleCode: { contains: query, mode: 'insensitive' } },
              ],
            }
          : undefined,
        include: {
          user: {
            include: {
              profile: { select: { firstName: true, middleName: true, lastName: true } },
              studentProfile: { select: { studentId: true } },
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      }),
      getAvailableModules(),
    ])

    // Unify bookings and results
    const unifiedRecords: ExamRecord[] = []

    // 1. Add all bookings
    for (const b of bookingsRaw) {
      const activeAssignment = b.sittingAssignments?.[0] || null
      const sitting = activeAssignment?.sitting || b.examAttendance?.sitting || null
      const effectiveExamDate = sitting?.startTime || b.examDate || null
      const displayResultKind = deriveBookingDisplayResult({
        result: b.result,
        demandStatus: b.demandStatus,
        executedAt: b.executedAt,
        rolloverToEventId: b.rolloverToEventId,
        status: b.status,
      })
      const hasRealResult = ['pass', 'fail'].includes(b.result?.toLowerCase() || '')
      const dateDisplayKind = effectiveExamDate
        ? 'DATE'
        : (b.eventId || ['POOLED', 'SCHEDULED', 'POSTPONED'].includes(b.demandStatus))
          ? 'TBC'
          : 'TBD'

      unifiedRecords.push({
        ...b,
        source: 'booking',
        id: b.id,
        score: b.score != null ? Number(b.score) : null,
        passed: hasRealResult
          ? b.result?.toLowerCase() === 'pass'
          : null,
        isMigrated: b.result?.toUpperCase() === 'MIGRATED',
        migrationRef: null,
        examCategory: b.examCategory as ExamCategory,
        examDate: effectiveExamDate,
        dateDisplay: effectiveExamDate ? format(new Date(effectiveExamDate), 'MMM d, yyyy') : dateDisplayKind,
        dateDisplayKind,
        sittingLabel: sitting ? `Day ${sitting.dayNumber} ${sitting.sessionType}` : null,
        displayResult: formatBookingDisplayResult(displayResultKind),
        displayResultKind,
      } as ExamRecord)
    }

    // 2. Merge results into bookings or add as standalone
    for (const r of resultsRaw) {
      const rModule = (r.moduleCode || '').toUpperCase()
      const existingIndex = unifiedRecords.findIndex(
        (rec) => {
          if (rec.source !== 'booking' || rec.userId !== r.userId || (rec.moduleCode?.toUpperCase() || '') !== rModule) return false
          if (rec.attemptType && r.attemptType && rec.attemptType !== r.attemptType) return false
          return true
        }
      )

      if (existingIndex !== -1) {
        unifiedRecords[existingIndex] = {
          ...unifiedRecords[existingIndex],
          id: `result_${r.id}`,
          score: r.score != null ? Number(r.score) : unifiedRecords[existingIndex].score,
          passed: r.passed,
          source: 'result',
          result: r.passed ? 'PASS' : 'FAIL',
          displayResult: r.passed ? 'PASS' : 'FAIL',
          displayResultKind: r.passed ? 'PASS' : 'FAIL',
          examDate: unifiedRecords[existingIndex].examDate || r.createdAt,
          dateDisplayKind: 'DATE',
          dateDisplay: format(new Date(unifiedRecords[existingIndex].examDate || r.createdAt), 'MMM d, yyyy'),
          examCategory: r.examCategory || unifiedRecords[existingIndex].examCategory,
          attemptType: r.attemptType || unifiedRecords[existingIndex].attemptType,
          isMigrated: !!r.migrationRef || !!unifiedRecords[existingIndex].migrationRef,
          migrationRef: r.migrationRef || unifiedRecords[existingIndex].migrationRef,
        }
      } else {
        const matchingBooking = bookingsRaw.find((b) => {
          if (b.userId !== r.userId) return false
          const bModule = (b.moduleCode || '').trim().toUpperCase()
          const rModuleNorm = rModule.trim()
          if (!rModuleNorm) return false
          return bModule === rModuleNorm || bModule.includes(rModuleNorm) || rModuleNorm.includes(bModule)
        })

        unifiedRecords.push({
          ...r,
          id: `result_${r.id}`,
          source: 'result',
          score: r.score != null ? Number(r.score) : null,
          result: r.passed ? 'PASS' : 'FAIL',
          displayResult: r.passed ? 'PASS' : 'FAIL',
          displayResultKind: r.passed ? 'PASS' : 'FAIL',
          examDate: r.createdAt,
          dateDisplayKind: 'DATE',
          dateDisplay: format(new Date(r.createdAt), 'MMM d, yyyy'),
          bookingType: matchingBooking?.bookingType || 'INDIVIDUAL',
          isMigrated: !!r.migrationRef,
          migrationRef: r.migrationRef,
          examCategory: r.examCategory || matchingBooking?.examCategory || 'OFFICIAL_EASA',
        } as ExamRecord)
      }
    }

    // Final sort and serialization
    const finalRecords = unifiedRecords.sort((a, b) => {
      const dateA = new Date(a.examDate || a.createdAt).getTime()
      const dateB = new Date(b.examDate || b.createdAt).getTime()
      if (dateB !== dateA) return dateB - dateA
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    }).slice(0, 2000)

    const serialized = serializePrisma(finalRecords)

    // eslint-disable-next-line react-hooks/error-boundaries
    return <RecordsTab records={serialized} modules={modules} />
  } catch (error) {
    console.error('[RecordsTabServer] Error:', error)
    return <DataUnavailableError />
  }
}

function DataUnavailableError() {
  return (
    <div className="rounded-2xl border-2 border-dashed border-slate-200 p-12 text-center dark:border-slate-800">
      <AlertCircle className="mx-auto mb-4 h-12 w-12 text-amber-500" />
      <h3 className="text-lg font-black text-slate-900 dark:text-white">Data temporarily unavailable</h3>
      <p className="mt-2 text-sm text-slate-500">The database connection timed out. Please refresh the page in a few moments.</p>
    </div>
  )
}

'use client'

import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import * as z from 'zod'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useState, useEffect } from 'react'
import { Loader2, Search, User, Check, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  FormDescription,
} from '@/components/ui/form'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'
import { ExamPool } from '@prisma/client'

interface AddCandidateFormProps {
  pool: any // Using any to key into complex include if needed. Wait, passing standard type + explicit props is better.
  // Actually, I fetched pool with details, so it has allowedModules.
  // Let's use `ExamPool` type and assume it's augmented or just use `any` temporarily for flexibility with Prisma includes.
}

const addCandidateSchema = z.object({
  userId: z.string().cuid('Please select a student'),
  selectedModule: z.string().min(1, 'Please select a module'),
})

type AddCandidateFormValues = z.infer<typeof addCandidateSchema>

export default function AddCandidateForm({ pool }: AddCandidateFormProps) {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<any[]>([])
  const [selectedUser, setSelectedUser] = useState<any>(null)

  const form = useForm<AddCandidateFormValues>({
    resolver: zodResolver(addCandidateSchema),
    defaultValues: {
      userId: '',
      selectedModule: '',
    },
  })

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(async () => {
      if (searchQuery.length >= 2) {
        try {
          const res = await fetch(`/api/staff/users/search?q=${encodeURIComponent(searchQuery)}`)
          const data = await res.json()
          if (res.ok) {
            setSearchResults(data)
          }
        } catch (error) {
          toast.error('Search failed')
        }
      } else {
        setSearchResults([])
      }
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery])

  const handleSelectUser = (user: any) => {
    setSelectedUser(user)
    form.setValue('userId', user.id)
    setSearchQuery('')
    setSearchResults([])
  }

  const handleClearUser = () => {
    setSelectedUser(null)
    form.setValue('userId', '')
  }

  async function onSubmit(values: AddCandidateFormValues) {
    setIsLoading(true)
    try {
      const response = await fetch(`/api/staff/exam-pools/${pool.id}/members`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(values),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || 'Failed to add candidate')
      }

      toast.success('Candidate added successfully')
      router.push(`/staff/exams/pools/${pool.id}`)
      router.refresh()
    } catch (error: any) {
      toast.error(error.message || 'Failed to add candidate')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        {/* User Search / Selection */}
        <div className="space-y-2">
          <FormLabel>Student</FormLabel>

          {selectedUser ? (
            <div className="flex items-center justify-between rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 p-3">
              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white dark:bg-slate-900 font-bold text-aerojet-blue shadow-sm">
                  <User className="h-5 w-5" />
                </div>
                <div>
                  <div className="font-bold text-slate-900 dark:text-slate-100">
                    {selectedUser.profile?.firstName} {selectedUser.profile?.lastName}
                  </div>
                  <div className="text-xs text-slate-500 dark:text-slate-400">{selectedUser.email}</div>
                </div>
              </div>
              <Button type="button" variant="ghost" size="sm" onClick={handleClearUser}>
                <X className="h-4 w-4" />
              </Button>
            </div>
          ) : (
            <div className="relative">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <Input
                id="candidate-search"
                placeholder="Search by name or email..."
                className="pl-10"
                autoComplete="off"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />

              {searchResults.length > 0 && (
                <div className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-lg border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-lg">
                  {searchResults.map((user) => (
                    <button
                      key={user.id}
                      type="button"
                      className="flex w-full items-center gap-3 px-4 py-3 text-left transition-all duration-150 ease-out hover:bg-white/80 dark:bg-slate-800/50 dark:hover:bg-slate-700/60"
                      onClick={() => handleSelectUser(user)}
                    >
                      <div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-100 text-xs font-bold text-slate-600 dark:text-slate-400">
                        {user.profile?.firstName?.charAt(0)}
                        {user.profile?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="text-sm font-medium text-slate-900 dark:text-slate-100">
                          {user.profile?.firstName} {user.profile?.lastName}
                        </div>
                        <div className="text-xs text-slate-500 dark:text-slate-400">{user.email}</div>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
          <input type="hidden" {...form.register('userId')} />
          {form.formState.errors.userId && (
            <p className="text-sm font-medium text-red-500">
              {form.formState.errors.userId.message}
            </p>
          )}
        </div>

        <FormField
          control={form.control}
          name="selectedModule"
          render={({ field }) => (
            <FormItem>
              <FormLabel htmlFor="candidate-module">Module</FormLabel>
              <Select onValueChange={field.onChange} defaultValue={field.value}>
                <FormControl>
                  <SelectTrigger id="candidate-module">
                    <SelectValue placeholder="Select a module" />
                  </SelectTrigger>
                </FormControl>
                <SelectContent>
                  {pool.allowedModules.map((module: string) => (
                    <SelectItem key={module} value={module}>
                      {module}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        <div className="flex justify-end gap-3 pt-4">
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
            disabled={isLoading}
          >
            Cancel
          </Button>
          <Button
            type="submit"
            className="bg-aerojet-blue px-8 hover:bg-aerojet-blue/90"
            disabled={isLoading || !selectedUser}
          >
            {isLoading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Adding...
              </>
            ) : (
              'Add Candidate'
            )}
          </Button>
        </div>
      </form>
    </Form>
  )
}

import { Metadata } from 'next'
import { getAuthSession } from '@/lib/auth/helpers'
import { redirect } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import Link from 'next/link'
import { ChevronLeft, Users, BookOpen, Search, Filter, Calendar } from 'lucide-react'
import SearchInput from '@/components/SearchInput'
import { buildOrderBy } from '@/lib/utils/build-order-by'
import { SortableTh } from '@/components/ui/sortable-th'
import type { Prisma } from '@prisma/client'

export const metadata: Metadata = { title: 'Booking Members Report | Staff Portal' }
export const dynamic = 'force-dynamic'

const ALLOWED_SORT_KEYS = {
  event: 'startDate',
  name: 'name',
  student: 'user.profile.lastName',
  module: 'examComponent.course.code',
  status: 'status',
} as const
type SortKey = keyof typeof ALLOWED_SORT_KEYS

export default async function PoolMembersReportPage({
  searchParams,
}: {
  searchParams: Promise<{ query?: string; sort?: string; order?: string }>
}) {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const params = await searchParams
  const query = params.query?.toLowerCase()
  const orderBy = buildOrderBy<SortKey>(params, ALLOWED_SORT_KEYS, { startDate: 'desc' })

  const events = await prismaUnfiltered.examEvent.findMany({
    where: {
      pools: {
        some: {},
      },
    },
    include: {
      pools: {
        include: {
          memberships: {
            where: query
              ? {
                  OR: [
                    { user: { profile: { firstName: { contains: query, mode: 'insensitive' } } } },
                    { user: { profile: { lastName: { contains: query, mode: 'insensitive' } } } },
                    { user: { email: { contains: query, mode: 'insensitive' } } },
                    {
                      user: {
                        studentProfile: { studentId: { contains: query, mode: 'insensitive' } },
                      },
                    },
                  ],
                }
              : undefined,
            include: {
              user: {
                include: {
                  profile: { select: { firstName: true, lastName: true } },
                  studentProfile: { select: { studentId: true } },
                },
              },
              examComponent: {
                include: { course: { select: { code: true } } },
              },
            },
          },
        },
      },
    },
    orderBy: orderBy as Prisma.ExamEventOrderByWithRelationInput,
  })

  // Filter out events/pools with no matching members after query
  const filteredEvents = events
    .map((event) => ({
      ...event,
      pools: event.pools
        .map((pool) => ({
          ...pool,
          memberships: pool.memberships,
        }))
        .filter((pool) => pool.memberships.length > 0),
    }))
    .filter((event) => event.pools.length > 0)

  return (
    <div className="mx-auto max-w-[1800px] space-y-8">
