            <DialogTitle className="text-sm font-black tracking-widest uppercase">
              Insert {pendingMediaType === 'IMAGE' ? 'Image' : 'Audio'} via URL
            </DialogTitle>
          </DialogHeader>
          <div className="flex items-center space-x-2 py-4">
            <div className="grid flex-1 gap-2">
              <Input
                id="media-url"
                placeholder={
                  pendingMediaType === 'IMAGE'
                    ? 'https://example.com/image.jpg'
                    : 'https://example.com/audio.mp3'
                }
                value={mediaUrl}
                onChange={(e) => setMediaUrl(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleUrlInsert()
                  }
                }}
                className="h-10 text-xs font-medium"
              />
            </div>
          </div>
          <DialogFooter className="sm:justify-start">
            <Button
              type="button"
              variant="default"
              onClick={handleUrlInsert}
              disabled={!mediaUrl}
              className="bg-aerojet-blue text-[10px] font-black tracking-widest uppercase"
            >
              Insert Media
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setIsUrlModalOpen(false)
                setMediaUrl('')
              }}
              className="text-[10px] font-black tracking-widest uppercase"
            >
              Cancel
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import {
  Info,
  AlertTriangle,
  AlertCircle,
  CheckCircle2,
  Clock,
  X,
  Siren,
} from 'lucide-react'
import { dismissStaffNotification } from '@/app/staff/actions/index'
import { Notification } from '@prisma/client'
import Link from 'next/link'

interface StaffNotificationCardProps {
  notification: Notification
  onDismiss?: (id: string) => void
}

export default function StaffNotificationCard({ notification, onDismiss }: StaffNotificationCardProps) {
  const [isRead, setIsRead] = useState(notification.isRead)
  const [isPending, startTransition] = useTransition()
  const [isDismissing, startDismissTransition] = useTransition()

  const handleMarkAsRead = () => {
    if (isRead || isPending) return
    setIsRead(true)
    // In a real implementation, you'd call a mark-as-read action here
  }

  const handleDismiss = async () => {
    if (isDismissing) return
    startDismissTransition(async () => {
      const result = await dismissStaffNotification(notification.id)
      if (result.success && onDismiss) {
        onDismiss(notification.id)
      }
    })
  }

  const isCritical = notification.type === 'CRITICAL'

  return (
    <div
      className={`group flex items-start gap-4 p-6 transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50 ${
        !isRead ? 'bg-red-50/30 dark:bg-red-900/5' : ''
      }`}
    >
      <div
        className={`mt-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${
          isCritical
            ? 'bg-red-50 text-red-600 dark:bg-red-900/30 dark:text-red-500'
            : notification.type === 'SUCCESS'
              ? 'bg-green-50 text-green-600 dark:bg-green-900/30 dark:text-green-500'
              : notification.type === 'WARNING'
                ? 'bg-amber-50 text-amber-600 dark:bg-amber-900/30 dark:text-amber-500'
                : notification.type === 'ERROR'
                  ? 'bg-red-50 text-red-600 dark:bg-red-900/30 dark:text-red-500'
                  : 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-500'
        }`}
      >
        {isCritical && <Siren className="h-5 w-5" />}
        {notification.type === 'SUCCESS' && <CheckCircle2 className="h-5 w-5" />}
        {notification.type === 'WARNING' && <AlertTriangle className="h-5 w-5" />}
        {notification.type === 'ERROR' && <AlertCircle className="h-5 w-5" />}
        {notification.type === 'INFO' && <Info className="h-5 w-5" />}
      </div>

      <div className="flex-1 space-y-1">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-2">
            <h3
              className={`font-bold text-slate-900 dark:text-slate-100 ${
                !isRead ? 'text-red-900 dark:text-red-100' : ''
              }`}
            >
              {notification.title}
            </h3>
            {isCritical && (
              <span className="rounded-full bg-red-100 px-2 py-0.5 text-[10px] font-black uppercase tracking-wider text-red-700 dark:bg-red-900/30 dark:text-red-400">
                Critical
              </span>
            )}
          </div>
          <div className="flex shrink-0 items-center gap-2">
            <div className="flex items-center gap-1 text-xs font-bold tracking-widest text-slate-400 uppercase">
              <Clock className="h-3 w-3" />
              {new Date(notification.createdAt).toLocaleDateString(undefined, {
                month: 'short',
                day: 'numeric',
              })}
            </div>
            {!isCritical && (
              <button
                type="button"
                onClick={handleDismiss}
                disabled={isDismissing}
                className="rounded-lg p-1 text-slate-300 transition-colors hover:bg-slate-100 hover:text-red-500 disabled:opacity-50 dark:hover:bg-slate-800"
                title="Dismiss notification"
              >
                <X className="h-4 w-4" />
              </button>
            )}
          </div>
        </div>
        <p className="text-sm leading-relaxed font-medium text-slate-500 dark:text-slate-400">
          {notification.message}
        </p>

        {notification.linkUrl && (
          <div className="mt-4">
            <Link
              href={notification.linkUrl}
              className="inline-flex items-center gap-2 text-xs font-black text-blue-600 transition-colors hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300"
            >
              {notification.linkText || 'View Details'}
              <span className="text-lg">→</span>
            </Link>
          </div>
        )}
      </div>

      {!isRead && !isCritical && (
        <div className="mt-2 h-2 w-2 rounded-full bg-blue-500 dark:bg-blue-400" />
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { BellOff, X, Trash2 } from 'lucide-react'
import TablePagination from '@/components/shared/TablePagination'
import StaffNotificationCard from './StaffNotificationCard'
import { Notification } from '@prisma/client'

interface StaffNotificationsListProps {
  notifications: Notification[]
}

export default function StaffNotificationsList({ notifications }: StaffNotificationsListProps) {
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(25)
  const [list, setList] = useState<Notification[]>(notifications)

  const total = list.length
  const paged = list.slice((page - 1) * perPage, page * perPage)

  const handleDismiss = (id: string) => {
    setList((prev) => prev.filter((n) => n.id !== id))
    if (paged.length === 1 && page > 1) {
      setPage((p) => p - 1)
    }
  }

  const handleDismissAll = () => {
    setList((prev) => prev.filter((n) => n.type === 'CRITICAL'))
    setPage(1)
  }

  if (total === 0) {
    return (
      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="p-16 text-center">
          <div className="mx-auto mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-slate-50 text-slate-200 dark:bg-slate-800/50">
            <BellOff className="h-10 w-10" />
          </div>
          <h3 className="text-xl font-black text-slate-900 dark:text-slate-100">
            All caught up!
          </h3>
          <p className="mx-auto mt-2 max-w-xs text-sm font-medium text-slate-500 dark:text-slate-400">
            You don&apos;t have any notifications at the moment.
          </p>
        </div>
      </div>
    )
  }

  const nonCriticalCount = list.filter((n) => n.type !== 'CRITICAL').length

  return (
    <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
      {nonCriticalCount > 0 && (
        <div className="flex items-center justify-end border-b border-slate-100 px-4 py-2 dark:border-slate-800">
          <button
            type="button"
            onClick={handleDismissAll}
            className="inline-flex items-center gap-1.5 text-xs font-bold text-slate-400 transition-colors hover:text-red-500"
          >
            <Trash2 className="h-3.5 w-3.5" />
            Dismiss all non-critical
          </button>
        </div>
      )}
      <div className="divide-y divide-slate-100 dark:divide-slate-800">
        {paged.map((notification) => (
          <StaffNotificationCard
            key={notification.id}
            notification={notification}
            onDismiss={handleDismiss}
          />
        ))}
      </div>
      <TablePagination page={page} perPage={perPage} total={total} onPageChange={setPage} onPerPageChange={setPerPage} />
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { UserPlus, Trash2, Star, Pencil, X } from 'lucide-react'
import { useRouter } from 'next/navigation'

interface Mentor {
  id: string
  mentorId: string
  assignedDate: string
  endDate?: string | null
  isPrimary: boolean
  notes: string | null
}

interface Props {
  logbookId: string
  mentorAssignments: Mentor[]
  availableMentors: Array<{ id: string; label: string }>
  staffId: string
}

export default function MentorAssignments({ logbookId, mentorAssignments, availableMentors, staffId }: Props) {
  const router = useRouter()
  const [selectedMentor, setSelectedMentor] = useState('')
  const [loading, setLoading] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editNotes, setEditNotes] = useState<Record<string, string>>({})
  const [editPrimary, setEditPrimary] = useState<Record<string, boolean>>({})

  const addMentor = async () => {
    if (!selectedMentor) return
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/ojt/${logbookId}/mentors`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mentorId: selectedMentor, isPrimary: mentorAssignments.length === 0 }),
      })
      if (!res.ok) throw new Error('Failed to assign mentor')
      toast.success('Mentor assigned')
      setSelectedMentor('')
      router.refresh()
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Failed to assign mentor')
    } finally {
      setLoading(false)
    }
  }

  const removeMentor = async (assignmentId: string) => {
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/ojt/${logbookId}/mentors/${assignmentId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to remove mentor')
      toast.success('Mentor removed')
      router.refresh()
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Failed to remove mentor')
    } finally {
      setLoading(false)
    }
  }

  const updateMentor = async (assignmentId: string) => {
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/ojt/${logbookId}/mentors/${assignmentId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          isPrimary: editPrimary[assignmentId] ?? false,
          notes: editNotes[assignmentId] ?? null,
        }),
      })
      if (!res.ok) throw new Error('Failed to update mentor')
      toast.success('Mentor updated')
      setEditingId(null)
      router.refresh()
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Failed to update mentor')
    } finally {
      setLoading(false)
    }
  }

  const startEdit = (m: Mentor) => {
    setEditingId(m.id)
    setEditNotes((n) => ({ ...n, [m.id]: m.notes || '' }))
    setEditPrimary((p) => ({ ...p, [m.id]: m.isPrimary }))
  }

  return (
    <div className="mt-6 rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
      <h3 className="text-lg font-black text-slate-900 dark:text-white">Mentor Assignments</h3>
      <div className="mt-4 space-y-3">
        {mentorAssignments.map((m) => {
          const mentor = availableMentors.find((a) => a.id === m.mentorId)
          const isEditing = editingId === m.id
          return (
            <div key={m.id} className="rounded-xl border border-slate-100 px-4 py-3 dark:border-slate-800">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-bold text-slate-700 dark:text-slate-200">{mentor?.label || 'Unknown'}</p>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    Assigned {new Date(m.assignedDate).toLocaleDateString('en-GB')}
                    {m.endDate && <> · Ended {new Date(m.endDate).toLocaleDateString('en-GB')}</>}
                  </p>
                  {m.isPrimary && <span className="ml-2 text-xs font-bold text-amber-600">★ Primary</span>}
                  {isEditing && (
                    <div className="mt-2 flex flex-col gap-2">
                      <label className="flex items-center gap-2 text-xs font-semibold text-slate-600 dark:text-slate-400">
                        <input
                          type="checkbox"
                          checked={editPrimary[m.id] || false}
                          onChange={(e) => setEditPrimary((p) => ({ ...p, [m.id]: e.target.checked }))}
                        />
                        Primary mentor
                      </label>
                      <textarea
                        value={editNotes[m.id] || ''}
                        onChange={(e) => setEditNotes((n) => ({ ...n, [m.id]: e.target.value }))}
                        placeholder="Mentor notes"
                        rows={2}
                        className="w-full rounded-lg border border-slate-200 px-2 py-1 text-xs dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                      />
                    </div>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  {isEditing ? (
                    <>
                      <button
                        onClick={() => updateMentor(m.id)}
                        disabled={loading}
                        className="rounded-lg bg-aerojet-blue px-2 py-1 text-xs font-bold text-white hover:bg-blue-700 disabled:opacity-50"
                      >
                        Save
                      </button>
                      <button
                        onClick={() => setEditingId(null)}
                        className="rounded-lg border border-slate-200 px-2 py-1 text-xs font-bold text-slate-600 dark:border-slate-700 dark:text-slate-300"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        onClick={() => startEdit(m)}
                        className="rounded-lg bg-slate-50 p-2 text-slate-500 hover:bg-slate-100 dark:bg-slate-800 dark:text-slate-400"
                        title="Edit mentor"
                      >
                        <Pencil className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => removeMentor(m.id)}
                        disabled={loading}
                        className="rounded-lg bg-red-50 p-2 text-red-600 hover:bg-red-100 disabled:opacity-50 dark:bg-red-900/30 dark:text-red-400"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          )
        })}
        {mentorAssignments.length === 0 && (
          <p className="text-xs text-slate-400">No mentors assigned yet.</p>
        )}
      </div>
      <div className="mt-4 flex gap-2">
        <select
          value={selectedMentor}
          onChange={(e) => setSelectedMentor(e.target.value)}
          className="flex-1 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs dark:border-slate-800 dark:bg-slate-800 dark:text-white"
        >
          <option value="">Select mentor...</option>
          {availableMentors
            .filter((m) => !mentorAssignments.some((a) => a.mentorId === m.id))
            .map((m) => (
              <option key={m.id} value={m.id}>{m.label}</option>
            ))}
        </select>
        <button
          onClick={addMentor}
          disabled={!selectedMentor || loading}
          className="rounded-xl bg-aerojet-blue px-4 py-2 text-xs font-bold text-white hover:bg-aerojet-sky disabled:opacity-50"
        >
          <UserPlus className="h-4 w-4" />
        </button>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Star, CheckCircle2, Circle, Shield, UserCheck } from 'lucide-react'
import { useRouter } from 'next/navigation'

interface Entry {
  id: string
  date: string
  aircraftType: string
  aircraftRegistration: string
  ataChapter: { code: string; title: string }
  taskDescription: string
  maintenanceType: string
  durationHours: number
  supervisorSignature: boolean
  studentSignature: boolean
  verifiedByManagement: boolean
  competencyRating: number | null
}

interface Props {
  entries: Entry[]
  logbookId: string
  staffId: string
}

export default function ReviewSignoffPanel({ entries, logbookId, staffId }: Props) {
  const router = useRouter()
  const [loadingId, setLoadingId] = useState<string | null>(null)
  const [commentId, setCommentId] = useState<string | null>(null)
  const [comments, setComments] = useState<Record<string, string>>({})

  const sign = async (entryId: string) => {
    setLoadingId(entryId)
    try {
      const res = await fetch(`/api/staff/ojt/entries/${entryId}/sign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ comments: comments[entryId] || null }),
      })
      if (!res.ok) throw new Error('Failed to sign')
      toast.success('Signed as supervisor')
      setComments((c) => ({ ...c, [entryId]: '' }))
      setCommentId(null)
      router.refresh()
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Failed to sign')
    } finally {
      setLoadingId(null)
    }
  }

  const verify = async (entryId: string) => {
    setLoadingId(entryId)
    try {
      const res = await fetch(`/api/staff/ojt/entries/${entryId}/verify`, { method: 'POST' })
      if (!res.ok) throw new Error('Failed to verify')
      toast.success('Verified by management')
      router.refresh()
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Failed to verify')
    } finally {
      setLoadingId(null)
    }
  }

  const rate = async (entryId: string, rating: number) => {
    setLoadingId(entryId)
    try {
      const res = await fetch(`/api/staff/ojt/entries/${entryId}/competency`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rating }),
      })
      if (!res.ok) throw new Error('Failed to rate')
      toast.success(`Rated ${rating}/5`)
      router.refresh()
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Failed to rate')
    } finally {
      setLoadingId(null)
    }
  }

  const statusBadge = (entry: Entry) => {
    if (entry.verifiedByManagement) {
      return <span className="rounded-full bg-emerald-100 px-2 py-1 text-[10px] font-black text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400">Fully Verified</span>
    }
    if (entry.supervisorSignature) {
      return <span className="rounded-full bg-blue-100 px-2 py-1 text-[10px] font-black text-blue-700 dark:bg-blue-900/30 dark:text-blue-400">Supervisor Signed</span>
    }
    return <span className="rounded-full bg-amber-100 px-2 py-1 text-[10px] font-black text-amber-700 dark:bg-amber-900/30 dark:text-amber-400">Unsigned</span>
  }

  return (
    <div className="mt-6 rounded-2xl border border-slate-100 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
      <h3 className="text-lg font-black text-slate-900 dark:text-white">Entry Review & Sign-off</h3>
      <div className="mt-4 overflow-x-auto">
        <table className="min-w-full text-left text-sm">
          <thead>
            <tr className="border-b border-slate-100 dark:border-slate-800">
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">Date</th>
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">ATA</th>
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">Task</th>
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">Type</th>
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">Hours</th>
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">Status</th>
              <th className="px-3 py-2 font-bold text-slate-500 dark:text-slate-400">Actions</th>
            </tr>
          </thead>
          <tbody>
            {entries.map((entry) => (
              <tr key={entry.id} className="border-b border-slate-50 dark:border-slate-800/50">
                <td className="px-3 py-3 text-xs text-slate-600 dark:text-slate-300">
                  {new Date(entry.date).toLocaleDateString('en-GB')}
                </td>
                <td className="px-3 py-3 text-xs font-bold text-slate-700 dark:text-slate-200">
                  {entry.ataChapter.code}
                </td>
                <td className="max-w-[240px] truncate px-3 py-3 text-xs text-slate-600 dark:text-slate-300">
                  {entry.taskDescription}
                </td>
                <td className="px-3 py-3 text-xs text-slate-500 dark:text-slate-400">{entry.maintenanceType}</td>
                <td className="px-3 py-3 text-xs font-bold text-slate-700 dark:text-slate-200">{entry.durationHours.toFixed(1)}</td>
                <td className="px-3 py-3">{statusBadge(entry)}</td>
                <td className="px-3 py-3">
                  <div className="flex flex-wrap gap-2">
                    {!entry.supervisorSignature && (
                      <div className="flex flex-col gap-1">
                        <button
                          onClick={() => setCommentId(commentId === entry.id ? null : entry.id)}
                          className="rounded-lg bg-slate-50 px-2 py-1 text-[10px] font-bold text-slate-600 hover:bg-slate-100 dark:bg-slate-800 dark:text-slate-400"
                        >
                          {commentId === entry.id ? 'Cancel' : 'Comment'}
                        </button>
                        {commentId === entry.id && (
                          <textarea
                            value={comments[entry.id] || ''}
                            onChange={(e) => setComments((c) => ({ ...c, [entry.id]: e.target.value }))}
                            placeholder="Supervisor comments (optional)"
                            rows={2}
                            className="w-full rounded-lg border border-slate-200 px-2 py-1 text-xs dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                          />
                        )}
                        <button
                          onClick={() => sign(entry.id)}
                          disabled={loadingId === entry.id}
                          className="rounded-lg bg-blue-50 px-2 py-1 text-[10px] font-bold text-blue-700 hover:bg-blue-100 disabled:opacity-50 dark:bg-blue-900/30 dark:text-blue-400"
                        >
                          {loadingId === entry.id ? '...' : 'Sign'}
                        </button>
                      </div>
                    )}
                    {entry.supervisorSignature && !entry.verifiedByManagement && (
                      <button
                        onClick={() => verify(entry.id)}
                        disabled={loadingId === entry.id}
                        className="rounded-lg bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-700 hover:bg-emerald-100 disabled:opacity-50 dark:bg-emerald-900/30 dark:text-emerald-400"
                      >
                        {loadingId === entry.id ? '...' : 'Verify'}
                      </button>
                    )}
                    <div className="flex items-center gap-1">
                      {[1, 2, 3, 4, 5].map((star) => (
                        <button
                          key={star}
                          onClick={() => rate(entry.id, star)}
                          disabled={loadingId === entry.id}
                          className="disabled:opacity-50"
                        >
                          <Star
                            className={`h-3.5 w-3.5 ${
                              entry.competencyRating && star <= entry.competencyRating
                                ? 'fill-amber-400 text-amber-400'
                                : 'text-slate-300 dark:text-slate-600'
                            }`}
                          />
                        </button>
                      ))}
                    </div>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

import { Metadata } from 'next'
import { requireStaff, getAuthSession } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { notFound } from 'next/navigation'
import LogbookDetail from './_components/LogbookDetail'

export const metadata: Metadata = { title: 'OJT Logbook Detail | Staff' }
export const dynamic = 'force-dynamic'

export default async function LogbookDetailPage({
  params,
}: {
  params: Promise<{ logbookId: string }>
}) {
  await requireStaff()
  const { logbookId } = await params
  const session = await getAuthSession()

  const [logbook, ataChapters, staffMembers] = await Promise.all([
    prismaUnfiltered.oJTLogbook.findUnique({
      where: { id: logbookId },
      include: {
        studentProfile: {
          select: {
            studentId: true,
            programmeChoice: true,
            userId: true,
            user: {
              select: {
                email: true,
                profile: { select: { firstName: true, lastName: true } },
              },
            },
          },
        },
        mentorAssignments: {
          include: {
            logbook: false,
          },
        },
        entries: {
          include: {
            ataChapter: { select: { id: true, code: true, title: true, category: true } },
          },
          orderBy: { date: 'desc' },
        },
      },
    }),
    prismaUnfiltered.aTAChapter.findMany({
      orderBy: { sortOrder: 'asc' },
      select: { id: true, code: true, title: true, category: true },
    }),
    prismaUnfiltered.user.findMany({
      where: { role: { in: ['ADMIN', 'STAFF', 'INSTRUCTOR'] } },
      select: {
        id: true,
        email: true,
        profile: { select: { firstName: true, lastName: true } },
      },
      take: 100,
    }),
  ])

  if (!logbook) return notFound()

  // Calculate analytics
  const totalHours = logbook.entries.reduce((s, e) => s + e.durationHours, 0)
  const hoursByType: Record<string, number> = {}
  for (const e of logbook.entries) {
    hoursByType[e.maintenanceType] = (hoursByType[e.maintenanceType] || 0) + e.durationHours
  }
  const coveredChapters = new Set(logbook.entries.map((e) => e.ataChapterId))
  const signedCount = logbook.entries.filter(
    (e) => e.supervisorSignature && e.studentSignature
  ).length
  const startDate = logbook.startDate
  const monthsExperience = Math.floor(
    // eslint-disable-next-line react-hooks/purity
    (Date.now() - startDate.getTime()) / (30.44 * 24 * 60 * 60 * 1000)
  )

  const studentName = logbook.studentProfile.user.profile
    ? `${logbook.studentProfile.user.profile.firstName ?? ''} ${logbook.studentProfile.user.profile.lastName ?? ''}`.trim()
    : logbook.studentProfile.user.email

  const serialised = {
    id: logbook.id,
    studentName,
    studentId: logbook.studentProfile.studentId,
    email: logbook.studentProfile.user.email,
    programme: logbook.studentProfile.programmeChoice ?? 'Unknown',
    licenceCategory: logbook.licenceCategory,
    facilityName: logbook.facilityName,
    facilityApprovalNo: logbook.facilityApprovalNo,
    startDate: logbook.startDate.toISOString(),
    targetEndDate: logbook.targetEndDate?.toISOString() ?? null,
    totalLoggedHours: logbook.totalLoggedHours,
    status: logbook.status,
    entries: logbook.entries.map((e) => ({
      id: e.id,
      date: e.date.toISOString(),
      aircraftType: e.aircraftType,
      aircraftRegistration: e.aircraftRegistration,
      ataChapterId: e.ataChapter.id,
      ataChapter: e.ataChapter,
      taskDescription: e.taskDescription,
      workOrderReference: e.workOrderReference,
      maintenanceManualRef: e.maintenanceManualRef,
      maintenanceType: e.maintenanceType,
      durationHours: e.durationHours,
      supervisorId: e.supervisorId,
      supervisorSignature: e.supervisorSignature,
      studentSignature: e.studentSignature,
      verifiedByManagement: e.verifiedByManagement,
      licenceCategory: e.licenceCategory,
      workEnvironment: e.workEnvironment,
      toolsUsed: e.toolsUsed,
      partNumbersUsed: e.partNumbersUsed,
      safetyPrecautions: e.safetyPrecautions,
      competencyRating: e.competencyRating,
    })),
    analytics: {
      monthsExperience,
      totalHours: Math.round(totalHours * 10) / 10,
      hoursByType: Object.fromEntries(
        Object.entries(hoursByType).map(([k, v]) => [k, Math.round(v * 10) / 10])
      ),
      ataChaptersCovered: coveredChapters.size,
      totalATAChapters: ataChapters.length,
      signedEntries: signedCount,
      unsignedEntries: logbook.entries.length - signedCount,
    },
    mentorAssignments: logbook.mentorAssignments.map((m) => ({
      id: m.id,
      mentorId: m.mentorId,
      assignedDate: m.assignedDate.toISOString(),
      endDate: m.endDate?.toISOString() ?? null,
      isPrimary: m.isPrimary,
      notes: m.notes,
    })),
  }

  const ataOptions = ataChapters.map((ch) => ({
    id: ch.id,
    label: `${ch.code} — ${ch.title}`,
    category: ch.category,
  }))

  const supervisorOptions = staffMembers.map((s) => ({
    id: s.id,
    label: s.profile
      ? `${s.profile.firstName ?? ''} ${s.profile.lastName ?? ''}`.trim() || s.email
      : s.email,
  }))

  return (
    <LogbookDetail
      logbook={serialised}
      ataChapters={ataOptions}
      supervisors={supervisorOptions}
      staffId={logbook.studentProfile.userId}
      mentorAssignments={serialised.mentorAssignments}
    />
  )
}

'use client'

import { useState, useMemo } from 'react'
import { Plus, Calendar, CheckCircle, XCircle, AlertTriangle, ShieldCheck, UserCheck, X, Loader2, Edit, Trash2 } from 'lucide-react'
import { useRouter } from 'next/navigation'
import { useConfirmDialog } from '@/hooks/use-confirm-dialog'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'
import { useToast } from '@/hooks/use-toast'

type PracticalResult = 'SATISFACTORY' | 'UNSATISFACTORY' | 'NEEDS_REVIEW'
type PracticalTaskCategory = 'P1' | 'P2'
type PracticalDeliveryMethod = 'TASK_PERFORMANCE' | 'DEMONSTRATION' | 'TECHNICAL_DISCUSSION' | 'SIMULATION'

interface RecordItem {
  id: string
  date: string
  studentProfileId: string
  courseId: string
  taskCategory: PracticalTaskCategory
  taskReference: string | null
  ataChapterId: string | null
  description: string
  deliveryMethod: PracticalDeliveryMethod
  durationMinutes: number
  result: PracticalResult | null
  signedByInstructor: boolean
  signedByStudent: boolean
  assessorNotes: string | null
  course: { id: string; code: string; name: string }
  ataChapter: { id: string; code: string; title: string } | null
  instructorId: string
  instructor: { id: string; profile: { firstName: string; lastName: string } | null }
  studentProfile: {
    id: string
    studentId: string
    user: { profile: { firstName: string; lastName: string } | null }
  }
}

const DEFAULT_FORM = {
  studentProfileId: '',
  courseId: '',
  taskCategory: 'P1' as PracticalTaskCategory,
  taskReference: '',
  ataChapterId: '',
  description: '',
  deliveryMethod: 'TASK_PERFORMANCE' as PracticalDeliveryMethod,
  date: new Date().toISOString().split('T')[0],
  durationMinutes: 60,
  instructorId: '',
  result: '' as PracticalResult | '',
  assessorNotes: '',
}

export default function PracticalAssessmentsClient({
  initialRecords,
  courses,
  students,
  instructors,
  ataChapters,
}: {
  initialRecords: any[]
  courses: any[]
  students: any[]
  instructors: any[]
  ataChapters: any[]
}) {
  const router = useRouter()
  const confirmDialog = useConfirmDialog()
  const toast = useToast()
  const [records, setRecords] = useState<RecordItem[]>(initialRecords as unknown as RecordItem[])
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [isActionPending, setIsActionPending] = useState(false)
  
  // Filters state
  const [studentFilter, setStudentFilter] = useState('')
  const [courseFilter, setCourseFilter] = useState('')
  const [resultFilter, setResultFilter] = useState('')

  // New Record Form state
  const [formData, setFormData] = useState(DEFAULT_FORM)

  const handleCreateClick = () => {
    setFormData(DEFAULT_FORM)
    setEditingId(null)
    setIsModalOpen(true)
  }

  const handleEditClick = (rec: RecordItem) => {
    setEditingId(rec.id)
    setFormData({
      studentProfileId: rec.studentProfileId,
      courseId: rec.courseId,
      taskCategory: rec.taskCategory,
      taskReference: rec.taskReference || '',
      ataChapterId: rec.ataChapterId || '',
      description: rec.description,
      deliveryMethod: rec.deliveryMethod,
      date: new Date(rec.date).toISOString().split('T')[0],
      durationMinutes: rec.durationMinutes,
      instructorId: rec.instructorId,
      result: rec.result || '',
      assessorNotes: rec.assessorNotes || '',
    })
    setIsModalOpen(true)
  }

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsActionPending(true)
    try {
      const payload = {
        ...formData,
        durationMinutes: Number(formData.durationMinutes),
        result: formData.result || undefined,
      }

      const isEditing = !!editingId
      const url = isEditing ? `/api/staff/practical-training/${editingId}` : '/api/staff/practical-training'
      const method = isEditing ? 'PUT' : 'POST'
      
      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(isEditing ? { ...payload, isFullEdit: true } : payload),
      })

      if (!res.ok) {
        const err = await res.json()
        toast.error(err.error || 'Failed to save practical record')
      } else {
        toast.success(isEditing ? 'Practical record updated successfully!' : 'Practical assessment record saved successfully!')
        setIsModalOpen(false)
        window.location.reload()
      }
    } catch (error) {
      toast.error('An unexpected error occurred.')
    } finally {
      setIsActionPending(false)
    }
  }

  const signRecord = (id: string, approve: boolean) => {
    confirmDialog.confirm({
      title: approve ? 'Approve and Sign' : 'Sign Record',
      description: approve 
        ? 'Are you sure you want to sign this practical record as Satisfactory? This will mark the task as complete.'
        : 'Are you sure you want to apply your instructor signature to this record?',
      onConfirm: async () => {
        setIsActionPending(true)
        try {
          const res = await fetch(`/api/staff/practical-training/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              signedByInstructor: true,
              result: approve ? 'SATISFACTORY' : undefined,
            }),
          })
          if (res.ok) {
            toast.success('Record signed successfully.')
            window.location.reload()
          } else {
            toast.error('Failed to sign record.')
          }
        } catch {
          toast.error('An unexpected error occurred.')
        } finally {
          setIsActionPending(false)
          confirmDialog.close()
        }
      }
    })
  }

  const deleteRecord = (id: string) => {
    confirmDialog.confirm({
      title: 'Delete Practical Record',
      description: 'Are you sure you want to permanently delete this record? This action cannot be undone.',
      onConfirm: async () => {
        setIsActionPending(true)
        try {
          const res = await fetch(`/api/staff/practical-training/${id}`, {
            method: 'DELETE',
          })
          if (res.ok) {
            toast.success('Record deleted successfully.')
            window.location.reload()
          } else {
            const err = await res.json()
            toast.error(err.error || 'Failed to delete record.')
          }
        } catch {
          toast.error('An unexpected error occurred.')
        } finally {
          setIsActionPending(false)
          confirmDialog.close()
        }
      }
    })
  }

  const filteredRecords = useMemo(() => {
    return records.filter((rec) => {
      const profile = rec.studentProfile?.user?.profile
      const stdName = profile ? `${profile.firstName} ${profile.lastName}`.toLowerCase() : ''
      const matchesStd = studentFilter === '' || rec.studentProfileId === studentFilter || stdName.includes(studentFilter.toLowerCase())
      const matchesCourse = courseFilter === '' || rec.course.id === courseFilter
      const matchesResult = resultFilter === '' || (rec.result || 'PENDING') === resultFilter
      return matchesStd && matchesCourse && matchesResult
    })
  }, [records, studentFilter, courseFilter, resultFilter])

  const getResultBadge = (res: PracticalResult | null) => {
    if (!res) return <span className="inline-flex items-center rounded-full bg-yellow-100 px-2.5 py-0.5 text-xs font-semibold text-yellow-800 dark:bg-yellow-500/10 dark:text-yellow-400">Pending Review</span>
    switch (res) {
      case 'SATISFACTORY':
        return <span className="inline-flex items-center gap-1 rounded-full bg-emerald-100 px-2.5 py-0.5 text-xs font-semibold text-emerald-800 dark:bg-emerald-500/10 dark:text-emerald-400"><CheckCircle className="h-3 w-3" /> Satisfactory</span>
      case 'NEEDS_REVIEW':
        return <span className="inline-flex items-center gap-1 rounded-full bg-orange-100 px-2.5 py-0.5 text-xs font-semibold text-orange-800 dark:bg-orange-500/10 dark:text-orange-400"><AlertTriangle className="h-3 w-3" /> Needs Review</span>
      case 'UNSATISFACTORY':
        return <span className="inline-flex items-center gap-1 rounded-full bg-rose-100 px-2.5 py-0.5 text-xs font-semibold text-rose-800 dark:bg-rose-500/10 dark:text-rose-400"><XCircle className="h-3 w-3" /> Fail</span>
    }
  }

  return (
    <div className="space-y-6">
      {/* Custom Confirmation Dialog */}
      <ConfirmDialog
        open={confirmDialog.open}
        onOpenChange={confirmDialog.onOpenChange}
        title={confirmDialog.title}
        description={confirmDialog.description}
        onConfirm={confirmDialog.onConfirm}
        loading={isActionPending}
      />

      {/* Top actions & filters */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-wrap gap-3">
          <select
            value={courseFilter}
            onChange={(e) => setCourseFilter(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-700 shadow-sm transition focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
          >
            <option value="">All Courses / Modules</option>
            {courses.map(c => (
              <option key={c.id} value={c.id}>{c.code} - {c.name}</option>
            ))}
          </select>

          <select
            value={studentFilter}
            onChange={(e) => setStudentFilter(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-700 shadow-sm transition focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
          >
            <option value="">All Students</option>
            {students.map(s => (
              <option key={s.id} value={s.id}>{s.studentId} — {s.user?.profile?.firstName || ''} {s.user?.profile?.lastName || ''}</option>
            ))}
          </select>

          <select
            value={resultFilter}
            onChange={(e) => setResultFilter(e.target.value)}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-700 shadow-sm transition focus:border-blue-500 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
          >
            <option value="">All Results</option>
            <option value="PENDING">Pending Assessment</option>
            <option value="SATISFACTORY">Satisfactory</option>
            <option value="NEEDS_REVIEW">Needs Review</option>
            <option value="UNSATISFACTORY">Unsatisfactory</option>
          </select>
        </div>

        <button
          onClick={handleCreateClick}
          className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white shadow-sm transition hover:bg-blue-700 active:scale-95"
        >
          <Plus className="h-4 w-4" />
          Log Practical Record
        </button>
      </div>

      {/* Main Data Table */}
      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-xs font-semibold uppercase tracking-wider text-slate-500 dark:bg-slate-800/50 dark:text-slate-400">
            <tr>
              <th className="px-6 py-4">Date / Module</th>
              <th className="px-6 py-4">Student</th>
              <th className="px-6 py-4">Task Detail</th>
              <th className="px-6 py-4">Result / Cat</th>
              <th className="px-6 py-4 text-center">Signatures</th>
              <th className="px-6 py-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200/60 dark:divide-slate-700/60">
            {filteredRecords.map((rec) => (
              <tr key={rec.id} className="transition hover:bg-slate-50/30 dark:hover:bg-slate-800/30">
                <td className="whitespace-nowrap px-6 py-4">
                  <div className="flex items-center gap-2 font-semibold text-slate-900 dark:text-white">
                    <Calendar className="h-4 w-4 text-slate-400" />
                    {new Date(rec.date).toLocaleDateString()}
                  </div>
                  <div className="mt-1 inline-flex rounded-full bg-slate-100 px-2.5 py-0.5 text-xs font-bold text-slate-700 dark:bg-slate-800 dark:text-slate-300">
                    {rec.course.code}
                  </div>
                </td>

                <td className="px-6 py-4">
                  <div className="font-bold text-slate-900 dark:text-white">
                    {rec.studentProfile?.user?.profile?.firstName || 'Unknown'} {rec.studentProfile?.user?.profile?.lastName || 'Student'}
                  </div>
                  <div className="mt-0.5 font-mono text-xs text-slate-500 dark:text-slate-400">
                    ID: {rec.studentProfile?.studentId}
                  </div>
                </td>

                <td className="px-6 py-4 max-w-xs">
                  <div className="font-medium text-slate-800 dark:text-slate-200 line-clamp-1">
                    {rec.description}
                  </div>
                  <div className="mt-1 flex flex-wrap gap-1 text-xs">
                    {rec.ataChapter && (
                      <span className="font-bold text-blue-600 dark:text-blue-400">
                        ATA {rec.ataChapter.code}
                      </span>
                    )}
                    <span className="text-slate-400">•</span>
                    <span className="text-slate-500 uppercase">
                      {rec.deliveryMethod.replace('_', ' ')}
                    </span>
                  </div>
                </td>

                <td className="whitespace-nowrap px-6 py-4">
                  <div>{getResultBadge(rec.result)}</div>
                  <div className="mt-1 flex items-center gap-1 font-mono text-[10px] font-black text-slate-400">
                    TASK CAT: <span className="text-slate-600 dark:text-slate-300">{rec.taskCategory}</span>
                  </div>
                </td>

                <td className="px-6 py-4 text-center">
                  <div className="flex flex-col items-center gap-1">
                    <div className="flex gap-2">
                      <span
                        title="Instructor Signature"
                        className={`inline-flex h-6 w-6 items-center justify-center rounded-full text-xs ${
                          rec.signedByInstructor
                            ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400'
                            : 'bg-slate-100 text-slate-400 dark:bg-slate-800'
                        }`}
                      >
                        Ins
                      </span>
                      <span
                        title="Student Signature"
                        className={`inline-flex h-6 w-6 items-center justify-center rounded-full text-xs ${
                          rec.signedByStudent
                            ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-500/20 dark:text-indigo-400'
                            : 'bg-slate-100 text-slate-400 dark:bg-slate-800'
                        }`}
                      >
                        Std
                      </span>
                    </div>
                  </div>
                </td>

                <td className="whitespace-nowrap px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    {!rec.signedByInstructor ? (
                      <button
                        onClick={() => signRecord(rec.id, !rec.result)}
                        disabled={isActionPending}
                        className="inline-flex items-center gap-1 rounded-lg bg-blue-50 px-3 py-1.5 text-xs font-bold text-blue-700 transition hover:bg-blue-100 active:scale-95 dark:bg-blue-500/10 dark:text-blue-400 dark:hover:bg-blue-500/20"
                      >
                        <UserCheck className="h-3.5 w-3.5" />
                        Sign
                      </button>
                    ) : (
                      <span className="inline-flex items-center gap-1 text-xs font-semibold text-emerald-600 dark:text-emerald-400 mr-2">
                        <ShieldCheck className="h-4 w-4" /> Complete
                      </span>
                    )}
                    
                    <button
                      onClick={() => handleEditClick(rec)}
                      title="Edit Record"
                      className="rounded-lg border border-slate-200 p-1.5 text-slate-500 hover:bg-slate-100 hover:text-blue-600 dark:border-slate-700 dark:hover:bg-slate-800"
                    >
                      <Edit className="h-3.5 w-3.5" />
                    </button>
                    
                    <button
                      onClick={() => deleteRecord(rec.id)}
                      title="Delete Record"
                      className="rounded-lg border border-slate-200 p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600 dark:border-slate-700 dark:hover:bg-red-950/30"
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredRecords.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center font-medium text-slate-500">
                  No practical assessment records found for current selection.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Log/Edit Record Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
          <div className="relative w-full max-w-2xl overflow-y-auto max-h-[90vh] rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
            <div className="flex items-center justify-between border-b border-slate-200/60 pb-4 dark:border-slate-700/60">
              <h2 className="text-xl font-black text-slate-900 dark:text-white">
                {editingId ? 'Edit Practical Record' : 'Log New Practical Training Record'}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="rounded-lg p-1 hover:bg-slate-100 dark:hover:bg-slate-800">
                <X className="h-5 w-5 text-slate-400" />
              </button>
            </div>

            <form onSubmit={handleSave} className="mt-6 space-y-5">
              <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Student <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={formData.studentProfileId}
                    onChange={(e) => setFormData({ ...formData, studentProfileId: e.target.value })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  >
                    <option value="">-- Select Student --</option>
                    {students.map(s => (
                      <option key={s.id} value={s.id}>{s.studentId} — {s.user?.profile?.firstName || ''} {s.user?.profile?.lastName || ''}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Course / Module <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={formData.courseId}
                    onChange={(e) => setFormData({ ...formData, courseId: e.target.value })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  >
                    <option value="">-- Select Module --</option>
                    {courses.map(c => (
                      <option key={c.id} value={c.id}>{c.code} — {c.name}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Practical category <span className="text-red-500">*</span>
                  </label>
                  <div className="flex gap-3">
                    {(['P1', 'P2'] as const).map((cat) => (
                      <button
                        key={cat}
                        type="button"
                        onClick={() => setFormData({ ...formData, taskCategory: cat })}
                        className={`flex-1 rounded-lg border py-2 text-center text-sm font-bold shadow-sm transition ${
                          formData.taskCategory === cat
                            ? 'border-blue-600 bg-blue-50 text-blue-700 dark:border-blue-500 dark:bg-blue-500/10 dark:text-blue-400'
                            : 'border-slate-200 bg-white hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300'
                        }`}
                      >
                        {cat} Task
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    ATA Chapter
                  </label>
                  <select
                    value={formData.ataChapterId}
                    onChange={(e) => setFormData({ ...formData, ataChapterId: e.target.value })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  >
                    <option value="">-- Select ATA Chapter (Optional) --</option>
                    {ataChapters.map(c => (
                      <option key={c.id} value={c.id}>{c.code} — {c.title}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Date Conducted <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="date"
                    required
                    value={formData.date}
                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Duration (Minutes) <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    required
                    min={15}
                    value={formData.durationMinutes}
                    onChange={(e) => setFormData({ ...formData, durationMinutes: Number(e.target.value) })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Responsible Instructor <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={formData.instructorId}
                    onChange={(e) => setFormData({ ...formData, instructorId: e.target.value })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  >
                    <option value="">-- Select Instructor --</option>
                    {instructors.map(i => (
                      <option key={i.id} value={i.id}>{i.profile?.firstName || ''} {i.profile?.lastName || ''}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                    Delivery Method <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={formData.deliveryMethod}
                    onChange={(e) => setFormData({ ...formData, deliveryMethod: e.target.value as PracticalDeliveryMethod })}
                    className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  >
                    <option value="TASK_PERFORMANCE">Task Performance</option>
                    <option value="DEMONSTRATION">Demonstration</option>
                    <option value="TECHNICAL_DISCUSSION">Technical Discussion</option>
                    <option value="SIMULATION">Simulation</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                  Task / Manual Reference
                </label>
                <input
                  type="text"
                  placeholder="e.g. AMM 24-20-00, Job Card #2024-12"
                  value={formData.taskReference}
                  onChange={(e) => setFormData({ ...formData, taskReference: e.target.value })}
                  className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                  Task Description <span className="text-red-500">*</span>
                </label>
                <textarea
                  required
                  rows={3}
                  placeholder="Describe the practical task, tools used, and objective performed..."
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                />
              </div>

              <div className="border-t border-slate-200/60 pt-4 dark:border-slate-700/60">
                <h3 className="text-sm font-black text-slate-800 dark:text-white mb-3">Assessment</h3>
                <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                      Result / Competency
                    </label>
                    <select
                      value={formData.result}
                      onChange={(e) => setFormData({ ...formData, result: e.target.value as PracticalResult })}
                      className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                    >
                      <option value="">-- Leave Unassessed (Pending) --</option>
                      <option value="SATISFACTORY">Satisfactory</option>
                      <option value="NEEDS_REVIEW">Needs Review</option>
                      <option value="UNSATISFACTORY">Unsatisfactory</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400 mb-1">
                      Instructor Notes
                    </label>
                    <input
                      type="text"
                      placeholder="e.g. Good handling of safety wire..."
                      value={formData.assessorNotes}
                      onChange={(e) => setFormData({ ...formData, assessorNotes: e.target.value })}
                      className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium shadow-sm transition focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                    />
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-end gap-3 border-t border-slate-200/60 pt-4 dark:border-slate-700/60 mt-6">
                <button
                  type="button"
                  disabled={isActionPending}
                  onClick={() => setIsModalOpen(false)}
                  className="rounded-lg px-4 py-2 text-sm font-bold text-slate-700 transition hover:bg-slate-100 active:scale-95 dark:text-slate-300 dark:hover:bg-slate-800"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isActionPending}
                  className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-6 py-2 text-sm font-bold text-white shadow-md transition hover:bg-blue-700 active:scale-95 disabled:opacity-60"
                >
                  {isActionPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle className="h-4 w-4" />}
                  {editingId ? 'Update Practical Task' : 'Save Practical Task'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import {
  Plus,
  Loader2,
  GraduationCap,
  ChevronDown,
  ChevronRight,
  Users,
  Calendar,
} from 'lucide-react'

export interface ProgrammeSemester {
  name: string
  startDate: string
  endDate: string
}

interface ProgrammeYear {
  id: string
  yearNumber: number
  yearFeeAmount: string | null
  seatConfirmationFee: string
  firstPaymentAmount: string
  semesters: ProgrammeSemester[]
  isActive: boolean
}

interface Programme {
  id: string
  code: string
  name: string
  durationYears: number
  totalFee: string
  currency: string
  description: string | null
  isActive: boolean
  programmeYears: ProgrammeYear[]
  _count: { enrollments: number }
}

export default function ProgrammesClient({ programmes }: { programmes: Programme[] }) {
  const router = useRouter()
  const [createOpen, setCreateOpen] = useState(false)
  const [yearOpen, setYearOpen] = useState(false)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  // Edit programme form state
  const [editOpen, setEditOpen] = useState(false)
  const [editingProgrammeId, setEditingProgrammeId] = useState<string | null>(null)
  const [isActive, setIsActive] = useState(true)

  // Create programme form
  const [code, setCode] = useState('')
  const [name, setName] = useState('')
  const [durationYears, setDurationYears] = useState('4')
  const [totalFee, setTotalFee] = useState('')
  const [description, setDescription] = useState('')

  // Add/Edit year form
  const [yearProgrammeId, setYearProgrammeId] = useState('')
  const [editingYearId, setEditingYearId] = useState<string | null>(null)
  const [yearNumber, setYearNumber] = useState('')
  const [yearFee, setYearFee] = useState('')
  const [seatFee, setSeatFee] = useState('1500')
  const [firstPayment, setFirstPayment] = useState('3500')
  const [semesters, setSemesters] = useState<ProgrammeSemester[]>([
    { name: 'Semester 1', startDate: '', endDate: '' },
    { name: 'Semester 2', startDate: '', endDate: '' },
  ])

  const handleCreateProgramme = async () => {
    if (!code || !name || !totalFee) {
      setError('Code, name, and total fee are required')
      return
    }
    setLoading(true)
    setError('')
    try {
      const res = await fetch('/api/staff/programmes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, name, durationYears, totalFee, description }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to create')
      setCreateOpen(false)
      setCode('')
      setName('')
      setTotalFee('')
      setDescription('')
      router.refresh()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const openEditProgramme = (programme: Programme) => {
    setEditingProgrammeId(programme.id)
    setCode(programme.code)
    setName(programme.name)
    setDurationYears(String(programme.durationYears))
    setTotalFee(programme.totalFee)
    setDescription(programme.description || '')
    setIsActive(programme.isActive)
    setError('')
    setEditOpen(true)
  }

  const handleEditProgramme = async () => {
    if (!name || !totalFee) {
      setError('Name and total fee are required')
      return
    }
    setLoading(true)
    setError('')
    try {
      const res = await fetch(`/api/staff/programmes/${editingProgrammeId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, totalFee, description, isActive }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to update')
      setEditOpen(false)
      setCode('')
      setName('')
      setTotalFee('')
      setDescription('')
      router.refresh()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const openAddYear = (programmeId: string) => {
    setEditingYearId(null)
    setYearProgrammeId(programmeId)
    const prog = programmes.find((p) => p.id === programmeId)
    const nextYear = (prog?.programmeYears.length || 0) + 1
    setYearNumber(String(nextYear))
    setYearFee('')
    setSeatFee('1500')
    setFirstPayment('3500')
    setSemesters([
      { name: 'Semester 1', startDate: '', endDate: '' },
      { name: 'Semester 2', startDate: '', endDate: '' },
    ])
    setError('')
    setYearOpen(true)
  }

  const openEditYear = (programmeId: string, year: ProgrammeYear) => {
    setEditingYearId(year.id)
    setYearProgrammeId(programmeId)
    setYearNumber(String(year.yearNumber))
    setYearFee(year.yearFeeAmount || '')
    setSeatFee(year.seatConfirmationFee)
    setFirstPayment(year.firstPaymentAmount)
    setSemesters(
      year.semesters && year.semesters.length > 0
        ? [...year.semesters]
        : [
            { name: 'Semester 1', startDate: '', endDate: '' },
            { name: 'Semester 2', startDate: '', endDate: '' },
          ]
    )
    setError('')
    setYearOpen(true)
  }

  const handleSaveYear = async () => {
    if (semesters.some((s) => !s.startDate || !s.endDate)) {
      setError('All semesters must have start and end dates')
      return
    }
    setLoading(true)
    setError('')
    try {
      const isEditing = !!editingYearId
      const url = isEditing
        ? `/api/staff/programmes/${yearProgrammeId}/years`
        : `/api/staff/programmes/${yearProgrammeId}/years`

      const method = isEditing ? 'PATCH' : 'POST'

      const body = {
        ...(isEditing ? { yearId: editingYearId } : { yearNumber }),
        yearFeeAmount: yearFee || null,
        seatConfirmationFee: seatFee,
        firstPaymentAmount: firstPayment,
        semesters: semesters,
      }

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to save year')
      setYearOpen(false)
      router.refresh()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const handleAddSemester = () => {
    setSemesters([
      ...semesters,
      { name: `Semester ${semesters.length + 1}`, startDate: '', endDate: '' },
    ])
  }

  const handleRemoveSemester = (index: number) => {
    setSemesters(semesters.filter((_, i) => i !== index))
  }

  const handleSemesterChange = (index: number, field: keyof ProgrammeSemester, value: string) => {
    const newSemesters = [...semesters]
    newSemesters[index] = { ...newSemesters[index], [field]: value }
    setSemesters(newSemesters)
  }

  return (
    <div className="mx-auto max-w-[1800px]">
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black tracking-tight text-aerojet-blue dark:text-white">
            Full-Time Programmes
          </h1>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            Manage programme structures, fees, and year configurations
          </p>
        </div>
        <Dialog open={createOpen} onOpenChange={setCreateOpen}>
          <DialogTrigger asChild>
            <Button className="gap-2">
              <Plus className="h-4 w-4" /> Add Programme
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[480px]">
            <DialogHeader>
              <DialogTitle>Create Programme</DialogTitle>
              <DialogDescription className="sr-only">
                Enter the details for a new full-time training programme.
              </DialogDescription>
            </DialogHeader>
            <div className="mt-4 space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="prog-code" className="mb-1 block text-xs font-bold text-slate-600">Code</label>
                  <input
                    id="prog-code"
                    name="code"
                    value={code}
                    onChange={(e) => setCode(e.target.value)}
                    placeholder="FT_4Y_B1B2"
                    autoComplete="off"
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
                <div>
                  <label htmlFor="prog-duration" className="mb-1 block text-xs font-bold text-slate-600">
                    Duration (years)
                  </label>
                  <input
                    id="prog-duration"
                    name="durationYears"
                    type="number"
                    value={durationYears}
                    onChange={(e) => setDurationYears(e.target.value)}
                    autoComplete="off"
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
              </div>
              <div>
                <label htmlFor="prog-name" className="mb-1 block text-xs font-bold text-slate-600">Name</label>
                <input
                  id="prog-name"
                  name="name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Full-Time 4-Year B1+B2"
                  autoComplete="off"
                  className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
              <div>
                <label htmlFor="prog-fee" className="mb-1 block text-xs font-bold text-slate-600">Total Fee</label>
                <input
                  id="prog-fee"
                  name="totalFee"
                  type="number"
                  value={totalFee}
                  onChange={(e) => setTotalFee(e.target.value)}
                  placeholder="32000"
                  autoComplete="off"
                  className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
              <div>
                <label htmlFor="prog-desc" className="mb-1 block text-xs font-bold text-slate-600">Description</label>
                <textarea
                  id="prog-desc"
                  name="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  rows={2}
                  autoComplete="off"
                  className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
              {error && <p className="text-sm text-red-600">{error}</p>}
            </div>
            <div className="mt-4 flex justify-end gap-3">
              <Button variant="outline" onClick={() => setCreateOpen(false)} disabled={loading}>
                Cancel
              </Button>
              <Button onClick={handleCreateProgramme} disabled={loading}>
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Create'}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {/* Programme List */}
      <div className="space-y-4">
        {programmes.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-slate-200 p-12 text-center dark:border-slate-800">
            <GraduationCap className="mx-auto mb-3 h-10 w-10 text-slate-300" />
            <p className="font-bold text-slate-500">No programmes configured yet</p>
          </div>
        ) : (
          programmes.map((prog) => {
            const isExpanded = expandedId === prog.id
            return (
              <div
                key={prog.id}
                className="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900"
              >
                <button
                  onClick={() => setExpandedId(isExpanded ? null : prog.id)}
                  className="flex w-full items-center justify-between p-6 text-left"
                >
                  <div className="flex items-center gap-4">
                    <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-blue-50 dark:bg-blue-900/20">
                      <GraduationCap className="h-6 w-6 text-blue-600" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono text-xs font-bold text-slate-400">
                          {prog.code}
                        </span>
                        {!prog.isActive && (
                          <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs font-bold text-slate-500">
                            Inactive
                          </span>
                        )}
                      </div>
                      <p className="text-lg font-black text-slate-800 dark:text-white">
                        {prog.name}
                      </p>
                      <p className="text-xs text-slate-500">
                        {prog.durationYears} year{prog.durationYears !== 1 ? 's' : ''} &middot;{' '}
                        {prog.currency} {Number(prog.totalFee).toLocaleString()} &middot;{' '}
                        <Users className="inline h-3 w-3" /> {prog._count.enrollments} enrolled
                      </p>
                    </div>
                  </div>
                  {isExpanded ? (
                    <ChevronDown className="h-5 w-5 text-slate-400" />
                  ) : (
                    <ChevronRight className="h-5 w-5 text-slate-400" />
                  )}
                </button>

                {isExpanded && (
                  <div className="border-t border-slate-200 px-6 pt-4 pb-6 dark:border-slate-700">
                    <div className="mb-4 flex items-start justify-between gap-4">
                      {prog.description ? (
                        <p className="text-sm text-slate-600 dark:text-slate-400">
                          {prog.description}
                        </p>
                      ) : <div />}
                      <Button
                        size="sm"
                        variant="secondary"
                        onClick={() => openEditProgramme(prog)}
                        className="shrink-0"
                      >
                        Edit Details
                      </Button>
                    </div>

                    <div className="mb-3 flex items-center justify-between">
                      <h3 className="text-xs font-black tracking-widest text-slate-400 uppercase">
                        Programme Years
                      </h3>
                      <Button
                        size="sm"
                        variant="outline"
                        className="gap-1 text-xs"
                        onClick={() => openAddYear(prog.id)}
                      >
                        <Plus className="h-3 w-3" /> Add Year
                      </Button>
                    </div>

                    {prog.programmeYears.length === 0 ? (
                      <p className="text-sm text-slate-400 italic">
                        No years configured. Add years to define semester schedules and fees.
                      </p>
                    ) : (
                      <div className="space-y-2">
                        {prog.programmeYears.map((y) => {
                          const effectiveYearFee = y.yearFeeAmount
                            ? Number(y.yearFeeAmount)
                            : Number(prog.totalFee) / prog.durationYears
                          
                          const hasSeatFee = y.yearNumber === 1
                          const seatFee = hasSeatFee ? Number(y.seatConfirmationFee) : 0
                          const firstPayment = hasSeatFee ? Number(y.firstPaymentAmount) : (effectiveYearFee * 0.5)
                          const remaining = Math.max(0, effectiveYearFee - seatFee - firstPayment)

                          const seatPct = Math.round((seatFee / effectiveYearFee) * 100) || 0
                          const firstPct = Math.round((firstPayment / effectiveYearFee) * 100) || 0
                          const remainingPct = Math.round((remaining / effectiveYearFee) * 100) || 0

                          return (
                            <div
                              key={y.id}
                              className="flex items-center justify-between rounded-xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800/50"
                            >
                              <div className="flex items-center gap-3">
                                <Calendar className="h-4 w-4 text-blue-500" />
                                <div>
                                  <p className="font-bold text-slate-700 dark:text-slate-200">
                                    Year {y.yearNumber}
                                  </p>
                                  <p className="text-xs text-slate-500">
                                    {y.semesters && y.semesters.length > 0
                                      ? y.semesters.map((sem, i) => (
                                          <span key={i}>
                                            {sem.name}:{' '}
                                            {sem.startDate
                                              ? new Date(sem.startDate).toLocaleDateString()
                                              : ''}
                                            {i < y.semesters.length - 1 ? ' · ' : ''}
                                          </span>
                                        ))
                                      : 'No semesters defined'}
                                  </p>
                                </div>
                              </div>
                              <div className="flex flex-col items-end gap-2 text-right text-xs text-slate-500">
                                <div className="flex gap-2">
                                  <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-6 px-2 text-xs"
                                    onClick={(e) => {
                                      e.stopPropagation()
                                      openEditYear(prog.id, y)
                                    }}
                                  >
                                    Edit Year
                                  </Button>
                                </div>
                                <div>
                                  <p className="font-bold text-slate-700 dark:text-slate-300">
                                    Fee: {prog.currency}{' '}
                                    {y.yearFeeAmount
                                      ? Number(y.yearFeeAmount).toLocaleString()
                                      : 'Auto'}
                                  </p>
                                  {hasSeatFee && (
                                    <p className="mt-0.5">
                                      Seat ({seatPct}%): {prog.currency} {seatFee.toLocaleString()}
                                    </p>
                                  )}
                                  <p className={!hasSeatFee ? "mt-0.5" : ""}>
                                    Sem 1 ({firstPct}%): {prog.currency} {firstPayment.toLocaleString()}
                                  </p>
                                  <p>
                                    Sem 2 ({remainingPct}%): {prog.currency} {remaining.toLocaleString()}
                                  </p>
                                </div>
                              </div>
                            </div>
                          )
                        })}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )
          })
        )}
      </div>

      {/* Add/Edit Year Dialog */}
      <Dialog open={yearOpen} onOpenChange={setYearOpen}>
        <DialogContent className="sm:max-w-[480px]">
          <DialogHeader>
            <DialogTitle>
              {editingYearId ? 'Edit Programme Year' : 'Add Programme Year'}
            </DialogTitle>
            <DialogDescription className="sr-only">
              Configure the schedule and fees for a specific year of the programme.
            </DialogDescription>
          </DialogHeader>
          <div className="mt-4 space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label htmlFor="year-num" className="mb-1 block text-xs font-bold text-slate-600">Year Number</label>
                <input
                  id="year-num"
                  name="yearNumber"
                  type="number"
                  value={yearNumber}
                  onChange={(e) => setYearNumber(e.target.value)}
                  disabled={!!editingYearId}
                  autoComplete="off"
                  className="w-full rounded-md border px-3 py-2 text-sm disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
              <div>
                <label htmlFor="year-fee" className="mb-1 block text-xs font-bold text-slate-600">
                  Year Fee (optional)
                </label>
                <input
                  id="year-fee"
                  name="yearFee"
                  type="number"
                  value={yearFee}
                  onChange={(e) => setYearFee(e.target.value)}
                  placeholder="Auto from total"
                  autoComplete="off"
                  className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
            </div>
            <div className={`grid ${Number(yearNumber) === 1 ? 'grid-cols-2' : 'grid-cols-1'} gap-3`}>
              {Number(yearNumber) === 1 && (
                <div>
                  <label htmlFor="year-seat" className="mb-1 block text-xs font-bold text-slate-600">
                    Seat Confirmation Fee
                  </label>
                  <input
                    id="year-seat"
                    name="seatFee"
                    type="number"
                    value={seatFee}
                    onChange={(e) => setSeatFee(e.target.value)}
                    autoComplete="off"
                    className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
              )}
              <div>
                <label htmlFor="year-1st" className="mb-1 block text-xs font-bold text-slate-600">
                  {Number(yearNumber) === 1 ? 'First Payment' : 'Sem 1 Payment'}
                </label>
                <input
                  id="year-1st"
                  name="firstPayment"
                  type="number"
                  value={firstPayment}
                  onChange={(e) => setFirstPayment(e.target.value)}
                  placeholder={Number(yearNumber) > 1 ? 'Auto (50%)' : ''}
                  autoComplete="off"
                  className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
            </div>

            <div className="pt-2">
              <div className="mb-2 flex items-center justify-between">
                <label htmlFor="sem-name-0" className="block text-xs font-bold text-slate-600">Semesters</label>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={handleAddSemester}
                  className="h-6 px-2 text-xs"
                >
                  + Add Semester
                </Button>
              </div>
              <div className="max-h-48 space-y-3 overflow-y-auto pr-1">
                {semesters.map((sem, idx) => (
                  <div
                    key={idx}
                    className="rounded-lg border border-slate-200 bg-slate-50 p-3 dark:bg-slate-800/50"
                  >
                    <div className="mb-2 flex items-center justify-between">
                      <input
                        id={`sem-name-${idx}`}
                        name={`semester-name-${idx}`}
                        autoComplete="off"
                        className="w-32 border-b border-dashed border-slate-300 bg-transparent text-xs font-bold outline-none"
                        value={sem.name}
                        onChange={(e) => handleSemesterChange(idx, 'name', e.target.value)}
                      />
                      <button
                        onClick={() => handleRemoveSemester(idx)}
                        className="text-xs text-red-500 hover:text-red-600"
                      >
                        Remove
                      </button>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <label htmlFor={`sem-start-${idx}`} className="text-xs text-slate-500">Start</label>
                        <input
                          id={`sem-start-${idx}`}
                          name={`semester-start-${idx}`}
                          type="date"
                          value={sem.startDate ? sem.startDate.split('T')[0] : ''}
                          onChange={(e) => handleSemesterChange(idx, 'startDate', e.target.value)}
                          autoComplete="off"
                          className="w-full rounded-md border px-2 py-1 text-xs dark:border-slate-700 dark:bg-slate-800"
                        />
                      </div>
                      <div>
                        <label htmlFor={`sem-end-${idx}`} className="text-xs text-slate-500">End</label>
                        <input
                          id={`sem-end-${idx}`}
                          name={`semester-end-${idx}`}
                          type="date"
                          value={sem.endDate ? sem.endDate.split('T')[0] : ''}
                          onChange={(e) => handleSemesterChange(idx, 'endDate', e.target.value)}
                          autoComplete="off"
                          className="w-full rounded-md border px-2 py-1 text-xs dark:border-slate-700 dark:bg-slate-800"
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            {error && <p className="text-sm text-red-600">{error}</p>}
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button variant="outline" onClick={() => setYearOpen(false)} disabled={loading}>
              Cancel
            </Button>
            <Button onClick={handleSaveYear} disabled={loading}>
              {loading ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : editingYearId ? (
                'Save Changes'
              ) : (
                'Add Year'
              )}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Edit Programme Dialog */}
      <Dialog open={editOpen} onOpenChange={setEditOpen}>
        <DialogContent className="sm:max-w-[480px]">
          <DialogHeader>
            <DialogTitle>Edit Programme Details</DialogTitle>
            <DialogDescription className="sr-only">
              Edit details for an existing full-time training programme.
            </DialogDescription>
          </DialogHeader>
          <div className="mt-4 space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="mb-1 block text-xs font-bold text-slate-600">Code (Cannot be changed)</label>
                <input
                  value={code}
                  disabled
                  className="w-full rounded-md border px-3 py-2 text-sm opacity-50 dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
              <div>
                <label className="mb-1 block text-xs font-bold text-slate-600">
                  Duration (Cannot be changed)
                </label>
                <input
                  value={durationYears}
                  disabled
                  className="w-full rounded-md border px-3 py-2 text-sm opacity-50 dark:border-slate-700 dark:bg-slate-800"
                />
              </div>
            </div>
            <div>
              <label htmlFor="edit-prog-name" className="mb-1 block text-xs font-bold text-slate-600">Name</label>
              <input
                id="edit-prog-name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                autoComplete="off"
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
            <div>
              <label htmlFor="edit-prog-fee" className="mb-1 block text-xs font-bold text-slate-600">Total Fee</label>
              <input
                id="edit-prog-fee"
                type="number"
                value={totalFee}
                onChange={(e) => setTotalFee(e.target.value)}
                autoComplete="off"
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
            <div>
              <label htmlFor="edit-prog-desc" className="mb-1 block text-xs font-bold text-slate-600">Description</label>
              <textarea
                id="edit-prog-desc"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={2}
                autoComplete="off"
                className="w-full rounded-md border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
              />
            </div>
            <div className="flex items-center gap-2 pt-2">
              <input
                id="edit-prog-active"
                type="checkbox"
                checked={isActive}
                onChange={(e) => setIsActive(e.target.checked)}
                className="h-4 w-4 rounded border-slate-300 text-aerojet-blue focus:ring-aerojet-blue"
              />
              <label htmlFor="edit-prog-active" className="text-sm font-bold text-slate-700 dark:text-slate-300">
                Is Active
              </label>
            </div>
            {error && <p className="text-sm text-red-600">{error}</p>}
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button variant="outline" onClick={() => setEditOpen(false)} disabled={loading}>
              Cancel
            </Button>
            <Button onClick={handleEditProgramme} disabled={loading}>
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Save Changes'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { getAuthSession } from '@/lib/auth/helpers'
import { redirect } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { Metadata } from 'next'
import { serializePrisma } from '@/lib/utils/serialization'
import { ProgrammeSemester } from './_components/ProgrammesClient'
import ProgrammesClient from './_components/ProgrammesClient'

export const metadata: Metadata = { title: 'Programmes | Staff Portal' }

export default async function ProgrammesPage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const programmes = await prismaUnfiltered.fullTimeProgramme.findMany({
    include: {
      programmeYears: {
        orderBy: { yearNumber: 'asc' },
      },
      _count: { select: { enrollments: true } },
    },
    orderBy: { code: 'asc' },
  })

  const serialized = serializePrisma(programmes).map((p: any) => ({
    ...p,
    programmeYears: p.programmeYears.map((y: any) => ({
      ...y,
      semesters: (Array.isArray(y.semesters) ? y.semesters : []) as unknown as ProgrammeSemester[],
    })),
  }))

  return <ProgrammesClient programmes={serialized} />
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { AlertTriangle, Shield, ShieldOff, Play } from 'lucide-react'

interface ReferralRow {
  id: string
  status: 'PENDING' | 'QUALIFIED' | 'DISQUALIFIED'
  fraudScore: number
  fraudReasons: string[]
  createdAt: string
  reviewedAt: string | null
  referrer: { id: string; email: string; isAmbassador: boolean; name: string }
  referee: { id: string; email: string; name: string }
}

export default function ReferralsManager({
  initialReferrals,
  currentFilters,
}: {
  initialReferrals: ReferralRow[]
  currentFilters: { status: string | null; minFraud: number | null }
}) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [status, setStatus] = useState(currentFilters.status ?? '')
  const [minFraud, setMinFraud] = useState(String(currentFilters.minFraud ?? ''))

  const applyFilters = () => {
    const params = new URLSearchParams()
    if (status) params.set('status', status)
    if (minFraud) params.set('minFraud', minFraud)
    router.push(`/staff/referrals${params.size ? `?${params}` : ''}`)
  }

  const callJson = async (url: string, init: RequestInit, ok: string) => {
    const res = await fetch(url, { ...init, headers: { 'Content-Type': 'application/json', ...(init.headers || {}) } })
    const json = await res.json().catch(() => ({}))
    if (!res.ok || json?.success === false) {
      toast.error(json?.error || `Request failed (${res.status})`)
      return false
    }
    toast.success(ok)
    startTransition(() => router.refresh())
    return true
  }

  const toggle = (id: string) => {
    const next = new Set(selected)
    next.has(id) ? next.delete(id) : next.add(id)
    setSelected(next)
  }

  const onBulkDisqualify = async () => {
    if (selected.size === 0) return
    const reason = prompt(`Disqualify ${selected.size} referral(s). Reason?`)
    if (!reason) return
    await callJson('/api/staff/referrals/bulk', {
      method: 'POST',
      body: JSON.stringify({ action: 'disqualify', ids: Array.from(selected), reason }),
    }, `Disqualified ${selected.size} referrals`)
    setSelected(new Set())
  }

  const onRevokeAmbassador = async (userId: string, name: string) => {
    const reason = prompt(`Revoke ambassador status for ${name}. Reason?`)
    if (!reason) return
    await callJson(`/api/staff/referrals/ambassador/${userId}/revoke`, {
      method: 'POST',
      body: JSON.stringify({ reason }),
    }, 'Ambassador revoked')
  }

  const onRunFraud = async () => {
    await callJson('/api/staff/referrals/fraud-scan', { method: 'POST', body: '{}' }, 'Fraud scan complete')
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2 rounded-2xl border border-slate-100 bg-white p-3 dark:border-slate-800 dark:bg-slate-900">
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          className="rounded-lg border border-slate-200 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
        >
          <option value="">All statuses</option>
          <option value="PENDING">Pending</option>
          <option value="QUALIFIED">Qualified</option>
          <option value="DISQUALIFIED">Disqualified</option>
        </select>
        <input
          value={minFraud}
          onChange={(e) => setMinFraud(e.target.value)}
          placeholder="Min fraud score"
          type="number"
          className="w-36 rounded-lg border border-slate-200 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
        />
        <button onClick={applyFilters} className="rounded-lg bg-slate-200 px-3 py-2 text-sm font-bold hover:bg-slate-300 dark:bg-slate-700 dark:text-slate-100 dark:hover:bg-slate-600">
          Apply
        </button>
        <div className="ml-auto flex gap-2">
          <button
            disabled={isPending}
            onClick={onRunFraud}
            className="flex items-center gap-1.5 rounded-lg bg-amber-500 px-3 py-2 text-sm font-bold text-white hover:bg-amber-600 disabled:opacity-50"
          >
            <Play className="h-4 w-4" /> Run fraud scan
          </button>
          <button
            disabled={isPending || selected.size === 0}
            onClick={onBulkDisqualify}
            className="flex items-center gap-1.5 rounded-lg bg-red-600 px-3 py-2 text-sm font-bold text-white hover:bg-red-700 disabled:opacity-50"
          >
            <ShieldOff className="h-4 w-4" /> Disqualify ({selected.size})
          </button>
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white dark:border-slate-800 dark:bg-slate-900">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-left text-[10px] font-black tracking-widest text-slate-400 uppercase dark:bg-slate-800">
            <tr>
              <th className="px-3 py-2"><input type="checkbox" onChange={(e) => setSelected(e.target.checked ? new Set(initialReferrals.map((r) => r.id)) : new Set())} /></th>
              <th className="px-3 py-2">Referrer</th>
              <th className="px-3 py-2">Referee</th>
              <th className="px-3 py-2">Status</th>
              <th className="px-3 py-2">Fraud</th>
              <th className="px-3 py-2">Created</th>
              <th className="px-3 py-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {initialReferrals.map((r) => (
              <tr key={r.id} className="border-t border-slate-100 dark:border-slate-800">
                <td className="px-3 py-2"><input type="checkbox" checked={selected.has(r.id)} onChange={() => toggle(r.id)} /></td>
                <td className="px-3 py-2">
                  <p className="font-bold text-slate-900 dark:text-slate-100">{r.referrer.name}</p>
                  <p className="text-xs text-slate-500">{r.referrer.email}</p>
                  {r.referrer.isAmbassador && (
                    <button onClick={() => onRevokeAmbassador(r.referrer.id, r.referrer.name)} className="mt-1 inline-flex items-center gap-1 text-[10px] font-black text-emerald-600 hover:text-red-600">
                      <Shield className="h-3 w-3" /> Ambassador (revoke)
                    </button>
                  )}
                </td>
                <td className="px-3 py-2">
                  <p className="font-bold text-slate-900 dark:text-slate-100">{r.referee.name}</p>
                  <p className="text-xs text-slate-500">{r.referee.email}</p>
                </td>
                <td className="px-3 py-2">
                  <span className={`rounded-full px-2 py-0.5 text-[10px] font-black tracking-widest uppercase ${
                    r.status === 'QUALIFIED' ? 'bg-emerald-50 text-emerald-700'
                    : r.status === 'DISQUALIFIED' ? 'bg-red-50 text-red-700'
                    : 'bg-slate-100 text-slate-600'
                  }`}>{r.status}</span>
                </td>
                <td className="px-3 py-2">
                  <span className={`inline-flex items-center gap-1 font-mono text-xs font-black ${
                    r.fraudScore >= 50 ? 'text-red-600' : r.fraudScore >= 30 ? 'text-amber-600' : 'text-slate-400'
                  }`}>
                    {r.fraudScore >= 30 && <AlertTriangle className="h-3 w-3" />} {r.fraudScore}
                  </span>
                  {r.fraudReasons.length > 0 && (
                    <p className="mt-0.5 text-[10px] text-slate-400">{r.fraudReasons.join(', ')}</p>
                  )}
                </td>
                <td className="px-3 py-2 text-xs text-slate-500">{new Date(r.createdAt).toLocaleDateString()}</td>
                <td className="px-3 py-2">
                  <button
                    disabled={isPending || r.status === 'DISQUALIFIED'}
                    onClick={async () => {
                      const reason = prompt('Disqualify reason?')
                      if (!reason) return
                      await callJson('/api/staff/referrals/bulk', {
                        method: 'POST',
                        body: JSON.stringify({ action: 'disqualify', ids: [r.id], reason }),
                      }, 'Disqualified')
                    }}
                    className="rounded-lg bg-red-50 px-2 py-1 text-xs font-bold text-red-600 hover:bg-red-100 disabled:opacity-30"
                  >
                    Disqualify
                  </button>
                </td>
              </tr>
            ))}
            {initialReferrals.length === 0 && (
              <tr><td colSpan={7} className="px-3 py-8 text-center text-sm text-slate-400">No referrals match these filters.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

'use client'

import * as React from 'react'
import { Area, AreaChart, ResponsiveContainer } from 'recharts'

interface SparklineProps {
  data: { value: number }[]
  color?: string
}

export function Sparkline({ data, color = '#3b82f6' }: SparklineProps) {
  const [mounted, setMounted] = React.useState(false)
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  React.useEffect(() => setMounted(true), [])

  // Generate some random-ish but stable data points if actual historical data isn't passed
  const chartData = data.length > 0 ? data : [
    { value: 10 }, { value: 25 }, { value: 15 }, { value: 35 }, 
    { value: 30 }, { value: 45 }, { value: 40 }
  ]

  return (
    <div className="h-10 w-24">
      {mounted ? (
        <ResponsiveContainer width="100%" height="100%" minWidth={0} minHeight={0}>
          <AreaChart data={chartData}>
            <defs>
              <linearGradient id={`grad-${color}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={color} stopOpacity={0.3} />
                <stop offset="95%" stopColor={color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <Area
              type="monotone"
              dataKey="value"
              stroke={color}
              strokeWidth={2}
              fillOpacity={1}
              fill={`url(#grad-${color})`}
              isAnimationActive={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      ) : (
        <div className="h-full w-full" />
      )}
    </div>
  )
}

'use client'

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  LineChart,
  Line,
} from 'recharts'

function shortCurrency(v: number) {
  if (v >= 1_000_000) return `€${(v / 1_000_000).toFixed(1)}M`
  if (v >= 1_000) return `€${(v / 1_000).toFixed(0)}K`
  return `€${v.toFixed(0)}`
}

const CURRENT_COLOR = '#1E40AF'   // aerojet blue
const PREVIOUS_COLOR = '#94A3B8'  // slate-400

export function YoYRevenueChart({
  data,
  currentYear,
  previousYear,
}: {
  data: any[]
  currentYear: number
  previousYear: number
}) {
  return (
    <ResponsiveContainer width="100%" height={280} minWidth={0}>
      <BarChart data={data} barGap={2} barCategoryGap="30%">
        <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
        <XAxis dataKey="month" tick={{ fontSize: 11, fill: '#94a3b8', fontWeight: 700 }} axisLine={false} tickLine={false} />
        <YAxis tickFormatter={shortCurrency} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
        <Tooltip
          formatter={(v: any, name: any) => [shortCurrency(Number(v)), String(name).includes(String(currentYear)) ? String(currentYear) : String(previousYear)]}
          contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0', fontSize: 12 }}
        />
        <Legend formatter={(v) => v.includes(String(currentYear)) ? String(currentYear) : String(previousYear)} />
        <Bar dataKey={`${currentYear}_revenue`} fill={CURRENT_COLOR} radius={[4, 4, 0, 0]} name={`${currentYear}_revenue`} />
        <Bar dataKey={`${previousYear}_revenue`} fill={PREVIOUS_COLOR} radius={[4, 4, 0, 0]} name={`${previousYear}_revenue`} />
      </BarChart>
    </ResponsiveContainer>
  )
}

