'use client'

import React, { useState, useMemo } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { FileText, ExternalLink, Trash2, Edit3, MoreVertical, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Button } from '@/components/ui/button'
import { deleteResource } from '@/lib/actions/resources'
import { toast } from '@/hooks/use-toast'
import { Badge } from '@/components/ui/badge'
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import ResourceForm from './ResourceForm'

interface ResourceListProps {
  resources: any[]
}

export default function ResourceList({ resources: initialResources }: ResourceListProps) {
  const [resources, setResources] = useState(initialResources)
  const [editingResource, setEditingResource] = useState<any>(null)
  const [sortField, setSortField] = useState<'name' | 'category' | 'type' | 'visibility'>('name')
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc')

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this resource?')) return

    try {
      await deleteResource(id)
      setResources(resources.filter((r) => r.id !== id))
      toast.success('Resource deleted')
    } catch (error) {
      toast.error('Failed to delete resource')
    }
  }

  const toggleSort = (field: 'name' | 'category' | 'type' | 'visibility') => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortOrder('asc')
    }
  }

  const sortedResources = useMemo(() => {
    return [...resources].sort((a, b) => {
      let valA = ''
      let valB = ''

      if (sortField === 'name') {
        valA = a.name || ''
        valB = b.name || ''
      } else if (sortField === 'category') {
        valA = a.category || ''
        valB = b.category || ''
      } else if (sortField === 'type') {
        valA = a.type || ''
        valB = b.type || ''
      } else if (sortField === 'visibility') {
        valA = (a.showToInstructors ? '1' : '0') + (a.showToStaff ? '1' : '0') + (a.showToStudents ? '1' : '0')
        valB = (b.showToInstructors ? '1' : '0') + (b.showToStaff ? '1' : '0') + (b.showToStudents ? '1' : '0')
      }

      const comparison = valA.localeCompare(valB, undefined, { sensitivity: 'base' })
      return sortOrder === 'asc' ? comparison : -comparison
    })
  }, [resources, sortField, sortOrder])

  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white dark:border-slate-800 dark:bg-slate-900">
        <Table>
          <TableHeader>
            <TableRow className="bg-slate-50/50 dark:bg-slate-800/50">
              <TableHead
                onClick={() => toggleSort('name')}
                className="cursor-pointer select-none text-[10px] font-bold tracking-wider uppercase group hover:text-slate-900 dark:hover:text-white"
              >
                <div className="flex items-center gap-1.5">
                  Resource
                  {sortField === 'name' ? (
                    sortOrder === 'asc' ? <ArrowUp className="h-3 w-3 text-blue-600" /> : <ArrowDown className="h-3 w-3 text-blue-600" />
                  ) : (
                    <ArrowUpDown className="h-3 w-3 text-slate-400 opacity-40 group-hover:opacity-100 transition-opacity" />
                  )}
                </div>
              </TableHead>
              <TableHead
                onClick={() => toggleSort('category')}
                className="cursor-pointer select-none text-[10px] font-bold tracking-wider uppercase group hover:text-slate-900 dark:hover:text-white"
              >
                <div className="flex items-center gap-1.5">
                  Category
                  {sortField === 'category' ? (
                    sortOrder === 'asc' ? <ArrowUp className="h-3 w-3 text-blue-600" /> : <ArrowDown className="h-3 w-3 text-blue-600" />
                  ) : (
                    <ArrowUpDown className="h-3 w-3 text-slate-400 opacity-40 group-hover:opacity-100 transition-opacity" />
                  )}
                </div>
              </TableHead>
              <TableHead
                onClick={() => toggleSort('type')}
                className="cursor-pointer select-none text-[10px] font-bold tracking-wider uppercase group hover:text-slate-900 dark:hover:text-white"
              >
                <div className="flex items-center gap-1.5">
                  Type
                  {sortField === 'type' ? (
                    sortOrder === 'asc' ? <ArrowUp className="h-3 w-3 text-blue-600" /> : <ArrowDown className="h-3 w-3 text-blue-600" />
                  ) : (
                    <ArrowUpDown className="h-3 w-3 text-slate-400 opacity-40 group-hover:opacity-100 transition-opacity" />
                  )}
                </div>
              </TableHead>
              <TableHead
                onClick={() => toggleSort('visibility')}
                className="cursor-pointer select-none text-[10px] font-bold tracking-wider uppercase group hover:text-slate-900 dark:hover:text-white"
              >
                <div className="flex items-center gap-1.5">
                  Visibility
                  {sortField === 'visibility' ? (
                    sortOrder === 'asc' ? <ArrowUp className="h-3 w-3 text-blue-600" /> : <ArrowDown className="h-3 w-3 text-blue-600" />
                  ) : (
                    <ArrowUpDown className="h-3 w-3 text-slate-400 opacity-40 group-hover:opacity-100 transition-opacity" />
                  )}
                </div>
              </TableHead>
              <TableHead className="text-right text-[10px] font-bold tracking-wider uppercase">
                Actions
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {sortedResources.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="py-12 text-center text-slate-500">
                  No general resources found.
                </TableCell>
              </TableRow>
            ) : (
              sortedResources.map((resource) => (
                <TableRow
                  key={resource.id}
                  className="group transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/40"
                >
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400">
                        {resource.type === 'LINK' ? (
                          <ExternalLink className="h-4 w-4" />
                        ) : (
                          <FileText className="h-4 w-4" />
                        )}
                      </div>
                      <div>
                        <div className="font-bold text-slate-900 dark:text-slate-100">
                          {resource.name}
                        </div>
                        <div className="max-w-[200px] truncate font-mono text-[10px] text-slate-400">
                          {resource.url}
                        </div>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className="border-slate-200 px-2 py-0 text-[10px] font-bold tracking-widest uppercase dark:border-slate-700"
                    >
                      {resource.category}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <span className="text-xs font-medium text-slate-500">{resource.type}</span>
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-1.5">
                      {resource.showToInstructors && (
                        <Badge className="h-5 border-blue-100 bg-blue-50 px-1.5 text-[9px] tracking-tighter text-blue-600 hover:bg-blue-50 dark:bg-blue-900/20 dark:text-blue-400">
                          INS
                        </Badge>
                      )}
                      {resource.showToStaff && (
                        <Badge className="h-5 border-purple-100 bg-purple-50 px-1.5 text-[9px] tracking-tighter text-purple-600 hover:bg-purple-50 dark:bg-purple-900/20 dark:text-purple-400">
                          STAFF
                        </Badge>
                      )}
                      {resource.showToStudents && (
                        <Badge className="h-5 border-emerald-100 bg-emerald-50 px-1.5 text-[9px] tracking-tighter text-emerald-600 hover:bg-emerald-50 dark:bg-emerald-900/20 dark:text-emerald-400">
                          STU
                        </Badge>
                      )}
                      {resource.courses?.length > 0 && (
                        <Badge variant="outline" className="h-5 px-1.5 text-[9px] tracking-tighter font-mono">
                          {resource.courses.length} MOD
                        </Badge>
                      )}
                      {resource.pathways?.length > 0 && (
                        <Badge variant="outline" className="h-5 px-1.5 text-[9px] tracking-tighter">
                          {resource.pathways.length} PTH
                        </Badge>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 rounded-lg outline-none"
                        >
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-40 rounded-xl">
                        <DropdownMenuItem
                          onClick={() => setEditingResource(resource)}
                          className="cursor-pointer gap-2 rounded-lg"
                        >
                          <Edit3 className="h-4 w-4" /> Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => handleDelete(resource.id)}
                          className="cursor-pointer gap-2 rounded-lg text-rose-600 focus:text-rose-600"
                        >
                          <Trash2 className="h-4 w-4" /> Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={!!editingResource} onOpenChange={() => setEditingResource(null)}>
        <DialogContent className="rounded-3xl lg:max-w-[1100px] sm:max-w-[600px] overflow-hidden p-8">
          <DialogHeader>
            <DialogTitle className="text-xl font-black text-slate-900 dark:text-slate-100">
              Edit Resource
            </DialogTitle>
          </DialogHeader>
          <ResourceForm
            initialData={editingResource}
            onSuccess={() => {
              setEditingResource(null)
              window.location.reload()
            }}
          />
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import React, { useState, useMemo, useTransition } from 'react'
import { Card, CardContent } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Checkbox } from '@/components/ui/checkbox'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { motion } from 'framer-motion'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { toggleCourseAssignment, ensureTermsForPathwayLicense } from '../actions'
import { toast } from 'sonner'
import { Loader2, Search, Layers, Sparkles, ShieldCheck, Info } from 'lucide-react'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

interface SchedulingClientProps {
  pathways: any[]
  programmes: any[]
  licenseCategories: LicenseCategory[]
  courses: any[]
}

interface LicenseCategoryRequirement {
  course: {
    id: string
  }
}

interface LicenseCategory {
  id: string
  code: string
  name: string
  requirements?: LicenseCategoryRequirement[]
}

interface AcademicTerm {
  id: string
  name: string
  licenseCategoryId: string | null
  yearNumber: number
  semesterNumber: number
  licenseCategory?: LicenseCategory | null
}

interface Pathway {
  id: string
  code: string
  name: string
  academicTerms: AcademicTerm[]
}

interface Programme {
  code: string
  name: string
}

interface Tab {
  pathway: Pathway
  programme: Programme
  licenseCategories: LicenseCategory[]
  totalYears: number
}

interface ProgrammeSchedulePanelProps {
  tab: Tab
  groupedCourses: Record<string, any[]>
  licenseCourseMap: Record<string, Set<string>>
  loading: string | null
  isPending: boolean
  onToggle: (termId: string, courseId: string, assigned: boolean) => void
  onEnsureTerms: (pathwayId: string, licenseCategoryId: string, totalYears: number) => void
  search: string
}

/** Maps a pathway code to the matching programme(s) */
const PATHWAY_PROGRAMME_MAP: Record<string, string[]> = {
  FULL_TIME_4Y: ['FT_4Y_B1B2'],
  FULL_TIME_2Y: ['FT_2Y_B1'],
  MILITARY_1Y: ['MIL_1Y_B1'],
}

interface SchedulingClientProps {
  pathways: any[]
  programmes: any[]
  licenseCategories: LicenseCategory[]
  courses: any[]
}

export default function SchedulingClient({
  pathways,
  programmes,
  licenseCategories,
  courses,
}: SchedulingClientProps) {
  const [loading, setLoading] = useState<string | null>(null)
  const [search, setSearch] = useState('')
  const [isPending, startTransition] = useTransition()

  // Build programme tabs that link to pathways
  const programmeTabs = useMemo(() => {
    const tabs: {
      programme: any
      pathway: any
      licenseCategories: any[]
      totalYears: number
    }[] = []

    for (const pathway of pathways) {
      // Find matching programmes for this pathway
      const matchingCodes = PATHWAY_PROGRAMME_MAP[pathway.code] || []
      const matchingProgrammes = programmes.filter((p) => matchingCodes.includes(p.code))

      if (matchingProgrammes.length === 0) {
        // Fallback: show the pathway itself (for pathways without a FullTimeProgramme)
        tabs.push({
          programme: { id: pathway.id, code: pathway.code, name: pathway.name, durationYears: 1 },
          pathway,
          licenseCategories,
          totalYears: 1,
        })
      } else {
        for (const prog of matchingProgrammes) {
          tabs.push({
            programme: prog,
            pathway,
            licenseCategories,
            totalYears: prog.durationYears,
          })
        }
      }
    }

    return tabs
  }, [pathways, programmes, licenseCategories])

  // Group courses by category for cleaner organization
  const groupedCourses = useMemo(() => {
    const filtered = courses.filter(
      (c: any) =>
        c.name.toLowerCase().includes(search.toLowerCase()) ||
        c.code.toLowerCase().includes(search.toLowerCase())
    )

    const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' })
    const sorted = [...filtered].sort((a: any, b: any) => collator.compare(a.code, b.code))

    const groups: Record<string, any[]> = {}
    sorted.forEach((course: any) => {
      const cat = course.category?.name || 'General'
      if (!groups[cat]) groups[cat] = []
      groups[cat].push(course)
    })
    return groups
  }, [courses, search])

  // Build a quick lookup: license category id → required course IDs
  const licenseCourseMap = useMemo(() => {
    const map: Record<string, Set<string>> = {}
    for (const lc of licenseCategories) {
      map[lc.id] = new Set(lc.requirements?.map((r) => r.course.id) ?? [])
    }
    return map
  }, [licenseCategories])

  const handleToggle = async (termId: string, courseId: string, assigned: boolean) => {
    setLoading(`${termId}-${courseId}`)
    try {
      const result = await toggleCourseAssignment(termId, courseId, assigned)
      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success(`Module ${assigned ? 'assigned to' : 'removed from'} term.`)
      }
    } catch {
      toast.error('An unexpected error occurred.')
    } finally {
      setLoading(null)
    }
  }

  const handleEnsureTerms = async (
    pathwayId: string,
    licenseCategoryId: string,
    totalYears: number
  ) => {
    startTransition(async () => {
      const result = await ensureTermsForPathwayLicense(pathwayId, licenseCategoryId, totalYears)
      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success('Terms created. Refresh the page to see them.')
      }
    })
  }

  const [activeProgrammeId, setActiveProgrammeId] = useState<string>(
    programmeTabs[0]?.programme.id || ''
  )

  const activeTab = useMemo(
    () => programmeTabs.find((t) => t.programme.id === activeProgrammeId) || programmeTabs[0],
    [programmeTabs, activeProgrammeId]
  )

  return (
    <div className="mx-auto max-w-[1800px] space-y-8">
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between"
      >
        <div>
          <h1 className="text-aerojet-blue text-3xl font-black tracking-tight dark:text-white">
            Academic Scheduling
          </h1>
          <p className="mt-1 flex items-center gap-2 text-base font-medium text-slate-500 dark:text-slate-400">
            <Sparkles className="text-aerojet-sky h-4 w-4" />
            Map modules to semesters per programme &amp; license category.
          </p>
        </div>
        <div className="relative w-full sm:w-80">
          <Search className="absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <Input
            placeholder="Search by code or name..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="focus:border-aerojet-sky focus:ring-aerojet-sky/10 h-11 rounded-xl border-slate-200 bg-white pl-11 shadow-sm transition-all focus:ring-2 dark:border-slate-800 dark:bg-slate-900/50"
          />
        </div>
      </motion.div>

      {/* Programme Selector for all devices */}
      <div className="mb-2 w-full sm:max-w-md">
        <label className="mb-2 block flex items-center gap-2 text-sm font-bold text-slate-500 dark:text-slate-400">
          <Layers className="h-4 w-4" />
          Select Programme
        </label>
        <Select value={activeProgrammeId} onValueChange={setActiveProgrammeId}>
          <SelectTrigger className="text-aerojet-blue focus:ring-aerojet-sky/20 h-12 w-full rounded-xl border-slate-200 bg-white font-semibold transition-all focus:ring-2 dark:border-slate-800 dark:bg-slate-950 dark:text-slate-200">
            <SelectValue placeholder="Select a programme" />
          </SelectTrigger>
          <SelectContent className="rounded-xl border-slate-200 dark:border-slate-800">
            {programmeTabs.map((tab) => (
              <SelectItem
                key={tab.programme.id}
                value={tab.programme.id}
                className="cursor-pointer font-medium"
              >
                {tab.programme.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {activeTab && (
        <ProgrammeSchedulePanel
          key={activeTab.programme.id}
          tab={activeTab}
          groupedCourses={groupedCourses}
          licenseCourseMap={licenseCourseMap}
          loading={loading}
          isPending={isPending}
          onToggle={handleToggle}
          onEnsureTerms={handleEnsureTerms}
          search={search}
        />
      )}
    </div>
  )
}

function ProgrammeSchedulePanel({
  tab,
  groupedCourses,
  licenseCourseMap,
  loading,
  isPending,
  onToggle,
  onEnsureTerms,
  search,
}: ProgrammeSchedulePanelProps) {
  const { pathway, licenseCategories, totalYears } = tab

  // "All (General)" = terms without a licenseCategoryId
  // + each license category that has terms OR that's available
  const categoryOptions = useMemo(() => {
    const options: { id: string | null; code: string; name: string }[] = [
      { id: null, code: 'ALL', name: 'All Modules (General)' },
    ]

    const progCode = (tab.programme.code || '').toUpperCase()
    const progName = (tab.programme.name || '').toUpperCase()

    // Determine if the programme code or name explicitly mentions ANY license category
    let hasAnyExplicitMatch = false
    for (const lc of licenseCategories) {
      const lcCodeStripped = lc.code.replace(/[^a-zA-Z0-9]/g, '').toUpperCase() // 'B1.1' -> 'B11'
      const looseMatch = lcCodeStripped.replace('11', '1') // 'B11' -> 'B1'

      if (
        progCode.includes(lcCodeStripped) ||
        progCode.includes(looseMatch) ||
        progName.includes(lc.code.toUpperCase())
      ) {
        hasAnyExplicitMatch = true
        break
      }
    }

    for (const lc of licenseCategories) {
      const lcCodeStripped = lc.code.replace(/[^a-zA-Z0-9]/g, '').toUpperCase()
      const looseMatch = lcCodeStripped.replace('11', '1')

      const isMatch =
        progCode.includes(lcCodeStripped) ||
        progCode.includes(looseMatch) ||
        progName.includes(lc.code.toUpperCase())

      // If the programme specifies specific licenses, only show those.
      // If it's a generic programme (no specific licenses mentioned), show all.
      if (!hasAnyExplicitMatch || isMatch) {
        options.push({ id: lc.id, code: lc.code, name: `${lc.code} — ${lc.name}` })
      }
    }
    return options
  }, [licenseCategories, tab.programme.code, tab.programme.name])

  const [activeLicenseId, setActiveLicenseId] = useState<string | null>(null)

  // Filter academic terms for the current license category selection
  const filteredTerms = useMemo(() => {
    return pathway.academicTerms.filter((term) => {
      if (activeLicenseId === null) {
        return term.licenseCategoryId === null
      }
      return term.licenseCategoryId === activeLicenseId
    })
  }, [pathway.academicTerms, activeLicenseId])

  // Filter courses to only those relevant to the selected license category
  const filteredGroupedCourses = useMemo(() => {
    if (activeLicenseId === null) return groupedCourses
    const requiredCourseIds = licenseCourseMap[activeLicenseId]
    if (!requiredCourseIds) return groupedCourses

    const filtered: Record<string, any[]> = {}
    for (const [cat, catCourses] of Object.entries(groupedCourses)) {
      const matching = catCourses.filter((c) => requiredCourseIds.has(c.id))
      if (matching.length > 0) {
        filtered[cat] = matching
      }
    }
    return filtered
  }, [groupedCourses, activeLicenseId, licenseCourseMap])

  const hasTerms = filteredTerms.length > 0

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      transition={{ duration: 0.2 }}
      className="space-y-6"
    >
      {/* License Category Sub-Tabs */}
      <div className="scrollbar-hide flex items-center gap-2 overflow-x-auto pb-2">
        <ShieldCheck className="h-4 w-4 shrink-0 text-slate-400" />
        <span className="mr-1 shrink-0 text-xs font-bold tracking-widest text-slate-400 uppercase">
          License:
        </span>
        {categoryOptions.map((opt) => (
          <button
            key={opt.code}
            onClick={() => setActiveLicenseId(opt.id)}
            className={`shrink-0 rounded-lg px-3 py-1.5 text-xs font-bold transition-all ${
              activeLicenseId === opt.id
                ? 'bg-aerojet-blue text-white shadow-sm'
                : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:hover:bg-slate-700'
            }`}
          >
            {opt.code === 'ALL' ? 'General' : opt.code}
          </button>
        ))}
      </div>

      {/* No Terms Yet - Prompt to create */}
      {!hasTerms && activeLicenseId !== null && (
        <div className="rounded-2xl border border-dashed border-blue-200 bg-blue-50/50 p-8 text-center dark:border-blue-900/30 dark:bg-blue-900/10">
          <Info className="mx-auto mb-3 h-8 w-8 text-blue-400" />
          <h3 className="font-bold text-blue-800 dark:text-blue-200">
            No schedule configured for this license category
          </h3>
          <p className="mx-auto mt-1 max-w-md text-sm text-blue-600 dark:text-blue-400">
            Create {totalYears * 2} semester terms for this programme + license combo to start
            assigning modules.
          </p>
          <Button
            className="mt-4 gap-2"
            disabled={isPending}
            onClick={() => onEnsureTerms(pathway.id, activeLicenseId, totalYears)}
          >
            {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Create Terms'}
          </Button>
        </div>
      )}

      {/* Scheduling Matrix */}
      {hasTerms && (
        <Card className="overflow-hidden rounded-2xl border-slate-100 shadow-xl dark:border-slate-800">
          <CardContent className="p-0">
            <div className="scrollbar-hide relative overflow-x-auto">
              <Table>
                <TableHeader className="bg-slate-50 dark:bg-slate-900/50">
                  <TableRow className="hover:bg-transparent">
                    <TableHead className="text-aerojet-blue sticky left-0 z-30 w-[160px] min-w-[160px] border-r bg-slate-50 py-6 text-sm font-bold sm:w-[300px] sm:min-w-[300px] dark:bg-slate-900 dark:text-slate-300">
                      Module Name
                    </TableHead>
                    {filteredTerms.map((term) => (
                      <TableHead
                        key={term.id}
                        className="min-w-[160px] border-r text-center align-middle"
                      >
                        <div className="flex flex-col items-center gap-1.5">
                          <span className="text-aerojet-blue text-sm font-bold dark:text-slate-100">
                            Year {term.yearNumber} • Sem {term.semesterNumber}
                          </span>
                          {term.licenseCategory && (
                            <Badge
                              variant="outline"
                              className="rounded-md border-emerald-200 bg-emerald-50 text-[10px] font-black text-emerald-700 uppercase dark:border-emerald-900/30 dark:bg-emerald-900/30 dark:text-emerald-300"
                            >
                              {term.licenseCategory.code}
                            </Badge>
                          )}
                        </div>
                      </TableHead>
                    ))}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {Object.entries(filteredGroupedCourses).map(([category, catCourses]) => (
                    <React.Fragment key={category}>
                      {/* Category Header */}
                      <TableRow className="bg-slate-50/50 hover:bg-slate-50/50 dark:bg-slate-800/10 dark:hover:bg-slate-800/10">
                        <TableCell colSpan={filteredTerms.length + 1} className="px-6 py-2.5">
                          <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-slate-400 uppercase">
                            <Layers className="h-3 w-3" />
                            {category}
                          </div>
                        </TableCell>
                      </TableRow>

                      {/* Course Rows */}
                      {catCourses.map((course) => (
                        <TableRow
                          key={course.id}
                          className="group border-b border-slate-50 transition-all duration-150 ease-out hover:bg-white/80 dark:border-slate-800/50 dark:hover:bg-slate-800/40"
                        >
                          <TableCell className="sticky left-0 z-20 w-[160px] min-w-[160px] border-r bg-white py-5 transition-all duration-150 ease-out group-hover:bg-white group-hover:shadow-sm sm:w-[300px] sm:min-w-[300px] dark:bg-slate-950 dark:group-hover:bg-slate-900">
                            <div className="space-y-1.5 px-2">
                              <div className="text-aerojet-blue text-sm leading-tight font-bold break-words whitespace-normal sm:text-lg dark:text-slate-100">
                                {course.name}
                              </div>
                              <div className="flex flex-wrap items-center gap-2">
                                <span className="rounded bg-slate-100 px-1.5 py-0.5 font-mono text-xs font-bold text-slate-500 dark:bg-slate-800">
                                  {course.code}
                                </span>
                                {course.duration > 0 && (
                                  <span className="text-[10px] font-medium text-slate-400 sm:text-xs">
                                    {course.duration} hrs
                                  </span>
                                )}
                              </div>
                            </div>
                          </TableCell>

                          {filteredTerms.map((term: any) => {
                            const isAssigned = term.courseAssignments.some(
                              (a: any) => a.courseId === course.id
                            )
                            const isLoading = loading === `${term.id}-${course.id}`

                            return (
                              <TableCell
                                key={`${term.id}-${course.id}`}
                                className={`relative border-r p-0 text-center transition-all ${
                                  isAssigned ? 'bg-blue-50/20 dark:bg-blue-900/5' : 'bg-transparent'
                                }`}
                              >
                                <label
                                  htmlFor={`check-${term.id}-${course.id}`}
                                  className="flex h-full min-h-[80px] w-full cursor-pointer items-center justify-center transition-all hover:bg-blue-50/50 dark:hover:bg-blue-900/10"
                                >
                                  {isLoading ? (
                                    <Loader2 className="text-aerojet-sky h-5 w-5 animate-spin" />
                                  ) : (
                                    <Checkbox
                                      id={`check-${term.id}-${course.id}`}
                                      checked={isAssigned}
                                      onCheckedChange={(checked) =>
                                        onToggle(term.id, course.id, !!checked)
                                      }
                                      className="data-[state=checked]:border-aerojet-blue data-[state=checked]:bg-aerojet-blue h-6 w-6 rounded-lg border-2 border-slate-200 transition-all dark:border-slate-800"
                                    />
                                  )}
                                </label>
                              </TableCell>
                            )
                          })}
                        </TableRow>
                      ))}
                    </React.Fragment>
                  ))}

                  {Object.keys(filteredGroupedCourses).length === 0 && (
                    <TableRow>
                      <TableCell colSpan={filteredTerms.length + 1} className="py-24 text-center">
                        <p className="text-xl font-bold text-slate-400">
                          No modules found matching &quot;{search}&quot;
                        </p>
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>
      )}

      {/* General tab with terms */}
      {hasTerms && activeLicenseId === null && (
        <div className="rounded-xl border border-slate-100 bg-slate-50 p-4 text-sm text-slate-500 dark:border-slate-800 dark:bg-slate-900/50">
          <strong>General</strong> schedule applies to all students regardless of license category.
          Select a specific license category above to create a tailored semester schedule (e.g. B1.1
          students see different modules than B2).
        </div>
      )}
    </motion.div>
  )
}

'use server'

import { requireStaff } from '@/lib/auth/helpers'
import { prismaUnfiltered } from '@/lib/prisma/client'
import type { TuitionRunStatus } from '@prisma/client'
import { revalidatePath } from 'next/cache'
import { handleActionError } from '@/lib/staff/errors'

/**
 * Assigns or unassigns a course to an academic term for a specific study pathway.
 */
export async function toggleCourseAssignment(termId: string, courseId: string, assigned: boolean) {
  try {
    await requireStaff()

    if (assigned) {
      await prismaUnfiltered.termCourseAssignment.upsert({
        where: { termId_courseId: { termId, courseId } },
        update: {},
        create: { termId, courseId },
      })
    } else {
      await prismaUnfiltered.termCourseAssignment.deleteMany({
        where: { termId, courseId },
      })
    }

    revalidatePath('/staff/scheduling')
    return { success: true }
  } catch (error) {
    console.error('Toggle course assignment error:', error)
    return { error: 'Failed to update assignment.' }
  }
}

/**
 * Creates a new academic term for a pathway, optionally scoped to a license category.
 */
export async function createAcademicTerm(
  pathwayId: string,
  yearNumber: number,
  semesterNumber: number,
  licenseCategoryId?: string | null
) {
  try {
    await requireStaff()

    await prismaUnfiltered.academicTerm.create({
      data: {
        pathwayId,
        yearNumber,
        semesterNumber,
        licenseCategoryId: licenseCategoryId || null,
      },
    })

    revalidatePath('/staff/scheduling')
    return { success: true }
  } catch (error) {
    console.error('Create academic term error:', error)
    return { error: 'Failed to create term.' }
  }
}

/**
 * Ensures all required academic terms exist for a given pathway + license category combination.
 * Creates any missing terms based on the programme's year configuration.
 * Returns the term IDs created or found.
 */
export async function ensureTermsForPathwayLicense(
  pathwayId: string,
  licenseCategoryId: string,
  totalYears: number,
  semestersPerYear: number = 2
) {
  try {
    await requireStaff()

    const terms = []
    for (let year = 1; year <= totalYears; year++) {
      for (let sem = 1; sem <= semestersPerYear; sem++) {
        // Try to find existing term
        let term = await prismaUnfiltered.academicTerm.findFirst({
          where: { pathwayId, yearNumber: year, semesterNumber: sem, licenseCategoryId },
        })
        if (!term) {
          term = await prismaUnfiltered.academicTerm.create({
            data: { pathwayId, yearNumber: year, semesterNumber: sem, licenseCategoryId },
          })
        }
        terms.push(term)
      }
    }

    revalidatePath('/staff/scheduling')
    return { success: true, terms }
  } catch (error) {
    console.error('Ensure terms error:', error)
    return { error: 'Failed to ensure terms.' }
  }
}

/**
 * Creates a new Revision Support tuition run.
 */
export async function createTuitionRun(data: {
  title: string
  moduleTag?: string
  description?: string
  startDatetime: Date
  endDatetime: Date
  capacity: number
  minClassSize: number
  price: number
}) {
  try {
    const session = await requireStaff()

    const run = await prismaUnfiltered.tuitionRun.create({
      data: {
        ...data,
        price: data.price,
        createdById: session.id,
      },
    })

    revalidatePath('/staff/revision-runs')
    revalidatePath('/student/courses/revision')
    return { success: true, run }
  } catch (error) {
    console.error('Create tuition run error:', error)
    return { error: 'Failed to create revision run.' }
  }
}

/**
 * Updates an existing Revision Support tuition run.
 */
export async function updateTuitionRun(
  runId: string,
  data: {
    title: string
    moduleTag?: string
    description?: string
    startDatetime: Date
    endDatetime: Date
    capacity: number
    minClassSize: number
    price: number
    status: TuitionRunStatus
  }
) {
  try {
    await requireStaff()

    const run = await prismaUnfiltered.tuitionRun.update({
      where: { id: runId },
      data: {
        ...data,
        price: data.price,
      },
    })

    revalidatePath('/staff/revision-runs')
    revalidatePath('/student/courses/revision')
    return { success: true, run }
  } catch (error) {
    console.error('Update tuition run error:', error)
    return { error: 'Failed to update revision run.' }
  }
}

/**
 * Deletes a Revision Support tuition run.
 */
export async function deleteTuitionRun(runId: string) {
  try {
    await requireStaff()

    // Also delete any existing bookings for the run if cascading isn't handled
    await prismaUnfiltered.tuitionBooking.deleteMany({
      where: { tuitionRunId: runId },
    })

    await prismaUnfiltered.tuitionRun.delete({
      where: { id: runId },
    })

    revalidatePath('/staff/revision-runs')
    revalidatePath('/student/courses/revision')
    return { success: true }
  } catch (error) {
    console.error('Delete tuition run error:', error)
    return { error: 'Failed to delete revision run.' }
  }
}

'use client'

import { useEffect, useState } from 'react'
import {
  Download,
  Mail,
  Loader2,
  AlertCircle,
  Database,
  Clock,
  FileJson,
  FileText,
  Zap,
  CheckCircle2,
} from 'lucide-react'
import { toast } from 'sonner'

type Schedule = 'off' | 'daily' | 'weekly' | 'monthly' | 'custom'

const SCHEDULE_OPTIONS: { value: Schedule; label: string; description: string }[] = [
  { value: 'off', label: 'Off', description: 'No automatic backups' },
  { value: 'daily', label: 'Daily', description: 'Every day at 4:00 AM UTC' },
  { value: 'weekly', label: 'Weekly', description: 'Every 7 days' },
  { value: 'monthly', label: 'Monthly', description: 'Every 30 days' },
  { value: 'custom', label: 'Custom', description: 'Set a custom interval' },
]

export default function BackupManager({ adminEmail }: { adminEmail?: string }) {
  const [downloading, setDownloading] = useState<'json' | 'html' | null>(null)
  const [emailing, setEmailing] = useState(false)
  const [backingUpNow, setBackingUpNow] = useState(false)
  const [email, setEmail] = useState(adminEmail || '')

  // Schedule state
  const [schedule, setSchedule] = useState<Schedule>('off')
  const [scheduleEmail, setScheduleEmail] = useState(adminEmail || '')
  const [customDays, setCustomDays] = useState('7')
  const [lastRun, setLastRun] = useState<string | null>(null)
  const [savingSchedule, setSavingSchedule] = useState(false)
  const [loadingSchedule, setLoadingSchedule] = useState(true)

  // Load current schedule
  useEffect(() => {
    fetch('/api/admin/backup/schedule')
      .then((r) => r.json())
      .then((data) => {
        setSchedule(data.schedule || 'off')
        setScheduleEmail(data.email || adminEmail || '')
        setCustomDays(data.customDays || '7')
        setLastRun(data.lastRun || null)
      })
      .catch(() => {})
      .finally(() => setLoadingSchedule(false))
  }, [adminEmail])

  const handleDownload = async (format: 'json' | 'html') => {
    setDownloading(format)
    try {
      const res = await fetch(`/api/admin/backup?format=${format}`)
      if (!res.ok) {
        const err = await res.json()
        throw new Error(err.error || 'Failed to export backup')
      }

      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download =
        res.headers.get('Content-Disposition')?.split('filename=')[1]?.replace(/"/g, '') ||
        `aerojet-backup.${format}`
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(url)

      toast.success(`${format.toUpperCase()} backup downloaded`)
    } catch (err: any) {
      toast.error(err.message || 'Failed to download backup')
    } finally {
      setDownloading(null)
    }
  }

  const handleEmail = async () => {
    if (!email.trim()) {
      toast.error('Please enter an email address')
      return
    }

    setEmailing(true)
    try {
      const res = await fetch('/api/admin/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.trim() }),
      })

      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to send backup')

      toast.success(`Backup sent to ${email.trim()} (JSON + HTML)`)
    } catch (err: any) {
      toast.error(err.message || 'Failed to email backup')
    } finally {
      setEmailing(false)
    }
  }

  const handleBackupNow = async () => {
    if (!scheduleEmail.trim()) {
      toast.error('Please set a backup email address first')
      return
    }

    setBackingUpNow(true)
    try {
      const res = await fetch('/api/admin/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: scheduleEmail.trim() }),
      })

      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to send backup')

      setLastRun(new Date().toISOString())
      toast.success('Backup completed and sent!')
    } catch (err: any) {
      toast.error(err.message || 'Backup failed')
    } finally {
      setBackingUpNow(false)
    }
  }

  const handleSaveSchedule = async () => {
    if (schedule !== 'off' && !scheduleEmail.trim()) {
      toast.error('Email address is required for scheduled backups')
      return
    }

    setSavingSchedule(true)
    try {
      const res = await fetch('/api/admin/backup/schedule', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          schedule,
          email: scheduleEmail.trim(),
          customDays: parseInt(customDays) || 7,
        }),
      })

      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to save schedule')

      toast.success('Backup schedule saved')
    } catch (err: any) {
      toast.error(err.message || 'Failed to save schedule')
    } finally {
      setSavingSchedule(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-700 dark:bg-slate-800">
        <div className="flex items-start gap-3">
          <div className="rounded-lg bg-blue-50 p-2 dark:bg-blue-900/30">
            <Database className="h-5 w-5 text-blue-600 dark:text-blue-400" />
          </div>
          <div>
            <h3 className="text-base font-bold text-slate-900 dark:text-white">
              Database Backup
            </h3>
            <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
              Export all data from the database. Backups are available in two formats:
            </p>
            <div className="mt-3 grid gap-2 sm:grid-cols-2">
              <div className="flex items-start gap-2 rounded-lg border border-slate-200 bg-slate-50 p-3 dark:border-slate-600 dark:bg-slate-700/50">
                <FileJson className="mt-0.5 h-4 w-4 shrink-0 text-blue-500" />
                <div>
                  <p className="text-xs font-bold text-slate-900 dark:text-white">
                    JSON (Machine-Readable)
                  </p>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    For database restoration. Import directly into PostgreSQL or any compatible
                    database.
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-2 rounded-lg border border-slate-200 bg-slate-50 p-3 dark:border-slate-600 dark:bg-slate-700/50">
                <FileText className="mt-0.5 h-4 w-4 shrink-0 text-emerald-500" />
                <div>
                  <p className="text-xs font-bold text-slate-900 dark:text-white">
                    HTML (Human-Readable)
                  </p>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    Formatted report with all tables and records. Open in any browser for review.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Automatic Backup Schedule */}
      <div className="rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-700 dark:bg-slate-800">
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-slate-600 dark:text-slate-400" />
          <h4 className="text-sm font-bold text-slate-900 dark:text-white">
            Automatic Backup Schedule
          </h4>
        </div>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Schedule automatic backups. Both JSON and HTML formats are sent to the specified email.
        </p>

        {loadingSchedule ? (
          <div className="mt-4 flex items-center gap-2 text-sm text-slate-400">
            <Loader2 className="h-4 w-4 animate-spin" />
            Loading schedule...
          </div>
        ) : (
          <div className="mt-4 space-y-4">
            {/* Schedule Options */}
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-5">
              {SCHEDULE_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => setSchedule(opt.value)}
                  className={`rounded-lg border-2 px-3 py-2 text-left transition-all ${
                    schedule === opt.value
                      ? 'border-blue-500 bg-blue-50 dark:border-blue-400 dark:bg-blue-900/30'
                      : 'border-slate-200 bg-white hover:border-slate-300 dark:border-slate-600 dark:bg-slate-700 dark:hover:border-slate-500'
                  }`}
                >
                  <p
                    className={`text-xs font-bold ${schedule === opt.value ? 'text-blue-700 dark:text-blue-300' : 'text-slate-900 dark:text-white'}`}
                  >
                    {opt.label}
                  </p>
                  <p className="mt-0.5 text-[10px] text-slate-500 dark:text-slate-400">
                    {opt.description}
                  </p>
                </button>
              ))}
            </div>

            {/* Custom Days Input */}
            {schedule === 'custom' && (
              <div className="flex items-center gap-2">
                <label className="text-xs font-medium text-slate-600 dark:text-slate-400">
                  Every
                </label>
                <input
                  type="number"
                  min="1"
                  max="365"
                  value={customDays}
                  onChange={(e) => setCustomDays(e.target.value)}
                  className="w-20 rounded-lg border border-slate-300 bg-white px-3 py-1.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 dark:border-slate-600 dark:bg-slate-700 dark:text-white"
                />
                <span className="text-xs text-slate-600 dark:text-slate-400">days</span>
              </div>
            )}

            {/* Schedule Email */}
            {schedule !== 'off' && (
              <div>
                <label className="mb-1 block text-xs font-medium text-slate-600 dark:text-slate-400">
                  Send backups to
                </label>
                <input
                  type="email"
                  value={scheduleEmail}
                  onChange={(e) => setScheduleEmail(e.target.value)}
                  placeholder="admin@example.com"
                  className="w-full max-w-md rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 dark:border-slate-600 dark:bg-slate-700 dark:text-white"
                />
              </div>
            )}

            {/* Last Run */}
            {lastRun && (
              <div className="flex items-center gap-2 text-xs text-slate-500 dark:text-slate-400">
                <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" />
                Last backup:{' '}
                {new Date(lastRun).toLocaleString('en-GB', {
                  dateStyle: 'medium',
                  timeStyle: 'short',
                })}
              </div>
            )}

            {/* Save + Backup Now */}
            <div className="flex items-center gap-3 border-t border-slate-100 pt-4 dark:border-slate-700">
              <button
                onClick={handleSaveSchedule}
                disabled={savingSchedule}
                className="inline-flex items-center gap-2 rounded-lg bg-aerojet-blue px-4 py-2 text-sm font-bold text-white transition-colors hover:bg-[#003d82] disabled:opacity-50"
              >
                {savingSchedule && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
                Save Schedule
              </button>
              <button
                onClick={handleBackupNow}
                disabled={backingUpNow || !scheduleEmail.trim()}
                className="inline-flex items-center gap-2 rounded-lg border border-amber-300 bg-amber-50 px-4 py-2 text-sm font-bold text-amber-700 transition-colors hover:bg-amber-100 disabled:opacity-50 dark:border-amber-700 dark:bg-amber-900/30 dark:text-amber-300 dark:hover:bg-amber-900/50"
              >
                {backingUpNow ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : (
                  <Zap className="h-3.5 w-3.5" />
                )}
                {backingUpNow ? 'Backing up...' : 'Backup Now'}
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Download Section */}
      <div className="rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-700 dark:bg-slate-800">
        <h4 className="text-sm font-bold text-slate-900 dark:text-white">Download Backup</h4>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Download a complete backup file directly to your device.
        </p>
        <div className="mt-4 flex flex-wrap gap-3">
          <button
            onClick={() => handleDownload('json')}
            disabled={downloading !== null}
            className="inline-flex items-center gap-2 rounded-lg bg-aerojet-blue px-4 py-2.5 text-sm font-bold text-white transition-colors hover:bg-[#003d82] disabled:opacity-50"
          >
            {downloading === 'json' ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <FileJson className="h-4 w-4" />
            )}
            {downloading === 'json' ? 'Exporting...' : 'Download JSON'}
          </button>
          <button
            onClick={() => handleDownload('html')}
            disabled={downloading !== null}
            className="inline-flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 transition-all duration-150 ease-out hover:border-slate-400 hover:shadow-sm disabled:opacity-50 dark:border-slate-600 dark:bg-slate-700 dark:text-white dark:hover:border-slate-500"
          >
            {downloading === 'html' ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <FileText className="h-4 w-4" />
            )}
            {downloading === 'html' ? 'Exporting...' : 'Download HTML Report'}
          </button>
        </div>
      </div>

      {/* Email Section */}
      <div className="rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-700 dark:bg-slate-800">
        <h4 className="text-sm font-bold text-slate-900 dark:text-white">Email Backup</h4>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Send both backup formats (JSON + HTML report) as email attachments.
        </p>
        <div className="mt-4 flex items-end gap-3">
          <div className="flex-1">
            <label
              htmlFor="backup-email"
              className="mb-1 block text-xs font-medium text-slate-600 dark:text-slate-400"
            >
              Recipient email
            </label>
            <input
              id="backup-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="admin@example.com"
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition-colors focus:border-blue-500 focus:ring-1 focus:ring-blue-500 dark:border-slate-600 dark:bg-slate-700 dark:text-white"
            />
          </div>
          <button
            onClick={handleEmail}
            disabled={emailing || !email.trim()}
            className="inline-flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2.5 text-sm font-bold text-white transition-colors hover:bg-emerald-700 disabled:opacity-50"
          >
            {emailing ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Mail className="h-4 w-4" />
            )}
            {emailing ? 'Sending...' : 'Send Backup'}
          </button>
        </div>
      </div>

      {/* Info */}
      <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 dark:border-amber-800 dark:bg-amber-900/20">
        <div className="flex gap-2">
          <AlertCircle className="h-4 w-4 shrink-0 text-amber-600 dark:text-amber-400" />
          <div className="text-sm text-amber-800 dark:text-amber-300">
            <p className="font-medium">Important notes</p>
            <ul className="mt-1 list-inside list-disc space-y-0.5 text-xs">
              <li>
                <strong>JSON backup</strong> contains all raw data and can be imported into any
                PostgreSQL database
              </li>
              <li>
                <strong>HTML report</strong> is a formatted, readable view of all records for admin
                review
              </li>
              <li>Passwords are exported as bcrypt hashes (secure, not reversible)</li>
              <li>Email attachments are limited to ~25MB — for very large databases, use download</li>
              <li>Store backups securely — they contain sensitive user data</li>
              <li>Automatic backups run daily at 4:00 AM UTC via Vercel Cron</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  Mail,
  CheckCircle2,
  AlertOctagon,
  Clock,
  RefreshCw,
  Search,
} from 'lucide-react'

interface Delivery {
  id: string
  recipient: string
  subject: string
  status: 'SUCCESS' | 'FAILED' | 'RETRYING'
  messageId: string | null
  error: string | null
  attempts: number
  template: string | null
  userId: string | null
  createdAt: string
}

interface Page {
  data: Delivery[]
  meta: { page: number; limit: number; total: number; totalPages: number }
}

const STATUS_COLOUR: Record<Delivery['status'], string> = {
  SUCCESS: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300',
  FAILED: 'bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-300',
  RETRYING: 'bg-amber-50 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300',
}

const STATUS_ICON: Record<Delivery['status'], React.ComponentType<{ className?: string }>> = {
  SUCCESS: CheckCircle2,
  FAILED: AlertOctagon,
  RETRYING: Clock,
}

export default function EmailDeliveryTab() {
  const router = useRouter()
  const [page, setPage] = useState<Page | null>(null)
  const [loading, setLoading] = useState(true)
  const [status, setStatus] = useState<'all' | 'SUCCESS' | 'FAILED' | 'RETRYING'>('FAILED')
  const [search, setSearch] = useState('')
  const [pageNum, setPageNum] = useState(1)

  const reload = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        status,
        search,
        page: String(pageNum),
        limit: '25',
      })
      const res = await fetch(`/api/staff/settings/email-deliveries?${params}`, {
        cache: 'no-store',
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error || 'Failed to load')
      setPage(json)
    } catch (e) {
      toast.error((e as Error).message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    void reload()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, pageNum])

  const onSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setPageNum(1)
    void reload()
  }

  const failedCount = page?.data.filter((d) => d.status === 'FAILED').length ?? 0
  const total = page?.meta.total ?? 0

  return (
    <div className="space-y-6">
      <div>
        <h2 className="flex items-center gap-2 text-lg font-black text-slate-900 dark:text-slate-100">
          <Mail className="h-5 w-5 text-aerojet-blue" />
          Email delivery
        </h2>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Every outbound email recorded by <code>lib/email/sender.ts</code>. Filter by status to
          spot deliverability problems (failures, retries, bounces from Resend).
        </p>
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        <button
          onClick={() => setStatus('FAILED')}
          className={`rounded-2xl border p-4 text-left transition ${
            status === 'FAILED'
              ? 'border-red-300 bg-red-50 dark:border-red-700 dark:bg-red-900/20'
              : 'border-slate-100 bg-white hover:border-red-200 dark:border-slate-800 dark:bg-slate-900'
          }`}
        >
          <p className="text-xs font-bold tracking-widest text-slate-500 uppercase">Failed</p>
          <p className="mt-1 text-2xl font-black text-red-600">{status === 'FAILED' ? total : 'â€”'}</p>
        </button>
        <button
          onClick={() => setStatus('SUCCESS')}
          className={`rounded-2xl border p-4 text-left transition ${
            status === 'SUCCESS'
              ? 'border-emerald-300 bg-emerald-50 dark:border-emerald-700 dark:bg-emerald-900/20'
              : 'border-slate-100 bg-white hover:border-emerald-200 dark:border-slate-800 dark:bg-slate-900'
          }`}
        >
          <p className="text-xs font-bold tracking-widest text-slate-500 uppercase">Delivered</p>
          <p className="mt-1 text-2xl font-black text-emerald-600">
            {status === 'SUCCESS' ? total : 'â€”'}
          </p>
        </button>
        <button
          onClick={() => setStatus('all')}
          className={`rounded-2xl border p-4 text-left transition ${
            status === 'all'
              ? 'border-aerojet-blue bg-aerojet-blue/5 dark:border-aerojet-blue'
              : 'border-slate-100 bg-white hover:border-aerojet-blue/30 dark:border-slate-800 dark:bg-slate-900'
          }`}
        >
          <p className="text-xs font-bold tracking-widest text-slate-500 uppercase">All recent</p>
          <p className="mt-1 text-2xl font-black text-aerojet-blue dark:text-white">
            {status === 'all' ? total : 'â€”'}
          </p>
        </button>
      </div>

      <form onSubmit={onSearch} className="flex flex-wrap items-center gap-2">
        <div className="relative flex-1 min-w-[240px]">
          <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search recipient, subject, error messageâ€¦"
            className="w-full rounded-lg border border-slate-200 bg-white py-2 pr-3 pl-9 text-sm dark:border-slate-700 dark:bg-slate-800"
          />
        </div>
        <button
          type="submit"
          className="rounded-lg bg-aerojet-blue px-3 py-2 text-sm font-bold text-white hover:bg-aerojet-blue/90"
        >
          Apply
        </button>
        <button
          type="button"
          onClick={() => {
            setSearch('')
            setPageNum(1)
            void reload()
          }}
          className="flex items-center gap-1 rounded-lg bg-slate-100 px-3 py-2 text-sm font-bold text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300"
        >
          <RefreshCw className="h-3.5 w-3.5" /> Refresh
        </button>
      </form>

      {loading && <p className="text-sm text-slate-400">Loadingâ€¦</p>}

      {!loading && page && (
        <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white dark:border-slate-800 dark:bg-slate-900">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-[10px] font-black tracking-widest text-slate-400 uppercase dark:bg-slate-800">
              <tr>
                <th className="px-3 py-2">Status</th>
                <th className="px-3 py-2">Recipient</th>
                <th className="px-3 py-2">Subject</th>
                <th className="px-3 py-2">Template</th>
                <th className="px-3 py-2">Attempts</th>
                <th className="px-3 py-2">When</th>
              </tr>
            </thead>
            <tbody>
              {page.data.map((row) => {
                const Icon = STATUS_ICON[row.status]
                return (
                  <tr
                    key={row.id}
                    className="border-t border-slate-100 align-top dark:border-slate-800"
                  >
                    <td className="px-3 py-2">
                      <span
                        className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-black tracking-widest uppercase ${STATUS_COLOUR[row.status]}`}
                      >
                        <Icon className="h-3 w-3" /> {row.status}
                      </span>
                    </td>
                    <td className="px-3 py-2 font-mono text-xs">{row.recipient}</td>
                    <td className="px-3 py-2">
                      <p className="text-sm">{row.subject}</p>
                      {row.error && (
                        <p className="mt-1 text-xs text-red-600 dark:text-red-400">
                          {row.error}
                        </p>
                      )}
                    </td>
                    <td className="px-3 py-2 text-xs text-slate-500">{row.template ?? 'â€”'}</td>
                    <td className="px-3 py-2 font-mono text-xs">{row.attempts}</td>
                    <td className="px-3 py-2 text-xs text-slate-500">
                      {new Date(row.createdAt).toLocaleString()}
                    </td>
                  </tr>
                )
              })}
              {page.data.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-3 py-8 text-center text-sm text-slate-400">
                    No deliveries match this filter. {status === 'FAILED' && 'â€” that\'s a good thing.'}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
          {page.meta.totalPages > 1 && (
            <div className="flex items-center justify-between border-t border-slate-100 px-3 py-2 text-xs dark:border-slate-800">
              <span className="text-slate-400">
                Page {page.meta.page} of {page.meta.totalPages} Â· {page.meta.total} total
              </span>
              <div className="flex gap-1">
                <button
                  disabled={pageNum <= 1}
                  onClick={() => setPageNum((p) => Math.max(1, p - 1))}
                  className="rounded-md bg-slate-100 px-2 py-1 text-slate-600 disabled:opacity-30 dark:bg-slate-800 dark:text-slate-300"
                >
                  â† Prev
                </button>
                <button
                  disabled={pageNum >= page.meta.totalPages}
                  onClick={() => setPageNum((p) => p + 1)}
                  className="rounded-md bg-slate-100 px-2 py-1 text-slate-600 disabled:opacity-30 dark:bg-slate-800 dark:text-slate-300"
                >
                  Next â†’
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useEffect, useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Mail, Plus, Trash2, Lock, Edit2, Save, X } from 'lucide-react'

interface RegistryEntry {
  id: string
  title: string
  description: string | null
  address: string
  category: 'AUTO' | 'CUSTOM'
  isSystem: boolean
  createdAt: string
  updatedAt: string
}

const PILL_COLOURS: Record<RegistryEntry['category'], string> = {
  AUTO: 'bg-indigo-50 text-indigo-700',
  CUSTOM: 'bg-emerald-50 text-emerald-700',
}

export default function EmailRegistryTab() {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [entries, setEntries] = useState<RegistryEntry[] | null>(null)
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState<string | null>(null)
  const [draft, setDraft] = useState({ title: '', description: '', address: '' })
  const [editDraft, setEditDraft] = useState({ title: '', description: '', address: '' })

  const reload = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/staff/settings/email-registry', { cache: 'no-store' })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error || 'Failed to load registry')
      setEntries(json.data ?? json)
    } catch (e) {
      toast.error((e as Error).message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    void reload()
  }, [])

  const onAdd = async () => {
    if (!draft.title.trim() || !draft.address.trim()) {
      toast.error('Title and address are required')
      return
    }
    const res = await fetch('/api/staff/settings/email-registry', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(draft),
    })
    const json = await res.json()
    if (!res.ok || json?.success === false) {
      toast.error(json?.error || 'Failed to add')
      return
    }
    toast.success('Entry added')
    setDraft({ title: '', description: '', address: '' })
    await reload()
    startTransition(() => router.refresh())
  }

  const onSaveEdit = async (entry: RegistryEntry) => {
    const payload: Record<string, string> = {}
    if (editDraft.title !== entry.title) payload.title = editDraft.title
    if (editDraft.description !== (entry.description ?? ''))
      payload.description = editDraft.description
    if (editDraft.address !== entry.address) payload.address = editDraft.address

    if (Object.keys(payload).length === 0) {
      toast.info('No changes to save')
      setEditing(null)
      return
    }

    const res = await fetch(`/api/staff/settings/email-registry/${entry.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })
    const json = await res.json()
    if (!res.ok || json?.success === false) {
      toast.error(json?.error || 'Failed to save')
      return
    }
    toast.success('Saved')
    setEditing(null)
    await reload()
  }

  const onDelete = async (entry: RegistryEntry) => {
    if (entry.category === 'AUTO') {
      toast.error(
        'Auto-synced entries cannot be deleted â€” update the source code or change the address instead'
      )
      return
    }
    if (!confirm(`Remove "${entry.title}" from the registry?`)) return
    const res = await fetch(`/api/staff/settings/email-registry/${entry.id}`, {
      method: 'DELETE',
    })
    const json = await res.json()
    if (!res.ok || json?.success === false) {
      toast.error(json?.error || 'Failed to delete')
      return
    }
    toast.success('Removed')
    await reload()
  }

  const autoEntries = entries?.filter((e) => e.category === 'AUTO') ?? []
  const customEntries = entries?.filter((e) => e.category === 'CUSTOM') ?? []

  return (
    <div className="space-y-8">
      <div>
        <h2 className="flex items-center gap-2 text-lg font-black text-slate-900 dark:text-slate-100">
          <Mail className="text-aerojet-blue h-5 w-5" />
          Communication emails
        </h2>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Every email address used by the application â€” both code-synced senders and admin-added
          entries. Edit any entry's title, description, or address. Auto-synced entries (tagged
          "AUTO") are re-linked on each visit but your edits are preserved.
        </p>
      </div>

      {loading && <p className="text-sm text-slate-400">Loadingâ€¦</p>}

      {!loading && (
        <>
          {/* â”€â”€ AUTO entries (read-only) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
          <section className="space-y-3">
            <header className="flex items-baseline justify-between border-b border-slate-100 pb-2 dark:border-slate-800">
              <h3 className="text-sm font-bold tracking-widest text-slate-500 uppercase">
                System auto-senders
              </h3>
              <span className="text-xs text-slate-400">
                {autoEntries.length} entries Â· synced from code
              </span>
            </header>
            <ul className="space-y-2">
              {autoEntries.map((entry) => (
