'use client'

import { useState, useEffect, useCallback } from 'react'
import { RefreshCw, Globe, ShieldCheck, AlertCircle, Loader2, TrendingUp, TrendingDown } from 'lucide-react'
import { toast } from 'sonner'

interface RateData {
  rates: Record<string, number>
  external: Record<string, number>
  manual: Record<string, number>
  sources: Record<string, 'admin' | 'auto'>
  base: string
  timestamp: number
}

export default function ExchangeRateDisplay() {
  const [data, setData] = useState<RateData | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)

  const fetchRates = useCallback(async () => {
    try {
      const res = await fetch('/api/finance/rates')
      if (res.ok) {
        const json = await res.json()
        setData(json)
      } else {
        toast.error('Failed to fetch live exchange rates')
      }
    } catch (error) {
      console.error('Error fetching rates:', error)
      toast.error('Error connecting to rates service')
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchRates()
  }, [fetchRates])

  const handleManualRefresh = () => {
    setRefreshing(true)
    fetchRates()
  }

  if (loading) {
    return (
      <div className="flex h-32 items-center justify-center rounded-2xl border border-slate-200/60 bg-white/50 dark:border-white/5 dark:bg-slate-900/50">
        <Loader2 className="h-5 w-5 animate-spin text-slate-400" />
      </div>
    )
  }

  if (!data) return null

  const currencies = ['GHS', 'USD']

  return (
    <div className="overflow-hidden rounded-2xl border border-slate-200/60 bg-white/70 shadow-sm transition-all dark:border-white/5 dark:bg-[#111827]/60">
      <div className="flex items-center justify-between border-b border-slate-100/60 px-6 py-4 dark:border-white/5">
        <div className="flex items-center gap-2">
          <Globe className="h-4 w-4 text-aerojet-blue dark:text-blue-400" />
          <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100">Market Rate Comparison</h3>
        </div>
        <button
          onClick={handleManualRefresh}
          disabled={refreshing}
          className="flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-bold text-slate-500 transition-all hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-800"
        >
          <RefreshCw className={`h-3 w-3 ${refreshing ? 'animate-spin' : ''}`} />
          Refresh
        </button>
      </div>

      <div className="divide-y divide-slate-100/60 dark:divide-white/5">
        {currencies.map((curr) => {
          const used = data.rates[curr]
          const live = data.external[curr]
          const source = data.sources[curr]
          const isManual = source === 'admin'
          
          // Calculate diff
          const diff = live ? ((used - live) / live) * 100 : 0
          const isHigher = diff > 0.01
          const isLower = diff < -0.01

          return (
            <div key={curr} className="flex flex-col gap-4 px-6 py-5 sm:flex-row sm:items-center sm:justify-between">
              <div className="flex items-center gap-4">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-slate-100 text-sm font-black text-slate-400 dark:bg-slate-800 dark:text-slate-500">
                  {curr}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-900 dark:text-slate-100">{data.base} to {curr}</span>
                    {isManual ? (
                      <span className="flex items-center gap-1 rounded-full bg-amber-50 px-2 py-0.5 text-[10px] font-bold text-amber-600 dark:bg-amber-900/20 dark:text-amber-400">
                        <ShieldCheck className="h-2.5 w-2.5" />
                        Manual
                      </span>
                    ) : (
                      <span className="flex items-center gap-1 rounded-full bg-emerald-50 px-2 py-0.5 text-[10px] font-bold text-emerald-600 dark:bg-emerald-900/20 dark:text-emerald-400">
                        <RefreshCw className="h-2.5 w-2.5" />
                        Linked
                      </span>
                    )}
                  </div>
                  <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">
                    {isManual ? 'Currently using administrative override' : 'Synchronized with market rates'}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-8 sm:flex sm:items-center sm:gap-12">
                <div className="text-right sm:text-left">
                  <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Used Rate</p>
                  <p className="text-lg font-black text-slate-900 dark:text-slate-100">
                    {used.toFixed(4)}
                  </p>
                </div>
                <div className="text-right sm:text-left">
                  <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Market Rate</p>
                  <p className="text-lg font-black text-slate-500 dark:text-slate-400">
                    {live.toFixed(4)}
                  </p>
                </div>
                <div className="col-span-2 flex items-center justify-between border-t border-slate-50 pt-3 sm:col-span-1 sm:border-none sm:pt-0">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 sm:hidden">Variance</span>
                  {isManual ? (
                     <div className={`flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-bold ${
                      isHigher ? 'bg-amber-50 text-amber-600 dark:bg-amber-900/20' : 
                      isLower ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20' : 
                      'bg-slate-50 text-slate-500 dark:bg-slate-800'
                    }`}>
                      {isHigher ? <TrendingUp className="h-3 w-3" /> : isLower ? <TrendingDown className="h-3 w-3" /> : null}
                      {diff > 0 ? '+' : ''}{diff.toFixed(2)}%
                    </div>
                  ) : (
                    <div className="flex items-center gap-1.5 rounded-lg bg-emerald-50 px-2 py-1 text-xs font-bold text-emerald-600 dark:bg-emerald-900/20">
                      Perfect Match
                    </div>
                  )}
                </div>
              </div>
            </div>
          )
        })}
      </div>

      <div className="bg-slate-50/50 px-6 py-3 dark:bg-slate-800/30">
        <div className="flex items-center gap-2 text-[10px] text-slate-400">
          <AlertCircle className="h-3 w-3" />
          <span>Rates are cached for 1 hour. Last updated: {new Date(data.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
        </div>
      </div>
    </div>
  )
}

'use client'

import React, { useState } from 'react'
import dynamic from 'next/dynamic'
import SettingsForm from './SettingsForm'
import { toast } from 'sonner'
import { FileText, Award } from 'lucide-react'

// Dynamically import PDFViewer with SSR disabled — @react-pdf/renderer needs DOM APIs
const LivePDFViewer = dynamic(() => import('./LivePDFViewer'), {
  ssr: false,
  loading: () => (
    <div className="flex h-[500px] items-center justify-center rounded-lg border border-slate-200 bg-slate-100">
      <div className="flex flex-col items-center">
        <div className="mb-4 h-8 w-8 animate-spin rounded-full border-4 border-blue-600 border-t-transparent"></div>
        <p className="font-medium text-slate-500">Loading PDF Previewer…</p>
      </div>
    </div>
  ),
})

const PDF_FIELDS = [
  {
    key: 'pdf_header_logo_url',
    label: 'Header Logo URL',
    description:
      'URL or path to the logo image displayed in the header. Must be PNG or JPG (not WebP).',
    type: 'STRING' as const,
    default: '/images/logos/AATA_logo_hor_onWhite.png',
  },
  {
    key: 'pdf_watermark_url',
    label: 'Watermark Image URL',
    description:
      'URL or path to the watermark image displayed in the background. Must be PNG or JPG (not WebP).',
    type: 'STRING' as const,
    default: '/apple-touch-icon.png',
  },
  {
    key: 'pdf_footer_text',
    label: 'Footer Text',
    description: 'Custom text to display in the footer of all PDFs.',
    type: 'STRING' as const,
    default: 'Aerojet Aviation Training Academy | 123 Flight Way | contact@aerojet.com',
  },
  {
    key: 'pdf_watermark_opacity',
    label: 'Watermark Opacity',
    description: 'Opacity of the watermark image (0.0 to 1.0).',
    type: 'NUMBER' as const,
    default: '0.1',
  },
]

interface PDFSettingsFormProps {
  values: Record<string, string>
  pdfSettings: {
    logoUrl: string
    watermarkUrl: string
    footerText: string
    watermarkOpacity: number
  }
}

export default function PDFSettingsForm({ values, pdfSettings }: PDFSettingsFormProps) {
  const [liveSettings, setLiveSettings] = useState(pdfSettings)

  const [isGenerating, setIsGenerating] = useState<string | null>(null)

  const handleFormChange = (e: React.FormEvent<HTMLDivElement>) => {
    const form = (e.currentTarget as HTMLElement).querySelector('form')
    if (form) {
      const formData = new FormData(form)
      setLiveSettings({
        logoUrl: (formData.get('pdf_header_logo_url') as string) || pdfSettings.logoUrl,
        watermarkUrl: (formData.get('pdf_watermark_url') as string) || pdfSettings.watermarkUrl,
        footerText: (formData.get('pdf_footer_text') as string) || pdfSettings.footerText,
        watermarkOpacity: parseFloat(
          (formData.get('pdf_watermark_opacity') as string) || String(pdfSettings.watermarkOpacity)
        ),
      })
    }
  }

  const handleDownloadPreview = async (type: string) => {
    try {
      setIsGenerating(type)

      const response = await fetch('/api/pdf/test-template', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type,
          logoUrl: liveSettings.logoUrl,
          watermarkUrl: liveSettings.watermarkUrl,
          footerText: liveSettings.footerText,
          watermarkOpacity: liveSettings.watermarkOpacity,
        }),
      })

      if (!response.ok) throw new Error('Failed to generate PDF')

      const blob = await response.blob()
      const url = URL.createObjectURL(blob)

      const a = document.createElement('a')
      a.href = url
      a.target = '_blank'
      a.download = `preview-${type}.pdf`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)

      setTimeout(() => URL.revokeObjectURL(url), 1000)
    } catch (error) {
      toast.error('Failed to download PDF preview')
      alert('Failed to generate PDF preview. Please try again.')
    } finally {
      setIsGenerating(null)
    }
  }

  return (
    <div className="space-y-6" onChange={handleFormChange}>
      {/* ── Live Preview ── */}
      <div className="rounded-lg bg-white p-6 shadow dark:bg-slate-900">
        <h3 className="mb-1 text-lg font-medium text-gray-900 dark:text-white">Live Preview</h3>
        <p className="mb-4 text-sm text-gray-500 dark:text-slate-400">
          Preview how your PDF templates will look. Any changes you make to the settings below will
          update here automatically.
        </p>
        <LivePDFViewer pdfSettings={liveSettings} />
      </div>

      {/* ── Quick Preview Links (API-generated) ── */}
      <div className="rounded-lg bg-white p-6 shadow dark:bg-slate-900">
        <h3 className="mb-4 text-lg font-medium text-gray-900 dark:text-white">
          Download Preview PDFs
        </h3>
        <p className="mb-6 text-sm text-gray-500 dark:text-slate-400">
          Generate and download full PDF files using your current live settings above.
        </p>
        <div className="flex flex-wrap gap-4">
          <button
            type="button"
            onClick={() => handleDownloadPreview('transcript')}
            disabled={isGenerating === 'transcript'}
            className="inline-flex items-center gap-2 rounded-md border border-transparent bg-blue-600 px-4 py-2 text-sm font-medium text-white shadow-sm hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isGenerating === 'transcript' ? (
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
            ) : (
              <FileText className="h-4 w-4" />
            )}
            Preview Transcript
          </button>
          <button
            type="button"
            onClick={() => handleDownloadPreview('certificate')}
            disabled={isGenerating === 'certificate'}
            className="inline-flex items-center gap-2 rounded-md border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isGenerating === 'certificate' ? (
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-gray-500 border-t-transparent" />
            ) : (
              <Award className="h-4 w-4" />
            )}
            Preview Certificate
          </button>
          <button
            type="button"
            onClick={() => handleDownloadPreview('invoice')}
            disabled={isGenerating === 'invoice'}
            className="inline-flex items-center gap-2 rounded-md border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isGenerating === 'invoice' ? (
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-gray-500 border-t-transparent" />
            ) : (
              <FileText className="h-4 w-4" />
            )}
            Preview Invoice
          </button>
          <button
            type="button"
            onClick={() => handleDownloadPreview('financial-report')}
            disabled={isGenerating === 'financial-report'}
            className="inline-flex items-center gap-2 rounded-md border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isGenerating === 'financial-report' ? (
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-gray-500 border-t-transparent" />
            ) : (
              <FileText className="h-4 w-4" />
            )}
            Preview Financial Report
          </button>
        </div>
      </div>

      {/* ── Settings Fields ── */}
      <SettingsForm fields={PDF_FIELDS} values={values} groupLabel="PDF Templates" />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'
import { startRegistration } from '@simplewebauthn/browser'
import {
  Fingerprint,
  KeyRound,
  Laptop,
  Loader2,
  Plus,
  Smartphone,
  Trash2,
  Edit2,
  Check,
  X,
} from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { useConfirmDialog } from '@/hooks/use-confirm-dialog'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'

interface Passkey {
  id: string
  name: string | null
  deviceType: string
  backedUp: boolean
  createdAt: string
  lastUsedAt: string | null
}

export function PasskeySettings() {
  const [passkeys, setPasskeys] = useState<Passkey[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isRegistering, setIsRegistering] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editName, setEditName] = useState('')
  const [webAuthnSupported, setWebAuthnSupported] = useState<boolean | null>(null)
  const confirmDialog = useConfirmDialog()

  const fetchPasskeys = async () => {
    try {
      const res = await fetch('/api/staff/settings/passkeys')
      if (res.ok) {
        const data = await res.json()
        setPasskeys(data.passkeys)
      }
    } catch (error) {
      toast.error('Failed to load passkeys')
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setWebAuthnSupported(typeof window !== 'undefined' && !!window.PublicKeyCredential)
    fetchPasskeys()
  }, [])

  const handleAddPasskey = async () => {
    try {
      setIsRegistering(true)

      // 1. Get registration options from server
      const optionsRes = await fetch('/api/auth/passkey/register-options', { method: 'POST' })
      if (!optionsRes.ok) {
        const errData = await optionsRes.json().catch(() => null)
        throw new Error(errData?.detail || errData?.error || 'Failed to get registration options')
      }

      const { options } = await optionsRes.json()

      // 2. Prompt browser to create passkey
      let credential
      try {
        credential = await startRegistration({ optionsJSON: options })
      } catch (err: any) {
        if (err.name === 'NotAllowedError') {
          toast.error('Passkey creation was cancelled or blocked by your browser.')
          return
        }
        if (err.name === 'NotSupportedError') {
          toast.error(
            'Your device or browser does not support passkeys. Try using a security key instead.'
          )
          return
        }
        if (err.name === 'AbortError' || err.name === 'TimeoutError') {
          toast.error('Passkey creation timed out. Please try again.')
          return
        }
        throw err
      }

      // 3. Send credential back to server to verify and store
      const verifyRes = await fetch('/api/auth/passkey/register-verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ credential }),
      })

      if (!verifyRes.ok) {
        const errData = await verifyRes.json().catch(() => null)
        throw new Error(errData?.detail || errData?.error || 'Failed to verify passkey')
      }

      toast.success('Passkey added successfully')
      fetchPasskeys()
    } catch (error: any) {
      console.error(error)
      toast.error(error.message || 'An error occurred while adding the passkey')
    } finally {
      setIsRegistering(false)
    }
  }

  const handleDelete = (id: string, name: string) => {
    confirmDialog.confirm({
      title: 'Delete Passkey',
      description: `Are you sure you want to delete the passkey "${name}"? You will no longer be able to use it to sign in.`,
      onConfirm: async () => {
        try {
          const res = await fetch(`/api/auth/passkey/${id}`, { method: 'DELETE' })
          if (!res.ok) throw new Error((await res.text()) || 'Failed to delete passkey')

          toast.success('Passkey deleted')
          setPasskeys((prev) => prev.filter((p) => p.id !== id))
        } catch (error: any) {
          toast.error(error.message)
        } finally {
          confirmDialog.close()
        }
      },
    })
  }

  const handleSaveEdit = async (id: string) => {
    if (!editName.trim()) {
      setEditingId(null)
      return
    }

    try {
      const res = await fetch(`/api/auth/passkey/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName }),
      })

      if (!res.ok) throw new Error((await res.text()) || 'Failed to rename passkey')

      toast.success('Passkey renamed')
      setPasskeys(passkeys.map((p) => (p.id === id ? { ...p, name: editName } : p)))
      setEditingId(null)
    } catch (error: any) {
      toast.error(error.message)
    }
  }

  const getDeviceIcon = (deviceType: string, backedUp: boolean) => {
    if (backedUp) return <Smartphone className="text-muted-foreground h-5 w-5" />
    if (deviceType === 'singleDevice') return <Laptop className="text-muted-foreground h-5 w-5" />
    return <KeyRound className="text-muted-foreground h-5 w-5" />
  }

  return (
    <>
      <ConfirmDialog
        open={confirmDialog.open}
        onOpenChange={confirmDialog.onOpenChange}
        title={confirmDialog.title}
        description={confirmDialog.description}
        onConfirm={confirmDialog.onConfirm}
      />
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Fingerprint className="text-primary h-6 w-6" />
            <div>
              <CardTitle>Passkeys</CardTitle>
              <CardDescription>
                Sign in securely without a password using your device's biometrics or a security
                key.
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          {isLoading ? (
            <div className="flex justify-center p-4">
              <Loader2 className="text-muted-foreground h-6 w-6 animate-spin" />
            </div>
          ) : webAuthnSupported === false ? (
            <div className="rounded-lg border border-dashed p-8 text-center">
              <p className="text-muted-foreground text-sm">
                Your browser does not support passkeys. Please use a modern browser (Chrome, Safari,
                Edge, or Firefox) to manage passkeys.
              </p>
            </div>
          ) : passkeys.length === 0 ? (
            <div className="rounded-lg border border-dashed p-8 text-center">
              <p className="text-muted-foreground mb-4 text-sm">
                You haven't set up any passkeys yet.
              </p>
              <Button onClick={handleAddPasskey} disabled={isRegistering}>
                {isRegistering ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Plus className="mr-2 h-4 w-4" />
                )}
                Add a Passkey
              </Button>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="divide-y rounded-md border">
                {passkeys.map((passkey) => (
                  <div key={passkey.id} className="flex items-center justify-between p-4">
                    <div className="flex items-center gap-4">
                      <div className="bg-muted rounded-full p-2">
                        {getDeviceIcon(passkey.deviceType, passkey.backedUp)}
                      </div>
                      <div>
                        {editingId === passkey.id ? (
                          <div className="flex items-center gap-2">
                            <Input
                              value={editName}
                              onChange={(e) => setEditName(e.target.value)}
                              className="h-8 w-48"
                              autoFocus
                              onKeyDown={(e) => e.key === 'Enter' && handleSaveEdit(passkey.id)}
                            />
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-8 w-8 text-green-600"
                              onClick={() => handleSaveEdit(passkey.id)}
                            >
                              <Check className="h-4 w-4" />
                            </Button>
                            <Button
                              size="icon"
                              variant="ghost"
                              className="text-muted-foreground h-8 w-8"
                              onClick={() => setEditingId(null)}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </div>
                        ) : (
                          <div className="flex items-center gap-2">
                            <p className="text-sm font-medium">
                              {passkey.name || 'Unnamed Passkey'}
                            </p>
                            {passkey.backedUp && (
                              <Badge variant="secondary" className="text-xs">
                                Synced
                              </Badge>
                            )}
                          </div>
                        )}
                        <p className="text-muted-foreground text-xs">
                          Added {new Date(passkey.createdAt).toLocaleDateString()}
                          {passkey.lastUsedAt &&
                            ` â€¢ Last used ${new Date(passkey.lastUsedAt).toLocaleDateString()}`}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      {editingId !== passkey.id && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="text-muted-foreground hover:text-foreground"
                          onClick={() => {
                            setEditName(passkey.name || '')
                            setEditingId(passkey.id)
                          }}
                        >
                          <Edit2 className="h-4 w-4" />
                        </Button>
                      )}
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-muted-foreground hover:text-destructive"
                        onClick={() => handleDelete(passkey.id, passkey.name || 'this passkey')}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>

              <Button
                onClick={handleAddPasskey}
                disabled={isRegistering}
                variant="outline"
                className="w-full"
              >
                {isRegistering ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Plus className="mr-2 h-4 w-4" />
                )}
                Add Another Passkey
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import {
  Plus,
  Building2,
  Smartphone,
  CreditCard,
  Trash2,
  Edit2,
  ChevronUp,
  ChevronDown,
  ToggleLeft,
  ToggleRight,
  Loader2,
  X,
} from 'lucide-react'
import { toast } from 'sonner'

type PaymentMethodType = 'BANK_TRANSFER' | 'MOBILE_MONEY' | 'CARD_STRIPE'

interface PaymentMethod {
  id: string
  type: PaymentMethodType
  label: string
  currency: string
  isActive: boolean
  sortOrder: number
  bankName: string | null
  bankAccountName: string | null
  bankAccountNumber: string | null
  bankSwiftCode: string | null
  bankBranch: string | null
  momoProvider: string | null
  momoNumber: string | null
  momoMerchantCode: string | null
  momoAccountName: string | null
  stripeAccountId: string | null
}

const TYPE_META: Record<PaymentMethodType, { label: string; icon: typeof Building2 }> = {
  BANK_TRANSFER: { label: 'Bank Transfer', icon: Building2 },
  MOBILE_MONEY: { label: 'Mobile Money', icon: Smartphone },
  CARD_STRIPE: { label: 'Card (Stripe)', icon: CreditCard },
}

const CURRENCIES = ['GHS', 'EUR', 'USD']
const MOMO_PROVIDERS = [
  { value: 'MTN', label: 'MTN MoMo Pay' },
  { value: 'TELECEL', label: 'Telecel Cash' },
  { value: 'AIRTELTIGO', label: 'AirtelTigo Cash' },
]

const emptyForm = {
  type: 'BANK_TRANSFER' as PaymentMethodType,
  label: '',
  currency: 'GHS',
  bankName: '',
  bankAccountName: '',
  bankAccountNumber: '',
  bankSwiftCode: '',
  bankBranch: '',
  momoProvider: 'MTN',
  momoNumber: '',
  momoMerchantCode: '',
  momoAccountName: '',
  stripeAccountId: '',
}

export default function PaymentMethodsManager() {
  const [methods, setMethods] = useState<PaymentMethod[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [form, setForm] = useState({ ...emptyForm })
  const [submitting, setSubmitting] = useState(false)

  const fetchMethods = useCallback(async () => {
    try {
      const res = await fetch('/api/staff/payment-methods')
      if (res.ok) {
        const data = await res.json()
        setMethods(data.data || [])
      }
    } catch {
      toast.error('Failed to load payment methods')
    } finally {
      setLoading(false)
    }
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchMethods() }, [fetchMethods])

  const handleToggle = async (id: string) => {
    try {
      const res = await fetch(`/api/staff/payment-methods/${id}/toggle`, { method: 'PATCH' })
      if (res.ok) {
        const data = await res.json()
        setMethods((prev) => prev.map((m) => (m.id === id ? data.data : m)))
        toast.success('Payment method updated')
      }
    } catch {
      toast.error('Failed to toggle')
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this payment method?')) return
    try {
      const res = await fetch(`/api/staff/payment-methods/${id}`, { method: 'DELETE' })
      if (res.ok) {
        setMethods((prev) => prev.filter((m) => m.id !== id))
        toast.success('Payment method deleted')
      }
    } catch {
      toast.error('Failed to delete')
    }
  }

  const handleReorder = async (id: string, direction: 'up' | 'down') => {
    const idx = methods.findIndex((m) => m.id === id)
    if ((direction === 'up' && idx === 0) || (direction === 'down' && idx === methods.length - 1)) return

    const swapIdx = direction === 'up' ? idx - 1 : idx + 1
    const updated = [...methods]
    const temp = updated[idx].sortOrder
    updated[idx] = { ...updated[idx], sortOrder: updated[swapIdx].sortOrder }
    updated[swapIdx] = { ...updated[swapIdx], sortOrder: temp }
    ;[updated[idx], updated[swapIdx]] = [updated[swapIdx], updated[idx]]
    setMethods(updated)

    // Persist sort orders
    await Promise.all([
      fetch(`/api/staff/payment-methods/${updated[idx].id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sortOrder: updated[idx].sortOrder }),
      }),
      fetch(`/api/staff/payment-methods/${updated[swapIdx].id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sortOrder: updated[swapIdx].sortOrder }),
      }),
    ])
  }

  const startEdit = (method: PaymentMethod) => {
    setEditingId(method.id)
    setForm({
      type: method.type,
      label: method.label,
      currency: method.currency,
      bankName: method.bankName || '',
      bankAccountName: method.bankAccountName || '',
      bankAccountNumber: method.bankAccountNumber || '',
      bankSwiftCode: method.bankSwiftCode || '',
      bankBranch: method.bankBranch || '',
      momoProvider: method.momoProvider || 'MTN',
      momoNumber: method.momoNumber || '',
      momoMerchantCode: method.momoMerchantCode || '',
      momoAccountName: method.momoAccountName || '',
      stripeAccountId: method.stripeAccountId || '',
    })
    setShowForm(true)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!form.label.trim()) { toast.error('Label is required'); return }

    setSubmitting(true)
    try {
      const url = editingId ? `/api/staff/payment-methods/${editingId}` : '/api/staff/payment-methods'
      const method = editingId ? 'PUT' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      })

      if (res.ok) {
        toast.success(editingId ? 'Payment method updated' : 'Payment method added')
        setShowForm(false)
        setEditingId(null)
        setForm({ ...emptyForm })
        fetchMethods()
      } else {
        const err = await res.json()
        toast.error(err.error || 'Failed to save')
      }
    } catch {
      toast.error('Error saving payment method')
    } finally {
      setSubmitting(false)
    }
  }

  const cancelForm = () => {
    setShowForm(false)
    setEditingId(null)
    setForm({ ...emptyForm })
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12 text-slate-400">
        <Loader2 className="h-5 w-5 animate-spin" />
        <span className="ml-2 text-sm">Loading payment methods...</span>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100">Payment Methods</h3>
          <p className="text-xs text-slate-500">
            Manage bank accounts, mobile money, and card payment options visible to applicants and students.
          </p>
        </div>
        <button
          onClick={() => { setShowForm(true); setEditingId(null); setForm({ ...emptyForm }) }}
          className="flex items-center gap-1.5 rounded-xl bg-aerojet-blue px-4 py-2.5 text-xs font-bold text-white shadow-sm transition-colors hover:bg-[#003875]"
        >
          <Plus className="h-3.5 w-3.5" />
          Add Method
        </button>
      </div>

      {/* Methods List */}
      {methods.length === 0 ? (
        <div className="rounded-2xl border-2 border-dashed border-slate-200 p-8 text-center dark:border-slate-700">
          <Building2 className="mx-auto mb-3 h-8 w-8 text-slate-300" />
          <p className="text-sm font-bold text-slate-500">No payment methods configured</p>
          <p className="text-xs text-slate-400">Add a bank account or mobile money option to get started.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {methods.map((m, idx) => {
            const meta = TYPE_META[m.type as PaymentMethodType] || TYPE_META.BANK_TRANSFER
            const Icon = meta.icon
            return (
              <div
                key={m.id}
                className={`flex items-center gap-4 rounded-xl border p-4 transition-all ${
                  m.isActive
                    ? 'border-slate-200 bg-white dark:border-white/10 dark:bg-slate-900'
                    : 'border-slate-100 bg-slate-50 opacity-60 dark:border-white/5 dark:bg-slate-900/50'
                }`}
              >
                <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${
                  m.isActive ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-slate-100 text-slate-400'
                }`}>
                  <Icon className="h-5 w-5" />
                </div>

                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-900 dark:text-slate-100">{m.label}</span>
                    <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-bold text-slate-500 dark:bg-slate-800">
                      {m.currency}
                    </span>
                    <span className="text-[10px] text-slate-400">{meta.label}</span>
                  </div>
                  <p className="mt-0.5 truncate text-xs text-slate-400">
                    {m.type === 'BANK_TRANSFER' && `${m.bankName || ''} Â· ${m.bankAccountNumber || ''}`}
                    {m.type === 'MOBILE_MONEY' && `${m.momoProvider || ''} Â· ${m.momoNumber || ''}`}
                    {m.type === 'CARD_STRIPE' && 'Online card payments'}
                  </p>
                </div>

                <div className="flex shrink-0 items-center gap-1">
                  <button onClick={() => handleReorder(m.id, 'up')} disabled={idx === 0}
                    className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 disabled:opacity-30"
                    title="Move up"
                  >
                    <ChevronUp className="h-4 w-4" />
                  </button>
                  <button onClick={() => handleReorder(m.id, 'down')} disabled={idx === methods.length - 1}
                    className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 disabled:opacity-30"
                    title="Move down"
                  >
                    <ChevronDown className="h-4 w-4" />
                  </button>

                  <button onClick={() => handleToggle(m.id)}
                    className="rounded-lg p-1.5 transition-colors hover:bg-slate-100"
                    title={m.isActive ? 'Disable' : 'Enable'}
                  >
                    {m.isActive ? (
                      <ToggleRight className="h-5 w-5 text-green-500" />
                    ) : (
                      <ToggleLeft className="h-5 w-5 text-slate-300" />
                    )}
                  </button>

                  <button onClick={() => startEdit(m)}
                    className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-blue-50 hover:text-blue-600"
                    title="Edit"
                  >
                    <Edit2 className="h-4 w-4" />
                  </button>

                  <button onClick={() => handleDelete(m.id)}
                    className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-red-50 hover:text-red-600"
                    title="Delete"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Add/Edit Form Overlay */}
      {showForm && (
        <div className="rounded-2xl border border-blue-200 bg-blue-50/30 p-6 dark:border-blue-800 dark:bg-blue-900/10">
          <div className="mb-4 flex items-center justify-between">
            <h4 className="text-sm font-bold text-slate-900 dark:text-slate-100">
              {editingId ? 'Edit Payment Method' : 'Add Payment Method'}
            </h4>
            <button onClick={cancelForm} className="rounded-lg p-1 text-slate-400 hover:text-slate-600">
              <X className="h-4 w-4" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Type Selection */}
            <div className="grid grid-cols-3 gap-2">
              {(Object.entries(TYPE_META) as [PaymentMethodType, typeof TYPE_META.BANK_TRANSFER][]).map(([type, meta]) => {
                const Icon = meta.icon
                const isSelected = form.type === type
                return (
                  <button
                    key={type}
                    type="button"
                    onClick={() => setForm({ ...form, type })}
                    className={`flex items-center gap-2 rounded-xl border-2 p-3 text-left text-xs font-bold transition-all ${
                      isSelected
                        ? 'border-aerojet-blue bg-aerojet-blue/5 text-aerojet-blue'
                        : 'border-slate-200 text-slate-500 hover:border-slate-300'
                    }`}
                  >
                    <Icon className="h-4 w-4" />
                    {meta.label}
                  </button>
                )
              })}
            </div>

            {/* Common Fields */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="mb-1 block text-xs font-bold text-slate-600">Display Label *</label>
                <input
                  value={form.label}
                  onChange={(e) => setForm({ ...form, label: e.target.value })}
                  placeholder={form.type === 'BANK_TRANSFER' ? 'e.g. FNB Bank (GHS)' : form.type === 'MOBILE_MONEY' ? 'e.g. MTN MoMo Pay' : 'e.g. Stripe'}
                  className="w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm focus:border-aerojet-blue focus:ring-2 focus:ring-aerojet-blue/10 focus:outline-none dark:border-white/10 dark:bg-black/20 dark:text-white"
                  required
                />
              </div>
              <div>
                <label className="mb-1 block text-xs font-bold text-slate-600">Currency *</label>
                <select
                  value={form.currency}
                  onChange={(e) => setForm({ ...form, currency: e.target.value })}
                  className="w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm focus:border-aerojet-blue focus:ring-2 focus:ring-aerojet-blue/10 focus:outline-none dark:border-white/10 dark:bg-black/20 dark:text-white"
                >
                  {CURRENCIES.map((c) => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Bank Transfer Fields */}
            {form.type === 'BANK_TRANSFER' && (
              <div className="space-y-3 rounded-xl border border-slate-200 bg-white p-4 dark:border-white/10 dark:bg-slate-900">
                <p className="text-[10px] font-bold tracking-widest text-slate-400 uppercase">Bank Details</p>
                <div className="grid grid-cols-2 gap-3">
                  <Input label="Bank Name" value={form.bankName} onChange={(v) => setForm({ ...form, bankName: v })} placeholder="e.g. FNB Bank" />
                  <Input label="Account Name" value={form.bankAccountName} onChange={(v) => setForm({ ...form, bankAccountName: v })} placeholder="e.g. AEROJET FOUNDATION" />
                  <Input label="Account Number" value={form.bankAccountNumber} onChange={(v) => setForm({ ...form, bankAccountNumber: v })} placeholder="e.g. 1020003980687" />
                  <Input label="SWIFT / BIC Code" value={form.bankSwiftCode} onChange={(v) => setForm({ ...form, bankSwiftCode: v })} placeholder="e.g. FIRNGHACXXX" />
                  <Input label="Branch / Code" value={form.bankBranch} onChange={(v) => setForm({ ...form, bankBranch: v })} placeholder="e.g. 330102" />
                </div>
              </div>
            )}

            {/* Mobile Money Fields */}
            {form.type === 'MOBILE_MONEY' && (
              <div className="space-y-3 rounded-xl border border-slate-200 bg-white p-4 dark:border-white/10 dark:bg-slate-900">
                <p className="text-[10px] font-bold tracking-widest text-slate-400 uppercase">Mobile Money Details</p>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="mb-1 block text-xs font-bold text-slate-600">Provider</label>
                    <select
                      value={form.momoProvider}
                      onChange={(e) => setForm({ ...form, momoProvider: e.target.value })}
                      className="w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm focus:border-aerojet-blue focus:ring-2 focus:ring-aerojet-blue/10 focus:outline-none dark:border-white/10 dark:bg-black/20 dark:text-white"
                    >
                      {MOMO_PROVIDERS.map((p) => (
                        <option key={p.value} value={p.value}>{p.label}</option>
                      ))}
                    </select>
                  </div>
                  <Input label="Phone Number" value={form.momoNumber} onChange={(v) => setForm({ ...form, momoNumber: v })} placeholder="e.g. 024 123 4567" />
                  <Input label="Merchant Code" value={form.momoMerchantCode} onChange={(v) => setForm({ ...form, momoMerchantCode: v })} placeholder="Optional" />
                  <Input label="Account Name" value={form.momoAccountName} onChange={(v) => setForm({ ...form, momoAccountName: v })} placeholder="e.g. Aerojet Academy" />
                </div>
              </div>
            )}

            {/* Stripe Fields */}
            {form.type === 'CARD_STRIPE' && (
              <div className="space-y-3 rounded-xl border border-slate-200 bg-white p-4 dark:border-white/10 dark:bg-slate-900">
                <p className="text-[10px] font-bold tracking-widest text-slate-400 uppercase">Stripe Configuration</p>
                <Input label="Stripe Account ID" value={form.stripeAccountId} onChange={(v) => setForm({ ...form, stripeAccountId: v })} placeholder="e.g. acct_..." />
                <p className="text-xs text-amber-600">Stripe integration is coming soon. You can add the account ID now for future use.</p>
              </div>
            )}

            <div className="flex items-center justify-end gap-3">
              <button type="button" onClick={cancelForm} className="rounded-xl px-4 py-2.5 text-xs font-bold text-slate-500 transition-colors hover:text-slate-700">
                Cancel
              </button>
              <button
                type="submit"
                disabled={submitting}
                className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-5 py-2.5 text-xs font-bold text-white shadow-sm transition-colors hover:bg-[#003875] disabled:opacity-50"
              >
                {submitting && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
                {editingId ? 'Update' : 'Add Method'}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  )
}

function Input({
  label,
  value,
  onChange,
  placeholder,
}: {
  label: string
  value: string
  onChange: (v: string) => void
  placeholder?: string
}) {
  return (
    <div>
      <label className="mb-1 block text-xs font-bold text-slate-600">{label}</label>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm focus:border-aerojet-blue focus:ring-2 focus:ring-aerojet-blue/10 focus:outline-none dark:border-white/10 dark:bg-black/20 dark:text-white"
      />
    </div>
  )
}

'use client'

import { useRouter, useSearchParams } from 'next/navigation'
import { createContext, useContext, useCallback } from 'react'
import {
  School,
  DollarSign,
  Mail,
  Globe,
  Sparkles,
  Send,
  Calendar,
  DatabaseBackup,
  Shield,
  ClipboardList,
  AtSign,
  FileText,
} from 'lucide-react'
import { useUnsavedChanges } from '@/hooks/useUnsavedChanges'
import { UnsavedChangesDialog } from '@/components/shared/UnsavedChangesDialog'

const TABS = [
  { key: 'general', label: 'General', icon: School },
  { key: 'admissions', label: 'Admissions', icon: ClipboardList },
  { key: 'finance', label: 'Finance', icon: DollarSign },
  { key: 'comms', label: 'Emails & Comms', icon: Mail },
  { key: 'academic', label: 'Academic', icon: Calendar },
  { key: 'templates', label: 'Templates', icon: FileText },
  { key: 'system', label: 'System & Data', icon: Globe },
  { key: 'security', label: 'My Security', icon: Shield },
]

// ── Context so child forms can mark dirty / clean without prop drilling ──────
interface DirtyContextValue {
  markDirty: () => void
  markClean: () => void
}

export const SettingsDirtyContext = createContext<DirtyContextValue>({
  markDirty: () => {},
  markClean: () => {},
})

export function useSettingsDirty() {
  return useContext(SettingsDirtyContext)
}

export default function SettingsTabs({ children }: { children: React.ReactNode }) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const currentTab = searchParams.get('tab') || 'general'

  const { isDirty, markDirty, markClean, confirmLeave, pendingTab, proceedLeave, cancelLeave } =
    useUnsavedChanges()

  const handleChange = useCallback(
    (tab: string) => {
      router.push(`/staff/settings?tab=${tab}`, { scroll: false })
      // Reset dirty state when we actually navigate
      markClean()
    },
    [router, markClean]
  )

  const currentTabObj = TABS.find((t) => t.key === currentTab) || TABS[0]

  return (
    <SettingsDirtyContext.Provider value={{ markDirty, markClean }}>
      <div className="space-y-6">
        <div>
          <h1 className="text-aerojet-blue text-2xl font-black tracking-tight sm:text-3xl dark:text-white">
            {currentTabObj.label} Settings
          </h1>
        </div>

        {children}

        <UnsavedChangesDialog
          open={pendingTab !== null}
          onProceed={proceedLeave}
          onCancel={cancelLeave}
        />
      </div>
    </SettingsDirtyContext.Provider>
  )
}

'use client'

import { useState } from 'react'
import { Shield, ShieldCheck, ShieldOff, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'

interface TwoFactorSettingsProps {
  twoFactorEnabled: boolean
}

export default function TwoFactorSettings({ twoFactorEnabled }: TwoFactorSettingsProps) {
  const [enabled, setEnabled] = useState(twoFactorEnabled)
  const [step, setStep] = useState<'idle' | 'setup' | 'disable'>('idle')
  const [loading, setLoading] = useState(false)
  const [qrCodeUrl, setQrCodeUrl] = useState('')
  const [code, setCode] = useState('')

  async function handleStartSetup() {
    setLoading(true)
    try {
      const res = await fetch('/api/auth/2fa/generate', { method: 'POST' })
      if (!res.ok) throw new Error('Failed to generate 2FA secret')
      const data = await res.json()
      setQrCodeUrl(data.qrCodeUrl)
      setStep('setup')
    } catch {
      toast.error('Failed to start 2FA setup')
    } finally {
      setLoading(false)
    }
  }

  async function handleVerifyAndEnable() {
    if (code.length !== 6) {
      toast.error('Enter a 6-digit code')
      return
    }
    setLoading(true)
    try {
      const res = await fetch('/api/auth/2fa/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: code }),
      })
      if (!res.ok) {
        const text = await res.text()
        throw new Error(text || 'Invalid code')
      }
      setEnabled(true)
      setStep('idle')
      setCode('')
      setQrCodeUrl('')
      toast.success('Two-factor authentication enabled')
    } catch (err: any) {
      toast.error(err.message || 'Failed to verify code')
    } finally {
      setLoading(false)
    }
  }

  async function handleDisable() {
    if (code.length !== 6) {
      toast.error('Enter your current 2FA code to disable')
      return
    }
    setLoading(true)
    try {
      const res = await fetch('/api/auth/2fa/disable', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: code }),
      })
      if (!res.ok) {
        const text = await res.text()
        throw new Error(text || 'Invalid code')
      }
      setEnabled(false)
      setStep('idle')
      setCode('')
      toast.success('Two-factor authentication disabled')
    } catch (err: any) {
      toast.error(err.message || 'Failed to disable 2FA')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex items-start gap-4">
          <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600 dark:bg-indigo-900/20">
            <Shield className="h-6 w-6" />
          </div>
          <div className="flex-1">
            <h3 className="text-aerojet-blue text-lg font-black dark:text-white">
              Two-Factor Authentication
            </h3>
            <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
              Add an extra layer of security to your account using a TOTP authenticator app.
            </p>

            <div className="mt-4 flex items-center gap-2">
              {enabled ? (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400">
                  <ShieldCheck className="h-3.5 w-3.5" />
                  Enabled
                </span>
              ) : (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-700 dark:bg-amber-900/20 dark:text-amber-400">
                  <ShieldOff className="h-3.5 w-3.5" />
                  Not Enabled
                </span>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Idle state — show enable or disable button */}
      {step === 'idle' && (
        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          {enabled ? (
            <div className="space-y-4">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Your account is protected with two-factor authentication. To disable it, you will
                need to enter a code from your authenticator app.
              </p>
              <Button
                variant="destructive"
                onClick={() => {
                  setStep('disable')
                  setCode('')
                }}
                disabled={loading}
              >
                Disable 2FA
              </Button>
            </div>
          ) : (
            <div className="space-y-4">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Protect your staff account by requiring a verification code from an authenticator
                app (Google Authenticator, Authy, etc.) each time you log in.
              </p>
              <Button
                onClick={handleStartSetup}
                disabled={loading}
                className="bg-aerojet-blue hover:bg-aerojet-sky"
              >
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Enable 2FA
              </Button>
            </div>
          )}
        </div>
      )}

      {/* Setup step — show QR code and verification input */}
      {step === 'setup' && (
        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="space-y-6">
            <div>
              <h4 className="text-sm font-bold text-slate-900 dark:text-white">
                Step 1: Scan QR Code
              </h4>
              <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
                Open your authenticator app and scan this QR code to add your account.
              </p>
            </div>

            {qrCodeUrl && (
              <div className="flex justify-center">
                <div className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700">
                  <img src={qrCodeUrl} alt="2FA QR Code" className="h-48 w-48" />
                </div>
              </div>
            )}

            <div>
              <h4 className="text-sm font-bold text-slate-900 dark:text-white">
                Step 2: Enter Verification Code
              </h4>
              <p className="mt-1 mb-3 text-sm text-slate-500 dark:text-slate-400">
                Enter the 6-digit code from your authenticator app to verify setup.
              </p>
              <div className="flex items-center gap-3">
                <Input
                  type="text"
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={6}
                  placeholder="000000"
                  value={code}
                  onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                  className="w-40 text-center font-mono text-lg tracking-[0.3em]"
                />
                <Button
                  onClick={handleVerifyAndEnable}
                  disabled={loading || code.length !== 6}
                  className="bg-aerojet-blue hover:bg-aerojet-sky"
                >
                  {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  Verify & Enable
                </Button>
              </div>
            </div>

            <Button
              variant="ghost"
              onClick={() => {
                setStep('idle')
                setCode('')
                setQrCodeUrl('')
              }}
            >
              Cancel
            </Button>
          </div>
        </div>
      )}

      {/* Disable step — require current TOTP code */}
      {step === 'disable' && (
        <div className="rounded-2xl border border-red-200 bg-red-50/50 p-6 shadow-sm dark:border-red-900/50 dark:bg-red-900/10">
          <div className="space-y-4">
            <h4 className="text-sm font-bold text-red-800 dark:text-red-400">
              Confirm Disable 2FA
            </h4>
            <p className="text-sm text-red-700/80 dark:text-red-400/80">
              Enter a code from your authenticator app to confirm you want to disable two-factor
              authentication.
            </p>
            <div className="flex items-center gap-3">
              <Input
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={6}
                placeholder="000000"
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                className="w-40 text-center font-mono text-lg tracking-[0.3em]"
              />
              <Button
                variant="destructive"
                onClick={handleDisable}
                disabled={loading || code.length !== 6}
              >
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Confirm Disable
              </Button>
              <Button
                variant="ghost"
                onClick={() => {
                  setStep('idle')
                  setCode('')
                }}
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Plus, Edit2, Trash2, CheckCircle2, XCircle, Settings, Save, X } from 'lucide-react'
import { useRouter } from 'next/navigation'
import { CustomFieldDefinition, CustomFieldType, CustomFieldTarget, ProgrammeChoice } from '@prisma/client'

export default function CustomFieldsManager({ initialFields }: { initialFields: CustomFieldDefinition[] }) {
  const router = useRouter()
  const [fields, setFields] = useState(initialFields)
  const [isAdding, setIsAdding] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [formData, setFormData] = useState<Partial<CustomFieldDefinition>>({})

  const handleSave = async () => {
    if (!formData.name || !formData.slug || !formData.fieldType || !formData.appliesTo) {
      alert('Please fill in all required fields (Name, Slug, Type, Applies To)')
      return
    }

    try {
      const url = editingId 
        ? `/api/staff/settings/custom-fields/${editingId}`
        : '/api/staff/settings/custom-fields'
      
      const method = editingId ? 'PUT' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      })

      if (res.ok) {
        setIsAdding(false)
        setEditingId(null)
        setFormData({})
        router.refresh()
        // Optimistic local update could be added here, but refresh is fine
      } else {
        const error = await res.json()
        alert(error.error || 'Failed to save custom field')
      }
    } catch (e) {
      alert('An unexpected error occurred')
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this custom field? All data associated with it will be lost.')) return

    try {
      const res = await fetch(`/api/staff/settings/custom-fields/${id}`, { method: 'DELETE' })
      if (res.ok) {
        router.refresh()
      } else {
        alert('Failed to delete custom field')
      }
    } catch (e) {
      alert('An unexpected error occurred')
    }
  }

  const startEdit = (field: CustomFieldDefinition) => {
    setEditingId(field.id)
    setFormData(field)
    setIsAdding(false)
  }

  const startAdd = () => {
    setIsAdding(true)
    setEditingId(null)
    setFormData({
      fieldType: 'TEXT',
      appliesTo: 'APPLICATION',
      isRequired: false,
      isActive: true,
      sortOrder: 0,
      applicableProgrammes: []
    })
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-bold text-slate-900 dark:text-white">Active Fields</h2>
        <button
          onClick={startAdd}
          disabled={isAdding || !!editingId}
          className="flex items-center gap-2 rounded-lg bg-aerojet-blue px-4 py-2 text-sm font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50"
        >
          <Plus className="h-4 w-4" />
          Add Field
        </button>
      </div>

      {(isAdding || editingId) && (
        <div className="rounded-xl border border-aerojet-blue/30 bg-aerojet-blue/5 p-6 dark:border-aerojet-sky/30 dark:bg-aerojet-sky/5">
          <div className="mb-4 flex items-center justify-between">
            <h3 className="font-bold text-aerojet-blue dark:text-aerojet-sky">
              {isAdding ? 'Create New Field' : 'Edit Field'}
            </h3>
            <button onClick={() => { setIsAdding(false); setEditingId(null); setFormData({}); }} className="text-slate-500 hover:text-slate-700 dark:hover:text-slate-300">
              <X className="h-5 w-5" />
            </button>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Display Name</label>
              <input
                type="text"
                className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                value={formData.name || ''}
                onChange={e => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g. Blood Type"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Unique Slug</label>
              <input
                type="text"
                className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                value={formData.slug || ''}
                onChange={e => setFormData({ ...formData, slug: e.target.value })}
                placeholder="e.g. blood_type"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Field Type</label>
              <select
                className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                value={formData.fieldType || 'TEXT'}
                onChange={e => setFormData({ ...formData, fieldType: e.target.value as CustomFieldType })}
              >
                {Object.values(CustomFieldType).map(type => (
                  <option key={type} value={type}>{type}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Applies To Entity</label>
              <select
                className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                value={formData.appliesTo || 'APPLICATION'}
                onChange={e => setFormData({ ...formData, appliesTo: e.target.value as CustomFieldTarget })}
              >
                {(Object.values(CustomFieldTarget) as string[]).map((entity) => (
                  <option key={entity} value={entity}>{entity.replace('_', ' ')}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Sort Order</label>
              <input
                type="number"
                className="w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900"
                value={formData.sortOrder ?? 0}
                onChange={e => setFormData({ ...formData, sortOrder: parseInt(e.target.value, 10) || 0 })}
              />
            </div>
            
            <div className="flex items-center gap-6 sm:col-span-2 lg:col-span-1">
              <label className="flex items-center gap-2 text-sm font-medium">
                <input
                  type="checkbox"
                  className="rounded border-slate-300 text-aerojet-blue"
                  checked={formData.isRequired || false}
                  onChange={e => setFormData({ ...formData, isRequired: e.target.checked })}
                />
                Required Field
              </label>
              <label className="flex items-center gap-2 text-sm font-medium">
                <input
                  type="checkbox"
                  className="rounded border-slate-300 text-aerojet-blue"
                  checked={formData.isActive !== false}
                  onChange={e => setFormData({ ...formData, isActive: e.target.checked })}
                />
                Active
              </label>
            </div>
            
            {(formData.fieldType === 'SELECT' || formData.fieldType === 'MULTI_SELECT') && (
              <div className="sm:col-span-2 lg:col-span-3">
                <label className="mb-1 block text-xs font-bold text-slate-700 dark:text-slate-300">Options (JSON Array)</label>
                <input
                  type="text"
                  className="w-full rounded-lg border px-3 py-2 text-sm font-mono dark:border-slate-700 dark:bg-slate-900"
                  value={formData.options ? JSON.stringify(formData.options) : '["Option 1", "Option 2"]'}
                  onChange={e => {
                    try {
                      const parsed = JSON.parse(e.target.value)
                      setFormData({ ...formData, options: parsed })
                    } catch (err) {
                      // Allow invalid state while typing, but don't save to state
                    }
                  }}
                  placeholder='["Option 1", "Option 2"]'
                />
                <p className="mt-1 text-[10px] text-slate-500">Must be a valid JSON array of strings.</p>
              </div>
            )}
          </div>
          
          <div className="mt-6 flex justify-end gap-3">
            <button
              onClick={handleSave}
              className="flex items-center gap-2 rounded-lg bg-aerojet-blue px-6 py-2 text-sm font-bold text-white hover:bg-aerojet-blue/90"
            >
              <Save className="h-4 w-4" /> Save Field
            </button>
          </div>
        </div>
      )}

      <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
        <table className="w-full text-left text-sm">
          <thead className="border-b border-slate-200 bg-slate-50 text-slate-600 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300">
            <tr>
              <th className="p-4 font-semibold">Field Name</th>
              <th className="p-4 font-semibold">Entity</th>
              <th className="p-4 font-semibold">Type</th>
              <th className="p-4 font-semibold text-center">Required</th>
              <th className="p-4 font-semibold text-center">Active</th>
              <th className="p-4 font-semibold text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
            {initialFields.length === 0 ? (
              <tr>
                <td colSpan={6} className="p-8 text-center text-slate-500">
                  No custom fields defined yet.
                </td>
              </tr>
            ) : (
              initialFields.map((field) => (
                <tr key={field.id} className="transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50">
                  <td className="p-4">
                    <div className="font-bold text-slate-900 dark:text-white">{field.name}</div>
                    <div className="font-mono text-xs text-slate-500">{field.slug}</div>
                  </td>
                  <td className="p-4">
                    <span className="inline-flex rounded-md bg-slate-100 px-2.5 py-0.5 text-xs font-medium text-slate-800 dark:bg-slate-800 dark:text-slate-300">
                      {field.appliesTo}
                    </span>
                  </td>
                  <td className="p-4">
                    <span className="inline-flex rounded-md bg-aerojet-blue/10 px-2.5 py-0.5 text-xs font-medium text-aerojet-blue dark:bg-aerojet-sky/10 dark:text-aerojet-sky">
                      {field.fieldType}
                    </span>
                  </td>
                  <td className="p-4 text-center">
                    {field.isRequired ? (
                      <CheckCircle2 className="mx-auto h-5 w-5 text-green-500" />
                    ) : (
                      <span className="text-slate-300 dark:text-slate-600">-</span>
                    )}
                  </td>
                  <td className="p-4 text-center">
                    {field.isActive ? (
                      <CheckCircle2 className="mx-auto h-5 w-5 text-green-500" />
                    ) : (
                      <XCircle className="mx-auto h-5 w-5 text-slate-300 dark:text-slate-600" />
                    )}
                  </td>
                  <td className="p-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        onClick={() => startEdit(field)}
                        className="rounded p-1 text-slate-400 hover:bg-slate-100 hover:text-aerojet-blue dark:hover:bg-slate-800 dark:hover:text-aerojet-sky"
                        title="Edit Field"
                      >
                        <Edit2 className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => handleDelete(field.id)}
                        className="rounded p-1 text-slate-400 hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-900/20 dark:hover:text-red-400"
                        title="Delete Field"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

'use client'

