export default function EmailPreviewsPage() {
  const [activeTemplate, setActiveTemplate] = useState('registration')
  const [hoveredTemplate, setHoveredTemplate] = useState<string | null>(null)
  const [allTemplates, setAllTemplates] = useState(TEMPLATES) // Start with default TEMPLATES
  const [isEditing, setIsEditing] = useState(false)
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [sendingTest, setSendingTest] = useState(false)
  const [editData, setEditData] = useState({
    subject: '',
    body: '',
  })
  const [testEmail, setTestEmail] = useState('')

  const fetchAllTemplates = async () => {
    try {
      const res = await fetch('/api/staff/email-templates')
      if (res.ok) {
        const dbTemplates = await res.json()

        // Merge DB templates with default TEMPLATES
        const mergedTemplates = [...TEMPLATES]

        dbTemplates.forEach((dbTemp: any) => {
          const existingIndex = mergedTemplates.findIndex((t) => t.id === dbTemp.name)
          if (existingIndex === -1 && dbTemp.name) {
            // It's a brand new custom template
            mergedTemplates.push({
              id: dbTemp.name,
              name: dbTemp.name.replace(/-/g, ' ').replace(/\b\w/g, (c: string) => c.toUpperCase()),
              icon: Layers, // Default icon for custom templates
              description: dbTemp.description || 'Custom Email Template',
              placeholders: ['firstName'], // Default placeholder, maybe more if parsable
            })
          }
        })

        setAllTemplates(mergedTemplates)
      }
    } catch (error) {
      toast.error('Failed to load email templates')
    }
  }

  const fetchTemplateContent = async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/email-templates?name=${activeTemplate}`)
      if (res.ok) {
        const data = await res.json()
        if (data) {
          setEditData({
            subject: data.subject || '',
            body: data.body || '',
          })
        } else {
          // No custom template yet
          setEditData({ subject: '', body: '' })
        }
      }
    } catch (error) {
      toast.error('Failed to load template')
    } finally {
      setLoading(false)
    }
  }

  // Fetch template data when editing starts
  useEffect(() => {
    if (isEditing) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchTemplateContent()
    }
  }, [isEditing, activeTemplate])

  // Fetch all templates on mount
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchAllTemplates()
  }, [])

  const handleSave = async () => {
    if (!editData.subject || !editData.body) {
      toast.error('Subject and Body are required')
      return
    }

    setSaving(true)
    try {
      const res = await fetch('/api/staff/email-templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: activeTemplate,
          ...editData,
        }),
      })

      if (res.ok) {
        toast.success('Template saved successfully')
        // Refresh templates list to get any new description
        fetchAllTemplates()
        // Refresh iframe (hacky but works)
        const iframe = document.querySelector('iframe')
        if (iframe) iframe.src = iframe.src
      } else {
        toast.error('Failed to save template')
      }
    } catch (error) {
      toast.error('Error saving template')
    } finally {
      setSaving(false)
    }
  }

  const handleReset = async () => {
    if (!confirm('Are you sure you want to reset to default? This will delete your custom layout.'))
      return

    try {
      await fetch(`/api/staff/email-templates?name=${activeTemplate}`, {
        method: 'DELETE',
      })
      toast.success('Reset to default')
      setIsEditing(false)
      const iframe = document.querySelector('iframe')
      if (iframe) iframe.src = iframe.src
    } catch (error) {
      toast.error('Failed to reset')
    }
  }

  const handleSendTest = async (sendAll = false) => {
    setSendingTest(true)
    const toastId = toast.loading(sendAll ? 'Sending all test emails...' : `Sending test email...`)

    try {
      const res = await fetch('/api/staff/email-test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          templateName: sendAll ? undefined : activeTemplate,
          sendAll,
          targetEmail: testEmail || undefined,
        }),
      })

      if (res.ok) {
        toast.success(sendAll ? 'Global test suite sent!' : 'Test email sent to your inbox!', {
          id: toastId,
        })
      } else {
        toast.error('Failed to send test email', { id: toastId })
      }
    } catch (error) {
      toast.error('Error sending test email', { id: toastId })
    } finally {
      setSendingTest(false)
    }
  }

  const currentTemplate = allTemplates.find((t) => t.id === activeTemplate)

  return (
    <div className="space-y-6">
      <div className="flex flex-col justify-between gap-4 md:flex-row md:items-center">
        <div>
          <h2 className="text-aerojet-blue text-xl font-black tracking-tight dark:text-white">
            Email Templates
          </h2>
          <p className="mt-1 text-sm text-slate-500">
            Review and customize automated email communications.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={() => setIsEditing(!isEditing)}
            className={cn(
              'text-xs font-bold tracking-widest uppercase transition-all',
              isEditing
                ? 'border-amber-500 text-amber-500'
                : 'border-aerojet-blue text-aerojet-blue'
            )}
          >
            {isEditing ? (
              <>
                <Eye className="mr-2 h-4 w-4" /> Switch to Preview
              </>
            ) : (
              <>
                <Edit3 className="mr-2 h-4 w-4" /> Customize Template
              </>
            )}
          </Button>
          <Button
            disabled={sendingTest}
            onClick={() => handleSendTest(true)}
            className="bg-aerojet-blue hover:bg-aerojet-sky text-xs font-bold tracking-widest uppercase shadow-lg transition-all"
          >
            <Send className="mr-2 h-4 w-4" />
            {sendingTest ? 'Sending...' : 'Send Global Test'}
          </Button>
        </div>
      </div>

      {/* Recipient Input Card */}
      <Card className="border-slate-200 bg-blue-50/30 shadow-sm">
        <CardContent className="flex flex-col gap-4 p-4 md:flex-row md:items-center">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-blue-100 text-blue-600">
            <Mail className="h-5 w-5" />
          </div>
          <div className="flex-1">
            <p className="text-sm font-bold text-slate-900">Test Recipient</p>
            <p className="text-xs text-slate-500">
              Specify where to send test emails. Defaults to your account email if left blank.
            </p>
          </div>
          <div className="w-full md:w-80">
            <Label htmlFor="test-recipient-email" className="sr-only">
              Test Recipient Email
            </Label>
            <Input
              id="test-recipient-email"
              type="email"
              placeholder="e.g. test@example.com"
              value={testEmail}
              onChange={(e) => setTestEmail(e.target.value)}
              className="bg-white"
            />
          </div>
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-4">
        {/* Sidebar List */}
        <Card className="flex flex-col border-none border-slate-200 bg-slate-50/50 shadow-sm lg:sticky lg:top-6 lg:col-span-1 lg:max-h-[calc(100vh-120px)] lg:self-start">
          <CardHeader className="shrink-0 pb-3">
            <CardTitle className="text-sm font-bold tracking-wider text-slate-400 uppercase">
              Templates
            </CardTitle>
          </CardHeader>
          <CardContent
            className="relative flex-1 space-y-1 overflow-y-auto p-2"
            onMouseLeave={() => setHoveredTemplate(null)}
          >
            {allTemplates.map((tmpl) => {
              const isActive = activeTemplate === tmpl.id
              const isHovered = hoveredTemplate === tmpl.id && !isActive
              return (
                <button
                  key={tmpl.id}
                  onClick={() => {
                    setActiveTemplate(tmpl.id)
                    setIsEditing(false)
                  }}
                  onMouseEnter={() => setHoveredTemplate(tmpl.id)}
                  className={`relative flex w-full items-center gap-3 rounded-xl p-3 text-left transition-all ${
                    isActive ? 'text-aerojet-blue font-bold' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  {/* Hover highlight */}
                  {isHovered && (
                    <motion.div
                      layoutId="template-hover"
                      className="absolute inset-0 bg-slate-100 dark:bg-slate-800/50"
                      style={{ borderRadius: 12, zIndex: 0 }}
                      transition={{ type: 'spring', bounce: 0.15, duration: 0.4 }}
                    />
                  )}
                  {/* Active indicator */}
                  {isActive && (
                    <motion.div
                      layoutId="template-pill"
                      className="absolute inset-0 bg-white shadow-md"
                      style={{ borderRadius: 12, zIndex: 0 }}
                      transition={{ type: 'spring', bounce: 0.2, duration: 0.6 }}
                    />
                  )}
                  <div
                    className={`relative z-10 rounded-lg p-2 ${
                      isActive ? 'bg-aerojet-blue text-white' : 'bg-slate-200'
                    }`}
                  >
                    <tmpl.icon className="h-4 w-4" />
                  </div>
                  <span className="relative z-10 text-sm">{tmpl.name}</span>
                </button>
              )
            })}
          </CardContent>
        </Card>

        {/* Work Area */}
        <div className="space-y-6 lg:col-span-3">
          <AnimatePresence mode="wait">
            {!isEditing ? (
              <motion.div
                key="preview"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
              >
                <Card className="overflow-hidden border-slate-200 shadow-none">
                  <CardHeader className="flex flex-row items-center justify-between border-b border-slate-100 bg-white">
                    <div>
                      <CardTitle className="text-aerojet-blue text-xl font-bold">
                        {currentTemplate?.name}
                      </CardTitle>
                      <CardDescription className="mt-1">
                        {currentTemplate?.description}
                      </CardDescription>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge variant="outline" className="font-mono text-[10px] uppercase">
                        HTML Template
                      </Badge>
                      <Badge className="bg-green-500 hover:bg-green-600">Active</Badge>
                    </div>
                  </CardHeader>
                  <CardContent className="flex justify-center bg-slate-100 p-0">
                    <div className="my-8 w-full max-w-[640px] overflow-hidden rounded-lg border border-slate-200 bg-white shadow-2xl">
                      <div className="flex items-center gap-2 border-b border-slate-200 bg-slate-50 p-3">
                        <div className="flex gap-1.5">
                          <div className="h-3 w-3 rounded-full bg-red-400" />
                          <div className="h-3 w-3 rounded-full bg-yellow-400" />
                          <div className="h-3 w-3 rounded-full bg-green-400" />
                        </div>
                        <div className="ml-4 flex flex-1 items-center justify-between rounded border border-slate-200 bg-white px-3 py-1 text-[11px] text-slate-400">
                          <span>
                            From: Aerojet Aviation Training Academy
                            &lt;noreply@aerojet-academy.com&gt;
                          </span>
                          <Eye className="h-3 w-3" />
                        </div>
                      </div>
                      <iframe
                        src={`/api/staff/email-preview?template=${activeTemplate}`}
                        className="min-h-[600px] w-full border-none"
                        title="Email Preview"
                      />
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ) : (
              <motion.div
                key="editor"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
              >
                <Card className="border-slate-200 shadow-xl">
                  <CardHeader className="border-b border-slate-100 pb-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <CardTitle className="text-aerojet-blue text-xl font-bold">
                          Edit Template: {currentTemplate?.name}
                        </CardTitle>
                        <CardDescription>
                          Customize the content and layout. Use placeholders like{' '}
                          <code className="rounded bg-slate-100 px-1 py-0.5">
                            {'{' + '{firstName}' + '}'}
                          </code>
                        </CardDescription>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={handleReset}
                          className="text-slate-500 hover:text-red-500"
                        >
                          <RotateCcw className="mr-2 h-4 w-4" /> Reset to Default
                        </Button>
                        <Button
                          disabled={saving}
                          onClick={handleSave}
                          className="bg-[#16a34a] hover:bg-[#15803d]"
                        >
                          {saving ? (
                            'Saving...'
                          ) : (
                            <>
                              <Save className="mr-2 h-4 w-4" /> Save Template
                            </>
                          )}
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-6 pt-6">
                    {loading ? (
                      <div className="py-20 text-center text-slate-400">Loading template...</div>
                    ) : (
                      <>
                        <div className="space-y-2">
                          <Label className="text-xs font-bold tracking-wider text-slate-500 uppercase">
                            Email Subject
                          </Label>
                          <Input
                            placeholder="Enter subject line..."
                            value={editData.subject}
                            onChange={(e) => setEditData({ ...editData, subject: e.target.value })}
                            className="text-aerojet-blue text-lg font-bold"
                          />
                        </div>

                        <div className="space-y-2">
                          <div className="flex items-center justify-between">
                            <Label className="text-xs font-bold tracking-wider text-slate-500 uppercase">
                              Email Body (HTML)
                            </Label>
                            <Badge variant="outline" className="gap-1 text-[10px]">
                              <Info className="h-3 w-3" />
                              Placeholders supported
                            </Badge>
                          </div>
                          <RichTextEditor
                            content={editData.body}
                            onChange={(body) => setEditData({ ...editData, body })}
                            className="min-h-[400px]"
                          />
                        </div>

                        <div className="rounded-xl border border-slate-200 bg-slate-50 p-4">
                          <p className="mb-3 text-xs font-bold tracking-wider text-slate-500 uppercase">
                            Available Placeholders
                          </p>
                          <div className="flex flex-wrap gap-2">
                            {currentTemplate?.placeholders.map((p) => (
                              <button
                                key={p}
                                type="button"
                                aria-label={`Copy placeholder ${p} to clipboard`}
                                onClick={() => {
                                  // Simple way to copy to clipboard or just show
                                  navigator.clipboard.writeText(`{{${p}}}`)
                                  toast.success(`Copied {{${p}}}`)
                                }}
                                className="group hover:border-aerojet-blue flex items-center gap-1 rounded-full border border-slate-200 bg-white px-3 py-1 font-mono text-[11px] transition-all"
                              >
                                <PlusCircle
                                  className="group-hover:text-aerojet-blue h-3 w-3 text-slate-300"
                                  role="presentation"
                                />
                                <span>
                                  {'{' + '{'}
                                  {p}
                                  {'}' + '}'}
                                </span>
                              </button>
                            ))}
                          </div>
                          <p className="mt-3 text-[10px] text-slate-400">
                            Click a placeholder to copy it to your clipboard.
                          </p>
                        </div>
                      </>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            )}
          </AnimatePresence>

          {!isEditing && (
            <div className="flex items-center justify-between rounded-2xl border border-slate-200 bg-white p-4">
              <div className="flex items-center gap-4">
                <div className="bg-aerojet-sky/10 flex h-10 w-10 items-center justify-center rounded-full">
                  <Mail className="text-aerojet-sky h-5 w-5" />
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-900">Individual Template Test</p>
                  <p className="text-xs text-slate-500">
                    Send a test of the <strong>{currentTemplate?.name}</strong> template.
                  </p>
                </div>
              </div>
              <Button
                variant="outline"
                disabled={sendingTest}
                onClick={() => handleSendTest(false)}
                className="border-aerojet-blue text-aerojet-blue hover:bg-aerojet-blue text-[10px] font-bold tracking-widest uppercase transition-all hover:text-white"
              >
                {sendingTest ? 'Sending...' : 'Send Live Test'}
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import {
  BookOpen,
  Calendar,
  Award,
  Clock,
  User,
  ChevronDown,
  ChevronRight,
  CheckCircle2,
  XCircle,
} from 'lucide-react'

interface Grade {
  id: string
  assessmentName: string
  assessmentType: string
  score: number | string
  maxScore: number | string
  percentage: number | string
  grade?: string | null
  assessmentDate: string | Date
}

interface Enrollment {
  id: string
  status: string
  enrolledAt?: string | null
  approvedAt?: string | null
  completedAt?: string | null
  course?: { name: string; code: string } | null
  grades?: Grade[]
}

interface AttendanceRecord {
  id: string
  date: string | Date
  status: string
  minutesLate?: number | null
  class?: { name?: string; course?: { name?: string } } | null
}

interface OjtPeriod {
  id: string
  companyName: string
  companyAddress?: string | null
  supervisorName?: string | null
  status: string
  hoursCompleted: number
  hoursRequired: number
  startDate?: string | null
  endDate?: string | null
}

interface FullTimeEnrollment {
  id: string
  currentYearNumber?: number | null
  status: string
  programme?: { name: string } | null
  ojtPeriods?: OjtPeriod[]
}

interface Props {
  student: any
  onRefresh: () => void
}

export default function AcademicTab({ student, onRefresh }: Props) {
  const [expandedEnrollment, setExpandedEnrollment] = useState<string | null>(null)
  const [expandedOjt, setExpandedOjt] = useState<string | null>(null)

  const enrollments: Enrollment[] = student.enrollments || []
  const attendanceRecords: AttendanceRecord[] = student.attendanceRecords || []
  const fullTimeEnrollments: FullTimeEnrollment[] = student.fullTimeEnrollments || []

  // Calculate attendance stats
  const attendanceStats = {
    total: attendanceRecords.length,
    present: attendanceRecords.filter((r: any) => r.status === 'PRESENT').length,
    absent: attendanceRecords.filter((r: any) => r.status === 'ABSENT').length,
    late: attendanceRecords.filter((r: any) => r.status === 'LATE').length,
  }

  return (
    <div className="space-y-8">
      {/* Enrollments */}
      <Section title="Course Enrollments" icon={BookOpen}>
        {enrollments.length === 0 ? (
          <EmptyState message="No course enrollments" />
        ) : (
          <div className="space-y-3">
            {enrollments.map((enrollment: Enrollment) => {
              const isExpanded = expandedEnrollment === enrollment.id
              const grades = enrollment.grades || []
              const avgGrade =
                grades.length > 0
                  ? grades.reduce((sum: number, g: Grade) => sum + Number(g.percentage || 0), 0) /
                    grades.length
                  : null

              return (
                <div
                  key={enrollment.id}
                  className="rounded-xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"
                >
                  <button
                    onClick={() => setExpandedEnrollment(isExpanded ? null : enrollment.id)}
                    className="flex w-full items-center justify-between p-4 text-left"
                  >
                    <div className="flex items-center gap-3">
                      {isExpanded ? (
                        <ChevronDown className="h-4 w-4 text-slate-400" />
                      ) : (
                        <ChevronRight className="h-4 w-4 text-slate-400" />
                      )}
                      <div>
                        <p className="font-bold text-slate-800 dark:text-slate-200">
                          {enrollment.course?.name || 'Unknown Course'}
                        </p>
                        <p className="font-mono text-xs text-slate-400">
                          {enrollment.course?.code || '—'}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span
                        className={`rounded-full px-2.5 py-0.5 text-[10px] font-black uppercase ${
                          enrollment.status === 'ACTIVE'
                            ? 'bg-emerald-100 text-emerald-700'
                            : enrollment.status === 'COMPLETED'
                              ? 'bg-blue-100 text-blue-700'
                              : enrollment.status === 'PENDING'
                                ? 'bg-amber-100 text-amber-700'
                                : 'bg-slate-100 text-slate-500'
                        }`}
                      >
                        {enrollment.status}
                      </span>
                      {avgGrade !== null && (
                        <span className="font-mono text-sm font-bold text-slate-600">
                          {avgGrade.toFixed(1)}%
                        </span>
                      )}
                    </div>
                  </button>

                  {isExpanded && (
                    <div className="border-t border-slate-200 px-4 pt-2 pb-4 dark:border-slate-700">
                      <div className="mb-3 flex items-center gap-4 text-xs text-slate-400">
                        <span>
                          Enrolled:{' '}
                          {enrollment.enrolledAt
                            ? new Date(enrollment.enrolledAt).toLocaleDateString('en-GB')
                            : '—'}
                        </span>
                        {enrollment.approvedAt && (
                          <span>
                            Approved: {new Date(enrollment.approvedAt).toLocaleDateString('en-GB')}
                          </span>
                        )}
                        {enrollment.completedAt && (
                          <span>
                            Completed:{' '}
                            {new Date(enrollment.completedAt).toLocaleDateString('en-GB')}
                          </span>
                        )}
                      </div>

                      {/* Grades */}
                      {grades.length > 0 ? (
                        <div className="space-y-2">
                          <p className="text-[10px] font-black tracking-widest text-slate-400 uppercase">
                            Grades ({grades.length})
                          </p>
                          <div className="overflow-x-auto">
                            <table className="w-full text-xs">
                              <thead>
                                <tr className="border-b border-slate-200 text-slate-400 dark:border-slate-700">
                                  <th className="pb-2 text-left font-black">Assessment</th>
                                  <th className="pb-2 text-center font-black">Score</th>
                                  <th className="pb-2 text-center font-black">%</th>
                                  <th className="pb-2 text-center font-black">Grade</th>
                                  <th className="pb-2 text-right font-black">Date</th>
                                </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
                                {grades.map((grade: Grade) => (
                                  <tr key={grade.id}>
                                    <td className="py-2">
                                      <span className="font-medium text-slate-700 dark:text-slate-300">
                                        {grade.assessmentName}
                                      </span>
                                      <span className="ml-1 text-slate-400">
                                        ({grade.assessmentType})
                                      </span>
                                    </td>
                                    <td className="py-2 text-center font-mono">
                                      {Number(grade.score)}/{Number(grade.maxScore)}
                                    </td>
                                    <td className="py-2 text-center font-mono">
                                      {Number(grade.percentage).toFixed(1)}%
                                    </td>
                                    <td className="py-2 text-center">
                                      <span
                                        className={`rounded px-1.5 py-0.5 text-[9px] font-bold ${
                                          Number(grade.percentage) >= 75
                                            ? 'bg-emerald-100 text-emerald-700'
                                            : 'bg-red-100 text-red-700'
                                        }`}
                                      >
                                        {grade.grade ||
                                          (Number(grade.percentage) >= 75 ? 'PASS' : 'FAIL')}
                                      </span>
                                    </td>
                                    <td className="py-2 text-right text-slate-400">
                                      {grade.assessmentDate
                                        ? new Date(grade.assessmentDate).toLocaleDateString('en-GB')
                                        : '—'}
                                    </td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        </div>
                      ) : (
                        <p className="text-xs text-slate-400">No grades recorded yet</p>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </Section>

      {/* Attendance */}
      <Section title="Attendance" icon={Calendar}>
        <div className="mb-4 grid grid-cols-4 gap-3">
          <div className="rounded-xl border border-slate-200 bg-white p-3 text-center dark:border-slate-700 dark:bg-slate-900">
            <p className="text-lg font-black text-slate-700 dark:text-slate-200">
              {attendanceStats.total}
            </p>
            <p className="text-[10px] font-black tracking-widest text-slate-400 uppercase">Total</p>
          </div>
          <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-3 text-center dark:border-emerald-900/30 dark:bg-emerald-900/10">
            <p className="text-lg font-black text-emerald-600">{attendanceStats.present}</p>
            <p className="text-[10px] font-black tracking-widest text-emerald-600 uppercase">
              Present
            </p>
          </div>
          <div className="rounded-xl border border-red-100 bg-red-50 p-3 text-center dark:border-red-900/30 dark:bg-red-900/10">
            <p className="text-lg font-black text-red-600">{attendanceStats.absent}</p>
            <p className="text-[10px] font-black tracking-widest text-red-600 uppercase">Absent</p>
          </div>
          <div className="rounded-xl border border-amber-100 bg-amber-50 p-3 text-center dark:border-amber-900/30 dark:bg-amber-900/10">
            <p className="text-lg font-black text-amber-600">{attendanceStats.late}</p>
            <p className="text-[10px] font-black tracking-widest text-amber-600 uppercase">Late</p>
          </div>
        </div>

        {attendanceRecords.length === 0 ? (
          <EmptyState message="No attendance records" />
        ) : (
          <div className="max-h-64 overflow-y-auto rounded-xl border border-slate-200 dark:border-slate-700">
            <table className="w-full text-xs">
              <thead className="sticky top-0 bg-slate-50 dark:bg-slate-900">
                <tr className="border-b border-slate-200 dark:border-slate-700">
                  <th className="px-4 py-2 text-left font-black text-slate-400">Date</th>
                  <th className="px-4 py-2 text-left font-black text-slate-400">Course</th>
                  <th className="px-4 py-2 text-center font-black text-slate-400">Status</th>
                  <th className="px-4 py-2 text-right font-black text-slate-400">Minutes Late</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
                {attendanceRecords.slice(0, 20).map((record: AttendanceRecord) => (
                  <tr key={record.id}>
                    <td className="px-4 py-2 text-slate-500">
                      {record.date
                        ? new Date(record.date).toLocaleDateString('en-GB', {
                            day: 'numeric',
                            month: 'short',
                          })
                        : '—'}
                    </td>
                    <td className="px-4 py-2 text-slate-700 dark:text-slate-300">
                      {record.class?.course?.name || record.class?.name || '—'}
                    </td>
                    <td className="px-4 py-2 text-center">
                      {record.status === 'PRESENT' ? (
                        <CheckCircle2 className="mx-auto h-4 w-4 text-emerald-500" />
                      ) : record.status === 'ABSENT' ? (
                        <XCircle className="mx-auto h-4 w-4 text-red-500" />
                      ) : (
                        <Clock className="mx-auto h-4 w-4 text-amber-500" />
                      )}
                    </td>
                    <td className="px-4 py-2 text-right font-mono text-slate-500">
                      {record.minutesLate || '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Section>

      {/* OJT (for full-time students) */}
      {fullTimeEnrollments.length > 0 && (
        <Section title="On-The-Job Training (OJT)" icon={User}>
          <div className="space-y-3">
            {fullTimeEnrollments.map((fte: FullTimeEnrollment) => (
              <div
                key={fte.id}
                className="rounded-xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"
              >
                <div className="flex items-center justify-between border-b border-slate-200 px-4 py-3 dark:border-slate-700">
                  <div>
                    <p className="font-bold text-slate-800 dark:text-slate-200">
                      {fte.programme?.name || 'Full-Time Programme'}
                    </p>
                    <p className="text-xs text-slate-400">
                      Year {fte.currentYearNumber} • {fte.status}
                    </p>
                  </div>
                  <button
                    onClick={() => setExpandedOjt(expandedOjt === fte.id ? null : fte.id)}
                    className="text-aerojet-blue flex items-center gap-1 text-xs font-bold"
                  >
                    {expandedOjt === fte.id ? 'Hide' : 'View'} OJT Periods
                  </button>
                </div>

                {expandedOjt === fte.id && fte.ojtPeriods && fte.ojtPeriods.length > 0 && (
                  <div className="space-y-3 p-4">
                    {fte.ojtPeriods.map((ojt: OjtPeriod) => (
                      <div
                        key={ojt.id}
                        className="rounded-lg border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-800/50"
                      >
                        <div className="flex items-center justify-between">
                          <div>
                            <p className="font-bold text-slate-700 dark:text-slate-200">
                              {ojt.companyName}
                            </p>
                            <p className="text-xs text-slate-400">
                              {ojt.companyAddress || 'No address'} • Supervisor:{' '}
                              {ojt.supervisorName || '—'}
                            </p>
                          </div>
                          <span
                            className={`rounded-full px-2 py-0.5 text-[9px] font-black uppercase ${
                              ojt.status === 'VERIFIED'
                                ? 'bg-emerald-100 text-emerald-700'
                                : ojt.status === 'IN_PROGRESS'
                                  ? 'bg-blue-100 text-blue-700'
                                  : 'bg-slate-100 text-slate-500'
                            }`}
                          >
                            {ojt.status}
                          </span>
                        </div>
                        <div className="mt-2 flex items-center gap-4 text-xs text-slate-400">
                          <span>
                            {ojt.startDate
                              ? new Date(ojt.startDate).toLocaleDateString('en-GB')
                              : '—'}
                            {ojt.endDate
                              ? ` - ${new Date(ojt.endDate).toLocaleDateString('en-GB')}`
                              : ' - Present'}
                          </span>
                          <span>
                            Hours: {ojt.hoursCompleted}/{ojt.hoursRequired}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {expandedOjt === fte.id && (!fte.ojtPeriods || fte.ojtPeriods.length === 0) && (
                  <div className="p-4 text-center text-sm text-slate-400">
                    No OJT periods recorded
                  </div>
                )}
              </div>
            ))}
          </div>
        </Section>
      )}
    </div>
  )
}

function Section({
  title,
  icon: Icon,
  children,
}: {
  title: string
  icon: React.ComponentType<{ className?: string }>
  children: React.ReactNode
}) {
  return (
    <div>
      <h3 className="mb-4 flex items-center gap-2 text-xs font-black tracking-widest text-slate-400 uppercase">
        <Icon className="h-4 w-4" />
        {title}
      </h3>
      {children}
    </div>
  )
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-10 text-center">
      <p className="text-sm font-bold text-slate-400">{message}</p>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { FileText, Plus, Loader2, Pencil, Trash2, X, Check, StickyNote } from 'lucide-react'
import { toast } from 'sonner'
import { formatDistanceToNow, format } from 'date-fns'

interface AdminNote {
  id: string
  content: string
  createdBy: string
  createdAt: string
  updatedAt: string
  authorName: string
}

interface Props {
  student: any
  onRefresh: () => void
  staffId: string
  staffRole: string
}

export default function AdminNotesTab({ student, onRefresh, staffId, staffRole }: Props) {
  const [notes, setNotes] = useState<AdminNote[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [newNote, setNewNote] = useState('')
  const [isAdding, setIsAdding] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editContent, setEditContent] = useState('')
  const [deletingId, setDeletingId] = useState<string | null>(null)

  const isSuperAdmin = staffRole === 'SUPER_ADMIN'

  const fetchNotes = useCallback(async () => {
    try {
      const res = await fetch(`/api/staff/students/${student.id}/notes`)
      if (res.ok) {
        const data = await res.json()
        setNotes(data.data?.notes || [])
      }
    } catch {
      console.error('Failed to fetch notes')
    } finally {
      setIsLoading(false)
    }
  }, [student.id])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchNotes()
  }, [fetchNotes])

  const handleAddNote = async () => {
    if (!newNote.trim()) return
    setIsAdding(true)
    try {
      const res = await fetch(`/api/staff/students/${student.id}/notes`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: newNote.trim() }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to add note')
      toast.success('Note added')
      setNewNote('')
      fetchNotes()
    } catch (err: unknown) {
      if (err instanceof Error) {
        toast.error(err.message)
      } else {
        toast.error('An unexpected error occurred')
      }
    } finally {
      setIsAdding(false)
    }
  }

  const handleUpdateNote = async (noteId: string) => {
    if (!editContent.trim()) return
    try {
      const res = await fetch(`/api/staff/students/${student.id}/notes/${noteId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: editContent.trim() }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to update note')
      toast.success('Note updated')
      setEditingId(null)
      fetchNotes()
    } catch (err: unknown) {
      if (err instanceof Error) {
        toast.error(err.message)
      } else {
        toast.error('An unexpected error occurred')
      }
    }
  }

  const handleDeleteNote = async (noteId: string) => {
    setDeletingId(noteId)
    try {
      const res = await fetch(`/api/staff/students/${student.id}/notes/${noteId}`, {
        method: 'DELETE',
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to delete note')
      toast.success('Note deleted')
      fetchNotes()
    } catch (err: any) {
      toast.error(err.message)
    } finally {
      setDeletingId(null)
    }
  }

  const canModify = (note: AdminNote) => isSuperAdmin || note.createdBy === staffId

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-2">
        <StickyNote className="text-aerojet-blue h-5 w-5" />
        <h3 className="text-lg font-semibold">Admin Notes</h3>
        {notes.length > 0 && (
          <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-black text-slate-500 dark:bg-slate-800">
            {notes.length}
          </span>
        )}
      </div>

      {/* Add Note Form */}
      <div className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
        <label className="mb-2 block text-xs font-bold tracking-wider text-slate-400 uppercase">
          Add a Note
        </label>
        <textarea
          value={newNote}
          onChange={(e) => setNewNote(e.target.value)}
          placeholder="Write a private note about this student..."
          className="focus:border-aerojet-blue focus:ring-aerojet-blue min-h-[100px] w-full rounded-lg border border-slate-200 p-3 text-sm focus:ring-1 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white"
        />
        <div className="mt-3 flex justify-end">
          <button
            onClick={handleAddNote}
            disabled={isAdding || !newNote.trim()}
            className="bg-aerojet-blue flex items-center gap-2 rounded-lg px-4 py-2 text-xs font-bold text-white transition-colors hover:bg-[#001d42] disabled:opacity-50"
          >
            {isAdding ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Plus className="h-3.5 w-3.5" />
            )}
            Add Note
          </button>
        </div>
      </div>

      {/* Notes List */}
      {isLoading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="h-6 w-6 animate-spin text-slate-400" />
        </div>
      ) : notes.length === 0 ? (
        <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-12 text-center dark:border-slate-700 dark:bg-slate-800/30">
          <FileText className="mx-auto mb-3 h-10 w-10 text-slate-200 dark:text-slate-700" />
          <p className="text-sm font-medium text-slate-400">No notes yet.</p>
          <p className="mt-1 text-xs text-slate-300 dark:text-slate-600">
            Add the first note using the form above.
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {notes.map((note) => (
            <div
              key={note.id}
              className="rounded-xl border border-slate-100 bg-white p-4 transition-colors hover:border-slate-200 dark:border-slate-800 dark:bg-slate-900 dark:hover:border-slate-700"
            >
              {/* Note Header */}
              <div className="mb-2 flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="bg-aerojet-blue/10 text-aerojet-blue flex h-8 w-8 items-center justify-center rounded-full text-[10px] font-black uppercase dark:bg-blue-500/10 dark:text-blue-400">
                    {note.authorName
                      .split(' ')
                      .map((n) => n[0])
                      .join('')
                      .slice(0, 2)}
                  </div>
                  <div>
                    <p className="text-sm font-bold text-slate-700 dark:text-slate-200">
                      {note.authorName}
                    </p>
                    <p
                      className="text-[10px] text-slate-400"
                      title={format(new Date(note.createdAt), 'PPpp')}
                    >
                      {formatDistanceToNow(new Date(note.createdAt), { addSuffix: true })}
                      {note.updatedAt !== note.createdAt && ' (edited)'}
                    </p>
                  </div>
                </div>

                {/* Actions */}
                {canModify(note) && editingId !== note.id && (
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => {
                        setEditingId(note.id)
                        setEditContent(note.content)
                      }}
                      className="rounded-lg p-1.5 text-slate-300 transition-all duration-150 ease-out hover:bg-slate-100 hover:text-slate-500 dark:hover:bg-slate-800/60"
                      title="Edit"
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </button>
                    <button
                      onClick={() => handleDeleteNote(note.id)}
                      disabled={deletingId === note.id}
                      className="rounded-lg p-1.5 text-slate-300 transition-colors hover:bg-red-50 hover:text-red-500 dark:hover:bg-red-900/20"
                      title="Delete"
                    >
                      {deletingId === note.id ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      ) : (
                        <Trash2 className="h-3.5 w-3.5" />
                      )}
                    </button>
                  </div>
                )}
              </div>

              {/* Note Content */}
              {editingId === note.id ? (
                <div className="mt-2">
                  <textarea
                    value={editContent}
                    onChange={(e) => setEditContent(e.target.value)}
                    className="focus:border-aerojet-blue focus:ring-aerojet-blue min-h-[80px] w-full rounded-lg border border-slate-200 p-3 text-sm focus:ring-1 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-white"
                  />
                  <div className="mt-2 flex justify-end gap-2">
                    <button
                      onClick={() => setEditingId(null)}
                      className="flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-500 transition-colors hover:bg-slate-100 dark:hover:bg-slate-800"
                    >
                      <X className="h-3 w-3" /> Cancel
                    </button>
                    <button
                      onClick={() => handleUpdateNote(note.id)}
                      disabled={!editContent.trim()}
                      className="bg-aerojet-blue flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-bold text-white transition-colors hover:bg-[#001d42] disabled:opacity-50"
                    >
                      <Check className="h-3 w-3" /> Save
                    </button>
                  </div>
                </div>
              ) : (
                <p className="text-sm leading-relaxed whitespace-pre-wrap text-slate-600 dark:text-slate-300">
                  {note.content}
                </p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { toast } from 'sonner'
import { Loader2, ShoppingCart, AlertCircle, Wallet, X } from 'lucide-react'

const BOOKING_TYPES = [
  { value: 'INDIVIDUAL', label: 'Single Exam', modules: 1, desc: 'Individual exam seat' },
  { value: 'TWIN_PACK', label: 'Twin Pack', modules: 2, desc: '2 exams bundled' },
  { value: 'FOUR_PACK', label: '4-Pack Bundle', modules: 4, desc: '4 exams bundled' },
  { value: 'RESIT', label: 'Resit', modules: 1, desc: 'Re-sit a failed exam' },
] as const

const ATTEMPT_TYPES = [
  { value: 'FIRST', label: '1st Attempt' },
  { value: 'RESIT_1', label: 'Resit (2nd)' },
  { value: 'RESIT_2', label: 'Resit (3rd)' },
  { value: 'RESIT_3', label: 'Resit (4th+)' },
]

// Default prices — will be overridden by backend
const DEFAULT_PRICES: Record<string, number> = {
  INDIVIDUAL: 520,
  TWIN_PACK: 980,
  FOUR_PACK: 1900,
  RESIT: 480,
}

interface Props {
  studentId: string
  studentName: string
  walletBalance: number
  walletCurrency: string
  enrollmentType?: string | null
  academicYears?: { id: string; name: string }[]
  semesters?: { id: string; name: string }[]
  examComponents: {
    id: string
    code: string
    name: string
    course?: { id: string; name: string; code: string }
  }[]
  upcomingEvents: {
    id: string
    name: string
    startDate: string
    endDate: string
  }[]
  onSuccess: () => void
}

export default function BookExamForStudentDialog({
  studentId,
  studentName,
  walletBalance,
  walletCurrency,
  enrollmentType,
  academicYears,
  semesters,
  examComponents,
  upcomingEvents,
  onSuccess,
}: Props) {
  const isFullTime = enrollmentType === 'FULL_TIME'
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)

  const [bookingType, setBookingType] = useState<string>('INDIVIDUAL')
  const [selectedModules, setSelectedModules] = useState<string[]>([])
  const [eventId, setEventId] = useState<string>('')
  const [examDate, setExamDate] = useState<string>('')
  const [academicYearId, setAcademicYearId] = useState<string>('')
  const [semesterId, setSemesterId] = useState<string>('')
  const [paymentMethod, setPaymentMethod] = useState<'AUTO_DEBIT' | 'MANUAL_LATER'>('AUTO_DEBIT')
  const [attemptType, setAttemptType] = useState<string>('FIRST')
  const [notes, setNotes] = useState<string>('')

  const selectedType = BOOKING_TYPES.find((t) => t.value === bookingType)!
  const price = DEFAULT_PRICES[bookingType] || 520
  const canAfford = walletBalance >= price

  // Deduplicate by code and naturally sort exam components
  const sortedExamComponents = useMemo(() => {
    const seenCourse = new Set<string>()
    return examComponents
      .filter((ec) => {
        const courseId = ec.course?.id || ec.id
        if (seenCourse.has(courseId)) return false
        seenCourse.add(courseId)
        return true
      })
      .sort((a, b) => {
        const codeA = a.code || ''
        const codeB = b.code || ''
        const numA = parseInt(codeA.replace(/\D/g, '') || '0', 10)
        const numB = parseInt(codeB.replace(/\D/g, '') || '0', 10)
        if (numA && numB) return numA - numB
        return codeA.localeCompare(codeB)
      })
  }, [examComponents])

  const toggleModule = (id: string) => {
    setSelectedModules((prev) => {
      if (prev.includes(id)) return prev.filter((m) => m !== id)
      if (prev.length >= selectedType.modules) return prev
      return [...prev, id]
    })
  }

  const handleSubmit = async () => {
    if (selectedModules.length !== selectedType.modules) {
      toast.error(`Please select exactly ${selectedType.modules} module(s)`)
      return
    }

    // For full-time students, allow academic calendar instead of exam date
    // For others, require exam event or date
    const hasAcademicInfo = isFullTime && academicYearId && semesterId
    const hasExamInfo = eventId || examDate

    if (!hasAcademicInfo && !hasExamInfo) {
      if (isFullTime) {
        toast.error('Please select an academic calendar (year & semester) or an exam event/date')
      } else {
        toast.error('Please select an exam event or enter an exam date')
      }
      return
    }

    if (paymentMethod === 'AUTO_DEBIT' && !canAfford) {
      toast.error('Insufficient wallet balance for auto-debit')
      return
    }

    setLoading(true)
    try {
      const res = await fetch(`/api/staff/students/${studentId}/book-exam`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bookingType,
          moduleIds: selectedModules,
          eventId: eventId || undefined,
          examDate: examDate || undefined,
          academicYearId: academicYearId || undefined,
          semesterId: semesterId || undefined,
          paymentMethod,
          attemptType: bookingType === 'RESIT' ? attemptType : 'FIRST',
          notes,
        }),
      })

      const data = await res.json()

      if (!res.ok || !data.success) {
        toast.error(data.error || 'Failed to book exam')
        return
      }

      toast.success(
        `Exam booked successfully! ${paymentMethod === 'AUTO_DEBIT' ? `€${price} debited from wallet.` : 'Payment pending.'}`
      )
      setOpen(false)
      resetForm()
      onSuccess()
    } catch (err) {
      toast.error('Failed to book exam. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  const resetForm = () => {
    setBookingType('INDIVIDUAL')
    setSelectedModules([])
    setEventId('')
    setExamDate('')
    setAcademicYearId('')
    setSemesterId('')
    setPaymentMethod('AUTO_DEBIT')
    setAttemptType('FIRST')
    setNotes('')
  }

  return (
    <>
      {/* Trigger button */}
      {!open && (
        <button
          onClick={() => setOpen(true)}
          className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-4 py-2 text-xs font-bold text-white transition-all hover:bg-[#001f45]"
        >
          <ShoppingCart className="h-3.5 w-3.5" />
          Book Exam
        </button>
      )}

      {/* Modal Overlay */}
      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="relative max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-xl dark:bg-slate-900">
            {/* Header */}
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-100 bg-white px-6 py-4 dark:border-slate-800 dark:bg-slate-900">
              <div>
                <h2 className="text-lg font-black text-slate-800 dark:text-white">
                  Book Exam for {studentName}
                </h2>
                <p className="text-xs text-slate-400">
                  Wallet: {walletCurrency} {walletBalance.toFixed(2)}
                </p>
              </div>
              <button
                onClick={() => {
                  setOpen(false)
                  resetForm()
                }}
                className="flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 hover:bg-slate-100"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="space-y-6 p-6">
              {/* Step 1: Booking Type */}
              <div>
                <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                  Booking Type
                </label>
                <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                  {BOOKING_TYPES.map((type) => (
                    <button
                      key={type.value}
                      onClick={() => {
                        setBookingType(type.value)
                        setSelectedModules([])
                        if (type.value === 'RESIT') setAttemptType('RESIT_1')
                        else setAttemptType('FIRST')
                      }}
                      className={`rounded-xl border p-3 text-left transition-all ${
                        bookingType === type.value
                          ? 'border-aerojet-blue bg-aerojet-blue/5 ring-1 ring-aerojet-blue'
                          : 'border-slate-200 hover:border-slate-300 dark:border-slate-700'
                      }`}
                    >
                      <div className="text-sm font-bold text-slate-800 dark:text-slate-200">
                        {type.label}
                      </div>
                      <div className="text-[10px] text-slate-400">{type.desc}</div>
                      <div className="mt-1 text-sm font-black text-aerojet-blue">
                        €{DEFAULT_PRICES[type.value]}
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Step 2: Select Modules */}
              <div>
                <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                  Select Module{selectedType.modules > 1 ? 's' : ''} ({selectedModules.length}/
                  {selectedType.modules})
                </label>
                <div className="grid max-h-48 grid-cols-1 gap-1.5 overflow-y-auto rounded-xl border border-slate-200 bg-slate-50 p-3 sm:grid-cols-2 dark:border-slate-700 dark:bg-slate-800/50">
                  {sortedExamComponents.map((comp) => {
                    const isSelected = selectedModules.includes(comp.id)
                    const isFull = selectedModules.length >= selectedType.modules && !isSelected
                    return (
                      <button
                        key={comp.id}
                        onClick={() => toggleModule(comp.id)}
                        disabled={isFull}
                        className={`rounded-lg border px-3 py-2 text-left text-xs transition-all ${
                          isSelected
                            ? 'border-aerojet-blue bg-aerojet-blue/10 font-bold text-aerojet-blue'
                            : isFull
                              ? 'cursor-not-allowed border-slate-100 bg-slate-100/50 text-slate-300'
                              : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300 dark:border-slate-700 dark:bg-slate-900'
                        }`}
                      >
                        <span className="font-mono font-bold">
                          {comp.course?.code || comp.code}
                        </span>
                        <span className="ml-1.5 text-slate-400">
                          {comp.course?.name || comp.name}
                        </span>
                      </button>
                    )
                  })}
                </div>
              </div>

              {/* Step 3: Academic Calendar (Full-Time Students Only) */}
              {isFullTime && academicYears && academicYears.length > 0 && (
                <div>
                  <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                    Academic Calendar (Full-Time)
                  </label>
                  <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                    <div>
                      <label className="mb-1 block text-xs text-slate-500">Academic Year</label>
                      <select
                        value={academicYearId}
                        onChange={(e) => setAcademicYearId(e.target.value)}
                        className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                      >
                        <option value="">— Select year —</option>
                        {academicYears.map((year) => (
                          <option key={year.id} value={year.id}>
                            {year.name}
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="mb-1 block text-xs text-slate-500">Semester</label>
                      <select
                        value={semesterId}
                        onChange={(e) => setSemesterId(e.target.value)}
                        className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                      >
                        <option value="">— Select semester —</option>
                        {semesters?.map((sem) => (
                          <option key={sem.id} value={sem.id}>
                            {sem.name}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>
              )}

              {/* Step 4: Exam Event or Date */}
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div>
                  <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                    {isFullTime ? 'Exam Event (optional)' : 'Exam Event'}
                  </label>
                  <select
                    value={eventId}
                    onChange={(e) => {
                      setEventId(e.target.value)
                      if (e.target.value) setExamDate('')
                    }}
                    className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  >
                    <option value="">— Select event —</option>
                    {upcomingEvents.map((ev) => (
                      <option key={ev.id} value={ev.id}>
                        {ev.name} (
                        {new Date(ev.startDate).toLocaleDateString('en-GB', {
                          day: 'numeric',
                          month: 'short',
                          year: 'numeric',
                        })}
                        )
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                    {isFullTime ? 'Or Enter Date' : 'Or Enter Date'}
                  </label>
                  <input
                    type="date"
                    value={examDate}
                    onChange={(e) => {
                      setExamDate(e.target.value)
                      if (e.target.value) setEventId('')
                    }}
                    className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  />
                </div>
              </div>

              {/* Attempt Type (for resit) */}
              {bookingType === 'RESIT' && (
                <div>
                  <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                    Attempt Type
                  </label>
                  <select
                    value={attemptType}
                    onChange={(e) => setAttemptType(e.target.value)}
                    className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                  >
                    {ATTEMPT_TYPES.map((at) => (
                      <option key={at.value} value={at.value}>
                        {at.label}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Step 4: Payment Method */}
              <div>
                <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                  Payment Method
                </label>
                <div className="grid grid-cols-2 gap-2">
                  <button
                    onClick={() => setPaymentMethod('AUTO_DEBIT')}
                    className={`rounded-xl border p-3 text-left transition-all ${
                      paymentMethod === 'AUTO_DEBIT'
                        ? 'border-aerojet-blue bg-aerojet-blue/5 ring-1 ring-aerojet-blue'
                        : 'border-slate-200 hover:border-slate-300 dark:border-slate-700'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <Wallet className="h-4 w-4 text-aerojet-blue" />
                      <span className="text-sm font-bold text-slate-800 dark:text-slate-200">
                        Auto-Debit Wallet
                      </span>
                    </div>
                    <p className="mt-1 text-[10px] text-slate-400">
                      Debit €{price} from student wallet immediately
                    </p>
                    {!canAfford && (
                      <p className="mt-1 flex items-center gap-1 text-[10px] font-bold text-red-500">
                        <AlertCircle className="h-3 w-3" />
                        Insufficient balance
                      </p>
                    )}
                  </button>
                  <button
                    onClick={() => setPaymentMethod('MANUAL_LATER')}
                    className={`rounded-xl border p-3 text-left transition-all ${
                      paymentMethod === 'MANUAL_LATER'
                        ? 'border-aerojet-blue bg-aerojet-blue/5 ring-1 ring-aerojet-blue'
                        : 'border-slate-200 hover:border-slate-300 dark:border-slate-700'
                    }`}
                  >
                    <div className="text-sm font-bold text-slate-800 dark:text-slate-200">
                      Manual / Later
                    </div>
                    <p className="mt-1 text-[10px] text-slate-400">
                      Create booking as pending. Debit wallet manually later.
                    </p>
                  </button>
                </div>
              </div>

              {/* Notes */}
              <div>
                <label className="mb-2 block text-xs font-black tracking-widest text-slate-400 uppercase">
                  Notes (optional)
                </label>
                <textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Any notes about this booking..."
                  rows={2}
                  className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
                />
              </div>

              {/* Summary */}
              <div className="rounded-xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800/50">
                <h4 className="mb-2 text-xs font-black tracking-widest text-slate-400 uppercase">
                  Booking Summary
                </h4>
                <div className="space-y-1 text-sm">
                  <div className="flex justify-between">
                    <span className="text-slate-500">Type</span>
                    <span className="font-bold text-slate-800 dark:text-slate-200">
                      {selectedType.label}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-slate-500">Modules</span>
                    <span className="font-mono text-xs font-bold text-slate-800 dark:text-slate-200">
                      {selectedModules.length > 0
                        ? examComponents
                            .filter((c) => selectedModules.includes(c.id))
                            .map((c) => c.course?.code || c.code)
                            .join(', ')
                        : '—'}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-slate-500">Price</span>
                    <span className="text-lg font-black text-aerojet-blue">€{price}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-slate-500">Payment</span>
                    <span className="font-bold text-slate-800 dark:text-slate-200">
                      {paymentMethod === 'AUTO_DEBIT' ? 'Auto-debit wallet' : 'Manual / Later'}
                    </span>
                  </div>
                </div>
              </div>
            </div>

            {/* Footer */}
            <div className="sticky bottom-0 flex items-center justify-end gap-3 border-t border-slate-100 bg-white px-6 py-4 dark:border-slate-800 dark:bg-slate-900">
              <button
                onClick={() => {
                  setOpen(false)
                  resetForm()
                }}
                className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-bold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:bg-white hover:shadow-sm dark:border-slate-700 dark:hover:border-slate-600"
              >
                Cancel
              </button>
              <button
                onClick={handleSubmit}
                disabled={
                  loading ||
                  selectedModules.length !== selectedType.modules ||
                  (!eventId && !examDate) ||
                  (paymentMethod === 'AUTO_DEBIT' && !canAfford)
                }
                className="flex items-center gap-2 rounded-xl bg-aerojet-blue px-6 py-2 text-sm font-bold text-white transition-all hover:bg-[#001f45] disabled:cursor-not-allowed disabled:opacity-50"
              >
                {loading && <Loader2 className="h-4 w-4 animate-spin" />}
                {paymentMethod === 'AUTO_DEBIT'
                  ? `Book & Debit €${price}`
                  : 'Book (Pending Payment)'}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { naturalCompare } from '@/lib/utils/array'
import {
  Search,
  Plus,
  Calendar,
  CheckCircle2,
  XCircle,
  Clock,
  Edit,
  Trash2,
  FileCheck,
  ShoppingCart,
  Filter,
  ArrowUp,
  ArrowDown,
} from 'lucide-react'
import { toast } from 'sonner'
import { updateExamBooking, deleteExamRecord } from '@/app/staff/actions/index'
import BookExamForStudentDialog from './BookExamForStudentDialog'
import AddExamRecordDialog from './AddExamRecordDialog'
import CertificateReleaseControl from './CertificateReleaseControl'
import { deriveBookingDisplayResult } from '@/lib/exams/fulfillment'
import type {
  SerializedExamBooking,
  SerializedExamComponent,
  SerializedExamBundle,
} from '@/lib/types/staff'

const EXAM_FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'passed', label: 'Passed' },
  { key: 'failed', label: 'Failed' },
  { key: 'resit', label: 'Resits' },
  { key: 'internal', label: 'Internal' },
  { key: 'official', label: 'Official EASA' },
  { key: 'upcoming', label: 'Upcoming' },
  { key: 'completed', label: 'Completed' },
] as const

type ExamFilter = (typeof EXAM_FILTERS)[number]['key']

interface Props {
  student: any
  examComponents: any[]
  upcomingEvents: any[]
  academicYears?: { id: string; name: string }[]
  semesters?: { id: string; name: string }[]
  onRefresh: () => void
}

export default function ExamsTab({
  student,
  examComponents,
  upcomingEvents,
  academicYears,
  semesters,
  onRefresh,
}: Props) {
  const [filter, setFilter] = useState<ExamFilter>('all')
  const [search, setSearch] = useState('')
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editData, setEditData] = useState<{
    score?: number
    result?: string
    examDate?: string
    moduleCode?: string
    attemptType?: string
    bookingType?: string
    examCategory?: string
  }>({})
  const [quickAddModule, setQuickAddModule] = useState<SerializedExamComponent | null>(null)
  const [sortBy, setSortBy] = useState<'moduleCode' | 'examDate' | 'score' | 'result'>('examDate')
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc')

  // Merge exam bookings and exam results into unified history
  const allExamRecords = useMemo(() => {
    const records: any[] = []

    // From examBookings
    for (const b of student.examBookings || []) {
      records.push({
        id: b.id,
        source: 'booking',
        moduleCode: b.moduleCode || b.course?.code || b.exam?.examComponent?.course?.code || '—',
        examName:
          b.exam?.name || b.course?.name || b.exam?.examComponent?.course?.name || 'Manual Record',
        examDate: b.examDate,
        courseId: b.course?.id || null,
        score: b.score != null ? Number(b.score) : null,
        percentage: b.percentage != null ? Number(b.percentage) : null,
        result:
          b.result?.toUpperCase().includes('MIGRATE') ||
          b.result?.toUpperCase().includes('HISTORICAL')
            ? null
            : deriveBookingDisplayResult({
                result: b.result,
                demandStatus: b.demandStatus,
                executedAt: b.executedAt,
                rolloverToEventId: b.rolloverToEventId,
                status: b.status,
              }),
        passed: b.result?.toLowerCase() === 'pass',
        status:
          (b.result != null && b.result !== '' && !b.result.toUpperCase().includes('MIGRATE')) ||
          (b.score != null && b.examDate && new Date(b.examDate) < new Date())
            ? 'COMPLETED'
            : b.status,
        bookingType: b.bookingType,
        attemptType:
          b.attemptType?.toUpperCase().includes('MIGRATE') ||
          b.attemptType?.toUpperCase().includes('HISTORICAL')
            ? null
            : b.attemptType,
        isResit: b.isResit || (b.attemptType?.toUpperCase().startsWith('RESIT') ?? false),
        eventName: b.event?.name,
        bookedAt: b.bookedAt,
        amountPaid: Number(b.amountPaid || 0),
        examCategory: b.examCategory,
        attendanceStatus:
          b.examAttendance?.status || b.sittingAssignments?.[0]?.attendanceStatus || null,
        sittingLabel: b.sittingAssignments?.[0]?.sitting
          ? `Day ${b.sittingAssignments[0].sitting.dayNumber} ${b.sittingAssignments[0].sitting.sessionType}`
          : null,
      })
    }

    // From examResults (formal results)
    for (const r of student.examResults || []) {
      const rModuleCode = r.moduleCode || r.exam?.examComponent?.course?.code || '—'
      const existingBooking = records.find(
        (rec) =>
          rec.source === 'booking' &&
          rec.moduleCode?.toUpperCase() === rModuleCode.toUpperCase() &&
          (rec.attemptType || 'FIRST') === (r.attemptType || 'FIRST')
      )

      if (existingBooking) {
        // Consolidate: Merge the score from ExamResult into the booking
        existingBooking.score = Number(r.score)
        existingBooking.percentage = Number(r.percentage)
        existingBooking.passed = r.passed
        existingBooking.result = r.passed ? 'pass' : 'fail'
        existingBooking.status = 'COMPLETED'
        existingBooking.hasResult = true
        existingBooking.resultId = r.id
        existingBooking.sourceNotes = r.sourceNotes
        existingBooking.examCategory = r.examCategory || existingBooking.examCategory
        // Treat "migrated" or "historical" results as pending for UI display purposes
        if (
          existingBooking.result?.toUpperCase().includes('MIGRATE') ||
          existingBooking.result?.toUpperCase().includes('HISTORICAL')
        ) {
          existingBooking.result = null
        }

        const rType = r.attemptType?.toUpperCase() || ''
        const bType = existingBooking.attemptType?.toUpperCase() || ''

        const isPlaceholder = (s: string) =>
          s.includes('MIGRATE') || s.includes('HISTORICAL') || s === '—'

        if (rType && !isPlaceholder(rType)) {
          existingBooking.attemptType = r.attemptType
          existingBooking.isResit = r.attemptType.startsWith('RESIT')
        } else if (!bType || isPlaceholder(bType)) {
          if (rType && !isPlaceholder(rType)) {
            existingBooking.attemptType = r.attemptType
            existingBooking.isResit = r.attemptType.startsWith('RESIT')
          } else if (r.attemptType) {
            // Fallback to result's attempt type even if it's a placeholder,
            // but only if booking has nothing better
            existingBooking.attemptType = r.attemptType
          }
        }
      } else {
        records.push({
          id: `result_${r.id}`,
          source: 'result',
          moduleCode: rModuleCode,
          examName: r.exam?.name || 'Manual Result',
          examDate: r.exam?.examDate || r.createdAt,
          score: Number(r.score),
          percentage: Number(r.percentage),
          result: r.passed ? 'pass' : 'fail',
          passed: r.passed,
          status: 'COMPLETED',
          bookingType: null,
          attemptType:
            r.attemptType?.toUpperCase().includes('MIGRATE') ||
            r.attemptType?.toUpperCase().includes('HISTORICAL')
              ? null
              : r.attemptType,
          isResit: r.attemptType ? r.attemptType.toUpperCase().startsWith('RESIT') : false,
          eventName: null,
          sourceNotes: r.sourceNotes,
          bookedAt: r.createdAt,
          certificateUrl: r.certificateUrl,
          amountPaid: 0,
          examCategory: r.examCategory,
          attendanceStatus: null,
        })
      }
    }

    // Sort by date descending
    records.sort((a, b) => {
      const da = a.examDate ? new Date(a.examDate).getTime() : 0
      const db = b.examDate ? new Date(b.examDate).getTime() : 0
      return db - da
    })

    return records
  }, [student.examBookings, student.examResults])

  // Apply filters
  const filteredRecords = useMemo(() => {
    let filtered = allExamRecords

    if (filter === 'passed') {
      filtered = filtered.filter((r) => r.passed || r.result?.toLowerCase() === 'pass')
    } else if (filter === 'failed') {
      filtered = filtered.filter((r) => !r.passed && r.result?.toLowerCase() === 'fail')
    } else if (filter === 'resit') {
      filtered = filtered.filter(
        (r) => r.isResit || ['RESIT_1', 'RESIT_2', 'RESIT_3'].includes(r.attemptType || '')
      )
    } else if (filter === 'upcoming') {
      filtered = filtered.filter(
        (r) => r.examDate && new Date(r.examDate) > new Date() && r.status !== 'COMPLETED'
      )
    } else if (filter === 'completed') {
      filtered = filtered.filter((r) => r.status === 'COMPLETED')
    } else if (filter === 'internal') {
      filtered = filtered.filter((r) => r.examCategory === 'INTERNAL')
    } else if (filter === 'official') {
      filtered = filtered.filter((r) => r.examCategory === 'OFFICIAL_EASA' || !r.examCategory)
    }

    if (search) {
      const q = search.toLowerCase()
      filtered = filtered.filter(
        (r) => r.moduleCode?.toLowerCase().includes(q) || r.examName?.toLowerCase().includes(q)
      )
    }

    // Apply sorting with natural sort for module codes
    const sorted = [...filtered].sort((a, b) => {
      let cmp = 0
      if (sortBy === 'moduleCode') {
        cmp = naturalCompare(a.moduleCode || '', b.moduleCode || '')
      } else if (sortBy === 'examDate') {
        const dateA = a.examDate ? new Date(a.examDate).getTime() : 0
        const dateB = b.examDate ? new Date(b.examDate).getTime() : 0
        cmp = dateA - dateB
      } else if (sortBy === 'score') {
        cmp = (a.score ?? -1) - (b.score ?? -1)
      } else if (sortBy === 'result') {
        cmp = (a.result || '').localeCompare(b.result || '')
      }
      return sortOrder === 'asc' ? cmp : -cmp
    })

    return sorted
  }, [allExamRecords, filter, search, sortBy, sortOrder])

  // Filter counts
  const counts = useMemo(
    () => ({
      all: allExamRecords.length,
      passed: allExamRecords.filter((r) => r.passed || r.result?.toLowerCase() === 'pass').length,
      failed: allExamRecords.filter((r) => !r.passed && r.result?.toLowerCase() === 'fail').length,
      resit: allExamRecords.filter(
        (r) => r.isResit || ['RESIT_1', 'RESIT_2', 'RESIT_3'].includes(r.attemptType || '')
      ).length,
      upcoming: allExamRecords.filter(
        (r) => r.examDate && new Date(r.examDate) > new Date() && r.status !== 'COMPLETED'
      ).length,
      completed: allExamRecords.filter((r) => r.status === 'COMPLETED').length,
      internal: allExamRecords.filter((r) => r.examCategory === 'INTERNAL').length,
      official: allExamRecords.filter((r) => r.examCategory === 'OFFICIAL_EASA' || !r.examCategory)
        .length,
    }),
    [allExamRecords]
  )

  // Handle inline edit save
  const handleSaveEdit = async (record: SerializedExamBooking) => {
    try {
      const res = await updateExamBooking(record.id, {
        score: editData.score,
        result: editData.result,
        examDate: editData.examDate ? new Date(editData.examDate) : undefined,
        moduleCode: editData.moduleCode || undefined,
        attemptType: editData.attemptType || undefined,
        bookingType: editData.bookingType || undefined,
        examCategory:
          (editData.examCategory as 'INTERNAL' | 'OFFICIAL_EASA' | undefined) || undefined,
        resultIdToSync: (record as { resultId?: string }).resultId || undefined,
      })
      if ('error' in res && res.error) {
        toast.error(res.error)
      } else {
        toast.success('Exam record updated')
        setEditingId(null)
        onRefresh()
      }
    } catch {
      toast.error('Failed to update record')
    }
  }

  // Handle delete
  const handleDelete = async (recordId: string) => {
    if (!confirm('Are you sure you want to delete this exam record?')) return
    try {
      const res = await deleteExamRecord(recordId)
      if ('error' in res && res.error) {
        toast.error(res.error)
      } else {
        toast.success('Exam record deleted')
        onRefresh()
      }
    } catch {
      toast.error('Failed to delete record')
    }
  }

  // Quick add handlers
  const handleQuickAdd = (module: SerializedExamComponent) => {
    setQuickAddModule(module)
  }

  // Handle column header click for sorting
  const handleSort = (column: 'moduleCode' | 'examDate' | 'score' | 'result') => {
    if (sortBy === column) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')
    } else {
      setSortBy(column)
      setSortOrder('asc')
    }
  }

  const handleQuickAddSave = async () => {
    if (!quickAddModule) return

    const moduleCode = quickAddModule.course?.code || quickAddModule.code
    const courseId = quickAddModule.course?.id

    try {
      const res = await fetch('/api/staff/students/' + student.id + '/exam-record', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          entries: [
            {
              courseId,
              moduleCode,
              score: undefined,
            },
          ],
          bookingType: 'INDIVIDUAL',
          examDate: undefined, // Leave date blank for admin to fill
          attemptType: 'FIRST',
          notes: 'Quick added from exam tab',
        }),
      })

      const data = await res.json()
      if (res.ok && data.success) {
        toast.success('Module added! Click edit to add exam date and score.')
        setQuickAddModule(null)
        onRefresh()
      } else {
        toast.error(data.error || 'Failed to add module')
      }
    } catch {
      toast.error('Failed to add module')
    }
  }

  const walletBalance = Number(student.wallet?.availableBalance ?? 0)

  // Build a map of moduleCode → courseId from examComponents for linking
  const courseLookup = useMemo(() => {
    const map = new Map<string, string>()
    for (const ec of examComponents) {
      if (ec.course?.code && ec.course?.id) {
        map.set(ec.course.code.toUpperCase(), ec.course.id)
      }
    }
    return map
  }, [examComponents])

  // Get list of modules that already have records
  const existingModuleCodes = new Set(allExamRecords.map((r) => r.moduleCode).filter(Boolean))

  // Available modules to add (not yet in records)
  const availableModules = examComponents.filter(
    (m) => !existingModuleCodes.has(m.course?.code || m.code)
  )

  return (
    <div className="space-y-6">
      <CertificateReleaseControl
        studentId={student.id}
        fundingSource={student.studentProfile?.fundingSource}
        pathwayCode={student.studentProfile?.pathwayRel?.code}
        initialCertificatesReleased={student.studentProfile?.certificatesReleased ?? false}
        initialDocumentsReleased={student.studentProfile?.documentsReleased ?? false}
      />

      {/* Header Actions */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <h3 className="text-xs font-black tracking-widest text-slate-400 uppercase">
            Exam Records ({allExamRecords.length})
          </h3>
        </div>
        <div className="flex items-center gap-2">
          <AddExamRecordDialog
            studentId={student.id}
            studentName={
              student.profile
                ? `${student.profile.firstName} ${student.profile.lastName}`
                : student.email
            }
            examComponents={examComponents}
            onSuccess={onRefresh}
          />
          <BookExamForStudentDialog
            studentId={student.id}
            studentName={
              student.profile
                ? `${student.profile.firstName} ${student.profile.lastName}`
                : student.email
            }
            walletBalance={walletBalance}
            walletCurrency={student.wallet?.currency || 'EUR'}
            enrollmentType={student.studentProfile?.enrollmentType}
            academicYears={academicYears}
            semesters={semesters}
            examComponents={examComponents}
            upcomingEvents={upcomingEvents}
            onSuccess={onRefresh}
          />
        </div>
      </div>

      {/* Quick Add Available Modules */}
      {availableModules.length > 0 && (
        <div className="rounded-xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800/50">
          <h4 className="mb-3 text-xs font-black tracking-widest text-slate-400 uppercase">
            Quick Add: Available Modules
          </h4>
          <div className="flex flex-wrap gap-2">
            {availableModules.slice(0, 12).map((module) => (
              <button
                key={module.id}
                onClick={() => handleQuickAdd(module)}
                className="hover:border-aerojet-blue hover:text-aerojet-blue flex items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-600 transition-all dark:border-slate-600 dark:bg-slate-700"
              >
                <Plus className="h-3 w-3" />
                {module.course?.code || module.code}
              </button>
            ))}
            {availableModules.length > 12 && (
              <span className="px-3 py-1.5 text-xs text-slate-400">
                +{availableModules.length - 12} more
              </span>
            )}
          </div>
        </div>
      )}

      {/* Quick Add Dialog */}
      {quickAddModule && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl dark:bg-slate-900">
            <h3 className="mb-4 text-lg font-bold">
              Add {quickAddModule.course?.code || quickAddModule.code}
            </h3>
            <p className="mb-4 text-sm text-slate-500">Module: {quickAddModule.name}</p>
            <p className="mb-4 text-xs text-amber-600">
              You can add the exam date and score later by editing this record.
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setQuickAddModule(null)}
                className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600"
              >
                Cancel
              </button>
              <button
                onClick={handleQuickAddSave}
                className="bg-aerojet-blue rounded-lg px-4 py-2 text-sm font-medium text-white"
              >
                Add Module
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Search & Filters */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="relative max-w-xs min-w-[200px] flex-1">
          <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search module or exam..."
            className="focus:ring-aerojet-sky w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pr-4 pl-9 text-sm outline-none focus:ring-2 dark:border-slate-700 dark:bg-slate-800/50"
          />
        </div>
        <div className="flex flex-wrap items-center gap-1.5">
          {EXAM_FILTERS.map((f) => (
            <button
              key={f.key}
              onClick={() => setFilter(f.key)}
              className={`rounded-full border px-3 py-1 text-xs font-bold whitespace-nowrap transition-all ${
                filter === f.key
                  ? 'border-aerojet-blue bg-aerojet-blue text-white'
                  : 'border-slate-200 bg-white text-slate-500 hover:border-slate-300 dark:border-slate-700 dark:bg-slate-800'
              }`}
            >
              {f.label}
              <span className="ml-1 opacity-60">({counts[f.key]})</span>
            </button>
          ))}
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <SummaryCard
          icon={CheckCircle2}
          label="Passed"
          value={counts.passed}
          color="text-emerald-600"
          bg="bg-emerald-50 dark:bg-emerald-900/20"
        />
        <SummaryCard
          icon={XCircle}
          label="Failed"
          value={counts.failed}
          color="text-red-600"
          bg="bg-red-50 dark:bg-red-900/20"
        />
        <SummaryCard
          icon={Clock}
          label="Upcoming"
          value={counts.upcoming}
          color="text-blue-600"
          bg="bg-blue-50 dark:bg-blue-900/20"
        />
        <SummaryCard
          icon={FileCheck}
          label="Total Records"
          value={counts.all}
          color="text-slate-600"
          bg="bg-slate-50 dark:bg-slate-800"
        />
      </div>

      {/* Exam Records Table */}
      {filteredRecords.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 text-center">
          <FileCheck className="mb-2 h-10 w-10 text-slate-200" />
          <p className="text-sm font-bold text-slate-400">
            {filter === 'all' ? 'No exam records yet' : `No ${filter} exam records`}
          </p>
        </div>
      ) : (
        <div className="overflow-x-auto rounded-xl border border-slate-100 dark:border-slate-800">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-slate-100 bg-slate-50/80 dark:border-slate-800 dark:bg-slate-900/50">
                <th
                  className="hover:text-aerojet-blue cursor-pointer px-4 py-3 text-left text-[10px] font-black tracking-widest text-slate-400 uppercase"
                  onClick={() => handleSort('moduleCode')}
                >
                  <span className="flex items-center gap-1">
                    Module
                    {sortBy === 'moduleCode' &&
                      (sortOrder === 'asc' ? (
                        <ArrowUp className="h-3 w-3" />
                      ) : (
                        <ArrowDown className="h-3 w-3" />
                      ))}
                  </span>
                </th>
                <th className="px-4 py-3 text-left text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Exam / Event
                </th>
                <th className="px-4 py-3 text-center text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Category
                </th>
                <th className="px-4 py-3 text-center text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Attempt
                </th>
                <th
                  className="hover:text-aerojet-blue cursor-pointer px-4 py-3 text-left text-[10px] font-black tracking-widest text-slate-400 uppercase"
                  onClick={() => handleSort('examDate')}
                >
                  <span className="flex items-center gap-1">
                    Date
                    {sortBy === 'examDate' &&
                      (sortOrder === 'asc' ? (
                        <ArrowUp className="h-3 w-3" />
                      ) : (
                        <ArrowDown className="h-3 w-3" />
                      ))}
                  </span>
                </th>
                <th
                  className="hover:text-aerojet-blue cursor-pointer px-4 py-3 text-center text-[10px] font-black tracking-widest text-slate-400 uppercase"
                  onClick={() => handleSort('score')}
                >
                  <span className="flex items-center justify-center gap-1">
                    Score
                    {sortBy === 'score' &&
                      (sortOrder === 'asc' ? (
                        <ArrowUp className="h-3 w-3" />
                      ) : (
                        <ArrowDown className="h-3 w-3" />
                      ))}
                  </span>
                </th>
                <th
                  className="hover:text-aerojet-blue cursor-pointer px-4 py-3 text-center text-[10px] font-black tracking-widest text-slate-400 uppercase"
                  onClick={() => handleSort('result')}
                >
                  <span className="flex items-center justify-center gap-1">
                    Result
                    {sortBy === 'result' &&
                      (sortOrder === 'asc' ? (
                        <ArrowUp className="h-3 w-3" />
                      ) : (
                        <ArrowDown className="h-3 w-3" />
                      ))}
                  </span>
                </th>
                <th className="px-4 py-3 text-center text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Booking
                </th>
                <th className="px-4 py-3 text-center text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Status
                </th>
                <th className="px-4 py-3 text-right text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
              {filteredRecords.map((record) => (
                <tr
                  key={record.id}
                  className="transition-all duration-150 ease-out hover:bg-white/80 dark:hover:bg-slate-800/40"
                >
                  <td className="px-4 py-3">
                    {editingId === record.id ? (
                      <select
                        value={editData.moduleCode ?? record.moduleCode}
                        onChange={(e) => setEditData((d) => ({ ...d, moduleCode: e.target.value }))}
                        className="w-28 rounded border border-slate-200 px-2 py-1 font-mono text-xs"
                      >
                        {examComponents.map((ec: SerializedExamComponent) => (
                          <option key={ec.id} value={ec.course?.code || ec.code}>
                            {ec.course?.code || ec.code}
                          </option>
                        ))}
                      </select>
                    ) : (
                      (() => {
                        const cid =
                          record.courseId ||
                          courseLookup.get(record.moduleCode?.toUpperCase() || '')
                        return cid ? (
                          <a
                            href={`/staff/courses/${cid}`}
                            className="text-aerojet-blue dark:text-aerojet-sky font-mono font-bold hover:underline"
                          >
                            {record.moduleCode}
                          </a>
                        ) : (
                          <span className="font-mono font-bold text-slate-800 dark:text-slate-200">
                            {record.moduleCode}
                          </span>
                        )
                      })()
                    )}
                  </td>
                  <td className="max-w-[200px] px-4 py-3 text-xs text-slate-500">
                    <div className="flex flex-col">
                      <span className="truncate font-medium text-slate-800 dark:text-slate-200">
                        {record.examName}
                      </span>
                      {record.eventName && (
                        <span className="text-[10px] text-slate-400">
                          Event: {record.eventName}
                        </span>
                      )}
                      {record.sittingLabel && (
                        <span className="text-[10px] text-slate-400">
                          Sitting: {record.sittingLabel}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-3 text-center">
                    {editingId === record.id ? (
                      <select
                        value={editData.examCategory ?? record.examCategory ?? 'OFFICIAL_EASA'}
                        onChange={(e) =>
                          setEditData((d) => ({
                            ...d,
                            examCategory: e.target.value as 'INTERNAL' | 'OFFICIAL_EASA',
                          }))
                        }
                        className="w-24 rounded border border-slate-200 px-1 py-0.5 text-[10px]"
                      >
                        <option value="OFFICIAL_EASA">OFFICIAL EASA</option>
                        <option value="INTERNAL">INTERNAL</option>
                      </select>
                    ) : (
                      <span
                        className={`inline-flex rounded-full px-2 py-0.5 text-[9px] font-bold ${
                          record.examCategory === 'INTERNAL'
                            ? 'bg-amber-100 text-amber-700'
                            : 'bg-blue-100 text-blue-700'
                        }`}
                      >
                        {record.examCategory === 'INTERNAL' ? 'INTERNAL' : 'OFFICIAL EASA'}
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-center">
                    {editingId === record.id ? (
                      <select
                        value={editData.attemptType ?? record.attemptType ?? 'FIRST'}
                        onChange={(e) =>
                          setEditData((d) => ({ ...d, attemptType: e.target.value }))
                        }
                        className="w-28 rounded border border-slate-200 px-2 py-1 text-xs"
                      >
                        <option value="FIRST">First Attempt</option>
                        <option value="RESIT_1">Resit 1</option>
                        <option value="RESIT_2">Resit 2</option>
                        <option value="RESIT_3">Resit 3</option>
                      </select>
                    ) : (
                      <span
                        className={`inline-flex rounded-full px-2 py-0.5 text-[10px] font-bold ${
