                                      : latestExam.result?.toLowerCase() === 'fail'
                                        ? 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400'
                                        : ['booked', 'scheduled', 'attended'].includes(latestExam.result?.toLowerCase() || '')
                                          ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
                                          : 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400'
                                  }`}>
                                    {latestExam.result?.toUpperCase() || 'PENDING'}
                                  </span>
                                ) : (
                                  <span className="text-xs italic text-slate-400">No exam record</span>
                                )}
                              </td>
                              <td className="px-4 py-2 font-mono text-xs text-slate-600 dark:text-slate-300">
                                {latestExam?.percentage != null ? `${latestExam.percentage}%` : '—'}
                              </td>
                              <td className="px-4 py-2 text-xs text-slate-500">
                                {latestExam?.attemptType?.replace('_', ' ') || '—'}
                              </td>
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}

      {/* Standalone Exams */}
      {unmatchedExams.length > 0 && (
        <div className="mt-6">
          <h3 className="mb-3 flex items-center gap-2 text-xs font-black tracking-widest text-slate-400 uppercase dark:text-slate-500">
            <BookOpen className="h-4 w-4" /> Standalone Exams
          </h3>
          <div className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/50">
            <p className="mb-4 text-xs text-slate-500 dark:text-slate-400">
              The following exams were taken independently or transferred, and are not linked to a specific semester enrollment.
            </p>
            <div className="flex flex-wrap gap-2">
              {unmatchedExams.map((exam) => {
                const isPass = exam.result?.toLowerCase() === 'pass'
                const isFail = exam.result?.toLowerCase() === 'fail'
                const statusColor = isPass
                  ? 'border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900/50 dark:bg-emerald-900/20 dark:text-emerald-400'
                  : isFail
                  ? 'border-red-200 bg-red-50 text-red-700 dark:border-red-900/50 dark:bg-red-900/20 dark:text-red-400'
                  : 'border-slate-200 bg-slate-50 text-slate-600 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300'

                return (
                  <span
                    key={exam.id}
                    className={`rounded-full border px-3 py-1 text-xs font-bold ${statusColor}`}
                  >
                    <span className="font-mono">{exam.moduleCode}</span>
                    <span className="mx-1.5 opacity-50">•</span>
                    <span className="uppercase">{exam.result || 'Pending'}</span>
                  </span>
                )
              })}
            </div>
          </div>
        </div>
      )}

      {/* Quick Actions */}
      <div className="mt-4 flex flex-wrap gap-2">
        <AddExamRecordDialog
          studentId={studentId}
          studentName={studentName}
          examComponents={examComponents}
          onSuccess={() => router.refresh()}
        />
        <Link
          href="/staff/enrollments/batch"
          className="inline-flex items-center gap-1 rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition-all duration-150 ease-out hover:border-slate-300 hover:bg-white hover:shadow-sm dark:border-slate-700 dark:text-slate-400 dark:hover:border-slate-600 dark:hover:bg-slate-800/60"
        >
          <BookOpen className="h-3 w-3" /> Batch Enroll
        </Link>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { ShieldAlert, Loader2, ChevronRight, AlertTriangle, CheckCircle2, Mail, Database } from 'lucide-react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

interface ChangeRoleDialogProps {
  userId: string
  currentRole: string
  userName: string
  open: boolean
  onOpenChange: (open: boolean) => void
}

interface PreviewSideEffect {
  kind: string
  description: string
}

interface PreviewResponse {
  currentRole: string
  newRole: string
  userEmail: string
  userName: string
  sideEffects: PreviewSideEffect[]
  sendsEmail: boolean
  warnings: string[]
}

type Step = 'select' | 'preview' | 'confirm'

const SIDE_EFFECT_ICON: Record<string, React.ComponentType<any>> = {
  CREATE_INSTRUCTOR_PROFILE: Database,
  CREATE_STAFF_PROFILE: Database,
  CREATE_STUDENT_PROFILE: Database,
  CREATE_WALLET: Database,
  SEND_EMAIL: Mail,
  AUDIT_LOG: CheckCircle2,
}

export default function ChangeRoleDialog({
  userId,
  currentRole,
  userName,
  open,
  onOpenChange,
}: ChangeRoleDialogProps) {
  const [step, setStep] = useState<Step>('select')
  const [loading, setLoading] = useState(false)
  const [newRole, setNewRole] = useState(currentRole)
  const [preview, setPreview] = useState<PreviewResponse | null>(null)
  const [confirmName, setConfirmName] = useState('')
  const router = useRouter()

  const reset = () => {
    setStep('select')
    setPreview(null)
    setConfirmName('')
    setNewRole(currentRole)
  }

  const close = () => {
    onOpenChange(false)
    // Reset after dialog close animation
    setTimeout(reset, 300)
  }

  const onLoadPreview = async () => {
    if (newRole === currentRole) {
      toast.info('Role unchanged.')
      return
    }
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/users/${userId}/role/preview`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: newRole }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error || 'Preview failed')
      setPreview(json.data ?? json)
      setStep('preview')
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setLoading(false)
    }
  }

  const onCommit = async () => {
    if (confirmName.trim() !== userName.trim()) {
      toast.error('Typed name must match exactly to confirm.')
      return
    }
    setLoading(true)
    try {
      const res = await fetch(`/api/staff/users/${userId}/role`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: newRole }),
      })
      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to update role')
      }
      toast.success(`Role updated to ${newRole} for ${userName}`)
      close()
      router.refresh()
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={(v) => (v ? onOpenChange(true) : close())}>
      <DialogContent className="sm:max-w-[520px]">
        <DialogHeader>
          <DialogTitle>Change User Role</DialogTitle>
          <DialogDescription className="sr-only">3-step wizard: select role, preview side effects, confirm.</DialogDescription>
        </DialogHeader>

        {/* Step indicator */}
        <div className="flex items-center justify-center gap-2 text-xs font-bold">
          {(['select', 'preview', 'confirm'] as Step[]).map((s, i) => (
            <div key={s} className="flex items-center gap-2">
              <span className={`flex h-6 w-6 items-center justify-center rounded-full ${step === s ? 'bg-aerojet-blue text-white' : ['select', 'preview', 'confirm'].indexOf(step) > i ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-500'}`}>{i + 1}</span>
              <span className={step === s ? 'text-slate-900 dark:text-slate-100' : 'text-slate-400'}>{s[0].toUpperCase() + s.slice(1)}</span>
              {i < 2 && <ChevronRight className="h-3 w-3 text-slate-300" />}
            </div>
          ))}
        </div>

        {step === 'select' && (
          <div className="grid gap-6 py-4">
            <div className="flex items-center gap-4 rounded-xl bg-amber-50 p-4 text-amber-800 dark:bg-amber-900/20 dark:text-amber-400">
              <ShieldAlert className="h-5 w-5 shrink-0" />
              <div className="text-xs font-medium">
                Pick the target role for <strong>{userName}</strong>. Next step shows exactly what will change.
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="role">New Role</Label>
              <Select value={newRole} onValueChange={setNewRole} name="role" autoComplete="off">
                <SelectTrigger id="role" className="w-full">
                  <SelectValue placeholder="Select a role" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="STUDENT">Student</SelectItem>
                  <SelectItem value="APPLICANT">Applicant</SelectItem>
                  <SelectItem value="EXAMINER">Examiner</SelectItem>
                  <SelectItem value="INSTRUCTOR">Instructor</SelectItem>
                  <SelectItem value="STAFF">Staff</SelectItem>
                  <SelectItem value="ADMIN">Admin</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        )}

        {step === 'preview' && preview && (
          <div className="grid gap-3 py-4">
            <div className="rounded-xl bg-slate-50 p-3 text-sm dark:bg-slate-800/40">
              <p className="font-bold text-slate-700 dark:text-slate-200">{preview.currentRole} → {preview.newRole}</p>
            </div>
            <div>
              <p className="mb-2 text-[10px] font-black tracking-widest text-slate-400 uppercase">Side effects ({preview.sideEffects.length})</p>
              <ul className="space-y-1.5">
                {preview.sideEffects.map((s, i) => {
                  const Icon = SIDE_EFFECT_ICON[s.kind] ?? Database
                  return (
                    <li key={i} className="flex items-start gap-2 text-xs">
                      <Icon className="mt-0.5 h-3.5 w-3.5 shrink-0 text-aerojet-blue" />
                      <span className="text-slate-700 dark:text-slate-300">{s.description}</span>
                    </li>
                  )
                })}
              </ul>
            </div>
            {preview.warnings.length > 0 && (
              <div className="rounded-xl bg-amber-50 p-3 text-xs text-amber-800 dark:bg-amber-900/20 dark:text-amber-400">
                <p className="mb-1 flex items-center gap-1 font-bold"><AlertTriangle className="h-3 w-3" /> Warnings</p>
                <ul className="ml-4 list-disc space-y-0.5">
                  {preview.warnings.map((w, i) => <li key={i}>{w}</li>)}
                </ul>
              </div>
            )}
          </div>
        )}

        {step === 'confirm' && (
          <div className="grid gap-3 py-4">
            <p className="text-sm text-slate-700 dark:text-slate-200">
              Type the user's name <strong>exactly</strong> to commit the role change:
            </p>
            <code className="rounded bg-slate-100 px-2 py-1 text-sm dark:bg-slate-800">{userName}</code>
            <input
              value={confirmName}
              onChange={(e) => setConfirmName(e.target.value)}
              placeholder="Type the name here"
              className="rounded-lg border border-slate-200 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
            />
            <a href="/docs/html/role-transitions.html" target="_blank" className="text-xs text-aerojet-blue hover:underline">What does this change exactly?</a>
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={close} disabled={loading}>Cancel</Button>
          {step === 'select' && (
            <Button onClick={onLoadPreview} disabled={loading || newRole === currentRole} className="bg-aerojet-blue">
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Preview changes
            </Button>
          )}
          {step === 'preview' && (
            <>
              <Button variant="outline" onClick={() => setStep('select')}>Back</Button>
              <Button onClick={() => setStep('confirm')} className="bg-aerojet-blue">Continue</Button>
            </>
          )}
          {step === 'confirm' && (
            <>
              <Button variant="outline" onClick={() => setStep('preview')}>Back</Button>
              <Button onClick={onCommit} disabled={loading || confirmName.trim() !== userName.trim()} className="bg-red-600 hover:bg-red-700">
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Commit role change
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { Edit2, Loader2, GraduationCap } from 'lucide-react'

interface AcademicYear {
  id: string
  name: string
  semesters: { id: string; name: string }[]
}

export default function EditAcademicPeriodDialog({
  userId,
  currentAcademicYearId,
  currentAcademicYearName,
  currentSemesterId,
  currentSemesterName,
}: {
  userId: string
  currentAcademicYearId?: string | null
  currentAcademicYearName?: string | null
  currentSemesterId?: string | null
  currentSemesterName?: string | null
}) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [academicYearId, setAcademicYearId] = useState(currentAcademicYearId || '')
  const [semesterId, setSemesterId] = useState(currentSemesterId || '')
  const [error, setError] = useState<string | null>(null)

  // Fetched data
  const [academicYears, setAcademicYears] = useState<AcademicYear[]>([])
  const [loadingYears, setLoadingYears] = useState(false)

  // Fetch active academic years when dialog opens
  useEffect(() => {
    if (open) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
      setLoadingYears(true)
      fetch('/api/staff/academic-years')
        .then((res) => res.json())
        .then((data) => {
          setAcademicYears(Array.isArray(data) ? data : data.academicYears || [])
        })
        .catch(() => setAcademicYears([]))
        .finally(() => setLoadingYears(false))
    }
  }, [open])

  // Get semesters for the selected academic year
  const selectedYear = academicYears.find((y) => y.id === academicYearId)
  const semesters = selectedYear?.semesters || []

  // Reset semester when academic year changes
  const handleYearChange = (yearId: string) => {
    setAcademicYearId(yearId)
    setSemesterId('') // Always reset semester when year changes
    setError(null)
  }

  // Clear both if academic year is cleared
  const handleClearYear = () => {
    setAcademicYearId('')
    setSemesterId('')
    setError(null)
  }

  const hasChanges =
    academicYearId !== (currentAcademicYearId || '') || semesterId !== (currentSemesterId || '')

  const handleSave = async () => {
    // Validate: can't have semester without academic year
    if (semesterId && !academicYearId) {
      setError('You must select an academic year before choosing a semester.')
      return
    }

    setIsSubmitting(true)
    setError(null)
    try {
      const res = await fetch(`/api/staff/students/${userId}/academic-period`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          academicYearId: academicYearId || null,
          semesterId: semesterId || null,
        }),
      })

      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to update academic period')
      }

      setOpen(false)
      router.refresh()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button className="ml-2 text-slate-400 hover:text-blue-500">
          <Edit2 className="h-4 w-4" />
        </button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[440px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <GraduationCap className="h-5 w-5 text-aerojet-sky" />
            Edit Academic Period
          </DialogTitle>
          <DialogDescription className="sr-only">
            Select the current academic year and semester for this student.
          </DialogDescription>
        </DialogHeader>

        <div className="mt-4 space-y-4">
          <p className="text-xs text-slate-500 dark:text-slate-400">
            Assign the student&apos;s current academic year and semester. Semester options update
            automatically based on the selected year.
          </p>

          {/* Academic Year */}
          <div className="space-y-2">
            <label htmlFor="academic-year-select" className="text-sm font-bold text-slate-700 dark:text-slate-300">
              Academic Year <span className="text-red-500">*</span>
            </label>
            {loadingYears ? (
              <div className="flex items-center gap-2 rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-400 dark:border-slate-700 dark:bg-slate-800">
                <Loader2 className="h-4 w-4 animate-spin" /> Loading academic years...
              </div>
            ) : academicYears.length === 0 ? (
              <div className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-700 dark:border-amber-800/50 dark:bg-amber-900/10 dark:text-amber-300">
                No active academic years found. Please create one in Academic Settings first.
              </div>
            ) : (
              <select
                id="academic-year-select"
                name="academicYearId"
                value={academicYearId}
                onChange={(e) =>
                  e.target.value ? handleYearChange(e.target.value) : handleClearYear()
                }
                className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm transition-colors focus:border-blue-500 focus:ring-1 focus:ring-blue-500 dark:border-slate-700 dark:bg-slate-800"
                autoComplete="off"
              >
                <option value="">â€” Select Academic Year â€”</option>
                {academicYears.map((year) => (
                  <option key={year.id} value={year.id}>
                    {year.name}
                  </option>
                ))}
              </select>
            )}
          </div>

          {/* Semester â€” only visible when academic year is selected */}
          <div
            className={`space-y-2 transition-all duration-200 ${
              academicYearId ? 'opacity-100' : 'pointer-events-none opacity-40'
            }`}
          >
            <label htmlFor="semester-select" className="text-sm font-bold text-slate-700 dark:text-slate-300">Semester</label>
            {semesters.length === 0 && academicYearId ? (
              <div className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-700 dark:border-amber-800/50 dark:bg-amber-900/10 dark:text-amber-300">
                No semesters found for this academic year.
              </div>
            ) : (
              <select
                id="semester-select"
                name="semesterId"
                value={semesterId}
                onChange={(e) => {
                  setSemesterId(e.target.value)
                  setError(null)
                }}
                disabled={!academicYearId}
                className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm transition-colors focus:border-blue-500 focus:ring-1 focus:ring-blue-500 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800"
                autoComplete="off"
              >
                <option value="">â€” Select Semester â€”</option>
                {semesters.map((sem) => (
                  <option key={sem.id} value={sem.id}>
                    {sem.name}
                  </option>
                ))}
              </select>
            )}
          </div>

          {/* Current Assignment Summary */}
          {(currentAcademicYearName || currentSemesterName) && (
            <div className="rounded-lg border border-slate-100 bg-slate-50 p-3 dark:border-slate-800 dark:bg-slate-800/40">
              <p className="mb-1 text-xs font-bold tracking-wider text-slate-400 uppercase">
                Current Assignment
              </p>
              <p className="text-sm font-medium text-slate-600 dark:text-slate-300">
                {currentAcademicYearName || 'None'}
                {currentSemesterName && ` â€” ${currentSemesterName}`}
              </p>
            </div>
          )}

          {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}
        </div>

        <div className="mt-4 flex justify-end gap-3">
          <Button variant="outline" onClick={() => setOpen(false)} disabled={isSubmitting}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isSubmitting || !hasChanges || !academicYearId}>
            {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Save Academic Period'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Pencil, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'

interface EditIdDialogProps {
  userId: string
  currentId: string
  type: 'studentId' | 'employeeId'
  label: string
}

export default function EditIdDialog({ userId, currentId, type, label }: EditIdDialogProps) {
  const [open, setOpen] = useState(false)
  const [value, setValue] = useState(currentId)
  const [loading, setLoading] = useState(false)
  const router = useRouter()

  const handleSave = async () => {
    if (!value || value === currentId) {
      setOpen(false)
      return
    }

    setLoading(true)
    try {
      const res = await fetch(`/api/staff/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ [type]: value }),
      })

      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to update ID')
      }

      toast.success(`${label} updated successfully`)
      setOpen(false)
      router.refresh()
    } catch (error: any) {
      toast.error(error.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button className="ml-2 rounded-full p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-blue-600">
          <Pencil className="h-4 w-4" />
        </button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Edit {label}</DialogTitle>
          <DialogDescription className="sr-only">
            Update the {label} for this user account.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid gap-2">
            <Label htmlFor="id-value">New {label}</Label>
            <Input
              id="id-value"
              name="id-value"
              value={value}
              onChange={(e) => setValue(e.target.value)}
              placeholder={`Enter new ${label}`}
              autoComplete="off"
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)} disabled={loading}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={loading}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Changes
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

