  try {
    const existing = await prisma.studentCalendarEvent.findUnique({
      where: { id: eventId },
    })

    if (!existing || existing.userId !== user.id) {
      return { error: 'Event not found or not authorized.' }
    }

    await prisma.studentCalendarEvent.update({
      where: { id: eventId },
      data: {
        ...(data.title !== undefined && { title: data.title.trim() }),
        ...(data.description !== undefined && { description: data.description.trim() || null }),
        ...(data.startDate && { startDate: new Date(data.startDate) }),
        ...(data.endDate !== undefined && {
          endDate: data.endDate ? new Date(data.endDate) : null,
        }),
        ...(data.color && { color: data.color }),
        ...(data.recurrenceType !== undefined && { recurrenceType: data.recurrenceType as any }),
        ...(data.recurrenceDays !== undefined && { recurrenceDays: data.recurrenceDays || null }),
        ...(data.recurrenceUntil !== undefined && {
          recurrenceUntil: data.recurrenceUntil ? new Date(data.recurrenceUntil) : null,
        }),
      },
    })

    revalidatePath('/student/academic-calendar')
    return { success: true }
  } catch (error) {
    console.error('Update Calendar Event Error:', error)
    return { error: 'Failed to update event.' }
  }
}

export async function deleteCalendarEvent(eventId: string) {
  const user = await requireStudent()

  try {
    const existing = await prisma.studentCalendarEvent.findUnique({
      where: { id: eventId },
    })

    if (!existing || existing.userId !== user.id) {
      return { error: 'Event not found or not authorized.' }
    }

    await prisma.studentCalendarEvent.delete({
      where: { id: eventId },
    })

    revalidatePath('/student/academic-calendar')
    return { success: true }
  } catch (error) {
    console.error('Delete Calendar Event Error:', error)
    return { error: 'Failed to delete event.' }
  }
}

'use client'

import { useState, useTransition } from 'react'
import { setReferrerAction } from '@/app/student/actions'
import { toast } from 'sonner'
import { Loader2, ArrowRight } from 'lucide-react'

export default function SetReferrerForm() {
  const [input, setInput] = useState('')
  const [isPending, startTransition] = useTransition()

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!input) {
      toast.error('Please enter an email or referral code.')
      return
    }

    startTransition(async () => {
      try {
        const res = await setReferrerAction(input)

        if (res?.error) {
          toast.error(res.error)
        } else {
          toast.success('Referrer set successfully!')
          setInput('')
        }
      } catch (err) {
        toast.error('Something went wrong. Please try again.')
      }
    })
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-3">
      <input
        type="text"
        placeholder="Email or Referral Code"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        disabled={isPending}
        required
        className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium outline-none transition-all focus:border-blue-800 focus:ring-4 focus:ring-blue-800/10 dark:border-slate-700 dark:bg-slate-800 dark:text-white"
      />
      <button
        type="submit"
        disabled={isPending || !input}
        className="flex items-center justify-center gap-2 rounded-xl bg-blue-800 py-3 text-sm font-bold text-white shadow-lg transition-all hover:bg-[#003a7c] active:scale-95 disabled:opacity-50"
      >
        {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Set Referrer'}
