import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Calendar, CheckCircle2, XCircle, Clock, AlertCircle } from 'lucide-react'

import { getAuthSession } from '@/lib/auth/helpers'
import prisma from '@/lib/prisma/client'
import {
  canAccessFeature,
  getEnrollmentMilestoneStatus,
  getStudentPaymentAccessLevel,
  getStudentStatus,
} from '@/lib/access-control'
import { PaymentRequiredBanner } from '../_components/PaymentRequiredBanner'
import AttendanceTable from './_components/AttendanceTable'

export const metadata: Metadata = {
  title: 'Attendance Registry | Student Portal',
  description: 'Track your class and exam attendance records.',
}

export default async function AttendancePage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const { isFullTime, isExamOnly, isModular } = await getStudentStatus(session.user.id)
  const hasAccess = await canAccessFeature(session.user.id, 'classes')

  if (isFullTime && !hasAccess) {
    const [milestoneStatus, wallet, accessLevel] = await Promise.all([
      getEnrollmentMilestoneStatus(session.user.id),
      prisma.wallet.findUnique({
        where: { userId: session.user.id },
        select: { availableBalance: true, reservedBalance: true, currency: true },
      }),
      getStudentPaymentAccessLevel(session.user.id),
    ])

    const walletBalance = {
      available: Number(wallet?.availableBalance ?? 0),
      held: Number(wallet?.reservedBalance ?? 0),
      currency: wallet?.currency ?? 'EUR',
    }

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div>
          <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white">
            Attendance Registry
          </h1>
          <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
            Track your class attendance and participation.
          </p>
        </div>

        <PaymentRequiredBanner
          accessLevel={accessLevel}
          milestoneStatus={milestoneStatus}
          walletBalance={walletBalance}
        />
      </div>
    )
  }

  const [classAttendance, examAttendance] = await Promise.all([
    prisma.attendanceRecord.findMany({
      where: { userId: session.user.id },
      include: {
        class: {
          include: { course: true },
        },
      },
      orderBy: { date: 'desc' },
      take: 200,
    }),
    prisma.examAttendance.findMany({
      where: { userId: session.user.id },
      include: {
        examComponent: { include: { course: true } },
        sitting: true,
      },
      orderBy: { attendanceDate: 'desc' },
      take: 100,
    }),
  ])

  // Merge and normalize records
  const allRecords = [
    ...classAttendance.map((r) => ({
      id: r.id,
      type: 'CLASS' as const,
      status: r.status,
      date: r.date.toISOString(),
      notes: r.notes,
      minutesLate: r.minutesLate,
      label: r.class.name,
      subLabel: r.class.course.code,
    })),
    ...examAttendance.map((r) => ({
      id: `exam_${r.id}`,
      type: 'EXAM' as const,
      status: r.status,
      date: r.attendanceDate.toISOString(),
      notes: r.notes,
      minutesLate: null,
      label: r.examComponent?.course?.name || r.examComponent?.code || 'Official Exam',
      subLabel: r.examComponent?.course?.code || 'EXAM',
    })),
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())

  const stats = {
    total: allRecords.length,
    present: allRecords.filter((r) => r.status === 'PRESENT').length,
    late: allRecords.filter((r) => r.status === 'LATE').length,
    absent: allRecords.filter((r) => r.status === 'ABSENT').length,
    excused: allRecords.filter((r) => r.status === 'EXCUSED').length,
  }

  const attendanceRate =
    stats.total > 0 ? Math.round(((stats.present + stats.late) / stats.total) * 100) : 0

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div>
        <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white">
          Attendance Registry
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          Comprehensive log of your participation in classes and exam sittings.
        </p>
      </div>

      {/* Stats Summary */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {[
          {
            label: 'Overall Attendance',
            value: `${attendanceRate}%`,
            icon: Calendar,
            color: 'text-blue-600',
            bg: 'bg-blue-50',
          },
          {
            label: 'Present',
            value: stats.present,
            icon: CheckCircle2,
            color: 'text-emerald-600',
            bg: 'bg-emerald-50',
          },
          {
            label: 'Punctual / Late',
            value: stats.late,
            icon: Clock,
            color: 'text-amber-600',
            bg: 'bg-amber-50',
          },
          {
            label: 'Absent',
            value: stats.absent,
            icon: XCircle,
            color: 'text-rose-600',
            bg: 'bg-rose-50',
          },
        ].map((stat) => (
          <div
            key={stat.label}
            className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"
          >
            <div className="flex items-center gap-4">
              <div
                className={`flex h-12 w-12 items-center justify-center rounded-xl ${stat.bg} ${stat.color}`}
              >
                <stat.icon className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black tracking-widest text-slate-400 uppercase">
                  {stat.label}
                </p>
                <p className="text-xl font-black text-slate-900 dark:text-slate-100">
                  {stat.value}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>

      <AttendanceTable records={allRecords} />
    </div>
  )
}

'use client'

import { useRouter, useSearchParams } from 'next/navigation'
import { useCallback, useState, useTransition } from 'react'
import { Search, Users, BookOpen, Calendar, Route, GraduationCap } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'

type FilterType = 'batch' | 'classmates' | 'year' | 'semester' | 'pathway' | 'class'

interface ClassmatesFiltersProps {
  currentFilter: string
  currentQuery: string
  currentYear?: string
  currentSemester?: string
  currentPathway?: string
  currentClassId?: string
  academicYears: { id: string; name: string }[]
  semesters: { id: string; name: string }[]
  pathways: { id: string; name: string }[]
  classes: { id: string; label: string }[]
}

const FILTER_TABS: { key: FilterType; label: string; icon: typeof Users }[] = [
  { key: 'batch', label: 'All Batch-mates', icon: Users },
  { key: 'classmates', label: 'My Classes', icon: BookOpen },
  { key: 'year', label: 'By Year', icon: Calendar },
  { key: 'semester', label: 'By Semester', icon: Calendar },
  { key: 'pathway', label: 'By Pathway', icon: Route },
  { key: 'class', label: 'By Class', icon: GraduationCap },
]

export default function ClassmatesFilters({
  currentFilter,
  currentQuery,
  currentYear,
  currentSemester,
  currentPathway,
  currentClassId,
  academicYears,
  semesters,
  pathways,
  classes,
}: ClassmatesFiltersProps) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [query, setQuery] = useState(currentQuery)

  const buildUrl = useCallback(
    (params: Record<string, string | undefined>) => {
      const sp = new URLSearchParams()
      for (const [k, v] of Object.entries(params)) {
        if (v) sp.set(k, v)
      }
      return `/student/classmates?${sp.toString()}`
    },
    []
  )

  function handleFilterChange(filter: FilterType) {
    startTransition(() => {
      router.push(buildUrl({ filter, q: query || undefined }), { scroll: false })
    })
  }

  function handleSubFilterChange(key: string, value: string) {
    startTransition(() => {
      router.push(
        buildUrl({ filter: currentFilter, q: query || undefined, [key]: value }),
        { scroll: false }
      )
    })
  }

  function handleSearch(e: React.FormEvent) {
    e.preventDefault()
    startTransition(() => {
      const params: Record<string, string | undefined> = {
        filter: currentFilter,
        q: query || undefined,
      }
      if (currentYear) params.year = currentYear
      if (currentSemester) params.semester = currentSemester
      if (currentPathway) params.pathway = currentPathway
      if (currentClassId) params.classId = currentClassId
      router.push(buildUrl(params), { scroll: false })
    })
  }

  return (
    <div className="space-y-4">
      {/* Search */}
      <form onSubmit={handleSearch} className="relative flex-1">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
        <Input
          placeholder="Search by name or email..."
          className="pl-10 rounded-2xl border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </form>

      {/* Filter tabs */}
      <div className="flex flex-wrap gap-2">
        {FILTER_TABS.map((tab) => {
          const Icon = tab.icon
          const isActive = currentFilter === tab.key
          return (
            <button
              key={tab.key}
              onClick={() => handleFilterChange(tab.key)}
              className={cn(
                'inline-flex items-center gap-1.5 rounded-full px-4 py-1.5 text-xs font-bold transition-all',
                isActive
                  ? 'bg-blue-800 text-white shadow-sm'
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:hover:bg-slate-700'
              )}
            >
              <Icon className="h-3.5 w-3.5" />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* Sub-filters */}
      {currentFilter === 'year' && academicYears.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {academicYears.map((ay) => (
            <Badge
              key={ay.id}
              variant={currentYear === ay.id ? 'default' : 'outline'}
              className="cursor-pointer px-3 py-1 text-xs font-bold"
              onClick={() => handleSubFilterChange('year', ay.id)}
            >
              {ay.name}
            </Badge>
          ))}
        </div>
      )}

      {currentFilter === 'semester' && semesters.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {semesters.map((sem) => (
            <Badge
              key={sem.id}
              variant={currentSemester === sem.id ? 'default' : 'outline'}
              className="cursor-pointer px-3 py-1 text-xs font-bold"
              onClick={() => handleSubFilterChange('semester', sem.id)}
            >
              {sem.name}
            </Badge>
          ))}
        </div>
      )}

      {currentFilter === 'pathway' && pathways.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {pathways.map((pw) => (
            <Badge
              key={pw.id}
              variant={currentPathway === pw.id ? 'default' : 'outline'}
              className="cursor-pointer px-3 py-1 text-xs font-bold"
              onClick={() => handleSubFilterChange('pathway', pw.id)}
            >
              {pw.name}
            </Badge>
          ))}
        </div>
      )}

      {currentFilter === 'class' && classes.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {classes.map((cls) => (
            <Badge
              key={cls.id}
              variant={currentClassId === cls.id ? 'default' : 'outline'}
              className="cursor-pointer px-3 py-1 text-xs font-bold"
              onClick={() => handleSubFilterChange('classId', cls.id)}
            >
              {cls.label}
            </Badge>
          ))}
        </div>
      )}

      {isPending && (
        <div className="h-1 w-full overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
          <div className="h-full w-1/3 animate-pulse rounded-full bg-sky-400" />
        </div>
      )}
    </div>
  )
}

import { Metadata } from 'next'
import { getAuthSession } from '@/lib/auth/helpers'
import { redirect } from 'next/navigation'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { Users, GraduationCap, BookOpen, Sparkles, Calendar, Route } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import Link from 'next/link'
import ClassmatesFilters from './_components/ClassmatesFilters'

export const metadata: Metadata = {
  title: 'Classmates | Student Portal',
  description: 'Connect with your fellow batch-mates and classmates.',
}

type FilterType = 'batch' | 'classmates' | 'year' | 'semester' | 'pathway' | 'class'

export default async function ClassmatesPage({
  searchParams,
}: {
  searchParams: Promise<{
    q?: string
    filter?: FilterType
    year?: string
    semester?: string
    pathway?: string
    classId?: string
  }>
}) {
  const session = await getAuthSession()
  if (!session || session.user.role !== 'STUDENT') redirect('/login')

  const {
    q = '',
    filter = 'batch',
    year: yearParam,
    semester: semesterParam,
    pathway: pathwayParam,
    classId: classIdParam,
  } = await searchParams

  // Get current student's profile
  const studentProfile = await prismaUnfiltered.studentProfile.findUnique({
    where: { userId: session.user.id },
    include: {
      academicYear: true,
      semester: true,
      pathwayRel: true,
    },
  })

  if (!studentProfile || !studentProfile.academicYearId) {
    return (
      <div className="flex h-[60vh] flex-col items-center justify-center space-y-4">
        <div className="rounded-full bg-slate-100 p-6 dark:bg-slate-800">
          <Users className="h-12 w-12 text-slate-400" />
        </div>
        <div className="text-center">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">Batch Not Assigned</h2>
          <p className="text-slate-500 dark:text-slate-400">
            You haven't been assigned to an academic batch yet.
          </p>
        </div>
      </div>
    )
  }

  const batchName = studentProfile.academicYear?.name || 'Current Batch'

  // Fetch filter options for the student
  const [allPathways, myClassesRaw, academicYears, semesters] = await Promise.all([
    prismaUnfiltered.studyPathwayModel.findMany({
      select: { id: true, name: true, code: true },
      orderBy: { name: 'asc' },
    }),
    prismaUnfiltered.attendanceRecord.findMany({
      where: { userId: session.user.id },
      distinct: ['classId'],
      select: {
        classId: true,
        class: {
          select: { id: true, name: true, course: { select: { code: true } } },
        },
      },
    }),
    prismaUnfiltered.academicYear.findMany({
      select: { id: true, name: true },
      orderBy: { startDate: 'desc' },
    }),
    prismaUnfiltered.semester.findMany({
      where: { academicYearId: studentProfile.academicYearId },
      select: { id: true, name: true },
      orderBy: { startDate: 'asc' },
    }),
  ])

  const myClasses = myClassesRaw.map((c) => ({
    id: c.class.id,
    label: `${c.class.course.code} — ${c.class.name}`,
  }))

  // Build the where clause based on the active filter
  let userIdFilter: string[] | undefined = undefined

  if (filter === 'classmates' || filter === 'class') {
    // Class-based filtering
    const targetClassIds = classIdParam
      ? [classIdParam]
      : myClassesRaw.map((c) => c.classId)

    if (targetClassIds.length > 0) {
      const peersInClasses = await prismaUnfiltered.attendanceRecord.findMany({
        where: {
          classId: { in: targetClassIds },
          userId: { not: session.user.id },
        },
        distinct: ['userId'],
        select: { userId: true },
      })
      userIdFilter = peersInClasses.map((p) => p.userId)
    } else {
      userIdFilter = []
    }
  }

  // Build peer query conditions
  const peerWhere: any = {
    userId: userIdFilter !== undefined ? { in: userIdFilter } : { not: session.user.id },
    user: q
      ? {
          OR: [
            { profile: { firstName: { contains: q, mode: 'insensitive' } } },
            { profile: { lastName: { contains: q, mode: 'insensitive' } } },
            { academyEmail: { contains: q, mode: 'insensitive' } },
          ],
        }
      : undefined,
  }

  // Apply filter-specific conditions
  if (filter === 'batch' || filter === 'classmates' || filter === 'class') {
    peerWhere.academicYearId = studentProfile.academicYearId
  }

  if (filter === 'year' && yearParam) {
    peerWhere.academicYearId = yearParam
  }

  if (filter === 'semester' && semesterParam) {
    peerWhere.semesterId = semesterParam
  }

  if (filter === 'pathway' && pathwayParam) {
    peerWhere.pathwayId = pathwayParam
  }

  const peers = await prismaUnfiltered.studentProfile.findMany({
    where: peerWhere,
    include: {
      user: {
        include: {
          profile: true,
          studentProfile: {
            include: {
              pathwayRel: true,
              academicYear: true,
              semester: true,
            },
          },
        },
      },
    },
    orderBy: {
      user: {
        profile: {
          firstName: 'asc',
        },
      },
    },
    take: 100,
  })

  return (
    <div className="mx-auto max-w-[1400px] space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-black tracking-tight text-blue-800 sm:text-4xl dark:text-white">
            Classmate Directory
          </h1>
          <p className="flex items-center gap-2 text-base font-medium text-slate-500 dark:text-slate-400">
            <Sparkles className="h-5 w-5 text-sky-400" />
            Connect with your peers from{' '}
            <span className="font-bold text-blue-800 dark:text-sky-400">
              {batchName}
            </span>
            .
          </p>
        </div>
      </div>

      {/* Filters */}
      <ClassmatesFilters
        currentFilter={filter}
        currentQuery={q}
        currentYear={yearParam}
        currentSemester={semesterParam}
        currentPathway={pathwayParam}
        currentClassId={classIdParam}
        academicYears={academicYears}
        semesters={semesters}
        pathways={allPathways.map((p) => ({ id: p.id, name: p.name }))}
        classes={myClasses}
      />

      {/* Results count */}
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">
        {peers.length} {peers.length === 1 ? 'student' : 'students'} found
      </p>

      {/* Grid of Classmates */}
      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
        {peers.length === 0 ? (
          <div className="col-span-full flex h-40 flex-col items-center justify-center rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-800">
            <p className="text-sm font-medium text-slate-400">
              No peers found matching your filters.
            </p>
          </div>
        ) : (
          peers.map((peer) => {
            const name = [
              peer.user.profile?.firstName,
              peer.user.profile?.lastName,
            ]
              .filter(Boolean)
              .join(' ')
            const initials = [
              peer.user.profile?.firstName?.[0],
              peer.user.profile?.lastName?.[0],
            ]
              .filter(Boolean)
              .join('')
            const pathway =
              peer.user.studentProfile?.pathwayRel?.name || 'Full-Time'
            const yearNum = peer.currentYearNumber
            const semesterName =
              peer.user.studentProfile?.semester?.name || null

            return (
              <div
                key={peer.id}
                className="group relative flex flex-col items-center rounded-3xl border border-slate-100 bg-white p-6 text-center shadow-sm transition-all hover:shadow-xl dark:border-slate-800 dark:bg-slate-900"
              >
                <div className="relative mb-4">
                  <div className="absolute -inset-1 rounded-full bg-linear-to-tr from-blue-800 to-sky-400 opacity-0 blur transition-opacity group-hover:opacity-20" />
