'use client'

import { useState } from 'react'
import { Calendar, Users, CheckCircle2, Loader2, Info } from 'lucide-react'
import { format } from 'date-fns'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import { bookRevisionRun } from '../actions'
import { useRouter } from 'next/navigation'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'

export default function RevisionRunCard({ 
  run, 
  isBooked, 
  walletBalance 
}: { 
  run: any, 
  isBooked: boolean, 
  walletBalance: number 
}) {
  const [loading, setLoading] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)
  const router = useRouter()

  const handleBookClick = () => {
    if (walletBalance < Number(run.price)) {
      toast.error('Insufficient funds in your wallet')
      return
    }
    setShowConfirm(true)
  }

  const executeBook = async () => {
    setShowConfirm(false)
    setLoading(true)
    try {
      const res = await bookRevisionRun(run.id)
      if (res.success) {
        toast.success('Successfully booked!')
        router.refresh()
      } else {
        toast.error(res.error)
      }
    } catch (err) {
      toast.error('Failed to book')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex flex-col rounded-3xl border border-slate-100 bg-white p-6 shadow-sm transition-all hover:border-blue-100 hover:shadow-md dark:border-slate-800 dark:bg-slate-900">
      <div className="mb-4 flex items-center justify-between">
        <span className="rounded-full bg-blue-100 px-3 py-1 text-[10px] font-black tracking-widest text-blue-700 uppercase">
          {run.moduleTag || 'General'}
        </span>
        <span className="text-lg font-black text-slate-900 dark:text-white">€{Number(run.price).toFixed(2)}</span>
      </div>

      <h3 className="mb-2 text-lg font-bold leading-tight text-slate-900 dark:text-slate-100">{run.title}</h3>
      <p className="mb-6 flex-1 text-sm text-slate-500 line-clamp-2">{run.description || 'No description provided.'}</p>

      <div className="mb-6 space-y-3">
        <div className="flex items-center gap-3 text-sm text-slate-600 dark:text-slate-400">
          <Calendar className="h-4 w-4 text-blue-600" />
          <span>
            {format(new Date(run.startDatetime), 'EEE, MMM d')} • {format(new Date(run.startDatetime), 'HH:mm')}
          </span>
        </div>
        <div className="flex items-center gap-3 text-sm text-slate-600 dark:text-slate-400">
          <Users className="h-4 w-4 text-blue-600" />
          <span>
            {run.currentEnrollments} / {run.capacity} enrolled
          </span>
        </div>
      </div>

      {isBooked ? (
        <div className="flex w-full items-center justify-center gap-2 rounded-xl bg-emerald-50 py-3 text-sm font-bold text-emerald-600 dark:bg-emerald-500/10">
          <CheckCircle2 className="h-4 w-4" />
          You are enrolled
        </div>
      ) : (
        <Button
          onClick={handleBookClick}
          disabled={loading || run.currentEnrollments >= run.capacity}
          className="w-full rounded-xl bg-blue-800 font-bold text-white shadow-lg shadow-blue-500/20 transition-all hover:scale-[1.02] active:scale-[0.98]"
        >
          {loading ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : run.currentEnrollments >= run.capacity ? (
            'Fully Booked'
          ) : (
            'Book Session'
          )}
        </Button>
      )}

      <ConfirmDialog
        open={showConfirm}
        onOpenChange={setShowConfirm}
        title="Confirm Session Booking"
        description={`Are you sure you want to book "${run.title}" for €${Number(run.price).toFixed(2)}? This will be deducted from your wallet balance.`}
        confirmLabel="Book Now"
        cancelLabel="Cancel"
        onConfirm={executeBook}
        loading={loading}
      />
    </div>
  )
}

'use server'

import { getAuthSession } from '@/lib/auth/helpers'
import prisma, { prismaUnfiltered } from '@/lib/prisma/client'
import { chargeWallet } from '@/lib/wallet/operations'
import { revalidatePath } from 'next/cache'

export async function bookRevisionRun(runId: string) {
  try {
    const session = await getAuthSession()
    if (!session) return { error: 'Unauthorized' }

    const userId = session.user.id

    // Check if student already booked ANY revision run
    const totalBookings = await prismaUnfiltered.tuitionBooking.count({
      where: { studentId: userId },
    })

    if (totalBookings >= 1) {
      return { error: 'You have already booked a revision run' }
    }

    // Check if run exists and is open
    const run = await prismaUnfiltered.tuitionRun.findUnique({
      where: { id: runId },
    })

    if (!run) return { error: 'Revision run not found' }
    if (run.status !== 'OPEN' && run.status !== 'SCHEDULED') {
      return { error: 'This revision run is not open for booking' }
    }

    if (run.currentEnrollments >= run.capacity) {
      return { error: 'This revision run is at full capacity' }
    }

    // Start transaction using unfiltered client to bypass any RLS restriction for operations
    const result = await prismaUnfiltered.$transaction(async (tx) => {
      // 1. Charge wallet
      await chargeWallet(
        tx,
        userId,
        Number(run.price),
        `Revision Support Booking: ${run.title}`,
        runId,
        'tuition_run'
      )

      // 2. Create booking
      const booking = await tx.tuitionBooking.create({
        data: {
          tuitionRunId: runId,
          studentId: userId,
          amountPaid: run.price,
          status: 'CONFIRMED',
        },
      })

      // 3. Increment enrollment count
      await tx.tuitionRun.update({
        where: { id: runId },
        data: {
          currentEnrollments: { increment: 1 },
          status: run.status === 'SCHEDULED' ? 'OPEN' : run.status,
        },
      })

      return booking
    }, {
      maxWait: 15000,
      timeout: 30000,
    })

    revalidatePath('/student/courses/revision')
    revalidatePath('/staff/revision-runs')
    return { success: true, booking: result }
  } catch (error: any) {
    console.error('Book revision run error:', error)
    return { error: error.message || 'Failed to book revision run' }
  }
}

import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import prisma from '@/lib/prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { Calendar, Users, BookOpen, Wallet, CheckCircle2, AlertCircle } from 'lucide-react'
import { format } from 'date-fns'
import { CurrencyDisplay } from '@/components/shared/CurrencyDisplay'
import RevisionRunCard from './_components/RevisionRunCard'

export const metadata: Metadata = {
  title: 'Revision Support | Student Portal',
}

export default async function StudentRevisionPage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const userId = session.user.id

  const [runs, userWallet, userBookings, userEnrollments, userExamBookings] = await Promise.all([
    prisma.tuitionRun.findMany({
      where: {
        status: { in: ['OPEN', 'SCHEDULED'] },
        startDatetime: { gte: new Date() },
      },
      include: {
        creator: { select: { role: true } },
      },
      orderBy: { startDatetime: 'asc' },
    }),
    prisma.wallet.findUnique({ where: { userId } }),
    prisma.tuitionBooking.findMany({
      where: { studentId: userId },
      select: { tuitionRunId: true },
    }),
    prisma.enrollment.findMany({
      where: {
        userId,
        status: { in: ['ACTIVE', 'APPROVED', 'ENROLLED'] },
      },
      include: { course: true },
    }),
    prisma.examBooking.findMany({
      where: {
        userId,
        status: { not: 'CANCELLED' },
      },
    }),
  ])

  const bookedRunIds = new Set(userBookings.map((b) => b.tuitionRunId))

  // Collect all module codes/tags the student is associated with
  const studentModuleTags = new Set<string>()

  for (const enrollment of userEnrollments) {
    if (enrollment.course.code) {
      studentModuleTags.add(enrollment.course.code.toUpperCase().trim())
    }
  }

  for (const booking of userExamBookings) {
    if (booking.moduleCode) {
      studentModuleTags.add(booking.moduleCode.toUpperCase().trim())
    }
  }

  const isRelated = (runTag: string | null) => {
    if (!runTag) return false
    const cleanRunTag = runTag.toUpperCase().trim()
    for (const studentTag of studentModuleTags) {
      if (studentTag.includes(cleanRunTag) || cleanRunTag.includes(studentTag)) {
        return true
      }
    }
    return false
  }

  // filter out runs not created by admin/staff or system
  const adminRuns = runs.filter((run) => {
    if (!run.creator) return true // null creator is system/admin
    return ['ADMIN', 'STAFF', 'SUPER_ADMIN'].includes(run.creator.role || '')
  })

  // filter for matching related module/course or exam
  const visibleRuns = adminRuns.filter((run) => isRelated(run.moduleTag))

  const plainRuns = visibleRuns.map((run) => ({
    ...run,
    price: Number(run.price),
  }))

  return (
    <div className="space-y-8 pb-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white uppercase">
            Revision Support
          </h1>
          <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Extra module support and intensive revision sessions</p>
        </div>
        <div className="flex items-center gap-4 rounded-2xl border border-slate-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-600">
            <Wallet className="h-5 w-5" />
          </div>
          <div>
            <p className="text-[10px] font-black tracking-widest text-slate-400 uppercase">Available Funds</p>
            <CurrencyDisplay
              amount={Number(userWallet?.availableBalance || 0)}
              baseCurrency={userWallet?.currency || 'EUR'}
              size="md"
              amountClassName="text-emerald-600 dark:text-emerald-400"
            />
          </div>
        </div>
      </div>

      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {plainRuns.length === 0 ? (
          <div className="col-span-full flex flex-col items-center justify-center rounded-3xl border border-slate-100 bg-white py-20 text-center dark:border-slate-800 dark:bg-slate-900">
            <div className="mb-4 rounded-full bg-slate-50 p-4 dark:bg-slate-800">
              <Calendar className="h-10 w-10 text-slate-300" />
            </div>
            <h3 className="text-lg font-bold text-slate-900 dark:text-slate-100">No Sessions Available</h3>
            <p className="mx-auto mt-2 max-w-xs text-sm text-slate-500">
              Check back later for new revision sessions scheduled by our instructors.
            </p>
          </div>
        ) : (
          plainRuns.map((run) => (
            <RevisionRunCard
              key={run.id}
              run={run}
              isBooked={bookedRunIds.has(run.id)}
              walletBalance={Number(userWallet?.availableBalance || 0)}
            />
          ))
        )}
      </div>
    </div>
  )
}

