'use client'

import { useState, useTransition } from 'react'
import { changeModuleBookingAction } from '@/app/student/actions'
import { toast } from 'sonner'
import { Loader2, Repeat, X } from 'lucide-react'
import { EASA_MODULES } from '@/lib/constants/easa-modules'

interface ChangeModuleModalProps {
  bookingId: string
  currentModuleCode: string
  hasFreeChanges: boolean
}

export default function ChangeModuleModal({ bookingId, currentModuleCode, hasFreeChanges }: ChangeModuleModalProps) {
  const [open, setOpen] = useState(false)
  const [isPending, startTransition] = useTransition()
  const [newModuleCode, setNewModuleCode] = useState('')

  const availableModules = EASA_MODULES.filter(m => m.code !== currentModuleCode)

  const handleSubmit = () => {
    if (!newModuleCode) {
      toast.error('Please select a new module.')
      return
    }

    startTransition(async () => {
      try {
        const res = await changeModuleBookingAction(bookingId, newModuleCode)

        if (res?.error) {
          toast.error(res.error)
        } else {
          toast.success(`Module successfully changed to ${newModuleCode}.`)
          setOpen(false)
        }
      } catch (err) {
        toast.error('Something went wrong. Please try again.')
      }
    })
  }

  if (!hasFreeChanges) return null

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="mt-4 flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-700 transition-all hover:bg-slate-50 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300 dark:hover:bg-slate-800"
      >
        <Repeat className="h-3.5 w-3.5" />
        Change Module (Free)
      </button>

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
            onClick={() => !isPending && setOpen(false)}
          />

          <div
            role="dialog"
            aria-modal="true"
            className="relative z-10 w-full max-w-sm overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-2xl dark:border-slate-800 dark:bg-slate-900"
          >
            <div className="flex items-center justify-between border-b border-slate-100 px-6 py-5 dark:border-slate-800">
              <h2 className="text-lg font-black tracking-tight text-slate-900 dark:text-slate-100">
                Change Module
              </h2>
              <button
                onClick={() => !isPending && setOpen(false)}
                className="flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="space-y-4 p-6">
              <p className="text-xs text-slate-500">
                You have a free module change available from your Exam Package. 
                Select a new module to swap <strong>{currentModuleCode}</strong> with.
              </p>

              <div>
                <label className="mb-2 block text-xs font-bold text-slate-700 dark:text-slate-300">
                  New Module
                </label>
                <select
                  value={newModuleCode}
                  onChange={(e) => setNewModuleCode(e.target.value)}
                  disabled={isPending}
                  className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800"
                >
                  <option value="">— Select new module —</option>
                  {availableModules.map((m) => (
                    <option key={m.code} value={m.code}>
                      {m.code} — {m.name}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="border-t border-slate-100 bg-slate-50 p-6 dark:border-slate-800 dark:bg-slate-900/50">
              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={() => setOpen(false)}
                  disabled={isPending}
                  className="flex-1 rounded-xl border border-slate-200 bg-white py-2.5 text-sm font-bold text-slate-700 transition-colors hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
                >
                  Cancel
                </button>
                <button
                  type="button"
                  onClick={handleSubmit}
                  disabled={isPending || !newModuleCode}
                  className="flex flex-[1.5] items-center justify-center gap-2 rounded-xl bg-blue-800 py-2.5 text-sm font-bold text-white shadow-lg transition-all hover:bg-[#003a7c] active:scale-95 disabled:opacity-50"
                >
                  {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Confirm Change'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { createStudentPoolAction } from '@/app/student/actions'
import { toast } from 'sonner'
import { Loader2, Plus, ArrowRight, BookOpen, Wallet, Calendar, Clock, X, Info } from 'lucide-react'
import { getCurrencySymbol } from '@/lib/currency'
import { EASA_MODULES } from '@/lib/constants/easa-modules'

interface CreatePoolModalProps {
  events: { id: string; name: string; startDate: Date; endDate: Date }[]
  poolFee: number
  currency: string
  availableBalance: number
}

export default function CreatePoolModal({
  events,
  poolFee,
  currency,
  availableBalance,
}: CreatePoolModalProps) {
  const [open, setOpen] = useState(false)
  const [isPending, startTransition] = useTransition()

  const [eventId, setEventId] = useState('')
  const [moduleCode, setModuleCode] = useState('')
  const [examDate, setExamDate] = useState('')
  const [examTimeSlot, setExamTimeSlot] = useState<'MORNING' | 'AFTERNOON'>('MORNING')

  const currencySymbol = getCurrencySymbol(currency)
  const canAfford = availableBalance >= poolFee

  const selectedEvent = events.find((e) => e.id === eventId)

  const handleSubmit = () => {
    if (!eventId || !moduleCode || !examDate) {
      toast.error('Please fill in all required fields.')
      return
    }

    startTransition(async () => {
      try {
        const res = await createStudentPoolAction({
          eventId,
          moduleCode,
          examDate,
          examTimeSlot,
        })

        if (res.error) {
          toast.error(res.error)
        } else {
          toast.success(`Booking created successfully! Seat reserved for Module ${moduleCode}.`)
          setOpen(false)
          // Reset form
          setEventId('')
          setModuleCode('')
          setExamDate('')
        }
      } catch (err) {
        toast.error('Something went wrong. Please try again.')
      }
    })
  }

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="flex items-center gap-2 rounded-xl bg-blue-800 px-6 py-2.5 text-sm font-bold text-white shadow-lg shadow-blue-500/20 transition-all hover:bg-[#003a7c] active:scale-95"
      >
        <Plus className="h-4 w-4" />
        Start New Booking
      </button>

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
            onClick={() => !isPending && setOpen(false)}
          />

          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="create-pool-title"
            onKeyDown={(e) => { if (e.key === 'Escape' && !isPending) setOpen(false) }}
            className="relative z-10 w-full max-w-lg overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-2xl dark:border-slate-800 dark:bg-slate-900"
          >
            {/* Header */}
            <div className="flex items-center justify-between border-b border-slate-100 px-8 py-6 dark:border-slate-800">
              <div>
                <h2 id="create-pool-title" className="text-xl font-black tracking-tight text-slate-900 dark:text-slate-100">
                  Start New Exam Booking
                </h2>
                <p className="mt-1 text-xs text-pretty text-slate-500 dark:text-slate-400">
                  Initiate a booking for a module not currently listed. Minimum 25 candidates required
                  for confirmation.
                </p>
              </div>
              <button
                onClick={() => !isPending && setOpen(false)}
                aria-label="Close"
                className="flex h-10 w-10 items-center justify-center rounded-xl text-slate-400 transition-colors hover:bg-slate-100 dark:hover:bg-slate-800"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="max-h-[70vh] space-y-6 overflow-y-auto p-8">
              {/* Wallet reservation warning */}
              <div className="flex items-center gap-3 rounded-2xl border border-blue-100 bg-blue-50 p-5 dark:border-blue-800 dark:bg-blue-900/20">
                <Wallet className="h-6 w-6 text-blue-600" />
                <div className="flex-1">
                  <p className="text-xs font-bold tracking-widest text-slate-500 uppercase">
                    Seat Reservation
                  </p>
                  <p className="mt-1 text-lg leading-none font-black text-slate-900 dark:text-slate-100">
                    {currencySymbol}
                    {poolFee.toFixed(2)}
                  </p>
                </div>
                <div className="text-right">
                  <p className="mb-1 inline-block rounded-full bg-blue-100 px-2 py-0.5 text-xs font-bold text-blue-600 dark:bg-blue-900/40 dark:text-blue-400">
                    On Hold
                  </p>
                  <p className="text-xs text-slate-500">Refundable if failed</p>
                </div>
              </div>

              {/* Form Grid */}
              <div className="grid gap-6 sm:grid-cols-2">
                {/* Exam Event */}
                <div className="sm:col-span-2">
                  <label className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-300">
                    Target Exam Event
                  </label>
                  <select
                    value={eventId}
                    onChange={(e) => setEventId(e.target.value)}
                    disabled={isPending}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3.5 text-sm font-medium transition-all outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                  >
                    <option value="">— Select an upcoming event —</option>
                    {events.map((e) => (
                      <option key={e.id} value={e.id}>
                        {e.name} ({new Date(e.startDate).toLocaleDateString()} -{' '}
                        {new Date(e.endDate).toLocaleDateString()})
                      </option>
                    ))}
                  </select>
                </div>

                {/* Module */}
                <div className="sm:col-span-2">
                  <label className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-300">
                    EASA Module Course
                  </label>
                  <select
                    value={moduleCode}
                    onChange={(e) => setModuleCode(e.target.value)}
                    disabled={isPending}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3.5 text-sm font-medium transition-all outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                  >
                    <option value="">— Choose module —</option>
                    {EASA_MODULES.map((m) => (
                      <option key={m.code} value={m.code}>
                        {m.code} — {m.name}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Preferred Date */}
                <div>
                  <label className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-300">
                    Preferred Date
                  </label>
                  <div className="relative">
                    <Calendar className="pointer-events-none absolute top-1/2 left-4 h-4 w-4 -translate-y-1/2 text-slate-400" />
                    <input
                      type="date"
                      value={examDate}
                      onChange={(e) => setExamDate(e.target.value)}
                      disabled={isPending || !eventId}
                      min={
                        selectedEvent
                          ? new Date(selectedEvent.startDate).toISOString().split('T')[0]
                          : undefined
                      }
                      max={
                        selectedEvent
                          ? new Date(selectedEvent.endDate).toISOString().split('T')[0]
                          : undefined
                      }
                      className="w-full rounded-2xl border border-slate-200 bg-white py-3.5 pr-4 pl-11 text-sm font-medium transition-all outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                    />
                  </div>
                </div>

                {/* Time Slot */}
                <div>
                  <label className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-300">
                    Preferred Slot
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={() => setExamTimeSlot('MORNING')}
                      className={`flex flex-col items-center justify-center gap-1 rounded-2xl border px-3 py-2.5 transition-all ${
                        examTimeSlot === 'MORNING'
                          ? 'border-blue-600 bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400'
                          : 'border-slate-200 hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-800'
                      }`}
                    >
                      <span className="text-xs font-black uppercase">Morning</span>
                      <span className="text-xs opacity-70">09:00 - 12:00</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => setExamTimeSlot('AFTERNOON')}
                      className={`flex flex-col items-center justify-center gap-1 rounded-2xl border px-3 py-2.5 transition-all ${
                        examTimeSlot === 'AFTERNOON'
                          ? 'border-blue-600 bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400'
                          : 'border-slate-200 hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-800'
                      }`}
                    >
                      <span className="text-xs font-black uppercase">Afternoon</span>
                      <span className="text-xs opacity-70">13:00 - 16:00</span>
                    </button>
                  </div>
                </div>
              </div>

              {!canAfford && (
                <div className="flex gap-3 rounded-2xl border border-amber-100 bg-amber-50 p-4 dark:border-amber-900/30 dark:bg-amber-900/20">
                  <Info className="h-5 w-5 shrink-0 text-amber-600" />
                  <div className="text-xs leading-relaxed text-amber-800 dark:text-amber-400">
                    <p className="mb-1 font-bold">Insufficient Wallet Balance</p>
                    You need at least {currencySymbol}
                    {poolFee.toFixed(2)} to start a booking and reserve your seat.
                  </div>
                </div>
              )}
            </div>

            {/* Footer */}
            <div className="border-t border-slate-100 bg-slate-50 p-8 dark:border-slate-800 dark:bg-slate-900/50">
              <div className="flex gap-4">
                <button
                  type="button"
                  onClick={() => setOpen(false)}
                  disabled={isPending}
                  className="flex-1 rounded-2xl border border-slate-200 bg-white py-4 text-sm font-bold text-slate-700 transition-colors hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="button"
                  onClick={handleSubmit}
                  disabled={isPending || !canAfford || !eventId || !moduleCode || !examDate}
                  className="flex flex-[1.5] items-center justify-center gap-2 rounded-2xl bg-blue-800 py-4 text-sm font-bold text-white shadow-lg shadow-blue-900/20 transition-all hover:bg-[#003a7c] active:scale-95 disabled:opacity-50"
                >
                  {isPending ? (
                    <Loader2 className="h-5 w-5 animate-spin" />
                  ) : (
                    <>
                      Create Booking & Join
                      <ArrowRight className="h-5 w-5" />
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { Users, User, Package, Calculator } from 'lucide-react'
import GroupBookingModal from '../../exams/_components/GroupBookingModal'
import StandaloneBooking from '../../exams/_components/StandaloneBooking'
import BundleBooking from '../../exams/_components/BundleBooking'

interface ExamEvent {
  id: string
  name: string
  startDate: Date
  endDate: Date
}

interface ExamPricing {
  groupCharterFee: number
  individualExamFee: number
  twoSeatBundle: number
  fourSeatBundle: number
  poolExamFee: number
  lateBookingDays: number
  lateBookingSurcharge: number
}

interface WalletInfo {
  availableBalance: number | string
  currency: string
}

interface QuickBookingActionsProps {
  events: ExamEvent[]
  pricing: ExamPricing
  wallet: WalletInfo | null
  examComponents: { id: string; code: string; name: string }[]
  upcomingExams: { id: string; name: string; examDate: Date; examComponent: { course: { code: string; name: string } } }[]
}

export default function QuickBookingActions({
  events,
  pricing,
  wallet,
  examComponents,
  upcomingExams,
}: QuickBookingActionsProps) {
  const balance = Number(wallet?.availableBalance || 0)
  const currency = wallet?.currency || 'EUR'

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-black tracking-tight text-slate-800 dark:text-slate-200">
           New Booking Request
        </h2>
        <p className="text-xs text-slate-500 dark:text-slate-400">
          Choose your preferred booking type below
        </p>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {/* 1. Group Charter */}
        <div className="group relative rounded-2xl border border-slate-100 bg-white p-5 transition-all hover:border-blue-200 hover:shadow-lg dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-xl bg-blue-50 text-blue-600 transition-colors group-hover:bg-blue-600 group-hover:text-white dark:bg-blue-900/20">
            <Users className="h-6 w-6" />
          </div>
          <h3 className="mb-1 font-bold text-slate-900 dark:text-slate-100">Group Charter</h3>
          <p className="mb-4 text-xs text-slate-500 dark:text-slate-400">
            Start a custom group booking for your organization or colleagues.
          </p>
          <GroupBookingModal
            events={events}
            examComponents={examComponents}
            groupCharterFee={pricing.groupCharterFee}
            currency={currency}
            availableBalance={balance}
            trigger={
              <button className="w-full rounded-xl bg-slate-900 py-2.5 text-xs font-bold text-white transition-all hover:bg-slate-800 dark:bg-slate-800 dark:hover:bg-slate-700">
                Start Group Booking
              </button>
            }
          />
        </div>

        {/* 2. Individual Seat */}
        <div className="group relative rounded-2xl border border-slate-100 bg-white p-5 transition-all hover:border-emerald-200 hover:shadow-lg dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-xl bg-emerald-50 text-emerald-600 transition-colors group-hover:bg-emerald-600 group-hover:text-white dark:bg-emerald-900/20">
            <User className="h-6 w-6" />
          </div>
          <h3 className="mb-1 font-bold text-slate-900 dark:text-slate-100">Individual Seat</h3>
          <p className="mb-4 text-xs text-slate-500 dark:text-slate-400">
            Book a single seat for any upcoming scheduled exam event.
          </p>
          <StandaloneBooking
            pricing={pricing}
            currency={currency}
            availableBalance={balance}
            upcomingExams={upcomingExams}
            examComponents={examComponents}
            events={events}
            trigger={
              <button className="w-full rounded-xl bg-emerald-600 py-2.5 text-xs font-bold text-white transition-all hover:bg-emerald-700">
                Book Individual Seat
              </button>
            }
          />
        </div>

