'use client'

import { useState, useTransition } from 'react'
import { bookStandaloneExamAction } from '@/app/student/actions'
import { toast } from 'sonner'
import { Loader2, ArrowRight, BookOpen, Wallet, Calendar, X, AlertCircle } from 'lucide-react'
import { getCurrencySymbol } from '@/lib/currency'

interface ExamWithCourse {
  id: string
  name: string
  examDate: Date
  examComponent: {
    course: { code: string; name: string }
  }
}

interface ExamComponent {
  id: string
  code: string
  name: string
  categoryCode?: string | null
  questionCount?: number | null
  courseCode?: string
  courseName?: string
}

interface ExamEvent {
  id: string
  name: string
  startDate: Date
  endDate: Date
}

interface StandaloneBookingProps {
  pricing: { individualExamFee: number; lateBookingDays: number; lateBookingSurcharge: number }
  currency: string
  availableBalance: number
  upcomingExams: ExamWithCourse[]
  examComponents: ExamComponent[]
  events: ExamEvent[]
  trigger?: React.ReactNode
}

export default function StandaloneBooking({
  pricing,
  currency,
  availableBalance,
  upcomingExams,
  examComponents,
  events,
  trigger,
}: StandaloneBookingProps) {
  const [open, setOpen] = useState(false)
  const [selectedExamId, setSelectedExamId] = useState('')
  const [selectedModuleCode, setSelectedModuleCode] = useState('')
  const [selectedEventId, setSelectedEventId] = useState(events[0]?.id || '')
  const [isPending, startTransition] = useTransition()

  const currencySymbol = getCurrencySymbol(currency)

  // Calculate dynamic surcharge based on selection
  let surcharge = 0
  let targetDate: Date | null = null

  if (selectedExamId) {
    const exam = upcomingExams.find(e => e.id === selectedExamId)
    if (exam) targetDate = new Date(exam.examDate)
  } else if (selectedModuleCode && selectedEventId) {
    const event = events.find(e => e.id === selectedEventId)
    if (event) targetDate = new Date(event.startDate)
  }

  if (targetDate) {
    // eslint-disable-next-line react-hooks/purity
    const daysUntilExam = Math.ceil((targetDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24))
    if (daysUntilExam <= pricing.lateBookingDays && daysUntilExam > 0) {
      surcharge = pricing.lateBookingSurcharge
    }
  }

  const finalPrice = pricing.individualExamFee + surcharge
  const canAfford = availableBalance >= finalPrice

  const handleConfirm = () => {
    // Priority 1: Specific Scheduled Exam
    // Priority 2: Module + Event pairing
    if (!selectedExamId && !selectedModuleCode) {
      toast.error('Please select an exam or module before booking.')
      return
    }

    startTransition(async () => {
      try {
        const res = await bookStandaloneExamAction({
          examId: selectedExamId || undefined,
          moduleCode: selectedModuleCode || undefined,
          eventId: selectedEventId || undefined,
        })

        if (res.error) {
          toast.error(res.error)
        } else {
          if (res.usedBundle) {
            toast.success('Exam booked successfully!  seat deducted from your bundle.')
          } else {
            toast.success(
              `Exam booked successfully! ${currencySymbol}${finalPrice.toFixed(2)} charged from your wallet.`
            )
          }
          setOpen(false)
          setSelectedExamId('')
          setSelectedModuleCode('')
        }
      } catch (err: any) {
        toast.error(err.message || 'Something went wrong. Please try again.')
      }
    })
  }

  return (
    <>
      {trigger ? (
        <div onClick={() => setOpen(true)} className="cursor-pointer">
          {trigger}
        </div>
      ) : (
        <button
          onClick={() => setOpen(true)}
          className="rounded-xl border border-slate-200 bg-white px-5 py-2.5 text-sm font-bold text-slate-700 transition-all hover:border-blue-300 hover:bg-blue-50/50 active:scale-95 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-100"
        >
          Book Individual Seat...
        </button>
      )}

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
            onClick={() => !isPending && setOpen(false)}
          />

          <div className="relative z-10 w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl dark:bg-slate-900">
            <div className="flex items-center justify-between border-b border-slate-100 px-6 py-5 dark:border-slate-800">
              <div>
                <h2 className="text-lg font-black tracking-tight text-slate-900 dark:text-slate-100">
                  Individual Exam Booking
                </h2>
                <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">
                  Select a module and event to book your individual seat.
                </p>
              </div>
              <button
                onClick={() => !isPending && setOpen(false)}
                className="flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="space-y-5 p-6">
              <div className="flex items-center gap-3 rounded-xl bg-blue-50 p-4 dark:bg-blue-900/20">
                <Wallet className="h-5 w-5 text-blue-600" />
                <div>
                  <p className="text-xs font-bold tracking-widest text-slate-500 uppercase">
                    Balance
                  </p>
                  <p className="text-base font-black text-slate-900 dark:text-slate-100">
                    {currencySymbol}
                    {availableBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </p>
                </div>
                <div className="ml-auto text-right">
                  <p className="text-xs font-bold tracking-widest text-slate-500 uppercase">Fee</p>
                  <p className="text-base font-black text-blue-700 dark:text-blue-400">
                    {currencySymbol}
                    {finalPrice.toFixed(2)}
                  </p>
                </div>
              </div>

              {surcharge > 0 && (
                <div className="flex items-start gap-2 rounded-xl border border-red-200 bg-red-50 p-3.5 text-xs text-red-700 dark:border-red-900/50 dark:bg-red-900/20 dark:text-red-400 font-bold uppercase tracking-wide">
                  <AlertCircle className="mt-0.5 h-4 w-4 shrink-0 text-red-500" />
                  <span>
                    A late booking surcharge of {currencySymbol}{surcharge} has been applied because this exam is within {pricing.lateBookingDays} days.
                  </span>
                </div>
              )}

              {/* Scheduled Exams Dropdown (Primary) */}
              {upcomingExams.length > 0 && (
                <div>
                  <label className="mb-2 flex items-center gap-1.5 text-sm font-bold text-slate-700 dark:text-slate-300">
                    <Calendar className="h-4 w-4" />
                    Scheduled Session (Optional)
                  </label>
                  <select
                    value={selectedExamId}
                    onChange={(e) => {
                      setSelectedExamId(e.target.value)
                      if (e.target.value) setSelectedModuleCode('')
                    }}
                    disabled={isPending}
                    className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                  >
                    <option value="">— Choose a specific session —</option>
                    {upcomingExams.map((exam) => (
                      <option key={exam.id} value={exam.id}>
                        {exam.examComponent.course.code} | {exam.name} (
                        {new Date(exam.examDate).toLocaleDateString(undefined, {
                          month: 'short',
                          day: 'numeric',
                        })}
                        )
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Module Dropdown (Secondary/Fallback) */}
              {!selectedExamId && (
                <>
                  <div>
                    <label className="mb-2 flex items-center gap-1.5 text-sm font-bold text-slate-700 dark:text-slate-300">
                      <BookOpen className="h-4 w-4" />
                      Select Module Exam
                    </label>
                    <select
                      value={selectedModuleCode}
                      onChange={(e) => setSelectedModuleCode(e.target.value)}
                      disabled={isPending}
                      className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                    >
                      <option value="">— Select a module —</option>
                      {examComponents.map((ec) => (
                        <option key={ec.id} value={ec.code}>
                          {ec.courseCode ? `${ec.courseCode} | ` : ''}{ec.code} | {ec.name}
                          {ec.categoryCode ? ` | Cat ${ec.categoryCode}` : ''}
                          {ec.questionCount ? ` | ${ec.questionCount} questions` : ''}
                        </option>
                      ))}
                    </select>
                  </div>

                  {selectedModuleCode && events.length > 0 && (
                    <div>
                      <label className="mb-2 flex items-center gap-1.5 text-sm font-bold text-slate-700 dark:text-slate-300">
                        <Calendar className="h-4 w-4" />
                        Target Exam Event
                      </label>
                      <select
                        value={selectedEventId}
                        onChange={(e) => setSelectedEventId(e.target.value)}
                        disabled={isPending}
                        className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 focus:outline-none dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                      >
                        {events.map((e) => (
                          <option key={e.id} value={e.id}>
                            {e.name}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}
                </>
              )}

              {!canAfford && (
                <div className="rounded-lg bg-amber-50 p-3 text-xs text-amber-700 dark:bg-amber-900/20 dark:text-amber-400">
                  Insufficient funds to book a standalone seat. Please top up your wallet.
                </div>
              )}

              <div className="flex gap-3 pt-2">
                <button
                  onClick={() => setOpen(false)}
                  className="flex-1 rounded-xl border border-slate-200 py-3 text-sm font-bold text-slate-700 dark:border-slate-700 dark:text-slate-300"
                >
                  Cancel
                </button>
                <button
                  onClick={handleConfirm}
                  disabled={isPending || (!selectedExamId && !selectedModuleCode) || !canAfford}
                  className="flex flex-[1.5] items-center justify-center gap-2 rounded-xl bg-blue-800 py-3 text-sm font-bold text-white hover:bg-[#003a7c] active:scale-95 disabled:opacity-50"
                >
                  {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Confirm Booking'}
                  {!isPending && <ArrowRight className="h-4 w-4" />}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { format } from 'date-fns'
import { Calendar, Clock, CreditCard, ExternalLink } from 'lucide-react'
import Link from 'next/link'
import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { useSort, SortHeader } from '@/lib/hooks/useSort'
import { payPendingExamBooking } from '@/app/student/actions'
import { PaymentStatus } from '@/types/enums'

interface BookingRecord {
  id: string
  moduleCode: string
  moduleName: string
  date: Date
  status: string
  amountPaid: number
  bookingType: string
  bookingGroupRef?: string | null
}

interface StudentBookingsTableProps {
  bookings: BookingRecord[]
}

export default function StudentBookingsTable({ bookings }: StudentBookingsTableProps) {
  const { items, requestSort, sortConfig } = useSort(bookings, { key: 'date', order: 'asc' })
  const router = useRouter()
  const [isPaying, setIsPaying] = useState<string | null>(null)

  const handlePay = async (bookingId: string) => {
    setIsPaying(bookingId)
    const res = await payPendingExamBooking(bookingId)
    setIsPaying(null)

    if (res.success) {
      toast.success('Payment successful!')
      router.refresh()
    } else {
      toast.error(res.error || 'Payment failed')
    }
  }

  return (
    <div className="overflow-hidden rounded-xl border border-stone-200/60 bg-white shadow-[0_1px_3px_rgba(0,0,0,0.04)] dark:border-white/10 dark:bg-slate-900 dark:shadow-none">
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm" aria-label="Exam bookings">
          <thead className="bg-stone-50/50 dark:bg-slate-800/50">
            <tr className="border-b border-stone-100 text-xs font-bold tracking-widest text-slate-400 uppercase dark:border-white/5">
              <SortHeader
                label="Module"
                sortKey="moduleCode"
                currentSort={sortConfig}
                onSort={requestSort}
              />
              <SortHeader
                label="Exam Date"
                sortKey="date"
                currentSort={sortConfig}
                onSort={requestSort}
              />
              <th scope="col" className="px-6 py-4">
                Status
              </th>
              <SortHeader
                label="Fee"
                sortKey="amountPaid"
                currentSort={sortConfig}
                onSort={requestSort}
                align="right"
              />
            </tr>
          </thead>
          <tbody className="divide-y divide-stone-100 dark:divide-white/5">
            {items.map((booking) => (
              <tr
                key={booking.id}
                className="transition-colors hover:bg-stone-50 dark:hover:bg-slate-800/50"
              >
                <td className="px-6 py-4">
                  <p className="font-bold text-slate-900 uppercase dark:text-white">
                    {booking.moduleCode}
                  </p>
                  <p
                    className="max-w-[150px] truncate text-xs font-medium text-slate-500"
                    title={booking.moduleName}
                  >
                    {booking.moduleName}
                  </p>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <Calendar className="h-3.5 w-3.5 text-slate-400" aria-hidden="true" />
                    {format(booking.date, 'MMM d, yyyy')}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span
                    className={`inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-xs font-bold uppercase ${
                      booking.status === PaymentStatus.APPROVED ||
                      booking.status === PaymentStatus.COMPLETED
                        ? 'bg-emerald-50 text-emerald-700'
                        : booking.status === PaymentStatus.CANCELLED ||
                            booking.status === PaymentStatus.REJECTED
                          ? 'bg-red-50 text-red-700'
                          : 'bg-amber-50 text-amber-700'
                    }`}
                  >
                    {booking.status === PaymentStatus.APPROVED ||
                    booking.status === PaymentStatus.COMPLETED ? (
                      <CreditCard className="h-3 w-3" aria-hidden="true" />
                    ) : (
                      <Clock className="h-3 w-3" aria-hidden="true" />
                    )}
                    {booking.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex flex-col items-end gap-1">
                    <p className="font-bold text-slate-900 dark:text-white">
                      {booking.amountPaid > 0 ? (
                        <>€{booking.amountPaid.toFixed(2)}</>
                      ) : booking.bookingGroupRef ? (
                        <span className="text-xs text-slate-400 uppercase italic">Bundle Seat</span>
                      ) : (
                        <>€0.00</>
                      )}
                    </p>
                    {booking.status === PaymentStatus.PENDING && (
                      <button
                        onClick={() => handlePay(booking.id)}
                        disabled={isPaying === booking.id}
                        className="bg-primary hover:bg-primary/90 rounded-lg px-3 py-1 text-xs font-bold text-white transition-all disabled:opacity-50"
                      >
                        {isPaying === booking.id
                          ? 'Processing...'
                          : booking.amountPaid > 0
                            ? 'Pay Bundle'
                            : 'Validate'}
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import {
  BookOpen,
  CheckCircle2,
  XCircle,
  Clock,
  Loader2,
  AlertTriangle,
  ArrowRight,
  Trophy,
  Hourglass,
  Download,
} from 'lucide-react'
import ConfirmModal from '@/app/staff/exams/internal/_components/ConfirmModal'

interface BankProgress {
  bankId: string
  bankName: string
  moduleCode: string | null
  categoryCode: string | null
  courseName: string
  courseCode: string
  attempted: boolean
  passed: boolean
  bestScore: number
  totalAttempts: number
  banned: boolean
  banLiftDate: string | null
  retakeEligibleAt: string | null
  isPublished: boolean
  pendingReview: boolean
}

interface ProgressData {
  studentDetails: {
    name: string
    email: string
    studentId: string | null
    dateOfBirth: string | null
    phone: string | null
    nationality: string | null
    enrollmentType: string | null
    programmeChoice: string | null
    targetCategories: string[]
  }
  bankProgress: BankProgress[]
  completionWindow: {
    startDate: string
    deadline: string
    yearsTotal: number
    percentElapsed: number
    remainingDays: number
  } | null
  summary: { totalModules: number; passedModules: number; progressPercent: number }
}

export default function InternalExamDashboard() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [data, setData] = useState<ProgressData | null>(null)
  const [loading, setLoading] = useState(true)
  const [starting, setStarting] = useState<string | null>(null)
  const [showLobby, setShowLobby] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [confirmedDetails, setConfirmedDetails] = useState<Record<string, boolean>>({})
  const [selectedCategories, setSelectedCategories] = useState<Record<string, string>>({})
  const [confirmStartBank, setConfirmStartBank] = useState<string | null>(null)

  const fetchProgress = useCallback(async () => {
    setError(null)
    try {
      const res = await fetch('/api/student/exams/internal/progress')
      const json = await res.json()
      if (json.success && json.data) {
        setData(json.data)
      } else {
        setError(json.error || 'Could not load your internal exam progress.')
      }
    } catch {
      setError('Could not connect to the exam server. Check your connection and try again.')
    } finally {
      setLoading(false)
    }
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchProgress() }, [fetchProgress])

  useEffect(() => {
    const bankId = searchParams.get('bankId')
  // eslint-disable-next-line react-hooks/set-state-in-effect
    if (!bankId || !data?.bankProgress.some(bank => bank.bankId === bankId)) return
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setShowLobby(bankId)
  }, [data?.bankProgress, searchParams])

  const handleStartExam = async (bankId: string) => {
    const bank = data?.bankProgress.find((item) => item.bankId === bankId)
    const categoryCode = bank?.categoryCode || selectedCategories[bankId] || ''
    if (bank && !bank.categoryCode && data?.studentDetails.targetCategories.length && !categoryCode) {
      setError('Select the licence category for this internal exam attempt.')
      return
    }

    setConfirmStartBank(bankId)
  }

  const handleConfirmStart = async () => {
    const bankId = confirmStartBank
    if (!bankId) return
    setConfirmStartBank(null)

    const bank = data?.bankProgress.find((item) => item.bankId === bankId)
    const categoryCode = bank?.categoryCode || selectedCategories[bankId] || ''

    setStarting(bankId)
    setError(null)
    try {
      const res = await fetch('/api/student/exams/internal/start', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ bankId, categoryCode: categoryCode || undefined }),
      })
      const json = await res.json()
      if (json.success && json.data) {
        router.push(`/student/exams/internal/${json.data.sessionId}`)
      } else {
        setError(json.error || 'Failed to start exam. Check your eligibility and try again.')
      }
    } catch {
      setError('Could not connect to the exam server. Check your connection and try again.')
    } finally {
      setStarting(null)
      setShowLobby(null)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-8 w-8 animate-spin text-blue-800" />
      </div>
    )
  }

  const now = new Date()
  const dateFormatter = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' })
  const formatOptionalDate = (value: string | null) => value ? dateFormatter.format(new Date(value)) : 'Not recorded'

  if (!data) {
    return (
      <div className="rounded-xl border border-red-200 bg-red-50 p-5 text-sm text-red-700 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-200">
        <div className="flex items-start gap-3">
          <XCircle className="mt-0.5 h-5 w-5 shrink-0" />
          <div>
            <p className="font-bold">Internal exams are unavailable</p>
            <p className="mt-1">{error || 'Your exam progress could not be loaded.'}</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {data.completionWindow && (
        <div className="rounded-xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-3 flex items-center justify-between gap-4">
            <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400">10-Year Completion Window</h3>
            <span className={`text-xs font-bold ${data.completionWindow.percentElapsed > 80 ? 'text-red-600' : 'text-slate-500'}`}>
              {data.completionWindow.remainingDays} days remaining
            </span>
          </div>
          <div className="h-3 rounded-full bg-slate-100 dark:bg-slate-800">
            <div
              className={`h-full rounded-full transition-all ${
                data.completionWindow.percentElapsed > 80 ? 'bg-red-500'
                : data.completionWindow.percentElapsed > 60 ? 'bg-amber-500'
                : 'bg-blue-800'
              }`}
              style={{ width: `${data.completionWindow.percentElapsed}%` }}
            />
          </div>
          <div className="mt-2 flex justify-between gap-4 text-[10px] text-slate-400">
            <span>Started: {dateFormatter.format(new Date(data.completionWindow.startDate))}</span>
            <span>Deadline: {dateFormatter.format(new Date(data.completionWindow.deadline))}</span>
          </div>
        </div>
      )}

      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-200">
          <div className="flex items-start gap-3">
            <XCircle className="mt-0.5 h-5 w-5 shrink-0" />
            <p>{error}</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <div className="rounded-xl border border-slate-200 bg-white p-4 text-center dark:border-slate-800 dark:bg-slate-900">
          <BookOpen className="mx-auto h-5 w-5 text-slate-400" />
          <p className="mt-1 text-2xl font-bold text-slate-900 dark:text-white">{data.summary.totalModules}</p>
          <p className="text-xs text-slate-500">Total Modules</p>
        </div>
        <div className="rounded-xl border border-green-200 bg-green-50 p-4 text-center dark:border-green-800/50 dark:bg-green-900/10">
          <Trophy className="mx-auto h-5 w-5 text-green-600" />
          <p className="mt-1 text-2xl font-bold text-green-800 dark:text-green-200">{data.summary.passedModules}</p>
          <p className="text-xs text-green-600">Passed</p>
        </div>
        <div className="rounded-xl border border-blue-800/20 bg-blue-50 p-4 text-center dark:border-blue-800/50 dark:bg-blue-900/10">
          <CheckCircle2 className="mx-auto h-5 w-5 text-blue-800" />
          <p className="mt-1 text-2xl font-bold text-aerojet-blue">{data.summary.progressPercent}%</p>
          <p className="text-xs text-slate-500">Complete</p>
        </div>
      </div>

      <div className="space-y-3">
        {data.bankProgress.map((bank) => {
          const canTake = bank.totalAttempts === 0

          return (
            <div key={bank.bankId} className="rounded-xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
              <div className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between">
                <div className="flex min-w-0 items-center gap-4">
                  <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-lg ${
                    bank.passed && bank.isPublished ? 'bg-green-100 dark:bg-green-900/30'
                    : bank.pendingReview ? 'bg-amber-100 dark:bg-amber-900/30'
                    : 'bg-slate-100 dark:bg-slate-800'
                  }`}>
                    {bank.passed && bank.isPublished ? <CheckCircle2 className="h-5 w-5 text-green-600" />
                      : bank.pendingReview ? <Hourglass className="h-5 w-5 text-amber-600" />
                      : <BookOpen className="h-5 w-5 text-slate-400" />}
                  </div>
                  <div className="min-w-0">
                    <h3 className="truncate font-bold text-slate-900 dark:text-white">
                      {bank.moduleCode || bank.courseCode}
                    </h3>
                    <p className="text-xs text-slate-500">
                      {bank.courseCode}
                      {bank.categoryCode && ` Â· Cat ${bank.categoryCode}`}
                      {bank.totalAttempts > 0 && ` Â· ${bank.totalAttempts} attempt${bank.totalAttempts !== 1 ? 's' : ''}`}
                      {bank.isPublished && bank.bestScore > 0 && ` Â· Best: ${bank.bestScore}%`}
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                  {bank.passed && bank.isPublished && (
                    <span className="rounded-full bg-green-100 px-3 py-1 text-xs font-bold text-green-700 dark:bg-green-900/30 dark:text-green-300">
                      Passed
                    </span>
                  )}
                  {bank.pendingReview && (
                    <span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-bold text-amber-700 dark:bg-amber-900/30 dark:text-amber-300">
                      Pending Review
                    </span>
                  )}
                  {canTake && (
                    <button
                      onClick={() => setShowLobby(bank.bankId)}
                      disabled={starting === bank.bankId}
                      className="flex items-center gap-1.5 rounded-lg bg-blue-800 px-4 py-2 text-xs font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50 dark:bg-sky-400"
                    >
                      {starting === bank.bankId ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      ) : (
                        <>
                          Start Exam
                          <ArrowRight className="h-3.5 w-3.5" />
                        </>
                      )}
                    </button>
                  )}
                  <a
                    href={`/api/student/exams/internal/banks/${bank.bankId}/seb-config`}
                    download
                    className="flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
                  >
                    <Download className="h-3.5 w-3.5" />
                    Download SEB Config
                  </a>
                </div>
              </div>

              {showLobby === bank.bankId && (
                <div className="border-t border-slate-100 bg-slate-50 p-5 dark:border-slate-800 dark:bg-slate-800/50">
                  <div className="mb-4 rounded-lg border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
                    <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                      <div>
                        <p className="text-xs font-bold uppercase tracking-widest text-slate-400">Confirm Candidate Details</p>
                        <dl className="mt-3 grid gap-2 text-xs text-slate-600 dark:text-slate-300 sm:grid-cols-2">
                          <div><dt className="font-bold text-slate-400">Name</dt><dd>{data.studentDetails.name}</dd></div>
                          <div><dt className="font-bold text-slate-400">Student ID</dt><dd>{data.studentDetails.studentId || 'Not assigned'}</dd></div>
                          <div><dt className="font-bold text-slate-400">Email</dt><dd className="break-all">{data.studentDetails.email}</dd></div>
                          <div><dt className="font-bold text-slate-400">Date of Birth</dt><dd>{formatOptionalDate(data.studentDetails.dateOfBirth)}</dd></div>
                          <div><dt className="font-bold text-slate-400">Phone</dt><dd>{data.studentDetails.phone || 'Not recorded'}</dd></div>
                          <div><dt className="font-bold text-slate-400">Programme</dt><dd>{data.studentDetails.programmeChoice || data.studentDetails.enrollmentType || 'Not recorded'}</dd></div>
                          <div><dt className="font-bold text-slate-400">Licence Target</dt><dd>{bank.categoryCode || selectedCategories[bank.bankId] || data.studentDetails.targetCategories.join(', ') || 'Not recorded'}</dd></div>
                        </dl>
                      </div>
                      <label className="flex max-w-sm items-start gap-3 rounded-lg border border-slate-200 bg-slate-50 p-3 text-xs font-medium text-slate-600 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300">
                        <input
                          type="checkbox"
                          checked={!!confirmedDetails[bank.bankId]}
                          onChange={(event) => setConfirmedDetails(prev => ({ ...prev, [bank.bankId]: event.target.checked }))}
                          className="mt-0.5 h-4 w-4 rounded border-slate-300 text-aerojet-blue focus:ring-blue-800"
                        />
                        <span>I confirm these details are correct for this exam attempt.</span>
                      </label>
                    </div>
                  </div>
                  {!bank.categoryCode && data.studentDetails.targetCategories.length > 0 && (
                    <div className="mb-4 rounded-lg border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
                      <label className="mb-2 block text-xs font-bold uppercase tracking-widest text-slate-400">
                        Licence Category for This Attempt
                      </label>
                      <select
                        value={selectedCategories[bank.bankId] || ''}
                        onChange={(event) => setSelectedCategories(prev => ({ ...prev, [bank.bankId]: event.target.value }))}
                        className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-900 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                      >
                        <option value="">Select category</option>
                        {data.studentDetails.targetCategories.map((category) => (
                          <option key={category} value={category}>Category {category}</option>
                        ))}
                      </select>
                    </div>
                  )}
                  <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 p-4 dark:border-amber-800/50 dark:bg-amber-900/10">
                    <div className="flex items-start gap-3">
                      <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-600" />
                      <div className="text-sm">
                        <p className="font-bold text-amber-800 dark:text-amber-200">Exam Rules - Please Read Carefully</p>
                        <ul className="mt-2 space-y-1 text-xs text-amber-700 dark:text-amber-300">
                          <li>- <strong>Single Attempt ONLY</strong> - You can only take this internal exam once. There are no retakes.</li>
                          <li>- <strong>Timer Starts Immediately</strong> - The countdown begins the moment you confirm and start.</li>
                          <li>- <strong>3-option MCQ</strong> - Each question has exactly 3 answer options (A, B, C)</li>
                          <li>- <strong>75 seconds per question</strong> - Timer limits are strictly enforced.</li>
                          <li>- <strong>75% pass mark</strong> - You must score at least 75% to pass.</li>
                          <li>- <strong>Keyboard auto-submit</strong> - Any keyboard press during the exam submits the attempt when this rule is enabled</li>
                          <li>- <strong>Auto-submit</strong> - The exam will auto-submit when time expires</li>
                          <li>- <strong>Answers are auto-saved</strong> - Your progress is saved as you answer</li>
                        </ul>
                      </div>
                    </div>
                  </div>
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <p className="text-xs text-slate-500">
                      Attempt 1 of 1
                    </p>
                    <div className="flex gap-2">
                      <button
                        onClick={() => setShowLobby(null)}
                        className="rounded-lg border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
                      >
                        Cancel
                      </button>
                      <button
                        onClick={() => handleStartExam(bank.bankId)}
                        disabled={
                          starting === bank.bankId ||
                          !confirmedDetails[bank.bankId] ||
                          (!bank.categoryCode && data.studentDetails.targetCategories.length > 0 && !selectedCategories[bank.bankId])
                        }
                        className="flex items-center gap-1.5 rounded-lg bg-aerojet-blue px-6 py-2 text-xs font-bold text-white hover:bg-aerojet-blue/90 disabled:opacity-50"
                      >
                        {starting === bank.bankId ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          'I Understand - Begin Exam'
                        )}
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )
        })}
      </div>
      <ConfirmModal
        open={confirmStartBank !== null}
        title="Confirm Exam Start"
        description="Once you begin, the timer starts immediately and cannot be paused. Ensure you are ready to complete the exam in one sitting."
        confirmLabel="Yes, Start Exam"
        cancelLabel="Cancel"
        variant="warning"
        loading={starting !== null}
        onConfirm={handleConfirmStart}
        onCancel={() => setConfirmStartBank(null)}
      />
    </div>
  )
}

