}

import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { GraduationCap, Award, FileText, TrendingUp, AlertCircle } from 'lucide-react'

import { getAuthSession } from '@/lib/auth/helpers'
import prisma from '@/lib/prisma/client'
import {
  canAccessFeature,
  getEnrollmentMilestoneStatus,
  getStudentPaymentAccessLevel,
  getStudentStatus,
} from '@/lib/access-control'
import { PaymentRequiredBanner } from '../_components/PaymentRequiredBanner'
import GradesTable from './_components/GradesTable'

export const metadata: Metadata = {
  title: 'Grades | Student Portal',
  description: 'View your academic grades and assessment results.',
}

export default async function GradesPage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const { isFullTime, isExamOnly, isModular } = await getStudentStatus(session.user.id)

  // Exam-only students have no enrollment grades — redirect to transcript
  if (isExamOnly) {
    redirect('/student/transcript')
  }

  const hasAccess = await canAccessFeature(session.user.id, 'courses')

  if (isFullTime && !hasAccess) {
    const [milestoneStatus, wallet, accessLevel] = await Promise.all([
      getEnrollmentMilestoneStatus(session.user.id),
      prisma.wallet.findUnique({
        where: { userId: session.user.id },
        select: { availableBalance: true, reservedBalance: true, currency: true },
      }),
      getStudentPaymentAccessLevel(session.user.id),
    ])

    const walletBalance = {
      available: Number(wallet?.availableBalance ?? 0),
      held: Number(wallet?.reservedBalance ?? 0),
      currency: wallet?.currency ?? 'EUR',
    }

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div>
          <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white">
            My Grades
          </h1>
          <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
            View your assessment results and academic progress.
          </p>
        </div>

        <PaymentRequiredBanner
          accessLevel={accessLevel}
          milestoneStatus={milestoneStatus}
          walletBalance={walletBalance}
        />
      </div>
    )
  }

  const grades = await prisma.grade.findMany({
    where: { userId: session.user.id },
    include: {
      enrollment: {
        include: { course: true },
      },
    },
    orderBy: { assessmentDate: 'desc' },
    take: 100,
  })

  // Calculate Average Score
  const averageScore =
    grades.length > 0
      ? Math.round(grades.reduce((acc, g) => acc + Number(g.percentage), 0) / grades.length)
      : 0

  // Serialize for client component
  const serializedGrades = grades.map((g) => ({
    id: g.id,
    assessmentName: g.assessmentName,
    assessmentType: g.assessmentType,
    percentage: g.percentage.toString(),
    score: g.score.toString(),
    maxScore: g.maxScore.toString(),
    grade: g.grade,
    assessmentDate: g.assessmentDate.toISOString(),
    enrollment: {
      course: {
        name: g.enrollment.course.name,
        code: g.enrollment.course.code,
      },
    },
  }))

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div>
        <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white">
          My Grades
        </h1>
        <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
          View your assessment results and academic progress.
        </p>
      </div>

      {/* Stats Summary */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {[
          {
            label: 'Average Score',
            value: `${averageScore}%`,
            icon: TrendingUp,
            color: 'text-blue-600',
            bg: 'bg-blue-50',
          },
          {
            label: 'Assessments',
            value: grades.length,
            icon: FileText,
            color: 'text-purple-600',
            bg: 'bg-purple-50',
          },
          {
            label: 'Modules Completed',
            value: grades.filter((g) => g.grade && ['A', 'B', 'C'].includes(g.grade)).length,
            icon: Award,
            color: 'text-green-600',
            bg: 'bg-green-50',
          },
        ].map((stat) => (
          <div
            key={stat.label}
            className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"
          >
            <div className="flex items-center gap-4">
              <div
                className={`flex h-12 w-12 items-center justify-center rounded-xl ${stat.bg} ${stat.color}`}
              >
                <stat.icon className="h-6 w-6" />
              </div>
              <div>
                <p className="text-xs font-bold tracking-widest text-slate-400 uppercase">
                  {stat.label}
                </p>
                <p className="text-xl font-black text-slate-900 dark:text-slate-100">
                  {stat.value}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>

      <GradesTable grades={serializedGrades} />
    </div>
  )
}

import { getAuthSession } from '@/lib/auth/helpers'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { AlertTriangle } from 'lucide-react'
import StudentSidebar from './_components/StudentSidebar'
import Heartbeat from '@/components/shared/Heartbeat'
import BreadcrumbNav from '@/components/layouts/BreadcrumbNav'
import PortalHeader from '@/components/layouts/PortalHeader'
import WelcomeBanner from '@/components/WelcomeBanner'
import StudentTopbarActions from './_components/StudentTopbarActions'
import ForcePasswordChange from '../applicant/_components/ForcePasswordChange'
import { getWelcomeMessages } from '@/lib/welcome-messages'
import { getStudentPaymentAccessLevel, getEnrollmentMilestoneStatus } from '@/lib/access-control'
import { resolveEffectivePathwayCode } from '@/lib/enrollment/pathway'
import AppTour from '@/components/Tour/AppTour'
import TourTrigger from '@/components/Tour/TourTrigger'
import { isInternalExamSystemEnabled } from '@/lib/internal-exam/engine'
import { shouldShowRevisionSupport } from '@/lib/revision/visibility'

export const dynamic = 'force-dynamic'

export default async function StudentLayout({ children }: { children: React.ReactNode }) {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const user = session.user

  const dbUser = await prismaUnfiltered.user.findUnique({
    where: { id: user.id },
    select: {
      status: true,
      role: true,
      mustChangePassword: true,
      registrationPaid: true,
      hasCompletedTour: true,
      profile: { select: { firstName: true, middleName: true, lastName: true } },
      studentProfile: {
        select: {
          pathwayId: true,
          pathwayRel: { select: { code: true, name: true } },
          enrollmentType: true,
        },
      },
      wallet: {
        select: { availableBalance: true, reservedBalance: true, currency: true },
      },
      fullTimeEnrollments: {
        take: 1,
        include: {
          programme: true,
          milestones: {
            orderBy: [{ yearNumber: 'asc' }, { dueDate: 'asc' }],
          },
        },
      },
    },
  })

  if (
    !dbUser ||
    ['SUSPENDED', 'DELETED', 'ARCHIVED'].includes(dbUser.status) ||
    dbUser.role !== 'STUDENT'
  ) {
    redirect('/login')
  }

  if (dbUser.mustChangePassword) {
    return (
      <ForcePasswordChange
        apiEndpoint="/api/student/profile/change-password"
        portalName="Student Portal"
      />
    )
  }

  // Pre-processed data for helpers
  const studentProfile = dbUser.studentProfile
  const effectivePathwayCode = resolveEffectivePathwayCode({
    pathwayCode: studentProfile?.pathwayRel?.code,
    enrollmentType: studentProfile?.enrollmentType,
  })
  const ftEnrollment = dbUser.fullTimeEnrollments?.[0] || null
  const preFetchedData = {
    profile: studentProfile,
    enrollment: ftEnrollment,
  }

  const userName = dbUser?.profile
    ? [dbUser.profile.firstName, dbUser.profile.middleName, dbUser.profile.lastName]
        .filter(Boolean)
        .join(' ')
    : (user.name || user.email || '')
  const userRole = user.role

  const [unreadNotifications, unreadMessages, paymentAccessLevel, milestoneStatus, welcomeMessages, internalExamEnabled, showRevision] =
    await Promise.all([
      prismaUnfiltered.notification.count({ where: { userId: user.id, isRead: false } }),
      prismaUnfiltered.message.count({ where: { recipientId: user.id, isRead: false } }),
      getStudentPaymentAccessLevel(user.id, preFetchedData),
      getEnrollmentMilestoneStatus(user.id, preFetchedData),
      getWelcomeMessages(prismaUnfiltered, session.user.role),
      isInternalExamSystemEnabled(),
      shouldShowRevisionSupport(user.id),
    ])

  const wallet = dbUser.wallet

  const hasPathway = !!studentProfile?.pathwayId || !!effectivePathwayCode

  const milestoneStatusJson = {
    ...milestoneStatus,
    milestones: milestoneStatus.milestones.map((m: any) => ({
      ...m,
      dueDate: m.dueDate.toISOString(),
      paidAt: m.paidAt?.toISOString() ?? null,
    })),
  }

  const walletBalance = {
    available: Number(wallet?.availableBalance ?? 0),
    held: Number(wallet?.reservedBalance ?? 0),
    currency: wallet?.currency ?? 'EUR',
  }

  const paymentInfo = {
    accessLevel: paymentAccessLevel,
    milestoneStatus: milestoneStatusJson,
    walletBalance,
  }

  const firstName = dbUser?.profile?.firstName || user.name?.split(' ')[0] || ''

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50 dark:bg-slate-900">
      <a href="#main-content" className="sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 focus:z-50 focus:rounded-lg focus:bg-white focus:px-4 focus:py-2 focus:text-sm focus:font-bold focus:text-slate-900 focus:shadow-lg dark:focus:bg-slate-800 dark:focus:text-white">
        Skip to main content
      </a>
      <Heartbeat />
      <AppTour
        hasCompletedTour={dbUser.hasCompletedTour}
        userRole={userRole}
        data={{
          walletBalance: dbUser.wallet ? walletBalance : undefined,
          unreadNotifications,
        }}
      />
      <StudentSidebar
        userName={userName}
        userRole={userRole}
        userImage={user.image ?? undefined}
        studyPathway={effectivePathwayCode}
        notificationCount={unreadNotifications}
        messageCount={unreadMessages}
        paymentAccessLevel={paymentAccessLevel}
        internalExamEnabled={internalExamEnabled}
        showRevisionSupport={showRevision}
        hasWallet={!!dbUser.wallet}
      />
      <main id="main-content" className="relative pt-16 lg:pt-0 min-w-0 flex-1 overflow-y-auto overflow-x-hidden">
        <div className="sticky top-0 z-30 border-b border-slate-100 bg-slate-50/80 backdrop-blur-lg dark:border-slate-800 dark:bg-slate-900/80">
          <div className="mx-auto max-w-[1920px] px-4 py-3 sm:px-8 lg:px-8">
            <PortalHeader
              actions={
                <>
                  <TourTrigger aria-label="Take a guided tour" title="Take a tour of this portal" />
                  <StudentTopbarActions />
                </>
              }
            >
              <BreadcrumbNav />
            </PortalHeader>
          </div>
        </div>
        {!dbUser.registrationPaid && (
          <div className="border-b border-amber-200 bg-amber-50 px-4 py-3 dark:border-amber-800 dark:bg-amber-900/20">
            <div className="mx-auto flex max-w-[1920px] items-center gap-3">
              <AlertTriangle className="h-4 w-4 shrink-0 text-amber-600" />
              <p className="text-sm font-bold text-amber-800 dark:text-amber-300">
                Registration fee unpaid.{' '}
                <Link href="/student/registration-fee" className="underline hover:no-underline">
                  Pay now
                </Link>{' '}
                to enroll in courses.
              </p>
            </div>
          </div>
        )}
        <div className="mx-auto max-w-[1920px] p-4 sm:p-8 lg:px-8 lg:py-6">
          {hasPathway ? (
            <div className="payment-info" data-payment-info={JSON.stringify(paymentInfo)}>
              {children}
            </div>
          ) : (
            <div className="space-y-8">
              <WelcomeBanner messages={welcomeMessages} userName={firstName} />
              <div className="mx-auto max-w-lg rounded-2xl border border-amber-200 bg-amber-50 p-6 text-center dark:border-amber-800/50 dark:bg-amber-900/10">
                <h2 className="mb-2 text-lg font-black text-amber-800 dark:text-amber-200">
                  Study Pathway Not Set
                </h2>
                <p className="text-sm text-amber-700 dark:text-amber-300">
                  Your study pathway has not been configured yet. Please contact the academy staff
                  to get your pathway assigned. Until then, portal features are restricted.
                </p>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  )
}

'use client'

import { useState } from 'react'
import {
  ChevronDown,
  ChevronRight,
  User,
  Clock,
  CornerDownRight,
  Send,
  Loader2,
} from 'lucide-react'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { sendMessage } from '../../actions'
import { markMessageAsRead } from '../../actions'
import { PresencePill } from '@/components/shared/PresencePill'

type MessageUser = {
  id: string
  email: string
  profile?: { firstName: string; lastName: string } | null
}

type Message = {
  id: string
  senderId: string
  recipientId: string
  subject: string | null
  body: string
  isRead: boolean
  createdAt: Date
  replyToId: string | null
  sender: MessageUser
  recipient: MessageUser
}

type Thread = {
  root: Message
  replies: Message[]
  unreadCount: number
}

interface MessageThreadProps {
  thread: Thread
  currentUserId: string
}

function formatTime(date: Date) {
  const now = new Date()
  const diff = now.getTime() - date.getTime()
  const hours = diff / (1000 * 60 * 60)
  if (hours < 24) return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  if (hours < 168)
    return date.toLocaleDateString([], { weekday: 'short', hour: '2-digit', minute: '2-digit' })
  return date.toLocaleDateString([], { month: 'short', day: 'numeric' })
}

function userName(user: MessageUser) {
  return user.profile ? `${user.profile.firstName} ${user.profile.lastName}` : user.email
}

function MessageBubble({
  message,
  isOwn,
  onReply,
}: {
  message: Message
  isOwn: boolean
  onReply: (msg: Message) => void
}) {
  return (
    <div className={`flex gap-3 ${isOwn ? 'flex-row-reverse' : 'flex-row'}`}>
      <div
        className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-xs font-bold text-white ${isOwn ? 'bg-blue-800' : 'bg-slate-400'}`}
      >
        {userName(isOwn ? message.sender : message.recipient)
          .charAt(0)
          .toUpperCase()}
      </div>
      <div
        className={`group max-w-[75%] ${isOwn ? 'items-end' : 'items-start'} flex flex-col gap-1`}
      >
        <p
          className={`text-xs text-slate-500 dark:text-slate-400 ${isOwn ? 'text-right' : 'text-left'}`}
        >
          {isOwn ? 'You' : userName(message.sender)} · {formatTime(message.createdAt)}
        </p>
        <div
          className={`rounded-2xl px-4 py-3 text-sm leading-relaxed ${
            isOwn
              ? 'rounded-tr-sm bg-blue-800 text-white'
              : 'rounded-tl-sm bg-slate-100 text-slate-800'
          }`}
        >
          {message.body}
        </div>
        {!isOwn && (
          <button
            onClick={() => onReply(message)}
            className="flex items-center gap-1 text-xs text-slate-400 opacity-0 transition-opacity group-hover:opacity-100 hover:text-blue-800"
          >
            <CornerDownRight className="h-3 w-3" />
            Reply
          </button>
        )}
      </div>
    </div>
  )
}

export default function MessageThread({ thread, currentUserId }: MessageThreadProps) {
  const [expanded, setExpanded] = useState(thread.unreadCount > 0)
  const [replyTo, setReplyTo] = useState<Message | null>(null)
  const [replyText, setReplyText] = useState('')
  const [sending, setSending] = useState(false)
  // Optimistic local unread count — zeroed immediately on open so the badge
  // disappears without waiting for a round-trip or page refresh.
  const [localUnreadCount, setLocalUnreadCount] = useState(thread.unreadCount)
  const router = useRouter()

  const allMessages = [thread.root, ...thread.replies].sort(
    (a, b) => a.createdAt.getTime() - b.createdAt.getTime()
  )

  const otherParticipant =
    thread.root.senderId === currentUserId ? thread.root.recipient : thread.root.sender
  const subjectDisplay = thread.root.subject || '(No subject)'

  async function markThreadRead() {
    if (localUnreadCount === 0) return
    // Clear badge immediately (optimistic)
    setLocalUnreadCount(0)
    const unreadIds = allMessages
      .filter((m) => m.recipientId === currentUserId && !m.isRead)
      .map((m) => m.id)
    if (unreadIds.length > 0) {
      await Promise.all(unreadIds.map((id) => markMessageAsRead(id)))
      router.refresh()
    }
  }

  async function handleExpand() {
    const opening = !expanded
    setExpanded(opening)
    if (opening) {
      await markThreadRead()
    }
  }

  async function handleSendReply() {
    if (!replyText.trim()) return
    setSending(true)
    try {
      const res = await sendMessage(
        otherParticipant.id,
        subjectDisplay.startsWith('Re: ') ? subjectDisplay : `Re: ${subjectDisplay}`,
        replyText.trim()
      )
      if (!res || res.error) {
        toast.error(res?.error ?? 'Failed to send reply')
        return
      }
      toast.success('Reply sent')
      setReplyText('')
      setReplyTo(null)
      router.refresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to send reply')
    } finally {
      setSending(false)
    }
  }

  return (
    <div
      className={`rounded-2xl border bg-white shadow-sm transition-shadow hover:shadow-md dark:bg-slate-900 ${
        localUnreadCount > 0 ? 'border-blue-200' : 'border-slate-100'
      }`}
    >
      {/* Thread header – click to expand */}
      <button onClick={handleExpand} className="flex w-full items-center gap-4 px-5 py-4 text-left">
        <div
          className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-sm font-bold text-white ${
            thread.root.senderId === currentUserId ? 'bg-blue-800' : 'bg-slate-500'
          }`}
        >
          {userName(otherParticipant).charAt(0).toUpperCase()}
        </div>
        <div className="flex-1 overflow-hidden">
          <div className="flex items-center gap-2">
            <p className="truncate text-sm font-bold text-slate-900 dark:text-slate-100">
              {userName(otherParticipant)}
            </p>
            <PresencePill peerId={otherParticipant.id} />
            {localUnreadCount > 0 && (
              <span className="shrink-0 rounded-full bg-blue-500 px-1.5 py-0.5 text-xs font-bold text-white">
                {localUnreadCount} new
              </span>
            )}
          </div>
          <p className="truncate text-sm font-semibold text-slate-700">{subjectDisplay}</p>
          <p className="truncate text-xs text-slate-400">
            {allMessages[allMessages.length - 1].body}
          </p>
        </div>
        <div className="flex shrink-0 flex-col items-end gap-1.5">
          <span className="text-xs text-slate-400">
            {formatTime(allMessages[allMessages.length - 1].createdAt)}
          </span>
          {allMessages.length > 1 && (
            <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-500 dark:text-slate-400">
              {allMessages.length} msgs
            </span>
          )}
          {expanded ? (
            <ChevronDown className="h-4 w-4 text-slate-400" />
          ) : (
            <ChevronRight className="h-4 w-4 text-slate-400" />
          )}
        </div>
      </button>

      {/* Expanded conversation */}
      {expanded && (
        <div
          className="border-t border-slate-100 px-5 pt-4 pb-4 dark:border-slate-800"
          onClick={markThreadRead}
        >
          <div className="space-y-4">
            {allMessages.map((msg) => (
              <MessageBubble
                key={msg.id}
                message={msg}
                isOwn={msg.senderId === currentUserId}
                onReply={setReplyTo}
              />
            ))}
          </div>

          {/* Reply box */}
          <div className="mt-4 flex gap-2">
            <input
              type="text"
              value={replyText}
              onChange={(e) => setReplyText(e.target.value)}
              onKeyDown={(e) =>
                e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendReply())
              }
              placeholder={`Reply to ${userName(otherParticipant)}…`}
              className="flex-1 rounded-xl border border-slate-200 px-3 py-2 text-sm text-slate-900 placeholder-slate-400 focus:border-blue-800 focus:ring-2 focus:ring-blue-800/20 focus:outline-none dark:border-slate-700 dark:text-slate-100"
            />
            <button
              onClick={handleSendReply}
              disabled={sending || !replyText.trim()}
              className="flex items-center gap-1.5 rounded-xl bg-blue-800 px-4 py-2 text-sm font-bold text-white transition-colors hover:bg-[#003875] disabled:opacity-50"
            >
              {sending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Send className="h-4 w-4" />
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import ThemeToggle from '@/components/shared/ThemeToggle'
import { Bell, Mail, Moon, Sun, Monitor, Loader2, Save, Eye } from 'lucide-react'
import { updateUserSettings } from '@/app/student/actions'
import { toast } from 'sonner'
import { useTheme } from '@/components/shared/theme-provider'
import PrivacyToggle from '@/components/shared/PrivacyToggle'
import { useProfileDirty } from './ProfileTabs'

interface SettingsFormProps {
  initialSettings: any
}

export default function SettingsForm({ initialSettings }: SettingsFormProps) {
  const [isPending, startTransition] = useTransition()
  const { theme, setTheme } = useTheme()
  const { markDirty, markClean } = useProfileDirty()
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.notifications?.email ?? true
  )

  const handleSave = async () => {
    startTransition(async () => {
      const result = await updateUserSettings({
        notifications: {
          email: emailNotifications,
        },
        theme: theme,
      })

      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success('Settings updated successfully')
        markClean()
      }
    })
  }

  return (
    <div className="space-y-6">
      {/* Notifications Section */}
      <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm sm:p-8 dark:border-slate-800 dark:bg-slate-900">
        <h3 className="mb-6 flex items-center gap-2 border-b border-slate-50 pb-4 text-lg font-black text-blue-800 dark:border-slate-800 dark:text-white">
          <Bell className="h-5 w-5 text-blue-600 dark:text-blue-400" />
          Notification Preferences
        </h3>

        <div className="space-y-4">
          <div className="flex items-center justify-between rounded-2xl border border-slate-50 p-4 transition-colors hover:bg-slate-50 dark:border-slate-800 dark:hover:bg-slate-800/50">
            <div className="flex items-center gap-4">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400">
                <Mail className="h-5 w-5" />
              </div>
              <div>
                <p className="font-bold text-slate-800 dark:text-slate-200">Email Notifications</p>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  Stay updated on course changes, results, and fees.
                </p>
              </div>
            </div>
            <label className="relative inline-flex cursor-pointer items-center">
              <input
                type="checkbox"
                checked={emailNotifications}
                onChange={(e) => {
                  const val = e.target.checked
                  setEmailNotifications(val)
                  markDirty()
                  startTransition(async () => {
                    const result = await updateUserSettings({
                      notifications: {
                        email: val,
                      },
                      theme: theme,
                    })
                    if (result.error) {
                      toast.error(result.error)
                      setEmailNotifications(!val)
                    } else {
                      toast.success('Notification settings updated')
                    }
                  })
                }}
                className="peer sr-only"
              />
              <div className="peer h-6 w-11 rounded-full bg-slate-200 peer-checked:bg-blue-600 after:absolute after:top-[2px] after:left-[2px] after:h-5 after:w-5 after:rounded-full after:border after:border-gray-300 after:bg-white after:transition-all after:content-[''] peer-checked:after:translate-x-full peer-checked:after:border-white dark:border-slate-600 dark:bg-slate-700"></div>
            </label>
          </div>
        </div>
      </div>

      {/* Privacy Section */}
      <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm sm:p-8 dark:border-slate-800 dark:bg-slate-900">
        <h3 className="mb-6 flex items-center gap-2 border-b border-slate-50 pb-4 text-lg font-black text-blue-800 dark:border-slate-800 dark:text-white">
          <Eye className="h-5 w-5 text-purple-600 dark:text-purple-400" />
          Privacy
        </h3>
        <PrivacyToggle />
      </div>

      {/* Appearance Section */}
      <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm sm:p-8 dark:border-slate-800 dark:bg-slate-900">
        <h3 className="mb-6 flex items-center gap-2 border-b border-slate-50 pb-4 text-lg font-black text-aerojet-blue dark:border-slate-800 dark:text-white">
          <Sun className="h-5 w-5 text-amber-500 dark:text-amber-400" />
          Appearance Settings
        </h3>

        <div className="grid grid-cols-3 gap-4">
          {[
            { id: 'light', label: 'Light', icon: Sun },
            { id: 'dark', label: 'Dark', icon: Moon },
            { id: 'system', label: 'System', icon: Monitor },
          ].map((item) => {
            const Icon = item.icon
            const isActive = theme === item.id
            return (
              <button
                key={item.id}
                onClick={() => {
                  setTheme(item.id)
                  markDirty()
                }}
                className={`flex flex-col items-center gap-3 rounded-2xl border p-4 transition-all ${
                  isActive
                    ? 'border-blue-500 bg-blue-50/50 text-blue-600 dark:border-blue-400 dark:bg-blue-400/10 dark:text-blue-400'
                    : 'border-slate-100 bg-white text-slate-400 hover:border-slate-200 hover:bg-slate-50 dark:border-slate-800 dark:bg-slate-800/50 dark:hover:border-slate-700'
                }`}
              >
                <Icon className="h-6 w-6" />
                <span className="text-xs font-bold tracking-widest uppercase">{item.label}</span>
              </button>
            )
          })}
        </div>
      </div>

      {/* Save Button */}
      <div className="flex justify-end pt-4">
        <button
          onClick={handleSave}
          disabled={isPending}
          className="flex items-center gap-2 rounded-xl bg-blue-800 px-8 py-3 text-sm font-bold text-white transition-all hover:bg-[#003d85] hover:shadow-lg disabled:opacity-50"
        >
          {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save Settings
        </button>
      </div>
    </div>
  )
}

'use client'

import React from 'react'
import { FileText, FileCode, Archive, ExternalLink, Download, Clock, BookOpen, GraduationCap, ClipboardList, Shield } from 'lucide-react'
import { motion } from 'framer-motion'
import { cn } from '@/lib/utils'

interface Resource {
  id: string
  name: string
  type: string
  category: string
  url: string
  updatedAt: Date | string
  courseCode?: string
}

interface StudentResourceCardProps {
  resource: Resource
}

export default function StudentResourceCard({ resource }: StudentResourceCardProps) {
  const getFileIcon = (type: string) => {
    switch (type.toUpperCase()) {
      case 'PDF':
        return <FileText className="h-6 w-6 text-rose-500" />
      case 'DOCX':
        return <FileText className="h-6 w-6 text-blue-500" />
      case 'ZIP':
        return <Archive className="h-6 w-6 text-amber-500" />
      case 'LINK':
        return <ExternalLink className="h-6 w-6 text-emerald-500" />
      default:
        return <FileCode className="h-6 w-6 text-slate-500" />
    }
  }

  const getCategoryColor = (category: string) => {
    switch (category.toUpperCase()) {
      case 'ACADEMIC':
        return 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800'
      case 'ADMINISTRATIVE':
        return 'bg-purple-50 text-purple-600 border-purple-100 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800'
      case 'EXAMINATION':
        return 'bg-rose-50 text-rose-600 border-rose-100 dark:bg-rose-900/20 dark:text-rose-400 dark:border-rose-800'
      default:
        return 'bg-slate-50 text-slate-600 border-slate-100 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700'
    }
  }

  return (
    <motion.div
      whileHover={{ y: -6 }}
      className="group relative flex flex-col justify-between overflow-hidden rounded-3xl border border-slate-100 bg-white/70 backdrop-blur-md p-6 transition-all duration-300 hover:border-blue-200/50 hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.06)] dark:border-slate-800 dark:bg-slate-900/70 dark:hover:border-blue-800/40"
    >
      <div className="absolute inset-0 bg-linear-to-br from-blue-50/0 to-indigo-50/0 opacity-0 transition-opacity duration-300 group-hover:from-blue-50/30 group-hover:to-indigo-50/30 dark:group-hover:from-blue-900/5 dark:group-hover:to-indigo-900/5 group-hover:opacity-100" />

      <div className="relative flex flex-1 flex-col">
        {/* Top Header */}
        <div className="mb-5 flex items-center justify-between">
          <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white border border-slate-100 shadow-sm transition-transform duration-300 group-hover:scale-105 dark:bg-slate-800 dark:border-slate-700">
            {getFileIcon(resource.type)}
          </div>
          <span
            className={cn(
              'rounded-xl border px-3 py-1 text-[10px] font-black tracking-widest uppercase transition-colors duration-300',
              getCategoryColor(resource.category)
            )}
          >
            {resource.category}
          </span>
        </div>

        {/* Title */}
        <div className="mb-5 flex-1">
          {resource.courseCode && (
            <div className="mb-2 inline-flex rounded-md bg-slate-50 border border-slate-100 px-2 py-0.5 font-mono text-[9px] font-black tracking-tight text-slate-400 uppercase dark:bg-slate-800/50 dark:border-slate-800">
              {resource.courseCode}
            </div>
          )}
          <h3 className="line-clamp-2 text-sm font-black text-slate-900 leading-snug tracking-tight transition-colors group-hover:text-blue-600 dark:text-slate-100 dark:group-hover:text-blue-400">
            {resource.name}
          </h3>
        </div>

        {/* Action Bottom Section */}
        <div className="mt-auto flex items-center justify-between border-t border-slate-50 pt-4 dark:border-slate-800">
          <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-400 uppercase">
            <Clock className="h-3 w-3 text-slate-300" />
            {new Date(resource.updatedAt).toLocaleDateString([], {
              month: 'short',
              day: 'numeric',
              year: 'numeric',
            })}
          </div>

          <a
            href={resource.url}
            target="_blank"
            rel="noopener noreferrer"
            className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-50 border border-slate-100 text-slate-500 transition-all duration-300 hover:bg-blue-600 hover:text-white hover:border-blue-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 dark:hover:bg-blue-600 dark:hover:border-blue-600"
            title={resource.type === 'LINK' ? 'Open link' : 'Download file'}
          >
            {resource.type === 'LINK' ? (
              <ExternalLink className="h-4 w-4" />
            ) : (
              <Download className="h-4 w-4" />
            )}
          </a>
        </div>
      </div>
    </motion.div>
  )
}

import { getStudentResources } from '@/lib/actions/resources'
import StudentResourcesView from './_components/StudentResourcesView'
import { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthSession } from '@/lib/auth/helpers'
import prisma from '@/lib/prisma/client'
import {
  canAccessFeature,
  getEnrollmentMilestoneStatus,
  getStudentPaymentAccessLevel,
  getStudentStatus,
} from '@/lib/access-control'
import { PaymentRequiredBanner } from '../_components/PaymentRequiredBanner'

export const metadata: Metadata = {
  title: 'Student Resources | Student Portal',
  description: 'Access course materials and learning resources.',
}

export default async function StudentResourcesPage() {
  const session = await getAuthSession()
  if (!session) redirect('/login')

  const { isFullTime, isExamOnly, isModular } = await getStudentStatus(session.user.id)
  const hasAccess = await canAccessFeature(session.user.id, 'materials')

  if (isFullTime && !hasAccess) {
    const [milestoneStatus, wallet, accessLevel] = await Promise.all([
      getEnrollmentMilestoneStatus(session.user.id),
      prisma.wallet.findUnique({
        where: { userId: session.user.id },
        select: { availableBalance: true, reservedBalance: true, currency: true },
      }),
      getStudentPaymentAccessLevel(session.user.id),
    ])

    const walletBalance = {
      available: Number(wallet?.availableBalance ?? 0),
      held: Number(wallet?.reservedBalance ?? 0),
      currency: wallet?.currency ?? 'EUR',
    }

    return (
      <div className="mx-auto max-w-[1600px] space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div>
          <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white">
            Resources
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Access student handbooks, forms, and institutional materials.
          </p>
        </div>

        <PaymentRequiredBanner
          accessLevel={accessLevel}
          milestoneStatus={milestoneStatus}
          walletBalance={walletBalance}
        />
      </div>
    )
  }

  const resources = await getStudentResources()

  return (
    <div className="mx-auto max-w-[1600px] space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div>
        <h1 className="text-3xl font-black tracking-tight text-blue-800 dark:text-white">
          Resources
        </h1>
        <p className="text-slate-500 dark:text-slate-400">
          Access student handbooks, forms, and institutional materials.
        </p>
      </div>

      <StudentResourcesView initialResources={resources} />
    </div>
  )
}

