export type SidebarLink = SidebarLinkItem | SidebarLinkHeader

function buildHref(basePath: string, href: string) {
  if (!basePath) return href
  if (href === basePath || href.startsWith(`${basePath}/`)) return href
  return `${basePath}${href}`
}

interface DashboardSidebarProps {
  links: SidebarLink[]
  portalLabel: string
  portalColor?: string
  userName?: string
  userRole?: string
  userImage?: string
  basePath?: string
  userMenuItems?: SidebarLinkItem[]
  appVersion?: string
  onBack?: () => void
  backLabel?: string
}

/* â”€â”€ Mobile Top Bar with inline breadcrumb â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
function segmentToLabel(segment: string): string {
  if (segment.length > 20) return '...'
  return segment
    .replace(/\[.*?\]/g, '')
    .replace(/-/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
}

function MobileTopBar({
  portalLabel,
  onOpenMenu,
}: {
  portalLabel: string
  onOpenMenu: () => void
}) {
  const pathname = usePathname()
  const portalRoots = ['staff', 'student', 'instructor', 'applicant']
  const segments = pathname
    .split('/')
    .filter((s) => Boolean(s) && !s.startsWith('(') && !s.endsWith(')'))

  const subSegments =
    segments.length > 0 && portalRoots.includes(segments[0]) ? segments.slice(1) : segments

  const displaySegments = subSegments.length > 2 ? subSegments.slice(-2) : subSegments
  const currentPageLabel = displaySegments.length === 0 ? 'Dashboard' : null

  return (
    <div className="border-border/50 fixed top-0 right-0 left-0 z-40 flex items-center gap-3 border-b bg-white/80 px-4 py-3 backdrop-blur-lg lg:hidden dark:bg-slate-900/80">
      {/* Hamburger */}
      <button
        onClick={onOpenMenu}
        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-slate-900 text-white shadow-md transition-transform active:scale-95 dark:bg-slate-700"
        aria-label="Open navigation menu"
      >
        <Menu className="h-4 w-4" aria-hidden="true" />
      </button>

      {/* Breadcrumb trail */}
      <nav className="flex min-w-0 items-center gap-1.5 overflow-hidden" aria-label="Breadcrumb">
        {currentPageLabel ? (
          <span className="text-xs font-bold text-slate-800 dark:text-slate-100">
            {currentPageLabel}
          </span>
        ) : (
          displaySegments.map((segment, i) => {
            const isLast = i === displaySegments.length - 1
            const label = segmentToLabel(segment)

            return (
              <span key={i} className="flex shrink-0 items-center gap-1.5">
                {i > 0 && <span className="text-xs text-slate-300 dark:text-slate-600">/</span>}
                <span
                  className={`max-w-30 truncate text-xs ${
                    isLast
                      ? 'font-bold text-slate-800 dark:text-slate-100'
                      : 'font-medium text-slate-400 dark:text-slate-500'
                  }`}
                >
                  {label}
                </span>
              </span>
            )
          })
        )}
      </nav>

      {/* Portal label - pushed to end */}
      <span className="ml-auto text-[9px] font-black tracking-widest text-slate-300 uppercase dark:text-slate-600">
        {portalLabel.replace(' Portal', '')}
      </span>
    </div>
  )
}
/* â”€â”€ Nav item with optional tooltip when collapsed â”€â”€ */
function NavItem({
  href,
  icon: Icon,
  label,
  badge,
  active,
  collapsed,
  basePath,
  setMobileOpen,
  hoveredItem,
  setHoveredItem,
  tourId,
}: {
  href: string
  icon?: ElementType
  label: string
  badge?: number
  active: boolean
  collapsed: boolean
  basePath: string
  setMobileOpen: (open: boolean) => void
  hoveredItem: string | null
  setHoveredItem: (key: string | null) => void
  tourId?: string
}) {
  const itemKey = `nav-${href}`
  const isHovered = hoveredItem === itemKey && !active && !collapsed

  const content = (
    <Link
      href={basePath + href}
      onClick={() => setMobileOpen(false)}
      onMouseEnter={() => !collapsed && setHoveredItem(itemKey)}
      onMouseLeave={() => setHoveredItem(null)}
      data-tour-id={tourId}
      className={`relative flex items-center rounded-xl border px-3 py-2.5 text-sm font-medium transition-all duration-150 ease-out ${
        collapsed ? 'mx-auto h-10 w-10 justify-center p-0' : 'gap-3'
      } ${
        active
          ? 'border-sidebar-border/40 bg-sidebar-accent text-sidebar-foreground font-semibold shadow-sm'
          : 'text-sidebar-foreground/60 hover:text-sidebar-foreground border-transparent'
      }`}
    >
      {isHovered && (
        <motion.div
          layoutId="sidebar-hover"
          className="bg-sidebar-accent/60 absolute inset-0 rounded-xl"
          style={{ zIndex: 0 }}
          transition={{ type: 'spring', bounce: 0.15, duration: 0.4 }}
        />
      )}
      {Icon && <Icon className="relative z-10 h-4.5 w-4.5 shrink-0" />}
      {!collapsed && <span className="relative z-10 flex-1">{label}</span>}
      {!collapsed && badge ? (
        <span className="relative z-10 min-w-4.5 rounded-full bg-red-500 px-1.5 py-0.5 text-center text-[10px] font-black text-white">
          {badge}
        </span>
      ) : null}
    </Link>
  )

  if (collapsed) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>{content}</TooltipTrigger>
        <TooltipContent side="right" className="flex items-center gap-2">
          {label}
          {badge ? (
            <span className="min-w-4 rounded-full bg-red-500 px-1 py-0.5 text-center text-[10px] font-black text-white">
              {badge}
            </span>
          ) : null}
        </TooltipContent>
      </Tooltip>
    )
  }

  return content
}

/* â”€â”€ Group item with optional tooltip when collapsed â”€â”€ */
function GroupItem({
  link,
  collapsed,
  openGroups,
  toggleGroup,
  basePath,
  setMobileOpen,
  isActivePath,
  isGroupActive,
  hoveredItem,
  setHoveredItem,
}: {
  link: SidebarLinkItem
  collapsed: boolean
  openGroups: string[]
  toggleGroup: (label: string) => void
  basePath: string
  setMobileOpen: (open: boolean) => void
  isActivePath: (href: string) => boolean
  isGroupActive: (link: SidebarLink) => boolean
  hoveredItem: string | null
  setHoveredItem: (key: string | null) => void
}) {
  const Icon = link.icon
  const active = isGroupActive(link)
  const isOpen = openGroups.includes(link.label)
  const groupKey = `group-${link.label}`
  const isHovered = hoveredItem === groupKey && !active && !collapsed

  const trigger = (
    <button
      onClick={() => toggleGroup(link.label)}
      onMouseEnter={() => !collapsed && setHoveredItem(groupKey)}
      onMouseLeave={() => setHoveredItem(null)}
      data-tour-id={link.tourId}
      className={`relative flex w-full items-center rounded-xl border px-3 py-2.5 text-sm font-medium transition-all duration-150 ease-out ${
        collapsed ? 'mx-auto h-10 w-10 justify-center p-0' : 'gap-3'
      } ${
        active
          ? 'border-sidebar-border/40 bg-sidebar-accent text-sidebar-foreground font-semibold shadow-sm'
          : 'text-sidebar-foreground/60 hover:text-sidebar-foreground border-transparent'
      }`}
    >
      {isHovered && (
        <motion.div
          layoutId="sidebar-hover"
          className="bg-sidebar-accent/60 absolute inset-0 rounded-xl"
          style={{ zIndex: 0 }}
          transition={{ type: 'spring', bounce: 0.15, duration: 0.4 }}
        />
      )}
      {Icon && <Icon className="relative z-10 h-4.5 w-4.5 shrink-0" />}
      {!collapsed && <span className="relative z-10 flex-1 text-left">{link.label}</span>}
      {!collapsed && link.badge ? (
        <span className="relative z-10 min-w-4.5 rounded-full bg-red-500 px-1.5 py-0.5 text-center text-[10px] font-black text-white">
          {link.badge}
        </span>
      ) : null}
      {!collapsed && (
        <ChevronDown
          className={`relative z-10 h-3.5 w-3.5 transition-transform ${isOpen ? 'rotate-180' : ''}`}
        />
      )}
    </button>
  )

  return (
    <div>
      {collapsed ? (
        <Tooltip>
          <TooltipTrigger asChild>{trigger}</TooltipTrigger>
          <TooltipContent side="right" className="flex items-center gap-2">
            {link.label}
            {link.badge ? (
              <span className="min-w-4 rounded-full bg-red-500 px-1 py-0.5 text-center text-[10px] font-black text-white">
                {link.badge}
              </span>
            ) : null}
          </TooltipContent>
        </Tooltip>
      ) : (
        trigger
      )}
      {!collapsed && isOpen && link.children && (
        <div className="border-sidebar-border mt-0.5 ml-7 space-y-0.5 border-l pl-3">
          {link.children.map((child) => {
            const childKey = `child-${child.href}`
            const childActive = isActivePath(child.href)
            const childHovered = hoveredItem === childKey && !childActive
            return (
              <Link
                key={child.href}
                href={basePath + child.href}
                onClick={() => setMobileOpen(false)}
                onMouseEnter={() => setHoveredItem(childKey)}
                onMouseLeave={() => setHoveredItem(null)}
                className={`relative flex items-center rounded-xl px-3 py-2 text-[13px] font-medium transition-all ${
                  childActive
                    ? 'bg-sidebar-accent text-sidebar-foreground font-semibold'
                    : 'text-sidebar-foreground/60 hover:text-sidebar-foreground'
                }`}
              >
                {childHovered && (
                  <motion.div
                    layoutId="sidebar-hover"
                    className="bg-sidebar-accent/60 absolute inset-0 rounded-xl"
                    style={{ zIndex: 0 }}
                    transition={{ type: 'spring', bounce: 0.15, duration: 0.4 }}
                  />
                )}
                <span className="relative z-10 flex-1">{child.label}</span>
                {child.badge ? (
                  <span className="relative z-10 min-w-4.5 rounded-full bg-red-500 px-1.5 py-0.5 text-center text-[10px] font-black text-white">
                    {child.badge}
                  </span>
                ) : null}
              </Link>
            )
          })}
        </div>
      )}
    </div>
  )
}

/* â”€â”€ User profile panel â”€â”€ */
const THEME_OPTIONS = [
  { value: 'light', icon: Sun, label: 'Light' },
  { value: 'dark', icon: Moon, label: 'Dark' },
  { value: 'system', icon: Monitor, label: 'System' },
] as const

function UserMenu({
  collapsed,
  userImage,
  userName,
  userRole,
  portalColor,
  basePath,
  userMenuItems,
  theme,
  setTheme,
}: {
  collapsed: boolean
  userImage?: string
  userName?: string
  userRole?: string
  portalColor: string
  basePath: string
  userMenuItems?: SidebarLinkItem[]
  theme: string | undefined
  setTheme: (t: string) => void
}) {
  const [open, setOpen] = useState(false)

  const initials = userName
    ? userName
        .split(' ')
        .map((w) => w[0])
        .slice(0, 2)
        .join('')
        .toUpperCase()
    : '?'

  const avatar = () => (
    <div className="border-sidebar-border/50 bg-sidebar-accent relative h-8 w-8 shrink-0 overflow-hidden rounded-xl border">
      {userImage ? (
        <Image
          src={userImage}
          alt={userName || 'User'}
          fill
          sizes="32px"
          className="object-cover"
          priority={false}
        />
      ) : (
        <div className="text-sidebar-foreground/50 flex h-full w-full items-center justify-center text-[11px] font-black uppercase">
          {initials}
        </div>
      )}
    </div>
  )

  const menuLink =
    'flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-sm text-sidebar-foreground/70 transition-all duration-150 ease-out hover:bg-sidebar-accent hover:text-sidebar-foreground'

  return (
    <div className="relative">
      {/* Click-outside overlay */}
      <AnimatePresence>
        {open && (
          <motion.div
            key="overlay"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-40"
            onClick={() => setOpen(false)}
          />
        )}
      </AnimatePresence>

      {/* Panel */}
      <AnimatePresence>
        {open && (
          <motion.div
            key="panel"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 6 }}
            transition={{ type: 'spring', bounce: 0.1, duration: 0.22 }}
            className="bg-sidebar/95 absolute right-0 bottom-full left-0 z-50 mb-2 overflow-hidden rounded-2xl border border-white/15 shadow-2xl backdrop-blur-xl"
          >
            <div className="p-1.5">
              {userMenuItems?.map((item) => {
                const Icon = item.icon

                return (
                  <Link
                    key={item.href}
                    href={buildHref(basePath, item.href)}
                    onClick={() => setOpen(false)}
                    className={menuLink}
                  >
                    {Icon ? <Icon className="text-sidebar-foreground/40 h-4 w-4" /> : null}
                    {!collapsed && item.label}
                  </Link>
                )
              })}

              {/* Homepage */}
              <Link href="/" onClick={() => setOpen(false)} className={menuLink}>
                <Home className="text-sidebar-foreground/40 h-4 w-4" />
                {!collapsed && 'Homepage'}
              </Link>

              {/* Appearance */}
              {!collapsed && (
                <>
                  <div className="bg-sidebar-border/50 my-1.5 h-px" />
                  <div className="px-1 py-1.5">
                    <p className="text-sidebar-foreground/30 mb-2 px-2 text-[10px] font-black tracking-widest uppercase">
                      Appearance
                    </p>
                    <div className="flex gap-1 rounded-2xl bg-black/20 p-1.5 ring-1 ring-white/5">
                      {THEME_OPTIONS.map(({ value, icon: Icon, label }) => (
                        <button
                          key={value}
                          onClick={() => setTheme(value)}
                          className={`relative flex flex-1 items-center justify-center gap-1.5 rounded-full py-1.5 text-[10px] font-bold transition-all duration-150 ${
                            theme === value
                              ? 'bg-sidebar-accent text-sidebar-foreground shadow-md ring-1 ring-white/10'
                              : 'text-sidebar-foreground/35 hover:text-sidebar-foreground/70'
                          }`}
                        >
                          <Icon className="h-3 w-3" />
                          <span>{label}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                </>
              )}

              <div className="bg-sidebar-border/50 my-1.5 h-px" />

              {/* Sign out */}
              <button
                onClick={() => signOut({ callbackUrl: `${window.location.origin}/login` })}
                className="flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-sm font-medium text-red-400 transition-all duration-150 hover:bg-red-500/10 hover:text-red-300"
              >
                <LogOut className="h-4 w-4" />
                {!collapsed && 'Sign Out'}
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Trigger */}
      {collapsed ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              onClick={() => setOpen((v) => !v)}
              className="border-sidebar-border/40 bg-sidebar-accent/20 hover:border-sidebar-border/70 hover:bg-sidebar-accent/50 mx-auto flex h-10 w-10 items-center justify-center rounded-xl border transition-all duration-150 ease-out"
            >
              {avatar()}
            </button>
          </TooltipTrigger>
          <TooltipContent side="right">{userName || 'User menu'}</TooltipContent>
        </Tooltip>
      ) : (
        <button
          onClick={() => setOpen((v) => !v)}
          className="border-sidebar-border/40 bg-sidebar-accent/20 hover:border-sidebar-border/70 hover:bg-sidebar-accent/50 flex w-full items-center gap-3 rounded-xl border px-3 py-2.5 text-left transition-all duration-150 ease-out"
        >
          {avatar()}
          <div className="min-w-0 flex-1">
            <p className="text-sidebar-foreground truncate text-xs font-bold">
              {userName || 'User'}
            </p>
            {userRole && (
              <p
                className={`mt-0.5 truncate text-[10px] font-bold tracking-widest uppercase ${portalColor}`}
              >
                {userRole}
              </p>
            )}
          </div>
          <ChevronDown
            className={`text-sidebar-foreground/30 h-3.5 w-3.5 shrink-0 transition-transform duration-200 ${
              open ? 'rotate-180' : ''
            }`}
          />
        </button>
      )}
    </div>
  )
}

function renderSidebarContent({
  isCollapsed,
  setIsCollapsed,
  links,
  basePath,
  portalLabel,
  portalColor,
  userName,
  userRole,
  userImage,
  userMenuItems,
  openGroups,
  toggleGroup,
  isActivePath,
  isGroupActive,
  setMobileOpen,
  hoveredItem,
  setHoveredItem,
  theme,
  setTheme,
  appVersion,
  forceFull = false,
  onBack,
  backLabel,
}: {
  isCollapsed: boolean
  setIsCollapsed: (c: boolean) => void
  links: SidebarLink[]
  basePath: string
  portalLabel: string
  portalColor: string
  userName?: string
  userRole?: string
  userImage?: string
  userMenuItems?: SidebarLinkItem[]
  openGroups: string[]
  toggleGroup: (label: string) => void
  isActivePath: (href: string) => boolean
  isGroupActive: (link: SidebarLink) => boolean
  setMobileOpen: (open: boolean) => void
  hoveredItem: string | null
  setHoveredItem: (key: string | null) => void
  theme: string | undefined
  setTheme: (t: string) => void
  appVersion?: string
  forceFull?: boolean
  onBack?: () => void
  backLabel?: string
}) {
  const collapsed = forceFull ? false : isCollapsed

  return (
    <div className="flex h-full flex-col">
      {/* Logo & Collapse Toggle */}
      <div
        className={`border-sidebar-border relative flex flex-col border-b px-5 py-5 ${
          collapsed ? 'items-center' : ''
        }`}
      >
        <div className="flex items-center justify-between">
          <Link
            href={basePath || '/'}
            className={`flex items-center gap-3 ${collapsed ? 'justify-center' : ''}`}
          >
            {collapsed ? (
              <Image
                src="/apple-touch-icon.webp"
                alt="Aerojet Academy"
                width={32}
                height={32}
                className="h-8 w-8"
                priority
              />
            ) : (
              <Logo tone="onDark" className="h-8 w-auto" priority />
            )}
          </Link>

          {!collapsed && (
            <button
              onClick={() => setIsCollapsed(!isCollapsed)}
              className="text-sidebar-foreground/40 hover:bg-sidebar-accent hover:text-sidebar-foreground hidden h-8 w-8 items-center justify-center rounded-md transition-all lg:flex"
              title="Collapse sidebar"
              aria-label="Collapse sidebar"
            >
              <PanelLeftClose className="h-4 w-4" aria-hidden="true" />
            </button>
          )}
        </div>

        {collapsed && (
          <button
            onClick={() => setIsCollapsed(!isCollapsed)}
            className="text-sidebar-foreground/40 hover:bg-sidebar-accent hover:text-sidebar-foreground mt-4 hidden h-8 w-8 items-center justify-center rounded-md transition-all lg:flex"
            title="Expand sidebar"
            aria-label="Expand sidebar"
          >
            <PanelLeft className="h-4 w-4" aria-hidden="true" />
          </button>
        )}

        {!collapsed && (
          <div className="mt-2 flex items-center justify-between">
            <div className="flex items-center gap-1.5">
              <span
                className={`block text-[10px] font-black tracking-[0.2em] uppercase ${portalColor}`}
              >
                {portalLabel}
              </span>
            </div>
            {appVersion && (
              <span className="bg-sidebar-foreground/5 text-sidebar-foreground/40 rounded-md px-1.5 py-0.5 text-[9px] font-black">
                v{appVersion}
              </span>
            )}
          </div>
        )}
      </div>

      {/* Nav Links */}
      <nav
        id="sidebar-nav"
        className="flex-1 space-y-0.5 overflow-y-auto px-3 py-4"
        style={{
          scrollbarWidth: 'thin',
          scrollbarColor: 'rgba(255,255,255,0.08) transparent',
        }}
      >
        {onBack && (
          <button
            onClick={onBack}
            className={`group text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground mb-2 flex w-full items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium transition-all ${
              collapsed ? 'justify-center' : ''
            }`}
            title="Go back"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="h-4 w-4 shrink-0 transition-transform group-hover:-translate-x-1"
            >
              <path d="m15 18-6-6 6-6" />
            </svg>
            {!collapsed && <span>{backLabel || 'Back'}</span>}
          </button>
        )}

        {links.map((link, idx) => {
          if (link.type === 'header') {
            return (
              <div
                key={link.label || idx}
                className={`text-muted-foreground/50 px-3 pt-5 pb-2 text-[10px] font-black tracking-widest uppercase transition-all ${
                  collapsed ? 'text-center' : ''
                }`}
              >
                {collapsed ? '---' : link.label}
              </div>
            )
          }

          if (link.children) {
            return (
              <GroupItem
                key={link.label}
                link={link}
                collapsed={collapsed}
                openGroups={openGroups}
                toggleGroup={toggleGroup}
                basePath={basePath}
                setMobileOpen={setMobileOpen}
                isActivePath={isActivePath}
                isGroupActive={isGroupActive}
                hoveredItem={hoveredItem}
                setHoveredItem={setHoveredItem}
              />
            )
          }

          return (
            <NavItem
              key={link.href}
              href={link.href}
              icon={link.icon}
              label={link.label}
              badge={link.badge}
              active={!!isActivePath(link.href)}
              collapsed={collapsed}
              basePath={basePath}
              setMobileOpen={setMobileOpen}
              hoveredItem={hoveredItem}
              setHoveredItem={setHoveredItem}
              tourId={link.tourId}
            />
          )
        })}
      </nav>

      {/* Footer â€” User Dropdown Menu */}
      <div id="sidebar-user-menu" className="border-sidebar-border border-t px-3 py-4">
        <UserMenu
          collapsed={collapsed}
          userImage={userImage}
          userName={userName}
          userRole={userRole}
          portalColor={portalColor}
          basePath={basePath}
          userMenuItems={userMenuItems}
          theme={theme}
          setTheme={setTheme}
        />
      </div>
    </div>
  )
}

export default function DashboardSidebar({
  links,
  portalLabel,
  portalColor = 'text-blue-400',
  userName,
  userRole,
  userImage,
  basePath = '',
  userMenuItems,
  appVersion,
  onBack,
  backLabel,
}: DashboardSidebarProps) {
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)
  const [openGroups, setOpenGroups] = useState<string[]>([])
  const [mobileOpen, setMobileOpen] = useState(false)
  const [isCollapsed, setIsCollapsed] = useState(false)
  const [hoveredItem, setHoveredItem] = useState<string | null>(null)

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setMounted(true)
  }, [])

  useEffect(() => {
    links.forEach((link) => {
      if (link.children) {
        const isActive = link.children.some((child) => pathname.startsWith(basePath + child.href))
        if (isActive) {
          setOpenGroups((prev) => (prev.includes(link.label) ? prev : [...prev, link.label]))
        }
      }
    })
  }, [pathname, links, basePath])

  const toggleGroup = (label: string) => {
    if (isCollapsed) setIsCollapsed(false)
    setOpenGroups((prev) =>
      prev.includes(label) ? prev.filter((l) => l !== label) : [...prev, label]
    )
  }

  const getComparableUrl = (href: string) => {
    if (!href.includes('?')) return basePath + href
    return basePath + href
  }

  const isActivePath = (href: string) => {
    if (href.includes('?')) {
      const url = new URL(`http://localhost${basePath}${href}`)
      let allMatch = true
      url.searchParams.forEach((val, key) => {
        if (searchParams.get(key) !== val) allMatch = false
      })
      return pathname === url.pathname && allMatch
    }
    return pathname === basePath + href
  }

  const isGroupActive = (link: SidebarLink): boolean => {
    if (link.type === 'header') return false
    if (link.href && isActivePath(link.href)) return true
    return link.children?.some((c) => isActivePath(c.href)) ?? false
  }

  return (
    <>
      {/* Desktop Sidebar */}
      <aside
        className={`bg-sidebar border-sidebar-border sticky top-0 hidden h-screen shrink-0 flex-col border-r transition-all duration-300 lg:flex ${
          isCollapsed ? 'w-20' : 'w-64'
        }`}
      >
        {renderSidebarContent({
          isCollapsed,
          setIsCollapsed,
          links,
          basePath,
          portalLabel,
          portalColor,
          userName,
          userRole,
          userImage,
          userMenuItems,
          openGroups,
          toggleGroup,
          isActivePath,
          isGroupActive,
          setMobileOpen,
          hoveredItem,
          setHoveredItem,
          theme,
          setTheme,
          appVersion,
          onBack,
          backLabel,
        })}
      </aside>

      {/* Mobile Top Bar */}
      <MobileTopBar portalLabel={portalLabel} onOpenMenu={() => setMobileOpen(true)} />

      {/* Mobile Sidebar */}
      <AnimatePresence>
        {mobileOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-60 bg-black/60 lg:hidden"
              onClick={() => setMobileOpen(false)}
            />
            <motion.aside
              initial={{ x: '-100%' }}
              animate={{ x: 0 }}
              exit={{ x: '-100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              className="bg-sidebar border-sidebar-border fixed inset-y-0 left-0 z-70 flex w-72 flex-col border-r shadow-2xl lg:hidden"
            >
              <button
                onClick={() => setMobileOpen(false)}
                className="text-sidebar-foreground/60 absolute top-5 right-5 z-80 flex h-9 w-9 items-center justify-center rounded-xl bg-white/5 transition-all hover:bg-white/10 hover:text-white"
                title="Close sidebar"
                aria-label="Close sidebar"
              >
                <X className="h-5 w-5" aria-hidden="true" />
              </button>
              <div className="flex-1 overflow-y-auto">
                {renderSidebarContent({
                  isCollapsed,
                  setIsCollapsed,
                  links,
                  basePath,
                  portalLabel,
                  portalColor,
                  userName,
                  userRole,
                  userImage,
                  userMenuItems,
                  openGroups,
                  toggleGroup,
                  isActivePath,
                  isGroupActive,
                  setMobileOpen,
                  hoveredItem,
                  setHoveredItem,
                  theme,
                  setTheme,
                  forceFull: true,
                  appVersion,
                  onBack,
                  backLabel,
                })}
              </div>
            </motion.aside>
          </>
        )}
      </AnimatePresence>
    </>
  )
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import Link from 'next/link'
import Logo from '@/components/shared/Logo'
import { usePathname } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import { Menu, X, Search as SearchIcon, ArrowRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion'
import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuList,
  NavigationMenuTrigger,
} from '@/components/ui/navigation-menu'
import SearchModal from '@/components/public/SearchModal'

// ===== START: TYPE DEFINITIONS TO FIX THE ERROR =====

// Define the shape of a single link
interface NavLink {
  href: string
  label: string
  disabled?: boolean // The '?' makes this property optional
}

// Define the shape of a group of links
interface NavGroup {
  value: string
  title: string
  links: NavLink[]
}

// Update the main data structure to use these types
const navLinks: {
  label: string
  href?: string
  isDropdown?: boolean
  groups?: NavGroup[]
}[] = [
  { label: 'Home', href: '/' },
  {
    label: 'Courses',
    isDropdown: true,
    href: '/courses', // Add href for the main link
    groups: [
      {
        value: 'item-1',
        title: 'Aircraft Engineering',
        links: [
          {
            href: '/courses/aircraft-engineering/easa-part-66',
            label: 'EASA Part-66 Overview',
          },
          {
            href: '/courses/aircraft-engineering/easa-part-66/four-year-b1-b2',
            label: '4-Year Full-Time (B1.1 & B2)',
          },
          {
            href: '/courses/aircraft-engineering/easa-part-66/two-year-b1',
            label: '2-Year Full-Time (B1.1)',
          },
          {
            href: '/courses/aircraft-engineering/easa-part-66/military-certification',
            label: 'Military / Industry (1 Year)',
          },
          {
            href: '/courses/aircraft-engineering/easa-part-66/modular-training',
            label: 'Modular Training',
          },
          {
            href: '/courses/aircraft-engineering/easa-part-66/exam-only',
            label: 'Exam Only',
          },
          {
            href: '/courses/aircraft-engineering/easa-part-66/revision-support',
            label: 'Revision Support',
          },
          {
            href: '/courses/aircraft-engineering/exam-schedule',
            label: 'Exam Schedule 2026/2027',
          },
        ],
      },
      { value: 'item-2', title: 'Skilled Training Programs', links: [] },
      { value: 'item-3', title: 'Certified Short Knowledge Courses', links: [] },
    ],
  },
  { label: 'Admissions', href: '/admissions' },
  { label: 'Newsroom', href: '/newsroom' },
  { label: 'About', href: '/about' },
  { label: 'Contact', href: '/contact' },
]
// ===== END: TYPE DEFINITIONS =====

export default function PublicNav() {
  const pathname = usePathname()
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [accordionValue, setAccordionValue] = useState<string>('item-1')
  const [navValue, setNavValue] = useState<string>('')
  const [mounted, setMounted] = useState(false)
  const headerRef = useRef<HTMLElement>(null)
  const [mousePos, setMousePos] = useState<{ x: number; y: number } | null>(null)

  const handleMouseMove = useCallback((e: React.MouseEvent<HTMLElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top })
  }, [])

  const handleMouseLeave = useCallback(() => {
    setMousePos(null)
  }, [])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMounted(true)
    const handleScroll = () => setScrolled(window.scrollY > 20)
    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      // If clicking outside the header, close the dropdown and reset the accordion
      if (!target.closest('header')) {
        setNavValue('')
        setAccordionValue('')
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  // eslint-disable-next-line react-hooks/set-state-in-effect
  }, [])
  // eslint-disable-next-line react-hooks/set-state-in-effect

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMobileOpen(false)
  }, [pathname])
  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
    document.body.style.overflow = mobileOpen ? 'hidden' : ''
  }, [mobileOpen])
  // eslint-disable-next-line react-hooks/set-state-in-effect

  const [hasForceClass, setHasForceClass] = useState(false)
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    // Initial check
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setHasForceClass(document.body.classList.contains('force-navbar-solid'))

    // Observe changes to body classes (for error pages that mount/unmount)
    const observer = new MutationObserver(() => {
      setHasForceClass(document.body.classList.contains('force-navbar-solid'))
    })
    observer.observe(document.body, { attributes: true, attributeFilter: ['class'] })
    return () => observer.disconnect()
  }, [])

  // Detect system pages or pages that don't transition well with transparent nav
  const isErrorPage = pathname === '/404' || pathname === '/500' || pathname.includes('/error')
  const forceSolid =
    isErrorPage ||
    hasForceClass ||
    pathname.startsWith('/_') ||
    pathname === '/login' ||
    pathname === '/register' ||
    pathname.startsWith('/privacy-policy') ||
    pathname.startsWith('/online-application-terms')

  const headerClasses = `fixed left-0 right-0 z-50 transition-all duration-300 border-b ${scrolled || mobileOpen || forceSolid ? 'bg-white/95 backdrop-blur-xl shadow-sm border-slate-100 dark:bg-slate-950/95 dark:border-slate-800' : 'bg-transparent border-transparent'}`
  const linkColorClasses =
    scrolled || mobileOpen || forceSolid ? 'text-slate-700 dark:text-slate-200' : 'text-white'
  const activeLinkColorClasses =
    scrolled || mobileOpen || forceSolid ? 'text-public-secondary' : 'text-white'

  return (
    <>
      <header
        ref={headerRef}
        className={headerClasses}
        style={{ top: 'var(--advisory-banner-height, 0px)' }}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
      >
        {/* Mouse-tracking glow */}
        <div
          className="pointer-events-none absolute inset-0 z-0 overflow-hidden"
          aria-hidden="true"
        >
          <div
            className="absolute inset-0 transition-opacity duration-300"
            style={{
              opacity: mousePos ? 1 : 0,
              background: mousePos
                ? `radial-gradient(600px circle at ${mousePos.x}px ${mousePos.y}px, ${
                    scrolled || forceSolid ? 'rgba(59,130,246,0.05)' : 'rgba(255,255,255,0.07)'
                  }, transparent 40%)`
                : 'none',
            }}
          />
        </div>
        <div className="relative z-10 mx-auto flex h-16 w-full items-center justify-between px-6 sm:px-10 lg:px-16">
          <Link href="/" className="flex shrink-0 items-center pr-4 md:pr-8">
            <Logo
              tone={scrolled || mobileOpen || forceSolid ? 'onWhite' : 'onDark'}
              className="h-10 w-auto sm:h-12"
              priority
            />
          </Link>

          <div className="hidden flex-1 items-center justify-center lg:flex">
            {mounted && (
              <NavigationMenu
                delayDuration={300}
                value={navValue}
                onValueChange={(val) => {
                  // Prevent closing on mouse leave if an accordion item is expanded (interacted with)
                  if (!val && accordionValue) {
                    return
                  }
                  setNavValue(val)
                }}
              >
                {/* Pill container for nav links */}
                <div
                  className={`inline-flex items-center gap-1 rounded-full p-1 transition-colors ${
                    scrolled || forceSolid ? 'bg-slate-100 dark:bg-slate-800' : 'bg-white/10'
                  }`}
                >
                  <NavigationMenuList>
                    {navLinks.map((item) =>
                      item.isDropdown ? (
                        <NavigationMenuItem key={item.label} value={item.label}>
                          <NavigationMenuTrigger
                            onClick={() => setAccordionValue('')}
                            className={`relative flex h-auto cursor-pointer items-center rounded-full bg-transparent px-4 py-2 text-xs font-black tracking-[0.15em] uppercase transition-all transition-none! duration-300 ${
                              pathname?.startsWith('/courses')
                                ? scrolled || forceSolid
                                  ? 'text-aerojet-blue dark:text-white'
                                  : 'text-white'
                                : scrolled || forceSolid
                                  ? 'text-slate-500 dark:text-slate-400'
                                  : 'text-white/70'
                            }`}
                          >
                            {pathname?.startsWith('/courses') && (
                              <motion.div
                                layoutId="nav-pill"
                                className={`absolute inset-0 rounded-full ${
                                  scrolled || forceSolid
                                    ? 'bg-white shadow-sm dark:bg-slate-900'
                                    : 'bg-white/20'
                                }`}
                                style={{ zIndex: 0 }}
                                transition={{ type: 'spring', bounce: 0.15, duration: 0.5 }}
                              />
                            )}
                            <span className="relative z-10">{item.label}</span>
                          </NavigationMenuTrigger>
                          <NavigationMenuContent>
                            <div className="w-100 p-4 md:w-125">
                              <div className="mb-4 border-b border-slate-100 pb-3">
                                <Link
                                  href="/courses"
                                  className="text-public-secondary hover:text-public-primary flex items-center gap-2 px-3 text-xs font-black tracking-widest uppercase transition-colors"
                                >
                                  View All Training Programs <ArrowRight className="h-4 w-4" />
                                </Link>
                              </div>
                              <Accordion
                                type="single"
                                collapsible
                                value={accordionValue}
                                onValueChange={setAccordionValue}
                              >
                                {item.groups?.map((group) => (
                                  <AccordionItem value={group.value} key={group.value}>
                                    <AccordionTrigger
                                      onPointerDown={(e) => e.stopPropagation()}
                                      className="text-public-primary px-3 text-sm font-bold hover:no-underline dark:text-white"
                                    >
                                      {group.title}
                                    </AccordionTrigger>
                                    <AccordionContent className="pt-2">
                                      {group.links.length > 0 ? (
                                        group.links.map((link) => (
                                          <Link
                                            href={link.disabled ? '#' : link.href}
                                            key={link.href}
                                            className={`block rounded-md p-3 leading-none no-underline transition-colors outline-none select-none hover:bg-slate-100 dark:hover:bg-slate-800 ${link.disabled ? 'cursor-not-allowed opacity-60' : ''}`}
                                          >
                                            <div className="text-public-dark text-sm leading-none font-medium dark:text-slate-200">
                                              {link.label}
                                            </div>
                                          </Link>
                                        ))
                                      ) : (
                                        <p className="px-3 py-2 text-sm text-slate-500 dark:text-slate-400">
                                          Coming soon.
                                        </p>
                                      )}
                                    </AccordionContent>
                                  </AccordionItem>
                                ))}
                              </Accordion>
                            </div>
                          </NavigationMenuContent>
                        </NavigationMenuItem>
                      ) : (
                        <NavigationMenuItem key={item.label} value={item.label}>
                          <Link
                            href={item.href || '#'}
                            className={`relative flex items-center rounded-full px-4 py-2 text-xs font-black tracking-[0.15em] uppercase transition-colors ${
                              pathname === item.href
                                ? scrolled || forceSolid
                                  ? 'text-aerojet-blue dark:text-white'
                                  : 'text-white'
                                : scrolled || forceSolid
                                  ? 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-300'
                                  : 'text-white/70 hover:text-white'
                            }`}
                          >
                            {pathname === item.href && (
                              <motion.div
                                layoutId="nav-pill"
                                className={`absolute inset-0 rounded-full ${
                                  scrolled || forceSolid
                                    ? 'bg-white shadow-sm dark:bg-slate-900'
                                    : 'bg-white/20'
                                }`}
                                style={{ zIndex: 0 }}
                                transition={{ type: 'spring', bounce: 0.15, duration: 0.5 }}
                              />
                            )}
                            <span className="relative z-10">{item.label}</span>
                          </Link>
                        </NavigationMenuItem>
                      )
                    )}
                  </NavigationMenuList>
                </div>
              </NavigationMenu>
            )}
            <div
              className={`ml-3 transition-colors ${scrolled || forceSolid ? 'text-slate-500 dark:text-slate-300' : 'text-white/80'}`}
            >
              <SearchModal />
            </div>
          </div>

          <div className="flex items-center gap-2 pr-4 md:pr-8">
            <Link
              href="/login"
              className={`hidden items-center rounded-lg px-4 py-2 text-xs font-bold tracking-widest uppercase transition-all sm:inline-flex ${scrolled || forceSolid ? 'hover:text-public-primary text-slate-500 dark:text-slate-300 dark:hover:text-white' : 'text-white/80 hover:text-white'}`}
            >
              Login
            </Link>
            <Link
              href="/register"
              className="bg-public-secondary hover:bg-public-primary hidden h-11 items-center rounded-xl px-5 py-2.5 text-xs font-black tracking-widest text-white uppercase transition-all sm:inline-flex"
            >
              Register
            </Link>
            <button
              onClick={() => setMobileOpen(!mobileOpen)}
              className={`flex h-11 w-11 items-center justify-center rounded-lg transition-all lg:hidden ${linkColorClasses}`}
              aria-label={mobileOpen ? 'Close navigation menu' : 'Open navigation menu'}
            >
              {mobileOpen ? (
                <X className="h-6 w-6" aria-hidden="true" />
              ) : (
                <Menu className="h-6 w-6" aria-hidden="true" />
              )}
            </button>
          </div>
        </div>
      </header>
      <AnimatePresence>
        {mobileOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-40 bg-black/50 backdrop-blur-sm lg:hidden"
              onClick={() => setMobileOpen(false)}
            />
            <motion.nav
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              transition={{ type: 'spring', damping: 30, stiffness: 300 }}
              className="fixed top-0 right-0 bottom-0 z-50 w-[85%] max-w-sm overflow-y-auto bg-white dark:bg-slate-950"
            >
              <div className="flex items-center justify-between border-b p-6 dark:border-slate-800">
                <span className="text-public-primary text-lg font-black uppercase dark:text-white">
                  Menu
                </span>
                <button
                  onClick={() => setMobileOpen(false)}
                  className="flex h-11 w-11 items-center justify-center p-2 text-slate-700 dark:text-slate-300"
                  aria-label="Close menu"
                >
                  <X className="h-5 w-5" aria-hidden="true" />
                </button>
              </div>
              <div className="p-4">
                {navLinks.map((item) =>
                  item.isDropdown ? (
                    <Accordion type="single" collapsible className="w-full" key={item.label}>
                      <AccordionItem
                        value="courses-mobile"
                        className="border-b-0 dark:border-slate-800"
                      >
                        <AccordionTrigger className="py-3 text-base font-bold text-slate-700 hover:no-underline dark:text-slate-200">
                          {item.label}
                        </AccordionTrigger>
                        <AccordionContent>
                          <Link
                            href="/courses"
                            className="text-public-secondary mb-4 ml-4 flex items-center gap-2 py-2 text-sm font-black tracking-widest uppercase"
                            onClick={() => setMobileOpen(false)}
                          >
                            View All Programs <ArrowRight className="h-4 w-4" />
                          </Link>
                          {item.groups?.map((group) => (
                            <div
                              key={group.value}
                              className="mb-2 ml-4 border-l pl-4 dark:border-slate-800"
                            >
                              <h4 className="text-public-primary mb-2 font-bold dark:text-white">
                                {group.title}
                              </h4>
                              {group.links.length > 0 ? (
                                group.links.map((link) => (
                                  <Link
                                    key={link.label}
                                    href={link.disabled ? '#' : link.href}
                                    className={`block py-2 text-sm text-slate-600 dark:text-slate-400 ${link.disabled ? 'cursor-not-allowed opacity-50' : 'hover:text-public-primary dark:hover:text-white'}`}
                                  >
                                    {link.label}
                                  </Link>
                                ))
                              ) : (
                                <p className="py-2 text-sm text-slate-400">Coming soon.</p>
                              )}
                            </div>
                          ))}
                        </AccordionContent>
                      </AccordionItem>
                    </Accordion>
                  ) : (
                    <Link
                      key={item.label}
                      href={item.href || '#'}
                      className="block py-3 text-base font-bold text-slate-700 dark:text-slate-200"
                    >
                      {item.label}
                    </Link>
                  )
                )}
              </div>
              <div className="mt-4 space-y-3 border-t p-6 dark:border-slate-800">
                <Button
                  asChild
                  variant="outline"
                  className="w-full dark:border-slate-800 dark:text-white"
                >
                  <Link href="/login">Login</Link>
                </Button>
                <Button asChild className="bg-public-secondary w-full text-white">
                  <Link href="/register">Register Now</Link>
                </Button>
              </div>
            </motion.nav>
          </>
        )}
      </AnimatePresence>
    </>
  )
}

