'use client'

import { useState, useEffect } from 'react'
import { useTheme } from '@/components/shared/theme-provider'
import { Monitor, Moon, Sun } from 'lucide-react'

export default function ThemeToggle({ isCollapsed = false }: { isCollapsed?: boolean }) {
  const [mounted, setMounted] = useState(false)
  const { theme, setTheme } = useTheme()

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    setMounted(true)
  }, [])

  const toggleTheme = () => {
    if (theme === 'light') setTheme('dark')
    else if (theme === 'dark') setTheme('system')
    else setTheme('light')
  }

  const renderIcon = () => {
    if (!mounted) return <div className="h-4 w-4 shrink-0" />
    if (theme === 'light') return <Sun className="h-4 w-4 shrink-0" />
    if (theme === 'dark') return <Moon className="h-4 w-4 shrink-0" />
    return <Monitor className="h-4 w-4 shrink-0" />
  }

  const renderLabel = () => {
    if (!mounted) return 'System Mode'
    if (theme === 'light') return 'Light Mode'
    if (theme === 'dark') return 'Dark Mode'
    return 'System Mode'
  }

  return (
    <button
      onClick={toggleTheme}
      className={`flex items-center gap-3 rounded-lg p-2 text-sm font-medium text-slate-400 transition-all hover:bg-white/5 hover:text-white ${
        isCollapsed ? 'justify-center' : ''
      }`}
      title={isCollapsed ? renderLabel() : undefined}
      aria-label="Toggle theme"
    >
      {mounted ? (
        theme === 'light' ? (
          <Sun className="h-4 w-4 shrink-0" aria-hidden="true" />
        ) : theme === 'dark' ? (
          <Moon className="h-4 w-4 shrink-0" aria-hidden="true" />
        ) : (
          <Monitor className="h-4 w-4 shrink-0" aria-hidden="true" />
        )
      ) : (
        <div className="h-4 w-4 shrink-0" />
      )}
      {!isCollapsed && <span className="flex-1 text-left">{renderLabel()}</span>}
    </button>
  )
}

'use client'

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'

type Theme = 'light' | 'dark' | 'system'

type ThemeContextValue = {
  theme: Theme
  setTheme: (theme: string) => void
  resolvedTheme: 'light' | 'dark'
  systemTheme: 'light' | 'dark'
  forcedTheme?: Theme
  themes: Theme[]
}

type ThemeProviderProps = {
  children: ReactNode
  attribute?: 'class' | `data-${string}`
  defaultTheme?: Theme
  forcedTheme?: Theme
  storageKey?: string
  disableTransitionOnChange?: boolean
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined)
const themes: Theme[] = ['light', 'dark', 'system']

function getSystemTheme(): 'light' | 'dark' {
  if (typeof window === 'undefined') return 'light'
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

function resolveTheme(theme: Theme, systemTheme: 'light' | 'dark') {
  return theme === 'system' ? systemTheme : theme
}

function applyTheme(
  theme: Theme,
  systemTheme: 'light' | 'dark',
  attribute: ThemeProviderProps['attribute']
) {
  if (typeof document === 'undefined') return

  const resolvedTheme = resolveTheme(theme, systemTheme)
  const root = document.documentElement

  if (attribute === 'class') {
    root.classList.remove('light', 'dark')
    root.classList.add(resolvedTheme)
  } else if (attribute?.startsWith('data-')) {
    root.setAttribute(attribute, resolvedTheme)
  }

  root.style.colorScheme = resolvedTheme
}

export function ThemeProvider({
  children,
  attribute = 'class',
  defaultTheme = 'light',
  forcedTheme,
  storageKey = 'theme',
}: ThemeProviderProps) {
  const [theme, setThemeState] = useState<Theme>(forcedTheme || defaultTheme)
  const [systemTheme, setSystemTheme] = useState<'light' | 'dark'>('light')

  useEffect(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const updateSystemTheme = () => setSystemTheme(getSystemTheme())
    updateSystemTheme()

    if (!forcedTheme) {
      const storedTheme = localStorage.getItem(storageKey)
      if (storedTheme && themes.includes(storedTheme as Theme)) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
        setThemeState(storedTheme as Theme)
      }
    }

    media.addEventListener('change', updateSystemTheme)
    return () => media.removeEventListener('change', updateSystemTheme)
  }, [forcedTheme, storageKey])

  useEffect(() => {
    applyTheme(forcedTheme || theme, systemTheme, attribute)
  }, [attribute, forcedTheme, systemTheme, theme])

  const setTheme = useCallback(
    (nextTheme: string) => {
      if (forcedTheme || !themes.includes(nextTheme as Theme)) return
      const normalizedTheme = nextTheme as Theme
      setThemeState(normalizedTheme)
      localStorage.setItem(storageKey, normalizedTheme)
    },
    [forcedTheme, storageKey]
  )

  const value = useMemo<ThemeContextValue>(
    () => ({
      theme: forcedTheme || theme,
      setTheme,
      forcedTheme,
      resolvedTheme: resolveTheme(forcedTheme || theme, systemTheme),
      systemTheme,
      themes,
    }),
    [forcedTheme, setTheme, systemTheme, theme]
  )

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
}

export function useTheme() {
  const context = useContext(ThemeContext)
  if (!context) {
    return {
      theme: 'light' as Theme,
      setTheme: () => {},
      resolvedTheme: 'light' as const,
      systemTheme: 'light' as const,
      themes,
    }
  }

  return context
}

'use client'

import * as React from 'react'
import { X, Check, ChevronsUpDown } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export interface Option {
  label: string
  value: string
}

interface MultiSelectProps {
  options: Option[]
  selected: string[]
  onChange: (selected: string[]) => void
  placeholder?: string
  className?: string
}

export function MultiSelect({
  options,
  selected,
  onChange,
  placeholder = 'Select items...',
  className,
}: MultiSelectProps) {
  const handleUnselect = (item: string) => {
    onChange(selected.filter((i) => i !== item))
  }

  const toggleOption = (value: string) => {
    if (selected.includes(value)) {
      onChange(selected.filter((s) => s !== value))
    } else {
      onChange([...selected, value])
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          className={cn(
            'flex h-auto min-h-[40px] w-full items-center justify-between rounded-xl px-3 py-2 hover:bg-transparent focus:ring-2 focus:ring-aerojet-blue focus:ring-offset-2',
            className
          )}
        >
          <div className="flex flex-wrap gap-1">
            {selected.length === 0 && (
              <span className="text-sm font-medium text-slate-400">{placeholder}</span>
            )}
            {selected.map((item) => {
              const option = options.find((o) => o.value === item)
              return (
                <Badge
                  key={item}
                  variant="secondary"
                  className="flex items-center gap-1 rounded-md px-1.5 py-0.5 text-xs font-bold text-aerojet-blue dark:bg-blue-900/30 dark:text-blue-300"
                  onClick={(e) => {
                    e.stopPropagation()
                    handleUnselect(item)
                  }}
                >
                  {option?.label || item}
                  <button
                    className="ml-1 rounded-full outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        handleUnselect(item)
                      }
                    }}
                    onMouseDown={(e) => {
                      e.preventDefault()
                      e.stopPropagation()
                    }}
                    onClick={(e) => {
                      e.preventDefault()
                      e.stopPropagation()
                      handleUnselect(item)
                    }}
                  >
                    <X className="h-3 w-3 text-slate-400 hover:text-slate-900" />
                  </button>
                </Badge>
              )
            })}
          </div>
          <ChevronsUpDown className="h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-full min-w-(--radix-dropdown-menu-trigger-width) max-h-[300px] overflow-y-auto p-1">
        {options.map((option) => (
          <DropdownMenuCheckboxItem
            key={option.value}
            checked={selected.includes(option.value)}
            onCheckedChange={() => toggleOption(option.value)}
            onSelect={(e) => e.preventDefault()}
            className="rounded-lg px-2 py-2 text-sm font-medium"
          >
            {option.label}
          </DropdownMenuCheckboxItem>
        ))}
        {options.length === 0 && (
          <div className="px-2 py-4 text-center text-xs text-slate-400">
            No options available
          </div>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'
import { useState, useMemo } from 'react'

interface UsePaginationOptions { initialPage?: number; pageSize?: number; total?: number }

export function usePagination({ initialPage = 1, pageSize = 10, total = 0 }: UsePaginationOptions = {}) {
  const [page, setPage] = useState(initialPage)
  const totalPages = Math.max(1, Math.ceil(total / pageSize))

  const goTo = (p: number) => setPage(Math.min(Math.max(1, p), totalPages))
  const next = () => goTo(page + 1)
  const prev = () => goTo(page - 1)

  return { page, pageSize, totalPages, setPage: goTo, next, prev, hasNext: page < totalPages, hasPrev: page > 1, offset: (page - 1) * pageSize }
}

'use client'
import { useState, useCallback, useMemo } from 'react'

export function useTableFilter<T extends Record<string, any>>(data: T[], searchKeys: (keyof T)[]) {
  const [search, setSearch] = useState('')
  const [filters, setFilters] = useState<Record<string, any>>({})

  const filtered = useMemo(() => {
    let result = data

    if (search) {
      const q = search.toLowerCase()
      result = result.filter((row) => searchKeys.some((key) => String(row[key] ?? '').toLowerCase().includes(q)))
    }

    Object.entries(filters).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        result = result.filter((row) => row[key] === value)
      }
    })

    return result
  }, [data, search, filters, searchKeys])

  const setFilter = useCallback((key: string, value: any) => {
    setFilters((prev) => ({ ...prev, [key]: value }))
  }, [])

  const clearFilters = useCallback(() => { setSearch(''); setFilters({}) }, [])

  return { filtered, search, setSearch, filters, setFilter, clearFilters }
}

