import { useEffect, useRef, useCallback, useState } from 'react'
import { useRealtimeExamMonitor } from '@/hooks/useRealtimeExamMonitor'
import { usePollVisibility } from '@/hooks/usePollVisibility'
import { getRealtimeClient } from '@/lib/realtime/client'

interface UseLiveExamSessionsOptions {
  classId: string
  pollIntervalMs?: number
}

export interface ExamSession {
  id: string
  status: string
  student: {
    id: string
    name: string
    email: string
    studentId: string | null
  }
  bank: {
    id: string
    name: string
    moduleCode: string
    courseCode: string
  }
  startedAt: string | null
  expiresAt: string | null
  submittedAt: string | null
  score: number | null
  totalPoints: number | null
  percentage: number | null
  passed: boolean | null
  timeRemaining: number | null
  answerCount: number
}

export function useLiveExamSessions({
  classId,
  pollIntervalMs = 15_000,
}: UseLiveExamSessionsOptions) {
  const [sessions, setSessions] = useState<ExamSession[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const sessionsRef = useRef<ExamSession[]>([])

  const updateSession = useCallback((updated: any) => {
    setSessions((prev) => {
      const idx = prev.findIndex((s) => s.id === updated.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = { ...next[idx], ...updated }
        sessionsRef.current = next
        return next
      }
      return prev
    })
  }, [])

  const insertSession = useCallback((inserted: any) => {
    setSessions((prev) => {
      if (prev.some((s) => s.id === inserted.id)) return prev
      const next = [inserted, ...prev]
      sessionsRef.current = next
      return next
    })
  }, [])

  const fetchSessions = useCallback(async () => {
    try {
      const res = await fetch(`/api/instructor/exams/classes/${classId}/sessions`)
      if (!res.ok) {
        if (res.status === 403 || res.status === 404) {
          setSessions([])
          setLoading(false)
          return
        }
        throw new Error(`Failed to fetch sessions: ${res.status}`)
      }
      const data = (await res.json()) as ExamSession[]
      setSessions(data)
      sessionsRef.current = data
      setLoading(false)
      setError(null)
    } catch (err) {
      console.error('[useLiveExamSessions] fetch error:', err)
      setError(err instanceof Error ? err.message : 'Unknown error')
      setLoading(false)
    }
  }, [classId])

  const { isLive } = useRealtimeExamMonitor({
    classId,
    onSessionUpdate: updateSession,
    onSessionInsert: insertSession,
    enabled: true,
  })

  const supabase = getRealtimeClient()
  const shouldPoll = !supabase || !isLive

  usePollVisibility({
    intervalMs: pollIntervalMs,
    onTick: fetchSessions,
    enabled: shouldPoll,
  })

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchSessions()
  }, [fetchSessions])

  useEffect(() => {
    return () => {
      sessionsRef.current = []
    }
  }, [])

  return {
    sessions,
    loading,
    error,
    isLive,
    refetch: fetchSessions,
  }
}

'use client'

import { useEffect, useRef, useCallback, useState } from 'react'
import { getRealtimeClient } from '@/lib/realtime/client'

interface UseRealtimeExamMonitorOptions {
  classId: string
  onSessionUpdate: (session: any) => void
  onSessionInsert: (session: any) => void
  enabled?: boolean
}

const STUDENT_THROTTLE_MS = 5_000
const DEBOUNCE_MS = 1_000
const POLL_INTERVAL_MS = 15_000
const RECONNECT_BACKOFF_MS = 5_000

export function useRealtimeExamMonitor({
  classId,
  onSessionUpdate,
  onSessionInsert,
  enabled = true,
}: UseRealtimeExamMonitorOptions) {
  const [isLive, setIsLive] = useState(false)
  const channelRef = useRef<ReturnType<ReturnType<typeof getRealtimeClient> extends null ? never : ReturnType<NonNullable<ReturnType<typeof getRealtimeClient>>['channel']>> | null>(null)
  const lastUpdateRef = useRef<Map<string, number>>(new Map())
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const reconnectAttemptRef = useRef(0)
  const maxReconnectAttempts = 10

  const flushDebounced = useCallback(() => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current)
      debounceTimerRef.current = null
    }
  }, [])

  const scheduleDebounced = useCallback(
    (fn: () => void) => {
      flushDebounced()
      debounceTimerRef.current = setTimeout(fn, DEBOUNCE_MS)
    },
    [flushDebounced]
  )

  const teardown = useCallback(() => {
    flushDebounced()
    if (reconnectTimerRef.current) {
      clearTimeout(reconnectTimerRef.current)
      reconnectTimerRef.current = null
    }
    const supabase = getRealtimeClient()
    if (supabase && channelRef.current) {
      void supabase.removeChannel(channelRef.current)
      channelRef.current = null
    }
    setIsLive(false)
  }, [flushDebounced])

  useEffect(() => {
    if (!enabled) {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
      teardown()
      return
    }

    const supabase = getRealtimeClient()
    if (!supabase) {
      setIsLive(false)
      return
    }

    const channelName = `exam_sessions:classId:${classId}`
    const channel = supabase
      .channel(channelName)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'internal_exam_sessions',
          filter: `classId=eq.${classId}`,
        },
        (payload: { new: Record<string, any> }) => {
          const studentId = (payload.new as any)?.studentId as string | undefined
          if (!studentId) return

          const now = Date.now()
          const last = lastUpdateRef.current.get(studentId) ?? 0
          if (now - last < STUDENT_THROTTLE_MS) return

          lastUpdateRef.current.set(studentId, now)

          scheduleDebounced(() => {
            onSessionInsert(payload.new as any)
          })
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'internal_exam_sessions',
          filter: `classId=eq.${classId}`,
        },
        (payload: { new: Record<string, any> }) => {
          const studentId = (payload.new as any)?.studentId as string | undefined
          if (!studentId) return

          const now = Date.now()
          const last = lastUpdateRef.current.get(studentId) ?? 0
          if (now - last < STUDENT_THROTTLE_MS) return

          lastUpdateRef.current.set(studentId, now)

          scheduleDebounced(() => {
            onSessionUpdate(payload.new as any)
          })
        }
      )
      .subscribe((status: string, err?: Error) => {
        if (status === 'SUBSCRIBED') {
          setIsLive(true)
          reconnectAttemptRef.current = 0
        } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
          setIsLive(false)
          console.warn(`[Realtime] exam monitor ${channelName}:`, status, err)

          if (reconnectAttemptRef.current < maxReconnectAttempts) {
            reconnectAttemptRef.current += 1
            reconnectTimerRef.current = setTimeout(() => {
              teardown()
              // Re-create subscription on next effect tick
              setIsLive(false)
            }, RECONNECT_BACKOFF_MS * reconnectAttemptRef.current)
          }
        }
      })

    channelRef.current = channel

    return () => {
      teardown()
    }
  }, [classId, enabled, onSessionUpdate, onSessionInsert, scheduleDebounced, teardown])

  return { isLive, flushDebounced }
}

import { cache } from 'react'
import prisma from '@/lib/prisma/client'
import { resolveEffectiveEnrollmentType, resolveEffectivePathwayCode } from '@/lib/enrollment/pathway'

export type PaymentAccessLevel = 'FULL_ACCESS' | 'SEAT_ONLY' | 'RESTRICTED'

export type FeatureType = 'courses' | 'classes' | 'exams' | 'materials' | 'milestones' | 'pools' | 'wallet' | 'wallet'

const FEATURE_ACCESS_MATRIX: Record<PaymentAccessLevel, FeatureType[]> = {
  FULL_ACCESS: ['courses', 'classes', 'exams', 'materials', 'milestones', 'pools', 'wallet'],
  SEAT_ONLY: ['milestones', 'pools'],
  RESTRICTED: ['milestones', 'pools'],
}

export async function getStudentPaymentAccessLevel(
  userId: string,
  preFetchedData?: {
    profile?: any
    enrollment?: any
  }
): Promise<PaymentAccessLevel> {
  const { isModular, isExamOnly, enrollmentType, pathwayCode } = await getStudentStatus(userId, preFetchedData?.profile)

  if (isModular || isExamOnly) {
    return 'FULL_ACCESS'
  }

  const ftEnrollment = preFetchedData?.enrollment || await prisma.fullTimeEnrollment.findFirst({
    where: { studentId: userId },
    include: {
      milestones: {
        where: { yearNumber: 1 },
      },
    },
  })

  if (!ftEnrollment) {
    return 'RESTRICTED'
  }

  // Handle case where enrollment was fetched without milestones
  const milestones = ftEnrollment.milestones || []
  
  const seatPaid = milestones.some(
    (m: any) => m.milestoneType === 'SEAT_CONFIRMATION' && m.status === 'PAID'
  )

  if (!seatPaid) {
    return 'RESTRICTED'
  }

  const sem1Paid = milestones.some(
    (m: any) => m.milestoneType === 'SEM1_DUE' && m.status === 'PAID'
  )

  if (!sem1Paid) {
    return 'SEAT_ONLY'
  }

  return 'FULL_ACCESS'
}

/**
 * Request-scoped student status resolver.
 * Wrapped in React.cache() so it is called at most ONCE per request,
 * even if multiple pages/components call it in parallel. This eliminates
 * the 3–5 redundant studentProfile DB queries per page load.
 */
export const getStudentStatus = cache(async (userId: string, preFetchedProfile?: any) => {
  const profile = preFetchedProfile || await prisma.studentProfile.findUnique({
    where: { userId },
    select: {
      enrollmentType: true,
      pathwayRel: { select: { code: true } },
    },
  })

  const enrollmentType = profile?.enrollmentType
  const pathwayCode = profile?.pathwayRel?.code
  const effectiveCode = resolveEffectivePathwayCode({ enrollmentType, pathwayCode })
  const effectiveEnrollmentType = resolveEffectiveEnrollmentType({ enrollmentType, pathwayCode })
  const isExamOnly = effectiveEnrollmentType === 'EXAM_ONLY'
  const isModular = effectiveEnrollmentType === 'MODULAR'
  const isFullTime = effectiveEnrollmentType === 'FULL_TIME'

  return {
    isFullTime,
    isExamOnly,
    isModular,
    enrollmentType: effectiveEnrollmentType,
    pathwayCode,
    effectiveCode,
  }
})

export async function canAccessFeature(userId: string, feature: FeatureType): Promise<boolean> {
  const accessLevel = await getStudentPaymentAccessLevel(userId)
  return FEATURE_ACCESS_MATRIX[accessLevel].includes(feature)
}

export async function getEnrollmentMilestoneStatus(
  userId: string,
  preFetchedData?: {
    profile?: any
    enrollment?: any
  }
) {
  const { isExamOnly, isModular, enrollmentType, pathwayCode } = await getStudentStatus(userId, preFetchedData?.profile)

  if (isModular || isExamOnly) {
    const label = isExamOnly ? 'Exam-Only Pathway' : 'Modular Programme'
    return {
      hasEnrollment: true,
      seatPaid: true,
      sem1Paid: true,
      sem2Paid: true,
      currentYear: null,
      programmeName: label,
      milestones: [],
    }
  }

  const ftEnrollment = preFetchedData?.enrollment || await prisma.fullTimeEnrollment.findFirst({
    where: { studentId: userId },
    include: {
      programme: true,
      milestones: {
        orderBy: [{ yearNumber: 'asc' }, { dueDate: 'asc' }],
      },
    },
  })

  if (!ftEnrollment) {
    return {
      hasEnrollment: false,
      seatPaid: false,
      sem1Paid: false,
      sem2Paid: false,
      currentYear: null,
      programmeName: 'Full-Time Programme',
      milestones: [],
    }
  }

  const milestones = ftEnrollment.milestones || []

  const seatPaid = milestones.some(
    (m: any) => m.milestoneType === 'SEAT_CONFIRMATION' && m.status === 'PAID'
  )
  const sem1Paid = milestones.some(
    (m: any) => m.milestoneType === 'SEM1_DUE' && m.status === 'PAID'
  )
  const sem2Paid = milestones.some(
    (m: any) => m.milestoneType === 'SEM2_DUE' && m.status === 'PAID'
  )

  return {
    hasEnrollment: true,
    seatPaid,
    sem1Paid,
    sem2Paid,
    currentYear: ftEnrollment.currentYearNumber,
    programmeName: ftEnrollment.programme?.name || 'Full-Time Programme',
    milestones: milestones.map((m: any) => ({
      id: m.id,
      type: m.milestoneType,
      yearNumber: m.yearNumber,
      amountDue: Number(m.amountDue),
      status: m.status,
      dueDate: m.dueDate,
      paidAt: m.paidAt,
    })),
  }
}

export async function getNextDueMilestone(userId: string) {
  const status = await getEnrollmentMilestoneStatus(userId)

  if (!status.hasEnrollment) return null

  const unpaidMilestones = status.milestones.filter(
    (m: any) => m.status === 'DUE' || m.status === 'OVERDUE'
  )

  if (unpaidMilestones.length === 0) return null

  return unpaidMilestones.sort(
    (a: any, b: any) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime()
  )[0]
}

