import { prismaUnfiltered } from '@/lib/prisma/client'
import type { AttendanceStatus } from '@prisma/client'
import { getAuthSession } from '@/lib/auth/helpers'
import { startOfDay, endOfDay, startOfWeek, endOfWeek } from 'date-fns'
