import { serializePrisma } from '@/lib/utils/serialization'
import { revalidatePath } from 'next/cache'

export async function getAdminResources() {
  await requireStaff()

  const resources = await prismaUnfiltered.generalResource.findMany({
    include: {
      courses: { select: { id: true, code: true, name: true } },
      pathways: { select: { id: true, code: true, name: true } },
    },
    orderBy: { createdAt: 'desc' },
  })

  return serializePrisma(resources)
}

export async function getResourceLinkingOptions() {
  await requireStaff()

  const [courses, pathways] = await Promise.all([
    prismaUnfiltered.course.findMany({
      where: { isActive: true },
      select: { id: true, code: true, name: true },
      orderBy: { code: 'asc' },
    }),
    prismaUnfiltered.studyPathwayModel.findMany({
      select: { id: true, code: true, name: true },
      orderBy: { name: 'asc' },
    }),
  ])

  return serializePrisma({ courses, pathways })
}

export async function getStudentResources() {
  const session = await requireAuth()
  const userId = session.id

  // 1. Get student status and pathway
  const profile = await prismaUnfiltered.studentProfile.findUnique({
    where: { userId },
    select: { pathwayId: true }
  })

  // 2. Get all "bought" or enrolled courses for the student
  // This includes full-time enrollments and modular ones
  const [ftEnrollments, modularEnrollments] = await Promise.all([
    prismaUnfiltered.enrollment.findMany({
      where: { 
        userId, 
        status: { in: ['ENROLLED', 'APPROVED', 'ACTIVE'] } 
      },
      select: { courseId: true }
    }),
    prismaUnfiltered.modularEnrollment.findMany({
      where: { 
        studentId: userId, 
        status: { in: ['ENROLLED', 'APPROVED', 'ACTIVE'] } 
      },
      include: { package: true }
    })
  ])

  const enrolledCourseIds = new Set(ftEnrollments.map(e => e.courseId))

  // Add modular course IDs (ModularPackage has modulesIncluded as codes, we need IDs)
  // We'll fetch course IDs for those codes
  const allModularCodes = modularEnrollments.flatMap(e => e.package.modulesIncluded)
  if (allModularCodes.length > 0) {
    const modularCourses = await prismaUnfiltered.course.findMany({
      where: { code: { in: allModularCodes } },
      select: { id: true }
    })
    modularCourses.forEach(c => enrolledCourseIds.add(c.id))
  }

  const courseIds = Array.from(enrolledCourseIds)

  // 3. Fetch resources
  const resources = await prismaUnfiltered.generalResource.findMany({
    where: {
      showToStudents: true,
      AND: [
        {
          OR: [
            { courses: { none: {} } }, // Global resource
            { courses: { some: { id: { in: courseIds } } } } // Linked to enrolled course
          ]
        },
        {
          OR: [
            { pathways: { none: {} } }, // Global or not pathway-restricted
            { pathways: { some: { id: profile?.pathwayId || 'none' } } } // Linked to their pathway
          ]
        }
      ]
    },
    include: {
      courses: { select: { id: true, code: true } },
    },
    orderBy: {
      createdAt: 'desc',
    },
  })

  return serializePrisma(resources)
}

export async function upsertResource(data: {
  id?: string
  name: string
  description?: string
  url: string
  type: string
  category: string
  showToInstructors: boolean
  showToStaff: boolean
  showToStudents: boolean
  courseIds?: string[]
  pathwayIds?: string[]
}) {
  await requireStaff()

  const { courseIds = [], pathwayIds = [], ...rest } = data

  const resource = await prismaUnfiltered.generalResource.upsert({
    where: { id: data.id || 'new' },
    update: {
      ...rest,
      courses: {
        set: courseIds.map(id => ({ id }))
      },
      pathways: {
        set: pathwayIds.map(id => ({ id }))
      }
    },
    create: {
      ...rest,
      courses: {
        connect: courseIds.map(id => ({ id }))
      },
      pathways: {
        connect: pathwayIds.map(id => ({ id }))
      }
    },
  })

  revalidatePath('/instructor/resources')
  revalidatePath('/staff/resources')
  revalidatePath('/student/resources')
  return serializePrisma(resource)
}

export async function deleteResource(id: string) {
  await requireStaff()

  await prismaUnfiltered.generalResource.delete({
    where: { id },
  })

  revalidatePath('/instructor/resources')
  revalidatePath('/staff/resources')
  revalidatePath('/student/resources')
  return { success: true }
}

/**
 * A.1.b — Dashboard alerts.
 *
 * Five cheap query checks that surface "things that need an admin's eye
 * today". Cached 5 minutes via `unstable_cache`; the AlertsCenter polls every
 * 60 seconds and re-fetches via revalidateTag if a fresh tick is overdue.
 */

import 'server-only'
import { unstable_cache } from 'next/cache'
import { prismaUnfiltered } from '@/lib/prisma/client'

export interface DashboardAlert {
  id: string
  severity: 'INFO' | 'WARNING' | 'CRITICAL'
  title: string
  description: string
  href?: string
  count?: number
}

export const DASHBOARD_ALERTS_TAG = 'dashboard-alerts'

async function compute(): Promise<DashboardAlert[]> {
  const now = new Date()
  const todayMinus7 = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
  const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000)
  const sevenDaysOut = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000)

  const [
    pendingPayments,
    overdueDsr,
    failingFraud,
    expiringBundles,
    mirrorBacklog,
    emailFailures24h,
    pendingExamReports,
  ] = await Promise.all([
    // 1) Payments awaiting review for >7 days
    prismaUnfiltered.payment.count({
      where: { status: 'PENDING', createdAt: { lt: todayMinus7 } },
    }).catch(() => 0),

    // 2) DSR with dueBy in the past and still open
    prismaUnfiltered.dataSubjectRequest.count({
      where: {
        dueBy: { lt: now },
        status: { in: ['RECEIVED', 'IN_PROGRESS', 'AWAITING_USER'] },
      },
    }).catch(() => 0),

    // 3) Referrals with fraudScore >= 50 awaiting review
    prismaUnfiltered.referral.count({
      where: { fraudScore: { gte: 50 }, reviewedAt: null },
    }).catch(() => 0),

    // 4) ExamBundles expiring in next 7 days with unused resits
    prismaUnfiltered.examBundle.count({
      where: {
        validUntil: { gte: tomorrow, lte: sevenDaysOut },
        status: { in: ['ACTIVE'] as any },
      },
    }).catch(() => 0),

    // 5) FileUpload rows older than 24h still unmirrored
    prismaUnfiltered.fileUpload.count({
      where: {
        mirroredAt: null,
        supabasePath: { not: null },
        createdAt: { lt: new Date(now.getTime() - 24 * 60 * 60 * 1000) },
      },
    }).catch(() => 0),

    // 6) Email deliveries that failed in the last 24h
    prismaUnfiltered.emailDelivery.count({
      where: {
        status: 'FAILED',
        createdAt: { gte: new Date(now.getTime() - 24 * 60 * 60 * 1000) },
      },
    }).catch(() => 0),

    // 7) Internal exam reports awaiting staff review
    prismaUnfiltered.internalExamReport.count({
      where: { status: 'PENDING' },
    }).catch(() => 0),
  ])

  const alerts: DashboardAlert[] = []

  if (pendingPayments > 0) {
    alerts.push({
      id: 'pending-payments',
      severity: pendingPayments > 10 ? 'CRITICAL' : 'WARNING',
      title: `${pendingPayments} payment${pendingPayments === 1 ? '' : 's'} awaiting reconciliation > 7 days`,
      description: 'Old payment proofs slow the admissions queue and may breach our SLA.',
      href: '/staff/payments?status=PENDING',
      count: pendingPayments,
    })
  }

  if (overdueDsr > 0) {
    alerts.push({
      id: 'overdue-dsr',
      severity: 'CRITICAL',
      title: `${overdueDsr} GDPR request${overdueDsr === 1 ? '' : 's'} past 30-day SLA`,
      description: 'GDPR Article 12(3) requires response within 30 days. Resolve immediately.',
      href: '/staff/gdpr',
      count: overdueDsr,
    })
  }

  if (failingFraud > 0) {
    alerts.push({
      id: 'fraud-referrals',
      severity: 'WARNING',
      title: `${failingFraud} referral${failingFraud === 1 ? '' : 's'} flagged for fraud review`,
      description: 'Fraud score ≥ 50. Disqualify or clear before payout.',
      href: '/staff/referrals?minFraud=50',
      count: failingFraud,
    })
  }

  if (expiringBundles > 0) {
    alerts.push({
      id: 'expiring-bundles',
      severity: 'INFO',
      title: `${expiringBundles} exam bundle${expiringBundles === 1 ? '' : 's'} expiring this week`,
      description: 'Students may need a heads-up to use remaining sittings.',
      href: '/staff/exams?filter=expiring',
      count: expiringBundles,
    })
  }

  if (mirrorBacklog > 0) {
    alerts.push({
      id: 'mirror-backlog',
      severity: mirrorBacklog > 100 ? 'WARNING' : 'INFO',
      title: `${mirrorBacklog} UploadThing file${mirrorBacklog === 1 ? '' : 's'} not yet mirrored to Supabase`,
      description: 'The nightly mirror cron may need attention.',
      href: '/staff/admin/permissions', // placeholder — no admin "sync" page yet
      count: mirrorBacklog,
    })
  }

  if (emailFailures24h > 0) {
    alerts.push({
      id: 'email-failures',
      severity: emailFailures24h >= 10 ? 'CRITICAL' : 'WARNING',
      title: `${emailFailures24h} email${emailFailures24h === 1 ? '' : 's'} failed to deliver in the last 24h`,
      description:
        'Transient Resend errors are retried automatically; persistent failures may signal a domain, DNS, or rate-limit issue.',
      href: '/staff/settings?tab=email-delivery',
      count: emailFailures24h,
    })
  }

  if (pendingExamReports > 0) {
    alerts.push({
      id: 'exam-reports',
      severity: pendingExamReports >= 5 ? 'WARNING' : 'INFO',
      title: `${pendingExamReports} internal exam report${pendingExamReports === 1 ? '' : 's'} awaiting review`,
      description:
        'Students have flagged issues with submitted exams (typo, ambiguous answer, etc.). Review in the exam Operations dashboard before publishing results.',
      href: '/staff/exams/internal?view=operations',
      count: pendingExamReports,
    })
  }

  return alerts
}

export const getDashboardAlerts = unstable_cache(compute, ['dashboard-alerts'], {
  revalidate: 300, // 5 minutes
  tags: [DASHBOARD_ALERTS_TAG],
})

import 'server-only'
import { prismaUnfiltered } from '@/lib/prisma/client'

// ============================================================================
// Event taxonomy — canonical list of tracked events
// ============================================================================

export type AnalyticsEventName =
  | 'PAGE_VIEW'
  | 'REGISTRATION_STARTED'
  | 'REGISTRATION_COMPLETED'
  | 'PAYMENT_SUBMITTED'
  | 'PAYMENT_APPROVED'
  | 'ENROLLMENT_CREATED'
  | 'COURSE_ACCESSED'
  | 'EXAM_POOL_JOINED'
  | 'EXAM_COMPLETED'
  | 'FEATURE_USED'
  | 'SEARCH_PERFORMED'
  | 'DOCUMENT_UPLOADED'
  | 'WALLET_TOP_UP'
  | 'REFERRAL_CLICKED'
  | 'TOUR_STARTED'
  | 'TOUR_COMPLETED'

export type AnalyticsEntity =
  | 'PAGE'
  | 'USER'
  | 'PAYMENT'
  | 'ENROLLMENT'
  | 'COURSE'
  | 'EXAM'
  | 'FEATURE'
  | 'SEARCH'
  | 'DOCUMENT'
  | 'WALLET'
  | 'REFERRAL'
  | 'TOUR'

// ============================================================================
// Payload types for structured events
// ============================================================================

export interface PageViewPayload {
  path: string
  referrer?: string
  device?: 'mobile' | 'tablet' | 'desktop'
}

export interface RegistrationPayload {
  programmeChoice?: string
  licenseCategories?: string[]
  source?: string
}

export interface PaymentPayload {
  amount?: number
  currency?: string
  method?: string
  paymentId?: string
}

export interface EnrollmentPayload {
  enrollmentId?: string
  courseId?: string
  courseCode?: string
  enrollmentType?: string
}

export interface ExamPayload {
  poolId?: string
  moduleCode?: string
  score?: number
  passed?: boolean
}

export interface FeaturePayload {
  feature: string
  action?: string
}

export interface SearchPayload {
  query: string
  resultsCount?: number
}

export interface DocumentPayload {
  documentType: string
  fileName?: string
}

export interface WalletPayload {
  amount?: number
  currency?: string
  method?: string
}

export interface ReferralPayload {
  referralCode?: string
  landingPage?: string
}

export interface TourPayload {
  tourName: string
  stepReached?: number
  totalSteps?: number
}

export type AnalyticsPayload =
  | PageViewPayload
  | RegistrationPayload
  | PaymentPayload
  | EnrollmentPayload
  | ExamPayload
  | FeaturePayload
  | SearchPayload
  | DocumentPayload
  | WalletPayload
  | ReferralPayload
  | TourPayload
  | Record<string, any>

// ============================================================================
// Event validation
// ============================================================================

export const REQUIRED_PAYLOAD_FIELDS: Record<AnalyticsEventName, string[]> = {
  PAGE_VIEW: ['path'],
  REGISTRATION_STARTED: [],
  REGISTRATION_COMPLETED: ['programmeChoice'],
  PAYMENT_SUBMITTED: ['amount', 'currency'],
  PAYMENT_APPROVED: ['amount', 'currency', 'paymentId'],
  ENROLLMENT_CREATED: ['enrollmentId', 'courseId'],
  COURSE_ACCESSED: ['courseId'],
  EXAM_POOL_JOINED: ['poolId'],
  EXAM_COMPLETED: ['poolId'],
  FEATURE_USED: ['feature'],
  SEARCH_PERFORMED: ['query'],
  DOCUMENT_UPLOADED: ['documentType'],
  WALLET_TOP_UP: ['amount', 'currency'],
  REFERRAL_CLICKED: [],
  TOUR_STARTED: ['tourName'],
  TOUR_COMPLETED: ['tourName'],
}

export function validatePayload(event: AnalyticsEventName, data: Record<string, any>): Record<string, any> {
  const required = REQUIRED_PAYLOAD_FIELDS[event] || []
  const missing = required.filter((field) => !(field in data))
  if (missing.length > 0) {
    console.warn(`[ANALYTICS] Missing required fields for ${event}: ${missing.join(', ')}`)
  }
  return data
}

// ============================================================================
// trackEvent — fire-and-forget, never throws
// ============================================================================

export async function trackEvent(
  event: AnalyticsEventName,
  data: AnalyticsPayload = {},
  userId?: string,
): Promise<void> {
  const payload = validatePayload(event, data as Record<string, any>)

  const resolvedUserId = userId ?? payload.userId

  // Validate that the user exists before tracking (if userId is provided)
  if (resolvedUserId) {
    try {
      const userExists = await prismaUnfiltered.user.findUnique({
        where: { id: resolvedUserId },
        select: { id: true },
      })
      if (!userExists) {
        console.warn(`[ANALYTICS] Skipping event ${event}: user ${resolvedUserId} does not exist`)
        return
      }
    } catch (err) {
      // If validation fails, log but don't block the event
      console.warn(`[ANALYTICS] Could not validate user ${resolvedUserId}:`, err)
    }
  }

  try {
    await prismaUnfiltered.auditLog.create({
      data: {
        action: event,
        entity: 'ANALYTICS',
        entityId: 'system',
        userId: resolvedUserId,
        changes: payload,
      },
    })
  } catch (err) {
    // Analytics must never break the user flow
    console.error('[ANALYTICS] Failed to track event:', event, err)
  }
}

