}

const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

export async function generateFinancialPDF(data: any, year: number, month: number) {
  const { summary, revenueByType, paymentMethods, monthlyData, paymentStatus } = data;
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 14;

  const periodLabel = `${MONTH_NAMES[month - 1]} ${year}`;
  const generatedAt = new Date().toLocaleString('en-GB', { dateStyle: 'full', timeStyle: 'short' });

  // Add Logo Placeholder / Header
  doc.setFontSize(22);
  doc.setTextColor(15, 43, 91); // #0F2B5B
  doc.text('Financial Report', margin, 25);
  
  doc.setFontSize(10);
  doc.setTextColor(100, 116, 139); // #64748b
  doc.text(`Aerojet Aviation Training Academy — ${periodLabel}`, margin, 32);
  
  doc.setFontSize(8);
  doc.text(`Generated: ${generatedAt}`, pageWidth - margin - 50, 32);

  // Line separator
  doc.setDrawColor(15, 43, 91);
  doc.setLineWidth(1);
  doc.line(margin, 38, pageWidth - margin, 38);

  // KPI Summary
  doc.setFontSize(12);
  doc.setTextColor(15, 43, 91);
  doc.text('Executive Summary', margin, 50);

  const kpiData = [
    ['Total Revenue (Year)', formatCurrency(summary.totalRevenue)],
    ['Revenue (Month)', formatCurrency(summary.revenueThisMonth)],
    ['Pending Payments', formatCurrency(summary.pendingAmount)],
    ['Avg Transaction', formatCurrency(summary.avgTransactionValue)],
  ];

  doc.autoTable({
    startY: 55,
    head: [['Metric', 'Value']],
    body: kpiData,
    theme: 'striped',
    headStyles: { fillColor: [15, 43, 91] },
    margin: { left: margin, right: margin },
  });

  // Monthly Data
  const lastY = (doc as any).lastAutoTable.finalY;
  doc.setFontSize(12);
  doc.text(`Monthly Breakdown — ${year}`, margin, lastY + 15);

  const monthlyRows = monthlyData.map((m: any) => [
    m.month,
    formatCurrency(m.revenue),
    m.count.toString(),
  ]);

  doc.autoTable({
    startY: lastY + 20,
    head: [['Month', 'Revenue', 'Transactions']],
    body: monthlyRows,
    theme: 'grid',
    headStyles: { fillColor: [15, 43, 91] },
    margin: { left: margin, right: margin },
  });

  // Program Type & Status
  const lastY2 = (doc as any).lastAutoTable.finalY;
  
  // Two columns roughly
  doc.text('Revenue by Programme', margin, lastY2 + 15);
  const progRows = revenueByType
    .filter((r: any) => r.value > 0)
    .map((r: any) => [r.name, formatCurrency(r.value), `${r.percentage}%`]);

  doc.autoTable({
    startY: lastY2 + 20,
    head: [['Programme', 'Amount', 'Percentage']],
    body: progRows,
    theme: 'striped',
    headStyles: { fillColor: [15, 43, 91] },
    margin: { left: margin, right: pageWidth / 2 + 5 },
  });

  const lastY3 = (doc as any).lastAutoTable.finalY;
  doc.text('Payment Status', pageWidth / 2 + 10, lastY2 + 15);
  const statusRows = paymentStatus.map((s: any) => [s.status, formatCurrency(s.amount), s.count.toString()]);

  doc.autoTable({
    startY: lastY2 + 20,
    head: [['Status', 'Amount', 'Count']],
    body: statusRows,
    theme: 'striped',
    headStyles: { fillColor: [15, 43, 91] },
    margin: { left: pageWidth / 2 + 10, right: margin },
  });

  // Footer
  const pageCount = (doc as any).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(
      'Aerojet Aviation Training Academy — Confidential',
      margin,
      doc.internal.pageSize.getHeight() - 10
    );
    doc.text(
      `Page ${i} of ${pageCount}`,
      pageWidth - margin - 15,
      doc.internal.pageSize.getHeight() - 10
    );
  }

  doc.save(`AATA_Financial_Report_${periodLabel.replace(/\s+/g, '_')}.pdf`);
}

import 'server-only'
import { prismaUnfiltered as defaultPrisma } from '@/lib/prisma/client'
import { subDays, subMonths, startOfDay, endOfDay, startOfMonth, endOfMonth } from 'date-fns'
import { AnalyticsEventName, AnalyticsEntity } from './events'

// Allow injecting a prisma client for testing
let prisma = defaultPrisma

export function __setPrisma(client: typeof defaultPrisma) {
  prisma = client
}

// ============================================================================
// Types
// ============================================================================

export interface FunnelStep {
  event: AnalyticsEventName
  label: string
  count: number
  conversionRate: number // from step 0
  dropoffRate: number // from previous step
}

export interface FunnelMetrics {
  name: string
  from: Date
  to: Date
  steps: FunnelStep[]
  overallConversion: number
}

export interface RetentionCohort {
  cohortDate: string
  cohortSize: number
  d1: { count: number; rate: number }
  d7: { count: number; rate: number }
  d30: { count: number; rate: number }
}

export interface FeatureAdoption {
  feature: string
  totalUsers: number
  adopters: number
  adoptionRate: number
  avgTimeToAdoptDays: number | null
}

export interface PageViewMetrics {
  path: string
  views: number
  uniqueVisitors: number
  avgViewsPerVisitor: number
}

export interface UserJourneyEvent {
  event: AnalyticsEventName
  entity: string
  timestamp: string
  payload: Record<string, any>
}

// ============================================================================
// Funnel Metrics
// ============================================================================

const STANDARD_FUNNELS: Record<string, AnalyticsEventName[]> = {
  registration: [
    'REGISTRATION_STARTED',
    'REGISTRATION_COMPLETED',
    'PAYMENT_SUBMITTED',
    'PAYMENT_APPROVED',
  ],
  enrollment: ['REGISTRATION_COMPLETED', 'ENROLLMENT_CREATED', 'COURSE_ACCESSED'],
  exam: ['EXAM_POOL_JOINED', 'EXAM_COMPLETED'],
  payment: ['PAYMENT_SUBMITTED', 'PAYMENT_APPROVED'],
}

export async function getFunnelMetrics(
  funnelName: keyof typeof STANDARD_FUNNELS = 'registration',
  from?: Date,
  to?: Date
): Promise<FunnelMetrics> {
  const now = new Date()
  const start = from ?? subDays(now, 30)
  const end = to ?? now
  const events = STANDARD_FUNNELS[funnelName]

  const counts = await Promise.all(
    events.map((event) =>
      prisma.auditLog.count({
        where: {
          action: event,
          entity: 'ANALYTICS',
          createdAt: { gte: start, lt: end },
        },
      })
    )
  )

  const steps: FunnelStep[] = events.map((event, i) => {
    const count = counts[i]
    const previousCount = i > 0 ? counts[i - 1] : count
    return {
      event,
      label: formatEventLabel(event),
      count,
      conversionRate: previousCount > 0 ? Math.round((count / previousCount) * 100) : 0,
      dropoffRate:
        i > 0 && previousCount > 0
          ? Math.round(((previousCount - count) / previousCount) * 100)
          : 0,
    }
  })

  const overallConversion =
    steps.length >= 2 && steps[0].count > 0
      ? Math.round((steps[steps.length - 1].count / steps[0].count) * 100)
      : 0

  return {
    name: funnelName,
    from: start,
    to: end,
    steps,
    overallConversion,
  }
}

function formatEventLabel(event: string): string {
  return event.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())
}

// ============================================================================
// Cohort Retention
// ============================================================================

export async function getCohortRetention(cohortDate?: Date): Promise<RetentionCohort[]> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const cohortRetention: any[] = []

  // Get users who registered in the specified month
  const targetMonth = cohortDate
    ? new Date(cohortDate.getFullYear(), cohortDate.getMonth(), 1)
    : startOfMonth(subMonths(new Date(), 1))
  const nextMonth = startOfMonth(subMonths(targetMonth, -1))

  const cohortUsers = await prisma.user.findMany({
    where: {
      createdAt: { gte: targetMonth, lt: nextMonth },
      deletedAt: null,
    },
    select: { id: true, createdAt: true },
  })

  if (cohortUsers.length === 0) {
    return []
  }

  const userIds = cohortUsers.map((u: { id: string }) => u.id)

  // Check activity at D1, D7, D30
  const [d1Active, d7Active, d30Active] = await Promise.all([
    prisma.auditLog.findMany({
      where: {
        userId: { in: userIds },
        createdAt: {
          gte: new Date(targetMonth.getTime() + 1 * 24 * 60 * 60 * 1000),
          lt: new Date(targetMonth.getTime() + 2 * 24 * 60 * 60 * 1000),
        },
      },
      select: { userId: true },
      distinct: ['userId'],
    }),
    prisma.auditLog.findMany({
      where: {
        userId: { in: userIds },
        createdAt: {
          gte: new Date(targetMonth.getTime() + 7 * 24 * 60 * 60 * 1000),
          lt: new Date(targetMonth.getTime() + 8 * 24 * 60 * 60 * 1000),
        },
      },
      select: { userId: true },
      distinct: ['userId'],
    }),
    prisma.auditLog.findMany({
      where: {
        userId: { in: userIds },
        createdAt: {
          gte: new Date(targetMonth.getTime() + 30 * 24 * 60 * 60 * 1000),
          lt: new Date(targetMonth.getTime() + 31 * 24 * 60 * 60 * 1000),
        },
      },
      select: { userId: true },
      distinct: ['userId'],
    }),
  ])

  const d1Set = new Set(
    d1Active
      .map((e: { userId: string | null }) => e.userId)
      .filter((id): id is string => Boolean(id))
  )
  const d7Set = new Set(
    d7Active
      .map((e: { userId: string | null }) => e.userId)
      .filter((id): id is string => Boolean(id))
  )
  const d30Set = new Set(
    d30Active
      .map((e: { userId: string | null }) => e.userId)
      .filter((id): id is string => Boolean(id))
  )

  return [
    {
      cohortDate: targetMonth.toISOString(),
      cohortSize: cohortUsers.length,
      d1: {
        count: d1Set.size,
        rate: cohortUsers.length > 0 ? Math.round((d1Set.size / cohortUsers.length) * 100) : 0,
      },
      d7: {
        count: d7Set.size,
        rate: cohortUsers.length > 0 ? Math.round((d7Set.size / cohortUsers.length) * 100) : 0,
      },
      d30: {
        count: d30Set.size,
        rate: cohortUsers.length > 0 ? Math.round((d30Set.size / cohortUsers.length) * 100) : 0,
      },
    },
  ]
}

// ============================================================================
// Feature Adoption
// ============================================================================

export async function getFeatureAdoption(
  feature: string,
  from?: Date,
  to?: Date
): Promise<FeatureAdoption | null> {
  const now = new Date()
  const start = from ?? subMonths(now, 1)
  const end = to ?? now

  const [totalUsers, adopters] = await Promise.all([
    prisma.user.count({ where: { deletedAt: null } }),
    prisma.auditLog.findMany({
      where: {
        action: 'FEATURE_USED',
        entity: 'ANALYTICS',
        changes: { path: ['feature'], equals: feature },
        createdAt: { gte: start, lt: end },
      },
      select: { userId: true, createdAt: true },
      distinct: ['userId'],
    }),
  ])

  if (totalUsers === 0) return null

  const adoptionRate = Math.round((adopters.length / totalUsers) * 100)

  // Calculate average time to adopt (from user creation to first use)
  // Fetch actual user creation dates instead of using audit log timestamps
  const adopterUserIds = adopters
    .map((e: { userId: string | null }) => e.userId)
    .filter((id): id is string => Boolean(id))
  const users = await prisma.user.findMany({
    where: { id: { in: adopterUserIds } },
    select: { id: true, createdAt: true },
  })

  const userCreatedAt = new Map(
    users.map((u: { id: string; createdAt: Date }) => [u.id, u.createdAt])
  )

  const avgTimeToAdopt =
    adopters.length > 0
      ? Math.round(
          adopters.reduce((sum: number, e: { userId: string | null; createdAt: Date }) => {
            if (!e.userId) return sum
            const userCreated = userCreatedAt.get(e.userId) ?? new Date(e.createdAt)
            const adoptDate = new Date(e.createdAt)
            const days = (adoptDate.getTime() - userCreated.getTime()) / (1000 * 60 * 60 * 24)
            return sum + days
          }, 0) / adopters.length
        )
      : null

  return {
    feature,
    totalUsers,
    adopters: adopters.length,
    adoptionRate,
    avgTimeToAdoptDays: avgTimeToAdopt,
  }
}

// ============================================================================
// Page Views
// ============================================================================

export async function getPageViews(from?: Date, to?: Date, limit = 20): Promise<PageViewMetrics[]> {
  const now = new Date()
  const start = from ?? subDays(now, 7)
  const end = to ?? now

  const pageViews = await prisma.auditLog.groupBy({
    by: ['entityId'],
    where: {
      action: 'PAGE_VIEW',
      entity: 'ANALYTICS',
      createdAt: { gte: start, lt: end },
    },
    _count: { id: true },
    orderBy: { _count: { id: 'desc' } },
    take: limit,
  })

  // Get unique visitors per page
  const uniqueVisitorsPromises = pageViews.map((pv) =>
    prisma.auditLog.findMany({
      where: {
        action: 'PAGE_VIEW',
        entity: 'ANALYTICS',
        entityId: pv.entityId,
        createdAt: { gte: start, lt: end },
      },
      select: { userId: true },
      distinct: ['userId'],
    })
  )

  const uniqueVisitorsLists = await Promise.all(uniqueVisitorsPromises)

  return pageViews.map((pv, i) => ({
    path: pv.entityId ?? '',
    views: pv._count.id,
    uniqueVisitors: uniqueVisitorsLists[i].length,
    avgViewsPerVisitor:
      uniqueVisitorsLists[i].length > 0
        ? Number((pv._count.id / uniqueVisitorsLists[i].length).toFixed(1))
        : 0,
  }))
}

