// ============================================================================
// Event volume (for time-series charts)
// ============================================================================

export async function getEventVolume(
  from?: Date,
  to?: Date,
  groupBy: 'day' | 'week' | 'month' = 'day'
) {
  const now = new Date()
  const start = from ?? subDays(now, 30)
  const end = to ?? now

  const events = await prisma.auditLog.findMany({
    where: {
      entity: 'ANALYTICS',
      createdAt: { gte: start, lt: end },
    },
    select: {
      action: true,
      createdAt: true,
    },
    orderBy: { createdAt: 'asc' },
  })

  // Group by time bucket
  const buckets = new Map<string, Record<string, number>>()

  for (const event of events) {
    let key: string
    const d = event.createdAt

    switch (groupBy) {
      case 'week':
        const weekStart = startOfDay(subDays(d, d.getDay()))
        key = weekStart.toISOString().split('T')[0]
        break
      case 'month':
        key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
        break
      default:
        key = d.toISOString().split('T')[0]
    }

    if (!buckets.has(key)) {
      buckets.set(key, {})
    }
    const bucket = buckets.get(key)!
    bucket[event.action] = (bucket[event.action] || 0) + 1
  }

  return Array.from(buckets.entries())
    .map(([date, counts]) => ({ date, ...counts }))
    .sort((a, b) => a.date.localeCompare(b.date))
}

import { unstable_cache } from 'next/cache'
