import prisma from '@/lib/prisma/client'
import { getSystemSettings } from '@/lib/settings'

/** EASA-approved regulatory minimum used as the default and the hard floor. */
export const EASA_APPROVED_ATTENDANCE_THRESHOLD = 80

/** Backwards-compatible default export (EASA baseline). */
export const ATTENDANCE_WARNING_THRESHOLD = EASA_APPROVED_ATTENDANCE_THRESHOLD

/**
 * Audit 9c: the academy can configure its own attendance threshold, but it can
 * never be set below the EASA-approved threshold. Both values are stored as
 * SystemSettings; the effective enforced threshold is max(academy, EASA).
 */
export async function getAttendanceThreshold(): Promise<{
  academy: number
  easa: number
  effective: number
}> {
  const settings = await getSystemSettings([
    'academy_attendance_threshold',
    'easa_attendance_threshold',
  ])
  const easaRaw = Number(settings.get('easa_attendance_threshold'))
  const easa =
    Number.isFinite(easaRaw) && easaRaw > 0 ? easaRaw : EASA_APPROVED_ATTENDANCE_THRESHOLD
  const academyRaw = Number(settings.get('academy_attendance_threshold'))
  const academy = Number.isFinite(academyRaw) && academyRaw > 0 ? academyRaw : easa
  return { academy, easa, effective: Math.max(academy, easa) }
}

export async function calculateAttendancePercentage(
  userId: string,
  enrollmentType?: string
): Promise<{
  percentage: number
  total: number
  present: number
  late: number
  absent: number
  excused: number
  belowThreshold: boolean
}> {
  const records = await prisma.attendanceRecord.findMany({
    where: { userId },
    orderBy: { date: 'desc' },
  })

  if (records.length === 0) {
    return {
      percentage: 0,
      total: 0,
      present: 0,
      late: 0,
      absent: 0,
      excused: 0,
      belowThreshold: false,
    }
  }

  const total = records.length
  const present = records.filter((r) => r.status === 'PRESENT').length
  const late = records.filter((r) => r.status === 'LATE').length
  const absent = records.filter((r) => r.status === 'ABSENT').length
  const excused = records.filter((r) => r.status === 'EXCUSED').length

  const attendedCount = present + late
  const percentage = Math.round((attendedCount / total) * 100)
  const { effective } = await getAttendanceThreshold()

  return {
    percentage,
    total,
    present,
    late,
    absent,
    excused,
    belowThreshold: percentage < effective,
  }
}

export async function getAttendanceWarning(
  userId: string,
  enrollmentType?: string
): Promise<{
  hasWarning: boolean
  message: string | null
  percentage: number
}> {
  if (enrollmentType !== 'FULL_TIME') {
    return { hasWarning: false, message: null, percentage: 0 }
  }

  const attendance = await calculateAttendancePercentage(userId, enrollmentType)

  if (attendance.belowThreshold && attendance.total > 0) {
    const { effective } = await getAttendanceThreshold()
    return {
      hasWarning: true,
      message: `Your attendance is ${attendance.percentage}%, which is below the required ${effective}%. Please improve your attendance to meet program requirements.`,
      percentage: attendance.percentage,
    }
  }

  return {
    hasWarning: false,
    message: null,
    percentage: attendance.percentage,
  }
}

export async function getAttendanceForClass(
  classId: string,
  userId: string
): Promise<{
  present: number
  late: number
  absent: number
  excused: number
  total: number
  percentage: number
}> {
  const records = await prisma.attendanceRecord.findMany({
    where: {
      classId,
      userId,
    },
  })

  const total = records.length
  const present = records.filter((r) => r.status === 'PRESENT').length
  const late = records.filter((r) => r.status === 'LATE').length
  const absent = records.filter((r) => r.status === 'ABSENT').length
  const excused = records.filter((r) => r.status === 'EXCUSED').length
  const percentage = total > 0 ? Math.round(((present + late) / total) * 100) : 0

  return { present, late, absent, excused, total, percentage }
}

import 'server-only'
import { getServerSession } from 'next-auth'
import type { NextAuthOptions } from 'next-auth'
import CredentialsProvider from 'next-auth/providers/credentials'
import { prismaBase as prisma } from '@/lib/prisma/db-base'
import { verifyPassword } from '@/lib/auth/helpers'
import { createAuditLog } from '@/lib/audit/logger'
import { UserStatus } from '@prisma/client'
import { verifyTOTP } from '@/lib/auth/totp'

export const authOptions: NextAuthOptions = {
  secret: process.env.NEXTAUTH_SECRET,
  debug: process.env.NEXTAUTH_DEBUG === 'true',
  providers: [
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
        token: { label: 'Token', type: 'text' }, // Added for auto-login
        totpCode: { label: '2FA Code', type: 'text' },
      },
      async authorize(credentials) {
        try {
          // Handling Auto-Login via Token (email verification or passkey bridge)
          if (credentials?.token) {
            const isPasskeyBridge = credentials.token.startsWith('pk_')

            // Look up by the appropriate token field
            const user = isPasskeyBridge
              ? await prisma.user.findUnique({
                  where: { passkeyBridgeToken: credentials.token },
                  include: { profile: { select: { firstName: true, lastName: true } } },
                })
              : await prisma.user.findUnique({
                  where: { verifyToken: credentials.token },
                  include: { profile: { select: { firstName: true, lastName: true } } },
                })

            if (!user) {
              throw new Error('Invalid verification token')
            }

            const tokenExpires = isPasskeyBridge
              ? user.passkeyBridgeExpires
              : user.verifyTokenExpires
            if (tokenExpires && tokenExpires < new Date()) {
              throw new Error('Verification link has expired')
            }

            // Check account status — suspended/archived users should not authenticate
            if (user.status === UserStatus.SUSPENDED) {
              throw new Error('Account has been suspended. Contact administration.')
            }
            if (user.status === UserStatus.ARCHIVED || user.status === UserStatus.DELETED) {
              throw new Error('Account is no longer active. Contact administration.')
            }

            // If user has 2FA enabled, require TOTP even for token-based login
            // (Passkey tokens skip 2FA — already proved possession and biometric)
            if (user.twoFactorEnabled && user.twoFactorSecret && !isPasskeyBridge) {
              const totpCode = credentials.totpCode
              if (!totpCode || totpCode === 'undefined' || totpCode === '') {
                throw new Error('2FA_REQUIRED')
              }
              const userSettings = ((user.settings as Record<string, unknown>) || {}) as Record<
                string,
                string | number | boolean
              >
              const lastCounter =
                typeof userSettings.lastTotpCounter === 'number'
                  ? userSettings.lastTotpCounter
                  : undefined
              const counter = verifyTOTP(totpCode, user.twoFactorSecret, 1, lastCounter)
              if (counter === false) {
                throw new Error('Invalid 2FA code')
              }
              // Store counter for replay protection
              await prisma.user.update({
                where: { id: user.id },
                data: { settings: { ...userSettings, lastTotpCounter: counter } },
              })
            }

            // Clear the used token and mark email as verified (for email verification tokens)
            await prisma.user.update({
              where: { id: user.id },
              data: isPasskeyBridge
                ? { passkeyBridgeToken: null, passkeyBridgeExpires: null }
                : { emailVerified: new Date(), verifyToken: null, verifyTokenExpires: null },
            })

            const name = user.profile
              ? `${user.profile.firstName} ${user.profile.lastName}`
              : user.email

            return {
              id: user.id,
              email: user.academyEmail || user.email,
              name,
              role: user.role,
              status: user.status,
              mustChangePassword: user.mustChangePassword && !user.passwordChanged,
            }
          }

          if (!credentials?.email || !credentials?.password) {
            throw new Error('Email and password are required')
          }

          const user = await prisma.user.findFirst({
            where: {
              OR: [
                { email: { equals: credentials.email, mode: 'insensitive' } },
                { academyEmail: { equals: credentials.email, mode: 'insensitive' } },
                { personalEmail: { equals: credentials.email, mode: 'insensitive' } },
              ],
            },
            include: {
              profile: { select: { firstName: true, lastName: true } },
            },
          })

          if (!user || !user.password) {
            throw new Error('Invalid email or password')
          }

          // Check if account is locked
          if (user.lockedUntil && user.lockedUntil > new Date()) {
            throw new Error('Account is temporarily locked. Please try again later.')
          }

          // Check account status
          if (user.status === UserStatus.SUSPENDED) {
            throw new Error('Account has been suspended. Contact administration.')
          }
          if (user.status === UserStatus.ARCHIVED || user.status === UserStatus.DELETED) {
            throw new Error('Account is no longer active. Contact administration.')
          }

          // Check email verification — skip for ADMIN and STAFF roles
          if (!user.emailVerified && !['SUPER_ADMIN', 'ADMIN', 'STAFF'].includes(user.role)) {
            throw new Error('Please verify your email before logging in.')
          }

          // Verify password

          const isValid = await verifyPassword(credentials.password, user.password)

          if (!isValid) {
            const attempts = user.loginAttempts + 1
            const updateData: Record<string, unknown> = { loginAttempts: attempts }

            if (attempts >= 5) {
              updateData.lockedUntil = new Date(Date.now() + 30 * 60 * 1000)
            }

            await prisma.user.update({
              where: { id: user.id },
              data: updateData,
            })

            throw new Error('Invalid email or password')
          }

          // 2FA Check
          if (user.twoFactorEnabled && user.twoFactorSecret) {
            const totpCode = credentials.totpCode
            if (!totpCode || totpCode === 'undefined' || totpCode === '') {
              throw new Error('2FA_REQUIRED')
            }
            const userSettings = (user.settings as Record<string, unknown>) || {}
            const lastCounter =
              typeof userSettings.lastTotpCounter === 'number'
                ? userSettings.lastTotpCounter
                : undefined
            const counter = verifyTOTP(totpCode, user.twoFactorSecret, 1, lastCounter)
            if (counter === false) {
              throw new Error('Invalid 2FA code')
            }
            // Store counter for replay protection
            await prisma.user.update({
              where: { id: user.id },
              data: { settings: { ...userSettings, lastTotpCounter: counter } },
            })
          }

          // Reset login attempts on successful login
          await prisma.user.update({
            where: { id: user.id },
            data: {
              loginAttempts: 0,
              lockedUntil: null,
              lastLoginAt: new Date(),
            },
          })

          // Audit log
          await createAuditLog({
            action: 'LOGIN',
            entity: 'users',
            entityId: user.id,
            userId: user.id,
            description: `User logged in: ${user.email}`,
          })

          const name = user.profile
            ? `${user.profile.firstName} ${user.profile.lastName}`
            : user.email

          return {
            id: user.id,
            email: user.academyEmail || user.email,
            name,
            role: user.role,
            status: user.status,
            mustChangePassword: user.mustChangePassword && !user.passwordChanged,
          }
        } catch (error: any) {
          throw error
        }
      },
    }),
  ],

  session: {
    strategy: 'jwt',
    maxAge: 8 * 60 * 60,
  },

  jwt: {
    maxAge: 8 * 60 * 60,
  },

  pages: {
    signIn: '/login',
    error: '/login',
  },

  callbacks: {
    async jwt({ token, user, trigger }) {
      if (user) {
        token.id = user.id
        token.role = user.role
        token.status = user.status
        token.mustChangePassword = user.mustChangePassword
        token.issuedAt = Date.now()
      }

      // Periodic session validation (every 5 minutes) — checks if password was changed after token issued
      const REVALIDATION_INTERVAL = 5 * 60 * 1000
      const lastChecked = (token.lastChecked as number) || 0
      const shouldRevalidate =
        trigger === 'update' || Date.now() - lastChecked > REVALIDATION_INTERVAL

      if (shouldRevalidate && token.id) {
        const dbUser = await prisma.user.findUnique({
          where: { id: token.id as string },
          select: {
            role: true,
            status: true,
            mustChangePassword: true,
            passwordChanged: true,
            passwordChangedAt: true,
          },
        })
        if (dbUser) {
          // Invalidate session if password was changed after this token was issued
          if (
            dbUser.passwordChangedAt &&
            token.issuedAt &&
            dbUser.passwordChangedAt.getTime() > (token.issuedAt as number)
          ) {
            // Invalidate by clearing identity — middleware/auth checks will reject
            token.id = ''
            token.role = ''
            token.status = ''
            return token
          }
          token.role = dbUser.role
          token.status = dbUser.status
          token.mustChangePassword = dbUser.mustChangePassword && !dbUser.passwordChanged
        }
        token.lastChecked = Date.now()
      }

      return token
    },

    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id as string
        session.user.role = token.role as string
        session.user.status = token.status as string
        session.user.mustChangePassword = token.mustChangePassword as boolean
      }
      return session
    },
  },

  events: {
    async signOut({ token }) {
      if (token?.id) {
        await createAuditLog({
          action: 'LOGOUT',
          entity: 'users',
          entityId: token.id as string,
          userId: token.id as string,
          description: `User logged out`,
        })
      }
    },
  },
}

export const getAuthSession = () => getServerSession(authOptions)

export const ROLE_HIERARCHY: Record<string, number> = {
