import 'server-only'
import { NotificationType } from '@prisma/client'
import prisma from '@/lib/prisma/client'
import { getFinanceConfig, getRegistrationConfig, getEmailConfig } from '@/lib/settings'
import { getBaseUrl } from '@/lib/utils/url'
import { formatPaymentType } from '@/lib/utils/string'

type TxClient = any // Prisma transaction client

// ---------------------------------------------------------------------------
// NOTIFICATION CREATOR (for use within transactions)
// ---------------------------------------------------------------------------

export async function createNotification(
  tx: TxClient,
  userId: string,
  data: {
    type: NotificationType
    title: string
    message: string
    link?: string
  }
) {
  return tx.notification.create({
    data: {
      userId,
      type: data.type,
      title: data.title,
      message: data.message,
      link: data.link,
    },
  })
}

// ---------------------------------------------------------------------------
// EMAIL SENDING (via Resend)
// ---------------------------------------------------------------------------

const RESEND_API_KEY = process.env.RESEND_API_KEY

/**
 * Resolves the sender email address based on environment variables or dynamic settings.
 * Defaults to the recommended subdomain pattern: noreply@mail.aerojet-academy.com
 */
async function getFromEmail() {
  if (process.env.FROM_EMAIL) return process.env.FROM_EMAIL

  const config = await getEmailConfig()
  const display = config.fromName ? `"${config.fromName}" ` : ''
  const email = `${config.fromAddress}@${config.subdomain}.${config.rootDomain}`

  return `${display}<${email}>`
}

/**
 * Replaces {{handlebars}} style placeholders in a string.
 */
function replacePlaceholders(template: string, data: Record<string, any>) {
  return template.replace(/\{\{(.*?)\}\}/g, (match, key) => {
    const value = data[key.trim()]
    return value !== undefined ? String(value) : match
  })
}

async function getTemplate(name: string, defaults: { subject: string; body: string }) {
  try {
    const t = await prisma.emailTemplate.findUnique({
      where: { name },
    })
    if (t && t.isActive) {
      return { subject: t.subject, body: t.body }
    }
  } catch (error) {
    console.warn(`[Email] Failed to fetch template "${name}", using default:`, error)
  }
  return defaults
}

interface EmailPayload {
  to: string
  subject: string
  html: string
}

export async function sendEmail(payload: EmailPayload): Promise<boolean> {
  if (!RESEND_API_KEY) {
    const fromAddress = await getFromEmail()
    console.warn('[Email] RESEND_API_KEY not set. Logging email instead:', payload.subject)
    console.log(`From: ${fromAddress} | To: ${payload.to} | Subject: ${payload.subject}`)
    return true
  }

  try {
    const fromAddress = await getFromEmail()
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${RESEND_API_KEY}`,
      },
      body: JSON.stringify({
        from: fromAddress,
        to: payload.to,
        subject: payload.subject,
        html: payload.html,
      }),
    })

    if (!res.ok) {
      const errorText = await res.text()
      console.error(`[Email] Send to ${payload.to} failed:`, errorText)
      return false
    }

    console.log(`[Email] Successfully sent "${payload.subject}" to ${payload.to}`)
    return true
  } catch (error) {
    console.error(`[Email] Exception sending to ${payload.to}:`, error)
    return false
  }
}

// ---------------------------------------------------------------------------
// EMAIL TEMPLATES
// ---------------------------------------------------------------------------

const COLORS = {
  navy: '#002a5c',
  sky: '#4c9ded',
  white: '#ffffff',
  gray: '#f4f6f8',
  text: '#334155',
}

let cachedBaseUrl: { value: string; expiresAt: number } | null = null

async function getCachedBaseUrl(): Promise<string> {
  if (cachedBaseUrl && Date.now() < cachedBaseUrl.expiresAt) return cachedBaseUrl.value
  const url = await getBaseUrl()
  cachedBaseUrl = { value: url, expiresAt: Date.now() + 5 * 60 * 1000 }
  return url
}

