import prisma from '@/lib/prisma/client'
import { getDeduplicatedModulesForStudent } from './deduplication'

/**
 * Triggers auto-enrollment for a student by their StudentProfile ID, if their pathway requires it.
 * Call this AFTER a transaction commits (not inside $transaction).
 */
export async function triggerAutoEnrollmentIfRequired(studentProfileId: string): Promise<void> {
  const profile = await prisma.studentProfile.findUnique({
    where: { id: studentProfileId },
    select: { pathwayRel: { select: { requiresAutoEnrollment: true } } },
  })
  if (profile?.pathwayRel?.requiresAutoEnrollment) {
    await autoEnrollStudent(studentProfileId).catch(console.error)
  }
}

/**
 * Triggers auto-enrollment for a student by their User ID, if their pathway requires it.
 * Call this AFTER a transaction commits (not inside $transaction).
 */
export async function triggerAutoEnrollmentByUserId(userId: string): Promise<void> {
  const profile = await prisma.studentProfile.findUnique({
    where: { userId },
    select: { id: true, pathwayRel: { select: { requiresAutoEnrollment: true } } },
  })
  if (profile?.pathwayRel?.requiresAutoEnrollment) {
    await autoEnrollStudent(profile.id).catch(console.error)
  }
}

/**
 * Enrollment Engine to handle automatic and manual enrollment processes.
 * Aligns with the blueprint for path-specific auto-enrollment and scheduling.
 */

/**
 * Automatically enrolls a student in modules based on their pathway and current academic term.
 * Primarily for Full-Time and Military pathways.
 *
 * @param studentProfileId The ID of the student profile
 */
export async function autoEnrollStudent(studentProfileId: string): Promise<number> {
  // 1. Fetch student profile and their relational pathway
  const profile = await prisma.studentProfile.findUnique({
    where: { id: studentProfileId },
    include: {
      pathwayRel: {
        include: {
          academicTerms: {
            include: {
              courseAssignments: true,
            },
          },
        },
      },
      academicYear: true,
      semester: true,
    },
  })

  if (!profile || !profile.pathwayRel) {
    throw new Error('Student profile or relational pathway not found')
  }

  // 2. Determine if this pathway requires auto-enrollment
  if (!profile.pathwayRel.requiresAutoEnrollment) {
    return 0 // Pathway like MODULAR or EXAM_ONLY doesn't auto-enroll
  }

  // 3. Find the academic term mapping for the student's current year/semester
  const currentYear = profile.currentYearNumber || 1
  const currentSem = profile.currentSemesterNumber || 1
  const academicYearId = profile.academicYearId
  const semesterId = profile.semesterId

  const targetTerm = (profile.pathwayRel as any).academicTerms.find(
    (term: any) => term.yearNumber === currentYear && term.semesterNumber === currentSem
  )

  if (!targetTerm) {
    console.warn(
      `No academic term found for Year ${currentYear}, Sem ${currentSem} in pathway ${profile.pathwayRel.code}`
    )
    return 0
  }

  // 4. Filter for modules the student *actually* needs (deduplication)
  const { modules: requiredModules } = await getDeduplicatedModulesForStudent(studentProfileId)
  const requiredModuleIds = new Set(requiredModules.map((m: any) => m.id))

  // 5. Create enrollments for modules assigned to this term that the student needs
  let enrollmentCount = 0
  for (const assignment of targetTerm.courseAssignments) {
    if (requiredModuleIds.has(assignment.courseId)) {
      // Check if already enrolled
      const existing = await prisma.enrollment.findFirst({
        where: {
          userId: profile.userId,
          courseId: assignment.courseId,
        },
      })

      if (!existing) {
        const course = requiredModules.find(m => m.id === assignment.courseId);
        await prisma.enrollment.create({
          data: {
            userId: profile.userId,
            courseId: assignment.courseId,
            status: 'ENROLLED',
            amountPaid: course?.price || 0,
            academicYearId,
            semesterId,
          },
        })
        enrollmentCount++
      }
    }
  }

  return enrollmentCount
}

/**
 * Promotes an applicant to a student and triggers initial auto-enrollment.
 *
 * @param userId The ID of the applicant user
 * @param pathwayCode The code of the chosen study pathway (relational)
 * @param licenseCategoryCodes Array of license category codes (e.g. ['B1.1', 'B2'])
 */
export async function promoteAndEnroll(
  userId: string,
  pathwayCode: string,
  licenseCategoryCodes: string[]
): Promise<void> {
  await prisma.$transaction(async (tx) => {
    // 1. Look up relational models
    const pathway = await tx.studyPathwayModel.findUnique({ where: { code: pathwayCode } })
    if (!pathway) throw new Error(`Pathway ${pathwayCode} not found`)

    const licenseCats = await tx.licenseCategory.findMany({
      where: { code: { in: licenseCategoryCodes } },
    })

    // 2. Update User role
    await tx.user.update({
      where: { id: userId },
      data: {
        role: 'STUDENT',
        status: 'ACTIVE',
      },
    })

    // 3. Create/Update Student Profile
    const profile = await tx.studentProfile.upsert({
      where: { userId },
      update: {
        pathwayId: pathway.id,
        enrollmentStatus: 'ENROLLED',
      },
      create: {
        userId,
        studentId: `AJA-TEMP-${Date.now()}`, // Temporary, actual one should be generated via helper
        pathwayId: pathway.id,
        enrollmentStatus: 'ENROLLED',
      },
    })

    // 4. Link License Targets
    for (const lc of licenseCats) {
      await tx.studentLicenseTarget.upsert({
        where: {
          studentProfileId_licenseCategoryId: {
            studentProfileId: profile.id,
            licenseCategoryId: lc.id,
          },
        },
        update: {},
        create: {
          studentProfileId: profile.id,
          licenseCategoryId: lc.id,
        },
      })
    }

    // Note: Actual auto-enrollment will be called outside the transaction or via a post-commit hook
    // to ensure deduplication has all updated data available.
  })
}

import prisma from '@/lib/prisma/client'
import { MilestoneStatus } from '@prisma/client'
import { triggerAutoEnrollmentByUserId } from './engine'
import { upgradeRoleInTransaction } from './pathway'

/**
 * Generates payment milestones for a Full-Time Enrollment.
 * Split percentages are loaded from SystemSettings (admin-editable).
 * Defaults: Y1 = 40/30/30, Y2+ = 50/50.
 */
export async function generateMilestonesForYear(enrollmentId: string, yearId: string) {
  const { getPaymentSplitConfig } = await import('@/lib/settings')

  const [enrollment, progYear, splitConfig] = await Promise.all([
    prisma.fullTimeEnrollment.findUnique({
      where: { id: enrollmentId },
      include: { programme: true, student: true },
    }),
    prisma.programmeYear.findUnique({ where: { id: yearId } }),
    getPaymentSplitConfig(),
  ])

  if (!enrollment) throw new Error('Enrollment not found')
  if (!progYear) throw new Error('Programme Year not found')

  // Use year-specific fee amount, otherwise derive from programme totalFee / duration
  const feeBase =
    progYear.yearFeeAmount ??
    Number(enrollment.programme.totalFee) / enrollment.programme.durationYears
  const totalAmount = Number(feeBase)

  const semesters = (progYear.semesters as any[]) || []
  const sem1Date =
    semesters.length > 0 && semesters[0].startDate ? new Date(semesters[0].startDate) : new Date()
  const sem2Date =
    semesters.length > 1 && semesters[1].startDate ? new Date(semesters[1].startDate) : new Date()

  const milestoneData: {
    enrollmentId: string
    yearNumber: number
    milestoneType: string
    dueDate: Date
    percentOfYearFee: number
    amountDue: number
    status: MilestoneStatus
  }[] = []

  if (progYear.yearNumber === 1) {
    milestoneData.push(
      {
        enrollmentId,
        yearNumber: 1,
        milestoneType: 'SEAT_CONFIRMATION',
        dueDate: new Date(), // Immediate
        percentOfYearFee: splitConfig.y1SeatPct,
        amountDue: totalAmount * (splitConfig.y1SeatPct / 100),
        status: 'DUE',
      },
      {
        enrollmentId,
        yearNumber: 1,
        milestoneType: 'SEM1_DUE',
        dueDate: sem1Date,
        percentOfYearFee: splitConfig.y1Sem1Pct,
        amountDue: totalAmount * (splitConfig.y1Sem1Pct / 100),
        status: 'DUE',
      },
      {
        enrollmentId,
        yearNumber: 1,
        milestoneType: 'SEM2_DUE',
        dueDate: sem2Date,
        percentOfYearFee: splitConfig.y1Sem2Pct,
        amountDue: totalAmount * (splitConfig.y1Sem2Pct / 100),
        status: 'DUE',
      }
    )
  } else {
    milestoneData.push(
      {
        enrollmentId,
        yearNumber: progYear.yearNumber,
        milestoneType: 'SEM1_DUE',
        dueDate: sem1Date,
        percentOfYearFee: splitConfig.y2Sem1Pct,
        amountDue: totalAmount * (splitConfig.y2Sem1Pct / 100),
        status: 'DUE',
      },
      {
        enrollmentId,
        yearNumber: progYear.yearNumber,
        milestoneType: 'SEM2_DUE',
        dueDate: sem2Date,
        percentOfYearFee: splitConfig.y2Sem2Pct,
        amountDue: totalAmount * (splitConfig.y2Sem2Pct / 100),
        status: 'DUE',
      }
    )
  }

  // Atomically create milestones
  const created = await prisma.$transaction(
    milestoneData.map((data) =>
      prisma.paymentMilestone.create({
        data,
      })
    )
  )

  return created
}

export async function processMilestonePayment(milestoneId: string, userId: string) {
  const milestone = await prisma.paymentMilestone.findUnique({
    where: { id: milestoneId },
    include: { enrollment: true },
  })

  if (!milestone) throw new Error('Milestone not found')
  if (milestone.enrollment.studentId !== userId) throw new Error('Unauthorized or invalid user')
  if (milestone.status === 'PAID') throw new Error('Milestone already paid')

  const amountToCharge = Number(milestone.amountDue)

  const wallet = await prisma.wallet.findUnique({ where: { userId } })
  if (!wallet || Number(wallet.availableBalance) < amountToCharge) {
    throw new Error('Insufficient wallet balance to pay this milestone')
  }

  const { chargeWallet } = await import('@/lib/wallet/operations')

  const updatedMilestone = await prisma.$transaction(async (tx) => {
    // 1. Charge wallet
    await chargeWallet(
      tx,
      userId,
      amountToCharge,
      `Paid milestone: ${milestone.milestoneType} (Year ${milestone.yearNumber})`,
      milestone.id,
      'MILESTONE_ID'
    )

    // 2. Mark milestone as PAID
    const updated = await tx.paymentMilestone.update({
      where: { id: milestone.id },
      data: {
        status: 'PAID',
        paidAt: new Date(),
      },
    })

    // 2.5 Special case: Seat confirmation activates enrollment
    if (milestone.milestoneType === 'SEAT_CONFIRMATION') {
      await tx.fullTimeEnrollment.update({
        where: { id: milestone.enrollmentId },
        data: { status: 'ACTIVE' },
      })
    }

    // 3. Check if promotion conditions are met:
    //    SEAT_CONFIRMATION must be PAID for applicant → student
    const allMilestones = await tx.paymentMilestone.findMany({
      where: { enrollmentId: milestone.enrollmentId, yearNumber: 1 },
    })
    const seatPaid = allMilestones.some(
      (m) =>
        m.milestoneType === 'SEAT_CONFIRMATION' &&
        (m.id === milestone.id ? true : m.status === 'PAID')
    )

    if (seatPaid) {
      await upgradeRoleInTransaction(tx, userId)
    }

    return updated
  })

  // 4. Post-transaction: trigger auto-enrollment for FT/Military pathways (if promoted)
  const postUser = await prisma.user.findUnique({ where: { id: userId } })
  if (postUser?.role === 'STUDENT') {
    await triggerAutoEnrollmentByUserId(userId)
  }

  return updatedMilestone
}

export async function payFullYear(enrollmentId: string, yearNumber: number, userId: string) {
  const enrollment = await prisma.fullTimeEnrollment.findUnique({
    where: { id: enrollmentId, studentId: userId },
    include: { milestones: { where: { yearNumber } } },
  })

  if (!enrollment) throw new Error('Enrollment not found')

  const unpaidMilestones = enrollment.milestones.filter(
    (m) => m.status === 'DUE' || m.status === 'OVERDUE'
  )
  if (unpaidMilestones.length === 0) throw new Error('No unpaid milestones for this year')

  const totalToCharge = unpaidMilestones.reduce((acc, m) => acc + Number(m.amountDue), 0)

  const wallet = await prisma.wallet.findUnique({ where: { userId } })
  if (!wallet || Number(wallet.availableBalance) < totalToCharge) {
    throw new Error('Insufficient wallet balance to pay the full year')
  }

  const { chargeWallet } = await import('@/lib/wallet/operations')

  await prisma.$transaction(async (tx) => {
    await chargeWallet(
      tx,
      userId,
      totalToCharge,
      `Paid full remaining balance for Year ${yearNumber}`,
      enrollment.id,
      'ENROLLMENT_ID'
    )

    // Mark them all as PAID
    for (const m of unpaidMilestones) {
      await tx.paymentMilestone.update({
        where: { id: m.id },
        data: { status: 'PAID', paidAt: new Date() },
      })
    }

    // Upgrade role
    await upgradeRoleInTransaction(tx, userId)
  })

  // Post-transaction: trigger auto-enrollment for FT/Military pathways
  await triggerAutoEnrollmentByUserId(userId)
}

import prisma from '@/lib/prisma/client'

export async function enrollInModularPackage(packageId: string, userId: string) {
  const pkg = await prisma.modularPackage.findUnique({
    where: { id: packageId },
  })

  if (!pkg) throw new Error('Modular Package not found')
  if (!pkg.isActive) throw new Error('Package is not currently available for enrollment')

  // Prevent duplicate
  const existing = await prisma.modularEnrollment.findFirst({
    where: { studentId: userId, packageId: packageId },
  })

  if (existing) throw new Error('You are already enrolled in this package.')

  const amountToCharge = Number(pkg.price)

  const wallet = await prisma.wallet.findUnique({ where: { userId } })
  if (!wallet || Number(wallet.availableBalance) < amountToCharge) {
    throw new Error('Insufficient wallet balance to purchase this modular package.')
  }

  const { chargeWallet } = await import('@/lib/wallet/operations')

  return prisma.$transaction(async (tx) => {
    // 1. Direct charge to wallet
    const chargeResult = await chargeWallet(
      tx,
      userId,
      amountToCharge,
      `Purchased Modular Package: ${pkg.name}`,
      pkg.id,
      'PACKAGE_ID'
    )

    // 2. Create the Enrollment
    const enrollment = await tx.modularEnrollment.create({
      data: {
        studentId: userId,
        packageId: packageId,
        status: 'ACTIVE',
        amountPaid: amountToCharge,
        // validFrom and validUntil could be set if durationMonths exists
      },
    })

    // 3. Role Upgrade
    const user = await tx.user.findUnique({ where: { id: userId } })
    if (user?.role === 'APPLICANT') {
      await tx.user.update({
        where: { id: userId },
        data: { role: 'STUDENT' },
      })
      await tx.studentProfile.update({
        where: { userId },
        data: { enrollmentStatus: 'ENROLLED' },
      })
    }

    // 4. Auto-Exam Booking (User Feedback: Modular enrollment guarantees exam booking)
    // For each module in the package, create a placeholder MCQ booking (amountPaid: 0, included in pkg).
    // The student will then pick a specific date/event later without further charge.
    // Batch fetch: one query for all module exams instead of N+1
    const exams = await tx.exam.findMany({
      where: {
        examComponent: { code: { in: pkg.modulesIncluded }, type: 'MCQ' },
      },
      orderBy: { examDate: 'asc' },
      distinct: ['examComponentId'],
      include: { examComponent: { select: { code: true } } },
    })

    if (exams.length > 0) {
      await tx.examBooking.createMany({
        data: exams.map((exam) => ({
          userId,
          examId: exam.id,
          bookingType: 'MODULAR' as const,
          moduleCode: exam.examComponent.code,
          amountPaid: 0, // Included in package price
          status: 'APPROVED' as const,
          examDate: exam.examDate,
        })),
      })
    }

    return enrollment
  })
}

import { EnrollmentType, ProgrammeChoice } from '@prisma/client'
import prisma from '@/lib/prisma/client'
import { triggerAutoEnrollmentByUserId } from './engine'
import { sendStudentPromotionEmail } from '@/lib/email/service'
import { createAuditLog, AuditAction } from '@/lib/audit/logger'
import { generateStudentId } from '@/lib/auth/helpers'

/**
 * Maps a ProgrammeChoice (or raw string) to the relational StudyPathwayModel code.
 */
export function mapProgrammeChoiceToPathwayCode(choice: string | null | undefined): string {
  const map: Record<string, string> = {
    FULL_TIME_4YEAR: 'FULL_TIME_4Y',
    FULL_TIME_2YEAR: 'FULL_TIME_2Y',
    MILITARY_1YEAR: 'MILITARY_1Y',
    MODULAR: 'MODULAR',
    EXAM_ONLY: 'EXAM_ONLY',
  }
  return map[choice || ''] || 'MODULAR'
}

/**
 * Resolves the higher-level EnrollmentType from a specific ProgrammeChoice.
 */
export function resolveEnrollmentType(programme: ProgrammeChoice): EnrollmentType {
  switch (programme) {
    case 'FULL_TIME_4YEAR':
    case 'FULL_TIME_2YEAR':
    case 'MILITARY_1YEAR':
      return 'FULL_TIME'
    case 'MODULAR':
      return 'MODULAR'
    case 'EXAM_ONLY':
      return 'EXAM_ONLY'
    default:
      return 'SHORT_COURSE'
  }
}

function normalizeEnrollmentType(
  enrollmentType: EnrollmentType | string | null | undefined
): EnrollmentType | null {
  switch (enrollmentType) {
    case 'FULL_TIME':
    case 'MODULAR':
    case 'EXAM_ONLY':
    case 'SHORT_COURSE':
      return enrollmentType
    default:
      return null
  }
}

function mapPathwayCodeToEnrollmentType(
  pathwayCode: string | null | undefined
): EnrollmentType | null {
  switch (pathwayCode) {
    case 'FULL_TIME':
    case 'FULL_TIME_4Y':
    case 'FULL_TIME_2Y':
    case 'MILITARY_1Y':
    case 'MILITARY_2Y':
      return 'FULL_TIME'
    case 'MODULAR':
      return 'MODULAR'
    case 'EXAM_ONLY':
      return 'EXAM_ONLY'
    case 'SHORT_COURSE':
      return 'SHORT_COURSE'
    default:
      return null
  }
}

function resolveEnrollmentTypeFromChoice(
  programmeChoice: ProgrammeChoice | string | null | undefined
): EnrollmentType | null {
  switch (programmeChoice) {
    case 'FULL_TIME_4YEAR':
    case 'FULL_TIME_2YEAR':
    case 'MILITARY_1YEAR':
      return 'FULL_TIME'
    case 'MODULAR':
      return 'MODULAR'
    case 'EXAM_ONLY':
      return 'EXAM_ONLY'
    default:
      return null
  }
}

function normalizePathwayCodeFromEnrollmentType(
  enrollmentType: EnrollmentType | string | null | undefined
): string | null {
  switch (enrollmentType) {
    case 'FULL_TIME':
      return 'FULL_TIME'
    case 'MODULAR':
      return 'MODULAR'
    case 'EXAM_ONLY':
      return 'EXAM_ONLY'
    case 'SHORT_COURSE':
      return 'SHORT_COURSE'
    default:
      return null
  }
}

export function resolveEffectivePathwayCode(input: {
  pathwayCode?: string | null
  programmeChoice?: ProgrammeChoice | string | null
  enrollmentType?: EnrollmentType | string | null
}): string | null {
  return (
    input.pathwayCode ||
    (input.programmeChoice ? mapProgrammeChoiceToPathwayCode(input.programmeChoice) : null) ||
    normalizePathwayCodeFromEnrollmentType(input.enrollmentType)
  )
}

export function resolveEffectiveEnrollmentType(input: {
  pathwayCode?: string | null
  programmeChoice?: ProgrammeChoice | string | null
  enrollmentType?: EnrollmentType | string | null
}): EnrollmentType | null {
  return (
    mapPathwayCodeToEnrollmentType(input.pathwayCode) ||
    resolveEnrollmentTypeFromChoice(input.programmeChoice) ||
    normalizeEnrollmentType(input.enrollmentType)
  )
}

/**
 * Defines what a student can see in the catalog based on their enrollment type.
 */
export function getCatalogVisibility(enrollmentType: EnrollmentType | null) {
  // If not logged in or no type, show everything public
  if (!enrollmentType) {
    return {
      showEasaModules: true,
      showExamOnlyVariants: false,
      showShortCourses: true,
      canPurchaseEasaModules: true,
    }
  }

  switch (enrollmentType) {
    case 'FULL_TIME':
      return {
        showEasaModules: false, // They are auto-enrolled, shouldn't buy individually
        showExamOnlyVariants: false,
        showShortCourses: true,
        canPurchaseEasaModules: false,
      }
    case 'MODULAR':
      return {
        showEasaModules: true,
        showExamOnlyVariants: false,
        showShortCourses: true,
        canPurchaseEasaModules: true,
      }
    case 'EXAM_ONLY':
      return {
        showEasaModules: true, // They see them but...
        showExamOnlyVariants: true, // ...specifically the exam-only versions
        showShortCourses: true,
        canPurchaseEasaModules: false, // Cannot buy tuition version
      }
    case 'SHORT_COURSE':
    default:
      return {
        showEasaModules: true,
        showExamOnlyVariants: false,
        showShortCourses: true,
        canPurchaseEasaModules: true,
      }
  }
}

/**
 * Checks if a student is allowed to access materials.
 * Per user: Exam-only students CAN access materials after payment, just not classes.
 */
export function canAccessMaterials(enrollmentType: EnrollmentType) {
  // All pathways can access materials if paid
  return true
}

/**
 * Checks if a student is allowed to attend live classes.
 */
export function canAccessClasses(enrollmentType: EnrollmentType) {
  // Exam-only students are strictly forbidden from classes
  return enrollmentType !== 'EXAM_ONLY'
}

/**
 * Payment reference types that trigger APPLICANT → STUDENT promotion per pathway.
 */
const PROMOTION_TRIGGERS: Record<string, string[]> = {
  // SEAT_CONFIRMATION activates enrollment and promotes to student.
  FULL_TIME: ['SEAT_CONFIRMATION', 'YEAR_1_FULL', 'FULL_PROGRAMME'],
  MODULAR: ['COURSE'],
  // EXAM_ONLY promotion is handled directly in join-pool/book-exam routes on first booking,
  // NOT on wallet top-up (topping up should not make you a student).
  EXAM_ONLY: ['EXAM'],
  SHORT_COURSE: ['COURSE'],
}

/**
 * Checks if a given payment reference type satisfies the promotion conditions
 * for the user's enrollment pathway.
 */
export function shouldPromoteOnPayment(
  programmeChoice: ProgrammeChoice | null,
  paymentReferenceType: string
): boolean {
  const enrollmentType = programmeChoice ? resolveEnrollmentType(programmeChoice) : 'MODULAR'
  const triggers = PROMOTION_TRIGGERS[enrollmentType] || PROMOTION_TRIGGERS['MODULAR']
  return triggers.includes(paymentReferenceType)
}

/**
 * Promotes an APPLICANT to STUDENT.
 * Creates StudentProfile, updates role, triggers auto-enrollment for FT/Military.
 */
/**
 * Check if this is a user's first exam activity and promote them from APPLICANT to STUDENT if so.
 * Used by exam-only booking routes (book-exam, join-pool, bundles).
 * Returns whether promotion occurred.
 */
export async function promoteIfFirstExamActivity(userId: string): Promise<boolean> {
  const [user, membershipCount, bookingCount] = await Promise.all([
    prisma.user.findUnique({ where: { id: userId }, select: { role: true } }),
    prisma.poolMembership.count({ where: { userId } }),
    prisma.examBooking.count({ where: { userId } }),
  ])

  if (!user || user.role !== 'APPLICANT') return false
  // Promote if this is among their first exam activities
  if (membershipCount > 1 && bookingCount > 1) return false

  try {
    await promoteApplicantToStudent(userId, userId)
    return true
  } catch (e) {
    console.error('[PROMOTION] Failed for user', userId, e)
    return false
  }
}

/**
 * Inline role upgrade within an existing transaction context.
 * Used by full-time enrollment and tuition booking flows where a full
 * promoteApplicantToStudent call isn't needed (studentProfile already exists).
 */
export async function upgradeRoleInTransaction(
  tx: Parameters<Parameters<typeof prisma.$transaction>[0]>[0],
  userId: string
): Promise<boolean> {
  const user = await tx.user.findUnique({ where: { id: userId }, select: { role: true } })
  if (user?.role !== 'APPLICANT') return false

  await tx.user.update({ where: { id: userId }, data: { role: 'STUDENT' } })
  await tx.studentProfile.update({ where: { userId }, data: { enrollmentStatus: 'ENROLLED' } })
  return true
}

export async function promoteApplicantToStudent(
  userId: string,
  actorId: string
): Promise<{ studentId: string }> {
  const user = await prisma.user.findUniqueOrThrow({
    where: { id: userId },
    include: { profile: true, studentProfile: true },
  })

  // Guard: only promote active applicants who haven't already been promoted
  if (user.role !== 'APPLICANT') {
    throw new Error(`Cannot promote user with role ${user.role}`)
  }
  if (user.studentProfile) {
    return { studentId: user.studentProfile.studentId }
  }

  const studentId = await generateStudentId()
  const enrollmentType = user.programmeChoice
    ? resolveEnrollmentType(user.programmeChoice as ProgrammeChoice)
    : 'MODULAR'
  const pathwayCode = mapProgrammeChoiceToPathwayCode(user.programmeChoice)

  await prisma.$transaction(async (tx) => {
    // Look up the relational pathway
    const pathway = await tx.studyPathwayModel.findUnique({
      where: { code: pathwayCode },
    })

    // Create StudentProfile
    const studentProfile = await tx.studentProfile.create({
      data: {
        userId,
        studentId,
        enrollmentType: enrollmentType as any,
        enrollmentStatus: 'ENROLLED',
        pathwayId: pathway?.id ?? null,
      },
    })

    // Promote role
    await tx.user.update({
      where: { id: userId },
      data: { role: 'STUDENT' },
    })

    // Create StudentLicenseTarget entries from selected license categories
    if (user.selectedLicenseCategories && user.selectedLicenseCategories.length > 0) {
      const licenseCategories = await tx.licenseCategory.findMany({
        where: { code: { in: user.selectedLicenseCategories } },
        select: { id: true },
      })
      if (licenseCategories.length > 0) {
        await tx.studentLicenseTarget.createMany({
          data: licenseCategories.map((lc) => ({
            studentProfileId: studentProfile.id,
            licenseCategoryId: lc.id,
          })),
          skipDuplicates: true,
        })
      }
    }

    // Ensure wallet exists
    const wallet = await tx.wallet.findUnique({ where: { userId } })
    if (!wallet) {
      await tx.wallet.create({
        data: {
          userId,
          balance: 0,
          reservedBalance: 0,
          availableBalance: 0,
        },
      })
    }
  })

  // Post-transaction: auto-enrollment for FT/Military pathways
  await triggerAutoEnrollmentByUserId(userId)

  // Send promotion email
  if (user.profile) {
    sendStudentPromotionEmail(user.email, user.profile.firstName, studentId).catch(console.error)
  }

  // Audit log
  await createAuditLog({
    action: AuditAction.APPROVE,
    entity: 'StudentPromotion',
    entityId: userId,
    userId: actorId,
    details: { studentId, enrollmentType, pathwayCode },
  })

  return { studentId }
}

import prisma from '@/lib/prisma/client'
import { upgradeRoleInTransaction } from './pathway'

export async function bookTuitionSession(sessionId: string, userId: string) {
  const sessionData = await prisma.tuitionRun.findUnique({
    where: { id: sessionId },
  })

  if (!sessionData) throw new Error('Tuition Session not found')
  if (sessionData.status !== 'SCHEDULED' && sessionData.status !== 'OPEN') {
    throw new Error('This session is no longer open for booking')
  }

  if (sessionData.currentEnrollments >= sessionData.capacity) {
    throw new Error('This session is full')
  }

  // Check if booking already exists
  const existing = await prisma.tuitionBooking.findFirst({
    where: { studentId: userId, tuitionRunId: sessionId },
  })

  if (existing) throw new Error('You are already booked for this session')

  const amountToCharge = Number(sessionData.price)

  const wallet = await prisma.wallet.findUnique({ where: { userId } })
  if (!wallet || Number(wallet.availableBalance) < amountToCharge) {
    throw new Error('Insufficient wallet balance to book this session.')
  }

  const { chargeWallet } = await import('@/lib/wallet/operations')

  return prisma.$transaction(async (tx) => {
    // 1. Direct charge to wallet
    const chargeResult = await chargeWallet(
      tx,
      userId,
      amountToCharge,
      `Booked Tuition Session: ${sessionData.title}`,
      sessionData.id,
      'TUITION_ID'
    )

    // 2. Create the Booking
    const booking = await tx.tuitionBooking.create({
      data: {
        studentId: userId,
        tuitionRunId: sessionId,
        status: 'CONFIRMED',
        amountPaid: amountToCharge,
      },
    })

    // 3. Update Run Count
    await tx.tuitionRun.update({
      where: { id: sessionId },
      data: {
        currentEnrollments: { increment: 1 },
      },
    })

    // 4. Role Upgrade
    await upgradeRoleInTransaction(tx, userId)

    return booking
  })
}

import { EnrollmentType, ProgrammeChoice } from '@prisma/client'
import prisma from '@/lib/prisma/client'
import { resolveEffectiveEnrollmentType } from './pathway'

/**
 * Validates if a student can be enrolled in a specific Full-Time Programme.
 */
export async function validateFullTimeProgrammeEnrollment(userId: string, programmeCode: string): Promise<{ allowed: boolean; error?: string; severity: 'ERROR' | 'WARNING' }> {
  const profile = await prisma.studentProfile.findUnique({
    where: { userId },
    include: { pathwayRel: true }
  })

  if (!profile) return { allowed: true, severity: 'ERROR' }

  const effectiveEnrollmentType = resolveEffectiveEnrollmentType({
    pathwayCode: profile.pathwayRel?.code,
    enrollmentType: profile.enrollmentType,
  })

  // Rule 1: 4-Year Full-Time students cannot enroll in 12-Month Military Certification
  if (profile.pathwayRel?.code === 'FULL_TIME_4Y' && programmeCode === 'MIL_1Y_B1') {
    return { 
      allowed: false, 
      error: '4-Year Full-Time students are not eligible for the 12-Month Military Certification.',
      severity: 'WARNING' // Staff can override
    }
  }

  // Rule 2: Modular or Exam-Only students cannot enroll in Full-Time Programmes
  if (effectiveEnrollmentType === 'MODULAR' || effectiveEnrollmentType === 'EXAM_ONLY') {
    return {
      allowed: false,
      error: `${effectiveEnrollmentType.replace('_', '-')} students cannot enroll in Full-Time Programmes.`,
      severity: 'WARNING' // Staff can override
    }
  }

  return { allowed: true, severity: 'ERROR' }
}

/**
 * Validates if a student can have OJT (On-the-Job Training) records.
 */
export async function validateOjtAccess(userId: string): Promise<{ allowed: boolean; error?: string; severity: 'ERROR' | 'WARNING' }> {
  const profile = await prisma.studentProfile.findUnique({
    where: { userId },
    include: { pathwayRel: true }
  })

  if (!profile) return { allowed: false, error: 'Student profile not found.', severity: 'ERROR' }

  const effectiveEnrollmentType = resolveEffectiveEnrollmentType({
    pathwayCode: profile.pathwayRel?.code,
    enrollmentType: profile.enrollmentType,
  })

  // Rule: Exam Only or Modular students cannot enroll in OJT
  if (effectiveEnrollmentType === 'EXAM_ONLY' || effectiveEnrollmentType === 'MODULAR') {
    return {
      allowed: false,
      error: `${effectiveEnrollmentType.replace('_', '-')} students are not eligible for On-the-Job Training (OJT).`,
      severity: 'WARNING'
    }
  }

  // Also check if the pathway specifically includes OJT
  if (profile.pathwayRel && !profile.pathwayRel.includesOjt) {
     return {
      allowed: false,
      error: `The student's current pathway (${profile.pathwayRel.name}) does not include On-the-Job Training (OJT).`,
      severity: 'WARNING'
    }
  }

  return { allowed: true, severity: 'ERROR' }
}

/**
 * Validates if a student can enroll in a specific course (module).
 */
export async function validateCourseEnrollment(userId: string, courseId: string): Promise<{ allowed: boolean; error?: string; severity: 'ERROR' | 'WARNING' }> {
  const [profile, course] = await Promise.all([
    prisma.studentProfile.findUnique({
      where: { userId },
      include: { pathwayRel: true }
    }),
    prisma.course.findUnique({
      where: { id: courseId },
      include: { category: true }
    })
  ])

  if (!profile) return { allowed: false, error: 'Student profile not found.', severity: 'ERROR' }
  if (!course) return { allowed: false, error: 'Course not found.', severity: 'ERROR' }

  const effectiveEnrollmentType = resolveEffectiveEnrollmentType({
    pathwayCode: profile.pathwayRel?.code,
    enrollmentType: profile.enrollmentType,
  })

  // Rule 1: Exam Only students cannot enroll in any training modules
  if (effectiveEnrollmentType === 'EXAM_ONLY') {
    return {
      allowed: false,
      error: 'Exam-Only students cannot enroll in training modules. Please contact support to change your pathway.',
      severity: 'WARNING'
    }
  }

  // Rule 2: Modular students cannot enroll in Full-Time specific categories
  const fullTimeCategories = ['FOUR_YEAR', 'TWO_YEAR', 'MILITARY']
  if (effectiveEnrollmentType === 'MODULAR' && course.category && fullTimeCategories.includes(course.category.name)) {
    return {
      allowed: false,
      error: `Modular students cannot enroll in courses specific to ${course.category.name.replace('_', ' ')} programmes.`,
      severity: 'WARNING'
    }
  }

  // Rule 3: Pre-requisite validation
  if (course.requiresPrerequisite && course.prerequisites.length > 0) {
    const prereqResult = await validatePrerequisites(userId, course.prerequisites)
    if (!prereqResult.allowed) return prereqResult
  }

  return { allowed: true, severity: 'ERROR' }
}

/**
 * Validates that a student has completed all prerequisite courses.
 * A course is considered "completed" if the student has an enrollment with status
 * GRADUATED, or has at least one passing grade (A, B, or C) for that course.
 */
export async function validatePrerequisites(
  userId: string,
  prerequisiteCodes: string[]
): Promise<{ allowed: boolean; error?: string; severity: 'ERROR' | 'WARNING' }> {
  if (prerequisiteCodes.length === 0) return { allowed: true, severity: 'ERROR' }

  // Find all prerequisite courses by code
  const prereqCourses = await prisma.course.findMany({
    where: { code: { in: prerequisiteCodes } },
    select: { id: true, code: true, name: true },
  })

  // Check for any codes that don't match real courses (stale data)
  const foundCodes = new Set(prereqCourses.map(c => c.code))
  const missingCodes = prerequisiteCodes.filter(c => !foundCodes.has(c))
  if (missingCodes.length > 0) {
    return {
      allowed: false,
      error: `Prerequisite course(s) not found: ${missingCodes.join(', ')}. Please contact support.`,
      severity: 'ERROR',
    }
  }

  // Fetch the student's enrollments + grades for prerequisite courses
  const prereqCourseIds = prereqCourses.map(c => c.id)
  const enrollments = await prisma.enrollment.findMany({
    where: {
      userId,
      courseId: { in: prereqCourseIds },
      deletedAt: null,
    },
    select: {
      courseId: true,
      status: true,
      grades: {
        select: { grade: true },
        where: { deletedAt: null },
      },
    },
  })

  const PASSING_GRADES = ['A', 'B', 'C']
  const completedCourseIds = new Set<string>()

  for (const enrollment of enrollments) {
    // Completed if GRADUATED
    if (enrollment.status === 'GRADUATED') {
      completedCourseIds.add(enrollment.courseId)
      continue
    }
    // Or if any passing grade exists
    if (enrollment.grades.some(g => g.grade && PASSING_GRADES.includes(g.grade))) {
      completedCourseIds.add(enrollment.courseId)
    }
  }

  const unmetPrereqs = prereqCourses.filter(c => !completedCourseIds.has(c.id))
  if (unmetPrereqs.length > 0) {
    const names = unmetPrereqs.map(c => `${c.code} (${c.name})`).join(', ')
    return {
      allowed: false,
      error: `You must complete the following prerequisite(s) first: ${names}`,
      severity: 'WARNING',
    }
  }

  return { allowed: true, severity: 'ERROR' }
}

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { confirmPoolInternal, failPool } from '@/lib/pools/confirm'
import { sendEventGoEmail, sendEventNoGoEmail, sendEventPostponedEmail } from '@/lib/email/service'
import { evaluateEventViability, type EventViabilityEvaluation } from '@/lib/exams/viability'
import { rollForwardGuaranteedBookingsFromCancelledEvent } from '@/lib/exams/rollforward'
import { ACTIVE_MEMBERSHIP_STATUSES } from '@/lib/utils/constants'

export type GoNoGoEvaluation = EventViabilityEvaluation

/**
 * Evaluate event viability without executing status transitions.
 */
export async function evaluateGoNoGo(
  eventId: string,
  options?: { unfiltered?: boolean }
): Promise<GoNoGoEvaluation> {
  return evaluateEventViability(eventId, options)
}

/**
 * Execute a Go decision.
 * Only pools that meet their own threshold are confirmed; underfilled pools can remain open
 * when the event is viable overall.
 */
export async function executeGo(eventId: string, adminId: string) {
  const event = await prisma.examEvent.findUnique({
    where: { id: eventId },
    include: {
      pools: { include: { memberships: { include: { user: { include: { profile: true } } } } } },
    },
  })
  if (!event) throw new Error('Event not found')

  const result = await prisma.$transaction(async (tx) => {
    await tx.examEvent.update({
      where: { id: eventId },
      data: { status: 'CONFIRMED' },
    })

    // Fetch candidate pools then filter by each pool's own minCandidates threshold
    const candidatePools = await tx.examPool.findMany({
      where: {
        eventId,
        status: { in: ['OPEN', 'NEAR_FULL'] },
      },
      select: { id: true, minCandidates: true, currentMemberCount: true },
    })
    const confirmablePools = candidatePools.filter(
      (p) => p.currentMemberCount >= (p.minCandidates ?? 25)
    )

    for (const pool of confirmablePools) {
      await confirmPoolInternal(pool.id, tx)
    }

    await tx.examPool.updateMany({
      where: { eventId, status: 'CONFIRMED' },
      data: { status: 'LOCKED' },
    })

    return {
      success: true,
      message:
        confirmablePools.length > 0
          ? 'Event confirmed and viable pools locked.'
          : 'Event confirmed with underfilled pools still awaiting manual handling.',
    }
  })

  if (result.success) {
    const notified = new Set<string>()
    for (const pool of event.pools) {
      for (const membership of pool.memberships) {
        if (
          (membership.status === 'RESERVED' || membership.status === 'CONFIRMED') &&
          !notified.has(membership.userId)
        ) {
          notified.add(membership.userId)
          const email = membership.user.academyEmail || membership.user.email
          const name = membership.user.profile?.firstName || 'Student'
          sendEventGoEmail(email, name, event.name).catch((error) =>
            console.error('[EMAIL ERROR]', error)
          )
        }
      }
    }
  }

  return result
}

/**
 * Execute a No-Go decision by failing remaining active pools and cancelling the event.
 */
export async function executeNoGo(eventId: string, adminId: string) {
  const event = await prisma.examEvent.findUnique({
    where: { id: eventId },
    include: {
      pools: { include: { memberships: { include: { user: { include: { profile: true } } } } } },
    },
  })
  if (!event) throw new Error('Event not found')

  for (const pool of event.pools) {
    if (!['COMPLETED', 'FAILED', 'CANCELLED'].includes(pool.status)) {
      await failPool(pool.id)
    }
  }

  await prisma.examEvent.update({
    where: { id: eventId },
    data: { status: 'CANCELLED' },
  })

  const rollForwardResult = await rollForwardGuaranteedBookingsFromCancelledEvent(eventId, adminId)

  const notified = new Set<string>()
  for (const pool of event.pools) {
    for (const membership of pool.memberships) {
      if (!notified.has(membership.userId)) {
        notified.add(membership.userId)
        const email = membership.user.academyEmail || membership.user.email
        const name = membership.user.profile?.firstName || 'Student'
        sendEventNoGoEmail(email, name, event.name).catch((error) =>
          console.error('[EMAIL ERROR]', error)
        )
      }
    }
  }

  return {
    success: true,
    message:
      rollForwardResult.rolledForwardCount > 0
        ? `Event cancelled, active candidate funds released where applicable, and ${rollForwardResult.rolledForwardCount} guaranteed booking(s) rolled into ${rollForwardResult.targetEventName || 'the next event'}.`
        : rollForwardResult.deferredCount > 0
          ? `Event cancelled. ${rollForwardResult.deferredCount} guaranteed booking(s) are awaiting a future event window.`
          : 'Event cancelled and active candidate funds released.',
  }
}

/**
 * Execute a postponement by moving event and pool dates together.
 */
export async function executePostponement(
  eventId: string,
  newStartDate: Date,
  newEndDate: Date,
  adminId: string
) {
  const event = await prisma.examEvent.findUnique({
    where: { id: eventId },
    include: { pools: { include: { memberships: true } } },
  })
  if (!event) throw new Error('Event not found')

  return prisma.$transaction(async (tx) => {
    const newPaymentDeadline = new Date(newStartDate)
    newPaymentDeadline.setDate(newPaymentDeadline.getDate() - 21)

    await tx.examEvent.update({
      where: { id: eventId },
      data: {
        startDate: newStartDate,
        endDate: newEndDate,
        paymentDeadline: newPaymentDeadline,
        status: 'POSTPONED',
      },
    })

    await tx.examBooking.updateMany({
      where: {
        eventId,
        deletedAt: null,
        demandStatus: { notIn: ['EXECUTED', 'ROLLED_FORWARD', 'CANCELLED'] },
      },
      data: {
        demandStatus: 'POSTPONED',
        examDate: newStartDate,
      },
    })

    const daysDiff = Math.round(
      (newStartDate.getTime() - event.startDate.getTime()) / (1000 * 60 * 60 * 24)
    )

    for (const pool of event.pools) {
      if (['FAILED', 'CANCELLED', 'COMPLETED'].includes(pool.status)) continue

      const newExamDate = new Date(pool.examDate.getTime() + daysDiff * 24 * 60 * 60 * 1000)
      const newStart = new Date(pool.examStartTime.getTime() + daysDiff * 24 * 60 * 60 * 1000)
      const newEnd = new Date(pool.examEndTime.getTime() + daysDiff * 24 * 60 * 60 * 1000)

      await tx.examPool.update({
        where: { id: pool.id },
        data: {
          examDate: newExamDate,
          examStartTime: newStart,
          examEndTime: newEnd,
          status: pool.status === 'LOCKED' ? 'CONFIRMED' : pool.status,
        },
      })
    }

    const uniqueUserIds = new Set<string>()
    for (const pool of event.pools) {
      for (const membership of pool.memberships) {
        if (ACTIVE_MEMBERSHIP_STATUSES.includes(membership.status)) {
          uniqueUserIds.add(membership.userId)
        }
      }
    }

    for (const userId of uniqueUserIds) {
      const user = await tx.user.findUnique({
        where: { id: userId },
        select: { email: true, academyEmail: true, profile: { select: { firstName: true } } },
      })
      if (!user) continue

      const name = user.profile?.firstName || 'Student'
      const email = user.academyEmail || user.email
      const newStartDateStr = newStartDate.toLocaleDateString('en-GB', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
      })
      const newEndDateStr = newEndDate.toLocaleDateString('en-GB', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
      })

      sendEventPostponedEmail(email, name, event.name, newStartDateStr, newEndDateStr).catch(
        (error) => {
          console.error('[EMAIL ERROR] Failed to send POSTPONED to', email, error)
        }
      )
    }

    return {
      success: true,
      message: `Event postponed to ${newStartDate.toLocaleDateString()}. ${uniqueUserIds.size} candidates notified.`,
      affectedCandidates: uniqueUserIds.size,
    }
  })
}

/**
 * Merge one pool into another.
 */
export async function mergePools(sourcePoolId: string, targetPoolId: string, adminId: string) {
  return prisma.$transaction(
    async (tx) => {
      const source = await tx.examPool.findUnique({
        where: { id: sourcePoolId },
        include: { memberships: { where: { status: { in: ACTIVE_MEMBERSHIP_STATUSES } } } },
      })
      const target = await tx.examPool.findUnique({
        where: { id: targetPoolId },
      })

      if (!source || !target) throw new Error('Pool not found')

      const combinedCount = (target.currentMemberCount || 0) + source.memberships.length
      if (combinedCount > target.maxCandidates) {
        throw new Error(
          `Combined count (${combinedCount}) exceeds target max (${target.maxCandidates})`
        )
      }

      const targetMembers = await tx.poolMembership.findMany({
        where: { poolId: targetPoolId, status: { in: ACTIVE_MEMBERSHIP_STATUSES } },
        select: { userId: true },
      })
      const targetUserIds = new Set(targetMembers.map((member) => member.userId))
      const duplicates = source.memberships.filter((member) => targetUserIds.has(member.userId))
      if (duplicates.length > 0) {
        throw new Error(
          `Cannot merge: ${duplicates.length} user(s) already exist in the target pool`
        )
      }

      for (const membership of source.memberships) {
        await tx.poolMembership.update({
          where: { id: membership.id },
          data: { poolId: targetPoolId },
        })
      }

      await tx.examPool.update({
        where: { id: targetPoolId },
        data: { currentMemberCount: combinedCount },
      })

      await tx.examPool.update({
        where: { id: sourcePoolId },
        data: { status: 'MERGED', currentMemberCount: 0 },
      })

      if (combinedCount >= 25 && target.status !== 'CONFIRMED') {
        await confirmPoolInternal(targetPoolId, tx)
      }

      return {
        success: true,
        message: `Merged ${source.memberships.length} members from "${source.name}" into "${target.name}"`,
        movedMembers: source.memberships.length,
      }
    },
    { isolationLevel: Prisma.TransactionIsolationLevel.Serializable }
  )
}

import { ExamAttendanceStatus, Prisma } from '@prisma/client'
import prisma from '@/lib/prisma/client'
import { resolveEffectiveEnrollmentType } from '@/lib/enrollment/pathway'

export async function markExamAttendance(params: {
  membershipId?: string
  bookingId?: string
  sittingId?: string
  status: ExamAttendanceStatus
  notes?: string | null
  recordedBy: string
}) {
  const { membershipId, bookingId, sittingId, status, notes, recordedBy } = params

  if (!membershipId && !bookingId && !sittingId) {
    throw new Error('Must provide a membership, booking, or sitting reference')
  }

  return prisma.$transaction(async (tx) => {
    const sitting = sittingId
      ? await tx.examSitting.findUnique({
          where: { id: sittingId },
          select: {
            id: true,
            eventId: true,
            examComponentId: true,
            startTime: true,
          },
        })
      : null

    if (sittingId && !sitting) {
      throw new Error('Exam sitting not found')
    }

    const membership = membershipId
      ? await tx.poolMembership.findUnique({
          where: { id: membershipId },
          include: {
            pool: { select: { id: true, eventId: true, examDate: true } },
            examComponent: { select: { courseId: true } },
          },
        })
      : null

    if (membershipId && !membership) {
      throw new Error('Pool membership not found')
    }

    const sittingAssignment = sittingId
      ? await tx.examSittingAssignment.findFirst({
          where: {
            sittingId,
            ...(bookingId ? { bookingId } : {}),
            status: { in: ['ASSIGNED', 'CONFIRMED', 'ATTENDED', 'ABSENT', 'EXCUSED'] },
          },
          select: {
            id: true,
            bookingId: true,
            userId: true,
          },
          orderBy: { assignedAt: 'desc' },
        })
      : null

    const resolvedBookingId = bookingId || sittingAssignment?.bookingId || membership?.bookingId || undefined
    const booking = resolvedBookingId
      ? await tx.examBooking.findUnique({
          where: { id: resolvedBookingId },
        select: {
          id: true,
          userId: true,
          eventId: true,
          examId: true,
          examComponentId: true,
          courseId: true,
          examComponent: { select: { courseId: true } },
          examDate: true,
          result: true,
          score: true,
            percentage: true,
            status: true,
          },
        })
      : null

    if (resolvedBookingId && !booking) {
      throw new Error('Exam booking not found')
    }

    const userId = booking?.userId || membership?.userId || sittingAssignment?.userId
    if (!userId) {
      throw new Error('Unable to resolve exam-attendance student')
    }

    const attendanceDate = sitting?.startTime || booking?.examDate || membership?.pool.examDate || new Date()
    const normalizedNotes = notes?.trim() || null
    const courseId =
      booking?.courseId ||
      booking?.examComponent?.courseId ||
      membership?.examComponent?.courseId ||
      null

    const studentProfile = await tx.studentProfile.findUnique({
      where: { userId },
      select: {
        enrollmentType: true,
        programmeChoice: true,
        academicYearId: true,
        semesterId: true,
      },
    })

    const effectiveEnrollmentType = studentProfile
      ? resolveEffectiveEnrollmentType({
          enrollmentType: studentProfile.enrollmentType,
          programmeChoice: studentProfile.programmeChoice,
        })
      : null

    let classId: string | null = null
    if (courseId && effectiveEnrollmentType === 'FULL_TIME') {
      const linkedClass = await tx.class.findFirst({
        where: {
          courseId,
          ...(studentProfile?.academicYearId ? { academicYearId: studentProfile.academicYearId } : {}),
          ...(studentProfile?.semesterId ? { semesterId: studentProfile.semesterId } : {}),
        },
        select: { id: true },
        orderBy: [{ startDate: 'desc' }, { createdAt: 'desc' }],
      })

      if (linkedClass) {
        classId = linkedClass.id
      } else {
        const fallbackClass = await tx.class.findFirst({
          where: { courseId },
          select: { id: true },
          orderBy: [{ startDate: 'desc' }, { createdAt: 'desc' }],
        })
        classId = fallbackClass?.id || null
      }
    }

    const payload = {
      userId,
      bookingId: booking?.id || null,
      membershipId: membership?.id || null,
      sittingId: sitting?.id || null,
      eventId: sitting?.eventId || booking?.eventId || membership?.pool.eventId || null,
      examId: booking?.examId || null,
      examComponentId: sitting?.examComponentId || booking?.examComponentId || membership?.examComponentId || null,
      classId,
      attendanceDate,
      status,
      notes: normalizedNotes,
      recordedBy,
    }

    const attendance =
      booking?.id
        ? await tx.examAttendance.upsert({
            where: { bookingId: booking.id },
            update: payload,
            create: payload,
          })
        : await tx.examAttendance.upsert({
            where: { membershipId: membership!.id },
            update: payload,
            create: payload,
          })

    if (booking?.id) {
      if (status === ExamAttendanceStatus.PRESENT) {
        const currentResult = booking.result?.toUpperCase()
        await tx.examBooking.update({
          where: { id: booking.id },
          data: {
            status: booking.status === 'NO_SHOW' ? 'APPROVED' : booking.status,
            demandStatus: 'EXECUTED',
            executedAt: attendanceDate,
            // Clear any stale absence/excusal fields if re-marking present
            ...(currentResult === 'ABSENT' || currentResult === 'EXCUSED'
              ? {
                  result: null,
                  cancellationReason: null,
                  cancelledAt: null,
                  cancelledBy: null,
                }
              : {}),
          },
        })
      } else if (status === ExamAttendanceStatus.ABSENT) {
        // Absent: seat is consumed but not passed — mark as no-show
        await tx.examBooking.update({
          where: { id: booking.id },
          data: {
            status: 'NO_SHOW',
            result: 'ABSENT',
            cancellationReason: 'Marked absent for exam attendance',
            cancelledAt: new Date(),
            cancelledBy: recordedBy,
          },
        })
      } else {
        // EXCUSED: the candidate did not sit but their paid guarantee is STILL OWED.
        // Do NOT mark as EXECUTED, do NOT set cancellation fields.
        // The booking stays SCHEDULED — fulfillment remains pending.
        await tx.examBooking.update({
          where: { id: booking.id },
          data: {
            result: 'EXCUSED',
            // Ensure any stale cancellation stamps are cleared
            cancellationReason: null,
            cancelledAt: null,
            cancelledBy: null,
          },
        })
      }
    }

    if (booking?.id && (sitting?.id || sittingAssignment?.id)) {
      await tx.examSittingAssignment.updateMany({
        where: {
          bookingId: booking.id,
          ...(sitting?.id ? { sittingId: sitting.id } : {}),
          status: { in: ['ASSIGNED', 'CONFIRMED', 'ATTENDED', 'ABSENT', 'EXCUSED'] },
        },
        data: {
          attendanceStatus: status,
          status:
            status === ExamAttendanceStatus.PRESENT
              ? 'ATTENDED'
              : status === ExamAttendanceStatus.ABSENT
                ? 'ABSENT'
                : 'EXCUSED',
        },
      })
    }

    if (membership?.id) {
      const membershipStatus =
        status === ExamAttendanceStatus.PRESENT
          ? 'CONFIRMED'
          : status === ExamAttendanceStatus.ABSENT
            ? 'NO_SHOW'
            : membership.status

      if (membership.status !== membershipStatus) {
        await tx.poolMembership.update({
          where: { id: membership.id },
          data: { status: membershipStatus as any },
        })
      }
    }

    return {
      attendance,
      bookingId: booking?.id || null,
      membershipId: membership?.id || null,
      sittingId: sitting?.id || null,
      eventId: sitting?.eventId || booking?.eventId || membership?.pool.eventId || null,
      userId,
      poolId: membership?.poolId || null,
    }
  }, {
    isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
  })
}

import { Prisma, SessionType, SittingAssignmentStatus, SittingStatus } from '@prisma/client'
import prisma from '@/lib/prisma/client'
import type { EventDemandSnapshot } from '@/lib/exams/demand'
import { getHolidayDates, isHolidayDate } from '@/lib/calendar/holidays'

const DEFAULT_SITTING_CAPACITY = 28
const DEFAULT_MAX_DAILY_EXAMS = 2
const DEFAULT_DURATION_MINUTES = 120

const ACTIVE_BOOKING_STATUSES = ['PENDING', 'APPROVED', 'PROCESSING', 'COMPLETED', 'NO_SHOW'] as const
const ACTIVE_DEMAND_STATUSES = ['DEMAND_CAPTURED', 'POOLED', 'SCHEDULED', 'POSTPONED'] as const
const ACTIVE_ASSIGNMENT_STATUSES = ['ASSIGNED', 'CONFIRMED', 'ATTENDED', 'ABSENT', 'EXCUSED'] as const
const FINAL_ASSIGNMENT_STATUSES = ['ATTENDED', 'ABSENT', 'EXCUSED'] as const

type ScheduleCandidate = {
  bookingId: string
  userId: string
  examComponentId: string
  moduleCode: string
  bookedAt: Date
  guaranteedSeat: boolean
  preferredSessionType: SessionType | null
}

type SlotKey = {
  dayNumber: number
  sessionType: SessionType
}

type SittingPlan = SlotKey & {
  examComponentId: string
  moduleCode: string
  bookingIds: string[]
}

function getInclusiveDayCount(start: Date, end: Date) {
  const normalizedStart = new Date(start)
  normalizedStart.setHours(0, 0, 0, 0)
  const normalizedEnd = new Date(end)
  normalizedEnd.setHours(0, 0, 0, 0)
  return Math.max(1, Math.floor((normalizedEnd.getTime() - normalizedStart.getTime()) / 86400000) + 1)
}

function getEventDayDate(startDate: Date, dayNumber: number) {
  const next = new Date(startDate)
  next.setDate(next.getDate() + (dayNumber - 1))
  return next
}

/**
 * Returns the start/end window for a session slot.
 * Uses ExamComponent.duration (minutes) when provided; falls back to a 3-hour block.
 */
function getSessionWindow(baseDate: Date, sessionType: SessionType, durationMinutes = DEFAULT_DURATION_MINUTES) {
  const start = new Date(baseDate)

  if (sessionType === 'MORNING') {
    start.setHours(9, 0, 0, 0)
  } else if (sessionType === 'AFTERNOON') {
    start.setHours(14, 0, 0, 0)
  } else {
    start.setHours(18, 0, 0, 0)
  }

  const end = new Date(start.getTime() + durationMinutes * 60_000)
  return { start, end }
}

/**
 * Picks the best available examiner for a time window.
 * Respects examiner.maxParallelSittings — supports future multi-examiner events.
 */
async function getExaminerForSlot(
  tx: Prisma.TransactionClient,
  slotStart: Date,
  slotEnd: Date,
): Promise<string | null> {
  const examiners = await tx.examiner.findMany({
    where: { isActive: true },
    select: { id: true, maxParallelSittings: true },
    orderBy: { createdAt: 'asc' },
  })
  if (examiners.length === 0) return null

  for (const examiner of examiners) {
    const overlapping = await tx.examSitting.count({
      where: {
        examinerId: examiner.id,
        status: { notIn: ['CANCELLED'] },
        startTime: { lt: slotEnd },
        endTime: { gt: slotStart },
      },
    })
    if (overlapping < examiner.maxParallelSittings) return examiner.id
  }
  return null
}

function slotToken(slot: SlotKey) {
  return `${slot.dayNumber}:${slot.sessionType}`
}

function buildSlotQueue(requiredCount: number, initialDayCount: number, excludedDays?: Set<number>): SlotKey[] {
  const slots: SlotKey[] = []
  const totalDays = Math.max(initialDayCount, Math.ceil(requiredCount / 2))

  for (let dayNumber = 1; dayNumber <= totalDays; dayNumber += 1) {
    if (excludedDays?.has(dayNumber)) continue // Skip holidays
    slots.push({ dayNumber, sessionType: 'MORNING' })
    slots.push({ dayNumber, sessionType: 'AFTERNOON' })
  }

  return slots
}

function choosePreferredSession(candidates: ScheduleCandidate[]) {
  let morning = 0
  let afternoon = 0

  for (const candidate of candidates) {
    if (candidate.preferredSessionType === 'MORNING') morning += 1
    if (candidate.preferredSessionType === 'AFTERNOON') afternoon += 1
  }

  if (morning > afternoon) return 'MORNING' as const
  if (afternoon > morning) return 'AFTERNOON' as const
  return null
}

function sortCandidates(candidates: ScheduleCandidate[]) {
  return [...candidates].sort((a, b) => {
    if (a.guaranteedSeat !== b.guaranteedSeat) return a.guaranteedSeat ? -1 : 1
    if (a.preferredSessionType !== b.preferredSessionType) {
      if (a.preferredSessionType === 'MORNING') return -1
      if (b.preferredSessionType === 'MORNING') return 1
    }
    return a.bookedAt.getTime() - b.bookedAt.getTime()
  })
}

function canUseSlot(
  slot: SlotKey,
  bookings: ScheduleCandidate[],
  occupiedSlots: Set<string>,
  userSlots: Map<string, Set<string>>,
  userDailyCounts: Map<string, Map<number, number>>
) {
  if (occupiedSlots.has(slotToken(slot))) return false

  for (const booking of bookings) {
    if (userSlots.get(booking.userId)?.has(slotToken(slot))) return false
    if ((userDailyCounts.get(booking.userId)?.get(slot.dayNumber) ?? 0) >= DEFAULT_MAX_DAILY_EXAMS) {
      return false
    }
  }

  return true
}

function reserveSlot(
  slot: SlotKey,
  bookings: ScheduleCandidate[],
  occupiedSlots: Set<string>,
  userSlots: Map<string, Set<string>>,
  userDailyCounts: Map<string, Map<number, number>>
) {
  occupiedSlots.add(slotToken(slot))

  for (const booking of bookings) {
    const slots = userSlots.get(booking.userId) ?? new Set<string>()
    slots.add(slotToken(slot))
    userSlots.set(booking.userId, slots)

    const dailyCounts = userDailyCounts.get(booking.userId) ?? new Map<number, number>()
    dailyCounts.set(slot.dayNumber, (dailyCounts.get(slot.dayNumber) ?? 0) + 1)
    userDailyCounts.set(booking.userId, dailyCounts)
  }
}

function buildSittingPlans(
  groupedCandidates: Array<{ examComponentId: string; moduleCode: string; bookings: ScheduleCandidate[] }>,
  initialDayCount: number,
  existingSlots: Set<string>,
  existingUserSlots: Map<string, Set<string>>,
  existingUserDailyCounts: Map<string, Map<number, number>>,
  excludedDays?: Set<number>
) {
  const requiredCount = groupedCandidates.reduce(
    (sum, group) => sum + Math.max(1, Math.ceil(group.bookings.length / DEFAULT_SITTING_CAPACITY)),
    0
  )

  const slots = buildSlotQueue(requiredCount + existingSlots.size, initialDayCount, excludedDays)
  const occupiedSlots = new Set(existingSlots)
  const userSlots = new Map(existingUserSlots)
  const userDailyCounts = new Map(existingUserDailyCounts)
  const plans: SittingPlan[] = []

  for (const group of groupedCandidates) {
    const sorted = sortCandidates(group.bookings)
    for (let index = 0; index < sorted.length; index += DEFAULT_SITTING_CAPACITY) {
      const chunk = sorted.slice(index, index + DEFAULT_SITTING_CAPACITY)
      const preferredSession = choosePreferredSession(chunk)

      let chosenSlot =
        slots.find(
          (slot) =>
            slot.sessionType === preferredSession &&
            canUseSlot(slot, chunk, occupiedSlots, userSlots, userDailyCounts)
        ) ?? null

      if (!chosenSlot) {
        chosenSlot =
          slots.find((slot) => canUseSlot(slot, chunk, occupiedSlots, userSlots, userDailyCounts)) ??
          null
      }

      if (!chosenSlot) {
        const dayNumber = Math.floor(slots.length / 2) + 1
        chosenSlot = {
          dayNumber,
          sessionType: slots.length % 2 === 0 ? 'MORNING' : 'AFTERNOON',
        }
        slots.push(chosenSlot)
      }

      reserveSlot(chosenSlot, chunk, occupiedSlots, userSlots, userDailyCounts)
      plans.push({
        examComponentId: group.examComponentId,
        moduleCode: group.moduleCode,
        dayNumber: chosenSlot.dayNumber,
        sessionType: chosenSlot.sessionType,
        bookingIds: chunk.map((booking) => booking.bookingId),
      })
    }
  }

  return plans
}

export async function scheduleEventSittings(
  eventId: string,
  options?: {
    preserveExistingAssignments?: boolean
    actorId?: string | null
  }
) {
  const preserveExistingAssignments = options?.preserveExistingAssignments ?? true

  return prisma.$transaction(async (tx) => {
    const event = await tx.examEvent.findUnique({
      where: { id: eventId },
      select: {
        id: true,
        name: true,
        startDate: true,
        endDate: true,
        location: true,
        status: true,
        examBookings: {
          where: {
            deletedAt: null,
            status: { in: [...ACTIVE_BOOKING_STATUSES] },
            demandStatus: { in: [...ACTIVE_DEMAND_STATUSES] },
          },
          select: {
            id: true,
            userId: true,
            examComponentId: true,
            moduleCode: true,
            bookedAt: true,
            guaranteedSeat: true,
            preferredSessionType: true,
            status: true,
            examAttendance: { select: { id: true } },
            sittingAssignments: {
              where: { status: { in: [...ACTIVE_ASSIGNMENT_STATUSES] } },
              select: {
                id: true,
                status: true,
                sittingId: true,
                sitting: {
                  select: {
                    id: true,
                    dayNumber: true,
                    sessionType: true,
                    examComponentId: true,
                  },
                },
              },
              orderBy: { assignedAt: 'desc' },
            },
            examComponent: {
              select: {
                id: true,
                course: { select: { code: true } },
              },
            },
          },
          orderBy: [{ guaranteedSeat: 'desc' }, { bookedAt: 'asc' }],
        },
      },
    })

    if (!event) throw new Error('Exam event not found')

    const existingSlots = new Set<string>()
    const existingUserSlots = new Map<string, Set<string>>()
    const existingUserDailyCounts = new Map<string, Map<number, number>>()
    const groupedCandidates = new Map<
      string,
      { examComponentId: string; moduleCode: string; bookings: ScheduleCandidate[] }
    >()

    for (const booking of event.examBookings) {
      const moduleCode = booking.moduleCode?.trim() || booking.examComponent?.course?.code?.trim() || null
      if (!booking.examComponentId || !moduleCode) continue

      const activeAssignment = booking.sittingAssignments[0]
      if (preserveExistingAssignments && activeAssignment) {
        reserveSlot(
          {
            dayNumber: activeAssignment.sitting.dayNumber,
            sessionType: activeAssignment.sitting.sessionType,
          },
          [
            {
              bookingId: booking.id,
              userId: booking.userId,
              examComponentId: booking.examComponentId,
              moduleCode,
              bookedAt: booking.bookedAt,
              guaranteedSeat: booking.guaranteedSeat,
              preferredSessionType: booking.preferredSessionType,
            },
          ],
          existingSlots,
          existingUserSlots,
          existingUserDailyCounts
        )
        continue
      }

      const key = `${booking.examComponentId}:${moduleCode}`
      const group = groupedCandidates.get(key) ?? {
        examComponentId: booking.examComponentId,
        moduleCode,
        bookings: [],
      }

      group.bookings.push({
        bookingId: booking.id,
        userId: booking.userId,
        examComponentId: booking.examComponentId,
        moduleCode,
        bookedAt: booking.bookedAt,
        guaranteedSeat: booking.guaranteedSeat,
        preferredSessionType: booking.preferredSessionType,
      })
      groupedCandidates.set(key, group)
    }

    const groupedList = Array.from(groupedCandidates.values()).sort((a, b) => {
      const guaranteedDiff =
        b.bookings.filter((booking) => booking.guaranteedSeat).length -
        a.bookings.filter((booking) => booking.guaranteedSeat).length
      if (guaranteedDiff !== 0) return guaranteedDiff
      return b.bookings.length - a.bookings.length
    })

    // Fetch holidays within the event date range and convert to excluded day numbers
    const holidayDates = await getHolidayDates(event.startDate, event.endDate)
    const excludedDays = new Set<number>()
    const totalDays = getInclusiveDayCount(event.startDate, event.endDate)
    for (let d = 1; d <= totalDays; d++) {
      const dayDate = getEventDayDate(event.startDate, d)
      if (isHolidayDate(dayDate, holidayDates)) {
        excludedDays.add(d)
      }
    }

    const plans = buildSittingPlans(
      groupedList,
      totalDays,
      existingSlots,
      existingUserSlots,
      existingUserDailyCounts,
      excludedDays
    )

    const existingSittings = await tx.examSitting.findMany({
      where: { eventId },
      select: {
        id: true,
        examinerId: true,
        examComponentId: true,
        dayNumber: true,
        sessionType: true,
      },
    })

    for (const plan of plans) {
      // Look up component duration for accurate session window
      const componentDuration = await tx.examComponent
        .findUnique({ where: { id: plan.examComponentId }, select: { duration: true } })
        .then((c) => c?.duration ?? DEFAULT_DURATION_MINUTES)

      const sessionDate = getEventDayDate(event.startDate, plan.dayNumber)
      const window = getSessionWindow(sessionDate, plan.sessionType, componentDuration)

      // Pick the least-loaded available examiner for this specific window
      const examinerId = await getExaminerForSlot(tx, window.start, window.end)

      const matchedSitting = existingSittings.find(
        (sitting) =>
          sitting.examComponentId === plan.examComponentId &&
          sitting.dayNumber === plan.dayNumber &&
          sitting.sessionType === plan.sessionType
      )

      const confirmedSeats = await tx.examBooking.count({
        where: {
          id: { in: plan.bookingIds },
          status: { in: ['APPROVED', 'PROCESSING', 'COMPLETED', 'NO_SHOW'] },
        },
      })

      const sitting =
        matchedSitting
          ? await tx.examSitting.update({
              where: { id: matchedSitting.id },
              data: {
                startTime: window.start,
                endTime: window.end,
                venue: event.location,
                reservedSeats: plan.bookingIds.length,
                confirmedSeats,
                examinerId: examinerId ?? matchedSitting.examinerId,
                status: event.status === 'CONFIRMED' ? SittingStatus.CONFIRMED : SittingStatus.SCHEDULED,
              },
            })
          : await tx.examSitting.create({
              data: {
                eventId,
                examinerId,
                examComponentId: plan.examComponentId,
                dayNumber: plan.dayNumber,
                sessionType: plan.sessionType,
                startTime: window.start,
                endTime: window.end,
                capacity: DEFAULT_SITTING_CAPACITY,
                reservedSeats: plan.bookingIds.length,
                confirmedSeats,
                status: event.status === 'CONFIRMED' ? SittingStatus.CONFIRMED : SittingStatus.SCHEDULED,
                venue: event.location,
                notes: 'Generated by sitting scheduler',
              },
            })

      for (const bookingId of plan.bookingIds) {
        const booking = event.examBookings.find((item) => item.id === bookingId)
        if (!booking) continue

        await tx.examSittingAssignment.upsert({
          where: {
            bookingId_sittingId: {
              bookingId,
              sittingId: sitting.id,
            },
          },
          update: {
            userId: booking.userId,
            status:
              booking.status === 'APPROVED' || booking.status === 'COMPLETED'
                ? SittingAssignmentStatus.CONFIRMED
                : SittingAssignmentStatus.ASSIGNED,
            assignedBy: options?.actorId ?? null,
          },
          create: {
            sittingId: sitting.id,
            bookingId,
            userId: booking.userId,
            status:
              booking.status === 'APPROVED' || booking.status === 'COMPLETED'
                ? SittingAssignmentStatus.CONFIRMED
                : SittingAssignmentStatus.ASSIGNED,
            assignedBy: options?.actorId ?? null,
          },
        })

        await tx.examSittingAssignment.updateMany({
          where: {
            bookingId,
            sittingId: { not: sitting.id },
            status: { in: ['ASSIGNED', 'CONFIRMED'] },
          },
          data: { status: 'CANCELLED', attendanceStatus: null },
        })

        await tx.examBooking.update({
          where: { id: bookingId },
          data: {
            demandStatus: 'SCHEDULED',
            examDate: window.start,
          },
        })

        if (booking.examAttendance?.id) {
          await tx.examAttendance.update({
            where: { bookingId },
            data: {
              sittingId: sitting.id,
              attendanceDate: window.start,
              eventId,
              examComponentId: plan.examComponentId,
            },
          })
        }
      }
    }

    const refreshedSittings = await tx.examSitting.findMany({
      where: { eventId },
      select: {
        id: true,
        assignments: {
          where: { status: { in: ['ASSIGNED', 'CONFIRMED', 'ATTENDED', 'ABSENT', 'EXCUSED'] } },
          select: { status: true },
        },
      },
    })

    for (const sitting of refreshedSittings) {
      await tx.examSitting.update({
        where: { id: sitting.id },
        data: {
          reservedSeats: sitting.assignments.length,
          confirmedSeats: sitting.assignments.filter((assignment) =>
            ['CONFIRMED', 'ATTENDED', 'ABSENT', 'EXCUSED'].includes(assignment.status)
          ).length,
        },
      })
    }

    return {
      eventId: event.id,
      eventName: event.name,
      generatedSittings: plans.length,
      preservedAssignments: existingSlots.size,
    }
  }, {
    isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
  })
}

/**
 * Phase 5 — demand-snapshot entry point.
 *
 * Accepts a pre-fetched EventDemandSnapshot (from lib/exams/demand.ts) to allow
 * callers to detect demand gaps before scheduling. The demand snapshot is used to
 * surface unscheduled guaranteed modules in the result; the actual sitting creation
 * still runs through scheduleEventSittings so all slot/examiner logic is shared.
 */
export async function scheduleEventSittingsFromDemand(
  eventId: string,
  demandSnapshot: EventDemandSnapshot,
  options?: { preserveExistingAssignments?: boolean; actorId?: string | null }
) {
  const result = await scheduleEventSittings(eventId, options)

  // Surface which guaranteed modules had demand but may still be unscheduled
  const guaranteedModules = demandSnapshot.modules.filter((m) => m.guaranteedCount > 0)
  const scheduledModuleCodes = new Set(
    await prisma.examSitting.findMany({
      where: { eventId },
      select: { examComponent: { select: { course: { select: { code: true } } } } },
    }).then((sittings) =>
      sittings
        .map((s) => s.examComponent?.course?.code)
        .filter((c): c is string => Boolean(c))
    )
  )

  const unscheduledGuaranteedModules = guaranteedModules
    .filter((m) => !scheduledModuleCodes.has(m.moduleCode))
    .map((m) => m.moduleCode)

  return { ...result, unscheduledGuaranteedModules }
}

// ─── Conflict Detection (Phase 5 warning panel) ───────────────────────────────

export type SchedulingConflictType =
  | 'CANDIDATE_OVERLAP'
  | 'EXAMINER_OVERLAP'
  | 'VENUE_OVERLAP'
  | 'SPARE_CAPACITY'
  | 'UNSCHEDULED_GUARANTEED'

export interface SchedulingConflict {
  type: SchedulingConflictType
  sittingId?: string
  userId?: string
  examinerId?: string
  venue?: string
  moduleCode?: string
  description: string
}

function timesOverlap(a: { startTime: Date | null; endTime: Date | null }, b: { startTime: Date | null; endTime: Date | null }): boolean {
  if (!a.startTime || !a.endTime || !b.startTime || !b.endTime) return false
  return a.startTime < b.endTime && b.startTime < a.endTime
}

/**
 * Phase 5 — detect scheduling problems for the staff warning panel.
 * Checks:
 *  - same candidate assigned to two overlapping sittings
 *  - same examiner assigned to two overlapping sittings
 *  - sittings with spare capacity
 *  - guaranteed bookings with no sitting assignment yet
 */
export async function detectSchedulingConflicts(eventId: string): Promise<SchedulingConflict[]> {
  const conflicts: SchedulingConflict[] = []

  const sittings = await prisma.examSitting.findMany({
    where: { eventId, status: { notIn: ['CANCELLED'] } },
    select: {
      id: true,
      examinerId: true,
      examiner: { select: { maxParallelSittings: true } },
      dayNumber: true,
      sessionType: true,
      startTime: true,
      endTime: true,
      capacity: true,
      venue: true,
      examComponent: { select: { course: { select: { code: true } } } },
      assignments: {
        where: { status: { in: ['ASSIGNED', 'CONFIRMED'] } },
        select: { userId: true },
      },
    },
  })

  // ── Candidate overlap (time-based) ──
  type SlotInfo = { dayNumber: number; startTime: Date | null; endTime: Date | null; sessionType: string; sittingId: string }
  const userSlotMap = new Map<string, SlotInfo[]>()
  for (const sitting of sittings) {
    for (const assignment of sitting.assignments) {
      const prior = userSlotMap.get(assignment.userId) ?? []
      const overlap = prior.find(
        (s) => s.dayNumber === sitting.dayNumber && (timesOverlap(s, sitting) || s.sessionType === sitting.sessionType)
      )
      if (overlap) {
        conflicts.push({
          type: 'CANDIDATE_OVERLAP',
          sittingId: sitting.id,
          userId: assignment.userId,
          description: `Candidate double-booked on Day ${sitting.dayNumber} ${sitting.sessionType}`,
        })
      }
      prior.push({ dayNumber: sitting.dayNumber, startTime: sitting.startTime, endTime: sitting.endTime, sessionType: sitting.sessionType, sittingId: sitting.id })
      userSlotMap.set(assignment.userId, prior)
    }
  }

  // ── Examiner overlap (respects maxParallelSittings) ──
  const examinerSlotMap = new Map<string, SlotInfo[]>()
  for (const sitting of sittings) {
    if (!sitting.examinerId) continue
    const maxParallel = sitting.examiner?.maxParallelSittings ?? 1
    const prior = examinerSlotMap.get(sitting.examinerId) ?? []
    const overlapping = prior.filter(
      (s) => s.dayNumber === sitting.dayNumber && (timesOverlap(s, sitting) || s.sessionType === sitting.sessionType)
    )
    if (overlapping.length >= maxParallel) {
      conflicts.push({
        type: 'EXAMINER_OVERLAP',
        sittingId: sitting.id,
        examinerId: sitting.examinerId,
        description: `Examiner exceeds ${maxParallel} parallel sitting(s) on Day ${sitting.dayNumber} ${sitting.sessionType}`,
      })
    }
    prior.push({ dayNumber: sitting.dayNumber, startTime: sitting.startTime, endTime: sitting.endTime, sessionType: sitting.sessionType, sittingId: sitting.id })
    examinerSlotMap.set(sitting.examinerId, prior)
  }

  // ── Venue overlap (same room, overlapping times) ──
  const venueSlotMap = new Map<string, Array<SlotInfo & { moduleCode?: string }>>()
  for (const sitting of sittings) {
    if (!sitting.venue) continue
    const venueKey = sitting.venue.trim().toLowerCase()
    const prior = venueSlotMap.get(venueKey) ?? []
    const overlap = prior.find(
      (s) => s.dayNumber === sitting.dayNumber && timesOverlap(s, sitting)
    )
    if (overlap) {
      conflicts.push({
        type: 'VENUE_OVERLAP',
        sittingId: sitting.id,
        venue: sitting.venue,
        description: `Venue "${sitting.venue}" double-booked on Day ${sitting.dayNumber} (conflicts with sitting ${overlap.sittingId})`,
      })
    }
    prior.push({ dayNumber: sitting.dayNumber, startTime: sitting.startTime, endTime: sitting.endTime, sessionType: sitting.sessionType, sittingId: sitting.id, moduleCode: sitting.examComponent?.course?.code })
    venueSlotMap.set(venueKey, prior)
  }

  // ── Spare capacity ──
  for (const sitting of sittings) {
    const assigned = sitting.assignments.length
    const spare = sitting.capacity - assigned
    if (spare > 0 && assigned > 0) {
      conflicts.push({
        type: 'SPARE_CAPACITY',
        sittingId: sitting.id,
        moduleCode: sitting.examComponent?.course?.code ?? undefined,
        description: `${spare} spare seat(s) available (${assigned}/${sitting.capacity} filled)`,
      })
    }
  }

  // ── Unscheduled guaranteed demand ──
  const unscheduled = await prisma.examBooking.findMany({
    where: {
      eventId,
      deletedAt: null,
      guaranteedSeat: true,
      demandStatus: { in: ['DEMAND_CAPTURED', 'POOLED'] },
      sittingAssignments: { none: { status: { in: ['ASSIGNED', 'CONFIRMED'] } } },
    },
    select: { id: true, moduleCode: true, userId: true },
  })
  for (const booking of unscheduled) {
    conflicts.push({
      type: 'UNSCHEDULED_GUARANTEED',
      userId: booking.userId,
      moduleCode: booking.moduleCode ?? undefined,
      description: `Guaranteed booking for module "${booking.moduleCode ?? 'unknown'}" has no sitting assignment`,
    })
  }

  return conflicts
}

/**
 * Data-protection retention sweeper.
 *
 * Reads `RetentionPolicy` rows and, for each, soft-deletes (sets
 * `deletedAt`) rows in the named entity whose anchor field is older than
 * `retentionDays`. Conservative: never hard-deletes.
 *
 * Default policies are seeded by `seedDefaultRetentionPolicies()` on first
 * data protection page load. Admins edit values via `/staff/settings/retention`.
 */

import 'server-only'
import { prismaUnfiltered } from '@/lib/prisma/client'

interface PolicyDefault {
  entity: string
  retentionDays: number
  anchor: 'CREATED_AT' | 'UPDATED_AT' | 'GRADUATION'
  description: string
}

/**
 * Models that support soft-delete (have a `deletedAt` column).
 * The sweep sets `deletedAt = now()` on expired rows.
 */
const SOFT_DELETABLE_MODELS = new Set([
  'User',
  'AdminNote',
  'Enrollment',
  'Grade',
  'ExamEvent',
  'PoolMembership',
  'ExamBooking',
  'Payment',
  'AdminCalendarEvent',
  'ExamResult',
])

/**
 * Ephemeral models that do NOT have `deletedAt` but are safe to hard-delete
 * after their retention period. These are transient records with no
 * cascading side-effects on financial or regulatory data.
 */
const HARD_DELETABLE_MODELS = new Set([
  'Notification',
  'Message',
])

/**
 * Default retention policies. Note:
 * - Wallet is intentionally EXCLUDED — wallets should persist as long as the
 *   owning user exists. Financial transaction history is retained via
 *   WalletTransaction which cascades from Wallet, so deleting wallets would
 *   also destroy transaction audit trails.
 * - AuditLog is intentionally EXCLUDED — audit logs should be archived
 *   (moved to AuditLogArchive) rather than deleted. They are governance
 *   records required for EASA Part-147 compliance.
 */
const DEFAULTS: PolicyDefault[] = [
  { entity: 'Payment', retentionDays: 5 * 365, anchor: 'CREATED_AT', description: '5 years — financial record retention' },
  { entity: 'Notification', retentionDays: 3 * 365, anchor: 'CREATED_AT', description: '3 years — operational messaging' },
  { entity: 'Message', retentionDays: 3 * 365, anchor: 'CREATED_AT', description: '3 years — staff/student correspondence' },
  { entity: 'Enrollment', retentionDays: 7 * 365, anchor: 'GRADUATION', description: 'Graduation + 7 years — EASA training record retention' },
  { entity: 'Grade', retentionDays: 7 * 365, anchor: 'GRADUATION', description: 'Graduation + 7 years' },
  { entity: 'ExamResult', retentionDays: 7 * 365, anchor: 'GRADUATION', description: 'Graduation + 7 years' },
]

export async function seedDefaultRetentionPolicies() {
  for (const d of DEFAULTS) {
    await prismaUnfiltered.retentionPolicy.upsert({
      where: { entity: d.entity },
      create: d,
      update: {}, // never overwrite admin edits
    })
  }
}

/**
 * For each active policy, soft-delete or hard-delete rows older than
 * retentionDays, depending on whether the model supports soft-delete.
 *
 * GRADUATION anchor is honoured for Enrollment/Grade/ExamResult:
 * only sweeps rows whose owning user has a StudentProfile with
 * `graduationDate` older than `retentionDays` ago. If the student
 * has not graduated yet, their records are never swept.
 *
 * Returns per-entity counts; intended to be called by the weekly cron at
 * `/api/cron/gdpr-retention`.
 */
export async function runRetentionSweep(): Promise<Array<{ entity: string; affected: number; error?: string }>> {
  const policies = await prismaUnfiltered.retentionPolicy.findMany({
    where: { isActive: true },
  })

  const results: Array<{ entity: string; affected: number; error?: string }> = []

  for (const p of policies) {
    try {
      const affected = await applyPolicy(p.entity, p.retentionDays, p.anchor as PolicyDefault['anchor'])
      results.push({ entity: p.entity, affected })
    } catch (err: any) {
      results.push({ entity: p.entity, affected: 0, error: err.message })
    }
  }
  return results
}

async function applyPolicy(
  entity: string,
  retentionDays: number,
  anchor: 'CREATED_AT' | 'UPDATED_AT' | 'GRADUATION'
): Promise<number> {
  const cutoff = new Date(Date.now() - retentionDays * 24 * 60 * 60 * 1000)

  // Lowercase first char to map to Prisma client property
  const modelKey = entity[0].toLowerCase() + entity.slice(1)
  const model = (prismaUnfiltered as any)[modelKey]
  if (!model) throw new Error(`Unknown entity "${entity}" — no Prisma model found`)

  const isSoftDeletable = SOFT_DELETABLE_MODELS.has(entity)
  const isHardDeletable = HARD_DELETABLE_MODELS.has(entity)

  // Safety check: refuse to process entities not explicitly allowed
  if (!isSoftDeletable && !isHardDeletable) {
    throw new Error(
      `Entity "${entity}" is not in SOFT_DELETABLE_MODELS or HARD_DELETABLE_MODELS — refusing to delete. ` +
      `Add it to the appropriate set or remove this retention policy.`
    )
  }

  // For GRADUATION-anchored models, find user IDs whose StudentProfile
  // has a graduationDate older than the cutoff. Only sweep those users' records.
  if (anchor === 'GRADUATION') {
    return applyGraduationPolicy(model, entity, cutoff, isSoftDeletable)
  }

  // CREATED_AT or UPDATED_AT anchor
  const field = anchor === 'UPDATED_AT' ? 'updatedAt' : 'createdAt'

  if (isSoftDeletable) {
    // Soft-delete: set deletedAt on rows past retention, only if not already deleted
    const r = await model.updateMany({
      where: { [field]: { lt: cutoff }, deletedAt: null } as any,
      data: { deletedAt: new Date() },
    })
    return r.count
  }

  // Hard-delete: only for explicitly allowed ephemeral models
  const r = await model.deleteMany({
    where: { [field]: { lt: cutoff } },
  })
  return r.count
}

/**
 * GRADUATION anchor: sweep only records belonging to users who graduated
 * more than `retentionDays` ago. Students who haven't graduated are never
 * swept.
 */
async function applyGraduationPolicy(
  model: any,
  entity: string,
  cutoff: Date,
  isSoftDeletable: boolean
): Promise<number> {
  // Find user IDs of students who graduated before the cutoff
  const graduatedProfiles = await prismaUnfiltered.studentProfile.findMany({
    where: {
      graduationDate: { lt: cutoff },
    },
    select: { userId: true },
  })

  if (graduatedProfiles.length === 0) return 0

  const graduatedUserIds = graduatedProfiles.map((p) => p.userId)

  if (isSoftDeletable) {
    // Soft-delete records belonging to those graduated users
    const r = await model.updateMany({
      where: {
        userId: { in: graduatedUserIds },
        deletedAt: null,
      } as any,
      data: { deletedAt: new Date() },
    })
    return r.count
  }

  // Hard-delete for ephemeral models
  const r = await model.deleteMany({
    where: {
      userId: { in: graduatedUserIds },
    },
  })
  return r.count
}

'use client'

import { useCallback, useEffect, useState } from 'react'

export interface FetchState<T> {
  data: T | null
  loading: boolean
  error: string | null
}

/**
 * Reusable client-side data fetching hook.
 *
 * Reduces the duplicated `useState` + `useEffect` fetch pattern used across
 * applicant portal client components. The hook unwraps `{ data }` envelopes
 * automatically and exposes a `refetch()` for re-fetching after mutations.
 */
export function useFetch<T = unknown>(url: string) {
  const [state, setState] = useState<FetchState<T>>({
    data: null,
    loading: true,
    error: null,
  })

  const load = useCallback(async () => {
    setState((prev) => ({ ...prev, loading: true, error: null }))
    try {
      const res = await fetch(url)
      if (!res.ok) {
        throw new Error(`Request failed with status ${res.status}`)
      }
      const json = await res.json()
      setState({ data: (json?.data ?? json) as T, loading: false, error: null })
    } catch (err) {
      setState({
        data: null,
        loading: false,
        error: err instanceof Error ? err.message : 'Failed to fetch data',
      })
    }
  }, [url])

  useEffect(() => {
  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
    void load()
  }, [load])

  return { ...state, refetch: load }
}

'use client'

import { useState, useMemo } from 'react'
import { ChevronUp, ChevronDown, ChevronsUpDown } from 'lucide-react'
import { cn } from '@/lib/utils'

export type SortOrder = 'asc' | 'desc' | null

export interface SortConfig {
  key: string
  order: SortOrder
}

export function useSort<T>(items: T[], initialSort?: SortConfig) {
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(initialSort || null)

  const sortedItems = useMemo(() => {
    if (!sortConfig || !sortConfig.order) return items

    return [...items].sort((a: any, b: any) => {
      const getNestedValue = (obj: any, path: string) => {
        return path.split('.').reduce((acc, part) => acc && acc[part], obj)
      }

      const aValue = getNestedValue(a, sortConfig.key)
      const bValue = getNestedValue(b, sortConfig.key)

      // Handle nulls
      if (aValue === null || aValue === undefined) return 1
      if (bValue === null || bValue === undefined) return -1

      // Handle dates
      if ((aValue instanceof Date || !isNaN(Date.parse(aValue))) && 
          (bValue instanceof Date || !isNaN(Date.parse(bValue))) &&
          typeof aValue !== 'number' && typeof bValue !== 'number') {
        const dateA = new Date(aValue).getTime()
        const dateB = new Date(bValue).getTime()
        return sortConfig.order === 'asc' ? dateA - dateB : dateB - dateA
      }

      // Handle strings
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortConfig.order === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }

      // Handle numbers
      return sortConfig.order === 'asc' ? aValue - bValue : bValue - aValue
    })
  }, [items, sortConfig])

  const requestSort = (key: string) => {
    let order: SortOrder = 'asc'
    if (sortConfig && sortConfig.key === key) {
      if (sortConfig.order === 'asc') order = 'desc'
      else if (sortConfig.order === 'desc') order = null
      else order = 'asc'
    }
    setSortConfig(order ? { key, order } : null)
  }

  return { items: sortedItems, requestSort, sortConfig }
}

interface SortHeaderProps {
  label: string
  sortKey: string
  currentSort: SortConfig | null
  onSort: (key: string) => void
  align?: 'left' | 'center' | 'right'
  className?: string
}

export function SortHeader({
  label,
  sortKey,
  currentSort,
  onSort,
  align = 'left',
  className,
}: SortHeaderProps) {
  const isSorted = currentSort?.key === sortKey
  const order = isSorted ? currentSort?.order : null

  return (
    <th
      scope="col"
      className={cn(
        'cursor-pointer px-6 py-4 transition-colors select-none hover:bg-slate-100/50 dark:hover:bg-slate-800/50',
        align === 'center' && 'text-center',
        align === 'right' && 'text-right',
        className
      )}
      onClick={() => onSort(sortKey)}
    >
      <div
        className={cn(
          'flex items-center gap-1.5',
          align === 'center' && 'justify-center',
          align === 'right' && 'justify-end'
        )}
      >
        <span>{label}</span>
        <div className="flex flex-col text-slate-300">
          {order === 'asc' ? (
            <ChevronUp className="h-3 w-3 text-aerojet-blue dark:text-blue-400" />
          ) : order === 'desc' ? (
            <ChevronDown className="h-3 w-3 text-aerojet-blue dark:text-blue-400" />
          ) : (
            <ChevronsUpDown className="h-3 w-3 opacity-30" />
          )}
        </div>
      </div>
    </th>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'

export interface UseUserTableOptions<T> {
  endpoint: string
  queryParams?: Record<string, string | undefined>
  initialPageSize?: number
  debounceMs?: number
}

export interface UseUserTableResult<T> {
  data: T[]
  total: number
  loading: boolean
  error: string | null
  search: string
  setSearch: (value: string) => void
  page: number
  setPage: (value: number) => void
  perPage: number
  setPerPage: (value: number) => void
  selectedIds: string[]
  setSelectedIds: (ids: string[]) => void
  refetch: () => Promise<void>
}

interface ApiEnvelope<T> {
  success?: boolean
  data?: T
  meta?: { total?: number }
}

export function useUserTable<T = Record<string, unknown>>(
  options: UseUserTableOptions<T>
): UseUserTableResult<T> {
  const { endpoint, queryParams = {}, initialPageSize = 25, debounceMs = 350 } = options

  const [data, setData] = useState<T[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(initialPageSize)
  const [selectedIds, setSelectedIds] = useState<string[]>([])

  const fetchData = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams({
        ...queryParams,
        search,
        page: page.toString(),
        limit: perPage.toString(),
      } as Record<string, string>)

      Object.entries(queryParams).forEach(([key, value]) => {
        if (value !== undefined) params.set(key, value)
      })

      const res = await fetch(`${endpoint}?${params.toString()}`)
      const json = (await res.json()) as ApiEnvelope<T[]>

      if (!res.ok || json.success === false) {
        throw new Error(`Request failed with status ${res.status}`)
      }

      setData(Array.isArray(json.data) ? json.data : [])
      setTotal(json.meta?.total ?? 0)
      setSelectedIds([])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch data')
      setData([])
      setTotal(0)
    } finally {
      setLoading(false)
    }
    // eslint-disable-next-line react-hooks/use-memo
  }, [endpoint, search, page, perPage, JSON.stringify(queryParams)])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setPage(1)
  }, [search])

  useEffect(() => {
    const timer = setTimeout(() => {
      void fetchData()
    }, search ? debounceMs : 0)
    return () => clearTimeout(timer)
  }, [fetchData, search, debounceMs])

  return {
    data,
    total,
    loading,
    error,
    search,
    setSearch,
    page,
    setPage,
    perPage,
    setPerPage,
    selectedIds,
    setSelectedIds,
    refetch: fetchData,
  }
}

/**
 * Internal Exam Engine — EASA-compliant rules and question selection
 *
 * EASA Part-66 exam rules:
 * - 3-option MCQ (A, B, C)
 * - 75 seconds per question
 * - 75% pass mark
 * - 90-day retake wait
 * - 3 attempts max, then 12-month ban
 * - 10-year completion window
 * - Stratified random selection with exposure-based deprioritization
 */

import { prismaUnfiltered } from '@/lib/prisma/client'
import { getSystemSetting } from '@/lib/settings'

// ---------------------------------------------------------------------------
// EASA DEFAULT RULES
// ---------------------------------------------------------------------------

export const EASA_DEFAULTS = {
  passMarkPct: 75,
  timePerQuestionSecs: 75,
  retakeWaitDays: 90,
  maxRetakes: 3,
  banDurationMonths: 12,
  completionWindowYears: 10,
  allowKeyboardAutoSubmit: true,
}

export async function isInternalExamSystemEnabled(): Promise<boolean> {
  const value = await getSystemSetting('internal_exam_system_enabled', 'false')
  return value === 'true'
}

// ---------------------------------------------------------------------------
// Get effective rules for a bank (defaults + overrides)
// ---------------------------------------------------------------------------

export async function getBankRules(bankId: string) {
  const override = await prismaUnfiltered.internalExamRuleOverride.findUnique({
    where: { bankId },
  })

  return {
    passMarkPct: override?.passMarkPct ?? EASA_DEFAULTS.passMarkPct,
    timePerQuestionSecs: override?.timePerQuestionSecs ?? EASA_DEFAULTS.timePerQuestionSecs,
    retakeWaitDays: override?.retakeWaitDays ?? EASA_DEFAULTS.retakeWaitDays,
    maxRetakes: override?.maxRetakes ?? EASA_DEFAULTS.maxRetakes,
    completionWindowYears: override?.completionWindowYears ?? EASA_DEFAULTS.completionWindowYears,
    allowKeyboardAutoSubmit: override?.allowKeyboardAutoSubmit ?? EASA_DEFAULTS.allowKeyboardAutoSubmit,
    customInstructions: override?.customInstructions ?? null,
  }
}

// ---------------------------------------------------------------------------
// Question pool health indicator (5x minimum bank size)
// ---------------------------------------------------------------------------

export type PoolHealth = 'GREEN' | 'AMBER' | 'RED'

export async function getPoolHealth(bankId: string): Promise<{ health: PoolHealth; questionCount: number; requiredMinimum: number }> {
  const bank = await prismaUnfiltered.internalExamBank.findUnique({
    where: { id: bankId },
    select: { mcqCount: true, minimumPoolSize: true },
  })
  if (!bank) return { health: 'RED', questionCount: 0, requiredMinimum: 0 }

  const questionCount = await prismaUnfiltered.internalExamQuestion.count({
    where: { bankId, isActive: true, status: 'APPROVED' },
  })

  const requiredMinimum = bank.minimumPoolSize ?? bank.mcqCount * 5
  const ratio = questionCount / requiredMinimum

  let health: PoolHealth = 'RED'
  if (ratio >= 1.0) health = 'GREEN'
  else if (ratio >= 0.6) health = 'AMBER'

  return { health, questionCount, requiredMinimum }
}

// ---------------------------------------------------------------------------
// Stratified random selection with exposure-based deprioritization
// ---------------------------------------------------------------------------

function shuffle<T>(array: T[]): T[] {
  const a = [...array]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

export async function selectInternalExamQuestions(bankId: string, count: number) {
  const questions = await prismaUnfiltered.internalExamQuestion.findMany({
    where: { bankId, isActive: true, status: 'APPROVED', isEssay: false },
    select: {
      id: true,
      subTopic: true,
      syllabusRef: true,
      difficulty: true,
      knowledgeLevel: true,
      timesServed: true,
      lastServedAt: true,
    },
    orderBy: [{ timesServed: 'asc' }, { lastServedAt: 'asc' }],
  })

  // Group by syllabusRef or subTopic for stratified selection
  const byTopic: Record<string, typeof questions> = {}
  for (const q of questions) {
    const key = q.syllabusRef || q.subTopic || '__general__'
    if (!byTopic[key]) byTopic[key] = []
    byTopic[key].push(q)
  }

  const topics = Object.keys(byTopic)
  const perTopic = Math.max(1, Math.floor(count / topics.length))
  const selected: string[] = []

  // Stratified: pick evenly from each topic, prioritizing least-served
  for (const topic of topics) {
    const pool = byTopic[topic]
    const minServed = pool[0]?.timesServed ?? 0
    const leastServed = pool.filter(q => q.timesServed === minServed)

    let picked: typeof pool
    if (leastServed.length >= perTopic) {
      picked = shuffle(leastServed).slice(0, perTopic)
    } else {
      const rest = pool.filter(q => q.timesServed > minServed)
      picked = [...leastServed, ...shuffle(rest).slice(0, perTopic - leastServed.length)]
    }
    selected.push(...picked.map(q => q.id))
  }

  // Fill remaining from global pool if needed
  if (selected.length < count) {
    const remaining = questions.filter(q => !selected.includes(q.id))
    const fill = shuffle(remaining).slice(0, count - selected.length)
    selected.push(...fill.map(q => q.id))
  }

  // Trim to exact count
  const final = shuffle(selected).slice(0, count)

  // Update exposure tracking
  if (final.length > 0) {
    await prismaUnfiltered.internalExamQuestion.updateMany({
      where: { id: { in: final } },
      data: { timesServed: { increment: 1 }, lastServedAt: new Date() },
    })
  }

  return final
}

// ---------------------------------------------------------------------------
// Eligibility check (retake wait, attempt limit, ban)
// ---------------------------------------------------------------------------

export async function checkEligibility(studentId: string, bankId: string) {
  const rules = await getBankRules(bankId)
  const now = new Date()

  // Get previous sessions for this student + bank (exclude VOIDED)
  const sessions = await prismaUnfiltered.internalExamSession.findMany({
    where: { studentId, bankId, status: { in: ['COMPLETED', 'TIMED_OUT'] } },
    orderBy: { submittedAt: 'desc' },
  })

  // Check if they've already taken it (non-voided)
  if (sessions.length >= 1) {
    return {
      eligible: false,
      reason: 'Internal exams can only be taken once. You have already completed this exam.',
    }
  }

  // Also check for an in-progress session
  const inProgress = await prismaUnfiltered.internalExamSession.findFirst({
    where: { studentId, bankId, status: 'IN_PROGRESS' },
  })
  if (inProgress) {
    return {
      eligible: true,
      attemptNumber: 1,
      totalAttempts: 0,
      resumeSessionId: inProgress.id,
    }
  }

  return {
    eligible: true,
    attemptNumber: 1,
    totalAttempts: sessions.length,
  }
}

// ---------------------------------------------------------------------------
// Build randomised paper (shuffled question order + shuffled options)
// ---------------------------------------------------------------------------

export interface RandomizedPaper {
  paper: {
    id: string
    text: string
    options: string[]
    points: number
    subTopic?: string | null
    syllabusRef?: string | null
  }[]
  questionOrder: string[]
}

export async function buildRandomizedPaper(
  rawQuestions: Array<{
    id: string
    text: string
    options: string[]
    points: number
    subTopic?: string | null
    syllabusRef?: string | null
  }>,
): Promise<RandomizedPaper> {
  const shuffledQuestions = shuffle(rawQuestions.map(q => ({ ...q, options: shuffle(q.options) })))
  const questionOrder = shuffledQuestions.map(q => q.id)

  return {
    paper: shuffledQuestions,
    questionOrder,
  }
}

import 'server-only'

interface RawQuestion {
  text?: string
  options?: unknown[]
  correctAnswer?: string
  correct_answer?: string
  subTopic?: string
  sub_topic?: string
  difficulty?: 'EASY' | 'MEDIUM' | 'HARD'
  points?: number
  explanation?: string
}

export interface ExtractedQuestion {
  text: string
  options: string[]
  correctAnswer: string
  subTopic?: string
  difficulty?: 'EASY' | 'MEDIUM' | 'HARD'
  points?: number
  explanation?: string
  confidence: number
  rawText: string
}

const OPTION_LABELS = ['A', 'B', 'C', 'D', 'E', 'F']

function splitQuestions(raw: string): string[] {
  const lines = raw.split(/\r?\n/).filter((l) => l.trim())
  const chunks: string[] = []
  let current: string[] = []

  for (const line of lines) {
    if (/^(Question\s+\d+|Q\d+|\d+\.)\b/i.test(line.trim())) {
      if (current.length) chunks.push(current.join('\n'))
      current = [line]
    } else {
      current.push(line)
    }
  }
  if (current.length) chunks.push(current.join('\n'))
  return chunks
}

function parseOptionLine(line: string): { label: string; text: string } | null {
  const m = line.trim().match(/^([A-F])[\.\)\-]\s*(.+)$/i)
  if (!m) return null
  return { label: m[1].toUpperCase(), text: m[2].trim() }
}

function detectCorrectAnswer(text: string): string | null {
  const patterns = [/(?:Answer|Correct|✓|✔|Right answer)[\s:]+([A-F])/i, /(?:=>|→)\s*([A-F])$/i]
  for (const p of patterns) {
    const m = text.match(p)
    if (m) return m[1].toUpperCase()
  }
  return null
}

export function detectConfidence(q: ExtractedQuestion): number {
  let score = 0
  if (q.text.length > 20) score += 0.3
  if (q.options.length >= 3) score += 0.3
  if (q.correctAnswer) score += 0.2
  if (q.options.some((o) => o.toLowerCase().includes(q.correctAnswer?.toLowerCase() || '')))
    score += 0.2
  return Math.min(1, score)
}

export function classifySeverity(confidence: number): 'LOW' | 'MEDIUM' | 'HIGH' {
  if (confidence < 0.5) return 'LOW'
  if (confidence < 0.8) return 'MEDIUM'
  return 'HIGH'
}

export async function extractFromTxt(content: string): Promise<ExtractedQuestion[]> {
  const chunks = splitQuestions(content)
  return chunks.map((chunk) => {
    const lines = chunk.split(/\r?\n/)
    const options: { label: string; text: string }[] = []
    let text = ''
    let correctAnswer: string | null = null

    for (const line of lines) {
      const parsed = parseOptionLine(line)
      if (parsed) {
        options.push(parsed)
      } else if (!correctAnswer) {
        text += (text ? ' ' : '') + line.trim()
      }
      correctAnswer = detectCorrectAnswer(chunk) || correctAnswer
    }

    const question: ExtractedQuestion = {
      text: text.replace(/\s+/g, ' ').trim(),
      options: options.map((o) => o.text),
      correctAnswer: correctAnswer || options[0]?.label || 'A',
      confidence: 0,
      rawText: chunk,
    }
    question.confidence = detectConfidence(question)
    return question
  })
}

export async function extractFromJson(content: string): Promise<ExtractedQuestion[]> {
  const parsed = JSON.parse(content)
  const arr = Array.isArray(parsed) ? parsed : [parsed]
  return arr.map((q: RawQuestion) => {
    const question: ExtractedQuestion = {
      text: q.text || '',
      options: Array.isArray(q.options) ? (q.options as string[]) : [],
      correctAnswer: q.correctAnswer || q.correct_answer || '',
      subTopic: q.subTopic || q.sub_topic,
      difficulty: q.difficulty,
      points: q.points,
      explanation: q.explanation,
      confidence: 0,
      rawText: JSON.stringify(q),
    }
    question.confidence = detectConfidence(question)
    return question
  })
}

export async function extractFromDocx(buffer: Buffer): Promise<ExtractedQuestion[]> {
  const mammoth = await import('mammoth')
  const result = await mammoth.extractRawText({ buffer })
  return extractFromTxt(result.value)
}

export async function extractFromPdf(buffer: Buffer): Promise<ExtractedQuestion[]> {
  const { PDFParse } = await import('pdf-parse')
  const parser = new PDFParse({ data: buffer })
  const result = await parser.getText()
  return extractFromTxt(result.text)
}

import { prismaUnfiltered as prisma } from '@/lib/prisma/client'
