import { getSystemSettings } from '@/lib/system-settings'
import fs from 'fs'
import path from 'path'

export interface PDFSettings {
  logoUrl: string
  watermarkUrl: string
  footerText: string
  watermarkOpacity: number
}

/**
 * Reads a local image file and returns a data: URI (base64-encoded).
 * This is the most reliable way to embed images in @react-pdf/renderer
 * since it avoids all URL resolution, fetch, and cross-platform path issues.
 *
 * @react-pdf/renderer does NOT support .webp — only PNG and JPG.
 */
function readImageAsDataUri(filePath: string): string | null {
  try {
    // Normalize: strip any leading /public or public prefix to avoid double public/public/
    const normalized = filePath.replace(/^\/?(public)\//i, '/')
    const absolutePath = normalized.startsWith('/')
      ? path.join(/*turbopackIgnore: true*/ process.cwd(), 'public', normalized)
      : normalized

    if (!fs.existsSync(absolutePath)) {
      console.warn(`[PDF] Image not found: ${absolutePath}`)
      return null
    }

    const stats = fs.statSync(absolutePath)
    if (stats.size === 0) {
      console.warn(`[PDF] Image is empty (0 bytes): ${absolutePath}`)
      return null
    }

    const buffer = fs.readFileSync(absolutePath)

    // Detect actual format from magic bytes (don't trust the file extension!)
    // PNG: 89 50 4E 47 (‰PNG)
    // JPEG: FF D8 FF
    let mime: string | null = null
    if (buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47) {
      mime = 'image/png'
    } else if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
      mime = 'image/jpeg'
    }

    if (!mime) {
      console.warn(`[PDF] Unsupported image format (not PNG/JPG by magic bytes): ${absolutePath}`)
      return null
    }

    return `data:${mime};base64,${buffer.toString('base64')}`
  } catch (err) {
    console.error(`[PDF] Failed to read image: ${filePath}`, err)
    return null
  }
}

/**
 * Resolves an image URL to a data URI for react-pdf.
 * For remote (non-localhost) HTTPS URLs, returns the URL as-is.
 * For local files, reads and base64-encodes them.
 */
function resolveImageForPdf(rawUrl: string): string | null {
  // Remote production URLs — react-pdf can fetch these directly
  if (rawUrl.startsWith('https://') && !rawUrl.includes('localhost')) {
    return rawUrl
  }

  // Local relative path or absolute path — read as data URI
  return readImageAsDataUri(rawUrl)
}

/**
 * PNG fallback defaults — @react-pdf/renderer does NOT support .webp
 */
const DEFAULT_LOGO = '/images/logos/AATA_logo_hor_onWhite.png'
const DEFAULT_WATERMARK = '/apple-touch-icon.png'

/**
 * Fetches PDF-specific system settings and resolves image URLs
 * to data URIs supported by @react-pdf/renderer (PNG/JPG only).
 */
export async function getPDFSettings(hostOrigin: string): Promise<PDFSettings> {
  const settings = await getSystemSettings([
    'pdf_header_logo_url',
    'pdf_watermark_url',
    'pdf_footer_text',
    'pdf_watermark_opacity',
  ])

  // Enforce PNG/JPG — reject .webp since react-pdf cannot render it
  let logoRaw = settings['pdf_header_logo_url'] || DEFAULT_LOGO
  let watermarkRaw = settings['pdf_watermark_url'] || DEFAULT_WATERMARK

  if (logoRaw.endsWith('.webp')) logoRaw = DEFAULT_LOGO
  if (watermarkRaw.endsWith('.webp')) watermarkRaw = DEFAULT_WATERMARK

  const footerText =
    settings['pdf_footer_text'] || 'Small Engines Dept., ATTC\nKokomlemle, Accra — Ghana'
  const watermarkOpacity = parseFloat(settings['pdf_watermark_opacity'] || '0.15')

  const logoUrl = resolveImageForPdf(logoRaw) || ''
  const watermarkUrl = resolveImageForPdf(watermarkRaw) || ''

  return {
    logoUrl,
    watermarkUrl,
    footerText,
    watermarkOpacity: isNaN(watermarkOpacity) ? 0.15 : Math.max(0, Math.min(1, watermarkOpacity)),
  }
}

/**
 * Bundle Operations — Purchase and use exam seat bundles.
 *
 * Two-Seat Bundle: €980 (€490/seat vs €520 individual)
 * Four-Seat Bundle: €1,900 (€475/seat + 1 free module change)
 *
 * Bundles are valid for 12 months. Seats can be used for any module
 * in any pool during the validity period.
 */

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { getExamPricingConfig } from './pricing-config'
import { placeExamBookingInStandardPool } from '@/lib/enrollment/exams'

export interface BundlePurchaseResult {
  success: boolean
  bundleId?: string
  error?: string
}

/**
 * Purchase a new exam seat bundle and auto-book into specific modules.
 */
export async function purchaseBundle(
  userId: string,
  bundleType: 'TWO_SEAT' | 'FOUR_SEAT',
  examComponentIds: string[]
): Promise<BundlePurchaseResult> {
  const pricing = await getExamPricingConfig()

  const seats = bundleType === 'TWO_SEAT' ? 2 : 4
  const price = bundleType === 'TWO_SEAT' ? pricing.twoSeatBundle : pricing.fourSeatBundle
  const freeChanges = bundleType === 'FOUR_SEAT' ? 2 : 1

  if (!examComponentIds || examComponentIds.length !== seats) {
    return { success: false, error: `Must provide exactly ${seats} modules.` }
  }

  // Find target event for these pools
  const activeEvent = await prisma.examEvent.findFirst({
    where: { status: { in: ['OPEN', 'DRAFT'] } },
    orderBy: { startDate: 'asc' },
  })

  if (!activeEvent) {
    return { success: false, error: 'No active upcoming Exam Events available to pool into.' }
  }

  // Pre-fetch the components to get module codes (course codes)
  const components = await prisma.examComponent.findMany({
    where: { id: { in: examComponentIds } },
    include: { course: true },
  })

  if (components.length !== examComponentIds.length) {
    return { success: false, error: 'One or more invalid modules selected.' }
  }

  try {
    const bundleBookingType = bundleType === 'TWO_SEAT' ? 'TWIN_PACK' as const : 'FOUR_PACK' as const

    const txResult = await prisma.$transaction(
      async (tx) => {
        // Check wallet balance
        const wallet = await tx.wallet.findUnique({ where: { userId } })
        if (!wallet) return { success: false, error: 'Wallet not found' }

        const available = Number(wallet.availableBalance)
        if (available < price) {
          return {
            success: false,
            error: `Insufficient balance. Need EUR ${price}, have EUR ${available}`,
          }
        }

        const purchaseRef = `BUNDLE-${userId.slice(-8)}-${Date.now()}`

        // Charge wallet for bundle price
        await tx.wallet.update({
          where: { userId },
          data: {
            balance: { decrement: price },
            availableBalance: { decrement: price },
          },
        })

        await tx.walletTransaction.create({
          data: {
            walletId: wallet.id,
            type: 'PAYMENT',
            amount: price,
            description: `${bundleType === 'TWO_SEAT' ? 'Twin Pack' : '4-Pack'} Exam Bundle`,
            referenceType: 'BUNDLE_PURCHASE',
            referenceId: purchaseRef,
            balanceBefore: Number(wallet.balance),
            balanceAfter: Number(wallet.balance) - price,
            availableBefore: available,
            availableAfter: available - price,
          },
        })

        // Create bundle
        const validUntil = new Date()
        validUntil.setFullYear(validUntil.getFullYear() + 1)

        const bundle = await tx.examBundle.create({
          data: {
            userId,
            bundleType,
            totalSeats: seats,
            usedSeats: 0,
            status: 'ACTIVE',
            amountPaid: price,
            freeModuleChanges: freeChanges,
            // Audit 1c: Twin Pack = 1 free resit, Four Pack = 2 free resits.
            freeResitsIncluded: bundleType === 'FOUR_SEAT' ? 2 : 1,
            usedFreeResits: 0,
            validUntil,
          },
        })

        // Route each module through shared standard-pool assignment (cost = 0 since bundle covers it)
        for (const comp of components) {
          const courseCode = comp.course.code

          const result = await placeExamBookingInStandardPool(tx, {
            userId,
            eventId: activeEvent.id,
            examComponentId: comp.id,
            moduleCode: courseCode,
            bookingType: bundleBookingType,
            reserveAmount: 0,
            bundleId: bundle.id,
          })

          if (!result.success) {
            throw new Error(result.error || `Failed to place module ${courseCode}.`)
          }
        }

        return { success: true, bundleId: bundle.id }
      },
      {
        timeout: 20000,
      }
    )

    // Send bundle purchase confirmation email (outside transaction)
    if (txResult.success) {
      const { sendBundlePurchaseEmail } = await import('@/lib/email/service')
      const user = await prisma.user.findUnique({
        where: { id: userId },
        select: { email: true, academyEmail: true, profile: { select: { firstName: true } } },
      })
      if (user) {
        const email = user.academyEmail || user.email
        const name = user.profile?.firstName || 'Student'
        const label = bundleType === 'TWO_SEAT' ? 'Twin Pack' : '4-Pack'
        sendBundlePurchaseEmail(email, name, label, seats, price).catch(console.error)
      }
    }

    return txResult
  } catch (err: any) {
    console.error('[BUNDLE PURCHASE ERROR]', err)
    return { success: false, error: err.message || 'Failed to purchase bundle' }
  }
}

/**
 * Find an available bundle seat for a pool join.
 * Returns the earliest-expiring active bundle with remaining seats, or null.
 */
export async function getAvailableBundle(userId: string) {
  // Prisma can't compare two columns (usedSeats < totalSeats) in findFirst,
  // so we fetch all active non-expired bundles and filter in JS
  const bundles = await prisma.examBundle.findMany({
    where: {
      userId,
      status: 'ACTIVE',
      validUntil: { gt: new Date() },
    },
    orderBy: { validUntil: 'asc' }, // Use earliest expiring first
  })
  return bundles.find((b) => b.usedSeats < b.totalSeats) ?? null
}

/**
 * Use one seat from a bundle.
 */
export async function useBundleSeat(tx: any, bundleId: string) {
  const bundle = await tx.examBundle.findUnique({ where: { id: bundleId } })
  if (!bundle) throw new Error('Bundle not found')
  if (bundle.usedSeats >= bundle.totalSeats) throw new Error('Bundle exhausted')
  if (bundle.validUntil < new Date()) throw new Error('Bundle expired')

  const newUsedSeats = bundle.usedSeats + 1
  const newStatus = newUsedSeats >= bundle.totalSeats ? 'EXHAUSTED' : 'ACTIVE'

  return tx.examBundle.update({
    where: { id: bundleId },
    data: {
      usedSeats: newUsedSeats,
      status: newStatus,
    },
  })
}

/**
 * Get all bundles for a user with usage info.
 */
export async function getUserBundles(userId: string) {
  return prisma.examBundle.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
  })
}

/**
 * Cancellation Flow — Handles booking cancellations with wallet credit.
 *
 * Per business rules:
 * - RESERVED memberships: release reserved funds back to available balance
 * - CONFIRMED memberships: credit wallet (no bank refund, wallet credit only)
 * - Notifications sent to both student and admin
 */

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { releaseFunds, creditToWallet } from '@/lib/wallet/operations'
import { decrementPoolMemberCount } from './operations'
import { logAuditEvent } from '@/lib/audit/logger'
import { ACTIVE_MEMBERSHIP_STATUSES } from '@/lib/utils/constants'

export interface CancellationResult {
  success: boolean
  error?: string
  refundAmount?: number
  refundType?: 'RELEASE' | 'CREDIT'
}

/**
 * Cancels a booking and its associated pool membership.
 * - RESERVED → release reserved funds
 * - CONFIRMED → credit wallet (wallet credit only, no bank refund)
 * Sends notifications to both student and admins.
 */
export async function cancelBooking(
  bookingId: string,
  cancelledBy: string,
  reason?: string
): Promise<CancellationResult> {
  try {
    const result = await prisma.$transaction(
      async (tx) => {
        // Find the booking
        const booking = await tx.examBooking.findUnique({
          where: { id: bookingId },
          include: {
            user: {
              select: { id: true, profile: { select: { firstName: true, lastName: true } } },
            },
            examComponent: { select: { course: { select: { code: true, name: true } } } },
            event: { select: { name: true } },
          },
        })

        if (!booking) throw new Error('Booking not found.')
        if (booking.status === 'COMPLETED') throw new Error('Cannot cancel a completed booking.')
        if (booking.cancelledAt) throw new Error('This booking has already been cancelled.')

        const userId = booking.userId
        const amount = Number(booking.amountPaid)
        const moduleLabel = booking.examComponent?.course?.code || booking.moduleCode || 'Exam'
        const studentName =
          `${booking.user.profile?.firstName || ''} ${booking.user.profile?.lastName || ''}`.trim() ||
          'Student'

        // Find associated pool membership(s)
        const memberships = await tx.poolMembership.findMany({
          where: {
            bookingId,
            status: { in: ACTIVE_MEMBERSHIP_STATUSES },
          },
        })

        // Also check memberships by userId + examComponentId if no bookingId link
        let membershipsByLegacy: typeof memberships = []
        if (memberships.length === 0 && booking.examComponentId) {
          membershipsByLegacy = await tx.poolMembership.findMany({
            where: {
              userId,
              examComponentId: booking.examComponentId,
              status: { in: ACTIVE_MEMBERSHIP_STATUSES },
            },
          })
        }

        const allMemberships = [...memberships, ...membershipsByLegacy]
        let totalRefund = 0
        let refundType: 'RELEASE' | 'CREDIT' = 'RELEASE'

        for (const membership of allMemberships) {
          const memberAmount = Number(membership.amountReserved) || amount

          if (membership.status === 'RESERVED' && memberAmount > 0) {
            // Release reserved funds back to available
            await releaseFunds(
              tx,
              userId,
              memberAmount,
              `Booking cancelled: ${moduleLabel}`,
              bookingId,
              'BOOKING_CANCELLATION'
            )
            totalRefund += memberAmount
            refundType = 'RELEASE'
          } else if (membership.status === 'CONFIRMED' && memberAmount > 0) {
            // Credit wallet (no bank refund per business rules)
            const creditAmount = Number(membership.amountPaid) || memberAmount
            await creditToWallet(
              tx,
              userId,
              creditAmount,
              `Cancellation credit: ${moduleLabel}`,
              bookingId,
              'BOOKING_CANCELLATION'
            )
            totalRefund += creditAmount
            refundType = 'CREDIT'
          }

          // Cancel the membership
          await tx.poolMembership.update({
            where: { id: membership.id },
            data: { status: 'CANCELLED' },
          })

          // Decrement pool count
          await decrementPoolMemberCount(membership.poolId, tx)
        }

        // Update the booking record
        await tx.examBooking.update({
          where: { id: bookingId },
          data: {
            status: 'FAILED',
            cancelledAt: new Date(),
            cancelledBy,
            cancellationReason: reason || 'Cancelled by user',
            refundAmount: totalRefund,
          },
        })

        // Student notification
        await tx.notification.create({
          data: {
            userId,
            title: 'Booking Cancelled',
            message:
              totalRefund > 0
                ? `Your booking for ${moduleLabel} has been cancelled. €${totalRefund.toFixed(2)} has been credited to your wallet.`
                : `Your booking for ${moduleLabel} has been cancelled.`,
            type: 'PAYMENT_UPDATE',
            linkUrl: '/student/wallet',
            linkText: 'View Wallet',
          },
        })

        // Admin notification — notify all staff
        const staffUsers = await tx.user.findMany({
          where: { role: { in: ['ADMIN', 'STAFF'] } },
          select: { id: true },
          take: 20,
        })

        for (const staff of staffUsers) {
          await tx.notification.create({
            data: {
              userId: staff.id,
              title: 'Booking Cancelled',
              message: `Booking cancelled for ${studentName} - ${moduleLabel}${booking.event ? ` (${booking.event.name})` : ''}. ${totalRefund > 0 ? `€${totalRefund.toFixed(2)} wallet credit issued.` : ''}`,
              type: 'PAYMENT_UPDATE',
              linkUrl: '/staff/exam-pools',
              linkText: 'View Pools',
            },
          })
        }

        await logAuditEvent(
          {
            action: 'BOOKING_CANCEL',
            entity: 'ExamBooking',
            entityId: bookingId,
            userId: cancelledBy,
            description: `Booking cancelled for ${studentName} - ${moduleLabel}${booking.event ? ` (${booking.event.name})` : ''}. Refund: €${totalRefund.toFixed(2)} (${refundType}). Reason: ${reason || 'User requested'}`,
          },
          tx
        )

        return { success: true, refundAmount: totalRefund, refundType }
      },
      {
        isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
        timeout: 15000,
      }
    )

    return result
  } catch (err: any) {
    console.error('[BOOKING CANCEL ERROR]', err instanceof Error ? err.message : 'Unknown error')
    return {
      success: false,
      error: err instanceof Error ? err.message : 'Failed to cancel booking.',
    }
  }
}

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { format } from 'date-fns'
import { sendPoolConfirmedEmail, sendPoolFailedEmail } from '@/lib/email/service'
import { logAuditEvent } from '../audit/logger'
import { captureFunds, releaseFunds } from '@/lib/wallet/operations'

export async function confirmPoolInternal(poolId: string, tx: any) {
  const memberships = await tx.poolMembership.findMany({
    where: { poolId, status: 'RESERVED' },
    include: {
      user: { include: { profile: true } },
      examComponent: { include: { course: true } },
    },
  })

  const pool = await tx.examPool.findUnique({ where: { id: poolId } })

  for (const m of memberships) {
    const captureAmount = Number(m.amountReserved) || Number(pool?.seatPrice) || 300

    await captureFunds(
      tx,
      m.userId,
      captureAmount,
      `Exam fee captured: ${pool?.name}`,
      m.bookingId || poolId,
      m.bookingId ? 'EXAM_BOOKING' : 'POOL_CAPTURE'
    )

    await tx.poolMembership.update({
      where: { id: m.id },
      data: {
        status: 'CONFIRMED',
        amountPaid: captureAmount,
        confirmedAt: new Date(),
        paidAt: new Date(),
      },
    })

    if (m.bookingId) {
      await tx.examBooking.update({
        where: { id: m.bookingId },
        data: {
          status: 'APPROVED',
          amountPaid: captureAmount,
        },
      })
    }
  }

  // Set pool status — CONFIRMED if under max, LOCKED if at capacity
  const updatedPool = await tx.examPool.findUnique({ where: { id: poolId } })
  const finalStatus =
    updatedPool && updatedPool.currentMemberCount >= updatedPool.maxCandidates
      ? 'LOCKED'
      : 'CONFIRMED'

  await tx.examPool.update({
    where: { id: poolId },
    data: { status: finalStatus, confirmedAt: new Date() },
  })

  // Log the audit event
  await logAuditEvent(
    {
      action: 'POOL_CONFIRM',
      entity: 'ExamPool',
      entityId: poolId,
      description: `Pool "${pool?.name}" has been confirmed and seats locked.`,
    },
    tx
  )

  // Send emails (non-blocking, outside tx)
  for (const m of memberships) {
    const name = m.user.profile?.firstName || 'Student'
    const moduleLabel = m.examComponent?.course?.code || 'Module'
    const amount = Number(m.amountPaid || m.amountReserved || 300)

    // Send to personal email
    sendPoolConfirmedEmail(
      m.user.email,
      name,
      pool?.name || '',
      moduleLabel,
      format(pool?.examDate || new Date(), 'dd MMM yyyy'),
      amount
    ).catch((e) =>
      console.error('[EMAIL ERROR] Failed to send pool confirmed email to personal address:', e)
    )

    // Send to academy email if exists
    if (m.user.academyEmail) {
      sendPoolConfirmedEmail(
        m.user.academyEmail,
        name,
        pool?.name || '',
        moduleLabel,
        format(pool?.examDate || new Date(), 'dd MMM yyyy'),
        amount
      ).catch((e) =>
        console.error('[EMAIL ERROR] Failed to send pool confirmed email to academy address:', e)
      )
    }
  }
}

export async function failPool(poolId: string, txClient?: Prisma.TransactionClient) {
  const execute = async (tx: Prisma.TransactionClient) => {
    const pool = await tx.examPool.findUnique({ where: { id: poolId } })
    if (!pool) return null

    const memberships = await tx.poolMembership.findMany({
      where: { poolId, status: 'RESERVED' },
      include: { user: { include: { profile: true } } },
    })

    for (const m of memberships) {
      const releaseAmount = Number(m.amountReserved) || Number(pool.seatPrice) || 300

      await releaseFunds(
        tx,
        m.userId,
        releaseAmount,
        `Pool failed - funds released: ${pool.name}`,
        m.bookingId || poolId,
        m.bookingId ? 'EXAM_BOOKING' : 'POOL_RELEASE'
      )

      await tx.poolMembership.update({ where: { id: m.id }, data: { status: 'CANCELLED' } })

      if (m.bookingId) {
        await tx.examBooking.update({
          where: { id: m.bookingId },
          data: {
            status: 'FAILED',
            refundAmount: releaseAmount,
            cancellationReason: 'Pool failed Go/No-Go criteria',
            cancelledAt: new Date(),
          },
        })
      }
    }

    await tx.examPool.update({ where: { id: poolId }, data: { status: 'FAILED' } })

    await logAuditEvent(
      {
        action: 'POOL_FAIL',
        entity: 'ExamPool',
        entityId: poolId,
        description: `Pool "${pool.name}" has failed Go/No-Go criteria. All funds released.`,
      },
      tx
    )

    return { pool, memberships }
  }

  // Run inside provided transaction or create a new one
  const result = txClient
    ? await execute(txClient)
    : await prisma.$transaction(execute, {
        isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
      })

  // Send emails OUTSIDE the transaction to avoid blocking on I/O
  if (result?.memberships) {
    for (const m of result.memberships) {
      const name = m.user.profile?.firstName || 'Student'

      // Send to personal email
      sendPoolFailedEmail(
        m.user.email,
        name,
        result.pool.name,
        format(result.pool.examDate, 'dd MMM yyyy')
      ).catch((e) =>
        console.error('[EMAIL ERROR] Failed to send pool failed email to personal address:', e)
      )

      // Send to academy email if exists
      if (m.user.academyEmail) {
        sendPoolFailedEmail(
          m.user.academyEmail,
          name,
          result.pool.name,
          format(result.pool.examDate, 'dd MMM yyyy')
        ).catch((e) =>
          console.error('[EMAIL ERROR] Failed to send pool failed email to academy address:', e)
        )
      }
    }
  }
}

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { chargeWallet } from '@/lib/wallet/operations'
import { getExamPricingConfig } from './pricing-config'
import { logAuditEvent } from '@/lib/audit/logger'

export interface GroupBookingParams {
  repUserId: string
  eventId: string
  groupName: string
  memberCount: number
  modules: string[] // exam component IDs
}

/**
 * Creates a group booking with a dedicated GROUP_CHARTER pool.
 * One representative books and pays the charter fee (default 7500 EUR)
 * for the entire group.
 */
export async function createGroupBooking(params: GroupBookingParams) {
  const { repUserId, eventId, groupName, memberCount, modules } = params

  if (!groupName.trim()) throw new Error('Group/company name is required.')
  if (memberCount < 1) throw new Error('At least 1 member is required.')
  if (!modules.length) throw new Error('At least 1 exam module must be selected.')

  const pricing = await getExamPricingConfig()
  const charterFee = pricing.groupCharterFee

  const event = await prisma.examEvent.findUnique({
    where: { id: eventId },
    select: { id: true, name: true, startDate: true, status: true },
  })
  if (!event) throw new Error('Exam event not found.')
  if (event.status !== 'OPEN' && event.status !== 'DRAFT') {
    throw new Error('This exam event is not accepting bookings.')
  }

  // Resolve exam components
  const components = await prisma.examComponent.findMany({
    where: { id: { in: modules } },
    include: { course: { select: { code: true, name: true } } },
  })
  if (components.length !== modules.length) {
    throw new Error('One or more invalid exam modules selected.')
  }

  return prisma.$transaction(
    async (tx) => {
      // Check wallet balance
      const wallet = await tx.wallet.findUnique({ where: { userId: repUserId } })
      if (!wallet || Number(wallet.availableBalance) < charterFee) {
        throw new Error(
          `Insufficient wallet balance for group charter. Required: €${charterFee.toFixed(2)}`
        )
      }

      // Charge the charter fee
      await chargeWallet(
        tx,
        repUserId,
        charterFee,
        `Group Charter Booking: ${groupName} - ${event.name}`,
        eventId,
        'GROUP_CHARTER'
      )

      // Create dedicated GROUP_CHARTER pool
      const examStartTime = new Date(event.startDate)
      examStartTime.setHours(9, 0, 0, 0)
      const examEndTime = new Date(examStartTime)
      examEndTime.setHours(12, 0, 0, 0)

      const pool = await tx.examPool.create({
        data: {
          eventId,
          name: `Group Charter - ${groupName}`,
          examDate: event.startDate,
          examStartTime,
          examEndTime,
          minCandidates: 1,
          maxCandidates: 28,
          moduleDiversityCap: modules.length,
          status: 'OPEN',
          poolType: 'GROUP_CHARTER',
          dayNumber: 1,
          poolLabel: `GRP-${groupName.substring(0, 8).toUpperCase()}`,
          isAutoPool: false,
          seatPrice: 0, // Covered by charter fee
          allowedModules: components.map((c) => c.course.code),
        },
      })

      // Create the booking record
      const booking = await tx.examBooking.create({
        data: {
          userId: repUserId,
          eventId,
          bookingType: 'GROUP_CHARTER',
          moduleCode: components.map((c) => c.course.code).join(', '),
          amountPaid: charterFee,
          status: 'APPROVED',
          groupRepId: repUserId,
          groupName,
        },
      })

      // Create notification
      await tx.notification.create({
        data: {
          userId: repUserId,
          title: 'Group Charter Booking Created',
          message: `Your group charter for "${groupName}" has been created for ${event.name}. Pool: "${pool.name}". You can now add members.`,
          type: 'SUCCESS',
          linkUrl: '/student/exam-bookings',
          linkText: 'View Bookings',
        },
      })

      await logAuditEvent(
        {
          action: 'GROUP_CHARTER_CREATE',
          entity: 'ExamBooking',
          entityId: booking.id,
          userId: repUserId,
          description: `Group charter created: ${groupName} for event ${event.name}, ${memberCount} members, ${modules.length} modules.`,
        },
        tx
      )

      return { pool, booking }
    },
    { timeout: 15000 }
  )
}

import prisma from '@/lib/prisma/client'
import { BookingType, Prisma, MembershipStatus, PoolStatus } from '@prisma/client'
import {
  POOL_MIN_CANDIDATES,
  POOL_NEAR_FULL_THRESHOLD,
  POOL_MAX_CANDIDATES,
  MAX_TOTAL_STUDENT_POOLS,
} from './types'
import { confirmPoolInternal } from './confirm'
import type { PoolJoinInput, PoolJoinResult } from './types'
import { resolveStandardPoolForJoin } from './assignment'
import { reserveFunds } from '@/lib/wallet/operations'
import { ACTIVE_MEMBERSHIP_STATUSES } from '@/lib/utils/constants'
import { trackEvent } from '@/lib/analytics/events'

// Simple string hash to generate two 32-bit integers for PG advisory locks
function getLockKeys(str: string): [number, number] {
  let h1 = 5381
  let h2 = 52711
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i)
    h1 = ((h1 << 5) + h1) ^ char
    h2 = ((h2 << 5) + h2) ^ char
  }
  return [h1 & 0x7fffffff, h2 & 0x7fffffff]
}

function resolveGuaranteeType(bookingType: BookingType) {
  if (bookingType === 'POOL') return 'POOL_FLEX' as const
  if (bookingType === 'GROUP_CHARTER') return 'COMPANY_GUARANTEED' as const
  if (bookingType === 'TWIN_PACK' || bookingType === 'FOUR_PACK')
    return 'BUNDLE_GUARANTEED' as const
  return 'INDIVIDUAL_GUARANTEED' as const
}

export async function joinPool(input: PoolJoinInput): Promise<PoolJoinResult> {
  try {
    const lockScope =
      input.eventId ||
      (
        await prisma.examPool.findUnique({
          where: { id: input.poolId },
          select: { eventId: true },
        })
      )?.eventId ||
      input.poolId

    const result = await prisma.$transaction(
      async (tx) => {
        const [lockKey1, lockKey2] = getLockKeys(lockScope)
        await tx.$executeRaw`SELECT pg_advisory_xact_lock(${lockKey1}, ${lockKey2})`
        return joinPoolInternal(tx, input)
      },
      { isolationLevel: Prisma.TransactionIsolationLevel.Serializable }
    )

    if (result.success && result.triggeredNearFull && result.pool?.id) {
      const memberships = await prisma.poolMembership.findMany({
        where: { poolId: result.pool.id, status: { in: ACTIVE_MEMBERSHIP_STATUSES } },
        include: {
          user: { include: { profile: true } },
          pool: { select: { name: true, examDate: true } },
          examComponent: { include: { course: true } },
        },
      })

      const { sendPoolApproachingConfirmationEmail } = await import('@/lib/email/service')
      const { format } = await import('date-fns')

      for (const membership of memberships) {
        const name = membership.user.profile?.firstName || 'Student'
        const email = membership.user.academyEmail || membership.user.email
        const moduleLabel = membership.examComponent?.course?.code || 'Module'
        const examDateStr = membership.pool.examDate
          ? format(membership.pool.examDate, 'dd MMM yyyy')
          : 'TBA'

        sendPoolApproachingConfirmationEmail(
          email,
          name,
          membership.pool.name,
          examDateStr,
          moduleLabel
        ).catch((error) => {
          console.error('[EMAIL ERROR] Failed to send NEAR_FULL to', email, error)
        })
      }
    }

    return result
  } catch (err: any) {
    console.error('[POOL JOIN ERROR]', err)
    return { success: false, error: err.message || 'Failed to join booking' }
  }
}

/**
 * Internal join logic that can be reused within an existing transaction.
 */
export async function joinPoolInternal(
  tx: Prisma.TransactionClient,
  input: PoolJoinInput
): Promise<PoolJoinResult & { triggeredNearFull?: boolean }> {
  const { poolId, userId, examComponentId } = input
  const bookingType = input.bookingType || 'POOL'
  const guaranteeType = resolveGuaranteeType(bookingType)
  const guaranteedSeat = guaranteeType !== 'POOL_FLEX'

  const sourcePool = await tx.examPool.findUnique({
    where: { id: poolId },
    select: {
      id: true,
      eventId: true,
      poolType: true,
    },
  })
  if (!sourcePool) return { success: false, error: 'Pool not found' }
  if (sourcePool.poolType === 'AUTO') {
    return {
      success: false,
      error: 'Cannot join auto pools directly. Please book an exam instead.',
    }
  }
  if (sourcePool.poolType === 'GROUP_CHARTER') {
    return { success: false, error: 'Group charter pools require a group booking representative.' }
  }
  if (!sourcePool.eventId) {
    return { success: false, error: 'Pool is not attached to an exam event.' }
  }
  if (!input.moduleCode) {
    return { success: false, error: 'Module code is required for pool assignment.' }
  }

  const resolvedPool = await resolveStandardPoolForJoin(tx, {
    eventId: sourcePool.eventId,
    moduleCode: input.moduleCode,
    preferredPoolId: poolId,
  })
  const eventIdForBooking = input.eventId || sourcePool.eventId

  // Advisory lock on pool to prevent concurrent modifications
  const lockKey = BigInt('0x' + resolvedPool.id.replace(/-/g, '').slice(0, 15))
  await tx.$executeRaw`SELECT pg_advisory_xact_lock(${lockKey})`

  const pool = await tx.examPool.findUnique({ where: { id: resolvedPool.id } })
  if (!pool) return { success: false, error: 'Pool not found' }
  if (!['OPEN', 'NEAR_FULL', 'DRAFT', 'CONFIRMED'].includes(pool.status)) {
    return { success: false, error: 'Pool is not open' }
  }
  if (pool.currentMemberCount >= POOL_MAX_CANDIDATES) {
    return { success: false, error: 'Pool is full' }
  }

  const existingInPool = await tx.poolMembership.findFirst({
    where: { poolId: pool.id, userId, status: { in: ACTIVE_MEMBERSHIP_STATUSES } },
  })
  if (existingInPool) {
    return {
      success: false,
      error: 'You already have a seat in this booking (one module per booking)',
    }
  }

  const totalMyPools = await tx.poolMembership.count({
    where: {
      userId,
      status: { in: ACTIVE_MEMBERSHIP_STATUSES },
    },
  })
  if (totalMyPools >= MAX_TOTAL_STUDENT_POOLS) {
    return {
      success: false,
      error: `You have reached the maximum of ${MAX_TOTAL_STUDENT_POOLS} pool bookings.`,
    }
  }

  if (pool.eventId && examComponentId) {
    const component = await tx.examComponent.findUnique({
      where: { id: examComponentId },
      select: { courseId: true },
    })

    const duplicateInEvent = await tx.poolMembership.findFirst({
      where: {
        userId,
        status: { in: ACTIVE_MEMBERSHIP_STATUSES },
        pool: { eventId: pool.eventId },
        examComponent: { courseId: component?.courseId },
      },
    })

    if (duplicateInEvent) {
      return {
        success: false,
        error:
          'You are already registered for this module in another pool within the same exam event.',
      }
    }
  }

  if (pool.examStartTime && pool.examEndTime) {
    const conflictingMemberships = await tx.poolMembership.findMany({
      where: {
        userId,
        status: { in: ACTIVE_MEMBERSHIP_STATUSES },
        pool: {
          id: { not: pool.id },
          examDate: pool.examDate,
          examStartTime: { lt: pool.examEndTime },
          examEndTime: { gt: pool.examStartTime },
        },
      },
      include: { pool: { select: { name: true, examStartTime: true, examEndTime: true } } },
    })
    if (conflictingMemberships.length > 0) {
      const conflictName = conflictingMemberships[0].pool.name
      return {
        success: false,
        error: `Time conflict: Already in "${conflictName}"`,
      }
    }
  }

  const profile = await tx.studentProfile.findUnique({
    where: { userId },
    include: { user: true },
  })

  if (!profile) {
    const user = await tx.user.findUnique({
      where: { id: userId },
      select: { role: true, programmeChoice: true },
    })
    if (!user || (user.role !== 'APPLICANT' && user.role !== 'STUDENT')) {
      return { success: false, error: 'User not found or unauthorized' }
    }
    if (user.role === 'APPLICANT' && user.programmeChoice !== 'EXAM_ONLY') {
      return { success: false, error: 'Please select the Exam Only pathway first' }
    }
  }

  if (profile?.enrollmentType === 'FULL_TIME') {
    return {
      success: false,
      error: 'Full-Time students do not join exam bookings individually.',
    }
  }

  // If the pool is already CONFIRMED (candidates 26-28), capture funds immediately
  const isJoiningConfirmedPool = pool.status === 'CONFIRMED'

  let feeToReserve = typeof input.reserveAmount === 'number' ? input.reserveAmount : 0
  if (typeof input.reserveAmount !== 'number') {
    const { calculatePoolSeatPrice } = await import('./pricing')
    const priceCalc = await calculatePoolSeatPrice(userId, pool.eventId)
    feeToReserve = priceCalc.totalPrice
  }

  if (input.bundleId) {
    // Imported dynamically and aliased to avoid a false-positive on the React
    // hooks linter, which treats any `use*` function call as a hook call.
    // `useBundleSeat` is a server-side bundle-redemption function, not a hook.
    const { useBundleSeat: applyBundleSeat } = await import('./bundles')
    await applyBundleSeat(tx, input.bundleId)
    feeToReserve = 0
  }

  // For non-confirmed pools: reserve funds (held until pool confirms)
  // For confirmed pools: skip reservation — we capture directly after membership creation
  if (feeToReserve > 0 && !isJoiningConfirmedPool) {
    await reserveFunds(
      tx,
      userId,
      feeToReserve,
      `Reserved for pool: ${pool.name}`,
      `POOL-${pool.id.substring(0, 8)}`,
      'POOL_RESERVATION'
    )
  }

  let booking: any = null
  if (eventIdForBooking && input.moduleCode) {
    booking = await tx.examBooking.create({
      data: {
        userId,
        examComponentId,
        eventId: eventIdForBooking,
        bookingType,
        moduleCode: input.moduleCode,
        amountPaid: input.amountPaid ?? feeToReserve,
        guaranteeType,
        demandStatus: 'POOLED',
        guaranteedSeat,
        status: isJoiningConfirmedPool ? 'APPROVED' : feeToReserve > 0 ? 'PENDING' : 'APPROVED',
        examDate: pool.examDate,
        isResit: input.isResit ?? bookingType === 'RESIT',
        // Audit 1a: persist the bundle association so bundle-funded bookings
        // remain traceable to the bundle that paid for them.
        bundleId: input.bundleId ?? null,
      },
    })
  }

  let membershipStatus: MembershipStatus
  let membershipAmountPaid: number

  if (isJoiningConfirmedPool && feeToReserve > 0) {
    // Pool is already confirmed — capture funds right away
    const { captureFunds } = await import('@/lib/wallet/operations')
    await captureFunds(
      tx,
      userId,
      feeToReserve,
      `Exam fee captured: ${pool.name}`,
      booking?.id || pool.id,
      booking?.id ? 'EXAM_BOOKING' : 'POOL_CAPTURE'
    )
    membershipStatus = 'CONFIRMED'
    membershipAmountPaid = feeToReserve
  } else {
    membershipStatus = feeToReserve > 0 ? 'RESERVED' : 'CONFIRMED'
    membershipAmountPaid = feeToReserve > 0 ? 0 : (input.amountPaid ?? 0)
  }

  const membership = await tx.poolMembership.create({
    data: {
      poolId: pool.id,
      userId,
      examComponentId,
      bookingId: booking?.id || null,
      status: membershipStatus,
      amountReserved: isJoiningConfirmedPool ? 0 : feeToReserve,
      amountPaid: membershipAmountPaid,
      ...(isJoiningConfirmedPool ? { confirmedAt: new Date(), paidAt: new Date() } : {}),
    },
  })

  const newCount = pool.currentMemberCount + 1

  // Determine new pool status:
  // - Already CONFIRMED and now at max → LOCKED
  // - Reaching POOL_MIN_CANDIDATES → CONFIRMED (auto-confirm trigger)
  // - Approaching threshold → NEAR_FULL
  // - Otherwise keep current status
  let newStatus: PoolStatus
  if (isJoiningConfirmedPool && newCount >= POOL_MAX_CANDIDATES) {
    newStatus = 'LOCKED'
  } else if (isJoiningConfirmedPool) {
    newStatus = 'CONFIRMED' // keep it confirmed
  } else if (newCount >= POOL_MIN_CANDIDATES) {
    newStatus = 'CONFIRMED'
  } else if (newCount >= POOL_NEAR_FULL_THRESHOLD) {
    newStatus = 'NEAR_FULL'
  } else {
    newStatus = pool.status
  }

  const allowedModules = pool.allowedModules || []
  const newAllowedModules =
    input.moduleCode && !allowedModules.includes(input.moduleCode)
      ? [...allowedModules, input.moduleCode]
      : allowedModules

  await tx.examPool.update({
    where: { id: pool.id },
    data: {
      currentMemberCount: newCount,
      status: newStatus,
      allowedModules: newAllowedModules,
      totalDemandSeats: { increment: 1 },
      ...(guaranteedSeat ? { guaranteedSeats: { increment: 1 } } : {}),
    },
  })

  let autoConfirmed = false
  if (newCount >= POOL_MIN_CANDIDATES && pool.status !== 'CONFIRMED') {
    await confirmPoolInternal(pool.id, tx)
    autoConfirmed = true
  }

  const triggeredNearFull = newStatus === 'NEAR_FULL' && pool.status !== 'NEAR_FULL'
  trackEvent('EXAM_POOL_JOINED', { poolId: pool.id }, input.userId).catch(() => {})
  return {
    success: true,
    membership,
    booking,
    pool: { id: pool.id, name: pool.name, status: newStatus, currentMemberCount: newCount },
    autoConfirmed,
    triggeredNearFull,
  }
}

import prisma from '@/lib/prisma/client'
import { joinPoolInternal } from './join'
import { ACTIVE_MEMBERSHIP_STATUSES } from '@/lib/utils/constants'

export async function joinWaitlist(poolId: string, userId: string, examComponentId: string) {
  // 1. Check if already on waitlist
  const existing = await prisma.poolWaitlist.findUnique({
    where: {
      poolId_userId_examComponentId: {
        poolId,
        userId,
        examComponentId,
      },
    },
  })
  if (existing && existing.status === 'PENDING') {
    return { success: false, error: 'You are already on the waitlist for this pool.' }
  }

  // 2. Check if already a member
  const inPool = await prisma.poolMembership.findFirst({
    where: { poolId, userId, status: { in: ACTIVE_MEMBERSHIP_STATUSES } },
  })
  if (inPool) {
    return { success: false, error: 'You are already a member of this pool.' }
  }

  // 3. Get next priority
  const lastEntry = await prisma.poolWaitlist.findFirst({
    where: { poolId },
    orderBy: { priority: 'desc' },
  })
  const priority = (lastEntry?.priority ?? 0) + 1

  const entry = await prisma.poolWaitlist.create({
    data: {
      poolId,
      userId,
      examComponentId,
      priority,
      status: 'PENDING',
    },
  })

  return { success: true, entry }
}

/**
 * Attempts to promote the next person on the waitlist into the pool.
 * Must be called within a transaction that has already locked the pool row.
 */
export async function promoteNextFromWaitlist(poolId: string, tx: any): Promise<any> {
  const next = await tx.poolWaitlist.findFirst({
    where: { poolId, status: 'PENDING' },
    orderBy: { priority: 'asc' },
  })

  if (!next) return null

  const examComponent = await tx.examComponent.findUnique({
    where: { id: next.examComponentId },
    select: { course: { select: { code: true } } },
  })

  // Attempt to join the pool using the internal function
  const result = await joinPoolInternal(tx, {
    poolId,
    userId: next.userId,
    examComponentId: next.examComponentId,
    moduleCode: examComponent?.course?.code,
  })

  if (result.success) {
    // Mark waitlist entry as PROMOTED
    await tx.poolWaitlist.update({
      where: { id: next.id },
      data: { status: 'PROMOTED' },
    })
    return { candidate: next, result }
  } else {
    // If promotion fails (e.g. no funds), mark entry as CANCELLED and try next
    await tx.poolWaitlist.update({
      where: { id: next.id },
      data: { status: 'CANCELLED' },
    })
    // Recursive call to try the next person
    return promoteNextFromWaitlist(poolId, tx)
  }
}

/**
 * Pool Withdrawal — Allows candidates to leave a pool.
 *
 * Supports both RESERVED and CONFIRMED memberships:
 * - RESERVED: release reserved funds back to available balance
 * - CONFIRMED: credit wallet (no bank refund, wallet credit only)
 *
 * On withdrawal:
 * 1. Release/credit funds to wallet
 * 2. Update membership to CANCELLED
 * 3. Decrement pool member count
 * 4. Downgrade pool status (NEAR_FULL → OPEN if count drops below 23)
 * 5. Send notifications to student and admin
 */

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { POOL_NEAR_FULL_THRESHOLD } from './types'
import { promoteNextFromWaitlist } from './waitlist'
import { decrementPoolMemberCount } from './operations'
import { creditToWallet } from '@/lib/wallet/operations'
import { logAuditEvent } from '../audit/logger'
import { sendWithdrawalConfirmationEmail, sendWaitlistPromotionEmail } from '@/lib/email/service'
import { ACTIVE_MEMBERSHIP_STATUSES } from '@/lib/utils/constants'

export interface WithdrawResult {
  success: boolean
  error?: string
  amountReleased?: number
}

export async function withdrawFromPool(poolId: string, userId: string): Promise<WithdrawResult> {
  try {
    const result = await prisma.$transaction(
      async (tx) => {
        // Advisory lock on pool to prevent concurrent modifications
        const lockKey = BigInt('0x' + poolId.replace(/-/g, '').slice(0, 15))
        await tx.$executeRaw`SELECT pg_advisory_xact_lock(${lockKey})`

        const pool = await tx.examPool.findUnique({ where: { id: poolId } })
        if (!pool) return { success: false, error: 'Pool not found' }

        // Find active membership (RESERVED or CONFIRMED)
        const membership = await tx.poolMembership.findFirst({
          where: { poolId, userId, status: { in: ACTIVE_MEMBERSHIP_STATUSES } },
        })

        if (!membership) {
          return { success: false, error: 'No active membership found in this pool' }
        }

        let releaseAmount = 0

        if (membership.status === 'RESERVED') {
          // Release reserved funds back to available balance
          releaseAmount = Number(membership.amountReserved) || 0
          if (releaseAmount > 0) {
            const wallet = await tx.wallet.findUnique({ where: { userId } })
            if (wallet) {
              await tx.wallet.update({
                where: { userId },
                data: {
                  reservedBalance: { decrement: releaseAmount },
                  availableBalance: { increment: releaseAmount },
                },
              })

              await tx.walletTransaction.create({
                data: {
                  walletId: wallet.id,
                  type: 'RELEASE',
                  amount: releaseAmount,
                  description: `Withdrew from pool: ${pool.name}`,
                  referenceId: `WITHDRAW-${poolId.substring(0, 8)}`,
                  referenceType: 'POOL_WITHDRAWAL',
                  balanceBefore: Number(wallet.balance),
                  balanceAfter: Number(wallet.balance),
                  reservedBefore: Number(wallet.reservedBalance),
                  reservedAfter: Number(wallet.reservedBalance) - releaseAmount,
                  availableBefore: Number(wallet.availableBalance),
                  availableAfter: Number(wallet.availableBalance) + releaseAmount,
                },
              })
            }
          }
        } else if (membership.status === 'CONFIRMED') {
          // Credit wallet for confirmed memberships (no bank refund, wallet credit only)
          releaseAmount = Number(membership.amountPaid) || Number(membership.amountReserved) || 0
          if (releaseAmount > 0) {
            await creditToWallet(
              tx,
              userId,
              releaseAmount,
              `Pool withdrawal credit: ${pool.name}`,
              poolId,
              'POOL_WITHDRAWAL'
            )
          }

          // Notify admin about confirmed withdrawal
          const staffUsers = await tx.user.findMany({
            where: { role: { in: ['ADMIN', 'STAFF'] } },
            select: { id: true },
            take: 20,
          })
          for (const staff of staffUsers) {
            await tx.notification.create({
              data: {
                userId: staff.id,
                title: 'Confirmed Member Withdrew',
                message: `A confirmed member withdrew from "${pool.name}". €${releaseAmount.toFixed(2)} wallet credit issued.`,
                type: 'POOL_UPDATE',
                linkUrl: '/staff/exam-pools',
                linkText: 'View Pools',
              },
            })
          }
        }

        // Cancel membership
        await tx.poolMembership.update({
          where: { id: membership.id },
          data: { status: 'CANCELLED' },
        })

        // Decrement pool count and possibly downgrade status
        await decrementPoolMemberCount(poolId, tx)

        // Log the audit event
        await logAuditEvent({
          userId,
          action: 'POOL_WITHDRAWAL',
          entity: 'ExamPool',
          entityId: poolId,
          description: `User ${userId} withdrew from pool "${pool.name}". Seat freed for waitlist.`,
        })

        // Phase 9: Auto-promote from waitlist if pool was full or has space
        const promotion = await promoteNextFromWaitlist(poolId, tx)

        return {
          success: true,
          amountReleased: releaseAmount,
          promotedUserId: promotion?.candidate?.userId,
          _emailData: { poolName: pool.name, examDate: pool.examDate },
        }
      },
      { isolationLevel: Prisma.TransactionIsolationLevel.Serializable }
    )

    // Send emails outside transaction
    if (result.success) {
      const { format } = await import('date-fns')

      // Withdrawal confirmation to the user who withdrew
      const user = await prisma.user.findUnique({
        where: { id: userId },
        select: { email: true, academyEmail: true, profile: { select: { firstName: true } } },
      })
      if (user) {
        const email = user.academyEmail || user.email
        const name = user.profile?.firstName || 'Student'
        sendWithdrawalConfirmationEmail(
          email,
          name,
          (result as any)._emailData?.poolName || 'Pool',
          result.amountReleased || 0
        ).catch(console.error)
      }

      // Waitlist promotion notification
      if ((result as any).promotedUserId) {
        const promoted = await prisma.user.findUnique({
          where: { id: (result as any).promotedUserId },
          select: { email: true, academyEmail: true, profile: { select: { firstName: true } } },
        })
        if (promoted) {
          const email = promoted.academyEmail || promoted.email
          const name = promoted.profile?.firstName || 'Student'
          const examDateStr = (result as any)._emailData?.examDate
            ? format(new Date((result as any)._emailData.examDate), 'dd MMM yyyy')
            : 'TBA'
          sendWaitlistPromotionEmail(
            email,
            name,
            (result as any)._emailData?.poolName || 'Pool',
            examDateStr,
            'Module'
          ).catch(console.error)
        }
      }
    }

    return result
  } catch (err: any) {
    console.error('[POOL WITHDRAW ERROR]', err)
    return { success: false, error: err.message || 'Failed to withdraw from pool' }
  }
}

import prisma from '@/lib/prisma/client'

export const DEFAULT_LATE_BOOKING_DAYS = 14
export const DEFAULT_LATE_BOOKING_SURCHARGE = 50

export async function calculateBookingPrice(
  poolId: string,
  userId: string
): Promise<{
  basePrice: number
  surcharge: number
  total: number
  isLateBooking: boolean
}> {
  const pool = await prisma.examPool.findUnique({
    where: { id: poolId },
    include: { event: true },
  })

  if (!pool) {
    throw new Error('Pool not found')
  }

  const basePrice = Number(pool.seatPrice)
  const lateBookingDays = pool.event?.lateBookingDays ?? DEFAULT_LATE_BOOKING_DAYS
  const surchargeAmount = Number(pool.event?.lateBookingSurcharge ?? DEFAULT_LATE_BOOKING_SURCHARGE)

  const examDate = new Date(pool.examDate)
  const today = new Date()
  const daysUntilExam = Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24))

  const isLateBooking = daysUntilExam <= lateBookingDays && daysUntilExam > 0

  return {
    basePrice,
    surcharge: isLateBooking ? surchargeAmount : 0,
    total: basePrice + (isLateBooking ? surchargeAmount : 0),
    isLateBooking,
  }
}

export function isLateBooking(
  examDate: Date,
  lateBookingDays: number = DEFAULT_LATE_BOOKING_DAYS
): boolean {
  const today = new Date()
  const daysUntilExam = Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24))
  return daysUntilExam <= lateBookingDays && daysUntilExam > 0
}

export function getDaysUntilExam(examDate: Date): number {
  const today = new Date()
  return Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24))
}

import 'server-only'
import { Prisma } from '@prisma/client'
import { AsyncLocalStorage } from 'async_hooks'

const rlsBypassStorage = new AsyncLocalStorage<boolean>()

// Request-scoped RLS transaction context.
// When set, queries reuse the existing transaction instead of opening a new one per query.
interface RlsTxContext {
  tx: any
  userId: string
  userRole?: string
}
const rlsTxStorage = new AsyncLocalStorage<RlsTxContext>()

function stripInternalPrismaArgs<T>(value: T): T {
  if (Array.isArray(value)) {
    return value.map((item) => stripInternalPrismaArgs(item)) as T
  }

  if (
    value &&
    typeof value === 'object' &&
    !(value instanceof Date) &&
    !(value instanceof Uint8Array)
  ) {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([key]) => !key.startsWith('__'))
      .map(([key, nestedValue]) => [key, stripInternalPrismaArgs(nestedValue)])

    return Object.fromEntries(entries) as T
  }

  return value
}

async function getSession() {
  if (process.env.NEXT_PHASE === 'phase-production-build') return null

  try {
    const { getCachedSession } = await import('@/lib/auth/session-context')
    const session = await getCachedSession()
    if (!session && process.env.NODE_ENV === 'development') {
      console.warn('[RLS] No active session - guest access.')
    }
    return session
  } catch {
    return null
  }
}

async function applyRlsContext(
  client: { $executeRaw: (...args: any[]) => Promise<unknown> },
  userId: string,
  userRole?: string
) {
  // Combine into a single transaction-local setup to prevent pg concurrent query warnings
  // and reduce round-trips. We use a single $executeRaw with multiple set_config calls.
  if (userRole) {
    await client.$executeRaw(Prisma.sql`
      SELECT 
        set_config('role', 'app_user', true),
        set_config('aerojet.user_id', ${userId}, true),
        set_config('aerojet.user_role', ${userRole}, true)
    `)
  } else {
    await client.$executeRaw(Prisma.sql`
      SELECT 
        set_config('role', 'app_user', true),
        set_config('aerojet.user_id', ${userId}, true)
    `)
  }
}

export const rlsExtension = (baseClient: any) =>
  Prisma.defineExtension({
    name: 'rlsExtensionHardened',

    client: {
      async $transaction<T>(this: T, args: any, options?: any) {
        const session = await getSession()
        const userId = session?.user?.id
        const userRole = (session as any)?.user?.role

        if (!userId) return (baseClient as any).$transaction(args, options)

        if (typeof args === 'function') {
          const originalBlock = args
          return (baseClient as any).$transaction(async (tx: any) => {
            await applyRlsContext(tx, userId, userRole)
            return originalBlock(tx)
          }, options)
        }

        // For array-based transactions, we must wrap them in a callback-based transaction
        // to ensure RLS context is applied to the same connection before any other queries run.
        return (baseClient as any).$transaction(async (tx: any) => {
          await applyRlsContext(tx, userId, userRole)
          const results = []
          for (const query of args) {
            results.push(await (tx as any)[query.model][query.operation](query.args))
          }
          return results
        }, options)
      },
    },

    query: {
      $allModels: {
        async $allOperations({ model, operation, args, query }) {
          const sanitizedArgs = stripInternalPrismaArgs(args)

          const rlsModels = new Set([
            'User',
            'Profile',
            'StudentProfile',
            'StaffProfile',
            'InstructorProfile',
            'Wallet',
            'WalletTransaction',
            'Payment',
            'Invoice',
            'PaymentMilestone',
            'Enrollment',
            'FullTimeEnrollment',
            'ModularEnrollment',
            'TuitionBooking',
            'Grade',
            'AttendanceRecord',
            'ExamBooking',
            'ExamResult',
            'ExamBundle',
            'PoolMembership',
            'PoolWaitlist',
            'BookingEntitlement',
            'ExamExemption',
            'Notification',
            'Message',
            'FileUpload',
            'Referral',
            'AdminNote',
            'StudentLicenseTarget',
            'AuditLog',
          ])

          if (process.env.NEXT_PHASE === 'phase-production-build' || !rlsModels.has(model)) {
            return query(sanitizedArgs)
          }

          const session = await getSession()
          const userId = session?.user?.id
          if (!userId) return query(sanitizedArgs)

          const userRole = (session as any)?.user?.role
          if (
            userRole &&
            ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER', 'INSTRUCTOR'].includes(userRole)
          ) {
            return query(sanitizedArgs)
          }

          if (rlsBypassStorage.getStore() === true) {
            return query(sanitizedArgs)
          }

          const modelKey = model.charAt(0).toLowerCase() + model.slice(1)

          // Reuse an existing request-scoped RLS transaction if available
          const existingCtx = rlsTxStorage.getStore()
          if (existingCtx) {
            return existingCtx.tx[modelKey][operation](sanitizedArgs)
          }

          return rlsBypassStorage.run(true, () =>
            baseClient.$transaction(
              async (tx: any) => {
                await applyRlsContext(tx, userId, userRole)
                return tx[modelKey][operation](sanitizedArgs)
              },
              {
                maxWait: 30000,
                timeout: 60000,
              }
            )
          )
        },
      },
      async $queryRaw({ args, query }) {
        const sanitizedArgs = stripInternalPrismaArgs(args)

        const session = await getSession()
        if (!session?.user?.id) return query(sanitizedArgs)

        const userRole = (session as any)?.user?.role
        if (
          userRole &&
          ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER', 'INSTRUCTOR'].includes(userRole)
        ) {
          return query(sanitizedArgs)
        }

        return baseClient.$transaction(
          async (tx: any) => {
            await applyRlsContext(tx, session.user.id, userRole)
            return query(sanitizedArgs)
          },
          {
            maxWait: 30000,
            timeout: 60000,
          }
        )
      },
    },
  })

/**
 * Run multiple RLS-protected queries in a single transaction.
 * `set_config()` is called once, and all queries inside `fn` reuse that connection.
 * Use this in student/applicant pages to avoid per-query transaction overhead.
 *
 * @example
 * const [enrollments, grades] = await withRlsBatch(async () => {
 *   return Promise.all([
 *     prisma.enrollment.findMany({ where: { userId } }),
 *     prisma.grade.findMany({ where: { userId } }),
 *   ])
 * })
 */
export async function withRlsBatch<T>(fn: () => Promise<T>): Promise<T> {
  const session = await getSession()
  const userId = session?.user?.id
  if (!userId) return fn()

  const userRole = (session as any)?.user?.role
  if (userRole && ['ADMIN', 'SUPER_ADMIN', 'STAFF', 'EXAMINER', 'INSTRUCTOR'].includes(userRole)) {
    return fn()
  }

  const { prismaBase } = await import('./db-base')

  return prismaBase.$transaction(
    async (tx: any) => {
      await applyRlsContext(tx, userId, userRole)
      const ctx: RlsTxContext = { tx, userId, userRole }
      return rlsTxStorage.run(ctx, fn)
    },
    { maxWait: 30000, timeout: 60000 }
  )
}

import 'server-only'
import { Prisma } from '@prisma/client'
import { isBackupEnabled } from '@/lib/supabase/client'
import { transformForSupabase, BACKUP_MODELS } from '@/lib/supabase/dual-write'
import { getSupabasePrismaClient } from '@/lib/supabase/dual-write'

/**
 * Prisma Extension for real-time synchronization to Supabase.
 * Hooks into create, update, delete, and upsert operations.
 */
export const supabaseSyncExtension = () => Prisma.defineExtension({
  name: 'supabaseSyncExtension',
  query: {
    $allModels: {
      async $allOperations({ model, operation, args, query }) {
        // Execute the operation in the primary DB (Neon) first
        const result = await query(args)

        // Non-blocking sync if backup is enabled
        if (model && isBackupEnabled()) {
          const modelKey = model.charAt(0).toLowerCase() + model.slice(1)

          // Only sync if the model is part of BACKUP_MODELS
          if (BACKUP_MODELS.includes(modelKey as any)) {
            setTimeout(async () => {
              try {
                const supabase = await getSupabasePrismaClient()
                if (!supabase) return

                const supabaseModel = (supabase as any)[modelKey]
                if (!supabaseModel) return

                const transformed = result ? transformForSupabase(result) as any : null

                if (operation === 'create' || operation === 'update' || operation === 'upsert') {
                  if (transformed && transformed.id) {
                    await supabaseModel.upsert({
                      where: { id: transformed.id },
                      create: transformed,
                      update: transformed,
                    })
                  }
                } else if (operation === 'delete') {
                  if (transformed && transformed.id) {
                    await supabaseModel.delete({
                      where: { id: transformed.id },
                    }).catch(() => {})
                  }
                }
              } catch (error) {
                console.error(`[Supabase Sync Extension Error] failed for ${model}/${operation}:`, error)
              }
            }, 0)
          }
        }

        return result
      },
    },
  },
})

/**
 * A.5.c — Staff/admin tooling on top of lib/referral/operations.ts.
 *
 * Adds: fraud heuristics, manual disqualification, ambassador revoke,
 * payout batch creation, CSV export.
 *
 * Gated by `MANAGE_REFERRALS` permission key at the route layer.
 */

import 'server-only'
import { prismaUnfiltered } from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { createAuditLog } from '@/lib/audit/logger'
import { getExamPricingConfig } from '@/lib/pools/pricing-config'

/** Fraud-score bumps — sum into final fraudScore. */
const FRAUD_WEIGHTS = {
  SAME_IP_HASH: 30,
  SAME_UA_HASH: 20,
  SAME_EMAIL_DOMAIN: 10,
  BURST_24H: 40,
  REFERRER_SELF_DOMAIN: 15,
}

interface FraudOutcome {
  referralId: string
  added: string[]
  newScore: number
}

/**
 * Scan recent referrals and stamp `fraudScore` + `fraudReasons` based on
 * cheap heuristics. Idempotent — running twice produces the same result for
 * the same input population.
 *
 * @param sinceDays look at referrals created in the last N days (default 7)
 */
export async function runFraudHeuristics(sinceDays = 7): Promise<{
  scanned: number
  flagged: number
  outcomes: FraudOutcome[]
}> {
  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000)
  const referrals = await prismaUnfiltered.referral.findMany({
    where: { createdAt: { gte: since } },
    include: {
      referrer: { select: { id: true, email: true } },
      referee: { select: { id: true, email: true, createdAt: true } },
    },
  })

  const outcomes: FraudOutcome[] = []
  let flagged = 0

  for (const r of referrals) {
    const reasons = new Set<string>(r.fraudReasons ?? [])
    let score = 0

    // 1) Burst: 3+ referrals from same referrer in 24h around this referee's signup
    const refereeAt = r.referee.createdAt.getTime()
    const windowStart = new Date(refereeAt - 24 * 60 * 60 * 1000)
    const windowEnd = new Date(refereeAt + 24 * 60 * 60 * 1000)
    const burst = await prismaUnfiltered.referral.count({
      where: {
        referrerId: r.referrerId,
        createdAt: { gte: windowStart, lte: windowEnd },
      },
    })
    if (burst >= 3) {
      reasons.add('BURST_24H')
      score += FRAUD_WEIGHTS.BURST_24H
    }

    // 2) Same email domain referrer ↔ referee
    const refDomain = r.referrer.email.split('@')[1]?.toLowerCase() ?? ''
    const refeDomain = r.referee.email.split('@')[1]?.toLowerCase() ?? ''
    if (refDomain && refDomain === refeDomain) {
      reasons.add('SAME_EMAIL_DOMAIN')
      score += FRAUD_WEIGHTS.SAME_EMAIL_DOMAIN
    }

    // 3) IP / UA collisions: if we have signup hashes recorded on Referral
    if (r.signupIpHash) {
      const ipMatches = await prismaUnfiltered.referral.count({
        where: { signupIpHash: r.signupIpHash, id: { not: r.id } },
      })
      if (ipMatches > 0) {
        reasons.add('SAME_IP_HASH')
        score += FRAUD_WEIGHTS.SAME_IP_HASH
      }
    }
    if (r.signupUaHash) {
      const uaMatches = await prismaUnfiltered.referral.count({
        where: { signupUaHash: r.signupUaHash, id: { not: r.id } },
      })
      if (uaMatches > 0) {
        reasons.add('SAME_UA_HASH')
        score += FRAUD_WEIGHTS.SAME_UA_HASH
      }
    }

    if (score !== r.fraudScore || reasons.size !== (r.fraudReasons?.length ?? 0)) {
      await prismaUnfiltered.referral.update({
        where: { id: r.id },
        data: { fraudScore: score, fraudReasons: Array.from(reasons) },
      })
    }
    if (score >= 30) flagged += 1
    outcomes.push({
      referralId: r.id,
      added: Array.from(reasons),
      newScore: score,
    })
  }

  return { scanned: referrals.length, flagged, outcomes }
}

/**
 * Manually disqualify a referral. Reverses the qualification side-effects:
 * decrements `successfulReferrals` and, if the referrer just lost ambassador
 * status, optionally revokes ambassador.
 */
export async function disqualifyReferral(
  referralId: string,
  actorId: string,
  reason: string
): Promise<void> {
  await prismaUnfiltered.$transaction(async (tx) => {
    const r = await tx.referral.findUnique({ where: { id: referralId } })
    if (!r) throw new Error('Referral not found')
    if (r.status === 'DISQUALIFIED') return

    await tx.referral.update({
      where: { id: referralId },
      data: {
        status: 'DISQUALIFIED',
        reviewedById: actorId,
        reviewedAt: new Date(),
        fraudReasons: Array.from(new Set([...(r.fraudReasons ?? []), 'STAFF_REVIEW'])),
      },
    })

    if (r.status === 'QUALIFIED') {
      await tx.user.update({
        where: { id: r.referrerId },
        data: { successfulReferrals: { decrement: 1 } },
      })
    }
  })

  await createAuditLog({
    userId: actorId,
    action: 'UPDATE',
    entity: 'Referral',
    entityId: referralId,
    description: `Referral disqualified: ${reason}`,
    changes: { after: { status: 'DISQUALIFIED', reason } },
  })
}

/** Revoke ambassador status — useful when fraud cluster found. */
export async function revokeAmbassador(
  userId: string,
  actorId: string,
  reason: string
): Promise<void> {
  await prismaUnfiltered.user.update({
    where: { id: userId },
    data: { isAmbassador: false },
  })
  await createAuditLog({
    userId: actorId,
    action: 'UPDATE',
    entity: 'User',
    entityId: userId,
    description: `Ambassador status revoked: ${reason}`,
    changes: { after: { isAmbassador: false } },
  })
}

/**
 * Create a payout run covering [periodStart, periodEnd]. Aggregates each
 * referrer's qualified-and-not-yet-paid referrals into a single
 * `ReferralPayout` row, valued at `pricing.ambassadorPayoutPerReferral`
 * (falls back to 25 EUR if not configured).
 *
 * Returns the number of payout rows created.
 */
export async function createPayoutRun(
  periodStart: Date,
  periodEnd: Date,
  actorId: string
): Promise<{ created: number }> {
  const pricing = await getExamPricingConfig().catch(() => ({} as any))
  const perReferral: number = pricing?.ambassadorPayoutPerReferral ?? 25

  const qualified = await prismaUnfiltered.referral.findMany({
    where: {
      status: 'QUALIFIED',
      qualifiedAt: { gte: periodStart, lte: periodEnd },
    },
    select: { referrerId: true },
  })

  const counts = new Map<string, number>()
  for (const q of qualified) {
    counts.set(q.referrerId, (counts.get(q.referrerId) ?? 0) + 1)
  }

  let created = 0
  for (const [referrerId, count] of counts) {
    const amount = new Prisma.Decimal(count * perReferral)
    await prismaUnfiltered.referralPayout.create({
      data: {
        referrerId,
        amount,
        currency: 'EUR',
        periodStart,
        periodEnd,
        status: 'PENDING',
      },
    })
    created += 1
  }

  await createAuditLog({
    userId: actorId,
    action: 'CREATE',
    entity: 'ReferralPayout',
    entityId: `run:${periodStart.toISOString()}..${periodEnd.toISOString()}`,
    description: `Payout run created — ${created} payouts`,
    changes: { period: { periodStart, periodEnd }, count: created, perReferral },
  })
  return { created }
}

/** Return a CSV string for a set of payouts (or all PENDING if no IDs). */
export async function exportPayoutCsv(payoutIds?: string[]): Promise<string> {
  const payouts = await prismaUnfiltered.referralPayout.findMany({
    where: payoutIds && payoutIds.length > 0 ? { id: { in: payoutIds } } : { status: 'PENDING' },
    orderBy: { createdAt: 'asc' },
  })

  // Need referrer details for the CSV (email, bank-ref placeholder)
  const referrerIds = Array.from(new Set(payouts.map((p) => p.referrerId)))
  const users = await prismaUnfiltered.user.findMany({
    where: { id: { in: referrerIds } },
    select: { id: true, email: true, profile: { select: { firstName: true, lastName: true } } },
  })
  const userMap = new Map(users.map((u) => [u.id, u]))

  const header = ['payoutId', 'referrerId', 'name', 'email', 'amount', 'currency', 'periodStart', 'periodEnd', 'status']
  const rows = payouts.map((p) => {
    const u = userMap.get(p.referrerId)
    const name = u?.profile ? `${u.profile.firstName} ${u.profile.lastName}` : ''
    return [
      p.id,
      p.referrerId,
      name,
      u?.email ?? '',
      String(p.amount),
      p.currency,
      p.periodStart.toISOString(),
      p.periodEnd.toISOString(),
      p.status,
    ].map((v) => `"${String(v).replace(/"/g, '""')}"`).join(',')
  })
  return [header.join(','), ...rows].join('\n')
}

/**
 * Referral & Ambassador System
 *
 * RULES:
 * - Each user gets a unique referralCode on first request
 * - When a referee registers + pays registration fee → referral qualifies
 * - 10+ qualified referrals → user auto-promoted to Ambassador
 * - Ambassador gets €100 wallet credit + lifetime discounted pool seat (€270)
 * - Ambassador pricing is already handled in lib/pools/pricing.ts
 */

import prisma from '@/lib/prisma/client'
import { Prisma } from '@prisma/client'
import { getExamPricingConfig } from '@/lib/pools/pricing-config'

const AMBASSADOR_THRESHOLD = 10

/**
 * Generate or retrieve a user's referral code.
 */
export async function getOrCreateReferralCode(userId: string): Promise<string> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { referralCode: true, email: true },
  })
  if (!user) throw new Error('User not found')

  if (user.referralCode) return user.referralCode

  // Generate a short, unique code
  const prefix = 'AERO'
  const randomPart = Math.random().toString(36).substring(2, 8).toUpperCase()
  const code = `${prefix}-${randomPart}`

  await prisma.user.update({
    where: { id: userId },
    data: { referralCode: code },
  })

  return code
}

/**
 * Record a referral when a new user registers with a referral code.
 * Called during registration flow.
 */
export async function recordReferral(
  referralCode: string,
  refereeId: string
): Promise<{ success: boolean; error?: string }> {
  const referrer = await prisma.user.findFirst({
    where: { referralCode: referralCode },
    select: { id: true, role: true },
  })

  if (!referrer) return { success: false, error: 'Invalid referral code' }
  if (referrer.role !== 'STUDENT') return { success: false, error: 'Only students can be referrers' }
  if (referrer.id === refereeId) return { success: false, error: 'Cannot refer yourself' }

  // Check if already referred
  const existing = await prisma.referral.findUnique({
    where: {
      referrerId_refereeId: { referrerId: referrer.id, refereeId },
    },
  })
  if (existing) return { success: false, error: 'Referral already recorded' }

  await prisma.referral.create({
    data: {
      referrerId: referrer.id,
      refereeId,
      status: 'PENDING',
    },
  })

  return { success: true }
}

/**
 * Qualify a referral when the referee pays their registration fee.
 * Also checks if the referrer has reached Ambassador threshold.
 */
export async function qualifyReferral(refereeId: string): Promise<void> {
  const referral = await prisma.referral.findFirst({
    where: { refereeId, status: 'PENDING' },
  })

  if (!referral) return // No pending referral for this user

  await prisma.$transaction(
    async (tx) => {
      // Mark referral as qualified
      await tx.referral.update({
        where: { id: referral.id },
        data: { status: 'QUALIFIED', qualifiedAt: new Date() },
      })

      // Increment referrer's successful referral count
      const referrer = await tx.user.update({
        where: { id: referral.referrerId },
        data: { successfulReferrals: { increment: 1 } },
      })

      // Check if referrer has reached Ambassador threshold
      if (referrer.successfulReferrals >= AMBASSADOR_THRESHOLD && !referrer.isAmbassador) {
        await promoteToAmbassador(tx, referrer.id)
      }
    },
    { isolationLevel: Prisma.TransactionIsolationLevel.Serializable }
  )
}

/**
 * Promote a user to Ambassador status and credit their wallet.
 */
async function promoteToAmbassador(tx: any, userId: string) {
  const pricing = await getExamPricingConfig()

  // Set ambassador flag
  await tx.user.update({
    where: { id: userId },
    data: { isAmbassador: true },
  })

  // Credit wallet with ambassador bonus
  const wallet = await tx.wallet.findUnique({ where: { userId } })
  if (wallet) {
    await tx.wallet.update({
      where: { userId },
      data: {
        balance: { increment: pricing.ambassadorCredit },
        availableBalance: { increment: pricing.ambassadorCredit },
      },
    })

    await tx.walletTransaction.create({
      data: {
        walletId: wallet.id,
        type: 'CREDIT',
        amount: pricing.ambassadorCredit,
        description: `Ambassador status achieved. EUR ${pricing.ambassadorCredit} bonus credited.`,
        referenceType: 'AMBASSADOR_BONUS',
        referenceId: `AMBASSADOR-${userId}`,
        balanceBefore: Number(wallet.balance),
        balanceAfter: Number(wallet.balance) + pricing.ambassadorCredit,
        availableBefore: Number(wallet.availableBalance),
        availableAfter: Number(wallet.availableBalance) + pricing.ambassadorCredit,
      },
    })
  }

  // Send ambassador promotion email (outside the calling transaction scope, fire-and-forget)
  import('@/lib/email/service').then(async ({ sendAmbassadorPromotionEmail }) => {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { email: true, academyEmail: true, profile: { select: { firstName: true } } },
    })
    if (user) {
      const email = user.academyEmail || user.email
      const name = user.profile?.firstName || 'Student'
      sendAmbassadorPromotionEmail(email, name, pricing.ambassadorCredit).catch(console.error)
    }
  }).catch(console.error)
}

/**
 * Get referral stats for a user (for dashboard display).
 */
export async function getReferralStats(userId: string) {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      referralCode: true,
      isAmbassador: true,
      successfulReferrals: true,
    },
  })

  const referrals = await prisma.referral.findMany({
    where: { referrerId: userId },
    include: {
      referee: {
        select: {
          profile: { select: { firstName: true, lastName: true } },
          createdAt: true,
        },
      },
    },
    orderBy: { createdAt: 'desc' },
  })

  return {
    referralCode: user?.referralCode,
    isAmbassador: user?.isAmbassador ?? false,
    totalReferrals: referrals.length,
    qualifiedReferrals: user?.successfulReferrals ?? 0,
    pendingReferrals: referrals.filter((r) => r.status === 'PENDING').length,
    progressToAmbassador: Math.min(
      100,
      Math.round(((user?.successfulReferrals ?? 0) / AMBASSADOR_THRESHOLD) * 100)
    ),
    remainingForAmbassador: Math.max(0, AMBASSADOR_THRESHOLD - (user?.successfulReferrals ?? 0)),
    referrals: referrals.map((r) => ({
      id: r.id,
      refereeName: r.referee.profile
        ? `${r.referee.profile.firstName} ${r.referee.profile.lastName?.[0]}.`
        : 'Unknown',
      status: r.status,
      qualifiedAt: r.qualifiedAt,
      createdAt: r.createdAt,
    })),
  }
}

export function sanitizeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
}

export function sanitizeInput(input: string): string {
  return input.trim().replace(/[\x00-\x1F\x7F]/g, '')
}

export function sanitizeEmail(email: string): string {
  return email.trim().toLowerCase()
}

export function sanitizePhone(phone: string): string {
  return phone.replace(/[^\d+]/g, '')
}

export function sanitizeObject<T extends Record<string, any>>(obj: T): T {
  const sanitized = { ...obj }
  for (const [key, value] of Object.entries(sanitized)) {
    if (typeof value === 'string') {
      (sanitized as any)[key] = sanitizeInput(value)
    }
  }
  return sanitized
}

import prisma from '@/lib/prisma/client'
import bcrypt from 'bcryptjs'
import { sendEmail, activationEmail, paymentApprovedEmail } from '@/lib/email'
import { generateAcademyEmail } from '@/lib/utils'
import { topUpWallet } from '@/lib/wallet/operations'
import type { ApprovalResult, ApprovalOptions } from './types'

export async function approveApplicant(
  userId: string,
  options: ApprovalOptions
): Promise<ApprovalResult<{ academyEmail: string; tempPassword: string }>> {
  try {
    const user = await prisma.user.findUnique({ where: { id: userId }, include: { profile: true } })
    if (!user) return { success: false, error: 'User not found' }
    if (user.status === 'ACTIVE') return { success: false, error: 'Already active' }

    const firstName = user.profile?.firstName || ''
    const lastName = user.profile?.lastName || ''
    const middleName = user.profile?.middleName || undefined
    const academyEmail = generateAcademyEmail(firstName, lastName, middleName)
    const tempPassword = Math.random().toString(36).slice(-10) + 'A1!'
    const hashed = await bcrypt.hash(tempPassword, 12)

    await prisma.user.update({
      where: { id: userId },
      data: {
        status: 'ACTIVE',
        personalEmail: user.email, // Preserve personal email
        email: academyEmail, // Replace with academy email
        academyEmail,
        password: hashed,
        mustChangePassword: true,
      },
    })

    sendEmail({
      to: user.email,
      subject: 'Aerojet Academy - Account Activated',
      html: await activationEmail(firstName, academyEmail, tempPassword),
    }).catch(() => {})

    return { success: true, data: { academyEmail, tempPassword } }
  } catch (err: unknown) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' }
  }
}

export async function approvePayment(
  paymentId: string,
  options: ApprovalOptions
): Promise<ApprovalResult> {
  try {
    const payment = await prisma.payment.findUnique({
      where: { id: paymentId },
      include: { user: { include: { profile: true } } },
    })
    if (!payment) return { success: false, error: 'Payment not found' }
    if (payment.status !== 'PENDING') return { success: false, error: 'Payment is not pending' }

    await prisma.payment.update({
      where: { id: paymentId },
      data: {
        status: 'APPROVED',
        approvedBy: options.approvedBy,
        approvedAt: new Date(),
        notes: options.notes,
      },
    })

    // If wallet top-up, credit the wallet
    if (payment.referenceType === 'WALLET_TOP_UP') {
      await prisma.$transaction(async (tx) => {
        await topUpWallet(
          tx,
          payment.userId,
          Number(payment.amount),
          `Top-up approved: ${payment.referenceCode}`,
          payment.id,
          'PAYMENT_ID'
        )
      })
    }

    const name = payment.user.profile?.firstName || 'User'
    sendEmail({
      to: payment.user.academyEmail || payment.user.email,
      subject: 'Payment Approved',
      html: await paymentApprovedEmail(name, `€${payment.amount}`, payment.referenceCode || ''),
    }).catch(() => {})

    return { success: true }
  } catch (err: unknown) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' }
  }
}

import 'server-only'
import { prismaUnfiltered } from '@/lib/prisma/client'
import {
  DOCUMENT_BUCKET,
  isSupabaseStorageAvailable,
  uploadToStorage,
} from './supabase-storage'
import { getSupabaseAdmin } from '@/lib/supabase/client'

/**
 * Mirrors a single FileUpload row from UploadThing → Supabase storage.
 * Called by the nightly `/api/cron/supabase-mirror` reconciliation job.
 *
 * Returns:
 *   - 'mirrored' on success
 *   - 'skipped:<reason>' when not applicable
 *   - 'error:<message>' on failure (logged + counted, not thrown)
 */
export async function mirrorOne(fileUploadId: string): Promise<string> {
  const row = await prismaUnfiltered.fileUpload.findUnique({
    where: { id: fileUploadId },
  })
  if (!row) return 'skipped:not-found'
  if (row.mirroredAt) return 'skipped:already-mirrored'
  if (!row.uploadthingUrl && !row.url) return 'skipped:no-source-url'
  if (!row.supabasePath) return 'skipped:no-target-path'

  const sourceUrl = row.uploadthingUrl || row.url
  try {
    const res = await fetch(sourceUrl)
    if (!res.ok) return `error:fetch ${res.status}`
    const bytes = Buffer.from(await res.arrayBuffer())
    await uploadToStorage(row.supabasePath, bytes, row.mimeType || 'application/octet-stream')
    await prismaUnfiltered.fileUpload.update({
      where: { id: row.id },
      data: { mirroredAt: new Date() },
    })
    return 'mirrored'
  } catch (err: any) {
    console.error(`[uploadthing-mirror] ${fileUploadId} failed:`, err.message)
    return `error:${err.message?.slice(0, 100) ?? 'unknown'}`
  }
}

/**
 * Process up to `limit` unmirrored uploads in one cron tick.
 * Default 50 keeps a run under the Vercel cron 10s budget assuming ~150KB/sec
 * UT→Supabase throughput (typical Vercel Edge → us-east-1).
 */
export async function mirrorBatch(limit = 50): Promise<{
  scanned: number
  mirrored: number
  errors: string[]
  skipped: number
}> {
  if (!isSupabaseStorageAvailable()) {
    return { scanned: 0, mirrored: 0, errors: ['supabase-not-configured'], skipped: 0 }
  }
  const candidates = await prismaUnfiltered.fileUpload.findMany({
    where: { mirroredAt: null, supabasePath: { not: null } },
    select: { id: true },
    orderBy: { createdAt: 'asc' },
    take: limit,
  })

  let mirrored = 0
  let skipped = 0
  const errors: string[] = []
  for (const c of candidates) {
    const result = await mirrorOne(c.id)
    if (result === 'mirrored') mirrored += 1
    else if (result.startsWith('error')) errors.push(`${c.id}: ${result}`)
    else skipped += 1
  }
  return { scanned: candidates.length, mirrored, errors, skipped }
}

/**
 * 30-day retention sweep for temporary applicant/payment uploads that were
 * never linked to a permanent record. Keeps Supabase storage bounded.
 *
 * "Temp" = folder prefix `applicants/temp/` or `payments/temp/`. Production
 * uploads use the user's id as the second segment, so they never match.
 */
export async function sweepTempFolders(maxAgeDays = 30): Promise<{
  deleted: number
  scanned: number
  errors: string[]
}> {
  const supa = getSupabaseAdmin()
  if (!supa) return { deleted: 0, scanned: 0, errors: ['supabase-not-configured'] }

  const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000
  const errors: string[] = []
  let deleted = 0
  let scanned = 0

  for (const prefix of ['applicants/temp', 'payments/temp']) {
    const { data, error } = await supa.storage.from(DOCUMENT_BUCKET).list(prefix, { limit: 1000 })
    if (error) {
      errors.push(`list ${prefix}: ${error.message}`)
      continue
    }
    if (!data) continue
    scanned += data.length
    const stale = data.filter((f) => {
      const ts = f.updated_at ? Date.parse(f.updated_at) : Date.parse(f.created_at ?? '')
      return Number.isFinite(ts) && ts < cutoff
    })
    if (stale.length === 0) continue
    const paths = stale.map((f) => `${prefix}/${f.name}`)
    const { error: delErr } = await supa.storage.from(DOCUMENT_BUCKET).remove(paths)
    if (delErr) errors.push(`remove ${prefix}: ${delErr.message}`)
    else deleted += paths.length
  }

  return { deleted, scanned, errors }
}

import { Prisma } from '@prisma/client'
import { 
  SerializedCourse, 
  SerializedEnrollment, 
  SerializedExamBooking, 
  SerializedPaymentMilestone,
  SerializedUserProfile
} from './types'

// Type definitions for Prisma objects with includes
type CourseWithRelations = Prisma.CourseGetPayload<{
  include: {
    examComponents: { include: { course: true } }
  }
}>

type EnrollmentWithRelations = Prisma.EnrollmentGetPayload<{
  include: { course: true }
}>

type ExamBookingWithRelations = Prisma.ExamBookingGetPayload<{
  include: { 
    exam: { include: { examComponent: { include: { course: true } } } },
    event: true 
  }
}>

type PaymentMilestoneWithRelations = Prisma.PaymentMilestoneGetPayload<{}>

type UserWithProfile = Prisma.UserGetPayload<{
  select: {
    id: true,
    email: true,
    role: true,
    profile: true,
    studentProfile: {
      include: {
        pathwayRel: {
          select: {
            name: true,
          }
        }
      }
    },
    settings: true,
  }
}>

export function serializeCourse(course: any): SerializedCourse {
  return {
    ...course,
    price: course.price ? Number(course.price) : undefined,
    duration: course.duration ? Number(course.duration) : undefined,
  }
}

export function serializeEnrollment(enrollment: EnrollmentWithRelations): SerializedEnrollment {
  return {
    ...enrollment,
    amountPaid: enrollment.amountPaid ? Number(enrollment.amountPaid) : undefined,
    enrolledAt: enrollment.enrolledAt.toISOString(),
    approvedAt: enrollment.approvedAt?.toISOString() || null,
    completedAt: enrollment.completedAt?.toISOString() || null,
    course: serializeCourse(enrollment.course),
  }
}

export function serializeExamBooking(booking: ExamBookingWithRelations): SerializedExamBooking {
  return {
    ...booking,
    examDate: (booking.examDate || booking.createdAt).toISOString(),
    exam: {
      id: booking.exam?.id || 'historical',
      name: booking.exam?.name || 'Exam Record',
      duration: Number(booking.exam?.duration || 0),
      examComponent: booking.exam?.examComponent ? {
        course: booking.exam.examComponent.course ? {
          name: booking.exam.examComponent.course.name,
          code: booking.exam.examComponent.course.code,
        } : undefined
      } : undefined
    },
    event: booking.event ? {
      location: booking.event.location || 'Online',
    } : null,
  }
}

export function serializePaymentMilestone(milestone: PaymentMilestoneWithRelations): SerializedPaymentMilestone {
  return {
    ...milestone,
    amountDue: Number(milestone.amountDue),
    percentOfYearFee: Number(milestone.percentOfYearFee),
    dueDate: milestone.dueDate.toISOString(),
    paidAt: milestone.paidAt?.toISOString() || null,
  }
}

export function serializeUserProfile(user: UserWithProfile): SerializedUserProfile {
  return {
    id: user.id,
    email: user.email,
    role: user.role,
    profile: user.profile ? {
      ...(user.profile as any),
      dateOfBirth: (user.profile as any).dateOfBirth?.toISOString() || null,
      createdAt: undefined,
      updatedAt: undefined,
    } : null,
    studentProfile: user.studentProfile ? {
      ...(user.studentProfile as any),
      pathwayName: user.studentProfile.pathwayRel?.name || null,
      enrollmentDate: (user.studentProfile as any).enrollmentDate?.toISOString() || null,
      createdAt: undefined,
      updatedAt: undefined,
    } : null,
    settings: user.settings || {},
  }
}

import { Enrollment, Course, ExamBooking, Exam, ExamComponent, PoolMembership, ExamPool, PaymentMilestone, FullTimeEnrollment, FullTimeProgramme, ExamResult } from '@prisma/client'

/**
 * Serialized version of Prisma models for Client Components
 * Replaces Decimal with number and Date with string
 */

export interface SerializedCourse extends Omit<Course, 'createdAt' | 'updatedAt' | 'price' | 'duration'> {
  price?: number
  duration?: number
}

export interface SerializedEnrollment extends Omit<Enrollment, 'createdAt' | 'updatedAt' | 'enrolledAt' | 'approvedAt' | 'completedAt' | 'amountPaid'> {
  course: SerializedCourse
  amountPaid?: number
  enrolledAt: string
  approvedAt?: string | null
  completedAt?: string | null
}

export interface SerializedExamBooking extends Omit<ExamBooking, 'createdAt' | 'updatedAt' | 'examDate'> {
  exam: {
    id: string
    name: string
    duration: number
    examComponent?: {
      course?: {
