  'examEvent',
  'examPool',
  'poolMembership',
  'poolWaitlist',
  'wallet',
  'walletTransaction',
  'exam',
  'examBooking',
  'bookingEntitlement',
  'examResult',
  'examBundle',
  'payment',
  'invoice',
  'notification',
  'message',
  'auditLog',
  'systemSetting',
  'paymentMethod',
  'fileUpload',
  'newsArticle',
  'generalResource',
  'academicYear',
