describe('Staff Wallet Top-up Routes', () => {
   beforeEach(() => {
     vi.resetAllMocks()
     ;(requireStaff as any).mockResolvedValue({ id: 'staff-1', email: 'staff@test.com' })
     ;(requirePermission as any).mockResolvedValue({ id: 'staff-1', email: 'staff@test.com' })
     prismaMock.notification.create.mockResolvedValue({})
   })

  describe('POST /api/staff/wallet-topups/[id]/approve', () => {
    it('approves a pending wallet top-up and credits wallet', async () => {
      prismaMock.payment.findUnique.mockResolvedValue({
        id: 'pay-1',
        status: 'PENDING',
        referenceType: 'WALLET_TOPUP',
        amount: 500,
        userId: 'user-1',
        user: { id: 'user-1', email: 'user@test.com' },
        currency: 'EUR',
        referenceCode: 'WTU-ABC123',
      })
      prismaMock.payment.update.mockResolvedValue({})

      const req = new NextRequest('http://localhost/api/staff/wallet-topups/pay-1/approve', {
        method: 'POST',
        body: JSON.stringify({ action: 'approve' }),
      })

      const res = await approveWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(200)
      const data = await res.json()
      expect(data.data.message).toContain('approved')
      expect(prismaMock.payment.update).toHaveBeenCalledWith({
        where: { id: 'pay-1' },
        data: expect.objectContaining({ status: 'APPROVED' }),
      })
    })

    it('rejects a pending wallet top-up', async () => {
      prismaMock.payment.findUnique.mockResolvedValue({
        id: 'pay-1',
        status: 'PENDING',
        referenceType: 'WALLET_TOPUP',
        amount: 500,
        userId: 'user-1',
        user: { id: 'user-1', email: 'user@test.com' },
        currency: 'EUR',
        referenceCode: 'WTU-ABC123',
      })
      prismaMock.payment.update.mockResolvedValue({})

      const req = new NextRequest('http://localhost/api/staff/wallet-topups/pay-1/approve', {
        method: 'POST',
        body: JSON.stringify({ action: 'reject', reason: 'Invalid proof' }),
      })

      const res = await approveWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(200)
      const data = await res.json()
      expect(data.data.message).toBe('Top-up rejected')
      expect(prismaMock.payment.update).toHaveBeenCalledWith({
        where: { id: 'pay-1' },
        data: expect.objectContaining({ status: 'REJECTED' }),
      })
    })

    it('returns 404 when payment is not found', async () => {
      prismaMock.payment.findUnique.mockResolvedValue(null)

      const req = new NextRequest('http://localhost/api/staff/wallet-topups/pay-1/approve', {
        method: 'POST',
        body: JSON.stringify({ action: 'approve' }),
      })

      const res = await approveWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(404)
    })

    it('returns error when payment is not pending', async () => {
      prismaMock.payment.findUnique.mockResolvedValue({
        id: 'pay-1',
        status: 'APPROVED',
        referenceType: 'WALLET_TOPUP',
      })

      const req = new NextRequest('http://localhost/api/staff/wallet-topups/pay-1/approve', {
        method: 'POST',
        body: JSON.stringify({ action: 'approve' }),
      })

      const res = await approveWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(400)
    })
  })

  describe('POST /api/staff/finance/wallet-topups/[id]/reject', () => {
    it('rejects a pending wallet top-up with reason', async () => {
      prismaMock.payment.findUnique.mockResolvedValue({
        id: 'pay-1',
        status: 'PENDING',
        referenceType: 'WALLET_TOPUP',
        amount: 500,
        userId: 'user-1',
      })
      prismaMock.payment.update.mockResolvedValue({ count: 1 })
      prismaMock.auditLog.create.mockResolvedValue({})

      const req = new NextRequest('http://localhost/api/staff/finance/wallet-topups/pay-1/reject', {
        method: 'POST',
        body: JSON.stringify({ reason: 'Insufficient proof' }),
      })

      const res = await rejectWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(200)
      const data = await res.json()
      expect(data.success).toBe(true)
      expect(prismaMock.payment.update).toHaveBeenCalledWith({
        where: { id: 'pay-1' },
        data: expect.objectContaining({
          status: 'REJECTED',
          rejectionReason: 'Insufficient proof',
        }),
      })
    })

    it('returns 400 when reason is missing', async () => {
      const req = new NextRequest('http://localhost/api/staff/finance/wallet-topups/pay-1/reject', {
        method: 'POST',
        body: JSON.stringify({}),
      })

      const res = await rejectWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(400)
    })

    it('returns 400 when payment is not a pending wallet top-up', async () => {
      prismaMock.payment.findUnique.mockResolvedValue({
        id: 'pay-1',
        status: 'APPROVED',
        referenceType: 'COURSE',
      })

      const req = new NextRequest('http://localhost/api/staff/finance/wallet-topups/pay-1/reject', {
        method: 'POST',
        body: JSON.stringify({ reason: 'test' }),
      })

      const res = await rejectWalletTopup(req, { params: Promise.resolve({ id: 'pay-1' }) })

      expect(res.status).toBe(400)
    })
  })
})

import { vi, describe, it, expect, beforeEach, afterEach } from 'vitest'
import { prismaMock } from '@/tests/setup'
import { NextRequest } from 'next/server'

const { mockVerify } = vi.hoisted(() => ({ mockVerify: vi.fn() }))

vi.mock('svix', () => ({
  Webhook: class {
    verify = mockVerify
  },
}))

import { POST } from '@/app/api/webhooks/resend/route'

const SECRET = 'RESEND_WEBHOOK_SECRET'
const originalSecret = process.env[SECRET]

function setSecret(value: string | undefined) {
  if (value === undefined) delete process.env[SECRET]
  else process.env[SECRET] = value
}

describe('POST /api/webhooks/resend', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockVerify.mockReset()
    prismaMock.$transaction.mockImplementation((fn: any) => fn(prismaMock))
    setSecret(originalSecret)
  })

  afterEach(() => {
    setSecret(originalSecret)
  })

  describe('POST', () => {
    it('returns 503 when RESEND_WEBHOOK_SECRET is not configured', async () => {
      setSecret(undefined)
      const req = new NextRequest('http://localhost/api/webhooks/resend', {
        method: 'POST',
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(503)
      expect(await res.json()).toEqual({ error: 'Webhook verification not configured' })
    })

    it('returns 401 when svix signature headers are missing', async () => {
      setSecret('test-secret')
      const req = new NextRequest('http://localhost/api/webhooks/resend', {
        method: 'POST',
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(401)
      expect(await res.json()).toEqual({ error: 'Missing webhook signature headers' })
    })

    it('returns 401 when signature verification fails', async () => {
      setSecret('test-secret')
      mockVerify.mockImplementationOnce(() => {
        throw new Error('Invalid signature')
      })
      const req = new NextRequest('http://localhost/api/webhooks/resend', {
        method: 'POST',
        headers: {
          'svix-id': 'msg_1',
          'svix-timestamp': '123',
          'svix-signature': 'sig',
        },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(401)
      expect(await res.json()).toEqual({ error: 'Invalid signature' })
    })

    it('returns 400 when payload is missing type or data', async () => {
      setSecret('test-secret')
      mockVerify.mockReturnValue({ type: 'sent', data: null, created_at: '2024-01-01' })
      const req = new NextRequest('http://localhost/api/webhooks/resend', {
        method: 'POST',
        headers: {
          'svix-id': 'msg_1',
          'svix-timestamp': '123',
          'svix-signature': 'sig',
        },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(400)
      expect(await res.json()).toEqual({ error: 'Invalid payload' })
    })

    it('returns 200 and logs an audit event on a valid payload', async () => {
      setSecret('test-secret')
      mockVerify.mockReturnValue({
        type: 'sent',
        data: { email_id: 'email-1', to: 'user@test.com', subject: 'Hello' },
        created_at: '2024-01-01T00:00:00Z',
      })
      prismaMock.auditLog.create.mockResolvedValue({ id: 'audit-1' } as any)
      const req = new NextRequest('http://localhost/api/webhooks/resend', {
        method: 'POST',
        headers: {
          'svix-id': 'msg_1',
          'svix-timestamp': '123',
          'svix-signature': 'sig',
        },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ received: true })
      expect(prismaMock.auditLog.create).toHaveBeenCalledWith(
        expect.objectContaining({
          data: expect.objectContaining({
            action: 'EMAIL_SENT',
            entity: 'email',
            entityId: 'email-1',
          }),
        })
      )
    })
  })
})

