import { POST } from '@/app/api/webhooks/stripe/route'
import { topUpWallet } from '@/lib/wallet/operations'
import { createAuditLog } from '@/lib/audit/logger'

const ENV_KEYS = ['STRIPE_SECRET_KEY', 'STRIPE_WEBHOOK_SECRET']
const originalEnv: Record<string, string | undefined> = {}

function saveEnv() {
  ENV_KEYS.forEach((k) => {
    originalEnv[k] = process.env[k]
  })
}

function restoreEnv() {
  ENV_KEYS.forEach((k) => {
    if (originalEnv[k] === undefined) delete process.env[k]
    else process.env[k] = originalEnv[k]
  })
}

function setEnv(values: Record<string, string | undefined>) {
  ENV_KEYS.forEach((k) => {
    const v = values[k]
    if (v === undefined) delete process.env[k]
    else process.env[k] = v
  })
}

describe('POST /api/webhooks/stripe', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockConstructEvent.mockReset()
    prismaMock.$transaction.mockImplementation((fn: any) => {
      if (typeof fn === 'function') return fn(prismaMock)
      return Promise.resolve(fn)
    })
    saveEnv()
    setEnv({ STRIPE_SECRET_KEY: undefined, STRIPE_WEBHOOK_SECRET: undefined })
  })

  afterEach(() => {
    restoreEnv()
  })

  describe('POST', () => {
    it('returns 503 when Stripe integration is not configured', async () => {
      setEnv({ STRIPE_SECRET_KEY: undefined, STRIPE_WEBHOOK_SECRET: undefined })
      const req = new NextRequest('http://localhost/api/webhooks/stripe', {
        method: 'POST',
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(503)
      expect(await res.json()).toEqual({ error: 'Stripe integration not configured' })
    })

    it('returns 400 when stripe-signature header is missing', async () => {
      setEnv({ STRIPE_SECRET_KEY: 'sk_test', STRIPE_WEBHOOK_SECRET: 'whsec_test' })
      const req = new NextRequest('http://localhost/api/webhooks/stripe', {
        method: 'POST',
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(400)
      expect(await res.json()).toEqual({ error: 'Missing stripe-signature header' })
    })

    it('returns 401 when signature verification fails', async () => {
      setEnv({ STRIPE_SECRET_KEY: 'sk_test', STRIPE_WEBHOOK_SECRET: 'whsec_test' })
      mockConstructEvent.mockImplementationOnce(() => {
        throw new Error('No signatures found matching the expected signature')
      })
      const req = new NextRequest('http://localhost/api/webhooks/stripe', {
        method: 'POST',
        headers: { 'stripe-signature': 'bad-sig' },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(401)
      expect(await res.json()).toEqual({ error: 'Invalid signature' })
    })

    it('returns 200 and processes payment_intent.succeeded', async () => {
      setEnv({ STRIPE_SECRET_KEY: 'sk_test', STRIPE_WEBHOOK_SECRET: 'whsec_test' })
      mockConstructEvent.mockReturnValue({
        type: 'payment_intent.succeeded',
        data: {
          object: {
            id: 'pi_123',
            amount: 1000,
            metadata: {
              userId: 'user-1',
              paymentType: 'WALLET_TOP_UP',
              paymentId: 'pay-1',
            },
          },
        },
      })
      prismaMock.payment.findUnique.mockResolvedValue({ id: 'pay-1', status: 'PENDING' } as any)
      prismaMock.payment.update.mockResolvedValue({ id: 'pay-1', status: 'APPROVED' } as any)

      const req = new NextRequest('http://localhost/api/webhooks/stripe', {
        method: 'POST',
        headers: { 'stripe-signature': 'sig' },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ received: true })
      expect(prismaMock.payment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: 'pay-1' },
          data: expect.objectContaining({ status: 'APPROVED', approvedBy: 'STRIPE' }),
        })
      )
      expect(topUpWallet).toHaveBeenCalledWith(
        prismaMock,
        'user-1',
        10,
        'Stripe payment pi_123',
        'pay-1',
        'PAYMENT_ID'
      )
      expect(createAuditLog).toHaveBeenCalledWith(
        expect.objectContaining({
          action: 'PAYMENT_APPROVE',
          entity: 'Payment',
          entityId: 'pay-1',
          userId: 'user-1',
        })
      )
    })

    it('returns 200 for an unhandled event type', async () => {
      setEnv({ STRIPE_SECRET_KEY: 'sk_test', STRIPE_WEBHOOK_SECRET: 'whsec_test' })
      mockConstructEvent.mockReturnValue({
        type: 'customer.deleted',
        data: { object: {} },
      })
      const req = new NextRequest('http://localhost/api/webhooks/stripe', {
        method: 'POST',
        headers: { 'stripe-signature': 'sig' },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ received: true })
    })
  })
})

import { vi, describe, it, expect, beforeEach, afterEach } from 'vitest'
import { prismaMock } from '@/tests/setup'
import { NextRequest } from 'next/server'

import { POST } from '@/app/api/webhooks/uploadthing/route'

const ENV_KEY = 'UPLOADTHING_SECRET'
const originalEnv: Record<string, string | undefined> = {}

function saveEnv() {
  originalEnv[ENV_KEY] = process.env[ENV_KEY]
}

function restoreEnv() {
  if (originalEnv[ENV_KEY] === undefined) delete process.env[ENV_KEY]
  else process.env[ENV_KEY] = originalEnv[ENV_KEY]
}

function setEnv(values: Record<string, string | undefined>) {
  Object.entries(values).forEach(([k, v]) => {
    if (v === undefined) delete process.env[k]
    else process.env[k] = v
  })
}

const VALID_SECRET = 'ut-test-secret'

describe('POST /api/webhooks/uploadthing', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    prismaMock.$transaction.mockImplementation((fn: any) => fn(prismaMock))
    saveEnv()
  })

  afterEach(() => {
    restoreEnv()
  })

  describe('POST', () => {
    it('returns 401 when UPLOADTHING_SECRET is set and bearer token does not match', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: { Authorization: 'Bearer wrong-secret' },
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(401)
      expect(await res.json()).toEqual({ error: 'Unauthorized' })
    })

    it('returns 401 when UPLOADTHING_SECRET is set and no auth header is present', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: {},
        body: JSON.stringify({}),
      })
      const res = await POST(req)
      expect(res.status).toBe(401)
      expect(await res.json()).toEqual({ error: 'Unauthorized' })
    })

    it('passes auth when uploadthing-hook header is present', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      prismaMock.fileUpload.create.mockResolvedValue({ id: 'file-1' } as any)

      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: { 'uploadthing-hook': 'true' },
        body: JSON.stringify({
          file: {
            name: 'test.pdf',
            url: 'https://test.com/file.pdf',
            type: 'application/pdf',
            size: 1024,
          },
        }),
      })
      const res = await POST(req)
      expect(res.status).toBe(200)
      expect(prismaMock.fileUpload.create).toHaveBeenCalled()
    })

    it('returns 400 for invalid input (no file)', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: { Authorization: `Bearer ${VALID_SECRET}` },
        body: JSON.stringify({ invalid: 'data' }),
      })
      const res = await POST(req)
      expect(res.status).toBe(400)
      expect(await res.json()).toEqual({ error: 'Invalid payload' })
    })

    it('returns 400 when file has no url', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: { Authorization: `Bearer ${VALID_SECRET}` },
        body: JSON.stringify({ file: { name: 'test' } }),
      })
      const res = await POST(req)
      expect(res.status).toBe(400)
      expect(await res.json()).toEqual({ error: 'Invalid payload' })
    })

    it('returns 200 and creates a file upload record on success', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      prismaMock.fileUpload.create.mockResolvedValue({ id: 'file-1' } as any)

      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: { Authorization: `Bearer ${VALID_SECRET}` },
        body: JSON.stringify({
          file: {
            name: 'test.pdf',
            url: 'https://test.com/file.pdf',
            type: 'application/pdf',
            size: 1024,
          },
          metadata: { userId: 'user-1', entityType: 'GENERAL' },
        }),
      })
      const res = await POST(req)
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ success: true, fileId: 'file-1' })
      expect(prismaMock.fileUpload.create).toHaveBeenCalledWith({
        data: {
          filename: 'test.pdf',
          originalName: 'test.pdf',
          url: 'https://test.com/file.pdf',
          mimeType: 'application/pdf',
          size: 1024,
          userId: 'user-1',
          fileType: 'GENERAL',
          referenceType: 'GENERAL',
          referenceId: undefined,
        },
      })
    })

    it('uses default values when file fields are missing', async () => {
      setEnv({ UPLOADTHING_SECRET: VALID_SECRET })
      prismaMock.fileUpload.create.mockResolvedValue({ id: 'file-1' } as any)

      const req = new NextRequest('http://localhost/api/webhooks/uploadthing', {
        method: 'POST',
        headers: { Authorization: `Bearer ${VALID_SECRET}` },
        body: JSON.stringify({
