      expect(prismaMock.auditLog.findMany).toHaveBeenCalledWith({
        where: { action: AuditAction.LOGIN },
        take: 5,
        skip: 0,
        orderBy: { createdAt: 'desc' },
        include: { user: { include: { profile: true } } },
      })
    })

    it('filters by userId and entity', async () => {
