        },
        take: 50,
        skip: 20,
        orderBy: { createdAt: 'desc' },
        include: { user: { include: { profile: true } } },
      })
    })
  })

  describe('createAuditLog', () => {
    it('is an alias for logAuditEvent', () => {
      expect(createAuditLog).toBe(logAuditEvent)
    })
  })
})

