      expect(result.STUDENT).toEqual(customMessages)
      expect(result.STAFF).toEqual(DEFAULT_ROLE_WELCOME_MESSAGES.STAFF)
    })
  })
})

import { describe, it, expect, vi } from 'vitest'

/**
 * Unit tests for proxy.ts hotlink protection logic.
 *
 * The proxy itself runs at the Next.js edge and cannot be invoked directly
 * from Vitest, so we extract the referer-check decision into a pure function
 * and test that. The route handlers (/api/images/*) are covered separately
 * in tests/integration/api/images-*.test.ts.
 */

function isHotlinkRequest(pathname: string, referer: string | null, host: string | null): boolean {
  const imageExtensions = /\.(webp|png|jpg|jpeg|gif|svg|avif)$/i
  if (!pathname.match(imageExtensions)) return false
  if (pathname.startsWith('/api/') || pathname.startsWith('/_next/')) return false
  if (!referer || !host) return false

  try {
    const refererUrl = new URL(referer)
    const refererHost = refererUrl.hostname
    const hostName = host.split(':')[0] || ''
    if (refererHost === hostName || refererHost.endsWith('.' + hostName)) {
      return false
    }
    return true
  } catch {
    return false
  }
}

describe('proxy.ts hotlink protection', () => {
  it('allows requests with no referer', () => {
    expect(isHotlinkRequest('/images/photo.jpg', null, 'example.com')).toBe(false)
  })

  it('allows requests from same host', () => {
    expect(isHotlinkRequest('/images/photo.jpg', 'https://example.com/page', 'example.com')).toBe(false)
  })

  it('allows requests from subdomain', () => {
    expect(isHotlinkRequest('/images/photo.jpg', 'https://sub.example.com/page', 'example.com')).toBe(false)
  })

  it('blocks requests from different host', () => {
    expect(isHotlinkRequest('/images/photo.jpg', 'https://evil.com/steal', 'example.com')).toBe(true)
  })

  it('ignores non-image paths', () => {
    expect(isHotlinkRequest('/api/images/proxy', 'https://evil.com/steal', 'example.com')).toBe(false)
    expect(isHotlinkRequest('/_next/static/image.jpg', 'https://evil.com/steal', 'example.com')).toBe(false)
    expect(isHotlinkRequest('/favicon.ico', 'https://evil.com/steal', 'example.com')).toBe(false)
  })

  it('handles invalid referer gracefully', () => {
    expect(isHotlinkRequest('/images/photo.jpg', 'not-a-url', 'example.com')).toBe(false)
  })

  it('handles host with port', () => {
    expect(isHotlinkRequest('/images/photo.jpg', 'https://example.com:3000/page', 'example.com:3000')).toBe(false)
    expect(isHotlinkRequest('/images/photo.jpg', 'https://evil.com/page', 'example.com:3000')).toBe(true)
  })

  it('matches all image extensions', () => {
    const extensions = ['webp', 'png', 'jpg', 'jpeg', 'gif', 'svg', 'avif']
    for (const ext of extensions) {
      expect(isHotlinkRequest(`/images/photo.${ext}`, 'https://evil.com/steal', 'example.com')).toBe(true)
    }
  })
})

import { describe, it, expect } from 'vitest'
import {
  capitalize,
  toTitleCase,
  truncate,
  slugify,
  getInitials,
  maskEmail,
  formatPaymentType,
} from '@/lib/utils/string'

describe('String Utilities', () => {
  // ─── capitalize ──────────────────────────────────────────────────
  describe('capitalize', () => {
    it('capitalizes the first letter and lowercases the rest', () => {
      expect(capitalize('hello')).toBe('Hello')
      expect(capitalize('WORLD')).toBe('World')
      expect(capitalize('mIxEd')).toBe('Mixed')
    })

    it('handles single character strings', () => {
      expect(capitalize('a')).toBe('A')
    })

    it('handles empty strings', () => {
      expect(capitalize('')).toBe('')
    })
  })

  // ─── toTitleCase ─────────────────────────────────────────────────
  describe('toTitleCase', () => {
    it('converts a string to title case', () => {
      expect(toTitleCase('hello world')).toBe('Hello World')
      expect(toTitleCase('THE QUICK BROWN FOX')).toBe('The Quick Brown Fox')
    })

    it('handles multiple spaces', () => {
      expect(toTitleCase('hello   world')).toBe('Hello   World')
    })

    it('handles empty strings', () => {
      expect(toTitleCase('')).toBe('')
    })
  })

  // ─── truncate ────────────────────────────────────────────────────
  describe('truncate', () => {
    it('returns the original string when under max length', () => {
      expect(truncate('hello', 10)).toBe('hello')
    })

    it('truncates and adds ellipsis when over max length', () => {
      expect(truncate('hello world', 5)).toBe('hello...')
    })

    it('uses default max length of 100', () => {
      const longStr = 'a'.repeat(150)
      expect(truncate(longStr)).toBe('a'.repeat(100) + '...')
    })

    it('returns empty string for empty input', () => {
      expect(truncate('')).toBe('')
    })
  })

  // ─── slugify ─────────────────────────────────────────────────────
  describe('slugify', () => {
    it('converts spaces to hyphens and lowercases', () => {
      expect(slugify('Hello World')).toBe('hello-world')
    })

    it('removes special characters', () => {
      expect(slugify('Hello! World?')).toBe('hello-world')
    })

    it('collapses multiple hyphens', () => {
      expect(slugify('Hello---World')).toBe('hello-world')
    })

    it('trims whitespace', () => {
      expect(slugify('  hello world  ')).toBe('hello-world')
    })

    it('returns empty string for falsy input', () => {
      expect(slugify('')).toBe('')
      expect(slugify(null as any)).toBe('')
    })
  })

  // ─── getInitials ─────────────────────────────────────────────────
  describe('getInitials', () => {
    it('returns uppercase initials', () => {
      expect(getInitials('John', 'Doe')).toBe('JD')
    })

    it('handles lowercase names', () => {
      expect(getInitials('john', 'doe')).toBe('JD')
    })
  })

  // ─── maskEmail ───────────────────────────────────────────────────
  describe('maskEmail', () => {
    it('masks most of the local part', () => {
      expect(maskEmail('john.doe@example.com')).toBe('jo***@example.com')
    })

    it('handles short local parts (<=2 chars)', () => {
      expect(maskEmail('ab@example.com')).toBe('a***@example.com')
    })

    it('preserves the domain', () => {
      expect(maskEmail('test@aerojet-academy.com')).toBe('te***@aerojet-academy.com')
    })
  })

  // ─── formatPaymentType ───────────────────────────────────────────
  describe('formatPaymentType', () => {
    it('returns "Payment" for empty string', () => {
      expect(formatPaymentType('')).toBe('Payment')
    })

    it('maps known payment types', () => {
      expect(formatPaymentType('WALLET_TOP_UP')).toBe('Wallet Top-Up')
      expect(formatPaymentType('REGISTRATION')).toBe('Registration Fee')
      expect(formatPaymentType('COURSE')).toBe('Course Enrollment')
      expect(formatPaymentType('EXAM_BOOKING')).toBe('Exam Booking')
      expect(formatPaymentType('TUITION')).toBe('Tuition Fee')
      expect(formatPaymentType('RESIT')).toBe('Exam Resit')
    })

    it('normalizes underscores and casing', () => {
      expect(formatPaymentType('registration_fee')).toBe('Registration Fee')
      expect(formatPaymentType('full_programme')).toBe('Full Programme Payment')
    })

    it('falls back to title case for unknown types', () => {
      expect(formatPaymentType('CUSTOM_TYPE')).toBe('Custom Type')
    })
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { getBaseUrl } from '@/lib/utils/url'

// Mock next/headers
vi.mock('next/headers', () => ({
  headers: vi.fn(),
}))

import { headers } from 'next/headers'

describe('getBaseUrl', () => {
  const originalEnv = process.env

  beforeEach(() => {
    process.env = { ...originalEnv }
    vi.mocked(headers).mockReset()
  })

  it('returns URL from host header if available', async () => {
    vi.mocked(headers).mockResolvedValue(
      new Map([
        ['host', 'test.com'],
        ['x-forwarded-proto', 'https'],
      ]) as any
    )

    const url = await getBaseUrl()
    expect(url).toBe('https://test.com')
  })

  it('detects http for localhost even if proto missing', async () => {
    vi.mocked(headers).mockResolvedValue(new Map([['host', 'localhost:3000']]) as any)

    const url = await getBaseUrl()
    expect(url).toBe('http://localhost:3000')
  })

  it('falls back to NEXT_PUBLIC_APP_URL if headers fail', async () => {
    vi.mocked(headers).mockRejectedValue(new Error('Outside request context'))
    process.env.NEXT_PUBLIC_APP_URL = 'https://env-defined.com'

    const url = await getBaseUrl()
    expect(url).toBe('https://env-defined.com')
  })

  it('falls back to VERCEL_URL if NEXT_PUBLIC_APP_URL missing', async () => {
    vi.mocked(headers).mockRejectedValue(new Error('Outside request context'))
    delete process.env.NEXT_PUBLIC_APP_URL
    process.env.NEXT_PUBLIC_VERCEL_URL = 'project.vercel.app'

    const url = await getBaseUrl()
    expect(url).toBe('https://project.vercel.app')
  })

  it('defaults to localhost:3000 as absolute fallback', async () => {
    vi.mocked(headers).mockRejectedValue(new Error('Outside request context'))
    delete process.env.NEXT_PUBLIC_APP_URL
    delete process.env.NEXT_PUBLIC_VERCEL_URL
    delete process.env.VERCEL_URL

    const url = await getBaseUrl()
    expect(url).toBe('http://localhost:3000')
  })
})
